-- Sources: data/i18n/deDE. Lore text adapted from warcraft.wiki.gg (CC BY-SA 4.0); the core add-on's src fields name the articles.
local P = LoreForeverPacks.Begin("LoreForever_Lang_deDE")
P.entries["quest:945"] = {n="Therylunes Flucht",s="An der südlichen Dunkelküste ist eine junge Nachtelfe namens Therylune in die unheilvollen Ausgrabungsstätten der Meistergleve geraten und sieht sich von feindseligen Kultisten in die Enge getrieben. Es wird eine Eskorte der Allianz benötigt, um sie in Sicherheit zu geleiten und ihrer besorgten Schwester Therysil, die am Schrein von Aessina weilt, die Nachricht von ihrem Überleben zu überbringen.",h="An der südlichen Dunkelküste ist eine junge Nachtelfe namens Therylune in die unheilvollen Ausgrabungsstätten...",kw={"eschental","kultisten","eskalte","die meistergleve","der schrein von aessina","therylune","therysil","schattenhammer"},ang={["faction:Alliance"]="Gestrandeten Wegweisern wie Therylune zu helfen, stärkt die Präsenz und das Wohlwollen der Allianz bei den einheimischen Nachtelfen, die das Eschental verteidigen.",["race:NightElf"]="Die Meistergleve ist eine uralte Narbe in der Geschichte Kalimdors. Zu sehen, wie Eure Miteifen der Kaldorei unbedacht in die Ausgrabungen der Kultisten wandern, ist eine ernüchternde Erinnerung an die schleichenden Bedrohungen im Eschental."},sec={{t="Ein gefährlicher Spaziergang",b="Die Meistergleve ist eines der beunruhigendsten Wahrzeichen an der Dunkelküste, überragt vom titanischen Schädel einer uralten Monstrosität, die von einer riesigen Steinklinge aufgespießt wurde. Trotz des Grauens, das über dem Tal liegt, wanderte Therylune direkt ins Herz der Schlucht. Schon bald sah sie sich von Kultisten des Schattenhammers festgesetzt und überlebte nur dank schneller Reflexe sowie eines Talents, sich im unwegsamen Gelände zu verbergen."},{t="Nachricht an den Schrein",b="Therylunes Schwester Therysil verweilt weit im Süden am friedvollen Schrein von Aessina. Während Therylune dafür bekannt ist, abenteuerlustig zu sein und sich nicht daran zu stören, Schmutz an ihre Kleidung zu bekommen, schockierte der Vorstoß in die unheilvollen Ausgrabungen der Meistergleve selbst ihre Verwandten. Die Nachricht von Therylunes Sicherheit zu überbringen, erleichtert eine zutiefst besorgte Schwester, die nur allzu gut um die finsteren Mächte weiß, die derzeit die uralte Erde der Dunkelküste durchgraben."}},faq={{q="Wer ist Therylune?",a="Therylune ist eine abenteuerlustige junge Nachtelfe, die in die gefährlichen Ausgrabungen an der Meistergleve an der südlichen Dunkelküste geraten ist. Sie ist die Schwester von Therysil.",al={"therylune","wer ist das mädchen","gefangene elfe"}},{q="Wer ist Therysil?",a="Therysil ist Therylunes Schwester, die am ruhigen Schrein von Aessina im Eschental stationiert ist. Sie erfährt mit Bestürzung davon, dass ihre Verwandte so nahe an einen derart finsteren und verdorbenen Ort gewandert ist.",al={"therysil","therylune schwester"}},{q="Warum ist die Meistergleve so gefährlich?",a="Die Meistergleve ist eine uralte, unheilvolle Schlucht, in der vor langer Zeit ein uralter „alter Lord“ fiel. Kultisten des Schattenhammers schwärmen in dem Gebiet aus, treiben die Ausgrabungen an der Stätte aggressiv voran und greifen jeden Eindringling an.",al={"meistergleve gefahr","kultisten meistergleve"}},{q="Wohin muss Therylune eskortiert werden?",a="Therylune benötigt eine Eskorte aus der unmittelbaren Umgebung der Meistergleve heraus in Sicherheit; danach muss der Retter zum Schrein von Aessina reisen, um ihre Schwester zu benachrichtigen.",al={"eskorteziel","wohin geht therylune"}},{q="Wo befindet sich der Schrein von Aessina?",a="Der Schrein von Aessina liegt im südwestlichen Eschental, westlich von Astranaar, und dient als Zufluchtsort, der dem Waldgeist Aessina geweiht ist.",al={"schrein von aessina standort","wo ist therysil"}},{q="Wie überlebte Therylune umringt von Kultisten?",a="Therylune entging einer Gefangennahme allein dadurch, dass sie ein enges Versteck inmitten der Felsen und des Geländes fand, bevor die umstehenden Kultisten des Schattenhammers sie entdecken konnten.",al={"wie hat sich therylune versteckt"}}},fx={["8c0c4bd7"]={q="Warum braucht Therylune Eure Hilfe bei der Flucht?",a="Therylune ist bei der unheilvollen Ausgrabung bei The Master's Glaive umhergeirrt und fand sich schnell gefangen und umzingelt von Kultisten des Schattenhammerklans wieder. Während ihr Geschick im Verstecken sie am Leben erhielt, kann sie nicht allein an den sie einkesselnden Eiferern vorbeischleichen, um Sicherheit zu erreichen und ihre Schwester Therysil zu beruhigen.",al={"warum will therylune hilfe","therylune beweggrund","warum therylune helfen"}},cc515991={q="Warum kann Therylune nicht alleine entkommen?",a="Obwohl sie geschickt genug darin ist, sich zu verstecken, um einer sofortigen Gefangennahme zu entgehen, ist Therylune völlig unbewaffnet, wehrlos und tief in feindlichem Gebiet gefangen. Da keine örtlichen Wachen oder Verbündeten in der Nähe sind, um ihr zu helfen, ist sie völlig darauf angewiesen, dass ein vorbeiziehender Abenteurer ihr einen Fluchtweg durch die Kultisten bahnt.",al={"warum braucht therylune mich","warum kann therylune nicht entkommen","warum ich therylune"}}},fp="18,319,17.430.0,18.430.0,17.163.0,16.181.0,40.202.0,41.176.0,39.135.0,49.167.0"}
P.entries["quest:94500"] = {n="Call of Water",s="Call of Water beauftragt einen Abenteurer damit, in das smaragdgrüne Blätterdach des Eschentals zu reisen, um reines, uraltes Wasser aus dem See zu sammeln, der Astranaar umgibt. Es markiert den letzten Sammelschritt, bevor der Reisende zu Norric zurückgeschickt wird.",h="Call of Water beauftragt einen Abenteurer damit, in das smaragdgrüne Blätterdach des Eschentals zu reisen, um...",kw={"eschental","astranaar","auberdine","call of water","menethil","norric","süderstade","wasserschlauch"},ang={["faction:Alliance"]="Diese Quest führt Reisende entlang der Seeroute der Allianz von den Östlichen Königreichen hinaus nach Kalimdor und verbindet den Hafen von Menethil mit Auberdine und der Nachtelfensiedlung Astranaar.",["race:NightElf"]="Die Quest führt Reisende zu den unberührten Gewässern rund um Astranaar, einem der Kernlande der Kaldorei im Eschental, wo uralte Ruinen noch immer ungestört liegen."},sec={{t="Die Suche nach reinem Wasser",b="Call of Water beauftragt einen Abenteurer damit, einen Wasserschlauch aus den unverdorbenen Gewässern des Eschentals zu füllen. Der Suchende muss sich nach Astranaar wagen, einer Zuflucht, die inmitten sauberer, uralter Wasser liegt, welche an versunkene Ruinen aus einer vergangenen Ära branden. Diese makellose Probe dient als die letzte Flüssigkeit, die der Questgeber benötigt, bevor der Reisende weiter zu Norric geschickt wird."},{t="Der Weg nach Astranaar",b="Um die Tiefen des Eschentals zu erreichen, muss das Meer von den Östlichen Königreichen aus überquert werden. Der empfohlene Weg führt Reisende an Bord des Schiffes, das vom Hafen von Menethil in Richtung Auberdine ausläuft und während der Reise in Süderstade anlegt. Von den Docks von Auberdine führt die Straße landeinwärts in das smaragdgrüne Geäst des Eschentals, wo Reisende gewarnt werden, inmitten der wachsamen Schatten der Bäume wachsam zu bleiben."}},faq={{q="Was ist die Quest Call of Water?",a="Call of Water ist eine Quest, die vom Reisenden verlangt, einen leeren Wasserschlauch tief in den uralten Wald des Eschentals zu bringen. Das Ziel ist es, eine Probe reinen, uralten und potenziell verzauberten Wassers aus dem See zu sammeln, der die Siedlung Astranaar umgibt, bevor sie zum Questgeber zurückgebracht wird.",al={"was ist call of water","quest call of water","ziel von call of water"}},{q="Wo sammle ich das Wasser für diese Quest?",a="Das Wasser muss aus dem See gesammelt werden, der Astranaar umgibt, das tief im Eschental liegt. Die Gewässer dort bleiben unverdorben und fließen inmitten uralter versunkener Ruinen, die aus einer vergangenen Ära stammen.",al={"wo man reines wasser findet","wo man den wasserschlauch füllt","ort von call of water"}},{q="Wie reise ich für diese Quest ins Eschental?",a="Reisenden wird geraten, das Schiff vom Hafen von Menethil nach Auberdine zu besteigen, das unterwegs einen Halt in Süderstade einlegt. Von Auberdine an der Küste der Dunkelküste reist man nach Süden in die tiefen, smaragdgrünen Wälder des Eschentals, um Astranaar zu erreichen.",al={"wie man nach astranaar gelangt","reise ins eschental","schiff nach astranaar"}},{q="Was macht das Wasser bei Astranaar so besonders?",a="Der See, der Astranaar umgibt, ist dafür bekannt, von Verderbnis unberührtes Wasser zu bergen. Unter seiner Oberfläche liegen versunkene Steinruinen, die auf eine uralte, vergangene Ära der Nachtelfenzivilisation hindeuten und dem Wasser seine makellosen und potenziell verzauberten Eigenschaften verleihen.",al={"welcher see in astranaar","wasserruinen von astranaar","ruinen im see von astranaar"}},{q="Wer ist Norric?",a="Norric ist die Person, die den Reisenden erwartet, nachdem diese letzte Flüssigkeitsprobe gesammelt wurde. Der Questgeber sammelt dieses reine Wasser aus dem Eschental als letzte Zutat, bevor er den Abenteurer zurück zu Norric schickt.",al={"wer ist norric","zu norric zurückkehren"}},{q="Welche Gefahren sollte ich im Eschental erwarten?",a="Das Eschental ist ein uralter, dichter Wald voller Gefahren. Der Questgeber warnt Reisende davor, ständig wachsam zu sein, und mahnt, dass der Wald wachsame Augen hat, die nicht blinzeln, wenn man sich unter sein smaragdgrünes Blätterdach wagt.",al={"gefahr im eschental","bedrohungen im eschental"}}},fp="13,229,25.349.0,21.403.0,32.289.0,44.199.0,44.240.0,42.251.0,14.209.0,42.219.0"}
P.entries["quest:94501"] = {n="Call of Water",s="Der Call of Water ist eine spirituelle Prüfung für Schamanen, die nach den heiligen Wassertotemriten streben. Indem Suchende reines, von Hervdana gesegnetes Wasser zu Norric Lochthane in Loch Modan bringen, bereiten sie das elementare Sapta vor, das nötig ist, um mit den Geistern an Stendels Tümpel zu kommunizieren.",h="Der Call of Water ist eine spirituelle Prüfung für Schamanen, die nach den heiligen Wassertotemriten streben.",kw={"call of water","hervdana","loch modan","mondbruch","norric lochthane","schamane","stendels tümpel","phiole mit reinstem wasser","water sapta","wassertotem"},ang={["class:Shaman"]="Diese Prüfung ist ein entscheidender Schritt bei der Zwiesprache mit den Elementen, um die Wassertotemriten zu erlangen und das Sapta herzustellen, das nötig ist, um Elementargeister zu sehen.",["faction:Alliance"]="Schamanen der Allianz suchen in den östlichen Ländern nach Zwiesprache mit Wassergeistern und schlagen eine Brücke zwischen Loch Modan und Westfall.",["race:Dwarf"]="Die Reise verbindet zwergische Schamanenanwärter mit elementaren Mentoren wie Norric Lochthane quer durch Khaz Modan."},sec={{t="Der Pfad zum Wassertotem",b="Der Call of Water stellt eine wesentliche Prüfung spiritueller Einstimmung für angehende Schamanen dar, die nach Harmonie mit dem Element des Wassers streben. Das Beschreiten dieses Pfades erfordert das Sammeln von Wasser, das von Hervdana selbst gesegnet wurde, was sowohl Geduld als auch Ehrfurcht vor den Geistern beweist, bevor das Gefäß zu Norric Lochthane in Loch Modan gebracht wird."},{t="Das Erschaffen des Saptas",b="Nach Erhalt des gesegneten Gefäßes offenbart Norric, dass die heilige Flüssigkeit dazu bestimmt ist, ein Water Sapta zu brauen. Dieser Trank ermöglicht es dem Suchenden, das Unsichtbare zu durchdringen und die Wassergeister zu erblicken, die an Stendels Tümpel nahe Mondbruch verweilen. Jeder einzelne Tropfen gilt als kostbar, da selbst ein befeuchteter Pfropfen in den heiligen Riten einen Zweck erfüllt."}},faq={{q="Wer ist Norric Lochthane?",a="Norric Lochthane ist ein in Loch Modan ansässiger Mentor, der Anwärter durch ihre elementare Zwiesprache leitet. Er beaufsichtigt die Vorbereitungen und Riten, die erforderlich sind, um sich das Wassertotem zu verdienen.",al={"wer ist norric","norric loch modan","wer ist norric lochthane"}},{q="Wer ist Hervdana?",a="Hervdana Saegrund ist die Führerin im Sumpfland, die mit ihrer Familie in einer Höhle bei den südlichen Wasserfällen lebt und geweihtes Wasser segnet, das von aufstrebenden Schamanen gesammelt wurde, wodurch sie es mit der spirituellen Reinheit erfüllt, die zur Herstellung von Water Sapta erforderlich ist.",al={"wer ist hervdana","von hervdana gesegnet","hervdana wasser"}},{q="Wofür wird ein Sapta verwendet?",a="Ein Sapta ist ein elementarer Trank, der unter Verwendung von heiligem Wasser zubereitet wird. Das Trinken dieses Tranks ermöglicht es einem Schamanen, den Schleier zu durchdringen und die schwer fassbaren Wassergeister wahrzunehmen, die in natürlichen Gewässern hausen.",al={"was ist water sapta","zweck des saptas","was bewirkt ein sapta"}},{q="Wo befindet sich Stendels Tümpel?",a="Stendels Tümpel befindet sich in Westfall nahe Mondbruch. Seine Wasser beherbergen elementare Wassergeister, die ein Schamane aufsuchen muss, nachdem er sein zubereitetes Sapta zu sich genommen hat.",al={"wo ist stendels tümpel","stendels tümpel ort","wassergeister stendel"}},{q="Warum ist die Phiole mit reinstem Wasser wichtig?",a="Die Phiole mit reinstem Wasser enthält gesegnetes Wasser, das für das Brauen des Water Saptas und die Durchführung der heiligen Riten unerlässlich ist, die zum Erlangen eines Wassertotems erforderlich sind. Norric warnt davor, dass nicht ein einziger Tropfen verschwendet werden darf.",al={"warum reines wasser benötigt wird","phiole mit reinstem wasser zweck"}},{q="Was sind die Wassertotemriten?",a="Die Wassertotemriten sind spirituelle Prüfungen, die von Schamanen unternommen werden, um sich auf das Element des Wassers einzustimmen und Respekt sowie Gleichgewicht zu demonstrieren, bevor ihnen ein Wassertotem gewährt wird.",al={"was sind wassertotemriten","wie man ein wassertotem erhält"}}},fp="13,257,27.325.0,18.332.1,24.179.0,16.226.0,25.175.0,32.161.0,42.208.0,31.180.0"}
P.entries["quest:94502"] = {n="Call of Water",s="Call of Water ist eine Elementarquest, die eine Reise von Loch Modan nach Westfall erfordert, um das Gleichgewicht einer verdorbenen Quelle wiederherzustellen. Indem Bittsteller das befleckte Wesen an Stendels Tümpel läutern und ein uraltes Ritual am vergessenen Schrein durchführen, erlangen sie die Gunst der Wassergeister und ihr Wassertotem.",h="Call of Water ist eine Elementarquest, die eine Reise von Loch Modan nach Westfall erfordert, um das...",kw={"call of water","loch modan","mondbruch","norric","schamane","stendels tümpel","wassertotem","westfall"},ang={["class:Shaman"]="Diese Prüfung stellt einen entscheidenden Übergangsritus dar, um sich auf die Wassergeister einzustimmen und das Wassertotem zu verdienen, was Harmonie und Beherrschung der Elementarkräfte beweist.",["faction:Alliance"]="Schamanen der Allianz müssen durch ihre Territorien reisen und sich von Loch Modan in die unruhigen Lande von Westfall wagen, um verdorbene Gewässer zu reinigen."},sec={{t="Eine vom Schatten befleckte Quelle",b="Im Schatten von Mondbruch liegt Stendels Tümpel, einst als klare und reine Quelle gepriesen. Dunkle Einflüsse, die über Westfall hinwegfegen, haben seine ruhigen Wasser verunreinigt und die hiesigen Wassergeister in tiefes Schweigen gestürzt. Ein alter Schrein steht am Ufer, vernachlässigt und in Staub sowie Spinnweben gehüllt, und wartet darauf, dass jemand die schlummernden Kräfte in seinem Inneren erweckt."},{t="Der Ritus der Läuterung",b="Norric in Loch Modan leitet Bittsteller durch das Ritual, das zur Wiederherstellung des Gleichgewichts erforderlich ist. Der Ritus verlangt, dem üblen Wesen entgegenzutreten, das Stendels Tümpel verpestet, seine Armschienen an sich zu bringen und sie zusammen mit Tropfen eines alchemistischen Tranks auf dem steinernen Schrein darzubringen. Wird die Beschwörungsformel gesprochen, rufen die Dämpfe einen geläuterten Geist herbei, der Weisheit vermittelt und beweist, dass der Träger des Wassertotems würdig ist."}},faq={{q="Was ist die Quest Call of Water?",a="Call of Water ist eine spirituelle Prüfung für Schamanen, die danach streben, mit den Elementen des Wassers zu kommunizieren. Die Quest beauftragt den Bittsteller damit, das verdorbene Wasser an Stendels Tümpel in Westfall zu reinigen und einen dortigen alten Schrein zu nutzen, um einen gereinigten Wassergeist zu beschwören und sich sein Wassertotem zu verdienen.",al={"was ist call of water","wassertotem quest","wasserquest westfall"}},{q="Wer vergibt diese Quest?",a="Die Quest wird von Norric vergeben, einem Mentor in Loch Modan. Er unterweist Bittsteller in elementaren Riten, stellt spezielle Tränke bereit und leitet sie bei der Läuterung verdorbener Elementargewässer an.",al={"wer vergibt call of water","norric loch modan","questgeber"}},{q="Wo befindet sich Stendels Tümpel?",a="Stendels Tümpel liegt direkt außerhalb von Mondbruch im südwestlichen Westfall. Einst eine reine Quelle, ist er unter dem Einfluss dunkler, verderbender Mächte still und trüb geworden.",al={"wo ist stendels tümpel","stendels tümpel standort","tümpel nahe mondbruch"}},{q="Wie reinigt man die Verderbnis an Stendels Tümpel?",a="Um die Wasser zu läutern, müsst Ihr die verderbende Präsenz an Stendels Tümpel besiegen, ihre Armschienen an Euch nehmen und sie zusammen mit den verbliebenen Tropfen des Tranks auf dem uralten Schrein platzieren, während Ihr die von Norric gelehrten Worte sprecht.",al={"wie man den tümpel läutert","stendels tümpel läutern","schreinritual"}},{q="Was erhaltet Ihr als Belohnung für den Abschluss dieser Quest?",a="Der Abschluss der Prüfung und die Rückkehr mit dem Beweis der Läuterung zu Norric in Loch Modan belohnt den Bittsteller mit seinem Wassertotem, was die Herrschaft über die elementaren Mächte des Wassers gewährt.",al={"welche belohnung call of water","wassertotem belohnung"}},{q="Warum ist Stendels Tümpel verdorben?",a="Der Ursprung der Dunkelheit ist ungewiss. Das Gewässer liegt unnatürlich regungslos da, umgeben von den Knochen von Bestien, was Anlass zur Sorge gibt, ob es durch das sich ausbreitende Unheil in Westfall vergiftet wurde oder selbst als Quelle der Verderbnis dient.",al={"warum ist stendels tümpel verdorben","was den tümpel verdorben hat"}}},fp="13,302,26.358.0,21.400.1,32.273.0,21.190.0,24.166.0,52.220.0,43.181.0,32.238.0"}
P.entries["quest:94503"] = {n="Call of Water",s="Call of Water ist eine Quest mit Schwerpunkt in Westfall, bei der Abenteurer den Auftrag erhalten, verderbte Elementarkräfte zu läutern. Indem sie rastlose Geister mit strahlendem Licht auflösen, treten Spieler mit einer Schwachen Wassermanifestation in Kontakt, um die schwindende Lebenskraft der Region zu schützen.",h="Call of Water ist eine Quest mit Schwerpunkt in Westfall, bei der Abenteurer den Auftrag erhalten, verderbte...",kw={"call of water","reinigung","verderbnis","elementar","schwache wassermanifestation","wassergeist","westfall"},ang={["class:Shaman"]="Die Zwiesprache mit den Urelementen und die Reinigung verdorbener Wassergeister ist ein grundlegender Ritus der Elemente, der Schamanen an ihre ewige Pflicht erinnert, das Gleichgewicht der Natur zu wahren.",["faction:Alliance"]="Die Manifestation befindet sich in Westfall, einem Territorium der Allianz, in dem einheimische Geister die schleichende Fäulnis ertragen, die das Land heimsucht."},sec={{t="Reinigung der verdorbenen Gewässer",b="In den windgepeitschten Ländern von Westfall droht das natürliche Gleichgewicht der Gewässer durch verderbte Geister verunreinigt zu werden. Der als Call of Water bekannte Ritus erfordert es, dieser Bosheit entgegenzutreten und heilige Worte anzurufen, die strahlendes Licht heraufbeschwören, um die rastlosen, verdorbenen Essenzen in harmlose Asche und stillen Mist aufzulösen."},{t="Die Warnung des Geistes",b="Nachdem die verderbten Wesenheiten zurückgeschlagen wurden, kann eine Schwache Wassermanifestation gefahrlos hervortreten, um Zwiesprache zu halten. Während die unmittelbare Verderbnis abebbt, mahnt der Geist zur Vorsicht, da die Lebensenergien des Landes weiterhin schwinden, und erinnert die Champions daran, dass die Bewahrung des Lebens eine endlose Wacht ist."}},faq={{q="Was ist Call of Water?",a="Call of Water ist eine spirituelle Prüfung in Westfall, bei der verderbte Geister durch eine rituelle Anrufung verbannt werden, die in Licht ausbricht, wodurch die unruhigen Gewässer befreit werden und die Zwiesprache mit einer Schwachen Wassermanifestation ermöglicht wird.",al={"was ist call of water","call of water westfall","westfall wasserquest"}},{q="Wo ist die Schwache Wassermanifestation zu finden?",a="Die Schwache Wassermanifestation befindet sich in Westfall. Sie erscheint, sobald die umgebenden verderbten Geister unterworfen und gebannt wurden, und wartet darauf, mit jenen zu sprechen, die den Gewässern geholfen haben.",al={"wo ist die schwache wassermanifestation","ort der manifestation","wassergeist westfall"}},{q="Was geschieht, wenn die verderbten Geister gereinigt werden?",a="Als die Beschwörung endet, bricht strahlendes Licht hervor, um die verderbten Geister zu vertreiben, wodurch sich ihre verdorbene Essenz auflöst und wie Asche verstreut, während Wasser zu sanftem Mist verzischt.",al={"was geschieht während des rituals","verderbte geister call of water"}},{q="Ist das Land nach Abschluss der Aufgabe vollständig wiederhergestellt?",a="Die unmittelbare Verderbnis wird zurückgeschlagen und ebbt ab, doch der Elementar warnt davor, dass die Lebenskraft weiterhin schwindet, wodurch der dauerhafte Schutz des Lebens in sterblichen Händen verbleibt.",al={"ist die verderbnis verschwunden","haben wir das wasser gerettet"}},{q="Wer wird herbeigerufen, um der Manifestation beizustehen?",a="Die Quest würdigt die Berufung des Spielers und dankt seiner Klasse dafür, dass sie hervorgetreten ist, um die Geister zu reinigen und die Verantwortung für den Schutz des schwindenden Lebens auf sich zu nehmen.",al={"wer kann call of water annehmen","klassenanforderung wasserquest"}},{q="Warum wurden die Wassergeister in Westfall verderbt?",a="Verderbte Geister haben die natürlichen Gewässer entlang von Westfall gestört. Obwohl der genaue Ursprung der Befleckung subtil bleibt, zehrt ihre bösartige Präsenz direkt an der lebendigen Lebenskraft des Gebiets.",al={"warum ist das wasser in westfall verderbt","wasserproblem in westfall"}}},fp="13,260,28.310.0,20.273.0,22.214.0,52.181.0,53.184.0,53.168.0,47.177.0,49.195.0"}
P.entries["quest:94505"] = {n="Call of Water",s="Call of Water ist ein elementarer Übergangsritus, bei dem Schamanen lernen, mit Wassergeistern zu kommunizieren und deren heilsame Kräfte zu nutzen. Indem sie Norric Lochthane in Loch Modan einen Wassersplitter aus Westfall beschaffen, beweisen die Initianden ihre Hingabe und erhalten ihr Wassertotem.",h="Call of Water ist ein elementarer Übergangsritus, bei dem Schamanen lernen, mit Wassergeistern zu...",kw={"call of water","loch modan","norric lochthane","schamane","wassersplitter","wassertotem","westfall"},ang={["class:Shaman"]="Diese Prüfung markiert einen grundlegenden Übergangsritus, der einem Schamanen die Zwiesprache mit Wassergeistern und das Wassertotem gewährt, um Leben zu heilen und zu erhalten.",["faction:Alliance"]="Anders als die Schamanen der Horde auf Kalimdor berichten der Allianz angehörende Initianden an Mentoren wie Norric Lochthane in Loch Modan und stellen sich Prüfungen an Orten wie Westfall."},sec={{t="Der Pfad des Wassers",b="Call of Water ist eine grundlegende spirituelle Prüfung für Schamanen, um ein Band mit dem Element Wasser zu schmieden. Initianden haben die Aufgabe, nach Westfall zu reisen und mit dem Wassersplitter zu Norric Lochthane in Loch Modan zurückzukehren. Indem sie ihr Verständnis für das lebensspendende Wesen des Wassers und seine Rolle bei der Beseitigung von Verderbnis unter Beweis stellen, verdienen sich Schamanen ihr Wassertotem und machen einen entscheidenden Schritt auf ihrer Reise der Elemente."},{t="Lebensspender",b="Die Prüfung vermittelt eine grundlegende elementare Wahrheit: Wasser ist Leben, und Verderbnis beendet das Leben. Schamanen sind dazu berufen, die heilsame Stärke des Wassers einzusetzen, um die Schwachen zu schützen und das Leben zu bewahren. Wie Mentor Norric Lochthane bei Erhalt des Wassersplitters feststellt, reichen die reinen Gaben des Wassers weit über das bloße Heilen körperlicher Wunden hinaus und umfassen Ausdauer, Erneuerung sowie spirituelles Gleichgewicht."}},faq={{q="Wer ist Norric Lochthane?",a="Norric Lochthane ist ein in Loch Modan stationierter Schamanen-Mentor. Er leitet Initianden durch ihre Prüfungen an, um Wassergeister zu verstehen, testet ihre Entschlossenheit mit einer Reise nach Westfall und überreicht ihnen nach Erbringen des Beweises ihrer Zwiesprache ihr Wassertotem.",al={"wer ist norric lochthane","wer gibt wassertotem","norric loch modan"}},{q="Was ist der Wassersplitter?",a="Der Wassersplitter ist der physische Beweis, der Norric Lochthane in Loch Modan aus Westfall überbracht wird. Er steht dafür, dass der Initiand mit dem Wasser Zwiesprache gehalten, seine lebensspendende Natur verstanden und gelernt hat, Verderbnis zu bekämpfen.",al={"was ist wassersplitter","wassersplitter verwendung","wassersplitter questgegenstand"}},{q="Warum führt die Prüfung nach Westfall?",a="Initianden werden nach Westfall geschickt, um die lebensspendende Macht des Wassers zu begreifen und zu verstehen, wie Verderbnis diese bedroht. Selbst bescheidene Siege in jenem unruhigen Land fallen ins Gewicht, um die Fähigkeit des Initianden zum Schutz des Lebens zu beweisen.",al={"warum nach westfall reisen","westfall wasserquest","reise nach westfall call of water"}},{q="Welche Bedeutung hat das Wassertotem?",a="Das Wassertotem verkörpert das Band eines Schamanen mit dem Element Wasser. Während es vor allem dafür bekannt ist, Wunden durch reines Wasser zu lindern und zu schließen, reichen seine spirituellen Gaben weit über grundlegende Heilung hinaus und umfassen Bewahrung sowie Vitalität.",al={"was bewirkt wassertotem","warum brauchen schamanen wassertotem","wassertotem lore"}},{q="Welche Lehre vermittelt die Prüfung über das Wasser?",a="Die während der Prüfung gelehrte Elementarphilosophie betont, dass Wasser Leben spendet, wohingegen Verderbnis ihm ein Ende setzt. Ein Schamane hat die Aufgabe, die elementare Macht des Wassers zu nutzen, um Leben zu nähren, zu schützen und das Gleichgewicht wiederherzustellen, wo immer Verderbnis lebendige Wesen bedroht.",al={"was bedeutet wasser ist leben","call of water philosophie","schamanen wasserlehren"}},{q="Was folgt auf den Abschluss von Call of Water?",a="Norric Lochthane merkt an, dass die nächste elementare Prüfung eines Initianden nicht unmittelbar folgt. Er ermutigt Schamanen dazu, sich Zeit zum Üben zu nehmen und die tieferen Geheimnisse des Wassers zu ergründen, bevor sie sich weiteren Prüfungen widmen.",al={"welche prüfung folgt als nächstes","nächste schamanenprüfung","was geschieht nach call of water"}}},fp="13,280,17.421.0,13.413.0,24.261.0,27.224.0,36.217.0,44.236.0,45.252.0,46.207.0"}
P.entries["quest:94568"] = {n="The Cult's True Plans",s="The Cult's True Plans befasst sich mit den Nachwirkungen des vorzeitigen Ablebens eines Kultüberläufers. Da der Informant tot ist und seine Geheimnisse verloren sind, müssen sich die Ermittler mit Talaanis Shadowsong beraten, um eine neue Strategie gegen den Kult zu entwickeln.",h="The Cult's True Plans befasst sich mit den Nachwirkungen des vorzeitigen Ablebens eines Kultüberläufers.",kw={"kult","überläufer","friedensbewahrer","talaanis shadowsong","the cult's true plans"},sec={{t="Ein zum Schweigen gebrachter Überläufer",b="Ein Insider lief aus Angst vor den drohenden Plänen des Kults über und hoffte auf Hilfe von außen. Tragischerweise wurde der Überläufer getötet, bevor er sein Wissen teilen konnte, und hinterließ unheilvolle Warnungen, aber keine konkreten Einzelheiten darüber, was der Kult zu entfesseln gedenkt."},{t="Überdenken des Vorgehens",b="Nach dem Tod ihres Hauptinformanten muss sich die Führung mit Talaanis Shadowsong beraten, um ihre Strategie neu zu bewerten. Dem Kult in einer offenen Konfrontation mit Friedensbewahrern entgegenzutreten, gilt als aussichtsloser Kampf, was diejenigen, die die Bedrohung untersuchen, dazu zwingt, nach einem alternativen Weg nach vorn zu suchen."}},faq={{q="Wer war der in dieser Quest erwähnte Überläufer?",a="Ein Kultüberläufer suchte Hilfe, nachdem er in Angst vor den Plänen des Kults geraten war. Unglücklicherweise wurde er getötet, bevor er die Einzelheiten ihrer Machenschaften enthüllen konnte, und nahm seine wertvollen Informationen mit ins Grab.",al={"wer starb in the cult's true plans","wer ist der tote überläufer","geheimnisse des kultüberläufers"}},{q="Wer ist Talaanis Shadowsong?",a="Talaanis Shadowsong ist die entscheidende Kontaktperson, die nach dem plötzlichen Tod des Informanten konsultiert wird, um das weitere Vorgehen gegen den Kult zu besprechen. Ihr beobachtet ein strategisches Gespräch mit Talaanis, um die nächsten Schritte zu ermitteln.",al={"rolle von talaanis schattensang","wer ist talaanis schattensang","mit talaanis sprechen"}},{q="Warum können die Friedensbewahrer den Kult nicht einfach direkt angreifen?",a="Der direkte Einsatz von Friedensbewahrern in einer offenen Schlacht gegen die Streitkräfte des Kults wird als viel zu riskant erachtet, da nicht zu erwarten ist, dass die Friedensbewahrer in einem frontalen Zusammenstoß gut abschneiden. Stattdessen ist eine subtilere oder alternative Strategie erforderlich.",al={"warum nicht gegen den kult kämpfen","friedensbewahrer gegen kult","direkter angriff auf den kult"}},{q="Was sind die tatsächlichen Pläne des Kults?",a="Die genaue Natur der Pläne des Kults bleibt im Dunkeln, da der Informant starb, bevor er sein Wissen teilen konnte. Was auch immer ihr Ziel ist, es war furchterregend genug, um ein Mitglied in seiner Verzweiflung zum Überlaufen zu bewegen.",al={"was plant der kult","kultpläne","bedeutung von the cult's true plans"}},{q="Was ist der nächste Schritt nach dem Gespräch mit Talaanis?",a="Nachdem die Führung erkannt hat, dass ein offener Kampf ausgeschlossen und ihre wichtigste Informationsquelle tot ist, muss sie eine alternative Methode entwickeln, um die Machenschaften des Kults aufzudecken und zu vereiteln.",al={"was geschieht nach the cult's true plans","nächste schritte kultquest"}},{q="Was geschieht während The Cult's True Plans?",a="Ihr sprecht mit Talaanis Shadowsong und beobachtet eine Lagebesprechung. Die Diskussion dreht sich um die Nachwirkungen des Todes des Informanten und die Einschätzung, warum man sich nicht auf reguläre Militärgewalt verlassen kann, um den Kult aufzuhalten.",al={"the cult's true plans quest-zusammenfassung","was tut man in the cult's true plans"}}},fp="21,224,19.279.0,23.278.1,45.215.0,27.228.0,55.235.0,33.221.0,51.196.0,42.219.0"}
P.entries["quest:94616"] = {n="Water Sapta",s="Der Water Sapta ist ein zeremonieller Trank, der verwendet wird, um die eigene spirituelle Sicht auf die verborgenen Geister und Verderbnisse des Wassers einzustimmen. Mit dieser Zubereitung betraut, wird der Träger ausgesandt, um verdorbenes Teichwasser auf den Feldern von Westfall ausfindig zu machen und ein elementares Ungleichgewicht zu untersuchen.",h="Der Water Sapta ist ein zeremonieller Trank, der verwendet wird, um die eigene spirituelle Sicht auf die...",kw={"elementare einstimmung","sapta","schamanenprüfung","verdorbener teich","water sapta","wassergeister","westfall"},ang={["class:Shaman"]="Ein Sapta ist ein alchemistischer oder ritueller Trank, der von Schamanen verwendet wird, um ihre spirituellen Sinne auf elementare Geister einzustimmen, die für den gewöhnlichen Blick unsichtbar bleiben.",["faction:Alliance"]="Die Untersuchung verderbter Wasser in Westfall bringt elementare Reinigungsriten in das Herz eines Reiches der Allianz."},sec={{t="Die Sicht der Wasser",b="In den elementaren Traditionen der Schamanen ist ein Sapta ein zeremonielles Gebräu, das zubereitet wird, um den Schleier zwischen dem physischen Reich und den Geistern zu durchdringen. Der Water Sapta stimmt die Sinne speziell auf das Element Wasser ein und verleiht die spirituelle Sicht, die notwendig ist, um elementare Störungen und verborgene Geister wahrzunehmen. Ohne eine solche Einstimmung könnten gewöhnliche Reisende direkt auf eine elementare Manifestation blicken und nichts weiter als gewöhnliche Wellen sehen."},{t="Störung in Westfall",b="Die Weisung hinter dem Water Sapta führt den Träger nach Westfall, ein von Unruhe und Vernachlässigung geplagtes, dürres Reich der Allianz. In diesem windgepeitschten Land liegt ein verdorbener Teich, dessen Wasser unter spiritueller Verunreinigung leidet. Geleitet von der Wahrnehmung des Sapta muss der Träger diese verderbten Wasser aufsuchen, um die Störung aufzudecken und die Harmonie mit den lokalen Wassergeistern wiederherzustellen."}},faq={{q="Was ist ein Water Sapta?",a="Ein Water Sapta ist ein spezielles spirituelles Gebräu, das für Schamanen geschaffen wurde, um mit den Elementen zu kommunizieren. Das Trinken oder Benutzen eines Sapta öffnet vorübergehend die eigene Wahrnehmung für elementare Wesenheiten und spirituelle Ungleichgewichte, die für sterbliche Augen andernfalls verborgen bleiben.",al={"was ist ein water sapta","zweck des water sapta","was bewirkt water sapta"}},{q="Wo befindet sich der verdorbene Teich in Westfall?",a="Das verdorbene Teichwasser befindet sich in den Ländern von Westfall. Schamanen werden mit dem Water Sapta dorthin geleitet, um verderbte Wasserquellen ausfindig zu machen und sich jeder spirituellen Störung anzunehmen, die in der Region schwelt.",al={"wo ist der verdorbene teich","verdorbener teich westfall","ort des verdorbenen teichs"}},{q="Warum führt der Water Sapta nach Westfall?",a="Selbst in landwirtschaftlich geprägten und von Dürre heimgesuchten Ländern der Menschen wie Westfall können elementare Gewässer einer Verunreinigung oder finsteren Verderbnis zum Opfer fallen. Die Quest beauftragt Euch damit, verdorbenes Teichwasser aufzusuchen, um die dort weilenden unruhigen Geister zu untersuchen und das Gleichgewicht wiederherzustellen.",al={"warum nach westfall reisen","wasserverderbnis in westfall","warum das wasser in westfall verdorben ist"}},{q="Wer benutzt den Water Sapta?",a="Water Saptas werden Schamanen anvertraut, die sich Prüfungen der elementaren Zwiesprache unterziehen. Indem der Praktizierende den Sapta zu sich nimmt, stimmt er seine Sinne auf Wassergeister ein, was es ihm ermöglicht, verborgene Elementare wahrzunehmen oder verdorbene Teiche zu untersuchen.",al={"wer trinkt water sapta","wer benutzt water sapta","schamanen-sapta-trank"}},{q="Was geschieht, wenn Ihr den Sapta zum verdorbenen Teich bringt?",a="Wenn Ihr den Water Sapta in der Nähe des verdorbenen Teichs in Westfall benutzt, wird Euch elementare Sicht gewährt, die den spirituellen Zustand des Wassers offenbart oder verborgene Geister herbeiruft, die an die örtliche Wasserprüfung gebunden sind.",al={"was nach der nutzung des sapta geschieht","elementare sicht des sapta"}},{q="Wie funktionieren elementare Saptas in der schamanischen Tradition?",a="Saptas verbinden irdische Reagenzien und elementare Segen zu einem zeremoniellen Trank. Schamanen verlassen sich während ihrer Prüfungen auf sie, um sich auf bestimmte Elemente einzustimmen – Erde, Feuer, Wasser oder Luft –, wodurch die Kluft zwischen der physischen Welt und dem Geisterreich überbrückt wird.",al={"wie saptas funktionieren","sapta-lore"}}},fp="11,274,23.457.0,23.371.0,22.247.0,38.224.0,42.260.0,25.232.0,58.191.0,51.250.0"}
P.entries["quest:947"] = {n="Höhlenpilze",s="Höhlenpilze ist ein Allianzauftrag, der von dem Nachtelfen Barithras Mondschatten in Auberdine angeboten wird. Während er einen speziellen Trank formuliert, beauftragt Barithras einen Abenteurer damit, sich in eine versteckte Höhle hinter den Cliffspring Falls zu wagen, um seltene Pilze zu ernten und beunruhigende Vorahnungen zu überprüfen, die der Hain der Uralten verspürt hat.",h="Höhlenpilze ist ein Allianzauftrag, der von dem Nachtelfen Barithras Mondschatten in Auberdine angeboten wird.",kw={"auberdine","barithras mondschatten","höhlenpilze","cliffspring falls","dunkelküste","todeskappe","der hain der uralten","onu","schorfstängel"},ang={["faction:Alliance"]="Auberdine dient als primäres Bollwerk der Allianz an der Küste von Kalimdor, und schleichende Übel in den östlichen Bergen gefährden direkt die Stabilität der gesamten Küste.",["profession:Herbalism"]="Sammler und Kräuterkundige werden die Jagd nach der Todeskappe und den Schorfstängeln zu schätzen wissen, obwohl diese speziellen Exemplare eher in dunklen Höhlen als in üppigem Waldboden gedeihen.",["race:NightElf"]="Der Hain der Uralten bleibt tief mit dem natürlichen Gleichgewicht von Dunkelküste verbunden, was jede Störung, die sie unter den Wasserfällen entdecken, zu einer Angelegenheit von dringender Sorge für die Kaldorei macht."},sec={{t="Ein Rezept hinter den Wasserfällen",b="Barithras Mondschatten benötigt für eine wirkungsvolle Mischung bestimmte Zutaten: Schorfstängel und eine schwer zu findende Todeskappe. Diese speziellen Pilze gedeihen in der feuchten, schattenhaften Höhle, die direkt hinter den Cliffspring Falls im nordöstlichen Dunkelküste verborgen liegt. Während die Alchemie an sich schon heikel ist, ist das Sammeln dieser Exemplare weitaus gefährlicher als das Ernten gewöhnlicher Waldkräuter."},{t="Die Warnung der Uralten",b="Barithras hat die Höhle nicht aus bloßer Faulheit gemieden. Die ehrwürdigen Baumwächter im Hain der Uralten gaben ernste Warnungen heraus, da sie spürten, dass sich eine üble Präsenz in den Berghöhlen eingenistet hatte. Indem er einen abgehärteten Erkunder schickt, anstatt selbst zu ermitteln, möchte Moonshade bestätigen, ob die düsteren Intuitionen der Ältesten über ein schleichendes Übel im nördlichen Dunkelküste tatsächlich begründet sind."}},faq={{q="Wo beginnt diese Aufgabe?",a="Ihr erhaltet diesen Auftrag von Barithras Mondschatten, der sich in der Küstensiedlung der Nachtelfen, Auberdine, im zentralen Dunkelküste aufhält.",al={"wo kann man höhlenpilze sammeln","barithras mondschatten standort","höhlenpilze quest start"}},{q="Wo befinden sich die Pilze?",a="Sie wachsen in einer Höhle, die hinter den Cliffspring Falls verborgen ist und sich entlang der Bergwand nordöstlich von Auberdine befindet.",al={"wo sind schorfstängel","todeskappe standort","höhle hinter wasserfall dunkelküste"}},{q="Warum holt Barithras Mondschatten die Pilze nicht selbst?",a="Barithras wurde vom Hain der Uralten ausdrücklich geraten, sich von den Wasserfällen fernzuhalten. Die großen Uralten spürten, dass ein unnatürliches, aufsteigendes Übel in jener Höhle Zuflucht gefunden hat.",al={"warum geht barithras nicht hin","warum bleibt barithras in auberdine"}},{q="Welche speziellen Pilze werden benötigt?",a="Moonshade benötigt fünf Schorfstängel sowie eine einzelne, äußerst gefährliche Todeskappe, um seinen Trank zu vervollständigen.",al={"benötigte pilze","welche pilze für moonshade"}},{q="Wohin führt dieser Auftrag als Nächstes?",a="Sobald die Präsenz in der Höhle überprüft und die Pilze geliefert wurden, wendet sich die Reise nach Süden zum uralten Beschützer Onu beim Hain der Uralten.",al={"nächste quest nach höhlenpilze","onu folgequest"}},{q="Warum sind die Uralten wegen der Cliffspring Falls besorgt?",a="Der Hain der Uralten warnte Barithras, dass ein aufsteigendes Übel in der Höhle hinter den Wasserfällen lauern könnte. Er bittet einen Reisenden, Pilze zu sammeln und die Warnung zu untersuchen.",al={"warnung der uralten cliffspring falls","warum höhle erkunden"}}},fx={a048db56={q="Warum möchte Barithras Mondschatten, dass dies getan wird?",a="Barithras Mondschatten ist ein Kräuterkundiger, der einen starken neuen Trank zusammenbraut, für den seltene Pilze benötigt werden, die nur in der Höhle hinter Cliffspring Falls zu finden sind. Neben seiner alchemistischen Arbeit hegt er jedoch eine tiefere Sorge: Die Grove of the Ancients hat ihn gewarnt, dass in genau dieser Höhle ein aufkommendes Übel lauert. Indem er Euch ausschickt, um die Zutaten zu sammeln, hofft er auch zu erfahren, ob die düsteren Vorzeichen der Ältesten wahr sind.",al={"warum will barithras cave mushrooms","barithras mondschatten beweggrund","warum pilze für barithras sammeln"}},["991c4c10"]={q="Wozu dient die Todeskappe?",a="Die Todeskappe ist ein außergewöhnlich seltener und stark giftiger Pilz, der in der Höhle hinter Cliffspring Falls heimisch ist. Barithras Mondschatten benötigt ein makelloses Exemplar als wichtiges Reagenz für einen speziellen Trank, den er in Auberdine herstellt.",al={"wozu dient die todeskappe","zweck der todeskappe","warum braucht barithras eine todeskappe"}},be6516db={q="Wozu dient der Schorfstängling?",a="Schorfstänglinge sind seltene Pilze, die in der feuchten, schattigen Höhle hinter Cliffspring Falls gedeihen. Barithras Mondschatten benötigt fünf davon, um sie zusammen mit der starken Todeskappe in seine laufenden alchemistischen Gebräue zu mischen.",al={"wozu dienen schorfstänglinge","zweck der schorfstänglinge","warum braucht barithras schorfstänglinge"}}},fp="14,322,25.366.0,21.406.1,27.136.0,32.122.0,61.183.0,35.115.0,35.153.0,55.168.1"}
P.entries["quest:94792"] = {n="Taming the Beast",s="Taming the Beast ist eine einführende Prüfung, bei der angehende Abenteurer die Kunst erlernen, wilde Tierbegleiter zu beruhigen und eine Bindung zu ihnen aufzubauen. Unter der Anleitung von Josephine Carson nehmen Initianden eine Zähmerrute mit in den Wald, um ein Rockhide Boar zu zähmen und grundlegende Überlebensfertigkeiten zu üben. Die Aufgabe zeigt, dass das Überleben an rauen Grenzen an der Seite einer treuen Bestie weitaus einfacher ist, vorausgesetzt, man achtet und bewahrt das empfindliche Gleichgewicht der Natur.",h="Taming the Beast ist eine einführende Prüfung, bei der angehende Abenteurer die Kunst erlernen, wilde...",kw={"tierbegleiter","gleichgewicht der natur","bestienzähmung","jägerbegleiter","josephine carson","rockhide boar","zähmerrute","taming the beast"},ang={["class:Druid"]="Während Druiden keine Tierbegleiter nach Art der Jäger halten, spiegelt die Betonung der Quest auf die Bewahrung des empfindlichen Gleichgewichts der Natur zentrale druidische Lehren wider. Der achtsame und zurückhaltende Umgang mit der Tierwelt des Waldes ehrt das natürliche Gleichgewicht, zu dessen Schutz sie geschworen haben.",["class:Hunter"]="Für Jäger ist das Meistern der Kunst, wilde Bestien zu zähmen, ein prägender Übergangsritus, der ihre Art und Weise, in der Wildnis zu überleben, grundlegend verändert. Ein treuer Gefährte bietet unverzichtbaren Schutz im Kampf sowie Wachsamkeit und schmiedet eine dauerhafte Partnerschaft zwischen Fährtenleser und Bestie."},sec={{t="Bindung zu Bestien",b="Für viele Wanderer der Wildnis ist es eine Einladung zur Gefahr, sich allein durch ungezähmte Gebiete zu wagen. Ein Tierbegleiter bietet nicht nur erbitterten Schutz im Kampf, sondern auch unerschütterliche Gefährtenschaft auf zermürbenden Reisen. Zu lernen, wie man eine solche Bindung aufbaut, ist ein entscheidender Meilenstein für jeden angehenden Jäger oder Fährtenleser. Unter der Anleitung von Josephine Carson wird Novizen eine spezialisierte Zähmerrute anvertraut und ihnen aufgetragen, ein Rockhide Boar im Wald aufzuspüren. Die Beruhigung und Führung einer solchen Kreatur dient als grundlegende Prüfung, die beweist, ob ein Reisender den Fokus und die Gelassenheit besitzt, die erforderlich sind, um eine Bestie zu führen, ohne der Furcht zu erliegen oder unnötiges Blutvergießen zu provozieren."},{t="Das Gleichgewicht der Natur",b="Die Beherrschung wilder Tiere bringt tiefgreifende ethische und ökologische Verantwortung mit sich. Wie Josephine Carson ihre Schüler erinnert, darf die Indienstnahme von Bestien niemals zu rücksichtsloser Ausbeutung verkommen, da das Gleichgewicht der Natur empfindlich bleibt und stets gewahrt werden muss. Beim Zähmungsprozess geht es nicht um Grausamkeit oder Dominanz, sondern darum, Harmonie und Disziplin zwischen Bestie und Meister herzustellen. Die Verwendung der verzauberten Rute ermöglicht es einem Novizen, den Umgang mit einer furchterregenden Kreatur wie einem Rockhide Boar sicher zu üben, ohne die einheimische Tierwelt dauerhaft zu dezimieren. Sobald die Grundlagen des Befehligens und Beruhigens der Bestie erlernt sind, wird die Rute zurückgegeben, was beweist, dass der Respekt vor der natürlichen Ordnung vor dem Stolz steht."}},faq={{q="Was ist der Zweck der Quest Taming the Beast?",a="Diese Quest dient als grundlegende Ausbildung für Abenteurer, die eine Bindung zu wilden Kreaturen aufbauen möchten. Unter der Anleitung von Josephine Carson lernen Novizen, wie man sich mithilfe einer spezialisierten Zähmerrute einem wilden Rockhide Boar nähert und es beruhigt. Die Übung lehrt angehende Jäger, wie ein Tierbegleiter ihnen beim Überleben in der Wildnis helfen kann, während gleichzeitig hervorgehoben wird, wie wichtig es ist, das Gleichgewicht der Natur zu achten.",al={"taming the beast quest","was ist taming the beast","jägerbegleiter quest"}},{q="Wer ist Josephine Carson?",a="Josephine Carson ist eine Mentorin, die Abenteurer in der feinfühligen Kunst des Umgangs mit Tierbegleitern unterweist. Sie stellt die Zähmerrute bereit und überträgt Schülern die Aufgabe, ihre Fähigkeiten an einem Rockhide Boar in den nahegelegenen Wäldern zu üben. Josephine betont, dass das Erlernen der Zusammenarbeit mit Bestien Geduld, Übung und ein achtsames Bewusstsein für das empfindliche Gleichgewicht der Natur erfordert.",al={"josephine carson","wer vergibt taming the beast","zähmerrute questgeber"}},{q="Wofür wird die Zähmerrute verwendet?",a="Die Zähmerrute ist ein spezialisiertes Werkzeug, das von Josephine Carson bereitgestellt wird, um die Ausbildung von Tieren zu erleichtern. Abenteurer nehmen die Rute mit in den Wald, um ein wildes Rockhide Boar zu beruhigen und zu zähmen. Sie ermöglicht es Novizen, das Befehligen einer Bestie sicher zu üben, ohne der einheimischen Fauna dauerhaften Schaden zuzufügen, und sie muss an Josephine zurückgegeben werden, sobald die Prüfung abgeschlossen ist.",al={"zähmerrute","was bewirkt die zähmerrute","wie man die zähmerrute verwendet"}},{q="Warum benötigen Jäger Tierbegleiter?",a="Sich den Gefahren der Wildnis allein zu stellen, setzt Reisende schweren Gefahren und Hinterhalten aus. Ein Tierbegleiter bietet verlässlichen Schutz, geteilte Wachsamkeit und beachtliche Hilfe im Kampf, wodurch gefährliche Umstände weitaus leichter zu ertragen sind. Eine treue Bestie fungiert sowohl als unerbittlicher Frontlinienwächter als auch als vertrauter Gefährte während langer und gefährlicher Expeditionen durch ungezähmte Lande.",al={"warum einen tierbegleiter holen","vorteile eines tierbegleiters","warum bestien zähmen"}},{q="Welche Kreatur muss während dieser Prüfung gezähmt werden?",a="Die Prüfung erfordert von Abenteurern, sich in den Wald zu wagen und mithilfe der bereitgestellten Zähmerrute ein Rockhide Boar zu zähmen. Diese robusten Bestien dienen als idealer Test, um grundlegende Fertigkeiten im Umgang mit Tieren zu üben, und lehren Reisende, Gelassenheit und Disziplin zu bewahren, wenn sie aggressiver Wildfauna gegenüberstehen, bevor sie zurückkehren, um Josephine Carson über ihre Fortschritte zu berichten.",al={"welchen eber zähmen","rockhide boar ziel","taming the beast mob"}},{q="Warum betont Josephine Carson das Gleichgewicht der Natur?",a="Josephine Carson warnt davor, dass die Unterwerfung wilder Bestien stets mit Vorsicht und Respekt angegangen werden muss statt mit Gier oder Gewalt. Die natürliche Ordnung ist empfindlich, und das rücksichtslose Stören der einheimischen Tierwelt oder das Misshandeln von Kreaturen bringt das ökologische Gleichgewicht aus den Fugen. Wahre Meisterschaft über Bestien erfordert das Verstehen und Achten ihres Platzes im Ökosystem, anstatt sie lediglich als austauschbare Werkzeuge zu behandeln.",al={"bedeutung des gleichgewichts der natur","gleichgewicht der natur zähmen","warum man die natur achten sollte"}}},fp="16,430,19.689.0,21.716.0,50.399.0,24.376.0,32.354.0,38.377.0,46.356.0,58.402.0"}
P.entries["quest:94793"] = {n="Training the Beast",s="Training the Beast ist eine grundlegende Quest für junge Jäger, die sie anweist, den erfahrenen Waldläufer Isaac Chan in Goldhain aufzusuchen. Durch den Abschluss dieses Schritts lernen Jäger, ihre tierischen Begleiter richtig auszubilden, zu ernähren und wiederzubeleben, wodurch eine frisch gezähmte Bestie in einen treuen Kampfgefährten verwandelt wird.",h="Training the Beast ist eine grundlegende Quest für junge Jäger, die sie anweist, den erfahrenen Waldläufer...",kw={"wald von elwynn","begleiter füttern","goldhain","jägerbegleiter","isaac chan","begleiterausbildung","begleiter wiederbeleben","training the beast","waldläufer"},ang={["class:Hunter"]="Diese Quest markiert einen entscheidenden Übergangsritus für heranreifende Jäger, der den Übergang vom reinen Einfangen von Bestien zum Schmieden eines dauerhaften, disziplinierten Bandes durch deren Fütterung, Wiederbelebung und Ausbildung darstellt.",["faction:Alliance"]="Jäger der Allianz, die im Wald von Elwynn aktiv sind, verlassen sich auf erfahrene Waldläufer wie Isaac Chan in Goldhain, um die Grundlagen des Umgangs mit Bestien zu meistern."},sec={{t="Die Pflichten der Jagd",b="Zu lernen, eine wilde Kreatur zu zähmen, ist für einen angehenden Jäger nur der erste Schritt; die Aufrechterhaltung einer dauerhaften Partnerschaft erfordert Disziplin und Wissen. Die Quest weist angehende Jäger an, Isaac Chan aufzusuchen, einen erfahrenen Waldläufer, der in Goldhain stationiert ist, um das wesentliche Handwerk der Ausbildung von Bestien zu erlernen. Ohne angemessene Führung bleibt eine gezähmte Bestie eher ein widerspenstiges wildes Tier als ein standhafter Verbündeter in der Wildnis."},{t="Die Unterweisung eines Waldläufers",b="Nach der Ankunft in Goldhain verleiht Isaac Chan die Fähigkeiten, die für die Pflege eines tierischen Begleiters erforderlich sind. Diese Unterweisung geht über einfache Kampfbefehle hinaus und umfasst die lebenswichtigen Pflichten, den Begleiter zu füttern, um ihn zufriedenzustellen, und die Riten zu erlernen, um ihn wiederzubeleben, sollte er im Kampf fallen. Chan erinnert seine Schüler daran, dass die Ausübung von Macht über die Tierwelt mit der Pflicht einhergeht, das natürliche Gleichgewicht zu respektieren und in Ehrfurcht vor der umgebenden Welt zu leben."}},faq={{q="Wer ist Isaac Chan?",a="Isaac Chan ist ein erfahrener, lebenslanger Waldläufer, der in Goldhain im Wald von Elwynn ansässig ist. Er wird für sein tiefes Verständnis der Tierwelt und des Überlebens in der Wildnis geschätzt und bringt unerfahrenen Jägern bei, wie sie ihre tierischen Begleiter richtig führen, füttern, wiederbeleben und ihnen Fähigkeiten beibringen.",al={"wer ist isaac chan","bestienausbilder goldhain","isaac chan lore"}},{q="Was ist der Zweck von Training the Beast?",a="Während ein Jäger vielleicht schon weiß, wie man eine Bestie zähmt, vermittelt diese Quest das wesentliche Wissen, um dieses Band aufrechtzuerhalten. Sie weist den Jäger darin an, seinen Begleiter zu füttern, ihn wiederzubeleben, falls er im Kampf fällt, und ihm neue Kampffähigkeiten beizubringen.",al={"was bewirkt diese quest","warum bestie ausbilden","zweck von training the beast"}},{q="Wo ist Isaac Chan zu finden?",a="Isaac Chan befindet sich in Goldhain, der zentralen Ortschaft des Waldes von Elwynn, direkt südlich des Nordhaintals und südwestlich von Sturmwind.",al={"wo ist isaac chan","wo quest abgeben","isaac chan standort"}},{q="Welche Fähigkeiten lehrt Isaac Chan?",a="Isaac Chan vermittelt die Kernprinzipien der Begleiterpflege und -ausbildung. Dies umfasst das Füttern Eurer Bestie, um ihr Wohlbefinden aufrechtzuerhalten, ihre Wiederbelebung, sollte sie im Kampf fallen, und das Beibringen neuer Fähigkeiten, während sie an Eurer Seite wächst.",al={"welche fähigkeiten erhält man","erlernte begleiterfähigkeiten","was lehrt isaac chan"}},{q="Warum erinnert Isaac Chan Jäger daran, die Natur zu respektieren?",a="Isaac Chan betont, dass das Meistern wilder Bestien eher Demut als Beherrschung erfordert. Er drängt Jäger dazu, das Gleichgewicht der natürlichen Welt zu ehren und in Ehrfurcht vor der umgebenden Natur zu leben, um sicherzustellen, dass die Partnerschaft zwischen Jäger und Bestie auf Fürsorge statt auf Ausbeutung aufgebaut ist.",al={"warum die natur respektieren","das gleichgewicht respektieren jäger"}},{q="Wer nimmt diese Quest an?",a="Training the Beast ist speziell auf Jäger zugeschnitten, die die anfängliche Fähigkeit erworben haben, Bestien zu zähmen, und die Disziplin des Waldes benötigen, die für den Erhalt und die Ausbildung eines tierischen Begleiters erforderlich ist.",al={"wer kann diese quest annehmen","ist training the beast nur für jäger"}}},fp="18,301,32.424.0,21.438.0,18.272.0,42.244.0,30.138.0,34.223.0,53.293.0,26.192.0"}
P.entries["quest:948"] = {n="Onu",s="Dieser Auftrag führt Reisende von Auberdine nach Süden in Richtung des Grove of the Ancients, um sich mit Onu zu beraten. Nachdem Ihr die Höhle hinter den Cliffspring Falls ausgekundschaftet habt, haben Eure Erkenntnisse die dringende Aufmerksamkeit eines der ältesten Beschützer der Dunkelküste erregt.",h="Dieser Auftrag führt Reisende von Auberdine nach Süden in Richtung des Grove of the Ancients, um sich mit Onu...",kw={"ancient of lore","auberdine","barithras mondschatten","cliffwater falls","dunkelküste","grove of the ancients","onu"},ang={["class:Druid"]="Druiden bringen den Urahnen tiefe Ehrfurcht als Manifestationen der Weisheit der Natur entgegen. Die Untersuchung seltsamer Höhlenwucherungen auf Onus Geheiß hin entspricht unmittelbar den Pflichten des Zirkels des Cenarius.",["faction:Alliance"]="Für Reisende der Allianz, die dabei helfen, die Dunkelküste zu sichern, ist es entscheidend, das Vertrauen und die Einsicht der Urahnen der Region zu gewinnen, um sich in Kalimdors geheimnisvoller nördlicher Wildnis zurechtzufinden.",["race:NightElf"]="Die Ancients of Lore sind den Kaldorei heilige Gefährten, die Euer Volk schon seit der Zeit vor der Zerschlagung geleitet haben. Onus Ruf zu folgen, ist eine feierliche Pflicht, um die Unversehrtheit der Dunkelküste zu bewahren."},sec={{t="Eine Vorladung von den Urahnen",b="Nachdem Barithras Mondschatten mit Pilzproben aus den Tiefen der Cliffspring Falls nach Auberdine zurückgekehrt ist, erkennt er, dass die Tragweite weit über bloße botanische Neugier hinausgeht. Die Kunde von den verderbten Höhlen dringt rasch zu Onu vor, einem Ancient of Lore, der in der friedvollen Zuflucht des Grove of the Ancients südlich der Stadt verwurzelt ist. So geduldig und schwerfällig die uralten Treants von Natur aus auch sein mögen, signalisiert Onus unmittelbarer Wunsch nach Rat, dass die Verderbnis, die durch die Gewässer der Dunkelküste fließt, uralte, beunruhigende Mächte berühren könnte."},{t="Reise zum Hain",b="Folgt man der Straße von Auberdine nach Süden, führt sie weg von den Küstenruinen und landeinwärts in Richtung der Berghänge. Der Grove of the Ancients dient als angestammte Bastion der Natur, weitgehend geschützt vor dem schleichenden Verfall, der die Küstenlinie heimsucht. Hier wartet Onu inmitten hoch aufragender Steinhügelgräber und verwandter Geister und bereitet sich darauf vor, Verbündete gegen tiefere, noch furchterregendere Plagen zu führen, die sich am Rande der Wildnis regen."}},faq={{q="Wer ist Onu?",a="Onu ist ein Ancient of Lore, ein kolossaler, denkender Baumwächter, der sich dem Sammeln und Bewahren von Wissen verschrieben hat. Er wacht über den im Süden der Dunkelküste gelegenen Grove of the Ancients und steht den Verteidigern des Landes mit Weisheit und Rat zur Seite.",al={"wer ist onu","onu identitaet","was ist onu"}},{q="Warum möchte Onu mit mir sprechen?",a="Ihr habt Euch kürzlich in die Höhlen unterhalb der Cliffspring Falls gewagt, um Pilzproben für Barithras Mondschatten zu sammeln. Die sonderbare Beschaffenheit dessen, was dort entdeckt wurde, hat die Naturforscher beunruhigt und Onu dazu veranlasst, um eine Audienz zu bitten, um der wachsenden Verderbnis zu begegnen.",al={"warum onu ruft","grund fuer gespraech","warum zu onu gehen"}},{q="Wo befindet sich der Grove of the Ancients?",a="Der Grove of the Ancients liegt südlich von Auberdine, eingebettet an den Ausläufern der östlichen Gebirgskette. Folgt der Hauptstraße nach Süden durch die Dunkelküste und haltet Euch nach Osten in Richtung der Berghänge, um Onu zu finden.",al={"onu standort","wo ist grove of the ancients","wie man onu findet"}},{q="Was für eine Kreatur ist ein Ancient of Lore?",a="Ancients of Lore sind uralte Treant-Wesen, die mit den Nachtelfen und dem Zirkel des Cenarius verbündet sind. Sie werden für ihre tiefe Weisheit und ihr Erinnerungsvermögen verehrt und dienen als lebende Speicher für Naturmagie und historische Geheimnisse.",al={"ancient of lore","welche kreatur ist onu","treant oder ancient"}},{q="Warum gilt Onus Vorladung als dringend?",a="Urahnen sind für ihr bedächtiges, unaufgeregtes Auftreten bekannt und handeln selten in Eile. Wie Barithras Mondschatten bemerkt, muss die Bedrohung für die Dunkelküste schwerwiegend sein, wenn ein so geduldiges und methodisches Wesen wie Onu aktiv nach Eurem Rat verlangt.",al={"warum dringend","ist onu besorgt","barithras warnung"}},{q="Was geschieht nach dem Treffen mit Onu?",a="Nachdem er Euch im Grove of the Ancients begrüßt hat, bittet Onu um Eure Hilfe bei der Untersuchung einer weitaus finstereren Bedrohung weiter südlich an der Küste: der unheilvollen Ausgrabung, die rund um die Meistergleve stattfindet.",al={"naechste quest nach onu","was als naechstes geschieht","wohin onu euch schickt"}}},fx={be40e913={q="Warum schickt mich Barithras Mondschatten zu Onu?",a="Barithras weiß, dass die Ältesten der Lehren tiefes Wissen über die Verderbnis des Landes besitzen, und Onu hat direkt bemerkt, was Ihr in der Höhle bei Cliffspring Falls gefunden habt. Da sich ein Ältester selten meldet, es sei denn, die Dunkelküste steht vor einer tiefgreifenden und dringenden Bedrohung, drängt Barithras Euch dazu, der Vorladung sofort Folge zu leisten.",al={"barithras beweggrund","warum zu onu schicken","warum will barithras das erledigt haben"}}},fp="3,240,27.538.0,20.427.0,11.238.0,35.259.0,35.208.0,44.211.0,39.231.0,34.209.1"}
P.entries["quest:94863"] = {n="Taming the Beast",s="Taming the Beast ist eine Ausbildungslektion für Jäger, die von Josephine Carson beaufsichtigt wird. Nachdem der angehende Jäger die Grundlagen des Umgangs mit Wildtieren an einem Eber erlernt hat, muss er eine Zähmerrute benutzen, um das Vertrauen eines wilderen Gray Forest Wolf zu gewinnen.",h="Taming the Beast ist eine Ausbildungslektion für Jäger, die von Josephine Carson beaufsichtigt wird.",kw={"wildtierzähmung","gray forest wolf","jäger","jägerausbildung","josephine carson","zähmerrute","taming the beast"},ang={["class:Hunter"]="Diese Ausbildung stellt einen wesentlichen Übergangsritus für Jäger dar und lehrt die Geduld und den Respekt, die erforderlich sind, um mit den wilden Raubtieren der Wildnis in Einklang zu treten."},sec={{t="Der Pfad des Jägers",b="Die Verbindung eines Jägers zur Wildnis erfordert mehr als bloßes Spurenlesen und Treffsicherheit; sie verlangt den Respekt und die Geduld, die nötig sind, um das Vertrauen einer wilden Kreatur zu gewinnen. Nachdem sie ihre grundlegenden Fähigkeiten an einfachen Ebern unter Beweis gestellt haben, stehen angehende Jäger vor einer weitaus wilderen Herausforderung: sich in den Wald zu wagen, um einen Gray Forest Wolf zu zähmen. Unter den wachsamen Augen der Ausbilderin Josephine Carson wird dem Jäger eine verzauberte Rute anvertraut, um das Raubtier zu beruhigen und das feine Gleichgewicht zwischen Jäger und Tier zu erlernen."},{t="Eine Prüfung von Instinkt und Vertrauen",b="Josephine Carson stattet den Jäger mit einer speziellen Zähmerrute aus, die dazu dient, einen beruhigenden Einfluss zu kanalisieren, der es dem Jäger ermöglicht, sich gefährlichen Wildtieren zu nähern. Die Aufgabe erfordert Geduld und Präzision, da man sich dem Wolf ohne tödliche Gewalt nähern muss, während seine natürliche Aggression sanft überwunden wird. Sobald die Bindung geübt ist und der Jäger beweist, dass er mit dem Geist des Wildtiers harmonieren kann, wird die Rute als Beweis für die wachsende Beherrschung der Wildnis an Josephine zurückgegeben."}},faq={{q="Was ist die Quest Taming the Beast?",a="Taming the Beast ist eine Ausbildungsprüfung für Jäger, bei der ein Ausbilder einen angehenden Jäger damit beauftragt, mithilfe einer verzauberten Zähmerrute einen Gray Forest Wolf aufzuspüren und zu zähmen.",al={"taming the beast quest","gray forest wolf quest","wolf zähmen lektion"}},{q="Wer vergibt und schließt diese Quest ab?",a="Josephine Carson dient als Ausbilderin für diese Prüfung. Sie stellt die Zähmerrute zur Verfügung und bewertet Eure Bindung zu den Tieren des Waldes, bevor sie die Rute nach Abschluss wieder an sich nimmt.",al={"wer vergibt taming the beast","wer ist josephine carson","wo gibt man taming the beast ab"}},{q="Welche Kreatur müsst Ihr zähmen?",a="Ihr werdet angewiesen, einen Gray Forest Wolf zu zähmen, und wechselt damit von Eurer vorherigen Übung mit Ebern zu einem wilderen Raubtier des Waldes.",al={"was zähme ich","welches wildtier","ziel von taming the beast"}},{q="Wofür wird die Zähmerrute verwendet?",a="Die Zähmerrute ist ein Ausbildungswerkzeug, das von Josephine Carson zur Verfügung gestellt wird, um einem Jägerlehrling dabei zu helfen, einen wilden Gray Forest Wolf zu beruhigen und eine vorübergehende Bindung zu ihm aufzubauen, ohne dauerhaften Schaden anzurichten.",al={"was macht die zähmerrute","warum zähmerrute benutzen","zähmerrute lore"}},{q="Was hat der Jäger vor dieser Prüfung gezähmt?",a="Bevor Ihr Euch dem Gray Forest Wolf gestellt habt, habt Ihr Eure anfängliche Beherrschung des Umgangs mit Wildtieren unter Beweis gestellt, indem Ihr gemeistert habt, wie man einen Waldeber zähmt.",al={"vorherige zähmungslektion","was wurde vor dem wolf gezähmt"}},{q="Behaltet Ihr den Gray Forest Wolf als dauerhaften Begleiter?",a="Nein, die Prüfung ist als gezielte Lektion konzipiert, um die Technik der Bindung zu Wildtieren zu meistern. Sobald Ihr Eure Fähigkeiten geübt habt, bringt Ihr die Zähmerrute zu Josephine Carson zurück.",al={"behält man den wolf","ist der wolf ein dauerhafter begleiter"}}},fp="16,228,22.510.0,28.478.0,35.164.0,35.178.0,34.125.0,32.191.0,43.131.0,58.174.0"}
P.entries["quest:94864"] = {n="Taming the Beast",s="Taming the Beast ist der Höhepunkt der frühen Ausbildung eines Jägers im Wald von Elwynn unter der Aufsicht von Josephine Carson. Nachdem sie die Beherrschung von Ebern und Wölfen unter Beweis gestellt haben, werden Jäger damit beauftragt, eine Zähmerrute zu verwenden, um einen Young Forest Bear zu beruhigen und sein Vertrauen zu gewinnen. Diese letzte Prüfung vertieft den Einklang eines Jägers mit Wildtieren und bewahrt das natürliche Gleichgewicht des Waldlandes durch Respekt und Geschick.",h="Taming the Beast ist der Höhepunkt der frühen Ausbildung eines Jägers im Wald von Elwynn unter der Aufsicht...",kw={"einklang mit tieren","tierausbildung","wald von elwynn","jägerquest","josephine carson","zähmerrute","taming the beast","young forest bear"},ang={["class:Hunter"]="Diese Prüfung markiert einen entscheidenden Übergangsritus für Jägerlehrlinge und wandelt einfache Fährtenleserfähigkeiten in einen tiefen, einfühlsamen Einklang mit den Bestien der Wildnis um.",["faction:Alliance"]="Erfahrene Meister der Tiere verstärken die Späher der Wildnis der Allianz und stellen disziplinierte Begleiter bereit, die in der Lage sind, Gehöfte zu verteidigen und Handelsstraßen in den Territorien von Sturmwind zu patrouillieren.",["race:Human"]="Für Jäger der Menschen, die im Wald von Elwynn trainieren, lehrt das Zähmen einheimischer Wildtiere die Wichtigkeit der Koexistenz mit den natürlichen Raubtieren des Königreichs, anstatt sie bloß auszurotten."},sec={{t="Die letzte Prüfung der Jagd",b="Angehende Jäger im Wald von Elwynn durchlaufen ein rigoroses Training, um die wilden Kreaturen zu verstehen, die ihre Lande teilen. Nachdem sie bereits die Beherrschung über den listigen Wolf und den zähen Eber bewiesen haben, stehen Jäger vor einer letzten Prüfung von Mut und Geduld. Josephine Carson weist sie an, sich dem Young Forest Bear zu stellen, dem stämmigsten und mächtigsten der gewöhnlichen Raubtiere des Waldes. Dieser Ritus prüft, ob ein Jäger der rohen Stärke des Bären widerstehen und sein Vertrauen gewinnen kann, anstatt ihn einfach zu unterwerfen."},{t="Respekt und Gleichgewicht in Elwynn",b="Die Lektion hinter dem Zähmen der Tierwelt Elwynns wurzelt in Respekt statt in Beherrschung. Waldbären verkörpern die Muskelkraft und Vitalität des Waldlandes und spielen eine entscheidende Rolle bei der Aufrechterhaltung der natürlichen Ordnung. Durch den Einsatz einer speziell vorbereiteten Zähmerrute lernen Jäger, die Aggression der Bestie zu besänftigen und ein echtes Band gegenseitigen Verständnisses aufzubauen. Ein solch beeindruckendes Tier erfolgreich zu beruhigen, vertieft den spirituellen Einklang des Jägers mit der Wildnis und schließt seine grundlegenden Lektionen unter Carsons Führung ab."}},faq={{q="Wer weist Jägern diese Prüfung zu?",a="Josephine Carson beaufsichtigt diese Prüfung für Jäger, die im Wald von Elwynn trainieren. Sie beurteilt den Fortschritt des Jägers, nachdem dieser erfolgreich geringere Bestien gezähmt hat, und bietet die notwendige Anleitung sowie die Zähmerrute, die zum Zähmen des Waldbären benötigt wird. Sobald die Prüfung abgeschlossen ist, bringen Jäger die Rute direkt zu ihr zurück, um den Abschluss ihrer Ausbildung zu markieren.",al={"wer vergibt taming the beast","questgeber für taming the beast","josephine carson quest"}},{q="Welche Bestien müssen vor dieser Herausforderung gezähmt werden?",a="Bevor sie die Herausforderung annehmen, einen Young Forest Bear zu zähmen, müssen Jäger zunächst ihr Geschick und ihre Geduld beweisen, indem sie einen Eber und einen Wolf zähmen. Diese vorbereitenden Prüfungen zeigen, dass der Jäger sowohl mit aggressiven als auch mit rudelorientierten Tieren umgehen kann, bevor er versucht, sich der schieren Kraft und Stärke von Elwynns Bären zu stellen.",al={"vorausgesetzte tiere zum zähmen","was habe ich vor dem bären gezähmt","zuvor gezähmte tiere"}},{q="Warum werden Jäger nach einem Young Forest Bear ausgesandt?",a="Der Young Forest Bear repräsentiert die Muskelkraft und Stärke der Tierwelt im Wald von Elwynn. Während Eber und Wölfe die Fähigkeit eines Jägers prüfen, mit schnellen oder widerstandsfähigen Tieren umzugehen, dient der Bär als ultimativer Test für Ausdauer, Respekt und körperlichen Mut. Das Vertrauen eines solch mächtigen Raubtiers zu gewinnen, beweist die vollständige Beherrschung des grundlegenden Umgangs mit Tieren.",al={"warum young forest bear zähmen","zweck von young forest bear","warum bären in elwynn"}},{q="Was ist der Zweck der Zähmerrute?",a="Die Zähmerrute ist ein spezialisiertes Trainingsinstrument, das von Josephine Carson bereitgestellt wird, um Jäger beim Beruhigen wilder Tiere zu unterstützen. Sie bündelt den Fokus, der erforderlich ist, um einen aggressiven Young Forest Bear zu besänftigen, ohne ihn zu töten, sodass der Jäger eine friedliche Verbindung knüpfen kann. Sobald die Prüfung abgeschlossen ist, wird die Rute an Carson zurückgegeben, womit die Ausbildung abgeschlossen ist.",al={"zweck der zähmerrute","was macht die zähmerrute","warum zähmerrute nutzen"}},{q="Wie hilft das Zähmen von Tieren dem Wald von Elwynn?",a="Das Zähmen von Wildtieren gilt als wesentliche Praxis zur Aufrechterhaltung des natürlichen Gleichgewichts im Wald von Elwynn. Indem Jäger Raubtieren mit Respekt und Zurückhaltung begegnen, anstatt sie zu jagen, tragen sie dazu bei, die Harmonie zwischen dem lokalen Ökosystem und den humanoiden Siedlungen in der gesamten Region zu bewahren, und stellen sicher, dass gefährliche Bestien friedlich gelenkt statt vernichtet werden.",al={"warum das gleichgewicht von elwynn wichtig ist","gleichgewicht im wald von elwynn","zähmen und waldgleichgewicht"}},{q="Was bedeutet der Abschluss dieser Lektion für einen Jäger?",a="Der Abschluss dieser letzten Aufgabe vertieft den inneren Einklang eines Jägers mit den Tieren der Wildnis. Indem er das Vertrauen von Elwynns mächtigster Kreatur gewinnt, geht der Jäger über einfache Jagdtechniken hinaus und meistert die spirituelle Verbindung, die erforderlich ist, um lebenslange Partnerschaften mit tierischen Begleitern in ganz Azeroth einzugehen.",al={"was passiert nach dem zähmen des bären","abschluss der jägerausbildung","bedeutung des einklangs mit tieren"}},{q="Wo sind Young Forest Bears zu finden?",a="Young Forest Bears streifen durch die bewaldeten Gebiete im Wald von Elwynn und leben zwischen den dichten Bäumen an der Seite von Wölfen und Spinnen. Jäger, die sich aus nahe gelegenen Siedlungen hinauswagen, müssen diese kräftigen Geschöpfe durch das Unterholz des Waldes aufspüren, um die Zähmerrute anzuwenden und Carsons letzte Weisung zu erfüllen.",al={"standort von young forest bear","wo man bären in elwynn findet","waldbär elwynn"}}},fp="16,388,27.493.0,29.509.0,34.354.0,49.325.0,47.350.0,38.343.0,42.366.0,54.308.0,35.294.0"}
P.entries["quest:94896"] = {n="Aid For The Refugees",s="Aid For The Refugees dreht sich um die vertriebenen Überlebenden von Ban'aethal, einer Siedlung tief im Schattenwindwald, die mitten in der Nacht plötzlich evakuiert wurde. Da ihre Heimat in den Himmel stürzt und die umliegende Wildnis viel zu gefährlich zum Betreten geworden ist, sind die Flüchtlinge auf mutige Reisende angewiesen, um die Besitztümer zu bergen, die sie zurücklassen mussten.",h="Aid For The Refugees dreht sich um die vertriebenen Überlebenden von Ban'aethal, einer Siedlung tief im...",kw={"aid for the refugees","ban'aethal","banaethal","habseligkeiten","ealaane","flüchtlinge","schattenwindwald"},sec={{t="Ein verzweifelter Hilferuf",b="Aid For The Refugees ist eine Bitte um Unterstützung von Ealaane und ihren vertriebenen Mitdörflern. Nachdem sie nur knapp aus ihren Heimen tief im Schattenwindwald geflohen sind, haben sich die Überlebenden mit fast nichts in den Händen versammelt, in der Hoffnung, dass ein vorbeiziehender Reisender den Gefahren trotzt, die sie hinter sich gelassen haben."},{t="Das Unheil von Ban'aethal",b="Die Siedlung Ban'aethal ereilte mitten in der Nacht ein undenkbares Schicksal, als das Dorf plötzlich begann, in den Himmel zu stürzen. Die bizarre und furchterregende Katastrophe ließ den Bewohnern nur wenige Augenblicke zur Flucht und zwang sie dazu, ihre persönlichen Besitztümer zurückzulassen, als die umliegenden Wälder feindselig und gefährlich wurden."}},faq={{q="Wer ist Ealaane?",a="Ealaane ist eine Flüchtende aus Ban'aethal, die zusammen mit anderen entkam, als ihre Siedlung einzustürzen begann. Sie bittet vorbeiziehende Abenteurer, die in Richtung Schattenwindwald reisen, in den Ruinen zurückgelassene persönliche Besitztümer zu bergen.",al={"wer gab aid for the refugees","questgeber aid for the refugees","ealaane"}},{q="Was geschah mit Ban'aethal?",a="Ban'aethal war eine Siedlung tief im Schattenwindwald. Ihre Bewohner wurden kürzlich aufgrund einer plötzlichen und bizarren Katastrophe mitten in der Nacht gezwungen zu evakuieren.",al={"was ist banaethal","wo ist banaethal","dorf ban aethal"}},{q="Warum mussten die Dorfbewohner Ban'aethal evakuieren?",a="Die Evakuierung wurde mitten in der Nacht plötzlich ausgelöst, als Ban'aethal begann, in den Himmel zu stürzen. Das Dorf und der umliegende Wald wurden für die Bewohner viel zu gefährlich, um dort zu bleiben oder dorthin zurückzukehren.",al={"warum banaethal evakuieren","in den himmel stürzen","katastrophe von ban aethal"}},{q="Warum bitten die Dorfbewohner darum, ihre Besitztümer zu bergen?",a="Die Katastrophe schlug mitten in der Nacht plötzlich zu und zwang die Dorfbewohner, mit so gut wie nichts um ihr Leben zu fliehen. Da der Wald und die Ruinen nun von Gefahren heimgesucht werden, sind sie auf fähige Abenteurer angewiesen, um das Zurückgelassene zu bergen.",al={"warum habseligkeiten gebraucht werden","zurückgelassene habseligkeiten","warum habseligkeiten bergen"}},{q="Was ist der Schattenwindwald?",a="Der Schattenwindwald ist die bewaldete Region, in der die Siedlung Ban'aethal liegt. Nach der bizarren Katastrophe, die das Dorf zerriss, ist der Wald für gewöhnliche Leute extrem gefährlich geworden.",al={"wo ist der schattenwindwald","schattenwindwald lore"}},{q="Können die Flüchtlinge in ihre Heimat zurückkehren?",a="Nein. Laut Ealaane sind sowohl der Schattenwindwald als auch die Ruinen von Ban'aethal viel zu gefährlich, als dass die vertriebenen Bewohner jemals auf eigene Faust dorthin zurückkehren könnten.",al={"können flüchtlinge zurückkehren","ist banaethal sicher"}}},fp="20,359,16.297.0,26.311.0,15.222.0,28.182.0,50.204.0,66.247.0,26.196.0,39.155.0"}
P.entries["quest:94897"] = {n="The Fate of a Loved One",s="The Fate of a Loved One ist eine Quest rund um Resaan, der sich in die gefaehrlichen Ruinen von Ban'aethal wagte, um Vorraete zu beschaffen, und nie zurueckkehrte. Mehr als eine Woche spaeter bittet sein trauernder Partner Reisende auf dem Weg zu den Ruinen darum, sein Schicksal aufzudecken und ihn nach Hause zu bringen oder sein geschaetztes Erbstueck zu bergen.",h="The Fate of a Loved One ist eine Quest rund um Resaan, der sich in die gefaehrlichen Ruinen von Ban'aethal...",kw={"ban'aethal","erbstueck","resaan","ruinen von ban'aethal","vorraete","the fate of a loved one"},sec={{t="Ein verzweifeltes Flehen",b="The Fate of a Loved One dreht sich um das verzweifelte Flehen von jemandem, dessen Partner Resaan in die Ruinen von Ban'aethal zurueckgekehrt ist. Trotz eindringlicher Bitten dazubleiben, fuehlte Resaan sich gedraengt, den Ruinen auf der Suche nach Vorraeten zu trotzen, und liess jemanden zurueck, der nun in qualvoller Ungewissheit wartet."},{t="Verschollen in den Ruinen",b="Mehr als eine Woche ist vergangen, seit Resaan aufgebrochen ist, was jede berechtigte Erwartung an eine rasche Rueckkehr bei Weitem uebersteigt. Reisende nach Ban'aethal werden angefleht, in den Ruinen nach ihm zu suchen – um ihm den Weg zurueckzuweisen, falls er noch am Leben ist, oder um sein Familienerbstueck zu bergen, falls nur noch eine Tragoedie vorzufinden ist."}},faq={{q="Wer ist Resaan?",a="Resaan ist jemand, der in die Ruinen von Ban'aethal zurueckkehrte, um Vorraete zu sammeln, obwohl er angefleht worden war zu bleiben. Nach ueber einer Woche ohne jede Nachricht befuerchtet sein Partner, dass er in den Ruinen ein tragisches Ende gefunden hat.",al={"wer ist resaan","wo ist resaan","resaan finden"}},{q="Was sind die Ruinen von Ban'aethal?",a="Die Ruinen von Ban'aethal sind ein gefaehrlicher Ort, an den sich Resaan auf der Suche nach notwendigen Vorraeten begab. Sein Partner haelt die Reise fuer derart riskant, dass ein einwoechiges Ueberleben dort allein unwahrscheinlich ist.",al={"was ist banaethal","ruinen von banaethal lore","wo ist banaethal"}},{q="Warum kehrte Resaan nach Ban'aethal zurueck?",a="Resaan kehrte eigens nach Ban'aethal zurueck, um Vorraete zu holen. Er entschied sich fuer die gefahrvolle Reise, obwohl sein geliebter Partner ihn anflehte, nicht zu gehen.",al={"warum kehrte resaan zurueck","warum resaan in banaethal"}},{q="Worum bittet der Questgeber Euch, zurueckzubringen?",a="Sollte Resaan noch am Leben sein, bittet der Questgeber darum, ihn sicher nach Hause zu geleiten. Falls er in den Ruinen umgekommen ist, fleht der Questgeber um die Bergung seines persoenlichen Erbstuecks als letztes Andenken.",al={"was will der questgeber","was passiert wenn resaan tot ist"}},{q="Wie lange wird Resaan schon vermisst?",a="Resaan wird seit ueber einer Woche vermisst, seit er zu den Ruinen von Ban'aethal aufgebrochen ist. Angesichts der Gefahren der Gegend laesst diese anhaltende Stille seinen Partner das Schlimmste befuerchten.",al={"wie lange ist resaan vermisst","wie lange ist resaan schon fort"}},{q="Wer bietet diese Quest an?",a="Die Quest wird von Resaans trauerndem Partner oder Geliebten angeboten, der verzweifelt nach Gewissheit sucht und bereit ist, vorbeikommende Reisende auf dem Weg nach Ban'aethal um Hilfe zu bitten.",al={"wer vergibt the fate of a loved one","the fate of a loved one questgeber"}}},fp="23,296,16.297.0,21.290.0,14.217.0,33.199.0,36.156.0,47.193.0,33.180.0,22.165.0"}
P.entries["quest:949"] = {n="Das Lager des Schattenhammers",s="Das Lager des Schattenhammers ist eine Aufklärungsmission der Allianz gegen die geheimniskrämerischen Kultisten, die ihr Lager um die Meistergleve an der südlichen Dunkelküste aufgeschlagen haben. Nachdem die Ermittler durch eine Schale der Wahrsagung einen Blick auf deren Ritualstätte erhaschen konnten, müssen sie die Ausgrabung infiltrieren, um herauszufinden, was der Schattenhammer ans Tageslicht bringen will.",h="Das Lager des Schattenhammers ist eine Aufklärungsmission der Allianz gegen die geheimniskrämerischen...",kw={"dunkelküste","die meistergleve","onu","schale der wahrsagung","das twilight-lager","twilight tome","schattenhammer"},ang={["class:Druid"]="Die Erforschung der Kultistenaktivitäten ist für die Wächter des Cenarius von entscheidender Bedeutung, um verderbende uralte Wesenheiten sicher unter der Erde zu halten.",["faction:Alliance"]="Das Unterbinden der merkwürdigen Ausgrabungen des Kults verhindert, dass eine aufkeimende Bedrohung das nördliche Kalimdor destabilisiert.",["race:NightElf"]="Der Schattenhammer schändet heilige Länder von Kalimdor mit finsterer Zauberei direkt unter den Wipfeln der uralten Haine der Dunkelküste."},sec={{t="Die Erkundung der Ausgrabung",b="Die Meistergleve ragte lange Zeit als unheilvolles, versteinertes Mysterium in den zerklüfteten Hügeln der südlichen Dunkelküste empor, doch das plötzliche Auftauchen des Schattenhammerkults verwandelte ein uraltes Kuriosum in eine akute Bedrohung. Nachdem Späher mithilfe einer Schale der Wahrsagung in deren Befestigungen geblickt haben, werden sie mitten in das Lager geschickt, um die wahren Absichten der Kultisten aufzudecken, bevor Verteidigungsmaßnahmen ergriffen werden können."},{t="Der illustrierte Foliant",b="Das Durchkämmen des Lagers offenbart, dass die Kultisten keine einfachen Plünderer oder Banditen sind; ihre Unternehmung wird von tiefgründigen, okkulten Studien geleitet. Tief in ihrem nördlichen Lager liegt ein uralter, sorgfältig handgeschriebener Foliant, der mit meisterhaften, doch verstörenden Zeichnungen versehen ist. Dieser Text dient als Beweis dafür, dass der Schattenhammer ganz gezielt jenes kolossale Wesen untersucht, das unter der Erde begraben liegt."}},faq={{q="Was ist das Ziel der Quest Das Lager des Schattenhammers?",a="Ihr müsst das Lager des Schattenhammers nahe der Meistergleve an der südlichen Dunkelküste infiltrieren und einen Hinweis auf ihre Beweggründe bergen – genauer gesagt ein handgeschriebenes Ritualbuch, das in ihrem Lager liegt.",al={"questziel das twilight-lager","was tun bei das twilight-lager"}},{q="Wer schickt Euch aus, um das Lager zu untersuchen?",a="Die Quest wird direkt von der Schale der Wahrsagung am Rundblick oberhalb der Meistergleve angenommen und setzt die Untersuchung im Auftrag des uralten Beschützers Onu fort.",al={"wer gibt das twilight-lager","questgeber das twilight-lager"}},{q="Wo befindet sich der Hinweis im Lager?",a="Der gesuchte Hinweis ist der Twilight Tome im nördlichen Teil des Lagers. Andere Folianten im Lager können gefährliche Attrappen sein, die Bannmagie gegen Eindringlinge entfesseln.",al={"wo ist das buch","fundort twilight tome","hinweis finden das twilight-lager"}},{q="Warum befindet sich der Schattenhammer an der Meistergleve?",a="Die Kultisten sind besessen von den uralten, dunklen Mächten der Alten Götter und ihrer Diener. Sie graben den gewaltigen versteinerten Kadaver aus, der von der riesigen Steinklinge durchbohrt wird, um das uralte Übel zu erforschen oder zu erwecken, das dort verblieben ist.",al={"warum sind kultisten an der meistergleve","ziel schattenhammer dunkelküste"}},{q="Was geschieht nach dem Fund des Folianten?",a="Die Bergung des Folianten führt zur Quest Rückkehr zu Onu, die Euch anweist, die entdeckten Schriften nach Norden zum uralten Urtum im Hain der Uralten zu bringen.",al={"folgequest nach das twilight-lager","wohin nach twilight tome"}}},fp="17,319,15.403.0,20.395.1,44.211.0,38.174.0,36.178.0,52.225.0,36.160.0"}
P.entries["quest:94947"] = {n="Welcome to Azeroth",s="'Welcome to Azeroth' markiert die Ankunft von Skyborne-Reisenden in der Menschenhauptstadt Sturmwind durch das Skyborne-Portal. Beim Melden in Burg Sturmwind erhalten Neuankömmlinge die formelle Anerkennung und die Erlaubnis von Hochlord Bolvar Fordragon, frei durch die Länder der Allianz zu reisen.",h="'Welcome to Azeroth' markiert die Ankunft von Skyborne-Reisenden in der Menschenhauptstadt Sturmwind durch...",kw={"bolvar fordragon","hochelf","der hohe orden","kirin tor","portal","skyborne","burg sturmwind","welcome to azeroth"},ang={["faction:Alliance"]="Hochlord Bolvar Fordragon heißt den Hohen Orden im Namen von König Anduin Wrynn offiziell willkommen und erteilt ihm die Erlaubnis, die Länder der Allianz frei zu bereisen.",["race:Skyborne"]="Für die Skyborne öffnet diese Audienz hochelfischen Reisenden, die durch das Portal eintreffen, formell die Tore von Sturmwind und des Allianzgebiets."},sec={{t="Ankunft in der Hauptstadt",b="Durch das mystische Skyborne-Portal reisend, betreten Reisende direkt die geschäftige Hauptstadt Sturmwind. Mit der Aufgabe betraut, sich am Sitz der Führung der Menschen zu melden, machen sich Neuankömmlinge auf den Weg durch die großen Straßen der Stadt hinauf zu Burg Sturmwind, um vor der Regentschaft vorzusprechen."},{t="Eine Audienz beim Regenten",b="Im prächtigen Thronsaal stehend, begrüßt Hochlord Bolvar Fordragon eintreffende Mitglieder des Hohen Ordens nach vorheriger Ankündigung durch einen Boten der Kirin Tor. Mit der Bemerkung, dass es schon geraume Zeit her sei, dass Hochelfen durch die Hallen von Burg Sturmwind schritten, nimmt der Regent sie gütig als Gäste auf und gewährt ihnen im Namen des Königs freies Geleit durch alle Gebiete der Allianz."}},faq={{q="Worum geht es in dieser Quest?",a="'Welcome to Azeroth' ist eine Einführungsquest, bei der ein Reisender durch das Skyborne-Portal nach Sturmwind tritt und vor Hochlord Bolvar Fordragon in Burg Sturmwind vorspricht.",al={"was ist welcome to azeroth","quest welcome to azeroth"}},{q="Wer ist Bolvar Fordragon?",a="Hochlord Bolvar Fordragon dient als Regent des Throns von Sturmwind und regiert das Reich in Burg Sturmwind im Namen des jungen Königs Anduin Wrynn, während König Varian weiterhin verschollen bleibt.",al={"wer ist bolvar fordragon","regent von sturmwind"}},{q="Warum empfängt Bolvar die Skyborne?",a="Ein Bote der Kirin Tor setzte Bolvar Fordragon davon in Kenntnis, dass Mitglieder des Hohen Ordens eintreffen würden. Bolvar nimmt sie als Gäste der Krone auf und erteilt ihnen die Erlaubnis, die Länder der Allianz frei zu erkunden und zu bereisen.",al={"warum sind skyborne in sturmwind","hochelfen sturmwind"}},{q="Was ist der Hohe Orden?",a="Der Hohe Orden stellt die Fraktion oder Gruppierung dar, die mit den Skyborne-Hochelfen verbunden ist, deren Ankunft der Führung von Sturmwind durch die Kirin Tor angekündigt wurde.",al={"wer ist der hohe orden","lore zum hohen orden"}},{q="Wohin führt das Skyborne-Portal?",a="Das Skyborne-Portal führt Reisende direkt in die Menschenhauptstadt Sturmwind, sodass Neuankömmlinge geradewegs zu Burg Sturmwind weitergehen können, um eine Audienz bei der Krone zu erbitten.",al={"ziel des skyborne-portals","wohin führt das portal"}},{q="Dürfen sich die Skyborne im gesamten Gebiet der Allianz aufhalten?",a="Bolvar Fordragon heißt die Skyborne im Namen des Königs formell als Gäste willkommen und gewährt ihnen ausdrücklich die Erlaubnis, ungehindert durch die Länder der Allianz zu reisen.",al={"gehören skyborne zur allianz","skyborne allianz empfang"}}},fp="18,272,22.292.0,27.369.0,25.187.0,24.188.0,37.226.0,23.158.0,36.180.0,55.171.0"}
P.entries["quest:95"] = {n="Svens Rache",s="Getrieben von Trauer und Rache bittet der Einsiedler Sven Yorgen Reisende darum, zu seinem zerstörten Bauernhof im südlichen Dämmerwald zurückzukehren. Während er Jahre damit verbrachte, die schattenhaften Reiter zu jagen, die seine Familie ermordeten, vergrub einst eine verdächtige Gestalt etwas in der Nähe seiner Scheune, das Antworten liefern könnte.",h="Getrieben von Trauer und Rache bittet der Einsiedler Sven Yorgen Reisende darum, zu seinem zerstörten...",kw={"dunkle reiter","gebirgspass der totenwinde","dämmerwald","haufen lockerer erde","baumstumpf","sven yorgen","svens rache","yorgens bauernhof"},ang={["class:Paladin"]="Das gewaltsame Abschlachten von Unschuldigen durch finstere Mächte aus dem Gebirgspass der Totenwinde verlangt nach rechtschaffener Vergeltung und Gerechtigkeit für die Toten.",["faction:Alliance"]="Das Massaker an der Familie Yorgen ist ein weiteres Zeichen für die Isolation des Dämmerwalds und zeigt, wie weit die Reichweite dunkler Kräfte ohne regelmäßige Patrouillen der Armee von Sturmwind reicht."},sec={{t="Tragödie auf dem Bauernhof",b="Sven Yorgen war einst ein einfacher Bauer, der die Felder im südöstlichen Dämmerwald bestellte. Sein Leben zerbrach, als verhüllte Dunkle Reiter aus dem Gebirgspass der Totenwinde sein Gehöft angriffen und seine Familie abschlachteten, während er fort war. Als er zum Ort des Gemetzels zurückkehrte, erblickte Sven eine unbekannte Gestalt, die nahe der Scheune herumschlich und hastig etwas in der Erde vergrub. Sven entschied sich für Rache und brach unverzüglich auf, um die Mörder zu jagen, wobei er das Verborgene zurückließ."},{t="Geheimnisse ausgraben",b="Nun in den westlichen Hügeln lagernd und von Zorn verzehrt, benötigt Sven jemanden, der zu Yorgens Bauernhof zurückkehrt. Hinter einem alten Baumstumpf zwischen dem Bauernhaus und der zerstörten Scheune liegt ein hastig aufgeschütteter Haufen lockerer Erde. Was auch immer dort vergraben liegt, zu bergen, ist der erste Schritt, um zu verstehen, warum die schattenhaften Reiter überhaupt einen friedlichen Bauern aus dem Dämmerwald ins Visier nahmen."}},faq={{q="Wer ist Sven Yorgen?",a="Sven Yorgen war ein gewöhnlicher Bauer, der im südöstlichen Dämmerwald nahe der Grenze zum Gebirgspass der Totenwinde lebte. Nachdem er nach Hause zurückgekehrt war und seine Familie von finsteren Reitern ermordet vorgefunden hatte, gab er seinen Bauernhof auf und wurde zu einem Einsiedler, der davon besessen war, Rache an den Verantwortlichen zu üben.",al={"wer ist sven","sven lore","sven hintergrundgeschichte"}},{q="Was geschah mit Svens Bauernhof?",a="Svens Bauernhof wurde von den mysteriösen Dunklen Reitern aus dem Gebirgspass der Totenwinde überfallen. Sie schlachteten seine gesamte Familie ab und hinterließen das Anwesen in Trümmern, bevor Sven zurückkehren konnte, um sie zu verteidigen.",al={"tragödie auf yorgens bauernhof","was geschah mit svens bauernhof","warum ist svens bauernhof zerstört"}},{q="Wer vergrub etwas hinter der Scheune?",a="Sven sah kurz nach dem Massaker eine schattenhafte Gestalt in der Nähe seiner Scheune lauern, die einen Gegenstand vergrub. Sven floh in die Wildnis, um die Dunklen Reiter zu verfolgen, bevor er den Fremden fassen oder das Verborgene ausgraben konnte.",al={"wer vergrub den gegenstand","schattenhafte gestalt svens bauernhof","wer hob den erdhügel aus"}},{q="Wo befindet sich der Haufen lockerer Erde?",a="Der Haufen lockerer Erde befindet sich auf Yorgens Bauernhof im südöstlichen Dämmerwald, direkt hinter einem alten Baumstumpf zwischen der Scheune und dem zerstörten Bauernhaus vergraben.",al={"wo ist der erdhügel","erdhügel standort","wo ist der baumstumpf"}},{q="Wer sind die Dunklen Reiter?",a="Die Dunklen Reiter sind unheilvolle, verhüllte Reiter, die aus dem Gebirgspass der Totenwinde herabreiten. Über ihre Herkunft ist wenig bekannt, doch ihre gewaltsamen Übergriffe in den Dämmerwald hinterlassen nichts als Tod und Verderben.",al={"was sind die dunklen reiter","dunkle reiter lore","reiter des gebirgspasses der totenwinde"}},{q="Warum grub Sven den vergrabenen Gegenstand nicht selbst aus?",a="Als Sven nach Hause zurückkehrte und die Gestalt beim Vergraben des Gegenstands sah, war er von Trauer überwältigt und verfolgte sofort die sich zurückziehenden Dunklen Reiter. Als er sein verstecktes Lager aufschlug, war der Bauernhof überrannt und es war zu schmerzhaft für ihn, ihn noch einmal selbst aufzusuchen.",al={"warum untersuchte sven die erde nicht","warum ging sven fort"}}},fx={e064b97c={q="Warum möchte Sven Yorgen, dass der vergrabene Gegenstand geborgen wird?",a="Sven sucht Rache für das brutale Massaker an seiner Familie durch die mysteriösen Dunklen Reiter vom Gebirgspass der Totenwinde. Als er das Massaker entdeckte, sah er eine schattenhafte Gestalt, die hastig etwas bei seiner Scheune vergrub, bevor sie floh. Getrieben von Wut und dem Bedürfnis nach Antworten, glaubt Sven, dass das, was unter der Erde liegt, der Schlüssel dazu ist, aufzudecken, warum sein Hof ins Visier genommen wurde und wer bei der Zerstörung seiner Familie geholfen hat.",al={"warum will sven das","sven yorgen beweggrund","grund für sven rachequest"}}},fp="14,282,24.471.0,18.385.0,19.274.0,29.193.0,37.213.0,41.166.0,24.197.0,47.247.0"}
P.entries["quest:950"] = {n="Rückkehr zu Onu",s="Rückkehr zu Onu ist eine Allianz-Quest, die eine anfängliche Untersuchung der Kultisten abschließt, die entlang der Küste von Dunkelküste kampieren. Nachdem sie das Lager der Kultisten überfallen und versucht haben, den Twilight Tome zu lesen, birgt ein Abenteurer eine einzelne Seite mit Irrsinniges Gekritzel, um sie dem Ancient of Lore Onu im Hain der Uralten zu überbringen.",h="Rückkehr zu Onu ist eine Allianz-Quest, die eine anfängliche Untersuchung der Kultisten abschließt, die...",kw={"dunkelküste","der hain der uralten","irrsinniges gekritzel","die alten","onu","twilight tome","twilight's hammer"},ang={["class:Druid"]="Die chaotische, unnatürliche Resonanz des Gekritzels stellt einen Affront gegen die natürliche Ordnung dar, die Druiden gemeinsam mit Treants wie Onu zu bewahren suchen.",["faction:Alliance"]="Die Untersuchung der Kultaktivitäten entlang der Küste von Dunkelküste stellt sicher, dass Nachtelfensiedlungen wie Auberdine vor verborgenen Bedrohungen geschützt bleiben.",["race:NightElf"]="Die Schändung der Küsten von Dunkelküste durch dunkle Kultisten bedroht das Gleichgewicht, das von den Ancients of Lore bewacht wird, was Onus Warnungen für die Kaldorei zutiefst persönlich macht."},sec={{t="Ein Blick in den Wahnsinn",b="Beim Entdecken des Twilight Tome innerhalb des Lagers des Twilight's Hammer erleidet jeder, der in seine Blätter blickt, einen unmittelbaren Angriff auf seine Sinne. Der geschriebene Text schwimmt und tanzt über das Pergament, und einst kunstvolle Schriftzüge verwandeln sich in groteske Figuren. Die geistige Anstrengung ist so überwältigend, dass das Herausreißen einer einzigen Seite mit gekritzelten Notizen alles ist, was ein sterblicher Geist ertragen kann, bevor er dem Schwindel erliegt."},{t="Uralte Verdächtigungen",b="Wenn sie Onu übergeben wird, erkennt der hoch aufragende Ancient die unnatürliche Aura, die das Fragment durchdringt. Das Pergament strahlt eine chaotische, urzeitliche Magie aus, die Onu direkt dem Wirken der uralten, schattenhaften Kräfte zuschreibt, die unter der Erde begraben liegen. Während das Gekritzel schwer zu entziffern ist, bestätigt es, dass die Präsenz des Twilight's Hammer in Dunkelküste nicht bloßes Banditentum ist, sondern Teil eines tieferen, blasphemischen Plans."}},faq={{q="Was ist die Seite aus dem Twilight Tome?",a="Die Seite, einfach bekannt als Irrsinniges Gekritzel, ist ein herausgerissenes Blatt aus dem heiligen Buch des Kults. Der Anblick verursacht schwere geistige Qualen, da sich die Schrift in groteske, sich verschiebende Muster windet, die an urzeitliche Leerenmagie gebunden sind.",al={"irrsinniges gekritzel","was ist das gekritzel","seite aus dem twilight tome"}},{q="Wer ist Onu?",a="Onu ist ein Ancient of Lore, der im Hain der Uralten im südlichen Dunkelküste verwurzelt ist. Er fungiert als älterer Wächter und Gelehrter, der Nachtelfen und Verbündete der Allianz gegen aufkommende Verderbnis im Wald anleitet.",al={"wer ist onu","onu dunkelküste","treant onu"}},{q="Was lernt Onu aus dem Gekritzel?",a="Onu spürt chaotische, urzeitliche Energien, die von der Seite ausgehen, und identifiziert den Einfluss uralter, bösartiger Wesenheiten. Die Schriften legen nahe, dass die Kultisten des Twilight's Hammer aktiv nach Reliktstätten und verborgenen Mächten in ganz Dunkelküste suchen.",al={"was hat onu gefunden","bedeutung des gekritzels"}},{q="Warum ist der Twilight's Hammer in Dunkelküste?",a="Der Kult wird nach Dunkelküste gezogen, um verfallene Elfenstätten auszugraben und Überreste uralter Macht freizulegen, die mit urzeitlicher Dunkelheit und den Alten Göttern verbunden sind, wobei sie das Chaos des Landes nutzen, um ihre Riten zu tarnen.",al={"kultisten in dunkelküste","warum ist der twilight's hammer hier"}},{q="Wohin führt diese Untersuchung als Nächstes?",a="Nach der Entdeckung der Präsenz des Kults richtet Onu seine Aufmerksamkeit auf die uralten Elfenruinen der Ruinen von Mathystra im Norden und weist Abenteurer an, uralte Relikte zu sichern, bevor die Kultisten sie ergreifen können.",al={"welche quest kommt als nächstes","nach rückkehr zu onu"}},{q="Warum verursacht das Lesen des Buches Schwindel?",a="Der Twilight Tome ist mit dunkler, wahnsinnig machender Magie der Leere und des Chaos beschriftet. Die Glyphen verwirren aktiv sterbliche Geister und verursachen Halluzinationen und Ohnmachtsanfälle, um Außenstehende daran zu hindern, ihre Geheimnisse zu enthüllen.",al={"warum schwindel durch das buch","effekte des twilight tome"}}},fp="13,336,22.414.0,18.421.1,46.218.0,11.210.0,39.241.0,42.194.0,40.208.1,42.205.0"}
P.entries["quest:95041"] = {n="Data Hoarders",s="Data Hoarders ist eine Aufgabe von Jemma Quikswitch, einer im Exil lebenden Gnomin mit Wohnsitz in Eisenschmiede. Während der verzweifelten Evakuierung von Gnomeregan kopierte sie die wertvollsten Archive ihrer Familie auf Lochkarten, nur um mehrere davon in den eisigen Schneewehen vor den Toren der Stadt zu verlieren. Die Wiederbeschaffung dieser verlorenen Datenkarten bedeutet die Rettung von allem, angefangen bei fortschrittlichen marinebaulichen Konstruktionsplänen bis hin zu unersetzlichen Familienrezepten.",h="Data Hoarders ist eine Aufgabe von Jemma Quikswitch, einer im Exil lebenden Gnomin mit Wohnsitz in...",kw={"data hoarders","dun morogh","gnomeregan","eisenschmiede","jemma quikswitch","lochkarten","zweiter krieg","u-boot-rumpf"},ang={["faction:Alliance"]="Die Allianz verlässt sich stark auf den gnomischen Erfindungsgeist; vertriebenen Flüchtlingen dabei zu helfen, Aufzeichnungen kriegszeitlicher Ingenieurskunst zu bewahren, stellt sicher, dass wertvolles technisches Wissen der Allianz nicht für immer verloren geht.",["profession:Cooking"]="Direkt neben erstklassigen Konstruktionsplänen der Ingenieurskunst verbirgt sich Oma Quikswitchs persönliches Chilirezept – ein Beweis dafür, dass gutes Essen genauso viel emotionalen Wert besitzt wie Wehrtechnik.",["profession:Engineering"]="Ingenieure vermögen den immensen Wert zu schätzen, der auf diesen Karten verborgen liegt, da sie authentische Baupläne für U-Boot-Rümpfe aus dem Zweiten Krieg sowie komplexe arkanotechnische Gleichungen enthalten.",["race:Gnome"]="Für gnomische Abenteurer ist die Wiederbeschaffung dieser Lochkarten eine Frage der kulturellen Bewahrung, um sicherzustellen, dass lebenswichtige Erfindungen und Familienerinnerungen nicht an die radioaktiven Ruinen ihrer Heimat verloren gehen."},sec={{t="Ein Gerangel im Schnee",b="Als die Invasion der Troggs und die darauffolgende Strahlenkatastrophe die Gnome aus Gnomeregan vertrieben, flohen Tausende mit allem Hab und Gut, das sie im Chaos an sich reißen konnten. Jemma Quikswitch unternahm den umsichtigen Schritt, Generationen an Familienwissen in physische Lochkartenarchive zu übertragen. Tragischerweise fielen aus einer beschädigten Tasche mehrere entscheidende Karten in die Schneefelder rund um die gefallene Stadt. Ohne diese fehlenden Lochkarten lesen sich die verbleibenden Daten als unentzifferbares Kauderwelsch, was das geistige Erbe ihrer Familie auszulöschen droht."},{t="Gleichungen und Chili",b="Gnomische Datenarchive spiegeln die eigentümliche Spannweite der Prioritäten ihrer Zivilisation wider. Die Aufzeichnungen der Familie Quikswitch umfassen tiefgründige arkanotechnische Feldgleichungen, wichtige Rumpfentwürfe für U-Boote aus dem Zweiten Krieg und Oma Quikswitchs geheimes Chilirezept. Für einen Außenstehenden mag die Kombination von militärischer Ingenieurskunst mit häuslichem Kochen merkwürdig erscheinen, doch für überlebende Flüchtlinge in Eisenschmiede bedeutet das Bewahren häuslicher Annehmlichkeiten genauso viel wie das Bewahren technologischer Wunder."}},faq={{q="Wer ist Jemma Quikswitch?",a="Jemma Quikswitch ist ein gnomischer Flüchtling, der dem Fall von Gnomeregan entkommen konnte und nun sicher in den Zwergenhallen von Eisenschmiede lebt.",al={"jemma quikswitch","wer vergibt data hoarders","questgeber data hoarders"}},{q="Welche Daten sind auf den verlorenen Karten gespeichert?",a="Die Lochkarten bergen die Archive der Familie Quikswitch, darunter arkanotechnische Gleichungen, auf den Zweiten Krieg zurückgehende U-Boot-Rumpfentwürfe sowie Oma Quikswitchs Chilirezept.",al={"was sind die lochkarten","was war auf den karten","quikswitch-archive"}},{q="Wo gingen die Datenkarten verloren?",a="Sie rutschten durch ein Loch in Jemmas Rucksack, während sie aus Gnomeregan floh, sodass sie im verschneiten Gelände direkt vor den Toren der unterirdischen Stadt in Dun Morogh begraben liegen.",al={"wo sind die karten","fundort der datenkarten","wo hat sie sie verloren"}},{q="Warum kann Jemma die verbliebenen Karten ohne die fehlenden nicht lesen?",a="Jemma berichtet, die Daten seien ohne die fehlenden Lochkarten zu sehr durcheinandergebracht, als dass man sie wiederherstellen könnte. Die Quest erklärt nicht, wie die Karten jene Informationen verschlüsseln oder organisieren.",al={"warum werden alle karten gebraucht","durcheinandergebrachte daten","lochkartendaten"}},{q="Welche Rolle spielten Gnome im Zweiten Krieg hinsichtlich U-Booten?",a="Während des Zweiten Krieges leisteten Gnome durch hochentwickelte Ingenieurskunst einen gewaltigen Beitrag zu den militärischen Bemühungen der Allianz, namentlich durch die Konstruktion und Steuerung von tauchfähigen Wasserfahrzeugen, um den Seestreitkräften der Horde entgegenzuwirken.",al={"gnomen-u-boote zweiter krieg","u-boot-rumpf-entwürfe"}},{q="Warum leben gnomische Flüchtlinge in Eisenschmiede?",a="Nach dem plötzlichen Fall von Gnomeregan an Trogg-Invasoren und katastrophaler Verstrahlung flohen die überlebenden Gnome aus ihrer unterirdischen Heimat und erhielten von König Magni Bronzebart Zuflucht in der benachbarten Zwergenstadt Eisenschmiede angeboten.",al={"warum sind gnome in eisenschmiede","gnome leben bei zwergen"}}},fp="13,403,22.544.0,19.469.0,24.143.0,38.187.0,34.180.0,66.158.0,65.204.0,45.234.0"}
P.entries["quest:95065"] = {n="Fishin' Time",s="Fishin' Time ist eine einfache Besorgung für Gilbert Gray, einen älteren Angler, der die malerische Aussicht auf die Küste im Hafen von Sturmwind genießt. Da ihm gerade dann die Köder ausgehen, als die Fische anzubeißen beginnen, verlässt er sich auf Vorbeigehende, die zu den Canals der Stadt laufen und seinen Angelkasten wieder auffüllen.",h="Fishin' Time ist eine einfache Besorgung für Gilbert Gray, einen älteren Angler, der die malerische Aussicht...",kw={"canals","catherine leland","fishin time","gilbert gray","nachtkriecher","heller schmuckstein","hafen von sturmwind","der handelsdistrikt"},ang={["faction:Alliance"]="Sich Zeit zu nehmen, um einem alten Bürger wie Gilbert Gray zu helfen, spiegelt die bescheidenen alltäglichen Pflichten wider, die das Leben und die Moral in ganz Sturmwind aufrechterhalten.",["race:Human"]="Für Menschen, die Sturmwind ihr Zuhause nennen, ist es eine willkommene Abwechslung von der Politik des Königreichs, einem älteren Nachbarn bei einem ruhigen Angelnachmittag zu helfen."},sec={{t="Ein Tag am Wasser",b="Nicht jeder in Sturmwind wird von Politik, Krieg oder drohenden Verschwörungen vereinnahmt. Unten am Rand des Hafens verbringt Gilbert Gray seine ruhigen Tage damit, die Meeresbrise zu genießen und seiner Pose dabei zuzusehen, wie sie auf den Gezeiten tanzt. Doch ein enthusiastischer Angler kann leicht den Überblick über sein Angelzeug verlieren, und eine plötzliche Beißphase der Fische leert selbst eine gut vorbereitete Köderdose rasch. Anstatt seinen geschätzten Angelplatz aufzugeben, wendet sich der alte Mann an hilfsbereite Abenteurer, um seine Vorräte wieder aufzufüllen."},{t="Nachschub entlang der Canals",b="Sturmwinds lokale Angelbedürfnisse laufen über Catherine Leland, die ein bekanntes Angelgeschäft betreibt, das an den steinernen Canals direkt westlich des geschäftigen Handelsdistrikts liegt. Leland versorgt Angler in der ganzen Stadt mit Ködern und Angelhaken und stellt sicher, dass alte Stammgäste wie Gilbert Gray ihre Angeln nie vorzeitig einpacken müssen, nur weil es an einem glänzenden Schmuckstück oder einem zappelnden Nachtkriecher fehlt."}},faq={{q="Wer ist Gilbert Gray?",a="Gilbert Gray ist ein älterer Fischer, der am Wasser des Hafens von Sturmwind steht. Er verbringt seine Tage zufrieden damit, die Angel ins Meer auszuwerfen, und bittet vorbeikommende Abenteurer, frische Köder zu beschaffen, wenn seine eigenen Vorräte zur Neige gehen.",al={"gilbert gray","alter gray","wer gibt diese quest"}},{q="Wer ist Catherine Leland?",a="Catherine Leland ist Sturmwinds ansässige Angelbedarfsverkäuferin. Ihr Laden liegt an den Canals der Stadt direkt westlich des Handelsdistrikts, wo sie Angelausrüstung und Köder an die Angler des Königreichs verkauft.",al={"catherine leland","angellehrer sturmwind","leland sturmwind"}},{q="Wo angelt Gilbert Gray?",a="Gilbert Gray befindet sich draußen nahe dem Wasser am Hafen von Sturmwind, wo er den freien Blick auf das Meer abseits der verstopften Straßen der Stadt genießt.",al={"gilbert gray standort","wo ist gilbert gray","hafenangler"}},{q="Welche Vorräte benötigt Gilbert Gray?",a="Gilbert Gray benötigt Nachtkriecher als Köder und einen glänzenden Schmuckstein als verlockenden Köder, die beide bei Catherine Leland entlang der Canals erworben werden können.",al={"questgegenstaende fishin time","welchen koeder moechte gray"}},{q="Warum holt Gilbert Gray die Vorräte nicht selbst?",a="Die Fische beißen gerade aktiv an, wenn Ihr mit ihm sprecht, und er möchte seinen Platz nicht verlieren oder einen guten Fang verpassen, indem er den ganzen Weg zurück in die Stadt wandert, um Nachschub zu holen.",al={"warum kann gray keinen koeder kaufen","warum braucht gray hilfe"}},{q="Wo entlang der Canals befindet sich Catherine Lelands Laden?",a="Ihr Laden liegt direkt am Wasser der Canals unmittelbar westlich des Handelsdistrikts und ist über die Steinwege, die das Wasserstraßennetz der Stadt überspannen, direkt erreichbar.",al={"catherine leland standort","wo ist lelands laden","kanaele handelsdistrikt"}}},fp="12,264,18.462.0,25.376.0,20.228.0,24.196.0,29.139.0,37.159.0,52.165.0,58.163.0"}
P.entries["quest:951"] = {n="Relikte von Mathystra",s="Diese Quest schickt Abenteurer der Allianz nach Norden entlang der Küste der Dunkelküste, um die überwucherten Ruinen von Mathystra zu durchkämmen. Onu, ein im Hain der Uralten verwurzelter Urahne der Lehren, sucht diese uralten Kaldorei-Artefakte, um zu verstehen, wie der Kult des Schattenhammers die Nachtelfenmagie für seine finsteren Riten missbraucht.",h="Diese Quest schickt Abenteurer der Allianz nach Norden entlang der Küste der Dunkelküste, um die...",kw={"dunkelküste","der hain der uralten","die meistergleve","mathystra","onu","relikte","die ruinen von mathystra","schattenhammer"},ang={["class:Druid"]="Onu beizustehen erlaubt Druiden, einem der größten uralten Wächter der Natur zu dienen und die alte Geschichte der Dunkelküste davor zu bewahren, von finsteren Kultisten entstellt zu werden.",["faction:Alliance"]="Den Schattenhammer daran zu hindern, uralte Magie als Waffe einzusetzen, ist unerlässlich, um das nördliche Kalimdor vor dunklen, unterirdischen Mächten zu schützen.",["race:NightElf"]="Für die Nachtelfen ist der Anblick von Relikten ihres Ruhms vor der Zerschlagung, die aus dem Schmutz gegraben werden, eine düstere Mahnung an den Niedergang ihrer Zivilisation – und eine alarmierende Warnung, dass die mächtigen Künste ihrer Vorfahren von apokalyptischen Verrückten missbraucht werden."},sec={{t="Eine beunruhigende Entdeckung",b="Nachdem Abenteurer ein verderbtes Pergament von den Kultisten geborgen hatten, die um das kolossale Monument namens die Meistergleve lauerten, entschlüsselte Onu eine beunruhigende Offenbarung. Der Text war keine einheimische Kultschrift, sondern das verfluchte Fragment einer uralten Nachtelfenschrift. Das vom Schattenhammer besudelte Pergament enthüllte, dass diese apokalyptischen Fanatiker vergessene Elfenmagie nutzen, um ihre uralten Meister zu erwecken oder in die sterbliche Welt zurückzubeschwören."},{t="Die gefallene Bastion",b="Um diesem dunklen Unterfangen entgegenzuwirken, weist Onu die Helden an, zu den Ruinen von Mathystra an den nordöstlichen Gestaden der Dunkelküste aufzubrechen. Vor langer Zeit war Mathystra eine glanzvolle Bastion der Hochgeborenen-Zivilisation, ehe sie während der Zerschlagung in Trümmer fiel. Obwohl die Stadt zu Schutt, Unkraut und einer Nagabrutstätte verfallen ist, überdauern mächtige Reste ihrer ursprünglichen arkanen und spirituellen Verzauberungen in zerbrochenen Urnen und uralten Relikten, die über die Steinfundamente verstreut liegen."},{t="Dunkle Pläne ergründen",b="Indem sie überlebende Artefakte aus den grasbewachsenen Trümmern der Ruine bergen, hoffen die Verteidiger der Dunkelküste, die genauen Techniken aufzudecken, die die Kultisten auszunutzen gedenken. Onu untersucht die in den Relikten verbliebene Restmagie in einem Wettlauf gegen die Zeit, um die Pläne des Kults zu entschlüsseln, bevor der Schattenhammer die uralte Zauberei der Kaldorei vollends dazu bringen kann, seine unterirdischen Meister zu befreien."}},faq={{q="Was sind die Relikte von Mathystra?",a="Es handelt sich um Fragmente verzauberter Töpferwaren, Urnen und Artefakte, die in den Ruinen von Mathystra zurückgelassen wurden. Sie wurden auf dem Höhepunkt der uralten Nachtelfenzivilisation vor der Großen Zerschlagung geschaffen und summen noch immer vor anhaltender magischer Energie.",al={"was sind die relikte","mathystra-relikt hintergrund","elfenrelikte mathystra"}},{q="Warum möchte Onu diese Relikte haben?",a="Onu fand heraus, dass der Kult des Schattenhammers uralte Elfenmagie nutzt, um zu versuchen, seine dunklen Meister zurück in diese Welt zu bringen. Durch das Studium intakter Relikte aus Mathystra hofft Onu zu verstehen, wie der Kult diese uralte Macht zu manipulieren beabsichtigt.",al={"warum will onu relikte","zweck der mathystra-relikte"}},{q="Wo lagen die Ruinen von Mathystra?",a="Die Ruinen liegen an der nordöstlichen Küste der Dunkelküste, nördlich der Ruinen von Ameth'Aran und Bashal'Aran, direkt hinter dem Turm von Althalaxx.",al={"wo liegt mathystra","mathystra standort"}},{q="Wen versucht der Schattenhammer zurückzubringen?",a="Der Kult ist uralten, bösartigen Meistern geweiht; Onu warnt davor, dass sie uralte Elfenmagie einsetzen, um jene alten Meister zurück nach Azeroth zu bringen.",al={"wer sind meister des schattenhammers","kultmeister dunkelküste"}},{q="Was war Mathystra, bevor es zu einer Ruine wurde?",a="Mathystra war vor Jahrtausenden einst eine große Bastion und Stadt der Nachtelfen. Sie verfiel während der Großen Zerschlagung zu Ruinen und wurde seither von Wildnis, Geistern und abscheulichen Küstenkreaturen wie den Naga überrannt.",al={"geschichte von mathystra","was war mathystra"}},{q="Wer vergibt die Quest 'Relikte von Mathystra'?",a="Die Quest wird von Onu vergeben, einem uralten Treant, der im Hain der Uralten im südlich-zentralen Teil der Dunkelküste verwurzelt ist, im Anschluss an die Untersuchung der Meistergleve.",al={"wer startet mathystra-relikte","questgeber mathystra-relikte"}}},fp="16,329,22.461.1,18.465.0,21.377.1,30.237.0,31.253.0,42.141.0,50.142.0,43.230.0,39.163.0"}
P.entries["quest:95161"] = {n="Denk daran, ich liebe dich",s="Denk daran, ich liebe dich ist eine Quest der Allianz, die im Waisenhaus von Sturmwind beginnt und Reisende in die düsteren Wälder des Dämmerwalds entsendet. Mit der Aufgabe betraut, einen düsteren Blutbefleckten Brief zu überbringen, müssen Abenteurer ein frisch adoptiertes Waisenkind namens Jeremy Heartweaver und seine Adoptivmutter Avette Fellwood ausfindig machen.",h="Denk daran, ich liebe dich ist eine Quest der Allianz, die im Waisenhaus von Sturmwind beginnt und Reisende...",kw={"avette fellwood","blutbefleckter brief","dämmerwald","jeremy heartweaver","denk daran, ich liebe dich","sturmwind","waisenhaus von sturmwind"},ang={["faction:Alliance"]="Das Überbringen von Andenken gefallener oder verschollener Verwandter an adoptierte Waisenkinder verdeutlicht den anhaltenden persönlichen Preis der turbulenten Lage des Königreichs.",["race:Human"]="Für die Menschen von Sturmwind schlägt dieser Botengang eine Brücke zwischen dem verhältnismäßig sicheren Herzen des Reiches und den heimgesuchten, vergessenen Siedlungen des Dämmerwalds."},sec={{t="Eine Nachricht für ein Waisenkind",b="Die Kinder des Waisenhauses von Sturmwind tragen schwere Lasten, da sie ihre Familien durch Kriege, Entbehrungen und das das Königreich erschütternde Chaos verloren haben. Jeremy Heartweaver war einer dieser Schutzbefohlenen, bis er kürzlich von einer Frau namens Avette Fellwood adoptiert wurde. Obwohl das Leben in den finsteren Wäldern des Dämmerwalds voller Gefahren und harter Arbeit ist, glaubten die Betreuer des Waisenhauses, dass es ihm die Chance auf eine Familie bot, anstatt weiterhin in der Stadt eingesperrt zu sein."},{t="Ein düsteres Zeichen",b="Die Quest dreht sich um das Überbringen eines Blutbefleckten Briefs, der für Jeremy bestimmt ist und an die Obhut von Avette Fellwood gerichtet wurde. Nachforschungen führen Reisende nach Süden, vorbei an der Sicherheit des Walds von Elwynn und in den Schatten des Dämmerwalds. Die düstere Natur der Sendung deutet auf eine vergangene Tragödie hin, die dem jungen Jeremy weit über die Tore von Sturmwind hinaus gefolgt ist."}},faq={{q="Wer ist Jeremy Heartweaver?",a="Jeremy Heartweaver ist ein kleiner Junge, der zuvor im Waisenhaus von Sturmwind aufwuchs. Er wurde vor Kurzem von Avette Fellwood adoptiert und verließ die Stadt, um im schattenhaften Reich des Dämmerwalds zu leben und zu arbeiten.",al={"jeremy","wer ist jeremy","waisenkind jeremy"}},{q="Wer ist Avette Fellwood?",a="Avette Fellwood ist Jeremys frischgebackene Adoptivmutter, die im Dämmerwald lebt. Die Waisenmütter von Sturmwind halten sie für eine herzensgute Frau, die Jeremy wahrscheinlich aufnahm, um ein weiteres Paar Hände für ihre tägliche Arbeit zu haben.",al={"avette","wer ist avette","adoptivmutter"}},{q="Was ist der Blutbefleckte Brief?",a="Der Blutbefleckte Brief ist ein düsterer Übergabegegenstand, der für Jeremy Heartweaver bestimmt ist und direkt in die Hände seiner Adoptivvormundin Avette Fellwood übergeben werden soll, wobei er Anzeichen von Gewalt oder Tragödie in sich trägt.",al={"blutbefleckter brief","der brief","was ist der brief"}},{q="Wo finde ich Avette Fellwood?",a="Avette Fellwood lebt draußen im Dämmerwald, dem dunklen Waldgebiet direkt südlich des Walds von Elwynn jenseits des Flusses.",al={"avette fellwood standort","wo ist avette","avette finden"}},{q="Warum wurde Jeremy in den Dämmerwald geschickt?",a="Jeremy wurde aus dem Waisenhaus von Sturmwind adoptiert. Obwohl der Dämmerwald ein gefährliches und unerbittliches Land ist, glaubten seine Betreuer, dass das Leben bei einer Familie und das Aushelfen bei ehrlicher Arbeit besser sei, als ein Waisenkind in einer Anstalt zu bleiben.",al={"warum dämmerwald","warum verließ jeremy sturmwind","waisenhaus dämmerwald"}},{q="Welche Fraktion kann diese Quest annehmen?",a="Diese Quest ist ausschließlich für die Allianz bestimmt, beginnt in der menschlichen Hauptstadt Sturmwind und führt in das von der Allianz gehaltene Gebiet des Dämmerwalds.",al={"ist das allianz","nur allianz","horde quest"}}},fp="24,311,23.447.0,12.328.1,26.197.0,23.205.0,33.200.0,32.124.0,32.231.0,34.149.0"}
P.entries["quest:95189"] = {n="Wappen von Lordaeron",s="Das Wappen von Lordaeron ist ein verwittertes Relikt, das das königliche Siegel des gefallenen nördlichen Königreichs trägt. Inmitten der trostlosen Ruinen von Capital City gefunden, sind solche Relikte seit dem Untergang des Königreichs rar, und jemand in Sturmwind wäre überaus begierig darauf, dieses hier in die Hände zu bekommen.",h="Das Wappen von Lordaeron ist ein verwittertes Relikt, das das königliche Siegel des gefallenen nördlichen...",kw={"wappen von lordaeron","heraldik","lady dena kennedy","lordaeron","relikt","ruinen von lordaeron","sturmwind","tirisfal"},ang={["faction:Alliance"]="Das Emblem von Lordaeron repräsentiert die Gründungssäule der ursprünglichen Allianz, was seine Bergung zu einem symbolischen Sieg gegen die vollständige Auslöschung durch die Geißel und die Verlassenen macht.",["race:Human"]="Für Menschen, insbesondere für jene, deren Familien einst den Norden ihre Heimat nannten, ist das Wappen eine ergreifende Erinnerung an das großartige Königreich, das einst die Allianz anführte."},sec={{t="Ein zersplittertes Erbe",b="Als die Geißel durch das Königreich Lordaeron fegte, wurden seine Paläste, Archive und stolzen Insignien größtenteils vernichtet oder dem Verfall im Schatten von Unterstadt überlassen. Überlebende physische Artefakte mit dem königlichen Wappen sind überaus selten. Die Bergung eines intakten oder verwitterten Wappens aus den nördlichen Ruinen stellt ein greifbares Stück Menschheitsgeschichte dar, das dem Vergessen entrissen wurde."},{t="Zuflucht im Süden",b="Nach dem Dritten Krieg flohen Tausende nördliche Flüchtlinge nach Süden in Richtung des Königreichs Sturmwind und trugen lediglich Erinnerungen an ihre Heimat mit sich. In Sturmwind ist Lady Dena Kennedy bestrebt, solche Überreste von Lordaeron zu erwerben, was Relikte wie dieses Wappen in der südlichen Hauptstadt zutiefst geschätzt macht."}},faq={{q="Was ist das Wappen von Lordaeron?",a="Es ist ein verwittertes heraldisches Emblem, das das offizielle Zeichen von Lordaeron zeigt. Zurückgelassen, nachdem das Königreich an die Geißel fiel, ist es ein geschätztes historisches Relikt für menschliche Überlebende.",al={"wappen von lordaeron","was ist das wappen von lordaeron","lordaeron wappen gegenstand"}},{q="Wer möchte das Wappen von Lordaeron haben?",a="Das Wappen wird zu Lady Dena Kennedy gebracht, einer aristokratischen Förderin in Sturmwind, die seltene Artefakte aus dem gefallenen nördlichen Reich sammeln und bewahren möchte.",al={"wer nimmt das wappen an","wohin bringt man das wappen von lordaeron","wappen abgeben"}},{q="Wo wurde das Wappen gefunden?",a="Es wurde in den Ruinen von Lordaeron in Tirisfal geborgen, der zerstörten Hauptstadt, die nun direkt über der Festung der Verlassenen in Unterstadt liegt.",al={"wappen fundort","ruinen wappen","wo gibt es das wappen"}},{q="Warum sind Artefakte aus Lordaeron so selten?",a="Der rasche und katastrophale Untergang des Königreichs während des Dritten Krieges führte zum systematischen Abschlachten seines Volkes und zum Ruin seiner Besitztümer. Nur sehr wenige persönliche Erbstücke überstanden die Geißel und den darauffolgenden Aufstieg der Verlassenen.",al={"warum sind lordaeron-relikte selten","seltenheit von lordaeron-artefakten"}},{q="Warum kümmert sich Sturmwind um Relikte aus Lordaeron?",a="Sturmwind nahm Wellen von Flüchtlingen, Rittern und Adligen auf, die vor der Verwüstung im Norden flohen. Die Bewahrung von Relikten ehrt das gefallene Schwesterkönigreich der Allianz und hält das Erbe der nördlichen Menschen am Leben.",al={"warum sturmwind sich kümmert","sturmwind lordaeron relikte"}},{q="Wer ist Lady Dena Kennedy?",a="Lady Dena Kennedy ist eine Adlige mit Wohnsitz in Sturmwind, die sich aktiv für die Rettung historischer Überreste und Erbstücke aus Lordaeron einsetzt.",al={"lady dena kennedy","wer ist dena kennedy"}}},fp="18,272,20.382.0,19.297.0,31.180.0,33.164.0,26.159.0,41.242.0,50.208.0,25.164.0"}
P.entries["quest:95195"] = {n="Blutverschmiertes Insigne",s="Blutverschmierte Insignien sind tragische Überreste der gefallenen Verteidiger von Lordaeron, die in den verheerten Ruinen des Königreichs verstreut liegen. Diese mit den alten Wappen der Allianz versehenen, zerschlagenen Abzeichen repräsentieren Soldaten, deren Familien während des Dritten Krieges nach Süden nach Sturmwind flohen.",h="Blutverschmierte Insignien sind tragische Überreste der gefallenen Verteidiger von Lordaeron, die in den...",kw={"allianz","blutverschmiertes insigne","lordaeron","marcus jonathan","flüchtlinge","ruinen von lordaeron","sturmwind","dritter krieg"},ang={["class:Paladin"]="Viele der Gefallenen in der Hauptstadt kämpften an der Seite der Ritter der Silbernen Hand; die Bergung ihrer Orden ehrt die verlorenen Brüder und Schwestern des heiligen Ordens.",["faction:Alliance"]="Die Rückgabe dieser Insignien an General Marcus Jonathan dient als Akt der Pflicht und des Gedenkens an die Soldaten, die ihr Leben zur Verteidigung der ursprünglichen Allianz gaben.",["race:Human"]="Für Menschen der Allianz sind diese Abzeichen feierliche Mahnmale für den Fall des größten Menschenkönigreichs und verbinden die in Sturmwind lebenden Flüchtlinge mit ihren gefallenen Verwandten im Norden."},sec={{t="Zeichen der Gefallenen",b="Als Prinz Arthas zurückkehrte, um Lordaeron mit der Geißel heizusuchen, wurde das stolze Militär des Reiches überwältigt und niedergemetzelt. Zahllose Soldaten fielen bei der Verteidigung der Hauptstadt und der umliegenden Länder und hinterließen kaum physische Spuren abgesehen von verrosteten Rüstungen und blutbeflecktem Messing. Diese alten Allianz-Insignien gehörten den Männern und Frauen, die dem Ansturm der Untoten die Stirn boten. In den Boden und den Schutt der Ruinen getreten, ist jeder dieser Orden ein Relikt des letzten, verzweifelten Gefechts des Königreichs."},{t="Ein Bote für die Verbannten",b="Viele Überlebende Lordaerons flohen über das Meer nach Süden und ließen sich als Flüchtlinge in Sturmwind nieder. Jahrzehnte des Bündnisses und der Verbundenheit verbinden die beiden Menschenreiche miteinander, weshalb viele im Süden nach Gewissheit über das Schicksal ihrer vermissten Angehörigen verlangen. General Marcus Jonathan, Kommandant der Stadtwache von Sturmwind, nimmt diese blutverschmierten Insignien in Verwahrung, damit das Andenken an die nördlichen Verteidiger bewahrt wird und ihre überlebenden Familien endlich von ihrem Schicksal erfahren können."}},faq={{q="Was sind die Blutverschmierten Insignien?",a="Es sind militärische Orden, die von Soldaten des Königreichs Lordaeron getragen wurden, die während des Dritten Krieges unter dem Banner der Allianz kämpften und starben.",al={"blutverschmiertes insigne gegenstand","was ist dieses insigne","insignie geschichte"}},{q="Wo sind diese Insignien zu finden?",a="Sie werden überall in den Ruinen von Lordaeron in Tirisfal geborgen, wo die Verteidiger des Königreichs ihr letztes Gefecht gegen die Geißel austrugen.",al={"woher droppen insignien","insigne fundort","ruinen von lordaeron abzeichen"}},{q="Warum will General Marcus Jonathan sie haben?",a="General Marcus Jonathan befehligt die Verteidigung von Sturmwind, wo inzwischen zahllose Flüchtlinge aus dem Norden leben. Er sammelt diese Relikte, damit die Opfer der Krieger Lordaerons gewürdigt werden und ihre lebenden Verwandten im Süden Gewissheit finden können.",al={"wer ist marcus jonathan","warum in sturmwind abgeben","marcus jonathan insigne"}},{q="Warum trugen die Soldaten Lordaerons Allianz-Insignien?",a="Die ursprüngliche Allianz wurde in Lordaeron unter König Terenas Menethil II. geschmiedet, um die Alte Horde zu besiegen. Lordaeron war während des Zweiten und Dritten Krieges das Herzstück und die Führung der Allianz von Lordaeron.",al={"wappen der allianz von lordaeron","allianz von lordaeron abzeichen"}},{q="Was geschah mit den Soldaten, die diese Orden trugen?",a="Sie wurden während des Dritten Krieges getötet, als Prinz Arthas Menethil das Reich verriet, seinen Vater ermordete und die untote Geißel auf die Hauptstadt losließ.",al={"was tötete die soldaten","schicksal der soldaten lordaerons"}},{q="Gibt es noch lebende Verwandte dieser Soldaten?",a="Ja. Tausende Bürger und Soldaten evakuierten Lordaeron während der Seuche und der Invasionen der Geißel und fanden schließlich Zuflucht im Königreich Sturmwind.",al={"flüchtlinge aus lordaeron sturmwind","wer vermisst diese soldaten"}}},fp="17,264,20.502.0,26.468.0,32.144.0,32.145.0,43.250.0,55.203.0,52.161.0,51.158.0"}
P.entries["quest:952"] = {n="Der Hain der Uralten",s="Der Hain der Uralten ist eine Lieferquest der Allianz, die Abenteurer aus Darnassus hinaus und über das Meer zur Dunkelküste führt. Vom Erzdruiden Fandral Hirschhaupt beauftragt, überbringt der Bote Korrespondenz an Onu, einen ehrwürdigen Ancient of Lore, der südlich von Auberdine weilt.",h="Der Hain der Uralten ist eine Lieferquest der Allianz, die Abenteurer aus Darnassus hinaus und über das Meer...",kw={"urzeitbeschützer","auberdine","zirkel des cenarius","dunkelküste","darnassus","fandral hirschhaupt","der hain der uralten","onu","die lichtung des orakels"},ang={["class:Druid"]="Das Überbringen von Botschaften zwischen dem Erzdruiden in Darnassus und Onu führt junge Druiden an die unterschiedlichen Naturelle der Ältesten des Zirkels des Cenarius heran und stellt Hirschhaupts Tatendrang der stillen Geduld eines Ancient of Lore gegenüber.",["faction:Alliance"]="Für die Streiter der Allianz, die ihre Aufgaben in Darnassus abschließen, bietet diese Lieferung einen frühen Anreiz, Hippogryphenrouten zu erschließen und das Küstengebiet der Dunkelküste zu erkunden.",["race:NightElf"]="Diese Aufgabe markiert den natürlichen Übergang von der behüteten Wiege Teldrassils in die weitläufigere Wildnis des Festlands von Kalimdor und verdeutlicht den philosophischen Kontrast zwischen Fandral Hirschhaupt und den Lehren von Malfurion Sturmgrimm."},sec={{t="Das Geäst verlassen",b="Nachdem sie bei Angelegenheiten bezüglich der Lichtung des Orakels auf Teldrassil geholfen haben, finden sich die Abenteurer von Erzdruide Fandral Hirschhaupt schroff zu weiteren Diensten herbeigerufen. Da Staghelm untätige Hände nicht leiden mag, beauftragt er den Boten damit, eine dringende Botschaft über das Meer in die uralten Wälder der Dunkelküste zu tragen, und weist ihn an, von der Stadt aus einen Flug auf einem Hippogryphen zu buchen."},{t="Ein Kontrast der Geduld",b="Nach Erreichen der Dunkelküste und einer Reise südlich von Auberdine zum Hain der Uralten überbringt der Bote das Schreiben an Onu. Der hoch aufragende Ancient of Lore nimmt die Korrespondenz in ruhiger Nachdenklichkeit entgegen und bemerkt feinsinnig Hirschhaupts unbändige Ungeduld. Für Onu und die uralten Hüter des Waldes entfaltet sich alles zu seiner Zeit – eine ruhige, beständige Weisheit, die Shan'do Malfurion Sturmgrimm verkörperte, die Hirschhaupt jedoch sichtlich fehlt."}},faq={{q="Wer startet die Quest Der Hain der Uralten?",a="Erzdruide Fandral Hirschhaupt vergibt die Quest aus der Enklave des Cenarius in Darnassus, nachdem Ihr seinen vorigen Auftrag bezüglich der Lichtung des Orakels abgeschlossen habt.",al={"questgeber der hain der uralten","wer vergibt der hain der uralten","fandral hirschhaupt quest"}},{q="Wo befindet sich der Hain der Uralten?",a="Der Hain der Uralten liegt auf dem Festland an der Dunkelküste, unmittelbar südlich der Hafenstadt Auberdine.",al={"der hain der uralten ort","wo ist der hain der uralten","onu aufenthaltsort"}},{q="Wer ist Onu?",a="Onu ist ein weiser und ehrwürdiger Ancient of Lore, der an der Dunkelküste weilt. Als Beschützer und Chronist natürlicher Weisheit empfängt er Korrespondenz von der Führung der Druiden in Darnassus.",al={"wer ist onu","onu dunkelküste","urzeitbeschützer onu"}},{q="Wie gelangt Ihr von Teldrassil aus an die Dunkelküste?",a="Reisende steigen gewöhnlich von Darnassus hinab nach Rut'theran und nehmen einen Hippogryphen über das Wasser zur Hafensiedlung Auberdine an der Dunkelküste.",al={"wie man nach dunkelküste kommt","reise nach auberdine","hippogryph nach dunkelküste"}},{q="Warum erwähnt Onu Shan'do Sturmgrimm?",a="Beim Empfang der Botschaft bemerkt Onu die rastlose Eile von Erzdruide Hirschhaupt. Er sinnt darüber nach, dass sich der Wald in seinem eigenen Tempo bewegt – eine zeitlose Geduld, die Shan'do Malfurion Sturmgrimm verstand und respektierte.",al={"onu malfurion kommentar","shan'do sturmgrimm erwähnung","warum shan'do erwähnt wird"}},{q="Welche Quests gehen dieser voraus?",a="Diese Quest ist der letzte Schritt einer kurzen, dreiteiligen Reihe, die mit The Enchanted Glade beginnt, von Teldrassil gefolgt wird und Euch schließlich hinaus an die Dunkelküste entsendet.",al={"voraussetzungen der hain der uralten","der hain der uralten reihe","quests vor onu"}}},fx={["00893f03"]={q="Warum möchte Erzdruide Fandral Hirschhaupt, dass diese Nachricht an Onu übermittelt wird?",a="Fandral Hirschhaupt ist bestrebt, eine enge Kommunikation mit den alten Beschützern auf der anderen Seite des Meeres in Kalimdor aufrechtzuerhalten. Onu, ein Ältester der Lehren, verwurzelt an der Dunkelküste, hat auf Nachricht vom Erzdruiden bezüglich der Angelegenheiten auf Teldrassil gewartet. Nun, da Fandral die neuesten Berichte aus Die Lichtung des Orakels erhalten hat, ist er ungeduldig, seine Erkenntnisse und Anweisungen unverzüglich weiterzuleiten, um seine Pläne für die Nachtelfen voranzutreiben.",al={"warum nachricht an onu schicken","fandral beweggrund grove of the ancients","warum muss fandral das übermitteln"}},["658e120a"]={q="Warum wählt Fandral Hirschhaupt Euch aus, um seine Nachricht zu überbringen?",a="Nachdem er gesehen hat, wie Ihr die Nachricht aus Die Lichtung des Orakels nach Darnassus gebracht habt, denkt Fandral, dass Ihr bereits in der Lage seid, sensible Besorgungen über Entfernungen hinweg zu erledigen. Anstatt erfahrene Emissäre des Zirkels des Cenarius oder Schildwachen von ihren Pflichten abzuziehen, setzt er einfach einen bewährten Boten ein, um sein Schreiben an die Dunkelküste zu befördern.",al={"warum ich für fandrals nachricht","warum spieler zu onu schicken","warum keine schildwache schicken"}}},fp="21,265,18.383.0,22.447.0,43.149.0,43.118.0,11.183.0,43.155.0,39.210.0,33.162.0"}
P.entries["quest:95204"] = {n="Crest of Lordaeron",s="Das Crest of Lordaeron ist ein verwittertes historisches Artefakt, welches das Emblem des gefallenen Königreichs trägt. Da nur wenige solcher Schätze die Zerstörung durch die Geißel überstanden haben, wird es zu Oran Snakewrithe in Unterstadt gebracht, um das vergangene Erbe der Verlassenen zu bewahren.",h="Das Crest of Lordaeron ist ein verwittertes historisches Artefakt, welches das Emblem des gefallenen...",kw={"crest of lordaeron","verlassene","lordaeron","oran snakewrithe","relikt","unterstadt"},ang={["faction:Horde"]="Den Archivaren der Verlassenen in Unterstadt beizustehen, hilft dabei, das materielle Vermächtnis von Lordaeron inmitten der von der Geißel hinterlassenen Ruinen zu bewahren.",["race:Undead"]="Als ehemalige Bürger von Lordaeron schätzen die Verlassenen überdauernde Relikte ihres gefallenen Königreichs als seltene Überbleibsel ihres früheren Lebens und Erbes."},sec={{t="Ein überdauerndes Symbol des gefallenen Königreichs",b="Das Königreich Lordaeron wurde während des Dritten Krieges zerstört und hinterließ kaum mehr als Asche, Ruinen und die Verwüstung der Geißel. Da ein so großer Teil der materiellen Kultur des Reiches vernichtet wurde, sind überdauernde Insignien und Embleme wie das Crest of Lordaeron außergewöhnlich selten. Für die Verlassenen, die unter den Ruinen der Capital City hausen, sind diese überdauernden Objekte kostbare physische Verbindungen zu der Zivilisation, der sie einst angehörten."},{t="Bewahrung des Erbes der Verlassenen",b="Wenn das verwitterte Wappen in der weiten Welt geborgen wird, wird es zu Oran Snakewrithe in die Unterstadt gebracht. Oran überprüft seine Echtheit – und testet das Metall sogar, indem er hineinbeißt –, bevor er es als authentisches, weitgehend intaktes Erbstück ihrer Heimat bestätigt. Für Oran und die Archivare der Verlassenen trägt jedes gerettete Stück dazu bei, eine Geschichte zusammenzufügen, welche die Geißel völlig auszulöschen suchte."}},faq={{q="Was ist das Crest of Lordaeron?",a="Das Crest of Lordaeron ist ein verwittertes Emblem, welches das Zeichen des gefallenen Menschenkönigreichs trägt. Da nur sehr wenige physische Relikte die Zerstörung durch die Geißel überstanden haben, ist es ein unschätzbares Stück Geschichte für jene, die versuchen, das Erbe von Lordaeron zu bewahren.",al={"was ist crest of lordaeron","lordaeron wappen quest","wappen gegenstand"}},{q="Wer will das Wappen in Unterstadt haben?",a="Das Wappen wird zu Oran Snakewrithe gebracht, der in Unterstadt weilt. Oran inspiziert und schützt geborgene Artefakte sorgfältig, die mit dem alten Königreich verbunden sind.",al={"wer bekommt das wappen","wo wappen abgeben","wappenabgabe unterstadt"}},{q="Warum beißt Oran Snakewrithe in das Wappen?",a="Nach Erhalt des Wappens beißt Oran Snakewrithe hinein, um dessen Echtheit und Materialzusammensetzung zu überprüfen, ehe er es zu einem echten, weitgehend intakten Relikt von Lordaeron erklärt.",al={"warum in das wappen beißen","oran beißt in wappen"}},{q="Warum schätzen die Verlassenen Relikte von Lordaeron?",a="Die Verlassenen sind die untoten Überreste der einstigen Bevölkerung von Lordaeron. Trotz ihres Untodes und ihrer neuen Loyalität stellen Relikte ihrer zerstörten Heimat greifbare Verbindungen zu ihrer Geschichte und Identität dar.",al={"warum kümmern sich verlassene um lordaeron","relikte der verlassenen"}},{q="Was geschieht mit dem Wappen, nachdem es abgegeben wurde?",a="Oran Snakewrithe nimmt das Wappen in Verwahrung, um dessen Sicherheit zu gewährleisten, und behandelt es als kostbaren historischen Schatz, der dabei hilft, das Erbe ihres Königreichs wiederherzustellen und in Erinnerung zu rufen.",al={"was passiert mit dem wappen","wappen bewahrung"}},{q="Wie selten sind überdauernde Relikte aus Lordaeron?",a="Physische Embleme und Relikte aus der Zeit vor dem Dritten Krieg sind außergewöhnlich rar. Die meisten Symbole von Lordaeron wurden zerschlagen, geplündert oder verderbt, als Arthas und die Geißel das Reich überrannten.",al={"ist das wappen selten","wie viele wappen übrig"}}},fp="18,256,40.433.0,28.385.0,31.248.0,33.159.0,41.173.0,46.203.0,52.181.0,45.187.0"}
P.entries["quest:95212"] = {n="Never Saddle on Quality",s="Never Saddle on Quality ist eine Aufgabe der Allianz, die auf Gehöft Bernruh in Dun Morogh angesiedelt ist. Tierführer benötigen makellose Bergleopardenbälge, um warme Sättel für Reitwidder herzustellen, die zur Verstärkung der Alterac-Expedition bestimmt sind. Diese Bemühungen stellen sicher, dass Reittiere und Reiter dem schneidenden Frost der nördlichen Berge trotzen können.",h="Never Saddle on Quality ist eine Aufgabe der Allianz, die auf Gehöft Bernruh in Dun Morogh angesiedelt ist.",kw={"alterac","alterac expedition","gehöft bernruh","dun morogh","leopardenbälge","never saddle on quality","makellose leopardenbälge","widder","sättel"},ang={["class:Hunter"]="Die Aufgabe fordert erfahrene Fährtenleser und Jäger dazu auf, Dun Moroghs wildeste Bergleoparden aufzuspüren, um makellose Bälge zu sichern.",["faction:Alliance"]="Die Widderzucht auf Gehöft Bernruh versorgt die in den eisigen Höhen von Alterac operierenden Streitkräfte der Allianz direkt mit Reittierverstärkung.",["race:Dwarf"]="Dun Moroghs widerstandsfähige Bergwidder sind ikonische Zwergenreittiere, und die Züchter auf Gehöft Bernruh weigern sich, sie mit minderwertiger Ausrüstung auszustatten."},sec={{t="Ausrüstung für die Expedition",b="Auf Gehöft Bernruh in Dun Morogh bereiten Tierführer eine neue Gruppe robuster Bergwidder vor, um die in Alterac operierende Expedition der Allianz zu verstärken. Allerdings gerieten die Vorbereitungen ins Stocken, da es an geeignetem Material mangelt, das zur Herstellung strapazierfähiger Kälteschutzsättel für die Tiere benötigt wird."},{t="Wärme für die Hochpässe",b="Um der unerbittlichen Kälte des Alteracgebirges standzuhalten, verlangen die Expeditionstiere eine dicke, hochwertige Isolierung. Jäger werden in die östlichen Klüfte geschickt, um Dun Moroghs größte und wildeste Bergleoparden aufzuspüren und ihre makellosen Bälge zu erbeuten, damit die Streitkräfte der Allianz Ausrüstung erhalten, die für das Überleben auf den Hochpässen geschaffen ist."}},faq={{q="Was ist Never Saddle on Quality?",a="Never Saddle on Quality ist eine Aufgabe, die von Gehöft Bernruh in Dun Morogh ausgeht. Ein Züchter benötigt hochwertige Leopardenbälge, um robuste, warme Sättel für eine Gruppe von Widdern herzustellen, die als Verstärkung für die Alterac-Expedition vorbereitet werden.",al={"was ist diese quest","never saddle on quality quest","was ist never saddle on quality"}},{q="Warum werden Leopardenbälge benötigt?",a="Die Bälge werden benötigt, um strapazierfähige, warme Sättel für Expeditionstiere herzustellen. Dun Moroghs Bergleoparden bieten ein dickes, isolierendes Fell, das Reiter und Reittiere vor der schneidenden Bergkälte von Alterac schützt.",al={"warum leopardenbälge","wofür sind bälge","warum makellose bälge"}},{q="Wohin werden die Widder geschickt?",a="Die Reittiere sind für Streitkräfte der Allianz bestimmt, die an der Alterac-Expedition teilnehmen. Angesichts des rauen Wetters und der anhaltenden Einsätze in den Hochpässen sind gut ausgerüstete Reitwidder eine unverzichtbare Unterstützung.",al={"wohin kommen die widder","wer bekommt die widder","alterac verstärkung"}},{q="Welche Rolle spielt Gehöft Bernruh hierbei?",a="Gehöft Bernruh liegt in den schneebedeckten Hügeln von Dun Morogh, östlich von Kharanos. Es dient als primäre Zucht- und Ausbildungsstätte für Zwergenbergwidder.",al={"wo liegt gehöft bernruh","gehöft bernruh standort"}},{q="Wo streifen die Leoparden umher?",a="Die wilden Schneeleoparden durchstreifen die schneebedeckten Bergrücken und Klüfte östlich von Gehöft Bernruh in Dun Morogh, wo Jäger die größten Bestien aufspüren müssen, um makellose Bälge zu erbeuten.",al={"wo leoparden finden","wo sind leoparden dun morogh"}},{q="Warum ist Kälteschutz für die Expedition so wichtig?",a="Das Königreich und die Gipfel von Alterac sind berüchtigt für ihre eisige Kälte und stürmischen Winde. Ohne dickes, hochwertiges Sattelmaterial riskieren Reittiere und Reiter im bergigen Gelände Erfrierungen und Erschöpfung.",al={"ist alterac kalt","warum warme sättel"}}},fp="23,312,23.289.0,26.335.0,32.233.0,29.217.0,30.186.0,37.160.0,27.174.0,63.193.0"}
P.entries["quest:95213"] = {n="Stolen Blasting Powder",s="Stolen Blasting Powder dreht sich um ein leeres, gefährliches Sprengstofffass, das bei Troggs in der Nähe vom Steinbruch Gol'Bolar entdeckt wurde. Das Zurückbringen des fehlenden Behälters zu Steinbruchmeister Thesten offenbart eine gefährliche Sicherheitslücke im Steinbruch und seinen Sprengstofflagern.",h="Stolen Blasting Powder dreht sich um ein leeres, gefährliches Sprengstofffass, das bei Troggs in der Nähe vom...",kw={"sprengpulver","dun morogh","leeres pulverfass","steinbruch gol'bolar","pulverfass","steinbruchmeister thesten","stolen blasting powder","thesten","troggs"},ang={["faction:Alliance"]="Die Sicherung der Versorgungslinien und Bergbau-Außenposten von Dun Morogh vor Troggüberfällen ist für Operationen der Allianz in ganz Khaz Modan von entscheidender Bedeutung.",["profession:Engineering"]="Sprengpulver ist ein gefährliches, instabiles Material; Ingenieure verstehen besser als jeder andere, welches Unheil Troggs mit unbefugten Sprengstoffen anrichten könnten.",["profession:Mining"]="Der Betrieb im Steinbruch ist auf kontrollierte Sprengungen zur Steingewinnung angewiesen, doch fehlende Pulverfässer deuten auf eine ernste Gefahr im Inneren der Ausgrabungsgruben hin.",["race:Dwarf"]="Der Steinbruch Gol'Bolar liefert Stein und Ressourcen, die für Eisenschmiede unverzichtbar sind, was die Sicherheit seiner Bergbausprengstoffe zu einem dringenden Anliegen für jeden Zwerg macht."},sec={{t="Eine gefährliche Entdeckung",b="Ein leeres Fass mit deutlichen Gefahrenhinweisen offenbart, dass gefährliches Sprengpulver im Steinbruch Gol'Bolar in unbefugte Hände geraten ist. Solche Sprengstoffe sind streng für kontrollierte Abbauarbeiten unter direkter Genehmigung des Steinbruchmeisters reserviert. Dass das Fass bei feindseligen Troggs gefunden wurde, deutet darauf hin, dass die Ausgrabungsstätte einer weit unberechenbareren Bedrohung gegenübersteht als gewöhnlichen Arbeitsunterbrechungen."},{t="Der Alarm des Steinbruchmeisters",b="Die Rückgabe des leeren Behälters an Steinbruchmeister Thesten bestätigt die schlimmsten Befürchtungen der zwergischen Vorarbeiter. Thesten erblasst beim Anblick des Fasses, da ihm klar wird, dass das fehlende Sprengpulver bereits geleert und von den die Gegend umschwärmenden unterirdischen Troggs gehandhabt wurde. Die Entdeckung versetzt die Leitung des Steinbruchs in Aufruhr, um herauszufinden, was die Kreaturen als Nächstes zu sprengen beabsichtigen."}},faq={{q="Was ist Stolen Blasting Powder?",a="Stolen Blasting Powder ist eine Quest, die ausgelöst wird, sobald ein leeres Sprengpulverfass mit Gefahrenhinweisen in den Händen von Troggs nahe dem Steinbruch Gol'Bolar entdeckt wird. Sie setzt Steinbruchmeister Thesten über den Diebstahl der unberechenbaren Bergbauvorräte in Kenntnis.",al={"was ist stolen blasting powder","pulverfass quest","leeres pulverfass lore"}},{q="Wer sollte das leere Pulverfass erhalten?",a="Das leere Pulverfass muss direkt zu Steinbruchmeister Thesten gebracht werden, der die Arbeiten im Steinbruch Gol'Bolar in Dun Morogh beaufsichtigt.",al={"wohin das fass bringen","wer ist thesten","standort des steinbruchmeisters"}},{q="Warum ist das gestohlene Sprengpulver gefährlich?",a="Das Fass trägt deutlich die Warnhinweise zur Genehmigung durch den Steinbruchmeister und enthielt gefährliches Sprengpulver. Dass Troggs im Besitz schwerer Sprengstoffe sind oder diese zur Explosion bringen, bedroht die gesamte Ausgrabung des Steinbruchs und nahegelegene Siedlungen.",al={"warum pulver gefaehrlich ist","troggs mit sprengstoff","warum troggs pulver haben"}},{q="Was ist der Steinbruch Gol'Bolar?",a="Der Steinbruch Gol'Bolar ist eine zwergische Ausgrabungsstätte in Dun Morogh, die für den Abbau von Stein und Mineralien für Eisenschmiede zuständig ist.",al={"wo ist gol bolar","standort des steinbruchs","golbolar dun morogh"}},{q="Warum erblasst Steinbruchmeister Thesten?",a="Beim Anblick des leeren Fasses erblasst Steinbruchmeister Thesten sichtlich und fragt, wo es gefunden wurde, da er sofort erkennt, dass die gefährlichen Inhalte bereits in die Hände feindseliger Troggs gefallen sind.",al={"warum thesten erblasst","thestens reaktion","was sagt thesten"}},{q="Was tun Troggs in der Nähe vom Steinbruch Gol'Bolar?",a="Troggs haben die unteren Bereiche und Außenbezirke vom Steinbruch Gol'Bolar heimgesucht, wo sie zwergische Bergleute stören und Ausrüstung sowie Sprengpulver von der Ausgrabungsstätte erbeuten.",al={"sind troggs im steinbruch","troggplage dun morogh","warum troggs pulver stehlen"}}},fp="22,240,21.389.0,24.378.1,31.240.0,40.129.0,44.210.0,25.128.0,40.193.0,44.164.0"}
P.entries["quest:95214"] = {n="Stolen Blasting Powder",s="Stolen Blasting Powder ist eine Quest im Steinbruch Gol'Bolar in Dun Morogh, bei der Abenteurer vermisste Munition wiederbeschaffen müssen. Primitive Troggs haben sich mit genug Sprengpulver davongemacht, um einen Festungsflügel dem Erdboden gleichzumachen, was Quarrymaster Thesten dazu zwingt, diskrete Hilfe anzuheuern, bevor es zu einer Katastrophe kommt.",h="Stolen Blasting Powder ist eine Quest im Steinbruch Gol'Bolar in Dun Morogh, bei der Abenteurer vermisste...",kw={"sprengpulver","dun morogh","sprengstoff","steinbruch gol'bolar","eisenschmiede","könig magni","quarrymaster thesten","thesten","troggs"},ang={["faction:Alliance"]="Die Nachschublinien und Steinmetzarbeiten von Dun Morogh sind für die Festung der Allianz im Gebirge von entscheidender Bedeutung. Den Frieden zu wahren und gefährliche Munition zu bewachen, sichert das Überleben des High Seat im nahegelegenen Eisenschmiede.",["profession:Mining"]="Sprengpulver ist ein unverzichtbares Werkzeug, um Gestein wegzusprengen und Adern bei tiefen Grabungen freizulegen, doch seine Handhabung erfordert Disziplin – ganze Fässer an wilde Höhlenbewohner zu verlieren, ist der Albtraum eines jeden Steinbruchmeisters.",["race:Dwarf"]="Der Steinbruch Gol'Bolar treibt Eisenschmiedes Steinmetzkunst und Ausgrabungsbemühungen voran. Unterirdischen Troggs zu gestatten, Bergbausprengstoff direkt vor König Magnis Haustür als Waffe einzusetzen, ist ein demütigendes Sicherheitsversagen für jeden zwergischen Vorarbeiter."},sec={{t="Ein vermisster Vorrat",b="Im Steinbruch Gol'Bolar in Dun Morogh hängt die Arbeit der Zwerge stark von schweren Sprengladungen ab, um Gestein zu brechen und tiefe Adern freizulegen. Die Wachsamkeit ließ jedoch nach, als es primitiven Troggs, die in den nahegelegenen Felsen lauerten, gelang, eine ganze Großlieferung hochwertigen Sprengpulvers zu entwenden. Quarrymaster Thesten sah sich gezwungen, fieberhaft nach fähigen Händen zu suchen, bevor die Diebesbande über eine versehentliche Detonation stolperte."},{t="Ein Pulverfass in den Felsen",b="Die schiere Menge des fehlenden Materials ist erschütternd: Thesten merkt an, dass das Fass genug Sprengkraft barg, um König Magni Bronzebarts prächtigen Thronsaal in einen offenen Innenhof zu verwandeln. Die Troggs schafften die explosive Beute nach Osten in ihre primitiven Lager in den Ausläufern der Hügel. Sich selbst überlassen, wäre es nur eine Frage der Zeit, bis die Unholde das Feuer entdeckten oder Stein gegen Funken schlugen."},{t="Stille Beilegung",b="Sobald die gestohlenen Sprengladungen den Troggs entrissen und sicher zum Steinbruchlager zurückgebracht wurden, atmet Thesten erleichtert auf. Der Steinbruchmeister belohnt The Adventurer mit der diskreten Bitte, diesen kleinen Vorfall niemandem gegenüber zu erwähnen."}},faq={{q="Wer ist Quarrymaster Thesten?",a="Quarrymaster Thesten leitet die Ausgrabungsarbeiten im Steinbruch Gol'Bolar in Dun Morogh. Verantwortlich für die Sicherheit und Produktivität der Grabungsstätte, findet er sich in einer peinlichen Zwickmühle wieder, nachdem unter seiner Aufsicht ein riesiger Vorrat an industriellem Sprengpulver abhandengekommen ist.",al={"wer ist thesten","quarrymaster thesten","wer vergibt diese quest"}},{q="Wo ist das gestohlene Sprengpulver zu finden?",a="Das Pulver wurde von den Troggs fortgeschleppt, welche die Felsen und Höhlen unmittelbar östlich des Steinbruchs Gol'Bolar heimsuchen. Abenteurer werden in diese Felsvorsprünge geschickt, um den Kreaturen die explosiven Fässer und Säcke wieder zu entreißen, bevor ein Unglück geschieht.",al={"wo ist stolen blasting powder","trogg aufenthaltsort","pulver aufenthaltsort"}},{q="Warum haben die Troggs das Sprengpulver gestohlen?",a="Troggs sind primitive, unterirdische Kreaturen, die von primitiver Schläue und territorialer Aggression getrieben werden. Obwohl sie die Pulverfässer lediglich von den Steinbrucharbeitern erbeutet haben, befürchtet Quarrymaster Thesten, dass selbst ungeschicktes Experimentieren dazu führen könnte, dass sie die Sprengstoffe versehentlich entzünden.",al={"warum troggs pulver stehlen","was wollen troggs mit pulver"}},{q="Wie gefährlich ist das gestohlene Sprengpulver?",a="Laut Quarrymaster Thesten enthielt das verschwundene Fass genug flüchtiges Sprengpulver, um König Magni Bronzebarts Thronsaal in einen offenen Innenhof zu verwandeln. Sollte es auf einmal im engen Steinbruch oder in den Höhlen detonieren, wäre die Wucht verheerend.",al={"wie stark ist pulver","magni thronsaal pulver","ist das pulver gefährlich"}},{q="Warum möchte Quarrymaster Thesten, dass der Vorfall verschwiegen wird?",a="Wenn Ihr das Pulver zurückbringt, bezahlt Euch Thesten und bittet Euch darum, diesen kleinen Vorfall niemandem gegenüber zu erwähnen. Er sagt nicht warum, aber so viel Sprengstoff an die Troggs zu verlieren, ist eindeutig etwas, das er lieber verschweigen möchte.",al={"warum geheim halten","thesten geheimnis","vorfall nicht erwähnen"}},{q="Was ist der Steinbruch Gol'Bolar?",a="Der Steinbruch Gol'Bolar ist eine bedeutende zwergische Ausgrabungsstätte im östlichen Dun Morogh, die für den Abbau von Steinen für Bau- und Ingenieursprojekte im gesamten Reich zuständig ist. Seine tiefen Gruben haben regelmäßig mit unterirdischen Plagen wie Troggs zu kämpfen, die aus dem Fels hervorkommen.",al={"was ist gol bolar","steinbruch gol'bolar","wo ist golbolar"}}},fp="22,286,19.408.0,25.386.0,16.238.1,28.281.0,46.238.0,45.275.0,44.242.0,59.214.0,25.266.0"}
P.entries["quest:95216"] = {n="The New Plague",s="The New Plague ist ein Forschungsvorhaben von Theodore Griffs im Apothekarium von Unterstadt. Griffs geht Berichten über einen tödlichen Arthropoden in den darüberliegenden Ruinen nach, dessen Gift selbst untotes Fleisch zersetzt, und versucht, die tödlichen Toxine des Organismus zu analysieren und nachzukonstruieren.",h="The New Plague ist ein Forschungsvorhaben von Theodore Griffs im Apothekarium von Unterstadt.",kw={"das apothekarium","ichor","ruinen von lordaeron","the new plague","theodore griffs","giftiger erreger","unterstadt","witherfang"},ang={["faction:Horde"]="Während die Horde die Verlassenen als taktische Verbündete in den Östlichen Königreichen duldet, wecken die finsteren biologischen Experimente, die im Apothekarium brodeln, unter ehrenhafteren Mitgliedern oft Unbehagen.",["race:Undead"]="Die Royal Apothecary Society strebt unerbittlich nach Toxinen, die sowohl Lebenden als auch Toten schaden können, um die Vorherrschaft der Verlassenen zu sichern und ihre noch junge Nation zu schützen."},sec={{t="Der Ehrgeiz des Apothekers",b="In den feuchten Tiefen des Apothekariums sammelt die Royal Apothecary Society unaufhörlich virulente Erreger aus ganz Azeroth. Theodore Griffs, einer ihrer engagierten Forscher, spürt exotische Bestien und tödliche Kontaminanten auf, um die alchemistische Innovation der Verlassenen voranzutreiben. Als er Gerüchte über eine giftige Kreatur hört, die im zerborstenen Gestein darüber lauert, entsendet Griffs Abenteurer, um eine brauchbare Probe zu beschaffen, bevor die Gelegenheit verstreicht."},{t="Ein fleischzersetzendes Toxin",b="Das Ziel der Nachforschungen ist Witherfang, ein giftiger Arthropode, der durch die oberirdischen Ruinen von Lordaeron streift. Sein Gift besitzt die seltene und furchterregende Eigenschaft, nicht nur lebendes Gewebe, sondern auch totes und konserviertes Fleisch zu zersetzen. Für einen Apotheker, der daran arbeitet, biologische Kriegsführung zu verfeinern und das Königreich der Verlassenen zu schützen, bietet die Entschlüsselung, wie ein solches Toxin nekrotische Resistenzen umgeht, unschätzbare chemische Erkenntnisse."},{t="Die Nachkonstruktion des Ichors",b="Obwohl Griffs seine Frustration darüber zum Ausdruck bringt, dass Abenteurer Witherfang vernichten, anstatt die Kreatur lebend zu sichern, liefert das gesammelte Ichor ausreichend Material für eine Analyse. Durch die Zersetzung der Körperflüssigkeiten der Kreatur beabsichtigt der Apotheker, die virulenten Mechanismen des Gifts nachzukonstruieren, um sicherzustellen, dass selbst ein zermalmter Arthropode zur wachsenden chemischen Macht von Unterstadt beiträgt."}},faq={{q="Wer ist Theodore Griffs?",a="Theodore Griffs ist ein Apothekerforscher, der im Apothekarium in Unterstadt tätig ist. Er untersucht wirksame Toxine und exotische Exemplare, um Verbindungen für die Verlassenen zu synthetisieren, und zeigt wenig Verständnis für jeden, der die feine alchemistische Kunst nicht zu schätzen weiß.",al={"wer vergibt the new plague","theodore griffs","wer ist theodore griffs"}},{q="Was ist Witherfang?",a="Witherfang ist ein tödlicher, giftiger Arthropode, der in den Ruinen von Lordaeron über Unterstadt lauert. Er produziert ein bemerkenswert ätzendes Toxin, das selbst widerstandsfähiges untotes Fleisch zersetzen kann.",al={"was ist witherfang","wo ist witherfang","ruinen von lordaeron arthropode"}},{q="Warum will Theodore Griffs das Gift von Witherfang?",a="Theodore Griffs möchte das Gift von Witherfang untersuchen, um festzustellen, wie sich seine Toxine durch untotes Fleisch fressen, in der Hoffnung, die Substanz zu wirksamen Erregern für das alchemistische Arsenal der Verlassenen nachzukonstruieren.",al={"was will theodore mit witherfang","warum den hochgiftigen erreger sammeln"}},{q="Warum ist Theodore Griffs verärgert, wenn Ihr zurückkehrt?",a="Theodore Griffs hatte gehofft, dass das Exemplar unversehrt bleibt oder sorgfältig geerntet wird, anstatt direkt getötet zu werden. Obwohl er verärgert darüber war, dass Witherfang getötet wurde, gelang es ihm dennoch, genügend verbliebenes Ichor aus den Überresten zu gewinnen, um dessen Eigenschaften zu untersuchen.",al={"warum war theodore wütend","habe ich die probe ruiniert"}},{q="Was ist der Zweck des Apothekariums?",a="Das Apothekarium dient als Forschungszentrum der Royal Apothecary Society unterhalb von Lordaeron. Als wichtigstes Viertel von Unterstadt beschrieben, widmet es sich der Erprobung virulenter Erreger, dem Brauen alchemistischer Waffen und Experimenten an exotischen Kreaturen.",al={"zweck des apothekariums","warum ist das apothekarium wichtig"}},{q="Wie werden virulente Erreger nach Theodores Ansicht am besten übertragen?",a="Laut Theodore Griffs ist der wirksamste und verlässlichste Vektor für eine virulente Übertragung stets die direkte Einbringung in die Blutbahn.",al={"wie wird das gift übertragen","übertragungsmethode"}}},fp="14,287,25.429.0,24.413.0,29.391.1,23.272.0,19.195.0,49.203.0,45.240.0,40.261.0,64.151.0"}
P.entries["quest:95217"] = {n="The Quarry's Smith",s="The Quarry's Smith ist eine Abmachung, die von Frast Dokner angeboten wird, einem arbeitenden Handwerker, der in einem Steinbruchlager stationiert ist. Da er ohne die erwartete Vorratslieferung festsitzt, wendet sich der Schmied an hilfsbereite Reisende, um Rohmetall und robustes Leder für unentbehrliche Lagerreparaturen zu sammeln. Im Austausch für die benötigten Materialien teilt Dokner praktische Schmiedetechniken mit aufstrebenden Metallarbeitern.",h="The Quarry's Smith ist eine Abmachung, die von Frast Dokner angeboten wird, einem arbeitenden Handwerker, der...",kw={"schmiedekunst","kupferbarren","dun morogh","zwerg","frast dokner","steinbruch gol'bolar","eisenschmiede","the quarry's smith","gehärtete eberfelle"},ang={["faction:Alliance"]="Dokner beizustehen sorgt dafür, dass der abgelegene Zwergensteinbruch einsatzbereit bleibt, was die lokale Infrastruktur und Einsatzbereitschaft der Ausrüstung im verschneiten Hochland stärkt.",["profession:Blacksmithing"]="Frast Dokner dient als Lehrmeister vor Ort für Schmiedelehrlinge und tauscht seine hart erarbeiteten Schmiedetechniken mit jedem, der bereit ist, das Rohmetall und Leder zu beschaffen, das nötig ist, um seinen Amboss heiß zu halten.",["profession:Mining"]="Bergleute, die die umliegenden Vorkommen abbauen, finden einen direkten lokalen Abnehmer für ihre verhütteten Kupferbarren, wodurch Roherz in praktische Ausbildung und Lagerreparaturen umgewandelt wird.",["race:Dwarf"]="Der Steinbruch Gol'Bolar verkörpert das Unternehmertum und den Fleiß der Bronzebärte in Dun Morogh, wo die Entschlossenheit der Zwerge die Schmiedefeuer brennen lässt, selbst wenn Versorgungskarawanen verspätet eintreffen."},sec={{t="Engpässe im Steinbruch",b="Das Leben an einer aktiven Ausgrabungsstätte verlangt ständige Instandhaltung, vom Schärfen von Spitzhacken und dem Ersetzen verschlissener Halterungen bis hin zur Verstärkung von Lagerausrüstung. Wenn eine lebenswichtige Vorratslieferung nicht pünktlich eintrifft, kommt die tägliche Arbeit allmählich zum Stillstand. Ohne frischen Nachschub von den großen Handelsstraßen sind die Handwerker vor Ort gezwungen zu improvisieren und auf durchreisende Abenteurer zu setzen, um das Lager funktionsfähig zu halten. Frast Dokner, der inmitten dieser anhaltenden Verzögerungen die Schmiede betreibt, verlässt sich auf jeden, der gewillt ist, einfache Metalle und Felle aufzutreiben, anstatt tatenlos auf Transportwagen zu warten, die womöglich hoffnungslos verspätet sind."},{t="Der Handel eines Lehrlings",b="Traditionelle Zwergenschmiedegilden schätzen Disziplin sowie streng gehütete Methoden und geben Berufsgeheimnisse selten an zufällige Wanderer weiter. Dokner wägt jedoch die örtliche Notwendigkeit gegen die formelle Gildenetiquette ab. Angesichts eines akuten Mangels an verarbeitbarem Kupfer und strapazierfähigem Leder, das zum Ausbessern von Werkzeugen und Lagerausrüstung gebraucht wird, bietet er einen pragmatischen Tausch an: Bringt die Rohstoffe direkt zu seinem Amboss, und er wird Euch in seinen persönlichen Schmiedetechniken unterweisen. Es ist ein beiderseits vorteilhafter Handel, der aus der Notwendigkeit an vorderster Front entstanden ist und wertvolles Fachwissen gegen unmittelbares Überleben und Instandhaltung eintauscht."}},faq={{q="Wer ist Frast Dokner?",a="Frast Dokner ist ein erfahrener Schmied, der in einem Steinbruchlager stationiert ist und dafür zuständig ist, Werkzeuge, strukturelle Beschläge und Ausrüstung für die Arbeiter vor Ort instand zu halten. Wenn logistische Verzögerungen seine reguläre Nachschublinie abschneiden, nimmt er die Dinge selbst in die Hand, indem er vorbeiziehende Abenteurer anwirbt, um die Rohmaterialien zu beschaffen, die er verzweifelt benötigt.",al={"frast dokner lore","wer ist the quarry's smith","steinbruchschmied"}},{q="Warum benötigt der Steinbruch Kupferbarren und Eberfelle?",a="Ausgrabungen und die Instandhaltung des Lagers verbrauchen gewaltige Mengen an robustem Material. Kupfer liefert ein leicht zugängliches, formbares Metall, das sich zum Schmieden von Ersatzbeschlägen, Nägeln, Befestigungselementen und Verstärkungsbändern für zerbrochene Werkzeuge eignet. Gehärtete Eberfelle liefern widerstandsfähiges Leder, das für Blasebälge, Werkzeugwickel, Riemen und Schutzschürzen benötigt wird, die den harten Funken und dem starken Abrieb der täglichen Steinbrucharbeit standhalten.",al={"warum kupferbarren und eberfelle","benötigte materialien steinbruchschmied","steinbruch reparaturmaterialien"}},{q="Warum verspätet sich die Vorratslieferung?",a="Während Frast Dokner die genaue Ursache der Verzögerung nicht näher erläutert, werden Überland-Nachschubwege über die verschneiten Klippen und Gebirgspässe häufig von heftigen Schneestürmen, streunenden Wildtieren und feindseligen Hinterhalten von Troggs oder Banditen heimgesucht. Abgelegene Bergbaulager und Steinbrüche sind oft die ersten Siedlungen, die die Belastung zu spüren bekommen, wann immer Transportwagen hinter dem Zeitplan zurückbleiben.",al={"verspätete vorratswagengelieferung","was geschah mit den vorräten","warum verzögern sich die vorräte"}},{q="Was bietet Frast Dokner im Austausch für die Materialien an?",a="Anstatt lediglich Münzen anzubieten, verspricht Frast Dokner, seine persönlichen Schmiedetechniken mit jedem zu teilen, der die benötigten Vorräte beschafft. Für einen aufstrebenden Handwerker bietet das direkte Lernen von einem erfahrenen, im Feld stationierten Handwerker praktische Einblicke in die Metallverarbeitung und Instandhaltung von Ausrüstung, die formelle städtische Gildenhallen Anfängern nur selten vermitteln.",al={"steinbruchschmied belohnungs lore","was lehrt frast","schmiedekunst techniken frast"}},{q="Wo befindet sich dieser Steinbruch?",a="Frast Dokner ist in Dun Morogh im Steinbruch Gol'Bolar tätig, einer Zwergenausgrabungsstätte, die in den verschneiten Ausläufern südlich von Kharanos liegt. Der Steinbruch sieht sich ständigem betrieblichem Druck durch raues Winterwetter und aggressive unterirdische Troggs ausgesetzt, die regelmäßig die Bergleute belästigen und Handelskonvois aus Eisenschmiede stören.",al={"welcher steinbruch ist das","wo ist frast dokner","standort des steinbruchschmieds"}},{q="Ist Frast Dokner mit Eisenschmiede verbündet?",a="Ja, Frast Dokner und das Steinbruchlager unterstehen dem Herrschaftsbereich des Bronzebart-Klans und dem Königreich von Eisenschmiede. Der Abbau von Stein und die Förderung von Erz aus den Bergen von Dun Morogh sind für die Bauprojekte und Verteidigungsanlagen des Zwergenkönigreichs von entscheidender Bedeutung, was örtliche Schmiede wie Dokner für Eisenschmiedes industrielle Stärke unerlässlich macht.",al={"frast dokner eisenschmiede","gehört der steinbruch zu eisenschmiede","steinbruch zwergen loyalität"}}},fp="18,369,23.580.0,23.599.0,20.349.0,52.409.0,32.369.0,59.358.0,29.326.0,42.360.0"}
P.entries["quest:95250"] = {n="Abominable Creatures",s="Abominable Creatures ist eine Quest von Captain Truman, einem loyalistischen Menschen, der am Rande der gefallenen Hauptstadt von Lordaeron verzweifelt auf Verstärkung wartet. In dem Glauben, sein Kommandant – ein hochverehrter Großmarschall – kämpfe noch immer tapfer in den nahe gelegenen Ruinen von Lordaeron, fleht Truman einen fähigen Abenteurer an, ihn aufzuspüren. Die Mission offenbart das grausame Schicksal der verlorenen Verteidiger des Königreichs und die erbitterte Feindseligkeit, die unter den überlebenden Loyalisten schwelt.",h="Abominable Creatures ist eine Quest von Captain Truman, einem loyalistischen Menschen, der am Rande der...",kw={"abominable creatures","captain truman","großmarschall","head of the baron","lordaeron","ruinen von lordaeron","the baron","wahre söhne lordaerons"},ang={["faction:Alliance"]="Die Quest unterstreicht die gefährliche, isolierte Notlage der mit der Allianz verbündeten Überreste, die versuchen, innerhalb der verheerten Ruinen des nördlichen Lordaeron zu operieren. Sie verdeutlicht, wie verbliebene Abteilungen von Loyalisten mit schwindender Hoffnung und der psychischen Belastung durch den Kampf gegen überwältigende Monstrositäten ringen.",["race:Human"]="Menschliche Abenteurer werden Zeuge des herzergreifenden Schicksals von Lordaerons gefallener Führung, da selbst ein geschätzter Großmarschall in einen grotesken untoten Schrecken verwandelt wurde. Captain Trumans bittere Trauer und sein nationalistischer Eifer spiegeln das unverhohlene Trauma wider, das von menschlichen Überlebenden getragen wird, die verzweifelt danach streben, ihre angestammte Heimat zurückzufordern.",["race:Undead"]="Für die Verlassenen ist die groteske Transformation von The Baron eine düstere Erinnerung daran, wie die Geißel Lordaerons beste Verteidiger zu monströsen Abscheulichkeiten verstümmelte. Captain Trumans Gelöbnis, die Ruinen von allen Bestien und Untoten zu säubern, spiegelt die unerbittliche Feindseligkeit wider, die lebende Loyalisten gegenüber dem Volk von Unterstadt hegen."},sec={{t="Eine verzweifelte Wache",b="Captain Truman hält an seinem Posten aufmerksam Wache und wartet ängstlich auf längst überfällige Verstärkung zur Unterstützung der Verteidigung von Lordaeron. Fest im Vertrauen auf die kriegerische Tüchtigkeit seines Vorgesetzten – eines berühmten Großmarschalls, den er als hochgewachsenen, stattlichen Helden beschreibt – bleibt Truman pflichtbewusst zurück, nachdem ihm befohlen worden war, die Stellung zu halten, während sein Kommandant sich in das anhaltende Kampfgetümmel stürzte. Da er Außenstehenden gegenüber tiefes Misstrauen hegt und jene, die er als minderwertige Rassen ansieht, offen verachtet, weigert sich der Captain, lokalen Freischärlern zu vertrauen. Als sich ein fähiger Reisender nähert, ergreift Truman die Gelegenheit, um Hilfe zu bitten, und fleht darum, dass sich jemand in das zerstörte Gebiet wagt, um nach dem Wohlergehen seines Meisters zu sehen und die Schlacht zu beurteilen."},{t="Die Ruinen von Lordaeron",b="Die Suche führt Abenteurer direkt in die gefährlichen Ruinen von Lordaeron, die zerschlagene Hauptstadt, die während des Dritten Krieges an die Geißel fiel. Obwohl Captain Truman erwartet, dass sein ruhmreicher Anführer triumphierend über den Gefallenen steht, ist die Wirklichkeit in der verheerten Stadt weitaus düsterer. Die Ruinen sind von Schrecken, untoten Überresten und Abscheulichkeiten überrannt, die über die zerstörten Steinplätze streifen. Das Durchqueren dieser verwüsteten Straßen erfordert die Konfrontation mit der brutalen Wahrheit darüber, was mit den Verteidigern geschah, die sich in die Stadt wagten. Statt einen makellosen Ritter vorzufinden, der die Stellung hält, entdecken Reisende, dass der Kommandant inmitten der Monstrositäten, die die Höfe besetzen, ein tragisches, verzehrtes Ende fand."},{t="Eine schreckliche Enthüllung",b="Nachdem sie den vermissten Kommandanten, bezeichnet als The Baron, ausfindig gemacht haben, machen Abenteurer eine schreckliche Entdeckung: Der einst stattliche Held wurde in eine groteske untote Monstrosität verwandelt. Die Erfüllung der düsteren Aufgabe erfordert, die Kreatur zu erschlagen und Head of the Baron zu Captain Truman zurückzubringen. Als ihm der abgetrennte Kopf seines einstigen Herrn präsentiert wird, reagiert Truman mit Schock, Entsetzen und tiefem Abscheu. Unfähig, das schreckliche Schicksal seines Kommandanten zu akzeptieren, bricht der Captain in bitterer Empörung aus, beschuldigt den Abenteurer, mit Monstern im Bunde zu sein, und schwört, dass die wahren Söhne Lordaerons eines Tages ihr Land zurückfordern und alle Bestien tilgen werden."}},faq={{q="Wer vergibt die Quest Abominable Creatures?",a="Die Quest wird von Captain Truman angeboten, einem loyalistischen Menschen, der in der Region um das gefallene Königreich stationiert ist. Während er ängstlich seinen Posten hält und auf Verstärkung wartet, sucht Truman verzweifelt nach Neuigkeiten über seinen Kommandanten, einen verehrten Großmarschall, der in die nahe gelegenen Ruinen von Lordaeron gestürmt ist.",al={"wer vergibt abominable creatures","abominable creatures questgeber","wo beginnt abominable creatures"}},{q="Wo findet die Quest Abominable Creatures statt?",a="Die Quest führt Abenteurer in die Ruinen von Lordaeron, die zerschlagene Hauptstadt, die von Schrecken der Geißel und untoten Überresten überrannt wird. Captain Truman unterhält einen Posten außerhalb der verheerten Hauptstadt und bittet mutige Reisende, sich direkt in die gefährlichen Ruinen zu wagen, um seinen vermissten Vorgesetzten ausfindig zu machen.",al={"abominable creatures ort","wo wird abominable creatures abgeschlossen","abominable creatures zone"}},{q="Wer ist Captain Trumans Meister?",a="Captain Truman bezeichnet seinen Meister als den Großmarschall und lobt ihn als hochgewachsenen, stattlichen Kriegshelden. Die Questziele beziehen sich auf diesen vermissten Adligen jedoch als The Baron, was darauf hinweist, dass er ein hochrangiger Aristokrat und militärischer Befehlshaber war, der die Verteidigung des Reiches anführte.",al={"wer ist trumans kommandant","großmarschall identität truman","wer ist der baron"}},{q="Was geschah mit dem Großmarschall in den Ruinen von Lordaeron?",a="Anstatt siegreich standzuhalten, wurde der Großmarschall in den Ruinen von Lordaeron getötet und in eine monströse untote Kreatur verwandelt. Wenn Abenteurer ihn aufspüren, finden sie eine Abscheulichkeit vor, die als The Baron bezeichnet wird, was sie dazu zwingt, ihn zu vernichten und seinen abgetrennten Kopf an sich zu nehmen.",al={"was geschah mit dem baron","großmarschall schicksal","ist der großmarschall tot"}},{q="Warum wird Captain Truman wütend, wenn Ihr die Quest abgebt?",a="Captain Truman erwartete, dass sein stattlicher Kommandant lebendig und siegreich sei. Als ihm der groteske, mutierte Kopf von The Baron präsentiert wird, wird Truman von Entsetzen und Abscheu überwältigt; er wirft dem Abenteurer wütend vor, sich einen bösen Scherz zu erlauben und mit abscheulichen Bestien zu paktieren.",al={"warum ist truman wütend","truman reaktion abominable creatures","warum schreit truman euch an"}},{q="Was meint Captain Truman mit den „wahren Söhnen Lordaerons“?",a="Captain Truman verwendet den Begriff, um fanatische menschliche Patrioten zu beschreiben, die sich der Rückeroberung ihrer zerrütteten Heimat verschrieben haben. Seine Worte drücken eine unerbittliche, intolerante Vision aus, in der die rechtmäßigen menschlichen Überlebenden das Königreich von allen Untoten, Bestien und jedem säubern werden, von dem angenommen wird, dass er mit ihnen paktiert.",al={"wahre söhne lordaerons bedeutung","wer sind die wahren söhne lordaerons","truman wahre söhne"}},{q="Warum weigert sich Captain Truman, „Mischlingen“ zu vertrauen?",a="Captain Truman zeigt tiefe Verachtung für nichtmenschliche Völker und irreguläre Verbündete und tut sie als unzuverlässige Mischlinge und Dreck ab. Seine ausgeprägte Fremdenfeindlichkeit hindert ihn daran, sich irgendjemand anderem als jenen anzuvertrauen, die er als würdige Vertreter des Reiches erachtet.",al={"truman mischlinge","warum ist captain truman rassistisch","truman fremdenfeindlichkeit"}}},fp="20,456,17.710.0,22.711.0,23.661.1,41.290.0,53.295.0,31.285.0,61.280.0,61.274.0,62.286.0,54.258.0"}
P.entries["quest:953"] = {n="Der Untergang von Ameth'Aran",s="Schildwache Tysha Mondklinge beauftragt Abenteurer damit, die unheimlichen Ruinen von Ameth'Aran in Dunkelküste zu erkunden, um uralte Steintafeln zu entziffern. Diese Inschriften berichten von der Tragödie und dem Untergang, die die Stadt der Hochgeborenen während der Zerschlagung heimsuchten. Das gesammelte Wissen ist für den Circle of Ancients in Auberdine bestimmt, um Geschichte wiederzuerlangen, die während des Krieges der Ahnen weitgehend verloren ging.",h="Schildwache Tysha Mondklinge beauftragt Abenteurer damit, die unheimlichen Ruinen von Ameth'Aran in...",kw={"ameth'aran","auberdine","azshara","circle of ancients","dunkelküste","hochgeborene","zerschlagung","tafeln","tysha moonblade"},ang={["class:Mage"]="Die Tafeln bieten einen ernüchternden Einblick in die Höhepunkte der elfischen Zauberkunst vor der Zerschlagung und den schrecklichen Ruin, der entstand, als diese Macht außer Kontrolle geriet.",["faction:Alliance"]="Den Schildwachen dabei zu helfen, die Geschichte von Dunkelküste zu sichern, trägt dazu bei, entscheidendes Wissen für die Anführer der Nachtelfen zu bewahren, die die Allianz auf Kalimdor leiten.",["race:NightElf"]="Die Ruinen von Ameth'Aran sind eine düstere Erinnerung an die Hybris Eurer Ahnen unter Königin Azshara und die katastrophalen Folgen unkontrollierter arkaner Zauberei."},sec={{t="Echos der Hochgeborenen",b="Lange bevor die Küste in die nebligen Weiten von Dunkelküste zerbrach, war Ameth'Aran eine blühende Siedlung, in der Königin Azsharas elitäre Zauberer mächtige arkane Magie praktizierten. Nach der kataklysmischen Zerstörung des Brunnens der Ewigkeit vor zehntausend Jahren wurde die Stadt zu zerbrochenem Marmor und rissigen Säulen reduziert. Heute wird sie noch immer von den rastlosen, gequälten Geistern der Hochgeborenen heimgesucht, die starben, als ihr goldenes Zeitalter jäh endete."},{t="Verlorene Chroniken enthüllen",b="Weil der Krieg der Ahnen die Zivilisation der Nachtelfen in ein chaotisches Überleben stürzte, überstanden bemerkenswert wenige schriftliche Berichte die Große Zerschlagung unbeschadet. Schildwache Tysha Mondklinge versuchte, die Ruinen selbst zu untersuchen, und entdeckte zwei große eingravierte Tafeln – die Lay of Ameth'Aran und Der Untergang von Ameth'Aran –, bevor geisterhafte Erscheinungen der Hochgeborenen sie zum Rückzug zwangen. Das Bergen dieser Inschriften stellt sicher, dass die historischen Wahrheiten dieser uralten Katastrophe die Gelehrten des Circle of Ancients in Auberdine erreichen."}},faq={{q="Was ist Ameth'Aran?",a="Ameth'Aran ist eine uralte Nachtelfenruine im Zentrum von Dunkelküste. Vor zehntausend Jahren war es eine Stadt, in der Königin Azsharas Adelige der Hochgeborenen offen gewaltige arkane Magie wirkten und studierten, ehe sie während der Großen Zerschlagung unterging.",al={"ametharan hintergrundgeschichte","was war ameth aran","wer lebte in ameth aran"}},{q="Warum gibt es Geister in Ameth'Aran?",a="Die rastlosen Geister, die die Ruinen heimsuchen, sind die Seelen der Hochgeborenen, die dort lebten und starben. Gefangen in der plötzlichen, gewaltsamen Katastrophe, die den Brunnen der Ewigkeit zerschmetterte und Kalimdor zerteilte, bleiben ihre Geister in ewiger Qual an die Ruinen gebunden.",al={"warum gibt es geister in ameth aran","ameth aran geister","rastlose hochgeborene"}},{q="Wer ist Schildwache Tysha Mondklinge?",a="Schildwache Tysha Mondklinge ist eine Nachtelfen-Schildwache, die an der Straße in Dunkelküste stationiert ist. Sie wurde damit beauftragt, uralte Stätten auszukundschaften und verlorene historische Aufzeichnungen für den Circle of Ancients in Auberdine zu bergen.",al={"tysha moonblade","wer gibt der untergang von ameth aran"}},{q="Warum möchte der Circle of Ancients diese Tafeln lesen lassen?",a="Die Zerstörung des Brunnens der Ewigkeit stürzte Kalimdor in gewaltige Umwälzungen und vernichtete unzählige Bibliotheken und Monumente. Da nur so wenige schriftliche Aufzeichnungen den Krieg der Ahnen überstanden haben, bieten die Tafeln seltene Berichte aus erster Hand über die Zerschlagung aus der Sicht der Hochgeborenen.",al={"warum die tafeln lesen","circle of ancients tafeln","lay of ameth aran bedeutung"}},{q="Wo befinden sich die Tafeln?",a="Die beiden großen Tafeln – die Lay of Ameth'Aran und Der Untergang von Ameth'Aran – sind in stehende Steinmonumente eingemeißelt, die inmitten der zerstörten Innenhöfe von Ameth'Aran liegen, umgeben von den umherwandernden Geistern der einstigen Bewohner der Stadt.",al={"wo sind die tafeln von ameth aran","standorte der tafeln","wie man ameth aran liest"}},{q="Was geschah während der Zerschlagung mit den Hochgeborenen von Ameth'Aran?",a="Als der Brunnen der Ewigkeit auf dem Höhepunkt des Krieges der Ahnen implodierte, rissen gewaltige Beben und arkaner Rückschlag Kalimdor entzwei. Ameth'Aran stürzte in Trümmern ein, begrub seine Bewohner und ließ ihre Geister im Schutt zurück.",al={"wie ging ameth aran unter","zerstörung von ameth aran"}}},fx={["4f4506ec"]={q="Warum möchte Schildwache Tysha Mondklinge, dass dies getan wird?",a="Schildwache Tysha Mondklinge wurde im Namen des Zirkels der Ältesten ausgesandt, um die alten Ruinen zu vermessen. Aufzeichnungen aus der Ära des Krieges der Ahnen und der Teilung sind aufgrund der Kataklysmen jener Zeit äußerst selten. Das Sammeln der in die Tafeln gemeißelten Geschichte ermöglicht es ihr, den Druiden und Ältesten in Auberdine einen vollständigen Bericht zu erstatten.",al={"tysha mondklinge beweggrund","warum braucht tysha das","warum ameth'aran tafeln studieren"}},["2329a43d"]={q="Warum benötigt Schildwache Tysha Mondklinge Eure Hilfe?",a="Tysha wagte sich zuvor in Ameth'Aran, um die Tafeln selbst zu untersuchen, wurde jedoch aus dem Hinterhalt angegriffen und von den rachsüchtigen Geistern der Hochelfen, die in den Ruinen spuken, vertrieben. Da sie die Inschriften unter ständigem spektralem Angriff nicht sicher selbst transkribieren konnte, benötigt sie einen fähigen Abenteurer, der in die Ruinen eindringt und den Text an ihrer Stelle entziffert.",al={"warum kann tysha die tafeln nicht lesen","warum braucht tysha mich","warum geht tysha nicht selbst"}}},fp="22,378,23.450.0,26.515.0,19.237.0,35.260.0,32.210.0,56.292.0,30.233.0,66.238.0"}
P.entries["quest:95314"] = {n="Ein Elixier so grün wie das Schattental",s="Carolai Anise in Brill sucht nach Bergungsgut aus der verlassenen Siedlung Schattental, die tief im abgeschiedenen Flüsternden Wald verborgen liegt. Vor dem Fall des Königreichs war das Dorf berüchtigt für das Destillieren von Flüsterelixier aus seltsamen einheimischen Kräutern – ein wirkmächtiger Trank, der selbst nach seinem Verbot in Lordaeron auf dem Schwarzmarkt hoch geschätzt blieb.",h="Carolai Anise in Brill sucht nach Bergungsgut aus der verlassenen Siedlung Schattental, die tief im...",kw={"apotheker","brill","carolai anise","gift","schattental","tirisfal","flüsterelixier","der flüsternde wald"},ang={["class:Rogue"]="Flüsterelixier wurde lange Zeit von illegalen Giftmischern und Schurken geschätzt, die unbemerkt von den einstigen Magistraten Lordaerons agierten.",["profession:Herbalism"]="Das Elixier verdankt seine Wirksamkeit einzigartigen Kräutern, die nur unter dem unheimlichen Blätterdach des abgeschiedenen Flüsternden Waldes gedeihen.",["race:Undead"]="Für die Verlassenen dient die Bergung von Lordaerons vergessenen Destillaten sowohl dem profitablen Handel als auch alchemistischen Experimenten in der noch jungen Unterstadt."},sec={{t="Ein verbotenes Gebräu",b="Lange vor dem Dritten Krieg und der Ankunft der Geißel brauten die zurückgezogen lebenden Bewohner von Schattental ein unverwechselbares Gebräu, das als Flüsterelixier bekannt war. Destilliert aus seltenen, nur in Tirisfal vorkommenden Kräutern, erlangte der Trank im gesamten nördlichen Lordaeron Berühmtheit. Obwohl er in der Hauptstadt offiziell verboten war, machten ihn seine ungewöhnlichen Eigenschaften bei Mystikern, Giftmischern und praktizierenden Apothekern heiß begehrt, die bereit waren, königliche Dekrete zu umgehen."},{t="Ruinen im Flüsternden Wald",b="Schattental liegt tief im Flüsternden Wald des westlichen Tirisfal verborgen. Die Dorfbewohner waren von jeher ein abgeschottetes und misstrauisches Volk, das Fremde selten willkommen hieß. Nach der Invasion der Geißel verfiel die Siedlung in Ruinen, doch vergessene Vorräte des gereiften grünen Elixiers verbleiben inmitten der Trümmer. Carolai Anise operiert von Brill aus und nutzt die anhaltende Nachfrage der Unterwelt, um Abenteurer zu entlohnen, die bereit sind, der beunruhigenden Stille des Waldes zu trotzen."},{t="Der Flüsternde Fluch",b="Während Carolai Gerüchte lieber als einfachen Aberglauben abtut, haftet dem Flüsternden Wald ein finsterer Ruf an. Lokale Überlieferungen besagen, dass der Boden und die Wurzeln des Waldes selbst von einem uralten Fluch verdorben sind, der direkt in die von Schattentals Brauern geerntete Flora übergeht. Welche anhaltende Bosheit das verlassene Dorf auch heimsucht, sie hat dem Verlangen fernab gelegener Käufer nach seinen abgefüllten Überresten kaum einen Dämpfer verpasst."}},faq={{q="Was ist Schattental?",a="Schattental war ein abgeschiedenes Dorf, das tief im Flüsternden Wald im westlichen Tirisfal lag. Seine Bewohner waren verschwiegene Isolationisten, die vor allem dafür bekannt waren, seltene Gebräue aus der örtlichen Wildnis zu destillieren, bevor die Geißel die Region überrannte.",al={"wo liegt schattental","wer lebte in schattental","dorf schattental"}},{q="Was ist Flüsterelixier?",a="Es ist ein wirkmächtiger grüner Trank, der aus einzigartigen Kräutern Tirisfals gebraut wurde. Von Mystikern, Giftmischern und Apothekern hoch geschätzt, war das Getränk vor dem Fall Lordaerons in der Hauptstadt verboten.",al={"was bewirkt das elixier","hintergrund ein elixier so grün wie das schattental","flüsterelixier"}},{q="Wer ist Carolai Anise?",a="Carolai Anise ist eine einfallsreiche Verlassene mit Wohnsitz in Brill. Sie fungiert als Maklerin für wertvolle und verbotene Kuriositäten und beschafft illegale Reagenzien wie Schattentals Elixier, um sie an interessierte Käufer im ganzen Reich zu verkaufen.",al={"carolai anise","wer vergibt die quest ein elixier so grün wie das schattental","questgeber brill"}},{q="Warum war das Elixier in der Hauptstadt verboten?",a="Es wird kein Grund genannt. Carolai erwähnt lediglich, dass das Elixier in der Stadt verboten war und dass Apotheker, Mystiker und Giftmischer es dennoch begehrten. Manche glauben, dass der Flüsternde Wald verflucht ist und das aus seinen Wurzeln destillierte Elixier denselben Fluch in sich trägt, doch Carolai tut dies als Aberglauben ab und bringt es nie mit dem Verbot in Verbindung.",al={"warum war flüsterelixier illegal","ist das elixier gift"}},{q="Warum gilt der Flüsternde Wald als gefährlich?",a="Die abgeschiedenen Wälder westlich von Todesend gelten weithin als unheimlich und verflucht. Diejenigen, die sich dorthin wagen, berichten von tiefer Bosheit und seltsamen Phänomenen der Wildnis, von denen Gerüchte behaupten, sie hätten die aus seinem Boden wachsenden Kräuter verdorben.",al={"ist der flüsternde wald verflucht","flüsternder wald hintergrund"}},{q="Wer sind die Käufer, die dieses Elixier wollen?",a="Laut Carolai Anise sind einige Käufer begierig darauf, verbliebene Flaschen aus der Vorkriegszeit zu erwerben, wenngleich sie nicht verrät, wer diese Käufer sind.",al={"wer kauft das elixier","käufer von carolai anise"}}},fx={["4d019fa8"]={q="Warum möchte Carolai Anise, dass das Whispering Elixir gesammelt wird?",a="Carolai Anise agiert als Beschafferin seltener Güter in Brill, und die Nachfrage nach dem illegalen Gebräu ist nie wirklich versiegt. Da zahlreiche eifrige Käufer sie zu Lieferungen drängen, lässt sich mit den Flaschen, die unter den Ruinen intakt geblieben sind, beträchtlicher Profit erzielen.",al={"warum will carolai das elixier","carolai anise beweggrund","warum whispering elixir sammeln"}}},fp="28,340,13.457.0,30.465.0,20.427.1,19.249.0,26.193.0,21.218.0,46.329.0,50.219.0,39.131.0"}
P.entries["quest:95328"] = {n="Whispering Horror Residue",s="Whispering Horror Residue ist der zappelnde Überrest einer seltsamen Bestie, die unter dem Flüsternden Wald geborgen wurde. Von unerschrockenen Abenteurern gesammelt, werden diese von der Leere berührten Überreste zu Vater Lankester ins War Quarter in Unterstadt für Schattenforschungen gebracht.",h="Whispering Horror Residue ist der zappelnde Überrest einer seltsamen Bestie, die unter dem Flüsternden Wald...",kw={"vater lankester","schatten","tirisfal","unterstadt","leere","war quarter","der flüsternde wald","whispering horror residue"},ang={["class:Priest"]="Schattenpriester der Verlassenen wie Vater Lankester hegen ein intensives wissenschaftliches und theologisches Interesse an Leerenproben und betrachten seltsame planare Überreste eher als Studienobjekte denn als bloße Abscheulichkeiten.",["faction:Horde"]="Abenteurer im Dienste der Horde bergen beunruhigende Proben aus den verborgenen Gefilden von Tirisfal, um die Forschungsbemühungen unter den Ruinen der Hauptstadt anzutreiben.",["race:Undead"]="Die Verlassenen von Unterstadt erforschen aktiv verbotene Magie und unnatürliche Verderbnisse in ganz Lordaeron und versuchen, dunkle Phänomene zu nutzen, um ihren unsicheren Halt im Königreich zu stärken."},sec={{t="Eine beunruhigende Ernte",b="Whispering Horror Residue stellt die bizarren, zappelnden Überreste dar, die von einer besiegten Bestie abgekratzt wurden, welche unter dem Flüsternden Wald hauste. Anstatt eine derart unnatürliche Kuriosität zurückzulassen, sammeln erfindungsreiche Abenteurer das zuckende Material in der Hoffnung, dass Forscher in Unterstadt es sinnvoll nutzen können."},{t="Studien im Schatten",b="Die Überreste der Kreatur finden in Vater Lankester, der sich im War Quarter von Unterstadt befindet, einen begierigen Abnehmer. Lankester bemerkt, dass Der Flüsternde Wald seit langem von der Leere berührt ist, und begrüßt die Gelegenheit, physische Überbleibsel dieser dunklen Verderbnis zu untersuchen, während er die Geheimnisse des Schattens ergründet."}},faq={{q="Was ist Whispering Horror Residue?",a="Whispering Horror Residue besteht aus den zappelnden körperlichen Überresten, die von einer seltsamen Bestie erbeutet wurden, welche unter dem Flüsternden Wald besiegt wurde. Trotz seiner beunruhigenden Natur halten Gelehrte von Shadow Magic es für wertvoll für arkane und okkulte Forschungen.",al={"was sind die rückstände","was ist whispering horror residue","rückstand gegenstand"}},{q="Wer möchte Whispering Horror Residue?",a="Die Rückstände werden zu Vater Lankester gebracht, einer Gestalt der Verlassenen im War Quarter von Unterstadt. Er begrüßt die Gelegenheit, die Geheimnisse des Schattens und von der Leere berührte Phänomene zu erforschen.",al={"wer nimmt die rückstände","wer ist vater lankester","wo rückstände abgeben"}},{q="Woher stammt diese Probe?",a="Die Probe stammt von unterhalb des Flüsternden Waldes, einem unheilvollen Waldgebiet westlich von Todesend in Tirisfal. Wie Vater Lankester bemerkt, ist die üble Gegend dafür bekannt, von der Leere berührt zu sein.",al={"woher kommt das grauen","der flüsternde wald lore","unter dem flüsternden wald"}},{q="Warum möchte Vater Lankester die Rückstände?",a="Vater Lankester strebt danach, die Geheimnisse des Schattens und der Leere zu studieren. Für Ausübende der Verlassenen, die verbotene Künste erforschen, bieten physische Überbleibsel von durch die Leere verdorbenen Kreaturen seltene Einblicke und Forschungsmaterial.",al={"warum will lankester das","unterstadt schattenforschung","warum rückstände untersuchen"}},{q="Wo ist Vater Lankester zu finden?",a="Vater Lankester weilt im War Quarter von Unterstadt. Das War Quarter dient als geschäftiges Zentrum für Krieger, Gelehrte und militärische Planer der Verlassenen unter den Ruinen von Lordaerons Hauptstadt.",al={"wo ist das war quarter","wo befindet sich lankester","unterstadt lankester standort"}},{q="Ist Der Flüsternde Wald von der Leere berührt?",a="Der Flüsternde Wald hat unter den Einheimischen von Tirisfal seit langem einen unheimlichen Ruf. Vater Lankester bemerkt, es sei kein Geheimnis, dass die üblen Wälder und die unterirdischen Räume darunter von der Leere berührt sind.",al={"ist der flüsternde wald verflucht","leerenverderbnis der flüsternde wald","was berührt den flüsternden wald"}}},fp="25,256,21.318.0,17.307.0,38.242.0,40.195.0,34.206.0,43.211.0,36.195.0,45.212.0"}
P.entries["quest:95349"] = {n="The Earthen Ring",s="Diese Reise markiert die Ankunft der Windformer aus Zephras auf Azeroth als Vorhut nach Verzögerungen, die durch Kultistenaktivitäten in Valanaar verursacht wurden. An Bord eines Himmelssegler-Schiffs vor der Loge gehen die Reisenden in Mulgore an Land, um Alaana Stormwalker zu treffen und sich in einer riesigen und gefährlichen neuen Welt einzugewöhnen.",h="Diese Reise markiert die Ankunft der Windformer aus Zephras auf Azeroth als Vorhut nach Verzögerungen, die...",kw={"alaana sturmwanderer","banu-alah","kult","mulgore","himmelssegler","der irdene ring","valanaar","windformer","zephras"},ang={["class:Shaman"]="Windformer und Schamanen teilen eine tiefe Ehrfurcht vor den Elementen und verlassen sich auf die Gunst der Winde, um ihre Luftüberfahrt zu leiten. Ihre Ankunft unter dem Banner des Irdenen Rings verbindet sie direkt mit den elementaren Traditionen, die in Mulgore Wurzeln schlagen.",["race:Skyborne"]="Für Himmelsgeborene Abenteurer, die aus Valanaar aufbrechen, markiert diese Reise ihre historische Ankunft auf Azeroth als Vorhut. Sie lassen die Kultprobleme ihrer Heimat hinter sich und setzen ihre ersten Schritte auf Die wogenden Ebenen von Mulgore.",["race:Tauren"]="Als einheimische Hüter von Mulgore werden die Tauren Zeuge der Ankunft neuer Reisender aus Zephras, die auf ihre angestammten Ebenen herabsteigen. Die Begrüßung dieser Himmelsreisenden bietet eine frühe Verbindung zu Verbündeten, die in ihren Landen Fuß fassen."},sec={{t="Abreise aus Valanaar",b="Reisende, die nach Azeroth aufbrechen, müssen ihre Pläne aufgrund jüngster Störungen durch Kultaktivitäten in Valanaar anpassen. Während hochrangige Anführer in der Loge zurückbleiben, um dringende Angelegenheiten zu regeln und die Bedrohung durch die Kultisten abzuwenden, wird eine kleine Vorhut von Windformern vorausgeschickt. Diese Pioniere reisen zu den Docks direkt vor der Loge und gehen an Bord eines Himmelssegler-Schiffs, das durch die Lüfte fährt. Obwohl ihre Kommandanten versprechen, bald zu ihnen zu stoßen, ruht die anfängliche Expedition ganz auf den Schultern dieser Vorhut, die vorausgesandt wurde, um eine Präsenz aufzubauen, bevor der Rest folgen kann."},{t="Ankunft in Mulgore",b="Nach der Landung in den wogenden Ebenen von Mulgore werden die ankommenden Abenteurer aus Zephras von Alaana Stormwalker willkommen geheißen. Der Aufbau eines Stützpunkts auf Azeroth wird Zeit und sorgfältige Anstrengungen erfordern, sodass die Neuankömmlinge ermutigt werden, das umliegende Gebiet auszukundschaften und sich an ihre neue Umgebung zu gewöhnen. Während die Winde der ankommenden Expedition hold sind, bleibt Azeroth ein unbekanntes und gefährliches Reich. Sich mit dem örtlichen Terrain, der Tierwelt und den benachbarten Bewohnern vertraut zu machen, ist ein wesentlicher erster Schritt, bevor die verbleibenden Reisenden aus Valanaar eintreffen, um sich den Bemühungen anzuschließen."}},faq={{q="Warum reisen die Windformer nach Azeroth?",a="Eine Vorhut von Windformern wird vorausgeschickt, um eine Präsenz auf Azeroth zu errichten, während ihre Anführer in Valanaar zurückbleiben. Jüngste Unruhen rund um einen lokalen Kult störten die ursprünglichen Reisepläne und verzögerten den Rest der Gruppe. Infolgedessen reist diese Vorhut allein voraus, um an Land zu gehen und einen Stützpunkt zu sichern, bis Verstärkung folgen kann.",al={"warum nach azeroth reisen","mission der windformer","warum sind die windformer in mulgore"}},{q="Wer ist Alaana Stormwalker?",a="Alaana Stormwalker ist die Kontaktperson, die darauf wartet, die ankommenden Windformer bei ihrer Landung in Mulgore in Empfang zu nehmen. Sie heißt die aus Zephras anreisenden Reisenden willkommen und stellt fest, dass der Aufbau einer sicheren Präsenz in diesen neuen Landen Zeit erfordern wird. Während die Vorbereitungen anlaufen, rät sie den neu eingetroffenen Abenteurern, die umliegende Region zu erkunden und sich auf die Gefahren von Azeroth vorzubereiten.",al={"wer ist alaana","rolle von alaana sturmwanderer","wo ist alaana sturmwanderer"}},{q="Warum wurde die Hauptabreise verzögert?",a="Die Hauptreise von Valanaar wurde aufgrund jüngster besorgniserregender Vorfälle im Zusammenhang mit einem lokalen Kult verschoben. Die Bewältigung dieser Kultisten-Komplikationen zwang die Expeditionsleiter dazu, in der Loge zurückzubleiben, um ihre Angelegenheiten zu beenden. Anstatt die Mission vollständig abzubrechen, entsandten sie eine kleine Vorhut von Windformern an Bord eines Himmelsseglers, um den Weg nach Azeroth zu weisen.",al={"warum die verzögerung","welcher kult verzögerte die reise","warum in valanaar bleiben"}},{q="Wie reisen Reisende von Valanaar nach Mulgore?",a="Reisende treten die Reise an, indem sie an Bord eines Himmelssegler-Schiffs gehen, das direkt vor der Loge in Valanaar vor Anker liegt. Dieses Schiff befördert die Vorhut über den Himmel zu den Ebenen von Mulgore und dient während der ersten Expedition als wichtigstes Transportmittel, das Zephras mit den Ländern von Azeroth verbindet.",al={"wie man mulgore erreicht","wo ist das schiff","wie reist man nach azeroth"}},{q="Was ist Zephras?",a="Zephras ist die Heimat oder der Ursprung der ankommenden Abenteurer, die an Bord des Himmelsseglers eintreffen. Wenn Reisende Mulgore erreichen, erkennt Alaana Stormwalker sie als Neuankömmlinge aus Zephras und stellt fest, dass günstige Winde ihre Überfahrt in das unbekannte und gefährliche Gebiet von Azeroth geleitet haben.",al={"wo liegt zephras","was ist zephras","zephras lore"}},{q="Was sollten Abenteurer tun, sobald sie in Mulgore ankommen?",a="Neu angekommenen Abenteurern wird geraten, die umliegenden Lande von Mulgore auszukundschaften und zu erkunden. Da der Aufbau einer festen Präsenz Zeit in Anspruch nimmt, ist das Vertrautmachen mit dem nahe gelegenen Terrain, den Kreaturen und den lokalen Bedrohungen eine wesentliche Vorbereitung, um sich in dieser aufregenden und dennoch gefährlichen neuen Welt zurechtzufinden.",al={"was man in mulgore tun kann","nächste schritte nach der ankunft","was als nächstes zu tun ist"}}},fp="16,317,23.583.0,18.573.0,45.356.0,26.381.0,35.358.0,50.281.0,16.299.0,52.302.0"}
P.entries["quest:95350"] = {n="Welcome to Azeroth",s="„Willkommen auf Azeroth“ ist eine einführende Quest, die im Namen der Windformer einen Reisenden von Donnerfels nach Orgrimmar entsendet. Geleitet von den spirituellen Banden des Irdenen Rings trifft der Abgesandte Kriegshäuptling Thrall, um Bande des Überlebens und des Bündnisses mit der Horde zu schmieden.",h="„Willkommen auf Azeroth“ ist eine einführende Quest, die im Namen der Windformer einen Reisenden von...",kw={"der irdene ring","horde","orgrimmar","thrall","donnerfels","tal der weisheit","willkommen auf azeroth","windformer"},ang={["class:Shaman"]="Mit einer Führung, die den Irdenen Ring anruft, und dem Segen der Winde verbindet diese Reise spirituelle Verwandte direkt mit dem Herzen der schamanistischen Führung im Tal der Weisheit.",["faction:Horde"]="Diese diplomatische Mission formalisiert die Bande mit der Horde und stellt Neuankömmlinge Kriegshäuptling Thrall direkt als wichtige Verbündete für das Überleben in Kalimdor vor.",["race:Skyborne"]="Die Skyborne Windformer verlassen die luftigen Höhen in Richtung der darunter liegenden Oberflächenwelt und strecken ihre Fühler nach Donnerfels und Orgrimmar aus, um sich ihren Platz unter neuen Verbündeten zu sichern."},sec={{t="Verbündete in einer größeren Welt",b="Beim Vorstoß in die weiten Gefilde von Kalimdor stellen Neuankömmlinge schnell fest, dass das Überleben von Brüderlichkeit abhängt. Die Windformer blicken über ihre isolierten Ursprünge hinaus auf die darunter wandelnden Völker und erkennen, dass Isolation keinen Schutz vor den Bedrohungen von Azeroth bietet. Indem sie der benachbarten Taurenstadt Donnerfels die Hand reichen und den Blick auf die orkischen Bastionen im Osten richten, suchen sie nach standhaften Gefährten, um der Wildnis gemeinsam zu trotzen."},{t="Eine Audienz beim Kriegshäuptling",b="Die Reise führt Gesandte zu den hoch aufragenden Türmen von Donnerfels, bevor sie sie durch das Brachland nach Orgrimmar, der mächtigen Hauptstadt der Horde, leitet. Im beschaulichen Tal der Weisheit wartet Kriegshäuptling Thrall, das leitende Herz der Koalition. Vor Thrall zu treten markiert den offiziellen Eintritt der Windformer in das politische und spirituelle Gefüge von Kalimdor, verbunden durch gemeinsame Ziele und geteilten Respekt vor den Elementen."}},faq={{q="Was ist der Zweck der Quest „Willkommen auf Azeroth“?",a="„Willkommen auf Azeroth“ ist eine diplomatische Einführungsquest, die einen Gesandten im Auftrag der Windformer entsendet, um Kriegshäuptling Thrall in Orgrimmar zu treffen. Sie dient als offizielle Einführung in die weitere Horde und die Oberflächenwelt von Kalimdor.",al={"was ist diese quest","quest willkommen auf azeroth","zweck von willkommen auf azeroth"}},{q="Wer sind die Windformer?",a="Die Windformer sind eine Gruppe, die sich von oben an Verbündete an der Oberfläche wendet und ihr Überleben durch Verbundenheit mit dem Irdenen Ring und der Horde sucht. Sie entsenden Reisende, um direkt mit der Führung der Horde in Durotar zu sprechen.",al={"wer sind die windformer","was sind die windformer"}},{q="Warum werdet Ihr geschickt, um mit Thrall zu sprechen?",a="Als Kriegshäuptling der Horde und verehrter schamanistischer Anführer wacht Thrall vom Tal der Weisheit aus über die bedeutenden Bündnisse der Koalition. Die Kontaktaufnahme mit ihm formalisiert die Beziehungen zwischen den Windformern und der Horde.",al={"warum thrall aufsuchen","mit thrall in orgrimmar sprechen","warum nach orgrimmar reisen"}},{q="Wie reist Ihr von Donnerfels nach Orgrimmar?",a="Reisende nehmen den Flug beim Flugmeister am zentralen Horst von Donnerfels und gleiten über die Ebenen von Kalimdor gen Osten in die Schluchtenfestung von Orgrimmar.",al={"wie man nach orgrimmar gelangt","flugmeister von donnerfels","von donnerfels nach orgrimmar gelangen"}},{q="Wie fügt sich der Irdene Ring in diese Mission ein?",a="In dieser Begegnung wird der Irdene Ring als im Einklang mit der Horde stehende Koalition gleichgesinnter Völker beschrieben, die dabei hilft, Bande zwischen schamanistischen Fraktionen und den Völkern von Kalimdor zu knüpfen.",al={"rolle des irdenen rings in der horde","gehört der irdene ring zur horde"}},{q="Wo befindet sich Thrall in Orgrimmar?",a="Kriegshäuptling Thrall residiert im Tal der Weisheit, einer ruhigen spirituellen Zuflucht im westlichen Teil von Orgrimmar, wo Schamanen und Stammesberater zusammenkommen.",al={"wo ist thrall","aufenthaltsort von thrall im tal der weisheit"}}},fp="18,275,25.456.0,29.431.0,52.238.0,24.215.0,38.218.0,50.177.0,48.190.0,37.159.0"}
P.entries["quest:954"] = {n="Bashal'Aran",s="Die dämonischen Satyrn und bösartigen Grells, die die uralte Nachtelfenstadt Bashal'Aran heimsuchen, nähern sich einem bestimmten Schrein nicht, der in eine übernatürliche blaue Aura gehüllt ist. Thundris Windweaver, der Älteste von Auberdine, sendet Abenteurer aus, um den Ursprung dieser unberührten Zuflucht zu ergründen.",h="Die dämonischen Satyrn und bösartigen Grells, die die uralte Nachtelfenstadt Bashal'Aran heimsuchen, nähern...",kw={"asterion","bashal'aran","blaue aura","dunkelküste","grell","kaldorei-ruinen","satyr","thundris windweaver"},ang={["faction:Alliance"]="Die Späher von Auberdine verlassen sich auf Wanderer der Allianz, um in die umkämpften Ruinen der Dunkelküste vorzudringen und dämonische Bedrohungen zu neutralisieren, bevor sie die Küste erreichen.",["race:NightElf"]="Bashal'Aran ist eine düstere Mahnung an das, was während der Zerschlagung verloren ging – ein Ort, an dem verbliebene Schemen Eures uralten Volkes noch immer einsame Wachen gegen die vordringende dämonische Verderbnis halten."},sec={{t="Ein Leuchtfeuer in den Ruinen",b="Bashal'Aran war einst eine prachtvolle Siedlung des uralten Reichs der Kaldorei, doch sein geborstener Marmor und die überwucherten Bögen wimmeln heute von dämonischer Verderbnis. Entartete Satyrn und verdorbene Grells laben sich gierig an den verbliebenen magischen Energien der Ruinen, und ihre Bosheit wächst mit jedem Tag. Doch ungeachtet ihrer räuberischen Vorherrschaft entdeckte Thundris Windweaver in Auberdine ein Kuriosum: Auf einer westlichen Klippe in den Ruinen glimmt eine ätherische blaue Aura über einem Schrein, dem sich kein Dämon nähert."},{t="Der verwundete Schemen",b="Wer den dämonischen Patrouillen trotzt, um den erhabenen Schrein zu erreichen, erkennt, dass das blaue Licht kein natürliches Phänomen ist. Es geht von Asterion aus, einem uralten Geist, dessen Wache über Jahrhunderte der Einsamkeit hinweg andauert. Umgeben von heulenden Bestien und abscheulichen Unholden empfindet der müde Schemen selbst einen reisenden Fremden als willkommene Erleichterung nach Jahrzehnten der Isolation."}},faq={{q="Wo befindet sich die blaue Aura?",a="Die blaue Aura leuchtet auf einer kleinen Anhöhe am westlichen Rand der Ruinen von Bashal'Aran, direkt östlich von Auberdine an der Dunkelküste. Sie liegt etwas erhöht über den umgebenden zerfallenen Mauern.",al={"blaue aura finden","wo ist asterion","ort des schreins von bashal'aran"}},{q="Warum meiden die Satyrn den Schrein?",a="Niemand weiß es bisher. Eine seltsame blaue Aura erfüllt den Schrein, und die dämonischen Satyrn und Grells, die die Ruinen ansonsten heimsuchen, nähern sich ihm nicht. Thundris Windweaver schickt Euch aus, um die Quelle der Aura zu finden.",al={"warum damonen angst haben","warum satyrn fernbleiben"}},{q="Wer schickt Euch auf diese Quest?",a="Thundris Windweaver, ein Nachtelfendruide und der Älteste von Auberdine, vergibt die Quest, nachdem er die unnatürlichen dämonischen Bewegungen in den östlichen Ruinen beobachtet hat.",al={"wer gibt quest","questgeber","aufenthaltsort von thundris windweaver"}},{q="Was ist Bashal'Aran?",a="Bashal'Aran ist eine uralte Kaldorei-Ruine, eingebettet in die Wälder der Dunkelküste. Während der uralten Zerschlagung geplündert, wird sie nun von magischen Parasiten, Grells und Satyrn heimgesucht, die sich an ihren schlummernden Ley-Kräften laben wollen.",al={"was geschah mit bashal'aran","geschichte von bashal'aran"}}},fx={["2cba9e48"]={q="Warum möchte Thundris Windweaver, dass ich Bashal'Aran untersuche?",a="Thundris Windweaver beobachtet die alten Ruinen von Bashal'Aran mit wachsender Sorge. Verderbte Sprites und Satyrn wimmeln auf dem Gelände und nutzen verbleibende arane Energien, um ihre dämonische Macht zu vergrößern. Doch inmitten dieses Befalls bleibt ein einziger Schrein, der von einer seltsamen blauen Aura umgeben ist, völlig unberührt von den Dämonen. Thundris muss verstehen, welche Macht sie in Schach hält – und ob dies der Schlüssel sein könnte, um die Verderbnis zurückzudrängen, die an der Dunkelküste überhandnimmt.",al={"warum bashal'aran untersuchen","thundris beweggrund","warum mich nach bashal'aran schicken"}}},fp="11,275,21.493.0,17.354.1,31.197.0,35.204.0,28.159.0,20.223.0"}
P.entries["quest:955"] = {n="Bashal'Aran",s="Asterion, ein trauernder Geist der Hochgeborenen, der die uralten Ruinen von Bashal'Aran heimsucht, sucht nach einem Weg, die bindende Magie zu lösen, die seine spektrale Gestalt fesselt. Im Glauben, die schelmischen einheimischen Grells hätten das Siegel berührt, das ihn festhält, beauftragt er Reisende damit, deren Ohrringe zu sammeln, um seiner verbliebenen magischen Resonanz nachzuspüren.",h="Asterion, ein trauernder Geist der Hochgeborenen, der die uralten Ruinen von Bashal'Aran heimsucht, sucht...",kw={"asterion","bashal'aran","die bindung","dunkelküste","geist","grell","grellohrring","siegel"},ang={["class:Mage"]="Asterions Methode, verzauberten Zierrat zu nutzen, um verbliebenen magischen Ausstrahlungen nachzuspüren, spiegelt uralte Praktiken der Hochgeborenen zur arkanen Weissagung wider.",["faction:Alliance"]="Die Beseitigung der chaotischen Grells um Bashal'Aran hilft dabei, die tückischen nördlichen Weiten der Dunkelküste für die Allianz zu befrieden.",["race:NightElf"]="Für die Kaldorei ist die Begegnung mit Asterion eine ernüchternde Erinnerung an die uralte Zivilisation, die während der Zerschlagung unterging und gequälte Seelen jahrtausendelang in Ruinen gebunden zurückließ."},sec={{t="Eine jahrhundertealte Qual",b="Inmitten des zerborstenen Marmors von Bashal'Aran verweilt Asterion, ein uralter Nachtelfengeist, der Jahrhunderte der Gefangenschaft ertragen hat. Gefangen zwischen Leben und wahrem Tod, ist seine Existenz zu einem qualvollen Warten unter dem Blätterdach der Dunkelküste verkümmert. Durch arkane Kunst direkt an die verfallene Siedlung gekettet, fehlen Asterion die Mittel, seine Fesseln allein abzustreifen, während sein Verstand durch ungezählte Jahre der Einsamkeit und Verzweiflung zermürbt wurde."},{t="Spuren in der Wildnis",b="Asterion vermutet, dass der Schlüssel zu seiner Befreiung ein uraltes Siegel ist, das irgendwo in den Ruinen verborgen liegt. Da er das Dickicht und die eingestürzten Steine nicht selbst physisch durchkämmen kann, nutzen die wilden Grells, die Bashal'Aran heimsuchen, jede Gelegenheit, um kleine Schmuckstücke zu erbeuten und zu horten. Asterion bittet Reisende, die Ohrringe dieser Kreaturen zu sammeln, um die verbliebenen magischen Eindrücke auf den Zierräten zu deuten und das Siegel zu lokalisieren, das seine Seele in Qualen gefangen hält."}},faq={{q="Wer ist Asterion?",a="Asterion ist ein uralter Geist eines Nachtelfen, der an die Ruinen von Bashal'Aran an der Dunkelküste gebunden ist. Seit Jahrhunderten durch ein mystisches Siegel gefangen, hat er den Lauf der Zeitalter voller Qualen miterlebt und sehnt sich nach der Erlösung aus seinem spektralen Dasein.",al={"asterion lore","wer ist der geist in bashal'aran","asterion questgeber"}},{q="Warum möchte Asterion Ohrringe der Grells?",a="Grells sind berüchtigte Aasfresser und Sammler, die glänzenden Zierrat und Schmuck horten. Asterion glaubt, dass die Kreaturen das magische Siegel berührt haben, das ihn bindet, sodass ihre getragenen Ohrringe genügend magische Rückstände aufweisen könnten, um ihm bei der Lokalisierung zu helfen.",al={"warum grellohrringe","zweck der grellohrringe","ohrringe quest dunkelküste"}},{q="Was ist Bashal'Aran?",a="Bashal'Aran ist eine uralte Nachtelfenruine an der bewaldeten Küste der Dunkelküste, die aus der Zeit vor der Großen Zerschlagung stammt. Sie ist von wilden Grells, Satyren und den spektralen Überresten ihrer längst gefallenen Bewohner überrannt.",al={"was ist bashal'aran","geschichte von bashal'aran","ruinen von bashal'aran"}},{q="Was geschieht nach dem Sammeln der Ohrringe?",a="Asterion untersucht die Ohrringe und spürt, dass die Grells das Siegel zwar nicht bei sich tragen, aber in für seine Begriffe relativ jüngerer Zeit damit in Berührung gekommen sind. Diese Spur ermöglicht es ihm, dessen Standort innerhalb der Ruinen einzugrenzen.",al={"was die ohrringe zeigen","hatten die grells das siegel","grellohrring ergebnis"}},{q="Warum ist Asterion hier gefangen?",a="Asterion wurde vor Jahrhunderten durch ein uraltes magisches Siegel an Bashal'Aran gekettet. Die Bindung verankert seinen Geist an dem physischen Ort der Ruinen und hindert ihn daran, zur ewigen Ruhe einzugehen.",al={"wer band asterion","wie asterion gebunden ist","asterions siegel"}},{q="Was sind Grells?",a="Grells sind kleine, boshafte Waldkreaturen, die in den Wäldern Kalimdors heimisch sind. Bekannt für ihr schelmisches Wesen, ihre scharfen Krallen und ihre Vorliebe für Schmuckgegenstände, befallen sie häufig alte Ruinen und greifen vorbeiziehende Reisende an.",al={"was ist ein grell","grells lore","dunkelküste grells"}}},fx={["99bf1a9e"]={q="Warum möchte Asterion, dass dies getan wird?",a="Asterion ist in einer qualvollen spektralen Form gefangen, die durch ein altes magisches Siegel an die Ruinen von Bashal'Aran gebunden ist. Die jahrhundertelange Gefangenschaft hat seinen Verstand langsam zersetzt, und er sehnt sich nach Erlösung von dieser Qual. Durch die Untersuchung der Ohrringe, die die lokalen Kreaturen tragen, hofft er, den genauen Ort des Schutzzaubers, der ihn bindet, magisch auszukundschaften, damit er letztendlich zerstört werden kann.",al={"asterion beweggrund","warum asterion helfen","warum will asterion ohrringe"}},a8a71265={q="Warum benötigt Asterion Eure Hilfe, anstatt selbst zu handeln?",a="Asterion ist ein körperloser Geist, der durch mächtige Zauberei direkt an die Ruinen gebunden ist. Da er nicht in der Lage ist, sich weit über seinen unmittelbaren Ruheplatz hinaus zu wagen oder physisch gegen die Grells und Sprites zu kämpfen, verlässt er sich vollständig auf vorbeiziehende Sterbliche, die die Kreaturen jagen und ihre Schmuckstücke für seine Weissagungen sammeln.",al={"warum braucht asterion mich","warum kann asterion die ohrringe nicht holen","warum kann asterion nicht weg"}}},fp="11,315,23.421.0,18.442.0,16.219.0,38.232.0,20.222.0,43.236.1,29.199.0,16.210.0"}
P.entries["quest:956"] = {n="Bashal'Aran",s="Asterion, der Geist eines Nachtelfen, der zwischen den verfallenen Säulen von Bashal'Aran gefangen ist, sucht nach dem Relikt, das ihn an diese Welt bindet. Nachdem er das Verderben seines Gefängnisses an den hiesigen Grells spürte, schickt er Reisende aus, um die Satyrn zu jagen, die ihnen befehlen, und das Alte Mondstein-Siegel zu bergen.",h="Asterion, der Geist eines Nachtelfen, der zwischen den verfallenen Säulen von Bashal'Aran gefangen ist, sucht...",kw={"altes mondsteinsiegel","asterion","bashal'aran","dunkelküste","grell","kaldorei","nachtelfengeist","satyr"},ang={["class:Druid"]="Der verdorbene Einfluss der Satyrn verdirbt weiterhin die Tierwelt der Dunkelküste und stört uralte Geister, die friedlich im Kreislauf der Natur ruhen sollten.",["faction:Alliance"]="Die Säuberung der Ruinen der Dunkelküste von der Verderbnis der Satyrn sichert Kalimdors Nordküste und hilft den Kaldorei dabei, ihre tragische Vergangenheit zur Ruhe zu betten.",["race:NightElf"]="Bashal'Aran ist eine düstere Mahnung an die uralte Vergangenheit Eures Volkes, in der verweilende Vorfahren durch Satyrn an die Erde gekettet bleiben, welche den dämonischen Verrat der Zerschlagung verkörpern."},sec={{t="Ein Gefängnis aus uraltem Stein",b="Seit weit über tausend Jahren ist der Geist Asterion an die zerfallenen Ruinen von Bashal'Aran gekettet. Die umstehenden Marmorsäulen dienen als unnachgiebiger Käfig, den weder seine schwindende geistige Kraft noch seine uralte Magie aufzubrechen vermögen. Gebunden durch ein verfluchtes Relikt blickt er seit Jahrhunderten auf das nebelverhangene Blätterdach der Dunkelküste hinaus und fragt sich, ob selbst die Verwitterung des Steins um ihn herum ihm Erlösung bringen würde."},{t="Satyrn und das Mondstein-Siegel",b="Nachdem Asterion entdeckte, dass Grells in der Nähe Spuren der Magie trugen, die seine Gefangenschaft aufrechterhielt, schloss er, dass der Ursprung der Verzauberung in die Hände der Satyrn gefallen war, die jene chaotischen Kreaturen befehligen. Diese dämonischen Nachtelfen streifen durch die uralten Haine und hüten das Alte Mondstein-Siegel mit wachsamer Hand. Die Wiederbeschaffung dieses Talismans ist der entscheidende Schritt, um die unsichtbaren Gitter zu zerschlagen, die Asterion an seinen Schrein binden."}},faq={{q="Wer ist Asterion?",a="Asterion ist ein uralter Nachtelfengeist, der in den Ruinen von Bashal'Aran gefangen ist. Gebunden durch uralte Magie verbringt er seit mehr als tausend Jahren seine Tage zwischen den stehenden Säulen des Schreins, unfähig, hinüberzugehen oder über sein steinernes Gefängnis hinaus zu wandern.",al={"wer ist asterion","asterion lore","geist in bashal aran"}},{q="Warum besitzen die Satyrn das Alte Mondstein-Siegel?",a="Satyrn führen und beeinflussen die wilden Grells, die die nördliche Dunkelküste heimsuchen. Da die Grells Spuren der bindenden Magie an sich trugen, erkannte Asterion, dass ihre boshaften Satyrmeister das Alte Mondstein-Siegel an sich gerissen hatten, um die lokalen Geister gequält und gebunden zu halten.",al={"warum haben satyrn das siegel","satyr mondstein-siegel","altes mondsteinsiegel"}},{q="Was geschieht, sobald das Siegel geborgen ist?",a="Asterion nimmt genau jenes Relikt in Besitz, das ihn seit Jahrhunderten gebunden hat. Die Bergung des Alten Mondstein-Siegels ist der vorletzte Schritt zu seiner Befreiung, wodurch das Siegel gebrochen werden kann, damit er die Wälder endlich wieder frei durchstreifen darf.",al={"was bewirkt das siegel","bergung des siegels"}},{q="Was ist Bashal'Aran?",a="Bashal'Aran ist eine uralte Nachtelfenruine an den nebelverhangenen Küsten der nördlichen Dunkelküste. Einst eine prächtige Siedlung oder heilige Enklave, liegt sie nun in Trümmern und wird von Grells, Satyrn und gefangenen Geistern aus einem früheren Zeitalter heimgesucht.",al={"bashal aran lore","was ist bashal aran"}},{q="Wie lange ist Asterion hier schon gefangen?",a="Asterion ist seit mehr als tausend Jahren eingekerkert. Ohne physische Mittel oder Magie, um die Barriere zu überwinden, war er gezwungen, über die Jahrhunderte hinweg zu warten und sich zu fragen, ob er jemals befreit werden würde.",al={"wie alt ist asterion","wie lange gefangen"}},{q="Kann Asterion den Schrein nicht einfach verlassen?",a="Nein. Das Alte Mondstein-Siegel hält eine metaphysische Barriere um den Schrein aufrecht. Die Steinsäulen wirken wie ein undurchdringlicher Käfig, der seine spektrale Gestalt daran hindert, sie zu überschreiten.",al={"kann asterion gehen","warum geist gefangen"}}},fx={["31aed888"]={q="Warum möchte Asterion, dass das Siegel geborgen wird?",a="Asterion verzweifelt nach Freiheit. Das alte Relikt dient als bindender Anker seines ewigen Gefängnisses und hält seinen Geist im zerstörten Schrein gefangen. Seit über tausend Jahren starrt er an den Steinsäulen vorbei, unfähig, ihren Halt durch Stärke oder Zauberei zu brechen. Die Bergung des Artefakts ist der einzige Weg, es zu zerstören und es ihm endlich zu ermöglichen, wieder frei durch die Wälder zu wandeln.",al={"warum will asterion das erledigt haben","asterion beweggrund","warum asterion helfen"}},["5f1ff286"]={q="Was ist das Alte Mondsteinsiegel?",a="Das Alte Mondsteinsiegel ist ein magisches Relikt, das als Schlüssel zu Asterions Gefangenschaft dient. Es erschafft eine immaterielle Barriere zwischen den Säulen von Bashal'Aran, die wie eine ewige Zelle funktioniert, die kein Zauber oder seine physische Stärke durchbrechen kann. Solange das Siegel in den Händen der nahegelegenen verderbten Kräfte besteht, bleibt Asterion an den Schrein gebunden.",al={"was ist das alte mondsteinsiegel","was bewirkt das mondsteinsiegel","zweck des alten mondsteinsiegels"}},c7650517={q="Warum werdet Ihr gegen die örtlichen Satyrn ausgesandt?",a="Die Satyrn befehligen die abscheulichen Grells, die in den Ruinen von Bashal'Aran wimmeln. Da die niederen Grells Spuren der Verzauberung des Siegels trugen, folgerte Asterion, dass ihre Meister das Artefakt selbst in Besitz genommen haben müssen. Die Satyrn sind verderbt und von alten magischen Relikten angezogen, weshalb sie das Siegel in ihrem Lager halten und zu Eurem Ziel machen.",al={"wer sind die satyrn in bashal'aran","warum die satyrn bekämpfen","wer hat das siegel"}},["341831b6"]={q="Warum kann Asterion das Siegel nicht selbst zurückholen?",a="Asterion kann die Grenzen des Schreins nicht verlassen. Die Magie des Siegels hält ihn völlig innerhalb seines Umkreises gebunden und behandelt die Steinsäulen als unüberwindbare Gitter. Er besitzt weder die Stärke noch die Zauberei, um seine Gefangenschaft zu durchbrechen, was ihn völlig abhängig von einem Außenstehenden macht, der in seinem Namen in die Lager der Satyrn eindringt.",al={"warum braucht asterion mich","warum kann asterion das siegel nicht holen","warum ich für asterion"}}},fp="11,291,25.425.0,29.449.0,16.239.0,50.265.0,40.232.1,20.235.0,40.201.0,46.187.0"}
P.entries["quest:95646"] = {n="Horrors in the Highland",s="Rethiel der Sumpfhüter spürt eine üble Verderbnis, die durch eine Berggully in die ungesalzenen Gewässer oberhalb des Sumpflands sickert. Abenteurer müssen zu den Ausgrabungsstätten aufsteigen, um einen Highland Horror zu erschlagen und seinen Root Core zu bergen. Rethiel entdeckt, dass sich eine uralte Energie regt, und warnt davor, dass die anhaltenden Ausgrabungen die Sicherheit aller in der Region bedrohen.",h="Rethiel der Sumpfhüter spürt eine üble Verderbnis, die durch eine Berggully in die ungesalzenen Gewässer...",kw={"verderbnis","ausgrabungsstätten","highland horror","horrors in the highland","rethiel","rethiel der sumpfhüter","root core","sumpfland"},ang={["class:Druid"]="Rethiel spürt durch seine Wurzeln und die Wasserwege, wie sich das natürliche Gleichgewicht verschiebt; Druiden, die mit dem Land im Einklang sind, werden die plötzliche Verwundbarkeit des Süßwasserlebens gegenüber uralter Verderbnis erkennen.",["faction:Alliance"]="Forscher und Prospectors der Allianz, die Ausgrabungsstätten in den Bergen betreiben, riskieren es, uralte, unter der Erde vergrabene Mächte aufzuschrecken.",["race:Dwarf"]="Zwergische Ausgrabungsstätten im Hochland haben mehr als nur uralte Relikte freigelegt, was Rethiel dazu veranlasst, die Ausgräber zu drängen, ihre Grabungen einzustellen, bevor noch schlimmere Übel erwachen."},sec={{t="Verderbnis in der Berggully",b="Tief im Sumpfland spürt Rethiel der Sumpfhüter eine beunruhigende Veränderung im Land. Eine üble Verderbnis sickert durch eine Berggully und infiziert die Süßwasserkreaturen, die das Hochland darüber bewohnen. Anders als das widerstandsfähige Leben, das durch die brackigen Gewässer des Tieflands geprägt wurde, haben diese Süßwesen das schützende Salz des Meeres nie kennengelernt, was sie gegenüber dem sich ausbreitenden Übel völlig wehrlos macht. Rethiel ruft Abenteurer dazu auf, zu den Ausgrabungsstätten hinaufzuziehen, einen Highland Horror zu erschlagen und seinen Root Core zu bergen."},{t="Ein uraltes Erwachen",b="Als der Root Core des Highland Horrors vor Rethiel gebracht wird, bestätigen sich die Befürchtungen des Hüters: Eine uralte Energie hat begonnen, sich zu regen. Die Heimsuchung, die die Hochlandkreaturen plagt, ist keine gewöhnliche Krankheit, sondern die Folge jüngster Grabungen. Rethiel warnt eindringlich davor, dass die eifrigen Ausgräber, die an den Bergen arbeiten, ihre Grabungen unverzüglich einstellen müssen, bevor ihre unbedachte Neugier etwas weit Schlimmeres auf das Sumpfland loslässt."}},faq={{q="Wer bietet die Quest Horrors in the Highland an?",a="Rethiel der Sumpfhüter, ein uralter Beschützer, der über das Sumpfland wacht, bietet diese Quest an, nachdem er eine üble Verderbnis gespürt hat, die durch eine nahe gelegene Berggully sickert.",al={"wer vergibt horrors in the highland","questgeber horrors in the highland","rethiel quest"}},{q="Wo können Highland Horrors gefunden werden?",a="Highland Horrors hausen innerhalb der Ausgrabungsstätten auf den Anhöhen über dem Tiefland, nahe der Berggully, durch welche die Verderbnis sickert.",al={"wo sind highland horrors","highland horror standort","wo man highland horror findet"}},{q="Warum sind die Hochlandkreaturen so anfällig für Verderbnis?",a="Den Süßwasserkreaturen des Hochlands fehlen die härtende Sole und das Salz des Meeres, die im unteren Sumpfland zu finden sind, was sie zerbrechlich und besonders empfindlich in ihrer Reaktion auf die verderbende Fäulnis macht.",al={"warum die kreaturen verderbt sind","warum hochlandkreaturen verderbt sind","verderbnis ungesalzenes wasser"}},{q="Was ist der Root Core eines Highland Horrors?",a="Der Root Core ist das Herz des verderbten Highland Horrors. Rethiel benötigt ihn, um die unnatürliche Macht zu untersuchen, die sich durch die Wasserwege ausbreitet, und die Natur der Verderbnis zu bestätigen.",al={"was ist der root core","highland horror kern","warum den root core nehmen"}},{q="Was entdeckt Rethiel, wenn Ihr den Root Core zurückbringt?",a="Bei der Untersuchung des Kerns erkennt Rethiel, dass tief im Inneren der Erde eine uralte Energie erwacht ist, wahrscheinlich aufgeschreckt durch rücksichtslose Grabungen an den Ausgrabungsstätten.",al={"was rethiel entdeckt","uralte energie sumpfland","ausgrabungsgefahr"}},{q="Warum möchte Rethiel, dass die Ausgräber aufhören zu graben?",a="Rethiel warnt davor, dass die eifrigen Ausgräber, die im Hochland arbeiten, ihre Grabungen zu ihrer eigenen Sicherheit unverzüglich einstellen sollten, da ihre Nachforschungen das Risiko bergen, gefährliche uralte Mächte freizusetzen.",al={"aufhören zu graben rethiel","was ausgräber tun sollten","zwergen-ausgrabungsstätte warnung"}}},fp="23,358,18.505.0,19.443.1,45.164.0,36.152.0,60.197.0,43.185.0,57.172.0,53.184.0"}
P.entries["quest:95647"] = {n="Lost in the Thicket Things",s="Eine besorgte Alchemistin bittet Reisende darum, ihren vermissten Ehemann Ardin Grassman aufzuspüren, der verschwand, nachdem er Gerüchten über hoch aufragende, unbekannte Gräser nachgegangen war. Ardins botanische Neugier führte ihn geradewegs zu einer nahe gelegenen Ausgrabungsstätte, an der gefährliche Wildtiere und Angriffe von Spinnen die Arbeiter belagern.",h="Eine besorgte Alchemistin bittet Reisende darum, ihren vermissten Ehemann Ardin Grassman aufzuspüren, der...",kw={"alchemie","ardin","ardin grassman","excavation sites","kräuterkunde","lost in the thicket things","spinnen","ragende gräser"},ang={["class:Druid"]="Druiden, die auf das Gleichgewicht der Wildnis eingestimmt sind, könnten an Ardins natürlicher Gabe zum Aufspüren von Flora sowie an der unnatürlichen Unruhe interessiert sein, welche die Wildtiere nahe den Ausgrabungsstätten aufschreckt.",["profession:Herbalism"]="Ardin Grassman besitzt eine angeborene Gabe, Pflanzen und Kräuter aufzuspüren, und erklimmt oft tückisches Terrain, um seltene Flora für die Alchemie zu sammeln."},sec={{t="Die Berufung eines Sammlers",b="In 'Lost in the Thicket Things' bittet eine Alchemistin um Hilfe bei der Suche nach ihrem vermissten Ehemann Ardin Grassman. Ardin besitzt eine verblüffende, instinktive Naturverbundenheit und trotzt regelmäßig steilen Klippen sowie entlegener Wildnis, um seltene Kräuter und botanische Proben für ihre Alchemievorräte zu sammeln. Als eine vorbeiziehende Ausgrabungsmannschaft von bizarren, hoch aufragenden Gräsern berichtete, wie man sie noch nie zuvor gesehen hatte, übermannte Ardin die Neugier, und er brach auf, um die Flora selbst in Augenschein zu nehmen."},{t="Hinterhalt an der Ausgrabungsstätte",b="Ardin folgte der Expedition zu ihrer Ausgrabungsstätte, nur um geradewegs in Gefahr zu geraten. Etwas in den umliegenden Landen versetzte die einheimische Fauna in Aufruhr, was dazu führte, dass aggressive Wildtiere – vor allem Schwärme feindseliger Spinnen – zuschlugen und das Ausgrabungsteam überrannten. Von den herandrängenden Bestien eingeschlossen, sahen sich Ardin und die Mannschaft belagert, bis Reisende eingriffen, um den gestrandeten Botaniker zu retten."}},faq={{q="Wer ist Ardin Grassman?",a="Ardin Grassman ist ein Sammler mit einer seltenen natürlichen Gabe dafür, Pflanzen und Kräuter aufzuspüren. Er durchstreift regelmäßig Klippen und Gipfel, um seine Frau mit wilder Flora für ihr Alchemiehandwerk zu versorgen, doch seine Neugier auf seltsame, hoch aufragende Gräser lockte ihn fort zu einer Ausgrabungsstätte.",al={"wer ist ardin","ardin grassman lore","wer ist ardin grassman"}},{q="Warum wanderte Ardin in die Wildnis hinaus?",a="Ardin hörte mit, wie eine Ausgrabungsmannschaft riesige, hoch aufragende Gräser beschrieb, wie sie ihnen noch nie zuvor begegnet waren. Getrieben von seiner Vorliebe für ungewöhnliche Pflanzen und Flora wagte er sich hinaus, um die sonderbare Vegetation mit eigenen Augen zu sehen, und kehrte nicht mehr nach Hause zurück.",al={"warum ist ardin gegangen","warum wird ardin vermisst","wonach suchte ardin"}},{q="Wohin ist Ardin gegangen?",a="Ardin begab sich in Richtung der nahe gelegenen Excavation Sites, nachdem er Berichte einer vorbeiziehenden Expeditionsmannschaft gehört hatte. Reisende, die nach ihm suchen, müssen die Ausgrabungsstätten durchkämmen, an denen das Team seine Arbeiten aufgenommen hat.",al={"wo ist ardin","ardin aufenthaltsort","wo man ardin grassman findet"}},{q="Was geschah mit Ardin an der Ausgrabungsstätte?",a="Ardin fand das Ausgrabungslager überrannt vor, als die örtlichen Wildtiere unruhig und aggressiv wurden. Riesenspinnen und andere aufgeschreckte Bestien überfielen die Expedition und schnitten Ardin sowie der Mannschaft den Rückweg ab, bis Hilfe von außen eintraf.",al={"was geschah mit ardin","ist ardin tot","was griff ardin an"}},{q="Wer sucht nach Ardin?",a="Die Suche beginnt bei Ardins Frau, einer Alchemistin, die auf seine Kräutersammelzüge angewiesen ist, um ihre Regale zu füllen. Als er von der Nachforschung über die Gerüchte um seltsames Gras nicht zurückkehrte, wandte sie sich an fähige Reisende, um ihn zurückzuholen.",al={"wer vergibt lost in the thicket things","wer startete diese quest","ardins ehefrau"}},{q="Warum griffen die Wildtiere die Ausgrabungsmannschaft an?",a="Die Wildtiere rund um die Ausgrabungsstätten gerieten plötzlich und heftig in Aufruhr, wenngleich die genaue Ursache für ihre Verstörung ungewiss bleibt. Die Unruhe trieb aggressive Kreaturen, insbesondere Spinnen, dazu, in Schwärmen über das Ausgrabungsteam herzufallen und es zu überwältigen.",al={"warum spinnen angreifen","was die tiere verärgerte","warum bestien wütend sind"}}},fp="26,298,19.490.0,22.401.1,22.269.0,39.259.0,19.190.0,46.221.0,25.237.0,48.253.0"}
P.entries["quest:957"] = {n="Bashal'Aran",s="Diese Quest beauftragt Abenteurer damit, dem gefangenen Geist von Asterion in den Ruinen von Bashal'Aran beizustehen. Indem sie sein bindendes Siegel nach Süden zu den Schwesterruinen von Ameth'Aran tragen, suchen Abenteurer nach einem Weg, seine uralten Fesseln zu zerbrechen.",h="Diese Quest beauftragt Abenteurer damit, dem gefangenen Geist von Asterion in den Ruinen von Bashal'Aran...",kw={"ameth'aran","asterion","athrikus","azshara","bashal'aran","dunkelküste","hochgeborene","mondsteinsiegel"},ang={["class:Mage"]="Die dauerhaften Verzauberungen, die Asterion binden, und die überdauernden Flammen von Ameth'Aran bieten einen Einblick in die rohe arkane Macht, die von uralten Hexenmeistern der Hochgeborenen geführt wurde.",["faction:Alliance"]="Das Beseitigen der uralten Flüche an der Dunkelküste sichert die Grenzen für neue Siedlungen der Nachtelfen, die von Auberdine aus vordringen.",["race:NightElf"]="Für die Nachtelfen des modernen Kalimdor ist die Befreiung Asterions eine ernüchternde Begegnung mit der Vergangenheit ihres Volkes vor der Zerschlagung und dem fortwirkenden Verderben des Adels der Hochgeborenen von Königin Azshara."},sec={{t="Ein Kerker uralter Zauberei",b="Der Geist Asterion verweilt seit Jahrtausenden in Bashal'Aran, im Tode angekettet durch ein Altes Mondsteinsiegel. Geschmiedet durch die mächtigen Zaubereien der Kaste der Hochgeborenen vor der Großen Zerschlagung, kann das Siegel nicht durch profane Stärke zerbrochen werden. Seine Zerstörung erfordert die spezifische Magie einer uralten Flamme, die noch immer inmitten des eingefallenen Mauerwerks von Ameth'Aran im Süden schwelt."},{t="Zwillingsruinen der Dunkelküste",b="Bashal'Aran und Ameth'Aran waren einst blühende Schwestersiedlungen der Zivilisation der Kaldorei, zu jener Zeit, als Königin Azshara herrschte und der Brunnen der Ewigkeit noch ihr Reich verankerte. Heute sind beide Stätten überwucherte, heimgesuchte Ruinen voller verweilender Geister und unbeständiger arkaner Energien. In einem steinernen Pavillon in Ameth'Aran bietet eine mystische Feuerschale mit einem cyanfarbenen Feuer die einzige Macht, die Asterions bindendes Relikt verzehren kann."},{t="Die Rache erwacht",b="Nachdem das Siegel zerstört ist, ist Asterion endlich entlastet und blickt auf ein zerschlagenes Kalimdor, das sich gegenüber dem goldenen Zeitalter seiner Erinnerung grundlegend gewandelt hat. Doch seine Freiheit bringt ihm keinen Frieden. Als er spürt, dass sein einstiger Meister und Kerkermeister, der Hochgeborene Athrikus, noch immer fortbesteht, wandelt sich Asterions uralte Verzweiflung rasch in einen kalten, brennenden Hunger nach Rache."}},faq={{q="Wer ist Asterion?",a="Asterion ist ein Nachtelfengeist, der in den Ruinen von Bashal'Aran gefangen ist. Seine Geschichte reicht zehntausend Jahre bis in die Herrschaft von Königin Azshara zurück, und er ist durch ein Siegel an die Ruinen gebunden, das von einem der mächtigsten der Hochgeborenen gefertigt wurde.",al={"asterion","wer ist der geist","nsc asterion"}},{q="Wo zerstöre ich das Alte Mondsteinsiegel?",a="Das Siegel muss nach Süden nach Ameth'Aran gebracht werden, der Zwillingsruine von Bashal'Aran. Haltet Ausschau nach einem steinernen Pavillon, der eine große kubische Feuerschale beherbergt, in der ein uraltes, grünlich-blaues magisches Feuer brennt.",al={"wo ist die flamme","standort der uralten flamme","siegel zerstoeren"}},{q="In welcher Beziehung stehen Bashal'Aran und Ameth'Aran zueinander?",a="Sie waren Schwesterstädte des uralten Nachtelfenreiches vor der Zerschlagung. Beide fielen vor zehntausend Jahren der Verwüstung anheim und hinterließen heimgesuchte Steinsäulen, arkane Restenergien und rastlose Geister.",al={"zwillingsruinen","verbindung zu ametharan","bashalaran ametharan"}},{q="Wer kerkerte Asterion ein?",a="Asterion berichtet, dass einer der mächtigsten Hochgeborenen das Siegel schuf, das ihn bindet. Mehr über seinen einstigen Meister wird im Verlauf der Questreihe enthüllt.",al={"wer kerkerte asterion ein","wer ist athrikus","meister von asterion"}},{q="An welches Zeitalter erinnert sich Asterion?",a="Asterion wandelte zuletzt auf der Welt, als der ursprüngliche Brunnen der Ewigkeit noch existierte, Königin Azshara das Reich regierte und der Adel der Hochgeborenen vor der Zerschlagung seine majestätischen Höfe abhielt.",al={"vergangenheit von asterion","aera des brunnens der ewigkeit","wie alt ist asterion"}},{q="Findet Asterions Geist durch seine Befreiung Ruhe?",a="Die Zerstörung des Siegels soll Asterions Gefängnis aufheben. Seine Reaktion auf die Freiheit offenbart sich, wenn Ihr zu ihm zurückkehrt.",al={"findet asterion frieden","was geschieht mit asterion","asterion nach der befreiung"}}},fx={["8275c861"]={q="Warum möchte Asterion, dass das Alte Mondsteinsiegel zerstört wird?",a="Das Alte Mondsteinsiegel ist der Anker, der Asterions Geist in den Ruinen von Bashal'Aran in Qualen bindet. Vor Jahrtausenden durch mächtige Hochgeborenen-Zauberei erschaffen, hält es ihn gefangen und blind für die Welt da draußen. Es im mystischen alten Feuer von Ameth'Aran zu zerstören, ist der einzige Weg, seine ätherischen Ketten zu sprengen, was ihm Freiheit und die Klarheit gewährt, zu sehen, was aus Kalimdor geworden ist.",al={"warum mondsteinsiegel zerstören","asterion beweggrund","warum will asterion das siegel brechen"}},["51df5ddd"]={q="Warum benötigt Asterion Euch, um das Siegel nach Ameth'Aran zu bringen?",a="Gebunden durch die alte Hochgeborenen-Magie, die ihn an Bashal'Aran verankert, kann Asterion die unmittelbaren Ruinen nicht verlassen, geschweige denn nach Süden nach Ameth'Aran reisen. Er benötigt einen Reisenden, der das Siegel in das alte Feuer trägt.",al={"warum kann asterion das siegel nicht selbst zerstören","warum braucht asterion mich","warum einen abenteurer zur zerstörung des siegels schicken"}}},fp="11,224,27.384.0,23.435.0,17.344.1,16.225.0,46.188.0,60.212.0,24.144.1,32.188.0,45.116.1"}
P.entries["quest:95772"] = {n="Songblade Search",s="Songblade Search ist eine Besorgung der Zwerge, bei der Dorin Songblade Reisende bittet, im Sumpfland nach seinem Bruder Daewyn zu sehen. Daewyn brach mit einer archäologischen Mannschaft von Loch Modan auf, um in unerforschten Hügeln zu graben, doch sein ungewöhnliches Schweigen ließ seinen Bruder das Schlimmste befürchten.",h="Songblade Search ist eine Besorgung der Zwerge, bei der Dorin Songblade Reisende bittet, im Sumpfland nach...",kw={"daewyn songblade","dls","dorin songblade","loch modan","songblade search","sumpfland","whelgars ausgrabungsstätte"},ang={["faction:Alliance"]="Reisende der Allianz, die zwischen Loch Modan und dem Hafen von Menethil unterwegs sind, passieren oft die Ausgrabungsstätten und stehen gestrandeten zwergischen Prospektoren sowie Handwerkern bei.",["race:Dwarf"]="Zwergische Expeditionstrupps und archäologische Ausgrabungen sind in ganz Khaz Modan verbreitet, doch sich jenseits der Sicherheit von Loch Modan in das gefährliche Sumpfland zu wagen, birgt für Verwandte oft schwere Risiken."},sec={{t="Die Unruhe eines Bruders",b="Dorin Songblade blieb in seiner Werkstatt zurück, überhäuft mit Aufträgen zum Ändern von Gürteln, während sich sein Bruder Daewyn einem zwergischen Ausgrabungstrupp anschloss, der von Loch Modan aus aufbrach. Daewyn wagte sich nach Norden in die schroffen Hügel des Sumpflands, begierig darauf, unberührten Boden zu erkunden, den noch keine zwergische Spitzhacke berührt hatte. Daewyn schickt jedoch für gewöhnlich sofort nach seiner Ankunft Briefe, und sein Schweigen beunruhigte Dorin zutiefst."},{t="Die Ausgrabung im Sumpfland",b="Reisende, die ins Sumpfland reisen, können Daewyn Songblade unter den Ausgräbern an Whelgars Ausgrabungsstätte ausfindig machen. Daewyn sieht seinem Bruder Dorin sehr ähnlich und trägt eine markante Flinte mit den in den Holzschaft eingeritzten Initialen „DLS“, was beweist, dass er das abgelegene Ausgrabungslager in den Marschen tatsächlich erreicht hat."}},faq={{q="Wer vergibt die Quest Songblade Search?",a="Dorin Songblade vergibt die Quest. Er ist ein Handwerker, der derzeit mit der Anpassung eines Stapels Gürtel überlastet ist, was ihn davon abhielt, seinen Bruder auf einer archäologischen Ausgrabung zu begleiten.",al={"wer vergibt songblade search","songblade search questgeber","dorin songblade"}},{q="Wer ist Daewyn Songblade?",a="Daewyn Songblade ist der Bruder von Dorin Songblade. Er brach zusammen mit einem Ausgrabungstrupp aus Loch Modan in Richtung der ungezähmten Hügel des Sumpflands auf, versäumte es jedoch, wie sonst üblich eine Nachricht zu schicken.",al={"wer ist dorins bruder","vermisster songblade-zwerg","daewyn songblade"}},{q="Wo kann Daewyn gefunden werden?",a="Daewyn befindet sich bei Whelgars Ausgrabungsstätte im Sumpfland. Man erkennt ihn an seiner starken familiären Ähnlichkeit mit Dorin und seiner Schusswaffe, in deren Holzschaft „DLS“ eingeschnitzt ist.",al={"wo ist daewyn","wo man daewyn songblade findet","songblade search ort"}},{q="Warum reiste Daewyn ins Sumpfland?",a="Daewyn schloss sich einer zwergischen Grabungsexpedition aus Loch Modan an, die unerforschte Hügel im Sumpfland suchte, um eine archäologische Ausgrabung durchzuführen.",al={"warum reiste daewyn ins sumpfland","zweck von whelgars ausgrabung","warum die zwerge ins sumpfland gingen"}},{q="Was bedeuten die in die Waffe eingeschnitzten Initialen?",a="Die in den Schaft der Schusswaffe eingeschnitzten Initialen „DLS“ gehören Daewyn Songblade und bestätigen, dass der an der Ausgrabungsstätte gefundene Zwerg tatsächlich Dorins vermisster Bruder ist.",al={"wofür dls steht","dls gewehreinschnitzung","dls-initialen"}},{q="Warum machte sich Dorin Sorgen um seinen Bruder?",a="Dorin wurde besorgt, da Daewyn normalerweise kurz nach Antritt einer Reise Antwort schreibt. Da er nach dem Aufbruch ins Sumpfland keine Briefe erhalten hatte, verspürte Dorin die ungute Vorahnung, dass etwas schiefgelaufen sei.",al={"warum dorin besorgt ist","warum nach daewyn suchen","songblade search grund"}}},fp="16,280,18.413.0,23.320.1,37.181.0,24.201.0,26.191.0,38.141.0,44.161.0,40.228.0"}
P.entries["quest:95795"] = {n="Fallen in the Fen",s="Fallen in the Fen ist eine düstere Reise, die mit der Entdeckung eines gefallenen Zwergs inmitten einer Ausgrabungsstätte beginnt. Das Überbringen der tragischen Nachricht an seinen Bruder, Dorin Songblade in Seenhain, bringt einem untröstlichen Handwerker Gewissheit, der Geschenke für seinen verstorbenen Verwandten geschmiedet hatte.",h="Fallen in the Fen ist eine düstere Reise, die mit der Entdeckung eines gefallenen Zwergs inmitten einer...",kw={"schmied","dorin","dorin songblade","zwerg","ausgrabung","ausgrabungsstätten","fallen in the fen","seenhain","songblade"},ang={["faction:Alliance"]="Einem Handwerker im Rotkammgebirge Gewissheit zu verschaffen, spendet einem trauernden Stadtbewohner in unruhigen Zeiten für das Königreich Trost.",["profession:Blacksmithing"]="Dorin ließ sein ganzes handwerkliches Können in Rüstgüter einfließen, die als Überraschung für seinen Verwandten gedacht waren – Ausrüstung, die nun nur noch als Mahnmal für das vorzeitige Ableben seines Bruders dient.",["race:Dwarf"]="Zwergensippen verstehen den bitteren Schmerz, einen Bruder an uralte Ausgrabungen und ungezähmte Wildnis zu verlieren, besonders wenn geschmiedetes Metall die Hand überdauert, die es führen sollte."},sec={{t="Tragödie an der Ausgrabung",b="Eine stille Tragödie nimmt an den Ausgrabungsstätten ihren Lauf, wo der leblose Körper eines abenteuerlustigen Zwergs entdeckt wird. Nachdem ein Abenteurer die sterblichen Überreste mit dem eigenen Umhang des Zwergs bedeckt hat, bringt er die finstere Nachricht zurück nach Seenhain, um seine Verwandten ausfindig zu machen."},{t="Die Trauer eines Bruders",b="In Seenhain bricht der Zwergenhandwerker Dorin Songblade zusammen, als er vom Schicksal seines Bruders erfährt. Dorin hatte wochenlang an seiner Schmiede gearbeitet, um eine Überraschungsausrüstung für seinen Bruder herzustellen, die für die Expedition nicht rechtzeitig fertig geworden war. Von Reue geplagt, weil er ihn nicht begleitet hatte, bringt Dorin es weder über das Herz, das mit eigenen Händen Geschaffene umzuschmieden noch zu verkaufen; stattdessen beschließt er, die fertigen Stücke demjenigen zu überlassen, der ihm Gewissheit brachte."}},faq={{q="Was ist Fallen in the Fen?",a="Fallen in the Fen ist eine düstere Aufgabe, die mit der Entdeckung der sterblichen Überreste eines gefallenen Zwergs in einer Ausgrabungsstätte beginnt. Nachdem Ihr den Leichnam mit seinem Umhang bedeckt habt, reist Ihr nach Seenhain, um den trauernden Bruder des Zwergs, Dorin Songblade, persönlich über sein Schicksal zu unterrichten.",al={"was ist fallen in the fen","fallen in the fen quest"}},{q="Wer ist Dorin Songblade?",a="Dorin Songblade ist ein Zwergenschmied, der in Seenhain ansässig ist. Er hatte Ausrüstung als Überraschungsgeschenk für seinen Bruder geschmiedet, bevor er von dessen tragischem Tod an den Ausgrabungsstätten erfuhr.",al={"wer ist dorin songblade","dorin in seenhain","rolle von dorin songblade"}},{q="Wer ist der gefallene Zwerg, der bei der Ausgrabung gefunden wurde?",a="Der gefallene Zwerg, der an den Ausgrabungsstätten entdeckt wurde, war der Bruder von Dorin Songblade. Er war vor Kurzem durch Seenhain gereist, um Vorräte für seine Expedition zu sammeln, bevor er in der Wildnis den Tod fand.",al={"wer starb im morast","toter zwerg ausgrabung","wessen leichnam liegt in der ausgrabung"}},{q="Wo ist Dorin Songblade zu finden?",a="Dorin Songblade ist in Seenhain zu finden, der Hauptsiedlung im Rotkammgebirge, wo er an der Schmiede seinem Handwerk nachgeht.",al={"wo ist dorin songblade","aufenthaltsort von dorin songblade"}},{q="Was schmiedete Dorin für seinen Bruder?",a="Dorin war damit beschäftigt, Ausrüstung zu schmieden, die als Überraschungsgeschenk für seinen Bruder gedacht war. Bedauerlicherweise wurde die Arbeit nicht vor dem Aufbruch seines Bruders zu seiner Expedition fertig, was einen am Boden zerstörten Dorin mit einer Ausrüstung zurücklässt, die er weder behalten noch verkaufen mag.",al={"was dorin schmiedete","überraschungsgeschenk von dorin"}},{q="Warum gibt Dorin die von ihm gefertigten Gegenstände weg?",a="Überwältigt von Kummer und Reue darüber, seinen Bruder nicht begleitet zu haben, verspürt Dorin kein Verlangen danach, die Waffen, für die er sich abgemüht hat, umzuschmieden oder zu verkaufen. Er trennt sich von dem vollendeten Werk aus Dankbarkeit gegenüber dem Reisenden, der ihm Nachricht von seinem Verwandten brachte.",al={"warum dorin die ausrüstung weggab","warum euch dorin ausrüstung schenkt"}}},fp="17,263,18.237.0,17.442.1,26.255.0,23.178.0,48.206.0,35.127.0,39.229.0,46.228.0"}
P.entries["quest:95805"] = {n="Grace of An'she and Mu'sha",s="Grace of An'she and Mu'sha ist eine heilige Pilgerreise der Tauren, die auf der Hochwolkenebene unternommen wird, um Sonne und Mond als himmlische Augen der Erdenmutter zu ehren. Indem sie zerbrechliches, glimmendes Räucherwerk zu einem erhabenen Schrein in den südöstlichen Hügeln tragen, erweisen Reisende den Himmelslichtern Respekt, die den Ebenen Wärme, Leben und Orientierung schenken.",h="Grace of An'she and Mu'sha ist eine heilige Pilgerreise der Tauren, die auf der Hochwolkenebene unternommen...",kw={"an'she","erdenmutter","mond","mu'sha","mulgore","die hochwolkenebene","schrein","glimmendes räucherwerk","sonne","tauren"},ang={["class:Druid"]="Druiden der Tauren betrachten den ewigen Tanz von Sonne und Mond als die ursprüngliche Verkörperung des Gleichgewichts, die ihr Verständnis für die kosmischen Rhythmen der Natur leitet.",["class:Shaman"]="Während Schamanen direkt mit den weltlichen Geistern von Erde, Feuer, Wasser und Luft sprechen, erweisen sie den himmlischen Zwillingen, deren Licht alle lebendige Energie erhält, gleichermaßen Ehrerbietung.",["faction:Horde"]="Die auf der Hochebene vollzogenen heiligen Riten verdeutlichen die tiefe, naturverbundene Kultur, die die nomadischen Tauren ihren Verbündeten innerhalb der Horde darbringen.",["race:Tauren"]="Die Ehrfurcht vor An'she und Mu'sha bildet den Kern der spirituellen Identität der Tauren und erinnert junge Krieger daran, dass das Leben verlangt, die beiden himmlischen Lichter ebenso treu wie die Erdenmutter selbst zu ehren."},sec={{t="Die Augen der Erdenmutter",b="Im Mythos der Tauren sind Sonne und Mond als An'she und Mu'sha bekannt, die als Zwillingsaugen der Erdenmutter verehrt werden. Während die Elementargeister unmittelbar in den Steinen, Winden und Wassern von Azeroth verweilen, wachen diese himmlischen Zwillinge von den Höhen des Himmels über die Welt. Ihre stete Reise über das Firmament bestimmt den ewigen Rhythmus von Tag und Nacht und schenkt allen lebenden Kreaturen Wärme, Führung und Hoffnung. Die Zwillinge zu ehren ist eine wesentliche spirituelle Pflicht, die lehrt, dass das Gleichgewicht nicht nur Ehrfurcht vor dem Land unter Euren Füßen verlangt, sondern auch vor dem Licht, das vom Himmel herabscheint."},{t="Eine Opfergabe auf den Höhen",b="Um die himmlischen Zwillinge zu ehren, muss ein Pilger glimmendes Räucherwerk in die südöstlichen Hügel tragen, die die Hochebene überblicken und sich direkt südlich der stacheligen Borstennackengebiete befinden. Die Reise ist eine Übung in Achtsamkeit und Schnelligkeit: Die duftende Glut muss überbracht werden, ehe sie zu kalter Asche verglimmt, und Reisende müssen darauf achten, sie entlang des Pfades vor Wasser zu bewahren. Nach Erreichen des erhabenen Schreins wirft der Pilger die Glut in das Sacred Fire und lässt den aromatischen Rauch seinen Respekt hinauf in den Himmel zu Sonne und Mond tragen."}},faq={{q="Wer sind An'she und Mu'sha?",a="An'she und Mu'sha sind Sonne und Mond in der Mythologie der Tauren, die als Zwillingsaugen der Erdenmutter verehrt werden. Anders als die Geister von Erde, Luft, Feuer und Wasser verweilen sie nicht unmittelbar im Boden von Azeroth. Stattdessen erleuchten sie die Welt vom Firmament droben, wobei An'she Wärme und Leben schenkt, während Mu'sha nächtliche Führung und Trost spendet.",al={"wer sind anshe und musha","anshe und musha lore","tauren sonnen- und mondgötter"}},{q="Warum bringen die Tauren Sonne und Mond Opfergaben dar?",a="Die Philosophie der Tauren lehrt, dass das Gleichgewicht für alles Dasein unerlässlich ist. Während irdische Geister die unmittelbare Landschaft beherrschen, verleiht das Licht von An'she und Mu'sha allen lebenden Kreaturen Lebenskraft, Weitsicht und Hoffnung. Das Darbringen von glimmendem Räucherwerk an hohen Orten ist ein Akt gegenseitigen Respekts, der anerkennt, dass sterbliches Leben ohne das stetige Wohlwollen beider Himmelskörper nicht gedeihen kann.",al={"warum sonne und mond verehren","himmlische verehrung der tauren","warum anshe und musha ehren"}},{q="Wo befindet sich der Schrein von An'she und Mu'sha?",a="Der Schrein von An'she und Mu'sha liegt in den hohen Hügeln südöstlich der Hochebene. Er überblickt die weiten Ebenen darunter und befindet sich direkt südlich der dornigen Gebiete der Borstennacken. Seine hohe Lage bietet eine freie, ungehinderte Sicht auf das offene Firmament, was ihn zu einem idealen Ort macht, um Rauch gen Himmel steigen zu lassen.",al={"wo ist der anshe-schrein","schreinposition mulgore","wie man den räucherwerkschrein findet"}},{q="Welche Bedeutung hat das glimmende Räucherwerk?",a="Das glimmende Räucherwerk dient als physischer Mittler für Gebet und Ehrerbietung. Während seine duftende Glut brennt, trägt der aufsteigende Rauch die Hingabe des Reisenden geradewegs hinauf in den Himmel zu Sonne und Mond. Das Werfen der Glut in das Schreinfeuer schließt das Ritual ab und belohnt den Pilger mit einem friedvollen Gefühl spiritueller Erfüllung.",al={"was bewirkt das räucherwerk","bedeutung des räucherwerkopfers","warum glimmendes räucherwerk verbrennen"}},{q="Warum muss das Räucherwerk schnell überbracht und trocken gehalten werden?",a="Das Ritual verlangt dem Pilger Wachsamkeit, Schnelligkeit und Sorgfalt ab. Das Räucherwerk muss noch glimmen, wenn es am Schrein in das Sacred Fire geworfen wird, was bedeutet, dass die Reise vollendet sein muss, ehe die Glut zu kalter Asche erlischt. Zudem löscht der Kontakt mit Wasser die Glut unverzüglich, wodurch die Opfergabe verdirbt, noch bevor sie die Höhen erreichen kann.",al={"warum ist das räucherwerk zeitlich begrenzt","nicht nass werden lassen","räucherwerk brennt nieder"}},{q="Bedrohen die Borstennacken die Pilgerreise zum Schrein?",a="Borstennackenstämme besetzen schwer verteidigte Dornenbauten in den Hügeln direkt nördlich des Schreins. Während der Schrein selbst an einem ruhigen Aussichtspunkt südlich ihrer Gebiete liegt, müssen Reisende auf der Hut sein, nicht in das Dornengestrüpp der Borstennacken zu geraten, da feindselige Angriffe die heikle Reise leicht verzögern oder vereiteln könnten.",al={"borstennacken nahe dem schrein","sind borstennacken eine bedrohung für pilger","borstennacken südlich der hochebene"}},{q="Wie steht Mu'sha im Vergleich zu den Mondansichten anderer Kulturen?",a="Der Mythos der Tauren sieht im Mond Mu'sha, das liebende linke Auge der Erdenmutter, das auf das sterbliche Leben herabblickt. Andere Völker auf Azeroth, allen voran die Nachtelfen, verehren denselben leuchtend weißen Mond als die Göttin Elune, doch die Tradition der Tauren betrachtet sie als untrennbar mit ihrem solaren Zwilling An'she verbunden.",al={"ist musha elune","taurenmond im vergleich zu elune","musha und die nachtelfen"}}},fp="26,342,27.602.0,26.548.0,26.366.0,53.398.0,49.314.0,51.336.0,55.353.0,54.310.0,61.306.0"}
P.entries["quest:95809"] = {n="Heartwoven",s="Heartwoven ist eine Quest der Allianz im Sumpfland, bei der sich alles um eine einfache Botschaft des Überlebens und der Zuneigung dreht. Nachdem sie einem gestrandeten Sammler in den Marschen einen Fluchtweg freigekämpft haben, bringen Abenteurer ein handgeflochtenes Schilfherz zurück zu Caitlin Grassman im Hafen von Menethil.",h="Heartwoven ist eine Quest der Allianz im Sumpfland, bei der sich alles um eine einfache Botschaft des...",kw={"caitlin grassman","grassman","heartwoven","hafen von menethil","schilfherz","schilfrohr","sumpfland"},ang={["faction:Alliance"]="Der Hafen von Menethil dient als wichtiger Hafen der Allianz im Sumpfland, wo einfache Zivilisten darauf angewiesen sind, dass Reisende die gefährlichen Marschwege sicher halten.",["profession:Cooking"]="Nachdem Caitlin das Schilfherz erhalten und erfahren hat, dass ihr Partner überlebt hat, macht sie sich sogleich daran, eine warme, herzhafte Mahlzeit zuzubereiten, um ihn daheim willkommen zu heißen."},sec={{t="Ein Signal aus den Marschen",b="Draußen in den tückischen Marschen des Sumpflands bringen Leben und Arbeit ständige Gefahren mit sich. Ardin Grassman, der loszog, um die seltsamen Gräser an den Ausgrabungsstätten zu sehen, saß inmitten der Gefahren des Sumpfes fest, bis ein vorbeikommender Reisender einen Pfad durch die Wildnis freiräumte. Erschöpft, aber entschlossen, hält er inne, um zu Atem zu kommen und seine Ernte zu sichern, bevor er sich wieder auf den Weg in die Sicherheit des Hafens macht."},{t="Zeichen von Menethil",b="Bevor er den Heimweg antritt, nimmt der Sammler Schilfrohr aus seinem Rucksack und flicht daraus ein gewobenes Herz. Er vertraut dieses Zeichen dem Abenteurer an, damit dieser es Caitlin Grassman im Hafen von Menethil überbringt. In der geschäftigen Küstensiedlung wartet Caitlin voller Sorge und drückt das geflochtene Schilfherz erleichtert an ihre Brust, als sie erfährt, dass er überlebt hat und bald zu einer warmen Mahlzeit heimkehren wird."}},faq={{q="Was ist die Quest Heartwoven?",a="Heartwoven ist eine Quest der Allianz im Sumpfland. Ein Abenteurer hilft Ardin Grassman, der an den Ausgrabungsstätten draußen in den Marschen festsitzt und ein geflochtenes Zeichen aus Schilf als Botschaft des Überlebens und der Liebe herstellt, das Caitlin Grassman im Hafen von Menethil überbracht werden soll.",al={"quest heartwoven","was ist heartwoven","sumpfland heartwoven"}},{q="Wer ist Caitlin Grassman?",a="Caitlin Grassman ist eine Bewohnerin der Allianz, die im Hafen von Menethil ängstlich wartet. Sie fürchtet um das Leben ihres Mannes Ardin, der inmitten der Gefahren des Sumpflands zu den Ausgrabungsstätten aufgebrochen war, und ist zutiefst erleichtert, als Ihr ihr die Nachricht von seinem Überleben überbringt.",al={"wer ist caitlin grassman","caitlin hafen von menethil","caitlin grassman"}},{q="Was ist das schilfgeflochtene Herz?",a="Das schilfgeflochtene Herz ist ein handgefertigtes Zeichen, das der gestrandete Sammler aus dem Schilfrohr in seinem Rucksack hergestellt hat. Er flicht es rasch, um als Beweis und Beruhigung zu dienen, dass er am Leben ist und bald nach Hause zurückkehrt.",al={"was ist das schilfherz","aus schilf geflochtenes herz","schilfgeflochtenes herz"}},{q="Wo gibt man Heartwoven ab?",a="Die Quest endet bei Caitlin Grassman, die in der Hafenstadt der Allianz, dem Hafen von Menethil, an der Westküste des Sumpflands wartet.",al={"wo gibt man heartwoven ab","abgabeort von heartwoven","wo ist caitlin grassman"}},{q="Wer gibt Euch die Quest Heartwoven?",a="Die Quest wird von Ardin Grassman angeboten, Caitlins Ehemann, der die Gefahr an den Ausgrabungsstätten draußen im Sumpfland überlebt hat. Nachdem ein Abenteurer einen sicheren Weg für ihn freigeräumt hat, ruht er sich aus, sammelt seine Bündel und schickt den Abenteurer mit einem handgemachten Zeichen für Caitlin voraus.",al={"wer vergibt heartwoven","wer fertigt das herz an","der ueberlebende heartwoven"}},{q="Was geschah mit dem gestrandeten Sammler?",a="Ardin begab sich zu den Ausgrabungsstätten, um seltsame, emporragende Gräser zu sehen, und saß in der Falle, als aufgeschreckte Wildtiere, vor allem Spinnen, das Ausgrabungsteam überwältigten. Dank eines Abenteurers, der einen Pfad durch die umgebenden Bedrohungen freiräumte, überlebte er und war in der Lage, seine Bündel sicher einzusammeln und zum Hafen von Menethil zurückzukehren.",al={"was geschah mit dem sammler","ist er am leben","heartwoven ueberlebender"}}},fp="10,263,25.409.0,18.392.0,29.261.0,24.263.0,29.209.0,32.140.0,35.268.0,39.319.0"}
P.entries["quest:95810"] = {n="Lost Relic Carry",s="Bei Lost Relic Carry geht es darum, ein zerbrochenes Teil eines uralten Felsmech-Automaten zu bergen und es zu Ausgrabungsleiter Whelgar im Sumpfland zu bringen. Das unbekannte Verbundmaterial des Relikts deutet auf die hochentwickelte Ingenieurskunst der Titanen hin und stößt bei zwergischen Forschern auf tiefen Respekt.",h="Bei Lost Relic Carry geht es darum, ein zerbrochenes Teil eines uralten Felsmech-Automaten zu bergen und es...",kw={"automat","ausgrabungsstätte","explorers league","lost relic carry","ausgrabungsleiter whelgar","felsmech","titanenrelikt","sumpfland"},ang={["profession:Engineering"]="Das Verbundmaterial und die komplexe Konstruktion des Felsmech-Automaten deuten auf fortschrittliche mechanische Prinzipien hin, die weit über normale sterbliche Ingenieurskunst hinausgehen.",["race:Dwarf"]="Zwergische Forscher der Explorers' League sind davon besessen, uralte Relikte ihrer Schöpfer auszugraben, was dieses Automatenfragment zu einem geschätzten Fund für das Erbe der Zwerge macht."},sec={{t="Ein Fragment uralter Handwerkskunst",b="Tief in uraltem Gelände können Abenteurer ein zerbrochenes Bauteil eines Felsmech-Automaten freilegen. Weit davon entfernt, einfacher Schutt zu sein, offenbart sein ungewöhnliches Verbundmaterial das handwerkliche Geschick eines hochentwickelten, uralten Mechanismus, der mit den Titanen in Verbindung steht."},{t="Lieferung an die Ausgrabung",b="Ausgrabungsleiter Whelgar, der an der Ausgrabungsstätte im Sumpfland stationiert ist, studiert Überreste aus alter Zeit. Das Relikt aus der Gefahr zu tragen und ihm zu überbringen, liefert zwergischen Gelehrten, die ihrem uralten Erbe nachspüren, wertvolle handfeste Beweise."}},faq={{q="Was ist das Titanenrelikt?",a="Das Relikt ist ein zerbrochenes Teil eines uralten Felsmech-Automaten. Anstatt gewöhnlicher Steintrümmer besteht es aus einem unbekannten Verbundmaterial, das eindeutig als Teil einer komplexen mechanischen Vorrichtung fungierte.",al={"was ist das relikt","was ist der gegenstand","felsmech-teil"}},{q="Wer ist Ausgrabungsleiter Whelgar?",a="Ausgrabungsleiter Whelgar ist ein zwergischer Forscher, der die Ausgrabungsstätte im Sumpfland beaufsichtigt. Er studiert uralte irdene Überreste und Relikte, die an den Ausgrabungsstätten in der gesamten Region freigelegt wurden.",al={"wer ist whelgar","whelgar lore","ausgrabungsleiter"}},{q="Wohin muss das Relikt gebracht werden?",a="Das Relikt wird zu Ausgrabungsleiter Whelgar an seine Ausgrabungsstätte im Sumpfland gebracht, wo zwergische Ausgräber uralte Ruinen untersuchen.",al={"wohin bringe ich es","wo ist die abgabe","whelgar aufenthaltsort"}},{q="Was hat den Felsmech-Automaten erschaffen?",a="Das Automatenfragment wird als Titanenrelikt identifiziert. In den Überlieferungen der Zwerge sind uralte mechanische Konstrukte und Steinautomaten mit den rätselhaften Titanen verknüpft, die die Welt geformt haben.",al={"wer schuf den felsmech","automatenursprung","titanenverbindung"}},{q="Warum begegnet Ausgrabungsleiter Whelgar dem Relikt mit Ehrfurcht?",a="Sich in die Tiefen vorzuwagen, in denen sich diese Automaten befinden, ist äußerst gefährlich. Whelgar bemerkt, dass das Überleben dieses Vorstoßes und die Rückkehr mit einem solchen intakten Stück echten Respekt abverlangt.",al={"warum ist whelgar beeindruckt","gefährlicher vorstoß"}},{q="Was ist ungewöhnlich am Material des Automaten?",a="Das Material ist ein einzigartiger Verbundstoff mit einer unvertrauten Beschaffenheit, anders als typischer Stein oder geschmiedetes Metall, was die hochentwickelte und geheimnisvolle Handwerkskunst uralter Titanenkonstrukte demonstriert.",al={"was ist das material","seltsamer verbundstoff"}}},fp="16,290,27.241.0,26.245.0,24.212.0,26.184.0,42.142.0,37.177.0,59.183.0,47.181.0"}
P.entries["quest:95883"] = {n="The Tortured Soul",s="The Tortured Soul ist eine Quest, die sich um einen hastig errichteten Ritualaltar bei Berens List im Silberwald dreht. Um die dunklen Riten voranzutreiben, die auf einer zurückgelassenen Notiz beschrieben sind, müssen Abenteurer eine von Leid erfüllte Seele aus den gefährlichen Felsen in der Nähe beschaffen.",h="The Tortured Soul ist eine Quest, die sich um einen hastig errichteten Ritualaltar bei Berens List im...",kw={"berens list","üble energie","blutopfer","the offering stone","ritual","silberwald","the tortured soul"},ang={["class:Priest"]="Das Ritual stützt sich auf üble Energie, die leidenden Geistern entrissen wurde, und steht in starkem Gegensatz zu den heilenden Prinzipien des Heiligen Lichts.",["class:Warlock"]="Das Kanalisieren gequälter Seelen und das Abhalten dunkler Riten an uralten Opfersteinen spiegeln die finstere, manipulative Natur von Dämonen- und Shadow Magic wider.",["race:Undead"]="Der Silberwald ist das Territorium der Verlassenen, wo Überreste dunkler Magie und anhaltendes Leiden ständig die Grenzen von Lordaeron bedrohen."},sec={{t="Ein hastiger Ritus",b="Bei Berens List im Silberwald liegt ein Altar mit den Überresten eines hastig vorbereiteten dunklen Rituals. Eine hingekritzelte Notiz inmitten des schmucklosen Durcheinanders besagt, dass die meisten Zutaten bereits gesammelt wurden und nur noch ein Blutopfer und eine Gequälte Seele fehlen, um das Werk zu vollenden."},{t="Entfesselte üble Energien",b="Die Bewohner, die in den Felsen von Berens List hausen, erleiden schwere Qualen, was sie zu idealen Zielen macht, um die für den Ritus benötigte gequälte Essenz zu sammeln. Wenn man die gesammelte Seele dem unheilvollen The Offering Stone darbringt, wird eine Woge übler magischer Energie hervorgerufen, die das Ritual seiner Vollendung näher bringt."}},faq={{q="Was ist The Tortured Soul?",a="The Tortured Soul ist eine Quest, die bei Berens List im Silberwald angesiedelt ist. Sie beinhaltet die Untersuchung eines unvollendeten dunklen Rituals an einem The Offering Stone und die Suche nach der Seele einer gequälten Kreatur in der Nähe, um die Komponenten des Ritus zu vervollständigen.",al={"was ist die quest the tortured soul","gequälte seele silberwald","berens list quest"}},{q="Wo findet dieses Ritual statt?",a="Der Ritualaltar und sein unheilvoller The Offering Stone befinden sich bei Berens List, einer bergigen und gefährlichen Enklave im Silberwald.",al={"wo ist das ritual","wo ist berens list","the offering stone ort"}},{q="Welche Komponenten werden für das Ritual benötigt?",a="Laut einem Notizzettel, der am Altar zurückgelassen wurde, wurden fast alle Materialien hastig zusammengetragen, bis auf zwei lebenswichtige Komponenten: ein Blutopfer und eine Gequälte Seele.",al={"was wird für das ritual benötigt","ritualkomponenten berens list"}},{q="Wo findet Ihr die Gequälte Seele?",a="Der Questtext merkt an, dass die nahe gelegenen Kreaturen, die Berens List bewohnen, gequält genug wirken, um die Essenz zu liefern, die zur Ermächtigung des The Offering Stone benötigt wird.",al={"wo man gequälte seele bekommt","wer hat die seele"}},{q="Was passiert, wenn die Gequälte Seele zum Altar gebracht wird?",a="Bringt man die gequälte Seele zum The Offering Stone, stößt dieser eine üble Energie aus und bringt die dunkle Zeremonie ihrer Vollendung einen Schritt näher.",al={"was passiert wenn man seele bringt","gequälte seele abgeben"}},{q="Wer hat das Ritual bei Berens List erschaffen?",a="Der genaue Schöpfer des Rituals wird nicht genannt, aber Notizen und hastig gesammelte Materialien deuten darauf hin, dass jemand geflohen ist oder den Altar in äußerster Hast inmitten der feindseligen Bewohner von Berens List errichtet hat.",al={"wer hat das ritual erschaffen","wer hat die notiz geschrieben"}}},fp="17,261,12.295.0,23.301.1,26.235.0,34.146.0,44.173.0,36.153.0,60.143.0,40.197.0"}
P.entries["quest:95884"] = {n="The Offering Stone",s="The Offering Stone ist ein Ritualaltar, der in Berens List im Silberwald verborgen liegt. Entdeckt durch Fragmente einer verwitterten Notiz, ist der Stein mit bizarren Werkzeugen und Gegenständen übersät, die für ein unbekanntes Opfer bestimmt sind. Eine Untersuchung der Stätte offenbart aktive Ritualvorbereitungen, die in der schattigen Wildnis stattfinden.",h="The Offering Stone ist ein Ritualaltar, der in Berens List im Silberwald verborgen liegt.",kw={"berens list","werkzeuge","the offering stone","ritual","notizzettel","silberwald"},ang={["class:Warlock"]="Der Anblick eines Opfersteins, der mit finsteren Werkzeugen übersät ist, deutet auf ritualistische Praktiken hin, die eine eingehende Untersuchung durch Ausübende der dunklen Künste rechtfertigen.",["faction:Horde"]="Abenteurer der Verlassenen und der Horde, die den Silberwald sichern, müssen ein wachsames Auge auf verdächtige Rituale und Aktivitäten von Kultisten haben, die in den schattigen Felsen von Berens List verweilen."},sec={{t="Eine Zerfledderte Notiz",b="Ein im Silberwald gefundener verwitterter Zettel spricht von seltsamen Ritualvorbereitungen. Obwohl Zeit und Feuchtigkeit den Großteil der Schrift unleserlich gemacht haben, sind genügend Fragmente erhalten geblieben, um Erwähnungen eines Rituals und eines Opfersteins irgendwo in der Nähe aufzudecken. Reisende, die diesen Hinweisen in die schroffen Felsen von Berens List folgen, können den einfachen, in der Wildnis verborgenen Altar ausfindig machen."},{t="Die Ritualstätte",b="Wenn Ihr The Offering Stone in Berens List findet, offenbart seine raue Oberfläche Spuren jüngster und beunruhigender Aktivitäten. Seltsame Werkzeuge und bizarre Gegenstände liegen über den Felsen verstreut und bestätigen, dass jemand die Stätte aktiv genutzt hat, um fernab neugieriger Blicke ein Opfer oder einen finsteren Ritus zu vollziehen."}},faq={{q="Was ist The Offering Stone?",a="The Offering Stone ist ein verwitterter Steinaltar, der sich in Berens List im Silberwald befindet. Er scheint als Mittelpunkt für mysteriöse Vorbereitungen und finstere Rituale zu dienen, übersät mit bizarren Werkzeugen und Ritualgegenständen.",al={"was ist the offering stone","the offering stone silberwald","was ist dieser stein"}},{q="Wo ist The Offering Stone zu finden?",a="The Offering Stone befindet sich in Berens List, einem gebirgigen und gefährlichen Gebiet im südlichen Silberwald.",al={"wo ist the offering stone","the offering stone fundort","the offering stone finden"}},{q="Wer hat The Offering Stone geschaffen oder nutzt ihn?",a="Die in der Nähe gefundene beschädigte Notiz lässt die Identität der Ritualisten im Dunkeln, doch die auf dem Stein zurückgelassenen Werkzeuge und Gegenstände weisen darauf hin, dass jemand in diesem Gebiet aktiv ein Opfer oder einen finsteren Ritus vorbereitete.",al={"wer schuf the offering stone","wer nutzt the offering stone","wer führt das ritual durch"}},{q="Was besagt die mysteriöse Notiz?",a="Der Notizzettel ist größtenteils verwittert und unleserlich, doch lesbare Fragmente beschreiben eindeutig Vorbereitungen für ein bevorstehendes Ritual und weisen auf die Gegenwart eines Opfersteins in der Nähe hin.",al={"welche notiz","notizzettel silberwald","was steht auf der notiz"}},{q="Was befindet sich auf The Offering Stone?",a="Die raue Oberfläche des Steins ist mit seltsamen Werkzeugen, Ritualgerätschaften und diversen Gegenständen übersät, die für ein Opfer hergerichtet wurden.",al={"welche gegenstände liegen auf dem stein","welche werkzeuge auf stein","the offering stone gegenstände"}},{q="Welche Art von Ritual wird hier durchgeführt?",a="Während die genaue Natur des Ritus in den erhaltenen Fragmenten der Notiz nicht vollständig beschrieben wird, ist der Stein eigens als Altar hergerichtet, auf dem Gegenstände oder Opfergaben für ein Ritual ausgelegt werden.",al={"welches ritual the offering stone","warum the offering stone","welches opfer silberwald"}}},fp="18,321,15.390.0,15.301.0,27.231.0,38.123.0,39.200.0,34.180.0,36.131.0,44.196.0"}
P.entries["quest:95885"] = {n="The Offering of Blood",s="The Offering of Blood ist ein mysteriöses Ritual, das am The Offering Stone in Berens List durchgeführt wird. Mithilfe einer Gequälten Seele bringen Abenteurer am Stein ein Blutopfer dar, wie es der Zettelfetzen verlangte.",h="The Offering of Blood ist ein mysteriöses Ritual, das am The Offering Stone in Berens List durchgeführt wird.",kw={"berens list","blutritual","the offering of blood","the offering stone","opfer","silberwald","gequälte seele"},ang={["class:Priest"]="Priester, die sich um das Schicksal geschiedener Geister sorgen, werden die Verwendung einer gequälten Seele in einem unheilvollen Blutritual als moralisch beunruhigend empfinden, ungeachtet dessen, ob es das Wesen zur Ruhe bettet.",["class:Warlock"]="Hexenmeister sind mit finsteren Riten und dem Feilschen um Seelen bestens vertraut, doch selbst erfahrene Anwender der Teufelsmagie könnten einen Schauer verspüren, wenn sie ein Blutopfer an einem uralten, unbekannten Stein darbringen."},sec={{t="Der letzte Ritus",b="Tief in den zerklüfteten Felsen von Berens List liegt The Offering Stone, ein unheilvolles Relikt, das auf einen letzten, finsteren Handel wartet. Den Hinweisen weggeworfener Notizfetzen folgend, die nach einem bereitwilligen Opfer verlangen, werden Abenteurer dazu geleitet, das Blutopfer darzubringen, das nötig ist, um die verbliebene Magie des Altars zufriedenzustellen. Sich dem Stein mit der rastlosen Essenz zu nähern, ruft ein überwältigendes Gefühl des Grauens hervor."},{t="Das Zerbrechen des Steins",b="Die Darbringung der Gequälten Seele an den Stein löst eine tiefgreifende Reaktion aus, die die verbliebene Macht aus dem uralten Monument saugt. Anstatt einen noch größeren Schrecken zu erwecken, erschöpft das Blutritual das Relikt vollständig. Seiner arkanen Bestimmung beraubt, bricht der grobe Stein und stürzt zu Trümmern ein, wobei eine glitzernde Belohnung zum Vorschein kommt, die in den zersplitterten Fragmenten begraben lag."}},faq={{q="Wo findet dieses Ritual statt?",a="The Offering of Blood findet am The Offering Stone statt, der sich in Berens List im Silberwald befindet. Das Gebiet ist voller Gefahren und wird von dunkler, anhaltender Magie überschattet.",al={"wo ist diese quest","wo ist the offering of blood","berens list quest"}},{q="Was ist The Offering Stone?",a="The Offering Stone ist ein mysteriöses uraltes Monument in Berens List. Es verlangt nach einem finsteren Ritual – genauer gesagt nach einem Blutopfer von einem bereitwilligen Opfer –, um die in ihm schlummernde Macht freizusetzen oder aufzuzehren.",al={"was ist the offering stone","the offering stone berens list","altar in berens list"}},{q="Wofür wird die Gequälte Seele verwendet?",a="Das Ritual erfordert eine Gequälte Seele, die als das in geborgenen Notizfetzen erwähnte „bereitwillige Opfer“ dient. Die Seele wird am The Offering Stone dargebracht, um das von dem uralten Relikt verlangte Blutopfer zu erfüllen.",al={"wer ist die gequälte seele","was ist gequälte seele","welches opfer wird benötigt"}},{q="Was geschieht, wenn die Opferung vollendet ist?",a="Nach Vollendung des Rituals ist die dunkle Energie, die The Offering Stone belebte, vollständig aufgebraucht. Seines Zwecks beraubt, zerbricht der grobe Stein und zerfällt, wobei etwas Glitzerndes zwischen seinen Überresten zurückbleibt.",al={"was geschieht mit dem stein","zerbricht der stein","was passiert nach dem ritual"}},{q="Wer erschuf den Stein und warum?",a="Der genaue Ursprung und der letztendliche Zweck des Steins bleiben ein Rätsel. Obwohl der erfolgreiche Abschluss des Ritus die latente Energie des Steins aufzehrt und ihn zerstört, bleibt unbekannt, wer das Monument ursprünglich erschuf und zu welchem großen Zweck.",al={"wer baute the offering stone","zweck von the offering of blood","warum wurde der stein erschaffen"}},{q="Was ist Berens List?",a="Berens List ist ein felsiger Orientierungspunkt im Silberwald, der für wilde Bestien und verborgene Gefahren bekannt ist. Die Anwesenheit des The Offering Stone offenbart, dass finstere Riten und rastlose Seelen ebenfalls ihre Spuren an diesem Ort hinterlassen haben.",al={"was ist berens list","berens list lore","warum heisst es berens list"}}},fp="21,202,14.388.0,18.371.1,34.176.0,27.217.0,35.211.0,44.213.0,30.244.0,22.216.0"}
P.entries["quest:959"] = {n="Ärger auf den Docks",s="Kranführer Moppelfuzz verursachte an den Docks von Ratschet ein Missgeschick mit der Fracht, wodurch ein kleiner Unruhestifter namens Mad Magglish eine unbezahlbare Vintage-Flasche entwenden konnte. Der Jahrgang – ein 99 Jahre alter Portwein, der direkt von Baron Revilgaz an Gazlowe geschickt wurde – muss aus den Schatten der Höhlen des Wehklagens geborgen werden, bevor der Hafenmeister den nachlässigen Kranführer entlässt.",h="Kranführer Moppelfuzz verursachte an den Docks von Ratschet ein Missgeschick mit der Fracht, wodurch ein...",kw={"bigglefuzz","beutebucht","gazlowe","magglish","portwein","ratschet","revilgaz","die höhlen des wehklagens"},ang={["class:Rogue"]="Die Jagd nach Mad Magglish ist eine Übung im Entdecken nachlässiger Verstecke, da sich der Dieb auf unausgereifte Verstohlenheit in den Höhlennischen verlässt, um unentdeckt zu bleiben.",["faction:Alliance"]="Obwohl man tief im Horde-dominierten Brachland agiert, sichert ein gutes Verhältnis zu den Hafenbetreibern von Steamwheedle eine sichere Durchreise durch neutrale Gewässer.",["faction:Horde"]="Die Unterstützung der Hafenarbeiter von Ratschet trägt dazu bei, den reibungslosen Betrieb des wichtigsten neutralen Hafens zu gewährleisten, der Kalimdor mit den Östlichen Königreichen verbindet."},sec={{t="Ein ungeschicktes Missgeschick",b="Ratschet lebt vom ständigen Seehandel mit Beutebucht auf der anderen Seite des Großen Meeres, doch die Goblin-Effizienz gerät unter der reinen Menge gelegentlich ins Wanken. Als am Hafen eine ungewöhnlich gewaltige Morgenlieferung eintraf, versuchte Kranführer Moppelfuzz abzukürzen, um das Entladen zu beschleunigen. Da er weit mehr hob, als sein Kran bewältigen konnte, ließ er die gesamte Ladung über die Docks fallen. Im darauffolgenden Chaos nutzte ein örtlicher Unruhestifter namens Mad Magglish die verschütteten Kisten aus, schnappte sich eine einzige wertvolle Flasche Schnaps und floh landeinwärts."},{t="Diplomatischer Jahrgang",b="Die gestohlene Fracht war weit mehr als eine gewöhnliche Ration Dockschnaps. Bei der Flasche handelte es sich um einen 99 Jahre alten Portwein, der als persönliches diplomatisches Geschenk von Baron Revilgaz, dem berüchtigten Herrscher des Schwarzwasserkartells von Beutebucht, an Gazlowe gesandt wurde, den Chefingenieur und Vorsteher von Ratschet. Der Verlust einer solch kostbaren Gabe droht Bigglefuzz zu demütigen und beide Handelsmogule zu erzürnen. Da ihm der Verlust seiner Arbeit oder Schlimmeres drohte, verfolgte Bigglefuzz den Dieb bis zum unheilvollen Eingang der Höhlen des Wehklagens, doch hielt ihn die Furcht davon ab, Magglish hinein zu folgen."},{t="Das Höhlenversteck",b="Statt sich tief in die verdorbene Traumwelt des Dungeons selbst zu wagen, zog es Mad Magglish vor, sich in den weitläufigen, feuchten Naturtunneln außerhalb des inneren Portals zu verstecken. Magglish verlässt sich auf ungeschickte Tarnung und dunkle Nischen und schleicht durch die unterirdischen Höhlen in der Hoffnung, dass die Verfolger aufgeben. Um den Portwein zurückzuholen, muss der Dieb in den äußeren Gefilden aufgespürt werden, bevor der Jahrgang entkorkt oder zerstört wird."}},faq={{q="Warum ist diese Flasche Portwein so wichtig?",a="Der 99 Jahre alte Portwein ist kein gewöhnlicher Grog; er ist ein extravagantes persönliches Geschenk von Baron Revilgaz aus Beutebucht an Gazlowe, den Boss von Ratschet. Ihn bei einem Missgeschick an den Docks zu verlieren, droht die Führung von Ratschet zutiefst zu verärgern und Kranführer Moppelfuzz seine Existenz zu kosten.",al={"warum kümmert es bigglefuzz","was ist der 99 jahre alte portwein","warum ist der wein wichtig"}},{q="Wer ist Mad Magglish?",a="Mad Magglish ist ein opportunistischer Dieb und Unruhestifter, der sich in Ratschet herumtreibt. Als Bigglefuzz eine riesige Frachtladung auf die Docks stürzen ließ, ergriff Magglish die seltene Flasche Portwein und floh direkt in die nahegelegenen Höhlen des Wehklagens, um sich zu verstecken.",al={"wer ist magglish","wer stahl den portwein","mad magglish lore"}},{q="Muss ich den Dungeon der Höhlen des Wehklagens betreten, um den Dieb zu finden?",a="Nein. Mad Magglish versteckt sich in den verwinkelten, öffentlichen Höhlengängen außerhalb des Instanzportals. Er nutzt eine schwache Verstohlenheit und lauert in den oberen Seitentunneln oder nahe den überfluteten Kammern, die zum Haupteingang führen.",al={"ist magglish in der instanz","wo ist mad magglish","magglish finden"}},{q="Wie kam es zu dem Frachtunfall?",a="Eine gewaltige Frachtlieferung traf aus Beutebucht ein, und Kranführer Moppelfuzz versuchte, mehr Kisten auf einmal zu entladen, als seine Ausrüstung bewältigen konnte. Der überladene Kran ließ die Fracht fallen und verstreute wertvolle Güter über die Docks von Ratschet.",al={"warum fielen die kisten herunter","was hat bigglefuzz getan","kranunfall ratschet"}},{q="In welcher Beziehung stehen Ratschet und Beutebucht?",a="Beide Hafenstädte sind lebenswichtige Hochburgen des Steamwheedle-Kartells, verbunden durch Handel und Kaperflotten. Regelmäßige Handelslieferungen und förmliche Aufmerksamkeiten wechseln zwischen Baron Revilgaz im Süden und Gazlowe im Brachland, um ihr gemeinsames Handelsimperium aufrechtzuerhalten.",al={"verbindung ratschet und beutebucht","steamwheedle häfen","revilgaz und gazlowe"}},{q="Warum hat Bigglefuzz die Flasche nicht selbst zurückgeholt?",a="Bigglefuzz verfolgte den Dieb bis zum Eingang der Höhlen des Wehklagens, doch der unheimliche Ruf und die monströsen Bewohner des unterirdischen Labyrinths versetzten den Goblin so sehr in Angst und Schrecken, dass er an der Schwelle stehen blieb.",al={"warum hat der goblin es nicht geholt","warum brach bigglefuzz die verfolgung ab"}}},fx={b908c2b9={q="Warum braucht Kranführer Moppelfuzz diesen Hafen zurück?",a="Moppelfuzz' Arbeit steht auf dem Spiel. Als er versuchte, mehr Kisten abzuladen, als sein Kran bewältigen konnte, stürzte die gesamte morgendliche Lieferung aus Beutebucht ab. In dem Chaos ging die wertvolle Flasche mit neunundneunzigjährigem Hafenwein verloren, und der Hafenmeister sitzt ihm seither im Nacken. Da der Jahrgang ein persönliches Geschenk für Ratschets Chefingenieur, Gazlowe, war, bedeutet das Versäumnis, ihn wiederzubekommen, dass Moppelfuzz kurz vor der Entlassung steht.",al={"warum will moppelfuzz den hafenwein","moppelfuzz motiv","warum moppelfuzz helfen"}}},fp="20,361,15.535.0,18.522.0,18.419.0,40.271.0,20.238.0,65.208.0,31.240.0,55.258.0,50.207.0"}
P.entries["quest:95981"] = {n="Watching the Roads",s="Watching the Roads ist eine Quest der Verlassenen im Silberwald, die von Schattenpriester Allister aus dem Grabmal geleitet wird. Sie beauftragt Abenteurer damit, Dalaran Wizards und Watchers entlang der Straßen nahe Mühlenbern anzugreifen, um Lieferungen der Kirin Tor in das Gebiet der Verlassenen zu unterbinden.",h="Watching the Roads ist eine Quest der Verlassenen im Silberwald, die von Schattenpriester Allister aus dem...",kw={"mühlenbern","dalaranwächter","dalaranzauberer","kirin tor","anhänger","relikte","das grabmal","schattenpriester allister","silberwald","watching the roads"},ang={["class:Mage"]="Dalarans Zauberer und Wächter verlassen sich auf spezialisierte Relikte und magische Patrouillen, um die Durchreise zu sichern, was sie zu erstklassigen Zielen für rivalisierende Zauberwirker macht.",["class:Priest"]="Schattenpriester Allister leitet diese Offensive aus dem Grabmal und demonstriert damit die aktive Rolle des Klerus der Verlassenen bei der Grenzverteidigung.",["faction:Horde"]="Die Unterbrechung von Dalarans Nachschublinien um Mühlenbern trägt dazu bei, die Stellung der Horde in der Region gegen feindselige Enklaven der Menschen zu behaupten.",["race:Undead"]="Die Sicherung der Transitwege durch den Silberwald ist für die Verlassenen von entscheidender Bedeutung, um ihre Grenzen zu verteidigen und Dalarans magische Übergriffe zu stoppen."},sec={{t="Spannungen entlang der Straße nach Mühlenbern",b="Entlang der Verkehrswege rund um Mühlenbern unterhalten die Kirin Tor eine aggressive Präsenz. Nach dem Zusammenbruch der Barriere, die Dalaran umschloss, haben ihre Zauberer und wachsamen Posten das Reisen über die Grenzen in den Silberwald hinein massiv eingeschränkt. Von ihrem Stützpunkt im Grabmal aus beobachten die Verlassenen diesen Aufmarsch mit wachsender Sorge, da sie erkennen, dass die menschlichen Magi diese offenen Straßen nutzen, um gefährliche Relikte und verzauberte Anhänger tief in umkämpfte Lande zu transportieren."},{t="Das Durchtrennen der Nachschublinie",b="Schattenpriester Allister sieht in der Beschlagnahmung einzelner Anhänger lediglich die Behandlung eines Symptoms. Um den Zustrom magischer Artefakte aus Dalaran einzudämmen, entsendet er Agenten, um die Eskorten der Kirin Tor direkt entlang der Straße zur Strecke zu bringen. Indem sie sowohl Dalaran Wizards als auch Dalaran Watchers nahe Mühlenbern dezimieren, versuchen die Verlassenen, den eisernen Griff der Kirin Tor um den regionalen Durchgangsverkehr zu brechen und ihre östliche Grenze gegen magische Einmischung von außen abzuriegeln."}},faq={{q="Wer vergibt die Quest Watching the Roads?",a="Die Quest wird von Schattenpriester Allister vergeben und abgeschlossen, der sich im Grabmal im Silberwald befindet. Er beauftragt Streiter damit, die Patrouillen der Kirin Tor anzugreifen, die entlang der örtlichen Handelswege operieren.",al={"wer vergibt watching the roads","questgeber watching the roads","wo watching the roads abgeben"}},{q="Warum greifen die Verlassenen Dalaran-Patrouillen nahe Mühlenbern an?",a="Schattenpriester Allister möchte den stetigen Strom magischer Relikte und Anhänger unterbinden, die von Dalaran in den Silberwald transportiert werden. Die Beseitigung der Zauberer und Wächter entlang der Straßen nahe Mühlenbern nimmt Dalaran den leichten Zugang über die Grenzen der Verlassenen hinweg.",al={"warum dalaranzauberer töten","warum straßen von mühlenbern angreifen","kirin tor silberwald zweck"}},{q="Wie ist die Lage bezüglich der Barriere um Dalaran?",a="Laut Schattenpriester Allister ist die Schutzbarriere um Dalaran gefallen. Als Reaktion darauf haben die Kirin Tor ihren Zugriff auf die umliegenden Straßen verschärft und legen auffällige Paranoia an den Tag, während sie die Region Mühlenbern patrouillieren.",al={"was geschah mit der barriere um dalaran","dalaran-kuppel gefallen","barriere gefallen dalaran"}},{q="Wo sind die Dalaran Wizards und Watchers zu finden?",a="Sowohl Dalaran Wizards als auch Dalaran Watchers patrouillieren auf den Straßen rund um die Ortschaft Mühlenbern im Silberwald. Sie überwachen den Durchgangsverkehr, um die Bewegung von Personal und verzauberten Gegenständen der Kirin Tor zu sichern.",al={"wo sind dalaranwächter","mühlenbern patrouillenorte","wo dalaranzauberer zu finden sind"}},{q="Welche Gegenstände transportiert Dalaran über diese Straßen?",a="Die Kirin Tor haben verzauberte Anhänger und andere magische Relikte aus Dalaran in den Silberwald geschafft. Allister will diese Nachschubroute an der Quelle abschneiden, bevor sich die Artefakte weiter im Gebiet verteilen können.",al={"welche relikte dalaran transportiert","was sind die anhänger","mühlenbern anhänger"}},{q="Warum sind die Kirin Tor entlang der Straßen von Mühlenbern so wachsam?",a="Seit die magische Barriere um Dalaran gefallen ist, halten die Kirin Tor eine aggressive Wache auf den Verkehrswegen, die in den Silberwald führen. Während Allister ihr tiefes Misstrauen und ihre Wachsamkeit bemerkt, bleiben ihre genauen Motive für die Verlassenen im Grabmal unbestätigt.",al={"warum sind die kirin tor paranoid","warum dalaran-wachen patrouillieren","kirin tor straßenkontrolle"}}},fp="18,263,33.480.0,24.437.0,39.205.0,62.268.0,54.243.0,52.225.0,57.239.0,60.284.0"}
P.entries["quest:95998"] = {n="The Great Outdoors",s="The Great Outdoors ist eine einführende Quest zum Überleben in der Wildnis, bei der der Reisende Sam angehenden Abenteurern die Kunst beibringt, sich in der Wildnis durchzuschlagen. Indem sie an einem einfachen Lagerfeuer rasten, lernen Reisende, wie sie sich unterwegs versorgen, bevor sie sich spezialisierten Handwerksberufen widmen.",h="The Great Outdoors ist eine einführende Quest zum Überleben in der Wildnis, bei der der Reisende Sam...",kw={"einfaches lagerfeuer","boosted rest","lagervorrichtung","lagerkunde","waldläufer","sam","the great outdoors","handwerksfertigkeit"},ang={["class:Hunter"]="Vom Land zu leben und neben einer offenen Flamme zu rasten, ist für Wildnispirscher eine zweite Natur, doch selbst erfahrene Kundschafter profitieren davon, das Lagerleben zu meistern.",["profession:Cooking"]="Lagerfeuer sind ein Grundpfeiler des Kochens im Feld, und das Erlernen des richtigen Lagerlebens in der Wildnis bildet die Grundlage für die Zubereitung von Mahlzeiten unter freiem Himmel."},sec={{t="Lektionen am Feuer",b="Die weiten Länder von Azeroth rufen zahllose rastlose Seelen, die nach Glück, Gefahr und Ruhm streben. Doch bloßer Ehrgeiz allein kann einen angehenden Abenteurer nicht vor der schneidenden Kälte oder der Erschöpfung der offenen Straße schützen. Das Meistern grundlegender Wildnisfertigkeiten – zu wissen, wann man anhält, ein Feuer entfacht und neue Kraft sammelt – ist das stille Fundament, auf dem jede legendäre Reise aufbaut. Sams Einladung bietet Neulingen eine Gelegenheit innezuhalten und diese unverzichtbaren Überlebensgewohnheiten im Freien zu erlernen."},{t="Wildniskunde und Handwerk",b="Neben einem wärmenden Lagerfeuer Schutz zu suchen, tut mehr, als nur die nächtliche Kälte abzuwehren; es gewährt einen lebenswichtigen Moment der Erholung, der als Boosted Rest bekannt ist. Erfahrene Überlebenskünstler erkennen, dass Ausdauer in der Wildnis davon abhängt, sich zwischen Expeditionen angemessen auszuruhen. Sobald diese Grundlagen des Überlebens verstanden sind, können Handwerker und Sammler ihre Aufmerksamkeit den Handwerksberufen widmen und lernen, wie man spezielle Lagervorrichtungen zusammenbaut, die auf ihre jeweilige Arbeit im Feld zugeschnitten sind."}},faq={{q="Wer ist Sam?",a="Sam ist ein erfahrener Naturkenner und versierter Reisender, der es auf sich nimmt, angehenden Abenteurern die Grundlagen des Überlebens in der Wildnis beizubringen. Er heißt wandernde Seelen willkommen, die Wärme seines Feuers zu teilen, während er praktische Weisheiten für die Wildnis vermittelt.",al={"wer ist sam","sam lagerfeuer quest","questgeber"}},{q="Was ist der Zweck des Sitzens am Lagerfeuer?",a="Boosted Rest stellt die verjüngende Wirkung des Ausruhens an einem richtigen Lagerfeuer in der Wildnis dar. Sich die Zeit zu nehmen, in wohliger Wärme zu sitzen, ermöglicht es müden Abenteurern, ihre Lebenskraft wiederzugewinnen und für den vor ihnen liegenden Weg gestärkt zu bleiben.",al={"was ist boosted rest","boosted rest buff","rasten am feuer"}},{q="Warum sind Wildnisfertigkeiten für Abenteurer wichtig?",a="Die Welt außerhalb der Siedlungsmauern ist gewaltig und gefährlich und verlangt von jedem Wanderer, der nach Glück und Ruhm strebt, zu lernen, sich selbst zu versorgen. Eine angemessene Wildniskunde stellt sicher, dass Reisende lange Reisen überstehen können, ohne der Erschöpfung zu erliegen.",al={"warum wildnisfertigkeiten lernen","warum in der wildnis überleben","überlebensfertigkeiten"}},{q="Wie hängen Handwerksberufe mit dem Lagern in der Wildnis zusammen?",a="Nachdem Ihr gelernt habt, ein einfaches Lager aufzuschlagen, können Euch Berufsmeister beibringen, wie Ihr spezielle Lagervorrichtungen herstellt, die auf Euren gewählten Beruf zugeschnitten sind und Eure Fähigkeiten verbessern, während Ihr im Feld stationiert seid.",al={"berufe lagern","lagervorrichtungen","berufe danach"}},{q="Was sollte ein Abenteurer nach Abschluss dieser Lektion tun?",a="Sobald Ihr an Sams Feuer gerastet und das grundlegende Lagerleben begriffen habt, drängt Sam Euch dazu, Berufslehrer aufzusuchen. Das Vorankommen in einem praktischen Handwerk ermöglicht es Euch, maßgeschneiderte Feldstationen zu bauen, die zu Eurem Beruf passen.",al={"nächste schritte","was nach the great outdoors","nach der lagerfeuer-quest"}},{q="Wer kann The Great Outdoors annehmen?",a="Die Quest steht jeder rastlosen Seele offen, die in die weite Welt hinauszieht, ungeachtet der Herkunft oder Loyalität, und dient als einführende Lektion für das Überleben auf der Reise.",al={"kann das jeder tun","wer kann the great outdoors annehmen","ist diese quest allgemein"}}},fp="18,291,19.479.0,20.460.0,11.258.0,47.240.0,52.235.0,48.215.0,58.210.0,37.177.0"}
P.entries["quest:95999"] = {n="GESUCHT: Verbrenner Gar'im",s="GESUCHT: Verbrenner Gar'im ist ein von den Behörden in Seenhain ausgesetztes Kopfgeld auf einen feindlichen Orkkommandanten, der sich in Renders Tal verschanzt hat. Gar'im befehligt ein gefährliches Kontingent von Schattenzauberern und soll Gerüchten zufolge mit dem Schwarzfelsklan zusammenarbeiten, der Burg Steinwacht hält. Magistrat Solomon bietet ein stattliches Kopfgeld für den Beweis seines Ablebens.",h="GESUCHT: Verbrenner Gar'im ist ein von den Behörden in Seenhain ausgesetztes Kopfgeld auf einen feindlichen...",kw={"blackrock","kopfgeld","gar'im","verbrenner","seenhain","renders tal","schattenzauberer","solomon"},ang={["class:Mage"]="Gar'im und seine Schattenzauberer verkörpern eine verdorbene Zurschaustellung von offensiven Arkanzaubern und Schattenmagie, die eine rasche magische Gegenreaktion erfordert.",["faction:Alliance"]="Das Strecken von Verbrenner Gar'im schützt die verwundbaren Bürger von Seenhain direkt vor dem Anführer einer orkischen Invasion und seinen äußerst gefährlichen Schattenzauberern."},sec={{t="Ein Feuer in Renders Tal",b="Das Rotkammgebirge ist zunehmend gefährlicher geworden, da die Schwarzfelsorcs aus ihren Gebirgsbastionen vorrücken. In Renders Tal führt Verbrenner Gar'im einen aktiven Überfall an und treibt an der Seite loyaler Schattenzauberer dunkle Zauberei voran. Da die örtliche Stadtwache überfordert und die Armeen der Krone weitgehend abwesend sind, wandte sich Magistrat Solomon an unabhängige Söldner, um Gar'im zu eliminieren, der Gerüchten zufolge mit den Schwarzfelsorcs von Burg Steinwacht zusammenarbeitet."},{t="Todesbeweis",b="Gar'im ist berüchtigt für seine zerstörerische Magie und seine Befehlsgewalt über schattenwebende Zauberer. Um die Belohnung der Ortschaft einzufordern, müssen Jäger tief in feindlich kontrolliertes Gebiet vordringen, den Verbrenner besiegen und seinen zerschlagenen Stab als physischen Beweis dafür, dass die Bedrohung beseitigt wurde, zum Rathaus von Seenhain zurückbringen."}},faq={{q="Wer ist Verbrenner Gar'im?",a="Verbrenner Gar'im ist ein orkischer Kriegsherr und Zauberer, der einen Überfall in Renders Tal anführt. Er soll Gerüchten zufolge mit den Schwarzfelsorcs von Burg Steinwacht zusammenarbeiten und befehligt gefährliche Schattenzauberer.",al={"wer ist gar'im","garim","verbrenner garim"}},{q="Wo ist Verbrenner Gar'im zu finden?",a="Gar'im schlägt sein Lager inmitten der feindlichen Orktruppen in Renders Tal auf, das sich im südöstlichen Rotkammgebirge befindet.",al={"gar'im aufenthaltsort","wo ist garim","renders tal lage"}},{q="Wer hat das Kopfgeld auf Gar'im ausgesetzt?",a="Das Kopfgeld wurde im Namen von Seenhain von Magistrat Solomon ausgesetzt, der verzweifelt versucht, die orkischen Überfälle einzudämmen, die die bedrängte Stadt bedrohen.",al={"wer gab das kopfgeld","solomon kopfgeld"}},{q="Welcher Beweis ist erforderlich, um das Kopfgeld einzufordern?",a="Magistrat Solomon verlangt den Zerbrochenen Stab von Verbrenner Gar'im, um das Ableben des Zauberers zu bestätigen, bevor er die Belohnung auszahlt.",al={"garim beweis","zerbrochener stab questgegenstand"}},{q="Welche Bedrohung stellen Gar'im und seine Anhänger dar?",a="Gar'im verfügt über tödliche zerstörerische Magie und wird von Schattenzauberern flankiert. Ihre Anwesenheit festigt die Stellung des Schwarzfelsklans im Rotkammgebirge und droht Seenhain zu überrennen, wenn sie nicht aufgehalten werden.",al={"gar'im fähigkeiten","schattenzauberer rotkammgebirge"}},{q="Warum verlässt sich Seenhain auf Kopfgelder statt auf die Armee von Sturmwind?",a="Sturmwind hat das Rotkammgebirge inmitten politischer Konflikte und Truppenmangels weitgehend sich selbst überlassen, was Magistrat Solomon dazu zwang, gewillte Abenteurer anzuheuern, um feindliche Anführer zu ermorden.",al={"warum kopfgelder seenhain","wo ist sturmwind armee"}}},fp="26,345,25.467.0,15.302.0,26.204.0,38.125.0,33.149.0,43.132.0,45.192.0,68.180.0"}
P.entries["quest:96"] = {n="Ruf des Wassers",s="Diese Aufgabe markiert den Höhepunkt der beschwerlichen Pilgerreise des Schamanen zur Einstimmung auf das Element des Wassers. Durch die Rückgabe eines gereinigten Wassersplitters an Islen Wasserdeuter an der Küste des Brachlands beweist ein Initiat seinen Einklang mit den wiederherstellenden Energien und verdient sich sein Wassertotem.",h="Diese Aufgabe markiert den Höhepunkt der beschwerlichen Pilgerreise des Schamanen zur Einstimmung auf das...",kw={"ruf des wassers","islen wasserdeuter","schwache wassermanifestation","wassersplitter","silberwald","brachland","wassertotem"},ang={["class:Shaman"]="Dieser Übergangsritus verleiht Euch Euer Wassertotem und eröffnet die wiederherstellenden Quellen und reinigenden Brunnen, die für Eure Rolle als spiritueller Heiler von zentraler Bedeutung sind.",["faction:Horde"]="Die Prüfung veranschaulicht die spirituelle Verantwortung der Horde und fordert junge Schamanen dazu auf, verheerte Länder sowohl in Kalimdor als auch in den Östlichen Königreichen zu reinigen."},sec={{t="Eine lange Heimreise",b="Die Suche nach dem Wasser erfordert von einem Initiaten, Kontinente zu überqueren und bis zu den verdorbenen Ufern des Silberwalds zu reisen, um der Verderbnis direkt entgegenzutreten. Wasser steht für Leben, Anpassungsfähigkeit und Heilung, doch seine geschmeidige Natur macht es einzigartig anfällig für die Seuche und dunkle Magie. Nachdem der Initiat vor die Schwache Wassermanifestation getreten ist und den reinen elementaren Willen bezeugt hat, wird ihm ein einzigartiges Geschenk anvertraut: der Wassersplitter. Dieses Zeichen über das Meer zurück in das sonnenverbrannte Brachland zu tragen, ist eine greifbare Mahnung daran, dass das Wasser alle fernen Winkel der Welt verbindet."},{t="Das Wassertotem",b="Als Islen Wasserdeuter den Splitter entgegennimmt, prüft sie nicht bloß den Beweis einer vollendeten Aufgabe; sie erforscht, ob der Schamane das Gleichgewicht zwischen Bewahrung und Erneuerung verinnerlicht hat. Die vordringende Fäulnis Lordaerons verdeckt oft subtile Siege, doch selbst die Reinigung einer einzelnen Quelle bedeutet den Geistern viel. Sobald diese Gabe anerkannt ist, überreicht Islen dem Schamanen das Wassertotem. Dieser physische Fokus erlaubt es dem Praktizierenden, reinigende, heilende und manaregenerierende Ströme in die sterbliche Welt zu leiten, und verankert seine dauerhafte Zwiesprache mit den Gezeiten."}},faq={{q="Was ist der Wassersplitter?",a="Der Wassersplitter ist ein konzentriertes Elementarrelikt, das von der Schwachen Wassermanifestation verliehen wird. Er dient als greifbarer Beweis dafür, dass ein Initiat die Rolle des Wassers als lebenspendende Kraft verstanden und sich der Verderbnis, die die elementaren Ströme bedroht, erfolgreich entgegengestellt hat.",al={"wassersplitter","was ist der splitter"}},{q="Wohin bringe ich den Wassersplitter?",a="Der Splitter muss zu Islen Wasserdeuter zurückgebracht werden, die in einem abgelegenen Lager an der östlichen Küstenlinie des Brachlands südlich von Ratschet weilt.",al={"wo abgeben","wer bekommt den splitter","abgabeort"}},{q="Was erhalte ich für den Abschluss dieser Prüfung?",a="Der Abschluss dieser letzten Prüfung belohnt den Schamanen mit seinem Wassertotem, dem unverzichtbaren Kanal, der benötigt wird, um wasserbasierte Elementartotems für Heil- und Wiederherstellungsmagie zu beschwören.",al={"questbelohnung","totembelohnung","was erhalte ich"}},{q="Warum fand die Prüfung im Silberwald statt?",a="Die Gewässer des Silberwalds leiden unter schwerer Verderbnis durch Seuche und Schattenmagie. Den Schamanen dorthin zu entsenden, zwang ihn dazu, die Zerbrechlichkeit des Wassers mitanzusehen und seine natürliche Reinheit aktiv gegen den Verfall zu verteidigen.",al={"warum silberwald","warum östliche königreiche","silberwald wasser"}},{q="Wer ist Islen Wasserdeuter?",a="Islen Wasserdeuter ist eine Taurenschamanin, die an der östlichen Küste des Brachlands lebt. Sie überwacht die schamanischen Prüfungen des Wassers und lehrt Initiaten, wie man mit fließenden Geistern kommuniziert und die Künste der Wiederherstellung meistert.",al={"islen","wer ist islen wasserdeuter"}}},fx={["352084e3"]={q="Warum schickt Euch die Schwache Wassermanifestation zurück zu Islen?",a="Die elementare Manifestation dient als lebendige Stimme des reinen Wassers, geprüft und beschworen durch Eure Rituale. Indem sie Euch den Wassersplitter gewährt, vertraut sie Euch die grundlegende Wahrheit ihres Wesens an: Wasser bringt Leben, während Verderbnis es auslöscht. Sie schickt Euch zurück zu Islen Wasserdeuter, damit der Schamane Eure Verbindung mit den Geistern bestätigen, Euren Erfolg bei der Konfrontation mit der Verderbnis anerkennen und Euch das Wassertotem gewähren kann, das zu führen Ihr Euch als würdig erwiesen habt.",al={"motiv der wassermanifestation","warum den splitter zu islen bringen","warum will die wassermanifestation das"}}},fp="13,274,19.595.0,15.570.0,27.269.0,35.143.0,44.171.0,43.205.0,23.208.0"}
P.entries["quest:960"] = {n="Onu meditiert",s="Während Ihr die Meistergleve im südlichen Dunkelküste untersucht, begibt sich der Uralte der Lehren Onu in eine tiefe Trance, um über die wachsende Bedrohung nachzudenken. Spieler, die ihre mystische Wahrsagephiole verlieren, können mit dem meditierenden Uralten sprechen, um einen Ersatz zu erhalten. Seine Gedanken konzentrieren sich auf die finstere Allianz und die Beweggründe des Kults des Schattenhammers und der schlangengleichen Naga.",h="Während Ihr die Meistergleve im südlichen Dunkelküste untersucht, begibt sich der Uralte der Lehren Onu in...",kw={"dunkelküste","der hain der uralten","die meistergleve","meditieren","onu","wahrsagephiole","wahrsageschale","schattenhammer"},ang={["class:Druid"]="Druiden teilen eine tiefe natürliche Bindung mit den Uralten der Lehren. Die Aufrechterhaltung der Kommunikation über Wahrsagerituale spiegelt die Methode des Zirkels des Cenarius wider, verseuchten Boden aus der Ferne zu überwachen.",["faction:Alliance"]="Die Sicherung der Dunkelküste vor Kultisten und aquatischen Eindringlingen ist für Reisende der Allianz, die zwischen Teldrassil und Eschental unterwegs sind, von entscheidender Bedeutung.",["race:NightElf"]="Als Bewahrer des Gleichgewichts von Kalimdor verehren Nachtelfen Uralte der Lehren wie Onu und verlassen sich auf ihre zeitlose Weisheit, um Störungen in der Wildnis der Dunkelküste zu deuten."},sec={{t="Ein Geist in tiefer Kontemplation",b="Onu ist ein Uralter der Lehren, der im Hain der Uralten in der Dunkelküste verwurzelt ist und als lebendiges Archiv der Geschichte Kalimdors dient. Als unheilvolle Berichte über dunkle Ausgrabungen bei der Meistergleve auftauchen, kehrt Onu sein immenses Bewusstsein nach innen. Er meditiert intensiv darüber, was sowohl die fanatischen Kultisten des Schattenhammers als auch die heimtückischen Naga zu den versteinerten Überresten eines uralten Ungetüms locken könnte. Für Abenteurer, die seine Aufklärung durchführen, bleibt er ein zugänglicher Anker und bietet Ersatz-Wahrsagephiolen an, falls ihre in der Wildnis verloren gehen sollten."},{t="Die Tiefen ausspähen",b="Um die Ruinen zu überwachen, ohne die physische Präsenz des Uralten zu riskieren, verlässt sich Onu auf naturverbundene Weissagung. Abenteurern wird eine Wahrsagephiole anvertraut, mit der sie direkt an der Ausgrabungsstätte eine Wahrsageschale herbeirufen können, damit Onu aus der Ferne mit ihnen kommunizieren kann. Da die Reise nach Süden durch die Dunkelküste gefährlich und von feindseliger Tierwelt und Kultistenpatrouillen durchsetzt ist, rechnet Onu mit Missgeschicken. Seine Trance ist kein ununterbrochener Schlaf, sondern eine aufmerksame Mahnwache; er stellt bereitwillig ein weiteres Gefäß mit heiligem Wasser zur Verfügung, um sicherzustellen, dass die Untersuchung der Meistergleve ohne Verzögerung fortgesetzt wird."}},faq={{q="Warum meditiert Onu?",a="Onu ist ein Uralter der Lehren, der über die beunruhigende Präsenz sowohl des Kults des Schattenhammers als auch der Naga bei der Meistergleve nachdenkt. Er nutzt diese Meditation, um ihre Beweggründe zu erkennen und Abenteurer bei der Untersuchung der Stätte anzuleiten.",al={"warum meditiert onu","onu trance","was macht onu"}},{q="Was ist der Zweck dieser Interaktion?",a="Es dient als Sicherheitsmechanismus für Spieler bei der Quest 'Die Meistergleve'. Wenn Ihr Eure Wahrsagephiole verliert, zerstört oder vorzeitig benutzt, erhaltet Ihr durch das Gespräch mit dem meditierenden Onu eine Ersatzphiole, damit Ihr das Ritual abschließen könnt.",al={"wahrsagephiole verloren","weitere phiole erhalten","onu ersatz quest"}},{q="Wo befindet sich Onu?",a="Onu ist im Hain der Uralten verwurzelt, der sich im mittleren Süden der Dunkelküste befindet, direkt abseits der Hauptstraße.",al={"onu standort","wo finde ich onu"}},{q="Was mache ich mit der Wahrsagephiole?",a="Bringt die Phiole zur Meistergleve und benutzt sie, um eine Wahrsageschale zu erschaffen. Onu kann dann durch die Schale mit Euch kommunizieren.",al={"wahrsagephiole benutzen","wahrsageschale dunkelküste","zweck der wahrsagephiole"}},{q="Was ist die Meistergleve?",a="Die Meistergleve ist eine riesige, uralte Ausgrabungsstätte im südlichen Dunkelküste, wo der kolossale, versteinerte Schädel einer vergessenen Entität von einer gigantischen Klinge durchbohrt liegt. Kultisten und Naga haben sich dort für unbekannte, bösartige Zwecke versammelt.",al={"was ist die meistergleve","denkmal im südlichen dunkelküste"}},{q="Können Hordespieler hier mit Onu interagieren?",a="Nein. Onu ist streng mit den Nachtelfen und der Allianz verbündet. Hordespieler, die den Hain der Uralten betreten, werden Onu und seine Beschützer feindselig oder unkooperativ vorfinden.",al={"ist onu nur für die allianz","horde onu meditieren"}}},fx={["72a6a09e"]={q="Warum braucht Onu Eure Hilfe, anstatt selbst zu ermitteln?",a="Onu bleibt im Grove of the Ancients, um über den Schattenhammer und die Naga zu meditieren. Er verlässt sich auf Reisende, um den The Master's Glaive zu untersuchen und ihn durch eine Schale des Schauens zu kontaktieren.",al={"warum mich schicken","warum geht onu nicht selbst","warum braucht onu euch"}}},fp="17,366,28.564.0,18.581.0,22.227.0,40.244.0,21.106.0,39.127.0,28.246.0,41.185.0"}
P.entries["quest:96031"] = {n="Camping 101: Leatherworking",s="Camping 101: Leatherworking leitet Handwerker darin an, gegerbte Bälge zu nutzen, um ihren ganz persönlichen tragbaren Wildnisunterschlupf herzustellen. Es betont die Notwendigkeiten des Überlebens fernab der Zivilisation und erinnert Abenteurer daran, dass ein echtes Lager sowohl ein in der Wildnis aufgeschlagenes Zelt als auch ein loderndes Lagerfeuer erfordert, wie es von Ausbildern für Kochkunst gelehrt wird.",h="Camping 101: Leatherworking leitet Handwerker darin an, gegerbte Bälge zu nutzen, um ihren ganz persönlichen...",kw={"lagerzelt","lagerfeuer","zelten","kochkunst","lederverarbeitung","unterkunft","zelt","wildnis"},ang={["profession:Cooking"]="Ein Lagerfeuer ist das unverzichtbare Herzstück eines jeden Lagers in der Wildnis. Das Erlernen der einfachen Kochkunst stellt sicher, dass ein Abenteurer Flammen entfachen kann, um ein Lager draußen in der Wildnis aufrechtzuerhalten."},sec={{t="Einen Unterschlupf in der Wildnis aufschlagen",b="Die Herstellung eines persönlichen Unterschlupfs ist ein wesentlicher Meilenstein für jeden Handwerker, der mit Bälgen und Leder arbeitet. Ein stabiles Lederzelt bietet Wanderern einen verlässlichen Schutz gegen raues Wetter, Wind und die Kälte der Nacht, wenn sie durch offenes Gelände reisen. Allerdings sehen es die örtlichen Stadtbewohner ungern, wenn persönliche Unterkünfte auf belebten Straßen oder Marktplätzen aufgeschlagen werden, was bedeutet, dass ein Abenteurer hinter die Stadttore in die ungezähmte Wildnis aufbrechen muss, um seinen Unterschlupf aufzuschlagen."},{t="Die Wärme eines Lagerfeuers",b="Ein aufgeschlagenes Zelt ist nur die halbe Miete für einen beständigen Lagerplatz. Ein ordentliches Lager erfordert ein loderndes Lagerfeuer, um die Dunkelheit abzuwehren, kalte Winde fernzuhalten und eine Heimstatt in gefährlichen Ländern zu bieten. Da das Entzünden und Versorgen eines Feuers grundlegend für die Zubereitung von Mahlzeiten im Felde ist, werden Abenteurer dazu angeleitet, sich an Meister der Kochkunst und Kochkunstlehrer zu wenden, um zu lernen, wie man ein Lagerfeuer entfacht, bevor man ein Lager errichtet."}},faq={{q="Wo könnt Ihr ein Lagerzelt aufschlagen?",a="Stadtbewohner sehen es ungern, wenn Lagerzelte mitten auf Straßen oder Stadtplätzen aufgestellt werden. Ein Abenteurer muss sich in die ungezähmte Wildnis hinauswagen, wo es reichlich offenen Boden gibt, um ein Zelt ordnungsgemäß aufzuschlagen.",al={"verwendung von lagerzelten","wo zelt aufschlagen","kann ich in der stadt zelten"}},{q="Was wird außer einem Zelt noch benötigt, um ein Lager aufzuschlagen?",a="Ein Lagerzelt allein macht noch kein funktionierendes Lager aus. Ihr benötigt außerdem ein ordentliches Lagerfeuer, das neben dem Zelt brennt, bevor ein richtiger Lagerplatz eingerichtet werden kann.",al={"feuer fuer lager benoetigt","lageranforderungen","wie man zeltet"}},{q="Wo lernen Abenteurer, ein Lagerfeuer zu errichten?",a="Ausbilder, die in den kulinarischen Künsten bewandert sind, lehren die Grundlagen der Zubereitung von Nahrung, wozu auch gehört, wie man ein einfaches Lagerfeuer entfacht und aufrechterhält. Das Aufsuchen eines Kochkunstlehrers vermittelt das Wissen, das erforderlich ist, um überall ein Feuer zu entzünden.",al={"lagerfeuer lernen","wer lehrt lagerfeuer","kochfeuer"}},{q="Wie hängt Lederverarbeitung mit der Herstellung von Lagerzelten zusammen?",a="Lederverarbeiter verwenden gegerbte Bälge, Pelze und robuste Nähte, um strapazierfähige Zeltplanen anzufertigen, die den rauen Elementen der Wildnis standhalten können. Dieses praktische Handwerk ermöglicht es Wanderern, aus Tierbälgen einen verlässlichen Unterschlupf zusammenzubauen.",al={"camping 101 leatherworking","lederlagerzelt","zeltherstellung lederverarbeitung"}},{q="Warum errichten Abenteurer Lager in der Wildnis?",a="Sich weit über besiedelte Außenposten hinauszuwagen, setzt Reisende den Elementen und gefährlichem Terrain aus. Einen tragbaren Unterschlupf und ein wärmendes Feuer zu haben, bietet eine sichere Zuflucht, um sich auszuruhen und zu erholen, wenn man fern von Gasthäusern und Siedlungen ist.",al={"warum draussen zelten","zweck des zeltens","wildnisueberlebenslager"}},{q="Warum haben Stadtbewohner Einwände gegen das Aufstellen von Zelten innerhalb der Stadt?",a="Siedlungen und Städte verfügen über etablierte Gasthäuser und private Unterkünfte für Reisende. Das Errichten von Zelten auf öffentlichen Straßen verstellt Durchgangswege und sorgt für Unruhe, weshalb die Einheimischen darauf bestehen, dass Lager draußen in der Wildnis bleiben.",al={"zeltregeln in staedten","keine zelte in der stadt","warum darf ich kein zelt in der stadt aufschlagen"}}},fp="27,322,28.477.0,24.427.0,32.206.0,53.152.0,47.220.0,54.235.0,53.215.0,56.216.0"}
P.entries["quest:96044"] = {n="Camping 101: Blacksmithing",s="Camping 101: Blacksmithing ist eine Einführungsaufgabe, die Schmiede zu Tognus Flintfire in Kharanos führt. Durch ihn lernen Handwerker, einen tragbaren Schleifstein zu bauen, um Waffen in Lagern in der Wildnis instand zu halten.",h="Camping 101: Blacksmithing ist eine Einführungsaufgabe, die Schmiede zu Tognus Flintfire in Kharanos führt.",kw={"schmiedekunst","klingen","lager","camping 101","dun morogh","kharanos","schleifstein","tognus flintfire","waffen"},ang={["class:Rogue"]="Ein scharfer Dolch ist für Schurken ein unverzichtbares Werkzeug ihres Handwerks, was einen Schleifstein im Lager zu einem willkommenen Anblick zwischen Feldeinsätzen macht.",["class:Warrior"]="Krieger verlassen sich in der Hitze des Gefechts auf scharfe Klingen und profitieren direkt davon, wenn Schmiede Schleifsteine in das Lager einer Expedition bringen.",["profession:Blacksmithing"]="Angehende Schmiede können lernen, nützliche Gegenstände für den Feldeinsatz wie den Schleifstein herzustellen, und so ihr Handwerk über die Stadtschmieden hinaus ausdehnen, um Verbündete draußen in der Wildnis zu unterstützen.",["race:Dwarf"]="Da Kharanos in den verschneiten Ausläufern von Dun Morogh eingebettet liegt, sind Zwergenschmiede stolz darauf, kalten Stahl scharf und für jeden Weg bereit zu halten."},sec={{t="Feldinstandhaltung für unterwegs",b="Camping 101: Blacksmithing leitet angehende Schmiede an, die Kunst des praktischen Feldeinsatzes zu erlernen. Während jede Stadtschmiede einen Brustpanzer oder ein Schwert fertigen kann, benötigen reisende Abenteurer Instandhaltung weit jenseits der behaglichen Stadtmauern. Schmiede, die ihr grundlegendes Können unter Beweis stellen, werden nach Kharanos gewiesen, wo Handwerksmeister Methoden weitergeben, um Rohmetall in tragbare Lagerwerkzeuge zu verwandeln, die Klingen auf langen Reisen scharf halten."},{t="Der Meister von Kharanos",b="In der verschneiten Siedlung Kharanos unterweist Tognus Flintfire fähige Schmiede im Bau des Schleifsteins. Das Aufstellen eines solchen Schleifsteins in einem Lager verwandelt einen gewöhnlichen Rastplatz in eine provisorische Waffenkammer und zieht Krieger und Schurken an, die darauf brennen, Scharten und abgestumpfte Schneiden vor dem nächsten Marsch aus ihrem Stahl zu schleifen."}},faq={{q="Wer ist Tognus Flintfire?",a="Tognus Flintfire ist ein Schmiedekunstlehrer in der Stadt Kharanos in Dun Morogh. Er bildet Schmiede aus, die ausreichendes Können in ihrem Beruf bewiesen haben, und lehrt sie, wie man spezialisierte Lagerausrüstung fertigt.",al={"wer ist tognus flintfire","wo ist tognus","tognus flintfire aufenthaltsort"}},{q="Was ist ein Schleifstein?",a="Der Schleifstein ist ein nützlicher Campinggegenstand, der von Schmieden hergestellt wird. Wenn er im Lager eines Abenteurers aufgestellt wird, bietet er einen eigenen Arbeitsplatz, an dem waffenführende Verbündete wie Krieger und Schurken die Schneiden ihrer Klingen im Feld schärfen und instand halten können.",al={"was macht ein schleifstein","schleifstein lager","zweck des schleifsteins"}},{q="Warum interessieren sich Krieger und Schurken für den Schleifstein?",a="Krieger und Schurken profitieren am meisten von einem Schleifstein im Lager, da ihre Kampfkraft während ausgedehnter Reisen fernab von städtischen Schmieden stark von der Erhaltung rasiermesserscharfer Klingen an ihren Schwertern, Äxten und Dolchen abhängt.",al={"wer braucht einen schleifstein","krieger schleifstein","schurken schleifstein"}},{q="Wo liegt Kharanos?",a="Kharanos ist eine geschäftige Zwergensiedlung knapp südwestlich von Eisenschmiede in den verschneiten Gipfeln von Dun Morogh. Es dient Reisenden, Bergleuten und Handwerkern, die die Gebirgspässe überqueren, als wichtiger Stützpunkt und Handelsposten.",al={"wo ist kharanos","standort von kharanos","kharanos finden"}},{q="Was ist erforderlich, um diesen Campinggegenstand zu erlernen?",a="Schmiede müssen zunächst grundlegende Fertigkeiten in ihrem Handwerk vorweisen, bevor Tognus Flintfire sie in der Herstellung von Lagerausrüstung unterweist. Sobald Ihr die Grundlagen an einem Amboss geübt habt, wird er Euch lehren, den tragbaren Schleifstein zu schmieden.",al={"camping 101: blacksmithing voraussetzung","wann kann ich den schleifstein erlernen","schmiedekunst lagerausbildung"}},{q="Warum stellen Schmiede Campinggegenstände her?",a="Campinggegenstände ermöglichen es Schmieden, Abenteurergruppen außerhalb von festen Siedlungen zu unterstützen. Anstatt Gefährten zu zwingen, für eine grundlegende Waffenpflege zu einer voll ausgestatteten Stadtschmiede zurückzukehren, bietet ein tragbares Hilfsmittel wie ein Schleifstein grundlegende Instandhaltung unter freiem Himmel.",al={"warum lagergegenstände herstellen","schmiedekunst lagergegenstände","schmiedenutzen in der wildnis"}}},fp="26,222,35.414.0,22.341.0,24.241.0,27.260.0,59.233.0,18.230.0,44.226.0,39.266.0"}
P.entries["quest:96045"] = {n="Camping 101: Alchemy",s="Camping 101: Alchemy führt angehende Alchemisten in Eisenschmiede unter der Anleitung von Vosur Brakthel in das praktische Handwerk im Feld ein. Indem Alchemisten lernen, einen Manabrunnen für ihre Lager in der Wildnis zu errichten, können sie Zauberkundigen und Heilern unterwegs lebenswichtige Erfrischung bieten.",h="Camping 101: Alchemy führt angehende Alchemisten in Eisenschmiede unter der Anleitung von Vosur Brakthel in...",kw={"alchemie","lagerfeuer","zelten","camping 101: alchemy","eisenschmiede","manabrunnen","vosur brakthel"},ang={["faction:Alliance"]="Angehende Alchemisten, die die Zwergenfestung Eisenschmiede besuchen, können sich an Vosur Brakthel wenden, um zu lernen, wie sie ihre Expeditionen mit stärkenden Gebräuen bereichern können.",["profession:Cooking"]="Ein ordentlicher Lagerplatz erfordert ein einfaches Lagerfeuer – eine praktische Fertigkeit, die von Kochkunstlehrern in allen Reichen gelehrt wird, um spezialisierte Handwerke für das Lagerleben zu ergänzen."},sec={{t="Brauen für die Reise",b="Für Alchemisten, die den ungezähmten Weiten von Azeroth trotzen, ist das Brauen von Phiolen in einem ruhigen Labor nur das halbe Handwerk. In der prächtigen Zwergenhauptstadt Eisenschmiede weist der Alchemist Vosur Brakthel Praktizierende an, wie sie ihr heikles Gewerbe an die Härten des Überlebens in der Wildnis anpassen. Durch den Nachweis von Fertigkeit in der Alchemie lernt ein Abenteurer, sein Wissen in die Erschaffung eines Manabrunnens einfließen zu lassen – eine tragbare Lagerinstallation, die Gefährten im Feld versorgen soll."},{t="Lagerplätze in der Wildnis",b="Während ein Manabrunnen einen erfrischenden Segen für müde Heiler und Zauberkundige bietet, kann er nicht allein mitten auf einer kopfsteingepflasterten Straße stehen. Stadtbewohner sehen es gar nicht gern, wenn Reisende innerhalb städtischer Zentren Zelte aufschlagen, sodass solche Werke in die Wildnis hinausgetragen werden müssen. Zudem ist kein Lager ohne die warmen Gluten eines ordentlichen Lagerfeuers vollständig, was angehende Lagermacher dazu veranlasst, Rat bei einheimischen Köchen zu suchen, bevor sie in die Wildnis aufbrechen."}},faq={{q="Wer ist Vosur Brakthel?",a="Vosur Brakthel ist ein Alchemielehrer, der in der Bergstadt Eisenschmiede ansässig ist. Er unterweist angehende Alchemisten darin, wie sie ihre Erfahrung in der Trankherstellung einsetzen können, um einen Manabrunnen zur Unterstützung von Abenteurern im Feld zu fertigen.",al={"wer lehrt camping 101 alchemy","vosur brakthel rolle","wer ist vosur brakthel"}},{q="Was ist ein Manabrunnen?",a="Ein Manabrunnen ist eine Lagerplatzinstallation, die von einem Alchemisten gebraut wird, um Zauberkundige und Heiler zu stärken. Wenn er in einem Lager in der Wildnis aufgestellt wird, bietet er Zauberwirkern einen erfrischenden Schluck, um ihre mystischen Energien auf langen Reisen wieder aufzufüllen.",al={"was bewirkt ein manabrunnen","zweck des manabrunnens","warum einen manabrunnen herstellen"}},{q="Kann man in Eisenschmiede ein Lager aufschlagen?",a="Die Stadtbewohner sehen es im Allgemeinen nicht gern, wenn innerhalb der Straßen der Stadt Lager aufgeschlagen werden. Alchemisten, die einen Lagerplatz errichten und ihren Manabrunnen aufstellen möchten, müssen über die Stadtmauern hinaus in die Wildnis reisen.",al={"kann man in eisenschmiede zelten","zelten in der stadt","wo manabrunnen platzieren"}},{q="Was wird noch benötigt, um ein Lager aufzuschlagen?",a="Jeder Lagerplatz benötigt ein einfaches Lagerfeuer als Kernstück. Abenteurern, die noch nicht wissen, wie man ein Feuer macht, wird geraten, vor dem Aufbruch einen Kochkunstlehrer aufzusuchen, um das grundlegende kulinarische Feuermachen zu erlernen.",al={"lagerfeuer voraussetzung","wird kochen zum zelten benoetigt","wie man ein lager aufschlaegt"}},{q="Wann kann ein Alchemist lernen, einen Manabrunnen herzustellen?",a="Vosur Brakthel bietet an, Alchemisten zu unterweisen, sobald sie den Beruf ergriffen und ein gewisses Maß an Fertigkeit in ihrem Handwerk bewiesen haben. Sobald sie erfahren genug sind, werden die Geheimnisse des Errichtens eines Manabrunnens vermittelt.",al={"wann kann man manabrunnen lernen","manabrunnen voraussetzungen","camping 101 voraussetzungen"}},{q="Wer profitiert am meisten von einem Manabrunnen im Lager?",a="Der Manabrunnen kommt in erster Linie Zauberkundigen und Heilern wie Magiern, Priestern und Druiden zugute, die stark darauf angewiesen sind, ihre Manavorräte aufzufüllen, während sie sich weit entfernt von städtischen Gasthäusern und Ruhesteinen bewegen.",al={"wer profitiert vom manabrunnen","manabrunnen klassen","wer nutzt den manabrunnen"}}},fp="20,273,20.475.0,20.465.0,22.228.0,20.235.0,39.195.0,37.203.0,48.215.0,43.202.0"}
P.entries["quest:96046"] = {n="Camping 101: Mining",s="Camping 101: Mining unterweist Bergleute in der Herstellung eines Magnetsteins, um Lagerplätze draußen in der Wildnis zu errichten. Es stellt einen wesentlichen Schritt im Überlebenstraining dar und unterstreicht, wie sehr wildes Campen auf der Bearbeitung von Mineralien und einfachem Feuermachen beruht.",h="Camping 101: Mining unterweist Bergleute in der Herstellung eines Magnetsteins, um Lagerplätze draußen in der...",kw={"lagerfeuer","camping","camping 101: mining","lagerplatz","kochkunst","magnetstein","bergbau","wildnis"},ang={["profession:Cooking"]="Das Lagerhandwerk stützt sich eng auf grundlegende kulinarische Fähigkeiten, da jede brauchbare Unterkunft ein richtiges Lagerfeuer erfordert, wie es von Kochlehrern gelehrt wird.",["profession:Mining"]="Bergleute lernen, wie man rohe Erde und Mineralerze zu einem Magnetstein formt, einem unverzichtbaren Instrument zur Verankerung von Wildnislagern im Freien."},sec={{t="Feldfertigkeiten für Bergleute",b="Sich über die Sicherheit bewachter Straßen hinauszuwagen, erfordert Selbstständigkeit und Feldfertigkeiten. Bergleute lernen, ihr Wissen über Mineralien und Gestein anzuwenden, um einen Magnetstein herzustellen – ein Verankerungsstück, mit dem sich ein funktionales Lager in der ungezähmten Welt aufschlagen lässt."},{t="Regeln der Wildnis",b="Sesshafte Leute sehen es gar nicht gern, wenn Reisende mitten auf Marktplätzen oder belebten Durchgangsstraßen Unterkünfte errichten. Das Aufschlagen eines Lagers erfordert es, in die offene Wildnis hinauszuziehen, weit weg von den Stadtgrenzen. Darüber hinaus ist kein Lagerplatz in der Wildnis wirklich funktional ohne ein loderndes Lagerfeuer, um die nächtliche Kälte abzuwehren, was einfache kulinarische Feuerfertigkeiten zu einem unverzichtbaren Begleiter der Mineralienarbeit macht."}},faq={{q="Wozu wird ein Magnetstein verwendet?",a="Ein Magnetstein dient als grundlegendes Werkzeug für Überlebenskünstler der Wildnis, um einen persönlichen Lagerplatz draußen in der Wildnis zu errichten und zu verankern.",al={"verwendungszweck des magnetsteins","wozu dient ein magnetstein","warum magnetstein herstellen"}},{q="Kann ich in einer Ortschaft oder Stadt ein Lager aufschlagen?",a="Stadtbewohner und Siedlungsbehörden sehen es ungerne, wenn Abenteurer auf öffentlichen Plätzen oder Stadtstraßen Zelte aufstellen und lagern, was bedeutet, dass Ihr Euch in die Wildnis hinauswagen müsst, um eines zu errichten.",al={"kann ich in einer stadt zelten","zelten in der stadt","lager innerhalb einer siedlung"}},{q="Was ist erforderlich, bevor man ein Lager aufschlägt?",a="Jedes Lager benötigt ein wärmendes Lagerfeuer, um als vollständig zu gelten. Ihr könnt Euer Lager nicht ordnungsgemäß aufschlagen, ohne dass eines in der Nähe brennt.",al={"brauche ich ein lagerfeuer","wie man ein lager aufschlaegt","voraussetzungen fuer ein lager"}},{q="Wo lerne ich, wie man ein Lagerfeuer macht?",a="Das grundlegende Entfachen von Feuern ist ein wesentlicher Bestandteil der Kochkunst und wird von Kochlehrern und Küchenchefs überall auf Azeroth gelehrt.",al={"wo lagerfeuer lernen","wer lehrt lagerfeuer","lagerfeuer-lehrer"}},{q="Wie hängt Bergbau mit der Herstellung eines Magnetsteins zusammen?",a="Bergleute besitzen das handwerkliche Wissen, das erforderlich ist, um die natürlichen Mineralien und Steine abzubauen und zu bearbeiten, die für die Herstellung eines Magnetsteins benötigt werden.",al={"warum bergleute zelten","bergbau verbindung zu magnetstein","magnetstein herstellen"}},{q="Wohin sollte ich gehen, um mein neues Lager zu testen?",a="Ihr solltet hinter die Stadttore und hinaus in die offene Wildnis ziehen, wo es reichlich freie Fläche und keine missbilligenden Stadtbewohner gibt.",al={"wo lager testen","magnetstein testen","im freien lagern"}}},fp="19,241,21.247.0,17.389.0,29.133.0,40.192.0,42.126.0,41.126.0,48.123.0,38.136.0"}
P.entries["quest:96047"] = {n="Grundlagen des Zeltens: Erste Hilfe",s="Diese Aufgabe leitet angehende Sanitäter in Dun Morogh dazu an, ihre Überlebenskunst über einfache Verbände hinaus zu erweitern. Indem Abenteurer Thamner Pol in Kharanos aufsuchen, lernen sie, wie man eine spezielle Verbandtasche zusammenstellt, um Rastende im Feld am Leben zu halten.",h="Diese Aufgabe leitet angehende Sanitäter in Dun Morogh dazu an, ihre Überlebenskunst über einfache Verbände...",kw={"verbände","camping 101","dun morogh","erste hilfe","verbandtasche","kharanos","überleben","thamner pol"},ang={["faction:Alliance"]="Rekruten der Allianz, die im gefrorenen Herzen von Khaz Modan ausgebildet werden, lernen früh, dass Selbstversorgung und Feldmedizin für jede Militär- oder Expeditionseinheit unverzichtbar sind.",["race:Dwarf"]="Zwergische Gebirgsjäger verlassen sich bei Patrouillen auf den hohen, verschneiten Pässen von Dun Morogh stark auf robuste, praktische Ausrüstung, was eine Verbandtasche im Lager zu einem unverzichtbaren Überlebensgrundbestandteil macht.",["race:Gnome"]="Flüchtlinge und gnomische Wanderer, die von Kharanos aus operieren, halten effiziente Feldmedizin für unbezahlbar, während sie außerhalb der verlorenen Hallen von Gnomeregan überleben."},sec={{t="Wundversorgung in der Wildnis",b="Abenteurer, die den eisigen Weiten von Dun Morogh trotzen, stellen schnell fest, dass Leinenfetzen und hastige Nähte nur der Anfang der Überlebensmedizin sind. Wahres Überleben in der Wildnis hängt oft davon ab, an einem Rastplatz über feste Vorräte zu verfügen. Jene, die Geschick bei der einfachen Wundversorgung beweisen, werden an örtliche Handwerkslehrer in Kharanos verwiesen, die ihnen beibringen können, wie man rohe medizinische Vorräte in vollwertige, auf das Überleben im Lager zugeschnittene Ausrüstung verwandelt."},{t="Die Lehren von Kharanos",b="Im geschäftigen Dorf Kharanos vermittelt Thamner Pol praktische Techniken, um Expeditionslager mit Notfallvorräten auszustatten. Zu wissen, wie man eine richtige Feldausrüstung herstellt, stellt sicher, dass eine ganze Gruppe gemeinsam am Lagerfeuer Schnittwunden verbinden und neue Kraft schöpfen kann, bevor sie sich wieder in die bittere Kälte hinauswagt."}},faq={{q="Was ist der Zweck dieser Aufgabe?",a="Die Aufgabe führt frisch ausgebildete Feldsanitäter zu Thamner Pol in Kharanos, der ihnen beibringt, wie man funktionale Verbandtaschen herstellt, die für die Lagerplätze von Abenteurern gedacht sind.",al={"warum camping 101 erste hilfe machen","was bringt diese quest","ziel von camping 101"}},{q="Wer ist Thamner Pol?",a="Thamner Pol ist ein Ausbilder im Ort Kharanos in Dun Morogh. Er unterweist geübte Überlebenskünstler in der Herstellung berufsbezogener Ausrüstung zur Aufwertung ihrer Wildnislager.",al={"wer ist thamner pol","thamner pol standort","wo ist thamner pol"}},{q="Wo findet diese Ausbildung statt?",a="Die Ausbildung findet in Kharanos statt, der Hauptsiedlung im zentralen Dun Morogh südlich von Eisenschmiede.",al={"wohin muss ich","camping 101 standort","kharanos erste hilfe"}},{q="Warum ist eine Verbandtasche für das Lager wichtig?",a="Verletzungen sind bei Expeditionen in rauer Wildnis keine Seltenheit. Eine spezielle Verbandtasche versorgt rastende Abenteurer mit lebenswichtigen Heilmitteln und ermöglicht es Reisenden, zwischen den Kämpfen Wunden zu verbinden und sich sicher zu erholen.",al={"was bewirkt verbandtasche","warum eine verbandtasche herstellen","nutzen von camping erste hilfe"}},{q="Benötigt man vor dem Aufsuchen von Thamner Pol eine medizinische Ausbildung?",a="Ja. Es wird von Abenteurern erwartet, dass sie bereits die Grundlagen der Ersten Hilfe beherrschen und ein grundlegendes Geschick in diesem Handwerk vorweisen, bevor Thamner Pol ihnen fortgeschrittene Campingrezepte beibringt.",al={"voraussetzungen für camping 101","erste hilfe fertigkeit benötigt","brauche ich zuerst erste hilfe"}},{q="Steht dieses Vorhaben jedem Abenteurer offen?",a="Jeder Abenteurer kann unabhängig von seiner Berufung Erste Hilfe erlernen, was Lagermedizin zu einer pragmatischen Fertigkeit für jeden Reisenden macht, der Dun Morogh durchstreift.",al={"kann das jeder machen","klassenanforderungen","wer kann camp erste hilfe lernen"}}},fp="22,236,26.437.0,23.337.0,33.161.0,19.174.0,36.111.0,38.218.0,62.176.0,39.143.0"}
P.entries["quest:96050"] = {n="Camping 101: Fishing",s="Camping 101: Fishing unterweist Naturbegeisterte in den grundlegenden Fertigkeiten und der Etikette des Überlebens in der Wildnis. Es lehrt Abenteurer, wie man ein dekoratives Fischglas für den eigenen Lagerplatz herstellt, und betont die Notwendigkeit, vor dem Aufbruch in die Wildnis die Kunst des Lagerfeuers bei einem Kochkunstlehrer zu erlernen.",h="Camping 101: Fishing unterweist Naturbegeisterte in den grundlegenden Fertigkeiten und der Etikette des...",kw={"lager","lagerfeuer","camping","kochkunst","fischglas","angeln","wildnis"},ang={["profession:Cooking"]="Das Erlernen der Grundlagen der Kochkunst ist für das Aufschlagen eines Lagers unerlässlich, da kulinarische Ausbilder Reisenden beibringen, wie man das erforderliche Lagerfeuer errichtet."},sec={{t="Wildnisetikette",b="Das Leben auf Reisen quer durch Azeroth erfordert praktisches Wissen über das Grenzland. Für angehende Angler und Wanderer setzt das Errichten eines ordentlichen Lagers das Verständnis grundlegender Benimmregeln im Freien voraus. Stadtbewohner und Wachen sehen es nicht gern, wenn Reisende mitten in Siedlungen Zelte aufschlagen und ihre Ausrüstung verstreuen, daher muss jeder, der rasten möchte, seine Vorräte über die Stadtgrenzen hinaus in die offene Wildnis bringen."},{t="Die Annehmlichkeiten des Lagers",b="Ein richtiger Expeditionsstützpunkt benötigt verschiedene grundlegende Annehmlichkeiten. Vor allem gilt kein Lagerplatz ohne ein wärmendes Lagerfeuer als funktionstüchtig – eine Fertigkeit, die traditionell von kulinarischen Lehrern vermittelt wird. Sobald ein Feuer entfacht ist, können erfahrene Reisende besondere Ausstattungsgegenstände wie ein handgefertigtes Fischglas aufstellen und so einen einfachen Rastplatz in ein voll ausgestattetes Refugium für Angler verwandeln."}},faq={{q="Was lernt Ihr aus Camping 101: Fishing?",a="Diese Lektion lehrt Abenteurer, wie sie ein Fischglas herstellen, um ihren Lagerplatz einzurichten. Sie behandelt die Grundlagen für das Errichten eines Rückzugsortes in der Wildnis, der sich zum Angeln und Entspannen abseits zivilisierter Siedlungen eignet.",al={"was diese quest lehrt","fischglas herstellung","camping angeln belohnung"}},{q="Wo könnt Ihr ein Lager aufschlagen?",a="Lager können nicht mitten in der Stadt aufgeschlagen werden, da Stadtbewohner Anstoß daran nehmen, wenn Reisende sich auf öffentlichen Straßen ausbreiten. Ihr müsst Euch in die Wildnis hinauswagen, um Euren Lagerplatz zu errichten.",al={"wo lager aufschlagen","kann man in der stadt campen","regeln fuer lagerorte"}},{q="Was benötigt Ihr, bevor Ihr ein Lager aufschlagt?",a="Kein Wildnislager gilt ohne ein Lagerfeuer als vollständig. Bevor Ihr damit beginnt, Euer Lager aufzuschlagen, müsst Ihr ein Feuer bereithaben, um den Platz zu verankern und Wärme zu spenden.",al={"wie man ein lager beginnt","braucht man ein lagerfeuer","lager voraussetzungen"}},{q="Wie lernt Ihr, ein Lagerfeuer zu errichten?",a="Kulinarische Ausbilder und Kochkunstlehrer lehren die grundlegende Kunst, ein Lagerfeuer zu entfachen. Diejenigen, die die Grundlagen des Kochens noch nicht erlernt haben, sollten einen Koch aufsuchen, um zu erfahren, wie man eines macht.",al={"wie man ein lagerfeuer macht","wo lagerfeuer lernen","wer feuer lehrt"}},{q="Welchen Zweck erfüllt das Fischglas?",a="Das Fischglas ist eine dekorative Ergänzung, die für einen Lagerplatz im Freien hergestellt wird und jedem reisenden Angler, der einen Außenposten am Wasser errichten möchte, die passende Note verleiht.",al={"wofuer ist das fischglas","camping fischglas nutzung","fischglas lore"}},{q="Warum werden Abenteurern Campinglektionen erteilt?",a="Wildnimentoren bieten praktische Anleitung für das Leben im Grenzland und stellen sicher, dass Wanderer wissen, wie sie sich richtig versorgen, Feuer machen und die Grenzen von Siedlungen respektieren, bevor sie in die Wildnis aufbrechen.",al={"wer camping 101 anbietet","warum campinglektionen","camping ueberlebenshandbuch"}}},fp="20,289,20.399.0,20.374.0,44.210.0,28.186.0,40.164.0,37.187.0,37.170.0,46.200.0"}
P.entries["quest:96055"] = {n="Camping 101: Herbalism",s="Camping 101: Herbalism weist vielversprechende Kräuterkundige an Reyna Stonebranch in Eisenschmiede, um ihr praktisches Handwerk zu erweitern. Sammler lernen, wie man wilde Kräuter zu beruhigenden Räucherkerzen für das Lagerleben kombiniert. Diese aromatischen Schöpfungen für das Feld heben die Stimmung und unterstützen Zauberwirker bei anstrengenden Expeditionen in die Wildnis.",h="Camping 101: Herbalism weist vielversprechende Kräuterkundige an Reyna Stonebranch in Eisenschmiede, um ihr...",kw={"lager","camping 101","kräuterkunde","kräuter","räucherkerze","eisenschmiede","reyna stonebranch"},ang={["faction:Alliance"]="Kräuterkundige der Allianz werden in die Zwergenstadt Eisenschmiede geschickt, um Reyna Stonebranch für die Unterweisung in spezialisiertem Feldhandwerk aufzusuchen.",["profession:Herbalism"]="Sammler, die ihr Pflanzenhandwerk verfeinern, können Räucherkerzen herstellen und so gesammelte Wildniskräuter in aromatische Lagerhilfen für zauberwirkende Verbündete verwandeln.",["race:Dwarf"]="Das Wissen zur Herstellung dieser kräuterkundlichen Lagerhilfen wird in Eisenschmiede von der Kräuterkundelehrerin Reyna Stonebranch bewahrt."},sec={{t="Praktische Feldbotanik",b="Das Sammeln von Kräutern in der gesamten Wildnis ist weit mehr als einfaches Blumenzupfen. Erfahrene Botaniker entdecken, dass geerntete Flora für das praktische Überleben in der freien Natur eingesetzt werden kann, wodurch Reisegruppen mit wertvollem Lagerbedarf versorgt werden. Für Sammler, die ihren Nutzen über das grundlegende Beschaffen von Reagenzien hinaus erweitern möchten, verwandelt das Erlernen spezialisierter Wildnistechniken wilde Pflanzen in unverzichtbare Hilfsmittel."},{t="Aromastoffe für das Lagerfeuer",b="Erfahrene Kräuterkundige werden angewiesen, Reyna Stonebranch in der Bergstadt Eisenschmiede aufzusuchen. Nachdem sie ihr Können im Handwerk unter Beweis gestellt haben, können Kräuterkundige lernen, wie man eine Räucherkerze herstellt. Diese aromatischen Kerzen bringen willkommene Erleichterung in die Lager, heben die Stimmung reisender Gefährten und bieten eine beruhigende Umgebung, die Zauberwirker und Heiler während langer Expeditionen besonders zu schätzen wissen."}},faq={{q="Was ist Camping 101: Herbalism?",a="Camping 101: Herbalism ist eine Ausbildungsanweisung, die geschickte Sammler anleitet zu lernen, wie sie ihr botanisches Handwerk für das Überleben in der freien Natur und das Campen in der Wildnis einsetzen können.",al={"was ist camping 101 herbalism","kräuterkunde camping quest","kräuterkunde lager guide"}},{q="Wer ist Reyna Stonebranch?",a="Reyna Stonebranch ist eine Kräuterkundelehrerin in der großen Zwergenstadt Eisenschmiede, die erfahrenen Kräuterkundigen beibringt, wie man Gegenstände für das Lager herstellt.",al={"wer lehrt räucherkerze","wo ist reyna stonebranch","reyna stonebranch aufenthaltsort"}},{q="Was bewirkt eine Räucherkerze?",a="Eine Räucherkerze ist ein aromatischer Campinggegenstand, der von Kräuterkundigen hergestellt wird und die Stimmung im Lager hebt, indem er eine erfrischende Stärkung bietet, die besonders von Heilern und Zauberwirkern geschätzt wird.",al={"was macht eine räucherkerze","räucherkerze camping","räucherkerze zweck"}},{q="Warum sind Räucherkerzen für Zauberwirker nützlich?",a="Eine gehobene Stimmung hilft dabei, das Durchhaltevermögen aufrechtzuerhalten, was das beruhigende Aroma einer Räucherkerze besonders vorteilhaft für Heiler und Magiewirker macht, die sich zwischen Reisen erholen.",al={"wer profitiert von räucherkerze","ist die räucherkerze für zauberwirker"}},{q="Wohin müssen Kräuterkundige für diese Unterweisung reisen?",a="Die Quest weist Kräuterkundige an, nach Eisenschmiede in Khaz Modan zu reisen, um sich mit Reyna Stonebranch zu treffen, sobald sie angemessenes Geschick beim Sammeln bewiesen haben.",al={"wohin für camping kräuterkunde","welche stadt für camping 101 herbalism"}},{q="Was ist erforderlich, bevor man das Herstellen der Kerze erlernen kann?",a="Kräuterkundige müssen ausreichendes Geschick und praktische Erfahrung beim Sammeln von Kräutern vorweisen, bevor Reyna Stonebranch ihnen die Techniken zur Herstellung von Lagerräucherwerk vermittelt.",al={"wann kann man räucherkerze lernen","kräuterkunde camping voraussetzung"}}},fp="22,311,22.393.0,24.411.0,31.172.0,25.157.0,31.173.0,47.166.0,50.158.0,53.161.0"}
P.entries["quest:96056"] = {n="Camping 101: Skinning",s="Camping 101: Skinning ist eine Einführungsquest, die Abenteurer in der Kunst unterweist, Wildnismöbel aus erbeuteten Tierpelzen herzustellen. Sie weist geübte Kürschner an, Balthus Stoneflayer in Eisenschmiede aufzusuchen, um zu lernen, wie man einen bequemen Lagerstuhl für das eigene Lager herstellt.",h="Camping 101: Skinning ist eine Einführungsquest, die Abenteurer in der Kunst unterweist, Wildnismöbel aus...",kw={"balthus stoneflayer","lagerstuhl","camping","camping 101: skinning","bälge","eisenschmiede","kürschnerei"},ang={["class:Hunter"]="Jäger, die vom Land leben und ihre Beute in der Wildnis kürschnern, profitieren vom Aufbau eines richtigen Lagers, um sich zwischen langen Fährten auszuruhen.",["faction:Alliance"]="Der Pfad zur Herstellung dieser Feldsitzgelegenheit führt geradewegs in die zwergische Bergstadt Eisenschmiede, was die Hauptstadt der Allianz zu einer wichtigen Anlaufstelle für Ledersammler macht.",["race:Dwarf"]="Balthus Stoneflayer ist in Eisenschmiede zu Hause und bietet geübten Kürschnern das zwergische Geheimnis, wie man rohe Bälge in robuste Lagerannehmlichkeiten verwandelt."},sec={{t="Die Ausbeute der Wildnis",b="Das Kürschnern erlegter Wildtiere gehört zu den praktischsten Fertigkeiten, die ein Abenteurer auf seinen Reisen durch die Wildnis von Azeroth erlernen kann. Über die Beschaffung von Rohleder für Rüstungsmacher und Handwerker hinaus können die von Raubkatzen, Bären und Ungetümen gesammelten Bälge direkt im Feld wiederverwendet werden. Diese einleitende Aufgabe weist Kürschner an, Rohmaterialien in praktische Annehmlichkeiten für die Wildnis zu verwandeln, anstatt sie einfach zu verkaufen."},{t="Der Handwerker von Eisenschmiede",b="Die Quest schickt Kürschner aus, um Balthus Stoneflayer in der Zwergenhauptstadt Eisenschmiede aufzusuchen. Balthus kennt die Geheimnisse, wie man zugerichtete Tierpelze in einen funktionellen Lagerstuhl verwandelt. Er verlangt jedoch, dass ein Abenteurer zunächst deutliches Können in der Kunst des Kürschnerns unter Beweis stellt, bevor er einwilligt, seine Handwerkstechniken weiterzugeben."},{t="Rast und Bereitschaft",b="Das Leben auf Reisen fordert von Wanderern und Jägern gleichermaßen einen hohen körperlichen Tribut. Ein robuster Lagerstuhl bietet einem Abenteurer die Möglichkeit, sich am Feuer niederzulassen, auszuspannen und neue Energie sowie geschärfte Sinne zurückzugewinnen. Sich einen Moment zur Erholung zu nehmen stellt sicher, dass der Abenteurer in Spitzenform kämpft und dort zuschlagen kann, wo es zählt, wenn das nächste gefährliche Handgemenge beginnt."}},faq={{q="Was ist Camping 101: Skinning?",a="Camping 101: Skinning ist eine lehrreiche Quest, die geübte Kürschner anweist, in Eisenschmiede eine spezielle Ausbildung im Herstellen von Lagerausstattung aufzusuchen. Sie lehrt Abenteurer, wie man im Feld erbeutete Tierbälge in einen bequemen Lagerstuhl für das persönliche Lager verwandelt.",al={"was ist camping 101 skinning","quest-zweck","camping 101 skinning quest"}},{q="Wer bringt Euch bei, den Campinggegenstand herzustellen?",a="Die Quest weist Euch an, mit Balthus Stoneflayer zu sprechen, einem Handwerksmeister, der in der Bergstadt Eisenschmiede weilt. Sobald Ihr ausreichendes Geschick in Eurem Sammlerberuf bewiesen habt, lehrt er Euch, wie man spezielle Lagerannehmlichkeiten anfertigt.",al={"mit wem sprechen","wer lehrt lagerstuhl","wer ist balthus stoneflayer"}},{q="Wohin müsst Ihr reisen, um diese Quest abzuschließen?",a="Ihr müsst nach Eisenschmiede reisen, der Zwergenhauptstadt, die in den schneebedeckten Gipfeln von Dun Morogh liegt. Balthus Stoneflayer ist in der Stadt zu finden, bereit, qualifizierte Kürschner zu unterweisen.",al={"wohin gehen","standort von balthus","lehrer in eisenschmiede"}},{q="Welchen Gegenstand lernen Kürschner für ihr Lager herzustellen?",a="Ihr lernt, wie man aus erbeuteten Bälgen einen Lagerstuhl herstellt. Das Aufstellen eines bequemen Stuhls ermöglicht es einem Abenteurer, seine Beine im Feld auszuruhen, was ihm dabei hilft, seine Konzentration wiederzuerlangen und zwischen gefährlichen Begegnungen in körperlicher Spitzenform zu bleiben.",al={"was stellt man her","zweck des lagerstuhls","kürschner-lagerhandwerk"}},{q="Warum ist die Herstellung eines Lagerstuhls für einen Abenteurer nützlich?",a="Das Ausruhen in einem bequemen Lagerstuhl bietet auf langen Märschen durch die Wildnis eine lebenswichtige Atempause. Sich Zeit zum Entspannen zu nehmen sorgt dafür, dass ein Abenteurer in bester Kampfform bleibt und mit Präzision zuschlagen kann, wenn unweigerlich ein Kampf entbrennt.",al={"warum einen stuhl herstellen","was bringt lagerstuhl","vorteil von lagerstuhl"}},{q="Welche Fertigkeit ist erforderlich, bevor Balthus Euch unterrichtet?",a="Balthus Stoneflayer wird sein Handwerkswissen erst weitergeben, wenn ein Abenteurer sein Können im Kürschnerhandwerk unter Beweis gestellt hat. Ihr müsst ein solides Geschick im Kürschnern von Wildtieren vorweisen, bevor er Euch das Muster beibringt.",al={"anforderungen","wann kann ich lernen","benötigte fertigkeit"}}},fp="21,281,20.424.0,24.346.0,18.363.0,30.262.0,42.252.0,47.179.0,52.240.0,54.240.0,59.219.0"}
P.entries["quest:96101"] = {n="The Great Outdoors",s="The Great Outdoors ist eine Einführungsquest, die von dem Waldläufer Raan angeboten wird, der unerfahrenen Abenteurern die Grundlagen des Überlebens in der Wildnis beibringt. Indem sie sich an einem einfachen Lagerfeuer ausruhen, um Boosted Rest zu erhalten, erlernen Wanderer wichtige Lagerfertigkeiten, bevor sie sich zu nahegelegenen Berufslehrern begeben, um praktische Berufe zu erlernen.",h="The Great Outdoors ist eine Einführungsquest, die von dem Waldläufer Raan angeboten wird, der unerfahrenen...",kw={"einfaches lagerfeuer","boosted rest","lager-ausstattung","lagerfeuer","raan","the great outdoors","beruf","überleben in der wildnis"},ang={["class:Hunter"]="Das Überleben in der Wildnis beginnt mit den Grundlagen der Lagerfertigkeit, einer unverzichtbaren Disziplin für Fährtenleser und Waldläufer, die daran gewöhnt sind, unter freiem Himmel zu leben.",["profession:Cooking"]="Sich um ein einfaches Lagerfeuer zu versammeln, um sich auszuruhen und zu erholen, liegt Lagerköchen im Blut, die auf offene Flammen angewiesen sind, um reisende Gruppen in der Wildnis zu versorgen."},sec={{t="Lektionen in der Wildnis",b="The Great Outdoors dient als Einführungslektion für das Überleben jenseits der Sicherheit von Siedlungsmauern. Die von einem erfahrenen Wildnisreisenden namens Raan angebotene Aufgabe erinnert wandernde Abenteurer daran, dass bloßer Ehrgeiz und Stahl nutzlos sind ohne die praktischen Lagerfertigkeiten, die man benötigt, um den rauen Elementen zu trotzen. Raan heißt angehende Wanderer in den Reihen ruheloser Seelen willkommen, die nach Glück und Ruhm suchen, und bietet denjenigen praktische Anleitung, die bereit sind zu lernen."},{t="Die Wärme des Herdes",b="Die Kernanforderung der Lektion ist täuschend einfach: Platz an Raans einfachem Lagerfeuer zu nehmen, bis die Wärme den Effekt Boosted Rest verleiht. Draußen in den weiten, ungezähmten Gebieten von Azeroth kann das Wissen darüber, wie man innehält, ein Lager aufschlägt und sich erholt, den Unterschied zwischen Leben und Tod bedeuten. Sobald die Grundlagen des Lagerns gemeistert sind, weist Raan Neulinge an lokale Dorflehrer, um ein Handwerk zu ergreifen und zu lernen, spezialisierte Lagereinrichtungen herzustellen."}},faq={{q="Wer vergibt die Quest The Great Outdoors?",a="Die Quest wird von Raan angeboten, einem erfahrenen Reisenden, der Potenzial in wandernden Abenteurern erkennt und ihnen die Grundlagen des Überlebens in der offenen Wildnis beibringt.",al={"wer bietet the great outdoors an","questgeber the great outdoors","raan lagerfeuer quest"}},{q="Was ist der Zweck von The Great Outdoors?",a="Sie führt Abenteurer in die Grundlagen des Überlebens in der Wildnis ein und zeigt, wie das Ausruhen an einem einfachen Lagerfeuer Behaglichkeit, Erholung und die gesteigerte Rast bietet, die man vor dem Antreten gefährlicher Reisen benötigt.",al={"was lehrt the great outdoors","the great outdoors zweck","was lerne ich von raan"}},{q="Wie wird die Quest abgeschlossen?",a="Um die Lektion abzuschließen, nehmt an Raans einfachem Lagerfeuer Platz und ruht Euch dort aus, bis Ihr den Stärkungszauber Boosted Rest erhaltet, was zeigt, dass Ihr versteht, wie man sich im Feld erholt.",al={"wie man the great outdoors abschließt","raan lagerfeuer ziel","boosted rest ziel"}},{q="Was schlägt Raan nach Abschluss der Quest vor?",a="Nach Abschluss der Lagerfeuerlektion ermutigt Raan Euch, Ausbilder im nahegelegenen Dorf aufzusuchen, um einen Beruf zu erlernen, und merkt an, dass Handwerker auf ihr Handwerk zugeschnittene Lagereinrichtungen herstellen können.",al={"was rät raan als nächstes","wohin nach the great outdoors","nach abschluss von the great outdoors"}},{q="Was ist Boosted Rest?",a="Boosted Rest ist der erholende Effekt, den man durch das Einlegen einer Rast an einem errichteten Lagerfeuer erhält und der reisenden Abenteurern eine verbesserte Erholung gewährt, während sie den Elementen trotzen.",al={"was ist boosted rest","lagerfeuer boosted rest stärkungszauber"}},{q="Ermöglichen es Berufe Abenteurern, Lagereinrichtungen herzustellen?",a="Ja, örtliche Berufslehrer können Handwerker darin unterweisen, wie man funktionale, für ihr gewähltes Handwerk geeignete Lagereinrichtungen herstellt, was es Reisenden ermöglicht, spezialisierte Lageraufbauten im Freien aufrechtzuerhalten.",al={"können berufe lagerfeuer herstellen","berufslager-ausstattung","handwerkslager-gegenstände"}}},fp="18,319,19.453.0,24.453.0,39.174.0,42.211.0,27.175.0,56.190.0,21.174.0,60.193.0"}
P.entries["quest:96130"] = {n="Chakuyak",s="Chakuyak ist ein außergewöhnlich aggressiver Präriewolf, der durch die Baumbestände westlich des Stonebullsees in Mulgore streift. Da sie eine wachsende Bedrohung für vorbeiziehende Reisende darstellt, wurde sie von den einheimischen Stammesangehörigen zur Jagd freigegeben, die die Region sichern und zugleich den Balg der erlegten Bestie ehren wollen.",h="Chakuyak ist ein außergewöhnlich aggressiver Präriewolf, der durch die Baumbestände westlich des...",kw={"chakuyak","mulgore","präriewolf","stonebullsee","taurenjagd","reisende","wolfsbalg"},ang={["class:Hunter"]="Das Aufspüren eines ungewöhnlich wilden, einsamen Alphawolfs in den bewaldeten Hügeln erfordert Geduld, scharfe Sinne und Respekt vor wilden Raubtieren.",["race:Tauren"]="Die Jagd spiegelt das Ethos der Tauren wider, die Ehrfurcht vor den Geschöpfen der Natur mit der praktischen Pflicht in Einklang zu bringen, den Stamm zu schützen und erlegte Bestien durch die Verwertung ihrer Bälge zu ehren."},sec={{t="Der Schatten des Stonebullsees",b="Unter den Präriewölfen, die die grasbewachsenen Hochebenen und sanften Hügel von Mulgore durchstreifen, hat sich ein außergewöhnlich wildes Alphaweibchen namens Chakuyak durch ihre unerbittliche Aggression hervorgetan. Sie lauert in den Baumbeständen westlich des Stonebullsees und hat sich von gewöhnlichem Wild zu einer direkten Gefahr für aus der Ferne eintreffende Reisende gewandelt, was einheimische Jäger dazu veranlasste, sie zur Beseitigung freizugeben, bevor unschuldige Wanderer zu Schaden kommen."},{t="Ehrfurcht und Notwendigkeit",b="Für die einheimischen Stämme begegnet man dem Beenden des Lebens eines prächtigen Raubtiers wie Chakuyak mit düsterer Ehrfurcht statt mit prahlerischer Grausamkeit. Sie zu erlegen, gilt als notwendiger Schutz für Reisende wie Dorfbewohner gleichermaßen. Den nomadischen Bräuchen folgend wird ihr dichter Balg zurückgebracht, um sorgfältig gegerbt und verwertet zu werden, damit der Geist und das Opfer des großen Wolfs geehrt und nicht verschwendet werden."}},faq={{q="Wer oder was ist Chakuyak?",a="Chakuyak ist ein ungewöhnlich aggressiver und großer Präriewolf, der die Hügel nahe dem Stonebullsee in Mulgore durchstreift. Sie hat sich aufgrund der Bedrohung, die sie für Reisende darstellt, welche die Region durchqueren, einen eigenen Namen gemacht.",al={"was ist chakuyak","wer ist chakuyak","ist chakuyak ein wolf"}},{q="Wo befindet sich Chakuyak?",a="Chakuyak durchstreift das bewaldete Gelände direkt westlich des Stonebullsees und zieht heimlich zwischen den Baumbeständen entlang der Hügel umher.",al={"wo man chakuyak findet","chakuyak standort","wo streift chakuyak umher"}},{q="Warum muss Chakuyak gejagt werden?",a="Während einheimische Präriewölfe ein natürlicher Bestandteil der Tierwelt von Mulgore sind, ist Chakuyak ungewöhnlich kühn und aggressiv geworden und bedroht Reisende, die das Gebiet von außerhalb betreten, ganz direkt.",al={"warum chakuyak töten","chakuyak bedrohung"}},{q="Was geschieht nach der Jagd mit Chakuyaks Balg?",a="Der Questgeber stellt sicher, dass das Nehmen des Lebens einer solch prächtigen Bestie nicht umsonst ist; ihr Balg wird konserviert und sinnvoll genutzt, damit nichts verschwendet wird.",al={"was passiert mit chakuyaks balg","chakuyak fell"}},{q="Brauche ich eine Gruppe, um Chakuyak zu jagen?",a="Chakuyak ist im Vergleich zu gewöhnlichen Wölfen außergewöhnlich wild und gefährlich, und Reisende schließen sich oft in kleinen Jagdgruppen zusammen, um sie sicher aufzuspüren und zu erlegen.",al={"gruppe für chakuyak nötig","ist chakuyak alleine schwer"}},{q="Wer erkennt Euren Sieg über Chakuyak an?",a="Der Jäger, der die Aufgabe vergibt, verspricht, nach der Bezwingung der Bestie und der Rückgabe ihres Balgs direkt beim Häuptling des Stammes ein hohes Lob für Eure Tat auszusprechen.",al={"wer belohnt die jagd auf chakuyak","chakuyak häuptling"}}},fp="8,280,28.419.0,23.408.0,24.208.0,26.125.0,33.182.0,47.156.0,35.170.0,44.157.0"}
P.entries["quest:962"] = {n="Schlangenflaum",s="Schlangenflaum ist eine Sammelaufgabe von Apothecary Zamah, einer Gesandten der Königlichen Apothekervereinigung, die in Donnerfels weilt. Zamah sucht nach Proben eines seltenen Krauts, das in den unterirdischen Tiefen der Höhlen des Wehklagens heimisch ist, um die Forschung der Verlassenen zu unterstützen.",h="Schlangenflaum ist eine Sammelaufgabe von Apothecary Zamah, einer Gesandten der Königlichen...",kw={"apotheker","brachland","königliche apothekervereinigung","schlangenflaum","die anhöhe der geister","donnerfels","unterstadt","die höhlen des wehklagens","zamah"},ang={["faction:Horde"]="Diese Aufgabe festigt das frühe operative Bündnis zwischen Unterstadt und den Stämmen Kalimdors, indem Ressourcen und seltene Reagenzien über das Meer hinweg geteilt werden.",["profession:Herbalism"]="Die verzerrte Umgebung im Inneren der Höhlen des Wehklagens bringt eine einzigartige Flora hervor, die nirgendwo sonst auf der sonnenverbrannten Oberfläche des Brachlands zu finden ist.",["race:Tauren"]="Die Beherbergung von Apothekern der Verlassenen unter der Anhöhe der Geister spiegelt die Gastfreundschaft der Horde wider, auch wenn ihr Fokus auf tödliche Gebräue im Gegensatz zur traditionellen Erdheilung steht.",["race:Undead"]="Der Beitrag von Schlangenflaum unterstützt direkt die alchemistischen Initiativen der Königlichen Apothekervereinigung in Lordaeron unter dem Mandat der Dunklen Fürstin."},sec={{t="Augen der Apothekerin",b="Stationiert in den Teichen der Visionen unter der Anhöhe der Geister in Donnerfels, dient Apothecary Zamah als Gesandte der Königlichen Apothekervereinigung aus Unterstadt. Während sich die Tauren-Gastgeber auf das spirituelle Gleichgewicht und die Heilung des verwundeten Landes konzentrieren, gilt Zamahs Aufmerksamkeit seltenen und virulenten Stoffen. Nachdem sie eine Probe einer ungewöhnlichen Pflanze namens Schlangenflaum isoliert hat, sucht sie nach größeren Mengen, um die Forschungsrichtlinien von Fürstin Sylvanas Windläufer und den Verlassenen voranzutreiben."},{t="Die Tiefen der Höhlen",b="Schlangenflaum wächst nicht unter der offenen Sonne des Brachlands, sondern gedeiht stattdessen in den feuchten, verwinkelten Grotten der Höhlen des Wehklagens. Herangewachsen im feuchten unterirdischen Klima, das von den verdorbenen Druiden des Giftzahns verzerrt wurde, ist die Pflanze schwer zu erreichen und wird von den schlangenartigen Bewohnern der Höhle erbittert bewacht. Zamah räumt unumwunden ein, dass zahlreiche zuvor ausgesandte Späher nicht zurückgekehrt sind, sodass das weitere Sammeln abgehärteten Abenteurern überlassen bleibt."}},faq={{q="Wer ist Apothecary Zamah?",a="Apothecary Zamah ist eine Forscherin, die die Königliche Apothekervereinigung von Unterstadt vertritt. Stationiert in den Teichen der Visionen unter Donnerfels' Anhöhe der Geister fungiert sie als Bindeglied zwischen den Alchemisten der Verlassenen und dem weiteren Kontinent Kalimdor.",al={"zamah","apothekerin zamah lore","wer vergibt schlangenflaum"}},{q="Warum will die Königliche Apothekervereinigung Schlangenflaum?",a="Zamah glaubt, dass das Kraut bei der Veredelung in großen Mengen ein beträchtliches latentes chemisches Potenzial besitzt. Die Vereinigung sucht in ganz Kalimdor aktiv nach seltener, wirksamer Flora, die den alchemistischen Experimenten der Verlassenen nützen kann.",al={"warum schlangenflaum","kräuterforschung der verlassenen","zweck von schlangenflaum"}},{q="Wo wächst Schlangenflaum?",a="Schlangenflaum wächst ausschließlich in den unterirdischen Gefilden der Höhlen des Wehklagens, eingebettet in die feuchten Steinkorridore und unterirdischen Gänge unter dem nördlichen Brachland.",al={"wo ist schlangenflaum","schlangenflaum fundort"}},{q="Warum sind vorherige Späher nicht zurückgekehrt?",a="Die Höhlen des Wehklagens werden von degenerierten Bestien, Raptoren und den verdorbenen Druiden des Giftzahns überrannt. Weniger erfahrene Sammler, die in die labyrinthischen Tunnel geschickt wurden, wurden schnell von der räuberischen Fauna und den giftigen Verteidigern der Höhle überwältigt.",al={"vermisste späher","zamahs späher","sind die höhlen des wehklagens gefährlich"}},{q="Befürworten die Tauren Zamahs Forschung?",a="Die Tauren von Donnerfels gewährten den Verlassenen aus Mitgefühl und dem Wunsch, sie zu heilen, Zuflucht, doch die alchemistischen Praktiken der Königlichen Apothekervereinigung grenzen oft an unnatürliche Experimente, die traditionelle Schamanen und Druiden beunruhigen.",al={"reaktion der tauren","apotheker auf der anhöhe der geister"}},{q="Erfordert das Sammeln von Schlangenflaum Fertigkeiten in Kräuterkunde?",a="Nein. Obwohl es sich um ein botanisches Exemplar handelt, kann jeder Abenteurer, der gewillt ist, den Tiefen der Höhlen des Wehklagens zu trotzen, die Pflanzen direkt vom Höhlenboden pflücken, ohne eine formelle Ausbildung in Kräuterkunde zu besitzen.",al={"braucht man kräuterkunde","beruf zum sammeln von schlangenflaum"}}},fx={["962715c8"]={q="Warum möchte Apothecary Zamah, dass Schlangenflaum gesammelt wird?",a="Apothecary Zamah wurde von der Königlichen Apothekervereinigung mit einem speziellen Auftrag nach Donnerfels entsandt, um die Interessen der Verlassenen und der Dunklen Fürstin, Fürstin Sylvanas Windläufer, zu fördern. Nachdem sie eine seltene Probe von Schlangenflaum analysiert hat, sieht Zamah ein enormes Potenzial in dessen Eigenschaften, wenn er in beträchtlichen Mengen beschafft wird. Die Sicherung von genügend Exemplaren ermöglicht es ihrer Forschung, die wissenschaftlichen und alchemistischen Ambitionen der Unterstadt voranzutreiben.",al={"apothecary zamah motiv","warum braucht zamah schlangenflaum","warum schlangenflaum sammeln"}},["92b49307"]={q="Warum schickt Apothecary Zamah einen Abenteurer, anstatt Schlangenflaum selbst zu sammeln?",a="Zamah kann ihren Posten in Donnerfels nicht ohne Weiteres verlassen, und das Ernten des Krauts erfordert das Vordringen in die tückischen, verdorbenen Tiefen der Höhlen des Wehklagens. Sie hat bereits mehrere Späher und Agenten in ihr Höhlensystem entsandt, aber keiner von ihnen kehrte lebend zurück. Sie braucht erfahrene, fähige Abenteurer, die bereit sind, jenen dunklen Winkeln zu trotzen, an denen gewöhnliche Späher gescheitert sind.",al={"warum mich für schlangenflaum schicken","warum besorgt zamah den schlangenflaum nicht","warum abenteurer für schlangenflaum"}}},fp="12,259,22.476.0,25.436.0,24.253.0,56.226.0,29.188.0,37.240.0,42.259.0,54.188.0"}
P.entries["quest:96243"] = {n="Call of Earth",s="Call of Earth ist eine einführende Aufforderung, die einen Initianden dazu aufruft, sich mit den Geistern des Steins abzustimmen. Ins Coldridgetal gewiesen, muss der Reisende Teo Hammerstorm innerhalb der Zwergenfeste Ambossar aufsuchen.",h="Call of Earth ist eine einführende Aufforderung, die einen Initianden dazu aufruft, sich mit den Geistern des...",kw={"ambossar","call of earth","das coldridgetal","dun morogh","erdtotem","elemente","schamane","teo hammerstorm"},ang={["class:Shaman"]="Dem Ruf der Erde zu folgen ist ein grundlegender Schritt auf dem schamanischen Pfad, der den Initianden an den tiefen Stein und die standhaften Geister des Landes bindet.",["faction:Alliance"]="Schamanen der Allianz in Dun Morogh beginnen ihre elementare Reise direkt in der uralten Zwergenfeste Ambossar.",["race:Dwarf"]="Zwerge teilen eine angeborene Verbindung zu Stein und Erde, wodurch sich die Zwiesprache mit diesen irdischen Geistern inmitten der tiefen Gewölbe von Dun Morogh ganz natürlich anfühlt."},sec={{t="Die Stimme des Steins",b="Für einen Initianden, der den Pfad der Elemente beschreitet, ist der Ruf der Erde die entscheidende erste Zwiesprache. Während elementare Energien bereits über die Haut strömen mögen, schafft das Erlernen des direkten Gesprächs mit dem Stein ein standhaftes Gleichgewicht. Es lehrt den Geist, unerschütterliche Kraft zu finden, und verleiht den eigenen Stiefeln sowie dem Geist selbst festen Stand."},{t="Die Feste Ambossar",b="Initianden in den verschneiten Weiten von Dun Morogh werden zum Schutz von Ambossar geleitet, einer gewaltigen Feste, geschmiedet durch Hammer, Feuer und Willenskraft. In dieser ehrwürdigen Bastion im Coldridgetal wartet Teo Hammerstorm, der angehende Schamanen darin unterweist, auf die grollende Erde zu lauschen und ihre elementaren Pflichten aufzunehmen."}},faq={{q="Was ist Call of Earth?",a="Call of Earth ist eine einleitende Aufforderung, die einen angehenden Schamanen anweist, die Zwiesprache mit den Erdgeistern zu beginnen. Sie weist den Initianden an, Führung zu suchen und sich in der Kraft des lebendigen Steins zu erden.",al={"was ist call of earth","call of earth quest","was ist diese quest"}},{q="Wer ist Teo Hammerstorm?",a="Teo Hammerstorm ist ein Mentor innerhalb der Zwergenfeste Ambossar im Coldridgetal. Er leitet Initianden dabei an, mit der Erde Zwiesprache zu halten und ihre beständige Stärke zu verstehen.",al={"wer ist teo hammerstorm","wo ist teo hammerstorm","teo hammerstorm standort"}},{q="Was ist Ambossar?",a="Ambossar ist eine wehrhafte Feste, geschmiedet durch Hammer, Feuer und Willenskraft, gelegen in den verschneiten Weiten des Coldridgetals in Dun Morogh. Sie dient als zentrale Bastion und Ausbildungsstätte für junge Helden.",al={"wo ist ambossar","was ist ambossar","ambossar standort"}},{q="Warum muss ein Schamane dem Ruf der Erde folgen?",a="Die Zwiesprache mit der Erde ermöglicht es einem Schamanen, seine spirituelle Essenz zu erden, was sowohl festen Halt unter seinen Sohlen als auch in seiner Seele schafft, damit er die beständige Macht des Steins kanalisieren kann.",al={"warum mit der erde sprechen","zweck von call of earth","schamane erdverbindung"}},{q="Wer nimmt diese Vorladung auf sich?",a="Die Quest richtet sich an angehende Schamanen, die ihre Reise in Dun Morogh beginnen, und weist sie an, erfahrene Elementarlehrer aufzusuchen, die ihre Verbindung zu den Geistern leiten können.",al={"wer schickt call of earth","wer nimmt call of earth an","wer macht diese quest"}},{q="Wohin führt diese Quest?",a="Die Reise führt nach Ambossar, eingebettet im Coldridgetal im verschneiten Reich von Dun Morogh. Initianden müssen sich in das Innere der Feste begeben, um ihren Mentor zu finden.",al={"wo findet call of earth statt","call of earth zone","wohin gehen"}}},fp="13,215,18.352.0,24.313.0,22.211.0,23.185.0,17.201.0,41.190.0,28.173.0,27.161.0"}
P.entries["quest:963"] = {n="In ewiger Liebe",s="„In ewiger Liebe“ ist eine tragische Quest, die von Cerellean Weißklaue in Auberdine vergeben wird. Von den Erinnerungen an seine verlorene Geliebte Anaya Dawnrunner heimgesucht, bittet Cerellean einen Abenteurer, zu den zerschmetterten Ruinen von Ameth'Aran zu reisen, um ihren rastlosen Geist aus einer Ewigkeit der Qual zu befreien.",h="„In ewiger Liebe“ ist eine tragische Quest, die von Cerellean Weißklaue in Auberdine vergeben wird.",kw={"ameth'aran","anaya dawnrunner","anayas anhänger","auberdine","cerellean weißklaue","dunkelküste","in ewiger liebe","zerschlagung"},ang={["class:Druid"]="Cerelleans Schicksal spiegelt den persönlichen Preis wider, den die Druiden zahlten, die sich an der Seite von Shan'do Sturmgrimm in einen jahrtausendelangen Schlummer begaben, nur um festzustellen, dass die erwachte Welt noch immer von ihren uralten Verlusten gezeichnet war.",["faction:Alliance"]="Cerellean zu helfen gewährt Helden der Allianz einen Einblick in das tragische, jahrtausendeumspannende Leben ihrer nachtelfischen Verbündeten, während diese sich an die erwachte Welt gewöhnen.",["race:NightElf"]="Für die Nachtelfen der Dunkelküste ist die Hilfe für Cerellean eine ergreifende Erinnerung an die bleibenden Narben, die die Große Zerschlagung und der Fall ihrer uralten Städte hinterlassen haben."},sec={{t="Ein Schlummer voller Kummer",b="Vor zehntausend Jahren während des Krieges der Ahnen riss die Katastrophe um den Brunnen der Ewigkeit das alte Kalimdor auseinander. Zu den Opfern zählte die Stadt Ameth'Aran, in der Cerellean Weißklaue seine Geliebte Anaya Dawnrunner verlor. Von Verzweiflung ergriffen folgte Cerellean Shan'do Malfurion Sturmgrimm in den langen Winterschlaf der Druiden, in der Hoffnung, die im Smaragdgrünen Traum verbrachten Jahrtausende würden sein schmerzendes Herz beruhigen. Stattdessen hielt seine Trauer nur an und begleitete ihn durch die Zeitalter."},{t="Der Geist von Ameth'Aran",b="Als Cerellean in jüngster Zeit erwachte, wanderte er wie betäubt durch die Dunkelküste, bis seine Schritte ihn zurück zu den melancholischen Ruinen von Ameth'Aran führten. Dort erblickte er zwischen den uralten Steinen den gequälten Geist von Anaya. Da er es nicht ertragen konnte, eine Waffe gegen die Frau zu erheben, die er liebte, fleht er vorbeireisende Wanderer an, ihre gepeinigte Manifestation zu vernichten, ihren Anhänger zu bergen und ihrer ruhelosen Seele endlich Frieden zu schenken."},{t="Abschied jenseits des Schleiers",b="Als Anayas Anhänger nach Auberdine zurückgebracht wird, erscheint ein spektrales Überbleibsel von Anaya ein letztes Mal vor Cerellean. Befreit von der anhaltenden Pein, die sie an die Ruinen band, verabschiedet sie sich kurz von ihm, bevor sie im Äther verblasst und den trauernden Druiden in bittersüßem Trost an der Küste weinend zurücklässt."}},faq={{q="Wer ist Cerellean Weißklaue?",a="Cerellean Weißklaue ist ein Nachtelfendruide, der in Auberdine weilt. Nachdem er seine geliebte Anaya während der Zerschlagung vor zehntausend Jahren verloren hatte, begab er sich an der Seite von Shan'do Malfurion Sturmgrimm in den langen druidischen Winterschlaf und trug seinen unheilbaren Kummer über Jahrtausende hinweg mit sich.",al={"cerellean weißklaue","wer vergibt in ewiger liebe","cerellean lore"}},{q="Wer war Anaya Dawnrunner?",a="Anaya Dawnrunner war eine Nachtelfe, die vor der Großen Zerschlagung in der Stadt Ameth'Aran lebte. Sie wurde getötet, als die Stadt in den Nachwehen des Krieges der Ahnen fiel, und ihr Geist ist seither in den Ruinen gefangen.",al={"anaya dawnrunner","wer ist anaya","anaya dunkelküste"}},{q="Wo befindet sich Anayas Geist?",a="Ihr Geist wandert durch die uralten, von Geistern heimgesuchten Ruinen von Ameth'Aran im Süden der Dunkelküste, östlich der Hauptstraße.",al={"anaya standort","wo ist anaya dawnrunner","anayas anhänger standort"}},{q="Warum konnte Cerellean Anaya nicht selbst befreien?",a="Trotz des Vergehens von zehntausend Jahren war Cerelleans Liebe zu Anaya so tief, dass er es nicht ertragen konnte, selbst die Hand gegen ihre Erscheinung zu erheben oder einen Zauber gegen sie zu wirken, selbst um ihr Leiden zu beenden.",al={"warum tötet cerellean anaya nicht","warum cerellean um hilfe bittet"}},{q="Was geschah mit Ameth'Aran?",a="Ameth'Aran war eine uralte Nachtelfensiedlung, die vor zehn Jahrtausenden während der Zerschlagung nach dem Krieg der Ahnen zerstört wurde. Ihre Ruinen an der Dunkelküste sind noch immer voller verweilender Geister und arkaner Echos.",al={"ameth'aran geschichte","fall von ameth'aran","was ist ameth'aran"}},{q="Was geschieht, wenn Ihr Anayas Anhänger zurückbringt?",a="Bringt Anayas Anhänger zu Cerellean in Auberdine, nachdem Ihr ihren gequälten Geist befreit habt. Das Ergebnis der Abgabe offenbart sich, wenn Ihr zurückkehrt.",al={"questabgabe anaya","cerellean ende","in ewiger liebe ende"}}},fx={dc23d6a3={q="Warum möchte Cerellean Weißklaue Anayas Geist befreit wissen?",a="Cerellean glaubte, seine Liebe, Anaya, sei vor Jahrtausenden umgekommen, als Ameth'Aran während des Großen Bruchs zerstört wurde. Die Entdeckung ihres ruhelosen, gequälten Geistes, der durch die Ruinen wandert, brach ihm das Herz. Da er weiß, dass sie an dieses Reich gebunden leidet, erträgt er den Gedanken nicht, dass sie in Qual bleibt, doch er bringt es nicht über sich, selbst Hand an sie zu legen.",al={"warum möchte cerellean das erledigt haben","cerellean motiv","warum anayas geist vernichten"}},ed60ea9d={q="Wozu dient Anayas Anhänger?",a="Anayas Anhänger ist das Andenken, das Cerellean Euch bittet zurückzubringen, nachdem Ihr ihren gequälten Geist in Ameth'Aran befreit habt.",al={"verwendung von anayas anhänger","was bewirkt anayas anhänger","zweck von anayas anhänger"}}},fp="16,272,23.504.0,23.431.0,23.312.1,27.264.0,25.241.0,32.126.0,42.217.0,28.223.0,45.138.1"}
P.entries["quest:96339"] = {n="Legacy Reward: Replica Ironforge Air Rifle",s="Legacy Reward: Replica Ironforge Air Rifle markiert die Abholung eines mysteriösen Pakets, das für Euch aufbewahrt wurde. Von einem unidentifizierten Boten hinterlassen, wurde das Paket nur knapp davor bewahrt, ins Meer geworfen zu werden, bevor es Eure Hände erreichte.",h="Legacy Reward: Replica Ironforge Air Rifle markiert die Abholung eines mysteriösen Pakets, das für Euch...",kw={"luftgewehr","eisenschmiede","luftgewehr aus eisenschmiede","legacy-belohnung","mysteriöses paket","replik des ironforge-luftgewehrs"},ang={["profession:Engineering"]="Tüftler und Büchsenmacher werden es zu schätzen wissen, ein kunstvolles Schusswaffenmodell zu erhalten, selbst wenn es über einen gleichgültigen Boten eintraf und beinahe auf dem Grund des Ozeans gelandet wäre.",["race:Dwarf"]="Das Paket enthält eine Replik eines Luftgewehrs aus Eisenschmiede, eine ehrende Verbeugung vor den berühmten Schusswaffen und der mechanischen Handwerkskunst von Khaz Modan."},sec={{t="Ein auf Abholung wartendes Paket",b="Ein mysteriöses Paket, das eigens an Euch adressiert war, wurde bei einem widerwilligen Verwalter abgegeben. Der unbekannte Bote bestand darauf, dass Ihr eintreffen würdet, um es abzuholen, und verschwand so rasch, dass der Empfänger die Annahme nicht einmal verweigern konnte. Glücklicherweise traft Ihr kurz davor ein, bevor die nicht abgeholte Kiste zusammen mit dem Unrat des Abends in den Ozean geworfen wurde."},{t="Zwergeningenieurskunst im Kleinformat",b="Im zugestellten Paket befindet sich eine Replik des Ironforge-Luftgewehrs, ein Souvenir zu Ehren der berühmten Schusswaffentraditionen der Zwergenhauptstadt. Während zwergische Gebirgsjäger und Scharfschützen tödliche Feuerkraft durch Dun Morogh tragen, feiern Repliken wie diese die kunstvollen Läufe und pneumatischen Mechanismen, die von Handwerkern aus Eisenschmiede perfektioniert wurden."}},faq={{q="Wer hat dieses Paket geschickt?",a="Der Bote oder ursprüngliche Absender hinterließ weder einen Namen noch eine Erklärung. Laut dem Empfänger, der es aufbewahrte, gab jemand das eigens an Euch adressierte Paket einfach ab, bestand darauf, dass Ihr schließlich eintreffen würdet, um es abzuholen, und verschwand, bevor Fragen gestellt werden konnten.",al={"wer hat das paket geschickt","absender des luftgewehrs","wer hat das gewehr hinterlassen"}},{q="Was wäre beinahe mit dem Paket geschehen?",a="Wärt Ihr nicht rechtzeitig eingetroffen, wäre das Paket zusammen mit dem nächtlichen Müll ins Meer geworfen worden. Der Verwalter gab zu, keinen Lagerdienst zu betreiben und unerwünschten Unrat routinemäßig im Ozean zu entsorgen.",al={"was sollte mit dem paket geschehen","müll im meer","paket weggeworfen"}},{q="Was befindet sich in dem Paket?",a="Das Paket enthält eine Replik des Ironforge-Luftgewehrs, geliefert als Legacy-Gegenstand, der eigens für Euch bestimmt ist. Es dient als Erinnerungsstück, das zwergische Schusswaffenkonstruktion repräsentiert.",al={"was ist im paket","inhalt replikagewehr","paketbelohnung"}},{q="Warum hat der Verwalter das Paket aufbewahrt?",a="Der Verwahrer stellte klar, dass er keine Postaufbewahrung oder Lagerdienste anbietet. Das Paket wurde nur behalten, weil der geheimnisvolle Bote es so eilig hatte, dass es keine Gelegenheit gab, die Annahme zu verweigern, bevor er verschwand.",al={"warum wurde es aufbewahrt","post aufbewahren","bewahrt dieser ort pakete auf"}},{q="Warum wird dies als Legacy-Belohnung betrachtet?",a="Legacy-Belohnungen in WoW Forever stellen besondere Anerkennungen und Pakete dar, die von geheimnisvollen Wohltätern für erfahrene Abenteurer hinterlassen wurden und an bestimmten Außenposten darauf warten, bei Eurer Ankunft abgeholt zu werden.",al={"warum heißt es legacy-belohnung","legacy-belohnung lore","was bedeutet legacy hier"}},{q="Ist die Gewehrreplik eine funktionstüchtige Waffe?",a="Es wird ausdrücklich als Replik eines Luftgewehrs aus Eisenschmiede beschrieben, das den fein konstruierten zwergischen Fernkampfwaffen nachempfunden ist, anstatt ein Kampfgewehr für die Front zu sein.",al={"ist das gewehr eine echte waffe","kann man damit schießen","funktion der replik"}}},fp="42,239,29.337.0,32.333.0,22.273.0,36.226.0,26.178.0,42.224.0,39.202.0,41.169.0"}
P.entries["quest:96390"] = {n="Erstickt sie im Keim",s="Erstickt sie im Keim ist eine von Erdseher Farsen erteilte Mission zur Beseitigung von Dunkeleisenspionen, die Dun Morogh infiltrieren. Die heimlichen Agenten wurden in der Nähe von Eisenbands Truppenlager gesichtet und bedrohen die Sicherheit der Heimat der Bronzebärte.",h="Erstickt sie im Keim ist eine von Erdseher Farsen erteilte Mission zur Beseitigung von Dunkeleisenspionen...",kw={"dunkeleisenkarte","dunkeleisenspion","dun morogh","erdseher farsen","die halle der thanen","eisenbands truppenlager","erstickt sie im keim","karte des untergrunds"},ang={["faction:Alliance"]="Das Ausschalten feindlicher Späher in Dun Morogh schützt die lebenswichtigen Versorgungslinien und umliegenden Außenposten von Eisenschmiede vor Sabotage.",["race:Dwarf"]="Für die Zwerge der Bronzebärte ist die Säuberung ihrer angestammten Berge von Dunkeleiseninfiltratoren eine Frage der Heimatverteidigung und der anhaltenden Clanrache."},sec={{t="Augen in der Kälte",b="Dun Morogh ist seit Langem ein befestigter Zufluchtsort für die Zwerge von Eisenschmiede, doch die uralte Feindschaft zwischen den Zwergenclans schläft nie wirklich. Dunkeleiseninfiltratoren haben sich durch die hohen Pässe und verschneiten Klippen geschlichen und lauern verdächtig nahe an lebenswichtigen Ausgrabungen und Siedlungen. Erdseher Farsen erkennt, dass selbst ein paar verborgene Beobachter einen verheerenden Angriff ankündigen können, und ruft standhafte Verteidiger der Allianz dazu auf, sie aufzuspüren, bevor ihre Pläne Gestalt annehmen."},{t="Bedrohung nahe Eisenbands Truppenlager",b="Die Spione haben ihr Herumschleichen auf das Gebiet um Eisenbands Truppenlager konzentriert, einen wichtigen Ort im östlichen Dun Morogh. Obwohl Farsen ihre genauen Absichten anfangs nicht erkennen kann, liefert die Beseitigung der verdeckten Agenten handfeste Beweise für ihre weitreichenderen Absichten. Beim Durchsuchen der besiegten Späher stößt man auf eine Karte des Untergrunds, die bestätigt, dass ihr Eindringen keine bloße Erkundungsmission ist, sondern Vorbereitungen darstellt, die mit uralten unterirdischen Geheimnissen wie der Halle der Thanen verknüpft sind."}},faq={{q="Wer bietet die Quest Erstickt sie im Keim an?",a="Die Quest wird von Erdseher Farsen im Anschluss an die Aufgabe Farsens Wacht angeboten und ersucht um Hilfe beim Umgang mit den Eindringlingen in Dun Morogh.",al={"questgeber erstickt sie im keim","wer startet erstickt sie im keim","farsen quest"}},{q="Warum sind Dunkeleisenspione in Dun Morogh?",a="Der Dunkeleisenclan schmiedet unablässig Ränke gegen seine Bronzebart-Vettern. Die Infiltration des östlichen Dun Morogh ermöglicht es seinen Agenten, Siedlungen zu überwachen und vergrabene unterirdische Gänge nahe Eisenbands Truppenlager auszugraben oder auszukundschaften.",al={"warum sind dunkeleisenspione hier","was machen die dunkeleisenzwerge in dun morogh","ironband dunkeleisenspione"}},{q="Wo befinden sich die Dunkeleisenspione?",a="Sie sammeln sich im Osten nahe Eisenbands Truppenlager im östlichen Dun Morogh und halten vom verschneiten Umland aus Wache.",al={"spion aufenthaltsort","wo sind dunkeleisenspione","wo findet man spione"}},{q="Was führt zu dieser Aufgabe?",a="Dieser Auftrag folgt nach dem Erstatten von Bericht für Farsens Wacht und verschärft die Verteidigungsmaßnahmen von bloßer Beobachtung zur aktiven Vernichtung.",al={"vorquest","was kommt vor erstickt sie im keim","erstickt sie im keim vorquest"}},{q="Was wird bei der Jagd nach diesen Spionen aufgedeckt?",a="Getötete Spione hinterlassen eine Dunkeleisenkarte, die die Quest Karte des Untergrunds einleitet und auf tiefere Geheimnisse rund um die Halle der Thanen verweist.",al={"was droppen spione","beute dunkeleisenkarte","folgequest nach erstickt sie im keim"}},{q="Wer ist Erdseher Farsen?",a="Erdseher Farsen ist ein aufmerksamer Zwerg, der in Dun Morogh stationiert ist und ungewöhnliche seismische sowie feindliche Clanbewegungen in den verschneiten Bergen überwacht.",al={"wer ist farsen","erdseher farsen geschichte"}}},fx={bdd12e65={q="Warum möchte Erdenrufer Farsen, dass sich um die Dunkeleisenspione gekümmert wird?",a="Erdenrufer Farsen weiß, dass jeder Stützpunkt der Dunkeleisenzwerge in Dun Morogh Gefahr für Eisenschmiede und die umliegenden Lande bedeutet. Obwohl ihre genauen Motive für ihn unklar bleiben, lädt das ungehinderte Agieren von Infiltratoren zu größerer Sabotage oder einem offenen Angriff ein. Er will ihre Präsenz sofort zerschlagen, bevor irgendein Plan, den sie vorbereiten, Fuß fassen kann.",al={"warum will farsen die spione tot sehen","erdenrufer farsen motiv","warum im keim ersticken"}}},fp="18,247,16.475.0,31.452.1,40.132.0,38.228.0,38.121.0,26.137.0,44.134.1,24.146.0"}
P.entries["quest:96391"] = {n="Underground Map",s="Die von infiltrierenden Spionen nahe Eisenbands Truppenlager erbeutete Underground Map enthüllt klammheimliche Tunnelnetzwerke, die sich in Richtung der Wurzeln von Eisenschmiede graben. Ihre gezackten Dunkeleisenrunen zeichnen eine heimliche unterirdische Route nach, die geradewegs auf uralte Kammern unter dem Berg zustößt. Ihre Übergabe an Erdseher Farsen stellt den ersten Schritt dar, um eine drohende Invasion von unten aufzudecken.",h="Die von infiltrierenden Spionen nahe Eisenbands Truppenlager erbeutete Underground Map enthüllt...",kw={"dunkeleisenkarte","dun morogh","erdseher farsen","die halle der thanen","eisenbands truppenlager","eisenschmiede","underground map"},ang={["class:Shaman"]="Der subtile Windstoß, der Euch zu Erdseher Farsen führt, deutet auf Elementargeister hin, die vor unnatürlichen unterirdischen Ausgrabungen unter Dun Morogh warnen.",["faction:Alliance"]="Die Neutralisierung dieser unterirdischen Infiltrationsroute ist von wesentlicher Bedeutung, um die Sicherheit von Eisenschmiede und dem nördlichen Anker der Allianz zu wahren.",["race:Dwarf"]="Für die Bronzebeartzwerge ist die Entdeckung von Dunkeleisentunneln, die geradewegs auf die Fundamente von Eisenschmiede zuschneiden, ein schwerwiegender Verstoß gegen die territoriale Integrität der Hauptstadt."},sec={{t="Ein Bauplan der Infiltration",b="Das von Dunkeleisenspionen nahe Eisenbands Truppenlager erbeutete Pergament zeigt ein verschlungenes Labyrinth unterirdischer Straßen. Die in rauen, gezackten Runen verfassten Diagramme, die einzigartig für den Dunkeleisenklan sind, verzeichnen tiefe unterirdische Gänge, die direkt unter Eisenschmiede zusammenlaufen. Die zusammenlaufenden Passagen deuten auf eine mögliche Bedrohung unter der Hauptstadt der Bronzebeärte hin, doch die Dunkeleisen-Anmerkungen der Karte bleiben ungewiss."},{t="Flüstern im Wind",b="Beim Studieren der groben Kartographie trägt ein unnatürlicher Windstoß das leise Murmeln einer Zwergenstimme heran, die zu raschem Handeln drängt. Der mystische Impuls deutet geradewegs auf Erdseher Farsen. Diese Informationen zu melden, enthüllt frühe Truppenbewegungen in Richtung der uralten Hallen, die tief unter der Stadt versiegelt sind, und bedroht die Zuflucht des Bergkönigreichs."}},faq={{q="Woher stammt diese unterirdische Karte?",a="Die Karte wird von Dunkeleisenspionen mitgeführt, die den Umkreis von Eisenbands Truppenlager in Dun Morogh auskundschaften. Man kann sie finden, während man sich in den Ausläufern mit ihren Spähern befasst.",al={"karte beute","wo karte finden","wie man underground map bekommt"}},{q="Was zeigt die Karte?",a="Sie skizziert ein komplexes Netzwerk unterirdischer Straßen und Tunnel, die sich durch die Erde schlängeln und alle direkt unter der Stadt Eisenschmiede zusammenlaufen.",al={"was ist auf der karte","kartendetails","zweck der dunkeleisenkarte"}},{q="Wer ist Erdseher Farsen?",a="Erdseher Farsen ist ein Zwergen-Erdseher aus Nistgipfel, der auf das tiefe Gestein und die Geister des Berges eingestimmt ist. Da er die unnatürlichen unterirdischen Bewegungen spürt, benötigt er die Karte, um den Durchbruch unter Eisenschmiede zu beurteilen.",al={"wo ist farsen","wer ist farsen","erdseher"}},{q="Warum graben die Dunkeleisen unter Eisenschmiede?",a="Die Karte deutet auf eine mögliche Route unter Eisenschmiede hin, doch ihre Dunkeleisen-Anmerkungen wurden nicht entziffert. Erdseher Farsen muss sie untersuchen, bevor der Plan festgestellt werden kann.",al={"warum dunkeleisen graben","dunkeleisen-komplott dun morogh"}},{q="Wozu führt diese Quest?",a="Die Übergabe dieser Karte an Erdseher Farsen beginnt die Nachforschungen in den Tiefen unter der Stadt, führt direkt zum Vorstoß in die Altstadt von Eisenschmiede und eröffnet den Zugang zur Halle der Thanen.",al={"underground map folgequest","nächste quest nach underground map"}},{q="In welcher Sprache sind die Runen der Karte verfasst?",a="Die Karte verwendet die gezackte Runenschrift der Dunkeleisenzwerge. Wer sie findet, kann sich nicht sicher sein, was die Anmerkungen besagen.",al={"kartenrunen","dunkeleisensprache"}}},fx={["1c73103d"]={q="Warum muss die Dunkeleisenkarte zu Erdenrufer Farsen gebracht werden?",a="Die Karte zeigt ein alarmierendes Netzwerk von unterirdischen Tunneln und Wegen, die alle direkt unter Eisenschmiede zusammenlaufen. Ihre gezackten Dunkeleisenrunen erfordern eine Übersetzung, und die unheimliche Zwergenstimme, die auf dem Wind getragen wird, macht deutlich, dass Erdenrufer Farsen die mögliche unterirdische Bedrohung sofort untersuchen muss, um das Bergkönigreich vor der Gefahr aus dem Untergrund zu warnen.",al={"warum die karte zu farsen bringen","motiv der dunkeleisenkarte","warum die karte überbringen"}}},fp="15,383,27.404.0,20.344.1,41.165.0,23.147.0,24.216.0,49.181.0,29.201.1,45.127.0"}
P.entries["quest:96392"] = {n="Farsens Wacht",s="Farsens Wacht ist eine Beobachtungsaufgabe von Erdseher Farsen, einem zu Besuch weilenden Wildhammer-Schamanen, der hoch über dem Gol'bolar Steinbruch stationiert ist. Mithilfe der schamanischen Weitsicht des Erdsehers werden Abenteurer aus erster Hand Zeugen der wachsenden Infiltration der Dunkeleisenzwerge tief im Herzen von Dun Morogh. Diese entscheidende Erkundung stellt einen frühen Schritt auf dem Weg in die Halle der Thanen dar.",h="Farsens Wacht ist eine Beobachtungsaufgabe von Erdseher Farsen, einem zu Besuch weilenden...",kw={"nistgipfel","dunkeleisen","dun morogh","erdseher","farsen","weitsicht","gol'bolar","die halle der thanen","wildhammer"},ang={["class:Shaman"]="Die Erdseher der Wildhämmer veranschaulichen die irdene und spirituelle Sichtweise ihrer Tradition und bieten einen Einblick in den Zwergenschamanismus, der in den Klippen von Nistgipfel verwurzelt ist.",["faction:Alliance"]="Die Aufdeckung der Umtriebe der Dunkeleisenzwerge in Dun Morogh ist unerlässlich, um die Sicherheit von Eisenschmiede und den umliegenden Gebirgspässen für alle Reisenden der Allianz zu gewährleisten.",["race:Dwarf"]="Für die Verteidiger der Bronzebärte unterstreicht die Warnung eines Vetters aus Nistgipfel nur allzu deutlich, wie dreist die Infiltration ihrer Heimat durch die Dunkeleisenzwerge mittlerweile geworden ist."},sec={{t="Blick über den Grat",b="Hoch über den schneeverwehten Ausgrabungen im Gol'bolar Steinbruch hält Erdseher Farsen wachsam Ausschau über die tiefer gelegenen Gefilde von Dun Morogh. Der Wildhammer-Gast, der aus den schroffen Höhen von Nistgipfel nach Süden gereist ist, bringt ein feines spirituelles Gespür in Lande, die für gewöhnlich von den Gebirgsjägern von Eisenschmiede bewacht werden. Anstatt sich auf bloße Späher zu verlassen, nutzt Farsen die traditionellen Künste seines Clans, um unterirdische Erschütterungen und unerwartete Bewegungen an den Hängen im Auge zu behalten."},{t="Eine geliehene Vision",b="Um Reisende von der drohenden Gefahr zu überzeugen, leiht Farsen ihnen seine Weitsicht – eine schamanische Gabe, die das eigene Bewusstsein über weite Entfernungen hinweg projiziert. Durch diesen spirituellen Blick wird rasch klar, dass die Probleme von Dun Morogh weit über widerspenstige Troggs und wilde Bestien hinausgehen. Dunkeleisenzwerge haben sich nahe an das Industriezentrum von Eisenschmiede herangepirscht und sich für eine Unternehmung verschanzt, die ein unverzügliches Eingreifen erfordert, ehe sie Fuß fassen kann."}},faq={{q="Wer ist Erdseher Farsen?",a="Erdseher Farsen ist ein Wildhammerzwerg, der Dun Morogh von Nistgipfel im Hinterland aus besucht. Als Erdseher beherrscht er schamanische Magie, die es ihm erlaubt, Störungen im Land wahrzunehmen und Gefahren aus der Ferne zu beobachten.",al={"erdseher farsen","wer ist farsen","farsen wildhammer"}},{q="Wo findet diese Wache statt?",a="Erdseher Farsen wacht von einem Aussichtspunkt über dem Gol'bolar Steinbruch, einer bedeutenden Bergbaustätte der Bronzebärte im östlichen Dun Morogh.",al={"farsen standort","wo ist farsen","steinbruch aussichtspunkt"}},{q="Welche Bedrohung deckt Farsen auf?",a="Durch seine schamanische Weitsicht offenbart Farsen, dass feindselige Dunkeleisenzwerge in der Nähe einen Stützpunkt errichtet haben und eine akute, gefährliche Bedrohung für die Region darstellen.",al={"was zeigt weitsicht","dunkeleisen bedrohung","farsen vision"}},{q="Wie hängt dies mit der Halle der Thanen zusammen?",a="Die Untersuchung der Dunkeleisenpräsenz, die während Farsens Wacht ausgemacht wurde, leitet die größere Aufgabenreihe ein, die Abenteurern den Zutritt in die Halle der Thanen ermöglicht.",al={"zugang halle der thanen","questreihe halle der thanen"}},{q="Warum ist ein Wildhammerzwerg an der Verteidigung von Dun Morogh beteiligt?",a="Auch wenn die Wildhämmer im Hinterland zu Hause sind, führen Bande der Sippschaft und die gemeinsame Feindschaft gegenüber den Dunkeleisenzwergen Reisende wie Farsen gelegentlich in die angestammten Länder der Bronzebärte in Dun Morogh.",al={"warum ist wildhammer hier","nistgipfel zwerg dun morogh"}},{q="Was folgt direkt nach dem Abschluss von Farsens Wacht?",a="Sobald Ihr die Unterwanderung durch die Dunkeleisenzwerge in seiner Vision mit eigenen Augen gesehen habt, treibt Euch Farsen mit der Aufgabe „Im Keim ersticken“ dazu an, dem vordringenden Feind aktiv Einhalt zu gebieten.",al={"folgequest","was folgt nach farsens wacht","im keim ersticken"}}},fx={["73fc96dc"]={q="Warum möchte Erdenrufer Farsen, dass dies getan wird?",a="Während er von Nistgipfel durch Dun Morogh reiste, entdeckte Erdenrufer Farsen Anzeichen von Aggressionen der Dunkeleisenzwerge, die nahe dem Steinbruch Gol'Bolar überhandnahmen. Bevor er handelt oder Alarm schlägt, möchte der Schamane, dass Ihr die aufkeimende Gefahr aus erster Hand durch seine hellseherische Magie miterlebt, um sicherzustellen, dass die Verteidiger von Eisenschmiede das wahre Ausmaß der feindlichen Infiltration erfassen, bevor sie außer Kontrolle gerät.",al={"warum farsens wache","farsens motiv","warum will farsen, dass ich nachsehe"}}},fp="14,364,21.463.0,17.448.0,24.219.0,33.127.0,31.165.0,44.164.0,59.191.0,52.174.0"}
P.entries["quest:96393"] = {n="Eindringlinge in der Altstadt von Eisenschmiede",s="Eindringlinge in der Altstadt von Eisenschmiede ist der abschließende Einsatz bei den Nachforschungen über die Dunkeleisenspione, die tief unter Eisenschmiede lauern. Unter der Leitung von Erdseher Farsen steigen die Champions in die uralte Halle der Thanen unter Altstadt von Eisenschmiede hinab, um den feindlichen Kommandanten Durgen Dirgehammer zu eliminieren und die Bedrohung König Magni Bronzebart persönlich zu melden.",h="Eindringlinge in der Altstadt von Eisenschmiede ist der abschließende Einsatz bei den Nachforschungen über...",kw={"dunkeleisen","dirgehammer","farsen","eindringlinge","eisenschmiede","kharanos","magni","thanen"},ang={["faction:Alliance"]="Das Stoppen des Überfalls verhindert einen verheerenden Überraschungsangriff auf die wichtigste Festung der Allianz in den Östlichen Königreichen.",["race:Dwarf"]="Für die Bronzebeards stellen Dunkeleisen-Infiltratoren, die in den vergessenen Gewölben unter dem High Seat lauern, eine untragbare Verletzung ihrer angestammten Festung dar."},sec={{t="Durchbrechen der Gewölbe",b="Nach der Entdeckung einer unterirdischen Karte, welche die Truppenbewegungen der Dunkeleisenzwerge offenbart, identifiziert Erdseher Farsen den Drahtzieher hinter dem unterirdischen Überfall. Tief in den uralten Steinhallen von Altstadt von Eisenschmiede liegt der Eingang zur Halle der Thanen. Während sich die Oberstadt mit Angelegenheiten der Oberfläche beschäftigt, sind heimtückische Streitkräfte direkt unter den Füßen des Königreichs in diese ruhenden Höhlen geschlüpft."},{t="Durgen Dirgehammer",b="Farsens Übersetzung erbeuteter Dunkeleisen-Dokumente weist auf einen einzigen Kommandanten hin, der die Operationen leitet: Durgen Dirgehammer. Tief in den unteren Gewölben stationiert, stellt Dirgehammer eine unmittelbare Bedrohung für das Herz des Bergkönigreichs der Bronzebeard dar. Um dem Vorstoß das Rückgrat zu brechen, müssen Abenteurer in die Tiefen hinabsteigen, ihn zur Strecke bringen und seinen abgetrennten Kopf nach oben zu König Magni Bronzebart bringen."},{t="Audienz beim König",b="König Magni Bronzebart den Kopf von Durgen Dirgehammer zu überreichen, bestätigt die düstere Realität der Dunkeleisen-Bedrohung, die durch die uralten Wurzeln der Stadt kriecht. Mit dem schaurigen Beweis des Sieges und einem persönlichen Gruß seines alten Freundes Farsen im Gepäck schließen die Abenteurer die Untersuchung formell ab und sorgen dafür, dass Magni von dem weiß, was in der Tiefe lauert."}},faq={{q="Was ist Eindringlinge in der Altstadt von Eisenschmiede?",a="Es ist das Finale einer Questreihe, die den Aktivitäten der Dunkeleisenzwerge unter Dun Morogh nachgeht. Von Erdseher Farsen vergeben, beauftragt sie Spieler damit, Die Halle der Thanen unter Altstadt von Eisenschmiede zu betreten, um den Dunkeleisenkommandanten Durgen Dirgehammer zu töten.",al={"eindringlinge in der altstadt von eisenschmiede quest","durgen dirgehammer quest"}},{q="Wo findet diese Quest statt?",a="Die Mission führt Abenteurer in die Halle der Thanen, eine uralte unterirdische Kammer unterhalb von Altstadt von Eisenschmiede, tief im Felsgestein unter der Berghauptstadt.",al={"wo ist die halle der thanen","die halle der thanen standort"}},{q="Wer ist Durgen Dirgehammer?",a="Durgen Dirgehammer ist der Dunkeleisenkommandant, der den unterirdischen Vorstoß in die Halle der Thanen unter Altstadt von Eisenschmiede anführt. Erdseher Farsen entnimmt seinen Namen sichergestellten Dunkeleisen-Dokumenten.",al={"wer ist dirgehammer","durgen dirgehammer"}},{q="Wer vergibt die Quest, und wer nimmt sie an?",a="Die Quest wird von Erdseher Farsen nach der Beschaffung der Karte des Untergrunds vergeben. Sie wird direkt bei König Magni Bronzebart in Eisenschmiede abgegeben.",al={"questgeber eindringlinge in der altstadt von eisenschmiede","abgabe eindringlinge in der altstadt von eisenschmiede"}},{q="Wie beginne ich die Questreihe, die hierher führt?",a="Die Reihe beginnt mit der Quest Ein Besucher in Dun Morogh, die von Beldin Stahlrost vor Kharanos in Dun Morogh angeboten wird.",al={"wie starte ich quest die halle der thanen","ein besucher in dun morogh start"}},{q="Welche Verbindung besteht zwischen Erdseher Farsen und König Magni?",a="Erdseher Farsen betrachtet sich als alter Freund von König Magni Bronzebart und weist Abenteurer an, ihm persönliche Grüße zu übermitteln, wenn sie Durgen Dirgehammers Kopf im Thronsaal präsentieren.",al={"farsen und magni","erdseher farsen lore"}}},fx={bdae81a8={q="Warum möchte Erdenrufer Farsen, dass Durgen Dirgehammer getötet wird?",a="Farsen deckte feindliche Bewegungen unter dem Berg auf und entschlüsselte Befehle, die Durgen Dirgehammer als den Kommandanten auswiesen, der den Einfall in die Altstadt von Eisenschmiede anführt. Die Präsenz der Dunkeleisen in der Halle der Thanen bedroht die Zwergenhauptstadt direkt von unten. Indem er Euch schickt, um ihren Anführer niederzustrecken, zielt Farsen darauf ab, den Angriff zu zerschlagen, bevor die Dunkeleisen sich verschanzen können, während er gleichzeitig einen unbestreitbaren Beweis für die Bedrohung direkt an König Magni Bronzebart sendet.",al={"farsens motiv","warum durgen dirgehammer töten","warum schickt euch farsen"}},["664606f0"]={q="Wozu dient Durgen Dirgehammers Kopf?",a="Ihr benötigt Durgen Dirgehammers Kopf als absoluten Beweis für König Magni Bronzebart, dass der Kommandant des unterirdischen Angriffs unschädlich gemacht wurde. Die direkte Übergabe der grausamen Trophäe an den Thronsaal bestätigt, dass die feindliche Dunkeleisen-Angriffstruppe in der Halle der Thanen ihren Anführer verloren hat, und überbringt Erdenrufer Farsens persönliche Warnung an den König.",al={"nutzen von durgen dirgehammers kopf","warum durgens kopf mitnehmen","kopf von durgen dirgehammer"}}},fp="23,341,20.394.0,18.411.1,22.347.1,32.237.0,33.165.0,26.200.0,41.150.0,50.117.0,63.190.0"}
P.entries["quest:96394"] = {n="The Restless Dead",s="The Restless Dead befasst sich mit einer besorgniserregenden Störung in den Krypten der Halle der Thanen, wo uralte Zwergengeister aus ihrer Ruhe aufgeschreckt wurden. Da die Pfleger sich fürchten, die Gewölbe zu betreten, muss ein Abenteurer in die Katakomben hinabsteigen, um die zornigen Phantome und den Geist von Ambossar wieder zur Ruhe zu betten.",h="The Restless Dead befasst sich mit einer besorgniserregenden Störung in den Krypten der Halle der Thanen, wo...",kw={"ambossar","zwergengräber","zwergengeister","enraged apparitions","geister","die halle der thanen","geist von ambossar","the restless dead","tormented souls"},ang={["class:Priest"]="Geister, die in Pein oder Zorn verweilen, sind ein direkter Pflichtaufruf für jene, die mit Seelen zwiesprache halten und unruhige Tote zur friedvollen Ruhe leiten.",["faction:Alliance"]="Die Sicherung der uralten Krypten unter Eisenschmiede sorgt dafür, dass die Hüter ihre heiligen Pflichten erfüllen können, ohne fürchten zu müssen, von rachsüchtigen Erscheinungen überrannt zu werden.",["race:Dwarf"]="Die Halle der Thanen birgt die geehrten Toten und Ahnen des Zwergenvolks, weshalb ihre plötzliche, gewaltsame Erregung eine beunruhigende Störung direkt im Herzen ihres Erbes darstellt."},sec={{t="Störung in den Tiefen Gewölben",b="Tief unter der Oberfläche in der Halle der Thanen bergen uralte Krypten Generationen geehrter Toter. Während sie für gewöhnlich in stiller Ruhe schlummern, wurden die Geister durch eine ungesehene Störung in den Gewölben heftig aufgewühlt. Seltsame Geräusche, die von unten heraufhallen, haben die Pfleger der Stätte verängstigt, die sich weigern, die unteren Kammern zur Verrichtung ihrer Pflichten zu betreten, bis die Ordnung wiederhergestellt ist. Abenteurer sind dazu aufgerufen, in die schattigen Steinhallen hinabzusteigen und die aufgewühlten Seelen zu besänftigen."},{t="Die Ahnen besänftigen",b="Die in der Halle der Thanen ruhenden Geister sind notorisch leichte Schläfer. Welches Ereignis oder welche Präsenz auch immer die unteren Grüfte erschütterte, wirbelte Wellen von Enraged Apparitions und Tormented Souls auf und verwandelte heiligen Boden in einen gefährlichen Spukort. Unter den Erweckten befindet sich auch der verehrte Geist von Ambossar, was eine respektvolle, doch feste Hand erfordert, um den Zorn der erwachten Ahnen zu bezwingen und den Frieden in die Katakomben zurückzubringen."}},faq={{q="Worum geht es in der Quest The Restless Dead?",a="The Restless Dead ist eine Aufgabe, die erteilt wird, um einen Ausbruch geisterhafter Störungen unterhalb der Halle der Thanen zu untersuchen und einzudämmen. Jemand oder etwas hat die beigesetzten Geister aufgeschreckt, sodass die Hüter sich fürchten, die Gewölbe zu betreten, bis man sich um die Erscheinungen gekümmert hat.",al={"was ist the restless dead","was ist diese quest","the restless dead quest übersicht"}},{q="Warum sind die Geister erwacht?",a="Eine unbekannte Störung tief in den Gewölben weckte die beigesetzten Toten auf. Da die Geister in der Halle der Thanen als leichte Schläfer beschrieben werden, versetzte sie das, was sich unten in den Grüften ereignete, in eine Raserei aus Zorn und Pein.",al={"warum sind die geister wütend","wer störte die gräber","warum sind erscheinungen erwacht"}},{q="Wo findet diese Störung statt?",a="Die Unruhe konzentriert sich unten in den Krypten und Gewölben der Halle der Thanen, einer uralten Ruhestätte unter Eisenschmiede, wo uralte Zwergengeister begraben liegen.",al={"wo ist die halle der thanen","wo erscheinen the restless dead","halle der thanen ort"}},{q="Wer ist der Geist von Ambossar?",a="Der Geist von Ambossar ist eine uralte und bedeutende Seele, die in den tiefen Grüften der Halle der Thanen ruht. Neben geringeren Erscheinungen wurde dieser große Geist aus dem Schlummer gerissen und muss wieder zu friedvoller Ruhe gebettet werden.",al={"wer ist geist von ambossar","geist von ambossar lore","wer ist der geist von ambossar"}},{q="Warum brauchen die Hüter die Hilfe eines Abenteurers?",a="Die Hüter sind Pfleger, die damit beauftragt sind, die Krypten zu versorgen und ihren gewohnten Pflichten in der Halle der Thanen nachzugehen. Da zornige Geister durch die Hallen ziehen, weigern sie sich, in die unteren Gewölbe hinabzusteigen, bis die Bedrohung beseitigt ist.",al={"wer sind die hüter","warum brauchen hüter hilfe","hüter halle der thanen"}},{q="Welche Geister spuken in der Halle der Thanen?",a="Die heimgesuchten Gewölbe werden von Enraged Apparitions, Tormented Souls und dem ehrwürdigen Geist von Ambossar selbst heimgesucht, die allesamt zu einer aggressiven Wacht innerhalb der Grabkammern aufgeschreckt wurden.",al={"welche arten von geistern gibt es dort unten","erscheinungen in der halle der thanen","arten von the restless dead"}}},fp="17,321,30.474.0,22.404.1,38.258.0,30.226.0,39.169.0,30.215.0,45.228.0,38.184.0"}
P.entries["quest:96395"] = {n="Ein uralter Groll",s="Tief in der geschichtsträchtigen Halle der Thanen fleht ein ätherischer Diener um ein Ende der Qualen eines gefallenen Herrschers. Der Geist von Faldrim Anvilmar verweilt dort, verzehrt von einem alten Groll, und ihm wird der ewige Frieden verwehrt. Abenteurer haben die Aufgabe, den rastlosen Thanen zur Ruhe zu betten.",h="Tief in der geschichtsträchtigen Halle der Thanen fleht ein ätherischer Diener um ein Ende der Qualen eines...",kw={"ein uralter groll","ambossar","zwergengeist","faldrim anvilmar","ghostly attendant","die halle der thanen","rastloser geist","thane"},ang={["class:Paladin"]="Eine gequälte Seele zur Ruhe zu betten, ist eine feierliche Pflicht für heilige Krieger, die geschworen haben, den leidenden Toten Frieden zu bringen.",["class:Priest"]="Priester verstehen, dass anhaltender Groll und ungesühnter Kummer einen sterblichen Geist noch lange an das irdische Reich binden können, nachdem der Körper zu Staub zerfallen ist.",["race:Dwarf"]="Für Zwerge ist die Konfrontation mit einem rastlosen Thanen ihres eigenen Volkes eine ernüchternde Erinnerung daran, dass ein uralter Groll selbst den Tod überdauern kann."},sec={{t="Ein Flehen aus dem Grab",b="In den steinerner Gewölben der Halle der Thanen bietet der Tod keinen unmittelbaren Aufschub. Ein geisterhafter Diener von Faldrim Anvilmar verweilt dort, kaum fähig, die Kraft aufzubringen, durch den sterblichen Schleier zu sprechen. Anstatt Freiheit für sich selbst zu suchen, gilt die einzige Sorge des Phantoms seinem Herrn, und es bittet Reisende darum, den aufgewühlten Geist des Thanen zu besänftigen."},{t="Die Last der Vergangenheit",b="Der Tod hat Faldrim Anvilmar nicht von der Vergangenheit befreit. Gebunden an die physische Welt durch einen verzehrenden, uralten Groll, verbleibt Faldrims Geist aufgewühlt und feindselig, unfähig, Ruhe zu finden, bis ihm eine gewaltsame Erlösung zuteilwird."}},faq={{q="Wer ist Faldrim Anvilmar?",a="Faldrim Anvilmar war ein zwergischer Thane, dessen rastlose Erscheinung nun die Halle der Thanen heimsucht. Sein Ghostly Attendant sagt, dass er von einem uralten Groll verzehrt wird und keine Ruhe finden kann. Die Quest verrät nichts Weiteres über sein Leben oder seine Abstammung.",al={"faldrim anvilmar geschichte","wer ist faldrim","thane ambossar"}},{q="Wo befindet sich die Halle der Thanen?",a="Die Halle der Thanen liegt in den Höhlen unter Altstadt von Eisenschmiede, innerhalb der Zwergenhauptstadt Eisenschmiede.",al={"halle der thanen ort","wo ist die halle der thanen","halle der thanen eingang"}},{q="Warum ist der Geist von Faldrim Anvilmar feindselig?",a="Dem geisterhaften Diener zufolge wird der ehemalige Thane von einem uralten Groll verzehrt. Die Zwergengeschichte ist geprägt von jahrhundertelangen Clanrivalitäten, und Faldrims anhaltender Hass hindert seinen Geist daran, in einen friedlichen Schlummer hinüberzugleiten.",al={"warum ist faldrim wütend","warum greift der thane an","ein uralter groll erklärung"}},{q="Wer vergibt die Quest Ein uralter Groll?",a="Die Quest wird von einem Ghostly Attendant vergeben, der sich in der Halle der Thanen befindet. Selbst nach dem Tod noch in Knechtschaft gebunden, sucht der Diener einzig Frieden für seinen früheren Herrn.",al={"wer startet ein uralter groll","ghostly attendant quest","questgeber"}},{q="Was müsst Ihr tun, um die Quest abzuschließen?",a="Ihr müsst Euch dem Geist von Faldrim Anvilmar in der Halle der Thanen stellen, seinen rastlosen Geist im Kampf besiegen, um ihn von seinen Qualen zu erlösen, und anschließend dem Ghostly Attendant Bericht erstatten.",al={"wie beendet man ein uralter groll","faldrim zur ruhe betten","ein uralter groll ziel"}},{q="Ist Faldrim mit der Stadt Ambossar verwandt?",a="Das ist noch nicht bekannt. Faldrim teilt seinen Namen mit der Siedlung Ambossar im Coldridgetal, doch die Quest erwähnt nichts über seine Familie oder eine Verbindung zu der Stadt.",al={"ist faldrim aus ambossar","ambossar coldridgetal verbindung","ambossar familie"}}},fp="17,276,21.348.0,22.214.1,24.233.0,36.102.0,45.234.0,38.168.0,39.186.0,43.166.0"}
P.entries["quest:96403"] = {n="Important Heirlooms",s="Important Heirlooms ist eine Quest, bei der ein Abenteurer einem nervösen Gnomen namens Thom hilft, der beim Herumlungern in der Halle der Thanen erwischt wurde, als Dunkeleisenzwerge in unterirdischen Maulwurfmaschinen die Gewölbe durchbrachen. Die Aufgabe besteht darin, verstreute zwergische Relikte unter dem zweifelhaften Deckmantel historischer Bewahrung zu bergen.",h="Important Heirlooms ist eine Quest, bei der ein Abenteurer einem nervösen Gnomen namens Thom hilft, der beim...",kw={"dunkeleisen","zwergische erbstücke","gnom","die halle der thanen","important heirlooms","maulwurfmaschine","thom","gewölbe"},ang={["class:Rogue"]="Ein Schurke durchschaut Thoms fadenscheinige Ausrede, die Gewölbe zu „patrouillieren“, mit Leichtigkeit und erkennt einen Mitplünderer, der von einer unterirdischen Invasion überrascht wurde.",["race:Dwarf"]="Zwergische Abenteurer betrachten Thoms plötzliches Interesse an der Bergung von Ahnenrelikten womöglich mit tiefer Skepsis, insbesondere angesichts seiner Versprecher bezüglich Beute und Schätzwert.",["race:Gnome"]="Thoms opportunistische Natur und seine ungeschickten Tarnberichte verdeutlichen eine wenig wissenschaftliche Seite der Neugier der Gnome, wenn wertvolle Relikte auf dem Spiel stehen."},sec={{t="Ärger in den Gewölben",b="Während er die unterirdischen Gewölbe der Halle der Thanen erkundete, wurde ein geschäftstüchtiger Gnom namens Thom durch das plötzliche Eintreffen von Dunkeleisenzwergen überrascht, die sich in Maulwurfmaschinen nach oben gruben. Da er das Gebiet nicht selbst sichern kann, heuert Thom vorbeikommende Abenteurer an, der feindseligen Ausgrabungsstätte zu trotzen und wertvolle, über die Kammern verstreute zwergische Relikte zu bergen, bevor die Invasoren sie an sich reißen oder zerstören."},{t="Kulturelle Bewahrung oder lukrative Beute?",b="Obwohl Thom darauf beharrt, dass er lediglich auf Patrouille war und die Relikte zur Bewahrung katalogisieren möchte, lassen seine ständigen Versprecher über „unschätzbare Beute“ und das „Schätzen des Fangs“ weitaus eigennützigere Motive vermuten. Abenteurer werden für ihren Mut fürstlich entlohnt, doch ob diese uralten zwergischen Schätze jemals ein Museum oder ein Auktionshaus sehen werden, bleibt eine offene Frage."}},faq={{q="Wer ist Thom?",a="Die Quest wird von Thom vergeben, einem geschäftstüchtigen Gnomen, der nahe den Gewölben zu finden ist. Seine nervösen Versprecher deuten darauf hin, dass er weitaus mehr an lukrativer Beute als an legitimer Sicherheit des Gewölbes interessiert ist.",al={"wer ist der questgeber","wer ist thom","questgeber"}},{q="Was ist die Halle der Thanen?",a="Die Halle der Thanen ist ein unterirdisches zwergisches Gewölbe, das uralte kulturelle Relikte und Erbstücke beherbergt und kürzlich von unterirdischen Streitkräften der Dunkeleisenzwerge durchbrochen wurde.",al={"was ist die halle der thanen","wo ist die halle der thanen"}},{q="Warum sind Dunkeleisenzwerge in den Gewölben?",a="Ein Stoßtrupp von Dunkeleisenzwergen durchbrach die Gewölbe direkt aus den Tiefen mithilfe von grabenden Maulwurfmaschinen und stürzte das Gebiet zu unbekannten Zwecken ins Chaos.",al={"warum sind dunkeleisenzwerge dort","maulwurfmaschinen der dunkeleisenzwerge"}},{q="Gibt Thom die Erbstücke wirklich zurück?",a="Thom verspricht sich ständig: Er bezeichnet Herumschleichen als „Patrouillieren“, Erbstücke als „Beute“ sowie „Fang“ und Katalogisieren als „Schätzen“. Zwar zahlt er seine versprochene Belohnung, doch seine Beteuerungen, die Relikte an Orte der Ehre zurückzubringen, sind höchst verdächtig.",al={"lügt thom","stiehlt thom","thom vertrauenswürdig"}},{q="Was sind die Zwergischen Erbstücke?",a="Es handelt sich um uralte zwergische Kulturrelikte, die in der Halle der Thanen aufbewahrt werden; von Historikern werden sie als unschätzbare Schätze angesehen – und von Opportunisten wie Thom als lukrative Beute.",al={"was sind die erbstücke","zwergische erbstücke lore"}},{q="Warum kann Thom die Erbstücke nicht selbst bergen?",a="Thom wurde beim Herumlungern in den Gewölben vom plötzlichen Eintreffen von Maulwurfmaschinen der Dunkeleisenzwerge überrascht, sodass er die Relikte nicht mehr sicher ohne den Schutz eines Abenteurers plündern kann.",al={"warum braucht thom hilfe","warum thom helfen"}}},fp="19,306,21.398.0,43.388.1,12.191.0,27.167.0,40.162.0,39.237.0,31.167.0,46.196.0"}
P.entries["quest:96408"] = {n="Ein Besucher in Dun Morogh",s="Ein Besucher in Dun Morogh ist eine Untersuchungsaufgabe, die von Beldin Stahlrost außerhalb von Kharanos angeboten wird. Gebirgsjäger meldeten ein unbekanntes Lagerfeuer hoch auf den Klippen über dem Gol'bolar Steinbruch, was dazu führte, dass ein Späher entsandt wird, um zu prüfen, ob der Fremde eine Bedrohung für die örtlichen Zwerge darstellt.",h="Ein Besucher in Dun Morogh ist eine Untersuchungsaufgabe, die von Beldin Stahlrost außerhalb von Kharanos...",kw={"beldin stahlrost","dun morogh","earthseer farsen","farsens wacht","steinbruch gol'bolar","die halle der thanen","kharanos","besucher"},ang={["class:Shaman"]="Die Begegnung mit Earthseer Farsen schlägt eine direkte Brücke zur spirituellen Zwiesprache mit den Steinen der Berge – ein seltener Anblick im verschneiten Hochland von Dun Morogh.",["faction:Alliance"]="Die Unterstützung der örtlichen Gebirgsjäger vor Kharanos stellt sicher, dass die Versorgungslinien und Steinbrucharbeiter vor unvorhergesehenen Bedrohungen geschützt bleiben.",["race:Dwarf"]="Für die Zwerge der Bronzebärte ist die Überwachung ungebetener Beobachter über bedeutenden Abbaustätten wie Gol'Bolar eine routinemäßige Sicherheitsmaßnahme zum Schutz der Grenzen Khaz Modans."},sec={{t="Eine Rauchsäule auf den Höhen",b="Dun Moroghs Gebirgsjäger wachen aufmerksam über die Klippen und verschneiten Täler rund um Eisenschmiede. Als plötzlich ein Lagerfeuer hoch über dem Gol'bolar Steinbruch auftauchte, sorgte dies in Kharanos für Verwunderung. Beldin Stahlrost, besorgt über das ungewöhnliche Lager direkt über einer lebenswichtigen Ausgrabungsstätte der Zwerge, rekrutiert Reisende, um die Kämme zu erklimmen und herauszufinden, ob es sich bei dem geheimnisvollen Fremden um einen friedlichen Reisenden oder einen Eindringling handelt."},{t="Begegnung mit dem Erdseher",b="Die Erkundung des Kamms enthüllt, dass es sich bei dem Reisenden um Earthseer Farsen handelt, einen Mystiker, der sein Lager auf den windgepeitschten Höhen aufgeschlagen hat. Weit davon entfernt, ein plündernder Trogg oder ein feindseliger Spion zu sein, besitzt dieser geheimnisvolle Beobachter tiefe spirituelle Bande zur Erde. Seine Anwesenheit an der Klippe über dem Steinbruch bildet den Auftakt zu einer Reise, die tiefere, unter Khaz Modan verborgene Unruhen aufdeckt und letztlich mit dem Geheimnis der Halle der Thanen verknüpft ist."}},faq={{q="Wer schickt Euch aus, um den Besucher zu untersuchen?",a="Beldin Stahlrost, stationiert vor Kharanos in Dun Morogh, vergibt die Quest, nachdem Gebirgsjäger ein unbekanntes Feuer oben in den Bergen gemeldet haben.",al={"wer gibt diese quest","queststarter","beldin stahlrost quest"}},{q="Wo befindet sich das geheimnisvolle Lager?",a="Das Lagerfeuer liegt hoch oben auf den verschneiten Kämmen östlich von Kharanos, direkt oberhalb der Ausgrabung des Gol'bolar Steinbruchs.",al={"lagerort","wo ist der besucher","standort des besuchers"}},{q="Wer ist der Besucher, der den Steinbruch überblickt?",a="Der Besucher ist Earthseer Farsen, ein spiritueller Beobachter, der in einem abgelegenen Lager auf den Höhen über dem Steinbruch weilt.",al={"wer ist farsen","wer ist der besucher","earthseer farsen"}},{q="Warum waren die Zwerge wegen des Lagerfeuers misstrauisch?",a="Der Steinbruch Gol'Bolar ist eine wichtige zwergische Unternehmung, die bereits durch die örtlichen Troggs bedrängt wird. Jedes unbekannte Lager hoch über der Grube könnte leicht zu Spähern oder feindlichen Truppen gehören, die die Bewegungen der Zwerge beobachten.",al={"warum misstrauisch","warum untersuchen","warum entsandt"}},{q="Wozu führt diese Quest?",a="Die Berichterstattung bei Earthseer Farsen führt direkt zur Quest 'Farsens Wache' und dient als Auftakt zur Zugangsquestreihe für die Halle der Thanen.",al={"was kommt danach","folgequest","die halle der thanen intro"}},{q="Müsst Ihr gegen den Fremden im Lager kämpfen?",a="Nein. Obwohl Beldin Stahlrost Euch auf eine gewaltsame Auseinandersetzung vorbereitet, ist der Besucher Earthseer Farsen, ein friedlicher Beobachter, der bereit ist, mit Euch zu sprechen.",al={"ist der besucher feindselig","muss ich den besucher töten","kampf gegen besucher"}}},fx={["3b0d76fb"]={q="Warum bittet Beldin Stahlrost einen Abenteurer und nicht die Gebirgsjäger?",a="Die lokalen Gebirgsjäger entdeckten das Lagerfeuer am Hang aus der Ferne, aber ihre Reihen sind ausgedünnt, da sie Straßen, Siedlungen und Steinbruchbetriebe vor Troggs und wilden Bestien schützen müssen. Da das Feuer wahrscheinlich harmlos ist, verlässt sich Beldin auf einen fähigen Reisenden, der Kharanos passiert, um schnell den Grat zu erkunden, anstatt Wachen vom aktiven Dienst abzuziehen.",al={"warum mich schicken","warum keine wachen schicken","beldin stahlrost warum ich"}}},fp="23,274,28.427.0,21.440.1,41.138.0,41.132.0,42.114.1,48.212.0,31.154.1,46.153.1"}
P.entries["quest:965"] = {n="Der Turm von Althalaxx",s="Betraut mit der Verteidigung von Auberdine hegt Schildwache Elissa Sternenhauch den Verdacht unlauterer Machenschaften in den uralten Ruinen im Norden. Sie beauftragt Abenteurer damit, Balthule Schattenhieb zu finden, einen Späher, der ausgesandt wurde, um den rätselhaften Turm von Althalaxx zu beobachten, und der sich nicht wie vorgesehen zurückgemeldet hat.",h="Betraut mit der Verteidigung von Auberdine hegt Schildwache Elissa Sternenhauch den Verdacht unlauterer...",kw={"althalaxx","auberdine","balthule schattenhieb","dunkelküste","elissa sternenhauch","späher","schildwache","turm"},ang={["faction:Alliance"]="Auberdine dient als wichtigstes Tor der Allianz nach Nordkalimdor, weshalb die Verteidigung der umliegenden Straßen und Grenzen für alle durchreisenden Verbündeten von entscheidender Bedeutung ist.",["race:NightElf"]="Die Ruinen von Althalaxx stehen als Mahnmal für die gefallene Hochgeborenen-Vergangenheit des alten Kalimdors, und die Bewahrung Auberdines vor dem Verfall, der in diesen Steinen schwelt, ist eine lebenswichtige Pflicht für Nachtelfen-Schildwachen."},sec={{t="Ein vermisster Späher",b="Auberdines Schildwachen müssen stets wachsam über die schleichenden Gefahren der Dunkelküste wachen. Schildwache Elissa Sternenhauch bemerkte verdächtige Aktivitäten rund um den Turm von Althalaxx in den nördlichen Ausläufern des Waldes. Sie entsandte Balthule Schattenhieb, um die uralte Ruine auszukundschaften. Tage sind vergangen, ohne dass eine Nachricht von dem Späher eintraf, was Elissa dazu veranlasst, nach einem willigen Reisenden zu suchen, der nach Norden zieht, Balthule ausfindig macht und sicherstellt, dass er kein vorzeitiges Ende gefunden hat."},{t="Ein wachsames Auge auf die Ruine",b="Die Straße nördlich von Auberdine führt an uralten Kaldorei-Ruinen vorbei und über den Klippenquell, bevor sie die schattenhaften Ausläufer des Turms erreicht. Obwohl er davon abgeschnitten war, Nachricht nach Auberdine zu senden, überlebte Balthule seine anfängliche Überwachung. Nachdem er in den umliegenden Wäldern ausfindig gemacht wurde, bestätigt er, dass Elissas Instinkte richtig lagen: Düstere und beunruhigende Entwicklungen sind innerhalb der zerfallenden Steinspitze in vollem Gange."}},faq={{q="Wer ist Schildwache Elissa Sternenhauch?",a="Elissa Sternenhauch ist eine Nachtelfen-Schildwache, die in Auberdine stationiert ist. Sie ist damit beauftragt, die Siedlung vor äußeren Bedrohungen an der Dunkelküste zu schützen, und überwacht regionale Gefahren wie den Turm von Althalaxx.",al={"elissa sternenhauch","wer gibt quest","auberdine questgeber"}},{q="Wer ist Balthule Schattenhieb?",a="Balthule Schattenhieb ist ein Späher, der von Schildwache Elissa Sternenhauch ausgesandt wurde, um die geheimnisvollen Aktivitäten rund um den Turm von Althalaxx auszuspionieren. Er hält Wache außerhalb der Ruine, um feindliche Streitkräfte im Auge zu behalten.",al={"balthule","wer ist der späher","schattenhieb"}},{q="Wo befindet sich der Turm von Althalaxx?",a="Der Turm befindet sich im Nordosten der Dunkelküste. Reisende können ihn erreichen, indem sie Auberdine nach Osten verlassen, der nördlichen Straße an Bashal'Aran vorbei folgen und die Brücke über den Klippenquell überqueren, bis die Turmspitze in Sicht kommt.",al={"turm von althalaxx standort","wo ist der turm","wie findet man althalaxx"}},{q="Warum wurde überhaupt ein Späher zum Turm geschickt?",a="Elissa schickte Balthule los, um merkwürdige Vorkommnisse rund um den Turm von Althalaxx zu beobachten, während sie ihrer Pflicht nachging, Auberdine zu beschützen.",al={"warum den turm beobachten","was stimmt nicht bei althalaxx","warum balthule geschickt"}},{q="Warum ist Balthule nicht nach Auberdine zurückgekehrt?",a="Elissa hat Balthules Bericht nicht erhalten und bittet Euch, nach ihm zu sehen. Balthule kann seine Lage erklären, sobald Ihr ihn findet.",al={"warum balthule vermisst","ist balthule gefangen","warum blieb balthule"}},{q="Wird diese Questreihe fortgesetzt?",a="Ja. Das Auffinden von Balthule Schattenhieb beginnt eine mehrteilige Untersuchung der finsteren Mächte, die den Turm von Althalaxx besetzen, und ihrer unheilvollen Ambitionen an der Dunkelküste.",al={"ist das eine reihe","welche quest kommt als nächstes","althalaxx reihe"}}},fx={["895f5562"]={q="Warum möchte Schildwache Elissa Sternenhauch, dass dies getan wird?",a="Als eine Schildwache, die mit der Verteidigung von Auberdine betraut ist, ist Elissa Sternenhauch dafür verantwortlich, die Dunkelküste vor eindringenden Bedrohungen zu schützen. Sie sandte Balthule Schattenhieb aus, um verdächtige Vorfälle nahe dem Turm von Althalaxx zu untersuchen, aber er ist längst überfällig. Da sie fürchtet, dass er in unerwartete Gefahr geraten ist, braucht sie jemanden, der ihn aufspürt und seine Sicherheit bestätigt.",al={"warum balthule finden","elissa sternenhauch motiv","warum mich zum turm von althalaxx schicken"}}},fp="22,285,23.441.0,18.424.1,34.211.0,29.214.0,40.228.0,53.132.0,42.125.0,31.166.0"}
P.entries["quest:966"] = {n="Der Turm von Althalaxx",s="Während er verdächtige Aktivitäten rund um den Turm von Althalaxx an der nördlichen Dunkelküste untersucht, sichert sich der Späher Balthule Schattenhieb Hilfe, um Informationen von den sich versammelnden Hexenmeistern zu sammeln. Indem er weggeworfene Pergamentfetzen von den Fanatikern birgt, die vor den Ruinen lagern, versucht er, die Identität und die finsteren Absichten der Kultisten aufzudecken.",h="Während er verdächtige Aktivitäten rund um den Turm von Althalaxx an der nördlichen Dunkelküste untersucht...",kw={"althalaxx","auberdine","balthule","dunkler strang","dunkelküste","delgren","fanatiker","pergament","läuterer","schattenhieb","hexenmeister"},ang={["class:Paladin"]="Die Entdeckung eines geschlossenen dunklen Kults, der an der nördlichen Dunkelküste agiert, kommt direkt dem Kreuzzug von Delgren dem Läuterer zugute, einem Verbündeten, der sich der Säuberung von Teufels- und Dämonenverderbnis verschrieben hat.",["class:Warlock"]="Der Kult des dunklen Strangs beweist, dass ungebundene Zirkel uralte Ruinen in Beschlag nehmen, um ihre Beschwörungen fernab der neugierigen Blicke der Autoritäten von Allianz und Horde gleichermaßen durchzuführen.",["race:NightElf"]="Die Schändung des Turms von Althalaxx durch dunkle Kultisten stellt eine weitere Entweihung uralten elfischen Erbes an den Küsten von Kalimdor dar."},sec={{t="Augen in den Untiefen",b="Balthule Schattenhieb hält an der nebligen Küste der nördlichen Dunkelküste Wache und behält die uralte Ruine im Auge, die als der Turm von Althalaxx bekannt ist. Ausgesandt, um den Ort für Auberdine zu überwachen und Delgren den Läuterer vor jeglicher aufkeimenden Gefahr zu warnen, zögerte Balthule, seinen Posten für einen Bericht zu verlassen. Aus Furcht, entscheidende Bewegungen der dunklen Zauberwirker zu verpassen, die das Mauerwerk besetzen, verlässt er sich stattdessen auf vorbeireisende Wanderer, um die Lager am Randbereich auszukundschaften."},{t="Entzifferung des Kults",b="Die niederen Anhänger, die das Ruinengelände heimsuchen, tragen bruchstückhafte Schriftrollen und Notizen bei sich. Indem er mehrere abgenutzte Pergamente zusammenfügt, die von diesen äußeren Kultisten erbeutet wurden, stößt Balthule auf einen beunruhigenden Namen: den Kult des dunklen Strangs. Völlig unvertraut mit dieser finsteren Sekte erkennt der Späher, dass die Gefahr organisierter ist als eine einfache Bande abtrünniger Hexenmeister, was eine sofortige Warnung an Delgren erfordert."}},faq={{q="Wer ist Balthule Schattenhieb?",a="Balthule Schattenhieb ist ein Späher der Allianz, der an der Straße nahe dem Turm von Althalaxx an der nördlichen Dunkelküste stationiert ist. Er wurde entsandt, um im Auftrag der Führung von Auberdine und des Paladins Delgren der Läuterer verdächtige Zusammenkünfte am Turm zu überwachen.",al={"balthule schattenhieb geschichte","wer ist balthule","balthule dunkelküste"}},{q="Was ist der Turm von Althalaxx?",a="Der Turm von Althalaxx ist eine uralte Elfenruine an der nördlichen Dunkelküste. Vor Kurzem haben finstere Hexenmeister und ihre kultistischen Knechte das umliegende Gelände sowie das Innere des Turms besetzt und vollziehen dort fernab der Wache von Auberdine dunkle Rituale.",al={"turm von althalaxx","was ist althalaxx","dunkelküste zerstörter turm"}},{q="Wer sind die Kultisten rund um den Turm?",a="Sie gehören zum Kult des dunklen Strangs, einer geheimnisvollen Organisation von Hexenmeistern und Fanatikern, die sich an den uralten Elfenruinen versammelt haben, um dunkle Beschwörungsrituale durchzuführen.",al={"wer sind die hexenmeister","kult des dunklen strangs","fanatiker des dunklen strangs"}},{q="Warum warnt Balthule davor, den Turm zu betreten?",a="Balthule merkt an, dass die im oberen Turmbereich weilenden Hexenmeister weitaus mächtiger und gefährlicher sind als die Fanatiker, die draußen inmitten der Ruinen lagern. Er rät dazu, zunächst Informationen im Randbereich zu sammeln, bevor man versucht, die Festung zu stürmen.",al={"kann ich den turm betreten","turm hexenmeister gefährlich","im inneren des turms"}},{q="Was offenbaren die abgenutzten Pergamente?",a="Bruchstückhafte Schnipsel, die von den Fanatikern des Kults mitgeführt werden, liefern die erste eindeutige Bestätigung des Namens der Gruppe – der Kult des dunklen Strangs – und offenbaren Balthule, dass es sich bei den Besetzern um eine organisierte Sekte handelt, deren Anwesenheit eine unmittelbare Bedrohung für die Region darstellt.",al={"was steht auf den pergamenten","abgenutztes pergament geschichte","kultnotizen"}},{q="Wer ist Delgren der Läuterer?",a="Delgren der Läuterer ist ein Paladin der Allianz, der an Maestras Posten im Eschental stationiert ist und daran arbeitet, dämonische und verderbte Einflüsse zu läutern. Er vermutete, dass am Turm von Althalaxx bösartige Umtriebe Fuß fassten, und ist für Aufklärungsdaten auf Späher wie Balthule angewiesen.",al={"delgren","wer ist delgren","delgren der läuterer"}}},fx={bc625320={q="Warum möchte Balthule Schattenhieb, dass dies getan wird?",a="Balthule Schattenhieb befürchtet, dass sich dunkle Mächte im Geheimen direkt an den Grenzen der Dunkelküste versammeln. Während Delgren vermutete, dass sich Hexenmeister in den alten Ruinen versammelten, weiß keiner von ihnen, wer sie sind oder welches niederträchtige Ritual sie zu vollziehen gedenken. Balthule benötigt genügend schriftliche Beweise, um ihre Identität und ihre Motive zusammenzusetzen, bevor er entscheidende Maßnahmen zum Schutz der Region ergreift.",al={"warum will balthule pergamente","balthule motiv","warum althalaxx untersuchen"}},["151da73d"]={q="Warum schickt Euch Balthule Schattenhieb, anstatt selbst zu gehen?",a="Balthule ist auf einer einsamen Aufklärungswache außerhalb der Ruinen stationiert. Er kann seinen Posten nicht verlassen, um die umliegenden Kultistenlager zu durchkämmen oder nach Auberdine zurückzukehren, um Bericht zu erstatten, in der Angst, dass jede Abwesenheit dazu führen könnte, dass er kritische feindliche Bewegungen verpasst. Indem er Euch die äußeren Kultisten konfrontieren und ihre Schriften bergen lässt, kann er die ständige Überwachung des Turms aufrechterhalten.",al={"warum braucht balthule hilfe","warum nicht balthule selbst","warum bittet balthule euch"}}},fp="22,337,20.454.0,20.404.1,29.253.0,31.250.0,43.171.0,50.247.0,35.255.0,28.265.0"}
P.entries["quest:96604"] = {n="The Great Outdoors",s="The Great Outdoors ist eine einführende Quest zum Überleben in der Wildnis, die von Brakk für angehende Abenteurer angeboten wird. Indem sie lernen, sich neben einem einfachen Lagerfeuer auszuruhen, entdecken Reisende die Grundlagen der Selbstversorgung in der Wildnis, bevor sie praktischen Handwerksfertigkeiten nachgehen.",h="The Great Outdoors ist eine einführende Quest zum Überleben in der Wildnis, die von Brakk für angehende...",kw={"boosted rest","brakk","lageraufbau","lagerfeuer","the great outdoors","handwerksfertigkeit","überleben in der wildnis"},ang={["faction:Horde"]="Mit einem traditionellen orkischen „Lok-tar“ begrüßt, bietet diese Überlebenslektion angehenden Abenteurern der Horde eine grundlegende Basis, bevor sie zu Reisen durch tückische Gebiete aufbrechen."},sec={{t="Lektionen in der Wildnis",b="Sich in die ungezähmten Weiten von Azeroth vorzuwagen, erfordert mehr als kriegerischen Mut; es verlangt das grundlegende Wissen, um den Elementen zu trotzen. Brakk begrüßt angehende Abenteurer mit einem herzlichen „Lok-tar“ und erkennt den rastlosen Geist derer an, die nach Glück und Ruhm streben. Um den langen Weg vor ihnen zu überstehen, muss jeder Reisende zuerst die Kunst beherrschen, ein Lager aufzuschlagen und inmitten der Wildnis neue Kraft zu schöpfen."},{t="Vom Herd zum Handwerk",b="Sich neben Brakks einfachem Lagerfeuer niederzulassen vermittelt das Wesentliche der Erholung und gewährt eine stärkende Rast unter freiem Himmel. Sobald diese Grundlagen des Überlebens verstanden sind, werden unerfahrene Abenteurer zu Handwerkern des örtlichen Dorfes gewiesen. Dort können sie Handwerksfertigkeiten erlernen und entdecken, wie man funktionale, auf ihr gewähltes Handwerk abgestimmte Lageraufbauten errichtet."}},faq={{q="Was ist The Great Outdoors?",a="The Great Outdoors ist eine einführende Überlebensquest von Brakk, die neuen Abenteurern beibringen soll, wie man in der Wildnis gedeiht, indem man sich an einem Lagerfeuer ausruht, bevor man einen Beruf ergreift.",al={"was ist the great outdoors","the great outdoors quest"}},{q="Wer ist Brakk?",a="Brakk ist ein erfahrener Überlebenskünstler in der freien Natur, der rastlose Reisende willkommen heißt und praktische Lektionen zum Überleben in der Wildnis sowie zum Rasten an einem Lagerfeuer erteilt.",al={"wer ist brakk","questgeber"}},{q="Was ist der Stärkungszauber Boosted Rest?",a="Das Ausruhen in der Nähe von Brakks einfachem Lagerfeuer gewährt den Stärkungszauber Boosted Rest und zeigt, wie das Finden von Schutz und das Erholen an einer offenen Flamme einen Abenteurer in der Wildnis wiederbelebt.",al={"boosted rest stärkungszauber","lagerfeuer stärkungszauber"}},{q="Was solltet Ihr nach Abschluss der Quest tun?",a="Nachdem sie die Grundlagen des Rastens in der Wildnis erlernt haben, rät Brakk den Abenteurern, Lehrer im nahe gelegenen Dorf aufzusuchen, um eine Handwerksfertigkeit zu studieren und zu lernen, wie man auf ihr Handwerk zugeschnittene Lageraufbauten errichtet.",al={"nächster schritt nach der quest","was tun nach dem lagerfeuer"}},{q="Was sind Lageraufbauten?",a="Lageraufbauten sind spezialisierte Lagerplatz-Installationen, die von Berufslehrern in nahe gelegenen Dörfern gelehrt werden und es Reisenden ermöglichen, ihre Lager anzupassen, um ihre gewählten Handwerksfertigkeiten zu unterstützen.",al={"lageraufbauten","was sind lageraufbauten"}},{q="Für wen ist diese Ausbildung gedacht?",a="Jede rastlose Seele, die in der Wildnis nach Glück und Ruhm sucht, profitiert von dieser Lektion, insbesondere jene, die ihre Reise gerade erst beginnen und sich darauf vorbereiten, ein Handwerk zu wählen.",al={"wer sollte diese quest machen","ist das für die horde"}}},fp="18,262,19.401.0,20.356.0,27.194.0,13.153.0,30.169.0,46.198.0,23.179.0,34.163.0"}
P.entries["quest:96605"] = {n="The Great Outdoors",s="The Great Outdoors ist eine einführende Quest, die angehende Abenteurer in den grundlegenden Künsten des Überlebens in der Wildnis unterweist. Unter der Führung des Reisenden Kaga lernen Neulinge, wie man sich an einem einfachen Lagerfeuer erholt, bevor sie dazu übergehen, Berufsfertigkeiten zu erlernen und spezialisierte Lagereinrichtungen herzustellen.",h="The Great Outdoors ist eine einführende Quest, die angehende Abenteurer in den grundlegenden Künsten des...",kw={"boosted rest","lager-einrichtung","lagerfeuer","kaga","überleben","the great outdoors","fertigkeit","wildnis"},ang={["profession:Cooking"]="Lagerfeuer und das Überleben in der Wildnis bilden das Fundament des Kochens im Feld, wodurch das Lagerhandwerk eine natürliche Ergänzung zur Zubereitung von Mahlzeiten unter freiem Himmel darstellt."},sec={{t="Lehren der Wildnis",b="Jeder Abenteurer, der seinen Fuß jenseits der Sicherheit der Zivilisation setzt, stellt schnell fest, dass bloßer Mut nicht ausreicht, um im Grenzland zu überleben. The Great Outdoors führt Neulinge an die lebenswichtige Notwendigkeit der Akklimatisierung in der Wildnis heran. Diese kurze Lektion, gelehrt vom erfahrenen Reisenden Kaga, erinnert angehende Helden daran, dass das Gedeihen in unerforschten Gebieten damit beginnt, zu wissen, wie man ein Lager aufschlägt und den Elementen im Freien trotzt."},{t="Die Herdstelle und das Handwerk",b="Ein einfaches Lagerfeuer ist oft alles, was zwischen einem Forscher und der Erschöpfung der ungezähmten Wildnis steht. Indem sie sich neben Kagas Herdstelle setzen und den Stärkungszauber Boosted Rest erhalten, entdecken Abenteurer die erholsame Kraft des Lagerlebens. Sobald die Grundlagen der Rast in der Wildnis verstanden sind, drängt Kaga die Reisenden, Handwerker in nahe gelegenen Siedlungen aufzusuchen, um Berufsfertigkeiten zu erlernen und die Herstellung professioneller Lagereinrichtungen zu meistern."}},faq={{q="Was ist The Great Outdoors?",a="The Great Outdoors ist eine einführende Wildnis-Überlebensquest, die von Kaga angeboten wird. Sie führt angehende Abenteurer in die Grundlagen des Überlebens in der Wildnis, des Ausruhens an einem Lagerfeuer und der Vorbereitung auf professionelle Berufe ein.",al={"was ist the great outdoors","the great outdoors quest"}},{q="Wer bietet diese Quest an?",a="Kaga ist ein erfahrener Reisender und Überlebensmentor, der angehende Abenteurer in den Grundlagen des Überlebens in der Wildnis anleitet. Er unterhält ein einfaches Lagerfeuer, an dem Neulinge lernen können, sich auszuruhen und zu erholen.",al={"wer ist kaga","kaga questgeber"}},{q="Was ist der Boosted Rest Stärkungszauber?",a="Boosted Rest ist der vorteilhafte Zustand der Entspannung, den man erlangt, wenn man friedlich neben Kagas Basic Campfire sitzt. Er stellt die verjüngende Wirkung dar, die eine angemessene Rast an einem Wildnislagerplatz mit sich bringt.",al={"boosted rest","was ist der boosted rest buff"}},{q="Was sind Lagereinrichtungen?",a="Nachdem sie das grundlegende Rasten in der Wildnis gemeistert haben, können Handwerkslehrer in nahe gelegenen Siedlungen Abenteurern beibringen, wie man spezialisierte, auf ihr jeweiliges Handwerk zugeschnittene Lagereinrichtungen errichtet.",al={"lager-inventar überlieferung","berufs-lager-inventar"}},{q="Warum lässt Kaga Euch am Lagerfeuer sitzen?",a="Das Überleben außerhalb zivilisierter Städte erfordert das Erlernen, wie man ein Lager aufschlägt und Ausdauer zurückgewinnt. Das Sitzen an einem Lagerfeuer ermöglicht es Abenteurern, zwischen gefährlichen Reisen Wärme, Fokus und erholte Regeneration zu erlangen.",al={"warum am lagerfeuer ausruhen","lagerfeuer-rasten"}},{q="Was solltet Ihr nach Abschluss dieser Lektion tun?",a="Nachdem man gelernt hat, wie man in der Wildnis richtig rastet, rät Kaga dazu, Lehrer für Berufe im nahe gelegenen Dorf aufzusuchen, um ein Handwerk zu erlernen und Rezepte für berufsspezifische Lagereinrichtungen zu erwerben.",al={"wie weiter nach the great outdoors","nach kaga quest"}}},fp="18,289,19.425.0,24.429.0,27.225.0,22.193.0,30.193.0,23.181.0,43.199.0,48.186.0"}
P.entries["quest:96606"] = {n="The Great Outdoors",s="The Great Outdoors ist eine einführende Wildnis-Überlebenslektion, die Jägern von einer erfahrenen Kundschafterin namens Lyreena angeboten wird. Sie betont, wie wichtig es ist, sich an einem Lagerfeuer auszuruhen, um sich zu erholen und den Stärkungszauber Boosted Rest zu erhalten, während man durch die ungezähmte Wildnis reist.",h="The Great Outdoors ist eine einführende Wildnis-Überlebenslektion, die Jägern von einer erfahrenen...",kw={"abenteurer","boosted rest","lagerfeuer","jäger","lyreena","überleben","the great outdoors","wildnis"},ang={["class:Hunter"]="Diese direkt an Jäger gerichtete Lektion unterstreicht die Notwendigkeit des Überlebens in der Wildnis und des Lagerlebens, wenn man durch die ungezähmte Wildnis spürt."},sec={{t="Lehren der Wildnis",b="Sich jenseits der Grenzen der Zivilisation zu wagen, erfordert mehr als eine zielsichere Hand und geschärfte Sinne; es verlangt Respekt vor den rohen, ungezähmten Elementen. Eine erfahrene Kundschafterin namens Lyreena bietet wandernden Jägern ihre Führung an und lädt sie ein, ihre Reise zu unterbrechen und an ihrem Lagerfeuer Trost zu finden. In der gefährlichen Wildnis von Azeroth ist das Wissen, wie man eine Feuerstelle errichtet und zwischen den Jagden neue Kräfte sammelt, ebenso entscheidend wie das Aufspüren von Beute."},{t="Erholung am Lagerfeuer",b="Ein prasselndes Lagerfeuer spendet Behaglichkeit gegen die nächtliche Kälte und bietet einen Moment der Ruhe, in dem müde Reisende ihre Erschöpfung abschütteln können. Wenn Abenteurer nahe an den Flammen sitzen, erhalten sie Boosted Rest, was ihre Energie belebt und sie auf die Härten der Erkundung vorbereitet. Sich die Zeit zu nehmen, an der Glut zu sitzen, lehrt junge Abenteurer, dass Geduld und Ruhe beständige Grundpfeiler des Überlebens in der Wildnis sind."}},faq={{q="Wer ist Lyreena?",a="Lyreena ist eine erfahrene Wildnislernmeisterin, die angehenden Abenteurern und Jägern beibringt, wie man sich draußen in den Elementen richtig ausruht und überlebt. An ihrem Lagerfeuer gibt sie praktische Ratschläge.",al={"wer ist lyreena","lyreena lagerfeuer","questgeber"}},{q="Was ist The Great Outdoors?",a="The Great Outdoors ist eine einführende Wildnis-Überlebensaufgabe, bei der eine erfahrene Überlebenskünstlerin namens Lyreena Jäger dazu einlädt, sich an ihr Lagerfeuer zu setzen und zu lernen, wie sie sich auf langen Expeditionen selbst versorgen.",al={"was ist the great outdoors","was ist diese quest","the great outdoors quest"}},{q="Was ist Boosted Rest?",a="Wenn sich müde Wanderer in unmittelbarer Nähe eines einfachen Lagerfeuers niederlassen, können sie sich von den Strapazen der Reise erholen und den Effekt Boosted Rest erhalten, der ihre Lebensgeister für bevorstehende Reisen neu entfacht.",al={"boosted rest stärkungszauber","boosted rest lagerfeuer","wie man boosted rest erhält"}},{q="Warum müsst Ihr Euch an einem Lagerfeuer ausruhen?",a="Lagerfeuer spenden lebenswichtige Wärme und Erholung in der rauen Wildnis. Wer in der Nähe eines Feuers rastet, kann wieder zu Atem kommen, den Geist klären und sich auf gefährliche Wanderungen durch ungezähmte Lande vorbereiten.",al={"zweck des lagerfeuers","warum am feuer sitzen","ausruhen am lagerfeuer"}},{q="Warum ist das Überleben im Freien für Jäger so wichtig?",a="Jäger verbringen den Großteil ihres Lebens damit, abgelegene Gebiete ohne Tavernen oder sichere Städte in der Nähe zu durchstreifen. Das Beherrschen grundlegender Lagerfertigkeiten stellt sicher, dass ein Jäger rauen Umgebungen trotzen kann, ohne der Erschöpfung zu erliegen.",al={"jäger überlebensfertigkeiten","überleben in der wildnis","warum jägerquest"}},{q="Was müsst Ihr tun, um die Aufgabe abzuschließen?",a="Um die Aufgabe abzuschließen, müsst Ihr Euch lediglich in der Nähe von Lyreenas einfachem Lagerfeuer niederlassen und eine kurze Weile warten, bis die Wärme des Lagerfeuers den Stärkungszauber Boosted Rest gewährt.",al={"questziel","wie man the great outdoors abschließt","the great outdoors ziele"}}},fp="18,266,19.439.0,16.406.0,15.191.0,27.207.0,21.189.0,38.200.0,44.214.0,38.164.0"}
P.entries["quest:96607"] = {n="Die große weite Welt",s="Die große weite Welt ist eine einführende Überlebenslektion, die erfahrene Reisende frisch gebackenen Wanderern in ganz Azeroth anbieten. Indem sie einen Moment an einem warmen Lagerfeuer verweilen, lernen Neulinge, wie man durch Erholung und Vorbereitung jenseits der Stadtmauern am Leben bleibt. Es markiert den ersten Schritt zur Meisterung des Überlebens in der Wildnis und spezialisierter Feldlager.",h="Die große weite Welt ist eine einführende Überlebenslektion, die erfahrene Reisende frisch gebackenen...",kw={"adventurer","erhöhte erholung","lagerfeuer","zelten","eleanor shackleton","wald von elwynn","sam sarsaparilla","überleben","handwerksfertigkeit"},ang={["faction:Alliance"]="In der Sicherheit des Walds von Elwynn lernen menschliche Reisende diese Grundlagen des Überlebens von erfahrenen Wanderern, bevor sie sich den härteren Gefahren stellen, die in Westfall und im Rotkammgebirge lauern.",["faction:Horde"]="Ob beim Durchqueren der trockenen Ebenen von Durotar oder der windgepeitschten Mesas von Mulgore: Die Überlebensexperten der Horde bringen jedem jungen Krieger Feuerkunst und Disziplin in der Wildnis bei.",["profession:Cooking"]="Jedes Lager in der Wildnis beginnt mit einem Feuer, was das Kochen zum natürlichen Begleiter des Überlebens in der Wildnis macht. Im Anschluss an diese Lektion weisen Euch erfahrene Camper direkt zu kulinarischen Unterweisungen am Wegesrand an."},sec={{t="Lektionen des Pfades",b="Ganz gleich, wie scharf Eure Klinge oder wie mächtig Eure Magie ist: Die Wildnis von Azeroth zermürbt jeden schnell, der die Grundlagen des Überlebens vernachlässigt. Erfahrene Wanderer, die an Lichtungen am Wegesrand postiert sind, bieten Reisenden, die aus ihren Heimattälern aufbrechen, diese einfache Lektion an. Sich Zeit zu nehmen, um an einem Lagerfeuer zu ruhen, lindert nicht nur schmerzende Stiefel – es beruhigt den Geist und bereitet die Seele auf den beschwerlichen Weg vor. Nur wer die Disziplin regelmäßiger Rast und Vorbereitung beherrscht, hat eine Chance, lange genug zu überleben, um Ruhm und Ehre zu erlangen."},{t="Ein Zuhause fern der Heimat",b="Sobald ein Abenteurer den Wert eines knisternden Feuers und angemessener Ruhe begreift, weisen die Ausbilder ihn direkt an die Handwerker der Stadt. Ein Lager im Feld ist selten komplett mit nur einer Glut und einer Schlafrolle; Überleben erfordert praktische Fertigkeiten. Ob man Ersatznieten schmiedet, Rationen für den Weg kocht oder zerrissene Ausrüstung unter dem Sternenhimmel flickt – jeder Beruf bietet einzigartige Lagereinrichtungen, um einen kargen Berghang in einen autarken Außenposten zu verwandeln."}},faq={{q="Wer bietet neuen Wanderern diese Lektion an?",a="Eine Vielzahl erfahrener Reisender bietet diese Führung an, je nachdem, wo Ihr Euch befindet. Im Wald von Elwynn tritt der erfahrene Wanderer Sam Sarsaparilla hervor, während andernorts Gestalten wie Eric Brighthammer, Lyreena Duskblade, Brakk, Eleanor Shackleton, Kaga Wildhoof und Raan Wildwind ihre Wildniserfahrung teilen.",al={"wer vergibt die große weite welt","wer startet die große weite welt","questgeber die große weite welt"}},{q="Was ist der Zweck des Sitzens am Lagerfeuer?",a="Ruhig an einem lodernden Lagerfeuer zu sitzen, lässt einen Abenteurer zu Atem kommen und einen Effekt für erhöhte Erholung erhalten. Bewusste Pausen im Feld sind unerlässlich, um Eure Kräfte bei langen Expeditionen durch die Wildnis aufrechtzuerhalten.",al={"warum ans feuer setzen","was bringt lagerfeuer","erhöhte erholung stärkungszauber"}},{q="Wohin führt diese Ausbildung als Nächstes?",a="Sobald Ihr Eure Rast am Feuer beendet habt, weist Euer Mentor Euch an nahegelegene Siedlungen, um praktische Handwerksfertigkeiten zu erlernen. Von dort aus beginnt Ihr mit Grundlagen des Zeltens: Kochen sowie mit speziellen Lektionen für Feldlager, die auf den von Euch gewählten Beruf zugeschnitten sind.",al={"was kommt nach die große weite welt","die große weite welt nächste quest","campingquests"}},{q="Können auch Abenteurer der Horde an dieser Lektion teilnehmen?",a="Ja. Das Überleben in der rauen Wildnis ist unabhängig von der Fraktionszugehörigkeit eine Notwendigkeit. Erfahrene Ausbilder sowohl der Allianz als auch der Horde – wie Brakk, Eleanor Shackleton und Kaga Wildhoof – lehren den Initianden ihrer Fraktion genau dieselben grundlegenden Fertigkeiten des Lagerlebens.",al={"nur für allianz","horde die große weite welt","können orcs diese quest machen"}},{q="Warum weisen die Ausbilder einen an, mit Handwerkslehrern zu sprechen?",a="Überleben erfordert mehr, als nur an den Flammen zu sitzen; ein Abenteurer muss auf sich selbst gestellt sein können. Handwerkslehrer bringen Euch bei, wie man spezialisierte Lagereinrichtungen herstellt, mit denen Ihr Eurem Handwerk nachgehen könnt – sei es das Kochen von Rationen für unterwegs, das Flicken von Rüstungen oder das Brauen von Heilmitteln unter freiem Himmel.",al={"warum berufe lernen","lagereinrichtungen handwerkslehrer","beruf verbindung lager"}},{q="Welche Vorerfahrung wird vor der Annahme dieser Quest erwartet?",a="Abenteurer erhalten diese Lektion typischerweise direkt im Anschluss an 'The Adventurer', sobald sie ihren grundlegenden Ehrgeiz bewiesen haben und über ihre Startgebiete hinaus in die weitere Region gezogen sind.",al={"voraussetzungen für die große weite welt","wie schalte ich die große weite welt frei","vor die große weite welt"}}},fp="18,359,20.539.0,21.445.0,40.310.0,47.231.0,35.262.0,52.261.0,61.278.0,59.186.0"}
P.entries["quest:96608"] = {n="The Great Outdoors",s="The Great Outdoors führt umherziehende Abenteurer an die Grundlagen des Überlebens in der Wildnis und der Lagerkunst heran. Indem sie an Erics Lagerfeuer Platz nehmen, lernen Reisende, wie sie sich in der Wildnis richtig erholen, bevor sie Berufsfertigkeiten erlernen, um ihre Reisen zu unterstützen.",h="The Great Outdoors führt umherziehende Abenteurer an die Grundlagen des Überlebens in der Wildnis und der...",kw={"boosted rest","camp fixture","lagerfeuer","eric","überleben","the great outdoors","fertigkeit","wildnis"},ang={["class:Priest"]="Während Priester ihre Berufung oft in heiligen Zufluchten und Kapellen finden, erfordert das Leben auf der Straße praktische Überlebensfertigkeiten, die über Gebete und Segen hinausgehen."},sec={{t="Lektionen der Wildnis",b="Der Schritt hinaus in die weite Welt erfordert mehr als nur Ehrgeiz und eine Waffe oder ein heiliges Symbol. Für unerfahrene Reisende hängt das Überleben davon ab, zu wissen, wie man sich inmitten der Elemente richtig ausruht. An seinem einfachen Lagerfeuer heißt der erfahrene Reisende Eric umherziehende Abenteurer willkommen, Platz zu nehmen, sich an der Glut zu wärmen und zu entdecken, wie wichtig die richtige Erholung ist, bevor man sich der ungezähmten Wildnis stellt."},{t="Vom Lagerfeuer zum Handwerk",b="Ein einfaches Feuer ist nur der Anfang, um auf langen Reisen ein effektives Lager zu unterhalten. Nachdem sie die Grundlagen der Erholung in der Wildnis erlernt haben, werden Reisende ermutigt, Berufslehrer in benachbarten Siedlungen aufzusuchen. Dort bringen Handwerker und Hersteller ihnen bei, wie man spezialisierte Lagervorrichtungen errichtet, was es Abenteurern ermöglicht, ihre Berufe auszuüben und ihre Expeditionen zu unterstützen, wohin auch immer der Weg führt."}},faq={{q="Wer ist Eric?",a="Eric ist ein erfahrener Naturbursche und Mitabenteurer, der anbietet, unerfahrenen Reisenden die Grundlagen des Überlebens in der Wildnis beizubringen. Er heißt Reisende willkommen, sich an seinem Lagerfeuer auszuruhen, und gibt praktische Ratschläge, wie man fernab von Stadtmauern gedeiht.",al={"wer vergibt diese quest","wer ist eric","wer lehrt the great outdoors"}},{q="Was ist der Boosted-Rest-Stärkungszauber?",a="Das Ausruhen an Erics Lagerfeuer gewährt den Boosted-Rest-Effekt, der müden Reisenden hilft, sich zu erholen und ihren Geist auf die bevorstehenden Prüfungen vorzubereiten. Er steht dafür, sich eine Auszeit von den Elementen zu nehmen, um sich im Feld richtig zu erholen.",al={"was ist boosted rest","wie hilft das lagerfeuer","erholungsstärkung im lager"}},{q="Was sind Lagervorrichtungen?",a="Lagervorrichtungen sind praktische Strukturen oder Werkzeuge, die auf bestimmte Berufsfertigkeiten zugeschnitten sind und von Abenteurern in der Wildnis aufgestellt werden können. Wie Berufslehrer in nahe gelegenen Siedlungen erklären, ermöglicht das Erlernen eines Berufs Handwerkern, funktionale Arbeitsplätze an ihren Lagern einzurichten.",al={"was sind camp fixtures","berufsvorrichtungen","fertigkeiten lagergegenstand"}},{q="Warum müsst Ihr in der Nähe von Erics Lagerfeuer sitzen?",a="Wenn Abenteurer am Lagerfeuer Platz nehmen, können sie innehalten, sich aufwärmen und Erics Ratschlägen zum Überleben in der Wildnis lauschen. Es gibt dem Körper Zeit, sich zu entspannen und den vollen Nutzen aus einem erholsamen Unterschlupf im Freien zu ziehen.",al={"warum am feuer sitzen","am lagerfeuer sitzen","lagerfeuer ziel"}},{q="Wohin sollte ein Abenteurer nach Abschluss dieser Lektion gehen?",a="Nachdem Ihr die Grundlagen des Ausruhens im Lager gemeistert habt, schlägt Eric vor, in das nahe gelegene Dorf zu gehen, um bei den örtlichen Handwerkslehrern eine Berufsfertigkeit zu erlernen. Sobald Ihr ausgebildet seid, könnt Ihr damit beginnen zu lernen, wie man Lagervorrichtungen baut, die zu Eurem Handwerk passen.",al={"was danach zu tun ist","wohin als nächstes","nach the great outdoors"}},{q="Für wen ist diese Überlebenslektion gedacht?",a="Eric ruft vorbeiziehenden Abenteurern zu und bemerkt ihren rastlosen Geist sowie ihre Bereitschaft, in der ganzen Welt nach Reichtum und Ruhm zu suchen. Seine Ratschläge für die Wildnis helfen jedem, der die Sicherheit hinter sich lässt und sich in die offene Wildnis wagt.",al={"wer kann diese quest annehmen","nur priester","ist das für abenteurer"}}},fp="18,255,19.391.0,22.411.0,12.250.0,30.227.0,23.266.0,44.212.0,59.230.0,41.227.0"}
P.entries["quest:96626"] = {n="Camping 101: Cooking",s="Camping 101: Cooking lehrt angehende Abenteurer, dass Kochen der grundlegende Eckpfeiler beim Errichten eines Lagers in der Wildnis ist. Indem sie das Handwerk von Koch Tomas in Goldhain erlernen, erlangen Reisende die Fähigkeit, Lagerfeuer zu entfachen und ihre eigenen Lager in der Wildnis aufzuschlagen.",h="Camping 101: Cooking lehrt angehende Abenteurer, dass Kochen der grundlegende Eckpfeiler beim Errichten eines...",kw={"lagerfeuer","camping","camping 101: cooking","lagerplatz","kochen","ausstattung","goldhain","tomas"},ang={["faction:Alliance"]="Unerfahrene Abenteurer der Allianz im Wald von Elwynn werden zu Koch Tomas im Gasthaus \"Zur Höhle des Löwen\" in Goldhain geschickt, um die Grundlagen der Kochkunst und das Errichten von Lagerfeuern zu meistern.",["profession:Cooking"]="Die Ausbildung in der Kochkunst dient als unverzichtbare Grundlage für das Überleben in der Wildnis und verleiht Abenteurern die Fertigkeit, einfache Lagerfeuer zu errichten, die als Mittelpunkt ihrer Lagerplätze dienen."},sec={{t="Die Feuerstelle in der Wildnis",b="Für jeden Abenteurer, der den Weiten der Wildnis von Azeroth trotzt, beginnt das Aufschlagen eines Lagers mit einem verlässlichen Feuer. Die Quest Camping 101: Cooking bringt unerfahrenen Wanderern bei, dass es bei der kulinarischen Ausbildung nicht bloß um das Zubereiten warmer Mahlzeiten geht; sie ist das entscheidende Fundament für das Überleben in der Wildnis. Durch das Meistern des Kochberufs lernen Reisende, wie man ein ordentliches Lagerfeuer entfacht, und verwandeln so eine ungezähmte Lichtung in eine sichere Zuflucht."},{t="Unterweisung in Goldhain",b="Neue Reisende im Wald von Elwynn werden losgeschickt, um mit Koch Tomas in Goldhain zu sprechen und die Grundlagen des Handwerks zu erlernen. Nach seiner Unterweisung erhalten Abenteurer die Fähigkeit, einfache Lager in der Wildnis zu errichten. Während anfängliche Lager schlicht sind und nur begrenzte Ausstattung fassen, schaltet das Verfeinern der eigenen Kochfertigkeit größere Feuer frei, während andere Handwerksdisziplinen weitere Möglichkeiten bieten, einen Lagerplatz einzurichten und anzupassen."}},faq={{q="Was ist die Quest Camping 101: Cooking?",a="Camping 101: Cooking führt Abenteurer an die Grundlagen des Überlebens in der Wildnis heran. Sie leitet Euch dazu an, den Kochberuf zu ergreifen, und lehrt Euch, ein einfaches Lagerfeuer zu entfachen, das als Herzstück für Euren Lagerplatz draußen in der Wildnis dient.",al={"was ist camping 101 cooking","was lehrt camping 101","zweck von camping 101"}},{q="Wer ist Tomas und wo ist er zu finden?",a="Tomas ist der ansässige Kochlehrer in Goldhain im Wald von Elwynn. Ausgehend vom Gasthaus \"Zur Höhle des Löwen\" unterweist er angehende Abenteurer im einfachen Kochen und in der Kunst, ein Lagerfeuer zu entfachen.",al={"wer ist tomas","wo ist tomas","tomas goldhain"}},{q="Warum ist Kochen erforderlich, um einen Lagerplatz zu errichten?",a="Ein Lagerfeuer ist das Fundament eines jeden Lagers in der Wildnis. Das Erlernen des Kochens vermittelt das unverzichtbare Wissen, das zum Errichten eines Feuers erforderlich ist, an dem sich ein Abenteurer ausruhen und seine Lagerausstattung anordnen kann.",al={"warum brauche ich kochen zum campen","ist kochen zum campen erforderlich","beziehung zwischen kochen und lagerfeuer"}},{q="Kann man mit steigender Fertigkeit größere Lagerfeuer errichten?",a="Das Verbessern Eurer Kochkunst erlaubt es Euch, größere und stabilere Feuer zu errichten. Mit der Weiterentwicklung Eurer Kochfertigkeit wird Euer Lagerfeuer zu einem solideren Stützpunkt für Erkundungen in der Wildnis.",al={"wie man ein lagerfeuer aufwertet","kann ich größere lagerfeuer errichten","größere feuer durch kochen"}},{q="Wie erhält man Ausstattung für seinen Lagerplatz?",a="Über das Kochen hinaus kann zusätzliche Lagerausstattung von anderen Handwerkstrainern auf der ganzen Welt erlernt werden. Abenteurer, die in verschiedenen Herstellungsberufen geschult sind, können Gegenstände herstellen, um ihre Wildnislager zu dekorieren und aufzuwerten.",al={"wie man lagerausstattung hinzufügt","woher lagerausstattung stammt","lagergegenstände herstellen"}},{q="Wo kann ein Abenteurer ein Lager aufschlagen?",a="Sobald Ihr die Grundlagen des Kochens und der Lagerfeuererstellung gemeistert habt, erlangt Ihr die Fähigkeit, ein Lager in der offenen Wildnis aufzuschlagen. Anfängliche Lagerplätze sind jedoch bescheiden und bieten nur Platz für eine minimale Anzahl von Ausstattungsstücken, bis Ihr Eure Fertigkeiten erweitert.",al={"kann ich überall mein lager aufschlagen","regeln fürs campen in der wildnis","grenzen für lagerplatzierung"}}},fp="20,267,22.409.0,24.423.0,39.254.0,39.203.0,48.210.0,53.190.0,49.228.0,36.245.0"}
P.entries["quest:96627"] = {n="Der Abenteurer",s="Der Abenteurer ist eine Wegweiseraufgabe von Marschall McBride im Nordhaintal. Da McBride Eure frühen Fähigkeiten anerkennt, schickt er Euch über das abgeschiedene Abteigelände hinaus in Richtung Goldhain, um einen Neuling namens Sam Sarsaparilla unter die Lupe zu nehmen.",h="Der Abenteurer ist eine Wegweiseraufgabe von Marschall McBride im Nordhaintal.",kw={"wald von elwynn","goldhain","marschall mcbride","nordhain","sam sarsaparilla","der abenteurer"},ang={["faction:Alliance"]="Für frische Rekruten der Allianz, die ihren Dienst in Nordhain beenden, markiert dies den ersten offiziellen Vorstoß in das weitere Reich des Waldes von Elwynn.",["race:Human"]="Menschliche Verteidiger, die aus der Abtei von Nordhain heraustreten, machen ihre ersten Schritte in Richtung Goldhain, dem belebten Herzen von Elwynn."},sec={{t="Das Tal verlassen",b="Sobald Rekruten das Nordhaintal von unmittelbaren Bedrohungen wie den hiesigen Defias und Ungeziefer befreit haben, blickt Marschall McBride die Straße hinab. Da die reguläre Militärpräsenz von Sturmwind über das gesamte Königreich hinweg dünn gesät ist, muss die örtliche Garnison auf vielversprechende Kämpfer zurückgreifen, um Reisende und Wanderer im Auge zu behalten, die die umliegenden Wälder durchstreifen."},{t="Ein merkwürdiger Neuling",b="Anstelle eines militärischen Befehls oder einer Kopfgeldjagd betraut McBride Euch mit einem ungewöhnlichen Auftrag: Ihr sollt nach einem bestimmten neuen Abenteurer namens Sam Sarsaparilla sehen, der nahe Goldhain gesichtet wurde. Die Bitte dient als Übergang aus dem abgelegenen Tal von Nordhain in die weitere, gefährlichere Ausdehnung des Waldes von Elwynn."}},faq={{q="Wer schickt mich auf diese Aufgabe?",a="Marschall McBride, der Kommandant der im Nordhaintal stationierten Garnison von Sturmwind, bietet diese Aufgabe an, sobald Ihr Euren Mut bei der Verteidigung der Abtei unter Beweis gestellt habt.",al={"questgeber","wer vergibt der abenteurer","marschall mcbride quest"}},{q="Wer ist Sam Sarsaparilla?",a="Sam Sarsaparilla ist ein Abenteurer, der sich an der Straße nahe Goldhain aufhält. Marschall McBride erfährt von seiner Anwesenheit und bittet Euch herauszufinden, was er im Schilde führt.",al={"sam sarsaparilla","wer ist sam","abenteurer in goldhain"}},{q="Wo finde ich Sam Sarsaparilla?",a="Er befindet sich an der Hauptstraße, die aus Nordhain hinaus in Richtung der Stadt Goldhain im Wald von Elwynn führt.",al={"sam sarsaparilla standort","wo ist sam","sam sarsaparilla finden"}},{q="Warum kümmert sich Marschall McBride um einen beliebigen Abenteurer?",a="Nordhain bleibt wegen Banditen und Eindringlingen in höchster Alarmbereitschaft. McBride zieht es vor, unbekannte Söldner und Wanderer, die durch die Region ziehen, genau im Auge zu behalten, und nutzt verlässliche Talente vor Ort für den Erstkontakt.",al={"warum werde ich geschickt","mcbrides motive","warum nach sam suchen"}},{q="Muss ich das Nordhaintal verlassen, um dies abzuschließen?",a="Ja. Diese Aufgabe führt Euch durch das Südtor des Nordhaintals hinaus auf die Waldstraße in Richtung Goldhain.",al={"außerhalb von nordhain","führt dies aus nordhain heraus","nach goldhain gehen"}},{q="Ist dies Teil der normalen militärischen Befehlskette von Sturmwind?",a="Obwohl sie von einem Offizier Sturmwinds erteilt wird, bezeichnet McBride sie ausdrücklich als ungewöhnliche Aufgabe statt als Standardwachdienst und vertraut dabei auf Euer Urteilsvermögen als unabhängiger Beschützer anstelle formaler militärischer Protokolle.",al={"streitkräfte von sturmwind","ist dies standarddienst","offizielle angelegenheit"}}},fx={dd262048={q="Warum wählt Marschall McBride mich aus, um Sam zu untersuchen?",a="Marschall McBride betrachtet dies eher als ungewöhnliche Aufgabe denn als Standardwachdienst. Nachdem er beobachtet hat, wie Ihr mit den lokalen Bedrohungen von Nordhain umgegangen seid, betrachtet er Euch als fähigen Beschützer, der diskret außerhalb der Abteitore agieren kann. Da seine eigene Garnison mit lokalen Problemen überlastet ist, macht es weit mehr Sinn, einen vertrauenswürdigen Rekruten zu schicken, der Gerüchten die Straße hinunter nachgeht, als reguläre Wachen zu entsenden.",al={"warum ich marschall mcbride","warum schickt mich mcbride","warum keine wache zu sam schicken"}}},fp="14,244,18.338.0,18.303.0,26.159.0,24.165.0,33.105.0,56.225.0,52.129.0,63.210.0"}
P.entries["quest:96628"] = {n="Der Abenteurer",s="Der Abenteurer ist ein lokaler Botengang von Gebirgsjäger Thalos am Südtor von Dun Morogh. Bevor er Reisende durch den Bergtunnel in Richtung Kharanos schickt, bittet Thalos sie darum, ein Bündel mit Vorräten zu Eric Brighthammer zu bringen, einem Neuankömmling, der unweit des Dorfes sein Lager aufgeschlagen hat.",h="Der Abenteurer ist ein lokaler Botengang von Gebirgsjäger Thalos am Südtor von Dun Morogh.",kw={"coldridgepass","dun morogh","eric brighthammer","kharanos","gebirgsjäger thalos","vorratsbündel","der abenteurer"},ang={["faction:Alliance"]="Die Gebirgsjäger verlassen sich auf Rekruten der Allianz, um wichtige Vorräte über die vereisten Straßen zu transportieren und sicherzustellen, dass umherziehende Verbündete vor Kharanos versorgt bleiben.",["race:Dwarf"]="Für junge Zwerge, die das Coldridgetal verlassen, ist das Überbringen von Vorräten an Eric Brighthammer ihr erster gemeinsamer Schritt an der Seite der Gebirgsjäger im weiteren Gebiet von Dun Morogh."},sec={{t="Ein Gefallen für die Gebirgsjäger",b="Die Bewachung der hohen Pässe und Tunnel zwischen dem Coldridgetal und den weiteren verschneiten Weiten von Dun Morogh ist eine anspruchsvolle Aufgabe für die Gebirgsjäger von Eisenschmiede. Am Grenztor postiert, hält Gebirgsjäger Thalos sowohl nach lokalen Gefahren als auch nach Reisenden auf dem ausgetretenen Pfad Ausschau. Als den Posten die Nachricht über einen einsamen Abenteurer erreicht, der in der Nähe von Kharanos eingetroffen ist, nutzt Thalos vertrauenswürdige Vorbeigehende, um nötige Vorräte weiterzubefördern und so Neuankömmlinge zu unterstützen, die sich in die gefrorenen Felsen wagen."},{t="Vorräte für Kharanos",b="Die Straße, die vom südlichen Pass herabführt, schlängelt sich zur Siedlung Kharanos, dem Hauptzentrum für Zwergenhandwerk und Reisen im Herzen von Dun Morogh. Eric Brighthammer hat sich vor Kurzem direkt am Rande des Dorfes niedergelassen. Indem Reisende ihm das Vorratsbündel der Gebirgsjäger überbringen, tragen sie dazu bei, eine wichtige Verbindung zwischen den vorgeschobenen Wachtposten auf den Kämmen und jenen zu knüpfen, die die Wildnis durchstreifen."}},faq={{q="Wer startet die Quest Der Abenteurer?",a="Gebirgsjäger Thalos bietet diese Quest an. Er hält Wache am Bergpasstorbau, der den Pfad aus dem Coldridgetal mit dem restlichen Dun Morogh verbindet.",al={"questgeber","wer vergibt der abenteurer","thalos quest"}},{q="Wer ist Eric Brighthammer?",a="Eric Brighthammer ist ein Abenteurer, der vor Kurzem vor den Toren der Zwergenstadt Kharanos eingetroffen ist. Gebirgsjäger Thalos schickt Reisende aus, um ihm ein wichtiges Bündel mit Vorräten zu bringen.",al={"wo ist eric brighthammer","wer ist der abenteurer","brighthammer"}},{q="Wo findet diese Übergabe statt?",a="Die Übergabe findet direkt vor den Toren von Kharanos in Dun Morogh statt, nördlich des Tunnels an der Eisklamm, an dem Gebirgsjäger Thalos stationiert ist.",al={"wo vorräte abliefern","eric brighthammer aufenthaltsort","vorratsbündel abgabe"}},{q="Warum schickt Gebirgsjäger Thalos Vorräte?",a="Die Gebirgsjäger behalten Reisende in ganz Dun Morogh im Auge. Als Thalos erfährt, dass ein Abenteurer nahe Kharanos ein Lager aufgeschlagen hat, veranlasst er den Transport von Proviant, um ihn in der Kälte zu unterstützen.",al={"warum vorräte schicken","thalos zweck","grund für das bündel"}},{q="Welchen Gegenstand tragt Ihr bei Euch?",a="Ihr tragt ein Vorratsbündel bei Euch, das Ihr direkt von Gebirgsjäger Thalos erhalten habt, um es Eric Brighthammer zu überbringen.",al={"welche vorräte","vorratsbündel gegenstand"}},{q="Ist diese Quest für Horde-Spieler verfügbar?",a="Nein. Gebirgsjäger Thalos ist eine der Allianz angehörende Zwergenwache in Dun Morogh, weshalb diese Aufgabe exklusiv der Allianz vorbehalten ist.",al={"kann die horde das machen","nur für die allianz","horde abenteurer quest"}}},fx={["95095969"]={q="Warum bittet Euch Gebirgsjäger Thalos, die Vorräte zu liefern?",a="Gebirgsjäger Thalos und seine Patrouille sind am Pass stationiert, mit der Aufgabe, die Straße zu bewachen und den Tunnel vor lokalen Gefahren zu sichern. Da Ihr ohnehin durch den Pass weiter Richtung Kharanos reist, bittet er Euch, die Lieferung auf Eurer Route mitzunehmen, anstatt seine Gebirgsjäger von ihren Wachposten abzuziehen.",al={"warum ich der abenteurer","warum braucht thalos mich","warum spieler zu eric brighthammer schicken"}}},fp="14,279,28.484.0,21.418.0,36.140.0,25.178.0,36.132.0,43.199.0,27.102.0,41.118.0"}
P.entries["quest:96629"] = {n="Camping 101: Cooking",s="Camping 101: Cooking führt Abenteurer in Dun Morogh an die grundlegende Überlebensfertigkeit des Kochens heran. Neben der Zubereitung von Reiseproviant ermöglicht das Erlernen dieses Handwerks Reisenden das Entzünden von Lagerfeuern, die als Grundlage für Lagerplätze in der Wildnis dienen.",h="Camping 101: Cooking führt Abenteurer in Dun Morogh an die grundlegende Überlebensfertigkeit des Kochens...",kw={"lagerfeuer","camping","kochen","dun morogh","ausstattung","gremlock pilsnor","kharanos","wildnis"},ang={["class:Priest"]="Selbst spirituelle Praktizierende, die sich dem Licht verschrieben haben, müssen grundlegende Überlebensfertigkeiten wie das Entzünden von Feuern meistern, wenn sie fernab von Tempeln und Siedlungen reisen.",["faction:Alliance"]="Abenteurer der Allianz, die in der Nähe von Dun Morogh beginnen, erlernen die Grundlagen des Überlebens in der Wildnis und des Kochens von den zwergischen Ausbildern in Kharanos.",["profession:Cooking"]="Das Kochen liefert das grundlegende Lagerfeuer, das erforderlich ist, um Lagerplätze in der Wildnis zu errichten und Lagerausstattung aufzustellen."},sec={{t="Die Feuerstelle in der Wildnis",b="Für jeden Reisenden, der den Gefahren der Wildnis trotzt, beginnt das Errichten eines verlässlichen Lagerplatzes mit einer Flamme. In Dun Morogh werden unerfahrene Abenteurer nach Kharanos geschickt, um die Grundlagen des Kochens bei Gremlock Pilsnor zu erlernen. Beim Kochen geht es nicht bloß darum, sich unterwegs mit warmen Mahlzeiten zu versorgen; ein beständiges Lagerfeuer dient als buchstäblicher und praktischer Ankerpunkt für jedes Lager unter freiem Himmel."},{t="Die Erweiterung des Lagerplatzes",b="Ein neu erlerntes Lagerfeuer erlaubt es einem Abenteurer, überall in der offenen Wildnis ein bescheidenes Lager aufzuschlagen. Während rudimentäre Feuer nur minimale Ausstattung unterstützen, schaltet die Verbesserung der eigenen Kochfertigkeit die Möglichkeit frei, größere Feuer zu entfachen. Darüber hinaus können Handwerker, die in anderen Berufen geübt sind, zusätzliche Einrichtungsgegenstände anfertigen, um einen einfachen Rastplatz in ein voll ausgestattetes Lager zu verwandeln."}},faq={{q="Was ist die Quest Camping 101: Cooking?",a="Camping 101: Cooking ist eine Lehrquest, die Abenteurer an das grundlegende Handwerk des Kochens als Eckpfeiler des Überlebens in der Wildnis und des Lageraufbaus heranführt.",al={"was ist camping 101 cooking","questzweck","campinggrundlagen kochen"}},{q="Wer ist Gremlock Pilsnor?",a="Gremlock Pilsnor ist der örtliche Kochkunstlehrer in Kharanos in Dun Morogh, der Neulingen beibringt, wie man Nahrung zubereitet und Lagerfeuer errichtet.",al={"wer kochen in kharanos lehrt","gremlock pilsnor standort","kochlehrer dun morogh"}},{q="Warum ist Kochen für das Campen notwendig?",a="Das Kochen ermöglicht Abenteurern, ein einfaches Lagerfeuer zu errichten, das als grundlegendes Fundament dient, um ein Lager in der Wildnis aufzuschlagen und Ausstattungsgegenstände darum herum zu platzieren.",al={"warum brauche ich kochen zum campen","lagerfeuerzweck","kochen und lager"}},{q="Wo kann ein Lagerplatz errichtet werden?",a="Sobald Ihr wisst, wie man ein Feuer entzündet, könnt Ihr draußen in der Wildnis ein einfaches Lager aufschlagen, das während Eurer Reisen als Rastplatz dient.",al={"wo kann ich ein lager aufschlagen","lagerplatzregeln","lager aufschlagen"}},{q="Wie verbessert oder erweitert man einen Lagerplatz?",a="Das Steigern Eurer Kochfertigkeit ermöglicht es Euch, größere Lagerfeuer zu errichten, und das Erlernen anderer Handwerksberufe befähigt Euch dazu, zusätzliche Lagerplatzausstattung herzustellen und aufzustellen.",al={"wie lagerplatz aufwerten","größere feuer","mehr lagerdekorationen"}},{q="Können andere Berufe zum Camping beitragen?",a="Andere Handwerkslehrer können Euch die Grundlagen für die Herstellung von Ausstattungsgegenständen für Euren Lagerplatz beibringen, sofern Ihr in ihren jeweiligen Berufen bewandert seid.",al={"wer bietet campingausstattung an","handwerks-lagergegenstände","andere lagerlehrer"}}},fp="20,242,22.367.0,22.396.0,39.166.0,24.141.0,37.157.0,36.136.0,40.165.0,44.140.0"}
P.entries["quest:96630"] = {n="The Adventurer",s="The Adventurer ist eine kurze Quest in Teldrassil, bei der es um die Entdeckung eines weggeworfenen Tagebuchs in der Wildnis geht. Das schlichte Notizbuch schildert die bescheidenen Reisen und Campingausflüge eines unbekannten Reisenden und ist für die Übergabe an Lyreena Duskblade nahe Dolanaar bestimmt.",h="The Adventurer ist eine kurze Quest in Teldrassil, bei der es um die Entdeckung eines weggeworfenen Tagebuchs...",kw={"zelten","dolanaar","tagebuch","verlorenes tagebuch","lyreena duskblade","teldrassil","the adventurer"},ang={["faction:Alliance"]="Für Neulinge der Allianz, die unter dem Weltenbaum Fuß fassen, hilft die Rückgabe verlegter Besitztümer an Mitreisende dabei, die Ordnung in den Hainen aufrechtzuerhalten.",["race:NightElf"]="Junge Nachtelfen, die in Teldrassil patrouillieren, finden oft Zeichen durchreisender Wanderer und übergeben verlorene persönliche Relikte an Reisende wie Lyreena Duskblade."},sec={{t="Das Tagebuch eines Wanderers",b="Inmitten der dichten Äste und verschlungenen Wurzeln von Teldrassil stoßen Reisende gelegentlich auf verlassene persönliche Gegenstände. Dieses einfache Tagebuch berichtet von den unscheinbaren, aber aufrichtigen Wanderungen eines namenlosen Abenteurers. Statt großer Heldentaten oder gefährlicher Monsterjagden dokumentiert der Großteil seiner Seiten voller Begeisterung die einfachen Freuden des Zeltens unter dem dämmrigen Blätterdach."},{t="Lieferung nach Dolanaar",b="Anstatt das persönliche Erinnerungsstück in der feuchten Wildnis verrotten zu lassen, fühlt sich der Finder dazu bewogen, es nach Dolanaar zu tragen. Lyreena Duskblade, die nahe der Siedlung der Nachtelfen stationiert ist, dient als Empfängerin für die verloren gegangenen Seiten und bietet vielleicht Aufschluss oder Einblick darüber, wessen Reisen dort zurückgelassen wurden."}},faq={{q="Was ist das in der Quest erwähnte Tagebuch?",a="Es ist ein schlichtes persönliches Notizbuch, das in der Wildnis von Teldrassil geborgen wurde. Seine Einträge beschreiben das ruhige Leben und die Reisen einer unbekannten Gestalt, wobei gewöhnliche Abenteuer und eine anhaltende Vorliebe für das Zelten im Freien hervorgehoben werden.",al={"verlorenes tagebuch","was ist das buch","the adventurer tagebuch"}},{q="Wer ist Lyreena Duskblade?",a="Lyreena Duskblade ist eine Nachtelfe, die nahe Dolanaar zu finden ist. Sie ist die vorgesehene Empfängerin des verlorenen Tagebuchs, das draußen im Wald gefunden wurde.",al={"lyreena","wo ist lyreena duskblade","abgabe-npc"}},{q="Wo findet diese Quest statt?",a="Die Quest findet in Teldrassil statt, dem großen Ast der Nachtelfen, mit Schwerpunkt auf der Wildnis rund um das Dorf Dolanaar.",al={"wo ist die quest the adventurer","questzone"}},{q="Beschreibt das Tagebuch gefährliche Monster oder Kämpfe?",a="Nein. Die Schrift wird als recht schlicht beschrieben und konzentriert sich auf das unaufgeregte Leben und die Wanderungen eines unbekannten Individuums, mit besonderem Schwerpunkt darauf, wie angenehm das Zelten sein kann.",al={"tagebuch-lore","was steht im tagebuch","was steht darin"}},{q="Wer kann diese Aufgabe abschließen?",a="Diese Aufgabe ist ausschließlich Mitgliedern der Allianz vorbehalten, die durch das Startgebiet von Teldrassil streifen, insbesondere unerfahrenen Nachtelfen, die sich in die Nähe von Dolanaar wagen.",al={"kann die horde das tun","allianzquest"}},{q="Warum sollte man das Tagebuch in Dolanaar abgeben?",a="Dolanaar ist der zentrale Sammelpunkt und Knotenpunkt für jene Region von Teldrassil, was es zum sinnvollsten Ort macht, um verlegte persönliche Besitztümer abzuliefern, und Lyreena Duskblade wartet in der Nähe, um das Tagebuch entgegenzunehmen.",al={"warum dolanaar","warum lyreena"}}},fp="14,259,20.373.0,20.307.0,43.220.0,25.128.0,33.135.0,56.177.0,27.153.0,36.218.0"}
P.entries["quest:96634"] = {n="Camping 101: Cooking",s="Camping 101: Cooking ist eine Einführungsquest, die Abenteurer durch die Kunst des Kochens in die Grundlagen des Campens in der Wildnis einweist. Indem sie von örtlichen Lehrern wie Zarrin in Dolanaar lernen, ein Lagerfeuer zu entfachen, schaffen Reisende den notwendigen Ankerpunkt für das Errichten von Lagern in der Wildnis. Sie markiert den ersten Schritt zur Meisterung des Überlebens in der Wildnis und zur Ausstattung persönlicher Lagerplätze.",h="Camping 101: Cooking ist eine Einführungsquest, die Abenteurer durch die Kunst des Kochens in die Grundlagen...",kw={"lagerfeuer","camping 101","lagerplatz","kochkunst","dolanaar","einrichtung","überleben in der wildnis","zarrin"},ang={["profession:Cooking"]="Kochkunst ist die grundlegende Disziplin des Überlebens in der Wildnis und liefert das Lagerfeuer, das notwendig ist, um jeden Lagerplatz im Freien zu verankern. Das Voranschreiten im kulinarischen Handwerk ermöglicht es Abenteurern, größere, widerstandsfähigere Lagerfeuer zu errichten.",["race:NightElf"]="Unerfahrene Abenteurer der Nachtelfen, die durch Dolanaar reisen, lernen oft die Grundlagen des Überlebens in der Wildnis und des Feuermachens von Zarrin, bevor sie sich tiefer in die Wildnis von Teldrassil wagen."},sec={{t="Der Herd der Wildnis",b="Jede lange Reise durch die Wildnis beginnt mit der Fähigkeit, ein wärmendes Feuer zu entfachen. In Camping 101: Cooking werden angehende Abenteurer dazu angeleitet, eine Kochkunstausbildung als ihre erste Lektion im Überleben in der Wildnis zu absolvieren. Kochen zu lernen bedeutet mehr, als nur Mahlzeiten aus Wildbret zuzubereiten; die grundlegende Fertigkeit, ein einfaches Lagerfeuer zu entzünden, dient als physischer und praktischer Ankerpunkt für jedes Lager im Freien. Ohne ein Feuer, das die Kälte vertreibt und die Dunkelheit fernhält, ist das Errichten eines verlässlichen Lagerplatzes in der Wildnis unmöglich."},{t="Den Lagerplatz erweitern",b="Zu lernen, wie man ein einfaches Lagerfeuer entzündet, verleiht die Fähigkeit, bescheidene Lager in der gesamten Wildnis aufzuschlagen. Obwohl ein einfaches Anfangslager nur wenige rudimentäre Einrichtungsgegenstände fassen kann, können engagierte Abenteurer ihre Möglichkeiten erweitern. Wenn ein Abenteurer seine Kochfertigkeit verbessert, schaltet er Methoden frei, um größere, beständigere Feuer zu entfachen. Darüber hinaus können Handwerker, die in anderen Berufen bewandert sind, ihre jeweiligen Lehrer aufsuchen, um zu lernen, wie sie Einrichtungsgegenstände und Verbesserungen herstellen, um ihre Lager zu bereichern."}},faq={{q="Was ist der Zweck von Camping 101: Cooking?",a="Camping 101: Cooking führt Abenteurer in die Grundlagen des Überlebens in der Wildnis ein, indem es sie anweist, den Beruf der Kochkunst zu erlernen. Das Errichten eines Lagerfeuers dient als zentrales Fundament, um überall in der Wildnis einen Lagerplatz aufzuschlagen.",al={"was bewirkt diese quest","zweck von camping 101 cooking","warum camping 101 abschließen"}},{q="Wer ist Zarrin?",a="Zarrin ist ein Kochkunstlehrer in Dolanaar auf Teldrassil. Er bringt angehenden Abenteurern die Grundlagen der kulinarischen Künste bei und lehrt sie, wie man ein einfaches Lagerfeuer errichtet.",al={"wer ist zarrin","zarrin dolanaar","wo ist der kochkunstlehrer in dolanaar"}},{q="Wie schlagt Ihr ein Lager in der Wildnis auf?",a="Das Einrichten eines Lagerplatzes beginnt mit dem Entzünden eines einfachen Lagerfeuers, das Ihr über den Beruf der Kochkunst erlernt. Während die Grundausbildung es Euch ermöglicht, Euer Lager in der Wildnis mit bescheidener Einrichtung aufzuschlagen, erlaubt Euch das Verbessern Eurer Fertigkeiten größere Feuer und zusätzliche Lagerplatzverbesserungen.",al={"wie man ein lager errichtet","wie camping funktioniert","errichten eines lagers"}},{q="Könnt Ihr Eurem Lagerplatz Einrichtungsgegenstände hinzufügen?",a="Während die Kochkunst das Lagerfeuer liefert, das Euren Lagerplatz verankert, können andere Handwerkslehrer in ganz Azeroth geschickten Handwerkern beibringen, wie sie ihre Lagerplätze mit spezialisierter Ausrüstung und Dekorationen ausstatten und aufwerten.",al={"lagerplatz einrichten","lagerdekorationen","lagereinrichtung andere berufe"}},{q="Warum ist Kochkunst für das Campen erforderlich?",a="Die Kochkunst lehrt Abenteurer, wie man ein offenes Lagerfeuer draußen in der Wildnis errichtet und unterhält. Da ein Feuer das unverzichtbare Herzstück jedes Lagers im Freien ist, stellt das Erlernen der Kochkunst den ersten notwendigen Schritt für das richtige Campen in der Wildnis dar.",al={"warum kochkunst fürs campen benötigt wird","verbindung von kochkunst und campen"}},{q="Könnt Ihr größere Lagerfeuer herstellen?",a="Ja. Wenn Ihr Euer kulinarisches Handwerk ausübt und Eure Kochfertigkeit steigert, könnt Ihr lernen, wie Ihr größere Feuer errichtet, um Eure Lager in der Wildnis besser zu unterstützen.",al={"kann ich größere lagerfeuer machen","wie man ein lagerfeuer aufwertet"}}},fp="20,384,22.515.0,22.504.0,44.234.0,14.159.0,44.272.0,41.214.0,36.228.0,30.155.0"}
P.entries["quest:96638"] = {n="The Adventurer",s="„The Adventurer“ ist eine einführende Reisequest auf der Insel Zephras. Sie wird von Aetheen of the Gales im Thendalhain vergeben und schickt frisch erprobte Wanderer nach Südwesten in Richtung Shen'dar, um Raan Wildwind zu treffen, einen erfahrenen Camper, der die Wildnis kennt.",h="„The Adventurer“ ist eine einführende Reisequest auf der Insel Zephras.",kw={"aetheen of the gales","raan wildwind","shen'dar","the adventurer","thendalhain","insel zephras"},ang={["race:Skyborne"]="Für junge Skyborne, die unter dem geschützten Blätterdach des Thendalhains hervortreten, markiert das Treffen mit Raan Wildwind den ersten echten Schritt in die weitere, ungezähmte Geografie ihrer insularen Heimat."},sec={{t="Den Hain verlassen",b="Während der Thendalhain Schutz und eine ruhige Zuflucht bietet, bleiben die weiteren Weiten der Insel Zephras wild und gefährlich. Aetheen of the Gales wacht über die Initianden und erkennt, wann ein aufstrebender Reisender bereit ist, über vertraute Grenzen hinauszutreten. Für diejenigen, die nach Ruhm, Reichtum oder Bestimmung suchen, reicht der Verbleib hinter den geschützten Grenzen des Hains nicht mehr aus."},{t="Ein Führer auf dem Weg",b="Südwestlich des Hains entlang der Straße nach Shen'dar hat bereits ein anderer Reisender sein Lager aufgeschlagen. Raan Wildwind hat einige Zeit damit verbracht, sich durch die Gefahren außerhalb der sicheren Zuflucht zu schlagen. Ihn aufzusuchen, bietet heranreifenden Wanderern eine pragmatische Einführung in das Überleben jenseits des Thendalhains – beim Lernen von jemandem, der sich bereits auf die offenen Pfade gewagt hat."}},faq={{q="Wer schickt Euch aus, um Raan Wildwind zu finden?",a="Aetheen of the Gales vergibt die Quest im Thendalhain. Nachdem Ihr Euch in den umliegenden Wäldern bewiesen habt, ermutigt sie Euch, jemanden mit Erfahrung aus erster Hand auf der weiteren Insel aufzusuchen.",al={"wer vergibt the adventurer","wer startet die quest the adventurer","aetheen quest"}},{q="Wo befindet sich Raan Wildwind?",a="Raan Wildwind hat sein Lager südwestlich des Thendalhains aufgeschlagen, direkt an der Hauptstraße, die nach Shen'dar führt.",al={"raan wildwind aufenthaltsort","wo ist raan","wie findet man raan wildwind"}},{q="Was ist der Zweck dieser Aufgabe?",a="Sie dient als Wegweiser, der Reisende aus der sicheren Zuflucht des Thendalhains herausführt und sie mit Mentoren und Herausforderungen tiefer auf der Insel Zephras zusammenbringt.",al={"warum the adventurer machen","zweck der quest the adventurer","was lehrt raan"}},{q="Welche Voraussetzung muss erfüllt sein, bevor man diese Quest erhält?",a="Ihr müsst die Aufgabe bezüglich der Foul Matriarch für Aetheen of the Gales abschließen, bevor sie Euch die Straße hinunter zu Raan Wildwind schickt.",al={"the adventurer voraussetzung","anforderungen für the adventurer"}},{q="Ist Shen'dar sicher für Reisende?",a="Shen'dar liegt kurz hinter Raans Lager, am Ende der Straße südwestlich des Thendalhains. Obwohl es eine bedeutende Siedlung auf der Insel darstellt, erfordern die Straßen und die umliegende Wildnis Vorsicht von jungen Abenteurern.",al={"ist shendar sicher","was ist shen'dar"}},{q="Wer ist Raan Wildwind?",a="Raan Wildwind ist ein abenteuerlustiger Wanderer, der sich über den Thendalhain hinausgewagt hat, um ein Lager außerhalb von Shen'dar zu errichten, wo er Neuankömmlingen, die die Straße entlangkommen, Ratschläge und Aufgaben anbietet.",al={"raan lore","wer ist raan wildwind"}}},fx={dc12ab9c={q="Warum schickt Euch Aetheen of the Gales los, um Raan Wildwind zu finden?",a="Aetheen erkennt, dass mehr Wanderer die Sicherheit des Thendalhain verlassen, auf der Suche nach Ruhm und Reichtum. Da er weiß, dass die Wildnis für Unerfahrene große Gefahren birgt, möchte Aetheen, dass Ihr Raan Wildwind aufsucht – einen Mitreisenden, der nahe Shen'dar lagert –, um praktische Weisheit und Überlebenslektionen zu lernen, die Euch auf Euren Reisen über die Insel am Leben halten.",al={"warum schickt euch aetheen","aetheen of the gales motiv","warum raan wildwind treffen"}}},fp="14,245,17.355.0,19.347.0,36.193.0,31.125.0,33.169.0,64.136.0,39.226.0,21.182.0"}
P.entries["quest:96646"] = {n="Camping 101: Cooking",s="Camping 101: Cooking ist eine einführende Quest, die Abenteurern die Kochkunst als unverzichtbare Grundlage für das Überleben in der Wildnis beibringt. Indem Reisende von Zerril Softbreeze in Shen'dar lernen, wie man ein Lagerfeuer entfacht, schalten sie die Fähigkeit frei, ihre eigenen Lagerplätze in der Wildnis aufzuschlagen.",h="Camping 101: Cooking ist eine einführende Quest, die Abenteurern die Kochkunst als unverzichtbare Grundlage...",kw={"lagerfeuer","camping","lagerplatz","kochen","ausstattung","shen'dar","zerril softbreeze"},ang={["profession:Cooking"]="Das Erlernen einfacher Kochkunst vermittelt das grundlegende Wissen, das zum Errichten eines Lagerfeuers erforderlich ist, und schafft so den zentralen Ankerpunkt für jedes Lager in der Wildnis."},sec={{t="Die Feuerstelle der Wildnis",b="Für einen Abenteurer, der durch ungezähmte Lande reist, beginnt das Verständnis für das Überleben mit der Feuerstelle. Camping 101: Cooking führt Wanderer in die Kochkunst ein – nicht bloß zur Zubereitung von Mahlzeiten, sondern weil das Meistern eines einfachen Feuers der wesentliche erste Schritt ist, um einen sicheren Rastplatz in der Wildnis zu errichten."},{t="Fundamente des Lagerplatzes",b="Angehende Camper werden angewiesen, mit Zerril Softbreeze in Shen'dar zu sprechen, um die Grundlagen des Kochhandwerks zu erlernen. Sobald ein Abenteurer versteht, wie man ein Lagerfeuer entfacht, erlangt er die Fähigkeit, überall in der Wildnis einen kleinen Lagerplatz zu errichten. Obwohl rudimentäre Lager nur minimale Ausstattung bieten, ermöglicht die Verbesserung des eigenen Handwerks größere Feuer und reichhaltigere Arrangements, die mit Hilfe anderer Handwerksfertigkeiten hergestellt werden."}},faq={{q="Was ist Camping 101: Cooking?",a="Es ist eine einführende Anleitung für die Wildnis, die Abenteurern beibringt, wie die Kunst des Kochens und das Entfachen einfacher Lagerfeuer als Grundlage für das Errichten eines Lagerplatzes dienen.",al={"was ist camping 101 cooking","camping kochquest"}},{q="Wer ist Zerril Softbreeze?",a="Zerril Softbreeze ist ein Kochlehrer in Shen'dar, der Neulinge in den grundlegenden kulinarischen Künsten und dem Entfachen eines Lagerfeuers unterweist.",al={"wer ist zerril softbreeze","kochlehrer shen'dar"}},{q="Warum ist Kochen erforderlich, um ein Lager aufzuschlagen?",a="Das Kochen lehrt Abenteurer, wie man ein Lagerfeuer errichtet und unterhält, welches als zentrales Fundament dient, um das herum jeder Lagerplatz in der Wildnis errichtet wird.",al={"warum kochen für camping lernen","warum kochen für lager nötig"}},{q="Wo befindet sich Zerril Softbreeze?",a="Zerril Softbreeze kann dabei angetroffen werden, wie er Handwerksfertigkeiten in Shen'dar lehrt.",al={"wo ist zerril softbreeze","ort von shen'dar"}},{q="Wie können Lagerplätze ausgestattet werden?",a="Neulinge können einfache Einrichtungsgegenstände um ihre Lagerfeuer platzieren, doch das Erlernen von Handwerksfertigkeiten bei anderen Handwerkslehrern ermöglicht es Abenteurern, zusätzliche Lagerplatzausstattungen herzustellen und aufzustellen.",al={"lagerplatzausstattung","wie man lager einrichtet"}},{q="Können Lagerfeuer aufgewertet werden?",a="Indem Ihr Eure Kochkunst verbessert, könnt Ihr lernen, wie man noch größere Lagerfeuer entfacht, um Eure Lager in der Wildnis aufzuwerten.",al={"größere lagerfeuer","lager aufwerten"}}},fp="20,284,22.312.0,27.442.0,29.173.0,25.145.0,41.152.0,35.76.0,31.183.0,26.116.0"}
P.entries["quest:96652"] = {n="The Adventurer",s="Während sie das zerklüftete Ödland von Durotar erkunden, stoßen Reisende auf ein einfaches, weggeworfenes Tagebuch, das von den ruhigen Reisen einer unbekannten Gestalt berichtet. Seine Seiten erzählen herzlich vom Leben im Freien und dem Lagern unter dem Sternenhimmel und warten auf ihre Übergabe an Brakk in der Nähe von Klingenhügel.",h="Während sie das zerklüftete Ödland von Durotar erkunden, stoßen Reisende auf ein einfaches, weggeworfenes...",kw={"the adventurer","brakk","zelten","durotar","tagebuch","verlorenes tagebuch","klingenhügel"},ang={["class:Hunter"]="Jäger, die ihr Leben damit verbringen, von dem zu leben, was das Land hergibt, können die herzlichen, wiederholten Einträge des Tagebuchs über die Freuden des Zeltens in der Wildnis leicht nachempfinden.",["faction:Horde"]="Die dürren Pfade von Durotar werden von vielen neuen Rekruten begangen; verlorenes Eigentum zu bergen und es zu Wanderern wie Brakk nahe Klingenhügel zu bringen, hilft dabei, die Ordnung entlang der zentralen Grenze aufrechtzuerhalten."},sec={{t="Aufzeichnungen eines Wanderers",b="Durotar ist ein raues Land, in dem das Überleben für gewöhnlich Vorrang vor gemächlichen Reisen hat, weshalb die Entdeckung des Buches eines wandernden Chronisten einen ungewöhnlichen Anblick darstellt. Das bescheidene Tagebuch, das unbeachtet im roten Staub lag, enthält die Gedanken und Taten von jemandem, der den einfachen Helden der Horde völlig unbekannt ist. Anstatt blutige Schlachten oder große Feldzüge im Detail zu schildern, verweilen seine Seiten bei den bescheidenen Freuden des Schlafens unter freiem Himmel und dem Errichten von Lagern in der Wildnis."},{t="Lieferung an Brakk",b="Wer auch immer die Einträge verfasst hat, hinterließ genug Eindruck – oder eine Verbindung –, um auf Brakk hinzuweisen, einen Abenteurer, der nahe der Siedlung Klingenhügel lagert. Die persönlichen Habseligkeiten verlorener Reisender zu jenen zu bringen, die den Weg kennen, ist oft die einzige Möglichkeit, wie verstreute Wanderer jemals wieder mit ihrem Besitz vereint werden, oder zumindest von denen in Erinnerung behalten werden, die über die staubigen Straßen wachen."}},faq={{q="Was befindet sich in dem verlorenen Tagebuch?",a="Das Buch ist bemerkenswert gewöhnlich und voll von alltäglichen Einträgen, die die stillen Taten eines obskuren Abenteurers schildern. Insbesondere hebt es wiederholt die einfachen Freuden und den Spaß am Lageraufbau in der Wildnis hervor.",al={"was im tagebuch steht","inhalt des verlorenen tagebuchs","tagebuchtext"}},{q="Wer hat das Tagebuch geschrieben?",a="Die Identität des Autors bleibt auf den geborgenen Seiten ungenannt; es beschreibt das Leben und die Reisen von jemandem, von dem Ihr noch nie gehört habt, bevor Ihr dem Buch in der Wildnis begegnet seid.",al={"wer ist the adventurer","autor des verlorenen tagebuchs","wer hat dieses buch geschrieben"}},{q="Wer ist Brakk?",a="Brakk ist ein Abenteurer, der nahe Klingenhügel im zentralen Durotar lagert und das verlorene Tagebuch entgegennimmt.",al={"brakk klingenhügel","wer ist brakk","wo ist brakk"}},{q="Wo wird das Tagebuch gefunden?",a="Das einfache Tagebuch wird verlassen inmitten des Geländes von Durotar entdeckt und wartet darauf, von einem vorbeikommenden Reisenden der Horde geborgen zu werden.",al={"wo finde ich das tagebuch","fundort des verlorenen tagebuchs","the adventurer questbeginn"}},{q="Warum kümmert sich Brakk um dieses Tagebuch?",a="Die Quest verrät es nicht. Brakk ist ein erfahrener Abenteurer, der direkt vor Klingenhügel lagert und Neulingen die Grundlagen des Zeltens beibringt, sodass ein Tagebuch voller Zeltgeschichten bei ihm ein natürliches Zuhause findet.",al={"warum zu brakk bringen","brakks zweck","brakk tagebuch"}},{q="Befindet sich der Abenteurer, der es geschrieben hat, in Gefahr?",a="Die geborgenen Seiten geben keinen Hinweis auf ein Verbrechen, sondern enthalten lediglich liebevolle Erinnerungen an das Lagern im Freien. Das eigene Reisetagebuch im roten Staub von Durotar zurückzulassen, deutet jedoch darauf hin, dass der Verfasser es entweder versehentlich verloren hat oder unerwartet weitergezogen ist.",al={"lebt der autor noch","ist the adventurer gestorben","status des verlorenen abenteurers"}}},fp="14,268,18.468.0,17.368.0,32.220.0,22.178.0,13.104.0,27.130.0,39.197.0,41.252.0"}
P.entries["quest:96655"] = {n="Camping 101: Cooking",s="Camping 101: Cooking führt Abenteurer in das grundlegende Handwerk des Überlebens in der Wildnis ein. Indem sie Reisende zu Cook Torka in Klingenhügel führt, vermittelt sie die Grundlagen des Kochens und der Errichtung von Lagerfeuern, die notwendig sind, um eigene Lagerplätze in der Wildnis aufzuschlagen.",h="Camping 101: Cooking führt Abenteurer in das grundlegende Handwerk des Überlebens in der Wildnis ein.",kw={"lagerfeuer","camping 101","camping 101: cooking","lagerplatz","cook torka","kochen","durotar","einrichtungsgegenstände","klingenhügel"},ang={["faction:Horde"]="Abenteurer, die in Durotar aufbrechen, können sich bei Cook Torka in Klingenhügel melden, um das grundlegende Handwerk des Kochens zu erlernen.",["profession:Cooking"]="Kochen ist die Hauptvoraussetzung für den Bau eines einfachen Lagerfeuers und bildet den unverzichtbaren Anker für das Überleben in der Wildnis und das Errichten eines Lagerplatzes."},sec={{t="Der Herd der Wildnis",b="Für jeden Wanderer, der seinen Fuß vor die Tore einer Siedlung setzt, erfordert das Überleben in der Wildnis mehr als scharfen Stahl und eine robuste Rüstung. Die Quest Camping 101: Cooking schickt angehende Abenteurer zu Cook Torka in Klingenhügel, um die Kochkunst zu erlernen. In den offenen Einöden von Durotar und darüber hinaus bedeutet Kochen weit mehr als nur die Zubereitung einer warmen Mahlzeit – es ist die grundlegende Disziplin, die erforderlich ist, um ein zuverlässiges Lagerfeuer zu entfachen, das das Herzstück jedes Lagers bildet."},{t="Errichten und Ausstatten eines Lagers",b="Das Meistern der Grundlagen ermöglicht es Reisenden, nahezu überall im Grenzland ein bescheidenes Lager aufzuschlagen. Während das Lagerfeuer eines Neulings nur eine Handvoll grundlegender Einrichtungsgegenstände unterstützt, eröffnet eine weitere Hingabe an das Handwerk neue Möglichkeiten. Die Vertiefung der eigenen Kochkenntnisse ermöglicht das Errichten größerer Feuer, während das Ausüben anderer Handwerksfertigkeiten das handwerkliche Geschick verleiht, das erforderlich ist, um Lager auszustatten und zu verlässlichen Bastionen gegen die ungezähmte Wildnis auszubauen."}},faq={{q="Was ist die Quest Camping 101: Cooking?",a="Camping 101: Cooking ist eine Einführungsquest, die Abenteurern die Grundlagen des Überlebens in der Wildnis vermittelt. Durch das Erlernen von Kochen und dem Errichten von Lagerfeuern erlangen Abenteurer die Fähigkeit, überall in der Wildnis ihre eigenen Lagerplätze aufzuschlagen.",al={"was ist camping 101 cooking","camping 101 cooking quest","was macht diese quest"}},{q="Wer ist Cook Torka?",a="Cook Torka ist der Kochkunstlehrer der Horde in Klingenhügel in Durotar. Er bringt aufstrebenden Abenteurern die Grundlagen der Kochkunst bei und wie man ein einfaches Lagerfeuer entfacht.",al={"wer lehrt kochen klingenhügel","wer ist cook torka","wo ist cook torka"}},{q="Warum ist Kochen für das Campen erforderlich?",a="Kochen dient nicht nur der Zubereitung von Nahrung; das durch das Kochen errichtete Lagerfeuer dient als grundlegender Anker, um ein Lager aufzuschlagen. Ohne ein Feuer kann in der Wildnis kein richtiger Lagerplatz unterhalten werden.",al={"warum kochen fürs campen nötig ist","zusammenhang kochen lagerfeuer","erfordert campen kochen"}},{q="Wo kann ein Abenteurer einen Lagerplatz aufschlagen?",a="Sobald Ihr die Grundlagen des Kochens und der Errichtung eines Lagerfeuers erlernt habt, könnt Ihr fast überall in der offenen Wildnis einen kleinen Lagerplatz aufschlagen. Erste Lagerplätze sind einfach und können nicht viele Einrichtungsgegenstände unterstützen.",al={"wo kann man campen","wie funktioniert campen","lagerplatz platzierung"}},{q="Wie wertet Ihr Euer Lagerfeuer auf?",a="Wenn Ihr Eure Fertigkeit im Kochberuf steigert, könnt Ihr lernen, größere und langlebigere Lagerfeuer zu errichten, was erweiterte Möglichkeiten für den Lagerplatz eröffnet.",al={"größere lagerfeuer","lagerfeuer aufwerten","wie man lagerplätze verbessert"}},{q="Wie erhaltet Ihr Einrichtungsgegenstände für einen Lagerplatz?",a="Während Kochen das Lagerfeuer als Grundlage liefert, können andere Handwerkslehrer auf der ganzen Welt Abenteurern beibringen, wie man zusätzliche Einrichtungsgegenstände herstellt und platziert, um ihre Lagerplätze anzupassen und zu erweitern.",al={"lagerplatz dekorationen","lager einrichten","lehrer für lagereinrichtung"}}},fp="20,265,22.457.0,30.450.0,39.235.0,18.177.0,36.207.0,42.208.0,33.160.0,45.199.0"}
P.entries["quest:96656"] = {n="The Adventurer",s="The Adventurer ist eine einführende Aufgabe, die Exekutor Arren erfahrenen jungen Champions der Verlassenen außerhalb von Todesend erteilt. Nachdem Ihr Euch bei Angriffen gegen den Scharlachroten Kreuzzug als zuverlässig erwiesen habt, werdet Ihr die Straße hinauf in Richtung Brill entsandt, um eine Fremde zu überprüfen, die sich in der Nähe der Siedlung aufhält. Anstatt einen weiteren fanatischen Spion zu enttarnen, macht die Aufgabe Euch mit Eleanor Shackleton bekannt, einer unabhängigen Reisenden, die begierig darauf ist, die praktischen Überlebensfertigkeiten der Wildnis zu lehren.",h="The Adventurer ist eine einführende Aufgabe, die Exekutor Arren erfahrenen jungen Champions der Verlassenen...",kw={"brill","lagern","todesend","eleanor shackleton","exekutor arren","scharlachroter kreuzzug","the adventurer","the great outdoors","tirisfal"},ang={["faction:Horde"]="Während Exekutor Arren die noch jungen Grenzen des Reiches der Verlassenen bewacht, sichert die Aufnahme eines friedlichen Dialogs mit wandernden Überlebenskünstlern wertvolle praktische Fertigkeiten für Novizen der Horde.",["race:Undead"]="Für junge Verlassene, die sich über Todesend hinauswagen, ist die Begegnung mit einer anderen Verlassenen und Abenteurerin wie Eleanor eine frühe Lektion, dass nicht jeder Fremde in der Nähe von Brill ein scharlachroter Spion ist."},sec={{t="Eine misstrauische Wache",b="Exekutor Arren wacht aufmerksam über Todesend und die umliegenden Zugangswege. Da Kreuzfahrer des Scharlachroten Kreuzzugs die Region aktiv ausspähen und das nördliche Lordaeron infiltrieren, erfordert jeder Neuling, der in der Nähe von Brill umherwandert, eine sofortige Überprüfung. Nachdem Ihr Eure Hingabe durch die Beseitigung von Bedrohungen der Kreuzfahrer entlang der Grenze unter Beweis gestellt habt, wendet sich Arren an Euch, um die unbekannte Gestalt unauffällig zu überprüfen und festzustellen, ob sie eine verborgene Gefahr für die Verlassenen darstellt."},{t="Eine Reisende in den Wäldern",b="Sobald Ihr Eleanor Shackleton am Straßenrand in der Nähe von Brill aufgespürt habt, erweisen sich ihre Absichten als weit entfernt von fanatischen Ränken des Kreuzzugs oder der Nekromantie der Geißel. Als Verlassene, die vor ihrer nächsten Reise in die Wildnis rastet, ist Eleanor schlichtweg eine Abenteurerin. Stattdessen erkennt sie den Funken eines Abenteurers in jenen, die geschickt wurden, um nach ihr zu sehen, und bietet an, die praktischen Grundlagen des Überlebens in der offenen Wildnis und des Lageraufbaus zu teilen."}},faq={{q="Warum möchte Exekutor Arren, dass Eleanor überprüft wird?",a="Todesend und Brill werden ständig von Infiltratoren des Scharlachroten Kreuzzugs und feindlichen Spionen bedroht. Jeder Unbekannte, der an der Hauptstraße lauert, wird mit Misstrauen behandelt, bis sich seine Absichten als harmlos erweisen.",al={"warum eleanor überprüfen","wer entsendet zu eleanor","arren eleanor aufgabe"}},{q="Wer ist Eleanor Shackleton?",a="Eleanor Shackleton ist eine unabhängige Abenteurerin, die an der Straße in der Nähe von Brill lagert. Sie hegt keine Loyalität gegenüber dem Scharlachroten Kreuzzug und konzentriert sich rein darauf, die Wildnis zu erkunden und Überlebenswissen mit anderen Reisenden zu teilen.",al={"wer ist eleanor","eleanor shackleton lore","wer ist the adventurer nsc"}},{q="Steht Eleanor mit dem Scharlachroten Kreuzzug in Verbindung?",a="Nein. Bei der Ankunft in ihrem Lager stellt Eleanor schnell klar, dass sie keinerlei Verbindung zu den eifernden Kreuzfahrern hat, die Tirisfal bedrohen.",al={"gehört eleanor zum scharlachroten kreuzzug","eleanor feind","ist eleanor eine spionin"}},{q="Wohin führt diese Quest?",a="Die Meldung bei Eleanor eröffnet die Quest 'The Great Outdoors', in der sie beginnt, Euch die Grundlagen des Überlebens in der Wildnis und das Errichten eines Lagers beizubringen.",al={"was kommt nach the adventurer","nächste quest nach the adventurer","eleanor shackleton folgequest"}},{q="Wo ist Eleanor Shackleton zu finden?",a="Sie schlägt ihr Lager direkt an der Hauptstraße auf, die nach Osten zur Stadt Brill in Tirisfal führt.",al={"eleanor standort","wo ist eleanor shackleton","eleanor lager tirisfal"}},{q="Warum hat Exekutor Arren Euch für diese Mission ausgewählt?",a="Ihr habt Euch Arrens Vertrauen durch Eure erfolgreichen Dienste beim Aufspüren von Agenten und Boten des Scharlachroten Kreuzzugs in der Nähe von Todesend verdient und damit bewiesen, dass Ihr heikle Aufklärungsmissionen bewältigen könnt.",al={"warum ausgewählt","arren vertrauen","warum exekutor arren entsendet"}}},fp="14,455,18.461.0,23.423.0,50.208.0,26.227.0,44.151.0,27.143.0,38.99.0,51.172.0"}
P.entries["quest:96658"] = {n="Camping 101: Cooking",s="Camping 101: Cooking bringt angehenden Abenteurern die grundlegende Kunst bei, ein Feuer zu entfachen und in der Wildnis Nahrung zuzubereiten. Diese Lektion, die in den Startgebieten sowohl der Allianz als auch der Horde zu finden ist, führt das Lagerfeuer als zentralen Ankerpunkt für jedes behelfsmäßige Lager im Freien ein.",h="Camping 101: Cooking bringt angehenden Abenteurern die grundlegende Kunst bei, ein Feuer zu entfachen und in...",kw={"lagerfeuer","camping 101","kochen","goldhain","shackleton","tomas","wildnis","zarrin"},ang={["faction:Alliance"]="Neulinge, die Nordhain, Dun Morogh oder Teldrassil verlassen, werden in Orte wie Goldhain, Kharanos und Dolanaar geführt, um Selbstständigkeit zu erlernen, bevor sie der Wildnis trotzen.",["faction:Horde"]="Das Überleben liegt der Horde im Blut, und junge Kämpfer in Durotar, Mulgore und Tirisfal werden direkt zu den Lagerfeuern in Klingenhügel, im Dorf der Bluthufe und in Brill geleitet.",["profession:Cooking"]="Kochen ist der buchstäbliche Funke des Camping-Lebens; es liefert sowohl die lebenswichtige Nahrung zur Wiedererlangung der Kräfte als auch das zentrale Lagerfeuer, das zum Aufschlagen eines Biwaks im Freien erforderlich ist."},sec={{t="Der Herd der Wildnis",b="Um außerhalb befestigter Mauern zu überleben, muss jeder Reisende wissen, wie man ein Feuer macht. Über das Abkochen von Wasser und das Braten von Fleisch hinaus dient ein einfaches Lagerfeuer als lebenswichtige Grundlage, um in unerforschtem Gelände ein Lager aufzuschlagen. Ein einfaches Lagerfeuer bildet das Herzstück des Zeltplatzes, den diese Lektion vorstellt."},{t="Von der Glut zum Lager",b="Während Kochanfänger lediglich ein bescheidenes Feuer mit minimaler Umgebung aufrechterhalten können, schaltet die Beherrschung der Kochkunst die Fähigkeit frei, größere Feuer zu entfachen, die aufwendigere Lagerplätze unterstützen können. Darüber hinaus entdecken Abenteurer, die sich anderen praktischen Handwerken zuwenden, Möglichkeiten, nützliche Einrichtungsgegenstände herzustellen, um ihre Lager zu ergänzen."}},faq={{q="Was ist der Zweck dieser Quest?",a="Die Quest weist neue Abenteurer an, ihren örtlichen Kochkunstlehrer in nahegelegenen Siedlungen aufzusuchen, um sicherzustellen, dass sie die Grundlagen des Kochens erlernen und erfahren, wie man ein Lagerfeuer als Ankerpunkt für einen Zeltplatz im Freien entfacht.",al={"warum camping 101 abschließen","camping 101 kochen zweck","was bringt diese quest"}},{q="Wer bietet Reisenden diese Quest an?",a="Verschiedene erfahrene Wildnisführer und Abenteurer bieten diese Ausbildung in beiden Fraktionen an, darunter Eleanor Shackleton, Eric Brighthammer, Lyreena Duskblade, Sam Sarsaparilla, Brakk, Kaga Wildhoof und Raan Wildwind.",al={"wer vergibt camping 101","camping questgeber"}},{q="Wo geben Allianzspieler dies ab?",a="Allianzabenteurer melden sich je nach Heimatgebiet bei Lehrern wie Tomas in Goldhain, Gremlock Pilsnor in Kharanos oder Zarrin in Dolanaar.",al={"wo abgeben allianz","allianz kochkunstlehrer"}},{q="Wo geben Hordespieler dies ab?",a="Hordeabenteurer können die Ausbildung bei Cook Torka in Klingenhügel, William Pickman in Brill oder Pyall Silentstride im Dorf der Bluthufe abschließen.",al={"horde kochkunstlehrer","wo abgeben horde"}},{q="Kann die Zeltplatzgröße später erweitert werden?",a="Ja. Wenn Ihr Eure Kochfertigkeit steigert, könnt Ihr lernen, größere Feuer zu entfachen, die mehr Lagerausstattung in der Wildnis tragen können.",al={"größeres lagerfeuer","lager verbessern"}},{q="Können andere Berufe zum Camping beitragen?",a="Ja. Während das Kochen das Lagerfeuer bereitstellt, das das Lager verankert, bieten andere Handwerkslehrer Möglichkeiten, praktische Gegenstände für Euren Platz herzustellen, sofern Ihr deren Handwerke ausgeübt habt.",al={"camping berufe","lagerplatz einrichtung"}}},fp="20,286,28.273.0,26.338.0,34.189.0,35.222.0,39.155.0,36.144.0,36.134.0,44.181.0"}
P.entries["quest:96659"] = {n="Der Abenteurer",s="Während sich junge Tauren darauf vorbereiten, ihre angestammten Trainingsgründe auf der Hochwolkenebene zu verlassen, bittet Häuptling Falkenwind sie um einen letzten Gefallen. Er vertraut ihnen ein Bündel lebenswichtiger Vorräte für Kaga Wildhoof an, eine erfahrene Wanderin, die nahe dem Dorf der Bluthufe ihr Lager aufgeschlagen hat und dem Häuptling einst in seiner eigenen Vergangenheit beistand.",h="Während sich junge Tauren darauf vorbereiten, ihre angestammten Trainingsgründe auf der Hochwolkenebene zu...",kw={"bloodhoof","camp narache","häuptling falkenwind","kaga wildhoof","mulgore","die hochwolkenebene","vorratsbündel","der abenteurer"},ang={["faction:Horde"]="Häuptling Falkenwind sorgt dafür, dass reisende Verbündete der Horde beim Verlassen der Start-Mesa frühzeitig Bande mit den erfahrenen Wanderern und Außenposten von Mulgore knüpfen.",["race:Tauren"]="Für junge Tauren, die zum ersten Mal über Camp Narache hinausgehen, stellt das Begleichen von Hawkwinds Ehrenschuld gegenüber Kaga Wildhoof ihren ersten Dienst für ihr Volk in den weiten Ebenen von Mulgore dar."},sec={{t="Die Begleichung einer Schuld des Häuptlings",b="Bevor Reisende den Pfad der Mesa hinab zu den weiteren Ebenen von Mulgore beschreiten, hält Häuptling Falkenwind inne, um offene persönliche Schulden zu begleichen. Lange bevor er neue Generationen von Jägern und Schamanen im Camp Narache anleitete, kreuzten sich Hawkwinds Wege mit Kaga Wildhoof. Vom Häuptling als versierte Abenteurerin beschrieben, leistete Wildhoof ihm lebenswichtige Hilfe, als er sie am meisten brauchte. Da er gehört hat, dass sie ihr Lager direkt vor dem Dorf der Bluthufe aufgeschlagen hat, nutzt Hawkwind den Aufbruch der frisch bewährten Neulinge, um seiner alten Wohltäterin Vorräte zukommen zu lassen."},{t="Das Verlassen der Mesa",b="Dieser Botengang stellt einen entscheidenden Übergangsritus für junge Champions der Horde dar, die die Hochwolkenebene verlassen. Der Weg hinab vom Plateau führt direkt ins Dorf der Bluthufe, dem kulturellen und logistischen Herzen Zentralmulgores. Das Vorratsbündel über die Ebenen zu tragen, schlägt eine Brücke zwischen dem behüteten Ausbildungsleben auf der Mesa und den größeren, wilderen Kämpfen der Vereinigten Taurenstämme."}},faq={{q="Wer ist Kaga Wildhoof?",a="Kaga Wildhoof ist eine erfahrene Tauren-Abenteurerin, die vor Kurzem ihr Lager direkt vor dem Dorf der Bluthufe aufgeschlagen hat. Sie verbindet eine langjährige Freundschaft mit Häuptling Falkenwind, dem sie vor Jahren maßgeblich geholfen hat.",al={"kaga wildhoof","wer ist wildhoof","wo ist kaga"}},{q="Warum schickt Häuptling Falkenwind diese Vorräte?",a="Hawkwind sieht den Aufbruch junger Champions hinab ins Dorf der Bluthufe als die ideale Gelegenheit, einen alten Gefallen gegenüber Wildhoof zu erwidern und sicherzustellen, dass seine Abenteurerkollegin frische Vorräte für ihre Reisen erhält.",al={"hawkwind schuld","warum vorräte senden","zweck des vorratsbündels"}},{q="Wo befindet sich Kaga Wildhoofs Lager?",a="Ihr Lager liegt in den Ebenen direkt vor dem Dorf der Bluthufe, entlang des gewundenen südlichen Pfads von der Hochwolkenebene nach Zentralmulgore.",al={"standort von kagas lager","kaga finden","lager bei bloodhoof"}},{q="Wann wird diese Quest verfügbar?",a="Häuptling Falkenwind bietet die Aufgabe an, sobald Reisende ihren Mut auf der Hochwolkenebene unter Beweis gestellt haben und bereit sind, in die weiteren Gebiete von Mulgore vorzudringen.",al={"wann erhalte ich der abenteurer","zeitpunkt hawkwind quest","quest zum verlassen der mesa"}},{q="Führt diese Quest weg vom Camp Narache?",a="Ja. Das Überbringen der Vorräte dient als direkte Aufforderung, Camp Narache hinter sich zu lassen und den Pfad hinab in Richtung des Dorfes der Bluthufe einzuschlagen.",al={"die hochwolkenebene verlassen","reise nach bloodhoof"}},{q="Was befindet sich im Vorratsbündel?",a="Das Bündel besteht aus lebenswichtigen Rationen, die von den Stämmen des Camp Narache gesammelt wurden, um eine Abenteurerin zu versorgen, die außerhalb organisierter Siedlungen überlebt.",al={"was sind die vorräte","inhalt des vorratsbündels"}}},fx={["2c6e5885"]={q="Warum bittet Euch Häuptling Falkenwind, die Vorräte zu liefern?",a="Ihr habt Eure anfänglichen Riten in Die Hochwolkenebene abgeschlossen und bereitet Euch darauf vor, Camp Narache zu verlassen, um in die weiteren Ebenen von Mulgore vorzustoßen. Da Eure Abreise Euch ohnehin am Dorf der Bluthufe vorbeiführt, betraut Euch Häuptling Falkenwind mit diesem Botengang, anstatt tapfere Krieger zu entsenden, die benötigt werden, um die Ebene zu bewachen und die jungen Tauren zu schützen, die dort trainieren.",al={"warum ich falkenwind","warum mich mit vorräten schicken","warum wählt mich falkenwind"}}},fp="14,306,23.521.0,16.370.0,21.217.0,44.208.0,38.139.0,38.157.0,48.133.0,43.148.0"}
P.entries["quest:96661"] = {n="Camping 101: Cooking",s="Camping 101: Cooking ist eine einführende Quest, die Abenteurer darin unterweist, wie grundlegendes kulinarisches Wissen das Fundament für die Errichtung eines Lagerplatzes in der Wildnis bildet. Indem Reisende Pyall Silentstride im Dorf der Bluthufe aufsuchen, lernen sie, ein Lagerfeuer zu entfachen, um ihr Lager zu verankern und sich auf das Leben im Grenzland vorzubereiten.",h="Camping 101: Cooking ist eine einführende Quest, die Abenteurer darin unterweist, wie grundlegendes...",kw={"dorf der bluthufe","lagerfeuer","camping 101","lagerplatz","kochen","einrichtung","pyall leisetreter","wildnis"},ang={["faction:Horde"]="Abenteurer, die durch Mulgore reisen, beginnen ihre Ausbildung zum Überleben im Grenzland im Dorf der Bluthufe unter der Anleitung einheimischer Handwerker und Köche der Tauren.",["profession:Cooking"]="Das Kochen dient als zentraler Grundpfeiler des Überlebens in der Wildnis und bietet nicht nur Nahrung, sondern auch die grundlegende Fertigkeit, ein Lagerfeuer zu entfachen, um das herum ein ganzer Lagerplatz aufgebaut wird."},sec={{t="Der Herd der Wildnis",b="Jede lange Reise durch die ungezähmte Wildnis erfordert grundlegendes Überleben in der Wildnis, und jedes echte Lager beginnt mit Feuer. Für Wanderer, die ihre Schritte über Kalimdor lenken, führt die Quest Camping 101: Cooking in die wesentliche Beziehung zwischen kulinarischer Ausbildung und dem Überleben im Grenzland ein. Beim Kochen geht es nicht bloß darum, nahrhafte Mahlzeiten aus erlegtem Wild zuzubereiten; es vermittelt das grundlegende Wissen, das nötig ist, um draußen in den Elementen ein funktionierendes Lagerfeuer zu errichten. Ohne ein Feuer hat ein Abenteurer kein Lager, zu dem er zurückkehren kann, wenn die Nacht hereinbricht."},{t="Das Errichten des Lagers",b="In den wogenden Ebenen von Mulgore werden Abenteurer zu Pyall Silentstride im Dorf der Bluthufe gewiesen, um die Grundlagen des Kochens zu erlernen. Mit dieser grundlegenden Ausbildung erlangt ein Abenteurer die Fähigkeit, überall in der Wildnis ein Lagerfeuer zu entfachen und ein einfaches Lager aufzuschlagen. Während anfängliche Lager schlicht sind und nur wenige Einrichtungsgegenstände zulassen, schaltet das Verbessern der eigenen Kochfertigkeit die Geheimnisse des Entfachens größerer Feuer frei. Im Gegenzug können Handwerker, die in anderen Gewerben bewandert sind, Einrichtungsgegenstände herstellen, um ihre Vorposten im Grenzland auszugestalten."}},faq={{q="Was ist Camping 101: Cooking?",a="Camping 101: Cooking ist eine einführende Quest, die Abenteurern vermittelt, wie das Kochen und das Feuermachen das buchstäbliche Fundament des Überlebens in der Wildnis bilden. Durch das Erlernen der Kochkunst erlangt ein Abenteurer die Fähigkeit, Lagerfeuer zu entfachen und Lagerplätze im Feld zu errichten.",al={"was ist camping 101 cooking","camping kochquest","camping grundlagen kochen"}},{q="Wer ist Pyall Silentstride?",a="Pyall Silentstride ist ein Kochlehrer im Dorf der Bluthufe in Mulgore. Er unterweist angehende Abenteurer in den kulinarischen Künsten und lehrt sie, wie man einfache Lagerfeuer entfacht.",al={"wer ist pyall leisetreter","pyall leisetreter aufenthaltsort","bluthufe kochlehrer"}},{q="Warum ist Kochen notwendig, um das Campen zu erlernen?",a="In der Wildnis geht es beim Kochen um mehr als die Zubereitung von Mahlzeiten; das Erlernen der Kochkunst lehrt einen Abenteurer, wie man ein Lagerfeuer entfacht, welches als physischer und praktischer Anker für jeden Lagerplatz dient.",al={"warum kochen für camping nötig ist","warum kochen lernen fürs campen","lagerfeuer camping verbindung"}},{q="Könnt Ihr größere Lagerfeuer entfachen, wenn sich Eure Fertigkeit verbessert?",a="Wenn Ihr voranschreitet und Eure Kochfertigkeit steigert, entwickelt Ihr das Wissen, das erforderlich ist, um größere, beständigere Feuer zu entfachen, was umfangreichere Lagerplatz-Einrichtungen in der Wildnis ermöglicht.",al={"kann ich lagerfeuer aufwerten","größere lagerfeuer","wie man größere feuer macht"}},{q="Wie richtet Ihr einen Lagerplatz ein?",a="Während ein Lagerfeuer den zentralen Anker eines Lagerplatzes bildet, können zusätzliche Einrichtungsgegenstände und Zubehörteile bei Ausbildern anderer Handwerke in der ganzen Welt erlernt werden, sofern Ihr in deren Gewerben ausgebildet seid.",al={"wie lagerplatz einrichtung funktioniert","lagerplatz dekorationen","lagerplätze einrichten berufe"}},{q="Wo könnt Ihr ein Lager aufschlagen?",a="Sobald Ihr durch die grundlegende Kochausbildung verstanden habt, wie man ein Lagerfeuer entfacht, seid Ihr in der Lage, ein bescheidenes Lager draußen in der offenen Wildnis zu errichten, wohin auch immer Eure Reisen Euch führen.",al={"wo lager aufschlagen","kann ich überall campen","lagerplatz einschränkungen"}}},fp="20,322,22.515.0,17.512.0,29.263.0,26.181.0,42.193.0,53.177.0,30.197.0,28.175.0"}
P.entries["quest:967"] = {n="Der Turm von Althalaxx",s="Diese Quest schlägt die Brücke zwischen den Nachforschungen über den Kult des Dunklen Strands im nördlichen Dunkelküste und der umfassenderen Verteidigung des nördlichen Kalimdor. Balthule Schattenhieb entsendet einen Kurier der Allianz nach Süden zu Maestras Posten in Eschental, um seinen Mentor, Delgren den Läuterer, über die unheilvolle Zusammenkunft des Kults am Turm von Althalaxx in Kenntnis zu setzen.",h="Diese Quest schlägt die Brücke zwischen den Nachforschungen über den Kult des Dunklen Strands im nördlichen...",kw={"eschental","balthule schattenhieb","dunkler strand","dunkelküste","delgren der läuterer","das heilige licht","maestras posten","turm von althalaxx"},ang={["class:Paladin"]="Die Begegnung mit Delgren bietet Paladinen ein inspirierendes Beispiel für ihre heilige Berufung in fremden Landen: ein menschlicher Kreuzfahrer, der das Licht nutzt, um sich das tiefe Vertrauen der zurückgezogenen Nachtelfen Kalimdors zu verdienen.",["faction:Alliance"]="Die Zusammenarbeit zwischen Balthule an der Dunkelküste und Delgren in Eschental verdeutlicht die unverzichtbaren Verbindungswege, die die verstreuten Allianz-Garnisonen im nördlichen Kalimdor zusammenhalten.",["race:NightElf"]="Für Nachtelfen unterstreicht diese Mission die wachsende, praktische Partnerschaft zwischen ihren Schildwachen und den Völkern des Ostens, die herbeigeeilt sind, um bei der Bereinigung ihrer Wälder von dämonischen Überresten zu helfen."},sec={{t="Ein Hilferuf nach Verstärkung",b="Nach ersten Zusammenstößen mit den Kultisten des Dunklen Strands rund um den Turm von Althalaxx erkennt der Nachtelfenspäher Balthule Schattenhieb, dass die Bedrohung seine einsame Wache übersteigt. Um eine entscheidende Reaktion in Gang zu setzen, verfasst er einen ausführlichen Bericht und vertraut ihn einem Boten der Allianz an, der zu seinem Meister, Delgren dem Läuterer, reisen soll. Da die Beschwörer des Kults mit jeder Stunde dreister werden, muss die Kunde erfahrene Anführer erreichen, die in der Lage sind, einen vernichtenden Gegenschlag anzuführen."},{t="Der Weg nach Eschental",b="Balthules Depesche zu überbringen erfordert eine Wanderung über die gesamte Länge von Dunkelküste, entlang der langen Küstenstraße nach Süden, hinaus aus dem Nebel und über die bewaldete Grenze nach Eschental. Delgren der Läuterer, der an Maestras Posten an der westlichen Straße stationiert ist, hat sich der Vernichtung von Dämonen und Untoten verschrieben, die in den Wäldern verweilen. Obwohl ihm die Bräuche der Nachtelfen anfangs fremd waren, hat sich der menschliche Paladin als unverzichtbarer Verbündeter tiefen gegenseitigen Respekt bei den Schildwachen erarbeitet."},{t="Ein geweihter Krieger erwacht",b="Delgren nimmt Balthules dringlichen Brief mit finsterer Entschlossenheit entgegen. Als Krieger, der dem Heiligen Licht geweiht ist, betrachtet er die Anwesenheit dunkler Kultisten, Seelenverderbnis und dämonischer Unholde in diesen uralten Wäldern als unerträgliche Plage. Als er von der festen Stellung des Dunklen Strands an der verfallenen Hochgeborenenturmruine liest, bereitet sich Delgren unverzüglich darauf vor, die Führung des Einsatzes zu übernehmen und zurückzuschlagen."}},faq={{q="Wer ist Delgren der Läuterer?",a="Delgren der Läuterer ist ein menschlicher Paladin, der an Maestras Posten in Eschental stationiert ist. Dem Heiligen Licht ergeben, stellt er den Nachtelfen-Schildwachen sein kriegerisches und spirituelles Können zur Verfügung, um Dämonen und Untote zu läutern, die in ihre angestammten Wälder eindringen.",al={"delgren der läuterer","wer ist delgren","delgren lore"}},{q="Warum schickt Balthule Schattenhieb einen Boten nach Eschental?",a="Balthule ist ein Späher, der vor dem Turm von Althalaxx stationiert ist und den Kult des Dunklen Strands beobachtet hat. Da er erkennt, dass die finsteren Rituale und die Zahl der Kultisten rasch zunehmen, sendet er seine Erkenntnisse an seinen Mentor Delgren, damit ein organisierter Angriff vorbereitet werden kann.",al={"warum brief an delgren senden","balthule brief grund"}},{q="In welcher Beziehung stehen Balthule und Delgren zueinander?",a="Delgren ist Balthules Meister. Der menschliche Paladin hat den Nachtelfen in der Kunst des Kampfes unterwiesen und ihn an die Lehren des Heiligen Lichts herangeführt, wodurch eine ungewöhnlich enge Bindung über ihre kulturellen Unterschiede hinweg entstanden ist.",al={"balthule und delgren","woher kennen sich balthule und delgren"}},{q="Wo liegt Maestras Posten?",a="Maestras Posten ist ein Außenposten der Allianz im westlichen Eschental an der Hauptstraße, die von Dunkelküste nach Süden führt. Er dient als früher Vorposten für Reisende, die zwischen Dunkelküste und den Tiefen des Waldes unterwegs sind.",al={"maestras posten lage","wo liegt maestras posten"}},{q="Was treibt der Kult des Dunklen Strands am Turm von Althalaxx?",a="Der Dunkle Strand ist ein Kult, der von der Ruine des Hochgeborenenturms von Althalaxx im nördlichen Dunkelküste aus operiert. Seine Mitglieder praktizieren dunkle Künste, paktieren mit dämonischen Mächten und drohen damit, verderbende Kräfte über die Küste zu entfesseln.",al={"kult des dunklen strands althalaxx","turm von althalaxx kultisten"}},{q="Wie sieht Delgren sein Bündnis mit den Nachtelfen?",a="Delgren gab zu, dass er anfangs nicht an die Sitten und die Lebensweise der Nachtelfen gewöhnt war, als er zum ersten Mal in Kalimdor eintraf. Im Laufe der Zeit jedoch hat der gemeinsame Kampf gegen die gleichen Übel dazu geführt, dass er immensen Respekt für die Schildwachen hegt.",al={"delgren nachtelfen","menschenpaladin nachtelfen"}}},fx={["4ad41352"]={q="Warum wählt Balthule Schattenhieb Euch als seinen Boten, anstatt selbst zu gehen?",a="Balthule muss in der Nähe von The Tower of Althalaxx stationiert bleiben, um ein wachsames Auge auf die Kultisten von Dark Strand zu haben und ihre eskalierende Bedrohung zu überwachen. Da sich die Reise über die gesamte Länge der Dunkelküste bis ins Eschental erstreckt, benötigt er einen fähigen und gut bewaffneten Reisenden, der auf den gefährlichen Straßen überleben und garantieren kann, dass die dringende Warnung sicher Delgrens Hände erreicht.",al={"warum schickt ihr mich zu delgren","warum balthule bote","warum kann balthule den brief nicht überbringen"}}},fp="22,322,25.469.0,21.486.0,23.383.1,28.252.0,62.264.0,54.217.0,24.221.0,61.223.0,56.246.0"}
P.entries["quest:968"] = {n="Werkzeuge der Hochgeborenen",s="Werkzeuge der Hochgeborenen ist eine Quest der Allianz, die von Thundris Windweaver in Auberdine angeboten wird. Reisende werden nach Süden in die zerstörten Ruinen von Ameth'Aran entsandt, um rastlosen Erscheinungen der Hochgeborenen verweilende magische Relikte zu entreißen. Das Ziel ist einfach: diese uralten Artefakte zu bergen, bevor ihre latente Zauberei weiteres Unheil über Kalimdor bringen kann.",h="Werkzeuge der Hochgeborenen ist eine Quest der Allianz, die von Thundris Windweaver in Auberdine angeboten...",kw={"ameth'aran","auberdine","dunkelküste","hochgeborene","relikte","zerschlagung","thundris windweaver"},ang={["class:Druid"]="Die Beseitigung der verderbten arkanen Überreste aus Ameth'Aran trägt dazu bei, die spirituellen Wunden zu heilen, welche die natürliche Ruhe der Wildnis der Dunkelküste stören.",["class:Mage"]="Während die Gesellschaft der Kaldorei danach trachtet, diese Artefakte aus Furcht zu zerschlagen, erkennen arkane Gelehrte in ihnen seltene, unberührte Beispiele für die Handwerkskunst der Hochgeborenen vor der Zerschlagung.",["faction:Alliance"]="Den Nachtelfen bei der Sicherung ihrer heimgesuchten Gebiete beizustehen, festigt die Präsenz und Solidarität der Allianz in den uralten Wäldern des nördlichen Kalimdor.",["race:NightElf"]="Für die Kaldorei ist die Konfrontation mit den Geistern von Ameth'Aran eine düstere Mahnung an die Hybris ihrer Vorfahren und die katastrophale Zerschlagung ihres angestammten Reiches."},sec={{t="Echos in den Ruinen",b="Südlich von Auberdine, östlich des Küstenwegs, liegen die überwucherten Steinfundamente von Ameth'Aran. Vor zehntausend Jahren diente diese Siedlung als Bastion der Hochgeborenen – der privilegierten Aristokratie des uralten Nachtelfenreichs. Als ihre ungezügelten arkanen Machenschaften in der Zerschlagung der Welt gipfelten, wurde Ameth'Aran zerstört. Doch seine Bewohner sind nie wahrhaft gewichen. Schildwachen, die an der Dunkelküste patrouillieren, berichten, dass die Geister dieser Aristokraten noch immer die versunkenen Plätze heimsuchen und sich an die verzauberten Werkzeuge und Schmuckstücke klammern, die sie zu Lebzeiten besaßen."},{t="Läuterung der arkanen Vergangenheit",b="Für die moderne Gesellschaft der Kaldorei ist das Arkane nicht bloß verbotenes Wissen; es ist eine existenzielle Bedrohung, die das Leben auf Azeroth beinahe ausgelöscht hätte. Thundris Windweaver erkennt, dass das Verbleiben dieser Gerätschaften der Hochgeborenen in Geisterhänden der Verderbnis Tür und Tor öffnet. Indem er Abenteurer entsendet, um den rastlosen Geistern diese Relikte zu entreißen, beabsichtigt Thundris, sie gründlich vernichten zu lassen, damit die schlummernde, behaftete Zauberei niemals wieder eine weitere Katastrophe befeuern kann."}},faq={{q="Wo finde Ich die Relikte der Hochgeborenen?",a="Die Relikte sind in den Ruinen von Ameth'Aran zu finden, südlich von Auberdine auf der östlichen Seite des Hauptwegs durch die Dunkelküste gelegen. Umherwandernde Geister auf den verfallenen Steinhöfen tragen diese uralten Gerätschaften bei sich.",al={"wo sich die relikte befinden","ameth'aran lage","wo relikte zu finden sind"}},{q="Wer ist Thundris Windweaver?",a="Thundris Windweaver ist ein Gelehrter und Ältester der Nachtelfen, der in der Hafenstadt Auberdine weilt. In enger Zusammenarbeit mit den örtlichen Schildwachen koordiniert er die Bemühungen, die Dunkelküste vor verweilenden magischen Verderbnissen und uralten Flüchen zu schützen, die durch die Zerschlagung hinterlassen wurden.",al={"thundris windweaver","wer vergibt werkzeuge der hochgeborenen"}},{q="Warum will Thundris, dass diese Relikte zerstört werden?",a="Die Nachtelfengesellschaft lehnt arkane Magie aufgrund der verheerenden Großen Zerschlagung, die durch die rücksichtslose Zauberei der Hochgeborenen verursacht wurde, strikt ab. Thundris fürchtet, dass die verweilende arkane Macht in diesen Gegenständen schlummernde Übel wiedererwecken könnte, wenn man sie unbeaufsichtigt lässt.",al={"warum die relikte zerstören","zweck von werkzeuge der hochgeborenen"}},{q="Welche Art von Geistern sucht Ameth'Aran heim?",a="Die Geister sind die spektralen Überreste der Elite der Hochgeborenen, die während des Krieges der Ahnen umkam. Selbst im Tode klammern sie sich an ihren einstigen Stolz, ihre Macht und ihre magischen Artefakte und durchleben inmitten des verfallenen Steins ihr verblasstes Leben aufs Neue.",al={"geister in ameth'aran","was sind die geister"}},{q="Warum sind die Hochgeborenen noch immer an die Ruinen gebunden?",a="Thundris sagt es nicht. Er weiß nur, was die Schildwachen ihm berichtet haben: Die Geister der Hochgeborenen verweilen inmitten der Ruinen von Ameth'Aran und führen noch immer ihre uralten magischen Gerätschaften.",al={"warum sind sie geister","fluch der hochgeborenen"}},{q="Was geschieht mit den Relikten, nachdem Ihr sie abgegeben habt?",a="Thundris Windweaver nimmt die gesammelten Relikte mit dem ausdrücklichen Plan in Obhut, sie dauerhaft zerlegen und vernichten zu lassen, damit ihr schlummernder arkaner Makel niemals wieder genutzt oder freigesetzt werden kann.",al={"was macht thundris mit relikten","schicksal der relikte"}}},fx={df86da6d={q="Was sind die Hochgeborenenrelikte?",a="Diese Relikte sind uralte magische Artefakte, die aus der Zeit vor der Großen Zerschlagung erhalten geblieben sind und einst von den Elite-Zauberern des Hofes von Königin Azshara geführt wurden. Selbst nach zehntausend Jahren bewahren sie noch immer den verbleibenden Makel des leichtsinnigen arkanen Spiels, das das alte Kalimdor zerriss. In den Händen verweilender Geister hinterlassen, bleiben sie Kanäle für ruhende, gefährliche Macht.",al={"was sind hochgeborenenrelikte","was ist ein hochgeborenenrelikt","lore zu hochgeborenenrelikten"}}},fp="22,360,19.561.0,23.480.0,37.224.0,27.257.0,46.238.0,38.236.0,47.186.0,50.202.0"}
P.entries["quest:96821"] = {n="Legging It",s="Legging It ist eine Quest, die sich darauf konzentriert, einen gefährlichen südlichen Pfad freizumachen, um arbeitende Peons zu schützen. Bedrohungen entlang der Straße hatten die Arbeitskräfte derart verängstigt, dass sie ihre Reisen einstellten, was grundlegende Pflichten zum Stillstand brachte. Indem sie die Gefahren zurückdrängen, stellen Abenteurer den sicheren Durchgang wieder her und ermöglichen es den Arbeitskräften, zu ihren Aufgaben zurückzukehren.",h="Legging It ist eine Quest, die sich darauf konzentriert, einen gefährlichen südlichen Pfad freizumachen, um...",kw={"pfad freigemacht","arbeit der horde","legging it","vorarbeiter","peon-arbeit","peons","südlicher pfad"},ang={["faction:Horde"]="Orkische Arbeits- und Versorgungslinien hängen stark von Peons ab, weshalb die Sicherung der Routen für die Bauvorhaben und die Rohstoffgewinnung der Horde lebenswichtig ist.",["race:Orc"]="Peons bilden das Rückgrat orkischer Siedlungen, und Vorarbeiter verlassen sich auf Krieger, um die Wege frei von Bedrohungen zu halten, damit die Arbeit fortgesetzt werden kann."},sec={{t="Sicherung der Linie",b="Legging It befasst sich mit einer Unterbrechung der örtlichen Arbeitsabläufe, da Peons zu verängstigt waren, um nach Süden zu reisen. Anstatt ihren zugewiesenen Aufgaben nachzugehen, weigerten sich die Arbeiter aufgrund der drohenden Gefahren, die Reise entlang der Straße zu riskieren. Indem Reisende eingreifen, um Bedrohungen entlang des Pfades zurückzudrängen, stellen sie genügend Sicherheit wieder her, damit Vorarbeiter ihre Mannschaften wieder an die Arbeit schicken können."},{t="Arbeit und Routensicherheit",b="Peons bilden das Rückgrat der Infrastruktur der Horde und sind für den Holzeinschlag, den Steinbruch und den Bau von Außenposten verantwortlich. Da Peons kaum über kriegerisches Geschick verfügen, können selbst unbedeutende Raubtiere am Wegesrand oder feindliche Späher Versorgungsketten lahmlegen. Die Gewährleistung, dass Transitkorridore frei bleiben, ist unerlässlich, um Siedlungen versorgt und produktiv zu halten."}},faq={{q="Was ist Legging It?",a="Legging It ist eine Aufgabe, die übernommen wird, um eine südliche Transitroute für Arbeitsmannschaften zu sichern. Bedrohungen entlang der Straße hatten einheimische Peons eingeschüchtert und ihre täglichen Pflichten lahmgelegt, bis ein Abenteurer eingriff, um den Weg freizumachen.",al={"was ist legging it","questinfos zu legging it","quest legging it"}},{q="Warum hatten die Peons Angst, nach Süden zu reisen?",a="Die Peons fürchteten sich aufgrund akuter Gefahren entlang der Straße davor, sich nach Süden zu wagen. Ohne Schutz oder einen geräumten Pfad weigerten sich die Arbeiter, die Reise zu ihren Aufgaben zu riskieren, was die örtlichen Arbeitsabläufe zum Erliegen brachte.",al={"warum hatten peons angst","furcht der peons","warum peons aufhörten zu arbeiten"}},{q="Was wird durch den Abschluss der Aufgabe erreicht?",a="Da die südliche Route freigemacht und unmittelbare Gefahren gebannt sind, können die Vorarbeiter die Peon-Arbeitskräfte wieder sicher aufs Feld schicken, um die Arbeit und die Rohstoffbeschaffung wiederaufzunehmen.",al={"was nach legging it geschieht","ergebnis von legging it","ergebnis des freimachens des pfades"}},{q="Wer sind die in der Aufgabe erwähnten Peons?",a="Peons sind die grundlegenden Arbeitskräfte der Horde, zuständig für schwere Arbeiten, Holzernte, Bergbau und den Bau von Befestigungen. Obwohl sie für die Abläufe der Siedlungen unverzichtbar sind, eignen sie sich kaum für den Kampf und weichen vor Gefahren rasch zurück.",al={"wer sind die peons","rolle der peons","was peons tun"}},{q="Wohin reisten die Peons?",a="Der Pfad führt nach Süden zu entlegenen Arbeitsbereichen und Rohstoffvorkommen, die eine regelmäßige Instandhaltung durch Peons erfordern, obwohl die Reise so gefährlich geworden war, dass jeglicher Verkehr zum Erliegen kam, bevor die Route geräumt wurde.",al={"wohin der pfad führt","südlicher pfad","richtung süden"}},{q="Warum benötigen Peons Abenteurer, um ihre Routen zu sichern?",a="Peons fehlt es an militärischer Ausbildung und Kampfausrüstung, was sie anfällig für Raubtiere der Wildnis und feindliche Streitkräfte macht. Vorarbeiter müssen sich auf erfahrene Abenteurer verlassen, um Gefahren im Umkreis zu beseitigen und sichere Arbeitskorridore aufrechtzuerhalten.",al={"warum peons schutz brauchen","sicherheit der peons","peons bewachen"}}},fp="10,324,17.367.0,24.349.0,19.211.0,42.218.0,44.182.0,40.243.0,31.207.0,55.231.0"}
P.entries["quest:96822"] = {n="For Honor",s="For Honor ist eine Quest, die dem Gedenken an gefallene Krieger gewidmet ist, damit ihre Taten nicht vergessen werden. Durch den Abschluss der Aufgabe stellt ein Abenteurer sicher, dass die Opfer dieser Kämpfer in Erinnerung bleiben.",h="For Honor ist eine Quest, die dem Gedenken an gefallene Krieger gewidmet ist, damit ihre Taten nicht...",kw={"gefallene krieger","for honor","ehre","denkmal","quest","gedenken","krieger"},ang={["class:Warrior"]="Diese Aufgabe konzentriert sich unmittelbar darauf, gefallene Kämpfer zu ehren, und findet starken Anklang bei Kriegern, die Opfer auf dem Schlachtfeld und dauerhaftes Gedenken schätzen."},sec={{t="Eine Pflicht des Gedenkens",b="Die Quest For Honor ist eine feierliche Mission, bei der das Gedenken an gefallene Kämpfer im Mittelpunkt steht. In einer Welt, die fortwährend durch Konflikte auf die Probe gestellt wird, ist es eine wesentliche Pflicht für jene, die sie überleben, sicherzustellen, dass Soldaten, die alles gaben, nicht vergessen werden."},{t="Das Vermächtnis bewahren",b="Nach Erfüllung der Aufgabe bestätigt der Questgeber, dass die gefallenen Kämpfer dank Eurer Bemühungen im Gedächtnis bleiben werden. Die vollbrachte Tat stellt sicher, dass ihre Opfer anerkannt und geachtet bleiben, anstatt in der Bedeutungslosigkeit zu verblassen."}},faq={{q="Worum geht es in der Quest For Honor?",a="For Honor ist eine Quest, die sich auf das Gedenken an gefallene Kämpfer konzentriert. Indem Ihr die Aufgabe annehmt und abschließt, helft Ihr sicherzustellen, dass die Opfer dieser Krieger gewürdigt werden und nicht in der Geschichte verloren gehen.",al={"was ist for honor","for honor questübersicht"}},{q="Wer sind die nach Abschluss erwähnten Krieger?",a="Der Questtext ehrt ausdrücklich gefallene Krieger, deren Taten und Andenken durch Eure Handlungen bewahrt werden. Ihr Dienst und ihr Opfer werden von jenen lebendig gehalten, die die Aufgabe zu Ende führen.",al={"wer sind die krieger","an wen wird erinnert"}},{q="Warum ist es wichtig, diese Krieger zu ehren?",a="Der Zweck der Aufgabe ist das Gedenken. In einer Welt voller anhaltender Kriege und Konflikte verleiht das Ehren des Andenkens derer, die in der Schlacht fielen, Würde und stellt sicher, dass ihr Mut anerkannt wird.",al={"warum diese quest annehmen","bedeutung von for honor"}},{q="Wer bittet darum, dass diese Aufgabe erledigt wird?",a="Die Aufgabe wird von jemandem geleitet, der gefallener Kameraden gedenken möchte. Bei der Rückkehr überprüft die Person, ob die Tat vollbracht wurde, und erkennt an, dass die Krieger für immer in Erinnerung bleiben werden.",al={"wer gibt for honor","questgeber for honor"}},{q="Führt diese Quest zu weiteren Aufgaben?",a="Nichts in der Quest weist auf eine weitere Aufgabe hin. Sie steht für sich allein als ein Akt des Gedenkens an gefallene Kämpfer und festigt ihr Vermächtnis, damit ihre Opfer niemals vergessen werden.",al={"ist for honor teil einer questreihe","was folgt auf for honor"}},{q="Was bedeutet der Titel For Honor?",a="Der Name spiegelt das zentrale Thema wider, gefallene Soldaten zu ehren. Er unterstreicht, dass das Anerkennen von Opfern und das Wachhalten der Erinnerung an das Schlachtfeld zu den feierlichsten Pflichten gehört, die ein Kämpfer erfüllen kann.",al={"was macht es ehrenhaft","bedeutung von for honor"}}},fp="9,201,21.240.0,21.232.0,34.196.0,47.187.0,41.197.0,34.194.0,36.186.0,38.201.0"}
P.entries["quest:96825"] = {n="This Fruit Could Bite Back",s="This Fruit Could Bite Back ist eine Sammelquest, bei der es darum geht, wilde Kaktusfeigen in den trockenen Ländereien nahe Orgrimmar zu sammeln. Die Früchte werden zu Nahrung verarbeitet, während ihre Samen für die zukünftige Aussaat aufgehoben werden, mit dem Ziel, eine widerstandsfähige Wüstenpflanze zu kultivieren, um die Hauptstadt der Horde zu ernähren.",h="This Fruit Could Bite Back ist eine Sammelquest, bei der es darum geht, wilde Kaktusfeigen in den trockenen...",kw={"kaktusfrucht","durotar","frucht","orgrimmar","kaktusfeige","kaktusfeigen","samen","this fruit could bite back"},ang={["faction:Horde"]="Die Sicherung nachhaltiger Nahrungsquellen wie nahrhafter Wüstenfrüchte ist entscheidend für den Erhalt der orkischen Hauptstadt und die Ernährung der wachsenden Bevölkerung der Horde.",["profession:Cooking"]="Kaktusfeigen bieten im trockenen Klima von Durotar kulinarisches Potenzial und dienen als Zutaten für schmackhafte Gerichte und als Vorräte für die Stadtbewohner.",["profession:Herbalism"]="Sammler und Botaniker verstehen die Widerstandsfähigkeit der Wüstenflora und die Mühe, die erforderlich ist, um stachelige Wildfrüchte für den Anbau zu sammeln."},sec={{t="Die Ernte der kargen Ödnis",b="Durotar ist eine raue, sonnenverbrannte Landschaft, in der traditionelle Landwirtschaft nahezu unmöglich ist. Um die aufstrebende Hauptstadt Orgrimmar zu versorgen, greifen findige Bewohner auf die einheimische Wüstenflora zurück. Die Kaktusfeige, eine widerstandsfähige Kaktusfrucht, die mit schützenden Stacheln ausgestattet ist, gedeiht im trockenen Boden und bietet dringend benötigte Nahrung, wenn sie mit Vorsicht geerntet wird."},{t="Kultivierung und Lebensunterhalt",b="Beim Sammeln von Kaktusfeigen geht es nicht nur um eine unmittelbare Mahlzeit. Während das Fruchtfleisch zu schmackhaften Gerichten zubereitet wird, werden die geernteten Samen sorgfältig für den Anbau aufbewahrt. Das Ziel ist es, diese widerstandsfähigen Pflanzen rund um Orgrimmar anzubauen, um direkt vor den Festungsmauern eine zugängliche und dauerhafte Nahrungsquelle zu schaffen."}},faq={{q="Was ist This Fruit Could Bite Back?",a="This Fruit Could Bite Back ist eine Aufgabe, die sich auf das Sammeln wilder Kaktusfeigen in Durotar konzentriert. Die gesammelten Früchte sind sowohl für das sofortige Kochen gedacht als auch für die Gewinnung von Samen, um sie über das trockene Gelände rund um Orgrimmar zu verbreiten.",al={"was ist this fruit could bite back","this fruit could bite back quest","bite back frucht quest"}},{q="Warum werden Kaktusfeigen gesammelt?",a="Die gesammelten Kaktusfeigen erfüllen einen doppelten Zweck: die Zubereitung köstlicher Mahlzeiten für den Verzehr vor Ort und das Ernten lebensfähiger Samen. Das langfristige Ziel ist es, Kaktusfeigen im gesamten trockenen Land rund um Orgrimmar weitflächig anzubauen.",al={"warum kaktusfeigen sammeln","kaktusfeige zweck","wofür sind kaktusfeigen da"}},{q="Wo werden die Samen gepflanzt?",a="Die aus der Ernte gewonnenen Samen sollen in den Außenbezirken und den Ländereien rund um Orgrimmar gepflanzt werden, was dazu beiträgt, eine widerstandsfähige, autarke Nahrungsversorgung im rauen Wüstenboden aufzubauen.",al={"wo wachsen kaktusfeigen","kaktusfeigen pflanzen orgrimmar"}},{q="Wer möchte, dass diese Früchte gesammelt werden?",a="Ein einheimischer Bewohner bittet um die Ernte, um die örtlichen Nahrungsvorräte aufzubessern und Nutzpflanzen im rauen Wüstenklima von Durotar anzubauen, um Reisende zu ernähren und zukünftige Saaten heranzuziehen.",al={"wer will die kaktusfeigen","questgeber bite back"}},{q="Warum „beißt“ die Frucht zurück?",a="Kaktusfeigen sind mit scharfen Stacheln und Nadeln bedeckt, wie sie für robuste Wüstenkakteen typisch sind, was ihre Ernte ohne entsprechende Vorsicht gefährlich macht.",al={"warum zurückbeißen","warum beißt frucht zurück"}},{q="Warum ist das Anpflanzen von Früchten rund um Orgrimmar wichtig?",a="Durotar ist überwiegend trocken und felsig, was die herkömmliche Landwirtschaft erschwert. Die Etablierung von dürretoleranten Nutzpflanzen wie Kaktusfeigen trägt dazu bei, eine nachhaltige Nahrungsgrundlage für die Hauptstadt zu schaffen.",al={"mangelt es orgrimmar an nahrung","orgrimmar landwirtschaft","durotar ackerbau"}}},fp="26,286,26.348.0,26.348.0,35.227.0,37.223.0,32.211.0,32.179.0,31.138.0,49.197.0"}
P.entries["quest:96875"] = {n="Beasts of Thunder Ridge",s="Beasts of Thunder Ridge ist eine Quest in Orgrimmar, die von der Lederverarbeiterin Kamari vergeben wird, welche die fortlaufende Erweiterung der Hauptstadt der Horde unterstützt. Abenteurer werden in die zerklüfteten Felsen des Donnergrats entsandt, um widerstandsfähige Eidechsenbälge zu sammeln und gehärtete Felle bereitzustellen, um die neu errichteten Bauten der Stadt zu verstärken.",h="Beasts of Thunder Ridge ist eine Quest in Orgrimmar, die von der Lederverarbeiterin Kamari vergeben wird...",kw={"beasts of thunder ridge","gehärtetes leichtes fell","durotar","kamari","lederverarbeitung","orgrimmar","peons","rauer eidechsenbalg","donnergrat"},ang={["faction:Horde"]="Während die Horde ihre Präsenz in Durotar aufbaut, treiben aus der umliegenden Wildnis gesammelte Vorräte direkt die Befestigung und das Wachstum von Orgrimmar voran.",["race:Orc"]="Die orcische Bauweise stützt sich auf robuste, langlebige Materialien, die von Jägern und Arbeitern gesammelt werden, um den Elementen von Durotar standzuhalten."},sec={{t="Eine wachsende Hauptstadt",b="Während die Horde ihre Heimat in den trockenen Weiten von Durotar errichtet, befindet sich die Hauptstadt Orgrimmar in einem Zustand ständiger Erweiterung. Neue Behausungen, Werkstätten und Verteidigungsanlagen erfordern einen stetigen Nachschub an Holz, Stein und Tierhäuten. Während Bauholz von weiter her herangeschafft werden muss, bietet die einheimische Tierwelt von Durotar einen robusten Vorrat an widerstandsfähigen Bälgen für die Peons und Baumeister der Stadt."},{t="Bestien des Canyons",b="In den Tiefen des Donnergrats entwickeln die einheimischen Eidechsen zähe, wettergegerbte Bälge. Obwohl diese Felle im Allgemeinen zu dick und steif sind, um daraus tragbare Lederrüstung zu fertigen, macht ihre Widerstandsfähigkeit sie zu einem außergewöhnlichen Baumaterial. Wenn sie fachgerecht gewonnen werden, dienen sie dazu, die Decken und Wände von Orgrimmars Holz- und Steinbauten auszukleiden, wodurch das Innere vor der sengenden Sonne und plötzlichen Canyonwinden geschützt wird."}},faq={{q="Warum benötigt Orgrimmar Eidechsenbälge aus dem Donnergrat?",a="Die im Donnergrat gesammelten rauen Eidechsenbälge sind viel zu grob und dick, um daraus tragbare Rüstung herzustellen, doch ihre Zähigkeit macht sie ideal für bauliche Zwecke. Peons in Orgrimmar nutzen sie, um die Wände und Dächer neu errichteter Gebäude auszukleiden und so Schutz vor den rauen Elementen zu bieten.",al={"wofür sind die bälge","warum rauer eidechsenbalg","wofür werden donnergrat-bälge verwendet"}},{q="Wer ist Kamari?",a="Kamari ist eine Lederverarbeiterin in der Hauptstadt der Horde, Orgrimmar, die die Baumeister und Peons der Stadt mit robusten Fellen und Bälgen versorgt, die für fortlaufende Bauprojekte benötigt werden.",al={"wer ist kamari","kamari orgrimmar","wer vergibt beasts of thunder ridge"}},{q="Wo befindet sich der Donnergrat?",a="Der Donnergrat ist eine zerklüftete Schlucht im ariden Territorium von Durotar, bekannt für die Eidechsen, deren dicke Bälge Kamari für die neuen Gebäude der Stadt benötigt.",al={"wo ist der donnergrat","donnergrat standort","donnergrat durotar"}},{q="Warum werden neben Eidechsenbälgen auch gehärtete leichte Felle verlangt?",a="Neben den schweren Eidechsenbälgen benötigt Kamari gehärtete leichte Felle als Ergänzung zu den schwereren Materialien, was die umfassendere Vertrautheit und das Geschick eines Abenteurers in der Lederverarbeitung auf die Probe stellt.",al={"warum gehärtete leichte felle","wofür sind die gehärteten felle"}},{q="Warum expandiert Orgrimmar so schnell?",a="Als neu gegründete Hauptstadt der Horde befindet sich Orgrimmar im ständigen Bau und Ausbau, um einer wachsenden Zahl von Orcs und ihren Verbündeten Platz zu bieten, was eine anhaltende Nachfrage nach Rohstoffen erzeugt.",al={"warum baut orgrimmar","orgrimmar erweiterung"}},{q="Können die Eidechsenbälge aus dem Donnergrat zu Rüstung verarbeitet werden?",a="Raue Eidechsenbälge aus dem Donnergrat sind typischerweise zu dick und starr, um daraus flexible Rüstung zu fertigen, weshalb ihr primärer praktischer Nutzen eher im Bauwesen als in tragbarer Ausrüstung liegt.",al={"kann man eidechsenbälge tragen","ist rauer eidechsenbalg rüstung"}}},fp="23,302,17.404.0,20.426.0,56.295.0,14.172.0,31.161.0,60.183.0,38.198.0,59.173.0"}
P.entries["quest:96876"] = {n="Ukor's Lost Pack",s="Ukor's Lost Pack ist ein fallengelassener Gegenstand, der in der Wildnis des südlichen Durotar gefunden werden kann und den grob aufgestickten Namen seines Besitzers trägt. Er wurde in aller Eile weggeworfen, als Ukor vor einer furchterregenden Begegnung mit einer riesigen, in dieser Region heimischen Spinne floh.",h="Ukor's Lost Pack ist ein fallengelassener Gegenstand, der in der Wildnis des südlichen Durotar gefunden...",kw={"durotar","horde","verlorener rucksack","suedliches durotar","spinne","ukor","ukor's lost pack"},ang={["faction:Horde"]="Junge Abenteurer der Horde, die durch das südliche Durotar ziehen, helfen häufig Einheimischen wie Ukor und beweisen ihren Wert sowie ihre Zuverlässigkeit, indem sie verlorene persönliche Habseligkeiten vor gefährlichen Wildtieren bergen."},sec={{t="Ein verlorener Besitz",b="Beim Durchqueren der trockenen Wildnis des südlichen Durotar stößt ein Abenteurer auf eine verlassene Reisetasche, auf deren Klappe grob der Name „Ukor“ gestickt ist. Das Überleben in den rauen Gefilden von Durotar lässt wenig Raum für unvorsichtiges Umherstreifen, und das Finden weggeworfener Ausrüstung deutet gewöhnlich auf eine verhängnisvolle Begegnung in der Nähe hin."},{t="Flucht aus der Wildnis",b="Nachdem der Rucksack zu Ukor im südlichen Durotar zurückgebracht wurde, kommt die Geschichte hinter dessen Zurücklassen ans Licht. Ukor ließ die Tasche in Panik fallen, als er von einer gewaltigen, in dieser Region heimischen Spinne überrumpelt wurde, überzeugt davon, seine Vorräte niemals wiederzusehen. Die unversehrte Tasche wiederzuerlangen bringt dem Reisenden aufrichtige Dankbarkeit und Lob ein."}},faq={{q="Wer ist Ukor?",a="Ukor ist ein Bewohner, der im südlichen Durotar lebt. Als er in der trockenen Wildnis mit einer riesigen Spinne konfrontiert wurde, war er gezwungen, seine Habseligkeiten in einem verzweifelten Versuch, sich in Sicherheit zu bringen, zurückzulassen.",al={"wer ist ukor","ukor durotar"}},{q="Warum verlor Ukor seinen Rucksack?",a="Ukor ließ seinen Rucksack fallen, während er vor einer riesigen, in Durotar lauernden Spinne um sein Leben rannte. Er ging davon aus, dass seine Habseligkeiten für immer verloren seien, bis ein Abenteurer die Tasche aufspürte.",al={"warum ging der rucksack verloren","wo verlor ukor den rucksack"}},{q="Wohin muss der Rucksack gebracht werden?",a="Der wiederbeschaffte Rucksack gehört Ukor, der wartend im südlichen Durotar anzutreffen ist, bereit, zurückkehrende Reisende zu begrüßen.",al={"wohin den rucksack zurueckbringen","ukor abgabe"}},{q="Wie wird der Rucksack identifiziert?",a="Der Rucksack lässt sich leicht an Ukors Namen erkennen, der grob auf die Klappe der Tasche gestickt ist.",al={"wie wird der rucksack identifiziert","rucksacknaht"}},{q="Welche Art von Kreatur jagte Ukor?",a="Ukor wurde von einer riesigen Spinne überfallen, die das Gelände des südlichen Durotar durchstreifte, was ihn derart verängstigte, dass er all seine Habseligkeiten fallen ließ und um sein Leben rannte.",al={"spinne in durotar","welche spinne ukor angriff"}},{q="Was passiert, wenn Ihr Ukor den Rucksack zurückbringt?",a="Ukor ist erstaunt und zutiefst dankbar, seine verlorenen Habseligkeiten wiederzusehen, und erklärt den Abenteurer, der seine Tasche wiederbeschafft hat, zu einem wahren Helden.",al={"ukor belohnung","wie reagiert ukor"}}},fp="16,232,16.327.0,17.317.0,12.183.0,27.174.0,37.116.0,27.99.0,34.152.0,46.138.0"}
P.entries["quest:96895"] = {n="The Argent Emissary",s="The Argent Emissary markiert die Ankunft zweier verlassener Vertreter der Argentumdämmerung, die Geißelkultisten nahe Unterstadt aufspüren. Ihre Anwesenheit unterstreicht sowohl den gemeinsamen Kampf gegen die Geißel als auch die schwelenden Spannungen zwischen dem neutralen Orden und den Behörden der Verlassenen.",h="The Argent Emissary markiert die Ankunft zweier verlassener Vertreter der Argentumdämmerung, die...",kw={"argentumdämmerung","the argent emissary","kultisten","verlassene","geißelkultisten","tirisfal","unterstadt"},ang={["faction:Horde"]="Obwohl die Argentumdämmerung neutral ist, behalten die Behörden der Horde ihre unabhängigen Operationen nahe Unterstadt wachsam im Auge.",["race:Undead"]="Zu sehen, wie Mitskrupellose bzw. Mitverlassene die Argentumdämmerung Unterstadt vorziehen, dient als deutliche Erinnerung an die geteilten Loyalitäten unter den freien Untoten."},sec={{t="Wachsamer Empfang",b="Zwei Gesandte der Verlassenen aus den Reihen der Argentumdämmerung sind vor Kurzem in Tirisfal eingetroffen und versetzen die örtlichen Behörden in Unruhe. Obwohl die Argentumdämmerung der Geißel entgegentritt, bleiben die einheimischen Verlassenen misstrauisch gegenüber jedem bewaffneten, neutralen Orden, der unüberwacht in ihrem Hoheitsgebiet agiert. Selbst die gemeinsame Herkunft der Gesandten vermag ihre Wachsamkeit kaum zu dämpfen."},{t="Kultisten vor den Toren",b="Die Gesandten kamen nicht, um die Ruinen von Lordaeron zu bewundern; sie verfolgen eine Gruppe von Geißelkultisten, die südöstlich an den Außenbezirken von Unterstadt auf der Lauer lagen. Entschlossen, die Agenten des Lichkönigs auszumerzen, bevor sie Fuß fassen können, hat sich einer der Gesandten in Stellung nahe den Stadttoren begeben, um die Bewegungen des Feindes zu überwachen."}},faq={{q="Wer sind die Gesandten der Argentumdämmerung?",a="Zwei Gesandte, welche die Argentumdämmerung vertreten, reisten vor Kurzem nach Tirisfal. Bemerkenswerterweise sind beide dieser Gesandten Verlassene, die sich dem heiligen und neutralen Orden angeschlossen haben, anstatt einzig Unterstadt zu dienen.",al={"wer sind die gesandten","besucher der argentumdämmerung","wer kam nach tirisfal"}},{q="Warum operiert die Argentumdämmerung nahe Unterstadt?",a="Sie spüren Geißelkultisten auf, die dabei ertappt wurden, wie sie sich in den Außenbezirken südöstlich von Unterstadt herumtrieben. Die Argentumdämmerung hat es sich zur Aufgabe gemacht, Überreste der Geißel zu jagen, wo immer sie auftauchen, selbst in der Nähe bedeutender Siedlungen der Horde.",al={"warum sind sie nahe unterstadt","mission der argentumdämmerung in tirisfal","was tun die gesandten"}},{q="Warum sind einheimische Verlassene misstrauisch gegenüber den Gesandten?",a="Auch wenn die Argentumdämmerung im Kampf gegen die Geißel den gemeinsamen Feind bekämpft, missfällt den einheimischen Verlassenen das unüberwachte Agieren neutraler bewaffneter Organisationen in Tirisfal, ungeachtet dessen, ob jene Gesandten ihren untoten Zustand teilen.",al={"warum nervös wegen argentumdämmerung","kann man der argentumdämmerung vertrauen","sicht der verlassenen auf argentumdämmerung"}},{q="Welche Bedrohung geht von den Kultisten aus?",a="Eine Zelle von Geißelkultisten wurde gesichtet, wie sie im Südosten nahe den Außenbezirken der Stadt lauerte. Aufgrund der anhaltenden Bedrohung, die der Lichkönig für freie Untote darstellt, zog ihre Anwesenheit sofort die Aufmerksamkeit sowohl einheimischer Späher als auch der Argentumdämmerung auf sich.",al={"kultisten außerhalb von unterstadt","geißel in tirisfal","wer sind die kultisten"}},{q="Wohin ging der Gesandte?",a="Einer der Gesandten begab sich nach Südosten in Richtung des Eingangs von Unterstadt und beschattete die Bewegungen der Geißelkultisten, die unmittelbar vor den Stadtmauern operierten.",al={"wo findet man den gesandten","standort des gesandten","mitglied der argentumdämmerung finden"}},{q="Dienen Verlassene in der Argentumdämmerung?",a="Ja. Im Gegensatz zum Scharlachroten Kreuzzug heißt die Argentumdämmerung alle willkommen, die gewillt sind, gegen die Geißel zu kämpfen, einschließlich untoter Wesen mit freiem Willen, die sich der Sache widmen.",al={"sind verlassene in argentumdämmerung erlaubt","argentumdämmerung untote","können untote der argentumdämmerung beitreten"}}},fp="19,285,12.370.0,21.360.0,30.233.0,52.219.0,46.234.0,41.244.0,26.162.0,41.174.0"}
P.entries["quest:96896"] = {n="A Righteous Cause",s="A Righteous Cause zeigt ein Gespräch zwischen Leonid Barthalomew the Revered und Danitha Morr, während sie über die Verteidigung der Unterstadt gegen Naxxramas nachdenken. Ihr Austausch hebt die Erinnerung an Garek Bandarion hervor, einen untoten Helden, der wiederentdeckte, wie man das Heilige Licht als Paladin führt. Die Quest beleuchtet jene seltenen Verlassenen, die danach streben, ihre Verbindung zum Licht trotz der Skepsis ihrer Artgenossen aufrechtzuerhalten.",h="A Righteous Cause zeigt ein Gespräch zwischen Leonid Barthalomew the Revered und Danitha Morr, während sie...",kw={"danitha morr","verlassene","garek bandarion","leonid barthalomew","kapelle des hoffnungsvollen lichts","naxxramas","paladin","a righteous cause","geißel","unterstadt"},ang={["class:Paladin"]="Garek Bandarion und Danithas Kohorte stellen eine außergewöhnliche Entwicklung dar: Verlassene, die trotz ihres untoten Zustands wiederentdecken, wie man das Heilige Licht als Paladine führt.",["faction:Horde"]="Leonid Barthalomews Anwesenheit verdeutlicht die Verbindungen zwischen den Verteidigern der Unterstadt und der Argentumdämmerung mit Sitz an der Kapelle des Hoffnungsvollen Lichts in den Pestländern.",["race:Undead"]="Während Leonid und Danitha danach streben, sich wieder mit dem Licht zu verbinden, bleiben die meisten Verlassenen dem heiligen Pfad in ihrem Untod gegenüber distanziert oder feindselig eingestellt."},sec={{t="Wiedersehen der Veteranen",b="A Righteous Cause dreht sich um ein ergreifendes Wiedersehen zwischen zwei erfahrenen Verteidigern von Lordaeron: Leonid Barthalomew the Revered und Danitha Morr. Nachdem sie den grauenvollen Angriff überstanden haben, als Naxxramas die Geißel auf die Unterstadt losließ, denken die beiden über ihre gefallenen Kameraden und den schwierigen Weg nach, den jene Verlassenen beschreiten, die das Heilige Licht noch immer verehren."},{t="Das Erbe von Garek Bandarion",b="Der Mittelpunkt ihrer gemeinsamen Erinnerung ist Garek Bandarion, der gefallene Held, nach dem die Feste benannt wurde. Laut Leonid war Garek möglicherweise der allererste der Verlassenen, der wiederentdeckte, wie man das Heilige Licht als wahrer Paladin führt. Während die meisten Verlassenen sich gänzlich vom Licht abgewandt haben, widmen sich Danitha und ihre Kohorte der Bewahrung von Gareks Erbe und der Erforschung des Potenzials eines heiligen Untodes."},{t="Rückkehr in die Pestländer",b="Im Anschluss an sein Gespräch mit Danitha bereitet sich Leonid darauf vor, die Feste zu verlassen. Seine Loyalität gilt dem fortwährenden Kampf gegen die Geißel im verheerten Osten, wo er seinen Posten an der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern bezieht und jeden tüchtigen Abenteurer willkommen heißt, der bereit ist, für die Sache zu den Waffen zu greifen."}},faq={{q="Wer ist Leonid Barthalomew the Revered?",a="Leonid Barthalomew the Revered ist ein prominentes untotes Mitglied der Argentumdämmerung. Obwohl er von der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern aus operiert, pflegt er Verbindungen zu ehemaligen Kameraden in Lordaeron, die an seiner Seite gegen die Geißel gekämpft haben.",al={"wer ist leonid barthalomew","leonid der verehrte","leonid barthalomew lore"}},{q="Wer ist Danitha Morr?",a="Danitha Morr ist eine Anführerin der Verlassenen, die während des Angriffs der Geißel auf die Unterstadt an der Seite von Leonid Barthalomew kämpfte. Sie führt nun eine Kohorte an, die sich der Weiterführung der Lehren und des heiligen Erbes von Garek Bandarion widmet.",al={"wer ist danitha morr","danitha","danitha morr lore"}},{q="Wer war Garek Bandarion?",a="Garek Bandarion war ein heroischer Streiter der Verlassenen, der bei der Verteidigung der Unterstadt fiel, als Naxxramas angriff. Leonid merkt an, dass er möglicherweise der allererste Verlassene war, der wiederentdeckte, wie man das Heilige Licht als Paladin führt.",al={"wer ist garek bandarion","garek bandarion lore","feste benannt nach"}},{q="Was geschah während des Angriffs auf die Unterstadt?",a="Als die Nekropole Naxxramas einen Angriff auf die Unterstadt startete, schlossen sich Champions der Verlassenen, darunter Danitha Morr, Leonid Barthalomew und Garek Bandarion, zusammen, um die Stadt gegen den Ansturm der Geißel zu verteidigen, und erlitten in diesem Ringen schwere Verluste.",al={"unterstadt naxxramas angriff","verteidigung von unterstadt","geißel angriff unterstadt"}},{q="Können die Verlassenen das Licht als Paladine führen?",a="Während das Kanalisieren des Lichts untotem Fleisch qualvolle Schmerzen zufügt und von den meisten Verlassenen abgelehnt wird, bewies Garek Bandarion, dass es für einen untoten Krieger möglich ist, das Heilige Licht als Paladin zu führen – eine Praxis, die Danitha und ihre Kohorte weiterhin erforschen.",al={"können verlassene paladine sein","untoter paladin lore","verlassene lichtwirker"}},{q="Wohin geht Leonid Barthalomew danach?",a="Nachdem er seine Freunde besucht und mit Danitha Morr gesprochen hat, plant Leonid, zur Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern zurückzukehren, wo die Argentumdämmerung ihren Kreuzzug gegen die Geißel koordiniert.",al={"wohin geht leonid","leonid später finden","kapelle des hoffnungsvollen lichts leonid"}}},fp="17,426,19.353.0,29.416.0,25.311.0,38.251.0,20.220.0,24.225.0,49.261.0,45.270.0,44.201.0"}
P.entries["quest:96897"] = {n="The Cult of the Damned",s="Der Kult der Verdammten ist eine Aufgabe, bei der man den sterblichen Dienern der Geißel entgegentritt, die in Tirisfal aktiv sind. Durch das Ausdünnen von Dark Neophytes und Dark Enforcers verhindern Verteidiger, dass die heimtückischen lebenden Agenten des Lichkönigs jene Verrätereien wiederholen, die einst Lordaeron erschütterten.",h="Der Kult der Verdammten ist eine Aufgabe, bei der man den sterblichen Dienern der Geißel entgegentritt, die...",kw={"kult der verdammten","dunkle vollstrecker","dunkle neophyten","lebende diener","lordaeron","nekromantie","geißel","tirisfal"},ang={["class:Paladin"]="Paladine leisteten Eide, den Schatten auszumerzen, der Lordaeron brach, was die lebenden, der Geißel ergebenen Kultisten zu geschworenen Feinden des Lichts macht.",["class:Priest"]="Priester aller Disziplinen erkennen die Perversion des Glaubens, die der Kult der Verdammten darstellt, welcher heilige Hingabe gegen dunkle Nekromantie eintauscht.",["race:Undead"]="Verlassene wissen allzu gut, wie die lebenden Kultisten Lordaeron verwüsteten und ihren Untod herbeiführten. Frische Zellen des Kults in Tirisfal aufzuhalten, ist unerlässlich, um das neue Königreich zu sichern."},sec={{t="Sterbliche Handlanger der Geißel",b="Der Kult der Verdammten stellt das sterbliche Gesicht der Geißel dar. Zusammengesetzt aus lebenden Männern und Frauen, die dem Lichkönig die Treue schworen, agieren diese Kultisten dort, wo geistlose Tote es nicht können. In Tirisfal, wo die Bewohner bereits mit umherstreifenden Untoten und unerbittlichen Eiferern des Scharlachroten Kreuzzugs zu kämpfen haben, signalisieren neu entdeckte Zellen von Dunklen Neophyten und Dunklen Vollstreckern einen heimtückischen Versuch der Geißel, wieder Fuß zu fassen."},{t="Lehren des Falls",b="Lordaeron wurde nicht bloß durch marschierende Legionen der Toten ins Verderben gestürzt, sondern durch Nachbarn, die Nachbarn verrieten. Der Kult der Verdammten infiltrierte ursprünglich Dörfer, vergiftete Kornspeicher und inszenierte den Zusammenbruch des Königreichs aus den Schatten heraus. Wachsam gegenüber frischen Aktivitäten des Kults in Tirisfal zu bleiben, ist unerlässlich, um sicherzustellen, dass sich die Geschichte in den gezeichneten Ländern des Nordens nicht wiederholt."}},faq={{q="Was ist der Kult der Verdammten?",a="Der Kult der Verdammten ist eine Organisation von Sterblichen, die dem Lichkönig und der Geißel bereitwillig dienen. Anstatt als geistlose Untote auferweckt zu werden, verbreiten diese lebenden Akolythen ganz bewusst die Seuche, sabotieren Verteidigungsanlagen und praktizieren Nekromantie im Dienste des Todes.",al={"was ist der kult der verdammten","wer sind die kultisten","wer sind dunkle neophyten"}},{q="Warum operieren Mitglieder des Kults in Tirisfal?",a="Tirisfal bleibt ein umkämpftes Grenzland, das von geistlosen Untoten, Eiferern des Scharlachroten Kreuzzugs und überlebenden Nestern des Einflusses der Geißel heimgesucht wird. Der Kult operiert verdeckt in der Region, um den örtlichen Widerstand zu untergraben und die finsteren Pläne der Geißel voranzutreiben.",al={"warum kultisten in tirisfal sind","kult in tirisfal"}},{q="Wer sind die Dunklen Neophyten und Dunklen Vollstrecker?",a="Dunkle Neophyten sind frische Initianden, die dunkle Künste und Rituale erlernen, während Dunkle Vollstrecker als Schlägertrupps die Operationen des Kults bewachen und die Disziplin in ihren Reihen aufrechterhalten. Zusammen bilden sie aktive operative Zellen vor Ort.",al={"wer sind dunkle vollstrecker","rolle der dunklen neophyten"}},{q="Warum gelten lebende Diener als schlimmer als geistlose Untote?",a="Geistlose Untote handeln rein aus Instinkt oder auf direkten Befehl, doch lebende Kultisten haben sich bei vollem Bewusstsein für den Verrat entschieden. Ihre Fähigkeit, sich unter die sterblichen Gesellschaften zu mischen und Siedlungen zu infiltrieren, macht sie weitaus heimtückischer als umherstreifende Ghule oder Skelette.",al={"warum lebende kultisten schlimmer sind","lebende diener der geißel"}},{q="Was bedeutet es, wenn die Quest verlangt, die Geschichte Lordaerons dürfe sich nicht wiederholen?",a="Lordaeron fiel nicht allein durch eine offene äußere Invasion, sondern weil der Kult der Verdammten klammheimlich Getreidevorräte vergiftete und seine Mitbürger von innen heraus verriet. Den Kultisten zu erlauben, erneut Fuß zu fassen, beschwört dieselbe Katastrophe herauf.",al={"geschichte von lordaeron wiederholen","fall von lordaeron kult"}},{q="In welcher Beziehung steht der Kult zum Scharlachroten Kreuzzug in Tirisfal?",a="Der Scharlachrote Kreuzzug jagt fanatisch alles, was vom Untod befleckt ist, wodurch sowohl die Geißel als auch der Kult zu Hauptzielen werden. Dieser andauernde Konflikt lässt die örtlichen Bewohner zwischen geistlosen Schrecken, eifernden Kreuzfahrern und verdeckten Kultisten gefangen zurück.",al={"verhältnis zum scharlachroten kreuzzug","kult gegen scharlachroten kreuzzug"}}},fp="22,276,28.432.0,19.400.0,31.262.0,57.261.0,46.233.0,62.256.0,74.239.0,60.241.0"}
P.entries["quest:96898"] = {n="Remnants of War",s="Remnants of War beauftragt Abenteurer damit, zersplitterte Scherben des nekrotischen Fokussierungskristalls zu bergen, die während ihres Angriffs auf die Unterstadt von Naxxramas abgesprengt wurden. Sowohl die Verlassenen als auch die Argentumdämmerung erlitten schwere Verluste bei der Abwehr der Zitadelle, und das Sammeln dieser gefährlichen Fragmente verhindert, dass Kultisten der Geißel ihre dunkle Magie zurückerlangen.",h="Remnants of War beauftragt Abenteurer damit, zersplitterte Scherben des nekrotischen Fokussierungskristalls...",kw={"argentumdämmerung","kultisten","verlassene","naxxramas","nekrotische kristallfragmente","remnants of war","geißel","tirisfal","unterstadt"},ang={["class:Mage"]="Selbst zerbrochen und weitgehend verbraucht behalten die nekrotischen Fokussierungskristalle von Naxxramas instabile magische Energie, die äußerste Vorsicht erfordert.",["class:Priest"]="Die verbliebene unheilige Verderbnis, die in den nekrotischen Scherben wohnt, stellt eine gefährliche Plage dar, die eingedämmt werden muss, bevor sie das Land weiter entweiht.",["faction:Horde"]="Die Sicherung von Tirisfal vor verbliebener Magie der Geißel trägt zum Schutz der Unterstadt bei und sichert den lebenswichtigen Stützpunkt der Horde im nördlichen Lordaeron.",["race:Undead"]="Der Angriff durch Naxxramas bedrohte die bloße Existenz der Unterstadt. Die Bergung dieser Fragmente schützt Euer Volk vor einem Wiedererstarken der Geißel vor Eurer eigenen Haustür."},sec={{t="Der Schatten über der Stadt",b="Vor nicht allzu langer Zeit ragte die Schreckenszitadelle Naxxramas direkt über Tirisfal auf, mit dem Ziel, die Unterstadt auszulöschen und die Verlassenen vollständig zu vernichten. In einer verzweifelten Verteidigung schlugen die Verlassenen und die Argentumdämmerung die schwebende Festung unter großen Opfern zurück. Während des Zusammenstoßes wurde der gewaltige nekrotische Fokussierungskristall auf der Spitze von Naxxramas zerstört, wodurch Fragmente über die Lichtungen darunter geschleudert wurden."},{t="Verstreute Nekromantie",b="Obwohl die Zitadelle vertrieben wurde, bleiben die Überreste im Boden eingebettet. Kultisten der Geißel sind herangerückt, um die nekrotischen Kristallfragmente zu bergen, in der Hoffnung, sich die noch immer in ihnen schlummernde dunkle Magie zunutze zu machen. Das Sammeln dieser Scherben entzieht der Geißel rohe unheilige Macht, auch wenn es Jahre dauern wird, jedes einzelne Stück aus Tirisfal zu beseitigen."}},faq={{q="Was sind die nekrotischen Kristallfragmente?",a="Es sind zersplitterte Teile des gewaltigen nekrotischen Fokussierungskristalls, der einst auf der schwebenden Schreckenszitadelle Naxxramas angebracht war. Als der Kristall während des Angriffs auf die Unterstadt zerstört wurde, regnete es Scherben über Tirisfal herab.",al={"was sind nekrotische kristallfragmente","was sind die kristalle","nekrotische kristalle"}},{q="Warum griff Naxxramas die Unterstadt an?",a="Naxxramas stieg über Tirisfal herab mit dem direkten Ziel, die Unterstadt dem Erdboden gleichzumachen und die Verlassenen von der Landkarte zu tilgen. Eine gemeinsame Verteidigung durch die Verlassenen und die Argentumdämmerung schlug die Zitadelle zurück, obwohl beide Fraktionen schwere Verluste erlitten.",al={"warum griff naxxramas an","naxxramas angriff auf unterstadt","was hat naxxramas hier getan"}},{q="Warum sammeln Kultisten der Geißel die Kristallfragmente?",a="Kultisten der Geißel durchkämmen Tirisfal, um die zersplitterten Fragmente zu bergen. Selbst zerbrochen und verbraucht enthalten die Kristalle noch verbliebene nekrotische Magie, welche die Geißel bergen oder für ihre unheiligen Rituale wiederverwenden könnte.",al={"warum wollen kultisten die kristalle","was wollen kultisten mit den scherben","geißelkultisten kristalle"}},{q="Ist der Umgang mit den nekrotischen Kristallen gefährlich?",a="Ja. Obwohl sie zerbrochen und ihrer primären Ladung weitgehend beraubt sind, bergen die Fragmente immer noch mächtige und flüchtige nekrotische Energie, was direkten körperlichen Kontakt gefährlich macht.",al={"sind die kristalle gefährlich zu berühren","körperlicher kontakt kristall","können nekrotische kristalle schaden"}},{q="Wer half den Verlassenen, Naxxramas abzuwehren?",a="In der Schlacht zur Verteidigung der Unterstadt kämpften die Verlassenen Seite an Seite mit der Argentumdämmerung gegen die Streitkräfte von Naxxramas und erlitten schwere Verluste, um das Überleben der Verlassenen zu sichern.",al={"wer kämpfte bei naxxramas","wer verteidigte die unterstadt","argentumdämmerung verteidigung der unterstadt"}},{q="Werden jemals alle nekrotischen Kristalle aus Tirisfal beseitigt werden?",a="Es ist unwahrscheinlich, dass das Gebiet schnell geräumt wird. Da der gewaltige Kristall hoch über den Lichtungen zersplitterte, verteilten sich die Fragmente überall, was bedeutet, dass Bewohner wahrscheinlich noch jahrelang Scherben aus der Erde ziehen werden.",al={"wird tirisfal frei von kristallen sein","können alle fragmente beseitigt werden","verbliebene kristalle in tirisfal"}}},fp="15,339,24.390.0,20.338.0,40.233.0,39.249.0,58.217.0,44.176.0,44.194.0,61.228.0"}
P.entries["quest:96899"] = {n="Die Bandarionfestung",s="Die Bandarionfestung ist eine Quest in Tirisfal, die Abenteurer dazu anleitet, Kommandant Leonid Barthalomew von der Argentumdämmerung an einer abgelegenen Festung aufzusuchen. Einst ein Stützpunkt der Argentumdämmerung gegen die Geißel, wird die Festung nun von Danitha und ihrem Paladinorden instand gehalten.",h="Die Bandarionfestung ist eine Quest in Tirisfal, die Abenteurer dazu anleitet, Kommandant Leonid Barthalomew...",kw={"argentumdämmerung","die bandarionfestung","kult der verdammten","danitha","leonid barthalomew","paladin","geißel","tirisfal"},ang={["class:Paladin"]="Die Bandarionfestung dient als von Danitha und ihren Mitpaladinen verwaltete Festung, die ein heiliges Bollwerk gegen dunkle Mächte in Tirisfal aufrechterhält."},sec={{t="Eine Vorladung zur Festung",b="Die Bandarionfestung ist eine Quest der Argentumdämmerung, die Abenteurer durch Tirisfal führt, um Kommandant Leonid Barthalomew zu treffen. Nachdem sie der Dämmerung gegen Aktivitäten des Kults der Verdammten beigestanden haben, werden Reisende nach Nordwesten zur Festung gewiesen, um sich mit dem Kommandanten zu treffen und mehr über den andauernden Kreuzzug des Ordens gegen die Finsternis zu erfahren."},{t="Geschichte und Verwaltung",b="Die Festung diente der Argentumdämmerung einst als entscheidender Stützpunkt im Kampf gegen Übergriffe der Geißel in ganz Tirisfal. Als die Dämmerung ihren Schwerpunkt auf die Östlichen und Westlichen Pestländer verlagerte, wurde das Fort zurückgelassen und drohte zu verfallen, bis die Paladin Danitha und ihre Gefährten die Verwaltung seiner Mauern übernahmen."},{t="Erinnerungen an einen gemeinsamen Freund",b="Nach der Wiedervereinigung mit Leonid Barthalomew an der Festung erinnert sich der Kommandant an die Schlachten zurück, die von ihren Zinnen aus geschlagen wurden. Zwar ist er erleichtert, dass die Festung nicht der Verwahrlosung anheimgefallen ist, doch bemerkt er, dass Danitha ihren Namen zu Ehren eines gemeinsamen Freundes verliehen hat."}},faq={{q="Wer ist Leonid Barthalomew?",a="Leonid Barthalomew ist ein Kommandant der Argentumdämmerung. Er nutzte die Bandarionfestung zuvor bei früheren Übergriffen der Geißel nach Tirisfal als Basis und ist dorthin zurückgekehrt, um sich mit Danitha und ihren Paladinen zu treffen.",al={"wer ist leonid barthalomew","wo ist leonid barthalomew","leonid die bandarionfestung"}},{q="Was ist die Bandarionfestung?",a="Die Bandarionfestung ist eine Festung im westlichen Tirisfal. Ursprünglich ein Außenposten der Argentumdämmerung während der Angriffe der Geißel, verfiel sie, als sich der Orden in die Pestländer zurückzog, bevor sie von Danithas Paladinen wiederhergestellt und gehalten wurde.",al={"was ist die bandarionfestung","geschichte der bandarionfestung","wer hält die bandarionfestung"}},{q="Wer ist Danitha?",a="Danitha ist eine Paladin, die gemeinsam mit ihrem Orden die Verwaltung der Bandarionfestung übernahm, nachdem sich die Argentumdämmerung nach Osten in die Pestländer zurückgezogen hatte. Sie benannte die Festung zudem zu Ehren eines gemeinsamen Freundes, den sie mit Leonid Barthalomew teilte.",al={"wer ist danitha","danitha paladin","wer leitet die bandarionfestung"}},{q="Warum heißt sie die Bandarionfestung?",a="Die Festung wurde von Danitha zu Ehren eines gemeinsamen Freundes benannt, der sowohl ihr als auch Kommandant Leonid Barthalomew bekannt war.",al={"warum wurde sie die bandarionfestung genannt","wer ist bandarion","bedeutung des namens bandarion"}},{q="Warum ist die Argentumdämmerung an der Bandarionfestung interessiert?",a="Mitglieder der Argentumdämmerung reisen zur Bandarionfestung, um sich mit Danithas Paladinen abzustimmen und die Wachsamkeit gegenüber den Streitkräften der Geißel sowie den Umtrieben des Kults der Verdammten in ganz Tirisfal aufrechtzuerhalten.",al={"warum zur bandarionfestung gehen","argentumdämmerung tirisfal","die bandarionfestung argentumdämmerung"}},{q="Warum verließ die Argentumdämmerung die Festung zuvor?",a="Die Argentumdämmerung zog sich aus der Festung zurück, als sie ihre Hauptstreitkräfte nach Osten verlegte, um die Geißel in den Pestländern zu bekämpfen, wodurch das Bauwerk leer stand, bis Danitha und ihre Paladine einsprangen, um es instand zu halten.",al={"was geschah nach dem krieg mit der festung","warum verließ die argentumdämmerung die bandarionfestung"}}},fp="14,264,21.335.0,23.351.0,27.268.1,26.218.0,23.246.0,15.226.0,32.113.0,52.192.0,52.215.0"}
P.entries["quest:96988"] = {n="Source of Power",s="Source of Power ist eine Quest aus Unterstadt, die von Doktor Martin Felben in Auftrag gegeben wird, der versucht, die Unruhen in Dalaran für sich zu nutzen. Während die magische Stadt von ihren eigenen abtrünnigen Konstrukten belagert wird, beauftragt Felben Abenteurer damit, deren Arkankerne zu beschaffen. Sein Ziel ist es, Dalarans magische Technologie mit der Fleischformung der Verlassenen zu verbinden, um mit Arkanenergie erfüllte Abscheulichkeiten zu erschaffen und die Aufmerksamkeit der Dunklen Fürstin auf sich zu ziehen.",h="Source of Power ist eine Quest aus Unterstadt, die von Doktor Martin Felben in Auftrag gegeben wird, der...",kw={"abscheulichkeiten","arkankonstrukte","gesprungener sentry-kern","dalaran","doktor martin felben","königliche apothekervereinigung","source of power","sylvanas windläufer","unterstadt"},ang={["class:Mage"]="Magier werden eine düstere Ironie darin erkennen, dass sich Dalarans magische Konstrukte gegen ihre Meister wenden, nur damit ihre hochentwickelten Arkanenergiequellen für grausame alchemistische Experimente in Unterstadt geplündert werden.",["faction:Horde"]="Hordeabenteurer, die in Lordaeron operieren, unterstützen die Bemühungen der Verlassenen, fortschrittliche militärische Mittel gegen ihre umliegenden Rivalen zu sichern, während Dalaran durch seine eigenen abtrünnigen Schöpfungen gelähmt ist.",["profession:Engineering"]="Ingenieure können die kunstvolle Handwerkskunst hinter Dalarans autonomen Wächtern würdigen, selbst wenn deren empfindliche Arkankerne herausgerissen werden, um grauenhafte Fleischformungs-Abscheulichkeiten anzutreiben.",["race:Undead"]="Die Verlassenen verlassen sich stark auf die rücksichtslosen Innovationen der Königlichen Apothekervereinigung, um ihr Überleben in Lordaeron zu sichern. Doktor Felben beizustehen, bringt die Forschungen der Fraktion zur arkanen Fleischformung unter den wachsamen Augen der Dunklen Fürstin voran."},sec={{t="Eine günstige Gelegenheit zur Ernte",b="Das Chaos in der magischen Stadt Dalaran hat eine Gelegenheit geschaffen, die die Verlassenen nur allzu gerne nutzen wollen. Da Dalarans eigene Arkankonstrukte außer Kontrolle geraten sind und die Magier belagern, sieht Doktor Martin Felben inmitten der Unruhen eine goldene Gelegenheit. Anstatt den belagerten Zauberern Hilfe anzubieten, versucht der Apotheker, die Arkankerne zu bergen, die diese abtrünnigen Wächter antreiben. Dalaran hütet seine magischen Forschungen seit langem streng, doch seine derzeitige Verwundbarkeit macht seine verzauberten Schildwachen zu einer leichten Beute für opportunistische Forscher aus Unterstadt."},{t="Ehrgeiz in der Apothekervereinigung",b="Doktor Felbens Interesse an den gesprungenen Wächterkernen entspringt ganz seinem persönlichen Ehrgeiz innerhalb der Königlichen Apothekervereinigung. Indem er Abscheulichkeiten der Verlassenen mit der unbeständigen Konstruktmagie aus Dalaran erfüllt, träumt Felben davon, eine verheerende Armee von arkanbetriebenen Fleischbestien zu erschaffen. Ein solch grauenhafter Durchbruch, so kalkuliert er, würde die ungeteilte Aufmerksamkeit von Fürstin Sylvanas Windläufer erregen und sein unübertroffenes alchemistisches Genie unter Beweis stellen. Letztlich hofft Felben, dass diese Schöpfung sein Ansehen dramatisch steigern und ihm vielleicht sogar die Führung der Königlichen Apothekervereinigung selbst einbringen könnte – einer Fraktion, in der rücksichtslose Schläue und wirkungsvolle Ergebnisse über Überleben und Rang entscheiden."}},faq={{q="Wer vergibt die Quest Source of Power?",a="Die Quest wird von Doktor Martin Felben vergeben, einem Apotheker, der in Unterstadt, der Hauptstadt der Verlassenen, residiert. Felben ist ein ehrgeiziger Forscher, der versucht, der Königlichen Apothekervereinigung und Fürstin Sylvanas Windläufer seine alchemistischen Talente zu beweisen, indem er völlig neuartige militärische Monstrositäten entwickelt.",al={"wer vergibt source of power","source of power questgeber","martin felben quest"}},{q="Was geschieht während dieser Quest in Dalaran?",a="Dalaran wird derzeit von seinen eigenen Arkankonstrukten belagert, die sich gegen ihre Schöpfer gewandt haben. Das daraus resultierende Chaos und die Kämpfe innerhalb der magischen Stadt bieten Außenstehenden eine seltene Gelegenheit, nach Dalaran einzudringen und die mächtigen magischen Komponenten zu bergen, die diese abtrünnigen Wächter antreiben.",al={"was geschah in dalaran","dalaran wird belagert","warum greifen konstrukte dalaran an"}},{q="Warum will Doktor Felben die Konstruktkerne haben?",a="Doktor Felben beabsichtigt, die Arkanenergie in den Wächterkernen aus Dalaran zu nutzen, um die Abscheulichkeiten der Verlassenen zu verstärken. Durch die Synthese von reiner Arkanmaschinerie mit Fleischformung hofft er, eine Armee arkanbetriebener Abscheulichkeiten zu erschaffen, die Fürstin Sylvanas Windläufer seine alchemistische Meisterschaft beweisen wird.",al={"warum sentry-kerne sammeln","wofür braucht felben kerne","felben sentry-kern plan"}},{q="Was sind die Ziele für Source of Power?",a="Abenteurer werden damit beauftragt, in die Stadt Dalaran zu reisen, um sich den abtrünnigen Konstrukten zu stellen und sechs gesprungene Wächterkerne zu sammeln. Sobald sie erbeutet wurden, müssen diese unbeständigen magischen Relikte zu Doktor Martin Felben nach Unterstadt gebracht werden, um seine laufenden Experimente voranzutreiben.",al={"source of power ziele","wie viele kerne brauche ich","was für source of power sammeln"}},{q="Was ist Doktor Felbens Ziel innerhalb der Königlichen Apothekervereinigung?",a="Doktor Martin Felben strebt nach Anerkennung und schnellem Aufstieg innerhalb der Hierarchie der Verlassenen. Indem er Fürstin Sylvanas Windläufer eine gewaltige Streitmacht aus arkanerfüllten Abscheulichkeiten präsentiert, hofft er, die Dunkle Fürstin so sehr zu beeindrucken, dass er zum Anführer der Königlichen Apothekervereinigung ernannt wird.",al={"felben apotheker ziel","wer führt die königliche apothekervereinigung an","felben anerkennung der dunklen fürstin"}},{q="Warum plündern die Verlassenen Dalarans Technologie?",a="Die Königliche Apothekervereinigung und die Verlassenen suchen ständig nach unkonventionellen Waffen und Energiequellen, um ihr Überleben in Lordaeron zu sichern. Das Ausnutzen der magischen Stadt Dalaran, während deren Verteidigung von innen heraus zusammenbricht, ermöglicht es den Apothekern der Verlassenen, hochentwickelte Arkankomponenten zu erbeuten, ohne die Magier förmlich in einen offenen Krieg verwickeln zu müssen.",al={"warum verlassene dalaran-magie wollen","unterstadt dalaran konstrukte","interesse der verlassenen an dalaran"}},{q="Wo sind die gesprungenen Wächterkerne zu finden?",a="Die gesprungenen Wächterkerne werden von den abtrünnigen Konstrukten erbeutet, die derzeit die Stadt Dalaran belagern. Spieler müssen diese feindseligen verzauberten Wächter in der gesamten magischen Stadt bekämpfen, um die notwendigen intakten Komponenten für Doktor Felbens Forschungen in Unterstadt zu gewinnen.",al={"wo man gesprungene sentry-kerne findet","fundort gesprungener sentry-kern","dalaran sentry-kern beute"}}},fp="15,407,24.594.0,34.676.0,36.287.0,47.296.0,48.294.0,44.276.0,65.281.0,53.344.0,41.282.0"}
P.entries["quest:97"] = {n="Die Legende von Stalvan",s="Dieser Abschnitt der Untersuchung bestätigt schließlich die finstere Wahrheit, die den schwer fassbaren Hauslehrer mit den Aufzeichnungen von Dunkelhain verbindet. Amtmann Daltry gleicht die auf den geborgenen Dokumenten gefundene Handschrift erfolgreich mit der von Stalvan Dunstmantel ab, was eine sofortige Meldung an Kommandantin Althea Schwarzhaupt veranlasst. Dies markiert den Moment, in dem die Verdächtigungen von The Night Watch zu einer unbestreitbaren Tatsache werden.",h="Dieser Abschnitt der Untersuchung bestätigt schließlich die finstere Wahrheit, die den schwer fassbaren...",kw={"althea schwarzhaupt","amtmann daltry","dunkelhain","dämmerwald","handschrift","dunstmantel","night watch","stalvan"},ang={["faction:Alliance"]="Für Ermittler der Allianz verdeutlicht das Entwirren von Stalvans Spur die entscheidende Zusammenarbeit, die zwischen der angeschlagenen Führung von Dunkelhain und wandernden Abenteurern erforderlich ist, um die südlichen Gebiete des Reiches zu sichern.",["race:Human"]="Menschliche Spieler sehen hier den tragischen Verfall ihrer eigenen Gesellschaft widergespiegelt, in der geachtete Hauslehrer und ländliche Ortschaften gleichermaßen unbemerkt aus der Zivilisation in den Wahnsinn und die Isolation abgleiten."},sec={{t="Ein Treffer in den Aufzeichnungen",b="Nachdem entlegene Gutshöfe, Gasthäuser und städtische Archive in den Königreichen der Menschen durchforstet wurden, kehrt die lückenhafte Spur zum Rathaus von Dunkelhain zurück. Amtmann Daltry vergleicht die Seite aus dem blutbefleckten Tagebuch mit den Unterschriften im Stadtregister. Das Ergebnis ist eindeutig: Die Handschrift gehört Stalvan Dunstmantel, was The Night Watch den stichhaltigen Beweis liefert, der nötig ist, um die Angelegenheit als dringende lokale Bedrohung zu behandeln."},{t="Die Verdächtigungen von The Night Watch",b="Kommandantin Althea Schwarzhaupt hegte von Beginn der Untersuchung an finstere Vorahnungen in Bezug auf Stalvan. Der Dämmerwald ächzt bereits unter der Last wilder Worgen, skelettartiger Untoter und lauernder Nekromanten; ein unauffindbarer Mörder, der sich in den Schatten der Wälder verbirgt, ist eine Gefahr, die sie nicht ignorieren kann. Die Bestätigung von Daltry zu erhalten, bestätigt ihre schlimmsten Befürchtungen und bringt The Night Watch auf Kurs, den Einsiedler ein für alle Mal aufzuspüren und zu neutralisieren."}},faq={{q="Was hat Amtmann Daltry herausgefunden?",a="Amtmann Daltry verglich die Seite aus dem blutbefleckten Tagebuch mit den Unterschriften im Stadtregister von Dunkelhain und bestätigte, dass die Handschrift genau mit Stalvan Dunstmantel übereinstimmte, genau wie Kommandantin Schwarzhaupt vermutet hatte.",al={"was hat daltry gefunden","daltry handschrift treffer","stalvan handschrift beweis"}},{q="Warum liegt Kommandantin Althea Schwarzhaupt so viel an Stalvan?",a="Kommandantin Althea Schwarzhaupt führt The Night Watch an, die bedrängte Miliz von Dunkelhain. In einem Land, das bereits von Schrecken heimgesucht wird, kann sie es nicht zulassen, dass eine gewalttätige, schattenhafte Gestalt mit finsterer Vergangenheit frei und unauffindbar innerhalb der Grenzen des Dämmerwalds verbleibt.",al={"warum kümmert sich althea","schwarzhaupt untersuchung","night watch stalvan"}},{q="Wo findet dieser Schritt statt?",a="Dieser gesamte Schritt findet innerhalb der Stadt Dunkelhain statt. Amtmann Daltry ist im Rathaus stationiert, während Kommandantin Althea Schwarzhaupt in der Nähe entlang der Hauptstraßen der Stadt auf Patrouille anzutreffen ist.",al={"wo ist diese quest","quest standort","dunkelhain stalvan abgabe"}},{q="Was geschieht, nachdem die Handschriftenübereinstimmung gemeldet wurde?",a="Sobald Kommandantin Schwarzhaupt die Bestätigung von Amtmann Daltry erhält, wendet sich die Untersuchung der aktiven Suche nach Stalvans derzeitigem Aufenthaltsort in der unheimlichen Wildnis des Dämmerwalds zu.",al={"wie geht es weiter stalvan","nach daltry handschrift","nächster schritt stalvan reihe"}},{q="Wer war Stalvan Dunstmantel ursprünglich?",a="Stalvan Dunstmantel unterrichtete einst an der Schule in Mondbruch und arbeitete später als privater Hauslehrer für die Kinder der Familie Flintridge. Die Spur seiner Briefe und Tagebuchseiten führt von Mondbruch und Goldhain zurück in den Dämmerwald, wo er nun als gefährlicher Einsiedler in den Wäldern lebt.",al={"wer ist stalvan","stalvan hintergrund","stalvan dunstmantel geschichte"}},{q="Warum war ein Schriftvergleich notwendig?",a="Da die Ereignisse und Anschuldigungen rund um Stalvan in verschiedenen Regionen stattfanden – einschließlich Mondbruch und Goldhain –, waren die offiziellen Aufzeichnungen lückenhaft und verstreut. Das Bürgerregister von Dunkelhain enthielt verifizierte lokale Proben, mit denen die auswärtigen Hinweise definitiv dem bestimmten Mann zugeordnet werden konnten.",al={"warum handschrift vergleichen","warum hat daltry schrift geprüft","stalvans identität beweisen"}}},fx={cc1b58e5={q="Warum ist Amtmann Daltry so sehr darauf bedacht, dass Ihr Kommandant Schwarzhaupt Bericht erstattet?",a="Amtmann Daltry ist ein Stadtarchivar, kein Offizier der The Night Watch, und die Bestätigung, dass die Handschrift von Stalvan Dunstmantel stammt, validiert Kommandant Schwarzhaupts schwerwiegende Verdachtsmomente. Daltry erkennt, dass eine offizielle Morduntersuchung sofortige bewaffnete Autorität erfordert, weshalb es dringend ist, dass Althea unverzüglich einen definitiven Beweis erhält.",al={"warum will daltry das","daltrys beweggrund","warum althea berichten"}}},fp="21,363,22.413.0,28.456.1,31.220.0,63.241.0,32.202.0,51.186.0,38.289.0,39.282.0"}
P.entries["quest:970"] = {n="Der Turm von Althalaxx",s="Diese Quest markiert einen entscheidenden Wendepunkt in den Ermittlungen bezüglich des finsteren Cult of the Dark Strand und verlagert die Verfolgung vom zerstörten Turm von Althalaxx an der Dunkelküste über die Grenze zu Maestras Posten im Eschental. Delgren der Läuterer entsendet Abenteurer in nahegelegene Kultistenlager, um einen mächtigen Leuchtenden Seelenedelstein zu beschaffen. Das Freischalten dieses Artefakts enthüllt die düstere Zauberei, die den Einfluss des Kults auf die nördlichen Wälder nährt.",h="Diese Quest markiert einen entscheidenden Wendepunkt in den Ermittlungen bezüglich des finsteren Cult of the...",kw={"althalaxx","eschental","dark strand","dunkelküste","delgren","delgren der läuterer","leuchtender seelenedelstein","maestras posten","ordil'aran"},ang={["class:Paladin"]="Das Läutern dunkler Seelengefäße und das Richten verdorbener Kultisten mit dem Schwert deckt sich eng mit der Pflicht des Paladins, unheilige Verderbnis aus der Welt zu tilgen.",["class:Priest"]="Das Untersuchen eines dunklen Seelengefäßes spiegelt die Berufung des Priesters wider, sich der Verderbnis entgegenzustellen und gequälten Seelen Trost zu spenden.",["faction:Alliance"]="Die Koordination zwischen Vorposten an der Dunkelküste und im Eschental sichert die nördliche Grenze gegen finstere Praktizierende, die Reisende der Allianz bedrohen.",["race:NightElf"]="Zu sehen, wie abscheuliche Kultisten uralte Ruinen wie Ordil'Aran schänden und die nördlichen Wälder verderben, macht die Auslöschung des Cult of the Dark Strand zu einer dringenden Priorität für jeden Nachtelfen."},sec={{t="Eine Bitte über die Grenze",b="Nachdem die unheilvollen Aktivitäten rund um den Turm von Althalaxx an der nördlichen Dunkelküste aufgedeckt wurden, führten Berichte direkt nach Süden ins Eschental zu Delgren dem Läuterer. Stationiert an Maestras Posten, kämpft Delgren schon lange gegen den Cult of the Dark Strand, der in die uralten Elfenwälder vordringt. In der Erkenntnis, dass sich die Bedrohung durch den Kult über beide Gebiete erstreckt, beschließt Delgren, das Herz ihrer abscheulichen Zauberei anzugreifen."},{t="Die Geheimnisse von Ordil'Aran",b="Nordöstlich von Maestras Posten liegen die Ruinen von Ordil'Aran, die nun von fanatischen Dark Strand-Kultisten überrannt sind. Delgren erkennt, dass ihre Agenten leuchtende Seelenedelsteine bei sich tragen – dunkle Gefäße, die mit unheimlicher Magie verzaubert sind und die Macht des Kults aufrechterhalten. Indem er die Kultisten in den Ruinen zur Strecke bringt und einen dieser Edelsteine an sich bringt, beabsichtigt Delgren, ihre Verzauberung zu brechen und den wahren Ursprung hinter ihrem bösartigen Ritus zu enthüllen."},{t="Ein gefangener Geist",b="Beim Entziffern der üblen Verzauberungen, die an den leuchtenden Seelenedelstein gebunden sind, fördert Delgren nicht bloß dunkle Beschwörungen zutage; er enträtselt ein Gefäß der Qual. Das Brechen der Schutzbannungen des Edelsteins befreit den Geist von Sargath, einen der Elfen von Ameth'Aran, den Athrikus Narassin während der Sundering in Seelenedelsteinen gefangen setzte und seitdem langsam aussaugt. Die Erscheinung nennt Athrikus' Leutnant, Ilkrud Magthrull, dessen Foliant enthüllen könnte, wo die übrigen Seelenedelsteine aufbewahrt werden."}},faq={{q="Wo finde ich den Leuchtenden Seelenedelstein?",a="Der Leuchtende Seelenedelstein befindet sich im Besitz von Mitgliedern des Cult of the Dark Strand, die sich nordöstlich von Maestras Posten bei den Ruinen von Ordil'Aran im Eschental aufhalten. Verschiedene Kultisten, die in den Ruinen lauern, tragen ihn bei sich, auch wenn es etwas Ausdauer erfordern kann, einen zu erbeuten.",al={"fundort des seelenedelsteins","wo droppt der seelenedelstein","dark strand seelenedelstein"}},{q="Wer ist Delgren der Läuterer?",a="Delgren der Läuterer ist ein Champion der Allianz, der an Maestras Posten im nördlichen Eschental stationiert ist. Er bekämpft aktiv die finsteren Mächte, die in den Wald eindringen, mit einem besonderen Schwerpunkt auf der Jagd und Vernichtung des Cult of the Dark Strand.",al={"delgren","wer ist delgren"}},{q="Was ist der Cult of the Dark Strand?",a="Der Cult of the Dark Strand ist eine bösartige Sekte, die vom Turm von Althalaxx an der Dunkelküste und uralten Elfenruinen wie Ordil'Aran im Eschental aus operiert. Sie praktizieren dunkle Zauberei, Seelenbindung und nekromantische Rituale.",al={"dark strand kult","wer sind die dark strand"}},{q="Warum schickt mich eine Quest von der Dunkelküste ins Eschental?",a="Während die Untersuchung am Turm von Althalaxx an der Dunkelküste beginnt, erstreckt sich das Netzwerk des Kults nach Süden über die Grenze ins Eschental. Delgren der Läuterer an Maestras Posten verfügt über das nötige Fachwissen, um der seelenbindenden Magie des Kults entgegenzuwirken.",al={"warum maestras posten","warum ins eschental"}},{q="Was geschieht, wenn der Seelenedelstein entziffert wird?",a="Delgren beabsichtigt, die dunkle Verzauberung auf dem Leuchtenden Seelenedelstein zu entziffern. Was er entdeckt, wird offenbart, nachdem Ihr ihm den Edelstein gebracht habt.",al={"was ist im seelenedelstein","seelenedelstein geist"}},{q="Wo befindet sich Ordil'Aran?",a="Ordil'Aran ist eine uralte Elfenruine, die knapp nordöstlich von Maestras Posten im nördlichen Eschental liegt und derzeit vom Cult of the Dark Strand heimgesucht wird.",al={"lage von ordil'aran","wo liegt ordilaran"}}},fx={a63b3648={q="Warum will Delgren der Läuterer, dass dies erledigt wird?",a="Delgren ist in einen Kampf gegen den Kult von Dark Strand verwickelt, der sich nordöstlich von Maestras Post verschanzt hat. Für ihn sind sie ein gefährlicher Dorn, der vollständig herausgerissen werden muss. Die direkten Warnungen im Brief von Balthule Schattenhieb bestätigen, dass ihr korrupter Einfluss eskaliert, und Delgren glaubt, dass das Entschlüsseln der Geheimnisse, die im verzauberten Seelenedelstein gefangen sind, der einzige Weg ist, ihre Macht aufzudecken und zu zerschlagen.",al={"delgrens beweggrund","warum will delgren den seelenedelstein","warum kult von dark strand bekämpfen"}},c112c454={q="Wozu dient der Leuchtende Seelenedelstein?",a="Der Leuchtende Seelenedelstein ist ein dunkles, verzaubertes Artefakt, das vom Kult von Dark Strand in Die Ruinen von Ordil'Aran getragen wird. Delgren glaubt, dass er das Geheimnis der abscheulichen Magie des Kults und der Macht, die sie ausüben, birgt. Indem Ihr den Edelstein zu ihm bringt, ermöglicht Ihr Delgren, die dunklen Verzauberungen zu entziffern, die in den Stein gewebt sind, und die Essenz oder Entität aufzudecken, die darin gefangen ist.",al={"was ist der leuchtende seelenedelstein","zweck des leuchtenden seelenedelsteins","seelenedelstein dark strand"}},d0742ede={q="Gegen wen werdet Ihr in Die Ruinen von Ordil'Aran ausgesandt?",a="Ihr werdet ausgesandt, um den Kult von Dark Strand zu konfrontieren, der die Ruinen von Ordil'Aran nordöstlich von Maestras Post besetzt hält. Kultisten, Fanatiker, Akolythen und geübte Zauberwirker haben sich inmitten der elfischen Ruinen versammelt, um verbotene Riten durchzuführen. Eines ihrer Mitglieder trägt einen verzauberten Seelenedelstein, den Delgren benötigt, um die Geheimnisse des Kults freizuschalten, was erfordert, dass Ihr Euch durch ihre Reihen schneidet, bis das Relikt geborgen ist.",al={"wer ist in ordil'aran","dark strand in ordil'aran","wer hält den seelenedelstein"}}},fp="22,428,24.417.0,25.426.0,16.471.1,37.251.0,28.239.0,36.222.0,49.245.0,45.132.1,28.151.0"}
P.entries["quest:97003"] = {n="Chol'aruk the Ravener",s="Chol'aruk the Ravener ist eine Jagd im Brachland, die auf einen kolossalen Quilboar abzielt, der Gerüchten zufolge in einer Höhle am Dornenhügel haust. Nachdem er den düsteren Erzählungen nach vergangenen Begegnungen mit ähnlichen Bestien Glauben schenkt, beauftragt der Orc Gur'ak Abenteurer damit, sich in dessen Bau zu wagen und seinen Kopf zurückzubringen.",h="Chol'aruk the Ravener ist eine Jagd im Brachland, die auf einen kolossalen Quilboar abzielt, der Gerüchten...",kw={"brachland","chol'aruk","cholaruk","gur'ak","gurak","quilboar","razormane","the ravener","dornenhügel"},ang={["class:Hunter"]="Das Aufspüren einer monströsen Bestie, die Gerüchten zufolge fünfmal größer als gewöhnliche Quilboar ist, erfordert die scharfen Instinkte eines Jägers und die Vorbereitung auf eine gewaltige Beute.",["class:Warrior"]="Einer brutalen Kreatur entgegenzutreten, die für ihren unstillbaren Blutdurst bekannt ist, verlangt nach Kriegern an vorderster Front, die bereit sind, sich überwältigender physischer Wut zu stellen.",["faction:Horde"]="Der Orc Gur'ak spricht diesen Ruf zu den Waffen unter dem traditionellen Schlachtruf der Horde „Blut und Donner“ aus und beauftragt Abenteurer damit, eine gefährliche Bedrohung niederzustrecken, die im Brachland lauert."},sec={{t="Die Legende des Raveners",b="In den dürren Weiten des Brachlands erzählen sich die Razormane-Quilboar Gerüchte über Chol'aruk, einen gewaltigen Schrecken, der „The Ravener“ genannt wird. Regionalen Gerüchten zufolge hat dieser albtraumhafte Koloss seinen Unterschlupf tief in einer Höhle am Dornenhügel nordöstlich der örtlichen Pfade. Die Quilboar behaupten, er sei etwa fünfmal so groß wie ein gewöhnlicher Quilboar und werde von einem gewalttätigen, unstillbaren Blutdurst getrieben. Während viele solche Erzählungen als übertriebene Lagerfeuergeschichten abtun, weiß Gur'ak es aus vergangenen Kämpfen mit ähnlichen Monstrositäten besser."},{t="Gur'aks Warnung",b="Da Gur'ak die tatsächliche Gefahr erkennt, die von einer Bestie dieses Ausmaßes ausgeht, weist er fähige Reisende an, die Kreatur zu ihrem unterirdischen Bau im Dornenhügel aufzuspüren. Seine Anweisungen sind unmissverständlich: Setzt dem monströsen Koloss ein Ende und kehrt mit seinem Kopf als unbestreitbarem Beweis zurück. Angesichts Chol'aruks gemunkelter Wildheit und kolossaler Größe spricht Gur'ak eine ernste Warnung aus, dass nur gut vorbereitete Gruppen es wagen sollten, die Höhle zu betreten, um Chol'aruk the Ravener entgegenzutreten."}},faq={{q="Wer ist Chol'aruk the Ravener?",a="Chol'aruk, vom Stamm der Razormane auch The Ravener genannt, ist ein legendärer und monströser Quilboar. Gerüchten zufolge ist er fünfmal so groß wie gewöhnliche Quilboar, besitzt einen unstillbaren Blutdurst und haust in einer tiefen Höhle im Brachland.",al={"wer ist cholaruk","was ist cholaruk","the ravener"}},{q="Wo ist Chol'aruk zu finden?",a="Chol'aruk haust tief in einer Höhle am Dornenhügel, nordöstlich von Gur'aks Lager im Brachland gelegen. Abenteurer müssen sich in die Höhlen des Dornenhügels wagen, um seinen Bau zu finden.",al={"wo ist cholaruk","cholaruk aufenthaltsort","wo ist die höhle am dornenhügel"}},{q="Wer bietet die Jagd auf Chol'aruk an?",a="Gur'ak, ein im Brachland stationierter Orc, bietet die Aufgabe an. Anders als andere, die Geschichten über die riesige Bestie als bloßes Tavernengeplauder abtun, glaubt Gur'ak den Gerüchten, da er bereits früher ähnlichen Monstrositäten gegenüberstand.",al={"wer vergibt cholaruk quest","wer ist gurak","gurak brachland"}},{q="Warum jagt Gur'ak Chol'aruk?",a="Gur'ak will, dass Chol'aruk vernichtet wird, um eine grausame Bedrohung zu beseitigen, die die Region terrorisiert, und verlangt den abgetrennten Kopf der Bestie als Beweis dafür, dass der Ravener gefallen ist.",al={"warum cholaruk töten","cholaruk kopfgeld grund"}},{q="Sollte ich Chol'aruk alleine bekämpfen?",a="Gur'ak warnt Reisende ausdrücklich davor, Chol'aruk alleine aufzusuchen. Angesichts seiner berichteten enormen Größe und wilden Blutgier ist das Bezwingen des Raveners als gewaltige Herausforderung gedacht, die eine vorbereitete Jagdgruppe erfordert.",al={"kann ich cholaruk alleine besiegen","ist cholaruk schwer","gruppe für cholaruk mitbringen"}},{q="Welche Verbindung besteht zwischen Chol'aruk und den Razormane-Quilboar?",a="Quilboar sind eberartige Humanoide, die in den Ebenen des zentralen Kalimdor heimisch sind, wobei der Stamm der Razormane Teile des Brachlands bewohnt. Die Razormane selbst sprechen voller Furcht von Chol'aruk und verleihen der Bestie den Titel „The Ravener“.",al={"was sind quilboar","razormane cholaruk","warum die razormane ihn fürchten"}}},fp="21,271,25.527.0,16.438.0,29.242.0,29.177.0,34.209.0,32.159.0,31.222.0,68.230.0"}
P.entries["quest:97005"] = {n="Chol'aruk der Verschlinger",s="Chol'aruk der Verschlinger ist eine gefürchtete monströse Abscheulichkeit, die in einer Höhle auf dem Dornenhügel im Brachland lauert. Die einheimischen Borstennacken nennen ihn Chol'aruk oder 'Der Verschlinger', und Gerüchte besagen, dass die Kreatur groß genug ist, um einen Ork im Ganzen zu verschlingen. Bainham verlangt seinen abgetrennten Kopf, um gefallene Kameraden zu rächen, die an ähnliche Schrecken verloren gingen.",h="Chol'aruk der Verschlinger ist eine gefürchtete monströse Abscheulichkeit, die in einer Höhle auf dem...",kw={"abscheulichkeit","bainham","brachland","chol'aruk","borstennacken","der verschlinger","dornenhügel"},ang={["class:Hunter"]="Sich einem legendären Spitzenprädator zu stellen, von dem gemunkelt wird, dass er voll gerüstete Krieger im Ganzen verschlingt, ist die ultimative Prüfung für das Können und die Nerven eines Fährtenlesers.",["class:Warrior"]="Bainhams Bitte appelliert direkt an den Ehrenkodex eines Kriegers: gefallene Kameraden zu rächen, indem man einem gewaltigen Schrecken in seinem unterirdischen Unterschlupf von Angesicht zu Angesicht entgegentritt.",["faction:Horde"]="Ungeheuer, die unkontrolliert über die Hochplateaus streifen, bedrohen Reisende und Karawanen, die sich ihren Weg durch das Brachland bahnen; die Vernichtung der Bestie ist somit eine Frage der regionalen Sicherheit."},sec={{t="Der Schrecken des Dornenhügels",b="Nordwestlich von der Stelle im Brachland, an der Bainham wartet, liegt das als Dornenhügel bekannte Plateau, das seit langem von den einheimischen Borstennackenstämmen umkämpft wird. Vor Kurzem sprachen Gerüchte von einer furchterregenden Präsenz, die sich in einer seiner Höhlen verschanzt hat: eine monströse Abscheulichkeit, die von den Borstennacken Chol'aruk oder 'Der Verschlinger' genannt wird. Obwohl viele Reisende Berichte über eine Bestie, die einen gerüsteten Ork mit einem einzigen Haps verschlingen kann, als Lagerfeuergeschichten abtun, wissen jene, die das Blutbad mit eigenen Augen gesehen haben, dass die Bedrohung allzu real ist."},{t="Vergoltene Rache",b="Für Bainham ist die Existenz von Chol'aruk alles andere als ein Mythos. Da er in der Vergangenheit bereits mit ähnlichen Schrecken aneinandergeraten ist, trägt er persönliche Narben davon und trauert um Kameraden, die solchen Bestien zum Opfer fielen. Wohl wissend, welche Gefahr eine unersättliche Abscheulichkeit für jeden darstellt, der die Savanne durchstreift, beauftragt er erfahrene Recken damit, das Plateau zu erklimmen, in den unterirdischen Unterschlupf einzudringen und Chol'aruk zu erschlagen, um seinen gewaltigen Kopf einzufordern."}},faq={{q="Was für eine Kreatur ist Chol'aruk?",a="Chol'aruk wird als eine monströse Abscheulichkeit beschrieben, die in einer Höhle auf dem Dornenhügel lauert. Berichten zufolge ist er so riesig, dass er einen ausgewachsenen Ork im Ganzen verschlingen kann, was ihm bei den einheimischen Borstennacken den furchterregenden Titel 'Der Verschlinger' einbrachte.",al={"was ist cholaruk","cholaruk monstertyp","wer ist der verschlinger"}},{q="Wo befindet sich Chol'aruks Unterschlupf?",a="Chol'aruk haust in einer Höhle auf dem Hochplateau des Dornenhügels, der im Nordwesten des Brachlands liegt.",al={"wo ist cholaruk","cholaruk standort","dornenhügel höhle"}},{q="Wer ist Bainham und warum will er Chol'aruk tot sehen?",a="Bainham, der sich im Brachland aufhält, hat eine persönliche Vorgeschichte im Kampf gegen solche Bestien. Da er in der Vergangenheit Verbündete an ähnliche Abscheulichkeiten verloren hat, trachtet er aus Ehre und Vergeltung für seine gefallenen Kameraden nach Chol'aruks Tod.",al={"wer gibt cholaruk quest","warum cholaruk töten","bainham lore"}},{q="Was bedeutet 'Der Verschlinger'?",a="Die einheimischen Borstennacken-Stacheleber gaben Chol'aruk diesen Namen, um seine unersättliche, gefräßige Natur zu beschreiben, da Gerüchten zufolge ausgewachsene Krieger ohne Zögern im Ganzen von ihm verschlungen werden.",al={"bedeutung von cholaruk","warum verschlinger genannt","borstennacken cholaruk"}},{q="Verehren oder fürchten die Borstennacken-Stacheleber Chol'aruk?",a="Das ist noch nicht bekannt. Die Borstennacken nennen die Kreatur Chol'aruk oder 'Der Verschlinger', aber die Quest verrät nicht, ob sie die monströse Abscheulichkeit, die in einer Höhle auf dem Dornenhügel haust, fürchten oder verehren.",al={"mögen stacheleber cholaruk","borstennacken und cholaruk"}},{q="Welcher Beweis ist erforderlich, um Chol'aruks Tod zu bestätigen?",a="Bainham verlangt, dass Ihr mit dem abgetrennten Kopf von Chol'aruk als unbestreitbarem Beweis dafür zurückkehrt, dass die Abscheulichkeit vernichtet wurde.",al={"cholaruk quest abgabe","was bringt man bainham"}}},fp="21,309,20.512.0,15.379.0,35.232.0,34.114.0,51.209.0,29.172.0,52.195.0,52.125.0"}
P.entries["quest:971"] = {n="Wissen in der Tiefe",s="„Wissen in der Tiefe“ ist eine Quest der Allianz, die von Gerrig Knochengriff in Eisenschmiedes Forlorn Cavern angeboten wird. Er beauftragt Abenteurer damit, über das Meer zu den versunkenen Ruinen der Tiefschwarzen Grotte im Eschental zu reisen, um das uralte Manuskript von Lorgalis zu bergen. Hinter Knochengriffs Fassade als Gelehrter verbirgt sich finstere Absichten, die mit dunklen Wesenheiten und apokalyptischen Prophezeiungen verknüpft sind.",h="„Wissen in der Tiefe“ ist eine Quest der Allianz, die von Gerrig Knochengriff in Eisenschmiedes Forlorn...",kw={"eschental","tiefschwarze grotte","forlorn cavern","gerrig knochengriff","eisenschmiede","wissen in der tiefe","manuskript von lorgalis"},ang={["class:Warlock"]="Knochengriff agiert direkt an der Seite der Hexenmeister, die sich in Eisenschmiedes Forlorn Cavern verbergen, und teilt ihren Hunger nach verbotenen, ebenenbeugenden Texten.",["faction:Alliance"]="Während die Hilfe für einen Gelehrten der Allianz harmlos erscheint, deuten Knochengriffs wahre Motive und zwielichtige Verbündete auf finsterere Pläne hin, die innerhalb der Mauern von Eisenschmiede geschmiedet werden.",["race:NightElf"]="Das Manuskript liegt in der Tiefschwarzen Grotte, einem versunkenen Nachtelfenheiligtum, das nun von Kultisten und anderen Eindringlingen besetzt ist."},sec={{t="Ein Gelehrter in den Schatten",b="Verborgen in den feuchten Gefilden von Eisenschmiedes Forlorn Cavern präsentiert sich Gerrig Knochengriff als ergebener Sammler alter Texte. Doch seine gelehrten Bestrebungen tragen einen unverkennbar unheilvollen Unterton. Knochengriff interessiert sich nicht für alltägliche Geschichte oder städtische Chroniken; er jagt ausdrücklich nach vergessener Kunde, die imstande ist, Pforten zu öffnen und „Jene, die schlafen“ zu erwecken. Sein Gerede über das Überleben jenseits der „Endtage“ zeichnet ihn als Sonderling aus – oder als gefährlichen Anhänger schattenhafter, schlummernder Mächte."},{t="Die versunkene Ruine von Lorgalis",b="Knochengriff schickt Suchende quer durch Azeroth an die schattigen Gestade des Eschentals, wo das uralte Nachtelfenheiligtum der Tiefschwarzen Grotte versunken liegt. Bevor die Große Zerschlagung Kalimdor zerriss, trugen nachtelfische Gelehrte in ihren Küstentempeln immenses magisches Wissen zusammen. Inmitten der überfluteten Gänge, in denen es heute von Naga, Satyren und Kultisten des Schattenhammers wimmelt, ruht das Manuskript von Lorgalis – ein Text verbotenen Wissens, der in einer Pitted Iron Chest aufbewahrt wird."},{t="Brüder und Schwestern",b="Als ihm das durchnässte Manuskript überreicht wird, unternimmt Knochengriff keinerlei Anstalten, es in Eisenschmiedes Hall of Explorers zu archivieren. Stattdessen freut er sich offen darüber, dass Duplikate angefertigt und unter seinen mysteriösen „Brüdern und Schwestern“ verbreitet werden. Obwohl er dem Abenteurer der Allianz dankbar ist, der es geborgen hat, liegen Knochengriffs Loyalitäten eindeutig bei einer geheimen Sekte, die begierig darauf brennt, das wiedererlangte Wissen für esoterische, weltverändernde Riten zu nutzen. Knochengriff steht mit dem Schattenhammer in Verbindung, dessen Anhänger nach verbotenem Wissen über die Alten Götter suchen."}},faq={{q="Wer vergibt die Quest „Wissen in der Tiefe“?",a="Die Quest wird von Gerrig Knochengriff vergeben, einem zwergischen Wissenssucher, der in der dämmrigen Forlorn Cavern innerhalb der Zwergenbergstadt Eisenschmiede weilt.",al={"questgeber","wo man die quest bekommt","wer startet wissen in der tiefe"}},{q="Was ist das Manuskript von Lorgalis?",a="Das Manuskript von Lorgalis ist ein Text, den Gerrig Knochengriff aus der Tiefschwarzen Grotte geborgen haben möchte. Es wird in einer Pitted Iron Chest inmitten der überfluteten Ruinen aufbewahrt.",al={"was ist das manuskript von lorgalis","lorgalis lore","welches buch findet man"}},{q="Wo befindet sich das Manuskript von Lorgalis?",a="Das Manuskript ruht tief im Dungeon der Tiefschwarzen Grotte, gelegen am Zoramstrand an der Nordwestküste des Eschentals in Kalimdor.",al={"ort des manuskripts von lorgalis","wo ist das buch in bfd","fundort des bfd buchs"}},{q="Wer sind „Jene, die schlafen“, die von Gerrig Knochengriff erwähnt werden?",a="Knochengriff verwendet diesen kryptischen Namen für die schlummernden Mächte, die in der von ihm gesammelten verbotenen Kunde beschrieben werden. Die geschützten Abschnitte der Quest beleuchten seine dunkleren Verbindungen.",al={"jene die schlafen","von wem spricht bonegrip","was betet gerrig an"}},{q="Wer sind die „Brüder und Schwestern“, mit denen Gerrig das Manuskript teilen will?",a="Knochengriffs Verbündete teilen sein Interesse an verbotener Kunde. Das Bergen des Manuskripts kann mehr darüber enthüllen, wem er dient.",al={"gerrig brüder und schwestern","für wen arbeitet gerrig","bonegrip fraktion"}},{q="Warum führt eine Quest in Eisenschmiede die Spieler den ganzen Weg ins Eschental?",a="Eisenschmiedes Forlorn Cavern zieht nicht autorisierte Magiewirker, Hexenmeister und Schurken an, die nach Geheimnissen suchen, die vor dem Licht verborgen sind. Knochengriff sammelt altes, mächtiges Wissen, und von dem Manuskript von Lorgalis, das er begehrt, heißt es, dass es auf dem Grund der Tiefschwarzen Grotte im Eschental liege, der alten Wohnstätte längst verstorbener Elfen, die über großes Wissen verfügten.",al={"warum ins eschental reisen","quest von eisenschmiede nach bfd","reise nach blackfathom"}}},fx={["32faf93b"]={q="Warum will Gerrig Knochengriff das Manuskript von Lorgalis?",a="Gerrig Knochengriff sammelt uralte, mächtige Texte, die in der Lage sind, vergessene Tore zu öffnen und Jene, die schlafen, zu erwecken. Er glaubt, dass das Manuskript von Lorgalis längst verlorene Geheimnisse der alten Nachtelfen aus der Tiefschwarzen Grotte enthält, und er beabsichtigt, ihr dunkles Wissen zu kopieren und unter seinen geheimnisvollen Brüdern und Schwestern vor den kommenden letzten Tagen zu verbreiten.",al={"gerrig knochengriffs beweggrund","warum will gerrig das manuskript","grund für gerrig knochengriffs quest"}}},fp="22,354,24.495.0,27.469.0,20.538.1,43.154.0,32.148.0,41.146.0,55.165.0,77.123.1,68.325.0"}
P.entries["quest:972"] = {n="Wassersapta",s="Wassersapta ist eine Übergangsaufgabe, die jungen Schamanen der Horde von Islen Wasserdeuter entlang der Küste des Brachlands übertragen wird. Nachdem der Schamane mit einem rituellen Gebräu durchdrungen wurde, wird er über das große Meer in die verseuchten Lande des Silberwalds geschickt, um sich einer verdorbenen Quelle zu stellen.",h="Wassersapta ist eine Übergangsaufgabe, die jungen Schamanen der Horde von Islen Wasserdeuter entlang der...",kw={"ruf des wassers","islen wasserdeuter","schamanenprüfung","silberwald","brachland","totemquest","wassersapta"},ang={["class:Shaman"]="Die Wassersapta markiert einen kritischen Wendepunkt in Euren elementaren Prüfungen und öffnet Euch die Augen für die Geisterwelt, bevor sie Euch die Herrschaft über Euer heilendes Wassertotem gewährt.",["faction:Horde"]="Die Prüfung demonstriert die kontinentalübergreifende Einheit der neuen Horde und sendet Eingeweihte von den sonnenverbrannten Ebenen von Kalimdor in die verwunschenen Wälder von Lordaeron."},sec={{t="Eine Vision des Wassers",b="In den elementaren Traditionen der Schamanen der Horde ist eine Sapta ein alchemistischer Trank, der hergestellt wurde, um die Sinne direkt auf die Geister der Welt einzustimmen. Während gewöhnliche Augen nur ruhige Bäche oder stagnierende Teiche wahrnehmen, durchbricht das Trinken einer Sapta den Schleier der physischen Ebene und enthüllt die Elementarwesen, die innerhalb der Strömung leben."},{t="Der Weg in den Silberwald",b="Nachdem sie ihre Hingabe an die Geister bewiesen haben, erhält der Schamane das Gebräu direkt von Islen Wasserdeuter, einer Einsiedlerin, die an den trostlosen Ufern südlich von Ratschet lebt. Anstatt die Sapta in den trockenen Tälern von Kalimdor zu testen, befiehlt Islen dem Eingeweihten, weit über das große Meer in die schattenhaften, verlassenen Wälder des Silberwalds zu reisen, um sich einer elementaren Verderbnis zu stellen, die die Bäche Lordaerons vergiftet."}},faq={{q="Was ist eine Wassersapta?",a="Eine Sapta ist ein rituelles Elixier, das von schamanischen Lehrmeistern zubereitet wird. Wenn es konsumiert wird, schärft es die spirituelle Wahrnehmung und ermöglicht es dem Trinkenden, direkt mit Elementargeistern zu sehen und zu kommunizieren, die für sterbliche Augen ansonsten unsichtbar sind.",al={"was ist eine sapta","bedeutung wassersapta","wirkung der sapta"}},{q="Wer ist Islen Wasserdeuter?",a="Islen Wasserdeuter ist eine Meisterschamanin, die in einsamer Kontemplation an der Ostküste des Brachlands lebt, südlich der Händlerküste. Sie führt junge Schamanen der Horde auf dem beschwerlichen Pfad, um mit dem Element Wasser zu kommunizieren und es zu binden.",al={"hintergrund islen wasserdeuter","wer ist islen"}},{q="Warum muss der Schamane in den Silberwald reisen?",a="Die Elementargeister des Wassers leiden im Silberwald unter weitverbreiteter Plage. Um ihre Initiation abzuschließen, muss der Schamane die Sapta über das Meer tragen, um eine verdorbene Wasserquelle aus erster Hand zu betrachten und die Verderbnis zu reinigen.",al={"warum silberwald","reise in die östlichen königreiche"}},{q="Was passiert nach dem Trinken der Sapta?",a="Der Konsum der Wassersapta ermöglicht es dem Schamanen, die verdorbenen Wasserelementare zu sehen, die in den verseuchten Teichen des Silberwalds lauern, und öffnet den Weg, um die Quelle des Verfalls zu konfrontieren.",al={"sapta trinken","effekt der sapta"}},{q="Ist diese Prüfung für alle Schamanen der Horde erforderlich?",a="Ja. Orc-, Tauren- und Trollschamanen gleichermaßen müssen dem Ruf des Wassers folgen und erhalten diese Sapta als einen wesentlichen Initiationsritus, bevor sie ihr Wassertotem verdienen können.",al={"wer absolviert diese quest","ist das eine klassenquest"}},{q="Wo im Silberwald befindet sich der verdorbene Teich?",a="Die verdorbene Quelle liegt an der Küste des Silberwalds, westlich vom Grabmal.",al={"fundort teich im silberwald","wo ist der wasserteich"}}},fx={c8d11240={q="Warum schickt Euch Islen Wasserdeuter in den Silberwald?",a="Islen Wasserdeuter versucht, Euch durch Euren spirituellen Ritus zu führen und Euch dabei zu helfen, Euch auf die elementaren Kräfte des Wassers einzustimmen. Um die Gemeinschaft mit den Geistern des Wassers zu verdienen und den Call of Water zu vollenden, müsst Ihr Euch dem Makel stellen und ihn reinigen, der die Wasserwege der Welt plagt. Sie hat Euch mit einer vorbereiteten Water Sapta betraut, damit Ihr verborgene elementare Verderbnis aus erster Hand wahrnehmen und Eure Hingabe als aufstrebender Schamane beweisen könnt.",al={"warum will islen das","islen wasserdeuters beweggrund","warum korrumpiertes wasser reinigen"}}},fp="11,256,17.335.0,22.426.0,22.231.0,23.239.0,48.240.0,38.177.0,44.162.0,50.86.0"}
P.entries["quest:97220"] = {n="Philmor's Favor",s="Philmor's Favor ist eine Lieferaufgabe in Sturmwind, die durch einen anhaltenden Mangel an einheimischen Dockarbeitern veranlasst wurde. Kuriere werden gebeten, eine heikle Gatehouse-Lieferung zu einem abgelegenen Lagerraumeingang im zweiten Stock von Trias' Cheese im Handelsdistrikt zu transportieren.",h="Philmor's Favor ist eine Lieferaufgabe in Sturmwind, die durch einen anhaltenden Mangel an einheimischen...",kw={"elaine","torhaus","torhauslieferung","philmor","philmors gefallen","sturmwind","der handelsdistrikt","trias' käse"},ang={["faction:Alliance"]="Das Aushelfen bei Lieferungen im gesamten Handelsdistrikt von Sturmwind sorgt dafür, dass die Logistik der Stadt reibungslos funktioniert, während Dockarbeiter weiterhin Mangelware sind."},sec={{t="Angespannte Logistik in Sturmwind",b="Ein anhaltender Mangel an Dockarbeitern in ganz Sturmwind hat die routinemäßigen Frachtoperationen der Stadt strapaziert. Um zu verhindern, dass die örtlichen Frachtzeitpläne in Verzug geraten, suchen Frachtführer nach zuverlässigen Reisenden, die bereit sind, empfindliche Kisten direkt in das Handelsviertel zu schleppen."},{t="Diskrete Lieferungen bei Trias' Cheese",b="Die Lieferung ist für das Gatehouse bestimmt, doch ihre Übergabe ist alles andere als gewöhnlich. Anstatt durch den Haupteingang des Wachhauses zu gelangen, wird die Kiste in den zweiten Stock des Käseladens Trias' Cheese im Handelsdistrikt getragen. Der Laden verbirgt einen Lagerraumeingang, der genutzt wird, um Vorräte und zeremonielle Geschenke, die für die Offiziere der Wache bestimmt sind, unbemerkt von neugierigen Blicken zu transportieren."}},faq={{q="Wer benötigt Hilfe bei dieser Lieferung?",a="Die Quest wird angeboten, um den Frachtplan rund um Sturmwind zu entlasten, wenn den örtlichen Betrieben die Dockarbeiter ausgehen.",al={"wer gibt philmors gefallen","philmor questgeber"}},{q="Wo befindet sich der Zielort der Lieferung?",a="Die Lieferung muss zum Lagerraumeingang des Gatehouse gebracht werden, der über den zweiten Stock von Trias' Cheese in Sturmwinds Handelsdistrikt erreicht wird.",al={"wohin bringe ich das paket","trias käse lieferung","wo ist der eingang zum torhaus"}},{q="Wer nimmt die Lieferung entgegen?",a="Elaine ist die Herrin des Käseladens Trias' Cheese, die daran gewöhnt ist, diskrete Frachtlieferungen abzuwickeln, die für den angrenzenden Gatehouse-Lagerraum bestimmt sind.",al={"wer ist elaine","elaine trias käse"}},{q="Was befindet sich in der Gatehouse-Lieferung?",a="Die Lieferung enthält heikle Güter, die für das Gatehouse bestimmt sind. Örtlichen Frachtführern zufolge treffen Lieferungen oft mit besonderer Diskretion ein, um zeremonielle Überraschungen für Wachoffiziere zu ermöglichen.",al={"was ist in dem paket","inhalt der torhauslieferung"}},{q="Warum wird ein militärischer Lagerraum über einen Käseladen betreten?",a="Das Obergeschoss des Käseladens Trias' Cheese beherbergt einen Zugang zum Gatehouse-Lagerraum, der einen diskreten Durchgang und Warenabwurf ermöglicht, ohne Güter durch den militärischen Haupteingang zur Schau stellen zu müssen.",al={"warum trias käse torhaus","geheimeingang trias käse"}},{q="Warum herrscht ein Mangel an Dockarbeitern?",a="Personalmangel hat dazu geführt, dass Hafen- und Frachtarbeiter die ganze Woche über unterbesetzt waren, was Logistikkoordinatoren dazu zwang, sich auf durchreisende Reisende zu verlassen, um die Lieferungen im Zeitplan zu halten.",al={"warum mangel an dockarbeitern","sturmwind dockarbeitermangel"}}},fp="15,268,31.262.0,36.382.0,34.118.0,34.167.0,26.147.0,38.202.0,59.193.0,34.182.0"}
P.entries["quest:97222"] = {n="Gatehouse Goods",s="Gatehouse Goods ist eine lokale Aufgabe in Sturmwind, bei der eine Lieferung über die Treppe im Inneren von Trias' Cheese transportiert werden muss. Da der Käseladen sich ein Stockwerk mit dem angrenzenden Torhaus teilt, können Waren unauffällig vor der Tür des Lagerraums abgestellt werden, damit die Wachen sie abholen. Diese Regelung unterstreicht die dichte, miteinander verbundene städtische Gestaltung von Sturmwinds Handels- und Verteidigungsvierteln.",h="Gatehouse Goods ist eine lokale Aufgabe in Sturmwind, bei der eine Lieferung über die Treppe im Inneren von...",kw={"lieferung","elling trias","gatehouse goods","torhaus-lieferung","lagerraum","sturmwind","trias cheese"},ang={["class:Rogue"]="Sich unauffällig in der Nähe von Trias' Cheese zu bewegen und auf feine architektonische Details wie nach innen schwingende Türen zu achten, liegt jenen im Blut, die Diskretion zu schätzen wissen.",["faction:Alliance"]="Die Mithilfe bei der Organisation diskreter Lieferungen über Trias' Cheese sorgt dafür, dass die Waren reibungslos zwischen den lokalen Ladenbesitzern von Sturmwind und dem benachbarten Torhauspersonal transportiert werden."},sec={{t="Gemeinsame Unterkünfte und geteilte Stockwerke",b="Gatehouse Goods beinhaltet einen unkomplizierten Lieferauftrag inmitten der belebten Straßen von Sturmwind. Die Aufgabe erfordert es, eine Torhaus-Lieferung über die Innentreppe von Trias' Cheese nach oben zu tragen. Obwohl der berühmte Käseladen ein völlig eigenständiges Geschäft mit eigenem separaten Inventar ist, teilt seine bauliche Struktur ein Stockwerk mit den benachbarten Einrichtungen des Torhauses. Diese architektonische Besonderheit macht den oberen Treppenabsatz des Ladens zu einer praktischen Passage für den Transport von Vorräten zwischen benachbarten Vierteln, ohne den Betrieb auf den vorderen Straßen zu stören."},{t="Eine praktische Übergabe",b="Das Übergabeprotokoll ist präzise: Kuriere müssen die Kiste direkt vor der Lagertür abstellen, anstatt sie hineinzutragen. Reguläre Torhauswachen behalten den ankommenden Verkehr im Auge und weisen Personal an, Pakete bei ihrer Rückkehr auf ihre Posten abzuholen. Darüber hinaus ist die Tür des Lagerraums bewusst mit nach innen öffnenden Scharnieren gebaut, um sicherzustellen, dass draußen gestapelte Waren niemals den Eingang versperren oder die Personen im Inneren daran hindern, sich frei zu bewegen."}},faq={{q="Was ist Gatehouse Goods?",a="Gatehouse Goods ist ein lokaler Lieferauftrag in Sturmwind, der Trias' Cheese und das angrenzende Torhaus betrifft. Ein Kurier wird gebeten, eine Lieferung die Treppe hinaufzuschleppen und vor der Lagertür des Torhauses abzustellen.",al={"was ist gatehouse goods","gatehouse goods quest"}},{q="Wohin soll die Lieferung gebracht werden?",a="Die Lieferung geht die Treppe im Laden von Trias' Cheese hinauf. Obwohl Trias' Cheese ein unabhängiges Geschäft ist, teilt sich das Gebäude ein Stockwerk mit dem Torhaus, was direkte Übergaben direkt vor deren Lagerraum ermöglicht.",al={"trias cheese torhaus","wohin geht die lieferung"}},{q="Warum wird die Kiste vor der Tür abgestellt, anstatt hineingebracht zu werden?",a="Der Empfänger weist den Kurier ausdrücklich an, die Kiste vor der Lagertür abzustellen, anstatt sie hineinzubringen. Die Torhauswachen bemerken die Ankunft und schicken jemanden im Rahmen des regulären Abholdienstes los, um sie bei der Rückkehr auf ihren Posten hineinzutragen.",al={"warum nicht drinnen abgeben","wer holt die kiste ab"}},{q="Warum öffnet sich die Lagertür nach innen?",a="Das Scharnier des Lagerraums öffnet sich gezielt nach innen, damit vor dem Eingang abgestellte Pakete und Waren weder die Tür blockieren noch Personen im Inneren einsperren.",al={"nach innen oeffnende tuer trias","lagerraum tuerscharnier"}},{q="Gehört Trias' Cheese zum Torhaus?",a="Nein, Trias' Cheese ist nicht Teil des Torhauses und teilt auch keinen Warenbestand. Allerdings teilen sich die beiden Einrichtungen ein Stockwerk des Gebäudes, was die oberen Stufen zu einem praktischen Übergabepunkt macht.",al={"gehoert trias cheese zum torhaus","trias cheese warenbestand"}},{q="Wer beaufsichtigt die Lieferung der Waren?",a="Die Aufgabe wird von lokalen Drahtziehern organisiert, die professionellen Respekt und gegenseitige Diskretion erwarten und zuverlässige Kuriere anerkennen, sobald die Übergabe erfolgreich durchgeführt wurde, ohne die Türschwelle zu blockieren.",al={"wer vergibt gatehouse goods","wer nimmt die lieferung an"}}},fp="15,378,33.531.0,20.455.0,24.213.0,47.214.0,65.245.0,40.142.0,47.194.0,39.207.0"}
P.entries["quest:97223"] = {n="Bloodtalon Matriarch",s="Die Bloodtalon Matriarch ist die furchterregende Anführerin eines schnellen und gerissenen Raptor-Rudels nahe Sen'jin. Nachdem sie sich als ausgewachsenes Tier als zu gefährlich und stur für eine Zähmung erwiesen hat, muss sie bekämpft werden, damit ihre Nachkommen aus dem Ei als treue Gefährten für den Darkspear tribe herangezogen werden können.",h="Die Bloodtalon Matriarch ist die furchterregende Anführerin eines schnellen und gerissenen Raptor-Rudels nahe...",kw={"blutkralle","dunkelspeer","matriarchin","raptor","raptoreier","raptoren","sen'jin","senjin","trollreittiere"},ang={["class:Hunter"]="Jäger verstehen die Schwierigkeit, erfahrene, ausgewachsene Bestien zu zähmen, und die Notwendigkeit, Raubtiere von Geburt an aufzuziehen, um eine echte Bindung zu schmieden.",["faction:Horde"]="Einheimische Raubtiere zu treuen Verbündeten heranzuziehen, trägt dazu bei, die Siedlung der Dunkelspeer zu sichern, und stärkt die Präsenz der Horde an der Küste von Durotar.",["race:Troll"]="Die Dunkelspeertrolle von Sen'jin schätzen Raptoren als wendige Gefährten und Kriegsrösser und achten die Linie der Bloodtalons für ihre Schläue und Schnelligkeit."},sec={{t="Die Blutlinie der Bloodtalons",b="Das Bloodtalon-Rudel ist entlang der Küste von Durotar für seine bemerkenswerte Schnelligkeit und ausgeprägte Schläue bekannt. Tierführer in Sen'jin schätzen diese Eigenschaften über alles, wenn sie nach zuverlässigen Reittieren und Gefährten für den Darkspear tribe suchen. Ausgewachsene Raptoren besitzen jedoch sture und gewalttätige Instinkte, wodurch erwachsene Tiere nahezu unmöglich zu domestizieren sind, sobald sie sich an das Leben in der Wildnis angepasst haben."},{t="Bewahrung der Blutlinie",b="Trotz mehrerer Versuche, die Matriarchin direkt einzufangen und abzurichten, machte ihre zunehmende Aggressivität sie zu einer offenen Bedrohung für das umliegende Gebiet. Um den Stamm zu schützen und gleichzeitig sicherzustellen, dass ihre außergewöhnliche Blutlinie nicht verloren geht, beschlossen die Trolle, die gefährliche Mutter zu bezwingen und ihr Gelege zu retten, damit die nächste Generation von Ei auf zu treuen Verbündeten herangezogen werden kann."}},faq={{q="Wer ist die Bloodtalon Matriarch?",a="Die Bloodtalon Matriarch ist ein wilder, ausgewachsener Raptor, dessen Rudel für Schnelligkeit und Schläue bekannt ist. Während frühere Versuche unternommen wurden, sie einzufangen und abzurichten, wurde sie schließlich viel zu gefährlich, um mit ihr umzugehen, was die Dunkelspeertrolle dazu veranlasste, stattdessen ihre Eier zu sichern.",al={"wer ist die blutkrallenmatriarchin","blutkrallenraptormatriarchin","matriarchin raptor"}},{q="Warum muss die Bloodtalon Matriarch beseitigt werden?",a="Ausgewachsene Raptoren sind bekanntermaßen schwer zu zähmen, und die Matriarchin wurde zu einer zu großen Gefahr für die örtliche Siedlung. Indem sie bezwungen und ihr Gelege gesammelt wird, können die Tierführer in Sen'jin die Gefahr neutralisieren und gleichzeitig ihre Blutlinie bewahren.",al={"warum die matriarchin toeten","warum eier erbeuten","warum die matriarchin jagen"}},{q="Warum zähmt man die Matriarchin nicht stattdessen?",a="Ausgewachsene Raptoren besitzen wilde, unzähmbare Instinkte, die es fast unmöglich machen, sie abzurichten, sobald sie ausgewachsen sind. Tierführer erzielen weitaus größere Erfolge, indem sie Eier an sich nehmen und die Jungtiere direkt an der Seite ihrer zukünftigen Gefährten aufziehen.",al={"kann man erwachsene raptoren zaehmen","erwachsenen raptor abrichten"}},{q="Was geschieht mit den Nachkommen der Matriarchin?",a="Das erbeutete Gelege wird zurück nach Sen'jin gebracht, um ausgebrütet und aufgezogen zu werden. Die Trolle beabsichtigen, die jungen Raptoren von klein auf abzurichten, damit sie zu zuverlässigen Verbündeten und Reittieren für den Stamm heranwachsen.",al={"was geschieht mit den eiern","nachkommen der matriarchin","raptoren in senjin"}},{q="Wo ist diese Quest angesiedelt?",a="Die Quest konzentriert sich auf Sen'jin, die Küstenzuflucht der Dunkelspeertrolle im südlichen Durotar, wo Tierführer daran arbeiten, loyale Raptoren für ihr Volk zu züchten und aufzuziehen.",al={"wo wird diese quest abgegeben","senjin raptorquest"}},{q="Was macht das Bloodtalon-Rudel besonders?",a="Die Bloodtalon-Raptoren werden insbesondere für ihre Schnelligkeit und Intelligenz geschätzt. Diese Eigenschaften machen ihre Abstammung als Gefährten und Reittiere außerordentlich begehrt, sofern sie trainiert werden, bevor ihre wilden Instinkte die Oberhand gewinnen.",al={"blutkrallenraptor merkmale","warum blutkrallenraptoren"}}},fp="20,280,22.393.0,24.386.0,32.262.0,48.249.0,35.230.0,46.200.0,29.175.0,39.231.0"}
P.entries["quest:97225"] = {n="Forgotten Loa Idols",s="Bei Forgotten Loa Idols geht es um die Wiederbeschaffung heiliger religiöser Bildnisse für die Dunkelspeertrolle. Diese verlorenen Relikte werden dringend benötigt, um lebenswichtige spirituelle Zeremonien wiederaufzunehmen und das beständige Band der Ehrfurcht des Stammes zu seinen beschützenden wilden Geistern zu bewahren.",h="Bei Forgotten Loa Idols geht es um die Wiederbeschaffung heiliger religiöser Bildnisse für die...",kw={"dunkelspeer","vergessene loaidole","idole","loa","verehrung","rituale","geister","troll"},ang={["class:Priest"]="Trollpriester und Hexendoktoren verlassen sich direkt auf Rituale und angestammte heilige Gegenstände, um spirituelle Macht zu kanalisieren und die Loa zu ehren.",["class:Shaman"]="Während schamanische Praktiken die Mächte der Elemente anrufen, hegen spirituelle Trolle tiefe Ehrfurcht vor den wilden Göttern und angestammten Loa, die mit dem Überleben ihres Stammes verbunden sind.",["faction:Horde"]="Die Dunkelspeer sind Gründungsmitglieder der Horde, und ihren heiligen Ältesten bei der Bewahrung lebenswichtiger religiöser Artefakte beizustehen, stärkt den Zusammenhalt des Stammes innerhalb der Fraktion.",["race:Troll"]="Für Dunkelspeertrolle steht die Zwiesprache mit den Loa im Mittelpunkt des spirituellen Lebens. Die Wiederbeschaffung verlorener Idole stellt sicher, dass lebenswichtige Rituale fortgeführt werden können und der Stamm im Wohlwollen der Geister verbleibt."},sec={{t="Heilige Überreste der Loa",b="Für die Dunkelspeertrolle ist das spirituelle Gleichgewicht untrennbar mit ihrer Verbindung zu den Loa verbunden – den ursprünglichen Tiergeistern und wilden Göttern ihres angestammten Erbes. Forgotten Loa Idols beinhaltet die Wiederbeschaffung verschollener religiöser Relikte, die für die Durchführung von Stammeszeremonien unerlässlich sind. Ohne diese heiligen Gegenstände können die spirituellen Anführer nicht die Riten vollziehen, die erforderlich sind, um die Harmonie mit ihren göttlichen Wächtern aufrechtzuerhalten."},{t="Das Band der Dunkelspeere",b="Während mehrere feindselige Trollfraktionen in ganz Azeroth Blutopfer praktizieren oder versuchen, Geister mit Gewalt zu unterwerfen, sind die Dunkelspeer stolz darauf, ein Band gegenseitigen Respekts und demütiger Ehrfurcht aufrechtzuerhalten. Für die Dunkelspeer bedeutet der Verlust der Gunst ihrer Schutzpatrone eine schwere Katastrophe, was die Wiederbeschaffung dieser verlorenen Idole zu einem lebenswichtigen Akt der Selbsterhaltung des Stammes macht."}},faq={{q="Was ist der Zweck von Forgotten Loa Idols?",a="Forgotten Loa Idols ist eine für die Dunkelspeertrolle übernommene Aufgabe, um verschwundene heilige Bildnisse wiederzubeschaffen. Die Idole werden benötigt, um entscheidende Stammesrituale wiederaufzunehmen und die Ehre gegenüber ihren verehrten wilden Geistern zu wahren.",al={"vergessene loaidole","was ist diese quest","was ist vergessene loaidole"}},{q="Was sind Loa?",a="Die Loa sind uralte, mächtige Urgeister und Gottheiten in Tiergestalt, die von Trollen verehrt werden. Die Trollkultur ehrt sie durch Opfergaben, Gebete und rituelle Zeremonien im Austausch für Schutz, Wohlwollen und spirituelle Führung.",al={"was sind loa","trollgötter","wer sind die loa"}},{q="Wie betrachten die Dunkelspeer ihre Loa im Vergleich zu anderen Trollstämmen?",a="Anders als brutalere Trollstämme, die versuchen, dunkle Gottheiten zu unterwerfen oder ihnen Opfer darzubringen, betrachten die Dunkelspeer ihre Verbundenheit mit den Loa als ein Verhältnis tiefer Ehrfurcht, gegenseitigen Respekts und spiritueller Pflicht. Sie glauben, dass ihr Überleben davon abhängt, in der Gunst der Geister zu bleiben.",al={"beziehung der dunkelspeere zu den loa","warum loa verehren","andere stämme loa"}},{q="Warum werden die Idole für Stammesrituale benötigt?",a="Die Idole dienen als geweihte Foki für Stammesrituale. Ohne sie können die Ältesten und spirituellen Führer die Riten nicht ordnungsgemäß durchführen, die erforderlich sind, um mit ihren Schutzgeistern zu kommunizieren und sie zu ehren.",al={"warum werden idole benötigt","zweck der loaidole","warum sind idole wichtig"}},{q="Warum ist es für die Dunkelspeer so wichtig, die Gunst der Loa zu behalten?",a="Die Ältesten der Dunkelspeer fürchten, dass ihr Stamm ohne angemessene Riten und Opfergaben die Gunst und die schützenden Segnungen der Loa verlieren könnte, was den Stamm in einer ohnehin gefährlichen Welt schutzlos zurücklassen würde.",al={"was passiert wenn nicht zurückgebracht","in ungnade fallen","gunst der loa für die dunkelspeere"}},{q="Wer verlangt die Rückkehr der Forgotten Loa Idols?",a="Die Quest wird von einem spirituellen Führer der Dunkelspeertrolle vergeben, der bestrebt ist, gemeinschaftliche Zeremonien wiederaufzunehmen und die Segnungen der angestammten Schutzpatrone des Stammes zu sichern.",al={"wer vergibt vergessene loaidole","questgeber","wer verlangt nach idolen"}}},fp="19,252,26.411.0,18.367.0,43.208.0,13.216.0,67.267.0,44.193.0,57.191.0,48.161.0"}
P.entries["quest:97234"] = {n="Reading Room",s="Reading Room dreht sich um einen Austausch zwischen Roys Buchclub und der Stormwind Library. Abenteurer unterstützen den Club, indem sie ein eingepacktes Paket älterer Literatur zur Bibliothek bringen, um moderne Schriften für Diskussionen unter den Mitgliedern zu beschaffen.",h="Reading Room dreht sich um einen Austausch zwischen Roys Buchclub und der Stormwind Library.",kw={"bücher","legenden","bibliothekar","reading room","roys buchclub","stormwind library","wälzer"},ang={["faction:Alliance"]="Reisende der Allianz besuchen häufig die Royal Library in Burg Sturmwind, wo bürgerlicher und gelehrter Austausch das geistige Leben der Stadt aufrechterhalten."},sec={{t="Literarische Bestrebungen in Sturmwind",b="In der geschäftigen Hauptstadt Sturmwind versammeln sich Literaturliebhaber unter dem Banner von Roys Buchclub, um klassische Legenden zu analysieren und provokante Schriften zu debattieren. Der Club hält seine Diskussionen lebendig, indem er Texte durchwechselt und ältere oder weniger beliebte Werke gegen neuere, fesselndere Bände aus dem riesigen Fundus der Stadt eintauscht."},{t="Der Austausch mit der Library",b="Um ihre Leseliste aktuell zu halten, verlässt sich der Club auf eine etablierte Leihvereinbarung mit der Stormwind Library. Roy verpackt die zurückgegebenen Bände des Clubs mit einer unverwechselbaren Einwickeltechnik, sodass Abenteurer die Bündel direkt zum Bibliothekar bringen können, im Austausch gegen eine neue Liste moderner Wälzer."}},faq={{q="Was ist die Quest Reading Room?",a="Reading Room ist eine Aufgabe rund um Roys Buchclub, eine Zusammenkunft von Lesern, die über geschichtsträchtige Legenden und Literatur diskutieren. Die Quest verlangt von einem Abenteurer, ein eingepacktes Bündel weniger beliebter Werke hinüber zur Stormwind Library zu bringen, um sie gegen modernere Wälzer einzutauschen.",al={"reading room quest","was ist reading room","reading room geschichte"}},{q="Wer ist Roy?",a="Roy leitet einen aktiven Leseclub, in dem Mitglieder zusammenkommen, um über die tieferen Bedeutungen geschichtsträchtiger Legenden und Literatur zu debattieren. Er unterhält eine Vereinbarung mit der Stormwind Library, um das Lesematerial durchzuwechseln und geliehene Wälzer in einwandfreiem Zustand zurückzugeben.",al={"wer ist roy","roys buchclub","buchclubleiter"}},{q="Wohin werden die Bücher gebracht?",a="Das eingepackte Lesematerial wird direkt zur Bibliothek in Sturmwind gebracht. Der dortige Bibliothekar erkennt die unverwechselbare Einwickeltechnik von Roys Club wieder und willigt gerne in den Tausch gegen frische moderne Schriften ein.",al={"wohin kommen die bücher","abgabe in stormwind library","lieferung des verpackten lesematerials"}},{q="Warum werden die Bücher ausgetauscht?",a="Der Club mustert einige seiner weniger beliebten Werke aus, um sie gegen modernere und zum Nachdenken anregende Schriften einzutauschen, wobei er sich auf eine etablierte Ausleihvereinbarung mit der städtischen Bibliothek stützt.",al={"warum bücher tauschen","warum wälzer zurückbringen","lesematerial austauschen"}},{q="Wie steht der Bibliothekar von Sturmwind zu dem Buchclub?",a="Der Bibliothekar von Sturmwind ist sehr zufrieden mit der Vereinbarung und merkt an, dass Roys Club geliehenes Material stets in hervorragendem Zustand zurückgibt und alle Texte pfleglich behandelt, ganz gleich, wie provokant der Inhalt auch sein mag.",al={"was denkt die bibliothekarin","ist der buchclub erlaubt","bibliotheksvereinbarung"}},{q="Welche Cluberfrischungen werden erwähnt?",a="Der Club bietet Gästen und Helfern, die bei der Durchführung ihrer Bücheraustausche zwischen dem Leseort und den städtischen Archiven mitwirken, kostenlose Erfrischungen an.",al={"kostenlose cluberfrischungen","clubvorteile","welche erfrischungen"}}},fp="12,239,30.329.0,20.310.0,31.259.0,11.248.0,32.219.0,34.189.0,52.237.0,41.159.0"}
P.entries["quest:97236"] = {n="Fang of Githyiss",s="Der Fang of Githyiss ist ein seltenes und beeindruckendes Exemplar, das von einem riesigen Spinnentier stammt, welches die Wildnis nahe Aldrassil durchstreift. Die Übergabe des Reißzahns an einen Naturforscher in der Zuflucht ermöglicht es Gelehrten, die monströse Kreatur zu studieren und die räuberischen Bedrohungen zu überwachen, die im Laubschattental nisten.",h="Der Fang of Githyiss ist ein seltenes und beeindruckendes Exemplar, das von einem riesigen Spinnentier...",kw={"aldrassil","fang of githyiss","githyiss","laubschattental","spinne","spinnenforschung","teldrassil"},ang={["class:Druid"]="Druiden wachen aufmerksam über das natürliche Gleichgewicht auf Teldrassil und erforschen ungewöhnliche Raubtiere sowie übergroße Spinnentiere, um den Zustand der umliegenden Wildnis zu überwachen.",["faction:Alliance"]="Die Erforschung der gefährlichen Tierwelt auf Teldrassil unterstützt die Allianz, indem sie sicherstellt, dass junge Rekruten und Forscher die verderbenden Bedrohungen verstehen, die nahe Aldrassil nisten.",["race:NightElf"]="Als Verteidiger von Teldrassil tragen junge Nachtelfenabenteurer im Laubschattental dazu bei, die Äste von Aldrassil zu schützen, indem sie gefährliche Monstrositäten beseitigen und den örtlichen Forschern beistehen."},sec={{t="Ein monströses Exemplar",b="Der Fang of Githyiss ist eine Trophäe und eine biologische Probe, die von der übergroßen Spinne Githyiss erbeutet wurde, welche in der Wildnis des Laubschattentals lauert. Eine Bestie von solch beachtlicher Größe stellt eine eindeutige Bedrohung für junge Reisende dar, die von Aldrassil aus aufbrechen, sodass die Bergung ihres Reißzahns sowohl eine Frage der Sicherheit als auch von wissenschaftlichem Interesse ist. Anstatt die Überreste der Kreatur im Unterholz verrotten zu lassen, bringen einfallsreiche Kundschafter das Exemplar zurück in die Zuflucht des großen Baumes."},{t="Forschung in Aldrassil",b="In Aldrassil behalten Naturforscher und Gelehrte der Nachtelfen die Tierwelt, die den Waldboden durchstreift, genau im Auge. Die Vorlage eines frischen, unversehrten Reißzahns einer Kreatur von Githyiss' Ausmaß liefert entscheidende Einblicke in die Spinnentierpopulationen, die unter dem Blätterdach von Teldrassil gedeihen. Die örtlichen Forscher begrüßen solche unerwarteten Entdeckungen und nutzen den gewaltigen Reißzahn, um ihre fortlaufenden Studien über die aggressive Fauna der Lichtung voranzutreiben."}},faq={{q="Was ist der Fang of Githyiss?",a="Der Fang of Githyiss ist ein frisches Exemplar, das von der großen Spinne Githyiss erbeutet wurde. Die Bergung eines derart gewaltigen Reißzahns liefert seltenes Forschungsmaterial über die räuberischen Spinnentiere, die in der Wildnis rund um Aldrassil hausen.",al={"was ist fang of githyiss","githyiss reißzahn quest","fang of githyiss gegenstand"}},{q="Wer oder was ist Githyiss?",a="Githyiss ist eine bemerkenswert große und gefährliche Spinne, die durch die Wälder nahe Aldrassil im Laubschattental streift. Ihre Größe macht sie zu einer Bedrohung für Reisende und zu einem faszinierenden Forschungsobjekt für die örtlichen Naturforscher.",al={"wer ist githyiss","githyiss spinne","wo ist githyiss"}},{q="Wer möchte den Fang of Githyiss haben?",a="Der Reißzahn wird zu einem Gelehrten in Aldrassil gebracht, der sich auf die Erforschung von Spinnen spezialisiert hat. Solche Forscher begrüßen frische Exemplare, um ihr Verständnis der Biologie der einheimischen Spinnentiere zu vertiefen.",al={"wer gibt fang of githyiss ab","wohin bringe ich den reißzahn","spinnenforscher aldrassil"}},{q="Wo liegt Aldrassil?",a="Aldrassil ist der große Ast und die zentrale Zuflucht des Laubschattentals, gelegen in der Krone des Weltenbaums Teldrassil. Er dient als Ausbildungsstätte und Zufluchtsort für junge Nachtelfen.",al={"wo ist aldrassil","aldrassil standort"}},{q="Warum erforschen Gelehrte in Aldrassil Spinnenreißzähne?",a="Gelehrte und Naturforscher in Aldrassil erforschen die einheimischen Spinnentiere, um die Ökologie des Laubschattentals besser zu verstehen und die aggressiven, übergroßen Bestien zu überwachen, die unter dem Blätterdach von Teldrassil hausen.",al={"warum erforscht man spinnen in aldrassil","warum spinnenreißzähne erforschen"}},{q="Können Spieler der Horde den Fang of Githyiss abgeben?",a="Nein. Die Quest findet im Laubschattental statt, der Startenklave der Nachtelfen auf Teldrassil, sodass sie ausschließlich für Abenteurer der Allianz zugänglich ist, die ihre Reise in Aldrassil beginnen.",al={"ist diese quest nur für die allianz","kann die horde fang of githyiss machen"}}},fp="16,279,20.462.0,21.438.0,29.219.0,24.188.0,31.185.0,19.184.0,52.194.0,47.182.0"}
P.entries["quest:97237"] = {n="Shelf Picked",s="Shelf Picked ist ein Kurierauftrag in Sturmwind, bei dem eine bestimmte Leseliste aus den Regalen einer Library für Roy Lewells besorgt werden muss. Als bevollmächtigter Vermittler holt der Bote die Bände im Auftrag eines örtlichen Buchclubs ab, der sich im Park versammelt.",h="Shelf Picked ist ein Kurierauftrag in Sturmwind, bei dem eine bestimmte Leseliste aus den Regalen einer...",kw={"buchclub","kurier","library","park","roy lewells","shelf picked","sturmwind"},ang={["faction:Alliance"]="Das Erledigen von Kurieraufträgen zwischen Sturmwinds Bibliotheken und örtlichen Treffpunkten spiegelt das ruhige alltägliche Bürgerleben wider, das in der Hauptstadt inmitten größerer Spannungen im Königreich seinen Fortgang nimmt."},sec={{t="Ein Botengang für die Bücherregale",b="Shelf Picked beinhaltet, als offizieller Kurier für Roy Lewells zu fungieren, einen Bewohner mit Verbindungen zum Parkbezirk von Sturmwind. Roy reicht eine Anfrage für verschiedene Leseauswahlen ein, und während der zuständige Bibliothekar bestätigt, dass jeder aufgeführte Titel vorrätig ist, muss der Kurier jeden Band persönlich in den Regalen ausfindig machen und heraussuchen. Der Bibliothekar bleibt am Tresen, um sich der aufsichtlichen Buchführung zu widmen, womit er für ordnungsgemäße Bestandsaufzeichnungen sorgt, während er das physische Holen delegiert."},{t="Der Keller-Lesezirkel",b="Der Umgang mit ausgeliehenen Bibliotheksbänden bringt oft strenge Rückgabepflichten mit sich, doch das Vorzeigen von Roy Lewells' Vollmacht verleiht den Status eines offiziellen Kuriers. Der beaufsichtigende Bibliothekar merkt an, dass die persönliche Haftung nicht auf den Boten zurückfällt; stattdessen trägt Lewells' Einrichtung die volle Verantwortung für die Rückgabe der geliehenen Werke. Sobald sie in den Park gebracht wurden, bereitet Roy die exotisch duftenden Bände auf lebhafte Diskussionen nach Feierabend vor, die unten in einem Keller stattfinden."}},faq={{q="Wer vergibt die Quest Shelf Picked?",a="Die Quest erhaltet Ihr von einem Bibliothekar, der das Inventar in einer Library beaufsichtigt, nachdem Roy Lewells eine Auftragsnotiz gesendet hat. Der Bibliothekar überprüft, ob Roys angeforderte Leseliste vorrätig ist, weist Euch jedoch an, die Bände selbst aus den Regalen zu holen.",al={"wer vergibt shelf picked","shelf picked questgeber","wo beginnt shelf picked"}},{q="Wer ist Roy Lewells?",a="Roy Lewells ist ein Organisator eines örtlichen Lesezirkels rund um Sturmwinds Park. Er schickt Kuriere los, um reservierte Bücher aus der Library für anstehende Diskussionen nach Feierabend abzuholen, die in ihrem Keller abgehalten werden.",al={"wer ist roy lewells","roy lewells park","wer ist lewells"}},{q="Wo findet die Büchersammlung statt?",a="Die Quest findet in einer Library statt, in der Herr Lewells' Leseauswahl vorrätig gehalten wird. Der beaufsichtigende Bibliothekar verwaltet die Bestandsunterlagen, während Kuriere die Regale der Räumlichkeiten nach den spezifisch angeforderten Texten absuchen.",al={"welche bibliothek ist das","wo werden die bücher geholt","welche bibliothek shelf picked"}},{q="Warum benötigt Roy Lewells diese Bücher?",a="Roy Lewells forderte den Lesestoff für einen informellen Buchclub an, um lebhafte Diskussionen unter den Mitgliedern anzuregen. Wegen der Art ihrer Treffen kommen sie nach Feierabend in einem Keller zusammen, sobald die Bücher geliefert wurden.",al={"warum bücher für lewells holen","was ist lewells buchclub","keller buchclub nach feierabend"}},{q="Seid Ihr für die Rückgabe der geliehenen Bücher verantwortlich?",a="Nein. Der Bibliothekar stellt ausdrücklich klar, dass das Auftreten als offizieller Kurier mit Roy Lewells' Notiz Euch von der persönlichen Verantwortung für die Rückgabe der Bände befreit; die Last der Rückgabe der Bücher liegt allein bei Roys Einrichtung.",al={"bin ich für die rückgabe der bücher verantwortlich","wer gibt die bücher von shelf picked zurück","verantwortlichkeit für bibliotheksrückgabe"}},{q="Wohin bringt Ihr die Bücher nach dem Abholen?",a="Ihr liefert die gesammelten Lesematerialien direkt an Roy Lewells zurück, der im Parkbezirk der Stadt Sturmwind anzutreffen ist.",al={"wo gibt man shelf picked ab","wo findet man roy lewells","shelf picked abgabe"}}},fp="12,256,24.484.0,23.462.0,33.245.0,19.204.0,42.225.0,38.222.0,53.238.0,44.137.0"}
P.entries["quest:97242"] = {n="Yelmak's Medley",s="Yelmak's Medley ist eine Quest in Orgrimmar, bei der es darum geht, Spannungen in Yelmak's Alchemy and Potions im Tal der Ehre abzubauen. Meisteralchemist Yelmak versucht, die zerstörerische Ungeschicklichkeit und den sturen Stolz seines Lehrlings Whuut einzudämmen, indem er eine beruhigende, selbstgebraute Mischung aus einheimischen Wasserpflanzen zubereitet.",h="Yelmak's Medley ist eine Quest in Orgrimmar, bei der es darum geht, Spannungen in Yelmak's Alchemy and...",kw={"alchemie","rohrkolben","kor'geld","orgrimmar","speergras","tal der ehre","whuut","yelmak","yelmak's medley"},ang={["faction:Horde"]="Dieser Botengang findet direkt im Tal der Ehre in Orgrimmar statt und trägt dazu bei, Ordnung zu wahren und gereizte Gemüter im alchemistischen Gewerbe der Hauptstadt zu beruhigen.",["profession:Herbalism"]="Das Sammeln frischer Rohrkolben und Speergräser entlang der Wasserläufe der Stadt verdeutlicht, wie einheimische Flora direkt im Herzen von Orgrimmar für Gebräue und Kräutermixturen genutzt werden kann."},sec={{t="Ärger im Labor",b="In Yelmak's Alchemy and Potions im Tal der Ehre in Orgrimmar wird das Leben durch den sturen Stolz des jungen Lehrlings Whuut erschwert. Anstatt um Hilfe zu bitten oder zuzugeben, wenn er überfordert ist, hat der unerfahrene Mischer aus Frustration damit begonnen, die Ausrüstung des Ladens zu zertrümmern. Um den Schaden einzudämmen und das aufbrausende Gemüt des Jünglings zu beruhigen, ohne sein zerbrechliches Ego zu verletzen, ersinnt Meisteralchemist Yelmak ein beruhigendes, selbstgebrautes Gebräu."},{t="Beruhigende einheimische Flora",b="Das Rezept erfordert eine frische Ernte wilder Schnittlinge von den Rohrkolben und dem Speergras, die entlang der Wasserläufe gedeihen, die sich durch das Tal der Ehre schlängeln. Kor'geld kann den Laden nicht verlassen, ohne den misstrauischen Lehrling misstrauisch zu machen, sodass ein unauffälliger Dritter die Uferpflanzen sammeln muss. Sobald die botanische Mischung gesammelt ist, wird sie zubereitet, um Whuuts Verhalten subtil zu zügeln und den Frieden im Alchemieladen wiederherzustellen."}},faq={{q="Wer bietet die Quest Yelmak's Medley an?",a="Kor'geld, der sich in Yelmak's Alchemy and Potions im Tal der Ehre in Orgrimmar aufhält, bietet die Aufgabe im Namen des Meisteralchemisten des Ladens an.",al={"wer vergibt yelmaks medley","questgeber yelmak medley"}},{q="Wer ist Whuut?",a="Whuut ist ein Mischer-Lehrling, der unter Yelmak im Tal der Ehre ausgebildet wird. Er ist für seinen sturen Stolz bekannt und hat Ausrüstung zertrümmert, anstatt zuzugeben, dass er Anleitung oder Hilfe benötigt.",al={"wer ist whuut","yelmak lehrling","whuut orgrimmar"}},{q="Was ist der Zweck des selbstgebrauten Medleys?",a="Es ist eine besondere, selbstgebraute Mischung, die von Meisteralchemist Yelmak aus frischen Schnittlingen von Rohrkolben und Speergras gebraut wurde, um die saure Stimmung seines stolzen Lehrlings subtil zu beruhigen oder zu zügeln.",al={"was ist das rezept fuer yelmak's medley","was moechte yelmak brauen"}},{q="Wo werden die Zutaten gesammelt?",a="Die wilden Rohrkolben und das Speergras wachsen direkt entlang der Süßwasserbäche und Wasserbecken, die durch das Tal der Ehre in Orgrimmar fließen.",al={"wo man rohrkolben und speergras findet","tal der ehre schnittlinge"}},{q="Warum sammelt Kor'geld die Schnittlinge nicht persönlich?",a="Kor'geld kann Yelmak's Alchemy and Potions nicht verlassen, weil Whuut sofort merken würde, dass die Mitarbeiter des Ladens heimlich Umwege machen, um auf sein schwieriges Gemüt einzugehen.",al={"warum braucht korgeld hilfe","warum kann korgeld keine pflanzen pfluecken"}},{q="Wo befindet sich Yelmak's Alchemy and Potions?",a="Yelmak's Alchemy and Potions liegt im Tal der Ehre, einem östlichen Viertel der Horde-Hauptstadt Orgrimmar, das für seine Wasserwege, Kriegerkasernen und Handwerksläden bekannt ist.",al={"wo ist yelmak alchemie und traenke","yelmak laden standort"}}},fp="15,307,25.449.0,20.431.0,37.139.0,13.190.0,46.177.0,35.135.0,52.180.0,46.180.0"}
P.entries["quest:97243"] = {n="Call of Fire",s="Call of Fire schickt einen Initianden durch die Winde des Himmelswalls, um Olariaan Swiftburn aufzusuchen, einen Shen'dorei-Windformer, der auf das Element Feuer eingestimmt ist. Indem er die Torch of Dormant Flame zum Shrine of Flames im Böenbeerentiefland bringt, beginnt der Reisende zu lernen, dem Ruf der Flamme selbst innerhalb der Domäne der Luft zu folgen.",h="Call of Fire schickt einen Initianden durch die Winde des Himmelswalls, um Olariaan Swiftburn aufzusuchen...",kw={"call of fire","elementarebene","böenbeerentiefland","olariaan swiftburn","shen'dorei","shrine of flames","der himmelswall","torch of dormant flame","valanaar","windformer"},ang={["class:Shaman"]="Heeding the Call der Elemente ist grundlegend für die schamanische Ausbildung, und selbst im Himmelswall erfordert die Zwiesprache mit dem Feuer hingebungsvolle Führung und Ehrfurcht vor den Ahnen.",["race:Skyborne"]="Obwohl sie in den Winden des Himmelswalls heimisch sind, erkennen Skyborne-Reisende und Windformer an, dass das Gleichgewicht die Würdigung aller vier Urelemente erfordert."},sec={{t="Stimmen über die Elementarebene hinweg",b="Selbst innerhalb des Himmelswalls, der von den Luftelementaren beherrschten Domäne, bleiben die weiteren Strömungen der Elementarebene verbunden. Die Geister von Erde, Wasser und Feuer sprechen weiterhin zu jenen, die das Feingefühl besitzen, sie zu hören. Die Windformer zählen zu ihrer Gemeinschaft Individuen, die für diese anderen Kräfte einzigartig empfänglich sind, darunter Olariaan Swiftburn, ein Shen'dorei, der eine tiefe Einstimmung auf das Element Feuer pflegt."},{t="Der Shrine of Flames",b="Initianden wird die Torch of Dormant Flame anvertraut und sie werden in Richtung des Böenbeerentieflands gewiesen. Weit draußen am Inselrand, westlich von Valanaar gelegen, steht der Shrine of Flames. Dort nimmt Olariaan Swiftburn die schlummernde Flamme entgegen und bietet an, aufstrebende Schüler darin zu unterweisen, dem fordernden Ruf des Feuers inmitten der aufgewühlten Strömungen des Luftreichs zu folgen."}},faq={{q="Wer ist Olariaan Swiftburn?",a="Olariaan Swiftburn ist ein Mitglied der Windformer aus den Reihen der Shen'dorei, das eine angeborene Einstimmung auf das Feuer besitzt. Er weilt am Shrine of Flames, der am Rande des Böenbeerentieflands westlich von Valanaar liegt.",al={"wer vergibt call of fire","zu wem bringe ich die fackel","olariaan swiftburn"}},{q="Wo befindet sich der Shrine of Flames?",a="Der Shrine of Flames befindet sich im Böenbeerentiefland innerhalb des Himmelswalls. Er liegt abgeschieden am Rande der Weite der schwebenden Inseln, direkt westlich von Valanaar.",al={"wo ist der shrine of flames","ort böenbeerentiefland","wie findet man olariaan"}},{q="Warum wird im Himmelswall Feuer studiert?",a="Obwohl der Himmelswall überwiegend die elementare Domäne der Luft ist, bleibt er ein integraler Bestandteil der weiteren Elementarebene. Die Geister aller vier Elemente schwingen für diejenigen, die eingestimmt genug sind, um zuzuhören, immer noch durch seine Weiten.",al={"warum feuer im himmelswall","elementarebene feuer","ist der himmelswall nicht nur luft"}},{q="Was ist die Torch of Dormant Flame?",a="Die Torch of Dormant Flame ist ein elementarer Fokus, der zu Olariaan Swiftburn gebracht wird und als Kanal für einen Initianden dient, der Unterweisung in der Zwiesprache mit dem Feuer sucht.",al={"was ist die schlummernde flamme","torch of dormant flame","welchen gegenstand trage ich"}},{q="Wer sind die Windformer?",a="Die Windformer sind Praktizierende innerhalb des Himmelswalls, die elementare Kräfte lenken und formen, wobei sich unter ihren Reihen Individuen verschiedenster Herkunft wie etwa die Shen'dorei befinden.",al={"wer sind die windformer","windformer fraktion"}},{q="Wozu führt diese Quest?",a="Olariaan Swiftburn unterweist Schüler darin, wie man dem Ruf des Feuers folgt, und betont, dass das Meistern von Urkräften innerhalb der anspruchsvollen Domäne des Himmelswalls große Beharrlichkeit erfordert.",al={"was lehrt olariaan","feuerausbildung himmelswall"}}},fp="12,327,33.414.0,20.363.0,26.202.0,30.164.0,37.225.0,35.162.0,24.170.0,29.180.0"}
P.entries["quest:97244"] = {n="Call of Fire",s="Call of Fire ist eine Quest der Windformer, die die Hinrichtung von Skypriest Faladiel befiehlt, einem ehemaligen Bruder, der seinen Orden für Macht verriet. Abenteurer müssen den abtrünnigen Skypriest im Böenbeerentiefland aufspüren und sein Herz beschaffen, um ein mächtiges Elementarritual zu nähren.",h="Call of Fire ist eine Quest der Windformer, die die Hinrichtung von Skypriest Faladiel befiehlt, einem...",kw={"al'aketh","call of fire","faladiel","faladiels herz","böenbeerentiefland","schrein von akir","himmelspriester faladiel","valanaar","windformer"},ang={["class:Priest"]="Priester dürften Skypriest Faladiels Verderbnis und tiefen Fall bemerkenswert finden, da seine heilige Berufung vom Rufen der Flamme in Verrat und Mord an seinem eigenen Orden verkehrt wurde.",["class:Shaman"]="Schamanen, die mit Feuer und elementaren Riten vertraut sind, werden das unerbittliche, urtümliche Wesen darin erkennen, die Essenz eines Verräters den Flammen zu opfern, um deren heilige Kraft zu verstärken."},sec={{t="Ein Verräter unter den Flammen",b="Call of Fire beauftragt Abenteurer damit, Jagd auf Skypriest Faladiel zu machen, einen ehemaligen Windformer, der seine Loyalitäten aufgab, um sich den Al'Aketh anzuschließen. Einst ein hingebungsvoller Rufer der Flamme, zog Faladiel Macht seiner Gefolgschaft vor, wandte sich gegen seine Ordensbrüder und lud deren Blut auf seine Hände. Die Windformer entsenden einen Beauftragten, um ihr kompromissloses Urteil an ihm zu vollstrecken."},{t="Abrechnung im Tiefland",b="Faladiel hat sich auf einem Bauernhof im Böenbeerentiefland abgeschottet, nordöstlich hinter Valanaar und knapp südlich des Schreins von Akir gelegen. Das Töten des abtrünnigen Skypriests dient mehr als bloßer Rache; die Windformer benötigen sein Herz als schauerliche Zutat für ein bevorstehendes Ritual, da sie glauben, dass der Verzehr des Herzens eines Verräters ihre heiligen Flammen mit unvergleichlicher Intensität brennen lässt."},{t="Blut mit Blut vergolten",b="Nach Erhalt des Herzens bekräftigen die Windformer ihren Kodex, dass Blut mit Blut vergolten werden muss. Doch Faladiels Ende markiert nur eine einzige Phase ihres Werks, da das Herz bloß ein Teil dessen ist, was ihr zeremonielles Feuer speisen muss, bevor ihre Riten abgeschlossen werden können."}},faq={{q="Wer ist Skypriest Faladiel?",a="Skypriest Faladiel war einst ein treuer Rufer der Flamme und ein standhaftes Mitglied der Windformer. Wie viele unter den Al'Aketh gab er seine Loyalitäten im Streben nach Macht auf, wandte sich gegen seine Sippe und befleckte seine Hände mit deren Blut.",al={"wer ist faladiel","faladiel hintergrundgeschichte","himmelspriester faladiel lore"}},{q="Warum wollen die Windformer Faladiels Tod?",a="Die Windformer verlangen nach Vergeltung, weil Faladiel sie für Macht verraten und seine ehemaligen Brüder und Schwestern ermordet hat. Gemäß dem Kodex der Windformer wird Blut mit Blut vergolten, was seine Hinrichtung sowohl zu Gerechtigkeit als auch zu Vergeltung macht.",al={"warum faladiel toeten","warum wollen die windformer faladiels tod","faladiels verrat"}},{q="Warum benötigen die Windformer Faladiels Herz?",a="Faladiels Herz dient als mächtiges Ritualreagenz. Die Windformer glauben, dass die Flammen das Opfer des Herzens eines Verräters gierig verschlingen und dabei heißer sowie weit intensiver brennen, wenn sie damit genährt werden.",al={"warum faladiels herz","wofuer ist das herz","ritualreagenz herz"}},{q="Wo ist Skypriest Faladiel zu finden?",a="Skypriest Faladiel hat auf einem Bauernhof im Böenbeerentiefland Zuflucht gesucht, nordöstlich hinter Valanaar und knapp südlich des Schreins von Akir gelegen.",al={"wo ist faladiel","himmelspriester faladiel aufenthaltsort","faladiel finden"}},{q="Was ist der Kodex der Windformer?",a="Die Windformer sind ein Orden, der an einen strengen und unerbittlichen Kodex gebunden ist, nach dem Verrat niemals vergessen und Blut stets mit Blut vergolten wird. Sie praktizieren das Rufen von Flammen und heilige Elementarrituale.",al={"wer sind die windformer","kodex der windformer","fraktion der windformer"}},{q="Welche Verbindung haben die Al'Aketh zu dieser Mission?",a="Die Al'Aketh sind eine Fraktion oder Gruppe, von der bekannt ist, dass ihre Mitglieder frühere Loyalitäten und Ehre gegen persönliche Macht eingetauscht haben, wobei Faladiel ein prominentes Beispiel unter ihren Skypriests darstellt.",al={"was sind die alaketh","faladiel alaketh","verraeter der alaketh"}}},fp="12,272,25.371.0,25.392.0,21.268.1,26.241.0,44.220.0,45.205.0,38.146.0,37.197.0,50.204.0"}
P.entries["quest:97245"] = {n="Call of Fire",s="Call of Fire ist eine Quest, in der Abenteurer von Olariaan Swiftburn damit beauftragt werden, den uralten Waldgeist Kuramaa im Shen'darhochland ausfindig zu machen und zu konfrontieren. Indem Reisende den Geist aus seinem Baumstumpf herbeirufen und ihn mit Flammen besiegen, erhalten sie seine mächtige hölzerne Maske. Das Relikt wird anschließend in das Böenbeerentiefland gebracht, um eine ewige Flamme zu entzünden und mit den Geistern des Feuers in Zwiesprache zu treten.",h="Call of Fire ist eine Quest, in der Abenteurer von Olariaan Swiftburn damit beauftragt werden, den uralten...",kw={"anchor pylon","call of fire","waldgeist","böenbeerentiefland","kuramaa","kuramaas maske","olariaan swiftburn","shen'darhochland"},ang={["class:Mage"]="Kuramaa ist gegenüber den meisten magischen Disziplinen äußerst widerstandsfähig, was Zauberkundige dazu zwingt, sich ausschließlich auf Feuermagie zu verlassen, um den Geist zu bezwingen.",["class:Shaman"]="Obwohl dieser Ritus den Namen mit traditionellen schamanischen Prüfungen des Feuers teilt, konzentriert er sich darauf, einen widerstandsfähigen Hochlandgeist mit Flammen zu unterwerfen, um Kraft für die Zwiesprache mit Feuergeistern zu sammeln."},sec={{t="Der Geist des Hochlands",b="Im Shen'darhochland flüstern einheimische Bewohner Geschichten über Kuramaa, einen uralten Waldgeist, der im Inneren eines verdrehten Baumstumpfs auf dem Gipfel eines Hügels nahe dem regionalen Anchor Pylon haust. Um das zurückgezogen lebende Wesen ins Freie zu locken, muss ein Herausforderer mit bloßer Faust gegen die Rinde seiner hölzernen Behausung schlagen, dessen Erscheinen fordern und seinen Mut im Kampf auf die Probe stellen."},{t="Feuer und Holz",b="Kuramaa zu bezwingen ist keine einfache Aufgabe für jene, die arkane oder göttliche Mächte wirken, da der Geist über tiefe natürliche Schutzresistenzen gegen die meisten Formen von Magie verfügt. Nur sengende Flammen können seine uralte Rinde durchdringen und ihn zu Fall bringen. Das Besiegen der Kreatur bringt Kuramaas hölzerne Maske ein, ein Artefakt, das von großer Macht erfüllt ist. Dennoch ist Kuramaa ewig und dazu bestimmt, sich neu zu formieren und sich erneut zu manifestieren, wenn er gerufen wird."},{t="Die ewige Flamme",b="Unten im Böenbeerentiefland wartet Olariaan Swiftburn auf die Beschaffung von Kuramaas Maske. Das verzauberte hölzerne Relikt dient als Katalysator für eine esoterische Zeremonie: das Entzünden einer ewigen Flamme, um direkt mit den Geistern des Feuers zu kommunizieren, wodurch uralte elementare Zwiesprache durch das Bezwingen von Naturgeistern des Hochlands freigeschaltet wird."}},faq={{q="Wer ist Kuramaa?",a="Kuramaa ist ein uralter Waldgeist, der im Shen'darhochland haust. Laut einheimischen Bewohnern des Hochlands befindet sich seine Behausung in einem verdrehten Baumstumpf auf dem Gipfel eines Hügels nahe dem Highlands Anchor Pylon.",al={"wer ist kuramaa","kuramaa geschichte","was ist kuramaa"}},{q="Wer ist Olariaan Swiftburn?",a="Olariaan Swiftburn ist der Ritualist, der Abenteurer damit beauftragt, Kuramaa gegenüberzutreten. Im Böenbeerentiefland stationiert, benötigt Olariaan Kuramaas hölzerne Maske, um einen heiligen Ritus des Feuers durchzuführen.",al={"wer vergibt call of fire","wer ist olariaan swiftburn","wo call of fire abgeben"}},{q="Wie beschwört Ihr Kuramaa?",a="Kuramaa lebt in einem verdrehten Baumstumpf auf dem Gipfel eines Hügels nahe dem Anchor Pylon im Shen'darhochland. Um den Geist zum Kampf herbeizurufen, muss man fest mit der Faust gegen die Rinde seines Stumpfs schlagen.",al={"wie beschwört man kuramaa","wo ist kuramaas baumstumpf","waldgeist beschwören"}},{q="Wogegen ist Kuramaa im Kampf verwundbar?",a="Kuramaa besitzt einen außergewöhnlichen natürlichen Widerstand gegen die meisten Formen von Magie. Nur die Berührung einer Flamme kann seine Verteidigung überwinden und den uralten Waldgeist im Kampf zu Fall bringen.",al={"kuramaa schwächen","wie besiegt man kuramaa","kuramaa magieimmun"}},{q="Warum benötigt Olariaan Swiftburn Kuramaas Maske?",a="Kuramaas hölzerne Maske gilt als Gefäß beträchtlicher Macht. Olariaan Swiftburn nutzt dieses mächtige Relikt als wesentlichen Bestandteil, um eine ewige Flamme zu entzünden und direkt mit Feuergeistern zu kommunizieren.",al={"warum kuramaas maske sammeln","was bewirkt die maske","zweck von kuramaas maske"}},{q="Wird Kuramaa bei einer Niederlage dauerhaft vernichtet?",a="Kuramaa ist eher ein ewiger Waldgeist als eine sterbliche Kreatur. Obwohl seine physische Manifestation besiegt wird, um seine Maske zu erlangen, überdauert der Geist und wird sich bei Bedarf erneut manifestieren.",al={"ist kuramaa tot","habe ich kuramaa getötet","kuramaa respawn geschichte"}}},fp="12,388,27.364.0,13.383.0,17.323.1,15.225.0,26.194.0,26.194.0,40.174.0,48.207.0,47.191.0"}
P.entries["quest:97246"] = {n="Meal Appeal",s="Meal Appeal ist eine Besorgung in Orgrimmar, die von Thatog vergeben wird, einem Orc, der durch seine täglichen Pflichten gebunden ist und sich sorgt, dass sein junger Sohn Migi Mahlzeiten auslässt, um zu spielen. Reisende werden gebeten, ein zubereitetes Mittagessen von Borstan's Firepit abzuholen und Migi aufzuspüren, der hinter Grommash Hold spielt. Sie bietet einen bodenständigen Einblick in das häusliche Familienleben innerhalb der Hauptstadt der Horde.",h="Meal Appeal ist eine Besorgung in Orgrimmar, die von Thatog vergeben wird, einem Orc, der durch seine...",kw={"borstan","borstans firepit","grommash hold","mittagessen-lieferung","meal appeal","migi","orgrimmar","thatog"},ang={["faction:Horde"]="Das Leben innerhalb der Mauern von Orgrimmar dreht sich nicht ausschließlich um Kriegsführung und Verteidigung; alltägliche Angelegenheiten wie die Versorgung von Kindern, die durch das Tal der Stärke rennen, halten die Gemeinschaft der Stadt am Leben.",["race:Orc"]="Selbst in der rauen Kultur der Orcs sorgen sich Eltern wie Thatog darum, dass ihre Kinder beim Spielen in den Straßen von Durotars Hauptstadt ihre Mahlzeiten vernachlässigen."},sec={{t="Die Pflicht eines Elternteils in Orgrimmar",b="In den geschäftigen roten Felsstraßen von Orgrimmar geht das alltägliche häusliche Leben neben den Übungen der Grunt-Krieger und den Machenschaften der Horde weiter. Thatog, der durch seine Pflicht an seinen täglichen Posten gebunden ist, sieht sich außerstande, ein wachsames Auge auf seinen energiegeladenen jungen Sohn Migi zu haben. Sich selbst überlassen, verbringt Migi die Zeit von morgens bis zur Dämmerung damit, mit seinen Freunden durch die Straßen der Stadt zu sausen, wobei er stets seinen Magen vernachlässigt, bis er ausgehungert nach Hause zurückkehrt."},{t="Lieferung hinter the Hold",b="Anstatt den Jungen einen weiteren Nachmittag hungern zu lassen, arrangiert Thatog eine warme Mahlzeit bei Borstan's Firepit. Da Migi sich nicht die Mühe machen wird, seine Spiele zu unterbrechen, um das Mittagessen selbst abzuholen, bittet Thatog vorbeikommende Abenteurer, als persönlicher Bote zu fungieren. Die Besorgung führt Reisende von Borstans Kochfeuer zum offenen Platz hinter Grommash Hold, wo Migi und die übrigen Jugendlichen der Nachbarschaft fast immer in ihre Kinderspiele vertieft anzutreffen sind."}},faq={{q="Wer ist Thatog?",a="Thatog ist ein vielbeschäftigter Orc-Elternteil, der in Orgrimmar stationiert ist und dessen tägliche Pflichten ihn daran hindern, sich zu entfernen, um seinen jungen Sohn Migi zu beaufsichtigen. Aus Sorge, dass Migi beim Spielen mit Freunden seine Mahlzeiten auslässt, heuert Thatog einen hilfsbereiten Abenteurer an, um Essen für den Jungen abzuholen und zu überbringen.",al={"wer ist thatog","questgeber thatog","thatog orgrimmar"}},{q="Wo ist Migi zu finden?",a="Migi verbringt seine Tage damit, mit seinen Freunden in der Hauptstadt Spiele zu spielen. Thatog merkt an, dass die Kinder fast mit Sicherheit beim Herumtoben und Spielen hinter Grommash Hold in Orgrimmar anzutreffen sind.",al={"wo ist migi","migi standort","migi finden"}},{q="Was ist Borstan's Firepit?",a="Borstan betreibt Borstan's Firepit, eine örtliche Gaststätte in Orgrimmar. Thatog bittet Reisende, zuerst dort vorbeizuschauen und Borstan mitzuteilen, dass sie ein vorbestelltes Mittagessen abholen, um es Migi persönlich zu überbringen.",al={"wo ist borstan firepit","borstans firepit standort","borstan mittagessen"}},{q="Warum vergisst Migi zu essen?",a="Wie viele energiegeladene junge Orcs ist Migi so sehr darin vertieft, den ganzen Tag mit seinen Freunden hinter Grommash Hold zu spielen, dass er vergisst oder darauf verzichtet, für etwas zu essen bei Borstan's Firepit vorbeizuschauen, sodass er am Ende des Tages häufig völlig ausgehungert nach Hause kommt.",al={"warum lässt migi das mittagessen aus","migi hungert","warum isst migi nicht"}},{q="Wer ist Migi?",a="Migi ist der junge Sohn von Thatog. Er streift durch Orgrimmar und spielt mit einer Gruppe von Freunden, wobei er seiner Spielzeit den Vorzug vor der Rückkehr nach Hause oder dem Abholen seiner vorbereiteten Mahlzeiten gibt.",al={"wer ist migi","migi orc-kind","thatogs sohn"}},{q="Was ist das Ziel von Meal Appeal?",a="Die Aufgabe erfordert es, bei Borstan's Firepit vorbeizuschauen, um Borstan mitzuteilen, dass Thatog Euch geschickt hat, um Migis Mittagessen abzuholen, und das Essen dann direkt zu Migi hinter Grommash Hold zu bringen, damit der Junge während seiner Spiele nicht hungert.",al={"meal appeal questziel","was bei meal appeal zu tun ist","meal appeal aufgabe"}}},fp="11,345,28.451.0,24.448.0,14.291.0,24.193.0,26.210.0,28.247.0,12.170.0,37.216.0"}
P.entries["quest:97249"] = {n="Favorite Food",s="Favorite Food ist eine Quest in Orgrimmar rund um Migi, einen verspielten Jugendlichen hinter Grommash Hold, dessen Eltern sich sorgen, dass er nicht genug isst. Um seinen Gaumen zu erweitern, ohne ihn hungrig zu lassen, bereitet Borstan von Borstan's Meats ein abwechslungsreiches Mittagessen zu, gewürzt mit Migis geliebten Sweetglaze-Grieben. Die Lieferung sorgt dafür, dass der Junge und seine Freunde ihre Spiele unterbrechen, um eine gesunde Mahlzeit zu genießen.",h="Favorite Food ist eine Quest in Orgrimmar rund um Migi, einen verspielten Jugendlichen hinter Grommash Hold...",kw={"borstan","borstan's meats","favorite food","grommash hold","hog belly","mittagessen","migi","orgrimmar","sweetglaze"},ang={["faction:Horde"]="Diese Quest bietet einen Einblick in den alltäglichen häuslichen Alltag in Orgrimmar und zeigt, wie örtliche Handwerker und Familien dafür sorgen, dass die Kinder der Hauptstadt ernährt und umsorgt werden.",["profession:Cooking"]="Die Aufgabe veranschaulicht praktisches kulinarisches Handwerk in der Hauptstadt der Horde, indem knusprige geräucherte Hog-Belly-Grieben zu einer geschmackvollen Würze für die täglichen Mahlzeiten wiederverwendet werden."},sec={{t="Appetit auf Spiel",b="Hinter dem Sitz der Macht der Horde in Grommash Hold verbringen der junge Migi und seine Freunde ihre Nachmittage damit, entlang der staubigen Pfade von Orgrimmar Spiele zu spielen. Migis Eltern sorgen sich jedoch, dass der Junge beim Spielen oft seine Mahlzeiten vernachlässigt und seinen Bauch nicht füllt. Um sicherzustellen, dass er regelmäßig Nahrung erhält, wandten sie sich an Borstan's Meats, um tägliche Lunchpakete zubereiten zu lassen. Seine Eltern knüpften jedoch eine strenge Bedingung daran: Borstan darf nicht jeden Tag die exakt gleiche Mahlzeit servieren, da sie darauf bestehen, dass Migi eine Wertschätzung für abwechslungsreiche Speisen entwickelt, anstatt sich auf ein einziges Lieblingsgericht zu verlassen."},{t="Der Sweetglaze-Kompromiss",b="Borstan stand vor einer kulinarischen Herausforderung, da Migi notorisch auf Sweetglazed-Hog-Belly-Sandwiches fixiert war und verlässlich nur dann zum Mittagessen erschien, wenn die Räucherei von ihrem süßen Duft erfüllt war. Um dem Wunsch der Eltern nach Abwechslung nachzukommen und den Jungen gleichzeitig wohlgenährt zu halten, erdachte der Metzger eine erfinderische Lösung. Wenn glasierter Schweinebauch zubereitet wird, werden die übrig gebliebenen knusprigen, glasierten Grieben zu einer herzhaften Würze zerbröselt, die über jedes Gericht gestreut werden kann. Hinter Grommash Hold abgeliefert, überzeugte das duftende Topping Migi und seine Gefährten erfolgreich, ihr Spiel zu unterbrechen und gemeinsam das Mittagessen zu teilen."}},faq={{q="Wer ist Migi?",a="Migi ist ein junger Bewohner von Orgrimmar, der seine Tage damit verbringt, mit Freunden hinter Grommash Hold zu spielen. Da er sich völlig in seine Spiele vertieft, sorgen sich seine Eltern, dass er es versäumt, genug zu essen, um seinen Bauch zu füllen, weshalb sie tägliche Essenslieferungen von Borstan's Meats organisierten.",al={"migi orgrimmar","wer ist das kind hinter grommash hold","migi mittagessen"}},{q="Wer vergibt die Quest Favorite Food?",a="Die Quest wird von Borstan von Borstan's Meats in Orgrimmar vergeben. Nachdem er von den Sorgen der Eltern bezüglich Migis Ernährung und Essgewohnheiten erfahren hat, bereitet Borstan eine besondere Mahlzeit zu, die den Gaumen des Jungen erweitern soll.",al={"favorite food questgeber","wer startet favorite food","borstan favorite food"}},{q="Wo ist Migi zu finden?",a="Migi befindet sich hinter Grommash Hold in Orgrimmar, wo er sich mit anderen einheimischen Kindern zum Spielen trifft. Die Jugendlichen kommen häufig am Weg zur Festung vorbei und erkennen Borstans tägliche kulinarische Spezialitäten allein an ihrem Duft.",al={"migi aufenthaltsort","wo ist migi","wohin migis mittagessen liefern","migi in orgrimmar finden"}},{q="Was ist Migis Lieblingsessen?",a="Migis Lieblingsessen ist das Sweetglazed-Hog-Belly-Sandwich aus der Räucherei von Borstan's Meats. Wann immer die Räucherei in Betrieb ist, kann man sich darauf verlassen, dass Migi pünktlich zum Mittagessen erscheint, angelockt von dem unverwechselbaren Aroma, das in Richtung Grommash Hold zieht.",al={"was isst migi gerne","migis lieblingsessen","sweetglazed hog belly migi"}},{q="Warum bitten Migis Eltern um unterschiedliche Mahlzeiten?",a="Migis Eltern baten Borstan darum, nicht jeden Tag genau die gleiche Mahlzeit einzupacken, damit ihr Sohn einen Geschmack für mehr als nur ein Gericht entwickelt. Obwohl sie möchten, dass er genug isst, wollen sie, dass er einen vielseitigen Appetit aufbaut, anstatt sich rein von Sweetglazed-Schweinefleisch zu ernähren.",al={"warum migis mittagessen aendern","bitte von migis eltern","warum nicht jeden tag sweetglazed sandwiches"}},{q="Wie bringt Borstan Migi dazu, verschiedene Speisen zu essen?",a="Borstan zerbröselt die übrig gebliebenen knusprigen, glasierten Stücke des geräucherten Hog Belly zu einem Topping, das über verschiedene Gerichte gestreut werden kann. Dieser kräftige, vertraute Sweetglaze-Geschmack ermöglicht es Borstan, abwechslungsreiche Mahlzeiten zu servieren, die Migi dennoch bis auf den letzten Bissen mit Freude verzehrt.",al={"borstans trick","wie bringt borstan migi zum essen","sweetglaze kruemel"}},{q="Was ist Borstan's Meats?",a="Borstan's Meats ist eine Räucherei und Metzgerei in Orgrimmar, die dafür bekannt ist, Hog-Belly-Sandwiches zu räuchern und verpackte Mahlzeiten für Stadtbewohner zuzubereiten. Borstan nutzt seine kulinarischen Talente, um die Jugendlichen des Viertels stets gut zu versorgen.",al={"borstans meats orgrimmar","wo ist borstans meats","was ist borstan"}}},fp="13,381,20.574.0,25.604.0,12.289.0,34.224.0,24.241.0,29.245.0,46.267.0,49.267.0,24.229.0"}
P.entries["quest:97253"] = {n="Parts and Pieces",s="Parts and Pieces ist eine Beschaffungsquest, die von Wrenix der Jämmerliche in der Hafenstadt Ratschet angeboten wird. Nachdem mehrere Mercenaries das Aufeinandertreffen mit den örtlichen Piraten nicht überlebt hatten, setzte Wrenix eine mechanische Vorrichtung ein, um die Bedrohung zu beseitigen – nur damit die Plünderer sie in Altmetall zerlegten. Abenteurer haben die Aufgabe, zum oberen Lager der Piraten aufzubrechen, um die verstreuten Maschinenteile zu bergen, bevor weiterer Schaden entsteht.",h="Parts and Pieces ist eine Beschaffungsquest, die von Wrenix der Jämmerliche in der Hafenstadt Ratschet...",kw={"komplizierte teile","maschine","parts and pieces","pirat","piraten","ratschet","krummsäbel","oberes piratenlager","wrenix der jämmerliche"},ang={["profession:Engineering"]="Tüftler und Ingenieure können die Ironie nachempfinden, wenn eine hochentwickelte mechanische Vorrichtung primitiver Piraterie zum Opfer fällt. Die Bergung von Wrenix' komplizierten Teilen bietet eine Mahnung aus erster Hand über die Gefahren, automatisierte Prototypen ohne angemessene physische Schutzmaßnahmen in feindliche Lager zu entsenden."},sec={{t="Eine mechanische Lösung",b="Die Piratenaktivitäten entlang der Küste südlich von Ratschet bereiten den Bewohnern und Händlern der Hafenstadt zunehmend Schwierigkeiten. Um den Marodeuren beizukommen, ohne noch mehr Geld für entbehrliche Mietlinge zu riskieren, nahm der Tüftler Wrenix der Jämmerliche die Angelegenheit selbst in die Hand. Nachdem fünf oder sechs Mercenaries ausgesandt worden waren und allesamt nicht lebend zurückkehrten, erdachte Wrenix eine scheinbar geniale Alternative: Er schickte eine automatisierte Maschine, um sich der Räuber anzunehmen. Anstatt ein weiteres Lebewesen in Gefahr zu bringen, wurde das mechanische Konstrukt losgeschickt, um das Problem im Lager selbstständig zu lösen."},{t="Krummsäbel und Schraubenzieher",b="Der erfinderische Einsatz verlief jedoch nicht so reibungslos wie geplant. Die Piraten, welche die Lager südlich der Stadt besetzt hielten, erwiesen sich mit ihren Klingen als überraschend einfallsreich und stellten rasch fest, dass geschwungene Krummsäbel auch als behelfsmäßige Schraubenzieher dienen konnten. Noch bevor Wrenix Anweisungen übermitteln konnte, die Maschine zum Rückzug nach Ratschet zu bewegen, hebelten die Marodeure den Mechanismus auseinander und verstreuten seine empfindlichen Komponenten über ihr gesamtes oberes Lager. Statt die Piratenpräsenz auszuschalten, benötigt der Erfinder nun einen wagemutigen Kundschafter, der sich in das Lager schleicht und fünf Handvoll der im Staub zurückgelassenen, komplizierten mechanischen Teile einsammelt."}},faq={{q="Wer ist Wrenix der Jämmerliche?",a="Wrenix der Jämmerliche ist ein exzentrischer Tüftler, der in der neutralen Hafenstadt Ratschet lebt. Angesichts einer aggressiven Bande von Marodeuren an der Küste im Süden versuchte Wrenix, das Piratenproblem durch technologische Innovation zu lösen. Nachdem mehrere angeheuerte Mercenaries ihre Missionen nicht überlebt hatten, baute und entsandte er eine automatisierte Maschine, um die Bedrohung zu bekämpfen – nur um mitzuerleben, wie sie rasch zerlegt wurde.",al={"wer ist wrenix","wrenix der jämmerliche lore","ratschet wrenix"}},{q="Was geschah mit den früheren Mercenaries, die Wrenix angeheuert hatte?",a="Bevor er zu mechanischer Automation griff, heuerte Wrenix fünf oder sechs verschiedene Abenteurer an, um die Piratenbedrohung südlich von Ratschet zu beseitigen. Nicht ein einziger dieser Auftragnehmer kehrte lebend zurück, was beweist, wie tödlich und gut verteidigt die Piratenlager tatsächlich sind. Ihr düsteres Schicksal veranlasste Wrenix zu dem Schluss, dass es sowohl ineffizient als auch fatal war, sich auf Mercenaries aus Fleisch und Blut zu verlassen.",al={"wrenix frühere mercenaries","was geschah mit den anderen abenteurern","wen schickte wrenix zuerst"}},{q="Warum schickte Wrenix eine Maschine gegen die Piraten?",a="Wrenix konstruierte und entsandte eine mechanische Vorrichtung, da seine früheren Versuche mit lebenden Mercenaries zu völligem Versagen und Verlusten von Menschenleben geführt hatten. Im Glauben, dass eine Schöpfung aus Uhrwerk dort Erfolg haben könnte, wo sterbliche Kämpfer fielen – oder zumindest weitere Verluste verhindert würden –, schickte er die Maschine direkt in das Lager und erwartete, dass mechanischer Erfindungsgeist die Piraten bezwingen würde.",al={"warum eine maschine schicken","wrenix roboterplan","warum nutzte wrenix eine vorrichtung"}},{q="Wie haben die Piraten Wrenix' Maschine zerlegt?",a="Die Piraten erwiesen sich als überraschend erfinderisch, als sie mit Wrenix' Konstrukt konfrontiert wurden. Indem sie ihre geschwungenen Krummsäbel als behelfsmäßige Schraubenzieher nutzten, brachen die Räuber die Maschine rasch auseinander, noch bevor Wrenix Befehle übermitteln konnte, sie zurück nach Ratschet zu leiten. Sie zerlegten die Vorrichtung bis auf ihr Gerüst und verstreuten ihre komplizierten Komponenten über ihr gesamtes Lager.",al={"wie wurde die maschine zerstört","wie zerlegten piraten den roboter","piraten krummsäbel schraubenzieher"}},{q="Wo befinden sich die komplizierten Teile?",a="Die Bauteile von Wrenix' zerstörter Maschine befinden sich im oberen Piratenlager an der Küste südlich von Ratschet. Nachdem sie die Vorrichtung mit ihren Krummsäbeln ausgeschlachtet hatten, ließen die Piraten ihre filigranen Teile auf dem Boden ihres Hügellagers verstreut zurück. Abenteurer müssen sich in das Lager schleichen und fünf Handvoll dieser komplizierten Teile einsammeln.",al={"wo sind die teile","oberes piratenlager ort","handvoll komplizierter teile fundort"}},{q="Warum hält Wrenix diesen Bergungsauftrag für sicherer?",a="Wrenix glaubt, dass dieser Auftrag weitaus bessere Überlebenschancen bietet, da es sich um eine reine Bergungsaktion und nicht um einen offenen Angriff handelt. Die früheren Mercenaries waren angewiesen worden, die Piratenpräsenz direkt auszulöschen, wohingegen diese Beschaffungsmission lediglich erfordert, sich in das obere Lager zu schleichen, fünf Handvoll verstreuter Maschinenteile aus dem Schmutz aufzulesen und nach Ratschet zurückzukehren.",al={"ist parts and pieces sicher","warum glaubt wrenix dass ihr überlebt","wrenix überlebenschancen"}},{q="Wofür werden die komplizierten Teile benötigt?",a="Die komplizierten Teile sind die spezialisierten Zahnräder, Federn und präzisen mechanischen Beschläge, die Wrenix' automatisiertes Konstrukt antrieben. Da sein Versuch, das Piratenproblem zu lösen, damit endete, dass die Maschine zerlegt wurde, benötigt Wrenix diese empfindlichen Stücke zurück, damit seine wertvolle Ingenieurskunst und die Materialien nicht völlig vergeudet sind.",al={"was sind komplizierte teile","warum braucht wrenix die teile","was macht wrenix mit den teilen"}}},fp="16,415,21.598.0,26.644.0,27.407.0,54.378.0,51.380.0,47.374.0,40.364.0,56.400.0,42.357.0"}
P.entries["quest:97257"] = {n="Call of Fire",s="Call of Fire ist ein schamanischer Übergangsritus, der von den Windformern im Himmelswall beaufsichtigt wird. Initianden müssen dabei helfen, Geister der Flamme herbeizurufen, die Eternal Flame einzufangen und in einem Wettlauf gegen die Zeit die Feuerschale bei Valanaar zu entzünden. Das erfolgreiche Abschließen der Prüfung beweist den Respekt vor den Elementen und bringt dem Initianden sein Feuertotem ein.",h="Call of Fire ist ein schamanischer Übergangsritus, der von den Windformern im Himmelswall beaufsichtigt wird.",kw={"call of fire","eternal flame","feuertotem","firelands","olariaan","der himmelswall","valanaar","windformer"},ang={["class:Shaman"]="Dieser Ritus markiert eine entscheidende Initiation für Schamanen, gewährt ihnen die Meisterschaft über das Feuer und verleiht ihnen nach Abschluss ihr Feuertotem.",["race:Skyborne"]="Diese von den Windformern im Himmelswall verwaltete Prüfung spiegelt die schamanischen Traditionen der Skyborne wider, die die Elementarebenen ehren."},sec={{t="Das Ritual der Flamme",b="Das Call of Fire ist eine heilige Prüfung der elementaren Einstimmung, die im Himmelswall durchgeführt wird. Angeführt von Olariaan von den Windformern versammeln sich Initianden am Brazier of Offering, um die Geister der Flamme aus den Firelands herbeizurufen. Wenn die Opfergaben als würdig erachtet werden, entzünden die Geister den Altar mit der heiligen Eternal Flame, bereit, von einem würdigen Anwärter genutzt zu werden."},{t="Die Reise nach Valanaar",b="Sobald sie entzündet ist, muss die Eternal Flame auf einer Fackel eingefangen und zügig durch den Himmelswall nach Valanaar getragen werden. Da die Energien der Firelands in der wirbelnden Atmosphäre des elementaren Luftreichs natürlicherweise schwächer werden und sich verflüchtigen, steht der Initiand vor einem Wettlauf gegen die Zeit, um den Brazier of Eternal Flames zu erreichen, bevor die Flamme erlischt."},{t="Das Feuertotem",b="Das Neuentfachen der Feuerschale bei Valanaar beweist die Disziplin und Ehrfurcht des Initianden gegenüber den Elementen. Als Anerkennung dieser Leistung verleihen die Windformer dem Initianden sein Feuertotem. Wie von den Ältesten gelehrt, dient elementare Macht bereitwillig jenen, die sie respektieren, wird aber diejenigen gnadenlos verzehren, die dies nicht tun."}},faq={{q="Was ist das Call of Fire?",a="Call of Fire ist ein heiliger Übergangsritus, bei dem ein angehender Schamane dabei hilft, Geister der Flamme herbeizurufen und die Eternal Flame einzufangen. Das Tragen dieses Sacred Fire nach Valanaar beweist den Respekt des Initianden vor der Elementarebene und gewährt ihm sein Feuertotem.",al={"was ist call of fire","call of fire quest","worum geht es in dieser quest"}},{q="Wer ist Olariaan?",a="Olariaan ist der Ritualleiter, der die Zeremonie am Brazier of Offering leitet. Er legt die notwendigen Materialien auf den Altar und ruft die Geister der Flamme herbei, um die Eternal Flame zu entzünden.",al={"wer ist olariaan","olariaan rolle","wer startet das ritual"}},{q="Was ist die Eternal Flame?",a="Die Eternal Flame ist eine Manifestation der Geister der Flamme, die während des Windformer-Rituals aus den Firelands herbeigerufen werden. Initianden müssen sie auf einer Fackel einfangen und den Brazier of Eternal Flames in Valanaar entzünden.",al={"was ist die eternal flame","eternal flame himmelswall"}},{q="Warum muss die Flamme schnell nach Valanaar getragen werden?",a="Das herbeigerufene rohe Elementarfeuer stammt aus den Firelands, und seine intensive Hitze verflüchtigt sich schnell im luftbeherrschten Reich des Himmelswalls. Initianden müssen sich zügig bewegen, um sicherzustellen, dass die Fackel nicht erlischt, bevor sie Valanaar erreichen.",al={"warum verflüchtigt sich die eternal flame","warum nach valanaar eilen","flammen der firelands himmelswall"}},{q="Wer sind die Windformer?",a="Die Windformer sind ein im Himmelswall ansässiger Orden, der Initianden durch elementare Prüfungen leitet. Sie achten das Gleichgewicht und die Macht der Elementarebenen und beaufsichtigen die Vergabe von Totems.",al={"wer sind die windformer","windformer fraktion"}},{q="Was ist die Belohnung für den Abschluss der Prüfung?",a="Das Abschließen des Rituals und das erfolgreiche Wiederanzünden der Feuerschale in Valanaar bringt dem Initianden sein Feuertotem ein, ein unverzichtbares Werkzeug und ein Fokus zum Kanalisieren feuriger Elementarkräfte.",al={"call of fire belohnung","feuertotem belohnung","was bekommt man bei call of fire"}}},fp="12,332,19.355.0,23.333.0,14.322.0,25.262.0,16.197.0,26.213.0,50.237.0,24.187.0,44.172.0"}
P.entries["quest:97263"] = {n="Your Package Has Arrived",s="„Your Package Has Arrived“ ist eine dringende Kurieraufgabe bezüglich fehlgeleiteter Post, die für die Zustellung in Eisenschmiede bestimmt ist. Eine Kurierkiste, die den weiten Weg von der Wildhammerfeste Nistgipfel geschickt wurde, wurde neben einem Briefkasten zurückgelassen, ausdrücklich an Eldrun Stormbreaker adressiert. Reisende, die das Paket entdecken, haben die Aufgabe, seine Reise zu vollenden und dafür zu sorgen, dass es seinen rechtmäßigen Besitzer erreicht.",h="„Your Package Has Arrived“ ist eine dringende Kurieraufgabe bezüglich fehlgeleiteter Post, die für die...",kw={"nistgipfel","eldrun stormbreaker","eisenschmiede","briefkasten","verlegtes paket","dringende lieferung","wildhammer","your package has arrived"},ang={["faction:Alliance"]="Die Aufrechterhaltung offener und verlässlicher Kommunikationswege zwischen dem Hinterland und Eisenschmiede ist für die Interessen der Allianz in ganz Khaz Modan und den nördlichen Gebieten von entscheidender Bedeutung.",["race:Dwarf"]="Zwerge werden die starken Bande zwischen den Bronzebärten von Eisenschmiede und ihren Wildhammer-Vettern in Nistgipfel erkennen, was die sichere Ankunft dieses Pakets zu einer Frage des Klanrespekts macht."},sec={{t="Fehlgeleitete Fracht",b="Ein Missgeschick bei der Post führt dazu, dass mehrere herrenlose Pakete neben einem städtischen Briefkasten zurückgelassen werden – ungeschützt im Freien, anstatt sicher an ihren Bestimmungsort gebracht zu werden. Inmitten dieses durcheinandergewürfelten Haufens vernachlässigter Fracht liegt ein dringendes Paket, das für die Zustellung aus dem fernen Nistgipfel bestimmt ist, der Bergfestung der Wildhammerzwerge im Hinterland. Der Transport von Gütern zwischen abgelegenen Außenposten quer durch Khaz Modan und Lordaeron kann gefährlich und chaotisch sein, weshalb verlegte Pakete gelegentlich einen aufmerksamen Passanten erfordern, der einspringt und die Lieferroute ordnungsgemäß zu Ende führt."},{t="Ein Paket für Eldrun Stormbreaker",b="Das verlegte Paket trägt eine deutliche Beschriftung, die Eisenschmiede als Bestimmungsort und Eldrun Stormbreaker als endgültigen Empfänger ausweist. Ausdrücklich mit einem Eilvermerk versehen, wurde die Fracht des Bündels als wichtig genug erachtet, um von den urigen Gipfeln des Hinterlands zu den unterirdischen Hallen der Zwergenhauptstadt befördert zu werden. Wer die Kiste an sich nimmt, übernimmt die Verantwortung des Postdienstes und sorgt dafür, dass Eldrun erhält, was über Gebirgskämme und wilde Hügel gesandt wurde, bevor es gestohlen oder gänzlich vergessen werden kann."}},faq={{q="Was ist das Paket, das am Briefkasten gefunden wurde?",a="Das Paket ist eine dringende Lieferung aus Nistgipfel im Hinterland, adressiert an einen Empfänger namens Eldrun Stormbreaker in Eisenschmiede. Es scheint neben mehreren anderen Paketen in der Nähe eines Briefkastens verlegt worden zu sein, anstatt sein endgültiges Ziel über die normale Kurierzustellung zu erreichen.",al={"was ist das paket","verlegtes paket","was lag am briefkasten","briefkastenpaket"}},{q="Wer ist Eldrun Stormbreaker?",a="Eldrun Stormbreaker ist der vorgesehene Empfänger des verlegten Pakets in der Zwergenhauptstadt Eisenschmiede. Während das Paket selbst deutlich mit diesem Namen gekennzeichnet und als dringend vermerkt ist, wird auf dem Versandetikett kaum Weiteres preisgegeben, bis die Lieferung sicher in diesen Händen liegt.",al={"wer ist eldrun stormbreaker","eldrun stormbreaker","wer bekommt das paket","paketempfaenger"}},{q="Von wo wurde das Paket abgeschickt?",a="Die Sendung stammte aus Nistgipfel, der bedeutenden Siedlung und Festung des Wildhammerklans hoch in den Bergen des Hinterlands. Das Etikett zeigt, dass sie durch verschiedene Regionen in Richtung Eisenschmiede transportiert wurde, bevor sie nahe einem örtlichen Briefkasten entlang der Route verlegt wurde.",al={"woher kam das paket","herkunft des pakets","von wo wurde es verschickt","nistgipfel lieferung"}},{q="Warum wurde das Paket als dringend gekennzeichnet?",a="Das Versandetikett trägt einen Eilvermerk, da der Absender der Kiste aus Nistgipfel ihren Inhalt oder den Zeitpunkt ihrer Ankunft als äußerst wichtig einstufte. Angesichts der Entfernung zwischen den Hochlanden der Wildhammer und der Stadt Eisenschmiede könnte verzögerte Fracht für Eldrun Stormbreaker erhebliche Schwierigkeiten bedeuten.",al={"warum ist es dringend","dringende lieferung","was ist im paket","warum dringend"}},{q="Warum blieb das Paket an einem Briefkasten liegen?",a="Mehrere Pakete wurden unerklärlicherweise neben dem Briefkasten zurückgelassen, anstatt von örtlichen Kurieren sortiert und verteilt zu werden. Hohes Kurieraufkommen, logistische Verwirrung oder schlichte Nachlässigkeit führen oft dazu, dass Fracht während des Transports vorübergehend verlegt wird, sodass es hilfsbereiten Abenteurern obliegt, dieses Versäumnis zu beheben.",al={"warum wurde es zurueckgelassen","warum wurde das paket abgelegt","verlorene post","verlegte pakete"}},{q="Wohin muss dieses Paket geliefert werden?",a="Das Paket ist für die Zustellung nach Eisenschmiede bestimmt, gezielt in die Hände von Eldrun Stormbreaker. Wer die verlegte Fracht entdeckt, muss die Rolle des Kuriers übernehmen und das dringende Bündel direkt zu Eldrun in die unterirdische Festungsstadt der Zwerge bringen.",al={"wohin liefere ich es","paketziel","lieferort","zu wem bringe ich das paket"}},{q="Welche Verbindung besteht zwischen Nistgipfel und Eisenschmiede?",a="Nistgipfel dient als Herz der Wildhammerzwerge, während Eisenschmiede der erhabene Sitz des Bronzebartklans ist. Obwohl die Klane unterschiedliche Bräuche und Heimstätten pflegen, bestehen regelmäßiger Schriftverkehr, Handel und verwandtschaftliche Bande zwischen den Felsen des Hinterlands und Der Großen Schmiede unter dem Berg.",al={"nistgipfel und eisenschmiede","handel zwischen wildhammer und bronzebeart","verbindung eisenschmiede nistgipfel","warum post von nistgipfel schicken"}}},fp="24,396,17.550.0,32.548.0,41.295.0,27.291.0,31.271.0,33.314.0,46.312.0,45.278.0,56.302.0"}
P.entries["quest:97275"] = {n="Whuut's the Rush",s="Whuut's the Rush ist eine alchemistische Besorgung, die das Spannungsfeld zwischen rohem Talent und diszipliniertem Handwerk beleuchtet. Yelmak beauftragt einen Abenteurer damit, seinem hochbegabten Lehrling Whuut ein bescheidenes, sorgfältig gebrautes Tonikum zu überbringen, um zu demonstrieren, dass wahre Meisterschaft mit alltäglichen Pflanzen beginnt, anstatt seltene Reagenzien zu verschwenden.",h="Whuut's the Rush ist eine alchemistische Besorgung, die das Spannungsfeld zwischen rohem Talent und...",kw={"alchemie","schwarzer lotus","rohrkolben","kräuterkunde","bergsilberweisling","trank","speergras","whuut","yelmak"},ang={["faction:Horde"]="Yelmak unterweist angehende Alchemisten in Geduld, Einfallsreichtum und im Respekt vor einheimischen Zutaten aus Kalimdor, anstatt kostbare Vorräte zu verschwenden.",["profession:Herbalism"]="Sammler und Kräuterkundige werden die Lehre im Herzen dieser Besorgung zu schätzen wissen: Die Eigenschaften alltäglicher Gewächse wie Speergras und Rohrkolben zu verstehen, kann für das Handwerk ebenso unerlässlich sein wie die Jagd nach legendären Blüten."},sec={{t="Das eifrige Wunderkind",b="In der Betriebsamkeit der Alchemielabore kollidiert rohes Talent oft mit rücksichtslosem Ehrgeiz. Whuut gilt als echtes Wunderkind, das am Rührstab über einen natürlichen Instinkt verfügt. Seine Ungeduld verleitet ihn jedoch dazu, die seltensten Reagenzien des Geschäfts aufzubrauchen, ohne sich zuvor ein solides Verständnis grundlegender Brautechniken anzueignen. Noch bevor er das feine Gleichgewicht gewöhnlicher Kräuter erlernt, sucht er nach legendären Pflanzen und behandelt die Alchemie wie ein Wettrennen statt wie eine Disziplin."},{t="Eine Lektion in einer Phiole",b="Um seinen Lehrling zu zügeln, ohne dessen Leidenschaft zu ersticken, bereitet Yelmak eine Lektion in einer Phiole vor. Statt Whuut auszuschimpfen, braut Yelmak mittels einer Schnelltonikum-Methode einen verfeinerten Trank, für den er lediglich gewöhnliches Speergras und Rohrkolben verwendet. Als die bescheidene Mischung Whuut überreicht wird, während der Junge gerade von Schwarzem Lotus und Bergsilberweisling träumt, führt sie ihm vor Augen, dass wahre alchemistische Meisterschaft aus Technik, Geduld und dem Respekt vor der alltäglichen Pflanzenwelt erwächst."}},faq={{q="Wer ist Whuut?",a="Whuut ist ein junges alchemistisches Wunderkind, das begierig darauf brennt, mit den seltensten Kräutern der Welt zu experimentieren. Obwohl er unbestreitbar talentiert ist, führt seine Eile, mit exotischen Reagenzien zu brauen, dazu, dass er die Grundlagen des Alchemiehandwerks vernachlässigt.",al={"wer ist whuut","whuut hintergrundgeschichte","über whuut"}},{q="Wer ist Yelmak?",a="Yelmak ist ein erfahrener Alchemist, der im Laden als Mentor fungiert. Aus Sorge darüber, dass Whuut kostbare Vorräte vergeudet, braut Yelmak ein einfaches Tonikum, um zu demonstrieren, dass wahre Meisterschaft mit bescheidenen, einheimischen Zutaten beginnt.",al={"wer vergibt diese quest","yelmaks rolle","wer ist yelmak"}},{q="Warum schickt Euch Yelmak mit einem Trank zu Whuut?",a="Yelmak möchte Whuut Geduld und Respekt vor den Grundlagen der Alchemie lehren. Indem er zeigt, dass ein wirksamer Trank aus gewöhnlicher Pflanzenwelt wie Speergras und Rohrkolben gebraut werden kann, hofft er, Whuuts Gewohnheit einzudämmen, sich Hals über Kopf auf seltene, unerforschte Kräuter zu stürzen.",al={"was ist yelmaks lektion","warum yelmak den trank schickt","sinn der quest"}},{q="Welche Zutaten hat Yelmak für seinen Trank verwendet?",a="Yelmak braut das Anschauungstonikum aus nichts weiter als gewöhnlichem Speergras und Rohrkolben und beweist seinem Lehrling damit, dass die gewöhnliche Vegetation am Wegesrand bemerkenswerte Ergebnisse hervorbringen kann, wenn man sie mit sorgfältiger Hand zubereitet.",al={"was ist im trank","reagenzien für yelmaks trank","schnelltonikum zutaten"}},{q="Mit welchen seltenen Reagenzien wollte Whuut arbeiten?",a="Bevor er unterbrochen wurde, griff Whuut voller Eifer nach einigen der kostbarsten und legendärsten Pflanzen Azeroths, namentlich Schwarzer Lotus und Bergsilberweisling, und überging alltägliche Zutaten dabei vollkommen.",al={"was whuut braute","seltene kräuter die whuut will","welche reagenzien whuut nutzte"}},{q="Lernt Whuut seine Lektion?",a="Nachdem Whuut das Tonikum gekostet und dessen bescheidene Rezeptur erfahren hat, ist er verblüfft darüber, dass gewöhnliche Pflanzen ein solches Gebräu hervorbringen können. Er gesteht demütig ein, dass Yelmak recht hat, und beschließt, der alltäglichen Pflanzenwelt, die er zuvor abgetan hatte, größere Aufmerksamkeit zu schenken.",al={"ändert whuut seine meinung","whuuts reaktion auf den trank","ausgang von whuut's the rush"}}},fp="16,323,17.474.0,18.436.0,13.227.0,14.226.0,49.251.0,46.216.0,50.207.0,28.240.0"}
P.entries["quest:97277"] = {n="Grund and Gozwin",s="Grund and Gozwin erzählt von einem Hinterhalt an einem Lagerplatz in den verschneiten Hügeln im Nordwesten, wo ein Zwerg und ein Gnom von einem räuberischen Schneeleoparden angegriffen wurden. Obwohl der Gnom dank der Schrotflinte seines Partners überlebte, blieb sein geschätztes Mechanikerlogbuch im Trubel zurück. Abenteurer werden in die Hügel entsandt, um die empfindlichen Aufzeichnungen zu bergen und die lauernde Bestie zu erlegen.",h="Grund and Gozwin erzählt von einem Hinterhalt an einem Lagerplatz in den verschneiten Hügeln im Nordwesten...",kw={"zwerg","gnomingenieur","gozwin","grund","mecha-walker","mechanikerlogbuch","schneeleopardenpirscher"},ang={["profession:Engineering"]="Gozwins Sorge über den Verlust seines Mechanikerlogbuchs zeigt, wie behutsam Tüftler ihre Mecha-Walker-Entwürfe und urheberrechtlich geschützten Aufzeichnungen hüten.",["race:Dwarf"]="Grunds schnelle Reaktion mit der Schrotflinte und die unerschütterliche Lagerfeuerkameradschaft spiegeln die beständige Loyalität wider, die Zwerge an den Tag legen, wenn sie an der Seite ihrer gnomischen Verbündeten reisen.",["race:Gnome"]="Gozwin verkörpert den typischen Gnomtüftler, dessen erster Instinkt nach dem Überleben des Angriffs eines bösartigen Raubtiers darin besteht, sich um die Sicherheit seiner Schreitermaschinenbaupläne zu sorgen."},sec={{t="Ein Hinterhalt am Feuer",b="Während sie gemeinsam in den verschneiten Hügeln reisten, schlugen der Zwerg Grund und sein gnomischer Gefährte Gozwin ein Lager für die Nacht auf. Als Grund dem Geschehen den Rücken zukehrte, um über dem Feuer ein Wildschwein zuzubereiten, sprang ein Schneeleopardenpirscher aus dem Dickicht hervor und packte Gozwin mit seinen Kiefern. Grund reagierte augenblicklich, griff nach seiner treuen Schrotflinte und feuerte einen Schuss über den Kopf der Bestie hinweg ab, was das Raubtier so sehr erschreckte, dass es den Gnom fallen ließ und in die kalten Felsen floh."},{t="Das verlorene Werk eines Tüftlers",b="Obwohl Gozwin den Fängen der Raubkatze mit tiefen Kratzern statt tödlichen Verletzungen entkam, wurde ihr Lager gründlich verwüstet. Im Chaos des Rückzugs ließ Gozwin sein geschätztes Mechanikerlogbuch fallen – ein technisches Notizbuch, das entscheidende Baupläne für seinen Mecha-Walker enthielt. In schrecklicher Sorge, dass jemand seine Ingenieursgeheimnisse entdecken könnte, fand der mitgenommene Gnom keine Ruhe, bis ein Abenteurer zustimmte, sich nach Nordwesten in die Hügel zu wagen, um sein Buch zurückzuholen und das lauernde Raubtier zu erlegen."}},faq={{q="Wer sind Grund and Gozwin?",a="Grund ist ein schrotflintenschwingender zwergischer Camper, und Gozwin ist sein gnomischer Ingenieursgefährte. Während sie in den verschneiten Hügeln ihr Lager aufschlugen, um ein Wildschwein zu braten, wurden sie von einem lauernden Schneeleoparden überrumpelt, wodurch Gozwin verwundet und ihre Ausrüstung verstreut wurde.",al={"wer sind grund and gozwin","grund gozwin"}},{q="Was griff Gozwin im Lager an?",a="Ein wilder Schneeleopardenpirscher überfiel Gozwin von hinten, während Grund das Abendessen zubereitete. Die Bestie vergrub ihre Zähne in dem Gnom und versuchte, ihn wegzuzerren, bevor Grund einen Warnschuss abfeuerte, der die Raubkatze vertrieb.",al={"was griff gozwin an","wer griff gozwin an"}},{q="Warum ist Gozwins Mechanikerlogbuch so wichtig für ihn?",a="Gozwins Mechanikerlogbuch enthält unverzichtbare technische Pläne und Notizen bezüglich seines Mecha-Walkers. Gozwin fürchtete, dass sein Projekt vollkommen ruiniert wäre, falls jemand anderes seine persönlichen Ingenieursaufzeichnungen in die Hände bekommen sollte.",al={"warum ist das logbuch wichtig","mechanikerlogbuch gozwin"}},{q="Wie schwer wurde Gozwin bei dem Angriff verletzt?",a="Ja, Gozwin überlebte den Hinterhalt dank Grunds schnellem Schrotflintenschuss. Er entkam mit tiefen Kratzern und einem schweren Schock, erholt sich jedoch wohlbehalten, während Grund ihn versorgt.",al={"geht es gozwin gut","hat gozwin überlebt"}},{q="Wo befindet sich das Lager von Grund and Gozwin?",a="Der Lagerplatz des Paares liegt eingebettet in den Hügeln im Nordwesten. Abenteurer werden zu dem Lager entsandt, um das verlorene Logbuch zu bergen und den Leopardenpirscher zu beseitigen, der in der Gegend herumstreift.",al={"wo ist das lager","grund lager standort"}},{q="Was geschah mit der Mahlzeit, die Grund zubereitete?",a="Nachdem der räuberische Schneeleopard durch Grunds Schüsse von Gozwin verscheucht worden war, kehrte er zum verlassenen Lagerplatz zurück und fraß den Eberbraten, den Grund für das Abendessen zubereitet hatte.",al={"was geschah mit dem eberbraten","leopard frisst eber"}}},fp="16,367,21.439.0,22.493.0,25.241.0,29.221.0,51.222.0,40.175.0,41.187.0,46.182.0"}
P.entries["quest:97279"] = {n="Verlorene Waffen",s="Verlorene Waffen ist eine frühe Trainingsaufgabe im Tal der Prüfungen, die vom Vorarbeiter Gornek vergeben wird. Da junge Krieger in Scharen eintreffen, um der Horde zu dienen, werden die Rüstungsgüter knapp. Um ihre Disziplin zu beweisen und das Lager zu unterstützen, durchkämmen Rekruten das Buschland, um Ausrüstung zu bergen, die von weniger fähigen Vorgängern zurückgelassen wurde.",h="Verlorene Waffen ist eine frühe Trainingsaufgabe im Tal der Prüfungen, die vom Vorarbeiter Gornek vergeben...",kw={"durotar","gornek","kzan dornenhieb","rekruten","bergen","der bau","übungswaffen","das tal der prüfungen"},ang={["class:Warrior"]="Respekt vor Waffen ist das Fundament eines jeden Kriegers. Das Bergen der von gescheiterten Rekruten weggeworfenen Waffen betont Disziplin und Eigenständigkeit, noch bevor der wahre Kampf überhaupt beginnt.",["faction:Horde"]="Die Horde behauptet sich in Durotar durch Härte und Einfallsreichtum und weigert sich, Waffen zu vergeuden, selbst wenn sie von jenen weggeworfen wurden, die nicht würdig waren, sie zu führen.",["profession:Blacksmithing"]="In Durotar zählt jeder Metallrest. Kzan beim Bergen ruinierter Ausrüstung zu helfen, spiegelt die Pflicht des Schmieds wider, Eisen zurückzugewinnen und ramponierte Klingen wieder in brauchbare Kriegswerkzeuge zu verwandeln."},sec={{t="Bewaffnung des frischen Blutes",b="Das Tal der Prüfungen ist die Schmiede, in der unerfahrene Rekruten den rauen roten Ödlanden von Durotar trotzen müssen. Da zahllose Anwärter vortreten, um ihre Klingen dem Kriegshäuptling zu weihen, sind die Waffenvorräte des Lagers bis an ihre Grenzen erschöpft. Waffenschmied Kzan Dornenhieb hat Mühe, mit der Nachfrage Schritt zu halten, besonders wenn sich frühe Lektionen für die Unvorbereiteten als fatal oder demütigend erweisen."},{t="Eine Prüfung des Einfallsreichtums",b="Vorarbeiter Gornek macht aus diesem Mangel eine praktische Prüfung. Anstatt neues Metall zu verschwenden, weist er die Neuankömmlinge an, die verlassenen Klingen und stumpfen Übungswaffen zu bergen, die von gescheiterten Rekruten zurückgelassen wurden, welche im Staub fielen oder flohen. Werden diese geborgenen Waffen Kzan überbracht, kann der Schmied sie reparieren und für die nächste Welle härten. So lernen Novizen, dass das Überleben in der Horde sowohl das Plündern als auch das Schwingen von Stahl erfordert."}},faq={{q="Warum liegen so viele verlassene Übungswaffen herum?",a="Nicht jeder Hoffnungsträger, der das Tal der Prüfungen betritt, besitzt die von der Horde geforderte Stärke oder Entschlossenheit. Verzagte oder unachtsame Rekruten lassen ihre Ausrüstung regelmäßig in Panik fallen oder erliegen den einheimischen Ebern und Skorpiden, sodass ihre ausgegebenen Waffen im Staub verstreut zurückbleiben.",al={"warum liegen waffen am boden","verlassene waffen durotar","gescheiterte rekruten waffen"}},{q="Wer ist Kzan Dornenhieb?",a="Kzan Dornenhieb ist der ansässige Waffenschmied, der im Höhlenbau im Tal der Prüfungen stationiert ist. Er ist dafür verantwortlich, neue Rekruten auszurüsten, ramponierte Übungsausrüstung zu reparieren und die militärischen Vorräte der Horde im Starttal instand zu halten.",al={"kzan dornenhieb lore","wer ist kzan","waffenschmied kzan"}},{q="Wer vergibt diese Aufgabe?",a="Gornek, der Vorarbeiter, der vor dem Höhlenbau steht, weist diese Aufgabe zu. Er beaufsichtigt die eintreffenden Anwärter, beurteilt ihr grundlegendes Potenzial und entsendet sie, um dringende Angelegenheiten rund um das Prüfungsgelände zu regeln.",al={"wer vergibt verlorene waffen","gornek quest"}},{q="Was wird Kzan mit diesen geborgenen Waffen tun?",a="Kzan repariert, schärft und restauriert die ramponierten Übungswaffen. Da die Ressourcen in Durotar spärlich sind und ständig neue Rekruten eintreffen, müssen das geborgene Eisen und Holz wiederverwendet werden, um die nächste Welle auszubilden.",al={"was geschieht mit den übungswaffen","waffen reparieren kzan"}},{q="Wo findet diese Quest statt?",a="Sie findet im Tal der Prüfungen statt, einer abgelegenen Schlucht im Süden von Durotar, in der junge Orcs und Dunkelspeere ihren Weg als Krieger für die Horde beginnen.",al={"tal der prüfungen standort","wo ist verlorene waffen"}},{q="Warum schmiedet die Horde nicht einfach völlig neue Waffen?",a="Durotar ist ein zerklüftetes, trockenes Land mit wenigen leicht zugänglichen Eisenvorkommen, und die junge Horde kann sich keine Verschwendung leisten. Das Wiederverwerten von Übungsklingen der Ausgemusterten stellt sicher, dass Rohmetall für die Fronttruppen aufgespart wird.",al={"warum waffen bergen","durotar metallmangel"}}},fx={c966be67={q="Warum will Gornek, dass die verlassenen Waffen gesammelt werden?",a="Ein frischer Zustrom von Rekruten in Das Tal der Prüfungen hat die Waffenkammer des Lagers belastet. Der Waffenschmied Kzan geht die Übungsausrüstung aus, und Gornek muss die Vorräte am Laufen halten, um die nächste Welle auszubilden. Euch zu bitten, das Gelände abzusuchen, löst den Mangel und lässt Gornek gleichzeitig Eure Sorgfalt und Eure Überlebensfähigkeiten im Tal testen.",al={"gorneks beweggrund","warum will gornek waffen","warum verlassene übungswaffen sammeln"}},["42aac14b"]={q="Wozu dient die Abandoned Training Weapon?",a="Diese groben Klingen und Knüppel wurden von früheren Rekruten getragen, die sich als unwürdig erwiesen oder starben, bevor sie ihre Prüfungen beendeten. Im Schmutz verstreut, sind sie immer noch robust genug, um restauriert zu werden. Sobald Ihr sie zu Kzan Dornenhieb bringt, repariert und schärft er sie, damit zukünftige Rekruten Ausrüstung haben, mit der sie kämpfen können.",al={"nutzen der verlassenen übungswaffen","wofür sind die verlassenen waffen gut","zweck der verlassenen übungswaffen"}},["056af0db"]={q="Warum schickt Gornek einen Rekruten anstatt Wachen?",a="Die Prüfungsgründe existieren, um fähige Krieger von den Schwachen zu trennen. Erfahrene Wachen loszuschicken, um hinter gescheiterten Rekruten aufzuräumen, verschwendet Veteranen-Arbeitskraft, während Euch zu schicken einen doppelten Zweck erfüllt: Ihr stählt Euch bei der Jagd auf Eber in der Wildnis, während Ihr beweist, dass Ihr Befehle befolgen und die Notwendigkeiten des Lagers aufrechterhalten könnt.",al={"warum keine wachen schicken","warum ich gornek","warum rekruten für waffen schicken"}}},fp="15,323,20.384.0,25.431.0,62.279.0,23.243.0,21.204.0,46.201.0,33.160.0,54.215.0"}
P.entries["quest:97281"] = {n="A Simmering Storm",s="A Simmering Storm beginnt, als ein Abenteurer von den Harpyien der Staubwindklamm ein seltsames, funkensprühendes Relikt erbeutet, das als Dull Stormy Orb bekannt ist. Dem Goblin-Tüftler Rezlak den wirbelnden Miniatursturm zu überbringen, gewährt Einblick in die merkwürdigen Schmuckstücke der Harpyien und weckt das Interesse der geschäftstüchtigen Bergungsexperten von Ratschet.",h="A Simmering Storm beginnt, als ein Abenteurer von den Harpyien der Staubwindklamm ein seltsames...",kw={"a simmering storm","staubwindklamm","dull stormy orb","durotar","dustwind","gazlowe","harpie","rezlak"},ang={["class:Shaman"]="Der in der Kugel eingeschlossene elektrische Miniatursturm spiegelt urtümliche Elementarkräfte wider, doch dessen Nutzbarmachung in diesem primitiven Gefäß wirft Fragen über die Methoden der Harpyien auf.",["faction:Horde"]="Abenteurer der Horde, die dem Goblin Rezlak nahe der Staubwindklamm beistehen, helfen dabei, geheimnisvolle magische Artefakte zu sichern, die von feindseligen Harpyien geborgen wurden, welche die Schluchten Durotars bedrohen.",["profession:Engineering"]="Tüftler und Ingenieure wie Rezlak fühlen sich naturgemäß von sonderbaren Kuriositäten angezogen, die vor unberechenbaren elektrischen Ladungen und wirbelndem innerem Mist sprühen."},sec={{t="Ein Funke im Staub",b="Während Reisende sich mit den aggressiven Harpyien der Dustwind auseinandersetzen, die überall in der Staubwindklamm nisten, stoßen sie womöglich auf eine ungewöhnliche Kuriosität: die Dull Stormy Orb. Obwohl ihre äußere Oberfläche matt und abgenutzt wirkt, offenbart das Halten des Objekts ein stetiges Vibrieren von reinem elektrischem Strom. Im Inneren der Kugel wallt endlos dunkler Mist, der in zufälligen Abständen von scharfen inneren Funken erleuchtet wird. Es ist ein unverkennbarer Beweis dafür, dass die Harpyien Sturm-Magie durch seltsame Relikte manipulierten."},{t="Goblin-Neugier",b="Anstatt solch unbeständige Magie in den Klauen wilder Harpyien zu belassen, kann die Kugel direkt zu Rezlak gebracht werden. Der pragmatische Goblin-Tüftler, der am Eingang der Staubwindklamm stationiert ist, zeigt sofortiges Interesse an dem seltsamen Relikt und bemerkt, dass dessen Entdeckung an alten Rat seines Arbeitgebers in Ratschet, Chefingenieur Gazlowe, erinnert. Was auch immer die Harpyien mit dem Miniatursturm zu brauen gedachten, er befindet sich nun in Goblinhänden."}},faq={{q="Was ist die Dull Stormy Orb?",a="Die Dull Stormy Orb ist ein merkwürdiges magisches Kuriosum, das von einer Harpyie in Durotar erbeutet wurde. Trotz ihres matten Äußeren summt sie vor schwachem elektrischem Strom, wirbelndem dunklem Mist und periodischen Funken, die in ihr eingeschlossen sind.",al={"was ist die dull stormy orb","stürmische kugel","kugel von harpien"}},{q="Wer will die Dull Stormy Orb?",a="Die Kugel wird zu Rezlak gebracht, einem Goblin-Späher, der direkt außerhalb der Staubwindklamm in Durotar stationiert ist und ein scharfes Auge für eigentümliche Kuriositäten und wertvolles Bergungsgut besitzt.",al={"wer nimmt die dull stormy orb an","stürmische kugel abgeben","wohin kugel bringen"}},{q="Warum hatten die Harpyien diese Kugel?",a="Der genaue Zweck bleibt unbekannt, aber die Harpyien der Staubwindklamm nutzten die Kugel eindeutig, um elektrische und stürmische Elementarenergien zu kanalisieren oder einzudämmen.",al={"was taten die harpien mit der kugel","warum haben harpien sturmkugel","zweck der harpienkugel"}},{q="Wer ist Rezlak?",a="Rezlak ist ein Goblin-Agent, der im nördlichen Durotar nahe der Staubwindklamm arbeitet und mit dem Steamwheedle Cartel sowie Chefingenieur Gazlowe von Ratschet in Verbindung steht.",al={"wer ist rezlak","rezlak durotar","goblin nahe staubwindklamm"}},{q="Wo befindet sich die Staubwindklamm?",a="Die Staubwindklamm ist ein zerklüftetes Schluchtensystem im nördlichen Durotar, das von feindseligen Staubwindharpyien heimgesucht wird, die Reisende belästigen und den örtlichen Handel sowie Siedlungen stören.",al={"wo ist die staubwindklamm","staubwindklamm lage","harpienschlucht durotar"}},{q="Was hält Rezlak von der Kugel?",a="Beim Erblicken der Kugel erinnert sich Rezlak sofort an Lektionen und Bemerkungen seines Chefs, Chefingenieur Gazlowe, bezüglich eigentümlicher und potenziell gewinnbringender Seltsamkeiten.",al={"was sagt rezlak über gazlowe","rezlak gazlowe verbindung"}}},fp="17,323,19.481.0,16.429.0,28.209.0,30.161.0,34.166.0,14.157.0,25.164.0,34.169.0"}
P.entries["quest:97282"] = {n="Stormy Potential",s="Stormy Potential ist eine Quest in Durotar, die vom Goblin Rezlak nahe der Staubwindklamm vergeben wird. In der Hoffnung, seine Handelskarawane vor marodierenden Harpyien zu schützen, versucht Rezlak, eine entladene Kugel mithilfe der wirkungsvollen elektrischen Organe einheimischer Donnerechsen aufzuladen.",h="Stormy Potential ist eine Quest in Durotar, die vom Goblin Rezlak nahe der Staubwindklamm vergeben wird.",kw={"geladene organe","staubwindklamm","durotar","gazlowe","harpyien","kugel","rezlak","stormy potential","donnerechse"},ang={["faction:Horde"]="Rezlaks Unternehmungen unterstützen den Stützpunkt und den Transit der Horde durch Durotar, wo marodierende Harpyien aus der Staubwindklamm Reisende und Nachschubkarawanen bedrohen.",["profession:Engineering"]="Die Nutzung unbeständiger biologischer Energie von Donnerechsen zur Wiederinbetriebnahme inaktiver Geräte ist klassischer Goblin-Erfindungsgeist, selbst wenn die Sicherheitsmargen im Grunde nicht existent sind."},sec={{t="Die Gunst der Stunde nutzen",b="Im Schatten der Staubwindklamm in Durotar sah sich der Goblin Rezlak mit zwei Problemen konfrontiert: eine Karawane, die ständig von einheimischen Harpyien bedroht wurde, und eine intakte magische Kugel, deren Energie völlig aufgebraucht war. In Erinnerung an den pragmatischen Rat von Ratschets Chefingenieur Gazlowe – jede Gelegenheit beim Schopf zu packen – schmiedete Rezlak einen ehrgeizigen Plan, um beide Probleme auf einmal zu lösen, indem er das inaktive Gerät überlud."},{t="Den Sturm bändigen",b="Um die entladene Kugel wieder aufzuladen, benötigte Rezlak eine wirkungsvolle, unmittelbare Quelle reiner Elektrizität. Die Schlucht westlich der Staubwindklamm ist die Heimat von Donnerechsen – Kreaturen, die für innere Organe bekannt sind, welche tödliche Blitze erzeugen und leiten können. Indem er einen Abenteurer ausschickte, um diese geladenen Organe zu erbeuten, hoffte Rezlak, ihre unbeständige Energie sicher direkt in das Gerät leiten zu können, was seinen verwundbaren Nachschubwagen eine gewaltige Verteidigung gegen künftige Überfälle der Harpyien verschaffen würde."}},faq={{q="Wer vergibt die Quest Stormy Potential?",a="Stormy Potential wird von Rezlak angeboten, einem Goblinhändler und Tüftler, der nahe der Staubwindklamm in Durotar stationiert ist. Dem Rat von Gazlowe folgend, jede Gelegenheit beim Schopf zu packen, versucht er, eine energielose Kugel mithilfe der natürlichen elektrischen Ladung einheimischer Bestien wieder aufzuladen.",al={"wer vergibt stormy potential","wo ist rezlak","rezlak questgeber"}},{q="Was versucht Rezlak mit den Organen aufzuladen?",a="Rezlak besitzt eine Kugel, die zwar intakt, aber völlig ohne Energie ist. Er hofft, sie mithilfe der elektrischen Organe von Donnerechsen wieder zu voller Stärke zu überladen, damit er seine Karawane vor den Harpyien verteidigen kann, die das Gebiet heimsuchen.",al={"was lädt rezlak auf","warum donnerrechsenorgane gebraucht werden","rezlak kugel zweck"}},{q="Wo sind die Donnerechsen zu finden?",a="Donnerechsen bewohnen eine Schlucht westlich von Rezlaks Position nahe der Staubwindklamm in Durotar. Jäger müssen ihre elektrischen Organe erbeuten, um sie Rezlak zurückzubringen.",al={"wo donnerrechsen finden","donnerrechsen standort durotar","wo sind die organe"}},{q="Warum ist die Jagd auf Donnerechsen gefährlich?",a="Trotz ihres donnernden Namens stoßen Donnerechsen gefährliche Blitze aus, anstatt bloß zu brüllen. Wie Rezlak warnt, sind ihre elektrischen Entladungen eine schmerzhafte Lektion, die die meisten Reisenden nur ein einziges Mal lernen.",al={"warum donnerrechsen blitze","nutzen donnerrechsen blitze"}},{q="Warum fürchtet Rezlak die Harpyien?",a="Rezlaks Karawane wurde von den feindseligen Harpyien überfallen, die die Staubwindklamm heimsuchen. Er beabsichtigt, die wiederaufgeladene Kugel als Abschreckung oder Waffe einzusetzen, damit die Harpyien es sich zweimal überlegen, ehe sie seine Transporte erneut angreifen.",al={"warum rezlak verteidigung braucht","wer griff rezlak an","harpyien karawanenangriff"}},{q="Welche Verbindung hat Rezlak zu Gazlowe?",a="Rezlak betrachtet Gazlowe, den Chefingenieur von Ratschet, als erfahrenen Mentor und geschäftliche Inspiration. Rezlak zitiert Gazlowes Geschäftsphilosophie über das Ergreifen von Gelegenheiten ausdrücklich, als er seinen Plan zur Überladung der Kugel formuliert.",al={"wer ist gazlowe für rezlak","rezlak gazlowe ratschlag"}}},fp="16,255,19.421.0,20.486.0,37.266.0,48.233.0,36.167.0,45.207.0,33.210.0,39.234.0"}
P.entries["quest:97288"] = {n="Unending Torment",s="Unending Torment beginnt, wenn eine seltsame Monstrosität erschlagen wird und ihr Kopf sich durch wiederholtes Zusammennähen löst und herabfällt. Das Relikt weist Spuren davon auf, viele Male abgetrennt und wieder befestigt worden zu sein, und deutet auf vorsätzliche finstere Experimente innerhalb der Hauptstadt der Verlassenen hin. Bringt man die grausige Beute zu Apothekermeister Faranell in Unterstadt, enthüllt sich der verquere Humor hinter der wiederholten Wiederbelebung.",h="Unending Torment beginnt, wenn eine seltsame Monstrosität erschlagen wird und ihr Kopf sich durch...",kw={"monströser kopf","monstrosität","das apothekarium","dunkle fürstin","apothekermeister faranell","königliche apothekervereinigung","sylvanas windläufer","unterstadt","unending torment"},ang={["faction:Horde"]="Abenteurer der Horde, die Faranells Entgegennahme des Kopfes miterleben, erhalten einen direkten Einblick in die beunruhigenden Praktiken ihrer Verbündeten aus Unterstadt. Obwohl wirksam, wirken die Methoden der Verlassenen mit ihrer endlosen Wiederbelebung und Fleischformung auf ihre eher an die Ehre gebundenen Gefährten oft verstörend.",["race:Undead"]="Für die Verlassenen veranschaulicht der Kopf den finsteren Humor und das unerbittliche Wesen ihrer Königin, Sylvanas Windläufer. Er dient als deutliche Mahnung an die absolute Autorität der Dunklen Fürstin und den makabren Erfindungsreichtum der Königlichen Apothekervereinigung."},sec={{t="Ein loser Faden",b="Als die hoch aufragende Monstrosität im Kampf schließlich zusammenbricht, stürzt ihr Kopf unvermittelt von ihren Schultern. Eine genaue Untersuchung offenbart, dass der Hals nicht bloß einmal abgetrennt wurde, sondern zahlreiche Male genäht, abgerissen und wieder befestigt worden ist. Mit jeder aufeinanderfolgenden Rekonstruktion wurde die Naht brüchiger, sodass der Kopf kaum noch an den Schultern des Konstrukts haftete. Ein derart schlampiges und doch hartnäckiges Flickwerk ist selbst für untote Konstrukte ungewöhnlich und deutet darauf hin, dass diese spezielle Monstrosität wiederholten Zyklen der Zerstörung und des Wiederzusammenbaus ausgesetzt war. Wer die Überreste untersucht, erkennt rasch, dass gewöhnliche Aasfresser eine solche Machart nicht erklären können und nur die geschickten Fleischformer von Unterstadt die Herkunft dieser Kreatur bestimmen könnten."},{t="Der Scherz der Dunklen Fürstin",b="Liefert man den abgetrennten Kopf im Apothekarium ab, gelangt er vor Apothekermeister Faranell, den Anführer der Königlichen Apothekervereinigung. Weit davon entfernt, von dem grauenhaften Fundstück überrascht zu sein, erkennt Faranell das Antlitz augenblicklich wieder. Er identifiziert den wiederholten Zusammenbau nicht als versehentliches Fehlschlagen der Nekromantie, sondern als vorsätzlichen und grausamen Scherz, den sich Fürstin Sylvanas Windläufer selbst ausgedacht hat. Welches konkrete Vergehen oder welche Kränkung der Kreatur eine derart ewige, entwürdigende Bestrafung eingebracht hat, bleibt allein der Dunklen Fürstin und ihrem inneren Zirkel bekannt. Statt das zerschundene Relikt wegzuwerfen, nimmt Faranell den abgetrennten Kopf voller Freude an, zuversichtlich, dass die Königliche Apothekervereinigung ihn für ihre laufenden alchemistischen und nekromantischen Vorhaben nutzen kann."}},faq={{q="Was ist der Monströse Kopf?",a="Der Monströse Kopf ist der abgetrennte Kopf eines einzigartigen Konstrukts, der erbeutet werden kann, wenn die Kreatur besiegt wird. Sein Hals trägt die Narben wiederholter Befestigung, wobei jedes erneute Verbinden das Fleisch und die Nähte weiter geschwächt hat. Er dient als Beweis für eine bizarre, wiederkehrende Strafe, die der Kreatur zugefügt wurde, und veranlasst den Finder dazu, ihn zur Untersuchung zu Apothekermeister Faranell in Unterstadt zu bringen.",al={"monströser kopf lore","was ist der monströse kopf","monströser kopf questgegenstand"}},{q="Warum wurde der Kopf so oft wieder befestigt?",a="Der Kopf der Kreatur wurde als Form der Qual wiederholt an ihren Körper genäht. Laut Apothekermeister Faranell ist der Zustand der Kreatur ein grausamer und vorsätzlicher Scherz, inszeniert von Fürstin Sylvanas Windläufer. Jedes Mal, wenn das Konstrukt fiel oder seinen Kopf verlor, wurde es wieder zusammengesetzt, um weiter zu dienen oder zu leiden, was zu einem zunehmend brüchigen Hals führte, der schließlich erneut nachgab.",al={"warum kopf wieder angenäht","warum wurde der kopf wieder angenäht","unending torment kopfnähte"}},{q="Wer ist Apothekermeister Faranell?",a="Apothekermeister Faranell ist das Oberhaupt der Königlichen Apothekervereinigung und im Apothekarium von Unterstadt stationiert. Unter der Autorität von Königin Sylvanas Windläufer beaufsichtigt Faranell die Apotheker der Verlassenen bei der Erforschung von Giften, Seuchen und anatomischen Veränderungen. Seine tiefe Vertrautheit mit den Projekten der Dunklen Fürstin erlaubt es ihm, die Herkunft des zusammengenähten Kopfes sofort zu erkennen.",al={"wer ist faranell","apothekermeister faranell lore","faranell unterstadt"}},{q="Warum betrachtet Sylvanas dies als grausamen Scherz?",a="Obwohl Faranell die ursprüngliche Identität der Kreatur nicht näher erläutert, betrachtet er den endlosen Kreislauf aus Tod und Wiederzusammenbau des Konstrukts als köstlichen Scherz der Dunklen Fürstin. Eine Kreatur dazu zu zwingen, wiederholte Zerstörung zu ertragen, nur um Mal um Mal schlampig wiederbelebt und zusammengenäht zu werden, verkörpert Sylvanas' gnadenlosen Sinn für Ironie und Bestrafung gegenüber ihren Feinden.",al={"sylvanas scherz","warum scherz der dunklen fürstin","grausamer scherz der dunklen fürstin"}},{q="Was wird Faranell mit dem Kopf tun?",a="Bei Erhalt des ramponierten Kopfes bemerkt Faranell mit düsterer Belustigung, dass er Verwendung dafür hat. Als Aufseher über die grotesken Experimente der Königlichen Apothekervereinigung verwendet er regelmäßig nekromantische Überreste, Fleisch und biologische Absonderlichkeiten für die Entwicklung neuer Gebräue, Seuchen und Konstruktverstärkungen wieder, um den Verlassenen in ihren andauernden Konflikten beizustehen.",al={"was geschieht mit dem kopf","faranell verwendung für kopf","was machen die apotheker damit"}},{q="Wo gibt man die Quest Unending Torment ab?",a="Die Quest wird abgeschlossen, indem man den Monströsen Kopf direkt zu Apothekermeister Faranell bringt. Er residiert im Apothekarium, dem alchemistischen Flügel im südlichen Quadranten von Unterstadt. Abenteurer der Verlassenen und Verbündete der Horde können ihn umgeben von brodelnden Bottichen, Assistenten und Versuchsobjekten antreffen, während er die Forschungen der Vereinigung beaufsichtigt.",al={"wo unending torment abgeben","unending torment abgabe","wer nimmt den monströsen kopf"}},{q="Können Spieler der Allianz diese Quest abgeben?",a="Da das Ziel erfordert, den Questgegenstand direkt bei Apothekermeister Faranell im Apothekarium von Unterstadt abzuliefern, ist diese Quest für Abenteurer der Horde bestimmt. Jeder Spieler der Allianz, der versuchen würde, sich Faranell zu nähern, sähe sich feindseligen Wachen von Unterstadt gegenüber und würde beim Betreten ihrer unterirdischen Feste den Tod durch die Hand der Verlassenen finden.",al={"ist unending torment nur für die horde","allianz unending torment","kann die allianz unending torment machen"}}},fp="16,406,14.772.0,20.739.1,28.399.0,47.406.0,34.404.0,45.388.0,36.370.0,48.346.0,40.355.0"}
P.entries["quest:97289"] = {n="Unending Torment",s="Unending Torment ist eine Quest in Unterstadt, bei der es um die Reanimation des abgetrennten Kopfes von Grand Marshal Othmar Garithos geht. Die Verlassenen versuchen, ihren ehemaligen Feind der Allianz zu verhören, indem sie ein zusammengenähtes Monstrum als sein neues Gefäß vorbereiten.",h="Unending Torment ist eine Quest in Unterstadt, bei der es um die Reanimation des abgetrennten Kopfes von...",kw={"monstrum","verlassene","garithos","großmarschall","kopf des barons","othmar","sylvanas","unterstadt","unending torment"},ang={["faction:Alliance"]="Die makabre Reanimation der Überreste von Grand Marshal Garithos verdeutlicht das grausame Schicksal, das Anführer der Allianz erwartete, die sich der Bansheekönigin in Lordaeron widersetzten.",["faction:Horde"]="Die Unterstützung der Royal Apothecary Society bei Reanimationsexperimenten in Unterstadt demonstriert das dunkle Handwerk der Verlassenen und ihre Rache an ehemaligen Unterdrückern.",["race:Undead"]="Für die Verlassenen stellen Experimente an den Überresten von Grand Marshal Garithos ausgleichende Gerechtigkeit und eine direkte Erinnerung an Fürstin Sylvanas' Eroberung von Lordaeron dar."},sec={{t="Eine Siegestrophäe",b="In den unterirdischen Labortiefen von Unterstadt nähen Praktiker der Verlassenen monströse Monstrositäten aus weggeworfenen Überresten der Toten zusammen. Doch unter zahllosen konservierten Schädeln birgt ein Relikt außergewöhnliche historische Gehässigkeit: der abgetrennte Kopf von Grand Marshal Othmar Garithos, dem arroganten Kommandanten, der die überlebenden Streitkräfte der Allianz durch Lordaeron führte, bevor er durch die Hände der Dunklen Fürstin den Tod fand."},{t="Geheimnisse des Grabes",b="Die Verlassenen behalten Garithos' Kopf nicht bloß als Kriegstrophäe. Indem sie den Körper eines zusammengeflickten Monstrums als neuen Wirt vorbereiten, beabsichtigen die Nekromanten der Verlassenen, den ehemaligen Grand Marshal zu verhören und Geheimnisse der Allianz aufzudecken, die in seinem abgetrennten Schädel eingeschlossen sind. Wenn der Kopf zu dem leblosen Konstrukt gebracht wird, erwacht das zusammengesetzte Monstrum mit qualvollem Bewusstsein und durchlebt seine grausamen letzten Momente in endloser Pein."}},faq={{q="Wer war Othmar?",a="Othmar bezieht sich auf Grand Marshal Othmar Garithos, einen berüchtigten militärischen Befehlshaber, der nach dem Dritten Krieg Überreste der Allianz in Lordaeron anführte. Er wurde von Nicht-Menschen verachtet, und Apothekermeister Faranell sagt, dass die Dunkle Fürstin das Vergnügen hatte, ihn selbst zu beseitigen.",al={"wer ist othmar","identität von othmar","wer war othmar"}},{q="Warum reanimieren die Verlassenen Othmars Überreste?",a="Die Verlassenen möchten ihm wertvolle Geheimnisse entlocken, die er mit ins Grab nahm. Indem sie seinen konservierten Kopf in die Nähe eines vorbereiteten Monstrum-Wirts platzieren, können die Verlassenen Informationen direkt aus den wiederbelebten Überresten gewinnen.",al={"warum othmar wiederbeleben","zweck der wiederbelebung des kopfes","welche geheimnisse othmar"}},{q="Wie starb Othmar?",a="Apothekermeister Faranell sagt, dass Fürstin Sylvanas Windläufer, die Dunkle Fürstin, das Vergnügen hatte, Grand Marshal Garithos selbst zu beseitigen.",al={"wer tötete othmar","wie starb othmar","othmars tod"}},{q="Warum heißt der Questgegenstand Kopf des Barons?",a="The Baron ist der Name der hoch aufragenden Monstrosität in den Ruinen von Lordaeron, deren Kopf dies war. Faranell enthüllt, dass der Kopf einst Grand Marshal Garithos gehörte.",al={"kopf des barons othmar","warum kopf des barons genannt"}},{q="Wo befindet sich Othmars neuer Körper?",a="Das kopflose Monstrum, das konstruiert wurde, um Othmars Kopf aufzunehmen, wird in einer angrenzenden Kammer in Unterstadt aufbewahrt und wartet auf seine Reanimation durch die Hände der Praktiker der Verlassenen.",al={"wo ist othmars körper","ort des monstrums unterstadt"}},{q="Was geschieht, wenn das Konstrukt erwacht?",a="Wenn es in die Nähe des zusammengesetzten Konstrukts platziert wird, zuckt das zusammengenähte Fleisch heftig zum Leben. Bei der Wiedererlangung des Bewusstseins geraten die Überreste sofort in Panik, da sie das Grauen von Garithos' letzten lebenden Momenten noch einmal durchleben.",al={"was geschieht wenn der körper erwacht","abschlussreaktion othmar"}}},fp="16,241,20.422.0,20.430.1,15.264.0,50.213.0,19.136.0,51.168.0,35.176.0,40.210.0"}
P.entries["quest:97290"] = {n="Unending Torment",s="Unending Torment ist eine Aufgabe, die im Auftrag der Königlichen Apothekervereinigung in Unterstadt übernommen wird. Ein Abgesandter konfrontiert einen aufsässigen Gefangenen oder ein Testobjekt, das sich weigert zu kooperieren und den Bittsteller als Abscheulichkeit bezeichnet. Die Meldung dieses Widerstands an Apothekermeister Faranell ruft eher Genugtuung als Enttäuschung hervor, da der Anführer der Apotheker die Gelegenheit genießt, ein schwieriges Subjekt zu brechen.",h="Unending Torment ist eine Aufgabe, die im Auftrag der Königlichen Apothekervereinigung in Unterstadt...",kw={"abscheulichkeit","das apothekarium","faranell","verlassene","apothekermeister faranell","königliche apothekervereinigung","unterstadt","unending torment"},ang={["faction:Horde"]="Champions der Horde, die in Lordaeron operieren, beobachten häufig die erschreckende Rücksichtslosigkeit ihrer Verbündeten unter den Verlassenen. Faranells Freude daran, eigensinnige Gefangene zu brechen, unterstreicht den finsteren Pragmatismus, der in Unterstadt vorherrscht.",["race:Undead"]="Abenteurer der Verlassenen sind bestens damit vertraut, von den Lebenden als Abscheulichkeiten abgestempelt zu werden. Apothekermeister Faranell beizustehen, bestärkt ihr Bekenntnis zum finsteren Wirken der Königlichen Apothekervereinigung."},sec={{t="Trotz in den Schatten",b="Die Königliche Apothekervereinigung hat häufig mit Versuchsobjekten, Gefangenen und feindseligen Wesen zu tun, die nichts als Hass für die Verlassenen hegen. In Unending Torment begegnet ein Ermittler einem unkooperativen Individuum, das den Bittsteller offen verachtet, ihn als Abscheulichkeit bezeichnet und sich vehement weigert, jegliche Hilfe zu leisten. Der verzweifelte Trotz des Subjekts verdeutlicht den schieren Abscheu und die Feindseligkeit, die viele lebende oder gefangene Wesen den Untoten von Lordaeron entgegenbringen."},{t="Faranells Ehrgeiz",b="Die Weigerung des Gefangenen an Apothekermeister Faranell in Unterstadt zu melden, führt zu einer unerwarteten Reaktion. Anstatt Frustration über das Ausbleiben unmittelbarer Fortschritte zu äußern, begrüßt das Oberhaupt der Königlichen Apothekervereinigung den Widerstand mit bösartiger Begeisterung. Für Faranell ist ein unnachgiebiges Subjekt kein gescheitertes Verhör, sondern eine faszinierende Herausforderung – eine, die den grausamen Erfindungsreichtum und die experimentellen Methoden heraufbeschwört, die im Apothekarium praktiziert werden."}},faq={{q="Was ist Unending Torment?",a="Unending Torment ist eine Quest, die mit der Königlichen Apothekervereinigung in Verbindung steht. Ein Abenteurer verhört oder untersucht einen unkooperativen Gefangenen oder ein Wesen, das jegliche Hilfe verweigert und ihn als Abscheulichkeit beschimpft. Der Abenteurer muss diese Nachricht des Fehlschlags daraufhin Apothekermeister Faranell in Unterstadt überbringen.",al={"unending torment quest","was ist unending torment","unending torment lore"}},{q="Wer vergibt die Quest Unending Torment?",a="Die Quest beginnt nach der Interaktion mit einem aufsässigen Subjekt, das jede Zusammenarbeit ablehnt, den Spieler als Abscheulichkeit verflucht und ihn dann wegschickt. Der genaue Gefangene bleibt im anfänglichen Austausch namenlos und weist den frustrierten Abenteurer an, seine Erkenntnisse der Führung der Königlichen Apothekervereinigung vorzulegen.",al={"wer startet unending torment","unending torment questgeber","wo man unending torment annimmt"}},{q="Wer ist Apothekermeister Faranell?",a="Apothekermeister Faranell ist das Oberhaupt der Königlichen Apothekervereinigung mit Sitz im Apothekarium unter den Ruinen von Lordaeron in Unterstadt. Er beaufsichtigt die Alchemisten und Forscher der Verlassenen, die neue Seuchen, Gebräue und Gifte entwickeln, um die Verlassenen zu verteidigen und ihre Feinde in ganz Azeroth zu vernichten.",al={"wer ist faranell","apothekermeister faranell","apotheker faranell rolle"}},{q="Warum bezeichnet der Sprecher den Spieler als Abscheulichkeit?",a="Der Gefangene blickt mit tiefem Ekel auf die Untoten und ihre Agenten, was eine verbreitete Einstellung unter den Lebenden und den Feinden der Verlassenen ist. Den Besucher als Abscheulichkeit anzuprangern, spiegelt die tiefen Vorurteile und das Entsetzen wider, das Außenstehende gegenüber den beseelten Toten empfinden, die nun in Unterstadt verweilen.",al={"warum abscheulichkeit","wer euch als abscheulichkeit bezeichnet","warum der gefangene wütend ist"}},{q="Wo müsst Ihr nach Abschluss der Aufgabe Bericht erstatten?",a="Die Erkenntnisse über das unkooperative Subjekt müssen direkt bei Apothekermeister Faranell in Unterstadt abgeliefert werden. Faranell weilt tief im Apothekarium, umgeben von brodelnden Kesseln, Laborbottichen und Forscherkollegen, die sich der Herstellung tödlicher Gebräue für Fürstin Sylvanas Windläufer und die Verlassenen widmen.",al={"wo man unending torment abgibt","unending torment abgabe","bei wem man unending torment meldet"}},{q="Wie reagiert Apothekermeister Faranell auf den Trotz des Subjekts?",a="Apothekermeister Faranell ist über die hartnäckige Weigerung des Subjekts, zu kooperieren, überaus erfreut. Anstatt über die Sackgasse verärgert zu sein, betrachtet er sie als eine unterhaltsame Herausforderung. Der oberste Apotheker genießt es, die Grenzen schwieriger Subjekte mithilfe der düsteren und unbarmherzigen Methoden auszutesten, die von der Königlichen Apothekervereinigung entwickelt wurden.",al={"faranells reaktion","was faranell sagt","wird faranell wütend"}}},fp="16,401,23.488.0,19.468.0,25.330.0,37.325.0,34.314.0,52.299.0,48.327.0,68.333.0"}
P.entries["quest:97291"] = {n="Unending Torment",s="Unending Torment ist eine Quest in der Unterstadt, bei der Apothekermeister Faranell versucht, einen wieder zusammengesetzten Gefangenen an den Willen der Dark Lady zu binden. Um das unterwerfende Gebräu zu vollenden, müssen Abenteurer tödliche Reagenzien aus der gesamten Hauptstadt der Verlassenen beschaffen.",h="Unending Torment ist eine Quest in der Unterstadt, bei der Apothekermeister Faranell versucht, einen wieder...",kw={"das apothekarium","blisterweed","essenz der pein","faranell","apothekermeister faranell","tawny grisette","toxic skullcap","unterstadt","unending torment"},ang={["class:Rogue"]="Die Quest erfordert es, sich in das Rogues' Quarter zu wagen, um Essenz der Pein zu kaufen, ein wirksames Reagenz, das typischerweise von Giftherstellern und Attentätern bevorzugt wird.",["faction:Horde"]="Die Royal Apothecary Society braut weiterhin finstere Gebräue tief unter den Ruinen von Lordaeron und testet die Grenzen alchemistischer Unterwerfung aus.",["profession:Herbalism"]="Die Beschaffung von Blisterweed von den Kräuterkundelehrern des Apothekariums verdeutlicht die Überschneidung zwischen gewöhnlichen botanischen Studien und den dunkleren alchemistischen Projekten der Gesellschaft.",["race:Undead"]="Für die Verlassenen ist die Unterwerfung wiederbelebter Überreste in den Dienst der Dark Lady durch alchemistische Qualen gängige Praxis im täglichen Betrieb des Apothekariums."},sec={{t="Den Willen binden",b="Tief im Apothekarium der Unterstadt beaufsichtigt Apothekermeister Faranell grausame Experimente, die darauf abzielen, die Macht der Verlassenen zu stärken. Nachdem er den abgetrennten Kopf eines geschundenen Gefangenen erfolgreich wieder befestigt hat, benötigt Faranell eine spezielle alchemistische Mischung, um den geringen verbliebenen Widerstand der Kreatur zu brechen und ihren Willen dauerhaft an Fürstin Sylvanas Windläufer zu binden."},{t="Apothekerreagenzien",b="Um sein unterwerfendes Gebräu zuzubereiten, schickt Faranell seinen Agenten durch die Unterstadt, um wirksame Zutaten zu sammeln. Die Aufgabe umfasst die Beschaffung eines Toxic Skullcap von Tawny Grisette im Trade Quarter, das Einfordern von Blisterweed von den nahegelegenen Kräuterkundelehrern, die ihm etwas schulden, und den Kauf von Essenz der Pein von einem Gifthändler, der im Rogues' Quarter lauert."},{t="Das Meisterwerk",b="Nach Erhalt der Zutaten äußert Faranell grimmige Genugtuung über sein bevorstehendes Meisterwerk. Er genießt die Aussicht, sein Gebräu an ihrem „ehrenwerten Gast“ zu testen, zuversichtlich, dass der qualvolle Trank die verbliebene Prahlerei des Gefangenen zunichtemachen und die verirrte Kreatur gehorsam in den Dienst der Dark Lady zurückführen wird."}},faq={{q="Wer bietet die Quest Unending Torment an?",a="Die Quest wird von Apothekermeister Faranell vergeben, dem Anführer der Royal Apothecary Society, der sich im Apothekarium in der Unterstadt befindet.",al={"wer gibt unending torment","questgeber unending torment","unending torment start"}},{q="Welche Reagenzien werden für Faranells Gebräu benötigt?",a="Apothekermeister Faranell benötigt drei bestimmte Zutaten: einen Toxic Skullcap von Tawny Grisette im Trade Quarter, Blisterweed aus der Nähe der Kräuterkundelehrer im Apothekarium und Essenz der Pein von einem Gifthändler im Rogues' Quarter.",al={"was sind die zutaten","unending torment gegenstände","welche reagenzien braucht faranell"}},{q="An wem experimentiert Apothekermeister Faranell?",a="Das Subjekt ist ein unwilliger Gefangener, dessen abgetrennter Kopf frisch wieder befestigt wurde. Faranell bezeichnet ihn spöttisch als „verlorenes Schaf“ und „ehrenwerten Gast“ und versucht, jegliche trotzige Prahlerei zu brechen, an die er sich nach schweren Schlägen noch klammert.",al={"wer ist die bestie","wer ist das verlorene schaf das faranell erwähnt","wer wird gefoltert"}},{q="Was ist das Ziel von Faranells Trank?",a="Der Trank ist so formuliert, dass er das Subjekt geistig bricht und es gewaltsam an den Willen von Fürstin Sylvanas Windläufer, der Dark Lady der Verlassenen, bindet. Faranell glaubt, dass der geschundene Zustand der Kreatur sie besonders anfällig für chemische Beherrschung macht.",al={"warum diesen trank herstellen","zweck des tranks von unending torment","was bewirkt das gebräu"}},{q="Wo können Spieler Tawny Grisette finden?",a="Tawny Grisette befindet sich im Trade Quarter der Unterstadt, wo sie Spezialwaren anbietet, darunter den von den Apothekern benötigten Toxic Skullcap.",al={"wo ist tawny grisette","toxic skullcap händler","miss grisette finden"}},{q="Wo befindet sich das Blisterweed?",a="Blisterweed findet man in der Nähe der Kräuterkunde-Lehrer von Unterstadt, den Alliestars, die im Apothekarium residieren. Faranell erwähnt, dass sie ihm einen Gefallen schulden, was es Abenteurern erlaubt, sich frei zu bedienen.",al={"wo man blisterweed findet","alliestaers kräuterkunde","kräuterkundelehrer unterstadt blisterweed"}}},fp="16,252,16.382.0,19.356.0,15.336.1,38.141.0,51.254.0,51.254.0,38.253.0,38.156.0,33.205.0"}
P.entries["quest:97292"] = {n="Unending Torment",s="Unending Torment ist eine Quest in Unterstadt, die von Apothekermeister Faranell im Apothekarium vergeben wird. Spieler unterstützen die Royal Apothecary Society, indem sie ein ätzendes Hissing Serum in eine Tropfvorrichtung einfüllen, die über den Überresten von Othmar angebracht ist. Die Aufgabe dient als dauerhafte Vergeltung für vergangene Verbrechen, die gegen die Dunkle Fürstin begangen wurden.",h="Unending Torment ist eine Quest in Unterstadt, die von Apothekermeister Faranell im Apothekarium vergeben...",kw={"das apothekarium","dunkle fürstin","garithos","hissing serum","apothekermeister faranell","othmar","unterstadt","unending torment"},ang={["faction:Horde"]="Die Unterstützung von Faranell in Unterstadt verdeutlicht die unerbittlichen Methoden, welche die Verlassenen gegen jene anwenden, die sich ihnen und der Bansheekönigin widersetzt haben.",["race:Undead"]="Apothekermeister Faranell leitet die Royal Apothecary Society in Unterstadt, und die Bestrafung von Feinden der Dunklen Fürstin wie Garithos ist von zentraler Bedeutung für die Vergeltung der Verlassenen."},sec={{t="Vergeltung der Apotheker",b="In den feuchten Gängen des Apothekariums von Unterstadt führt Apothekermeister Faranell grausame Experimente durch, um sicherzustellen, dass die Feinde der Verlassenen niemals in Frieden ruhen. Für diese Aufgabe hat Faranell eine ätzende Substanz namens Hissing Serum vorbereitet, die endlos auf ein gefangenes Subjekt tropfen soll, das unter einer alchemistischen Vorrichtung aufgehängt ist."},{t="Das Schicksal von Garithos",b="Das Versuchsobjekt von Faranells Apparatur ist kein Geringerer als Othmar, die Überreste von Grand Marshal Garithos. Da er Verbrechen gegen die Dark Lady begangen hat, hält Faranell ständige chemische Qualen für das Mindeste, was er verdient. Das Serum wird in das über Othmars Körper aufgehängte Gestell geleitet, um sein Fleisch stetig sieden zu lassen, wodurch sichergestellt wird, dass der gefallene Kommandant als Objekt dauerhafter Bestrafung und Untersuchung dient."}},faq={{q="Wer ist Othmar?",a="Othmar bezieht sich auf Grand Marshal Othmar Garithos, den ehemaligen menschlichen Kommandanten, der während der Rückeroberung von Lordaeron eine unsichere Allianz mit Sylvanas Windläufer einging, bevor er von den Verlassenen verraten und getötet wurde. Apothekermeister Faranell hat sich seiner Überreste bemächtigt, um ihn anhaltenden Qualen und Experimenten zu unterziehen.",al={"wer ist othmar","was othmar","othmar garithos"}},{q="Warum wird Othmar gequält?",a="Othmar Garithos arbeitete an der Seite von Sylvanas Windläufer, um Capital City von den Schreckenslords zurückzuerobern, hegte jedoch tiefe Verachtung für Nichtmenschen und versuchte, Lordaeron gänzlich für die Menschheit zurückzufordern. Die Verlassenen machen ihn für Verbrechen gegen die Dunkle Fürstin verantwortlich und erachten die fortwährende chemische Qual als angemessene Vergeltung für seine Arroganz und vergangenen Taten.",al={"warum othmar gefoltert wird","was hat othmar getan","verbrechen gegen sylvanas"}},{q="Wer ist Apothekermeister Faranell?",a="Apothekermeister Faranell ist das Oberhaupt der Royal Apothecary Society im Apothekarium von Unterstadt. Er beaufsichtigt die Entwicklung neuartiger Seren, Toxine sowie Seuchen und leitet diese Operation gegen Othmar direkt.",al={"rolle von faranell","wer vergibt unending torment","apotheker faranell"}},{q="Was bewirkt das Hissing Serum?",a="Das Hissing Serum ist ein von Apothekermeister Faranell gebrautes alchemistisches Gebräu, das darauf ausgelegt ist, Fleisch sieden zu lassen und unerträgliche Schmerzen hervorzurufen. Es wird in eine Tropfvorrichtung eingespeist, die direkt über Othmars aufgehängtem Körper angebracht ist.",al={"was ist hissing serum","serumeffekte","faranells serum"}},{q="Ist Othmar am Leben oder untot?",a="Othmar ist ein Untoter. Garithos wurde von der Dark Lady höchstpersönlich erschlagen, und sein Kopf wurde wieder an den Körper einer Monstrosität angenäht, der zuckend zum Leben erwacht. Faranell bezeichnet ihn als ihren „neuen Gast“ und plant, ihn unter dem herabtropfenden Serum leiden zu lassen.",al={"othmar tot oder lebendig","ist garithos am leben","zustand von othmar"}},{q="Was plant Faranell als Nächstes mit Othmar?",a="Apothekermeister Faranell beabsichtigt, Othmars Fleisch unter der Tropfvorrichtung sieden zu lassen, während er A Watchful Eye auf ihn hat. Faranell gibt an, weitreichende Pläne für Othmars Zukunft zu haben, und nutzt den Elenden für fortlaufende Experimente und Vergeltung.",al={"faranells zukunftspläne","was geschieht als nächstes mit othmar","othmars zukunft"}}},fp="16,341,22.344.0,20.402.1,14.325.0,30.351.0,34.226.0,31.223.0,26.245.0,47.247.0"}
P.entries["quest:973"] = {n="Der Turm von Althalaxx",s="Diese Quest ist das fünfte Kapitel bei der Untersuchung des Turms von Althalaxx, die Abenteurer der Allianz von der Dunkelküste nach Süden ins Eschental führt. Delgren der Läuterer entsendet Euch, um Ilkrud Magthrull, einen am verderbten Schrein des Sengenden Feuers weilenden Hexenmeister der Orcs, niederzustrecken und dessen esoterischen Wälzer zu beschaffen.",h="Diese Quest ist das fünfte Kapitel bei der Untersuchung des Turms von Althalaxx, die Abenteurer der Allianz...",kw={"althalaxx","eschental","delgren","schrein des sengenden feuers","ilkrud","maestra","magthrull","wälzer","hexenmeister"},ang={["class:Paladin"]="Die Zusammenarbeit mit Delgren dem Läuterer, um Teufelsbeschwörer niederzustrecken und verderbte Wälzer zu konfiszieren, spiegelt die klassische Berufung des Heiligen Lichts gegen dämonische Verderbnis wider.",["class:Warlock"]="Die Konfrontation mit Ilkrud Magthrull lässt Euch gegen einen anderen Wirker der dunklen Künste antreten, der beschworene Sukkuben und Leerwandler einsetzt, um seine unheiligen Texte zu bewachen.",["faction:Alliance"]="Diese Aufgabe führt Allianzabenteurer aus der Sicherheit der Dunkelküste tief in die dämonenverseuchten Winkel des Eschentals, um eine wachsende finstere Bedrohung zu läutern.",["race:NightElf"]="Der Schrein des Sengenden Feuers stellt eine abscheuliche Schändung der uralten Wälder des Eschentals dar, weshalb die Beseitigung Ilkruds eine Verteidigung heiliger Ahnenerde bedeutet."},sec={{t="Eine Jagd ins Eschental",b="Auf der Spur der finsteren Kultistenumtriebe, die am Turm von Althalaxx an der Dunkelküste aufgedeckt wurden, erkennt der heilige Krieger Delgren der Läuterer die Handschrift eines gefährlichen Magiewirkers: des Hexenmeisters der Orcs Ilkrud Magthrull. Aus der dämonischen Fäulnis des Schreins des Sengenden Feuers im südwestlichen Eschental heraus bedrohen Ilkruds finstere Machenschaften die unberührten Elfenwälder mit fauliger Magie. Delgren beauftragt Euch damit, den Hexenmeister zu töten und sein Grimoire an Euch zu bringen, um die Pläne seines Meisters offenzulegen."},{t="Das Versteck des Hexenmeisters",b="Der Schrein des Sengenden Feuers ist eine teufelsgezeichnete Ruine voller dämonischer Knechte. Gekennzeichnet durch unheilvolle rote Säulen entlang des felsigen Aufstiegs beherbergt der Schrein Ilkrud zusammen mit einer beschworenen Sukkubus und bewachenden Teufelstötern. Das Besiegen des Orcs im Herzen seiner Dämonendomäne ermöglicht es Delgren, Ilkruds Wälzer nach dunklem Wissen und Befehlen zu durchforsten, die mit den unheilvollen Ritualen bei Althalaxx verknüpft sind."}},faq={{q="Wer ist Delgren der Läuterer?",a="Delgren der Läuterer ist ein Champion der Allianz, der an Maestras Posten stationiert ist, einem Außenposten der Nachtelfen an der Grenze zwischen der Dunkelküste und dem Eschental. Er leitet die Einsätze gegen die dämonische Verderbnis und die in der Region operierenden Kultisten.",al={"delgren","delgren lore","wer startet quest"}},{q="Wer ist Ilkrud Magthrull?",a="Ilkrud Magthrull ist ein mächtiger Hexenmeister der Orcs, der sein Lager am Schrein des Sengenden Feuers im südwestlichen Eschental aufgeschlagen hat. Obwohl er von Delgren anfangs nur als geringfügiges Ärgernis erachtet wurde, macht ihn seine Verbindung zu den finsteren Riten am Turm von Althalaxx zu einem entscheidenden Ziel.",al={"ilkrud","wer ist ilkrud magthrull","orc hexenmeister eschental"}},{q="Wo befindet sich der Schrein des Sengenden Feuers?",a="Der Schrein liegt im südwestlichen Eschental, südlich des Schreins von Aessina und westlich von Astranaar. Er ist eine verderbte, von Dämonen heimgesuchte Enklave, die von zwei markanten roten Säulen flankiert wird, welche zu Ilkruds Altar hinaufführen.",al={"fire scar-schrein ort","wo ist ilkrud","wie ilkrud erreichen"}},{q="Warum benötigt Delgren Ilkrud Magthrulls Wälzer?",a="Ilkruds Wälzer enthält seine finsteren Rituale und Botschaften. Delgren beabsichtigt, die Schriften zu entziffern, um herauszufinden, welches finstere Komplott den Orc-Hexenmeister mit den Kultisten verbindet, die sich um den Turm von Althalaxx herumtreiben.",al={"warum wälzer","was steht in ilkruds wälzer","zweck des wälzers"}},{q="Wie verbindet diese Quest die Dunkelküste mit dem Eschental?",a="Die Questreihe beginnt mit Nachforschungen am Turm von Althalaxx an der Nordküste der Dunkelküste. Als sich das Geheimnis vertieft, führt das Netzwerk der Kultisten Abenteurer südwärts durch die Dunkelküste in die umkämpften Wälder des Eschentals.",al={"quest dunkelküste nach eschental","althalaxx reihe verbindung"}},{q="Was geschieht nach der Bergung des Wälzers?",a="Delgren untersucht den Text, um die tieferen Ränke hinter der Anwesenheit der Kultisten am Turm von Althalaxx zu ergründen, was zu den finalen Konfrontationen der Questreihe führt.",al={"nächste quest","was folgt auf althalaxx 5"}}},fx={b25de95c={q="Warum will Delgren der Läuterer, dass dies erledigt wird?",a="Delgren der Läuterer widmet sich der Ausrottung dämonischer Verderbnis in der Region. Während er Ilkrud Magthrull früher für kaum mehr als ein geringfügiges Ärgernis hielt, machen ihn die finsteren Forschungen des Hexenmeisters und seine aktive Präsenz am korrumpierten Schrein des Sengenden Feuers zu einer wachsenden Bedrohung, die Delgren nicht länger ignorieren kann.",al={"delgrens beweggrund","warum ilkrud magthrull töten","delgren der läuterers ziel"}}},fp="22,305,21.502.0,18.385.1,28.227.0,24.253.0,38.211.0,46.206.0,51.230.0,39.167.0"}
P.entries["quest:97326"] = {n="Rocks to Rests",s="Rocks to Rests ist eine heitere Besorgung für Thra, einen jungen Orc, der mit Freunden hinter Grommash Hold in Orgrimmar Spiele spielt. Die Kinder benötigen die Stärke eines Abenteurers, um glatte Felsblöcke auf ihre Lichtung zu schleppen, damit sie als behelfsmäßige Stühle und Tische dienen können. Es bietet einen charmanten Einblick in den Alltag und die Spiele der jüngeren Generation, die in der Hauptstadt der Horde aufwächst.",h="Rocks to Rests ist eine heitere Besorgung für Thra, einen jungen Orc, der mit Freunden hinter Grommash Hold...",kw={"durotar","grommash hold","orcs","orgrimmar","rocks to rests","glatte felsblöcke","tabletop","thra"},ang={["faction:Horde"]="Sich Zeit zu nehmen, um jungen Orcs hinter der Festung des Kriegshäuptlings zu helfen, zeigt, dass selbst in einer Kriegergesellschaft die Gemeinschaft und das alltägliche Leben in Orgrimmar zählen.",["race:Orc"]="Orc-Jugendliche, die hinter Grommash Hold ihre eigenen Spiele kreieren, spiegeln das alltägliche Heranwachsen der nächsten Generation wider, die im Herzen von Durotar groß wird."},sec={{t="Eine ruhige Ecke von Orgrimmar",b="In der staubigen Lichtung direkt hinter Grommash Hold in Orgrimmar versammelt sich eine Gruppe junger Orcs, fernab der strengen Blicke der Festungswachen. Der Ort bietet reichlich offenen Boden zum Aufstellen von Miniaturfiguren, doch mangelt es an jeglichem richtigen Mobiliar, sodass die Jugendlichen gezwungen sind, direkt im Staub sitzend zu spielen."},{t="Behelfsmäßiges Mobiliar",b="Als ein Jugendlicher namens Thra einen vorbeikommenden Abenteurer erblickt, bittet er um Unterstützung beim Heranschaffen von acht mittelgroßen, glatten Felsblöcken zu ihrem Spielplatz. Dank ihrer flachen Seiten dienen die wuchtigen Steine als stabile behelfsmäßige Stühle und niedrige Tische, wodurch die Jugendlichen ihre Spiele bequem ausrichten können, ohne im Dreck sitzen zu müssen."}},faq={{q="Wer vergibt die Quest Rocks to Rests?",a="Thra ist ein junger Orc, der mit Freunden auf der offenen Lichtung spielt, die sich hinter Grommash Hold in Orgrimmar befindet. Ausgesprochen aufmerksam und verspielt bittet Thra vorbeikommende Abenteurer um eine helfende Hand, um ihren Spielbereich zu verbessern.",al={"wer vergibt rocks to rests","thra orgrimmar","wer ist thra"}},{q="Wo findet diese Quest statt?",a="Die Quest findet auf der Lichtung direkt hinter Grommash Hold statt, dem Sitz von Kriegshäuptling Thrall im Valley of Wisdom in Orgrimmar. Die Kinder versammeln sich auf dieser relativ freien Erdstelle abseits des dichten Verkehrs der Festung.",al={"wo ist rocks to rests","thra aufenthaltsort","wo hinter grommash hold"}},{q="Warum benötigt Thra glatte Felsblöcke?",a="Thra und die anderen Jugendlichen benötigen glatte, mittelgroße Steine, die als behelfsmäßige Stühle und Tische dienen sollen. Ohne Möbel sind sie gezwungen, direkt im Dreck zu sitzen, während sie ihre Miniaturspiele aufbauen und spielen.",al={"warum steine","wozu glatte felsblöcke","warum felsblöcke"}},{q="Welches Spiel wird hinter Grommash Hold gespielt?",a="Thra und die Gefährten spielen ein zwangloses Tabletop-Spiel mit kleinen Figuren, die auf dem Boden verteilt sind. Die glatten Felsblöcke bieten stabile Oberflächen, um Figuren abzustellen und beim Spielen bequem zu sitzen.",al={"welches spiel spielen sie","thra spiel orgrimmar","figuren hinter grommash hold"}},{q="Beinhaltet Rocks to Rests Kämpfe?",a="Nein, Rocks to Rests ist eine einfache, friedliche Besorgung und keine militärische Operation oder Kampfprüfung. Sie setzt gänzlich auf rohe Körperkraft, um schwere Felsblöcke zum Spielplatz der Kinder zu schaffen.",al={"ist rocks to rests gefährlich","kampf rocks to rests"}},{q="Was machen die Kinder mit den Felsblöcken, sobald diese abgeliefert wurden?",a="Sobald die acht glatten Felsblöcke abgeliefert sind, schieben Thra und die Kinder sie auf der staubigen Lichtung in Position und nutzen die flachen Seiten, um Sitzgelegenheiten und Tische für ihre Tabletop-Figuren zu schaffen.",al={"was passiert nach rocks to rests","was macht thra mit steinen"}}},fp="14,375,27.316.0,19.313.0,35.220.0,33.238.0,35.213.0,47.205.0,37.191.0,57.196.0"}
P.entries["quest:97539"] = {n="Silky Sutures",s="Silky Sutures ist eine Quest der Horde im Arathihochland, die von Doktor Gregory Victor im Außenposten Hammerfall angeboten wird. Frustriert über unreparierte Belagerungsschäden und schwindende medizinische Vorräte rekrutiert der ansässige Arzt des Lagers Abenteurer, um giftige Hochlandspinnenseide für den Einsatz als behelfsmäßige Feldnähte zu sammeln. Die Aufgabe verdeutlicht die verzweifelten, von Ressourcenmangel geprägten Bedingungen, mit denen die Verteidiger von Hammerfall konfrontiert sind, während sie darum kämpfen, ihre Wachen und Arbeiter auf den Beinen zu halten.",h="Silky Sutures ist eine Quest der Horde im Arathihochland, die von Doktor Gregory Victor im Außenposten...",kw={"arathihochland","doktor gregory victor","feldnähte","hammerfall","lazarett","silky sutures","spinnenseide","chirurgische spinnenseide"},ang={["faction:Horde"]="Hammerfall stellt eine wichtige Festung der Horde im Arathihochland dar, weshalb Doktor Victors Bemühungen, deren Verteidiger gesund und kampfbereit zu halten, für das regionale Überleben der Fraktion von entscheidender Bedeutung sind.",["race:Undead"]="Doktor Gregory Victor bringt die für die Verlassenen charakteristische pragmatische, unsentimentale medizinische Expertise nach Hammerfall ein und nutzt improvisierte Ressourcen des Hochlands, um den Betrieb der Klinik aufrechtzuerhalten."},sec={{t="Der zerfallende Außenposten",b="Hammerfall behauptet sich im rauen Arathihochland, doch das Lager zeigt sichtbare Spuren anhaltender Belastung. Unreparierte Belagerungsschäden zeichnen die Befestigung, was den örtlichen Arzt, Doktor Gregory Victor, zu der bitteren Bemerkung verleitet, dass Vernachlässigung offizielle Politik zu sein scheine. Trotz der bröckelnden Festungsanlagen und des Mangels an breiterer Unterstützung weigert sich Victor, sein Lazarett dem Verfall preiszugeben. Die Aufrechterhaltung einer funktionierenden Klinik ist unerlässlich, um die Arbeiter und Schildwachen aufrecht und kampfbereit zu halten."},{t="Behelfsmäßige medizinische Vorräte",b="Schwindende Vorräte haben die Krankenstation von Hammerfall an den Rand der Erschöpfung gebracht und zwingen Doktor Victor zur Improvisation auf dem Schlachtfeld. Wenn herkömmliche Verbände und Nähte knapp werden, kann die zähe, reißfeste Seide von Hochlandspinnen zu überraschend widerstandsfähigen Feldnähten verdrillt werden. Obwohl Victor trocken bemerkt, dass das Infektionsrisiko die geringste Sorge eines verwundeten Soldaten sei, verschafft das Erbeuten der Seide dem Lazarett die lebenswichtige Ausrüstung, die benötigt wird, um verwundete Verteidiger in feindseligem Gebiet zusammenzuflicken."},{t="Galgenhumor in Hammerfall",b="Der Betrieb einer Frontklinik unter Belagerungsbedingungen erfordert ein abgehärtetes Gemüt, das Doktor Gregory Victor im Überfluss an den Tag legt. Indem er Reisende mit bissigen Witzen über düstere Prognosen und Spinnenfadennähte begrüßt, überspielt der Arzt die bittere Realität der Isolation von Hammerfall. Regelmäßige Hilfe bleibt im Hochland selten, weshalb jede Unterstützung durch durchreisende Helden entscheidend für den Fortbestand der Klinik ist. Durch improvisierte Heilmittel und starrsinnigen Trotz stellt Victor sicher, dass die Verwundeten von Hammerfall Pflege erhalten, selbst wenn der Außenposten um sie herum dem Verfall überlassen scheint."}},faq={{q="Wer ist Doktor Gregory Victor?",a="Doktor Gregory Victor ist der leitende Sanitätsoffizier und Unfallchirurg, der das Lazarett in Hammerfall im Arathihochland leitet. Ausgestattet mit einem bissigen Witz und einem sachlichen Ansatz bei der Triage auf dem Schlachtfeld arbeitet er unermüdlich daran, verwundete Wachen und Arbeiter zu behandeln. Trotz gravierender Versorgungsengpässe und unreparierter Belagerungsschäden im gesamten Außenposten bleibt Victor entschlossen zu verhindern, dass die Krankenstation der Vernachlässigung anheimfällt.",al={"wer ist victor","gregory victor lore","hammerfall arzt"}},{q="Warum benötigt Doktor Victor Spinnenseide?",a="Das Lazarett in Hammerfall hat fast keine medizinischen Standardvorräte und Ausrüstungsgegenstände mehr. Unter extremem Druck auf dem Schlachtfeld greift Doktor Victor auf Improvisation zurück und spinnt robuste Hochlandspinnenseide zu wirksamen chirurgischen Fäden, um Fleischwunden und Verletzungen zu nähen. Die Spinnenseide liefert einen strapazierfähigen Faden, der in der Lage ist, zerrissenes Fleisch zusammenzuhalten, wenn ordentliche klinische Nähte nicht verfügbar sind.",al={"warum spinnenseide","nutzung von chirurgischer spinnenseide","spinnenseidennaht"}},{q="In welchem Zustand befindet sich Hammerfall während dieser Quest?",a="Hammerfall befindet sich in einem Zustand sichtbarer Vernachlässigung und physischer Zerrüttung. Alte Belagerungsschäden entlang der Verteidigungsanlagen des Lagers sind völlig unrepariert, was Doktor Victor den Eindruck vermittelt, dass behördliche Vernachlässigung zur offiziellen Politik geworden ist. Der Stützpunkt leidet unter einem Mangel an beständiger Hilfe und Vorräten von außerhalb, sodass die dort stationierten Wachen, Arbeiter und das medizinische Personal gezwungen sind, für sich selbst zu sorgen.",al={"hammerfall status","warum ist hammerfall beschädigt","zustand von hammerfall"}},{q="Woher stammen die Spinnen für diese Quest?",a="Die Spinnen streifen durch die Wildnis des Arathihochlands rund um das Lager von Hammerfall. Abenteurer, die sich vor die Mauern des Außenpostens wagen, müssen diese aggressiven Spinnentiere in den Ebenen des Hochlands jagen, um die für Doktor Victors Feldnähte benötigte chirurgische Spinnenseide zu erbeuten, bevor sie sicher in die Klinik zurückkehren.",al={"arathispinnen","wo man spinnenseide findet","fundort von chirurgischer spinnenseide"}},{q="Warum äußert sich Doktor Victor sarkastisch über Infektionen?",a="Als ihm die gesammelte Spinnenseide überreicht wird, scherzt Doktor Victor, dass eine kleine Infektion die geringste Sorge eines verwundeten Soldaten sei, wenn er wieder zusammengeflickt werde. Dieser schwarze Humor spiegelt die bittere Realität der Triage an vorderster Front in Hammerfall wider, wo das Verhindern schweren Blutverlusts und tödlicher Traumata auf dem Schlachtfeld Vorrang vor sterilem klinischen Luxus hat.",al={"arzt humor","spinnenseide infektion","victor witze"}},{q="Warum sind die Vorräte in Hammerfall so knapp?",a="Hammerfall liegt in einer umkämpften und isolierten Lage im Arathihochland, umgeben von feindlichen Bedrohungen und abgeschnitten von beständigen Nachschublinien. Verstärkung und logistische Lieferungen von außerhalb treffen selten ein, sodass die Garnison und das Lazarett des Außenpostens unter chronischen Engpässen bei Rohstoffen, Werkzeugen und einfachen Heilmitteln leiden.",al={"warum keine vorräte","hammerfall versorgungsengpass","fehlende hilfe hammerfall"}},{q="Wen behandelt das Lazarett in Hammerfall?",a="Das Lazarett untersteht direkt Doktor Gregory Victor und ist für die Behandlung der in Hammerfall stationierten Arbeiter und Wachen zuständig. Da der Außenposten durch Gefahren des Hochlands und bauliche Schäden ständiger Belastung ausgesetzt ist, ist die Erhaltung der körperlichen Gesundheit dieser Verteidiger unerlässlich, um die Siedlung befestigt und einsatzfähig zu halten.",al={"wen behandelt victor","hammerfall patienten","klinikpatienten"}}},fp="13,478,21.507.0,26.542.0,27.573.0,29.431.0,40.397.0,50.396.0,46.324.0,47.364.0,41.347.0,43.336.0"}
P.entries["quest:97558"] = {n="Hides for the Forsaken",s="Eine düstere Notwendigkeit der Existenz als Untoter in Tirisfal, wo die Verlassenen Tierhäute plündern müssen, um ihr verwesendes Fleisch zu ersetzen. Shelene Rhobart beauftragt Abenteurer damit, Felle von Dunkelhunden, Nachtsaugerflügelmembranen und Murlochaut zu sammeln, um beschädigte Körper zu flicken.",h="Eine düstere Notwendigkeit der Existenz als Untoter in Tirisfal, wo die Verlassenen Tierhäute plündern...",kw={"dunkelhundfell","nachtsaugerflügel","hides for the forsaken","shelene rhobart","tirisfal","transplantat für untote","vile fin-murloc"},ang={["profession:Tailoring"]="Die Schneiderei der Verlassenen überschneidet sich oft mit der Leichenschau, wobei Nähfertigkeiten nicht nur für Kleidungsstücke eingesetzt werden, sondern um rohe Bestienmembranen an verwesenden Körpern zu befestigen.",["race:Undead"]="Eine deutliche Erinnerung an die praktischen Belastungen des Zustands der Verlassenen, bei denen das Überleben manuelle Instandhaltung und geplünderte Transplantate statt natürlicher Heilung erfordert."},sec={{t="Der Preis des Untodes",b="Das Fleisch der Verlassenen heilt nicht auf natürliche Weise. Körperliche Wunden hinterlassen verwesende Lücken, die sich nicht durch normale biologische Mittel regenerieren können. Um ihre Gestalt zu bewahren und ihre Leichen funktionsfähig zu halten, müssen die Verlassenen organisches Material aus der Welt der Lebenden beschaffen und Ersatzteile über ihre Verletzungen nähen."},{t="Spezialisierte Materialien",b="Nicht jede Haut erfüllt den gleichen anatomischen Zweck. Dickes Dunkelhundfell bietet Haltbarkeit für großflächige, robuste Reparaturen. Empfindliche Nachtsaugerflügelmembranen sind leicht und biegsam genug, um Gesichter und Finger zu bedecken, ohne steife, klobige Schichten zu erzeugen. Währenddessen wird die biegsame Haut der Vile Fin-Murlocs gesammelt, um innere Membranen und empfindliche Bereiche wie das Innere der Wangen und den Mund auszukleiden."}},faq={{q="Warum benötigen die Verlassenen Tierhäute?",a="Die Haut eines Untoten heilt oder regeneriert sich bei Beschädigungen nicht auf natürliche Weise. Um körperliche Verletzungen zu überstehen und den äußeren Verfall aufzuhalten, ernten die Verlassenen Häute und Membranen von lebenden Kreaturen, um sie über ihre verwundeten Körper zu flicken und zu nähen.",al={"warum verlassene häute benötigen","heilung der untoten lore","heilen untote"}},{q="Wer ist Shelene Rhobart?",a="Shelene Rhobart ist eine Lederverarbeiterin der Verlassenen in Tirisfal. Sie sammelt verschiedene Häute und biologische Materialien, um sicherzustellen, dass beschädigte Verlassene über die Ressourcen verfügen, die sie benötigen, um ihre verwesenden Gestalten zu flicken.",al={"shelene rhobart","wer ist shelene"}},{q="Warum werden Nachtsaugerflügelmembranen speziell benötigt?",a="Nachtsaugerflügelmembranen sind im Vergleich zu schwereren Fellen außergewöhnlich dünn und geschmeidig. Diese Leichtigkeit macht sie ideal für die Abdeckung empfindlicher und komplexer Teile der Anatomie, wie Gesichtszüge und Finger, und verhindert, dass die transplantierte Haut zu dick oder starr wird.",al={"verwendung von nachtsaugerflügeln","warum nachtsauger-membran"}},{q="Wofür wird Murlochaut verwendet?",a="Die Haut der Vile Fin-Murlocs besitzt eine einzigartige Feuchtigkeit und Flexibilität, wodurch sie sich gut für innere Membranen oder empfindliche Schleimhautoberflächen wie das Innere von Wangen und Mündern eignet.",al={"warum murlochaut","murlochaut untote"}},{q="Wo findet man diese Materialien?",a="Alle drei Kreaturen durchstreifen die heimgesuchten Landschaften von Tirisfal. Dunkelhunde und Nachtsauger lauern in den Wäldern und an den Straßenrändern, während Vile Fin-Murlocs an der Nordküste und an den Binnengewässern nisten.",al={"wo bekommt man häute","tirisfal-kreaturen"}},{q="Ist die Verwendung von Tierhäuten bei den Verlassenen üblich?",a="Ja. Die Beschaffung von Gewebe von Tieren und geplünderten Überresten ist ein grundlegender Teil des alltäglichen Überlebens der Verlassenen. Ohne Zugang zu Ersatzfleisch und -häuten würden ungeheilte Wunden die darunter liegenden Knochen, Organe und Muskeln vollständig den Elementen aussetzen.",al={"verwenden alle verlassene häute","fleischformung der verlassenen"}}},fx={["84f1a52c"]={q="Wofür wird das Darkhound Hide verwendet?",a="Das Fleisch von Untoten heilt nicht auf natürliche Weise von Verletzungen, was die Verlassenen dazu zwingt, ihre Körper mit geernteten Tierfellen zu flicken. Während empfindliches Gewebe dünne Membranen erfordert, dienen dickere und härtere Felle wie das Darkhound Hide als dauerhafte Transplantate für breite, stark beanspruchte Oberflächen am Körper, die eine zähe, widerstandsfähige Ersatzhaut erfordern.",al={"nutzen von darkhound hide","warum darkhound hide","darkhound hide verlassene"}}},fp="22,266,20.316.0,21.383.0,38.240.0,23.197.0,51.273.0,29.175.0,32.197.0,46.256.0"}
P.entries["quest:97583"] = {n="WRIGGLE.",s="WRIGGLE. ist eine Begegnung mit einem leicht erregbaren jungen Schleim, der es liebt zu tanzen, bis ihm die Energie ausgeht. Um die Kreatur wiederzubeleben und sich mit ihr anzufreunden, muss ein Abenteurer eine besondere Portion nahrhafte Pampe aus den Kanälen von Unterstadt beschaffen.",h="WRIGGLE.",kw={"canals","leicht erregbarer schleim","nahrhafte schleimpampe","schleim","pampe","unterstadt","wriggle"},ang={["faction:Horde"]="Die Beschaffung der speziellen Pampe erfordert es, sich in die Kanäle der Hauptstadt der Verlassenen, Unterstadt, zu wagen, um mit einheimischen Händlern zu handeln.",["race:Undead"]="Die Verlassenen sind an die giftigen Abflüsse und die belebten Schleime gewöhnt, die in den Kanalnetzen von Unterstadt hausen, was einen Schleimbegleiter zu einer natürlichen Ergänzung macht."},sec={{t="Ein tanzender Schleim",b="WRIGGLE. beinhaltet die Interaktion mit einem lebhaften, leicht erregbaren kleinen Schleim, der mit Freude die Tanzbewegungen freundlicher Reisender nachahmt. Trotz seiner Begeisterung erschöpft das Tanzen den kleinen Schlamm schnell, sodass er ermattet zurückbleibt und Nahrung benötigt, um seine Kräfte wiederzuerlangen."},{t="Nahrung aus den Canals",b="Um die erschöpfte Kreatur wiederzubeleben, müssen Abenteurer nach Nahrhafter Schleimpampe suchen, einer eigentümlichen Mischung, die in den ranzigen Kanälen von Unterstadt verkauft wird. Sobald der gestärkte Schleim diesen bevorzugten üblen Leckerbissen absorbiert hat, schließt er sich begierig seinem Versorger an, bereit, seinem neuen Freund zu folgen."}},faq={{q="Was ist WRIGGLE.?",a="WRIGGLE. ist eine Begegnung, bei der sich ein Abenteurer durch Tanzen mit einem leicht erregbaren kleinen Schleim anfreundet, nur um festzustellen, dass die Kreatur spezielle Nahrung benötigt, um ihre Energie aufrechtzuerhalten.",al={"wriggle quest","was ist wriggle","schleimtanz quest"}},{q="Wo findet Ihr Nahrhafte Schleimpampe?",a="Nahrhafte Schleimpampe wird von einem Händler verkauft, der in den Kanälen von Unterstadt ansässig ist, wo alchemistischer Abfall und Abflüsse alltäglich sind.",al={"wo man pampe bekommt","händler für nahrhafte schleimpampe","schleim füttern unterstadt"}},{q="Wie erregt Ihr die Aufmerksamkeit des Schleims, wenn er müde wirkt?",a="Wenn der leicht erregbare Schleim müde oder abgelenkt wird, erregt das Tanzen mit ihm seine Aufmerksamkeit und spiegelt seine verspielten Bewegungen wider.",al={"wie man aufmerksamkeit des schleims erregt","müder schleim","schleim aufwecken wriggle"}},{q="Warum ernährt sich der Schleim von Pampe?",a="Schleime absorbieren alchemistischen Umgebungsschlamm und -pampe, um sich zu ernähren und Vitalität wiederzuerlangen, wodurch sie sich nach dem Energieaufwand verjüngen.",al={"warum schleim pampe frisst","was fressen schleime"}},{q="Was geschieht, sobald der Schleim gefüttert wurde?",a="Nachdem er mit seiner bevorzugten Pampe genährt wurde, schließt sich der wiederbelebte Schleim dem Abenteurer an und versucht, ihm überallhin zu folgen.",al={"folgt einem der schleim","schleimbegleiter","wriggle belohnung"}},{q="Können Spieler der Allianz die Pampe leicht erhalten?",a="Da die Beschaffung der notwendigen Nahrhaften Schleimpampe den Besuch der Händler in den Kanälen von Unterstadt erfordert, werden Reisende der Allianz das Betreten der Hauptstadt der Verlassenen als extrem gefährlich empfinden.",al={"kann allianz wriggle machen","allianz schleimpampe"}}},fp="8,236,15.270.0,26.283.0,17.182.0,42.139.0,57.124.0,34.127.0,35.129.0,46.196.0"}
P.entries["quest:976"] = {n="Nachschub für Auberdine",s="Nachschub für Auberdine ist eine Begleitmission, bei der Abenteurer der Allianz Feero Eisenhand beschützen, während er wichtige Vorräte und Nachrichten von Maestras Posten nach Norden in Richtung Dunkelküste bringt. Angesichts der wachsenden Bedrohung, die vom Turm von Althalaxx ausgeht, und der Anwesenheit feindlicher Infiltratoren im Eschental kann eine sichere Durchreise nicht als selbstverständlich angesehen werden.",h="Nachschub für Auberdine ist eine Begleitmission, bei der Abenteurer der Allianz Feero Eisenhand beschützen...",kw={"eschental","auberdine","balizar the umbrage","dunkelküste","delgren der läuterer","feero eisenhand","maestras posten","sentinel starbreeze","turm von althalaxx"},ang={["faction:Alliance"]="Die Sicherung dieses Korridors gewährleistet, dass die Außenposten im Eschental mit dem logistischen Knotenpunkt von Auberdine verbunden bleiben, wodurch der fragile Halt der Allianz im nördlichen Kalimdor gewahrt wird.",["race:Human"]="Feero Eisenhand verkörpert die Bereitschaft der Menschen, Verbündete der Kaldorei tief in unbekannten, gefährlichen alten Wäldern zu unterstützen.",["race:NightElf"]="Die nach Norden gesandten Vorräte und Depeschen helfen den Schildwachen in Auberdine direkt dabei, der wachsenden Dunkelheit in ganz Dunkelküste und entlang der Grenze zum Eschental zu trotzen."},sec={{t="Ein gefährlicher Weg nach Norden",b="Maestras Posten liegt an der westlichen Grenze des Eschentals, ein ruhiger Außenposten, gefangen zwischen den wilden Spannungen des Waldes und den unruhigen Landen der Dunkelküste. Nach Untersuchungen der unheimlichen Aktivitäten rund um den Turm von Althalaxx sammelt Delgren der Läuterer lebenswichtige Vorräte und Geheimdienstberichte, die für Sentinel Starbreeze in Auberdine bestimmt sind. Anstatt einzelne Kuriere zu riskieren, verlässt sich der Außenposten auf bewaffnete Eskorten, die Feero Eisenhand bei seinem Marsch über die Waldstraße begleiten."},{t="Schatten am Wegesrand",b="Die Reise offenbart, wie unsicher die Wildnis rund um die Straße geworden ist. Feeros Route wird von koordinierten Hinterhalten heimgesucht. Kultisten des Dark Strand versuchen, jeden Bericht über ihre dämonischen Rituale zu unterdrücken, Späher der Verlassenen pirschen durch das Unterholz des Waldes, und bösartige Anführer wie Balizar the Umbrage, Aligar the Tormentor und Caedakar the Vicious versuchen, die Karawane niederzumachen, bevor sie die Grenze erreicht."}},faq={{q="Wer ist Feero Eisenhand?",a="Feero Eisenhand ist ein menschlicher Kurier, der an Maestras Posten im westlichen Eschental stationiert ist. Von Delgren dem Läuterer damit betraut, wichtige Nachrichten und logistische Hilfe nach Auberdine zu bringen, ist er vorsichtig genug, um sich zu weigern, ohne fähige Leibwächter zu reisen.",al={"feero","feero eisenhand lore","wer ist der zwergen-begleiter"}},{q="Warum benötigt Auberdine diesen Nachschub?",a="Die Dunkelküste und das nördliche Eschental sehen sich wachsender Verderbnis und Bedrohungen durch dämonische Kultisten gegenüber, die vom Turm von Althalaxx aus operieren. Die in Auberdine stationierten Schildwachen der Nachtelfen, die vor Ort von Persönlichkeiten wie Sentinel Starbreeze angeführt werden, benötigen frische Vorräte und aktuelle Informationen, um die Verteidigung der Küste aufrechtzuerhalten.",al={"warum nachschub nach auberdine schicken","auberdine nachschub","sentinel starbreeze"}},{q="Wer greift Feero entlang der Straße an?",a="Feero warnt davor, dass im gesamten Wald gefährliche Feinde lauern, und bittet um Wachen. Wer die Angreifer sind, stellt sich während der Eskorte heraus.",al={"wer überfällt feero","feero angreifer","wer greift auf der straße an"}},{q="Was ist die Verbindung zum Turm von Althalaxx?",a="Delgren der Läuterer hat die Bemühungen koordiniert, die finsteren Rituale der Kultisten am Turm von Althalaxx aufzudecken und zu stören. Diese Eskorte ist aus dieser Untersuchung hervorgegangen, um sicherzustellen, dass Geheimdienstinformationen und lebenswichtige Unterstützung die Führung der Nachtelfen in Auberdine erreichen.",al={"althalaxx verbindung","turm von althalaxx","delgren verbindung"}},{q="Wo melde ich mich nach dem Schutz von Feero?",a="Nachdem Ihr Feero sicher durch die Hinterhalte im Eschental geleitet habt, meldet Ihr Euch bei Delgren dem Läuterer an Maestras Posten zurück, um zu bestätigen, dass die Lieferung erfolgreich war.",al={"nachschub für auberdine abgeben","wohin nach feeros begleitung","quest abgeben"}}},fx={["1813fb85"]={q="Warum möchte Feero Eisenhand diese Vorräte ausliefern?",a="Delgren der Läuterer beauftragte Feero damit, wichtige Vorräte und lebenswichtige Nachrichten nach Norden an Sentinel Starbreeze in Auberdine zu liefern. Dunkle Mächte und Kultisten, die mit finsteren Plänen infiziert sind, operieren im gesamten westlichen Eschental, und Feero weiß, dass es für die Verteidigung der Allianz verheerend sein könnte, wenn diese sensiblen Kommunikationen oder Proviante in feindliche Hände fallen würden.",al={"feero eisenhands beweggrund","warum braucht feero hilfe","warum vorräte nach auberdine"}},affb8fb0={q="Warum bittet Feero Eisenhand Euch um Schutz anstatt die Wachen des Postens?",a="Feero reist nur ungern allein, während er wichtige Vorräte und Nachrichten durch das gefährliche Eschental trägt. Er bittet um Leibwächter, um der Lieferung zu helfen, Auberdine sicher zu erreichen.",al={"warum ich feero","warum braucht feero geleitschutz","warum geht feero nicht allein"}}},fp="21,347,21.488.0,23.428.1,22.248.0,39.317.0,33.151.0,49.269.0,41.153.0"}
P.entries["quest:97891"] = {n="Prompt Potion Runner",s="Prompt Potion Runner ist eine dringende Lieferquest in Unterstadt, bei der Spieler ein instabiles Gebräu über den Schleimkanal zum Apothekarium bringen müssen. Die Quest verdeutlicht die körperlichen Gebrechen des Untods und die unbeständige Natur der alchemistischen Forschung der Verlassenen.",h="Prompt Potion Runner ist eine dringende Lieferquest in Unterstadt, bei der Spieler ein instabiles Gebräu über...",kw={"alessandro","das apothekarium","doctor martin felben","prompt potion runner","royal apothecary society","schleimkanal","unterstadt","instabiler trank"},ang={["faction:Horde"]="Unterstadt dient als entscheidender Knotenpunkt für die Horde, auch wenn Reisende die giftigen Schleimkanäle durchqueren müssen, um den Verlassenen bei ihren gefährlichen alchemistischen Unterfangen beizustehen.",["race:Undead"]="Die Lieferung verdeutlicht die fragile körperliche Realität des Unlebens der Verlassenen, in der brüchige Gelenke und verfallende Knie lebenswichtige Laborarbeiten der Royal Apothecary Society leicht durchkreuzen können."},sec={{t="Ein Wettlauf gegen den Verfall",b="In den unterirdischen Gängen von Unterstadt benötigt der Alchemist der Verlassenen, Alessandro, dringend einen schnellen Kurier. Da er ein hochgradig flüchtiges Gebräu mit einer extrem kurzen Haltbarkeit hergestellt hat, kann er es aufgrund des gebrechlichen Zustands seiner untoten Gelenke nicht riskieren, es selbst über den giftigen Schleimkanal der Stadt zu transportieren. Ein Abenteurer muss gegen die Zeit antreten, um sicherzustellen, dass das Gebräu unversehrt ankommt, bevor es zu nutzlosem Schlamm zerfällt."},{t="Die Forderungen des Apothekariums",b="Das Ziel ist das Apothekarium, wo Doctor Martin Felben die Lieferung für seine laufenden Forschungen ungeduldig erwartet. Felben enthüllt, dass die vorherigen sechs Kuriere oder Versuche fehlschlugen, da die Tränke während des Transports destabilisierten. Eine rechtzeitige Ankunft ermöglicht es dem Doktor, seine düsteren Experimente ununterbrochen fortzusetzen, was sowohl die Flüchtigkeit der Gebräue der Royal Apothecary als auch die körperlichen Unbilden des Untods unterstreicht."}},faq={{q="Wer gibt diese Quest?",a="Die Quest wird von Alessandro in Unterstadt vergeben. Er benötigt einen Abenteurer, der über den Schleimkanal sprintet, da seine eigenen verfallenden untoten Knie herausspringen und klappern, wenn er zu laufen versucht.",al={"wer gibt prompt potion runner","wer startet prompt potion runner","wer ist alessandro"}},{q="Wohin muss der Trank gebracht werden?",a="Der Trank muss zu Doctor Martin Felben gebracht werden, der alchemistische Experimente im Apothekarium von Unterstadt durchführt.",al={"wohin bringt man den trank","wer ist doctor martin felben","prompt potion runner abgeben"}},{q="Warum ist die Lieferung zeitlich begrenzt?",a="Das Gebräu ist ein instabiler Trank mit einer außergewöhnlich kurzen Haltbarkeit. Wenn es nicht schnell über den Kanal gebracht wird, destabilisiert die Mischung und wird unbrauchbar.",al={"warum zeitbegrenzt","haltbarkeit instabiler trank","warum beeilen"}},{q="Sind andere Lieferversuche fehlgeschlagen?",a="Doctor Martin Felben merkt an, dass die vorherigen sechs Tränke, die Alessandro zu schicken versuchte, unterwegs destabilisierten, bevor sie das Apothekarium erreichten, was Eure erfolgreiche Lieferung zu einem seltenen Triumph macht.",al={"sind andere kuriere gescheitert","alessandros frühere versuche","wie viele tränke sind fehlgeschlagen"}},{q="Warum kann Alessandro den Trank nicht selbst abliefern?",a="Alessandro erklärt, dass seine Knie jedes Mal klappern und herausspringen, wenn er zu laufen versucht, und bezeichnet dies als eine weitere bedauerliche körperliche Nebenwirkung des Untods, die ihn daran hindert, die Lieferung selbst eilig zu überbringen.",al={"warum kann alessandro nicht selbst liefern","alessandros knie"}},{q="Was sind Doctor Felbens Experimente?",a="Doctor Martin Felben ist ein Apotheker, der Experimente im Apothekarium durchführt. Während die genaue Formel geheim gehalten wird, nimmt er seine Forschung unverzüglich wieder auf, sobald die stabile Mischung eintrifft.",al={"was macht doctor felben","wofür wird der trank verwendet"}}},fp="20,263,20.434.0,26.420.0,21.183.0,33.127.0,26.171.0,36.194.0,48.195.0,37.191.0"}
P.entries["quest:97894"] = {n="Geschäfte in Auberdine",s="Geschäfte in Auberdine ist eine Botenaufgabe, die von dem Zwergenhändler Borgus Steelhand in Sturmwind angeboten wird. Borgus bittet Reisende, die nach Westen segeln, nach seinem Bruder Gorbold zu sehen, der vor Kurzem den Handel im Nachtelfenhafen von Auberdine aufgenommen hat. Dies verbindet die geschäftigen Docks der Menschenhauptstadt mit den nebligen Küsten des nördlichen Kalimdor.",h="Geschäfte in Auberdine ist eine Botenaufgabe, die von dem Zwergenhändler Borgus Steelhand in Sturmwind...",kw={"auberdine","borgus steelhand","geschäfte in auberdine","dunkelküste","gorbold stahlhand","händler","steelhand","hafen von sturmwind"},ang={["faction:Alliance"]="Die direkte Seeverbindung zwischen dem Hafen von Sturmwind und Auberdine stärkt die Handels- und Militärbeziehungen zwischen dem Menschenkönigreich und den Ländern der Kaldorei im nördlichen Kalimdor.",["race:Dwarf"]="Der Handel der Zwerge reicht weit über die Berge von Khaz Modan hinaus; unternehmungslustige Händler wie die Steelhands errichten ihre Stände selbst in den ruhigen, schattigen Siedlungen der Nachtelfen."},sec={{t="Ein Zwerg fern der Heimat",b="Die Familie Steelhand ist für ihren Scharfsinn und fairen Handel bekannt, und Borgus bürgt gerne für ihren Ruf. Sein Bruder, Gorbold Stahlhand, wagte sich vor Kurzem über das große Meer, um einen Händlerstand in Auberdine zu betreiben. Schiffe zu versorgen, die die Dunkelküste anlaufen, schien ein einfacher Weg zu Wohlstand zu sein, doch wochenlanges völliges Schweigen beunruhigt Borgus darüber, wie es seinem Bruder so weit weg von Eisenschmiede und Sturmwind tatsächlich ergeht."},{t="Die Hafenpassage",b="Von den Östlichen Königreichen in die ungezähmte Wildnis von Kalimdor zu segeln, erforderte früher umständliche Reisen über den Hafen von Menethil oder neutrale Goblinhäfen wie Beutebucht. Borgus weist Reisende auf ein Schiff hin, das am südlichsten Steg im Hafen von Sturmwind liegt und eine direkte Seeverbindung zu den langen Holzpiers von Auberdine bietet."}},faq={{q="Wer ist Borgus Steelhand?",a="Borgus Steelhand ist ein Zwergenhändler in Sturmwind. Stolz auf den Ruf seiner Familie für ehrliche Geschäfte, sucht er nach durchreisenden Abenteurern, die seinem Bruder Gorbold jenseits des Meeres eine Nachricht überbringen.",al={"borgus steelhand","wer gibt geschäfte in auberdine","borgus"}},{q="Wo befindet sich Gorbold Stahlhand?",a="Gorbold Stahlhand hält sich in Auberdine auf, der Hauptsiedlung an der Dunkelküste entlang der Nordwestküste von Kalimdor. Er betreibt einen Händlerstand, der ankommende Schiffe versorgt.",al={"wo ist gorbold","gorbold stahlhand finden","gorbold standort"}},{q="Wie gelangt man von Sturmwind nach Auberdine?",a="Ein Schiff legt direkt am südlichsten Steg im Hafen von Sturmwind ab und befördert Passagiere geradewegs über das große Meer zu den Docks von Auberdine an der Dunkelküste.",al={"schiff nach auberdine","wie man von sturmwind zur dunkelküste kommt","schiff von sturmwind nach auberdine"}},{q="Warum macht sich Borgus Sorgen um seinen Bruder?",a="Gorbold brach vor Wochen auf, um einen Händlerstand in Auberdine zu übernehmen, in der Hoffnung, durch die Versorgung von Seefahrtschiffen großen Gewinn zu erzielen. Seit seiner Abreise hat er jedoch keine Nachricht nach Hause geschickt, weshalb Borgus Reisende bittet, der Sache nachzugehen.",al={"warum nach gorbold sehen","was ist mit gorbold passiert"}},{q="Was für eine Siedlung ist Auberdine?",a="Auberdine ist ein Zufluchtsort an der Küste, der hauptsächlich von Nachtelfen erbaut und bewohnt wird. Gelegen an der Dunkelküste dient er als primärer Umschlagplatz der Allianz und Fährverbindung zwischen dem nördlichen Kalimdor und dem Inselreich Teldrassil.",al={"was ist auberdine","auberdine stadt"}},{q="Wofür ist die Familie Steelhand bekannt?",a="Die Steelhands sind eine Händlerfamilie der Zwerge, bekannt für ihren Handel, ihre Marktstände und ihren Anspruch, Reisenden wie Hafenarbeitern stets ein faires Geschäft anzubieten.",al={"familie steelhand","steelhands"}}},fp="21,329,21.430.0,18.345.0,24.185.0,35.169.0,42.162.0,40.238.0,37.232.0,39.163.0"}
P.entries["quest:97903"] = {n="Camping 101: First Aid",s="Camping 101: First Aid ist eine Lehrquest, die erfahrene Reisende zu Rawrk in Klingenhügel schickt, der ihnen beibringt, wie sie ihre eigene Verbandtasche für das Überleben in der Wildnis herstellen. Sie betont die Notwendigkeiten der Selbstständigkeit unterwegs und erinnert Abenteurer daran, das Errichten von Lagerfeuern zu meistern und lokale Siedlungen zu respektieren, indem sie draußen in der Wildnis lagern.",h="Camping 101: First Aid ist eine Lehrquest, die erfahrene Reisende zu Rawrk in Klingenhügel schickt, der ihnen...",kw={"lagerfeuer","camping 101","durotar","verbandtasche","rawrk","klingenhügel","überleben","wildnislager"},ang={["faction:Horde"]="Mit Ausgangspunkt in Klingenhügel in Durotar richtet sich diese Ausbildung an Reisende der Horde, die ihren Lebensunterhalt in den rauen Grenzlanden von Kalimdor bestreiten möchten.",["profession:Cooking"]="Lagerbau und Kochkunst gehen Hand in Hand; Rawrk merkt an, dass das Aufschlagen eines ordentlichen Lagers ein loderndes Lagerfeuer erfordert – eine unverzichtbare Technik, die von Kochlehrern vermittelt wird."},sec={{t="Überleben an der Grenze",b="Das Überleben in den ungezähmten Weiten von Durotar und darüber hinaus erfordert mehr als bloße kriegerische Stärke; es verlangt Selbstversorgung auf den Pfaden. In Klingenhügel bietet Rawrk fähigen Wanderern Unterweisung, die unverzichtbare Wildnisausrüstung herstellen möchten. Durch Camping 101: First Aid lernen Ausübende, die ihr grundlegendes Können bewiesen haben, eine zweckmäßige Verbandtasche zusammenzustellen, was ihnen die Mittel verleiht, fernab der Sicherheit einer Apotheke oder Krankenstation Wunden zu verbinden und Verletzungen zu versorgen."},{t="Die Kunst des Lagerfeuers",b="Das Errichten eines Lagers ist eine Kunst, die von praktischer Grenzer-Etikette und Notwendigkeit bestimmt wird. Rawrk warnt Abenteurer davor, dass das Aufschlagen von Zelten im Zentrum von Siedlungen wie Klingenhügel unerwünscht ist, was bedeutet, dass diese Wildnisstationen draußen in der offenen Wildnis erprobt werden müssen. Zudem ist kein Lagerplatz ohne ein loderndes Lagerfeuer funktionsfähig, um die Nacht abzuwehren, was grundlegende Vertrautheit mit der Kochkunst – bei der das Feuermachen zuerst gemeistert wird – zu einem unverzichtbaren Vorzug für jeden angehenden Camper macht."}},faq={{q="Wer ist Rawrk und wo ist er zu finden?",a="Rawrk befindet sich in Klingenhügel in Durotar. Er unterweist im Überlebens-Lagerbau und bringt bewährten Ausübenden bei, wie sie ihre eigenen Verbandtaschen für Reisen durch das Hinterland zusammenstellen.",al={"wer lehrt camping erste hilfe","wo ist rawrk","camping 101 lehrer"}},{q="Was ist erforderlich, bevor man ein Wildnislager aufschlägt?",a="Das Errichten eines Lagers erfordert sowohl eine offene Wildnisumgebung als auch ein ordentliches Lagerfeuer. Rawrk warnt davor, dass das Aufschlagen eines Lagers innerhalb von Stadtgrenzen ungern gesehen wird, und erinnert Reisende daran, vor dem Aufbruch die Grundlagen des Feuermachens bei einem Kochlehrer zu erlernen.",al={"was brauche ich zum campen","wie man ein lager aufschlägt","lagerfeuer anforderung camping"}},{q="Können Lager innerhalb von Städten oder Siedlungen aufgeschlagen werden?",a="Lager können nicht innerhalb von Siedlungen oder Stadtzentren errichtet werden. Einheimische Bewohner haben Einwände dagegen, dass Reisende mitten auf den Straßen Zelte aufschlagen, sodass Abenteurer in die offene Wildnis hinausziehen müssen, um ihren Lagerplatz zu errichten.",al={"kann ich in klingenhügel campen","campen in städten","wo kann ich mein lager aufschlagen"}},{q="Was lernen Abenteurer durch diese Ausbildung herzustellen?",a="Der Abschluss dieser Ausbildung weist Abenteurer darin ein, eine persönliche Verbandtasche herzustellen – ein unverzichtbares Feldzubehör, das genutzt wird, um die Gesundheit zu erhalten und längere Ausflüge in die Wildnis zu unterstützen.",al={"camping 101 first aid belohnung","welchen gegenstand lehrt dies","verbandtasche herstellung"}},{q="Warum empfiehlt Rawrk, Kochen zu lernen?",a="Ein ordentliches Lager erfordert ein wärmendes Lagerfeuer als Mittelpunkt. Da die Grundlagen des Entfachens und Hütens eines einfachen Feuers von Kochlehrern gelehrt werden, rät Rawrk Campern, sich vorher mit der Kochkunst zu befassen.",al={"warum brauche ich kochen zum campen","kochen lagerfeuer camping"}},{q="Welche Voraussetzungen sind erforderlich, bevor man dieses Handwerk erlernt?",a="Reisende müssen grundlegende Fertigkeiten in ihren medizinischen und Überlebensfähigkeiten vorweisen, bevor Rawrk ihnen beibringt, wie man eine spezialisierte Verbandtasche für das Feld fertigt.",al={"voraussetzungen für camping 101 first aid","benötigte fertigkeit für camping erste hilfe"}}},fp="22,349,24.489.0,23.482.0,35.190.0,53.243.0,49.218.0,51.189.0,42.205.0,57.163.0"}
P.entries["quest:97905"] = {n="Camping 101: Herbalism",s="Camping 101: Herbalism führt Sammler in das Handwerk ein, Räucherkerzen aus wilden Pflanzen herzustellen. Es betont die grundlegenden Regeln des Überlebens in der Wildnis, vom Entfachen eines ordentlichen Lagerfeuers bis hin zum Hinter-sich-Lassen zivilisierter Städte, bevor ein Lager aufgeschlagen wird.",h="Camping 101: Herbalism führt Sammler in das Handwerk ein, Räucherkerzen aus wilden Pflanzen herzustellen.",kw={"lager","lagerfeuer","camping","kochkunst","kräuterkunde","räucherkerze","wildnis"},ang={["profession:Cooking"]="Eine grundlegende Ausbildung in Kochkunst lehrt Reisende, wie man ein ordentliches Lagerfeuer entfacht, welches das unverzichtbare Zentrum jedes Lagers bildet.",["profession:Herbalism"]="Kräuterkundige lernen, Räucherkerzen aus gesammelten Pflanzen herzustellen, um Wärme, aromatischen Duft und Nutzen in Lager in der Wildnis zu bringen."},sec={{t="Aromatisches Handwerk der Wildnis",b="Das Überleben in der Wildnis von Azeroth erfordert mehr als nur eine Klinge; es verlangt das Wissen, gesammelte Flora in praktische Annehmlichkeiten zu verwandeln. Durch Kräuterkunde lernen Sammler, ihre eigenen Räucherkerzen herzustellen und so gesammelte Kräuter in beruhigende Aromastoffe für das Leben auf Reisen zu verwandeln. Da Stadtbewohner den Anblick von Zelten missbilligen, die die Straßen der Stadt verstopfen, sind diese Kerzen für die Verwendung weit jenseits der bewachten Mauern von Siedlungen gedacht."},{t="Das Herz des Lagers",b="Kein Lager in der Wildnis ist wirklich vollständig ohne den einladenden Schein eines offenen Feuers. Das Aufschlagen eines Lagers erfordert ein ordentliches Lagerfeuer in seiner Mitte, bevor eine Räucherkerze sinnvoll genutzt werden kann. Während Kräuterkundige für den aromatischen Abbrand sorgen, müssen Reisende sich an die Kochkunst wenden, um von Köchen im ganzen Land grundlegende Techniken zum Entfachen von Feuern zu erlernen."}},faq={{q="Was ist eine Räucherkerze?",a="Eine Räucherkerze ist ein von Kräuterkundigen hergestelltes, aromatisches Camping-Hilfsmittel. Sie besteht aus einer Mischung wilder Pflanzen und ist dafür gedacht, an einem Lagerplatz in der Wildnis neben einem lodernden Lagerfeuer abgebrannt zu werden.",al={"was ist eine räucherkerze","räucherkerze verwendung","camping kräuterkunde gegenstand"}},{q="Wo könnt Ihr ein Lager aufschlagen?",a="Lager können nicht in Stadtzentren aufgeschlagen werden, da Stadtbewohner Anstoß daran nehmen, wenn Reisende sich auf öffentlichen Durchgangswegen ausbreiten. Jeder, der eine Räucherkerze ausprobieren und ein Lager aufschlagen möchte, muss in die offene Wildnis hinausreisen.",al={"wo lager aufschlagen","kann man in der stadt lagern","campen in städten"}},{q="Warum benötigt Ihr ein Lagerfeuer, um ein Lager aufzuschlagen?",a="Jedes funktionale Lager benötigt ein loderndes Lagerfeuer in seinem Zentrum. Grundlegende Techniken zum Errichten eines Lagerfeuers werden von Kochkunstlehrern in ganz Azeroth gelehrt, daher sollten Reisende sich die Grundlagen der Kochkunst aneignen, bevor sie sich hinauswagen.",al={"wie man ein lagerfeuer macht","lagerfeuer für lager benötigt","koch lagerfeuer campen"}},{q="Wer lehrt, wie man ein Lagerfeuer macht?",a="Kochkunstlehrer bringen Reisenden bei, wie man ein einfaches Lagerfeuer entfacht. Das Erlernen der Grundlagen des Kochhandwerks liefert das nötige Fundament, um in der Wildnis ein Feuer zu entzünden.",al={"wer lehrt lagerfeuer","feuer machen lernen","kochkunstlehrer feuer"}},{q="Wie hängt Kräuterkunde mit dem Campen zusammen?",a="Kräuterkunde liefert die aromatischen Pflanzen und Harze, die zur Herstellung spezieller Räucherkerzen benötigt werden, und bereichert die Umgebung des Lagers mit beruhigenden natürlichen Pflanzenstoffen, die überall in der Wildnis geerntet wurden.",al={"verbindung von kräuterkunde und camping","warum kräuterkunde camping","was bringt kräuterkunde für lager"}},{q="Benötigt Ihr ein Lagerfeuer, um eine Räucherkerze zu verwenden?",a="Ein Lager gilt ohne ein ordentliches Lagerfeuer als unvollständig. Reisende werden angewiesen, zuerst ein Lagerfeuer zu errichten, bevor sie sich niederlassen und die Vorzüge einer Räucherkerze genießen können.",al={"kann man eine räucherkerze ohne feuer anzünden","räucherkerze lagerfeuer voraussetzung"}}},fp="22,255,26.413.0,25.346.0,26.180.0,28.226.0,44.218.0,35.171.0,36.190.0,48.186.0"}
P.entries["quest:97907"] = {n="Camping 101: Mining",s="Camping 101: Mining ist eine lehrreiche Handwerksquest, die angehende Bergbauarbeiter zu Krunn in Klingenhügel führt. Indem sie ihr Können in ihrem Beruf unter Beweis stellen, lernen Bergleute das Schmieden eines Lodestone, einer spezialisierten Lagereinrichtung, die das Kampfgeschick von Kriegern verbessert, die sich um ein Feuer in der Wildnis versammeln.",h="Camping 101: Mining ist eine lehrreiche Handwerksquest, die angehende Bergbauarbeiter zu Krunn in...",kw={"lager","lagerfeuer","camping 101: mining","kochkunst","durotar","krunn","magnetstein","bergbau","klingenhügel"},ang={["faction:Horde"]="Bergleute der Horde, die durch Durotar reisen, können sich bei Krunn in Klingenhügel melden, um die Kunst zu erlernen, Lodestones für ihre Expeditionen anzufertigen.",["profession:Cooking"]="Kochkunstlehrer vermitteln das grundlegende Wissen, das für das Entzünden eines einfachen Lagerfeuers erforderlich ist, dem Mittelpunkt jedes funktionstüchtigen Lagers in der Wildnis.",["profession:Mining"]="Der Bergbau erlaubt es Euch, rohe Mineralien abzubauen und spezialisierte Feldausrüstung wie einen Lodestone herzustellen, um Eure Verbündeten im Lager zu unterstützen."},sec={{t="Das Lager des Bergarbeiters",b="Der Bergbau bietet ein ehrliches Auskommen und liefert praktische Materialien für Erkundungen und das Überleben in der Wildnis. Wenn Bergleute ihr Handwerk weiterentwickeln und ihr Geschick mit Spitzhacke und Erz beweisen, können sie lernen, spezialisierte Ausrüstung für das Lager herzustellen. In Durotar werden erfahrene Bergleute an Krunn in der Siedlung Klingenhügel verwiesen, um zu erfahren, wie sie einen Lodestone für ihre Reisen schmieden."},{t="Kameradschaft am Lagerfeuer",b="Ein Lodestone dient Abenteurern, die in der Wildnis rasten, als ansprechender Mittelpunkt. Wenn er neben einem Lager aufgestellt wird, verleiht er Nah- und Fernkämpfern, die sich am Feuer versammeln, einen zusätzlichen Vorteil für ihr Kampfgeschick. Ein ordentlicher Lager-Knigge verlangt jedoch, zivilisierte Siedlungen hinter sich zu lassen: Die Stadtbewohner missbilligen es, wenn auf Marktplätzen Lager aufgeschlagen werden, sodass Reisende die freie Wildnis aufsuchen müssen, um ihre Handwerkskunst zu erproben."},{t="Feuer und Überlebenstechnik",b="Selbst der stabilste Lodestone nützt nichts ohne ein richtiges Feuer, das das Lager verankert. Ein einfaches Lagerfeuer ist unerlässlich, bevor überhaupt ein Rastplatz eingerichtet werden kann, und jene, die sich nicht mit dem Feuermachen auskennen, sollten einen Kochkunstlehrer aufsuchen. Die Unterweisung in den Kochkünsten stellt sicher, dass Expeditionen in die Wildnis über die Wärme und die grundlegende Nahrung verfügen, die zum Überleben außerhalb der Stadtmauern erforderlich sind."}},faq={{q="Was ist Camping 101: Mining?",a="Camping 101: Mining ist eine einführende Ausbildungsquest, die sich an Bergleute richtet. Sie leitet Bergleute an, die ihr Können unter Beweis gestellt haben, Krunn in Klingenhügel aufzusuchen, um zu lernen, wie man ein nützliches Lagerobjekt namens Lodestone herstellt.",al={"was ist camping 101: mining","camping bergbau quest","bergbau magnetstein quest"}},{q="Wer ist Krunn?",a="Krunn ist ein Ausbilder in Klingenhügel in Durotar. Er unterrichtet erfahrene Bergleute darin, wie man Gegenstände für das Lager wie den Lodestone herstellt, sobald sie ausreichendes berufliches Können vorweisen.",al={"wer ist krunn","wo ist krunn","klingenhügel lehrer"}},{q="Wozu dient ein Lodestone?",a="Ein Lodestone ist eine von Bergleuten herstellbare Lagereinrichtung. Wenn er an einem Lagerfeuer in der Wildnis aufgestellt wird, verleiht er physischen Kämpfern, die sich um das Feuer versammeln, zusätzliches Kampfgeschick, um ihre Kampfkraft zu stärken.",al={"was bewirkt ein magnetstein","magnetstein nutzen","warum magnetstein herstellen"}},{q="Kann man sein Lager in Klingenhügel aufschlagen?",a="Stadtbewohner und die Obrigkeit der Siedlung sehen es nicht gern, wenn mitten in belebten Straßen Lager aufgeschlagen werden. Ihr müsst Euch in die umliegende Wildnis wagen, um ein Lager aufzuschlagen und Euren Lodestone aufzustellen.",al={"kann ich in der stadt campen","warum kann ich nicht in klingenhügel campen","campen in städten"}},{q="Warum benötigt man ein Lagerfeuer, bevor man ein Lager aufschlägt?",a="Jeder funktionstüchtige Lagerplatz erfordert ein Lagerfeuer als Mittelpunkt. Der Bau eines einfachen Lagerfeuers wird von Kochkunstlehrern gelehrt, was das Kochen zu einer unverzichtbaren Ergänzung für Camper macht, die in die Wildnis aufbrechen.",al={"brauche ich ein lagerfeuer","wie man ein lager aufschlägt","feueranforderung campen"}},{q="Wer kann lernen, einen Lodestone herzustellen?",a="Die Herstellung eines Lodestone erfordert eine Ausbildung im Bergbauberuf. Bergleute, die ausreichendes Geschick in ihrem Handwerk beweisen, können die Technik direkt bei Krunn in Klingenhügel erlernen.",al={"wer kann magnetsteine herstellen","kann jeder einen magnetstein herstellen"}}},fp="19,287,16.379.0,20.419.0,19.382.0,28.220.0,13.183.0,29.211.0,38.209.0,50.208.0,35.178.0"}
P.entries["quest:97908"] = {n="Camping 101: Skinning",s="Camping 101: Skinning ist eine einführende Wildnisquest, die Kürschner in Orgrimmar zu Thuwd führt, um zu lernen, wie man einen Lagerstuhl herstellt. Indem sie erbeutete Häute für mehr Komfort im Feld nutzen, können Abenteurer richtige Lagerplätze in der Wildnis von Kalimdor errichten.",h="Camping 101: Skinning ist eine einführende Wildnisquest, die Kürschner in Orgrimmar zu Thuwd führt, um zu...",kw={"lagerstuhl","lagerfeuer","camping","camping 101: skinning","orgrimmar","kürschnerei","thuwd"},ang={["faction:Horde"]="Thuwd bildet Kürschner in Orgrimmar aus, was diese Einführung in das Wildnishandwerk exklusiv für Abenteurer der Horde zugänglich macht, die von Durotar aus operieren.",["profession:Cooking"]="Ein richtiger Lagerplatz erfordert sowohl Sitzgelegenheiten als auch Wärme; angehende Kürschner werden ermutigt, die Grundlagen der Kochkunst zu erlernen, um zu erfahren, wie man ein einfaches Lagerfeuer entzündet."},sec={{t="Komfort in der Wildnis",b="Das Sammeln von Fellen und Häuten erlegter Bestien ist eine der praktischsten Überlebensfertigkeiten, die ein Abenteurer in der Wildnis kultivieren kann. Während rohes Leder gewöhnlich der Rüstungsherstellung dient, können geschickte Kürschner ihre erbeuteten Pelze auch in Annehmlichkeiten für das Feld verwandeln. In Orgrimmar verweisen Ausbilder fähige Kürschner an Thuwd, um das Handwerk zu erlernen, aus gehärteten Häuten einen stabilen Lagerstuhl zu fertigen."},{t="Regeln des Pfades",b="Stadtbewohner und Wachen sehen es ungern, wenn Reisende provisorische Lager entlang belebter Straßen der Stadt aufschlagen. Wie Thuwd neue Handwerker erinnert, ist ein Lagerstuhl für offenes Gelände abseits von Siedlungsmauern gedacht. Zudem ist kein Wildnislager allein mit Sitzgelegenheiten komplett; ein richtiger Platz erfordert ein wärmendes Lagerfeuer – eine grundlegende Technik, die von Köchen in ganz Kalimdor gelehrt wird."}},faq={{q="Wer bringt Kürschnern bei, wie man Gegenstände für das Lager herstellt?",a="Die Quest weist angehende Kürschner an, mit Thuwd zu sprechen, einem Lehrer für Lederverarbeitung und Kürschnerei in der Hauptstadt der Horde, Orgrimmar, sobald sie grundlegende Fertigkeiten in ihrem Sammelberuf bewiesen haben.",al={"wer vergibt camping 101 skinning","mit wem in orgrimmar sprechen","wer ist thuwd"}},{q="Welchen Camping-Gegenstand können Kürschner herstellen?",a="Kürschner lernen, wie man unter Verwendung der von erlegten Bestien gesammelten Häute und Pelze einen Lagerstuhl fertigt. Er bietet eine bequeme Sitzgelegenheit zum Ausruhen und Erholen in der Wildnis.",al={"was kürschner fürs lager herstellen","kürschnerei camping handwerk","lagerstuhl kürschnerei"}},{q="Kann man einen Lagerstuhl innerhalb einer Stadt aufstellen?",a="Stadtbewohner und Wachen sehen es nicht gerne, wenn Lagerausrüstung mitten in der Stadt aufgestellt wird. Abenteurer müssen sich in die Wildnis jenseits der Tore von Siedlungen wagen, um ein Lager aufzuschlagen und ihren Stuhl aufzustellen.",al={"kann ich in orgrimmar campen","lager in der stadt","wo lager aufschlagen"}},{q="Was ist sonst noch nötig, um ein Lager zu vervollständigen?",a="Ein Lagerplatz ist ohne ein Feuer für Wärme, Sicht und zum Kochen unvollständig. Abenteurern wird geraten, einen Kochkunstlehrer aufzusuchen, um zu lernen, wie man ein einfaches Lagerfeuer entfacht, bevor sie ihr Lager aufschlagen.",al={"warum lagerfeuer nötig","camping voraussetzungen","wie man ein lager aufschlägt"}},{q="Warum sollte ein Abenteurer einen Lagerstuhl herstellen?",a="Sich zwischen den Jagden einen Moment Zeit zu nehmen, um sich in einem bequemen Stuhl auszuruhen, hilft Abenteurern, sich von den Strapazen der Reise zu erholen, und sorgt dafür, dass sie in Topform bleiben, bevor sie sich in ihr nächstes Gefecht stürzen.",al={"kürschnerei vorteil camping","warum im lagerstuhl ausruhen","lagerstuhl vorteile"}},{q="Wann lehrt Thuwd das Muster für den Lagerstuhl?",a="Kürschner müssen ihre grundlegende Fertigkeit im Sammeln von Fellen und Häuten erlegter Bestien unter Beweis stellen, bevor Thuwd die Geheimnisse zur Herstellung von Wildnis-Lagermöbeln preisgibt.",al={"wann kann ich lagerstuhl lernen","camping 101 voraussetzungen","benötigte kürschnereifertigkeit"}}},fp="21,260,19.381.0,18.353.0,44.209.0,37.172.0,42.203.0,41.191.0,44.181.0,45.167.0"}
P.entries["quest:97914"] = {n="Expanding Horizons",s="Expanding Horizons ist eine diplomatische Kurpermission mit Ursprung an der Dunkelküste, die die Nachtelfensiedlung Auberdine direkt mit dem Menschenkönigreich Sturmwind verbindet. Im Auftrag von Thundris Windweaver befördert ein Abenteurer offizielle Korrespondenz über das Meer zu Stadtarchitekt Baros Alexston, um engere Beziehungen und Handel zwischen den beiden fernen Reichen der Allianz zu fördern.",h="Expanding Horizons ist eine diplomatische Kurpermission mit Ursprung an der Dunkelküste, die die...",kw={"ameth'aran","auberdine","baros alexston","bashal'aran","dunkelküste","darnassus","expanding horizons","hafen","sturmwind","thundris windweaver"},ang={["faction:Alliance"]="Diese Mission verdeutlicht die praktische Arbeit an der Basis, die nötig ist, um ungleiche Völker über zwei Kontinente hinweg zu einer funktionierenden, geeinten Fraktion zusammenzuschweißen.",["race:Human"]="Die Rückkehr nach Sturmwind mit dem Siegel einer Zuflucht der Kaldorei unterstreicht die wachsende Reichweite und den weltweiten Einfluss des wiederaufgebauten Königreichs.",["race:NightElf"]="Für die Kaldorei stellt die Eröffnung von Seewegen zu den Östlichen Königreichen einen grundlegenden Bruch mit zehntausend Jahren der Abgeschiedenheit dar und bindet Euer Volk untrennbar an die menschliche Zivilisation."},sec={{t="Zwei Hemisphären überbrücken",b="Jahrtausertelang blieben die Nachtelfen in den Wäldern von Kalimdor, isoliert von den Östlichen Königreichen. Nach dem Dritten Krieg erforderte ihr Beitritt zur Großen Allianz echte logistische Verbindungen und nicht bloß ideologische. Auberdine dient als primärer nördlicher Hafen für das Festland der Kaldorei, doch stand es lange im Schatten uralter, zerstörter Städte wie Ameth'Aran und Bashal'Aran. Mit der Errichtung einer direkten Seeverbindung zwischen Auberdine und Sturmwind versuchen die örtlichen Anführer, diese neu gewonnenen Schifffahrtsrouten zu festigen und ihre Küstengemeinschaft in das weitere Netzwerk der Allianz einzugliedern."},{t="Ein Schreiben an den Stadtarchitekten",b="Die über das Große Meer beförderte Korrespondenz ist ausdrücklich an Baros Alexston adressiert, den Stadtarchitekten von Sturmwind. Als leitender Baumeister, der für den Wiederaufbau und die Infrastruktur der menschlichen Hauptstadt zuständig ist, kümmert sich Alexston um große öffentliche Bauwerke und Logistik. Thundris' eigenes Ziel ist einfacher: Er möchte erleben, dass Auberdines Schaffen gewürdigt und seine Heimat bekannt gemacht wird."}},faq={{q="Wer schickt Euch auf diese Quest?",a="Thundris Windweaver, ein einflussreicher Nachtelf in Auberdine, überträgt Reisenden diese Aufgabe. Da er das Gefühl hat, Auberdine werde sowohl von den hohen Ästen von Darnassus als auch von fernen Verbündeten jenseits des Ozeans übersehen, versucht er, eine formelle Verbindung mit dem Menschenkönigreich aufzubauen.",al={"questgeber expanding horizons","wer vergibt expanding horizons","thundris quest"}},{q="Wer ist Baros Alexston?",a="Baros Alexston ist der Stadtarchitekt von Sturmwind. Als angesehener Stadtplaner, der Edwin van Cleef in jüngeren Jahren kannte, überwacht er Bauvorhaben und bauliche Verwaltung in der gesamten Hauptstadt.",al={"baros alexston lore","wer ist baros","stadtarchitekt sturmwind"}},{q="Warum wendet sich Auberdine an Sturmwind?",a="Auberdine möchte, dass sein Hafen als wichtiger Umschlagplatz für Nachschub, Handel und Reisen der Allianz anerkannt wird. Mit neu eingerichteten Seewegen zwischen der Dunkelküste und den Östlichen Königreichen hoffen die örtlichen Anführer, die wirtschaftlichen und logistischen Bande mit dem Menschenkönigreich zu festigen.",al={"warum brief nach sturmwind senden","verbindung auberdine sturmwind","warum menschen kontaktieren"}},{q="Wie funktioniert das Reisen zwischen Auberdine und Sturmwind?",a="Ein neues Schiff verbindet nun Auberdine mit dem Königreich Sturmwind, segelt über das Große Meer direkt in den Hafen von Sturmwind und bringt Leben und Vorräte an die Gestade von Auberdine.",al={"schiff nach sturmwind","wie man von auberdine nach sturmwind gelangt"}},{q="Was sind Ameth'Aran und Bashal'Aran?",a="Sie waren wohlhabende Hochgeborenen-Städte an der antiken Dunkelküste, bevor die Große Zerschlagung den Kontinent vor zehntausend Jahren entzweiriss. Heute liegen sie in heimgesuchten Ruinen da und sind in der Geschichte der Kaldorei oft weitaus präsenter als lebendige Dörfer wie Auberdine.",al={"ameth'aran lore","bashal'aran","antike städte der dunkelküste"}},{q="Warum wird dies einem Architekten überbracht statt König Anduin oder Bolvar?",a="Die Quest verrät nicht, warum Thundris ihn ausgewählt hat. Thundris bittet lediglich darum, dass der Brief an einen Menschen namens Baros Alexston, Sturmwinds Stadtarchitekt, überbracht wird, damit das Schaffen Auberdines Anerkennung findet.",al={"warum baros alexston","warum nicht bolvar","warum nicht hochlord bolvar"}}},fp="18,372,24.620.0,31.370.0,28.266.0,22.201.0,43.263.0,53.180.0,36.261.0,66.187.0"}
P.entries["quest:97916"] = {n="Camping 101: Blacksmithing",s="Camping 101: Blacksmithing ist eine Einführungsaufgabe in Goldhain, die Schmiede in der Herstellung von Feldausrüstung unterweist. Durch Rücksprache mit Schmied Argus lernen erfahrene Metallarbeiter, einen tragbaren Schleifstein für Reisen in die Wildnis zu schmieden. Sie betont die Einsatzbereitschaft im Feld und hebt die Notwendigkeit des offenen Geländes sowie eines ordentlichen Lagerfeuers hervor, um ein funktionierendes Lager aufzuschlagen.",h="Camping 101: Blacksmithing ist eine Einführungsaufgabe in Goldhain, die Schmiede in der Herstellung von...",kw={"schmiedekunst","lagerfeuer","camping","camping 101","wald von elwynn","goldhain","schleifstein","schmied argus"},ang={["faction:Alliance"]="Handwerker der Allianz, die ihre Reise in Goldhain beginnen, können Schmied Argus aufsuchen, um sich auf längere Expeditionen jenseits der Stadtmauern vorzubereiten.",["profession:Blacksmithing"]="Schmiede, die ihr Handwerk im Wald von Elwynn erlernen, können einen Schleifstein herstellen, um Ausrüstung zu warten und Klingen im Feld zu schärfen.",["profession:Cooking"]="Ein ordentlicher Lagerplatz erfordert ein zuverlässiges Feuer, was eine grundlegende Kochausbildung zu einer natürlichen Ergänzung für die Metallbearbeitung in der Wildnis macht."},sec={{t="Schmieden für die Reise",b="Schmied Argus aus Goldhain bietet aufstrebenden Metallarbeitern Anleitung dazu, wie sie ihr Handwerk unterwegs ausüben können. Anstatt strikt an die Ambosse der Stadt gebunden zu bleiben, können Schmiede, die ausreichendes Können an den Tag legen, lernen, praktische Ausrüstung herzustellen, die für das raue Leben in der Wildnis geeignet ist. Diese Unterweisung konzentriert sich auf das Schmieden eines persönlichen Schleifsteins, ein unverzichtbares Werkzeug, um Klingen auf langen Reisen scharf zu halten."},{t="Das Leben im Feld",b="Das Errichten eines Lagers erfordert mehr als nur Feldausrüstung; die richtige Etikette in der Wildnis und Vorbereitung sind gleichermaßen entscheidend. Stadtbewohner sehen es nicht gern, wenn man mitten in Siedlungen wie Goldhain ein Lager aufschlägt, sodass Handwerker das offene Grenzland aufsuchen müssen, um ihre Ausrüstung aufzubauen. Darüber hinaus ist kein Lagerplatz in der Wildnis ohne ein wärmendes Lagerfeuer vollständig, was den Besuch bei einem örtlichen Koch zum Erlernen grundlegender Feuerherstellung zu einem unverzichtbaren ersten Schritt macht."}},faq={{q="Was ist Camping 101: Blacksmithing?",a="Diese Quest führt angehende Schmiede in das Überlebenshandwerk ein und lehrt sie, wie man einen tragbaren Schleifstein für Expeditionen in die Wildnis schmiedet.",al={"was macht diese quest","zweck von camping 101 blacksmithing","was lerne ich"}},{q="Wer ist Schmied Argus?",a="Schmied Argus ist der ansässige Schmied und Lehrer in Goldhain im Wald von Elwynn. Er unterweist vielversprechende Schmiede in grundlegender Metallbearbeitung und Campinghandwerk.",al={"wer ist schmied argus","schmiedelehrer in goldhain","argus goldhain"}},{q="Was ist ein Schleifstein?",a="Der Schleifstein ist ein berufsspezifischer Campinggegenstand, den Schmiede für ihre Expeditionen herzustellen lernen, wodurch sie Werkzeuge und Waffen abseits traditioneller Stadtschmieden schärfen können.",al={"was ist ein schleifstein","camping-schleifstein","schmiede-campinggegenstand"}},{q="Kann man innerhalb der Stadt ein Lager aufschlagen?",a="Die Stadtbewohner sehen es nicht gern, wenn in besiedelten Gebieten wie Goldhain Lager errichtet werden. Schmiede müssen sich in die Wildnis hinauswagen, um ihre Ausrüstung aufzubauen.",al={"kann ich in goldhain zelten","zelt in der stadt aufschlagen","wo kann ich zelten"}},{q="Warum benötigt man ein Lagerfeuer, um ein Lager aufzuschlagen?",a="Jedes Lager benötigt ein loderndes Lagerfeuer, um vollständig zu sein. Schmieden wird geraten, einen Kochkunstlehrer aufzusuchen, um grundlegende Techniken zum Entfachen von Feuern zu erlernen, bevor sie aufbrechen.",al={"brauche ich kochen zum zelten","lagerfeuer fuer lager","wie man ein lager aufschlaegt"}},{q="Wann kann man dieses Campinghandwerk erlernen?",a="Ihr müsst eine ausreichende Fertigkeit in der Schmiedekunst vorweisen, bevor Schmied Argus Euch beibringt, wie man spezialisierte Campingausrüstung schmiedet.",al={"voraussetzungen fuer camping 101","schmiedevoraussetzung"}}},fp="26,355,21.401.0,17.424.0,35.150.0,19.170.0,27.188.0,32.150.0,40.167.0,38.141.0"}
P.entries["quest:97917"] = {n="Camping 101: Enchanting",s="Camping 101: Enchanting weist Verzauberer an, Betty Quin in der Stadt Sturmwind aufzusuchen, um spezialisiertes Lagerhandwerk zu erlernen. Indem sie Freizeitgegenstände wie eine Verzauberte Laute mit Magie erfüllen, tragen Verzauberer dazu bei, die Moral hoch und die Körper entlang des Weges ausgeruht zu halten.",h="Camping 101: Enchanting weist Verzauberer an, Betty Quin in der Stadt Sturmwind aufzusuchen, um...",kw={"betty quin","lager","camping 101","camping 101: enchanting","verzauberte laute","verzauberkunst","sturmwind"},ang={["faction:Alliance"]="Verzauberer, die durch das Territorium der Allianz reisen, werden in das Herz von Sturmwind geschickt, um Betty Quin für eine Einweisung ins Camping aufzusuchen."},sec={{t="Magie auf dem Weg",b="Das Leben unterwegs in ganz Azeroth erfordert mehr als Stahl und Rationen; Moral und Komfort in der Wildnis sind für das Überleben langer Reisen ebenso unerlässlich. Verzauberer verleihen jedem Lagerfeuer ein magisches Flair, indem sie ihr esoterisches Handwerk nutzen, um ruhige Ruhezeiten in erholsame Unterhaltung zu verwandeln, die Reisende auf die Prüfungen des Weges vorbereitet."},{t="Auf der Suche nach Betty Quin",b="Verzauberer, die besondere Lagerplatzgegenstände herstellen möchten, werden zu Betty Quin in Sturmwind geschickt. Sobald ein Ausübender ausreichendes Können in der Verzauberkunst nachweist, kann sie das Wissen vermitteln, das für den Bau einer Verzauberten Laute erforderlich ist – eines Instruments, das mit Zaubern gewoben ist, um die Stimmung rund um das Lagerfeuer zu heben."}},faq={{q="Was ist Camping 101: Enchanting?",a="Camping 101: Enchanting leitet Ausübende der Verzauberkünste dazu an zu lernen, wie man magischen Lagerbedarf herstellt. Es schickt angehende Verzauberer zu Betty Quin in Sturmwind, sobald sie ihr Handwerk verfeinert haben.",al={"was ist camping 101 enchanting","camping 101 verzauberer","verzauberkunst lagerquest"}},{q="Wer ist Betty Quin?",a="Betty Quin ist eine in Sturmwind ansässige Ausbilderin, die sachkundigen Verzauberern beibringt, wie man nützliche magische Ausrüstung für das Überleben und die Freizeit auf Reisen herstellt.",al={"wer ist betty quin","sturmwind verzauberkunstlehrerin betty","wo ist betty quin"}},{q="Was ist eine Verzauberte Laute?",a="Die Verzauberte Laute ist ein mit Magie erfülltes Musikinstrument, das während der Ruhezeiten im Lager für Unterhaltung und Moral sorgen soll und Abenteurern hilft, Widrigkeiten zu trotzen, wenn sie sich auf den Weg machen.",al={"was macht die verzauberte laute","warum verzauberte laute herstellen","zweck der verzauberten laute"}},{q="Warum werden Verzauberer an einem Lagerplatz geschätzt?",a="Verzauberer bringen wohltuende Magie an einen Lagerplatz und verwandeln alltägliche Ruhezeiten in Momente der Erholung, Vorbereitung und Entspannung, die Reisenden dabei helfen, raue Reisen durch die Wildnis zu überstehen.",al={"warum verzauberer im lager","nutzen von verzauberern im lager"}},{q="Wohin muss ich gehen, um diese Aufgabe abzuschließen?",a="Die Quest weist Euch an, Betty Quin in der Hauptstadt Sturmwind zu finden, die im gleichnamigen Königreich liegt.",al={"wo gibt man camping 101 enchanting ab","aufenthaltsort von betty quin"}},{q="Welche Fertigkeit ist erforderlich, um Camping-Verzauberungsrezepte zu lernen?",a="Ihr müsst ein solides Können in der Verzauberkunst vorweisen, bevor Betty Quin Euch in der Herstellung von Lagergegenständen wie der Verzauberten Laute unterweist.",al={"voraussetzungen für camping 101 enchanting","wann kann man die verzauberte laute lernen"}}},fp="23,252,18.332.0,18.297.0,32.216.0,18.157.0,26.193.0,40.185.0,36.119.0,57.139.0"}
P.entries["quest:97919"] = {n="Grundlagen des Zeltens: Erste Hilfe",s="Grundlagen des Zeltens: Erste Hilfe führt angehende Abenteurer im Wald von Elwynn in die praktische Überlebenskunst der Feldmedizin ein. Sie schickt Reisende zu Michelle Belle in Goldhain, um zu lernen, wie man eine Verbandtasche für Wildnislager vorbereitet.",h="Grundlagen des Zeltens: Erste Hilfe führt angehende Abenteurer im Wald von Elwynn in die praktische...",kw={"verbände","lagerausrüstung","grundlagen des zeltens","wald von elwynn","erste hilfe","goldhain","michelle belle","überleben"},ang={["class:Rogue"]="Schurken, die in den Schatten fernab jeglicher Unterstützung operieren, sind auf Feldmedizin angewiesen, um blutende Wunden zu verbinden, bevor sie zu ihrem nächsten Ziel weiterziehen.",["class:Warrior"]="Ohne angeborene Heilzauber verlassen sich Frontkämpfer stark auf Verbände und Feldapotheken, um langwierige Feldzüge in der Wildnis zu überstehen.",["faction:Alliance"]="Goldhain bleibt die entscheidende Kreuzung für Reisende der Allianz, die ihre Wege vom Nordhaintal in das weitere Reich von Elwynn beginnen."},sec={{t="Feldmedizin unterwegs",b="Abenteurer, die den Wald von Elwynn durchqueren, stellen schnell fest, dass Kämpfe und das raue Überleben in der Wildnis ihren Tribut fordern. Zwar bieten Heiler in den Städten und Gasthäuser Erholung, doch Reisen durch gefährliches Gebiet erfordern oft unmittelbare, eigenständige Versorgung. Das Erlernen von Erste Hilfe bietet ein praktisches Mittel gegen Blutungen und Verletzungen, sodass Reisende ihre Wunden versorgen können, ohne auf arkane Rituale oder heilige Gebete angewiesen zu sein."},{t="Vorräte für das Lager",b="Ein widerstandsfähiges Lager ist mehr als nur ein Feuer und eine Schlafrolle; es ist eine vorübergehende Zuflucht vor den Gefahren der Wildnis. Durch die Unterweisung von Michelle Belle im Gasthaus \"Zur Höhle des Löwen\" von Goldhain lernen geübte Anwender, spezielle Erste-Hilfe-Ausrüstung zusammenzustellen. Medizinische Vorräte im Lager griffbereit zu haben stellt sicher, dass eine erschöpfte Gruppe Verletzungen behandeln und neue Kräfte sammeln kann, bevor sie sich den nächsten Gefahren stellt."}},faq={{q="Was ist der Zweck dieser Quest?",a="Diese Quest leitet Abenteurer, die die Grundlagen von Erste Hilfe erlernt haben, dazu an, Michelle Belle in Goldhain aufzusuchen. Sie bringt Anwendern bei, wie man eine Verbandtasche herstellt, um ihre Wildnislager mit lebenswichtigen medizinischen Vorräten auszustatten.",al={"zelten erste hilfe zweck","was bringt diese quest","warum grundlagen des zeltens erste hilfe"}},{q="Mit wem muss ich in Goldhain sprechen?",a="Ihr müsst mit Michelle Belle sprechen, einer Ausbilderin in Goldhain. Sobald Ihr ausreichendes Können in Erste Hilfe bewiesen habt, teilt sie die Techniken zur Herstellung von Lagervorräten, die für die Feldmedizin geeignet sind, mit Euch.",al={"wer ist michelle belle","zelten ausbilder goldhain","erste hilfe lager ausbilder"}},{q="Warum ist Erste Hilfe wichtig für Reisende?",a="Das Abenteuerleben birgt ständige Risiken körperlicher Verletzungen durch Bestien, Banditen und die rauen Elemente. Erste Hilfe erlaubt es jedem, unabhängig davon, ob man göttliche oder arkane Magie wirkt, Wunden zu verbinden und sich zwischen Scharmützeln zu erholen.",al={"warum erste hilfe lernen","ist erste hilfe nützlich","erste hilfe hintergrund"}},{q="Wo befindet sich Goldhain?",a="Goldhain ist das Hauptdorf im Wald von Elwynn, gelegen südlich von Sturmwind an der Haupthandelsstraße. Es dient als zentraler Knotenpunkt für Vorräte, örtliche Ausbilder und Rast im Gasthaus \"Zur Höhle des Löwen\".",al={"wo ist goldhain","goldhain standort","michelle belle finden"}},{q="Benötige ich eine vorherige Ausbildung, um diese Aufgabe abzuschließen?",a="Ja. Michelle Belle verlangt von Euch, dass Ihr Euer Können in Erste Hilfe unter Beweis stellt, bevor sie Euch in der Herstellung berufsspezifischer Lagerausrüstung unterweist.",al={"voraussetzungen grundlagen des zeltens","benötigte fertigkeit erste hilfe","voraussetzungen"}},{q="Welche Rolle spielt eine Verbandtasche beim Zelten?",a="Ein Lagerplatz in der Wildnis bietet einen sicheren Schutzbereich zum Erholen, und die Ausstattung mit einer Verbandtasche stellt sicher, dass verletzte Wanderer sofortigen Zugang zu Verbänden und Heilmitteln haben, die fernab von städtischen Heilern Leben retten können.",al={"lager verbandtasche nutzen","campinggegenstand erste hilfe","warum verbandtasche herstellen"}}},fp="22,239,26.409.0,25.391.0,34.232.0,41.207.0,41.226.0,27.208.0,47.151.0,42.221.0"}
P.entries["quest:97920"] = {n="Grundlagen des Zeltens: Angeln",s="Grundlagen des Zeltens: Angeln führt angehende Angler im Wald von Elwynn an das praktische Handwerk des Überlebens in der Wildnis und an nützliche Lagerannehmlichkeiten heran. Wenn Reisende den einheimischen Angelexperten Lee Brown in der Nähe von Goldhain aufsuchen, können sie lernen, ihr Anglerwissen für das Herstellen gemütlicher Zusätze für ein Lagerfeuer einzusetzen, wie etwa ein dekoratives Fischglas, das die Gemüter der Abenteurer erheitert.",h="Grundlagen des Zeltens: Angeln führt angehende Angler im Wald von Elwynn an das praktische Handwerk des...",kw={"lagerhandwerk","grundlagen des zeltens: angeln","kristallsee","wald von elwynn","fischglas","goldhain","lee brown"},ang={["faction:Alliance"]="Menschliche Reisende, die ihre Abenteuer im Wald von Elwynn beginnen, können sich auf die vertrauten Gewässer von Goldhain verlassen, um wichtige Selbstversorgung in der Wildnis zu erlernen."},sec={{t="Lagerhandwerk für Angler",b="Während das Angeln oft als einsamer Zeitvertreib an ruhigen Seeufern und Flussläufen gilt, wissen erfahrene Überlebenskünstler, dass das Lagerleben mehr erfordert als nur Nahrung und Schutz. Die Anfertigung behaglicher Einrichtungsgegenstände wie eines Fischglases bringt Heiterkeit und Moral für erschöpfte Reisende, die sich zwischen Ausflügen ausruhen, und bestärkt den Glauben, dass ein klarer Verstand und ein aufgeschlossenes Gemüt formidable Kämpfer hervorbringen."},{t="Lee Browns Fachwissen",b="Am Gewässer vor Goldhain stationiert, steht der erfahrene Angler Lee Brown Neulingen zur Seite, die ihr Handwerk erweitern möchten. Jene, die ausreichendes Können mit Rute und Schnur beweisen, werden zu ihm geschickt, um zu lernen, wie einfache Fänge und Grundmaterialien in funktionale Lageraufwertungen verwandelt werden können."}},faq={{q="Was ist der Zweck dieser Quest?",a="Die Quest schickt angehende Fischer zu Lee Brown in die Nähe von Goldhain. Sobald Ihr grundlegendes Anglerkönnen vorweist, bringt er Euch bei, wie Ihr spezialisierte Lagergegenstände wie ein Fischglas herstellt, um Rastplätze am Wegesrand aufzuwerten.",al={"warum zeltangeln","was bewirkt grundlagen des zeltens","zweck der quest"}},{q="Wer ist Lee Brown?",a="Lee Brown ist ein sachkundiger Angellehrer, der am Kristallsee direkt vor Goldhain im Wald von Elwynn stationiert ist. Er unterweist im Fischen und lehrt, wie man auf Angler zugeschnittene Gegenstände für das Lagerhandwerk herstellt.",al={"wo ist lee brown","wer lehrt angelzelten","lee brown"}},{q="Was bewirkt ein Fischglas für einen Rastplatz?",a="Ein Fischglas dient als Lagergegenstand, der rastenden Abenteurern Behaglichkeit und Freude bringen soll. Eine angenehme Lagerumgebung hebt die Moral und trägt dazu bei, dass sich Abenteurer bereit und gewappnet fühlen, wenn sie sich den Gefahren der Wildnis stellen.",al={"fischglas effekt","was bringt fischglas","warum fischglas herstellen"}},{q="Wo findet diese Ausbildung statt?",a="Die Quest findet im Wald von Elwynn statt und führt Spieler zu den Gewässern rund um Goldhain, wo sich die einheimischen Angler versammeln.",al={"questort","wohin gehen","elwynn lagerlehrer"}},{q="Benötige ich anglerische Vorkenntnisse, um dies abzuschließen?",a="Ja. Lee Brown unterrichtet nur Reisende, die ihren Auswurf geübt und ein grundlegendes Geschick im Angelhandwerk unter Beweis gestellt haben.",al={"angeln fähigkeitsanforderung","brauche ich angeln","fertigkeitsanforderung"}},{q="Ist Lagern nützlich für den Kampf?",a="Ja. Ein gut gepflegtes Lager bietet Annehmlichkeiten, die die körperliche und geistige Einsatzbereitschaft eines Abenteurers verbessern, was sich direkt in seiner Widerstandskraft und Kampfkraft im Feld widerspiegelt.",al={"hilft lagern im kampf","zelten stärkungszauber","warum rasten"}}},fp="20,358,21.392.0,21.312.0,34.220.0,17.215.0,40.218.0,36.123.0,50.138.0,29.187.0"}
P.entries["quest:97921"] = {n="Camping 101: Herbalism",s="Camping 101: Herbalism ist eine Ausbildungsquest, die geschickte Sammler anweist, im Wald von Elwynn spezialisierten Unterricht für die Wildnis aufzusuchen. Nachdem sie ihre Fertigkeit beim Ernten von Pflanzen unter Beweis gestellt haben, werden Kräuterkundige an Kräuterkundige Pomeroy verwiesen, um die Kunst der Herstellung von Lagerplatz-Nützlichkeiten zu erlernen. Der Abschluss dieser Ausbildung schaltet die Fähigkeit frei, Räucherkerzen herzustellen – botanische Hilfsmittel, die darauf ausgelegt sind, den Fokus und den Geist von Zauberwirkern zu stärken, die im Feld rasten.",h="Camping 101: Herbalism ist eine Ausbildungsquest, die geschickte Sammler anweist, im Wald von Elwynn...",kw={"lager","camping 101","lagerplatz","wald von elwynn","heiler","kräuterkunde","kräuterkundige pomeroy","räucherkerze","zauberwirker"},ang={["class:Mage"]="Magier im Feld schätzen die beruhigenden botanischen Eigenschaften von Räucherkerzen, was einen kräuterkundigen Gefährten für lange Reisen durch die Wildnis besonders begehrt macht.",["class:Priest"]="Priester und andere hingebungsvolle Heiler profitieren enorm vom Rasten in der Nähe von Räucherkerzen, die den Geist heben und helfen, lebenswichtige Energie während Expeditionen in der Wildnis wiederherzustellen.",["faction:Alliance"]="Da Kräuterkundige Pomeroy im Wald von Elwynn ansässig ist, genießen Abenteurer der Allianz die bequeme Nähe zu dieser spezialisierten Lagerplatz-Unterweisung.",["profession:Herbalism"]="Diese Quest hebt die Kräuterkunde von einem einfachen Sammelberuf zu einer aktiven Rolle zur Lagerunterstützung empor und ermöglicht es Botanikern, Räucherkerzen herzustellen, die reisenden Gefährten helfen."},sec={{t="Botanische Nützlichkeiten für unterwegs",b="Für wandernde Kräuterkundige dient das Ernten von Kräutern in der Wildnis von Azeroth Zwecken, die weit über das Brauen einfacher stärkender Tränke oder den Verkauf von Blumenbündeln an städtische Händler hinausgehen. Während Ausübende ihr Sammelhandwerk verfeinern, ergeben sich Gelegenheiten, ihr Wissen über die Pflanzenwelt für das Überleben in der Wildnis einzusetzen. Feldlager erfordern mehr als nur ein prasselndes Feuer und eine trockene Schlafrolle; die Ausdauer und geistige Schärfe einer reisenden Gruppe aufrechtzuerhalten, verlangt nach besonderen Annehmlichkeiten. Erfahrene Sammler erkennen, dass bestimmte Pflanzen aromatische Eigenschaften besitzen, die in der Lage sind, erschöpfte Geister zu beleben. Indem sie vielversprechende Kräuterkundige an etablierte Mentoren verweist, schlägt diese Aufgabe eine Brücke zwischen einfachem Sammeln und praktischem Überlebenstraining und beweist, dass ein scharfer Blick für die Gaben der Natur eine ganze Expedition fernab der Zivilisation ernähren und erhalten kann."},{t="Die Führung von Kräuterkundiger Pomeroy",b="Angehende Kräuterkundige, die ihr Handwerk für das Lagerleben erweitern möchten, werden in das Herz des Walds von Elwynn geschickt, um sich mit Kräuterkundiger Pomeroy zu beraten. Pomeroy, die sich bestens mit den botanischen Varietäten der umliegenden Wälder auskennt, versteht, wie getrocknete Blütenblätter, aromatische Stängel und natürliche Harze zu funktioneller Lagerausrüstung verarbeitet werden können. Anstatt Kräuter ausschließlich für Alchemiefläschchen zu verwenden, unterweist sie Sammler im Bau einer Räucherkerze. Wenn sie an einem Lagerplatz verbrannt wird, beruhigt diese duftende Schöpfung erschöpfte Reisende und hebt die Stimmung manaanhängiger Gefährten. Pomeroy zu finden und das eigene Geschick mit der Sichel zu beweisen, stellt sicher, dass ein Kräuterkundiger zu einer unverzichtbaren Bereicherung für jede Abenteurergruppe wird, die sich in die ungezähmte Wildnis wagt."}},faq={{q="Was ist Camping 101: Herbalism?",a="Camping 101: Herbalism ist eine Einführungsquest, die erfahrenen Kräuterkundigen beibringt, wie sie ihr Sammelhandwerk um Nützlichkeiten für das Campen erweitern können. Sie weist Spieler an, in den Wald von Elwynn zu reisen, um Kräuterkundige Pomeroy zu treffen, die lehrt, wie man spezialisierte Räucherkerzen für Feldlager herstellt.",al={"camping 101 herbalism quest","kräuterkunde camping quest","was ist camping 101 herbalism"}},{q="Wer lehrt das Campingrezept für Kräuterkundige?",a="Kräuterkundige Pomeroy lehrt das Campingrezept der Kräuterkunde. Sie ist im Wald von Elwynn zu finden, wo sie ihr Wissen über einheimische Pflanzen teilt und geschickte Sammler darin anleitet, aromatische Räucherkerzen herzustellen, um ihre Rast am Lagerplatz zu verbessern.",al={"wer lehrt kräuterkunde camping","camping 101 lehrer","wo ist kräuterkundige pomeroy","kräuterkundige pomeroy aufenthaltsort"}},{q="Welchen Gegenstand lernen Kräuterkundige durch diese Quest herzustellen?",a="Der Abschluss dieser Ausbildung ermöglicht es Kräuterkundigen, eine Räucherkerze für ihren Lagerplatz herzustellen. Aus gesammelten Kräutern und botanischen Materialien gefertigt, verströmt die Kerze beruhigende Aromen, die den Geist beleben und Zauberwirkern sowie Heilern, die in der Wildnis rasten, einen willkommenen Vorteil bieten.",al={"was stellen kräuterkundige fürs camping her","kräuterkunde lagergegenstand","räucherkerze kräuterkunde","was lehrt camping 101"}},{q="Was sind die Voraussetzungen, um Camping 101: Herbalism zu beginnen?",a="Ihr müsst den Beruf Kräuterkunde ausüben und ausreichendes Geschick beim Sammeln vorweisen, bevor Ihr diese Aufgabe erhaltet. Sobald Eure Kräuterkundefertigkeit über das Niveau eines Neulings hinaus fortgeschritten ist, halten Ausbilder Euch für erfahren genug, um von Kräuterkundiger Pomeroy zu lernen, wie man botanische Lagernützlichkeiten zubereitet.",al={"camping 101 herbalism voraussetzungen","wann kann man camping 101 herbalism annehmen","benötigte kräuterkundefertigkeit für camping 101"}},{q="Warum sind Räucherkerzen für Abenteurergruppen nützlich?",a="Räucherkerzen verströmen beruhigende Kräuterdüfte, die die Moral heben und den geistigen Fokus wiederherstellen. Im Feld verbrauchen Zauberwirker und Heiler gewaltige Energien beim Kanalisieren magischer Mächte, was den spirituellen und magischen Schub durch diese Duftkerzen bei Erholungsphasen in der Wildnis besonders wertvoll macht.",al={"was bewirkt die räucherkerze","warum eine räucherkerze herstellen","vorteile der räucherkerze","kräuterkunde räucherkerze nutzung"}},{q="Wo findet diese Quest statt?",a="Das Ziel führt Abenteurer in den Wald von Elwynn, das üppige Waldgebiet, das die Stadt Sturmwind umgibt. Spieler reisen in die ländlichen Gegenden von Elwynn, um Kräuterkundige Pomeroy aufzusuchen, schließen den Auftrag ab und schalten ihre Fähigkeit frei, botanische Campingvorräte herzustellen.",al={"camping 101 herbalism zone","wo gibt man camping 101 herbalism ab","wald von elwynn kräuterkunde quest"}},{q="Können Nicht-Kräuterkundige die Räucherkerze herstellen?",a="Nein, das Herstellen der Räucherkerze ist direkt an den Beruf Kräuterkunde gebunden. Das Rezept beruht auf einem speziellen Verständnis von Wildpflanzen, der Konservierung von Blüten und aromatischen Essenzen, das von Kräuterkundiger Pomeroy eigens Abenteurern beigebracht wird, die pflanzliche Materialien sammeln.",al={"kann jeder eine räucherkerze herstellen","ist die räucherkerze nur für kräuterkundige","braucht man kräuterkunde für die räucherkerze"}}},fp="22,450,32.806.0,33.739.0,31.293.0,46.240.0,55.276.0,58.300.0,55.310.0,33.278.0,44.262.0"}
P.entries["quest:97922"] = {n="Camping 101: Leatherworking",s="Camping 101: Leatherworking weist Lederverarbeitungslehrlinge an Adele Fielder in Goldhain, um das Handwerk zur Herstellung eines Reisezeltes zu erlernen. Das Aufschlagen eines Zeltes in der Wildnis bietet Schutz und Ruhe vor rauem Wetter und verschafft Abenteurern außerhalb besiedelter Städte ein wichtiges Überlebenswerkzeug.",h="Camping 101: Leatherworking weist Lederverarbeitungslehrlinge an Adele Fielder in Goldhain, um das Handwerk...",kw={"adele fielder","lagerfeuer","camping","wald von elwynn","goldhain","lederverarbeitung","zelt","ueberleben in der wildnis"},ang={["faction:Alliance"]="Diese Ausbildung mit Sitz in Goldhain im Wald von Elwynn leitet Lederverarbeiter der Allianz zu praktischem Überlebenshandwerk für ihre Reisen quer durch Azeroth an.",["profession:Cooking"]="Adele Fielder merkt an, dass kein Lagerplatz in der Wildnis ohne ein Lagerfeuer vollständig ist, und drängt Reisende dazu, sich im Kochen ausbilden zu lassen, um zu lernen, wie man eine ordentliche Glut entfacht."},sec={{t="Unterschlupf für die offene Straße",b="Für einen Abenteurer, der weit hinter den Stadttoren umherzieht, ist ein Unterschlupf ebenso lebenswichtig wie eine Rüstung. Lederverarbeiter im Wald von Elwynn werden an Adele Fielder in Goldhain verwiesen, um ihr Handwerk über einfache Gürtel und Tuniken hinaus zu erweitern. Sobald ein Handwerker sein Können mit Leder und Nadel unter Beweis stellt, vermittelt Adele die praktische Kunst des Zusammenbaus eines strapazierfähigen Lagerzeltes, das dafür geschaffen ist, rauem Wetter auf langen Überlandexpeditionen standzuhalten."},{t="Die Grundlagen des Lagerlebens",b="Ein fertiges Zelt bietet mehr als nur ästhetischen Schutz; es hält müde Reisende unter sengender Sonne kühl, bei peitschenden Regenstürmen trocken und zwischen gefährlichen Begegnungen gut ausgeruht. Doch die Etikette der Wildnis und städtische Verordnungen spielen eine Rolle: Die Bewohner von Goldhain und die Stadtwachen dulden keine Lagerplätze mitten auf den Straßen des Ortes. Handwerker müssen in die offene Wildnis hinausziehen, um ihr Lager aufzuschlagen, und Adele erinnert alle Wanderer daran, dass kein Lagerplatz ohne ein ordentliches Lagerfeuer vollständig ist, wie man es bei einem Kochkunstlehrer lernt."}},faq={{q="Wer bringt Lederverarbeitern bei, Zelte herzustellen?",a="Adele Fielder ist im Ort Goldhain im Wald von Elwynn anzutreffen. Sie bringt qualifizierten Lederverarbeitern bei, wie man robuste Überlebenszelte anfertigt, sobald sie ihr Können in ihrem Handwerk unter Beweis gestellt haben.",al={"wer zelttraining anbietet","adele fielder standort","lederverarbeitung zeltlehrer"}},{q="Welchem Zweck dient ein hergestelltes Zelt?",a="Ein gut gearbeitetes Zelt schützt Reisende vor extremem Wetter, hält sie an drückend heißen Tagen kühl und bei starkem Regen trocken. Noch wichtiger ist, dass es Abenteurern die Erholung bietet, die sie brauchen, um auf Reisen durch die Wildnis auf der Hut zu bleiben.",al={"warum ein zelt herstellen","was ein zelt bewirkt","zeltvorteile"}},{q="Kann man ein Zelt innerhalb einer Stadt aufschlagen?",a="Zelte können nicht einfach überall aufgeschlagen werden; die Stadtbewohner sehen es ungern, wenn Reisende Straßen oder Dorfzentren mit Zeltlagern verstellen. Von Abenteurern wird erwartet, dass sie ihre Ausrüstung in die Wildnis hinaustragen, um dort ordnungsgemäß ihr Lager aufzuschlagen.",al={"kann man ein zelt in der stadt aufschlagen","wo man ein zelt benutzen kann","zelt in sturmwind oder goldhain"}},{q="Was wird neben einem Zelt noch benötigt, um ein Lager zu vervollständigen?",a="Ein Zelt allein macht noch keinen funktionstüchtigen Lagerplatz aus. Adele Fielder betont, dass zu jedem richtigen Lager ein Lagerfeuer gehört, das in der Wildnis Wärme und praktischen Nutzen spendet.",al={"was noch fuer das lager gebraucht wird","zelt lagerfeuer anforderung","wie man ein lager komplettiert"}},{q="Wo kann ein Reisender lernen, ein Lagerfeuer zu errichten?",a="Kochkunstlehrer und örtliche Köche lehren die Grundlagen des Entzündens eines Lagerfeuers. Abenteurer, die sich auf das Zelten vorbereiten, werden dazu angehalten, die Kochkünste zu erlernen, damit sie wissen, wie sie überall auf ihren Reisen ein verlässliches Feuer entfachen können.",al={"wer lagerfeuer lehrt","wie man lagerfeuer lernt","feuer fuer das lager"}},{q="Wann kann ein Lederverarbeiter lernen, ein Campingzelt herzustellen?",a="Angehende Lederverarbeiter müssen zunächst Fertigkeit in der Lederverarbeitung nachweisen, bevor Adele Fielder sie in der Herstellung eines Zeltes unterweist. Sobald ausreichendes handwerkliches Können gezeigt wird, kann die Technik erlernt werden.",al={"zelt faehigkeitsanforderungen","wie man das zeltrezept bekommt","wann man ein zelt herstellen kann"}}},fp="27,277,25.402.0,27.521.0,46.203.0,39.246.0,35.215.0,56.175.0,47.212.0,55.206.0"}
P.entries["quest:97923"] = {n="Camping 101: Mining",s="Camping 101: Mining ist eine Einführungsquest, die Bergbauarbeitern beibringt, wie man einen Magnetstein herstellt, um Lagerplätze in der Wildnis aufzuwerten. Angeleitet von Gelman Stonehand in Sturmwind lernen Schürfer, resonantes Erdkunstwerk zu kanalisieren, um die Kampfeskraft ihrer Gefährten am Lagerfeuer zu stärken.",h="Camping 101: Mining ist eine Einführungsquest, die Bergbauarbeitern beibringt, wie man einen Magnetstein...",kw={"lagerfeuer","camping 101: mining","lagerplatz","gelman steinhand","magnetstein","bergbau","sturmwind","wildnis"},ang={["faction:Alliance"]="Gelman Stonehand wirkt von Sturmwind aus und leitet Handwerker der Allianz dabei an, rohes Erdkunstwerk in praktische Ausrüstung für den Feldeinsatz zu verwandeln.",["profession:Cooking"]="Lager sind elementar auf ein gut gepflegtes Lagerfeuer angewiesen, was eine grundlegende Kochausbildung zu einer unverzichtbaren Ergänzung für spezialisiertes Lagerzubehör macht.",["profession:Mining"]="Bergbauarbeiter, die ihr Handwerk verfeinern, können Magnetsteine formen, um ihre Lagerplätze in der Wildnis aufzuwerten, was Verbündeten, die an ihrer Seite rasten, kämpferische Vorteile gewährt."},sec={{t="Die resonante Kraft der Erde",b="Bergbau ist harte, ehrliche Arbeit, doch sein Lohn reicht weit über das Verhütten von Barren und das Schmieden von Rüstungen hinaus. Hingebungsvolle Bergbauarbeiter in Sturmwind können lernen, den natürlichen Magnetismus der Erde für einen funktionalen Magnetstein nutzbar zu machen. Wenn dieser Stein am Lagerplatz einer Expedition aufgestellt wird, stärkt er die Kampfeskraft jedes Kämpfers, der sich um das Herdfeuer versammelt. Gelman Stonehand, der erfahrene Bergbaulehrer in der Hauptstadt des Königreichs, gibt das Handwerk an Schürfer weiter, die Geschick mit der Spitzhacke beweisen."},{t="Wildnislager und Lagerfeuer",b="Ein Magnetstein kann nicht einfach auf das Kopfsteinpflaster des Kathedralenplatzes oder des Handelsdistrikts geworfen werden. Die Stadtbevölkerung betrachtet es mit Missbilligung, wenn Reisende innerhalb der Stadtgrenzen provisorische Lager aufschlagen, sodass Pioniere in die ungezähmte Wildnis aufbrechen müssen, um ihr Lager zu errichten. Darüber hinaus ist spezialisierte Ausrüstung wie ein Magnetstein nutzlos ohne das wärmende Fundament eines Lagerfeuers – eine grundlegende Fertigkeit zum Überleben in der Wildnis, die von Köchen im gesamten Reich gelehrt wird."}},faq={{q="Was ist Camping 101: Mining?",a="Diese Quest führt Bergbauarbeiter in die Kunst ein, spezialisierte Lagerplatz-Aufwertungen herzustellen. Sobald Ihr Euer Geschick im Bergbau bewiesen habt, sprecht Ihr mit Gelman Stonehand in Sturmwind, um zu lernen, wie man einen Magnetstein schmiedet.",al={"was ist camping 101 mining","questziel","was soll ich tun"}},{q="Wer lehrt den Bauplan für den Magnetstein?",a="Gelman Stonehand ist ein Bergbaulehrer in Sturmwind. Er bringt qualifizierten Bergbauarbeitern bei, wie man einen Magnetstein herstellt, um ihre Expeditionen in der Wildnis zu stärken.",al={"wer lehrt magnetstein","wo ist gelman steinhand","standort von steinhand"}},{q="Was bewirkt ein Magnetstein?",a="Ein Magnetstein ist ein Gegenstand, der an einem Lagerplatz in der Wildnis aufgestellt wird. Er verströmt eine stärkende Präsenz um das Lagerfeuer herum, die das Kampfgeschick von Kriegern und anderen Nahkämpfern verbessert, die sich dort zum Rasten versammeln.",al={"was bewirkt ein magnetstein","magnetstein-stärkungszauber","warum magnetstein herstellen"}},{q="Kann ich mein Lager innerhalb von Sturmwind aufschlagen?",a="Die städtischen Behörden und das einfache Volk sehen es gar nicht gern, wenn Lager auf öffentlichen Plätzen oder an Stadtstraßen aufgeschlagen werden. Ihr müsst in die Wildnis jenseits der Tore von Siedlungen reisen, um ein Lager zu errichten und Euren Magnetstein aufzustellen.",al={"kann man in der stadt rasten","wo kann man ein lager aufschlagen","lager-beschränkungen"}},{q="Warum brauche ich ein Lagerfeuer, um ein Lager aufzuschlagen?",a="Jeder Lagerplatz erfordert ein einfaches Lagerfeuer als zentrales Fundament, bevor spezialisierte Lagerausrüstung genutzt werden kann. Köche bringen Reisenden für gewöhnlich bei, wie man Feuer mit einfachem Holz und Feuerstein entfacht.",al={"braucht man kochen für das lagern","wie man ein lager aufschlägt","lagerfeuer-voraussetzung"}},{q="Wer profitiert am meisten davon, sich um einen Magnetstein zu versammeln?",a="Jeder, der eine Klinge, eine Axt oder einen Hammer schwingt, profitiert enorm von der Macht des Magnetsteins. Er strahlt einen zusätzlichen kriegerischen Vorzug aus, den Kämpfer suchen, während sie sich vor einer gefährlichen Schlacht an den Flammen ausruhen.",al={"wer profitiert vom magnetstein","ist der magnetstein für nahkämpfer","magnetstein-klassen"}}},fp="19,281,26.496.0,30.439.0,28.209.0,36.163.0,25.207.0,35.210.0,40.192.0,52.198.0"}
P.entries["quest:97924"] = {n="Camping 101: Skinning",s="Camping 101: Skinning ist eine einführende Ausbildungsaufgabe für geübte Kürschner, die durch den Wald von Elwynn reisen. Sie schickt Abenteurer zu Helene Peltskinner in Goldhain, um zu lernen, wie man aus gesammelten Bälgen einen Lagerstuhl anfertigt. Das Erlernen der Herstellung eigener Lagermöbel ermöglicht es Reisenden in der Wildnis, weit außerhalb der Sicherheit besiedelter Städte zu rasten und sich zu erholen.",h="Camping 101: Skinning ist eine einführende Ausbildungsaufgabe für geübte Kürschner, die durch den Wald von...",kw={"lagerstuhl","lagerfeuer","camping 101: skinning","goldhain","helene peltskinner","kürschnerei","wildnis-camping"},ang={["faction:Alliance"]="Kürschnerlehrlinge der Allianz, die den Wald von Elwynn besuchen, werden zu Helene Peltskinner in Goldhain geschickt, um ihr Wissen über das Überleben in der Wildnis zu erweitern.",["profession:Cooking"]="Kürschnern, die den Aufbau eines Feldlagers erlernen, wird empfohlen, einen Koch zu Rate zu ziehen, da kein Lagerplatz ohne ein einfaches Lagerfeuer vollständig ist, um sich warm zu halten und Mahlzeiten zuzubereiten."},sec={{t="Annehmlichkeiten in der Wildnis",b="Für Jäger und Kundschafter in der Wildnis bietet die Kunst, Bestienbälge zu gewinnen, weit mehr als nur Handelswaren und Rüstungsfetzen. Erfahrene Kürschner können feldfähige Annehmlichkeiten wie einen Lagerstuhl herstellen, der es Reisenden ermöglicht, zu sitzen, ihre Glieder auszuruhen und während langer Märsche durch gefährliche Länder in bester körperlicher Verfassung zu bleiben. Helene Peltskinner in Goldhain unterweist geübte Kürschner darin, wie man rohe Bestienpelze in bequeme Sitzgelegenheiten für das Lager verwandelt."},{t="Regeln des Lagerplatzes",b="Das Errichten einer Raststätte im Feld erfordert Respekt vor den örtlichen Siedlungen und die richtige Vorbereitung auf das Überleben im Freien. Die meisten Stadtbewohner sehen es ungern, wenn Abenteurer auf dem Dorfplatz persönliche Lager aufschlagen, weshalb Reisende in die Wildnis aufbrechen müssen, bevor sie ihre Ausrüstung ausrollen. Zudem ist kein Lagerplatz wirklich brauchbar ohne ein Lagerfeuer, was viele Kürschner dazu veranlasst, grundlegende Kochkünste zu erlernen, um das Entfachen von Feuern zu meistern."}},faq={{q="Was ist Camping 101: Skinning?",a="Camping 101: Skinning ist eine einführende Ausbildungsaufgabe, die geübte Kürschner dazu anleitet zu lernen, wie man aus gesammelten Bestienbälgen einen Lagerstuhl herstellt, was ihre Überlebensfähigkeiten in der Wildnis erweitert.",al={"was ist camping 101: skinning","was bewirkt diese quest","kürschnerei lagerstuhl quest"}},{q="Wer bringt Kürschnern bei, wie man einen Lagerstuhl herstellt?",a="Helene Peltskinner, eine Lederverarbeitungs- und Kürschnereilehrerin in Goldhain im Wald von Elwynn, lehrt geübte Kürschner, wie man den Stuhl herstellt.",al={"wer lehrt lagerstuhl","helene peltskinner aufenthaltsort","wo gibt man camping 101: skinning ab"}},{q="Was ist der Zweck der Herstellung eines Lagerstuhls?",a="Ein Lagerstuhl bietet einem Abenteurer einen bequemen Sitzplatz an seinem Lager, um zu rasten und sich zu erholen, wodurch sichergestellt wird, dass er für Reisen und Kämpfe in der Wildnis in Bestform bleibt.",al={"was macht ein lagerstuhl","warum einen lagerstuhl herstellen","lagerstuhl zweck"}},{q="Wo können Abenteurer ihr Lager aufschlagen?",a="Stadtbewohner schätzen es im Allgemeinen nicht, wenn Lager mitten in Siedlungen aufgeschlagen werden. Von Abenteurern wird erwartet, dass sie sich in die Wildnis hinauswagen, bevor sie ihre Stühle und Lager aufstellen.",al={"kann ich in städten campen","wo kann ich einen lagerstuhl aufstellen","campen in goldhain"}},{q="Was wird sonst noch benötigt, um ein vollständiges Lager zu errichten?",a="Jedes richtige Lager erfordert ein einfaches Lagerfeuer, bevor man die Ausrüstung aufstellt. Abenteurer ohne Kenntnisse über das Feuermachen werden ermutigt, die Kochkunst bei einem Koch vor Ort zu erlernen.",al={"was brauche ich für ein lager","brauche ich ein feuer zum campen","lagerfeuer voraussetzung"}},{q="Wer ist berechtigt, dieses Camping-Handwerk zu erlernen?",a="Dieses spezielle Camping-Handwerk ist auf Kürschner zugeschnitten, die Geschick beim Erbeuten von Bälgen erlegter Bestien bewiesen haben, wodurch sie ihr im Feld gesammeltes Leder für praktische Überlebenszwecke nutzen.",al={"wer kann lagerstuhl lernen","können nicht-kürschner dies tun","kürschnerei voraussetzung camping"}}},fp="21,368,29.435.0,21.394.0,30.200.0,47.149.0,45.173.0,34.188.0,51.174.0,44.199.0"}
P.entries["quest:97925"] = {n="Camping 101: Tailoring",s="Camping 101: Tailoring verweist erfahrene Stoffwirker an Eldrin im Holzfällerlager des Osttals im Wald von Elwynn. Durch ihn lernen Schneider, ein Fraktionsbanner zu weben, das an abgelegenen Lagerplätzen für Inspiration sorgt und die Moral stärkt.",h="Camping 101: Tailoring verweist erfahrene Stoffwirker an Eldrin im Holzfällerlager des Osttals im Wald von...",kw={"banner","camping","camping 101","holzfällerlager des osttals","eldrin","wald von elwynn","fraktionsbanner","schneiderei"},ang={["faction:Alliance"]="Abenteurer der Allianz werden zu Eldrin im Holzfällerlager des Osttals im Wald von Elwynn geschickt, um das Nähen von Fraktionsbannern zu erlernen.",["profession:Tailoring"]="Schneider können ein inspirierendes Fraktionsbanner weben, um die Moral zu stärken und die Stimmung im Lager während langer Expeditionen voller Tatkraft zu halten."},sec={{t="Der Zweck eines Webers in der Wildnis",b="Camping 101: Tailoring leitet vielversprechende Nadelarbeiter zu Eldrin, einem Handwerker im Holzfällerlager des Osttals im östlichen Wald von Elwynn. Die Schneiderei wird oft für die Herstellung schützender Stoffkleidung und Taschen gerühmt, doch dieser Auftrag hebt ihre Rolle bei der Unterstützung von Unternehmungen in der Wildnis hervor. Abenteurern, die ihr Geschick mit Faden und Webstuhl bewiesen haben, wird eine spezialisierte Anleitung zur Gestaltung von Lagerzubehör geboten, das ausgedehnte Reisen durch die Wildnis unterstützt."},{t="Banner der Moral",b="Das wichtigste durch diese Unterweisung gelehrte Handwerk ist das Fraktionsbanner – ein Emblem, das dafür entworfen wurde, hoch neben dem Feuer eines Reisenden aufgestellt zu werden. Auf gefährlichen Reisen ebenso wie auf Schlachtfeldern ist das Aufrechterhalten einer hohen Moral genauso unerlässlich wie das Instandhalten von Waffen oder Rationen. Das Aufstellen eines inspirierenden Banners über einem Lager bietet erschöpften Abenteurern ein vertrautes Symbol der Entschlossenheit und schenkt den nötigen Energieschub, um weiter in feindliche Länder vorzudringen."}},faq={{q="Was ist der Zweck von Camping 101: Tailoring?",a="Camping 101: Tailoring weist angehende Schneider an, Eldrin im Holzfällerlager des Osttals im Wald von Elwynn aufzusuchen. Sobald ein Schneider ausreichendes Können unter Beweis stellt, unterweist Eldrin ihn darin, wie man ein inspirierendes Fraktionsbanner näht, um die Stimmung an einem Lagerplatz zu heben.",al={"was ist camping 101 tailoring","schneider camp gegenstand quest","wie man ein lagerbanner bekommt"}},{q="Wer ist Eldrin und wo ist er zu finden?",a="Eldrin ist ein Handwerker, der im Holzfällerlager des Osttals im östlichen Wald von Elwynn ansässig ist. Er besitzt das Fachwissen, um erfahrene Schneider in der Herstellung lagertauglicher Fraktionsbanner zu unterweisen.",al={"wer ist eldrin","wo ist eldrin","eldrin aufenthaltsort"}},{q="Was bewirkt das Fraktionsbanner für ein Lager?",a="Das Fraktionsbanner dient als Mittelpunkt des Lagers, der darauf ausgelegt ist, Moral und Inspiration zu fördern. Im Feld hilft das Zeigen Eurer Zugehörigkeit, erschöpfte Reisende während zermürbender Feldzüge voller Tatkraft und konzentriert zu halten.",al={"was bewirkt das schneiderbanner","fraktionsbanner lager","warum ein fraktionsbanner herstellen"}},{q="Welche Voraussetzungen sind nötig, um das Handwerk von Eldrin zu erlernen?",a="Das Handwerk erfordert nachgewiesenes Können in der Schneiderei, bevor Eldrin die Technik weitergibt. Nur Ausübende, die ihre Nadelarbeit verfeinert haben, können das Banner ordnungsgemäß weben und zusammensetzen.",al={"welche fertigkeit brauche ich","campingbanner voraussetzungen","kann jeder schneider ein banner herstellen"}},{q="Wo befindet sich das Holzfällerlager des Osttals?",a="Das Holzfällerlager des Osttals liegt eingebettet in den östlichen Wäldern des Walds von Elwynn an der Straße, die zum Rotkammgebirge führt. Es ist ein aktiver Holzfällerknotenpunkt, an dem lokale Handwerker und Arbeiter zusammenkommen.",al={"wo liegt das holzfällerlager des osttals","holzfällerlager des osttals elwynn"}},{q="Ist diese Aufgabe ausschließlich für Schneider der Allianz gedacht?",a="Dieser spezielle Botengang schickt den Handwerker zu Eldrin im Herzen des Walds von Elwynn, tief im Territorium der Allianz. Daher richtet er sich an der Allianz angehörende Handwerker, die von den östlichen Siedlungen aus operieren.",al={"kann die horde diese quest machen","ist das nur für die allianz"}}},fp="22,234,30.473.0,17.433.0,46.267.0,40.179.0,43.211.0,60.191.0,43.207.0,43.206.0"}
P.entries["quest:97926"] = {n="Making Do",s="Making Do ist eine Quest der Allianz, die den Hafen von Auberdine an der Dunkelküste mit dem fernen Königreich Sturmwind verbindet. Ein Abenteurer wird damit beauftragt, Elder Thundris Windweaver eine offizielle Antwort von Alexston zu überbringen, und bringt düstere Kunde: Da Sturmwinds Kassen erschöpft sind, sieht sich die Stadt außerstande, der bedrängten Nachtelfensiedlung beizustehen.",h="Making Do ist eine Quest der Allianz, die den Hafen von Auberdine an der Dunkelküste mit dem fernen...",kw={"alexston","alexstons antwort","auberdine","staatskasse","dunkelküste","making do","sturmwind","thundris windweaver"},ang={["faction:Alliance"]="Diese Quest verdeutlicht den zerbrechlichen Zusammenhalt innerhalb der Allianz und veranschaulicht, wie geografische Entfernung und innere Belastungen dazu führen, dass abgelegene Siedlungen wie Auberdine ohne finanzielle Rückendeckung aus Sturmwind auf sich allein gestellt sind.",["race:Human"]="Alexstons Brief spiegelt die bittere Realität wider, mit der sich das Königreich Sturmwind konfrontiert sieht, wo geleerte Kassen und weit verbreitete Not im eigenen Land die Krone daran hindern, überseeische Hilfsmaßnahmen zu finanzieren.",["race:NightElf"]="Für die Nachtelfen von Auberdine unterstreicht die Absage aus Sturmwind die wachsende Erkenntnis, dass weder ihre menschlichen Verbündeten jenseits des Meeres noch das nahegelegene Darnassus eingreifen, um ihre lokalen Nöte zu lindern."},sec={{t="Ein Bote über das Meer",b="Making Do beauftragt einen Reisenden damit, Alexstons Antwort über das Meer zu Elder Thundris Windweaver in Auberdine zu bringen. Statt Versprechungen von Hilfsgütern oder Truppenentsendungen enthält das Schreiben jedoch eine bedauerliche Absage. Der Vertreter von Sturmwind beklagt, dass die Schatzkammer des Königreichs zur Neige geht und der wenige verbleibende Wohlstand bereits für die eigenen darbenden Gebiete kaum ausreicht."},{t="Ihrem eigenen Schicksal überlassen",b="Nach Erhalt der Antwort beklagt Thundris Windweaver das Ergebnis, dankt dem Reisenden jedoch dafür, die lange Reise auf sich genommen zu haben. Da Sturmwind keine Hilfe leisten kann und auch Darnassus sich nicht rührt, fügen sich Thundris und sein Volk in die Selbstversorgung und stellen fest, dass das Schicksal von Auberdine vollkommen in ihren eigenen Händen liegt."}},faq={{q="Was ist die Quest Making Do?",a="Making Do ist eine Quest, bei der ein Abenteurer Baros Alexstons formelle Antwort aus Sturmwind zurück zu Ältester Thundris Windweaver in Auberdine überbringt und die enttäuschende Nachricht überbringt, dass Sturmwind es sich nicht leisten kann, Hilfe an die Dunkelküste zu senden.",al={"was ist making do","quest making do","auberdine sturmwind quest"}},{q="Warum weigert sich Sturmwind, Auberdine zu helfen?",a="Sturmwinds Vertreter erklärt, dass die Kassen des Königreichs stark erschöpft sind und die wenigen verbliebenen Ressourcen bereits für die eigenen Ländereien kaum ausreichen, weshalb sie außerstande sind, Unterstützung für Auberdine zu finanzieren.",al={"warum sturmwind nein gesagt hat","sturmwinds klamme kassen","warum sturmwind auberdine nicht hilft"}},{q="Wie reagiert Thundris Windweaver auf die Nachricht?",a="Thundris Windweaver nimmt den Brief mit Trauer auf, akzeptiert jedoch die Realität und zieht den Schluss, dass die Bewohner von Auberdine ihr Schicksal selbst in die Hand nehmen müssen, da weder Sturmwind noch Darnassus Unterstützung leisten werden.",al={"thundris reaktion auf sturmwind","wie reagiert thundris"}},{q="Wer hat Alexstons Antwort gesendet?",a="Baros Alexston ist Sturmwinds Stadtarchitekt, der die Antwort des Königreichs überbringt und dabei persönliches Mitgefühl für Auberdines Notlage ausdrückt, während er die harte Wahrheit über Sturmwinds finanzielle Unfähigkeit zu helfen überbringt.",al={"wer ist alexston","absender von alexstons antwort"}},{q="Hilft Darnassus Auberdine?",a="Beim Lesen von Alexstons Brief stellt Thundris Windweaver fest, dass weder Sturmwind noch die nahegelegene Hauptstadt Darnassus zur Hilfe geeilt sind, was die Siedlung Auberdine isoliert und auf sich allein gestellt zurücklässt.",al={"hilfe von darnassus für auberdine","warum darnassus nicht geholfen hat"}},{q="Wo wird Alexstons Antwort abgegeben?",a="Die Quest endet in der Hafenstadt Auberdine an der Küste der Dunkelküste, wo Thundris Windweaver auf die Rückkehr des Boten aus Sturmwind wartet.",al={"wo endet diese quest","abgabeort von making do"}}},fp="9,322,24.392.0,22.316.1,28.231.0,43.211.0,47.222.0,26.214.0,31.205.0,36.156.0"}
P.entries["quest:97932"] = {n="Camping 101: Fishing",s="Camping 101: Fishing führt Angler in die Kunst ein, Lagerplätze in der Wildnis mit handgefertigten Annehmlichkeiten auszustatten. Indem Fischer Uthan Stillwater im Dorf der Bluthufe ihr Können unter Beweis stellen, lernen sie, ein Fischglas herzustellen, das in der Wildnis rastenden Reisenden moralstärkende Aufheiterung spendet.",h="Camping 101: Fishing führt Angler in die Kunst ein, Lagerplätze in der Wildnis mit handgefertigten...",kw={"dorf der bluthufe","lagerfeuer","zelten","camping 101: fishing","fischglas","angeln","mulgore","uthan stillwater"},ang={["faction:Horde"]="Angler der Horde, die durch Mulgore reisen, können bei Uthan Stillwater im Dorf der Bluthufe lernen, Lagerausstattung herzustellen.",["profession:Cooking"]="Jeder richtige Lagerplatz erfordert zu Beginn ein einfaches Lagerfeuer, was eine grundlegende Kochausbildung zu einer natürlichen Ergänzung für das Feldlager eines jeden Fischers macht."},sec={{t="Angeln in der Wildnis",b="Angler, die durch Mulgore reisen, können ihren ruhigen Zeitvertreib durch Camping 101: Fishing in praktisches Lagerhandwerk verwandeln. Abenteurer, die ihr Können mit Rute und Rolle bewiesen haben, werden angewiesen, Uthan Stillwater im Dorf der Bluthufe aufzusuchen. Anstatt bloß für Nahrung zu sorgen, lernen geschickte Fischer, einen häuslichen Einrichtungsgegenstand für das Leben in der Wildnis herzustellen: ein persönliches Fischglas, um den Lagerplatz zu verschönern."},{t="Annehmlichkeiten des Lagers",b="Ein Fischglas mag für abgehärtete Wanderer wie ein seltsamer Begleiter wirken, doch ein komfortabler Rastplatz zahlt sich auf Reisen aus. Der kleine Einrichtungsgegenstand bringt einen willkommenen Hauch von Heiterkeit und Ruhe in die raue Wildnis und stärkt die Moral aller, die an den Flammen rasten. Wie erfahrene Überlebenskünstler wissen, schlagen sich gehobene Lebensgeister direkt in geschärften Instinkten und größerer Widerstandskraft im Kampf nieder."},{t="Lagerfeuer und offenes Land",b="Das Aufschlagen eines Lagers erfordert sowohl Respekt vor lokalen Bräuchen als auch solide Grundkenntnisse. Siedlungen wie das Dorf der Bluthufe dulden es nicht, wenn Reisende mitten im Ort temporäre Zeltlager errichten, was bedeutet, dass das Fischglas nur draußen in der offenen Wildnis ausprobiert werden kann. Darüber hinaus lässt sich kein Lagerplatz ohne ein ordentliches Lagerfeuer errichten, weshalb angehende Camper Kochkunstlehrer aufsuchen müssen, um das grundlegende Feuermachen zu erlernen."}},faq={{q="Was bewirkt das Fischglas für einen Lagerplatz?",a="Ein Fischglas dient als dekorativer Lagergegenstand, der von geübten Fischern hergestellt wird. Es soll Abenteurern, die in der Wildnis rasten, Freude und Behaglichkeit bringen und ihre Moral hochhalten, damit sie im Kampf wachsam und schlagkräftig bleiben.",al={"fischglas lager","fischglas was bewirkt es","fischglas vorteil"}},{q="Wer lehrt das Rezept für das Fischglas?",a="Uthan Stillwater lehrt das Handwerk im Dorf der Bluthufe, gelegen in den wogenden Ebenen von Mulgore. Er unterweist Angler, die bereits ausreichendes Können in ihrer Angelfertigkeit bewiesen haben.",al={"wo fischglas lernen","wer lehrt fischglas","uthan stillwater aufenthaltsort"}},{q="Warum kann man kein Lager innerhalb einer Siedlung aufschlagen?",a="Stadtbewohner und Dorfwachen sehen es im Allgemeinen nicht gern, wenn Reisende mitten auf bewohnten Straßen vollständige Lager aufschlagen und Feuer entzünden. Lager müssen stattdessen draußen in der weiten, unberührten Wildnis aufgeschlagen werden.",al={"lager in der stadt","warum kann ich im dorf der bluthufe nicht lagern","zelten in städten"}},{q="Was wird sonst noch benötigt, um ein Lager aufzuschlagen?",a="Ein richtiger Lagerplatz kann ohne ein Lagerfeuer in seinem Herzen nicht funktionieren. Reisenden, die nicht über die Fähigkeit verfügen, eines zu entfachen, wird geraten, einen Kochkunstlehrer aufzusuchen, um die Kunst des Feuermachens zu meistern, bevor sie ein Lager errichten.",al={"lagerfeuer anforderung fürs zeltlager","feuer für lager benötigt","camping grundlagen feuer"}},{q="Welche Voraussetzungen müssen erfüllt sein, bevor man das Fischglas erlernen kann?",a="Die Ausbildung erfordert nachgewiesenes Können im Angeln, bevor Uthan Stillwater die Geheimnisse zur Herstellung von Lagergegenständen teilt. Unerfahrene Angler müssen zunächst einige Zeit am Wasser verbringen, um ihr Handwerk zu verfeinern.",al={"angeln fertigkeit zeltlager","wann kann ich fischglas erhalten","camping 101: fishing anforderungen"}},{q="Warum sollte ein Abenteurer beim Zelten ein Fischglas haben wollen?",a="Das Leben auf den Straßen ganz Azeroths ist düster und beschwerlich. Kleine Nuancen des häuslichen Lebens und friedliche Hobbys, wie das Beobachten eines Fisches in einem Glas am Feuer, schenken einen seltenen Funken Freude, der den Geist eines Abenteurers stärkt.",al={"warum fischglas zum zelten mitbringen","lager fischglas geschichte"}}},fp="20,285,19.401.0,16.384.0,25.420.0,42.228.0,33.196.0,45.194.0,39.211.0,59.214.0,55.218.0"}
P.entries["quest:97934"] = {n="Camping 101: Leatherworking",s="Camping 101: Leatherworking schickt angehende Lederverarbeiter in das Dorf der Bluthufe in Mulgore, um die Kunst des Baus tragbarer Lagerzelte zu erlernen. Indem sie dieses grundlegende Handwerk bei Chaw Stronghide meistern, können Reisende schützende Unterkünfte in der Wildnis errichten, um auf ihren Reisen ausgeruht und widerstandsfähig zu bleiben. Es verdeutlicht die Bedeutung von Selbstständigkeit, dem Überleben in der Wildnis und Vorbereitung im Freien im gesamten Grenzland.",h="Camping 101: Leatherworking schickt angehende Lederverarbeiter in das Dorf der Bluthufe in Mulgore, um die...",kw={"dorf der bluthufe","lagerfeuer","camping 101","chaw stronghide","lederverarbeitung","mulgore","unterkunft","zelt"},ang={["faction:Horde"]="Reisende der Horde, die das weite und trockene Terrain von Kalimdor durchqueren, sind auf robuste Campingausrüstung angewiesen, um fernab befestigter Festungen zu überleben.",["profession:Cooking"]="Kochkunstlehrer lehren die Kunst, ein ordentliches Lagerfeuer zu errichten, was unerlässlich ist, um aus einem einfachen Lederzelt ein voll funktionsfähiges, wärmendes Lager zu machen.",["race:Tauren"]="Die Herstellung tragbarer Lederunterkünfte fügt sich ganz natürlich in die nomadischen Traditionen und das Überlebenserbe der Taurenstämme in den Ebenen von Mulgore ein."},sec={{t="Unterkünfte für die offenen Ebenen",b="Für Lederverarbeiter, die durch die wilden Weiten von Kalimdor reisen, ist das Wissen um das Zusammennähen eines stabilen Zelts ebenso wichtig wie das Gerben von Leder. Ein gut gefertigtes Zelt schützt müde Reisende vor der sengenden Mittagssonne und hält die unerbittlichen Regengüsse der Prärie ab. Mehr als bloße Leinwand und Leder bietet es eine ruhige Zuflucht, in der ein Abenteurer ordentlich rasten und neue Kräfte sammeln kann, bevor er sich der nächsten Prüfung in den offenen Ebenen stellt."},{t="Das Handwerk von Chaw Stronghide",b="In der friedlichen Taurensiedlung des Dorfs der Bluthufe, eingebettet in das goldene Gras von Mulgore, gibt Chaw Stronghide die praktischen Geheimnisse des Überlebens in der Wildnis weiter. Chaw erkennt, wann ein Lederverarbeiter die nötige Fertigkeit entwickelt hat, um schwerere Leder und robuste Nähte zu verarbeiten. Sobald ein Handwerker sein Können unter Beweis stellt, unterweist er ihn darin, wie man ein langlebiges Lagerzelt konstruiert, das den Elementen auf langen Reisen fernab der Zivilisation trotzt."},{t="Lager in der Wildnis",b="Das Aufschlagen eines Zelts erfordert gutes Urteilsvermögen und Respekt gegenüber den örtlichen Siedlungen. Die Dorfbewohner sehen es ungern, wenn Reisende ihre zentralen Pfade und Durchgangsstraßen mit persönlichen Lagerplätzen verstellen, weshalb Lederverarbeiter in das wilde Grenzland hinausziehen müssen, bevor sie ihre Unterkünfte abspannen. Darüber hinaus ist kein Lager in der Wildnis wirklich vollständig ohne die Wärme und den Schutz eines knisternden Feuers, was Wanderer dazu bewegt, erfahrene Köche aufzusuchen, um zu lernen, wie man ein ordentliches Lagerfeuer entfacht."}},faq={{q="Was lehrt diese Quest Lederverarbeiter?",a="Die Quest weist Lederverarbeiter an, zu lernen, wie man ein persönliches Lagerzelt für ihre Reisen herstellt. Ein stabiles Zelt bietet lebenswichtigen Schutz gegen raues Wetter, hält Reisende bei sengender Hitze kühl und bei Regengüssen trocken, während es gleichzeitig dafür sorgt, dass sie in der Wildnis angemessene Erholung finden.",al={"lederverarbeitung zelt quest","was lehrt camping 101","lederverarbeitung lager gegenstand"}},{q="Wer bringt Lederverarbeitern bei, wie man Lagerzelte herstellt?",a="Chaw Stronghide im Dorf der Bluthufe in Mulgore unterweist Lederverarbeiter in der Errichtung von Campingunterkünften. Er erklärt sich bereit, sein Wissen über die Zeltherstellung weiterzugeben, sobald ein Lederverarbeiter angemessenes Können in seinem Handwerk unter Beweis stellt, und lehrt traditionelle Überlebenstechniken, die für lange Expeditionen durch die Wildnis geeignet sind.",al={"wer lehrt zeltherstellung","chaw stronghide zelt","lederverarbeitung zeltlehrer"}},{q="Wo können Reisende ihre Lagerzelte aufstellen?",a="Lagerzelte müssen draußen in der offenen Wildnis aufgeschlagen werden und nicht innerhalb bevölkerter Siedlungen. Stadtbewohner und Dorfälteste schätzen es nicht, wenn Reisende mitten auf Dorfplätzen oder belebten Straßen private Unterkünfte errichten, daher müssen Wanderer in die freie Natur hinausziehen, um ihre neue Ausrüstung zu erproben.",al={"wo kann ich ein zelt aufschlagen","kann ich in einer stadt zelten","zeltplatzierung"}},{q="Warum wird neben einem Zelt auch ein Lagerfeuer benötigt?",a="Ein ordentliches Lager in der Wildnis ist unvollständig ohne ein knisterndes Lagerfeuer, das Licht, Wärme und Nahrung spendet. Während ein Lederverarbeiter das schützende Zelt herstellt, erfordert das Entzünden eines Feuers grundlegende kulinarische Überlebenstechniken. Reisenden wird geraten, örtliche Köche aufzusuchen, um zu lernen, wie man ein Lagerfeuer entfacht und unterhält, bevor man in die Wildnis aufbricht.",al={"warum brauche ich ein lagerfeuer","kochkunst lagerfeuer zelt","zelt und feuer"}},{q="Wo befindet sich das Dorf der Bluthufe?",a="Das Dorf der Bluthufe ist eine bedeutende Taurensiedlung im zentralen Mulgore, südlich von Donnerfels an den Ufern des Stonebullsees gelegen. Es dient als wichtiger Gemeinschaftsknotenpunkt für einheimische Jäger, Sammler und Handwerker und bietet Ausbildung, Handelsgüter sowie Führung für Reisende, die die umliegenden Ebenen erkunden.",al={"wo liegt das dorf der bluthufe","dorf der bluthufe standort","wie findet man chaw stronghide"}},{q="Benötigt man Kochfertigkeit, um ein ordentliches Lager zu unterhalten?",a="Auch wenn Kochkunst für das Zusammennähen eines Lederzelts nicht zwingend vorgeschrieben ist, wird das Erlernen der kulinarischen Künste jedem Camper wärmstens empfohlen. Köche bringen Reisenden bei, wie man einfache Lagerfeuer entfacht, die unerlässlich sind, um ein Freiluftlager zu vervollständigen, die Nachtluft zu erwärmen und auf langen Reisen durch unbesiedelte Lande Speisen zuzubereiten.",al={"wird kochkunst zum zelten benoetigt","brauche ich kochkunst","lagerfeuer kochkunst grundlagen"}},{q="Welche Vorteile bietet ein Lagerzelt einem Reisenden?",a="Ein Lagerzelt bietet zuverlässigen Schutz vor den unbarmherzigen Elementen des Grenzlands, schirmt Wanderer an sonnigen Tagen vor großer Hitze ab und hält sie bei starkem Regen trocken. Das Rasten in einem gut gefertigten Zelt stellt sicher, dass ein Abenteurer erfrischt, wachsam und bereit für Gefahren bleibt, während er ferne Gebiete erkundet.",al={"vorteile eines campingzelts","warum ein zelt herstellen","was bewirkt ein zelt"}}},fp="27,418,28.445.0,28.472.0,17.472.0,42.292.0,51.329.0,44.310.0,42.342.0,35.321.0,56.330.0,53.324.0"}
P.entries["quest:97935"] = {n="Camping 101: Mining",s="Camping 101: Mining führt Bergleute durch ihr Handwerk in die Kunst des Überlebens in der Wildnis ein. Indem sie Brek Steinhuf in Donnerfels aufsuchen, lernen Bergleute, wie man einen spezialisierten Magnetstein fertigt, der das kriegerische Können von am Lagerfeuer rastenden Abenteurern stärkt.",h="Camping 101: Mining führt Bergleute durch ihr Handwerk in die Kunst des Überlebens in der Wildnis ein.",kw={"brek steinhuf","lager","lagerfeuer","camping 101: mining","magnetstein","bergbau","donnerfels"},ang={["faction:Horde"]="Expeditionsteilnehmer der Horde, die um das Lagerfeuer eines Bergmanns rasten, profitieren von dem vorbereiteten Magnetstein, der ihre Frontkämpfer für bevorstehende Kämpfe stärkt.",["profession:Mining"]="Bergleute lernen, wie sie ihr Sammelhandwerk direkt auf das Überleben im Feld anwenden, indem sie einen Magnetstein für Expeditionslager vorbereiten.",["race:Tauren"]="Die Ausbildung führt Bergleute zu Brek Steinhuf auf den Mesas von Donnerfels und greift auf das Wissen der Tauren über Stein- und Erdkunst zurück."},sec={{t="Ehrliche Arbeit in der Erde",b="Dem Bergbau mag es an Glanz und Eleganz hoher Arkanmagie fehlen, doch bleibt er auf ganz Azeroth eine grundlegende, ehrliche Arbeit. Ausübende fördern nützliche Mineralien und dichtes Gestein aus tiefen Felswänden und liefern so unverzichtbare Materialien für Waffen, Rüstungen und nun auch praktische Feldarbeiten. Durch das Campinghandwerk können Bergleute geförderten Stein in robuste Verbesserungen für ihre Rastplätze in der Wildnis verwandeln."},{t="Der Magnetstein von Donnerfels",b="Für Prospektoren, die ihr Handwerk dem Überleben widmen möchten, bietet Brek Steinhuf in Donnerfels spezialisierten Unterricht an. Sobald ein Bergmann angemessene Fertigkeit mit seiner Spitzhacke beweist, teilt Brek das Handwerk des Formens eines Lagermagnetsteins. Neben einem offenen Feuer platziert, verleiht der Stein jedem, der sich darauf vorbereitet, eine Klinge im Kampf zu schwingen, kriegerische Kraft und eine entscheidende Schärfe."}},faq={{q="Was bewirkt der Magnetstein für ein Lager?",a="Ein hergestellter Magnetstein, der in einem Lager platziert wird, strahlt subtile kriegerische Eigenschaften aus und verleiht Kriegern und Abenteurern, die sich um das Lagerfeuer versammeln, zusätzliches kriegerisches Können und neue Kraft.",al={"magnetstein lagervorteil","magnetstein bonus","was bewirkt magnetstein"}},{q="Wer ist Brek Steinhuf?",a="Brek Steinhuf befindet sich in der Taurenhauptstadt Donnerfels. Er unterweist erfahrene Bergleute darin, wie man aus abgebautem Stein und Erz spezialisierte Campingutensilien herstellt.",al={"brek steinhuf standort","wo ist brek steinhuf","wer lehrt bergbau lagergegenstand"}},{q="Wann kann ein Bergmann lernen, wie man einen Magnetstein herstellt?",a="Bergleute müssen zuerst grundlegende Fertigkeiten in ihrem Bergbauhandwerk vorweisen, bevor Brek Steinhuf ihnen die Techniken beibringt, die zur Konstruktion eines Magnetsteins erforderlich sind.",al={"wann kann man magnetstein lernen","bergbaufertigkeit anforderung magnetstein"}},{q="Wer profitiert am meisten von dem Magnetstein eines Bergmanns?",a="Jeder, der eine Waffe schwingen möchte, profitiert von der Anwesenheit eines Magnetsteins, da sein Einfluss physischen Kämpfern zusätzliche kriegerische Stärke verleiht, wenn sie neben ihm rasten.",al={"wer profitiert magnetstein","ist magnetstein fuer nahkaempfer"}},{q="Wie hängt Bergbau mit dem Errichten eines Lagers zusammen?",a="Neben der Versorgung von Schmelzern und Schmieden mit Rohmetall ermöglicht der Bergbau Wildnisreisenden, robuste Steingegenstände wie Magnetsteine herzustellen, die Überlebenslager in der Wildnis aufwerten.",al={"warum bergbau fuer camping","wie hilft bergbau dem lager"}},{q="Was ist der Zweck von Camping 101: Mining?",a="Camping 101: Mining ist eine Ausbildungsanweisung, die angehende Bergleute nach Donnerfels schickt, damit sie lernen, für das Überleben in der Wildnis geeignete Feldutensilien herzustellen.",al={"camping 101 mining uebersicht","was ist camping 101 mining"}}},fp="19,267,25.382.0,30.360.0,42.171.0,22.173.0,48.162.0,43.163.0,49.183.0,43.169.0"}
P.entries["quest:97936"] = {n="Camping 101: Skinning",s="Camping 101: Skinning führt erfahrene Balgsammler ins Dorf der Bluthufe, um ihr praktisches Handwerk im Feld zu erweitern. Unter der Anleitung von Yonn Deepcut lernen Kürschner, Bestienpelze zu bequemen Lagerstühlen für das Überleben in der Wildnis zu verarbeiten. Diese Ausbildung betont die Bedeutung von Rast und Vorbereitung, wenn man weit über die Sicherheit der Zivilisation hinaus reist.",h="Camping 101: Skinning führt erfahrene Balgsammler ins Dorf der Bluthufe, um ihr praktisches Handwerk im Feld...",kw={"dorf der bluthufe","lagerstuhl","lagerfeuer","camping 101","camping 101: skinning","mulgore","kürschnerei","yonn deepcut"},ang={["faction:Horde"]="Kürschner der Horde, die in Mulgore tätig sind, können das Dorf der Bluthufe besuchen, um zu lernen, wie sie aus ihren gesammelten Bälgen funktionale Lagerausrüstung herstellen.",["profession:Cooking"]="Ein ordentliches Lager erfordert ein wärmendes Lagerfeuer zur Sitzgelegenheit, dessen Entfachen Abenteurern von Kochlehrern auf der ganzen Welt beigebracht werden kann.",["race:Tauren"]="Yonn Deepcut bringt Kürschnern im Herzen von Mulgore bei, wie man aus Bestienbälgen bequeme Stühle für die Rast in der Wildnis herstellt."},sec={{t="Bälge der Wildnis",b="Das Erbeuten von Bälgen und Pelzen erlegter Bestien ist eine der praktischsten Überlebensfertigkeiten auf Azeroth. Abgesehen vom Gerben von Leder für Rüstungen und Ausrüstung kann ein findiger Kürschner rohe Tierfelle in Annehmlichkeiten für die Wildnis verwandeln. Für Reisende, die lange Wochen damit verbringen, wilde Regionen zu durchqueren, macht das Erlernen der Verarbeitung von Bälgen zu Rastausrüstung den Unterschied zwischen Erschöpfung und Kampfbereitschaft aus."},{t="Lehren im Dorf der Bluthufe",b="In Mulgore werden Kürschner ins Dorf der Bluthufe geschickt, um mit Yonn Deepcut zu sprechen. Sobald ein Kürschner grundlegende Fertigkeiten im Erbeuten von Bestienbälgen vorweist, vermittelt Yonn das Handwerk des Zusammennähens eines Lagerstuhls. Siedler in Städten und Dörfern sehen es nicht gern, wenn Reisende mitten auf der Straße Zelte aufschlagen, daher sind diese Stühle eigens für den Einsatz in der Wildnis gedacht – kombiniert mit einem prasselnden Lagerfeuer, wie es von örtlichen Köchen gelehrt wird."}},faq={{q="Was ist Camping 101: Skinning?",a="Camping 101: Skinning ist eine Einführungsaufgabe, die geübte Kürschner anweist, einen spezialisierten Ausbilder in Mulgore aufzusuchen. Nachdem sie ihr Können beim Erbeuten von Bälgen unter Beweis gestellt haben, lernen Kürschner, wie sie einen Lagerstuhl herstellen, um ihre Lager in der Wildnis auszustatten.",al={"was ist camping 101: skinning","camping skinning quest","was bewirkt diese quest"}},{q="Wer lehrt das Rezept für den Lagerstuhl?",a="Yonn Deepcut, ein im Dorf der Bluthufe in Mulgore stationierter Kürschner, lehrt die Technik zur Herstellung eines Lagerstuhls, sobald ein Abenteurer Geschick beim Erbeuten von Bestienbälgen bewiesen hat.",al={"wer lehrt lagerstuhl","mit wem sprechen für camping skinning","wo ist yonn deepcut"}},{q="Wofür wird ein Lagerstuhl verwendet?",a="Ein Lagerstuhl bietet einen bequemen Ort zum Rasten, wenn man draußen in der Wildnis sein Lager aufschlägt. Sich die Zeit zu nehmen, um zu sitzen und sich auszuruhen, hilft Abenteurern dabei, ihre Kräfte wiederzuerlangen und in Spitzenform für bevorstehende Kämpfe zu bleiben.",al={"was bewirkt ein lagerstuhl","lagerstuhl verwendung","warum einen lagerstuhl herstellen"}},{q="Wo kann man ein Lager aufschlagen?",a="Stadtbewohner sehen es ungern, wenn Reisende mitten in Siedlungen Lager errichten. Abenteurer müssen in die Wildnis hinausziehen, um ihre Lager aufzuschlagen und ihre hergestellte Ausrüstung auszuprobieren.",al={"wo kann ich ein lager aufschlagen","kann ich in städten lagern","lagerstuhl in stadt"}},{q="Was wird sonst noch benötigt, um ein Lager aufzuschlagen?",a="Ein Lager ist ohne ein loderndes Lagerfeuer nicht vollständig. Abenteurer müssen ein Feuer entfachen, bevor sie ihr Lager errichten – eine grundlegende Fertigkeit, die gewöhnlich von Kochlehrern und Köchen gelehrt wird.",al={"was brauche ich noch für ein lager","lagerfeuer benötigt","brauche ich ein feuer zum zelten"}},{q="Wo befindet sich das Dorf der Bluthufe?",a="Das Dorf der Bluthufe ist eine bedeutende Taurensiedlung in den windgepeitschten Ebenen von Mulgore und Heimat verschiedener Handwerker, darunter auch Kürschnerlehrer.",al={"wo liegt das dorf der bluthufe","standort dorf der bluthufe"}}},fp="21,361,17.406.0,28.429.0,30.248.0,34.189.0,30.204.0,28.180.0,39.180.0,35.149.0"}
P.entries["quest:97938"] = {n="Camping 101: Alchemy",s="Camping 101: Alchemy ist eine Einführungsquest, die grundlegendes Tränkebrauen mit dem Überleben in der Wildnis verbindet. Alchemisten werden zu Cyndra Kindwhisper in Dolanaar geschickt, um zu lernen, wie man einen erfrischenden Manabrunnen für seine Lagerplätze errichtet, der reisenden Zauberwirkern und Heilern lebenswichtige magische Erholung bietet.",h="Camping 101: Alchemy ist eine Einführungsquest, die grundlegendes Tränkebrauen mit dem Überleben in der...",kw={"alchemie","lager","camping 101","camping 101: alchemy","cyndra kindwhisper","dolanaar","manabrunnen","teldrassil"},ang={["faction:Alliance"]="Alchemisten der Allianz, die Abenteuer auf Teldrassil erleben, werden direkt nach Dolanaar geführt, um ihre Überlebensfähigkeiten in der Wildnis durch magische Lager-Einrichtungen zu erweitern.",["race:NightElf"]="Kräuterkundige und Alchemisten der Nachtelfen, die von Dolanaar aus agieren, verbinden natürliche Botanik mit Lagerhandwerk, um Zauberwirker in der Wildnis zu unterstützen."},sec={{t="Feldhandwerk für Alchemisten",b="Camping 101: Alchemy leitet praktizierende Alchemisten dazu an, ihre Fertigkeiten im Tränkebrauen an das Leben auf Reisen anzupassen. Anstatt Tränke lediglich in Labor-Glaswaren zu brauen, lernen Abenteurer, Feldinstallationen zu schaffen, die Reisegruppen auf ausgedehnten Reisen durch die Wildnis unterstützen."},{t="Der Manabrunnen von Dolanaar",b="Die Quest weist Abenteurer an, Cyndra Kindwhisper in Dolanaar aufzusuchen, sobald sie grundlegende Fertigkeiten in ihrem Handwerk bewiesen haben. Sie vermittelt die Technik zur Errichtung eines Manabrunnens im Lager – einer erfrischenden Quelle, die speziell darauf ausgelegt ist, manaintensiven Heilern und Zauberwirkern zu helfen, die sich weit entfernt von Tavernen und Siedlungen aufhalten."}},faq={{q="Was ist Camping 101: Alchemy?",a="Camping 101: Alchemy ist eine lehrreiche Aufgabe, die angehende Alchemisten nach Dolanaar führt. Sie lehrt Reisende, wie sie ihre Fertigkeiten im Tränkebrauen einsetzen können, um funktionale Lagereinrichtungen in der Wildnis aufzubauen.",al={"was ist camping 101 alchemy","quest camping 101 alchemy","alchemie-lager-quest"}},{q="Wer lehrt diese Camping-Fertigkeit?",a="Cyndra Kindwhisper ist eine Alchemielehrerin in der Nachtelfensiedlung Dolanaar auf Teldrassil. Sie unterweist jene Praktizierenden, die ausreichendes Geschick im Brauen und Herstellen spezialisierter Campinggegenstände bewiesen haben.",al={"wer ist cyndra kindwhisper","aufenthaltsort von cyndra kindwhisper","wo ist cyndra kindwhisper"}},{q="Was ist ein Manabrunnen?",a="Ein Manabrunnen ist eine spezialisierte Wildnis-Installation, die von Alchemisten für ihre Lagerplätze hergestellt wird. Er bietet eine erfrischende Quelle arkanaer Regeneration, die Zauberwirker und Heiler anzieht, die ihre magischen Reserven unterwegs auffüllen müssen.",al={"was bewirkt ein manabrunnen","lagergegenstand manabrunnen","geschichte des manabrunnens"}},{q="Wohin führt diese Quest?",a="Dolanaar ist ein Nachtelfendorf im Zentrum von Teldrassil, das als zentraler Knotenpunkt für junge Abenteurer und Handwerksausbilder dient, nachdem sie das Laubschattental verlassen haben.",al={"wo liegt dolanaar","wie man nach dolanaar gelangt","lage von dolanaar"}},{q="Wer profitiert von der Lagerinstallation eines Alchemisten?",a="Heiler und zauberwirkende Reisende profitieren am meisten von Manabrunnen, da die herbeigezauberten oder gebrauten Quellen lebenswichtige Erfrischung und Erholung während beschwerlicher Reisen fernab von Städten bieten.",al={"wer profitiert von manabrunnen","wer nutzt manabrunnen","manabrunnen zauberwirker"}},{q="Was ist erforderlich, bevor man das Herstellen eines Manabrunnens erlernen kann?",a="Alchemisten müssen zunächst Fertigkeit in ihren grundlegenden Brau- und Tränkekünsten nachweisen, bevor Cyndra Kindwhisper sie in der Errichtung von Camping-Einrichtungen wie dem Manabrunnen unterweist.",al={"wann kann ich den manabrunnen erlernen","voraussetzungen fuer camping 101","benoetigte fertigkeit"}}},fp="20,304,26.291.0,25.319.0,29.212.0,31.224.0,20.245.0,31.156.0,51.177.0,54.189.0"}
P.entries["quest:97942"] = {n="Camping 101: First Aid",s="Camping 101: First Aid führt Abenteurer in das Überleben in der Wildnis ein, indem es ihnen beibringt, wie man eine medizinische Feldtasche für seinen Lagerplatz herstellt. Gelehrt von Byancie in Dolanaar, betont es Selbstständigkeit und praktische Triage fernab von städtischen Lazaretten.",h="Camping 101: First Aid führt Abenteurer in das Überleben in der Wildnis ein, indem es ihnen beibringt, wie...",kw={"byancie","lagerfeuer","zelten","dolanaar","feldsanitäter","erste hilfe","verbandtasche","jäger"},ang={["class:Hunter"]="Für Jäger, die lange Zeit fern der Zivilisation Bestien nachspüren, erlaubt die Verbindung von Wildnisüberleben mit Erster Hilfe, Verletzungen zu versorgen, ohne auf Heiler in den Städten angewiesen zu sein.",["profession:Cooking"]="Das Lagerleben erfordert sowohl Nahrung als auch Wärme, weshalb eine grundlegende Kochausbildung unerlässlich ist, um zu lernen, wie man das erforderliche Lagerfeuer entfacht."},sec={{t="Feldmedizin in der Wildnis",b="Sich tief in die Wildnis vorzuwagen, birgt ständige Gefahren – von Tierbissen bis hin zu zerklüftetem Gelände. Für Waldläufer und Reisende im Feld können medizinische Vorräte nicht immer bis zur Rückkehr in die Stadt warten. Das Erlernen des Zusammenstellens einer zweckmäßigen Verbandtasche verwandelt eine einfache Rast am Wegesrand in eine funktionale Feldstation und stellt sicher, dass kleinere Schrammen unter freiem Himmel nicht tödlich enden."},{t="Unterweisungen in Dolanaar",b="Byancie, die man in den schattigen Lauben von Dolanaar antrifft, weist in der Triage erfahrene Reisende darin ein, wie man medizinische Vorräte verpackt, die für das raue Pfadfinderleben geeignet sind. Der Aufbau einer solchen Ausrüstung erfordert Rücksicht auf die örtlichen Siedlungen; Stadtbewohner dulden keine aufgeschlagenen Zelte und unordentliche Vorräte in Dorfzentren, weshalb Camper in den Wald aufbrechen müssen, bevor sie ihr Lager errichten."},{t="Der Herd des Lagers",b="Jedes funktionale Lager beginnt mit einer offenen Flamme. Bevor medizinische Taschen oder Schlafstätten abgelegt werden, müssen Abenteurer ein Lagerfeuer für Wärme und Schutz entfachen. Da das Entzünden und Unterhalten eines Feuers für das Überleben im Feld grundlegend ist, empfehlen Ausbilder, einen Koch aufzusuchen, um die Kunst des Anzündens zu meistern, bevor man versucht, ein Lager in der Wildnis zu unterhalten."}},faq={{q="Wer ist Byancie?",a="Byancie ist eine Lehrerin in der Siedlung Dolanaar auf Teldrassil. Sie weist Abenteurer, die ihr Geschick in medizinischen Fertigkeiten unter Beweis gestellt haben, darin ein, wie man spezialisierte Verbandtaschen für das Zelten in der Wildnis zusammenstellt.",al={"wer ist byancie","standort von byancie","wo ist byancie"}},{q="Was ist eine Camping-Verbandtasche?",a="Eine Verbandtasche ist ein spezialisiertes Camping-Utensil, das von in der Medizin ausgebildeten Abenteurern hergestellt wird. Wird sie an einem eingerichteten Lagerplatz platziert, bietet sie eine dedizierte Station, um Wunden zu versorgen und lebenswichtige Heilung im Feld zu gewährleisten.",al={"was ist die verbandtasche im lager","wie funktioniert die verbandtasche","camping-verbandtasche"}},{q="Wo könnt Ihr ein Lager aufschlagen?",a="Einwohner und Wachen von Siedlungen sehen es nicht gerne, wenn Reisende temporäre Lagerplätze auf städtischen Plätzen oder in Ortszentren aufschlagen. Lager müssen draußen in der offenen Wildnis abseits der Grenzen von Siedlungen errichtet werden.",al={"kann ich in der stadt zelten","warum außerhalb der stadt zelten","regeln fürs zelten"}},{q="Warum wird für ein Lager ein Lagerfeuer benötigt?",a="Ein Lagerfeuer bildet das zentrale Fundament jedes Wildnislagers und spendet Wärme, Licht sowie Sicherheit. Abenteurer erlernen das Entfachen eines einfachen Lagerfeuers üblicherweise von Kochlehrern und Köchen.",al={"warum brauche ich ein lagerfeuer","kochen lagerfeuer zelten","lagerfeueranforderung"}},{q="Warum gilt Erste Hilfe als pragmatisch für Jäger?",a="Jäger operieren gewöhnlich allein in abgelegenen Gebieten der Wildnis, weit entfernt von etablierten Heilern oder Templern. Das Verständnis von Feldtriage und der Kunst des Verbindens sichert ihre Selbstständigkeit beim Fährtenlesen oder beim Überleben von Hinterhalten.",al={"warum erste hilfe für jäger","heilung für jäger"}},{q="Wie lernt man, eine Camping-Verbandtasche herzustellen?",a="Abenteurer müssen zunächst grundlegende Fertigkeiten in der Disziplin der Ersten Hilfe nachweisen, woraufhin Byancie in Dolanaar ihnen die spezifischen Techniken beibringen kann, die zum Zusammenstellen einer Camping-Verbandtasche erforderlich sind.",al={"wie man eine verbandtasche bekommt","herstellung einer verbandtasche erlernen"}}},fp="22,250,27.356.0,19.372.0,22.350.0,15.220.0,32.222.0,28.201.0,38.191.0,50.219.0,50.196.0"}
P.entries["quest:97943"] = {n="Camping 101: Fishing",s="Camping 101: Fishing führt Angler in die Kunst des Komforts in der Wildnis ein, indem es ihnen beibringt, ein dekoratives Fischglas für ihr Lager herzustellen. Gewiesen an Astaia in Darnassus erfahren erfahrene Angler, dass kleine Freuden den Geist und die Kampfkraft eines Abenteurers draußen in der Wildnis stärken können.",h="Camping 101: Fishing führt Angler in die Kunst des Komforts in der Wildnis ein, indem es ihnen beibringt, ein...",kw={"astaia","lagerfeuer","camping","camping 101: fishing","lagerplatz","darnassus","fischglas","angeln"},ang={["faction:Alliance"]="Astaia weilt in Darnassus, was die Hauptstadt der Nachtelfen zu einer zentralen Anlaufstelle für Angler der Allianz macht, die ihr Lagerhandwerk erweitern möchten.",["profession:Cooking"]="Lager erfordern ein ordentliches Lagerfeuer zu ihrer Errichtung, was eine grundlegende Ausbildung in der Kochkunst zu einem unverzichtbaren Begleiter für den Unterschlupf eines Anglers im Freien macht."},sec={{t="Komfort am Lagerplatz",b="Angler, die durch Kalimdor reisen, stellen oft fest, dass ihre ruhigen Stunden am Ufer einem höheren Zweck dienen können. In Darnassus zeigt die Handwerkerin Astaia erfahrenen Anglern, wie sie ihre Fänge und Fertigkeiten in Lagereinrichtungen verwandeln können, insbesondere durch die Anfertigung eines Fischglases zur Präsentation im Lager. Dieses dekorative Stück verleiht wegmüden Reisenden einen willkommenen Hauch von Gemütlichkeit und Heiterkeit."},{t="Notwendigkeiten der Wildnis",b="Die Errichtung eines ordentlichen Zufluchtsorts in der Wildnis erfordert mehr als nur Angelzeug. Lager können nicht in belebten Stadtzentren oder städtischen Bezirken aufgeschlagen werden, sodass Abenteurer unter den freien Himmel hinausziehen müssen. Zudem erfordert jedes Lager ein wärmendes Lagerfeuer als Grundlage, weshalb Abenteurer örtliche Kochkunstlehrer aufsuchen sollten, um das grundlegende Entfachen von Feuern zu meistern, bevor sie sich für die Nacht niederlassen."}},faq={{q="Wer bringt Euch bei, wie man Campinggegenstände fürs Angeln herstellt?",a="Astaia befindet sich in Darnassus. Sobald ein Angler eine angemessene Fertigkeit im Angeln bewiesen hat, bringt Astaia ihm bei, wie man ein dekoratives Fischglas für das eigene Lager herstellt.",al={"wer lehrt camping angeln","wo ist astaia","fischglas lehrer"}},{q="Welchem Zweck dient ein Fischglas im Lager?",a="Das Fischglas dient als Lagereinrichtung, die rastenden Abenteurern Behaglichkeit und Freude bringen soll. Ein glücklicher, wohlbehaltener Camper kämpft mit neuem Elan, was Expeditionen in freier Natur direkt zugutekommt.",al={"was bewirkt fischglas","lager fischglas nutzen","fischglas lagereinrichtung"}},{q="Könnt Ihr ein Lager in Darnassus oder anderen Städten aufschlagen?",a="Lager können nicht im Herzen von Siedlungen oder Ortskernen aufgeschlagen werden. Um ein Lager zu errichten und Gegenstände wie ein Fischglas aufzustellen, müssen Reisende in die Wildnis hinausziehen.",al={"kann man in darnassus campen","wo lager aufschlagen","lager in städten"}},{q="Was ist erforderlich, bevor man ein Lager aufschlägt?",a="Kein Lagerplatz ist ohne ein einfaches Lagerfeuer vollständig. Reisenden wird empfohlen, einen Kochkunstlehrer aufzusuchen, um zu lernen, wie man ein Feuer entfacht, bevor sie ihr Wildnislager aufschlagen.",al={"was braucht man für ein lager","wie camp beginnen","lagerfeuer erforderlich"}},{q="Benötigt Ihr die Fertigkeit Angeln, um zu lernen, wie man ein Fischglas herstellt?",a="Um das Handwerk von Astaia zu erlernen, muss ein Abenteurer zunächst Fertigkeit im Angelberuf nachweisen.",al={"angelfertigkeit camping","wann fischglas lernen"}},{q="Warum schlagen Abenteurer Lager in der Wildnis auf?",a="Das Aufschlagen eines Lagers bietet Reisenden in freier Natur einen Ort der Rast und moralfördernde Annehmlichkeiten wie ein hergestelltes Fischglas, wodurch sichergestellt wird, dass Abenteurer bei ihren Unternehmungen in der Wildnis ausgeruht und handlungsfähig bleiben.",al={"warum lager aufschlagen wow forever","camping vorteile"}}},fp="20,296,23.391.0,22.390.0,55.172.0,44.193.0,55.165.0,42.174.0,60.107.0,44.191.0"}
P.entries["quest:97944"] = {n="Camping 101: Herbalism",s="Camping 101: Herbalism führt Sammler an die praktischen Überlebensanwendungen ihres Handwerks heran. Durch einen Besuch bei Malorne Bladeleaf in Dolanaar lernen erfahrene Kräuterkundige, beruhigende Räucherkerzen herzustellen, die Heiler und Zauberwirker am Lagerfeuer stärken.",h="Camping 101: Herbalism führt Sammler an die praktischen Überlebensanwendungen ihres Handwerks heran.",kw={"camping","camping 101: herbalism","dolanaar","kräuterkunde","räucherkerze","malorne bladeleaf","teldrassil"},ang={["faction:Alliance"]="Kräuterkundige der Allianz, die rund um Teldrassil tätig sind, werden nach Dolanaar geschickt, um von den dortigen Nachtelfen-Praktizierenden spezialisierte Techniken des Feldhandwerks zu erlernen.",["profession:Herbalism"]="Kräuterkundige entdecken, dass das Sammeln von Flora über die Alchemie hinaus dem praktischen Überleben in der Wildnis dient, indem es pflanzliche Rohstoffe liefert, um Lagerutensilien wie Räucherkerzen herzustellen.",["race:NightElf"]="Nachtelfen haben die stimmungsvollen und erholsamen Eigenschaften von Kräutern aus der Natur seit langem verstanden und teilen diese Traditionen in Siedlungen wie Dolanaar."},sec={{t="Mehr als nur Blumenpflücken",b="Kräuterkunde ist weit mehr als das bloße Durchstreifen der Wiesen, um Blüten zu pflücken. Während Sammler ihre Funde oft verkaufen oder Alchemisten beliefern, wissen erfahrene Wildnisreisende, dass wilde Flora direkt zu wertvoller Campingausrüstung verarbeitet werden kann. Das Erlernen der Zubereitung gesammelter Pflanzen für Überlebenszwecke stellt sicher, dass ein gesammelter Ertrag ausgedehnte Reisen im Feld direkt unterstützt."},{t="Die beruhigende Flamme von Dolanaar",b="In der Siedlung Dolanaar bringt ein Ausbilder namens Malorne Bladeleaf geübten Kräuterkundigen bei, wie man eine Räucherkerze herstellt. Diese aromatischen Kerzen schaffen eine konzentrierte, heitere Zuflucht um ein Lagerfeuer und bieten eine belebende Präsenz, die Heiler und Zauberwirker schätzen, wenn sie zwischen Gefahren ihre magischen Energien wiederherstellen."}},faq={{q="Was ist der Zweck dieser Quest?",a="Camping 101: Herbalism ist eine einführende Berufsaufgabe, die erfahrene Sammler dazu anleitet, spezialisiertes Wildnishandwerk zu erlernen. Sie leitet Kräuterkundige an zu erfahren, wie man Lagergüter aus der im Feld gesammelten Flora herstellt.",al={"was ist camping 101 herbalism","camping kräuterkunde quest"}},{q="Was bewirkt eine Räucherkerze für ein Lager?",a="Eine Räucherkerze sorgt für eine belebende Atmosphäre an einem Lagerplatz, hebt die Stimmung und bietet eine beruhigende Stärkung, auf die sich Zauberwirker und Heiler verlassen, um ihren magischen Fokus aufrechtzuerhalten.",al={"was bewirkt räucherkerze","räucherkerze vorteil"}},{q="Wer ist Malorne Bladeleaf?",a="Malorne Bladeleaf ist ein in Dolanaar ansässiger Ausbilder, der das Wissen zur Herstellung von Campingbedarf für Kräuterkundige besitzt und geübte Sammler gezielt in der Anfertigung von Räucherkerzen unterweist.",al={"wer lehrt räucherkerze","wer ist malorne bladeleaf","bladeleaf dolanaar"}},{q="Wohin führt Euch diese Quest?",a="Dolanaar ist eine Siedlung der Nachtelfen auf der Insel Teldrassil, die als regionaler Knotenpunkt für Reisende, Lehrer und Waldhandwerker dient.",al={"wo ist dolanaar","dolanaar standort"}},{q="Warum sind Räucherkerzen für Magiewirker nützlich?",a="Heiler und Zauberwirker profitieren am unmittelbarsten von der ruhigen, konzentrierten Umgebung, die durch eine Räucherkerze geschaffen wird, was dabei hilft, ihren Geist und ihre magische Widerstandskraft während Expeditionen in der Wildnis wieder aufzufüllen.",al={"wer profitiert von räucherkerze","ist räucherkerze für zauberwirker"}},{q="Was ist erforderlich, bevor Malorne Bladeleaf Euch unterrichtet?",a="Sammler müssen ausreichend praktische Fertigkeit und Kenntnis in der Kräuterkunde nachweisen, bevor Malorne Bladeleaf bereit ist, das Handwerk der Herstellung von Lagerutensilien weiterzugeben.",al={"wann kann ich räucherkerze lernen","kräuterkunde fertigkeitsanforderung camping"}}},fp="22,259,25.388.0,30.344.0,34.233.0,42.187.0,25.197.0,31.146.0,46.198.0,57.167.0"}
P.entries["quest:97946"] = {n="Camping 101: Leatherworking",s="Camping 101: Leatherworking führt geschickte Handwerker auf Teldrassil in die Kunst ein, Notunterkünfte für das Überleben im Freien herzustellen. Indem Lederverarbeiter Nadyia Maneweaver entlang der Straße zwischen Dolanaar und Darnassus aufsuchen, lernen sie, widerstandsfähige Zelte anzufertigen, die Reisende auf ihren Reisen durch die Wildnis vor rauem Wetter schützen.",h="Camping 101: Leatherworking führt geschickte Handwerker auf Teldrassil in die Kunst ein, Notunterkünfte für...",kw={"lagerfeuer","campen","darnassus","dolanaar","lederverarbeitung","nadyia maneweaver","zelt","wildnis"},ang={["class:Rogue"]="Schurken, die durch die Wildnis reisen, verlassen sich auf gute Erholung und Schutz, um scharf zu bleiben, was ein persönliches Lederzelt zu einem unschätzbaren Überlebenswerkzeug macht.",["profession:Cooking"]="Das Errichten eines richtigen Lagerplatzes erfordert ein wärmendes Lagerfeuer, eine wesentliche Fertigkeit, die von kulinarischen Ausbildern im ganzen Land gelehrt wird."},sec={{t="Unterschlupf in der Wildnis",b="Für Abenteurer, die durch die wilden Weiten von Kalimdor reisen, birgt das Rasten unter freiem Himmel harte Herausforderungen, von plötzlichen Regengüssen bis hin zu sengender Hitze. Geschickten Lederverarbeitern wird beigebracht, aus Fellen und Pelzen strapazierfähige Unterkünfte herzustellen, sodass Reisende eine zuverlässige Zuflucht errichten können, wohin auch immer ihre Reisen sie führen. Durch das Herstellen eines persönlichen Lagerzelts stellen Wanderer sicher, dass sie sich die nötige Ruhe verschaffen, um ihre Reflexe scharf und ihre Sinne wach zu halten, weit abseits der Sicherheit örtlicher Gasthäuser."},{t="Die Straße von Dolanaar",b="Entlang der Waldstraße, die sich zwischen der Siedlung Dolanaar und den Ästen von Darnassus schlängelt, bietet Nadyia Maneweaver geübten Lederverarbeitern ihre Anleitung an. Sie vermittelt die Kunst, robuste Zelte zu nähen, die für das Leben auf Reisen geeignet sind. Ein Zelt allein macht jedoch noch kein funktionstüchtiges Lager aus; Reisende müssen auch wissen, wie man ein Lagerfeuer entfacht – eine grundlegende Überlebenskunst, die von Köchen gelehrt wird – und müssen daran denken, ihre Unterkünfte in der offenen Wildnis aufzuschlagen, anstatt die Straßen von Städten zu verstellen."}},faq={{q="Wer lehrt diese Campingfertigkeit?",a="Die Quest weist angehende Lederverarbeiter an, mit Nadyia Maneweaver zu sprechen, die sich an der Straße befindet, die von Dolanaar in Richtung Darnassus auf Teldrassil verläuft.",al={"wer gibt camping 101 lederverarbeitung","wer lehrt camping 101","nadyia maneweaver"}},{q="Was lernen Lederverarbeiter aus dieser Quest?",a="Sie leitet Lederverarbeiter darin an, wie sie ihr ganz eigenes Campingzelt herstellen können, das dazu gedacht ist, Reisende an heißen Tagen kühl und bei Regenwetter draußen in der Wildnis trocken zu halten.",al={"was lehrt camping 101","zeltrezept","was lerne ich aus camping 101"}},{q="Wo könnt Ihr ein Lagerzelt aufschlagen?",a="Zelte können nicht innerhalb von Siedlungen oder Stadtzentren aufgeschlagen werden, da Stadtbewohner Lager inmitten der Stadt nicht schätzen. Reisende müssen sich nach draußen in die offene Wildnis wagen, um ihren Lagerplatz zu errichten.",al={"wo kann man ein zelt aufschlagen","kann man ein zelt in der stadt aufschlagen","campen in städten"}},{q="Was wird sonst noch benötigt, um ein Lager aufzuschlagen?",a="Jedes richtige Lager erfordert neben dem Zelt ein brennendes Lagerfeuer, bevor es errichtet werden kann. Die einfache Lagerfeuerherstellung wird üblicherweise von Kochlehrern erlernt.",al={"was wird für ein lager benötigt","lagerfeuervoraussetzung","wird ein lagerfeuer fürs zelt gebraucht"}},{q="Warum ist ein Zelt für Reisende nützlich?",a="Ein zuverlässiges Zelt bietet Schutz vor den Elementen und stellt sicher, dass Abenteurer ausreichend Erholung finden, um auf Reisen fernab von Gasthäusern wachsam und scharf zu bleiben.",al={"warum ein zelt bauen","zelt erholungsvorteil","warum campen"}},{q="Wo befindet sich Nadyia Maneweaver?",a="Nadyia Maneweaver ist an der Hauptstraße stationiert, die vom Dorf Dolanaar in Richtung der Nachtelfenhauptstadt Darnassus führt.",al={"wo ist nadyia maneweaver","nadyia aufenthaltsort","lehrer straße nach darnassus"}}},fp="27,320,25.499.0,22.491.0,31.156.0,45.173.0,32.201.0,39.160.0,42.153.0,35.140.0"}
P.entries["quest:97948"] = {n="Camping 101: Mining",s="Camping 101: Mining ist eine Einführungsquest, die Bergleute zu Kurdram Stonehammer in Auberdine führt. Indem sie ihre Fertigkeit im Beruf unter Beweis stellen, können Bergleute lernen, einen Lager-Magnetstein herzustellen, der die Kampfkraft von Verbündeten stärkt, die an einem Lagerfeuer rasten.",h="Camping 101: Mining ist eine Einführungsquest, die Bergleute zu Kurdram Stonehammer in Auberdine führt.",kw={"auberdine","lagerhandwerk","lagerfeuer","camping 101: mining","dunkelküste","kurdram stonehammer","magnetstein","bergbau"},ang={["faction:Alliance"]="Kurdram Stonehammer bietet seine Unterweisung von Auberdine an den Gestaden der Dunkelküste aus an, wodurch dieses Lagerhandwerk für Reisende der Allianz auf der Durchreise durch das nördliche Kalimdor leicht zugänglich ist.",["profession:Mining"]="Bergleute können die Mineralkunst nutzen, um Reisenden auf der Straße zu helfen, indem sie rohen Stein in einen funktionalen Lager-Magnetstein verwandeln, der Frontkämpfer stärkt."},sec={{t="Die praktische Kunst von Erde und Stein",b="Bergbau ist raue, ehrliche Mühe, doch sein Nutzen reicht weit über das Verhütten von Barren und das Hämmern von Rüstungen hinaus. Erfahrene Prospektoren können rohe Erde und magnetisches Erz zu spezialisierter Campingausrüstung formen, was es Reisenden ermöglicht, gut befestigte Herde in der Wildnis zu errichten. Camping 101: Mining führt Bergleute an diese praktische Anwendung ihres Handwerks heran."},{t="Ein Mentor in Auberdine",b="Die Quest weist vielversprechende Bergleute an, Kurdram Stonehammer in Auberdine aufzusuchen, dem geschäftigen Küstenzufluchtsort an der Dunkelküste. Sobald ein Bergmann seine Hingabe und sein Können unter Beweis stellt, lehrt Kurdram die Methode zum Bau eines Lager-Magnetsteins. Neben einem Feuer platziert, strahlt der Stein eine stärkende Präsenz aus, die die Kampfkraft kriegerischer Gefährten steigert, die sich in der Nähe versammelt haben."}},faq={{q="Was ist Camping 101: Mining?",a="Camping 101: Mining weist Bergleute an, Kurdram Stonehammer in der Hafenstadt Auberdine zu finden. Sobald Ihr Euer Können im Bergbau unter Beweis gestellt habt, lehrt er Euch, wie man einen besonderen Magnetstein konstruiert, um Lagerplätze aufzuwerten.",al={"was ist diese quest","camping 101 mining ziel","was tun bei camping bergbau"}},{q="Wer ist Kurdram Stonehammer?",a="Kurdram Stonehammer ist ein erfahrener Handwerker mit Sitz in Auberdine an der Küste der Dunkelküste. Er unterweist qualifizierte Bergleute darin, nützliche Campinggegenstände herzustellen, insbesondere Magnetsteine.",al={"wer ist kurdram stonehammer","auberdine bergbaulehrer","kurdram stonehammer standort"}},{q="Was ist ein Lager-Magnetstein?",a="Ein Magnetstein ist ein von Bergleuten für ein Lager hergestellter Gegenstand. Wird er neben einem Lagerfeuer errichtet, verleiht er eine belebende Präsenz, die physischen Kämpfern zusätzliche Schlagkraft und Kampffertigkeit gewährt.",al={"was bewirkt der magnetstein","lager-magnetstein effekt","camping oomph stärkungszauber"}},{q="Wo findet diese Quest statt?",a="Auberdine ist eine Küstenhafen-Siedlung an der Dunkelküste, die als primärer Hafen der Allianz und Kreuzungspunkt im nördlichen Kalimdor dient. Kurdram Stonehammer verweilt dort, um angehende Bergleute im Lagerhandwerk zu unterweisen.",al={"wo ist auberdine","auberdine lage","wie man nach auberdine gelangt"}},{q="Wer profitiert von einem Lager-Magnetstein?",a="Der Magnetstein wird besonders von Nahkämpfern geschätzt, die im Nahkampf Schwerter und Waffen schwingen, da seine resonierende Kraft kampffokussierten Reisenden gesteigerte Vitalität verleiht, während sie um das Feuer rasten.",al={"wer profitiert vom magnetstein","ist der magnetstein gut für krieger","ziel des lager-magnetstein-stärkungszaubers"}},{q="Wann kann man lernen, den Magnetstein herzustellen?",a="Ihr müsst ausreichende Fertigkeit im Bergbauhandwerk vorweisen, bevor Kurdram Stonehammer die Geheimnisse der Herstellung eines Magnetsteins für Euer Lager mit Euch teilen wird.",al={"wann kann man magnetstein erlernen","bergbaufertigkeit für lager-magnetstein","fertigkeitsanforderung"}}},fp="19,259,36.352.0,21.368.0,28.217.0,27.188.0,25.183.0,33.202.0,35.211.0,42.145.0"}
P.entries["quest:97949"] = {n="Camping 101: Skinning",s="Camping 101: Skinning unterweist Wildnisreisende darin, wie sie ihren eigenen tragbaren Lagerstuhl herstellen. Es betont die Grundlagen des Überlebens in der Wildnis und erinnert Abenteurer daran, dass ein ordentlicher Lagerplatz erfordert, sich von der Stadt zu entfernen und ein Lagerfeuer zu entfachen.",h="Camping 101: Skinning unterweist Wildnisreisende darin, wie sie ihren eigenen tragbaren Lagerstuhl herstellen.",kw={"lagerstuhl","lagerfeuer","camping 101","camping 101: skinning","kochen","kürschnerei","wildnis"},ang={["profession:Cooking"]="Campern wird geraten, grundlegendes Kochen von einem Kochlehrer zu lernen, da das Wissen, wie man ein einfaches Lagerfeuer errichtet, unerlässlich ist, um ein ordentliches Lager in der Wildnis aufzuschlagen."},sec={{t="Annehmlichkeiten des Pfades",b="Camping 101: Skinning führt Naturfreunde und Kürschner in das Handwerk des Überlebens in der Wildnis ein. Indem sie erbeutete Bälge und Materialien praktisch nutzen, lernen Reisende, einen tragbaren Lagerstuhl für ihre Reisen zu bauen. Anstatt belebte Stadtkerne zu überfüllen, wo Einheimische Einwände gegen aufgeschlagene Lager haben, wird von Abenteurern erwartet, dass sie ihr Handwerk in die offene Wildnis von Azeroth hinaustragen."},{t="Das unverzichtbare Lagerfeuer",b="Kein Lagerplatz in der Wildnis ist ohne ein wärmendes Lagerfeuer funktionsfähig. Die Errichtung eines Lagers erfordert, dass zuerst ein Feuer gelegt wird, das Wärme und Schutz vor den Elementen bietet. Angehende Überlebenskünstler, die sich noch keine grundlegenden Kochfertigkeiten angeeignet haben, werden dazu ermutigt, einen Kochlehrer aufzusuchen, der sie im grundlegenden Handwerk des Entfachens eines Feuers überall im Feld unterweisen kann."}},faq={{q="Was lernt Ihr aus Camping 101: Skinning?",a="Der Abschluss dieser Aufgabe lehrt Euch, wie Ihr Euren eigenen Lagerstuhl fertigt – eine unverzichtbare Annehmlichkeit, um in der Wildnis zu rasten.",al={"was erhalte ich","was bringt camping 101","lagerstuhl herstellen"}},{q="Könnt Ihr in der Stadt ein Lager aufschlagen?",a="Stadtbewohner sehen es im Allgemeinen nicht gerne, wenn Reisende auf Marktplätzen oder in Stadtstraßen ihr Lager aufschlagen. Ihr müsst in die Wildnis hinausreisen, um Euer Lager ordnungsgemäß zu errichten.",al={"kann man in der stadt campen","zelt in sturmwind aufschlagen","camping in städten"}},{q="Benötigt Ihr ein Lagerfeuer, um das Lager aufzuschlagen?",a="Ein ordentlicher Lagerplatz erfordert ein brennendes Lagerfeuer, bevor er errichtet werden kann. Grundlegende Techniken zum Entzünden eines Feuers können bei den meisten Kochlehrern in ganz Azeroth erlernt werden.",al={"feuer für lager benötigt","wie man ein lagerfeuer macht","feuer für lagerstuhl"}},{q="Wo könnt Ihr lernen, wie man ein Lagerfeuer macht?",a="Die meisten Kochlehrer können Euch die Grundlagen der Zubereitung von Nahrung beibringen, wozu auch gehört, wie man mit einfachem Feuerstein und Holz ein einfaches Lagerfeuer entfacht.",al={"wer lehrt lagerfeuer","kochlehrer für kochfeuer","wo man kochfeuer lernt"}},{q="Warum müsst Ihr in die Wildnis aufbrechen, um ein Lager aufzuschlagen?",a="Die Wildnis bietet den offenen Raum, der erforderlich ist, um ein Lager aufzuschlagen, ohne die Stadtbewohner zu stören oder örtliche Straßen und Siedlungen zu blockieren.",al={"warum wildnis nötig ist","wo man den lagerstuhl nutzen kann","wo man das lager aufschlägt"}},{q="Welcher Zusammenhang besteht zwischen Kürschnerei und der Herstellung eines Lagerstuhls?",a="Kürschner verarbeiten Leder und Bälge, die von Wildtieren erbeutet wurden – Materialien, die sich dafür eignen, zu tragbaren Sitzgelegenheiten für den Außenbereich wie einem Lagerstuhl aufgespannt und vernäht zu werden.",al={"zusammenhang kürschnerei und camping","warum kürschnerei für stuhl","kürschnerei lagerstuhl"}}},fp="21,255,21.388.0,22.368.0,45.124.0,30.160.0,36.164.0,43.163.0,53.137.0,48.158.0"}
P.entries["quest:97955"] = {n="Camping 101: First Aid",s="Camping 101: First Aid weist Abenteurer mit medizinischer Ausbildung an, Nurse Neela in Brill aufzusuchen. Indem sie lernen, eine Verbandtasche für ihre Lagerplätze herzustellen, können Reisende lebensrettende Behandlung und Erholung bieten, während sie tief in der Wildnis überleben.",h="Camping 101: First Aid weist Abenteurer mit medizinischer Ausbildung an, Nurse Neela in Brill aufzusuchen.",kw={"brill","lagerfeuer","camping","camping 101","erste hilfe","verbandtasche","nurse neela","tirisfal"},ang={["faction:Horde"]="Nurse Neela wirkt in der Siedlung Brill der Verlassenen in Tirisfal, was diese Unterweisung zu einer wichtigen lokalen Anlaufstelle für Abenteurer der Horde macht.",["profession:Cooking"]="Kochlehrer lehren die Kunst, ein einfaches Lagerfeuer zu entfachen, das erforderlich ist, um einen Lagerplatz in der Wildnis zu errichten, bevor medizinische Annehmlichkeiten hinzugefügt werden.",["race:Undead"]="Von Brill aus hilft Nurse Neela den Verlassenen und ihren Verbündeten dabei, medizinische Fertigkeiten für das Überleben in den verheerten Landschaften von Lordaeron anzupassen."},sec={{t="Medizin im Feld",b="Sich über befestigte Siedlungen hinauszuwagen birgt ständige körperliche Gefahren, von feindseligen Bestien bis hin zu gegnerischen Fraktionen. Für reisende Kundige der Ersten Hilfe ermöglicht das Erlernen des Zusammenbaus einer speziellen Verbandtasche, dass ein gewöhnlicher Rastplatz in der Wildnis als mobile Feldklinik dient, die fernab ziviler Infrastruktur Wunden versorgt und Lebenskraft wiederherstellt."},{t="Unterweisung in Brill",b="In der Stadt Brill der Verlassenen erteilt Nurse Neela Unterweisung darin, wie man grundlegendes medizinisches Fachwissen in praktische Lagerausrüstung umsetzt. Sobald ein Reisender ausreichendes Geschick im Verbinden und Behandeln nachweist, teilt sie die Techniken, die für den Bau einer tragbaren Ausrüstung erforderlich sind. Das Errichten einer solchen Ausrüstung erfordert einen geeigneten Platz in der Wildnis rund um ein einfaches Lagerfeuer, dessen Bau gewöhnliche Kochlehrer Reisenden beibringen können."}},faq={{q="Wer ist Nurse Neela?",a="Nurse Neela ist eine Heilkundige in der Siedlung Brill der Verlassenen in Tirisfal. Sie unterweist geübte Kundige der Ersten Hilfe darin, wie man Verbandtaschen herstellt, die für Feldlagerplätze gedacht sind.",al={"wer ist nurse neela","wo ist nurse neela","nurse neela standort"}},{q="Was bewirkt eine Verbandtasche in einem Lager?",a="Eine Verbandtasche ist ein spezielles Campingzubehör, das von Kundigen der Ersten Hilfe hergestellt wird. Wenn sie an einem Lagerplatz in der Wildnis aufgestellt wird, bietet sie grundlegende Heilungsressourcen zur Behandlung von Verletzungen, die während des Abenteuers erlitten wurden.",al={"was ist eine verbandtasche","zweck der verbandtasche","lager-verbandtasche"}},{q="Warum benötigt Ihr ein Lagerfeuer, um ein Lager aufzuschlagen?",a="Ein Lagerfeuer ist das Fundament jedes Lagers in der Wildnis und wird benötigt, bevor zusätzliche Annehmlichkeiten wie Verbandtaschen aufgestellt werden können. Der Bau einfacher Lagerfeuer wird üblicherweise von Kochlehrern und Köchen gelehrt.",al={"warum ein lagerfeuer nötig ist","wie man ein lagerfeuer macht","kochen lagerfeuer lager"}},{q="Könnt Ihr in einer Stadt ein Lager aufschlagen?",a="Stadtbewohner und örtliche Behörden haben im Allgemeinen etwas dagegen, wenn Reisende mitten auf den Straßen der Stadt Zelte aufschlagen und Feuer entfachen. Lagerplätze müssen draußen in der offenen Wildnis errichtet werden.",al={"kann man in der stadt lagern","camping in brill","warum in der wildnis lagern"}},{q="Wer lehrt, wie man die Verbandtasche herstellt?",a="Nurse Neela in Brill lehrt berechtigte Abenteurer, wie man die Tasche herstellt, sobald sie angemessene Fertigkeit im Beruf der Ersten Hilfe vorweisen.",al={"wer lehrt camping-erste-hilfe","lehrer für camping-erste-hilfe","lehrer für verbandtaschen"}},{q="Was ist das Ziel von Camping 101: First Aid?",a="Camping 101: First Aid ist eine Einführungsaufgabe, die angehende Mediziner zu Nurse Neela in Brill führt. Sie lehrt Abenteurer, wie sie ihre feldmedizinischen Fähigkeiten einsetzen, um medizinische Vorräte für Lager im Freien herzustellen.",al={"was ist camping 101 first aid","camping 101 quest"}}},fp="22,261,21.354.0,20.426.0,19.208.0,39.214.0,42.204.0,36.189.0,42.142.0,43.217.0"}
P.entries["quest:97957"] = {n="Grundlagen des Zeltens: Kräuterkunde",s="Grundlagen des Zeltens: Kräuterkunde führt angehende Kräuterkundige zu örtlichen Berufslehrern in ganz Azeroth, wie etwa Faruza in Brill, um das Handwerk der Räucherkerzen zu meistern. Diese aromatischen Schöpfungen bieten Zauberwirkenden, die in Lagern in der Wildnis rasten, lebenswichtige Erholung.",h="Grundlagen des Zeltens: Kräuterkunde führt angehende Kräuterkundige zu örtlichen Berufslehrern in ganz...",kw={"brill","zelten","eleanor shackleton","faruza","kräuterkunde","räucherkerze","tirisfal"},ang={["class:Mage"]="Zauberwirkende schätzen Kräuterkundige, die Räucherkerzen herstellen, da ihr beruhigender Rauch fernab der Annehmlichkeiten einer Taverne hilft, Konzentration und Geist wiederherzustellen.",["profession:Herbalism"]="Statt bloß Tränke zu brauen oder Halme zu verkaufen, können Kräuterkundige abenteuerlustige Gruppen direkt unterstützen, indem sie duftende Räucherkerzen für Lagerfeuer anfertigen.",["race:Undead"]="Verlassene Reisende, die von Todesend und Brill aus operieren, lernen von Faruza, wie man aus Tirisfals verwelkter Vegetation praktische Feldhandwerkskunst schafft."},sec={{t="Flora für das Lager",b="Während Kräuterkunde gemeinhin als Grundlage der Alchemie gilt, beruht das praktische Überleben in der Wildnis ebenso sehr auf gesammelten Wurzeln und Blüten. Erfahrene Reisende verweisen aufstrebende Sammler an regionale Meisterkräuterkundige, um zu lernen, wie man Räucherkerzen herstellt. In Tirisfal schickt Eleanor Shackleton vielversprechende Sammler zu Faruza in Brill, sobald sie grundlegende Fertigkeiten vorweisen können."},{t="Nahrung für den Geist",b="Das Leben auf Reisen zehrt schwer an den geistigen Kräften von Zauberwirkenden und Spiritualisten. Räucherkerzen verströmen erholsame Düfte, die das Gemüt aufheitern und erschöpfte Geister beruhigen sollen. Indem Sammler getrocknete Pflanzen in Kerzen einarbeiten, leisten sie den Heilern und Magiern, deren magische Reserven auf langen Reisen schwinden, entscheidende Hilfe."}},faq={{q="Was ist der Zweck dieser Quest?",a="Die Quest weist Kräuterkundige an, ein grundlegendes Maß an Fertigkeit zu erlangen, damit sie von einem Kräuterkundelehrer lernen können, wie man Räucherkerzen herstellt. Diese Kerzen dienen dazu, Zauberwirkende während der Rast in der Wildnis zu stärken und zu unterstützen.",al={"warum zelten kräuterkunde machen","was bringt grundlagen des zeltens","grundlagen des zeltens kräuterkunde ziel"}},{q="Wer bietet diese Quest in Tirisfal an?",a="Eleanor Shackleton bietet Kräuterkundigen in Tirisfal diese Führung an und verweist sie an Faruza in der nahegelegenen Siedlung Brill.",al={"wer gibt grundlagen des zeltens kräuterkunde tirisfal","eleanor shackleton quest"}},{q="Was bewirkt eine Räucherkerze?",a="Räucherkerzen verleihen einem Lagerplatz wohltuende Umgebungseffekte, heben die Stimmung und unterstützen Heiler sowie Magiewirker, die bei der Rast im Feld ihren geistigen Fokus wiedererlangen müssen.",al={"räucherkerze effekt","wofür sind räucherkerzen"}},{q="Wer lehrt das Rezept für die Räucherkerze?",a="Örtliche Kräuterkundelehrer unterweisen Abenteurer, sobald sie die Voraussetzungen erfüllen. In Tirisfal übernimmt Faruza in Brill die Ausbildung, während in anderen Städten und Siedlungen Lehrer wie Jandi in Orgrimmar, Reyna Stonebranch in Eisenschmiede und Malorne Bladeleaf in Dolanaar zur Verfügung stehen.",al={"wer lehrt zelten kräuterkunde","wo abgeben grundlagen des zeltens kräuterkunde"}},{q="Können Mitglieder anderer Fraktionen und Völker diese Quest annehmen?",a="Ja. Während Eleanor Shackleton und Faruza für Reisende in Tirisfal zuständig sind, bieten andere Questgeber und Lehrer Kräuterkundigen in ganz Kalimdor und den Östlichen Königreichen dieselbe Unterweisung.",al={"ist grundlagen des zeltens nur huld","allianz grundlagen des zeltens kräuterkunde"}},{q="Welche Fertigkeitsstufe ist erforderlich, um die Ausbildung abzuschließen?",a="Kräuterkundige müssen echtes Können in ihrem Handwerk beweisen und eine Kräuterkundefähigkeit von zwanzig erreichen, bevor der Lehrer ihnen das Kerzenrezept beibringt.",al={"wie viel kräuterkunde benötigt","grundlagen des zeltens fertigkeitsstufe"}}},fp="22,259,18.400.0,23.318.0,34.223.0,41.136.0,31.176.0,38.256.0,56.196.0,58.140.0"}
P.entries["quest:97960"] = {n="Grundlagen des Zeltens: Kürschnerei",s="Grundlagen des Zeltens: Kürschnerei ist eine einführende Wildnisanweisung für unerfahrene Sammler in Tirisfal und ganz Azeroth. Sie weist Kürschner, die ihr Handwerk geübt haben, an regionale Handwerker weiter, um zu lernen, wie man aus erbeuteten Häuten einen langlebigen Campingstuhl herstellt.",h="Grundlagen des Zeltens: Kürschnerei ist eine einführende Wildnisanweisung für unerfahrene Sammler in Tirisfal...",kw={"brill","campingstuhl","zelten","eleanor shackleton","rand rhobart","kürschnerei","tirisfal","unterstadt"},ang={["faction:Horde"]="Jäger und Sammler der Horde verwerten jeden Rest einer erlegten Bestie, damit auf den unbarmherzigen Pfaden nichts verschwendet wird.",["race:Undead"]="Selbst die Verlassenen, die von sterblicher Erschöpfung befreit sind, ziehen praktischen Nutzen daraus, funktionale Feldlager instand zu halten, während sie die verseuchten Bestien von Tirisfal jagen."},sec={{t="Komfort in der Wildnis",b="Das Überleben in der Wildnis erfordert mehr als eine scharfe Klinge; man muss wissen, wie man seine Kräfte zwischen den Prüfungen einteilt. Abenteurer wie Eleanor Shackleton betonen, dass das Erbeuten von Tierpelzen mehr als nur reine Handelswaren liefert. Durch die Entwicklung grundlegender Fertigkeiten im Feld können Kürschner aus behandelten Fellen nützliche Bequemlichkeiten fürs Lager wie etwa Stühle herstellen, die es müden Wanderern ermöglichen, sich vor der nächsten gefährlichen Begegnung ordentlich auszuruhen und zu erholen."},{t="Das Handwerk meistern",b="In Tirisfal werden junge Kürschner der Verlassenen, die eine erste Grundfertigkeit erlangt haben, an Rand Rhobart verwiesen, der seinem Gewerbe entlang der Straße zwischen Brill und den Ruinen der Hauptstadt von Unterstadt nachgeht. Rhobart vermittelt praktische Methoden, um aus grobem Leder funktionale Sitzgelegenheiten fürs Feldlager herzustellen – eine Kunst, die von Kürschnermeistern in den gesamten Gebieten von Horde und Allianz gleichermaßen gelehrt wird."}},faq={{q="Was ist der Zweck dieser Quest?",a="Die Quest weist unerfahrene Kürschner an, einen erfahrenen Handwerkslehrer aufzusuchen, der ihnen beibringen kann, wie man aus erbeuteten Tierpelzen einen Campingstuhl baut.",al={"was bringt grundlagen des zeltens kürschnerei","warum grundlagen des zeltens kürschnerei machen","grundlagen des zeltens belohnung"}},{q="Wer bietet diese Ausbildung in Tirisfal an?",a="In Tirisfal wird die Aufgabe von Eleanor Shackleton vergeben, um neue Kürschner zu Rand Rhobart entlang der Hauptstraße zwischen Brill und Unterstadt zu leiten.",al={"wer gibt quest tirisfal","eleanor shackleton quest"}},{q="Welche Fertigkeitsstufe ist erforderlich, um diese Aufgabe abzuschließen?",a="Ihr müsst Eure Kürschnerfertigkeit auf mindestens 20 steigern, bevor der Ausbilder Euch als erfahren genug ansieht, um die Herstellung von Lagerausrüstung im Feld zu erlernen.",al={"welche kürschnereistufe wird benötigt","grundlagen des zeltens kürschnerei anforderungen","benötigte kürschnerfertigkeit"}},{q="Wo ist Rand Rhobart zu finden?",a="Rand Rhobart befindet sich an der Hauptstraße, die von Brill nach Süden zum Eingang von Unterstadt in Tirisfal führt.",al={"rand rhobart standort","wo ist rand rhobart","rand rhobart tirisfal"}},{q="Können Mitglieder anderer Fraktionen diese Technik erlernen?",a="Ja. Während Verlassene von Rand Rhobart lernen, bilden entsprechende Ausbilder Kürschner in Goldhain, Eisenschmiede, Dolanaar, Orgrimmar, im Dorf der Bluthufe und in Shen'dar aus.",al={"ist das nur für horde","kann allianz grundlagen des zeltens kürschnerei machen","allianz kürschnerei campingstuhl"}},{q="Warum ist das Herstellen eines Campingstuhls nützlich?",a="Ein Campingstuhl bietet einen bequemen Platz zum Sitzen und zur Erholung der Ausdauer in der Wildnis, wodurch ein Abenteurer ausgeruht und wachsam für bevorstehende Kämpfe bleibt.",al={"was bewirkt ein campingstuhl","warum campingstuhl herstellen"}}},fp="21,270,20.439.0,19.382.0,34.152.0,44.157.0,51.149.0,32.127.0,51.169.0,36.153.0"}
P.entries["quest:97965"] = {n="Camping 101: First Aid",s="Camping 101: First Aid führt Reisende nach Shen'dar, um zu lernen, wie man essenzielle medizinische Vorräte für ein Lager in der Wildnis herstellt. Wenn geübte Anwender Naleeia Tattermend aufsuchen, können sie Lagersets herstellen, die in der Lage sind, fernab der Zivilisation Verletzungen zu behandeln und Leben zu retten.",h="Camping 101: First Aid führt Reisende nach Shen'dar, um zu lernen, wie man essenzielle medizinische Vorräte...",kw={"verbände","camping","camping 101: first aid","erste hilfe","verbandtasche","naleeia tattermend","shen'dar","überleben in der wildnis"},sec={{t="Heilung in der Wildnis",b="Das Leben auf den Straßen ganz Azeroths ist voller Gewalt, wilder Bestien und Gefahren durch die Umwelt. Für jeden Reisenden ist das Erlernen von First Aid ebenso praktisch wie ehrenhaft, da es dafür sorgt, dass blutende Schnittwunden und gebrochene Knochen verbunden werden können, ohne sich einzig auf Zauberkunst verlassen zu müssen. Das Einrichten einer eigenen Verbandtasche in einem Wildnislager bietet einen verlässlichen Mittelpunkt für die Heilung, sodass erschöpfte Abenteurer sich erholen und ihre Gefährten versorgen können, bevor sie weiterziehen."},{t="Die Mentorin von Shen'dar",b="Nicht jeder Feldsanitäter versteht es, strapazierfähige medizinische Lagervorräte fachgerecht zusammenzustellen. In Shen'dar unterweist eine Spezialistin namens Naleeia Tattermend engagierte Anwender in der Kunst, Verbandtaschen für Lagerplätze anzufertigen. Diejenigen, die ihren Rat suchen, müssen zunächst ihr eigenes Können in der grundlegenden medizinischen Versorgung unter Beweis stellen, bevor sie ihre Techniken offenbart."}},faq={{q="Mit wem muss ich für diese Quest sprechen?",a="Ihr müsst Naleeia Tattermend in Shen'dar aufsuchen. Sie verfügt über das Wissen, das erforderlich ist, um spezialisierte medizinische Ausrüstung für Lager in der Wildnis herzustellen.",al={"mit wem für camping erste hilfe sprechen","wo ist naleeia tattermend","camping 101 first aid abgabe"}},{q="Wo befindet sich Shen'dar?",a="Shen'dar ist ein Dorf auf der Insel Zephras, in dem die Sanitäterin Naleeia Tattermend weilt. Heiler, die eine fortgeschrittene Ausbildung in Wildnis-Erster-Hilfe suchen, reisen dorthin, sobald sie ihre Fertigkeiten verfeinert haben.",al={"wo ist shen'dar","shen'dar ort","shen'dar erste hilfe"}},{q="Welchen Zweck hat das Herstellen einer Verbandtasche für das Lager?",a="Die Ausbildung ermöglicht es Euch, eine auf das Lager eines Abenteurers abgestimmte Verbandtasche herzustellen. In der Wildnis sorgt die ständige Verfügbarkeit medizinischer Vorräte im Lager für lebenswichtige Heilung zwischen den Reisen und kann den Unterschied zwischen Leben und Tod bedeuten.",al={"was bringt camping erste hilfe","verbandtasche lager","warum verbandtasche herstellen"}},{q="Wann bringt mir Naleeia Tattermend bei, die Tasche herzustellen?",a="Naleeia Tattermend verlangt, dass Ihr ausreichende Fertigkeiten in First Aid nachweist, bevor sie sich bereit erklärt, ihre Herstellungsmethoden weiterzugeben. Ihr müsst die grundlegenden Künste des Verbindens und Behandelns beherrschen, bevor Ihr Ausrüstungen für das Feld zusammenstellt.",al={"wann kann man die verbandtasche lernen","naleeia tattermend anforderung","camping 101 first aid voraussetzung"}},{q="Warum gilt First Aid sowohl als ehrenhaft als auch als pragmatisch?",a="Wunden und körperliche Traumata sind eine unvermeidliche Gefahr bei Abenteuern in ganz Azeroth. Verbände und medizinische Behandlungen ermöglichen es Reisenden jeder Disziplin, ihre eigenen Wunden zu versorgen und Gefährten zu stabilisieren, ohne sich allein auf magische Unterstützung verlassen zu müssen.",al={"warum ist erste hilfe wichtig","erste hilfe lore","ist erste hilfe nützlich"}},{q="Kann jeder Abenteurer eine Verbandtasche für das Camping herstellen?",a="Jeder Abenteurer, der sich dem Studium von First Aid widmet und seine Kompetenz beweist, kann von Naleeia Tattermend in Shen'dar lernen, eine Verbandtasche für sein Lager anzufertigen.",al={"kann jeder diese tasche lernen","wer kann verbandtasche lager herstellen"}}},fp="22,281,25.455.0,30.355.0,43.150.0,34.199.0,57.243.0,55.223.0,57.242.0,49.177.0"}
P.entries["quest:97967"] = {n="Camping 101: Fishing",s="Camping 101: Fishing leitet angehende Angler an zu entdecken, wie ihre Geduld mit Rute und Schnur Expeditionen in die Wildnis bereichern kann. Indem sie Fenn Fairweather in Shen'dar aufsuchen, können erfahrene Fischer lernen, ein dekoratives Fischglas herzustellen, um die Moral und den Komfort im Lager zu stärken.",h="Camping 101: Fishing leitet angehende Angler an zu entdecken, wie ihre Geduld mit Rute und Schnur...",kw={"camping","camping 101: fishing","fenn fairweather","fischglas","angeln","shen'dar"},sec={{t="Annehmlichkeiten des Herdes",b="Das Leben in der Wildnis erfordert mehr als scharfe Klingen und robuste Rüstung; die Moral im Feld aufrechtzuerhalten, kann den Unterschied zwischen Triumph und Erschöpfung bedeuten. Während Angeln oft rein als geruhsamer Zeitvertreib oder als Mittel zur Nahrungsbeschaffung betrachtet wird, können geschickte Angler ihr Handwerk darauf verwenden, den Komfort des Lagers zu verbessern. Indem ein Reisender lebende Fische fängt und zweckmäßige Vorrichtungen vorbereitet, kann er ein trostloses Lager in eine einladende Zuflucht verwandeln."},{t="Der Handwerker von Shen'dar",b="In Shen'dar teilt der Handwerker Fenn Fairweather Berufsgeheimnisse mit erfahrenen Fischern, welche die Geduld von Rute und Rolle verstehen. Jene, die ausreichendes Geschick beweisen, können lernen, ein Fischglas anzufertigen – eine einfache Lagervorrichtung, die dazu gedacht ist, müden Gefährten Freude und Entspannung zu bringen. Eine gehobene Stimmung draußen in der Wildnis hilft den Gruppenmitgliedern, konzentriert und entschlossen zu bleiben, wenn sie drohenden Gefahren gegenüberstehen."}},faq={{q="Wer lehrt das Camping-Handwerk für das Fischglas?",a="Fenn Fairweather verweilt in Shen'dar. Sobald Ihr angemessene Fertigkeit in Eurem Fischerhandwerk bewiesen habt, kann Fenn Euch beibringen, wie man ein Fischglas herstellt, um Euren Lagerplatz einzurichten und zu verschönern.",al={"wer gibt fischglas","wo ist fenn fairweather","fischglas-lehrer"}},{q="Welchem Zweck dient ein Fischglas im Lager?",a="Ein Fischglas dient als dekorative Vorrichtung für Euer Lager, die Euch und Euren Gefährten einen Hauch von Gemütlichkeit und Heiterkeit verleiht. Ein gut gepflegtes Lager und eine hohe Moral halten Abenteurer wachsam und stärken ihre Bereitschaft für gefährliche Prüfungen im Feld.",al={"was bringt fischglas","fischglas-stärkungszauber","camping fischglas-effekt"}},{q="Wo liegt Shen'dar?",a="Shen'dar ist eine Siedlung, die als Treffpunkt für Handwerker und Ausbilder dient, darunter auch Fenn Fairweather. Anhänger des Angelns reisen dorthin, um praktische Camping-Fertigkeiten zu erlernen, die ihren Fähigkeiten entsprechen.",al={"wo ist shen'dar","shen'dar standort"}},{q="Welche Fertigkeit ist erforderlich, um dieses Camping-Handwerk zu lernen?",a="Ihr müsst zunächst eine solide Grundfertigkeit als Angler vorweisen, bevor Ihr das Handwerk erlernen könnt. Sobald Ihr Eure Angelfähigkeit verfeinert habt, werden Ausbilder in Shen'dar die Methoden zum Zusammenbau von Lagervorrichtungen wie dem Fischglas mit Euch teilen.",al={"camping angeln anforderungen","wann kann man fischglas lernen","wie startet man camping angeln"}},{q="Warum ist Angeln wichtig für das Camping in der Wildnis?",a="Weit über das bloße Einholen von Fängen zur Ernährung hinaus können das scharfe Auge und die Geduld eines Anglers auf unerwartete Weise zum Lagerleben beitragen. Das Ausstellen eines frischen Fangs in einem angefertigten Glas bietet beruhigende Vertrautheit und hebt die Stimmung während langer Expeditionen in die Wildnis.",al={"warum angeln fürs camping","angeln nützlichkeit im lager"}},{q="Wer ist Fenn Fairweather?",a="Fenn Fairweather ist ein Handwerker und Ausbilder, der sich in Shen'dar befindet. Fenn erkennt die praktischen Annehmlichkeiten des Lebens in der Wildnis an und teilt spezialisiertes Wissen über Lagervorrichtungen mit geschickten Fischern.",al={"wer ist fenn fairweather","fenn fairweather lore"}}},fp="20,292,22.452.0,23.416.0,40.199.0,44.251.0,26.221.0,51.241.0,47.256.0,24.206.0"}
P.entries["quest:97969"] = {n="Camping 101: Leatherworking",s="Camping 101: Lederverarbeitung weist angehende Lederverarbeiter an, fortgeschrittenen Unterricht in der Herstellung robuster Wildnisunterkünfte zu suchen. Zu Indari Sunseam in Shen'dar geführt, lernen Handwerker, schützende Zelte zu nähen, die auf langen Expeditionen in die Wildnis lebenswichtige Erholung bieten.",h="Camping 101: Lederverarbeitung weist angehende Lederverarbeiter an, fortgeschrittenen Unterricht in der...",kw={"campzelt","lagerfeuer","camping","kochen","indari sunseam","lederverarbeitung","shen'dar","zelt","wildnis"},ang={["profession:Cooking"]="Ein Zelt allein macht noch kein funktionsfähiges Lager aus; Reisende müssen auch die Grundlagen des Lagerfeuers beherrschen, die üblicherweise von Kochlehrern erlernt werden."},sec={{t="Zuflucht auf Reisen",b="Für reisende Lederverarbeiter ist die Fähigkeit, Tierhaut und Pelz zu robuster Wildnisausrüstung zu verarbeiten, von entscheidender Bedeutung. Nach dem Erlernen des Handwerks werden Gewerbetreibende angewiesen, Indari Sunseam in Shen'dar aufzusuchen, um zu lernen, wie man ein ordentliches Campingzelt herstellt. Solche Unterkünfte halten Abenteurer bei unerbittlichen Regengüssen trocken und unter sengender Sonne kühl, sodass sichergestellt ist, dass sie während langer Reisen gut erholt bleiben."},{t="Lagerplätze in der Wildnis",b="Das Aufstellen eines Zeltes erfordert Respekt vor bürgerlichen Grenzen, da sich die Stadtbevölkerung an einfachen Lagerplätzen stört, die die Straßen der Gemeinde verstellen. Lager müssen draußen in der Wildnis aufgeschlagen werden. Darüber hinaus ist eine stabile Unterkunft nur die halbe Miete: Kein Lagerplatz ist ohne ein wärmendes Lagerfeuer vollständig, was Abenteurer dazu veranlasst, einen örtlichen Koch aufzusuchen, um grundlegende Fertigkeiten des Feuermachens zu erlernen, bevor sie in die Wildnis aufbrechen."}},faq={{q="Wer bringt Lederverarbeitern bei, wie man ein Zelt herstellt?",a="Indari Sunseam wohnt in Shen'dar und unterweist geübte Lederverarbeiter darin, wie sie ihre eigenen Campingzelte herstellen können.",al={"wer lehrt lederverarbeitung zelte","campzelt lehrer","wo ist indari sunseam"}},{q="Was ist der Zweck der Herstellung eines Zeltes?",a="Ein gut gemachtes Zelt schützt Reisende vor rauen Elementen wie Regen und drückender Hitze und ermöglicht es Abenteurern, die nötige Ruhe zu finden, um unterwegs wachsam zu bleiben.",al={"was bewirkt ein zelt","zelt zweck","zelt vorteile"}},{q="Wo kann ein Campingzelt aufgestellt werden?",a="Zelte können nicht in Stadtzentren aufgestellt werden, wo die Einheimischen Einwände dagegen haben. Reisende müssen in die offene Wildnis hinausreisen, bevor sie ihr Lager aufschlagen.",al={"kann man in der stadt ein zelt aufschlagen","wo zelt benutzen","lager regeln"}},{q="Was wird noch benötigt, um ein ordentliches Lager aufzuschlagen?",a="Jeder vollständige Lagerplatz erfordert neben der Unterkunft ein prasselndes Lagerfeuer. Abenteurer werden ermutigt, einen Kochkunstlehrer aufzusuchen, um zu lernen, wie man ein einfaches Feuer entfacht.",al={"brauche ich ein feuer","lager anforderungen","was braucht man noch fürs lager"}},{q="Wann lehrt Euch Indari Sunseam das Zeltmuster?",a="Ihr müsst die Lederverarbeitung ausüben und ein angemessenes Können in Eurem Handwerk unter Beweis stellen, bevor Indari Sunseam Euch in der Herstellung eines Campinggegenstands unterweisen wird.",al={"wann kann ich das zelt erlernen","zelt anforderungen","lederverarbeitung zelt anforderungen"}},{q="Was ist Shen'dar?",a="Shen'dar ist die Siedlung, in der Indari Sunseam lebt und arbeitet und Reisenden gewerblichen Unterricht in der Herstellung von Campingbedarf anbietet.",al={"wo ist shen'dar","shen'dar lage","indari sunseam stadt"}}},fp="27,285,19.396.0,20.392.0,47.123.0,39.162.0,36.144.0,43.167.0,52.151.0,25.142.0"}
P.entries["quest:97971"] = {n="Camping 101: Skinning",s="Camping 101: Skinning leitet Abenteurer darin an, gesammelte Pelze in einen funktionalen Lagerstuhl für Feldlager zu verwandeln. Unter der Anleitung von Mendalass Tattermend in Shen'dar lernen Kürschner, ihr Sammelhandwerk mit dem Überleben in der Wildnis und der Entspannung am Lagerfeuer zu verbinden.",h="Camping 101: Skinning leitet Abenteurer darin an, gesammelte Pelze in einen funktionalen Lagerstuhl für...",kw={"lagerstuhl","lagerfeuer","camping 101","bã¤lge","mendalass tattermend","shen'dar","kã¼rschnerei","wildnis"},ang={["profession:Cooking"]="Kochen und das Ãœberleben in der Wildnis gehen Hand in Hand; wie Mendalass anmerkt, erfordert das Errichten eines ordentlichen Lagerplatzes ein einfaches Lagerfeuer â€“ eine Fertigkeit, die traditionell von Kochlehrern vermittelt wird."},sec={{t="Komfort in der Wildnis",b="Das Sammeln von Fellen erlegter Bestien ist in ganz Azeroth eine grundlegende Überlebensfertigkeit, doch sein Nutzen reicht weit über die einfache Rüstungsherstellung hinaus. Durch Camping 101: Skinning lernen Sammler, ihr Handwerk auf das Überleben in der Wildnis auszurichten, indem sie einen tragbaren Lagerstuhl herstellen. Sich die Zeit zu nehmen, um auf einem bequemen Sitz in der Wildnis auszuruhen, ermöglicht es müden Abenteurern, neue Kräfte zu sammeln und vor ihrem nächsten Kampf in optimaler Verfassung zu bleiben."},{t="Die Lehren von Shen'dar",b="Um dieses Muster zu meistern, werden Abenteurer nach Shen'dar geschickt, um sich mit Mendalass Tattermend zu treffen, sobald sie ihr KÃ¶nnen mit dem KÃ¼rschnermesser unter Beweis gestellt haben. Mendalass unterweist Reisende darin, aus gesammelten Pelzen eine strapazierfÃ¤hige Sitzgelegenheit zusammenzufÃ¼gen. Doch das Errichten eines Lagerplatzes erfordert mehr als nur Mobiliar: Siedlungen dulden keine spontanen Lager innerhalb der Stadtgrenzen, und kein Lagerplatz ist wirklich komplett ohne ein prasselndes Lagerfeuer â€“ eine FÃ¤higkeit, die man traditionell von Ã¶rtlichen Kochlehrern erlernt."}},faq={{q="Worum geht es bei Camping 101: Skinning?",a="Camping 101: Skinning führt geschickte Kürschner zu Mendalass Tattermend in Shen'dar. Durch das Abschließen dieser Ausbildung lernen Abenteurer, wie man gesammelte Felle zu einem praktischen Lagerstuhl für Rast und Erholung im Feld umfunktioniert.",al={"was ist diese quest","camping 101 zweck","warum diese quest machen"}},{q="Wer ist Mendalass Tattermend?",a="Mendalass Tattermend ist ein Kürschnerlehrer in Shen'dar. Er bringt geübten Kürschnern bei, wie man gesammelte Felle zu bequemen Feldsitzgelegenheiten für Lager in der Wildnis zusammennäht.",al={"wer ist mendalass","wer lehrt lagerstuhl","mendalass tattermend"}},{q="Wo ist Mendalass Tattermend zu finden?",a="Mendalass Tattermend hÃ¤lt sich in Shen'dar auf, wohin Abenteurer reisen mÃ¼ssen, um ihr KÃ¶nnen zu beweisen und die Kunst der Herstellung von LagerausrÃ¼stung zu erlernen.",al={"wo ist mendalass","wo ist shen'dar","wo gebe ich das ab"}},{q="Welchen Gegenstand lernt Ihr durch diese Quest herzustellen?",a="Kürschner erlernen das Muster zur Anfertigung eines Lagerstuhls aus Fellen und Pelzen erlegter Bestien, der eine bequeme Sitzgelegenheit zum Ausruhen in der Wildnis bietet.",al={"was stellen kã¼rschner her","rezept für lagerstuhl","welchen gegenstand erhalte ich"}},{q="Kann man in einer Stadt ein Lager aufschlagen?",a="Stadtbewohner sehen es nicht gern, wenn mitten in Siedlungen ein Lager aufgeschlagen wird. Lager und Lagerstühle sind dafür gedacht, draußen in der Wildnis abseits von Stadtzentren errichtet zu werden.",al={"kann ich in stã¤dten zelten","wo kann ich ein lager aufschlagen","wo lagerstuhl benutzt wird"}},{q="Was wird noch fÃ¼r ein ordentliches Lager benÃ¶tigt?",a="Zu jedem ordentlichen Lagerplatz gehÃ¶rt ein prasselndes Lagerfeuer, damit er vollstÃ¤ndig ist. Abenteurern, die das Entfachen von Feuern noch nicht beherrschen, wird geraten, sich an einen Kochlehrer zu wenden, um die Grundlagen zu erlernen.",al={"was brauche ich noch fã¼rs lager","lagerfeuer benã¶tigt","lagervoraussetzungen"}}},fp="21,267,20.446.0,33.502.0,36.232.0,28.185.0,40.147.0,44.170.0,34.158.0,44.189.0"}
P.entries["quest:97973"] = {n="Camping 101: Tailoring",s="Camping 101: Tailoring führt Schneider in die Kunst ein, spezialisierte Ausrüstung für Lagerplätze in der Wildnis herzustellen. Indem sie Taleen Shimmerthread in Shen'dar ihr Können unter Beweis stellen, lernen Schneider, ein inspirierendes Fraktionsbanner zu nähen, das den Geist belebt und die Moral im Lager aufrechterhält.",h="Camping 101: Tailoring führt Schneider in die Kunst ein, spezialisierte Ausrüstung für Lagerplätze in der...",kw={"lagerbanner","camping","camping 101: tailoring","fraktionsbanner","shen'dar","schneiderei","taleen shimmerthread","beruf"},ang={["profession:Tailoring"]="Schneider lernen, inspirierende Fraktionsbanner herzustellen, welche die Lagermoral stärken und Verbündeten im Feld neue Kraft verleihen."},sec={{t="Der Beitrag von The Weaver zum Lager",b="Camping 101: Tailoring leitet Stoffarbeiter an, ihr Handwerk über einfache Kleidungsstücke und Taschen hinaus zu erweitern. In der ungezähmten Wildnis erfordert das Überleben mehr als warme Kleidung; ein ordentlicher Lagerplatz kann den Unterschied zwischen Ausdauer und Niederlage bedeuten. Schneider werden ermutigt, fortgeschrittene Unterweisung zu suchen, um Ballen gewebten Stoffs in Symbole der Einheit und Seelenstärke zu verwandeln."},{t="Unterweisung in Shen'dar",b="Die Quest führt angehende Schneider nach Shen'dar, wo Taleen Shimmerthread Unterweisung in Campinghandwerken anbietet. Diejenigen, die ausreichendes Geschick in der Schneiderei entwickelt haben, können die Methoden erlernen, die zur Herstellung eines Fraktionsbanners erforderlich sind. Mit Sorgfalt genäht und stolz im Lager aufgestellt, dient ein solches Banner als inspirierender Sammelpunkt, der die Moral stärkt und Verbündete für die bevorstehenden Prüfungen mit Energie versorgt."}},faq={{q="Was ist Camping 101: Tailoring?",a="Camping 101: Tailoring leitet vielversprechende Schneider an, spezialisierte Unterweisung im Feldhandwerk zu suchen. Sobald Ihr ausreichendes Geschick in der Schneiderei vorweist, könnt Ihr lernen, ein dekoratives und inspirierendes Fraktionsbanner für Lagerplätze in der Wildnis herzustellen.",al={"was ist diese quest","camping 101 tailoring quest","schneiderei campingbanner"}},{q="Wer ist Taleen Shimmerthread?",a="Taleen Shimmerthread ist eine Meisterschneiderin in Shen'dar. Sie unterweist geschickte Handwerker darin, für die Schneiderei spezifische Campinggegenstände zu weben, einschließlich Bannern, die den Geist im Lager beleben.",al={"taleen shimmerthread","wer lehrt schneidereibanner","wo ist taleen shimmerthread"}},{q="Wo ist Shen'dar?",a="Shen'dar ist die Siedlung, in der Taleen Shimmerthread weilt. Schneider reisen dorthin, um spezialisierte Anleitung zur Anwendung ihres Handwerks der Stoffbearbeitung auf Campingausrüstung zu erhalten.",al={"wo ist shendar","shendar aufenthaltsort"}},{q="Welchen Campinggegenstand können Schneider herzustellen lernen?",a="Ein Fraktionsbanner ist ein von Schneidern hergestellter Campinggegenstand. Auf jedem Schlachtfeld und bei jeder harten Expedition ist die Aufrechterhaltung von Inspiration und Moral von entscheidender Bedeutung, und das Aufstellen eines Banners verleiht jenen, die im Lager rasten, eine belebende Präsenz.",al={"fraktionsbanner camping","was stellt schneiderei fürs lager her","schneiderei lagergegenstand"}},{q="Was sind die Voraussetzungen, um das Campingbanner zu erlernen?",a="Ihr müsst Fertigkeit im Schneidereiberuf vorweisen, bevor Taleen Shimmerthread in Shen'dar Euch das Muster lehrt, um ein Fraktionsbanner für Euer Lager zu weben.",al={"wie man fraktionsbanner lernt","schneiderei voraussetzungen campingbanner"}},{q="Warum sind Fraktionsbanner im Lager wertvoll?",a="Moral und Inspiration sind auf jedem Feldzug entscheidend. Schneider nähen Fraktionsbanner, um Loyalität zu zeigen und einen belebenden Mittelpunkt zu bieten, der Abenteurer auf zermürbenden Reisen stärkt.",al={"warum ein fraktionsbanner herstellen","campingbanner moral"}}},fp="22,281,33.349.0,31.405.0,31.244.0,28.199.0,26.178.0,45.216.0,54.169.0,41.196.0"}
P.entries["quest:97977"] = {n="Nature's Call",s="Nature's Call ist eine Quest im Laubschattental, bei der die Dryade Tarindrella aufzudecken versucht, warum sich die einheimischen Gnarlpine-Furbolgs plötzlich gegen ihre langjährigen Nachtelfenverbündeten wandten. Durch das Sammeln geschnitzter Totems aus ihren verlassenen Lagern helfen Abenteurer dabei, die beunruhigende geistige Verderbnis zu enthüllen, die sich in Teldrassil ausbreitet.",h="Nature's Call ist eine Quest im Laubschattental, bei der die Dryade Tarindrella aufzudecken versucht, warum...",kw={"furbolg","gnarlpine","grell","grellkin","nature's call","albträume","laubschattental","tarindrella","teldrassil","totem"},ang={["class:Druid"]="Druiden sind auf das natürliche Gleichgewicht und die geistige Verderbnis eingestimmt, die die Kreaturen von Kalimdor befällt, was die albtraumhafte Verderbnis der Furbolg-Totems zu einer besorgniserregenden Entwicklung macht.",["faction:Alliance"]="Die Sicherung der Äste von Teldrassil ist unerlässlich, um das junge Reich der Nachtelfen zu schützen und sicherzustellen, dass ihre neuen Verbündeten der Allianz fest auf Kalimdor verankert bleiben.",["race:NightElf"]="Die Gnarlpine waren langjährige Gefährten der Nachtelfen, weshalb ihr Abdriften in Feindseligkeit und Wahnsinn eine zutiefst persönliche Tragödie für die Verteidiger von Teldrassil darstellt."},sec={{t="Untersuchung des Tals",b="Nature's Call ist eine Untersuchungsmission im Laubschattental, die von der Dryade Tarindrella vergeben wird. Da sie sich weigert zu glauben, dass die Gnarlpine-Furbolgs eine jahrhundertelange Freundschaft mit den Nachtelfen ohne Grund aufgeben würden, bittet sie Reisende, die hastig verlassenen Lager der Furbolgs entlang der Westgrenze des Tals zu durchkämmen, um intakte gravierte Totems zu bergen."},{t="Der Schatten und der Albtraum",b="Die Entschlüsselung der geborgenen Totems offenbart einen tragischen Abstieg in den Wahnsinn. Die Gnarlpine wurden von wiederkehrenden Albträumen über einen herannahenden Schatten geplagt, der dazu bestimmt war, sie auszulöschen. Im Laufe der Zeit schlug das bloße Entsetzen in blinde Wut um und verzerrte ihren Geist, bis sie ihre langjährigen elfischen Nachbarn als genau jenen Schatten ansahen, den sie fürchteten. Tarindrella hofft, dass diese Erkenntnisse Licht auf das tiefere Unheil werfen, das durch Teldrassil kriecht."}},faq={{q="Wer vergibt die Quest Nature's Call?",a="Tarindrella ist eine Dryade, die über das Laubschattental in Teldrassil wacht. Besorgt über die plötzliche Feindseligkeit der einheimischen Gnarlpine-Furbolgs weist sie Abenteurer an, Relikte aus deren verlassenen Lagern zu bergen, um die Ursache ihres Wahnsinns zu untersuchen.",al={"wer vergibt nature's call","wer ist tarindrella","tarindrella aufenthaltsort"}},{q="Warum wurden die Gnarlpine-Furbolgs feindselig?",a="Gravuren, die von Gnarlpine-Totems geborgen wurden, enthüllen, dass die Furbolgs unter schrecklichen Albträumen über einen drohenden Schatten zu leiden begannen, der sie zu vernichten drohte. Diese schleichende Furcht wandelte sich in unkontrollierbare Paranoia und Wut, was dazu führte, dass sie ihre uralten Nachtelfenverbündeten als Feinde ansahen.",al={"warum griffen gnarlpine an","warum sind gnarlpine verrückt","was geschah mit den gnarlpine-furbolgs"}},{q="Wo befinden sich die Gnarlpine-Totems?",a="Die kleineren Totems können in den verlassenen Lagern der Gnarlpine-Furbolgs am westlichen Rand des Tals gefunden werden, wenngleich Grell und Grellkin, die die Ruinen durchwühlen, einige davon in der Umgebung verstreut haben.",al={"wo sind die gnarlpine-totems","gnarlpine-totems finden","gnarlpine-lager standort"}},{q="Warum können Spieler die größeren Totems in den Lagern nicht sammeln?",a="Tarindrella rät ausdrücklich davon ab, die größeren Totems in den Lagern mitzunehmen. Als Dryade merkt sie an, dass sie keine Ahnung hätte, was sie mit derart unhandlichen Schnitzereien anfangen sollte, und bevorzugt stattdessen kleinere, transportable gravierte Totems.",al={"warum große totems ignoriert werden","kann ich große totems plündern","großes gnarlpine-totem"}},{q="Wer sind die Gnarlpine-Furbolgs?",a="Die Gnarlpine sind ein in Teldrassil heimischer Stamm von Furbolgs, der an der Seite der Nachtelfen als friedliche Verbündete lebte. Ihre jüngste Verwandlung in aggressive Feinde ist eine unnatürliche Entwicklung, die durch schleichende Albträume und nicht durch uralte Bosheit hervorgerufen wurde.",al={"wer sind die gnarlpine","gnarlpine lore","sind gnarlpine böse"}},{q="Was ist der große Schatten, der in den Totems erwähnt wird?",a="Die Gravuren berichten von einem unsichtbaren Großen Schatten, der die Träume der Furbolgs heimsucht. Während der genaue Ursprung dieses dunklen Einflusses unbekannt bleibt, hofft Tarindrella, dass die Entschlüsselung ihres Schicksals dazu beitragen wird, die umfassendere Verderbnis aufzuklären, die Teldrassil befällt.",al={"welcher schatten gnarlpine","was ist der schatten in teldrassil","albträume in teldrassil"}}},fp="13,321,22.354.0,28.424.1,34.247.0,44.280.0,39.225.0,57.252.0,30.248.0,49.245.0"}
P.entries["quest:97979"] = {n="The Goddess Provides",s="The Goddess Provides ist eine einführende Quest der Kaldorei, die sich darum dreht, Elunes göttliche Gaben anzuerkennen. Angesiedelt im Geäst von Teldrassil nach dem Ende der langen Wache, lehrt sie junge Nachtelfen, die lunare Führung und die verhüllenden Schatten anzunehmen, die von Mutter Mond verliehen wurden.",h="The Goddess Provides ist eine einführende Quest der Kaldorei, die sich darum dreht, Elunes göttliche Gaben...",kw={"elune","the goddess provides","hyjal","kaldorei","lange wache","mutter mond","schattenhaftigkeit","teldrassil"},ang={["class:Priest"]="Die Priesterschaft der Kaldorei ist Mutter Mond geweiht und kanalisiert Elune's Grace direkt als leitendes Strahlen und göttlichen Schutz.",["faction:Alliance"]="Nach der Schlacht am Hyjal beendeten die Nachtelfen ihre lange Isolation und traten der Allianz bei, wobei sie ihre heiligen Mondkräfte in den Dienst der gemeinsamen Verteidigung stellten.",["race:NightElf"]="Als Kinder der Sterne erben die Kaldorei die direkten Segnungen Elunes und nutzen Mondlicht, um ungesehene Pfade zu offenbaren, sowie Verhüllung, um mit den Schatten zu verschmelzen."},sec={{t="Eine beendete Wache",b="Über Jahrtausende nach der Zerschlagung hielten die Kaldorei an ihrer einsamen langen Wache fest, wachten über Kalimdor und beschützten die heiligen Gipfel des Hyjal. Die Verheerung des Dritten Krieges und die entscheidende Verteidigung des Weltenbaums erzwangen ein Ende dieser uralten Abgeschiedenheit. Nun in das schützende Geäst von Teldrassil umgesiedelt, stehen die Nachtelfen vor einer ungewohnten Welt und betreten die größere Bühne Azeroths, indem sie sich Verbündeten jenseits des Ozeans anschließen."},{t="Segnungen von Mutter Mond",b="Selbst inmitten wechselnder Bündnisse und neuer Behausungen bleibt das Fundament der Identität der Kaldorei in der Verehrung Elunes, der Mutter Mond, verwurzelt. Nachtelfen wird von ihren frühesten Tagen an beigebracht, ihre beiden Aspekte anzurufen: Glanz, um kriegerische Schläge zu leiten und die Entschlossenheit zu schärfen, und Schatten, um die eigene Anwesenheit vor den Blicken der Feinde zu verhüllen. Diese ererbten Gaben anzurufen dient sowohl der spirituellen Zwiesprache als auch der praktischen Vorbereitung auf die Gefahren jenseits des Großen Baumes."}},faq={{q="Was ist The Goddess Provides?",a="The Goddess Provides ist ein Einführungsritus für junge Nachtelfen, eingebettet im Geäst von Teldrassil. Er unterweist die Kaldorei darin, die angeborenen Segnungen anzuerkennen und zu demonstrieren, die ihnen von der Mondgöttin Elune gewährt wurden.",al={"was ist the goddess provides","quest the goddess provides"}},{q="Wer ist die Göttin, auf die sich diese Quest bezieht?",a="Die Göttin ist Elune, die von den Kaldorei auch als Mutter Mond verehrt wird. Sie ist die zentrale Gottheit der Kultur und des spirituellen Lebens der Nachtelfen, von der geglaubt wird, dass sie ihren Kindern lunare Segnungen des Schutzes, der Klarheit und der Heimlichkeit schenkt.",al={"wer ist die göttin","wer ist mutter mond","nachtelfengöttin"}},{q="Welche Gaben gewährt Elune den Kaldorei?",a="Elune gewährt Elune's Grace, die die Hiebe eines Kriegers erleuchten kann, damit sie zielsicher treffen, sowie die Fähigkeit, mit den umgebenden Schatten zu verschmelzen, so wie der Mond die Sonne während einer Finsternis verbirgt.",al={"welche gaben verleiht elune","volksfähigkeiten elunes","mächte elunes"}},{q="Was war die lange Wache?",a="Die lange Wache war die Jahrtausende währende bewachte Isolation, die die Nachtelfen aufrechterhielten, um über Kalimdor zu wachen. Sie endete nach der entscheidenden Verteidigung des Hyjal gegen die Brennende Legion, was die Kaldorei dazu veranlasste, schließlich ihre Grenzen zu öffnen.",al={"was war die lange wache","warum endete die lange wache"}},{q="Warum haben sich die Nachtelfen der Allianz angeschlossen?",a="Nachdem die Verteidigung des Hyjal ihrer einsamen Isolation ein Ende gesetzt hatte, beschlossen die Kaldorei, Bande mit sterblichen Völkern jenseits des Meeres zu knüpfen, und traten der Großen Allianz für das gegenseitige Überleben und die Kameradschaft bei.",al={"warum traten nachtelfen der allianz bei","kaldorei-allianz"}},{q="Wo findet diese Unterweisung statt?",a="Teldrassil ist der gewaltige Weltenbaum vor der Nordküste von Kalimdor. Seine hohen, schützenden Äste dienen dem Volk der Nachtelfen nach dem Dritten Krieg als neue Heimat und Zuflucht.",al={"wo liegt teldrassil","was ist teldrassil"}}},fp="20,274,17.476.0,24.466.0,29.226.0,44.222.0,46.194.0,24.252.0,45.213.0,39.196.0"}
P.entries["quest:98013"] = {n="Swelling Forces",s="Swelling Forces ist eine Quest, bei der Arbal Abenteurer vom Grove of the Ancients dazu anhält, die erstarkenden Stormscale-Naga zu dezimieren, welche die Ruinen im Nordosten besetzen. Diese verfluchten ehemaligen Hochgeborenen bedrohen die Wälder, indem sie sich mit dem tückischen Schattenhammerkult verbünden. Die Waffen gegen sie zu erheben, ist entscheidend, um den uralten Wald vor weiterer Verwüstung zu bewahren.",h="Swelling Forces ist eine Quest, bei der Arbal Abenteurer vom Grove of the Ancients dazu anhält, die...",kw={"arbal","grove of the ancients","hochgeborene","myrmidone","naga","zauberin","stormscale","swelling forces","schattenhammer"},ang={["faction:Alliance"]="Streitkräfte der Allianz, welche die heiligen Wälder rund um die Dunkelküste und den Grove of the Ancients verteidigen, müssen sich einer koordinierten Front zwischen den Naga und dem Schattenhammer stellen.",["race:NightElf"]="Die Naga, die diese Ruinen durchstreifen, gehörten einst zu den Hochgeborenen und waren Verwandte der Nachtelfen. Zu sehen, wie sie zurückkehren, um die uralten Wälder an der Seite finsterer Kultisten zu entweihen und zu plündern, ist ein bitterer Verrat."},sec={{t="Schlangen in der versunkenen Stadt",b="Vom Grove of the Ancients aus beobachtet Arbal die Ruinen im Nordosten mit ernster Besorgnis. Verfluchte Hochgeborene, die in die schlangenartigen Naga des Stormscale-Stammes verwandelt wurden, haben die Überreste ihrer einst prachtvollen Zivilisation besetzt. Anstatt friedlich in der Erinnerung zu ruhen, hallen die versunkenen Steine nun vom schlängelnden Marsch einer heranrückenden Armee wider. Arbal beauftragt Verteidiger damit, sich in die Ruinen zu wagen, um ihre wachsende Zahl zu dezimieren, bevor ihre Macht auf den restlichen Wald überschwappt."},{t="Ein unheiliges Bündnis",b="Die Anwesenheit der Stormscale-Naga ist mehr als einfache territoriale Aggression. Arbal enthüllt, dass diese entstellten ehemaligen Hochgeborenen dem nihilistischen Schattenhammerkult beistehen. Dass Kreaturen genau jene Wälder entweihen und plündern, die ihnen einst Zuflucht boten – besonders im Dienste finsterer, schattenhafter Meister –, ist ein unverzeihliches Vergehen. Ihre Reihen zu lichten, ist eine dringende Notwendigkeit, um zu verhindern, dass der Kult und seine schlangenartigen Verbündeten das Land noch fester in ihren Griff nehmen."}},faq={{q="Wer vergibt die Quest Swelling Forces?",a="Swelling Forces wird von Arbal vergeben, der Abenteurer vom Grove of the Ancients aussendet, um sich den feindseligen Naga-Streitkräften zu stellen, die sich in den Ruinen im Nordosten sammeln.",al={"wer vergibt swelling forces","arbal questgeber","wo ist arbal"}},{q="Warum geraten die Naga in dieser Quest ins Visier?",a="Die Stormscale-Naga haben die nahe gelegenen Ruinen überrannt und bedrohen die umliegenden Wälder. Noch alarmierender ist, dass sie anscheinend dem Schattenhammerkult helfen und Gewalt in genau jene Lande bringen, die sie einst ihr Zuhause nannten.",al={"warum naga töten","naga in den ruinen","bedrohung durch stormscale"}},{q="Welche Verbindung besteht zwischen den Naga und den Ruinen?",a="Wie Arbal bemerkt, waren die Naga einst hochelbische Hochgeborene des uralten Kalimdor, die ein schrecklicher Fluch traf. Obwohl sie einst diese prächtigen Städte bewohnten, sind sie nun als entstellte Schlangen zurückgekehrt, die nach Eroberung und Verwüstung trachten.",al={"wer sind die stormscale-naga","ursprung der naga","verfluchte hochgeborene"}},{q="Welche Verbindung besteht zwischen den Naga und dem Schattenhammer?",a="Die Quest enthüllt, dass die Naga dem schattenhaften Schattenhammerkult beistehen. Während ihre genauen Vereinbarungen im Dunkeln liegen, warnt Arbal davor, dass ihr Bündnis den uralten Wäldern nur weiteren Ruin und Elend bringen kann.",al={"schattenhammer naga","warum naga mit kult zusammenarbeiten"}},{q="Wo sammeln sich die Streitkräfte der Stormscale?",a="Die Ruinen liegen nordöstlich vom Grove of the Ancients. Abenteurer werden dorthin entsandt, um das anwachsende Heer der Stormscale einzudämmen, indem sie deren Myrmidonen, Zauberinnen und Krieger jagen.",al={"wo sind die ruinen","wo man stormscale findet"}},{q="Warum hält Arbal die Taten der Naga für unverzeihlich?",a="Für Arbal ist die Plünderung der eigenen uralten Heimat auf Geheiß eines dunklen Meisters völlig unverzeihlich. Welchen Adel die Hochgeborenen auch einst besessen haben mögen, ist durch ihren Abstieg in Grausamkeit und finstere Bündnisse vollständig ausgelöscht worden.",al={"warum hasst arbal naga","unverzeihlich arbal"}}},fp="15,381,27.499.0,18.482.1,36.166.0,46.225.0,54.221.0,55.222.0,38.184.0,56.221.0"}
P.entries["quest:98021"] = {n="Journey to Sentinel Hill",s="Journey to Sentinel Hill führt Abenteurer der Allianz in das krisengeschüttelte Ackerland von Westfall, damit sie sich am Außenposten auf der Späherkuppe melden. Frustriert über monatelang unbeantwortete Bitten um königliche Verstärkung aus Sturmwind sind die Befehlshaber vor Ort bereit, jeden hilfsbereiten Reisenden direkt einzuspannen.",h="Journey to Sentinel Hill führt Abenteurer der Allianz in das krisengeschüttelte Ackerland von Westfall, damit...",kw={"journey to sentinel hill","volksmiliz","späherkuppe","dünner elf","sturmwind","westfall"},ang={["faction:Alliance"]="Westfall ist ein Gebiet der Allianz, das verzweifelt Unterstützung benötigt, doch Sturmwind hat die örtlichen Befehlshaber allein gelassen, sodass sie um Verstärkung bitten und auf jeden eintreffenden Freiwilligen angewiesen sind.",["race:NightElf"]="Der Grenzkommandant auf der Späherkuppe mag darüber murren, dass ihm ein „dünner Elf“ statt erfahrener Infanterie aus Sturmwind geschickt wurde, doch die Späherkuppe braucht jede Hilfe, die sie bekommen kann."},sec={{t="Ankunft an der Grenze",b="Journey to Sentinel Hill markiert die Ankunft eines Abenteurers in der bedrängten Region Westfall. Der Außenposten der Späherkuppe dient als Hauptverteidigungsbastion für das umliegende Ackerland, doch seine Garnison ist chronisch unterbesetzt und wird vom königlichen Hof übersehen. Wenn Reisende eintreffen, um Hilfe anzubieten, verliert der örtliche Befehlshaber wenig Zeit damit, ihre Herkunft zu hinterfragen, begierig darauf, jede willige Hand an die Arbeit zu setzen."},{t="Bitten an Sturmwind",b="Monatelang hat die Führung auf der Späherkuppe Sturmwind um militärische Verstärkung gebeten, um die Region gegen die vordringenden Bedrohungen zu sichern. Die Vernachlässigung durch das Königreich hat die örtlichen Befehlshaber dazu gezwungen, jede Hilfe anzunehmen, die zur Tür hereinspaziert – selbst wenn das bedeutet, einen neu eingetroffenen Abenteurer mit trockenen Bemerkungen darüber zu begrüßen, dass man eigentlich eine Armee erwartet habe und stattdessen einen dünnen Elfen erhalte. In Westfall können Bettler nun einmal nicht wählerisch sein."}},faq={{q="Was ist Journey to Sentinel Hill?",a="Journey to Sentinel Hill ist eine Quest der Allianz, die Abenteurer in das Grenzgebiet von Westfall führt. Sie macht Neuankömmlinge mit den örtlichen Verteidigern bekannt, die auf der Späherkuppe stationiert sind und vergeblich Sturmwind um Hilfe gebeten haben, ohne angemessene offizielle Verstärkung zu erhalten.",al={"was ist journey to sentinel hill","journey to sentinel hill quest","späherkuppe quest"}},{q="Warum bittet die Späherkuppe um Hilfe?",a="Die auf der Späherkuppe stationierte militärische Führung bittet Sturmwind seit Monaten um Verstärkung, um die Westfall plagenden Probleme in den Griff zu bekommen. Statt regulärer Truppen ist die Führung vor Ort gezwungen, sich auf jene einzelnen Abenteurer zu verlassen, die zufällig vorbeikommen.",al={"wer bittet sturmwind um hilfe","späherkuppe garnison","warum die späherkuppe hilfe braucht"}},{q="Warum erwähnt der Questtext einen dünnen Elfen?",a="Nach Abschluss der Reise bemerkt der Befehlshaber, dass man Sturmwind monatelang um Hilfe angefleht habe, nur um einen dünnen Elfen geschickt zu bekommen. Mit dem Murren, dass Bettler nicht wählerisch sein können, beschließt der Befehlshaber rasch, den neu eingetroffenen Abenteurer direkt an die Arbeit zu setzen.",al={"dünner elf zitat","warum dünner elf","späherkuppe kommentar elf"}},{q="Warum hat Sturmwind keine richtige Verstärkung geschickt?",a="Die königliche Regierung von Sturmwind ist derzeit abgelenkt und überfordert, sodass äußere Gebiete wie Westfall weitgehend vernachlässigt werden. Die Späherkuppe hat über mehrere Monate hinweg wiederholt um Hilfe ersucht, doch offizielle königliche Unterstützung bleibt aus, sodass die örtlichen Befehlshaber auf Freiwillige angewiesen sind.",al={"warum sturmwind westfall nicht hilft","sturmwind vernachlässigt westfall","sturmwind westfall hilfe"}},{q="Was ist die Späherkuppe?",a="Die Späherkuppe ist der zentrale militärische Außenposten und die Bastion der Volksmiliz in Westfall. Sie dient als vorderste Verteidigungslinie gegen Gesetzlosigkeit, Defias-Banditen und Gnolle, die das Ackerland der Region heimsuchen.",al={"wo ist die späherkuppe","was ist die späherkuppe","späherkuppe standort"}},{q="Was passiert nach Erreichen der Späherkuppe?",a="Sobald Ihr Euch auf der Späherkuppe meldet, verlieren die örtlichen Verteidiger keine Zeit, Euch an die Arbeit zu setzen. Abenteurer werden damit beauftragt, bei der Bewältigung der zahlreichen Bedrohungen in den Ebenen und dem Ackerland von Westfall zu helfen.",al={"was tun in westfall","westfall nächste quests","was passiert nach der ankunft in westfall"}}},fp="24,291,23.433.0,18.430.0,33.285.0,37.265.0,45.249.0,48.288.0,22.223.0,42.200.0"}
P.entries["quest:98024"] = {n="Journey to the Crossroads",s="Journey to the Crossroads führt neu eingetroffene Reisende von der Elementarebene in die zerklüftete Savanne des Brachlands. Abenteurer haben die Aufgabe, sich bei Thork am Wegekreuz zu melden, um den Streitkräften der Horde beizustehen, die sich an der rauen Grenze behaupten müssen. Sie dient als grundlegende Einführung in die tödlichen Gefahren, denen die Horde in Kalimdor gegenübersteht.",h="Journey to the Crossroads führt neu eingetroffene Reisende von der Elementarebene in die zerklüftete Savanne...",kw={"brachland","das wegekreuz","elementarebene","horde","journey to the crossroads","thork"},ang={["faction:Horde"]="Diese Reise führt neu eingetroffene Champions dazu, die Waffen für die Horde zu ergreifen, und bietet eine Feuertaufe an Kalimdors rauer Grenze.",["race:Skyborne"]="Nach ihrer Ankunft auf Azeroth von der Elementarebene werden Reisende dazu angehalten, sterbliche Konflikte nicht zu unterschätzen und ihren Mut im Dienste der Horde unter Beweis zu stellen."},sec={{t="Ein Ruf an die Grenze",b="Reisende, die nach ihrer Reise von der Elementarebene auf Azeroth eintreffen, werden mit einer ernüchternden Realität empfangen: Sterbliche Konflikte mögen im Vergleich bescheiden wirken, doch die Gefahren, denen die Horde gegenübersteht, sind nur allzu real. Der Dienst an vorderster Front bietet ein entscheidendes Prüffeld für all jene, die danach streben, bedeutende Stärke zu erlangen und gleichzeitig dem Reich beizustehen."},{t="Das Wegekreuz von Kalimdor",b="Um ihren Dienst anzutreten, werden Abenteurer nach Südwesten in die weiten, sonnenverbrannten Ebenen des Brachlands gewiesen. Dort liegt das Wegekreuz, ein zentraler Knotenpunkt und lebenswichtiger Außenposten der Horde, dessen stolze Verteidiger durch die umgebenden Gefahren fortwährend bedrängt werden. Wer sich direkt bei Thork meldet, wird in die Verteidigung der Siedlung eingebunden."}},faq={{q="Wer ist Thork?",a="Thork ist eine prominente Autoritätsperson der Horde, die am Wegekreuz im Brachland stationiert ist. Er überwacht die örtliche Verteidigung und weist Abenteurer an, bei der Bewältigung der zahlreichen Bedrohungen zu helfen, denen die Siedlung und die umliegenden Gebiete ausgesetzt sind.",al={"wer ist thork","anführer des wegekreuzes","wo ist thork"}},{q="Was ist das Wegekreuz?",a="Das Wegekreuz ist ein zentraler Außenposten und Handelspunkt der Horde an der Kreuzung wichtiger Pfade im Brachland. Umgeben von feindseliger Tierwelt, Zentaurenstämmen und Stacheleberräubern benötigen seine Verteidiger ständige Unterstützung, um die lebenswichtigen Nachschublinien zu sichern.",al={"was ist das wegekreuz","wegekreuz brachland","warum zum wegekreuz reisen"}},{q="Wo liegt das Brachland?",a="Das Brachland ist eine weite, trockene Savanne in Zentralkalimdor, südwestlich von Durotar. Es dient als lebenswichtiges Gebiet, das die Territorien der Horde auf dem gesamten Kontinent miteinander verbindet.",al={"wo liegt das brachland","lage des brachlands"}},{q="Warum erwähnt die Quest die Elementarebene?",a="Die Quest hält fest, dass der Reisende kürzlich von der Elementarebene eingetroffen ist. Auch wenn übernatürliche Konflikte gewaltig erscheinen mögen, sind die Gefahren, die das Reich der Sterblichen und die Horde bedrohen, unmittelbar und schwerwiegend.",al={"ankunft von der elementarebene","warum elementarebene","reise von der elementarebene"}},{q="Was ist der Zweck von Journey to the Crossroads?",a="Die Mission weist Neuankömmlinge an, sich direkt bei Thork am Wegekreuz zu melden, wodurch sie in die Frontbemühungen der Horde eingebunden werden und die Möglichkeit erhalten, durch ehrenhaften Dienst an Stärke zu gewinnen.",al={"zweck der wegekreuz quest","warum zum wegekreuz geschickt"}},{q="Welchen Gefahren sehen sich die Bewohner des Wegekreuzes ausgesetzt?",a="Das Brachland sieht sich ständigen Angriffen durch einheimische Raubtiere, umherstreifende Zentauren, Kriegstrupps der Stacheleber und Übergriffen der Allianz ausgesetzt, was jeden Außenposten zu einer umkämpften Bastion macht, die fähige Verteidiger benötigt.",al={"welche gefahren im brachland","bedrohungen im brachland"}}},fp="25,335,22.324.0,26.328.0,13.222.0,23.260.0,30.167.0,47.209.0,49.199.0,52.195.0"}
P.entries["quest:98025"] = {n="WANTED: Jai'vhanel",s="WANTED: Jai'vhanel ist ein Kopfgeldauftrag der Allianz, der vom Dorfrat von Auberdine an der Dunkelküste ausgehängt wurde. Der Aushang fordert die Beseitigung von Jai'vhanel, einer rasenden schwarzen Eule, die als „Schwertfeder“ bekannt ist und begonnen hat, Reisende entlang der Straße nahe Auberdine aus dem Hinterhalt anzugreifen. Abenteurer müssen die Kreatur nahe den Ruinen von Ameth'Aran jagen und Schildwache Glynda Nal'Shea einen Beweis für ihren Tod bringen.",h="WANTED: Jai'vhanel ist ein Kopfgeldauftrag der Allianz, der vom Dorfrat von Auberdine an der Dunkelküste...",kw={"ameth'aran","auberdine","schwarze eule","dunkelküste","glynda nal'shea","jai'vhanel","schwertfeder","wanted: jai'vhanel"},ang={["class:Druid"]="Nachtelfendruiden beobachten die Tierwelt der Dunkelküste aufmerksam, weshalb der plötzliche Wahnsinn und die Aggression eines edlen Vogels wie Jai'vhanel eine besorgniserregende ökologische Störung darstellen.",["class:Hunter"]="Dieser wilde, pechschwarze Greifvogel, der als Schwertfeder bekannt ist, ist ein aggressiver Lauerjäger nahe den Bergen der Dunkelküste, dessen Jagdgewohnheiten auf tödliche Weise unberechenbar geworden sind.",["faction:Alliance"]="Der Dorfrat von Auberdine verlässt sich auf Abenteurer der Allianz und Nachtelfenschildwachen, um die lebenswichtigen Küstenstraßen der Dunkelküste vor rasenden Raubtieren zu schützen."},sec={{t="Eine Bedrohung auf der Straße",b="Ein Aushang des Dorfrats von Auberdine warnt Reisende entlang der Küstenstraßen der Dunkelküste vor einer gefährlichen Bedrohung. Eine bekannte einheimische Eule namens Jai'vhanel, die den Beinamen „Schwertfeder“ trägt, ist einem plötzlichen Wahnsinn verfallen. Anstatt in der dichten Wildnis zu bleiben, hat sie begonnen, Reisende und Kuriere nahe Auberdine aus dem Hinterhalt anzugreifen, wodurch sich ein gewöhnliches Raubtier der Wälder in eine ernste Gefahr für die Siedlung verwandelt hat."},{t="Das Kopfgeld des Rates",b="Um die Sicherheit der Straßen zu gewährleisten, hat der Rat ein offenes Kopfgeld auf Jai'vhanel ausgesetzt. Jäger werden angewiesen, den schwarzgefiederten Greifvogel zu seinen Jagdgründen nördlich der Ruinen von Ameth'Aran entlang des Bergfußes zu verfolgen. Jäger müssen Schildwache Glynda Nal'Shea in Auberdine eine ihrer markanten pechschwarzen Federn bringen, um den Abschuss zu bestätigen und ihre Belohnung einzustreichen."}},faq={{q="Wer ist Jai'vhanel?",a="Jai'vhanel, auch bekannt unter dem Beinamen „Schwertfeder“, ist eine große Eule, die sich durch ihre pechschwarzen Federn auszeichnet. Normalerweise eine wilde, in den Wäldern der Dunkelküste heimische Kreatur, ist sie dem Wahnsinn verfallen und gegenüber Reisenden aggressiv feindselig geworden.",al={"wer ist jaivhanel","was ist jaivhanel","wer ist schwertfeder"}},{q="Warum ist ein Kopfgeld auf Jai'vhanel ausgesetzt?",a="Der Dorfrat von Auberdine hat ein offizielles Kopfgeld auf Jai'vhanel ausgesetzt, weil sie den Verstand verloren hat und begann, Reisende auf der Hauptstraße nahe Auberdine anzugreifen, was eine schwere Gefahr für den örtlichen Reiseverkehr darstellt.",al={"warum jaivhanel toeten","warum gibt es ein kopfgeld auf jaivhanel","warum wird die eule angegriffen"}},{q="Wo ist Jai'vhanel zu finden?",a="Jai'vhanel wurde zuletzt nördlich der uralten Ruinen von Ameth'Aran an der Dunkelküste gesichtet, wo sie nahe dem Fuß der östlichen Berge umherstreift.",al={"wo ist jaivhanel","jaivhanel aufenthaltsort","wo man schwertfeder findet"}},{q="Wer hat das Kopfgeld auf Jai'vhanel ausgesetzt?",a="Das Kopfgeld wurde vom Dorfrat von Auberdine ausgesetzt, der die zivile Sicherheit und das örtliche Wohl der Küstensiedlung sowie der umliegenden Straßen überwacht.",al={"wer hat das kopfgeld ausgesetzt","wer will jaivhanel tot sehen"}},{q="Wer nimmt die Belohnung für Jai'vhanel entgegen?",a="Kopfgeldjäger müssen Schildwache Glynda Nal'Shea, die in der Stadt Auberdine stationiert ist, eine von Jai'vhanels pechschwarzen Federn als Beweis für ihr Ableben vorlegen.",al={"wer nimmt den todesbeweis entgegen","wo man die feder von jaivhanel abgibt","kopfgeld von glynda nalshea"}},{q="Welcher Beweis wird benötigt, um das Kopfgeld einzufordern?",a="Jeder, der das Kopfgeld des Rates einfordern will, muss eine von Jai'vhanels unverkennbaren pechschwarzen Federn beschaffen und vorlegen, um zu beweisen, dass der rasende Vogel getötet wurde.",al={"was ist der todesbeweis fuer jaivhanel","welcher gegenstand beweist dass jaivhanel tot ist"}}},fp="18,379,20.436.0,20.388.0,18.249.0,36.208.0,30.132.0,36.150.0,39.154.0,41.148.0"}
P.entries["quest:98042"] = {n="It's All Fun and Games Until...",s="It's All Fun and Games Until... ist eine Quest, die sich um eine zutiefst beunruhigende Entdeckung dreht, die Thundris vorgelegt wird. Thundris erkennt das unverkennbare Zeichen eines uralten Bösen und veranlasst, dass das Relikt zur weiteren Untersuchung unverzüglich nach Darnassus geschickt wird.",h="It's All Fun and Games Until...",kw={"uraltes boese","ande'thoras-ethil","darnassus","zeichen eines uralten boesen","nachtelf","thundris"},ang={["faction:Alliance"]="Abenteurer der Allianz, die den Obrigkeiten der Nachtelfen beunruhigende Entdeckungen vorlegen, tragen dazu bei, dass gefährliche Relikte von Gelehrten aus Darnassus untersucht und eingedämmt werden.",["race:NightElf"]="Die Untersuchung berührt unmittelbar die Wachsamkeit der Nachtelfen gegenüber uralter Verderbnis und veranlasst ein sofortiges Eingreifen von Darnassus."},sec={{t="Ein beunruhigender Bericht",b="Eine beunruhigende Entdeckung führt einen Abenteurer zu Thundris, um Rat in einer verstörenden Angelegenheit zu suchen. Nachdem Thundris den Bericht des Abenteurers gehört und das Vorgelegte inspiziert hat, verfällt er in ein stilles Nachdenken und erkennt finstere Zeichen, die man nicht leichthin abtun kann."},{t="Das Zeichen uralten Bösen",b="Bei genauer Untersuchung der Angelegenheit erkennt Thundris das unverkennbare Zeichen eines uralten Bösen, das der Entdeckung anhaftet. In dem Wissen, dass die Gefahr weit über ein lokales Missgeschick hinausgeht, beschließt Thundris, das Relikt unverzüglich nach Darnassus zu entsenden und es den Gelehrten und Priestern der Hauptstadt für gründliche Untersuchungen und die Eindämmung anzuvertrauen."}},faq={{q="Wer ist am Abschluss dieser Quest beteiligt?",a="Die Quest wird zu Thundris gebracht und bei ihm abgeschlossen, der dem besorgten Abenteurer zuhört und den vorgelegten Gegenstand oder Beweis prüft, bevor er ihn für den Transport vorbereitet.",al={"wer vergibt its all fun and games until","thundris quest","wer gibt its all fun and games until ab"}},{q="Warum wird der Gegenstand nach Darnassus geschickt?",a="Thundris stellt fest, dass das Artefakt oder der Fund das Zeichen eines uralten Bösen trägt. Thundris sagt, er werde dafür sorgen, dass es für weitere Untersuchungen unverzüglich nach Darnassus gebracht wird, und er sagt nicht mehr als das.",al={"warum nach darnassus schicken","darnassus untersuchung","uraltes boese darnassus"}},{q="Welches uralte Böse meint Thundris?",a="Thundris stellt fest, dass der Fund das Zeichen eines uralten Bösen trägt, wenngleich konkrete Details zu dessen genauer Herkunft bis zu einer genaueren Untersuchung in der Hauptstadt der Nachtelfen unter Verschluss bleiben.",al={"was ist das uralte boese","zeichen eines uralten boesen bedeutung"}},{q="Was bedeutet „Ande'thoras-ethil“?",a="„Ande'thoras-ethil“ ist eine darnassische Phrase, die Thundris ausspricht, als er das Gespräch mit Euch beendet, nachdem er gesagt hat, dass der Fund nach Darnassus gebracht wird.",al={"bedeutung von ande'thoras-ethil","andethoras ethil nachtelfen ausspruch","darnassischer abschiedsgruss thundris"}},{q="Was geschieht nach dem Abschluss der Quest?",a="Nach der Enthüllung der uralten Verderbnis bereitet Thundris das beunruhigende Relikt für den sofortigen Transport nach Darnassus vor, damit Gelehrte in der Hauptstadt es untersuchen können.",al={"was passiert nach its all fun and games until","folgequest nach fun and games","to darnassus folgequest"}},{q="Welche Fraktion befasst sich mit dieser Untersuchung?",a="Die Angelegenheit wird von der Führung Darnassus' und Nachtelfengestalten wie Thundris gehandhabt und konzentriert sich auf Bedrohungen, die den Obrigkeiten der Nachtelfen vorgelegt werden.",al={"ist its all fun and games nur allianz","wer kann its all fun and games until annehmen"}}},fp="31,248,18.272.0,24.322.1,41.170.0,42.196.0,48.187.0,35.146.0,40.170.0,41.160.0"}
P.entries["quest:98046"] = {n="Crown of the Earth",s="Crown of the Earth ist eine Quest in Darnassus, die beginnt, als Erzdruide Fandral Hirschhaupt eine fehlgeschlagene Beschwörung mit einer Phiole voller Wasser abbricht. Vom frustrierten Erzdruiden weggeschickt, wird der Abenteurer damit beauftragt, das Ausgelaugte Gefäß zur Entsorgung zu Priestess Lariia im Tempel des Mondes zu bringen. Bei der Untersuchung der Phiole bemerkt die Priesterin jedoch, dass sich noch immer etwas Wasser darin befindet, was Zweifel daran aufkommen lässt, warum das Ritual wirklich fehlschlug.",h="Crown of the Earth ist eine Quest in Darnassus, die beginnt, als Erzdruide Fandral Hirschhaupt eine...",kw={"zirkel des cenarius","crown of the earth","darnassus","ausgelaugtes gefäß","elune","fandral hirschhaupt","lariia","malfurion","tempel des mondes"},ang={["class:Druid"]="Fandral spricht den Abenteurer ausdrücklich als Druidenkollegen an und behandelt das Scheitern des Rituals mit kurz angebundener Ungeduld, ehe er ihn aus seiner Gegenwart entlässt.",["faction:Alliance"]="Die Quest verdeutlicht die stillen Spannungen in der Führung von Darnassus, der wichtigsten Hauptstadt der Allianz auf Kalimdor, während Malfurion Sturmgrimm abwesend bleibt.",["race:NightElf"]="Der Botengang offenbart die alltäglichen Spannungen in Darnassus und stellt Fandral Hirschhaupts gereizte Autorität der geduldigen Hingabe der The Sisterhood of Elune im Tempel des Mondes gegenüber."},sec={{t="Fandrals Frustration",b="In Darnassus trägt Erzdruide Fandral Hirschhaupt die Verantwortung für die Führung der Nachtelfen, während Malfurion Sturmgrimm abwesend bleibt. Auf seiner Suche nach Antworten versucht Fandral eine Beschwörung mit heiligem Wasser aus einer Phiole. Als der Ritus scheinbar keine Ergebnisse liefert, verliert der Erzdruide die Beherrschung. Davon überzeugt, dass das Wasser nutzlos ist, fertigt er den Abenteurer mit schroffen Worten ab und weist ihn an, das Ausgelaugte Gefäß nach Süden zum Tempel des Mondes zu bringen, damit die Priesterinnen es entsorgen können."},{t="Die verbliebenen Tropfen",b="Nach der Ankunft im Tempel des Mondes bietet Priestess Lariia eine sanftere Sicht der Dinge und bittet den Abenteurer, sich angesichts der schweren Last, die Fandral trägt, nicht an dessen schroffer Art zu stören. Doch als sie die Phiole inspiziert, bemerkt sie etwas, das dem Erzdruiden in seiner Eile entgangen war: Mehrere Wassertropfen befinden sich noch immer darin. Dieser verbliebene Rückstand lässt die deutliche Möglichkeit aufkommen, dass Fandrals Ritual nicht an fehlerhafter Magie scheiterte, sondern daran, dass das Gefäß nicht ordnungsgemäß geleert worden war."}},faq={{q="Wer vergibt die Quest Crown of the Earth?",a="Die Quest wird von Erzdruide Fandral Hirschhaupt in Darnassus vergeben. Fandral, der derzeit in Abwesenheit von Malfurion Sturmgrimm den Zirkel des Cenarius leitet, erteilt die Aufgabe in einem plötzlichen Anflug von Frustration, nachdem eine Beschwörung mit heiligem Wasser nicht die von ihm erhofften Antworten lieferte.",al={"wer startet crown of the earth","questgeber für crown of the earth","fandral-quest"}},{q="Wohin bringt Ihr das Ausgelaugte Gefäß?",a="Ihr bringt das Ausgelaugte Gefäß zu Priestess Lariia im Tempel des Mondes im Süden von Darnassus. Fandral befiehlt Euch, es zu übergeben, damit die Priesterinnen von Elune es entsorgen können, da er davon ausgeht, dass der verbrauchte Behälter zu nichts mehr zu gebrauchen ist.",al={"wohin mit ausgelaugtem gefäß","abgabe ausgelaugtes gefäß","wo ist lariia"}},{q="Warum ist Fandral Hirschhaupt so frustriert?",a="Erzdruide Fandral Hirschhaupt steht unter erheblichem Druck, während Malfurion Sturmgrimm fort ist und er die Nachtelfen sowie den Zirkel des Cenarius anführt. Als seine magische Beschwörung nichts einbringt, lassen seine Verärgerung und sein Stolz ihn die Beherrschung verlieren und den Abenteurer schnell wegschicken, anstatt dem Fehlschlag genauer auf den Grund zu gehen.",al={"warum ist fandral wütend","fandrals verhalten","warum ist fandral ungeduldig"}},{q="Warum schlug Fandrals Beschwörung fehl?",a="Fandral Hirschhaupt nimmt an, dass dem Wasser selbst jegliche nützliche Kraft fehlte, doch Priestess Lariia bemerkt ein entscheidendes Detail, als sie das Gefäß entgegennimmt. Mehrere Wassertropfen haften noch immer an der Innenseite, was darauf hindeutet, dass die Beschwörung schlicht daran gescheitert sein könnte, dass das Gefäß während des Ritus nicht vollständig geleert wurde.",al={"warum schlug die beschwörung fehl","hat fandrals ritual funktioniert","fehlgeschlagene beschwörung"}},{q="Wo ist Malfurion während dieser Quest?",a="Malfurion Sturmgrimm ist derzeit nicht in Darnassus anwesend, sodass die Führung des Zirkels des Cenarius und die Leitgewalt über die Nachtelfen bei Erzdruide Fandral Hirschhaupt liegen. Diese Abwesenheit bürdet Fandral eine schwere Bürde auf und trägt zu seinem aufbrausenden Temperament und seiner Ungeduld bei Rückschlägen bei.",al={"wo ist malfurion","warum ist malfurion abwesend","status von malfurion"}},{q="Wer ist Priestess Lariia?",a="Priestess Lariia ist eine Nachtelfendienerin von Elune, die im Tempel des Mondes in Darnassus stationiert ist. Sie nimmt das Gefäß vom Abenteurer entgegen und zeigt Mitgefühl angesichts von Fandrals schwerer Verantwortung, während sie scharfsinnig erkennt, dass das Gefäß noch Reste von Wasser enthält.",al={"wer ist lariia","wissen über priesterin lariia","lariia tempel des mondes"}}},fp="18,440,21.512.0,19.479.1,39.284.0,37.232.0,38.307.0,35.304.0,37.287.0,24.283.0"}
P.entries["quest:98065"] = {n="Crown of the Earth",s="Crown of the Earth ist eine Quest in Darnassus, bei der Abenteurer gereinigte Mondbrunnenüberreste zu Hohepriesterin Tyrande Wisperwind bringen. Die Begegnung, die im Tempel des Mondes stattfindet, offenbart die heilige Bedeutung des Wassers von Elune und die wachsenden politischen Spannungen zwischen Tyrande und Erzdruide Fandral Hirschhaupt.",h="Crown of the Earth ist eine Quest in Darnassus, bei der Abenteurer gereinigte Mondbrunnenüberreste zu...",kw={"crown of the earth","darnassus","elune","fandral hirschhaupt","malfurion","mondbrunnenüberreste","tempel des mondes","tyrande wisperwind"},ang={["class:Druid"]="Tyrandes scharfe Worte bezüglich Erzdruide Fandral Hirschhaupt unterstreichen die wachsenden Reibungen innerhalb des Zirkels des Cenarius in Malfurions Abwesenheit.",["class:Priest"]="Der Dienst an Hohepriesterin Tyrande Wisperwind bestärkt die lebenswichtige Rolle, die Elunes Geistlichkeit bei der Führung und Leitung der Gesellschaft der Nachtelfen einnimmt.",["faction:Alliance"]="Eine Audienz bei der Anführerin von Darnassus zu erhalten, gewährt einen Einblick in die inneren politischen Spannungen, denen eine der wichtigsten Hauptstädte der Allianz gegenübersteht.",["race:NightElf"]="Die direkte Übergabe des heiligen Mondbrunnenwassers verdeutlicht die doppelte Führung der Kaldorei, die zwischen Tyrandes Priesterschaft und Fandrals Druiden gefangen ist."},sec={{t="Audienz bei der Hohepriesterin",b="Nachdem sie die heiligen Mondbrunnenüberreste gesammelt haben, werden Abenteurer angewiesen, das gesegnete Wasser in ein zeremonielles Gefäß umzufüllen und es direkt zu Tyrande Wisperwind zu bringen. Die Hohepriesterin von Elune weilt hoch oben im Tempel des Mondes in Darnassus, wacht über die Stadt und spendet allen, die eintreten, das Licht ihrer Göttin. Derart heiliges Wasser in ihre Obhut zu übergeben, gilt als Ehre und als ein Akt der Hingabe an Elune."},{t="Spannungen in der Führung",b="Nach Erhalt der Überreste drückt Tyrande tiefe Dankbarkeit für die Rettung des gesegneten Wassers aus, doch ihre Gedanken wenden sich schnell den politischen Belastungen zu, die Darnassus im Griff haben. In Abwesenheit von Malfurion Sturmgrimm hat Erzdruide Fandral Hirschhaupt das Kommando über die druidischen Angelegenheiten übernommen, doch Tyrande stellt unmissverständlich klar, dass die Führung der Kaldorei allein ihre Bürde ist. Obwohl sie zu Respekt vor Hirschhaupts Stellung mahnt, offenbart der Austausch deutliche Reibungen zwischen The Sisterhood of Elune und dem Zirkel des Cenarius."}},faq={{q="Was ist Crown of the Earth?",a="Crown of the Earth ist eine Quest in Darnassus, bei der ein Abenteurer einen zeremoniellen Behälter mit Mondbrunnenüberresten zu Hohepriesterin Tyrande Wisperwind in den Tempel des Mondes bringt. Sie markiert einen Moment der direkten Zwiesprache mit der obersten Anführerin der Nachtelfen.",al={"was ist crown of the earth","quest crown of the earth"}},{q="Wer ist Tyrande Wisperwind?",a="Tyrande Wisperwind ist die Hohepriesterin von Elune und die politische Anführerin der Nachtelfen. Sie wacht von der oberen Ebene des Tempels des Mondes aus über Darnassus und trägt die Bürde, ihr Volk durch unruhige Zeiten zu führen.",al={"wer ist tyrande wisperwind","wo ist tyrande","hohepriesterin tyrande"}},{q="Warum werden die Mondbrunnenüberreste zu Tyrande gebracht?",a="Die Mondbrunnenüberreste bestehen aus heiligem, von Elune gesegnetem Wasser. Angesichts seiner heiligen Natur wird es in ein zeremonielles Gefäß umgefüllt und zu Tyrande gebracht, damit sie es im Namen der Göttin empfangen und behüten kann.",al={"warum mondbrunnenüberreste zu tyrande bringen","was sind mondbrunnenüberreste","heiliges wasser darnassus"}},{q="Was ist der Streit zwischen Tyrande und Fandral Hirschhaupt?",a="Während Malfurion Sturmgrimm abwesend ist, führt Erzdruide Fandral Hirschhaupt die Druiden an, doch Tyrande beharrt fest darauf, dass die Regierung von Darnassus und die Führung der Kaldorei allein ihre Verantwortung bleiben, und weigert sich zuzulassen, dass die druidische Autorität die Priesterschaft von Elune in den Schatten stellt.",al={"spannung tyrande fandral","warum mag tyrande hirschhaupt nicht","fandral gegen tyrande"}},{q="Wo ist Malfurion während dieser Quest?",a="Malfurion Sturmgrimm ist derzeit nicht in Darnassus anwesend, was ein Führungsvakuum unter den Druiden hinterlässt, in das Erzdruide Fandral Hirschhaupt getreten ist, was die politischen Spannungen mit Tyrande verschärft.",al={"wo ist malfurion","was geschah mit malfurion","malfurions abwesenheit"}},{q="Wo befindet sich der Tempel des Mondes?",a="Der Tempel des Mondes befindet sich im Herzen von Darnassus. Er dient als wichtigstes Heiligtum für The Sisterhood of Elune, wobei Tyrande auf der oberen Ebene direkt über dem Hauptbereich des Heiligtums Audienz gewährt.",al={"standort des tempels des mondes","wo ist der tempel des mondes","wo man tyrande findet"}}},fp="18,325,32.433.0,22.494.1,27.258.0,27.229.0,49.219.0,57.257.0,37.201.0,32.214.0"}
P.entries["quest:98067"] = {n="Eyes of the Sentinels",s="Eyes of the Sentinels ist eine Quest in Darnassus, bei der Spieler Sentinel Dalia Sunblade dabei unterstützen, magische Spähereulen an entscheidenden Posten in der gesamten Hauptstadt der Nachtelfen zu stationieren. Angesichts wachsender Unruhe auf ganz Teldrassil stärkt diese Luftüberwachung die Verteidigung der Stadt, während sie den Schildwachen Zeit für Gebete an Elune verschafft.",h="Eyes of the Sentinels ist eine Quest in Darnassus, bei der Spieler Sentinel Dalia Sunblade dabei...",kw={"burg cenarius","craftsman's terrace","dalia sunblade","darnassus","elune","eyes of the sentinels","mondfeder","schildwacheneulen","teldrassil","tempel des mondes"},ang={["class:Hunter"]="Der Einsatz von Spähereulen spiegelt die klassische Aufklärung der Nachtelfen wider, bei der dressierte Bestien und himmlische gefiederte Wächter als natürliche Erweiterung der Sinne einer Jägerin dienen.",["class:Priest"]="Die Schildwachen betonen, dass Waffen allein die Kaldorei nicht schützen; regelmäßiges Gebet und die spirituellen Gaben von Elune sind für ihre Wacht unerlässlich.",["faction:Alliance"]="Die Gewährleistung der Sicherheit von Darnassus schützt die Hauptstadt der Nachtelfen und stärkt die wichtigste Festung der Allianz im nördlichen Kalimdor.",["race:NightElf"]="Die Schildwachen sind das traditionelle stehende Heer und die Beschützer des Volkes der Nachtelfen, die kriegerisches Können mit den göttlichen Segnungen und wachsamen Augen von Elune verbinden."},sec={{t="Hingabe und Verteidigung",b="Im heiligen Refugium des Tempels des Mondes hält Sentinel Dalia Sunblade die Wacht über Darnassus. Geleitet vom Erlass von Generalin Shandris Mondfeder, dass jeder Krieger kriegerisches Können mit spiritueller Hingabe verbinden muss, veranlasst Dalia die Aufstellung wachsamer Schildwacheneulen an zentralen Knotenpunkten der Stadt. Die Übernahme dieser täglichen Pflichten gewährt der Schildwache wertvolle Momente des Gebets und des Nachdenkens vor der Mondgöttin, während gleichzeitig sichergestellt wird, dass die Hauptstadt der Kaldorei streng bewacht bleibt."},{t="Wacht über Darnassus",b="Unruhe liegt in der Luft über Teldrassil und veranlasst die Schildwachen, ihre Wachsamkeit zu verdoppeln. Um sich gegen Infiltration und Unruhen zu wappnen, werden Schildwacheneulen an entscheidenden Knotenpunkten stationiert: in den Tiefen unter der Burg Cenarius im Norden, der belebten Bank auf dem Stadtplatz, dem Gasthaus auf der Craftsman's Terrace und den Haupttoren der Stadt. Da die örtlichen Stadtwachen bei ihrer Platzierung behilflich sind, fungieren diese gefiederten Wächter als stille Schützer, die über alle wachen, die die Straßen des Großen Baumes beschreiten."}},faq={{q="Was ist Eyes of the Sentinels?",a="Eyes of the Sentinels ist eine Aufgabe in Darnassus, bei der ein Abenteurer Sentinel Dalia Sunblade unterstützt, indem er Schildwacheneulen an wichtigen Orten in der Stadt aufstellt, um die Wachsamkeit gegenüber drohenden Gefahren aufrechtzuerhalten.",al={"quest eyes of the sentinels","was ist eyes of the sentinels","übersicht zu eyes of the sentinels"}},{q="Wer ist Sentinel Dalia Sunblade?",a="Sentinel Dalia Sunblade ist eine kaldoreische Beschützerin, die im Tempel des Mondes in Darnassus stationiert ist, wo sie die örtlichen Verteidigungsabläufe beaufsichtigt und dafür sorgt, dass wachsame Eulen die wichtigsten Durchgangsstraßen der Stadt bewachen.",al={"wer ist dalia sunblade","dalia sunblade lore","sentinel dalia sunblade"}},{q="Warum werden Schildwacheneulen in Darnassus platziert?",a="Schildwacheneulen dienen als wachsame Luftspäher und göttliche Kundschafter, die von Elune gewährt wurden und es den Schildwachen ermöglichen, entscheidende Sammelpunkte und Verkehrsengpässe in ganz Darnassus zu überwachen.",al={"warum schildwacheneulen platzieren","was machen schildwacheneulen","zweck der schildwacheneulen"}},{q="Wo werden die Schildwacheneulen platziert?",a="Die Schildwacheneulen werden am Eingang zu den Tiefen unter der Burg Cenarius im Norden, der Bank von Darnassus im Stadtzentrum, dem Gasthaus auf der Craftsman's Terrace und den Stadttoren aufgestellt.",al={"orte für eulenplatzierung","wohin kommen die eulen","orte in eyes of the sentinels"}},{q="Warum sind die Schildwachen auf Teldrassil in höchster Alarmbereitschaft?",a="Sentinel Dalia Sunblade bemerkt, dass auf dem gesamten Weltenbaum Teldrassil etwas nicht stimmt, was die Schildwachen dazu veranlasst, die Überwachung zu verstärken und ständige Einsatzbereitschaft gegenüber ungesehenen Gefahren aufrechtzuerhalten.",al={"warum sind schildwachen besorgt","was stimmt nicht mit teldrassil","teldrassil stimmt etwas nicht"}},{q="Welche Rolle spielt Generalin Mondfeder bei den täglichen Pflichten der Schildwachen?",a="Generalin Shandris Mondfeder befehligt die Schildwachen und stellt sicher, dass ihre Jägerinnen ihre kriegerischen Pflichten mit täglicher Hingabe und Gebeten an die Göttin Elune in Einklang bringen.",al={"rolle von generalin mondfeder","shandris mondfeder schildwachen","mondfeders gebetsregel"}}},fp="21,324,20.489.0,20.490.0,30.201.0,31.195.0,52.188.0,35.188.0,50.197.0,71.175.0"}
P.entries["quest:981"] = {n="Der Turm von Althalaxx",s="Dieser Botengang markiert den triumphalen Abschluss des Feldzugs gegen den Cult of the Dark Strand am Turm von Althalaxx. Nachdem die Führung des Kults in den finsteren Ruinen der Dunkelküste ausgeschaltet wurde, überbringt ein Abenteurer die Nachricht nach Süden ins Eschental zu Delgren dem Läuterer. Dies stellt einen entscheidenden Sieg für die Allianz dar, um die dämonische Verderbnis von den uralten Grenzen der Nachtelfen zu vertreiben.",h="Dieser Botengang markiert den triumphalen Abschluss des Feldzugs gegen den Cult of the Dark Strand am Turm...",kw={"althalaxx","eschental","balthule","kult","dark strand","dunkelküste","delgren","maestras posten"},ang={["class:Paladin"]="Der Bericht an Delgren den Läuterer besitzt für Paladine eine besondere Bedeutung, da sie seine heilige Mission teilen, dämonische Verderbnis und finstere Kulte aus der Welt zu tilgen.",["faction:Alliance"]="Die Beseitigung des Kults sichert die Überlandstraße zwischen der Dunkelküste und Eschental, sodass Späher und Reisende der Allianz vor dämonischen Hinterhalten geschützt sind.",["race:NightElf"]="Für Nachtelfen befreit die Säuberung des Turms von Althalaxx die uralten Hochgeborenen-Ruinen, die ihre heiligen Küstenwälder säumen, von einem abscheulichen Makel."},sec={{t="Eine zerschlagene Bedrohung",b="Der Turm von Althalaxx glich über Wochen einer schwärenden Wunde im Norden der Dunkelküste, besetzt vom fanatischen Cult of the Dark Strand und seinen schattenhaften Meistern. Durch unermüdliche Fährtenlese, Informationsbeschaffung und heftige Scharmützel wurden die Umtriebe des Kults systematisch zerschlagen. Da ihre Zauberer erschlagen und ihre dunklen Rituale gebrochen sind, konnte die unmittelbare Gefahr einer dämonischen Infiltration in der Dunkelküste endlich abgewendet werden."},{t="Bericht an Maestras Posten",b="Nach dem Tod des Kultführers schickt Balthule Schattenhieb den Sieger nach Süden zu Maestras Posten unter dem Blätterdach von Eschental. Dort wartet Delgren der Läuterer, ein ergebener Krieger des Heiligen Lichts, der den Kreuzzug gegen die finsteren Besatzer von Althalaxx leitete. Das Überbringen der Nachricht vom Zusammenbruch des Kults beruhigt die Verteidiger der Region und bringt dem Streiter Delgrens dauerhaften Segen sowie wohlverdiente Dankbarkeit ein."}},faq={{q="Was ist das Ziel dieser Quest?",a="Diese Quest dient als finale Abgabe für die lange Questreihe um den Turm von Althalaxx. Ihr müsst lediglich aus der Umgebung des Turms nach Süden zu Maestras Posten im Eschental reisen und Delgren dem Läuterer von Eurem entscheidenden Sieg berichten.",al={"turm von althalaxx ziel","turm von althalaxx abgeben","wo quest 981 abgeben"}},{q="Wer ist Delgren der Läuterer?",a="Delgren der Läuterer ist ein Champion der Allianz, der an Maestras Posten im nördlichen Eschental stationiert ist. Er führt das Heilige Licht und hat es sich zur Aufgabe gemacht, Verderbnis zu tilgen und dämonische Bedrohungen wie den Cult of the Dark Strand im gesamten nördlichen Kalimdor zu bekämpfen.",al={"wer ist delgren","delgren lore","delgren der läuterer"}},{q="Wer ist Balthule Schattenhieb?",a="Balthule Schattenhieb ist ein Agent der Allianz, der nahe dem Turm von Althalaxx in der Dunkelküste stationiert ist. In enger Zusammenarbeit mit Delgren überwacht er die Bewegungen des Kults und leitet Abenteurer dabei an, die finstere Verschwörung von innen heraus zu zerschlagen.",al={"balthule","balthule lore","wer ist balthule schattenhieb"}},{q="Was trieb der Cult of the Dark Strand an dem Turm?",a="Der Cult of the Dark Strand besetzte die uralten Ruinen des Turms von Althalaxx, um dunkle Rituale zu vollziehen, dämonische Wesenheiten zu beschwören und seinen unheilvollen Einfluss über die Küstengebiete der Dunkelküste auszudehnen.",al={"cult of the dark strand","was geschah bei althalaxx","turm von althalaxx lore"}},{q="Wo befindet sich Maestras Posten?",a="Maestras Posten ist ein Außenposten der Allianz im nordwestlichen Eschental, der direkt südlich des Grenzübergangs von der Dunkelküste entlang der Hauptstraße liegt.",al={"maestras posten standort","wo ist maestras posten","delgren standort"}},{q="Ist der Cult of the Dark Strand vollständig vernichtet?",a="Zwar wurde ihre Führung am Turm von Althalaxx hingerichtet und ihr Hauptritual vereitelt, doch versprengte Kultisten und Überreste suchen noch immer abgelegene Winkel von Kalimdor heim. Ihre organisierte Bedrohung in der Dunkelküste wurde jedoch gebrochen.",al={"ist der kult vernichtet","dark strand vernichtet","wurde der kult getötet"}}},fx={b456cfd7={q="Warum will Balthule Schattenhieb, dass dies erledigt wird?",a="Da der Kult von Dark Strand zerschlagen und seine Führung gebrochen ist, möchte Balthule, dass Ihr die Nachricht vom Sieg zurück zu Delgren der Läuterer tragt. Delgren initiierte den Feldzug gegen die Kultisten, die im Turm lauerten, und Balthule glaubt, dass Eure Bemühungen angemessene Anerkennung und die versprochene Belohnung des Paladins verdienen.",al={"warum schickt ihr mich zurück zu delgren","balthules beweggrund","warum delgren berichten"}}},fp="22,390,16.431.0,24.418.0,31.228.0,28.247.0,29.233.0,56.205.0,32.143.0,52.238.0"}
P.entries["quest:98155"] = {n="Pristine Pesterhide Pelts",s="Pristine Pesterhide Pelts ist eine Aufgabe, die im Auftrag von Kristy Grant übernommen wird, einer Reisenden, die nach den strahlenden Fellen der Pesterhidehyänen in Tausend Nadeln sucht. Da Kristy selbst über keine Kampfausbildung verfügt, verlässt sie sich auf fähige Abenteurer, um die Bestien zu jagen und ihre Bälge zu erbeuten. Ihr Ziel ist es, diese einzigartigen Bälge über das Meer zurück zu ihren Schwestern in Sturmwind zu schicken, wo sie zu feinen Kleidungsstücken und Waren verarbeitet werden können.",h="Pristine Pesterhide Pelts ist eine Aufgabe, die im Auftrag von Kristy Grant übernommen wird, einer Reisenden...",kw={"pelz","jagd","hyäne","kristy grant","bälge","pesterhide","sturmwind","tausend nadeln"},ang={["faction:Alliance"]="Als Unterfangen einer Reisenden aus Sturmwind zur Versorgung ihrer Handwerkerfamilie in der Hauptstadt verdeutlicht diese Aufgabe, wie Untertanen der Allianz tief in die Grenzwelt von Kalimdor vordringen, um exotische Materialien zu beschaffen.",["profession:Tailoring"]="Handwerker, die mit Stoffen und dekorativen Fellen arbeiten, können den Ehrgeiz von Kristys Schwestern schätzen, die wilde Bälge aus Kalimdor in veredelte Kleidungsstücke verwandeln möchten.",["race:Human"]="Kristy Grant veranschaulicht den Unternehmergeist der Menschen aus Sturmwind, die weit über das Meer reisen und dabei enge Bande zu ihrer Verwandtschaft in der Heimat des Königreichs pflegen."},sec={{t="Ein schwesterliches Bestreben",b="Weit entfernt von den belebten, gepflasterten Straßen von Sturmwind reist Kristy Grant durch den trockenen, sonnenverbrannten Schluchtgrund von Tausend Nadeln. Während sie die einheimische Tierwelt beobachtet, fällt ihr die auffällige Färbung und Qualität des Fells der heimischen Pesterhidehyänen ins Auge. In der Erkenntnis, dass solche unverwechselbaren Bälge in den Östlichen Königreichen praktisch unbekannt sind, plant Kristy, eine Lieferung von Bälgen nach Hause zu ihren Schwestern zu schicken. In ihren Augen stellen die Bälge nicht nur ein Stück der Grenzwelt von Kalimdor dar, sondern Rohmaterial, das geschickte Hände ihrer Familie im Königreich in etwas wahrhaft Außergewöhnliches verwandeln können."},{t="Jäger der Salzwüste und Schluchten",b="Trotz ihres Blicks für Handwerk und Handel ist Kristy Grant kein Krieger und verfügt über keinerlei Kampferfahrung, um den wilden Raubtieren der Schlucht selbst entgegenzutreten. Die Pesterhidehyänen sind bösartige Rudelaasfresser, die die staubigen Weiten unterhalb der hoch aufragenden Mesas durchstreifen, was das Erbeuten makelloser Bälge für jeden einsamen Reisenden gefährlich macht. Um sich fünf unversehrte Bälge zu sichern, ohne ihren eigenen Hals zu riskieren, nimmt Kristy die Hilfe erfahrener Abenteurer in Anspruch, die die Nadeln durchqueren. Die Aufgabe erfordert es, sich in die Wildnis hinauszuwagen, die territorialen Bestien zu bezwingen und sorgfältig die Bälge zu sammeln, die für die handwerklichen Unternehmungen ihrer Familie in der Heimat benötigt werden."}},faq={{q="Wer ist Kristy Grant?",a="Kristy Grant ist eine Reisende aus dem Königreich Sturmwind, die derzeit durch Kalimdor zieht. Anders als die abgehärteten Soldaten und Mercenaries, die Tausend Nadeln durchqueren, gibt sie zu, selbst keinerlei Kampferfahrung zu besitzen. Stattdessen verlässt sie sich auf ihre scharfe Beobachtungsgabe und ein Auge für wertvolle Handwerksmaterialien und heuert fähige Abenteurer an, um Waren wie Hyänenbälge in ihrem Auftrag zu beschaffen.",al={"kristy grant lore","wer vergibt makellose pesterhidebälge","wer ist kristy grant"}},{q="Was sind Pesterhidehyänen?",a="Pesterhidehyänen sind wilde hundeartige Raubtiere, die auf den trockenen Schluchtgründen und Weiten von Tausend Nadeln heimisch sind. Sie durchstreifen das unwirtliche Terrain und jagen und suchen im Rudel nach Aas. Abgesehen von ihrer bösartigen Natur zeichnen sie sich durch ihr leuchtendes, wunderschön gefärbtes Fell aus, das sich deutlich vom Wüstengestein abhebt und die Aufmerksamkeit reisender Schneider und Kürschner auf sich zieht.",al={"pesterhidehyäne","tausend nadeln hyänen","was sind pesterhides"}},{q="Warum möchte Kristy Grant die Bälge?",a="Kristy Grant möchte makellose Hyänenbälge sammeln, um sie über das Meer zu ihren Schwestern im Königreich Sturmwind zu schicken. Sie ist von der leuchtenden Färbung ihres Fells vollauf beeindruckt und glaubt, dass ihre Schwestern das handwerkliche Geschick besitzen, um die exotischen Felle zu unglaublichen Fertigwaren zu weben oder schneidern.",al={"warum pesterhidebälge sammeln","zweck der pesterhidebälge","was macht kristy mit den bälgen"}},{q="Wohin gelangen die Bälge?",a="Die in Tausend Nadeln gesammelten Bälge sind für die Östlichen Königreiche bestimmt, genauer gesagt für das Stadtkönigreich Sturmwind. Kristy beabsichtigt, die erbeuteten Bälge über das große Meer nach Hause zu verschiffen, damit ihre Schwestern mit exotischen Materialien arbeiten können, die in den vertrauten Wäldern von Elwynn oder dem Rotkammgebirge praktisch unerreichbar sind.",al={"wohin werden die bälge geschickt","bälge sturmwind","wer bekommt die hyänenbälge"}},{q="Warum kann Kristy die Hyänen nicht selbst jagen?",a="Kristy Grant gibt offen zu, dass sie überhaupt keine Kampferfahrung besitzt. Den wilden Bestien von Tausend Nadeln zu begegnen, ist aggressiv und gefährlich, insbesondere für eine unbewaffnete Kunsthandwerkerin oder Reisende. Anstatt bei den umherstreifenden Hyänenrudeln Verletzungen oder den Tod zu riskieren, heuert sie geschickte Wanderer an, um die Tiere gefahrlos zu jagen.",al={"warum kann kristy nicht kämpfen","kristy grant kampf","warum braucht kristy hilfe"}},{q="Was macht diese Bälge makellos?",a="Da die Bälge für feines Handwerk und Mode durch Kristys Schwestern in Sturmwind bestimmt sind, genügen gewöhnliche oder zerfetzte Felle nicht. Nur unbeschädigte, makellose Bälge bewahren den lebendigen Farbton und die Textur, die für die Herstellung hochwertiger Kleidungsstücke erforderlich sind, sodass sorgfältig gejagt und nur die besten Exemplare von den Bestien geborgen werden müssen.",al={"bedeutung makelloser bälge","warum makellose bälge","qualität makelloser pesterhidebälge"}}},fp="25,416,19.626.0,37.648.0,20.388.0,27.373.0,37.309.0,26.326.0,41.329.0,32.339.0"}
P.entries["quest:98190"] = {n="A Friend of the Family",s="A Friend of the Family ist ein dringender Kurierauftrag aus dem Hafen von Menethil im Sumpfland. Aus Furcht vor lokalen Bedrohungen wie den Orcs des Dragonmaw-Klans vertraut die Hafenführung einem Abenteurer an, die unbezahlbare Statuette von Menethil direkt zu Hochlord Bolvar Fordragon in Burg Sturmwind zu bringen.",h="A Friend of the Family ist ein dringender Kurierauftrag aus dem Hafen von Menethil im Sumpfland.",kw={"bolvar","dragonmaw","fordragon","hafen","menethil","statuette","sturmwind","terenas","sumpfland"},ang={["class:Paladin"]="Der Name Menethil erinnert an den Gründungspatron der Ritter der Silbernen Hand, was die Bewahrung dieses Relikts für jeden heiligen Krieger zu einer feierlichen Pflicht macht.",["faction:Alliance"]="Die Übergabe des Relikts ehrt die historische nördliche Allianz und hält ein unschätzbares Symbol fern von den Fängen des Dragonmaw-Klans.",["race:Human"]="Für Menschen bewahrt der Schutz eines Artefakts der Menethil-Dynastie die stolze, tragische Erinnerung an das gefallene Lordaeron und bestärkt Sturmwinds Pflicht als letztes großes Menschenkönigreich."},sec={{t="Ein gefährdeter Hafen",b="Der Hafen von Menethil dient als entscheidendes maritimes Tor, das die nördlichen Gefilde der Östlichen Königreiche mit dem Süden verbindet. Benannt zu Ehren des verstorbenen Königs Terenas Menethil II. von Lordaeron, liegt der Hafen isoliert inmitten tückischer Sümpfe und aggressiver Feinde. Angesichts wachsender lokaler Gefahren erkennt die Hafenführung, dass unbezahlbare Relikte des gefallenen nördlichen Königreichs in einem derart exponierten Außenposten nicht sicher aufbewahrt werden können."},{t="Die Dragonmaw-Bedrohung",b="Das Sumpfland wird weiterhin von Überresten des Dragonmaw-Klans heimgesucht, wilden Orcs, die für ihre finstere Vergangenheit und ihren skrupellosen Opportunismus bekannt sind. Angesichts ihrer Nähe und ihres Eroberungsdrangs fürchten die Verteidiger des Hafens, dass der Dragonmaw-Klan vor nichts zurückschrecken würde, um historische Schätze wie die Statuette von Menethil zu plündern, und ein solches Symbol möglicherweise für eigene Zwecke schänden oder instrumentalisieren könnte."},{t="Direkt zum Hochlord",b="Anstatt Verzögerungen über die üblichen bürokratischen oder militärischen Wege zu riskieren, wird der Bote angewiesen, die Befehlskette gänzlich zu umgehen. Das Relikt wird direkt nach Burg Sturmwind in die Hände von Hochlord Bolvar Fordragon geschickt, dem Regenten des jungen Königs Anduin Wrynn, im Vertrauen darauf, dass die Führung in der Hauptstadt ein Stück des Erbes von Lordaeron am besten schützen kann."}},faq={{q="Was ist die Statuette von Menethil?",a="Die Statuette von Menethil ist ein wertvolles Erbstück, das mit der königlichen Linie von Lordaeron und König Terenas Menethil II. verbunden ist. Sie repräsentiert die historischen Bande zwischen dem nördlichen Königreich und der Allianz, was sie zu einem Ziel für Plünderer und Feinde macht.",al={"menethil relikt","was ist die statuette","hintergrund der statuette"}},{q="Warum kann die Statuette nicht im Hafen von Menethil bleiben?",a="Der Hafen von Menethil ist isoliert und von feindseligen Sümpfen, Dunkeleisenzwergen, Murlocs und aggressiven Orcs umgeben. Die Garnison hält die Siedlung für viel zu verwundbar, um ein so bedeutendes Relikt sicher zu schützen.",al={"warum die statuette verlegt wird","ist der hafen von menethil unsicher"}},{q="Wer sind die Dragonmaw und warum wollen sie die Statuette?",a="Der Dragonmaw-Klan ist eine Fraktion von Orcs, die sich im Sumpfland festgesetzt hat. Hafenbeamte sorgen sich, dass sie bereitwillig Krieger opfern würden, um prestigeträchtige Allianz-Relikte zu erbeuten und sie potenziell zu entweihen oder bösartig einzusetzen.",al={"dragonmaw-bedrohung","warum orcs die statuette wollen"}},{q="Warum wird das Relikt direkt an Bolvar Fordragon übergeben?",a="Als Regent von Sturmwind und Beschützer des jungen Königs Anduin besitzt Hochlord Bolvar Fordragon die höchste vollziehende Gewalt in der Hauptstadt. Die direkte Übergabe an ihn stellt sicher, dass bürokratischer Stillstand vermieden wird und maximale Sicherheit gewährleistet ist.",al={"warum bolvar","warum befehlskette umgehen"}},{q="Wo befindet sich Hochlord Bolvar Fordragon?",a="Hochlord Bolvar Fordragon steht im Thronsaal von Burg Sturmwind an der Seite des Knabenkönigs Anduin Wrynn.",al={"bolvars aufenthaltsort","wo ist bolvar"}},{q="Wie ist der Hafen von Menethil mit König Terenas verbunden?",a="Der Hafen von Menethil wurde als Tribut an König Terenas Menethil II. benannt, der Lordaeron anführte und die Allianz von Lordaeron durch den Zweiten Krieg hindurch unterstützte, bevor er während des Dritten Krieges tragisch starb.",al={"warum hafen von menethil","verbindung zu terenas menethil"}}},fx={ece51c60={q="Warum seid Ihr auserwählt, die Statuette von Menethil nach Sturmwind zu tragen?",a="Der Hafen von Menethil ist isoliert und wird ständig von feindlichen Kräften im Sumpfland bedroht, wodurch seine Garnison bei der Verteidigung des Hafens überlastet ist. Ihr habt Eure Fähigkeiten und Vertrauenswürdigkeit bereits bewiesen, indem Ihr das Erbstück geborgen habt. Einen fähigen, unabhängigen Reisenden damit zu beauftragen vermeidet es, die lokale Verteidigung der Stadt zu schwächen, und hält die Mission diskret, während Ihr Euch durch gefährliches Gebiet bewegt.",al={"warum schickt ihr mich","warum keine wachen schicken","warum statuette überbringen"}}},fp="22,291,19.430.0,20.362.0,24.373.0,31.240.0,48.205.0,46.226.0,51.236.0,43.118.0,49.192.0"}
P.entries["quest:98191"] = {n="A Friend of the Family",s="Hochlord Bolvar Fordragon betraut einen Abenteurer damit, eine seltene Statuette von Menethil zur Kathedrale des Lichts zu bringen. Das Relikt, das den verstorbenen König Terenas Menethil II. von Lordaeron darstellt, hat begonnen, sich mit heiliger Macht zu erfüllen. Es wird Lord Grayson Schattenbruch zur dauerhaften Verwahrung im spirituellen Herzen Sturmwinds übergeben.",h="Hochlord Bolvar Fordragon betraut einen Abenteurer damit, eine seltene Statuette von Menethil zur Kathedrale...",kw={"bolvar","kathedrale","lordaeron","menethil","schattenbruch","statuette","sturmwind","terenas"},ang={["class:Paladin"]="Für einen Paladin bedeutet die Bewahrung eines Relikts von König Terenas, das die spürbare Berührung des Lichts in sich trägt, tiefen Respekt vor dem Herrscher, der ursprünglich die Gründung der Ritter der Silbernen Hand genehmigte.",["class:Priest"]="Das Sammeln heiliger Energie in einem einfachen geschnitzten Bildnis bekräftigt das fortwährende spirituelle Erbe der Gläubigen Lordaerons selbst nach der physischen Zerstörung des Königreichs.",["faction:Alliance"]="König Terenas Menethil II. war die Grundsäule der Allianz von Lordaeron, was jedes mit ihm verbundene Artefakt zu einem geschätzten Symbol der Einheit und des Gedenkens macht."},sec={{t="Ein seltenes Andenken",b="König Terenas Menethil II. war während des Zweiten Krieges der Architekt der Großen Allianz und ein Mann von großer persönlicher Hingabe. Trotz seiner überragenden Statur unter den Königreichen der Menschheit war Terenas zutiefst demütig und hegte eine berüchtigte Abneigung gegen Monumente, die zu seinen eigenen Ehren gemeißelt wurden. Aufgrund seiner persönlichen Zurückhaltung wurden nur sehr wenige Bildnisse von ihm in Auftrag gegeben, und noch weniger schafften es, die schreckliche Zerstörung und Heimsuchung zu überstehen, die Lordaeron überrollte."},{t="Von Gnade berührt",b="Als Hochlord Bolvar Fordragon die erhaltene Statuette von Menethil untersucht, erkennt er etwas, das weit über einfache Handwerkskunst hinausgeht. Das Heilige Licht selbst hat begonnen, sich in der geschnitzten Figur zu sammeln, und erfüllt sie mit einer leisen spirituellen Resonanz. Da er entscheidet, dass der königliche Palast von Burg Sturmwind nicht die angemessene Zuflucht für ein derart heiliges Stück ist, ordnet Bolvar an, es quer durch die Stadt zur Kathedrale des Lichts zu bringen und in die vertrauensvollen Hände des Paladintrainers Lord Grayson Schattenbruch zu legen."}},faq={{q="Wer war König Terenas Menethil II.?",a="König Terenas Menethil II. war der geliebte Herrscher des Königreichs Lordaeron. Während des Zweiten Krieges versammelte er die verschiedenen Völker der Menschen zusammen mit den Zwergen, Gnomen und Hochelfen, um die Große Allianz zu schmieden und letztlich die orkische Horde zu besiegen. Er wurde während des Falls seines Reiches getötet.",al={"terenas menethil","wer ist terenas","könig von lordaeron"}},{q="Warum sind Statuen von König Terenas so selten?",a="Trotz seines immensen Ansehens und der Liebe seines Volkes war König Terenas für seine persönliche Demut bekannt und verabscheute extravagante Selbstmonumente. Nur sehr wenige Statuen oder Gedenkstätten wurden jemals nach seinem Vorbild gemeißelt, und fast keine überstand die Zerstörung Lordaerons durch die Geißel.",al={"warum gibt es so wenige statuen","seltenheit der menethil-statuette","warum so wenige denkmäler"}},{q="Warum leuchtet die Statuette von Menethil im Licht?",a="Bolvar bemerkt, dass sich das Licht offenbar in der Statuette gesammelt hat. Er spricht von Terenas als einem guten und frommen Mann, erklärt jedoch nicht, warum gerade dieses Bildnis heilige Macht angesammelt hat.",al={"warum hat die statuette licht","heilige statuette","sich sammelndes licht"}},{q="Wer ist Lord Grayson Schattenbruch?",a="Lord Grayson Schattenbruch ist ein erfahrener Paladin der Menschen von den Rittern der Silbernen Hand und ein prominenter Meister innerhalb der Kathedrale des Lichts. Am Kathedralenplatz stationiert, bildet er angehende Paladine aus und überwacht heilige Angelegenheiten für die Gläubigen von Sturmwind.",al={"wer ist schattenbruch","rolle von lord grayson"}},{q="Warum schickt Hochlord Bolvar die Statuette zur Kathedrale?",a="Während Bolvar Terenas' Rolle als Vater der Allianz ehrt, hat die Statuette sichtlich heilige Macht angesammelt. Bolvar glaubt, dass ein solches Gefäß des Lichts nicht unter Hofbürokraten in Burg Sturmwind gehört, sondern in die Kathedrale des Lichts unter die Obhut der heiligen Orden.",al={"warum zur kathedrale schicken","warum nicht in burg sturmwind behalten"}},{q="Wo befindet sich die Kathedrale des Lichts?",a="Die Kathedrale des Lichts dominiert den Kathedralenplatz, der direkt im Herzen von Sturmwind zwischen dem Zwergendistrikt, dem Handelsdistrikt und dem Magierviertel liegt. Sie dient als primäre Zuflucht und Zentrum der Anbetung für die Kirche des Heiligen Lichts in den südlichen Königreichen.",al={"wo ist die kathedrale des lichts","lage des kathedralenplatzes"}}},fp="22,330,18.456.0,16.505.0,33.294.0,40.275.0,53.193.0,34.252.0,61.275.0,40.275.0"}
P.entries["quest:982"] = {n="Tiefer Ozean, weites Meer",s="Tiefer Ozean, weites Meer ist eine Allianz-Quest, die von Gorbold Stahlhand in Auberdine angeboten wird. Die Spieler werden damit beauftragt, in die Gewässer nördlich des Dorfes zu tauchen, um persönliche Schließkassetten aus zwei gesunkenen Nachtelfenschiffen zu bergen, der Silver Dawning und der Nebelschleier. Beide Schiffe wurden von Küstenmurlocs überfallen, wodurch ihre überlebenden Besatzungsmitglieder nach einem Abschluss suchen.",h="Tiefer Ozean, weites Meer ist eine Allianz-Quest, die von Gorbold Stahlhand in Auberdine angeboten wird.",kw={"auberdine","dunkelküste","tiefer ozean weites meer","gorbold stahlhand","schließkassette","nebelschleier","murloc","schiffswrack","silver dawning"},ang={["faction:Alliance"]="Die geteilte Trauer der Besatzung in Auberdine bezeugt die enge maritime Zusammenarbeit zwischen Zwergen und Nachtelfen an der Küste von Kalimdor.",["race:Dwarf"]="Gorbold Stahlhand zeigt den typischen Zwergeninstinkt, gefallene Kameraden zu ehren und seinen Seemannskollegen in fremden Häfen beizustehen.",["race:NightElf"]="Die gefallenen Kapitäne waren Nachtelfenseefahrer im Dienste des Seehandels von Auberdine, was die Bergung ihrer Besitztümer zu einer Frage der Ehre ihrer Vorfahren macht."},sec={{t="Tragödie vor der Küste",b="Die Gewässer vor Dunkelküste sind zunehmend gefährlicher geworden, nicht nur durch tückische Strömungen und natürliche Riffe, sondern auch durch aggressive Küstenstämme. Die Schiffe Silver Dawning und Nebelschleier befanden sich auf dem Weg in den Hafen von Auberdine, als sie von schwärmenden Murlocs überwältigt wurden. Keines der Schiffe überstand die Begegnung, und beide sanken in den Untiefen nördlich der Siedlung. Die überlebende Besatzung schaffte es an Land, doch der Verlust ihrer Schiffe und Kapitäne legte einen schweren Schatten über den Hafen."},{t="Verlorene Erinnerungen bergen",b="Gorbold Stahlhand, ein in Auberdine stationierter Zwerg, nimmt sich der Sache an, die gefallenen Nachtelfenkapitäne zu ehren. Obwohl die Schiffe nun Unterwasserruinen sind, die von den einheimischen Murlocs als Trophäen und Nester beansprucht werden, bleiben die Schließkassetten der Kapitäne in den überfluteten Frachträumen verschlossen. Das Bergen der Logbücher und persönlichen Gegenstände im Inneren ermöglicht es den überlebenden Seeleuten in Auberdine, angemessen um ihre Befehlshaber zu trauern und deren Geister zur Ruhe zu betten."}},faq={{q="Wo befinden sich die gesunkenen Schiffe?",a="Die Wracks sowohl der Silver Dawning als auch der Nebelschleier liegen vor der Küste von Dunkelküste unter Wasser, direkt nördlich der Docks von Auberdine.",al={"wo sind die schiffswracks","wrack standort","wo man die silver dawning findet"}},{q="Was geschah mit der Silver Dawning und der Nebelschleier?",a="Beide Schiffe gerieten in einen Hinterhalt von Murlocs, als sie über das Meer in Richtung Auberdine fuhren. Die Besatzungen wurden überrannt, beide Kapitäne starben, und die Schiffe gingen unter und kamen auf dem Meeresgrund zur Ruhe.",al={"wie schiffe sanken","warum schiffe sanken","was die nebelschleier versenkte"}},{q="Wer ist Gorbold Stahlhand?",a="Gorbold Stahlhand ist ein Zwerg, der im Nachtelfenhafen Auberdine ansässig ist. Er kümmert sich um die überlebenden Seeleute im Ort und beauftragt Abenteurer damit, die Habseligkeiten der verlorenen Kapitäne zu bergen.",al={"wer gibt tiefer ozean weites meer","gorbold stahlhand lore"}},{q="Was befindet sich in den Schließkassetten?",a="Die Schließkassetten enthalten die persönlichen Habseligkeiten und Logbücher der gefallenen Nachtelfenkapitäne – Gegenstände, die den überlebenden Besatzungsmitgliedern, die dem Wrack entkamen, sehr am Herzen liegen.",al={"was ist in den schließkassetten","inhalt schließkassetten kapitäne"}},{q="Warum bedeuten diese Gegenstände den Überlebenden so viel?",a="Die Kapitäne waren angesehene Nachtelfenseefahrer. Das Bergen ihrer Logbücher und Besitztümer verschafft ihrer überlebenden Besatzung Gewissheit und soll dabei helfen, ihre Geister zur Ruhe zu betten.",al={"warum schließkassetten bergen","warum kapitän helfen"}},{q="Welche Kreaturen bewohnen die Schiffswracks jetzt?",a="Die Ruinen wurden von Murlocs übernommen, die die zerschellten Rümpfe als Trophäen betrachten und in den umliegenden Gewässern umherstreifen.",al={"was bewacht die schiffe","mobs an den schiffswracks"}}},fp="20,359,21.488.0,24.426.0,35.143.0,54.185.0,25.193.0,29.164.0,54.177.0,42.115.0"}
P.entries["quest:98208"] = {n="Bloom of the Heavens",s="Bloom of the Heavens befasst sich mit der Bergung von Nord'el, einer heiligen Blume der Nachtelfen, die unter einem Vollmond auf dem Hyjal gepflückt wurde. Die Blume ging verloren, als das Nachtelfenschiff Flying Osprey südlich vom Hafen von Menethil zusammen mit Schiffen der Dritten Flotte der Kul Tiraner Schiffbruch erlitt, sodass ihre Bergung in den Händen von Abenteurern liegt, die mutig genug sind, sich den zwischen den Trümmern nistenden Murlocs zu stellen.",h="Bloom of the Heavens befasst sich mit der Bergung von Nord'el, einer heiligen Blume der Nachtelfen, die unter...",kw={"auberdine","bloom of the heavens","flying osprey","hafen von menethil","hyjal","murlocs","nord'el","sylessa duskwhisper","teldrassil","sumpfland"},ang={["faction:Alliance"]="Das verlorene Schiff Flying Osprey segelte an der Seite der Dritten Flotte der Kul Tiraner, bevor beide vor der Küste des Hafens von Menethil ihr Unglück fanden.",["profession:Herbalism"]="Nord'el ist eine überaus seltene Nachtelfenblume, die unter dem Vollmond auf dem Gipfel des Hyjal herangezogen wird, was sie zu einem Exemplar von außergewöhnlichem botanischem Wunder macht.",["race:NightElf"]="Das Nord'el stellt ein kostbares botanisches Relikt vom Hyjal dar, gepflückt bevor die Nachtelfen ihre Heimat in die Äste von Teldrassil verlegten."},sec={{t="Ein Relikt des Hyjal",b="Sylessa Duskwhisper unternahm die weite Reise von Auberdine an den Küsten von Kalimdor zum Hafen von Menethil, um einen Schatz von tiefer kultureller Bedeutung zu bergen. Bei der gesuchten Fracht handelt es sich um Nord'el, in der Gemeinsprache bekannt als Bloom of the Heavens, eine heilige Blume, die unter einem strahlenden Vollmond auf dem Gipfel des Hyjal gepflückt wurde. Für die vertriebenen Nachtelfen, die nun in Teldrassil weilen, sind solche Relikte ihres angestammten Berges unersetzliche Erinnerungen an ihr Erbe."},{t="Das Schicksal der Flying Osprey",b="Die Blume ging vor vielen Monden verloren, als das Nachtelfenschiff Flying Osprey an der felsigen Küste direkt südlich vom Hafen von Menethil Schiffbruch erlitt, nachdem es in Begleitung der Dritten Flotte der Kul Tiraner gesegelt war. Heute ruht der zerstörte Rumpf in den Untiefen als düsteres Mahnmal der Katastrophe. Erschwerend kommt hinzu, dass wilde Murlocräuber das Wrack kolonisiert haben, das zerstörte Schiff erbittert verteidigen und jeden bedrohen, der versucht, die Fracht der Kaldorei zu bergen."}},faq={{q="Was ist Nord'el?",a="Nord'el bedeutet auf Darnassisch Bloom of the Heavens. Es ist eine heilige Blume von großer Bedeutung für die Nachtelfen, die gepflückt wird, nachdem sie unter einem Vollmond auf dem Hyjal erblüht ist, der angestammten bergigen Heimat der Nachtelfen.",al={"was ist nordel","nordel blume","was ist bloom of the heavens"}},{q="Was war die Flying Osprey?",a="Die Flying Osprey war ein Nachtelfenschiff, das in Begleitung der Dritten Flotte der Kul Tiraner segelte. Vor vielen Monden erlitt das Schiff direkt südlich vom Hafen von Menethil an der Küste des Sumpflands Schiffbruch und verstreute seine wertvolle Fracht.",al={"flying osprey schiff","welches schiff erlitt schiffbruch","dritte flotte von kul tiras sumpfland"}},{q="Wer ist Sylessa Duskwhisper?",a="Sylessa Duskwhisper ist eine nachtelfische Gesandte, die von Auberdine und den Ästen von Teldrassil über das Meer zum Hafen von Menethil reiste, eigens um die verlorene Blüte für ihr Volk zu bergen.",al={"wer ist sylessa duskwhisper","questgeber menethil","nachtelf in menethil"}},{q="Warum ist das Schiffswrack gefährlich?",a="Wilde Murlocräuber haben das Küstenwrack südlich vom Hafen von Menethil heimgesucht, die Überreste der Flying Osprey für sich beansprucht und machen eine Bergung für Sylessa zu einem gefährlichen Unterfangen.",al={"warum sind murlocs beim wrack","wer bewacht das wrack","wrack suedlich von menethil"}},{q="Warum ist Nord'el für die Nachtelfen so wichtig?",a="Die Blume wurde vor der Gründung von Teldrassil auf dem Gipfel des Hyjal gepflückt, der einstigen Heimat der Kaldorei. Aufgrund ihrer Herkunft und ihrer heiligen Ernte unter dem Vollmond besitzt sie für die Nachtelfen einen immensen kulturellen und emotionalen Wert.",al={"warum ist die blume wichtig","warum will sylessa nordel"}},{q="Wo befindet sich das Wrack?",a="Das Wrack der Flying Osprey liegt an der Küste direkt südlich vom Hafen von Menethil im Sumpfland, inmitten von Felsen, die nun von feindseligen Murlocs überrannt sind.",al={"wo ist das schiffswrack","wo ist die blume","schiffswrack ort sumpfland"}}},fp="20,370,22.466.0,29.455.0,16.225.0,27.218.0,27.190.0,31.166.0,47.248.0,32.143.0"}
P.entries["quest:98209"] = {n="Bloom of the Heavens",s="Bloom of the Heavens ist eine Reise über das Meer, um ein wundersames botanisches Relikt der Nachtelfen namens Nord'el zu überbringen. Die überlebende Blüte, die über Generationen hinweg als verloren galt, dient als kraftvolles Symbol für Elunes Gnade und die Widerstandskraft der Kaldorei nach dem Verlust ihrer Unsterblichkeit.",h="Bloom of the Heavens ist eine Reise über das Meer, um ein wundersames botanisches Relikt der Nachtelfen...",kw={"auberdine","bloom of the heavens","dunkelküste","darnassus","elune","hafen von menethil","nord'el","sylessa","thundris windweaver","sumpfland"},ang={["faction:Alliance"]="Diese Mission verbindet den geschäftigen Hafen der Allianz von Hafen von Menethil in den Östlichen Königreichen über das Große Meer hinweg mit Auberdine und Darnassus im nördlichen Kalimdor.",["profession:Herbalism"]="Kräuterkundige und Botaniker werden die seltene Bergung von Nord'el zu schätzen wissen – eine seit Zeitaltern verloren geglaubte heilige Pflanze, die in Darnassus kultiviert werden muss.",["race:NightElf"]="Nord'el stellt ein kostbares Überbleibsel des heiligen Erbes von Kalimdor dar und ist ein ermutigendes Zeichen dafür, dass Elune über die Kaldorei wacht, während sie sich an den Verlust ihrer Unsterblichkeit anpassen."},sec={{t="Eine gefährliche Bergung",b="In den Sümpfen des Sumpflands gelingt es Sylessa, eine legendäre Blume namens Nord'el zu bergen, wobei sie dem Angriff bösartiger Murlocs der Umgebung trotzt. Erschöpft von ihrer gefährlichen Flucht vertraut sie die geborgene Pflanze einem Abenteurer an, um sie über das Große Meer nach Auberdine zu bringen. Das Schiff, das vom Hafen von Menethil ablegt, bietet eine direkte Überfahrt zur Dunkelküste und schlägt so eine Brücke von den Östlichen Königreichen zum nördlichen Kalimdor."},{t="Ein Zeichen von Elunes Gnade",b="Als Ältester Thundris Windweaver Nord'el in Auberdine entgegennimmt, reagiert er voller Erstaunen, da er geglaubt hatte, die heilige Blüte sei für immer verloren. Für die Nachtelfen, die nach der Schlacht um den Hyjal noch immer mit dem Opfer ihrer Unsterblichkeit zu kämpfen haben, erstrahlt das wundersame Überleben von Nord'el als Segen von Elune. Thundris bereitet vor, die zarte Pflanze nach Darnassus weiterzuschicken, um sicherzustellen, dass sie kultiviert und für zukünftige Generationen bewahrt wird."}},faq={{q="Was ist Nord'el?",a="Nord'el ist eine heilige Pflanze, die von den Nachtelfen lange Zeit für verloren gehalten wurde. Ihre Wiederentdeckung und ihr Überleben nach vielen Jahren machen sie zu einem geschätzten Symbol für Elunes göttliche Gunst und zu einem Zeugnis der Widerstandskraft der Natur.",al={"was ist nord'el","nordel-blume","heilige blüte"}},{q="Wer vergibt die Quest Bloom of the Heavens?",a="Die Quest wird von Sylessa im Sumpfland vergeben. Sie konnte die heilige Blüte erfolgreich bergen, obwohl sie von feindseligen Murlocs überfallen und verfolgt wurde, doch die Strapazen ließen sie zu erschöpft zurück, um die Reise selbst zu vollenden.",al={"wer vergibt bloom of the heavens","sumpfland questgeber nordel","sylessa sumpfland"}},{q="Wohin muss Nord'el gebracht werden?",a="Nord'el muss über das Meer zu Ältester Thundris Windweaver in Auberdine gebracht werden, das an der Küste der Dunkelküste liegt. Vom Hafen von Menethil aus nehmen Reisende das Schiff direkt nach Auberdine.",al={"wohin bringt man nord'el","thundris windweaver aufenthaltsort","lieferung nach auberdine"}},{q="Warum ist Nord'el für die Nachtelfen von so großer Bedeutung?",a="Ältester Thundris Windweaver betrachtet das Überleben der Blume als seltenen Hoffnungsschimmer in finsteren Zeiten. Sie dient als heiliges Mahnmal für Elunes Gnade und den unerschütterlichen Geist der Kaldorei, weiterzubestehen, nachdem sie während des Dritten Krieges ihre Unsterblichkeit geopfert haben.",al={"warum nord'el für nachtelfen wichtig ist","nordel lore","unsterblichkeit nachtelfen nordel"}},{q="Was geschieht mit der Blume nach ihrer Ankunft in Auberdine?",a="Nachdem Thundris Windweaver die Blüte in Auberdine in Empfang genommen hat, veranlasst er ihren sicheren Transport ins Landesinnere nach Darnassus, wo Botaniker und Priester der Nachtelfen sie angemessen pflegen und kultivieren können.",al={"was geschieht als nächstes mit nord'el","nord'el darnassus","wohin schickt thundris nord'el"}},{q="Wie gelangt Ihr vom Hafen von Menethil nach Auberdine?",a="Reisende können das Passagierschiff nutzen, das im Hafen von Menethil im Sumpfland anlegt und direkt über das Große Meer zu den Docks von Auberdine an der Dunkelküste segelt.",al={"wie man vom sumpfland nach auberdine gelangt","schiff von menethil nach auberdine","schiff zur dunkelküste"}}},fp="20,274,20.407.0,23.464.0,16.200.0,41.219.0,40.188.0,49.256.0,56.197.0,52.165.0"}
P.entries["quest:98245"] = {n="Razormaw Needling",s="Razormaw Needling ist eine Quest im Sumpfland, bei der Howin Kindfeather Reisende damit beauftragt, Schneidezähne von einheimischen Razormaw-Raptoren zu erbeuten. Howin beabsichtigt, aus ihren scharfen Zähnen robuste Ahlen herzustellen, um Schuppen von Drachenwelpen zu durchstechen und für eine feuerbeständige Rüstung zusammenzunähen.",h="Razormaw Needling ist eine Quest im Sumpfland, bei der Howin Kindfeather Reisende damit beauftragt...",kw={"düstereisen","drachenmal","howin kindfeather","raptorgrat","raptoren","razormaw-schneidezähne","razormaw needling","salzgischtschlucht","sumpfland","welpenschuppen"},ang={["faction:Alliance"]="Die Beschaffung von Ausrüstung zum Schutz vor Drachenfeuer unterstützt den anhaltenden Kampf der Allianz gegen Drachenbrut und Dragonmaw-Truppen, die die östlichen Sümpfe halten.",["race:Dwarf"]="Howin Kindfeather teilt den bitteren Hass der Wildhammer- und Eisenschmiedezwerge auf den Dunkeleisenklan und die Dragonmaw-Orcs, die das Sumpfland und Grim Batol verwüsteten."},sec={{t="Werkzeuge der Vergeltung",b="In den durchnässten Weiten des Sumpflands hegt Howin Kindfeather einen anhaltenden Zorn auf die Feinde, die die Region heimgesucht haben: die tückischen Dunkeleisenzwerge, die brutalen Dragonmaw-Orcs und die feuerspeienden Drakes, die sie in die Schlacht führten. Um zurückzuschlagen und sich vor Drachenfeuer zu schützen, arbeitet Howin daran, aus den Schuppen von Drachenwelpen eine schützende Rüstung zu fertigen. Die widerstandsfähigen Häute erweisen sich jedoch ohne spezialisierte Handwerkswerkzeuge als notorisch schwer zusammenzunähen."},{t="Reißzähne als Nadeln",b="Um die widerstandsfähige Welpenhaut zu durchstoßen, benötigt Howin Werkzeuge, die weitaus schärfer und robuster sind als gewöhnliche Metallnadeln, die sich an Drachenschuppen leicht verbiegen oder abstumpfen. Er wendet sich an die einheimischen Razormaw-Raptoren, die den Raptorgrat im Nordosten und die Salzgischtschlucht im Nordwesten durchstreifen. Benannt nach ihrem tödlichen, nadelscharfen Gebiss, dienen unbeschädigte Razormaw-Schneidezähne als erstklassige Ahlen, die zähe Schuppen durchdringen, ohne unter Druck zu zerspringen."}},faq={{q="Wer vergibt die Quest Razormaw Needling?",a="Howin Kindfeather vergibt diese Aufgabe im Sumpfland. Er hegt einen tiefen Groll gegen die Dunkeleisenzwerge, den Dragonmaw-Klan und die Drakes, die sie ritten, und versucht, aus Welpenschuppen gegen Drachenfeuer beständige Rüstung herzustellen.",al={"wer vergibt razormaw needling","wer ist howin kindfeather","questgeber razormaw needling"}},{q="Warum benötigt Howin Kindfeather Razormaw-Schneidezähne?",a="Howin arbeitet mit zähen Drachenwelpenschuppen, um eine Schutzrüstung herzustellen, doch die Haut ist zu dicht, um sie einfach zusammenzunähen. Er benötigt die scharfen, robusten Schneidezähne der Razormaw-Raptoren, um Ahlen zu fertigen, die stark genug sind, die Schuppen zu durchstoßen, ohne zu brechen.",al={"warum howin raptorzähne will","zweck von razormaw-schneidezähnen","wofür die zähne sind"}},{q="Wo befinden sich die Razormaw-Raptoren?",a="Razormaw-Raptoren streifen durch zwei Hauptjagdgebiete im Sumpfland: den Raptorgrat im Hochland im Nordosten und die Salzgischtschlucht, die im Nordwesten zur Küste hin liegt.",al={"wo man razormaw-raptoren findet","standort der razormaw-raptoren im sumpfland","wo sind die raptoren"}},{q="Was stellt Howin Kindfeather aus den Welpenschuppen her?",a="Howin näht Drachenwelpenschuppen zu einer Schutzrüstung zusammen. Die Schuppen bieten erheblichen Schutz gegen feurige Atemwaffen und gewähren lebenswichtigen Schutz gegen Drachen und die Drakes des Dragonmaw-Klans.",al={"welche rüstung howin herstellt","welpen-schuppenrüstung sumpfland","warum welpenschuppen"}},{q="Warum hasst Howin die Dunkeleisenzwerge und die Dragonmaw?",a="Das Sumpfland und die umliegenden Berge tragen tiefe Narben sowohl durch den Dunkeleisenklan als auch durch die Dragonmaw-Orcs, die während des Zweiten Krieges rote Drachen versklavten. Howin verabscheut beide Fraktionen mitsamt ihren Flugreittieren und ist entschlossen, das Gleichgewicht wiederherzustellen.",al={"warum hass auf düstereisenzwerge und drachenmalork","howins feinde","warum hasst howin den drachenmalklan"}},{q="Wozu verarbeitet Howin die Raptorschneidezähne?",a="Eine Ahle ist ein schlankes, spitzes Handwerkzeug, mit dem vor dem Nähen Löcher in zähe Häute und Leder gestochen werden. Indem er intakte Raptorschneidezähne an Griffen befestigt oder ihre natürliche Verjüngung nutzt, stellt Howin robuste Ahlen her, die Drachenschuppen durchdringen können, ohne abzubrechen.",al={"was ist eine ahle","razormaw-ahlen","wie raptorzähne als werkzeuge verwendet werden"}}},fp="17,275,20.479.0,16.435.0,38.217.0,50.270.0,39.178.0,55.213.0,49.257.0,46.258.0"}
P.entries["quest:98246"] = {n="Trying Times",s="Trying Times ist eine Quest der Allianz im Sumpfland, bei der Abenteurer dem Zwerg Howin Kindfeather beistehen. Um seinen mürrischen Greifen Bassbeak auf einen bevorstehenden Einsatz vorzubereiten, benötigt Howin ein Dutzend unversehrte Eier, die von wilden Razormaw-Raptoren gesammelt werden müssen.",h="Trying Times ist eine Quest der Allianz im Sumpfland, bei der Abenteurer dem Zwerg Howin Kindfeather...",kw={"bassbeak","greif","howin kindfeather","raptorgrat","razormaw-eier","salzgischtschlucht","trying times","sumpfland"},ang={["faction:Alliance"]="Die Haltung gesunder Greifen ist für Reisen und die Kommunikation der Allianz in ganz Khaz Modan von entscheidender Bedeutung, insbesondere wenn lokale Gefahren die Sicherheit der Region bedrohen.",["race:Dwarf"]="Zwergische Greifenreiter wissen, dass ein schlecht gelaunter Greif ebenso gefährlich ist wie jeder Feind, weshalb die richtige Fütterung und Pflege eine unabdingbare Notwendigkeit sind, bevor man sich in die Lüfte erhebt.",["race:Gnome"]="Howin merkt scherzhaft an, dass die Eier der Razormaw-Raptoren ein Eigelb von der Größe eines Gnomenschädels haben, was eine anschauliche, wenn auch etwas respektlose zwergische Maßeinheit darstellt."},sec={{t="Einen hungrigen Greifen besänftigen",b="In den trüben Weiten des Sumpflands erfordert die Pflege eines Arbeitstiers ständige Wachsamkeit. Howin Kindfeather, ein Zwerg, der an der Seite seines Greifen Bassbeak arbeitet, weigert sich abzuheben, ohne zuvor den launischen Appetit seines Partners gestillt zu haben. Ein hungriger Greif ist stur, unberechenbar und neigt zu Wutausbrüchen, weshalb eine ordentliche Mahlzeit die Grundvoraussetzung für jedes Flugvorhaben im Moor darstellt."},{t="Die Razormaw-Beute",b="Im Sumpfland ist es zunehmend schwieriger geworden, verlässliche, unverworbene Nahrung zu finden. Um Bassbeak zufriedenzustellen, nimmt Howin die Nester der einheimischen Razormaw-Raptoren auf dem Raptorgrat im Nordosten und in der Salzgischtschlucht im Nordwesten ins Visier. Die Eier der Raptoren sind berühmt dafür, dass ihr Eigelb so groß wie der Kopf eines Gnoms ist, und bieten die nahrhafte, unverfälschte Mahlzeit, die Bassbeak benötigt, bevor er den Gefahren der Region entgegentritt."}},faq={{q="Wer ist Howin Kindfeather?",a="Howin Kindfeather ist ein zwergischer Tierführer im Sumpfland, der sich um einen Greifen namens Bassbeak kümmert. Er beauftragt Abenteurer damit, frische Raptoreier zu sammeln, um seinen Partner zu füttern, bevor er seine Pläne in die Tat umsetzt.",al={"wer ist howin kindfeather","howin kindfeather sumpfland","questgeber trying times"}},{q="Wer ist Bassbeak?",a="Bassbeak ist der Greif von Howin Kindfeather. Laut Howin wird sie gereizt und regelrecht gefährlich, wenn sie hungrig ist, weshalb es unüberlegt ist, sie ohne gefüllten Magen zu reiten oder einzusetzen.",al={"wer ist bassbeak","bassbeak der greif","howins greif"}},{q="Warum braucht Howin Raptoreier?",a="Howin sucht gezielt nach Eiern von Razormaw-Raptoren, da unbelastete Nahrung im Sumpfland rar ist und diese Eier riesige, nahrhafte Dotter bieten, die groß genug sind, um Bassbeaks gewaltigen Appetit zu stillen.",al={"warum raptoreier","warum eier an greif verfuettern","wozu sind die eier da"}},{q="Wo sind Razormaw-Raptoren zu finden?",a="Razormaw-Raptoren bevölkern den Raptorgrat im Nordosten und die Salzgischtschlucht im Nordwesten des Sumpflands. Abenteurer müssen diesen Nestern direkt trotzen, um makellose Eier zu erbeuten.",al={"wo sind razormaw-raptoren","wo man razormaw-eier findet","sumpfland raptor standorte"}},{q="Warum müssen die Eier makellos sein?",a="Howin besteht auf Eiern ohne Risse oder Makel, um sicherzustellen, dass die Nahrung völlig frisch und unverdorben ist, damit Bassbeak gesund und zufrieden bleibt, anstatt sie mit verdorbenen Resten abzuspeisen.",al={"warum muessen eier makellos sein","beschaedigte eier trying times"}},{q="Was hat Howin mit Bassbeak vor?",a="Howin erwähnt, dass er mit Bassbeak einen umfassenderen Plan verfolgt, beharrt jedoch darauf, die Einzelheiten hintenanzustellen, bis der Greif ordentlich gefüttert und ruhig genug ist, um inmitten der regionalen Gefahren sicher abzuheben.",al={"was ist howins plan","was planen howin und bassbeak"}}},fp="12,240,26.401.0,19.405.0,25.204.0,16.178.0,32.200.0,36.176.0,35.181.0,43.204.0"}
P.entries["quest:98247"] = {n="Shipping Label",s="Das Shipping Label ist eine geborgene Frachtmarkierung an einer Vorratskiste, die der Handelskommission von Azeroth gehört. Sie weist Kuriere zu deren Handelsknotenpunkt an der Wegkreuzung Drei Ecken im Rotkammgebirge und führt Reisende in das Netzwerk unabhängiger Spediteure der Organisation ein.",h="Das Shipping Label ist eine geborgene Frachtmarkierung an einer Vorratskiste, die der Handelskommission von...",kw={"handelskommission von azeroth","kiste","lieferung","merchant's favor","rotkammgebirge","shipping label","drei ecken"},ang={["faction:Alliance"]="Von der Wegkreuzung Drei Ecken aus agierend, verlässt sich die Handelskommission von Azeroth auf reisende Abenteurer in den südlichen Gebieten der Allianz, um verirrte Fracht zu bergen und Landtransportwege zu sichern."},sec={{t="Eine verirrte Lieferung",b="Dieses beschädigte Shipping Label, das auf eine gefüllte Vorratskiste geklebt vorgefunden wurde, kennzeichnet Frachtgut der Handelskommission von Azeroth. Obwohl der vorgesehene Bestimmungsort und der Empfänger abgerissen wurden, weisen klare Anweisungen jeden Finder der Fracht an, diese zurückzubringen oder sich beim Handelsposten der Kommission im Rotkammgebirge zu melden. Neben dem formellen Text skizziert eine rudimentäre Karte die Straßen, die zur Wegkreuzung Drei Ecken führen."},{t="Der Knotenpunkt der Handelskommission",b="An der Wegkreuzung Drei Ecken werben Vertreter der Handelskommission von Azeroth aktiv Reisende als unabhängige Kuriere an. Anstatt Spediteure an strenge Händlerverträge zu binden, betreibt die Kommission ein informelles Netzwerk, in dem Abenteurer im Gegenzug für die Bergung verschollener Fracht und die Ausführung herrenloser Lieferungen entlang der Handelsstraße mit Merchant's Favor entlohnt werden."}},faq={{q="Was ist das Shipping Label?",a="Das Shipping Label ist ein zerrissenes Dokument, das an der Seite einer geborgenen Vorratskiste gefunden wurde. Obwohl der Name des Empfängers fehlt, weist das Etikett die Waren als Eigentum der Handelskommission von Azeroth aus und leitet den Finder an, sich an deren Knotenpunkt bei Drei Ecken zu melden.",al={"was ist das shipping label","shipping label quest","zerrissenes shipping label"}},{q="Was ist die Handelskommission von Azeroth?",a="Die Handelskommission von Azeroth ist ein Unternehmen, das Logistik, Handel und Frachtverkehr in der gesamten Region organisiert. Sie unterhält lokale Handelsknotenpunkte zur Bergung verlorener Sendungen und beschäftigt umherziehende Kuriere ohne langfristige Verträge.",al={"wer ist die handelskommission von azeroth","handelskommission von azeroth","was ist die handelskommission von azeroth"}},{q="Wo befindet sich der Handelsknotenpunkt der Handelskommission von Azeroth?",a="Der Handelsknotenpunkt der Handelskommission von Azeroth befindet sich an der Wegkreuzung Drei Ecken im Rotkammgebirge, strategisch günstig an den Straßen gelegen, die den Wald von Elwynn, den Dämmerwald und Seenhain verbinden.",al={"wo ist der handelsposten der handelskommission von azeroth","handelsknotenpunkt drei ecken","wo shipping label abgeben"}},{q="Was ist Merchant's Favor?",a="Merchant's Favor ist ein spezieller Schuldschein oder Kredit, den die Handelskommission von Azeroth unabhängigen Kurieren gewährt. Partner nutzen ihn zum Erwerb verschiedener Handelsgüter und logistischer Dienstleistungen, die an den Posten der Kommission angeboten werden.",al={"was ist merchant's favor","merchant's favor","entschädigung der handelskommission von azeroth"}},{q="Wie wird man Partner der Handelskommission von Azeroth?",a="Um Partner zu werden, sind keine formellen Verträge, Formalitäten oder langfristigen Verpflichtungen erforderlich. Die Handelskommission von Azeroth verlangt von Kurieren lediglich, bei der Rückgabe oder dem Abschluss verlegter Lieferungen zu helfen, auf die sie in der Welt stoßen.",al={"wie wird man mitglied der handelskommission von azeroth","der handelskommission von azeroth beitreten","brauche ich einen vertrag"}},{q="Was geschieht mit der Kiste nach Abgabe des Etiketts?",a="Das Etikett selbst veranlasst die Vertreter des Handelsknotenpunkts dazu, sich nach der physischen Kiste zu erkundigen, an der es befestigt war, da die Rückgabe leerer oder befüllter Transportbehälter für ihre Handelsgeschäfte weiterhin von entscheidender Bedeutung ist.",al={"was passiert mit der kiste","fehlende kiste","wollen sie die kiste"}}},fp="14,287,16.447.0,28.387.0,27.270.0,39.220.0,58.199.0,25.225.0,65.232.0,53.203.0"}
P.entries["quest:98248"] = {n="Shipping Label",s="Ein zerrissenes Liefermanifest, das auf einem neu aufgef\\u00fcllten Frachtbeh\\u00e4lter gefunden wurde, weist Bote zu einem regionalen H\\u00e4ndlerknotenpunkt im Brachland. Versorgung und Logistik Durotar verl\\u00e4sst sich auf reisende Wanderer, um verlorene Kisten zu bergen und Schriftst\\u00fccke zu ihrem Posten westlich des Wegekreuzes zur\\u00fcckzubringen. Der Abschluss der R\\u00fcckgabe sichert wichtige Lieferketten und den Handelsverkehr im zentralen Kalimdor.",h="Ein zerrissenes Liefermanifest, das auf einem neu aufgef\\u00fcllten Frachtbeh\\u00e4lter gefunden wurde, weist...",kw={"kiste","das wegekreuz","versorgung und logistik durotar","shipping label","brachland","handelsau\\u00dfenposten"},ang={["faction:Horde"]="Abenteurer der Horde, die das Brachland durchqueren, sto\\u00dfen h\\u00e4ufig auf Unternehmungen von Versorgung und Logistik Durotar und helfen dabei, den lebenswichtigen Handel sowie die Versorgungslinien zwischen Durotar und dem zentralen Kalimdor aufrechtzuerhalten."},sec={{t="Ein fehlgeleitetes Manifest",b="Dieses zerrissene Dokument, das an einer frisch aufgef\\u00fcllten Frachtkiste angebracht ist, tr\\u00e4gt die logistischen Anweisungen von Versorgung und Logistik Durotar. W\\u00e4hrend der Name des Empf\\u00e4ngers durch Reise und Abnutzung abgerissen wurde, weist der Absenderkopf eindeutig auf das Frachtunternehmen hin, das aus den Gebieten der Horde heraus operiert. Eine grob skizzierte Routenkarte neben dem Text f\\u00fchrt Boten direkt zum Sammelplatz des Unternehmens in den zentralen Ebenen."},{t="Grenzlandhandel",b="Der Aushang l\\u00e4dt Reisende dazu ein, fehlgeleitete Beh\\u00e4lter, besch\\u00e4digte Waren oder Bergungsnachweise zu ihrem Handelsau\\u00dfenposten direkt westlich des Wegekreuzes zu transportieren. In den rauen Weiten des Brachlands t\\u00e4tig, verl\\u00e4sst sich Versorgung und Logistik Durotar in hohem Ma\\u00dfe auf unabh\\u00e4ngige Frachtf\\u00fchrer und Reisende, um verstreute Fracht zu bergen, und garantiert eine Verg\\u00fctung f\\u00fcr jene, die dazu beitragen, die regionalen Versorgungskan\\u00e4le am Laufen zu halten."}},faq={{q="Was ist das Shipping Label?",a="Es ist ein Dokument, das an einer voll beladenen Kiste angebracht ist und R\\u00fcckgabeanweisungen f\\u00fcr Versorgung und Logistik Durotar enth\\u00e4lt, wodurch verlorene oder leere Beh\\u00e4lter zur\\u00fcck zu ihrem Posten in der N\\u00e4he des Wegekreuzes geleitet werden.",al={"was ist das shipping label","shipping label quest","zerrissenes shipping label"}},{q="Wo soll das Etikett abgeliefert werden?",a="Das Etikett weist Boten an, es beim Personal abzuliefern, das am Handelsknotenpunkt von Versorgung und Logistik Durotar direkt westlich des Wegekreuzes im Brachland stationiert ist.",al={"wohin bringt man das shipping label","wer will das shipping label","shipping label abgabe"}},{q="Was ist Versorgung und Logistik Durotar?",a="Versorgung und Logistik Durotar ist ein kommerzielles Frachtunternehmen, das in ganz Durotar und dem Brachland operiert und sich um den Transport von Fracht, das Einsammeln von Kisten und die logistische Unterst\\u00fctzung in den Gebieten der Horde k\\u00fcmmert.",al={"was ist versorgung und logistik durotar","versorgung und logistik durotar au\\u00dfenposten"}},{q="F\\u00fcr wen war die Lieferung urspr\\u00fcnglich gedacht?",a="Der Name des vorgesehenen Empf\\u00e4ngers ist vollst\\u00e4ndig vom Etikett abgerissen, sodass lediglich die R\\u00fcckgabeanweisungen und die Herkunftsinformationen des Unternehmens unversehrt auf der Kiste verbleiben.",al={"f\\u00fcr wen war die kiste bestimmt","kistenempf\\u00e4nger"}},{q="Wo befindet sich der Handelsau\\u00dfenposten von Versorgung und Logistik Durotar?",a="Den Wegbeschreibungen und der groben Karte auf dem Etikett zufolge liegt der Au\\u00dfenposten g\\u00fcnstig gelegen direkt westlich der Siedlung Das Wegekreuz im Brachland.",al={"wo ist der handelsau\\u00dfenposten","versorgung und logistik durotar standort wegekreuz"}},{q="Entlohnt Versorgung und Logistik Durotar Reisende f\\u00fcr das Zur\\u00fcckbringen von Kisten?",a="Ja, der gedruckte Aushang verspricht ausdr\\u00fccklich, dass Boten, die besch\\u00e4digte Lieferungen, Etiketten oder leere Kisten zur\\u00fcckbringen, nach der Zustellung an ihren Knotenpunkt f\\u00fcr ihre Zeit und M\\u00fchen entsch\\u00e4digt werden.",al={"zahlen sie f\\u00fcr zur\\u00fcckgebrachte kisten","versorgung und logistik durotar verg\\u00fctung"}}},fp="14,364,18.424.0,17.415.0,27.191.0,36.161.0,37.198.0,45.164.0,64.158.0,76.184.0"}
P.entries["quest:98286"] = {n="Camping 101: Enchanting",s="Camping 101: Enchanting weist Ausübende des arkanen Handwerks nach Shen'dar, um zu lernen, wie man spezialisierte Wildnisausrüstung herstellt. Im Gespräch mit Nasalanna Windsinger können bewährte Verzauberer lernen, eine Verzauberte Laute anzufertigen, um ihre Gefährten am Lagerfeuer zu unterhalten und zu stärken.",h="Camping 101: Enchanting weist Ausübende des arkanen Handwerks nach Shen'dar, um zu lernen, wie man...",kw={"lagerfeuer","camping","camping 101","verzauberte laute","verzauberkunst","laute","nasalanna windsinger","shen'dar"},sec={{t="Annehmlichkeiten des Herdes",b="Das Leben auf der offenen Straße verlangt mehr als nur geschärfte Klingen und Rationen; Rast und Moral sind unerlässlich, um langwierige Expeditionen zu überstehen. Ausübende der Verzauberkunst bringen einzigartige magische Annehmlichkeiten in das Lagerleben ein, indem sie ihre Beherrschung der umgebenden Arkanmagie nutzen, um Reisende während ihrer Ruhezeiten aufzumuntern. In Wildnislagern in ganz Azeroth sorgt die Anwesenheit eines Verzauberers dafür, dass erschöpfte Abenteurer ihre Kräfte und ihren Geist erholen können, bevor sie auf gefährliche Pfade zurückkehren."},{t="Das Lied von Shen'dar",b="Um die subtile Magie der Lagerplatzherstellung zu erlernen, werden angehende Verzauberer nach Shen'dar gewiesen. Dort unterweist Nasalanna Windsinger fähige Zauberweber im Bau einer Verzauberten Laute. Handwerker müssen zuerst ihre Hingabe und ihr Können in der Verzauberkunst beweisen, bevor Nasalanna die Geheimnisse der Anfertigung eines Instruments teilt, das in der Lage ist, unter den Sternen erholsame Melodien zu weben."}},faq={{q="Wer ist Nasalanna Windsinger?",a="Nasalanna Windsinger ist eine Ausbilderin, die in Shen'dar weilt. Sie lehrt geschickte Praktizierende, wie man besondere Berufsgegenstände für Wildnislager herstellt, insbesondere die Verzauberte Laute für Verzauberer, die Können in ihrem Handwerk beweisen.",al={"wer lehrt verzauberte laute","wer ist nasalanna windsinger","wo ist nasalanna windsinger"}},{q="Wo liegt Shen'dar?",a="Shen'dar ist die Siedlung, in der Nasalanna Windsinger residiert. Abenteurer, die Unterweisung in der Herstellung von Campingausrüstung wie der Verzauberten Laute suchen, reisen dorthin, sobald sie ihre Grundfertigkeiten entwickelt haben.",al={"wo ist shen'dar","wie man shen'dar findet"}},{q="Was ist eine Verzauberte Laute?",a="Die Verzauberte Laute ist ein magisches Campinginstrument, das von Verzauberern hergestellt wird. Es bietet Unterhaltung und erholsame Moral während der Ruhezeit am Lagerfeuer und hilft Reisenden, sich zu stählen und auf die bevorstehenden Härten der Wildnis vorzubereiten.",al={"was macht die verzauberte laute","warum verzauberte laute herstellen","campinglaute"}},{q="Was sind die Voraussetzungen, um das Rezept zu erlernen?",a="Bevor Nasalanna Windsinger Euch beibringt, wie Ihr eine Verzauberte Laute herstellt, müsst Ihr zunächst Euer Können in der magischen Kunst der Verzauberkunst beweisen. Nur erfahrenen Praktizierenden wird die Anfertigung dieser Nützlichkeitsverzauberungen für das Lager anvertraut.",al={"voraussetzungen für camping 101: enchanting","wann kann ich die verzauberte laute lernen"}},{q="Warum sind Verzauberer in Wildnislagern wertvoll?",a="Verzauberer bringen subtilen Nutzen und magische Annehmlichkeiten in abgelegene Lager, in denen profane Vorräte oft nicht ausreichen. Indem sie gewöhnliche Lagerwerkzeuge mit magischen Verbesserungen erfüllen, helfen sie Abenteurern, sich zu erholen, unterhalten zu bleiben und sich auf unerwartete Gefahren unterwegs vorzubereiten.",al={"warum camper verzauberer wollen","campingvorteile von verzauberern"}},{q="Können andere Berufe Campinggegenstände herstellen?",a="Ja, Handwerker und Sammler verschiedenster Disziplinen lernen, spezielle Lagerplatzwerkzeuge zu bauen. Für Verzauberer nimmt dieses spezialisierte Handwerk die Form der Verzauberten Laute an, die von Nasalanna Windsinger in Shen'dar gelehrt wird.",al={"gibt es andere campinggegenstände","campingherstellung anderer berufe"}}},fp="23,296,22.461.0,20.402.0,28.252.0,26.213.0,26.250.0,46.233.0,52.266.0,42.228.0"}
P.entries["quest:98293"] = {n="Forced Disarmament",s="Forced Disarmament ist eine Quest der Allianz im Sumpfland, bei der Abenteurer den Auftrag erhalten, Waffenlager des Dragonmaw-Clans bei Dragonmaw Retreat zu beschlagnahmen. Durch das Sammeln von dreißig Waffenbündeln hindern die Spieler die feindseligen Orcs daran, zusätzliche Soldaten für künftige Überfälle auszurüsten. Die konfiszierte Ausrüstung wird zu Hauptmann Starkfaust in Burg Menethil gebracht, um den lebenswichtigen Hafen der Region zu schützen.",h="Forced Disarmament ist eine Quest der Allianz im Sumpfland, bei der Abenteurer den Auftrag erhalten...",kw={"hauptmann starkfaust","dragonmaw armaments","dragonmaw-clan","dragonmaw retreat","forced disarmament","hafen von menethil","burg menethil","sumpfland"},ang={["faction:Alliance"]="Die Streitkräfte der Allianz sind auf den Hafen von Menethil als lebenswichtige Verbindung über Das große Meer angewiesen, was die Entwaffnung nahegelegener feindseliger Clans zu einer dringenden strategischen Notwendigkeit macht.",["race:Dwarf"]="Zwergische Verteidiger aus Eisenschmiede halten die Garnison in Burg Menethil aufrecht und bemühen sich, die Grenzen von Khaz Modan vor alten Feinden zu sichern, die sich in den Marschen verschanzt haben.",["race:Orc"]="Die Dragonmaw stellen einen abgespaltenen, unbelehrbaren Überrest der Alten Horde dar, dessen gewaltsame Kriegstreiberei ihn von der Führung von The New Horde in Kalimdor isoliert."},sec={{t="Eine Waffenkammer in den Marschen",b="In den Marschen des Sumpflands hat der feindselige Dragonmaw-Clan damit begonnen, einen besorgniserregenden Vorrat an Waffen in Dragonmaw Retreat anzuhäufen. Blieben diese Vorräte unkontrolliert, würden sie es den abtrünnigen Orcs ermöglichen, neue Wellen von Kriegern auszurüsten und verheerende Überfälle auf benachbarte Siedlungen zu verüben. Die Entwaffnung ihrer Lager trifft ihre logistischen Kapazitäten direkt und schwächt jede geplante Offensive ab, bevor ihre Kriegstrupps voll mobilisieren und ins Feld ziehen können."},{t="Sicherung des Küstenhafens",b="Der Hafen von Menethil dient als wichtigstes Tor, das Khaz Modan und Sturmwind mit dem Meer verbindet, was jeden militärischen Aufmarsch in der Nähe zu einer ernsten Gefahr macht. Hauptmann Starkfaust koordiniert die Verteidigungsmaßnahmen von Burg Menethil aus und wacht wachsam über die feindseligen Clans und Bestien, die die Stadt bedrängen. Die Bergung von dreißig Sätzen von Dragonmaw-Waffen entzieht den Orcs essentielle Munition und liefert der Zwergengarnison gleichzeitig Vital Intelligence über die Gefechtsbereitschaft des Feindes."}},faq={{q="Wer ist Hauptmann Starkfaust?",a="Hauptmann Starkfaust ist ein Zwergen-Militäroffizier, der in Burg Menethil stationiert und für die Verteidigung des Hafens von Menethil sowie des umliegenden Sumpflands verantwortlich ist. Angesichts des ständigen Drucks durch feindselige Bestien, Saboteure der Dunkeleisenzwerge und den Dragonmaw-Clan leitet Starkfaust aktiv Soldaten und Abenteurer an, Bedrohungen in der Nähe zu unterdrücken, bevor die lebenswichtigen Nachschublinien und Hafenanlagen des Hafens überrannt werden.",al={"starkfaust","wer ist starkfaust","hauptmann von burg menethil"}},{q="Warum müssen die Dragonmaw entwaffnet werden?",a="Der Dragonmaw-Clan hortet aktiv Waffen in seinem Rückzugsort, um neue Kämpfer für die Schlacht auszurüsten. Wenn man ihnen erlaubt, Munition ungestört anzuhäufen, könnten ihre Kriegstrupps die örtlichen Verteidigungsanlagen der Allianz überwältigen und den Hafen von Menethil gefährden. Die Beschlagnahmung von dreißig Waffenbündeln behindert ihre logistischen Vorbereitungen direkt und verhindert, dass weitere Orc-Soldaten ins Feld ziehen.",al={"warum waffen der dragonmaw nehmen","zweck der dragonmaw-bewaffnung","dragonmaw entwaffnen"}},{q="Wo befindet sich Dragonmaw Retreat?",a="Dragonmaw Retreat ist ein von den Dragonmaw-Orcs errichtetes Lager im Sumpfland, das östlich in Richtung der Berge jenseits des Hafens von Menethil liegt. Der Clan nutzt diesen abgelegenen Außenposten, um Streitkräfte zu sammeln, Waffen zu lagern und Angriffe auf Reisende entlang der Marschen zu inszenieren. Abenteurer müssen sich mitten in das Lager wagen, um ihre gehorteten Waffen zu bergen.",al={"standort von dragonmaw retreat","wo ist dragonmaw retreat","dragonmaw retreat sumpfland"}},{q="Was sind Dragonmaw Armaments?",a="Dragonmaw Armaments sind Vorräte an Kriegsausrüstung, Klingen und Ausrüstungsgegenständen, die vom Dragonmaw-Clan geschmiedet oder gestohlen wurden, um seine Krieger zu versorgen. Diese Waffen repräsentieren die unmittelbare militärische Schlagkraft des Clans in der Region. Hauptmann Starkfaust verlangt, dass dreißig Bündel dieser Rüstungsgüter beschlagnahmt und zur Auswertung sowie Entsorgung nach Burg Menethil zurückgebracht werden.",al={"dragonmaw-waffen","was sind rüstungsgüter","dragonmaw-ausrüstung"}},{q="Gehört der Dragonmaw-Clan im Jahr 25 n. d. P. zur Horde?",a="Nein, der Dragonmaw-Clan im Sumpfland agiert als unabhängige, feindselige Fraktion, die Kriegshäuptling Thrall nicht untersteht. Diese Orcs, die nach dem Zweiten Krieg ihren alten Traditionen treu blieben, hegen tiefen Hass auf die Allianz und lehnen jegliche friedliche Annäherung ab. Daher betrachten sowohl die Verteidiger der Allianz als auch unabhängige Reisende sie als tödliche Widersacher.",al={"gehören dragonmaw zur horde","fraktion des dragonmaw-clans","dragonmaw thrall"}},{q="Warum ist Burg Menethil wegen der Dragonmaw besorgt?",a="Burg Menethil ist die administrative und militärische Festung, die den Hafen von Menethil sichert, den wichtigsten maritimen Knotenpunkt der Allianz in Khaz Modan. Da das Sumpfland rund um den Hafen von Sumpfbestien und aggressiven Orcs heimgesucht wird, kann Hauptmann Starkfaust nicht zulassen, dass ein schwer bewaffnetes Lager wie Dragonmaw Retreat so nah an den Docks und Handelsrouten des Königreichs floriert.",al={"burg menethil bedrohung durch dragonmaw","warum es starkfaust kümmert","verteidigung des hafens von menethil"}}},fp="18,389,24.469.0,25.479.0,25.398.0,41.365.0,35.362.0,29.356.0,50.362.0,50.382.0"}
P.entries["quest:98298"] = {n="Arugal's Folly",s="Arugal's Folly ist eine Quest der Verlassenen im Silberwald, bei der Dalar Morgenweber den wahren Ursprung der Worgen untersucht, die in der Nähe des Greymane-Walls lauern. Durch die Analyse erbeuteter Worgenüberreste versucht Dalar zu beweisen, dass Erzmagier Arugal ein Betrüger war, der die Kreaturen lediglich band, anstatt ihren Fluch heraufzubeschwören.",h="Arugal's Folly ist eine Quest der Verlassenen im Silberwald, bei der Dalar Morgenweber den wahren Ursprung...",kw={"arugal","arugal's folly","dalar morgenweber","der greymane-wall","silberwald","das grabmal","worgenteile","worgenfluch"},ang={["class:Mage"]="Praktiker der Arkanmagie können Dalars analytische Dekonstruktion von Arugals sogenanntem magischen Fluch nachvollziehen und den Unterschied zwischen bindenden Verzauberungen und übertragbaren Leiden erkennen.",["faction:Horde"]="Abenteurer der Horde, die Dalar Morgenweber unterstützen, tragen dazu bei, den Silberwald sowohl vor zügellosen wilden Raubtieren als auch vor den benachbarten Menschensiedlungen zu schützen, die dem Leiden erliegen.",["race:Undead"]="Für die im Grabmal ansässigen Verlassenen ist die Entschlüsselung der wahren Natur des Worgenausbruchs im Silberwald von entscheidender Bedeutung, um Lordaeron vor unkontrollierbaren wilden Bedrohungen zu schützen."},sec={{t="Die Entlarvung des Erzmagiers",b="Stationiert im Grabmal im Silberwald versucht der Magier der Verlassenen Dalar Morgenweber, den Mythos um seinen Rivalen, Erzmagier Arugal, zu demontieren. Nach der Untersuchung verzauberter Fesseln stellt Dalar fest, dass es Arugal an der rohen Macht fehlte, die Worgenrudel, die die Region terrorisieren, hervorzubringen oder ihren Ursprung zu bilden. Stattdessen verfügte Arugal lediglich über geringfügige Verzauberungen, die dazu fähig waren, die Bestien vorübergehend zu binden, wodurch die wahre Mechanik und die Entstehung ihrer bestialischen Seuche ein ungelöstes Rätsel bleiben."},{t="Der bestialische Übergriff",b="Auf der Suche nach empirischen Beweisen entsendet Dalar Abenteurer nach Süden zu den imposanten Befestigungen des Greymane-Walls. In der umliegenden Wildnis haben wilde Worgen begonnen, nahe gelegene Menschenpopulationen zu überfallen und zu infizieren. Indem sie die unersättlichen Kreaturen zur Strecke bringen und anatomische Gewebeproben beschaffen, versorgen die Ermittler Dalar mit den direkten physischen Proben, die zur Analyse der biologischen und magischen Realität des Leidens erforderlich sind."},{t="Eine bittere Genugtuung",b="Nach der Inspektion der gesammelten Worgenüberreste verkündet Dalar voller Freude den Sieg über Arugals akademischen Ruf und bestätigt, dass der Erzmagier keinen Anteil am Ursprung des Leidens hatte. Diese Offenbarung birgt jedoch eine düstere Konsequenz für die Verlassenen: Wenn Arugal den Fluch niemals erschaffen hat, dann sind die angeblichen Heilmittel und Gegenmaßnahmen, die er ersonnen hat, völlig wertlos, wodurch das wahre Geheimnis des Worgenausbruchs gänzlich ungelöst bleibt."}},faq={{q="Wer vergibt die Quest Arugal's Folly?",a="Die Quest wird von Dalar Morgenweber angeboten und abgeschlossen, einem arkanen Forscher und Magier der Verlassenen, der im Grabmal im Silberwald stationiert ist.",al={"wer gibt arugals folly","wo gebe ich arugals folly ab","questgeber arugals folly"}},{q="Warum hält Dalar Morgenweber Arugal für einen Betrüger?",a="Dalar Morgenweber kommt zu dem Schluss, dass Erzmagier Arugal ein arroganter Betrüger ist. Dalar argumentiert, dass Arugal kaum genug magisches Können besaß, um die Worgen vorübergehend zu binden, geschweige denn sie zu erschaffen oder hervorzubringen, was den sogenannten „Fluch von Arugal“ als Schwindel entlarvt.",al={"was denkt dalar über arugal","hat arugal die worgen erschaffen","arugal betrüger"}},{q="Wo findet Ihr die Worgenteile für Dalar?",a="Um die Quest abzuschließen, reisen Abenteurer durch den Silberwald nach Süden in Richtung des Greymane-Walls, wo die wilden Worgen in der Nähe der örtlichen Menschensiedlungen lauern. Das Töten dieser Bestien liefert die Worgenteile, die Dalar für seine Untersuchung benötigt.",al={"wo sind die worgenteile","greymane-wall worgen","wohin bei arugals folly"}},{q="Findet Dalar ein Heilmittel für den Worgenfluch?",a="Hier wird kein Heilmittel entdeckt. Da Dalar herausfindet, dass Arugal das Worgenleiden gar nicht erst erschaffen hat, sind alle von Arugal ersonnenen Heilmittel oder Gegenzauber völlig nutzlos, sodass die Verlassenen anderswo nach einer wahren Lösung suchen müssen.",al={"kann der worgenfluch geheilt werden","funktioniert arugals heilmittel","gibt es ein heilmittel gegen worgen"}},{q="Wie breitet sich das Worgenleiden in der Nähe des Greymane-Walls aus?",a="Dalar stellt fest, dass sich das Worgenleiden offenbar durch physische Begegnungen und Bisse direkt auf die nahe gelegenen Menschenpopulationen am Greymane-Wall überträgt und nicht über ein allumfassendes arkanes Ritual oder einen von Arugal gewirkten Zauber.",al={"wie verbreitet sich der fluch","worgen verbreiten sich auf menschen","wer wird infiziert"}},{q="Welchen Schluss zieht Dalar nach der Untersuchung der Worgenteile?",a="Die Untersuchung der anatomischen Teile der getöteten Worgen beweist Dalar, dass ihr Fluch nichts mit Arugals Zauberei zu tun hat. Obwohl dies die magische Inkompetenz seines Rivalen bestätigt, bekräftigt es zugleich, dass der Worgenfluch eine aktive, unerklärte Bedrohung ohne funktionierendes Gegenmittel bleibt.",al={"was erfährt dalar aus den teilen","fazit arugals folly","arugals folly lore enthüllung"}}},fp="14,316,21.476.0,21.440.0,20.435.1,35.143.0,50.256.0,44.244.0,44.255.0,62.233.0,58.282.0"}
P.entries["quest:98299"] = {n="Stop the Spread",s="Stop the Spread ist eine Quest im Silberwald, die sich mit der Eindämmung des Worgenfluchs befasst, der mit Erzmagier Arugal in Verbindung steht. Während Forscher nach einem Weg suchen, das Leiden aufzuhalten, werden am Greymane-Wall Präventivmaßnahmen gegen lebende menschliche Flüchtlinge angeordnet, um zu verhindern, dass sie zu Dienern Arugals werden.",h="Stop the Spread ist eine Quest im Silberwald, die sich mit der Eindämmung des Worgenfluchs befasst, der mit...",kw={"arugal","fluch","verlassene","der greymane-wall","flüchtlinge","silberwald","skyborne","stop the spread","worgen"},ang={["race:Human"]="Nicht infizierte menschliche Flüchtlinge, die sich am versiegelten Greymane-Wall zusammendrängen, werden von Forschern der Verlassenen als Hauptüberträger für Arugals sich ausbreitenden Fluch angesehen.",["race:Skyborne"]="Skyborne-Abenteurer werden direkt davor gewarnt, sich beißen zu lassen, während sie die finsteren Eindämmungsbefehle nahe dem Greymane-Wall ausführen.",["race:Undead"]="Die Verlassenen scheinen einzigartig immun gegen das Worgenleiden zu sein, was Eindämmungsoperationen ohne Infektionsrisiko für untote Streitkräfte möglich macht."},sec={{t="Das Leiden im Silberwald",b="Im Silberwald breitet sich die Plage der Worgen durch das Zutun des abtrünnigen Erzmagiers Arugal aus. Während die genauen Methoden und Mechanismen hinter der Ausbreitung dieses wilden Zustands weitgehend unbekannt bleiben, ist die Gefahr, die er für das Gebiet darstellt, unbestreitbar. Forscher arbeiten aktiv daran, die Natur der Magie zu verstehen, doch ihr unmittelbarer Schwerpunkt liegt darauf zu verhindern, dass Arugal eine unaufhaltsame Schar wilder Gefolgsleute um sich schart."},{t="Eindämmung am Wall",b="Ermittler der Verlassenen haben beobachtet, dass ihre untote Physiologie sie gegen die Worgeninfektion immun macht. Lebende Menschen besitzen jedoch keinen solchen natürlichen Schutz. An der südlichen Grenze hat sich ein verzweifeltes Lager menschlicher Flüchtlinge um die verschlossenen Tore des Greymane-Walls gesammelt aus Furcht, dass diese wehrlosen Überlebenden gebissen und in loyale Knechte für Arugal verwandelt werden, wurden präventive und rücksichtslose Eindämmungsbefehle erteilt, um die Ansammlung zu säubern, bevor das Leiden sie befällt."}},faq={{q="Worum geht es in der Quest Stop the Spread?",a="Stop the Spread ist eine Mission, die sich auf die Eindämmung des Worgenfluchs konzentriert, der den Silberwald heimsucht. Um zu verhindern, dass Erzmagier Arugal neue Diener gewinnt, werden Streitkräfte entsandt, um menschliche Flüchtlinge nahe dem Greymane-Wall zu eliminieren, bevor sie dem Leiden erliegen können.",al={"was ist stop the spread","stop the spread quest lore"}},{q="Wer ist für die Worgen im Silberwald verantwortlich?",a="Erzmagier Arugal wird für die Anwesenheit der Worgen im Silberwald verantwortlich gemacht, sei es durch seine absichtlichen Machenschaften oder unvorhergesehene Folgen seiner Magie. Sein wachsendes Rudel bedroht die gesamte Region.",al={"wer verbreitet den worgenfluch","arugal worgen verbindung"}},{q="Können die Verlassenen den Worgenfluch bekommen?",a="Lokalen Forschungen der Verlassenen zufolge kann der Worgenfluch Untote nicht infizieren. Diese Immunität ermöglicht es den Agenten der Verlassenen, der Bedrohung entgegenzutreten, ohne Gefahr zu laufen, sich in bestialische Diener Arugals zu verwandeln.",al={"können verlassene zu worgen werden","sind untote immun gegen worgen"}},{q="Warum werden menschliche Flüchtlinge am Greymane-Wall ins Visier genommen?",a="Vor dem versiegelten Greymane-Wall hat sich eine große Menschenmenge von Flüchtlingen versammelt. Da lebende Menschen anfällig für Arugals Fluch sind, gelten sie als unmittelbare Bedrohung, die Reihen der Worgen anschwellen zu lassen.",al={"warum flüchtlinge töten","flüchtlinge am greymane-wall"}},{q="Wie verbreitet sich das Worgenleiden?",a="Obwohl bekannt ist, dass der Worgenfluch durch Bisse übertragen werden kann, werden die genauen magischen und biologischen Mechanismen seiner Ausbreitung von Forschern im Silberwald noch aktiv untersucht.",al={"wie verbreiten sich worgen","übertragung des worgenfluchs"}},{q="Gibt es einen Weg, den Worgenfluch aufzuhalten oder zu heilen?",a="Gegenwärtig gibt es kein bekanntes Heilmittel für das Worgenleiden. Forscher versuchen, ein Mittel zu entdecken, um den Fluch aufzuhalten, doch ihre unmittelbare Priorität bleibt die aggressive Eindämmung.",al={"kann der worgenfluch geheilt werden","heilung für worgen"}}},fp="15,307,25.434.0,23.511.1,40.259.0,48.223.0,40.203.0,59.218.0,38.201.0,48.189.0"}
P.entries["quest:983"] = {n="Dröhnkiste 827",s="Dröhnkiste 827 ist die erste Station einer experimentellen Kommunikationskette, die der Gnom Hexknall Kurbeldreh entlang der Küste der Dunkelküste errichtet hat. Diese sonderbaren mechanischen Vorrichtungen werden von ständigen Pannen geplagt und basieren auf einer exzentrischen Konstruktion, die Teile der heimischen Tierwelt für Reparaturen vor Ort nutzt. Wird die verstummte Maschine wieder in Gang gesetzt, kann Wizbang sein Fernsprechnetzwerk direkt von Auberdine aus testen.",h="Dröhnkiste 827 ist die erste Station einer experimentellen Kommunikationskette, die der Gnom Hexknall...",kw={"auberdine","dröhnkiste 827","kriecherbeine","dunkelküste","gnomen-ingenieurskunst","reef crawler","tide crawler","hexknall kurbeldreh"},ang={["profession:Engineering"]="Die Verwendung von organischem Chitin und Gliederfüßerbeinen anstelle von geschmiedeten Messingzahnrädern ist gnomische Improvisation in Reinkultur, bei der Haltbarkeit zugunsten leicht zu beschaffender lokaler Materialien eingetauscht wird.",["race:Gnome"]="Wizbangs Vorrichtung steht stellvertretend für den klassischen Ehrgeiz der Gnome, technologische Vernetzung in ein uraltes, wildes Land zu bringen, das noch nie ein Telefon oder ein Funkgerät gesehen hat.",["race:NightElf"]="Die klappernden, rauchenden Dröhnkisten sind ein bizarrer Fremdkörper an den heiligen, düsteren Küsten von Kalimdor, auch wenn die Nachtelfen von Auberdine die Experimente des Tüftlers dulden."},sec={{t="Gnomische Innovation an uralten Gestaden",b="Während seines Aufenthalts in Auberdine versuchte der exzentrische Gnomen-Ingenieur Hexknall Kurbeldreh, die weiten Distanzen der wilden Küste mit einer Reihe akustischer Weitstrecken-Relais namens Dröhnkisten zu überbrücken. Diese mit Hebeln versehenen Apparaturen wurden entwickelt, um Stimmen über große Entfernungen zu übertragen, und heben sich drastisch von den uralten Ruinen und düsteren Wäldern der Dunkelküste ab. Wie viele ehrgeizige Erfindungen der Gnome leiden sie jedoch unter ständiger Instabilität und erfordern beinahe ununterbrochene Wartung, damit ihre internen Zahnräder weiterlaufen."},{t="Ökologische Wartung",b="Statt geschmiedete Eisenzahnräder und Kupferstifte durch die Wildnis zu schleppen, wählte Wizbang eine unkonventionelle Lösung: Er konstruierte jede Dröhnkiste so, dass sie mit Komponenten der heimischen Tierwelt instand gehalten werden kann. Dröhnkiste 827, die südlich von Auberdine an der nebligen Küste steht, wurde so konstruiert, dass sie mit den robusten Gliedmaßen der örtlichen Gezeiten- und Riffkriecher funktioniert. Sobald die Beine in den Aufgabetrichter geworfen werden, setzt sich die Maschine selbstständig zusammen, erwacht wieder zum Leben und überträgt Wizbangs ferne Stimme über ihre Lautsprecher."}},faq={{q="Was ist eine Dröhnkiste?",a="Eine Dröhnkiste ist eine Maschine zur Fernübertragung von Sprache, die von dem Gnom Hexknall Kurbeldreh erfunden wurde. Ausgestattet mit Hebeln und interner Mechanik ist sie darauf ausgelegt, Stimmen über die ungezähmten Weiten der Dunkelküste hinweg zu übertragen, sodass Personen über meilenweite Entfernungen hinweg miteinander sprechen können.",al={"was macht eine dröhnkiste","dröhnkiste zweck","gnomenkasten dunkelküste"}},{q="Warum benötigt eine Metallmaschine Krabbenbeine, um zu funktionieren?",a="Wizbang hat jede Dröhnkiste ganz bewusst so konstruiert, dass organische Komponenten der umliegenden Fauna als improvisierte Ersatzteile genutzt werden können. Indem er Dröhnkiste 827 in Strandnähe platzierte, wo Kriecher leben, stellte er sicher, dass Reisende mechanische Notfallreparaturen mit Chitin-Gliedmaßen anstelle von seltenem, gefrästem Metall durchführen können.",al={"warum kriecherbeine","kriecherbein reparatur","warum mit beinen füttern"}},{q="Wo befindet sich Dröhnkiste 827?",a="Dröhnkiste 827 steht an der Küstenlinie der Dunkelküste, nur eine kurze Reise südlich der Küstensiedlung Auberdine.",al={"dröhnkiste 827 standort","wo ist dröhnkiste 827","dröhnkiste 827 finden"}},{q="Wer ist Hexknall Kurbeldreh?",a="Hexknall Kurbeldreh ist ein gnomischer Tüftler, der im oberen Stockwerk des Gasthauses von Auberdine untergekommen ist. Ehrgeizig und geschäftstüchtig versucht er, trotz der ständigen Fehlfunktionen seiner Prototypen ein zusammenhängendes Kommunikationsnetz über die Dunkelküste hinweg zu errichten.",al={"hexknall kurbeldreh","wer baute die dröhnkiste","auberdine gnom"}},{q="Wo lassen sich Kriecherbeine für die Reparatur finden?",a="Kriecherbeine können von Pygmy Tide Crawlern und Young Reef Crawlern erbeutet werden, die über den Sand und durch die Untiefen des Strandes der Dunkelküste südlich von Auberdine huschen.",al={"kriecherbeine fundort","kriecherbeine bekommen","pygmy tide crawler"}},{q="Was passiert, sobald Dröhnkiste 827 repariert ist?",a="Sobald die Kriecherbeine in den Trichter geworfen werden, verarbeitet die Maschine sie an Ort und Stelle, erwacht summend zum Leben und überträgt Wizbangs Stimme aus Auberdine. Erfreut über den Erfolg bittet er Euch sogleich, Die Küste entlang weiterzureisen, um die nächste Einheit der Kette, Dröhnkiste 411, zu reparieren.",al={"nach dröhnkiste 827","dröhnkisten questreihe weiter","dröhnkiste 827 abschluss"}}},fx={aa80bf26={q="Warum will Hexknall Kurbeldreh, dass Buzzbox 827 repariert wird?",a="Hexknall Kurbeldreh testet seine neueste Erfindung: ein experimentelles Kommunikationsnetzwerk an der Dunkelküste, das es Menschen ermöglicht, über große Entfernungen miteinander zu sprechen. Leider benötigen seine Buzzboxen ständige Wartung und gehen häufig kaputt. Buzzbox 827 wieder betriebsbereit zu machen, ist der erste Schritt, um zu beweisen, dass sein Netzwerk tatsächlich funktioniert.",al={"hexknall kurbeldrehs beweggrund","warum buzzbox 827 reparieren","warum braucht wizbang das erledigt"}},["2c1df07a"]={q="Wofür werden die Kriecherbeine verwendet?",a="Wizbang hat jede Buzzbox so konzipiert, dass sie auf Teilen basiert, die von nahegelegenen einheimischen Wildtieren geerntet werden. Buzzbox 827 benötigt speziell sechs Kriecherbeine, um abgenutzte oder kaputte mechanische Komponenten innerhalb ihres Haltemechanismus zu ersetzen. Sobald sie eingesetzt sind, mahlen die inneren Zahnräder des Geräts und rasten die Beine an ihrem Platz ein, um die Stromversorgung und Übertragung wiederherzustellen.",al={"wofür sind kriecherbeine","kriecherbein buzzbox","warum kriecherbeine"}}},fp="11,384,36.502.0,22.539.0,18.258.0,47.302.0,29.121.0,27.256.0,45.164.0,42.278.1"}
P.entries["quest:98319"] = {n="Secure the Mountain",s="Secure the Mountain ist eine Quest der Allianz, die sich mit dem plötzlichen Ansturm von Wendigos befasst, die den altgedienten Bau in Dun Morogh überrennen. Abenteurer werden in die verseuchte Höhle geschickt, um einen übereifrigen Zwergenspäher namens Cornelius ausfindig zu machen und einen entscheidenden Bericht für Whitebeard zu bergen.",h="Secure the Mountain ist eine Quest der Allianz, die sich mit dem plötzlichen Ansturm von Wendigos befasst...",kw={"cornelius","dun morogh","der altgediente bau","gebirgsjäger","secure the mountain","troll","wendigo","whitebeard"},ang={["faction:Alliance"]="Sicherzustellen, dass Whitebeard Geheimdienstberichte erhält, ist für die Streitkräfte der Allianz von entscheidender Bedeutung, um die Grenzsicherheit gegen einheimische Bergbedrohungen aufrechtzuerhalten.",["race:Dwarf"]="Die Rückeroberung von Höhlen wie dem altgedienten Bau schützt Zwergengebirgsjäger und Reisende vor aggressiven Wendigos, die auf Dun Moroghs Pfade vordringen."},sec={{t="Ein überrannter Bau",b="Zwergenspäher, die die eisigen Berghänge überwachen, sehen sich an zwei Fronten mit Problemen konfrontiert. Abgesehen von der allgegenwärtigen Bedrohung durch die Frostmane-Trolle haben die einheimischen Wendigos begonnen, sich aggressiv zu vermehren, und verlassen ihre gewohnten einsamen Höhlen, um sich im altgedienten Bau im Norden zusammenzurotten. Diese wilden Bestien machen das Reisen durch das zerklüftete Gebirge für Patrouillen und Kuriere gleichermaßen gefährlich."},{t="Waghalsiger Mut",b="Ein Späher namens Cornelius stürmte kopfüber in den altgedienten Bau, um einen wichtigen Bericht für Whitebeard zu sichern. Seine impulsive Tapferkeit ließ seinen Partner draußen stranden, der fähige Abenteurer sucht, die bereit sind, in die von Bestien wimmelnde Höhle vorzudringen, den leichtsinnigen Zwerg aufzuspüren und die wilde Wendigopopulation auszudünnen."}},faq={{q="Wer ist Cornelius?",a="Cornelius ist ein Späher oder Gebirgsjäger und Partner des Questgebers. Getrieben von waghalsigem Mut stürmte er geradewegs in den von Wendigos verseuchten altgedienten Bau und ließ seinen Partner draußen zurück, der auf Hilfe wartet, um sowohl ihn als auch Whitebeards Bericht zu retten.",al={"wer ist cornelius","cornelius zwerg","wo ist cornelius"}},{q="Was ist der altgediente Bau?",a="Der altgediente Bau ist eine Höhle nördlich des Postens der Gebirgsjäger. Während Wendigos normalerweise auf tiefe Berghöhlen beschränkt bleiben, haben sie den Bau vor Kurzem in ungewöhnlich großer Zahl überrannt.",al={"was ist der altgediente bau","wo sind wendigos","wendigohöhle dun morogh"}},{q="Warum breiten sich die Wendigos aus?",a="Wendigos halten sich für gewöhnlich in abgelegenen Höhlen auf, doch örtliche Späher bemerken, dass sie begonnen haben, sich rasch zu vermehren und über die verschneiten Bergklippen auszubreiten, was neben der örtlichen Trollbedrohung eine ernste Gefahr darstellt.",al={"warum wendigos sich ausbreiten","wendigoproblem dun morogh","wendigos wie kaninchen"}},{q="Wer ist Whitebeard und was ist sein Bericht?",a="Whitebeard ist eine Autoritätsperson oder ein Kommandant, der einen wichtigen Aufklärungsbericht über die Bedingungen im Gebirge erwartet. Cornelius trug diesen Bericht bei sich oder sicherte ihn, bevor er rücksichtslos in den Bau stürmte.",al={"wer ist whitebeard","whitebeard-bericht","senir weißbart"}},{q="Was ist das Ziel von Secure the Mountain?",a="Es handelt sich um eine Rettungs- und Dezimierungsmission, bei der Abenteurer beauftragt werden, den altgedienten Bau zu betreten, um den vermissten Späher Cornelius zu finden und die feindseligen Wendigos auszudünnen, die die Höhle heimsuchen.",al={"was ist secure the mountain","ziel von secure the mountain"}},{q="Welche Rolle spielen die Trolle bei den Problemen im Gebirge?",a="Einheimische Späher stehen bereits unter anhaltendem Druck durch die ansässigen Frostmane-Trolle in den Gipfeln. Die plötzliche Zunahme aggressiver Wendigos schafft eine gefährliche Zwei-Fronten-Bedrohung für Patrouillen, die versuchen, die Bergpässe zu sichern.",al={"trolle dun morogh","trollbedrohung"}}},fp="19,269,13.358.0,14.321.0,17.251.0,25.196.0,31.204.0,41.195.0,40.177.0,54.215.0"}
P.entries["quest:98321"] = {n="Flintfire's Shipment",s="Tognus Flintfire in Kharanos steht vor einem schweren Versorgungsengpass, nachdem wilde Wendigos seine Haupterzquelle im Graufelsbau überrannt haben. Da die Bergleute während der Evakuierung gezwungen waren, ihre Kisten zurückzulassen, werden Abenteurer damit beauftragt, die verlorenen Lieferungen zu bergen, um die örtlichen Schmieden in Betrieb zu halten.",h="Tognus Flintfire in Kharanos steht vor einem schweren Versorgungsengpass, nachdem wilde Wendigos seine...",kw={"dun morogh","flintfire","schmiede","der graufelsbau","kharanos","bergleute","erz","lieferungen","tongus flintfire","wendigo"},ang={["profession:Blacksmithing"]="Die Bergung von Flintfires Lieferungen ist von entscheidender Bedeutung, um die örtlichen Schmieden in Kharanos mit bearbeitbarem Metall zu versorgen.",["profession:Mining"]="Die verlorenen Lieferungen bestehen aus lebenswichtigem Erz, das von Bergleuten zurückgelassen wurde, die ihre primäre Ausgrabungsstätte evakuierten, als Wendigos angriffen.",["race:Gnome"]="Tognus Flintfire heißt insbesondere Gnom-Abenteurer willkommen, die bereit sind, in Dun Morogh harte körperliche Arbeit zu leisten, und zeigt aufrichtige Wertschätzung für ihren Mut."},sec={{t="Eine Versorgungskrise in Kharanos",b="In der verschneiten Siedlung Kharanos sieht sich Tognus Flintfire mit einer kritischen Versorgungskrise an seiner Schmiede konfrontiert. Die produktivste und verlässlichste Erzquelle der Region ist plötzlich verstummt, nachdem wilde Wendigos die Ausgrabungsstätte überrannt haben. Von den wilden Raubtieren überrascht, mussten die örtlichen Bergleute ihre Posten von einem Moment auf den anderen aufgeben, flohen um ihr Leben und ließen frisch gepackte Kisten mit wertvollem Erz auf dem Höhlenboden verstreut zurück."},{t="Der Vorstoß in den Graufelsbau",b="Die überrannte Mine, bekannt als der Graufelsbau, liegt westlich von Kharanos. Obwohl Tognus dankbar ist, dass jeder Bergmann den wilden Bestien unversehrt entkommen konnte, droht der Arbeitsstillstand das örtliche Schmiedehandwerk völlig lahmzulegen. Anstatt auf eine bewaffnete Expedition zur Säuberung der Höhle zu warten, sucht Tognus nach wagemutigen Abenteurern, die sich in den Wendigobau schleichen, die gestrandeten Kisten einsammeln und das lebenswichtige Erz zurück zur Schmiede bringen."}},faq={{q="Wer ist Tognus Flintfire?",a="Tognus Flintfire ist ein Zwerg in Kharanos, der auf stetige Lieferungen von gefördertem Erz angewiesen ist, um seine Schmiede betriebsbereit zu halten. Angesichts eines schweren Versorgungsengpasses, nachdem Wendigos seine primäre Bergbauhöhle überrannt haben, heuert er Reisende an, um der Gefahr zu trotzen und die verlassenen Kisten zu bergen.",al={"wer ist tongus flintfire","tongus flintfire","questgeber"}},{q="Wo befindet sich der Graufelsbau?",a="Der Graufelsbau ist ein Höhlensystem westlich von Kharanos in Dun Morogh. Einst eine verlässliche Abbaustätte, dient er nun wilden Wendigos als Bau, was jeden, der nach dem verlorenen Erz sucht, dazu zwingt, sich in feindliches Gebiet zu wagen.",al={"wo ist der graufelsbau","ort des graufelsbaus","wo lieferungen zu finden sind"}},{q="Warum wurde die Bergbauhöhle aufgegeben?",a="Die Höhle war die verlässlichste Erzquelle der einheimischen Bergleute, bis feindselige Wendigos eindrangen und die Stätte überrannten. Die Arbeiter waren gezwungen, ihre Ausrüstung und gelagerten Lieferungen bei einer verzweifelten Flucht fallen zu lassen, und kamen wie durch ein Wunder mit dem Leben davon.",al={"warum bergleute fliehen","was mit der mine geschah","wendigo-angriff"}},{q="Was befindet sich in den verschwundenen Lieferungen?",a="Die Lieferungen bestehen aus gefördertem Erz, das von den Bergleuten in Kisten verpackt wurde, bevor sie vertrieben wurden. Ohne diese Materialien kommen die örtliche Metallverarbeitung und die Schmiedearbeiten in Kharanos völlig zum Erliegen.",al={"was sind flintfires lieferungen","was ist in den kisten","inhalt der lieferung"}},{q="Wurde bei dem Angriff einer der Bergleute verletzt?",a="Trotz der furchterregenden Wildheit der Wendigos stellt Tognus mit Erleichterung fest, dass alle Bergleute dem Graufelsbau unversehrt entkommen konnten und lediglich ihre Vorräte und ihr Erz zurückließen.",al={"haben die bergleute überlebt","bergbau-opfer","wendigo-opfer"}},{q="Was passiert, sobald die Lieferungen geborgen sind?",a="Die Sicherung der geborgenen Lieferungen versorgt Tognus Flintfire mit dem Rohmetallbestand, der erforderlich ist, um die örtliche Schmiede wieder anzufeuern und in Betrieb zu nehmen, ohne vorher die gesamte verseuchte Höhle säubern zu müssen.",al={"warum erz benötigt wird","was nach der bergung geschieht","schmiede in betrieb"}}},fp="20,302,27.462.0,31.435.0,24.270.0,34.235.0,34.255.0,37.209.0,42.189.0,46.204.0"}
P.entries["quest:98322"] = {n="Secure the Mountain",s="Secure the Mountain ist eine Quest der Allianz, die in Kharanos in Dun Morogh ihren Anfang nimmt. Ein lokaler Beamter, der Informationen für Eisenschmiede sammelt, schickt Abenteurer westlich der Stadt, um nach Bergsteigerin Gretchen zu sehen, nachdem Späher, die aggressive Wendigos untersuchen, sich nicht wie vorgesehen gemeldet haben.",h="Secure the Mountain ist eine Quest der Allianz, die in Kharanos in Dun Morogh ihren Anfang nimmt.",kw={"dun morogh","zwerg","eisenschmiede","kharanos","bergsteigerin gretchen","secure the mountain","wendigo","weißbart"},ang={["faction:Alliance"]="Das Unterstützen lokaler Zwergenpatrouillen rund um Kharanos stärkt die defensive Koordination im gesamten verschneiten Herzen von Khaz Modan.",["race:Dwarf"]="Dun Moroghs Bergsteiger unterhalten wachsame Patrouillen über verschneiten Graten und gefährlichen Höhlen, wodurch verlässliche Aufklärung unerlässlich für die Sicherheit von Zwergensiedlungen bleibt."},sec={{t="Ein überfälliger Bericht",b="Beauftragt mit dem Zusammentragen lokaler militärischer Informationen für den High Seat von Eisenschmiede, sieht sich ein Beamter in Kharanos in seiner alltäglichen Korrespondenz unterbrochen. Ein Bergsteiger-Team, das entsandt wurde, um die nahegelegene Wendigo-Aktivität zu beurteilen, ist nicht mit Neuigkeiten zurückgekehrt. Anstatt selbst durch eisige Höhlen zu klettern, heuert der Bürokrat fähige Reisende an, damit sie sich kurz westlich der Stadt wagen und den Status der Späher feststellen."},{t="Ärger auf dem westlichen Grat",b="Beim Aufspüren von Bergsteigerin Gretchen westlich von Kharanos weicht die ruhige Routine der regionalen Überwachung der Beunruhigung. Gretchen bestätigt, dass Weißbarts Anfragen sie erreicht haben, offenbart jedoch, dass die Wendigo-Unruhe in den umliegenden Bergschrofen weitaus unbeständiger ist, als anfängliche Depeschen vermuten ließen, was den Weg für tiefergehende Aufklärung in der nahen Wildnis ebnet."}},faq={{q="Wer vergibt die Quest Secure the Mountain?",a="Die Quest wird von Senir Weißbart in Kharanos vergeben, der von Gebirgsjägerin Gretchen als „der alte Weißbart“ bezeichnet wird. Zu seinen Pflichten gehört es, offizielle Berichte über lokale Bedrohungen aus der Wildnis zu verfassen und sie an die Zwergenführung in Eisenschmiede zu übermitteln.",al={"wer vergibt secure the mountain","questgeber secure the mountain","wer startet secure the mountain"}},{q="Wo kann Bergsteigerin Gretchen gefunden werden?",a="Bergsteigerin Gretchen ist kurz westlich der Ortschaft Kharanos in Dun Morogh stationiert und behält die örtliche Bedrohung durch die Wendigos an den Berghängen und nahegelegenen Höhlen im Auge.",al={"wo ist gretchen","aufenthaltsort bergsteigerin gretchen","bergsteigerin gretchen finden"}},{q="Warum sucht der Questgeber nach Bergsteigerin Gretchen?",a="Der Questgeber ist dafür verantwortlich, Aufklärungsberichte an Eisenschmiede zurückzusenden, doch der Späher, der zur Untersuchung der lokalen Wendigo-Aktivität entsandt wurde, versäumte es, rechtzeitig Bericht zu erstatten. Da ihm die Zeit davonläuft und er gefährliche Erkundungen in Höhlen vermeiden will, bittet er einen vorbeikommenden Abenteurer, nach Bergsteigerin Gretchen zu sehen.",al={"warum abenteurer senden","warum weißbart hilfe braucht","warum nach gretchen sehen"}},{q="Welches Wendigo-Problem bedroht das Gebiet?",a="Wendigos bewohnen die felsigen Ausläufer und finsteren Höhlen rund um Kharanos. Ihre aggressive Präsenz stellt eine direkte Bedrohung für Reisende und örtliche Außenposten dar, was die Späher aus Eisenschmiede veranlasst, ihre Bewegungen genau zu überwachen.",al={"wendigo-bedrohung kharanos","was wendigos tun","warum wendigo-problem"}},{q="Was berichtet Bergsteigerin Gretchen bei der Ankunft?",a="Als Ihr Bergsteigerin Gretchen westlich der Stadt erreicht, bestätigt sie den Erhalt von Weißbarts Anfragen und bemerkt grimmig, dass die gesamte Situation bezüglich der nahen Wendigos zu einem handfesten Schlamassel geworden ist.",al={"was gretchen sagt","abgabe secure the mountain","statusbericht gretchen"}},{q="Welche Rolle spielen Bergsteiger rund um Kharanos?",a="Bergsteiger dienen als primäre Grenzwächter, Fährtenleser und Spähtruppen der Zwerge von Eisenschmiede; sie überwachen abgelegene Pässe, finstere Höhlen und verschneite Pfade in ganz Dun Morogh, um Ortschaften wie Kharanos zu schützen.",al={"wer sind bergsteiger","eisenschmiede bergsteigerpatrouille","was tun bergsteiger"}}},fp="19,263,17.400.0,28.377.1,40.242.0,40.162.0,55.298.0,45.217.0,51.195.0,47.205.0"}
P.entries["quest:98323"] = {n="Secure the Mountain",s="Secure the Mountain ist ein Aufklärungsbericht, der im Auftrag von Gebirgsjägerin Gretchen an Senir Weißbart in Kharanos überbracht wird. Nachdem sich eine Expedition in eine nahegelegene Höhle als katastrophal erweist, gelangt Gretchen zu dem Schluss, dass die Höhle ein aussichtsloser Fall ist, und weigert sich, weitere Späher in die überrannte Todesfalle zu schicken. Die Mission verdeutlicht das ständige Ringen der Gebirgsjäger von Eisenschmiede, Dun Morogh inmitten wachsender Bedrohungen zu schützen.",h="Secure the Mountain ist ein Aufklärungsbericht, der im Auftrag von Gebirgsjägerin Gretchen an Senir Weißbart...",kw={"höhle","cornelius","dun morogh","kharanos","gebirgsjägerin gretchen","bericht der gebirgsjägerin","secure the mountain","senir weißbart"},ang={["faction:Alliance"]="Die Sicherung der Hochpässe rund um Eisenschmiede ist von entscheidender Bedeutung, um sicheres Reisen und die Verteidigung der schneebedeckten Feste der Allianz in Khaz Modan aufrechtzuerhalten.",["race:Dwarf"]="Dun Morogh ist die angestammte bergige Heimat der Bronzebergyzwerge, weshalb Gebirgsjägerin Gretchens beharrliche Wacht ein unerlässlicher Einsatz ist, um ihr Volk vor den umliegenden Gefahren zu bewahren."},sec={{t="Ein düsterer Bericht",b="Gebirgsjägerin Gretchen ist in den eisigen Höhen von Dun Morogh stationiert und hält Wache mit dem Befehl, für die Sicherheit der Hochpässe zu sorgen. Ein kürzlicher Vorstoß in eine nahegelegene Höhle offenbart jedoch, dass die Wildnis keineswegs befriedet ist. Nach einer Lagebeurteilung kommt Gretchen zu dem Schluss, dass die Höhle zu einer regelrechten Todesfalle geworden ist, die von feindseligen Bastarden überrannt wurde. Anstatt weitere Menschenleben zu riskieren, verbleibt sie auf ihrem Posten an den Hängen – fest entschlossen, die Stellung zu halten, während sie einen Boten entsendet, um ihren schriftlichen Lagebericht zu überbringen."},{t="Verluste in den Tiefen",b="Der Entschluss, keine weiteren Vorstöße in die Höhle zu unternehmen, folgt auf ein schweres Opfer. Unter den Opfern des gescheiterten Aufklärungseinsatzes war Cornelius, dessen Verlust Gebirgsjägerin Gretchen schwer belastet. In dem Eingeständnis, dass die Höhle unter den gegenwärtigen Bedingungen nicht zurückerobert werden kann, ordnet sie die Einstellung aller weiteren Erkundungsmissionen in die unterirdischen Tunnel an. Ihre Priorität verlagert sich von einer offensiven Säuberung auf eine defensive Eindämmung, da sie sich weigert, noch mehr Späher sinnlos an die bösartigen Kreaturen zu opfern, die unter den schneebedeckten Felsen lauern."},{t="Senir Weißbarts Dossier",b="In der geschäftigen Siedlung Kharanos verfolgt Senir Weißbart die zahlreichen Gefahren, die das Zwergenkernland bedrohen. Bei Erhalt von Gretchens düsterem Lagebericht zeigt sich Weißbart kaum überrascht über die Nachricht, dass die Höhle vollkommen überrannt ist. Ergebungsvoll gegenüber der harten Realität, mit der Dun Morogh konfrontiert ist, reiht er Gretchens Schreiben stillschweigend in seinen wachsenden Stapel von Feldberichten ein. Die Aufklärungsinformationen dienen als weiteres ernüchterndes Dokument im umfassenderen Bestreben von Eisenschmiede, das unruhige Grenzland zu erfassen und unter Kontrolle zu halten."}},faq={{q="Wer ist Gebirgsjägerin Gretchen?",a="Gebirgsjägerin Gretchen ist ein Wachposten von Eisenschmiede, der in der verschneiten Wildnis von Dun Morogh stationiert ist. Ihrer Pflicht treu ergeben weigert sie sich, ihren Posten auf dem Berg aufzugeben, bis das umliegende Gebiet als gesichert gilt. Nach einem verhängnisvollen Aufklärungseinsatz in einer nahegelegenen Höhle verfasst sie einen offiziellen Feldbericht, der die starke feindliche Präsenz darlegt, und entsendet ihn nach Kharanos.",al={"gretchen","gebirgsjägerin gretchen lore","wer ist gretchen"}},{q="Wer ist Senir Weißbart?",a="Senir Weißbart ist eine zwergische Respektsperson, die in der Stadt Kharanos stationiert ist. Er fungiert als Nachrichtensammler und Koordinator für lokale Sicherheitsoperationen in ganz Dun Morogh und nimmt Meldungen sowie Lageberichte von Gebirgsjägern im Feld entgegen. Wenn er über gefährliche feindliche Übergriffe oder verlorene Höhlen unterrichtet wird, katalogisiert er die Berichte in seinen offiziellen Akten, um das regionale Bedrohungsniveau einzuschätzen.",al={"senir weißbart","weißbart kharanos","wer ist senir"}},{q="Wer war Cornelius?",a="Cornelius war ein Gefährte oder Mitspäher, der an der Erkundung der befallenen Berghöhle beteiligt war. Gebirgsjägerin Gretchen erwähnt sein tragisches Schicksal mit Bedauern und deutet an, dass er während des unglückseligen Aufklärungsversuchs verloren ging. Sein Ende beeinflusste maßgeblich Gretchens Entschluss, die Höhle als tödliche Todesfalle einzustufen und zu verbieten, dass darin weitere Leben verwirkt werden.",al={"cornelius","wer ist cornelius","was geschah mit cornelius","cornelius secure the mountain"}},{q="Was geschah in der Berghöhle?",a="Eine Erkundung der Höhle endete im Desaster, als Späher feststellten, dass die Tunnel vollständig von feindseligen Bastarden überrannt waren. Die Mission führte zum tragischen Verlust von Cornelius. Nach dieser düsteren Entdeckung erklärte Gebirgsjägerin Gretchen den unterirdischen Durchgang für aussichtslos und gelangte zu der Überzeugung, dass es selbstmörderisch wäre, weiteres Personal hineinzuschicken, woraufhin sie beschloss, das Gebiet abzuriegeln oder zu meiden.",al={"was ist in der höhle","warum ist die höhle eine todesfalle","höhle aussichtsloser fall"}},{q="Warum weigert sich Gretchen, ihren Posten zu verlassen?",a="Gebirgsjägerin Gretchen nimmt ihren Eid zum Schutz von Dun Morogh ernst und erklärt entschieden, dass sie ihre Stellung nicht aufgeben wird, bis der Berg selbst gesichert ist. Obwohl sie erkennt, dass die nahegelegene Höhle zu gefährlich für eine Rückeroberung ist, verbleibt sie auf den verschneiten Höhen, um den Zugang zu bewachen und Ausschau zu halten, während sie die Nachricht über die Bedrohung nach Kharanos schickt.",al={"warum gretchen bleibt","gretchens posten","warum auf dem berg bleiben"}},{q="Wie reagiert Senir Weißbart auf Gretchens Bericht?",a="Senir Weißbart ist kaum überrascht zu erfahren, dass die Höhle gänzlich überrannt ist, was darauf hindeutet, dass solche feindseligen Heimsuchungen in ganz Dun Morogh zu einem allzu alltäglichen Problem geworden sind. Anstatt Bestürzung zu zeigen, nimmt er die schlechte Nachricht stoisch auf und legt Gretchens schriftliche Meldung zu seinem wachsenden Notizstapel, wobei er die Gefahren, die das Reich bedrohen, akribisch dokumentiert.",al={"senirs reaktion","reaktion von weißbart auf den bericht","was tut senir"}},{q="Welche Rolle spielen die Gebirgsjäger in Dun Morogh?",a="Die Gebirgsjäger dienen als wachsame Grenzspäher und Grenzwächter von Eisenschmiede und patrouillieren auf den tückischen schneebedeckten Gipfeln, Hochpfaden und Bergpässen von Dun Morogh. Weit entfernt von der Wärme der Hauptstadt stationiert, überwachen diese wettergegerbten Zwerge die Bewegungen feindlicher Bestien, kundschaften Höhlen aus und melden entscheidende Informationen an örtliche Knotenpunkte wie Kharanos zurück, um Reisende und Siedlungen zu schützen.",al={"gebirgsjäger von eisenschmiede","was sind gebirgsjäger","zwergen-gebirgsjäger lore"}}},fp="19,408,13.521.0,20.537.1,26.515.0,28.375.0,24.401.0,18.390.0,35.405.0,43.359.0,53.378.0,49.403.0"}
P.entries["quest:98326"] = {n="Frosthowl",s="Frosthowl ist eine Quest in Dun Morogh, bei der Abenteurer damit beauftragt werden, einen gestohlenen Sack Fisch von einem diebischen Wendigo wiederzubeschaffen. Die Bestie überfiel eine einheimische Zwergenfischerin und floh in die Tiefen des Graufelsbaus.",h="Frosthowl ist eine Quest in Dun Morogh, bei der Abenteurer damit beauftragt werden, einen gestohlenen Sack...",kw={"dun morogh","frosthowl","zugefrorener see","der graufelsbau","eisfischen","paxton","gestohlener fisch","wendigo"},ang={["faction:Alliance"]="Die eisigen Pfade und Angelplätze nahe Brewnall und Kharanos vor aggressiven Raubtieren sicher zu halten, liegt ganz bei den lokalen Abenteurern der Allianz.",["race:Dwarf"]="Abgehärtete Zwergenfischer ertragen die bittere Kälte auf den zugefrorenen Seen von Dun Morogh, was Angriffe räuberischer Wendigos zu einer ständigen Gefahr für die einheimischen Siedler und ihre Lebensgrundlagen macht."},sec={{t="Ein gestohlener Fang",b="Eisfischen auf den gefrierenden Gewässern von Dun Morogh ist eine zermürbende, harte Arbeit. Eine Zwergenfischerin und ihr Ehemann Paxton verbrachten Tage auf dem zugefrorenen See und trotzen beißenden Winden, nur um einen einzigen Sack Fisch einzuholen. Ihre harte Arbeit wurde jäh zunichtegemacht, als Frosthowl, ein bedrohlicher und ohrenbetäubender Wendigo, das Lager überfiel und sich mit ihrem gesamten Fang in die verschneite Wildnis davonmachte."},{t="Das Großmaul des Graufelsbaus",b="Frosthowl ist nicht bloß ein gewöhnlicher Aasfresser; die Bestie ist berüchtigt für ihr dröhnendes Gebrüll, das das Eis erzittern lässt und die spärlichen Fische des Sees verscheucht. Nachdem die sabbernde Kreatur den Vorratssack der Fischerin an sich gerissen hatte, zog sie sich tief in die dunklen Tunnel des Graufelsbaus im Südosten zurück, sodass die gestrandeten Fischer verzweifelt nach jemandem suchen, der sich dem Ungeheuer stellt und ihre gestohlenen Waren wiederbeschafft."}},faq={{q="Wer ist Frosthowl?",a="Frosthowl ist ein lauter, aggressiver Wendigo, der in Dun Morogh lauert. Die Bestie, die dafür bekannt ist, zu brüllen und die zugefrorenen Wasserwege zu terrorisieren, griff kürzlich eine einheimische Zwergenfischerin an und machte sich mit dem mühsam erarbeiteten Fang ihres Mannes davon.",al={"wer ist frosthowl","was ist frosthowl","frosthowl wendigo"}},{q="Wo ist Frosthowl zu finden?",a="Frosthowl hat tief im Graufelsbau Zuflucht gesucht, einem Höhlensystem südöstlich des zugefrorenen Sees, an dem Paxton fischt.",al={"wo ist frosthowl","frosthowl standort","wo versteckt sich der wendigo"}},{q="Was hat Frosthowl gestohlen?",a="Frosthowl überfiel eine Zwergenfischerin und stahl einen vollen Sack Fisch, den ihr Ehemann Paxton tagelang auf dem zugefrorenen See gefangen hatte. Abenteurer werden gebeten, die Bestie zur Strecke zu bringen und den gestohlenen Fang wiederzubeschaffen.",al={"was hat frosthowl gestohlen","warum frosthowl töten","was hat der wendigo genommen"}},{q="Wer ist Paxton?",a="Paxton ist ein Zwergenfischer, der Tage auf dem zugefrorenen See verbrachte, um einen bescheidenen Fang einzuholen. Seine Frau beauftragt vorbeikommende Reisende damit, Frosthowl aufzuspüren, nachdem die Bestie ihren einzigen Sack Fisch gestohlen hat.",al={"wer ist paxton","paxton dun morogh","paxton fischer"}},{q="Was ist der Graufelsbau?",a="Der Graufelsbau ist ein bekannter Wendigobau südöstlich des zugefrorenen Sees in Dun Morogh, der Bestien wie Frosthowl als dunkler Rückzugsort dient, um erbeutetes Fleisch und Stolen Supplies zu horten.",al={"was ist der graufelsbau","graufelsbau wendigohöhle","wo leben wendigos in dun morogh"}},{q="Warum heißt die Bestie Frosthowl?",a="Der Wendigo wird als Großmaul bezeichnet, dessen ohrenbetäubendes Gebrüll und Heulen über die schneebedeckten Ebenen hallen, was die Fische zu verscheuchen droht und jeden in Schrecken versetzt, der auf den zugefrorenen Seen arbeitet.",al={"wie kam frosthowl zu seinem namen","warum frosthowl genannt","großmaul wendigo"}}},fp="9,205,13.383.0,33.394.0,17.220.0,29.135.0,25.209.0,14.211.0,25.197.0,33.187.0"}
P.entries["quest:98341"] = {n="The Great Windborne Cat Spirit",s="The Great Windborne Cat Spirit ist ein heiliger Mentor aus dem Reich Zephras, der als Avatar of Saeyleenan in der Mondlichtung erscheint. Er leitet junge Druiden der Shen'dorei durch ihre spirituelle Prüfung, damit sie die windgeborene Katzengestalt ihrer fernen Heimat verkörpern können.",h="The Great Windborne Cat Spirit ist ein heiliger Mentor aus dem Reich Zephras, der als Avatar of Saeyleenan in...",kw={"katzengestalt","katzengeist","druidenprüfung","mondlichtung","saeyleenan","shen'dorei","windgeborene katze","zephras"},ang={["class:Druid"]="Druiden aus Zephras treten mit dem windgeborenen Katzengeist in Verbindung, um ihre Katzengestalt zu meistern, und vollenden einen Ritus, der auf ihr einzigartiges Erbe zugeschnitten ist, anstatt den traditionellen azerothischen Pfad zu beschreiten.",["race:Skyborne"]="Als Shen'dorei angesprochen, werden Skyborne-Druiden von den Geistern ihrer Heimat Zephras geleitet, anstatt die einheimischen Formen Azeroths anzunehmen."},sec={{t="Ein Besucher aus Zephras",b="Im heiligen Refugium der Mondlichtung hat sich südlich der Zwillingsbrücken ein Geist aus dem fernen Reich Zephras manifestiert. Dieser windgeborene Katzengeist, der sich Avatar of Saeyleenan nennt, ist nach Azeroth übergesiedelt, um junge Druiden der Shen'dorei anzuleiten und zu unterweisen, die bereit sind, ihre feline Gestaltwandelform freizuschalten."},{t="Das Wesen der windgeborenen Gestalt",b="Während alle Druiden letztlich nach der Weisheit der Katzengestalt streben, pflegen jene aus Zephras eine Tradition, die sich von den einheimischen Bewohnern Azeroths unterscheidet. Anstatt die Gestalt einer azerothischen Wildkatze anzunehmen, verkörpern die Shen'dorei das windgeborene Raubtier ihrer Heimat. Um sicherzustellen, dass sie dessen spirituelle Natur begreifen, überwacht Saeyleenan ihre Prüfung in der Mondlichtung persönlich."}},faq={{q="Wer ist The Great Windborne Cat Spirit?",a="Der windgeborene Katzengeist manifestiert sich als Avatar of Saeyleenan, ein Geist aus der fernen Heimat Zephras. Er ist in die Mondlichtung gereist, um junge Druiden der Shen'dorei zu unterweisen und zu prüfen, die seine felide Gestalt annehmen wollen.",al={"wer ist der windgeborene katzengeist","was ist avatar von saeyleenan","saeyleenan lore"}},{q="Wo ist der Avatar of Saeyleenan zu finden?",a="Der Avatar des Geistes erscheint in den südlichen Gefilden der Mondlichtung, direkt südlich der Zwillingsbrücken gelegen.",al={"wo findet man katzengeist mondlichtung","avatar von saeyleenan aufenthaltsort","aufenthaltsort der windgeborenen katze"}},{q="Warum treten Druiden aus Zephras mit einem anderen Katzengeist in Verbindung?",a="Da die Druiden der Shen'dorei aus Zephras stammen, spiegelt ihre Katzengestalt die windgeborenen Geister ihrer Heimat wider und nicht die einheimischen Großkatzen Azeroths. Der Geist überwacht ihre Prüfung persönlich, um sicherzustellen, dass sie seine Essenz gebührend verkörpern.",al={"warum sieht katzengestalt anders aus","zephras katzengestalt unterschied","warum nicht katzengeist von azeroth"}},{q="Was beinhaltet die Prüfung der windgeborenen Katze?",a="Der Avatar of Saeyleenan lässt den Initianten die Prüfung des Großen Katzengeistes von Azeroth ablegen, während er selbst persönlich eingreift, um zu überwachen und zu bestätigen, dass der Druide die einzigartige Natur des windgeborenen Geistes begreift.",al={"welche prüfung stellt der katzengeist","katzengeist prüfung zephras","wie man die windgeborene katzengestalt erhält"}},{q="Worauf bezieht sich Shen'dorei?",a="Der Avatar of Saeyleenan spricht den Initianten als Shen'dorei an, was deren Herkunft aus Zephras bezeichnet und ihr Erbe sowie ihre spirituellen Praktiken von den einheimischen Völkern Azeroths unterscheidet.",al={"wer sind shendorei","shen dorei druiden","was bedeutet shendorei"}},{q="Was ist Zephras?",a="Zephras ist die ferne Heimat der Shen'dorei. Seine einheimische Flora, Fauna und Geister unterscheiden sich spürbar von denen Azeroths, was unter seinen Druiden einzigartige Gestaltwandelformen hervorbringt.",al={"was ist zephras","wo liegt zephras","heimat zephras"}}},fp="30,266,22.312.0,32.368.0,38.227.0,44.106.0,58.248.0,48.211.0,30.191.0,16.188.0"}
P.entries["quest:98362"] = {n="Nach Donnerfels",s="„Nach Donnerfels“ markiert die triumphale Rückkehr eines jungen Tauren-Druiden von seiner Zwiesprache mit dem Zirkel des Cenarius in Mondlichtung. Nachdem er die Gunst des Großen Katziergeistes erlangt hat, kehrt der Initiand zu Turak Runentotem auf der Anhöhe der Ältesten zurück, um die Kunst des katzengestaltigen Gestaltwandelns zu meistern.",h="„Nach Donnerfels“ markiert die triumphale Rückkehr eines jungen Tauren-Druiden von seiner Zwiesprache mit dem...",kw={"katzengestalt","dendrite sternenschauer","druide","die anhöhe der ältesten","großer katziergeist","mondlichtung","donnerfels","turak runentotem"},ang={["class:Druid"]="Dieser Ritus steht für das Erwecken Eurer Raubtierinstinkte und gewährt Euch die Beherrschung von Heimlichkeit und Klauen, wie von Turak Runentotem gelehrt.",["faction:Horde"]="Obwohl der Zirkel des Cenarius neutral bleibt, müssen Horde-Druiden in ihre Hauptstadt zurückkehren, um sicherzustellen, dass ihre wachsende Macht der Verteidigung ihres Volkes dient.",["race:Tauren"]="Die Reise unterstreicht die Wiederanknüpfung der Tauren an die Traditionen des Cenarius und trägt die Lehren aus der heiligen Mondlichtung zurück auf die Anhöhe der Ältesten von Donnerfels."},sec={{t="Rückkehr aus Mondlichtung",b="Nachdem sie ihre Einsicht und ihren Wert vor Dendrite Sternenschauer und dem Großen Katziergeist in den heiligen Hainen von Mondlichtung bewiesen haben, muss ein junger Druide den Segen des Geistes nach Mulgore zurückbringen. Die Zwiesprache mit solch urtümlichen Mächten stellt einen entscheidenden Meilenstein in der Ausbildung eines Druiden dar und schlägt eine Brücke zwischen den uralten Lehren der Nachtelfen und dem irdischen Erbe der Tauren."},{t="Die Katzengestalt meistern",b="Hoch oben auf der Anhöhe der Ältesten in Donnerfels erwartet Turak Runentotem Eure Rückkehr. Während Dendrite die Zwiesprache mit dem Geist selbst ermöglicht hat, obliegt es Turak, die körperliche Verwandlung anzuleiten. Da der Segen des Großen Katziergeistes anerkannt ist, vermittelt der ältere Ausbilder das heilige Wissen, das erforderlich ist, um die flinke, raubtierhafte Gestalt der Katze anzunehmen."}},faq={{q="Wo beginnt und endet diese Quest?",a="Die Quest wird von Dendrite Sternenschauer in der heiligen Zuflucht von Mondlichtung vergeben. Sie schickt den Reisenden zurück zur Anhöhe der Ältesten in Donnerfels, um mit Turak Runentotem zu sprechen.",al={"wo gebe ich das ab","wer startet nach donnerfels","nach donnerfels quest abgabe"}},{q="Was ist der Zweck dieser Quest?",a="Sie dient als abschließender Übergang in der Druidenprüfung der Katze. Nach Erhalt des Segens des Großen Katziergeistes in Mondlichtung muss der Initiand zu seinem Mentor in Donnerfels zurückkehren, um schließlich zu lernen, wie man die Katzengestalt annimmt.",al={"warum nach donnerfels","was erhalte ich von nach donnerfels","katzengestalt quest"}},{q="Wer ist Turak Runentotem?",a="Turak Runentotem ist ein angesehener Ältester der Tauren-Druiden, der auf der Anhöhe der Ältesten von Donnerfels weilt. Er überwacht die Ausbildung und Einweihung junger Horde-Druiden, die danach streben, mit der Natur in Einklang zu kommen und ihre Gestaltwandlungsformen zu meistern.",al={"turak runentotem lore","wer ist turak"}},{q="Wer ist Dendrite Sternenschauer?",a="Dendrite Sternenschauer ist ein Nachtelfen-Hüter des Zirkels des Cenarius, der reisende Druiden in Nachthafen in Mondlichtung anleitet. Er schlägt die Brücke zwischen den alten Lehren der Kaldorei und den taurischen Anwendern, ungeachtet politischer Spannungen.",al={"dendrite sternenschauer rolle","nachtelf in mondlichtung"}},{q="Was ist der Große Katziergeist?",a="Der Große Katziergeist ist ein uraltes, urtümliches Wesen, das von Druiden verehrt wird und Raubtierinstinkt, Heimlichkeit und Wendigkeit verkörpert. Jeder Druide, der die feline Gestalt annehmen möchte, muss eine Prüfung bestehen, um seinen Segen zu erhalten und sein zweifaches Wesen – sowohl verspielt als auch tödlich – zu verstehen.",al={"katzengeist lore","geist der katze"}},{q="Haben Allianz-Druiden eine gleichwertige Aufgabe?",a="Ja. Druiden der Nachtelfen durchlaufen einen parallelen Ritus in Mondlichtung und kehren nach Darnassus zurück, um ihrem eigenen Mentor Bericht zu erstatten, anstatt zu den windgepeitschten Hochebenen von Mulgore aufzubrechen.",al={"allianz version von nach donnerfels","nachtelf katzengestalt rückkehr"}}},fx={cdfa9758={q="Warum schickt Euch Dendrite Sternenschauer zurück nach Thunder Bluff?",a="Dendrite Sternenschauer dient als Mentor und Proktor in der Mondlichtung und führt Euch durch die Gemeinschaft mit dem Geist der Großen Katze. Da diese Prüfung abgeschlossen ist und die Gunst des Geistes verdient wurde, ist seine Rolle in dieser Phase Eurer Ausbildung beendet. Er schickt Euch zurück zu Turak Runentotem, damit Euer primärer Ausbilder die letzten Lehren vermitteln und Euch bei der tatsächlichen Annahme der Katzenform anleiten kann.",al={"warum nach thunder bluff schicken","dendrite sternenschauers beweggrund","warum zu turak runetotem zurückkehren"}}},fp="16,278,21.359.0,22.359.0,36.169.0,34.235.0,23.236.0,26.240.0,29.262.0,43.168.0"}
P.entries["quest:98386"] = {n="Althers Mühle",s="Althers Mühle ist eine Quest im Rotkammgebirge, die von Großknecht Oslow in Seenhain vergeben wird. Der Großknecht benötigt Abenteurer, um einen gefährlichen Tarantelbefall im nahegelegenen Sägewerk zu beseitigen, damit die Arbeiter das für die Fertigstellung der Brücke von Seenhain benötigte Bauholz sicher heranschaffen können.",h="Althers Mühle ist eine Quest im Rotkammgebirge, die von Großknecht Oslow in Seenhain vergeben wird.",kw={"althers mühle","brücke","großknecht oslow","seenhain","sägewerk","rotkammgebirge","tarantel"},ang={["faction:Alliance"]="Der Wiederaufbau der Infrastruktur von Seenhain ist für das Königreich Sturmwind von entscheidender Bedeutung, doch ständige Bedrohungen ziehen immer wieder Ressourcen von der Brücke ab."},sec={{t="Ein Engpass beim Bauholz",b="Großknecht Oslow hat alle Hände voll zu tun, um die Reparaturen an der Brücke in Seenhain im Zeitplan zu halten. Zwischen feindseligen Schwarzfelsorcs, vordringenden Gnollrudeln und aggressiven Murlocs entlang des Immerruhsees ist seine Arbeiterschaft an ihren Grenzen angelangt. Die jüngste Störung trifft seine Lieferkette direkt: Althers Mühle, der Holzbetrieb im Osten, wurde von riesigen Taranteln überrannt, was die für die Brücke der Stadt benötigten Bauholzlieferungen zum Erliegen brachte."},{t="Beseitigung des Befalls",b="Das Sägewerk ist so gut wie unbrauchbar, während Spinnen zwischen den Holzstapeln lauern. Großknecht Oslow kann es nicht riskieren, seine Arbeiter in ein Nest von Riesentaranteln zu schicken, weshalb er fähige Abenteurer anheuert, um die Spinnentiere zu beseitigen und ihre Eiergelege zu zerstören. Obwohl Oslow verärgert darüber ist, dass Alther die Mühle in eine solche Unordnung geraten ließ, hat die Wiederherstellung der Holzlieferungen Vorrang vor jeglichem Groll."}},faq={{q="Wer ist Großknecht Oslow?",a="Großknecht Oslow ist der Steinmetz und Vorarbeiter, der für die Reparatur und den Wiederaufbau der Brücke in Seenhain zuständig ist. Er wird ständig von lokalen Bedrohungen geplagt, die seine Bauarbeiten verzögern.",al={"wer ist großknecht oslow","großknecht oslow rotkammgebirge"}},{q="Was ist Althers Mühle?",a="Althers Mühle ist ein Sägewerk östlich von Seenhain im Rotkammgebirge. Es liefert wichtige Bauholzlieferungen, die für Bauprojekte rund um Seenhain, einschließlich der Brücke, benötigt werden.",al={"was ist althers mühle","wo ist althers mühle"}},{q="Wer ist Alther?",a="Alther ist der Eigentümer oder Betreiber des Sägewerks östlich von Seenhain. Laut Großknecht Oslow ist Alther für die Leitung des Geländes verantwortlich, obwohl derzeit ein Spinnenbefall seine Mühle heimgesucht hat.",al={"wer ist alther","wo ist ol alther"}},{q="Warum muss Althers Mühle befreit werden?",a="Großknecht Oslow kann Arbeiter nicht gefahrlos entsenden, um lebenswichtige Bauholzlieferungen abzuholen, solange Taranteln die Mühle befallen. Die Beseitigung der Spinnen und die Zerstörung ihrer Eier stellt sicher, dass die Mühle die Materiallieferungen für den Brückenbau sicher wieder aufnehmen kann.",al={"warum althers mühle befreien","warum spinnen töten rotkammgebirge"}},{q="Wovon wird Althers Mühle heimgesucht?",a="Riesentaranteln haben zusammen mit Gelegen von Spinneneiern das Mühlengelände befallen und stellen eine ernsthafte Bedrohung für jeden Arbeiter dar, der zum Holen von Bauholz ausgesandt wird.",al={"welche spinnen bei althers mühle","rotkammgebirge spinnen"}},{q="Welche Brücke versucht Großknecht Oslow zu bauen?",a="Großknecht Oslow arbeitet am Wiederaufbau der Brücke in Seenhain, doch sein Zeitplan wird immer wieder durch feindselige Orcs, Gnolls, Murlocs und durch lokale Schädlinge verursachte Ressourcenknappheit aufgehalten.",al={"welche brücke im rotkammgebirge","seenhain brücke"}}},fp="13,266,22.434.0,24.416.0,21.184.0,22.193.0,14.214.0,50.241.0,32.148.0,45.179.0"}
P.entries["quest:98387"] = {n="Blackrock Blockade",s="Blackrock Blockade ist eine militärische Aufgabe der Allianz, die von Marschall Marris in Seenhain erteilt wird. Im Kampf gegen die vordringenden Schwarzfelsorcs östlich des Immerruhsees zielt die Stadtwache darauf ab, die Eindringlinge auszuhungern und ihre Waffen zu beschlagnahmen.",h="Blackrock Blockade ist eine militärische Aufgabe der Allianz, die von Marschall Marris in Seenhain erteilt...",kw={"kampferprobte axt","blackrock blockade","schwarzfelsklan","seenhain","marschall marris","rotkammgebirge","burg steinwacht"},ang={["class:Warrior"]="In Nahkampfgefechten gegen die abgehärteten Schwarzfelsorcs ist es grundlegende Grenzkriegsführung, dem Feind schwere Spalter und Vorräte zu entziehen.",["faction:Alliance"]="Jede Waffe, die der Vorhut des Schwarzfelsklans abgenommen wird, verschafft Seenhain wertvolle Zeit, da es sich ohne nennenswerte Hilfe aus Sturmwind gegen feindliche Armeen wehren muss."},sec={{t="Ein Zermürbungskrieg",b="Während der Schwarzfelsklan kühne Vorstöße in das Rotkammgebirge unternommen hat, hat sein dreister Vorstoß in das Gebiet der Allianz seine Logistik an ihre Grenzen gebracht. Abgeschnitten von regelmäßigen Nachschubtransporten sind ihre vorderen Kriegstrupps gezwungen, von den kargen Hügeln des Rotkammgebirges zu leben. Marschall Marris erkennt, dass selbst wilde Orcs einen Feldzug nicht ohne stetigen Nachschub und Stahl aufrechterhalten können."},{t="Abschneiden der vorderen Lager",b="Die südlich von Burg Steinwacht gelegenen Orc-Lager stellen die Speerspitze der Offensive des Schwarzfelsklans dar. Durch Überfälle auf diese Lager, das Plündern ihrer Vorräte und die Beschlagnahmung ihrer gestohlenen Waffen hoffen die Verteidiger der Allianz, die Kampfkraft der Vorhut zu schwächen und ihre Moral zu brechen."}},faq={{q="Was ist das Ziel der Blackrock Blockade?",a="Die Mission zielt darauf ab, die vorderen Lager des Schwarzfelsklans südlich von Burg Steinwacht zu schwächen. Indem ihre Nachschublinien überfallen, ihre Nahrung erbeutet und ihre Waffen sichergestellt werden, hofft die Wache von Seenhain, die Orcs auszuhungern und ihren Vorstoß in das Rotkammgebirge abzuwehren.",al={"was ist blackrock blockade","ziel der blackrock blockade","zweck der blockade"}},{q="Wer erteilt diesen Auftrag?",a="Marschall Marris, der kommandierende Offizier der in Seenhain stationierten Stadtwache, beaufsichtigt die Verteidigung des Rotkammgebirges und leitet die Bemühungen, den Nachschub des Schwarzfelsklans zu unterbrechen.",al={"wer vergibt blackrock blockade","questgeber","marschall marris quest"}},{q="Wo befinden sich diese Lager des Schwarzfelsklans?",a="Die anvisierten Kriegslager liegen in den östlichen Hügeln des Rotkammgebirges, direkt südlich von Burg Steinwacht, auf der anderen Seite des Flusses von Seenhain.",al={"wo sind die orcs","position des lagers der schwarzfelsorcs","wo ist das steinwacht-lager"}},{q="Warum verlässt sich Seenhain eher auf Zermürbung als auf einen direkten Angriff?",a="Die Wache von Seenhain ist unterbesetzt und erhält kaum Verstärkung aus Sturmwind. Dies ist ein Zermürbungskrieg: Der dreiste Vorstoß der Schwarzfelsorcs in das Gebiet der Allianz hat sie verwundbar und ohne Nachschub zurückgelassen, sodass sie auf die Ressourcen der umliegenden Berge angewiesen sind – und eine Armee kann nicht mit leerem Magen kämpfen.",al={"warum die orcs aushungern","warum burg steinwacht nicht direkt angreifen","strategie von seenhain"}},{q="Welche Waffen werden von den Orcs konfisziert?",a="Marschall Marris möchte, dass die in den Lagern des Schwarzfelsklans gehorteten Waffen und Vorräte beschlagnahmt werden, damit den Orcs ihre Kriegswerkzeuge genommen werden.",al={"welche gegenstände werden benötigt","welche äxte","lore zu abgenutzten äxten"}},{q="Gehören diese Orcs zu Thralls Horde?",a="Nein. Die Schwarzfelsorcs im Rotkammgebirge gehören zur abtrünnigen Dunklen Horde mit Sitz im Schwarzfels. Sie lehnen Thralls Führung ab und stehen sowohl der Allianz als auch The New Horde erbittert feindselig gegenüber.",al={"sind das horde-orcs","gehört der schwarzfelsklan zur horde","thrall schwarzfelsklan"}}},fp="18,226,18.396.0,26.282.0,43.267.0,27.167.0,46.134.0,67.307.0,49.139.0,46.205.0"}
P.entries["quest:98389"] = {n="Ein Licht in der Dunkelheit",s="Diese von Aramis Hammerhand in Todesend angebotene Quest beauftragt Abenteurer der Verlassenen damit, neu erweckte Untote zu retten, die in Night's Web Hollow gefangen sind. Sie verdeutlicht die heikle Beziehung zwischen untoten Wirken des Heiligen Lichts und einer Bevölkerung, die ihnen zutiefst misstraut. Indem sie ihren gefallenen Artgenossen helfen, hoffen diese heiligen Praktizierenden, ihre Loyalität gegenüber Sylvanas und der Sache der Verlassenen zu beweisen.",h="Diese von Aramis Hammerhand in Todesend angebotene Quest beauftragt Abenteurer der Verlassenen damit, neu...",kw={"aramis hammerhand","todesend","exekutor arren","verlassene","das heilige licht","night's web hollow","tirisfal","eingesponnene opfer"},ang={["class:Priest"]="Für Verlassene, die heilige Energie kanalisieren, verdeutlicht diese Mission die heikle Gratwanderung zwischen verbliebenem sterblichem Glauben und der harten Realität des Untodes.",["race:Undead"]="Diese Aufgabe zeigt die komplexen inneren Kämpfe der Verlassenen und demonstriert, wie Einzelne Vorurteile innerhalb ihres eigenen, frisch auferstandenen Volkes überwinden können."},sec={{t="Ein prekärer Glaube",b="Das Heilige Licht ist für Untote notorisch quälend und gefährlich, doch einige Verlassene bewahren ihre Verbindung zu der heiligen Magie, die sie im Leben gewirkt haben. In Todesend bemühen sich Persönlichkeiten wie Aramis Hammerhand zu beweisen, dass ihr Glaube sie nicht gegen ihr eigenes Volk aufgebracht hat. Um dem Verdacht entgegenzuwirken, dass heilige Praktizierende sich als Monstrositäten gegen andere Untote wenden könnten, nutzen sie ihre Fähigkeiten und ihr Mitgefühl aktiv, um ihre Artgenossen zu beschützen."},{t="Night's Web Hollow",b="Nordwestlich von Todesend liegt Night's Web Hollow, eine feuchte Höhle voller bösartiger Spinnen. Frisch erweckte Untote, die von ihrem Erwachen noch desorientiert sind und nicht über den Verstand verfügen, sich zu verteidigen, stolpern häufig in die Höhle und enden in klebrigen Netzen eingesponnen. Die Rettung dieser unglückseligen Verlassenen erfüllt einen doppelten Zweck: Sie rettet neue Rekruten für die Dunkle Fürstin und beweist Anführern wie Exekutor Arren, dass Praktizierende des Lichts ergebene Diener der Verlassenen sind."}},faq={{q="Wer vergibt die Quest Ein Licht in der Dunkelheit?",a="Die Quest wird von Aramis Hammerhand vergeben, einem heiligen Praktizierenden, der in Todesend in Tirisfal stationiert ist.",al={"questgeber","wer startet ein licht in der dunkelheit","aramis hammerhand quest"}},{q="Wo befindet sich Night's Web Hollow?",a="Night's Web Hollow befindet sich nordwestlich von Todesend in den Hügeln von Tirisfal.",al={"night's web hollow ort","wo sind die eingesponnenen opfer","wo ist die höhle"}},{q="Warum misstrauen die Verlassenen den Wirken des Lichts?",a="Das Heilige Licht ist für untotes Fleisch zutiefst versengend und gefährlich. Viele Verlassene fürchten, dass jeder, der heilige Mächte führt, sie als Monstrositäten betrachten könnte, die vernichtet werden müssen, statt als Brüder, die es aufzunehmen gilt.",al={"warum das licht fürchten","warum verlassene paladine hassen","verlassene heilige furcht"}},{q="Wer sind die in den Netzen gefangenen Opfer?",a="Die Opfer in den Kokons sind frisch erwachte Abenteurer der Verlassenen, die in die Spinnenhöhlen hineingestolpert sind, bevor sie sich orientieren konnten.",al={"wer ist eingesponnen","was ist in den netzen","gefangene opfer"}},{q="Wer ist Exekutor Arren und warum möchte Aramis ihn beeindrucken?",a="Exekutor Arren überwacht die militärische und zivile Ordnung in Todesend. Sein Vertrauen zu gewinnen, ist unerlässlich für heilige Wirker, die sich reibungslos in die Streitkräfte der Verlassenen integrieren wollen.",al={"wer ist exekutor arren","warum arren wichtig ist"}},{q="Können Untote wirklich das Heilige Licht wirken?",a="Ja, durch unglaubliche Willenskraft und Hingabe behalten manche Untote ihr Band zum Licht, obwohl das Kanalisieren immense Qualen verursacht und ihre eigene Gesellschaft sie mit Misstrauen betrachtet.",al={"können verlassene licht nutzen","untote licht lore"}}},fx={f946e0be={q="Warum möchte Aramis Hammerhand, dass die versponnenen Opfer befreit werden?",a="Aramis möchte seinen Mitstreitern, den Verlassenen, beweisen, dass Untote, die das Heilige Licht führen, keine Bedrohung für ihresgleichen darstellen. Viele in Todesend, einschließlich Exekutor Arren, fürchten oder vermuten, dass Lichtnutzer ihre Kräfte als Monstrositäten gegen andere Untote richten werden. Indem Aramis frisch erhobene Verlassene aus den Spinnen von Night's Web Hollow rettet, hofft er zu demonstrieren, dass ihre Macht existiert, um die Verlassenen zu schützen und der Vision der Dunklen Fürstin zu dienen.",al={"aramis hammerhand motiv","warum die versponnenen opfer befreien","warum möchte aramis dies erledigt haben"}}},fp="23,388,18.444.0,18.480.0,44.104.0,36.90.0,51.201.0,40.137.0,63.169.0,43.194.0"}
P.entries["quest:98391"] = {n="The Sisterhood of Elune",s="The Sisterhood of Elune ist eine einführende Quest, die Abenteurer nach Darnassus führt, um Schwester Aquinne zu treffen. Als oberste spirituelle Autorität unter den Nachtelfen benötigt die Schwesterschaft rasche Hilfe von außen, um sich anbahnenden Herausforderungen in ihren Ländern zu stellen.",h="The Sisterhood of Elune ist eine einführende Quest, die Abenteurer nach Darnassus führt, um Schwester Aquinne...",kw={"aquinne","darnassus","elune","priesterin","schwester aquinne","the sisterhood of elune","teldrassil"},ang={["class:Priest"]="Das Priestertum in der Kultur der Kaldorei ist gleichbedeutend mit der Hingabe an Elune, und Schwester Aquinne zu antworten, verbindet direkt mit den hohen Traditionen des Tempels.",["faction:Alliance"]="Da Darnassus eine lebenswichtige Hauptstadt der Allianz in Kalimdor ist, sichert die Unterstützung der Schwesterschaft die Stabilität der geistigen und bürgerlichen Führung der Nachtelfen.",["race:NightElf"]="The Sisterhood of Elune ist das spirituelle Herz der Gesellschaft und Führung der Nachtelfen, weshalb das Befolgen ihres Rufs eine heilige Pflicht für jedes Kind der Sterne darstellt."},sec={{t="Ein Ruf in die Hauptstadt",b="„The Sisterhood of Elune“ ist eine Aufforderung, die Abenteurer anweist, Schwester Aquinne in der Nachtelfenhauptstadt Darnassus aufzusuchen. Als Vertreterinnen der Gläubigen Elunes entsenden die Priesterinnen oft Rufe nach verlässlichen Champions, um bei dringenden Angelegenheiten zu helfen, die ihr Volk und ihre heiligen Länder betreffen."},{t="Meldung bei Schwester Aquinne",b="Nach Eurer Ankunft in Darnassus und dem Auffinden von Schwester Aquinne zeigt sie sich zutiefst erleichtert über Euer promptes Erscheinen. Ihre Begrüßung markiert den Beginn des direkten Dienstes für die Schwesterschaft und signalisiert, dass die Priesterinnen vor wachsenden Anforderungen stehen, die vertrauenswürdige Hände außerhalb ihrer klausurierten Reihen erfordern."}},faq={{q="Wer ist Schwester Aquinne?",a="Schwester Aquinne ist eine Gesandte und Priesterin, die der Sisterhood of Elune in der Hauptstadt Darnassus dient. Sie empfängt Reisende, die entsandt wurden, um der Priesterschaft bei dringenden Angelegenheiten beizustehen, vor denen die Nachtelfen stehen.",al={"wer ist schwester aquinne","aquinne darnassus","wo ist aquinne"}},{q="Was ist The Sisterhood of Elune?",a="The Sisterhood of Elune ist der uralte Orden von Nachtelfenpriesterinnen, die der Mondgöttin Elune geweiht sind. Verehrt als spirituelle Führerinnen, Heilerinnen und Anführerinnen der Kultur der Kaldorei wachen sie über das geistige Wohl und die Verteidigung ihres Volkes.",al={"was ist the sisterhood of elune","wer sind die schwestern von elune","nachtelfenpriesterinnen"}},{q="Wohin muss ich reisen, um diese Quest abzuschließen?",a="Ihr müsst nach Darnassus reisen, der großen Hauptstadt der Nachtelfen auf Teldrassil. Schwester Aquinne erwartet Eure Ankunft in der Stadt, um Euch im Namen der Schwesterschaft einzuweisen.",al={"wo the sisterhood of elune abgeben","ort der schwesterschaftsquest","wohin für the sisterhood of elune"}},{q="Warum benötigt die Schwesterschaft Hilfe?",a="Schwester Aquinne deutet an, dass die Schwesterschaft sofortige Hilfe von außen benötigt, um drängende Probleme zu bewältigen, mit denen Darnassus und die umliegenden Länder der Nachtelfen konfrontiert sind. Ein Gespräch mit ihr schaltet weitere Aufgaben in ihrem Namen frei.",al={"warum braucht die schwesterschaft hilfe","schwesterschaft probleme","welche hilfe braucht die schwesterschaft"}},{q="Können Charaktere der Horde diese Quest annehmen?",a="Nein. The Sisterhood of Elune ist von zentraler Bedeutung für die Führung der Nachtelfen und streng auf die Allianz ausgerichtet. Darnassus ist eine Hauptstadt der Allianz, weshalb diese Quest ausschließlich Abenteurern der Allianz vorbehalten ist.",al={"erhält die horde diese quest","kann die horde the sisterhood of elune annehmen"}},{q="Wer führt The Sisterhood of Elune an?",a="Hohepriesterin Tyrande Wisperwind steht als spirituelles Oberhaupt an der Spitze der Sisterhood of Elune und ist die oberste Anführerin des Volkes der Kaldorei, die ihre Schwestern aus dem Tempel des Mondes in Darnassus leitet.",al={"wer leitet the sisterhood of elune","anführerin der schwesterschaft","tyrande schwesterschaft"}}},fp="23,262,21.297.0,27.292.0,22.215.0,32.239.0,45.187.0,36.224.0,42.189.0,34.199.0"}
P.entries["quest:98392"] = {n="Darkness in the Glade",s="Darkness in the Glade ist eine Untersuchung unter der Leitung von Schildwache Arynia Wolkenbruch bezüglich verdorbener Ledergürtel, die von Harpyien in der Lichtung des Orakels gesammelt wurden. Die Bergung von Amuletten der Harpyienmatriarchinnen bestätigt, dass eine dämonische Verderbnis durch Teufelsmoos in den Ästen von Teldrassil Fuß gefasst hat.",h="Darkness in the Glade ist eine Untersuchung unter der Leitung von Schildwache Arynia Wolkenbruch bezüglich...",kw={"arynia wolkenbruch","arysa","darkness in the glade","teufelsmoos","gaedress","harpyien","hatescreech","die lichtung des orakels","teldrassil"},ang={["class:Druid"]="Das Vorhandensein von Teufelsmoos, welches die Tierwelt und Lederfasern verseucht, deutet auf eine unnatürliche Plage hin, die das natürliche Gleichgewicht des Weltenbaums heimsucht.",["faction:Alliance"]="Schildwache Wolkenbruch verkörpert die militärische Wachsamkeit von Darnassus und bemüht sich, dämonische Verseuchungen zu identifizieren, welche die Ländereien der Allianz bedrohen.",["race:NightElf"]="Die Ausbreitung dämonischer Verderbnis durch heilige Äste wie die Lichtung des Orakels trifft die Bestrebungen der Kaldorei, Teldrassil zu hegen und zu beschützen, unmittelbar."},sec={{t="Verdorbene Fasern",b="In den ruhigen Baumkronen der Lichtung des Orakels bemerkte Schildwache Arynia Wolkenbruch, dass bei den örtlichen Harpyienschwärmen etwas nicht stimmte. Ledergürtel, die den Kreaturen abgenommen wurden, wiesen eine unnatürliche Verderbnis auf, die direkt durch das Material gewoben war. Da Wolkenbruch eher ein dämonisches Eindringen als gewöhnliche tierische Aggression vermutete, benötigte sie eindeutige Beweise, bevor sie in Darnassus Alarm schlug."},{t="Eine Verderbnis bestätigt",b="Wolkenbruch wies Streiter an, in die westlichen Nester vorzudringen, um die Matriarchinnen des Schwarms niederzustrecken: Hatescreech, Windmistress Gaedress und Witchmother Arysa. Jede Anführerin trug ein Amulett mit sichtbaren Spuren ihrer Macht bei sich. Bei der Untersuchung der Steine entdeckte die Schildwache üble grüne Wirbel im Inneren der Edelsteine, was bestätigte, dass Teufelsmoos die Harpyien aktiv entstellte und in die heiligen Äste sickerte."}},faq={{q="Was ist Darkness in the Glade?",a="Darkness in the Glade ist ein Auftrag unter der Leitung von Schildwache Arynia Wolkenbruch in der Lichtung des Orakels. Nachdem sie eine unnatürliche Verderbnis an ledernen Harpyiengürteln bemerkt hat, schickt sie Abenteurer los, um Amulette von Harpyienanführerinnen zu beschaffen und so die Quelle der Heimsuchung zu überprüfen.",al={"was ist darkness in the glade","darkness in the glade quest"}},{q="Wer vergibt diese Quest?",a="Schildwache Arynia Wolkenbruch bietet diese Aufgabe an. Sie ist in der Lichtung des Orakels stationiert, wacht über die Äste von Teldrassil und untersucht merkwürdige Unruhen unter den dort ansässigen Harpyien.",al={"wer vergibt darkness in the glade","questgeber die lichtung des orakels"}},{q="Warum möchte Arynia Amulette von den Harpyienanführerinnen?",a="Schildwache Wolkenbruch fand verdorbene Fasern in Ledergürteln gewöhnlicher Harpyien und benötigte weitere Beweise. Sie vermutete, dass die Führung der Harpyien Schmuckstücke trug, welche das wahre Wesen und den Ursprung der sich ausbreitenden Verderbnis offenbaren würden.",al={"warum harpyienanführerinnen töten","warum amulette beschaffen","grund für harpyienamulette"}},{q="Welche Harpyienanführerinnen besitzen die Amulette?",a="Die Amulette gehören drei bedeutenden Anführerinnen, die im Westen nisten: Hatescreech, Windmistress Gaedress und Witchmother Arysa.",al={"welche harpyien haben amulette","harpyienanführerinnen die lichtung des orakels"}},{q="Was verursacht die Verderbnis in der Lichtung?",a="Die Verderbnis geht von Teufelsmoos aus. Als Arynia die wiederbeschafften Amulette untersucht, erkennt sie üble grüne Wirbel in deren Edelsteinen, was bestätigt, dass Teufelsmoos die Region verseucht.",al={"was verdirbt die harpyien","was ist der grüne wirbel","ursprung der dunkelheit in der lichtung"}},{q="Ist diese Verderbnis noch anderswo aufgetreten?",a="Ja, Schildwache Wolkenbruch merkt an, dass Berichte über Teufelsmoos, welches die Umwelt gegen die Nachtelfen aufbringt, auch aus dem Laubschattental und von anderen Ästen des Weltenbaums aufgetaucht sind.",al={"teufelsmoos andernorts","ist das laubschattental verdorben"}}},fp="21,273,14.379.0,18.410.1,30.255.0,21.184.0,52.224.0,37.125.0,44.185.0,43.179.0"}
P.entries["quest:98393"] = {n="The Great Cat Spirit",s="The Great Cat Spirit ist eine heilige Druidenquest, die Praktizierende nach Nachthafen in der Mondlichtung ruft, um Dendrite Sternenschauer zu treffen. Nachdem sie den Aspekt des Bären bereits gemeistert haben, sind Druiden dazu aufgerufen, unter dem Segen von Vater Cenarius ihre Reise in die Katzenperspektive der Wildnis zu beginnen.",h="The Great Cat Spirit ist eine heilige Druidenquest, die Praktizierende nach Nachthafen in der Mondlichtung...",kw={"katzenaspekt","cenarius","dendrite sternenschauer","druidenausbildung","mondlichtung","nachthafen","the great cat spirit"},ang={["class:Druid"]="Dieser Ruf markiert einen wesentlichen Übergangsritus für Druiden, die ihre Meisterschaft über die Aspekte der Wildnis über den Bären hinaus erweitern.",["race:NightElf"]="Die Mondlichtung dient den Druiden der Kaldorei als uralter Boden, um den alten Lehren zu folgen, die von Cenarius weitergegeben wurden.",["race:Tauren"]="Tauren-Druiden reisen an der Seite ihrer Nachtelfenbrüder unter der gemeinsamen Führung des Zirkels des Cenarius frei nach Nachthafen."},sec={{t="Der Ruf nach Mondlichtung",b="Nachdem sie bereits ihre Meisterschaft über den ausdauernden Aspekt des Bären bewiesen haben, finden sich angehende Druiden erneut in den heiligen Wald der Mondlichtung gerufen. Ältester Dendrite Sternenschauer streckt seine Hand über das Land aus und ruft Jünger in die friedvolle Zuflucht von Nachthafen, um die nächste Stufe ihrer natürlichen Verbundenheit zu beschreiten. Druiden wirken ihre einzigartige spirituelle Magie, um weite Entfernungen zu überwinden und sich im ruhigen Herzen cenarischer Weisheit zu versammeln."},{t="Die Perspektive der Katze",b="Bei Eurer Ankunft in Nachthafen ruft Dendrite Sternenschauer Vater Cenarius an und beschwört eine schwache Aura der Macht herab, während er den heranwachsenden Jünger willkommen heißt. Er offenbart, dass die Zeit gekommen ist, die Perspektive der Katze anzunehmen, einen raubtierhaften und gewandten Aspekt der Wildnis. Wie bei früheren Übergangsriten wird Dendrite den Pfad des Verständnisses eröffnen, doch die Reise, diesen Katzengeist zu verkörpern und zu verbreiten, liegt ganz beim Praktizierenden."}},faq={{q="Wer lässt in The Great Cat Spirit nach Euch rufen?",a="Eure Druidenlehrer rufen Euch im Namen von Dendrite Sternenschauer herbei, einem älteren Mentor, der in Nachthafen innerhalb der abgeschiedenen Zuflucht der Mondlichtung stationiert ist.",al={"wer gibt die quest the great cat spirit","dendrite sternenschauers ruf"}},{q="Wo ist Dendrite Sternenschauer zu finden?",a="Dendrite Sternenschauer hält sich im Dorf Nachthafen auf, der zentralen Siedlung der Mondlichtung, die über druidische Teleportationsmagie erreichbar ist.",al={"wo ist dendrite sternenschauer","aufenthaltsort von dendrite sternenschauer"}},{q="Was ist der Zweck des Treffens mit Dendrite Sternenschauer?",a="Dendrite bereitet Euch darauf vor, mit dem Katzenaspekt der Natur Zwiesprache zu halten und ihn zu verstehen, wodurch Euer spiritueller Fortschritt nach dem Erlernen der Pfade des Bären fortgesetzt wird.",al={"was lehrt dendrite","quest zur katzengestalt-ausbildung"}},{q="Warum ruft Dendrite Vater Cenarius an?",a="Dendrite ruft Vater Cenarius bei Eurer Begrüßung an und ehrt damit den Halbgott und Schutzpatron des Druidentums, der die Sterblichen ursprünglich die Geheimnisse der Natur und des Gestaltwandelns lehrte.",al={"warum vater cenarius","cenarius erwähnung dendrite"}},{q="Wie reisen Druiden für diesen Ruf in die Mondlichtung?",a="Druiden nutzen ihre angeborene spirituelle Fähigkeit, um mit der Natur Zwiesprache zu halten und sich direkt in die Mondlichtung zu teleportieren, wann immer ihre Mentoren rufen.",al={"wie man nach mondlichtung gelangt","teleportieren zur mondlichtung druide"}},{q="Wie verhält sich dieser Aspekt zum Bärenaspekt?",a="Die druidische Doktrin nähert sich der Natur aus verschiedenen Blickwinkeln. Neulinge beginnen damit, die ausdauernde Stärke des Bären zu meistern, bevor sie zur schnellen Raubtiermentalität der Katze übergehen.",al={"katzengestalt vs bärengestalt lore","zuerst bärengestalt"}}},fp="20,299,24.440.0,26.441.0,42.143.0,38.137.0,50.156.0,41.166.0,51.134.0,47.184.0"}
P.entries["quest:98397"] = {n="Auf nach Darnassus",s="Auf nach Darnassus ist der Höhepunkt der Reise eines Nachtelfendruiden, um mit dem Großen Katzengeist Zwiesprache zu halten. Nachdem Ihr Euch vor Dendrite Sternenschauer in Mondlichtung bewiesen habt, werdet Ihr zurück in die Enklave des Cenarius geschickt, um die Kunst des Gestaltwandels in die Katzengestalt zu meistern.",h="Auf nach Darnassus ist der Höhepunkt der Reise eines Nachtelfendruiden, um mit dem Großen Katzengeist...",kw={"katzengestalt","die enklave des cenarius","dendrite sternenschauer","großer katzengeist","mathrengyl bärenfährte","mondlichtung","teldrassil","auf nach darnassus"},ang={["class:Druid"]="Diese Quest markiert Euren Übergang zur Jagd aus den Schatten heraus und verleiht Euch die Fähigkeit, den Großen Katzengeist direkt durch die Katzengestalt zu kanalisieren.",["faction:Alliance"]="Allianz-Druiden kehren von den neutralen Gestaden von Mondlichtung nach Darnassus zurück und stärken so die magischen Verteidigungslinien ihrer Heimat.",["race:NightElf"]="Die Rückkehr nach Darnassus ehrt die nachtelfischen Traditionen, die vom Zirkel des Cenarius unter dem Weltenbaum Teldrassil bewahrt werden."},sec={{t="Rückkehr in die Enklave",b="Nachdem ein aufstrebender Nachtelfendruide unter der Führung von Dendrite Sternenschauer in Mondlichtung Zwiesprache mit dem Großen Katzengeist gehalten hat, muss er nach Teldrassil zurückkehren. Starblaze erkennt an, dass Ihr Euch als würdiger Schüler erwiesen habt, und schickt Euch zurück zu Eurem primären Ausbilder, Mathrengyl Bärenfährte, der unter den Ästen der Enklave des Cenarius in Darnassus wartet."},{t="Das Wesen der Katze",b="Bei Eurer Ankunft in Darnassus erkennt Mathrengyl Bärenfährte an, dass Ihr die Weisheit des Großen Katzengeistes verinnerlicht habt. In seinen Augen steht jede Generation von Druiden vor einer Prüfung, die von diesem uralten Wesen geprägt ist, das ebenso verspielt wie tödlich ist. Da Eure Verbindung gefestigt und Euer Geist vorbereitet ist, erteilt Euch Mathrengyl die letzten Riten, die erforderlich sind, um die anmutige Gestalt der Katze anzunehmen."}},faq={{q="Was ist der Zweck dieser Quest?",a="Diese Quest schließt Eure Prüfung mit dem Großen Katzengeist ab. Nachdem Ihr Eure Aufgaben für Dendrite Sternenschauer in Mondlichtung erledigt habt, weist sie Euch an, zu Mathrengyl Bärenfährte in Darnassus zurückzukehren, damit er Euch lehren kann, wie Ihr Euch in die Katzengestalt verwandelt.",al={"warum diese quest abschließen","auf nach darnassus zweck","katzengestalt quest"}},{q="Wer schickt Euch zurück nach Darnassus?",a="Dendrite Sternenschauer, ein ranghoher Druide, der in Nachthafen in der heiligen Zuflucht von Mondlichtung weilt, gibt Euch diese Quest, nachdem Ihr den Segen des Großen Katzengeistes erhalten habt.",al={"wer startet diese quest","questgeber"}},{q="Wo kann ich Mathrengyl Bärenfährte finden?",a="Mathrengyl Bärenfährte befindet sich in der Enklave des Cenarius, dem druidischen Refugium im nordwestlichen Viertel von Darnassus auf Teldrassil.",al={"mathrengyl aufenthaltsort","wo ist bearwalker"}},{q="Welche Bedeutung hat der Große Katzengeist?",a="Der Große Katzengeist ist ein uralter, wilder Geist der Natur, der für gewandte, tödliche Raubtiere steht. Druiden müssen seine Gunst erlangen und sein duales Wesen aus Verspieltheit und Tödlichkeit verstehen, bevor es ihnen gestattet ist, seine Gestalt anzunehmen.",al={"katzengeist lore","was ist der große katzengeist"}},{q="Absolvieren alle Druiden genau dieselbe Prüfung?",a="Laut Mathrengyl Bärenfährte variiert die genaue Natur der Prüfungen von Generation zu Generation, auch wenn alle Druiden eine vom Großen Katzengeist auferlegte Prüfung bestehen müssen, um seine Gestalt zu meistern.",al={"sind druidenprüfungen identisch","generationenprüfungen"}},{q="Können Nicht-Nachtelfen diese Quest annehmen?",a="Diese spezifische Quest ist für Nachtelfendruiden der Allianz gedacht, die nach Darnassus zurückkehren. Taurendruiden folgen ihrem eigenen Pfad und erstatten nach ihrem Besuch in Mondlichtung ihren eigenen Ausbildern in Donnerfels Bericht.",al={"ist das nur für allianz","können tauren das tun"}}},fx={["5fd4c60a"]={q="Warum schickt Euch Dendrite Sternenschauer zurück nach Darnassus?",a="Ihr habt Euch vor dem Großen Katzengeist in der Mondlichtung bewährt und Eure Prüfungen unter Dendrite Sternenschauer sind abgeschlossen. Dendrites Pflicht war es, Eure Verbindung mit dem uralten Geist zu beaufsichtigen; nun erwartet Euch Euer ursprünglicher Ausbilder, Mathrengyl Bärenfährte, in Darnassus, um Euch dabei zu helfen, diese spirituellen Lektionen anzuwenden und endlich die Kunst der Gestaltwandlung der Katze zu meistern.",al={"warum nach darnassus schicken","dendrite sternenschauer motiv","warum zu mathrengyl zurückkehren"}}},fp="12,246,21.359.0,21.391.0,34.229.0,32.172.0,39.143.0,49.232.0,44.180.0,36.193.0"}
P.entries["quest:98398"] = {n="The Oracle Tree",s="The Oracle Tree ist eine Quest, in der ein vielversprechender Abenteurer angewiesen wird, mit einem empfindungsfähigen, uralten Baum in Zwiesprache zu treten. Indem Reisende nach einem Stück Rinde suchen, das der Baum absichtlich abgeworfen hat, empfangen sie seine beruhigende telepathische Botschaft und bereiten sich auf größere bevorstehende Aufgaben vor.",h="The Oracle Tree ist eine Quest, in der ein vielversprechender Abenteurer angewiesen wird, mit einem...",kw={"oracle tree","oracle tree rinde","empfindungsfähiger baum","abgeworfene rinde","telepathie","the oracle tree"},ang={["class:Druid"]="Druiden sind von Natur aus auf empfindungsfähiges pflanzliches Leben und die Stimmen uralter Bäume eingestimmt, was die Zwiesprache mit The Oracle Tree zu einer natürlichen Fortführung ihrer Ehrfurcht vor der Natur macht."},sec={{t="Ein Ruf zu höheren Pflichten",b="The Oracle Tree ist ein weiser, empfindungsfähiger Baum, der über seine Umgebung wacht und Reisende leitet, die ihren Mut unter Beweis stellen. Wenn er einen Vertreter in der Welt benötigt, wirft er ganz bewusst ein Fragment seiner Rinde in der Nähe ab. Diejenigen, die dies bemerken, werden herbeigerufen vorzutreten, was signalisiert, dass ihre einführenden Aufgaben abgeschlossen sind und größere Pflichten auf sie warten."},{t="Zwiesprache durch die Rinde",b="The Oracle Tree spricht nicht mit einer gewöhnlichen physischen Stimme. Stattdessen erlaubt die Untersuchung des abgefallenen Rindenstücks dem Baum, direkt den Geist des Suchenden zu erreichen. Seine Präsenz ist ruhig und beruhigend, bricht wie eine sanfte Brise durch ein Blätterdach über den Zuhörer herein und überträgt Gedanken sowie Wünsche, ohne ein einziges gesprochenes Wort zu äußern."}},faq={{q="Was ist The Oracle Tree?",a="The Oracle Tree ist ein uralter, empfindungsfähiger Baum, der in der Lage ist, telepathisch mit jenen in seiner Nähe zu kommunizieren. Wenn er eine Botschaft übermitteln oder eine Aufgabe vergeben möchte, wirft er ein Stück seiner Rinde ab, um die Aufmerksamkeit würdiger Abenteurer zu erregen.",al={"was ist der oracle tree","oracle tree lore"}},{q="Wie kommuniziert The Oracle Tree?",a="Anstatt mit einer hörbaren Stimme zu sprechen, übermittelt The Oracle Tree seine Gedanken telepathisch. Jeder, der die abgefallene Rinde untersucht, hört eine ruhige, beruhigende Stimme in seinen Geist dringen, gleich einer sanften Brise, die durch Blätter rauscht.",al={"wie spricht der oracle tree","oracle tree kommunikation"}},{q="Warum müsst Ihr die Rinde von The Oracle Tree finden?",a="Der Baum wirft gezielt ein Stück seiner Rinde ab, wenn ein Anliegen oder eine Pflicht erfüllt werden muss. Die Untersuchung der Rinde fungiert als Brennpunkt für den Empfang der telepathischen Führung des Baumes.",al={"warum rinde finden","zweck der abgefallenen rinde"}},{q="Wer schickt Euch zu The Oracle Tree?",a="Ein örtlicher Aufseher oder Pfleger, der Eure Taten beobachtet hat, erkennt, dass größere Pflichten vor Euch liegen. Da er die frisch abgeworfene Rinde bemerkt hat, weist er Euch an, an den Baum heranzutreten, um dessen Führung zu empfangen.",al={"wer schickt euch zum oracle tree","questgeber oracle tree"}},{q="Was ist der Zweck der Quest The Oracle Tree?",a="Die Quest leitet den Kontakt zwischen einem versierten Reisenden und dem Baum selbst ein. Indem Ihr nach der Rinde sucht, öffnet Ihr Euren Geist, um die Botschaft des Baumes zu vernehmen und zu erfahren, welche größere Aufgabe er vollendet sehen möchte.",al={"oracle tree questziel","was will der oracle tree"}},{q="Wo ist die Rinde von The Oracle Tree zu finden?",a="Die abgeworfene Rinde liegt in unmittelbarer Nähe von The Oracle Tree auf dem Boden und wartet darauf, von jemandem untersucht zu werden, der empfänglich genug ist, um ihre Botschaft zu vernehmen.",al={"wo man oraclerinde findet","fundort der rinde"}}},fp="15,263,24.358.0,26.358.0,24.230.0,37.225.0,47.190.0,35.216.0,49.203.0,36.149.0"}
P.entries["quest:984"] = {n="Wie groß ist die Bedrohung?",s="„Wie groß ist die Bedrohung?“ ist eine Quest der Allianz, die von Terenthis in Auberdine vergeben wird. Nachdem er miterlebt hat, wie der Wahnsinn der Furbolgs auf Teldrassil Fuß fasste, weist der Nachtelfendruide Kundschafter an, lokale Furbolgsiedlungen an der Dunkelküste zu untersuchen, um zu bestätigen, ob dieselbe finstere Verderbnis das Meer überquert hat.",h="„Wie groß ist die Bedrohung?“ ist eine Quest der Allianz, die von Terenthis in Auberdine vergeben wird.",kw={"ameth'aran","auberdine","verderbnis","dunkelküste","furbolg","teldrassil","terenthis","bedrohung"},ang={["class:Druid"]="Furbolgs teilen tiefe Bande mit der Natur und uralten Geistern der Wildnis, was ihren plötzlichen Verfall in die Verderbnis zu einer ernsten Sorge für Druiden macht, die mit der Heilung des Gleichgewichts von Kalimdor betraut sind.",["faction:Alliance"]="Als wichtigstes Tor der Allianz zum nördlichen Festland von Kalimdor ist der Schutz Auberdines vor Gefahren aus der Wildnis für die regionale Sicherheit und Logistik unerlässlich.",["race:NightElf"]="Für die Kaldorei ist es sowohl eine bittere Tragödie als auch eine unmittelbare Gefahr für heilige Ländereien mitanzusehen, wie uralte Verbündete wie die Furbolgs so kurz nach dem Dritten Krieg einer irrationalen Dunkelheit anheimfallen."},sec={{t="Schatten über dem Meer",b="Die Nachtelfen des nördlichen Kalimdor pflegen seit langem herzliche oder friedliche Beziehungen zu einheimischen Furbolgstämmen. Nach dem Dritten Krieg begann jedoch eine seltsame Verderbnis, den Geist der Furbolgs auf Teldrassil zu verwirren, was zu gewaltsamen Entführungen und wilden Angriffen auf ihre einstigen Verbündeten führte. Der in Auberdine stationierte Druide Terenthis befürchtet, dass dieses unheilvolle Leiden nicht auf den Weltenbaum beschränkt ist, sondern sich aktiv unter den Festlandstämmen entlang der nebligen Küsten der Dunkelküste ausbreitet."},{t="Ein aufziehender Sturm",b="Die Aufklärung eines Furbolglagers in der Nähe der Ruinen von Ameth'Aran bestätigt Terenthis' schlimmste Befürchtungen. Die Furbolgs dort zeigen ein unberechenbares, feindseliges Verhalten und tragen die deutlichen Zeichen derselben Verderbnis, die den Norden heimsucht. Ihre unmittelbare Nähe zu Auberdine macht sie von einem friedlichen Nachbarn in der Wildnis zu einer dringenden Gefahr für die Verteidigung der Siedlung der Allianz."}},faq={{q="Wer ist Terenthis?",a="Terenthis ist ein Nachtelfendruide, der im Küstenhafen von Auberdine stationiert ist. Heimgesucht von Berichten über Nachtelfen, die auf ganz Teldrassil von wahnsinnigen Furbolgs angegriffen und gefangen genommen wurden, arbeitet er daran, aufkommende Bedrohungen an der gesamten Dunkelküste zu überwachen und einzudämmen.",al={"terenthis questgeber","wer vergibt how big a threat","terenthis auberdine"}},{q="Warum werden die Furbolgs an der Dunkelküste feindselig?",a="Terenthis hat Hinweise auf Verderbnis an der Dunkelküste gesehen und vermutet, dass die Furbolgs betroffen sein könnten, wie es bei einigen auf Teldrassil der Fall war. Er bittet darum, ihre Lager zu untersuchen, da er noch keine weit verbreiteten Anzeichen festgestellt hat.",al={"warum furbolgs verrückt sind","verderbte furbolgs dunkelküste","furbolg-verderbnis"}},{q="Wo befindet sich das verderbte Furbolglager?",a="Das Lager liegt im Landesinneren im Zentrum der Dunkelküste, direkt nördlich der uralten Hochgeborenen-Ruinen von Ameth'Aran und südöstlich von Auberdine.",al={"lagerort","wo ist das furbolglager","how big a threat ort"}},{q="In welcher Beziehung steht dies zu den Ereignissen auf Teldrassil?",a="Auf Teldrassil entführten und verletzten mehrere verderbte Furbolgs Schildwachen und Zivilisten der Nachtelfen. Terenthis verweist auf jene jüngsten Rettungen, als er überprüfen will, ob das Festland der Dunkelküste vor exakt derselben Krise steht.",al={"teldrassil verbindung","teldrassil furbolgs","warum terenthis teldrassil erwähnt"}},{q="Was geschieht nach der Rückkehr zu Terenthis?",a="Meldet alle Anzeichen von Verderbnis Terenthis in Auberdine. Seine Reaktion auf die Erkenntnisse wird offenbart, wenn Ihr zurückkehrt.",al={"folgequest","was folgt auf how big a threat","quest-fortsetzung"}},{q="Warum sind Nachtelfen so besorgt über Furbolglager in der Nähe von Auberdine?",a="Auberdine dient als wichtigster Hafen und Nachschub-Lebensader der Allianz auf dem Festland. Tief verderbte, feindselige Stämme in Schlagdistanz zu haben, setzt Handelswege, Spähtrupps und die Stadt selbst plötzlichen Überfällen aus.",al={"bedrohung für auberdine","warum furbolgs wichtig sind"}}},fx={["0269df0a"]={q="Warum möchte Terenthis, dass dies erledigt wird?",a="Terenthis legte ein persönliches Gelübde ab, weiteres Blutvergießen zu verhindern, nachdem seine Nachtelfenbrüder auf Teldrassil vor korrumpierten Furbolgs gerettet werden mussten. Er hat bereits schwache Anzeichen von Verderbnis bemerkt, die die Dunkelküste berühren, und er befürchtet, dass sich die Ansteckung unentdeckt durch die örtlichen Furbolgstämme ausbreiten könnte. Indem er Euch aussendet, um ihre Lager auszukundschaften, hofft er einzuschätzen, ob die Gefahr bereits vor Auberdines Haustür steht, bevor weitere Leben verloren gehen.",al={"terenthis motiv","warum furbolgs dunkelküste untersuchen","warum interessiert sich terenthis dafür"}},["1e1a0eb0"]={q="Wen sollt Ihr untersuchen?",a="Ihr werdet ausgesandt, um die örtlichen Furbolgstämme an der Dunkelküste auszukundschaften. Während viele Furbolgclans einst friedlich oder zurückgezogen an der Seite der Nachtelfen lebten, haben dunkle Einflüsse begonnen, ihren Verstand zu verzerren und sie in den Wahnsinn zu treiben. Terenthis schickt Euch, um ihre Siedlungen zu inspizieren und zu bestätigen, ob diese Plage unter den Stämmen, die gefährlich nah an Auberdine leben, Wurzeln geschlagen hat.",al={"wen untersuche ich","welches furbolglager","wer ist das ziel"}}},fp="17,284,22.502.0,17.381.1,17.245.0,50.218.0,42.141.0,45.214.0,47.115.0,68.246.0"}
P.entries["quest:98403"] = {n="Twisted Hatred",s="Twisted Hatred ist eine Quest in Teldrassil, die den Drahtzieher hinter den Taten von Lord Melenas aufdeckt. Abenteurer reisen in die Kluft nordwestlich von Dolanaar, um Xethorr the Wicked zu konfrontieren und seine verderbten Spinnen auszurotten, bevor sich seine niederträchtigen Pläne über die Äste ausbreiten können.",h="Twisted Hatred ist eine Quest in Teldrassil, die den Drahtzieher hinter den Taten von Lord Melenas aufdeckt.",kw={"befouled webwood","die kluft","dolanaar","lord melenas","ausgewachsenes teufelsmoos","satyr","tallonkai flinkwurzel","teldrassil","twisted hatred","xethorr the wicked"},ang={["class:Druid"]="Die Perversion von Teldrassils natürlichen Spinnentieren zu einer besudelten Brut verstößt gegen das Gleichgewicht der Natur und erfordert eine Reinigung durch die Hände cenarischer Verteidiger.",["faction:Alliance"]="Tallonkai Flinkwurzel beizustehen, schützt die Siedlung Dolanaar vor den sich ausbreitenden Machenschaften der Satyrn innerhalb der primären Zuflucht der Allianz auf Kalimdor.",["race:NightElf"]="Teldrassil ist das junge Herz des Wiederaufstiegs der Kaldorei, wodurch die dämonische Verderbnis, die unter der einheimischen Tierwelt in der Kluft schwelt, eine direkte Beleidigung und Bedrohung für Euer Volk darstellt."},sec={{t="Ein schattenhafter Hintermann",b="Die Entdeckung, dass Lord Melenas nicht isoliert handelte, offenbart eine dunklere Unterströmung, die Teldrassils Wildnis durchzieht. Hinter Melenas stand Xethorr the Wicked, ein verschanzter Satyr, der aus den Schatten des Waldes die Fäden zog, um die friedlichen Äste des Weltenbaums zu untergraben."},{t="Die besudelte Brut der Kluft",b="Nachdem er nordwestlich von Dolanaar in der abgelegenen Enklave namens die Kluft Zuflucht gesucht hatte, wandte sich Xethorr Teldrassils einheimischen Spinnentieren zu. Indem er lokale Webwood-Spinnen in besudelte Bestien verwandelte, versuchte der Satyr, ihr Gift für heimtückische dämonische Ränke als Waffe einzusetzen. Tallonkai Flinkwurzel entsandte Abenteurer, um die Brut auszudünnen und Xethorrs Ausgewachsenes Teufelsmoos an sich zu bringen, bevor sich die Verderbnis weiter ausbreiten konnte."}},faq={{q="Wer ist Xethorr the Wicked?",a="Xethorr the Wicked ist ein bösartiger Satyr, der die Verderbnis in Teldrassil orchestriert. Er leitete Lord Melenas an und schlug sein Lager in der Kluft auf, wobei er einheimische Spinnen verzerrte und Ausgewachsenes Teufelsmoos nutzte, um seine finsteren Pläne zu hegen.",al={"wer ist xethorr","xethorr the wicked","wer ist der satyr"}},{q="Wo befindet sich die Kluft?",a="Die Kluft ist ein abgelegenes Gebiet tief im Wald nordwestlich von Dolanaar auf Teldrassil, in dem sich Xethorr the Wicked und seine besudelte Brut niedergelassen haben.",al={"wo ist die kluft","lage der kluft","wo findet man xethorr"}},{q="Warum sind die Spinnen von Teldrassil besudelt?",a="Die Befouled Webwoods sind einheimische Spinnen von Teldrassil, die von Xethorr the Wicked verderbt wurden. Der Satyr verzerrte ihren Verstand und ihre Physiologie in der Absicht, ihr Gift für einen üblen dämonischen Plan zu gewinnen.",al={"warum veränderten sich die spinnen","was sind befouled webwoods","lore der befouled webwoods"}},{q="Wer ist Tallonkai Flinkwurzel?",a="Tallonkai Flinkwurzel ist ein Nachtelfenwächter, der im Dorf Dolanaar auf Teldrassil stationiert ist und Abenteurer damit beauftragt, die dämonische Subversion in den umliegenden Wäldern auszumerzen.",al={"wer gab diese quest","wo ist tallonkai","rolle von tallonkai flinkwurzel"}},{q="Was ist das Ausgewachsene Teufelsmoos?",a="Ausgewachsenes Teufelsmoos ist ein verderbendes botanisches Exemplar, das von Xethorr the Wicked getragen wird und von Tallonkai Flinkwurzel gesucht wird, um mehr über die wahren Motive des Satyrs und sein fortlaufendes Wirken in Teldrassil aufzudecken.",al={"ausgewachsenes teufelsmoos","warum teufelsmoos sammeln","was ist teufelsmoos"}},{q="Wie war Lord Melenas beteiligt?",a="Lord Melenas handelte nicht aus isolierter Bosheit, sondern auf ausdrückliches Geheiß von Xethorr the Wicked, was eine koordinierte Satyr-Verschwörung enthüllt, die in Teldrassil operiert.",al={"verbindung zu melenas","wer ist lord melenas","melenas und xethorr"}}},fp="14,273,18.291.0,31.408.1,26.227.0,27.169.0,43.188.0,27.178.0,28.194.0,30.171.0"}
P.entries["quest:98404"] = {n="The Great Windborne Cat Spirit",s="The Great Windborne Cat Spirit ist eine heilige Prüfung der List und Verstohlenheit für angehende Druiden. Initianden müssen sich in den nahegelegenen Stormrage Barrow Den wagen, um drei uralte Relikte zu bergen, während sie an feindseligen Enraged Spirits vorbeischleichen. Das Bestehen dieses spirituellen Ritus beweist die Meisterschaft über die felinen Tugenden von Verstohlenheit, Wildheit und List und verleiht den Segen, die Katzengestalt anzunehmen.",h="The Great Windborne Cat Spirit ist eine heilige Prüfung der List und Verstohlenheit für angehende Druiden.",kw={"avatar of saeyleenan","katzengestalt","druidenprüfung","enraged spirits","relikt der klaue","relikt des fangzahns","relikt des stillen schattens","saeyleenan","stormrage barrow den","the great windborne cat spirit"},ang={["class:Druid"]="Dieser Ritus ist ein wesentlicher Meilenstein für Druiden, die lernen, die Beweglichkeit, Verstohlenheit und den Raubtierinstinkt der wilden Katze zu kanalisieren. Zu beweisen, dass man List und Wildheit verkörpert, ist erforderlich, bevor der Geist seinen Gestaltwandelsegen verleiht.",["race:NightElf"]="Der Stormrage Barrow Den trägt den Namen einer der bedeutendsten druidischen Linien der Nachtelfen. Die Erkundung seiner Tiefen verbindet Ausübende der Kaldorei direkt mit dem uralten Erbe des Barrow Dens und den Ahnengeistern ihres Volkes."},sec={{t="Die Prüfung der List und Verstohlenheit",b="Um die Macht des großen Katzengestaltgeists anzurufen, müssen Anwärter beweisen, dass sie das Wesen des Raubtiers besitzen. Wahre Harmonie mit der Katze erfordert ein Verständnis von List und Geduld, gepaart mit explosiver Wildheit, wenn man in die Enge getrieben wird. Der Geist gewährt seine Gabe nicht leichtfertig jenen, die einfach nur nach Macht verlangen; stattdessen prüft er, ob ein Suchender wie die felinen Jäger der Wildnis denken, sich bewegen und zuschlagen kann. Nur indem ein Initiand diese inneren Eigenschaften demonstriert, kann er hoffen, das Recht zu erlangen, die physische Gestalt der Katze anzunehmen."},{t="Der Stormrage Barrow Den",b="Die Prüfung schickt Suchende in die Düsternis des nahegelegenen Stormrage Barrow Den, der sich östlich des Avatars des Geistes befindet. Tief in diesen unterirdischen Hallen liegen drei heilige Zeichen: das Relikt des Fangzahns, das Relikt der Klaue und das Relikt des stillen Schattens. Sie einzufordern ist jedoch keineswegs unkompliziert. Der Barrow Den wird von Enraged Spirits heimgesucht, die jeden Eindringling bei Sichtkontakt gewaltsam angreifen. Um die Höhle zu überleben und die Relikte zu erreichen, kann sich ein Suchender nicht allein auf rohe Gewalt verlassen, sondern muss vorsichtig durch die Dunkelheit schreiten."},{t="Der Avatar of Saeyleenan",b="Im Zentrum dieser Prüfung steht der Avatar of Saeyleenan, die physische Manifestation, durch die The Great Windborne Cat Spirit zu jungen Initianden spricht. Im Wissen, dass ungeübten Suchenden die natürliche Verstohlenheit eines erfahrenen Raubtiers fehlt, bietet eine am Eingang des Barrow Dens platzierte Statue einen temporären Segen der Verhüllung. Jene, die erfolgreich an den rasenden Geistern vorbeischlüpfen und alle drei Relikte zurückbringen, beweisen, dass sie die Lehren des Raubtiers verinnerlicht haben. Im Gegenzug erkennt der Avatar ihre Würdigkeit an und verleiht den Segen, der nötig ist, um die Katzengestalt anzunehmen."}},faq={{q="Wer ist The Great Windborne Cat Spirit?",a="The Great Windborne Cat Spirit ist ein wilder Schutzpatron, der junge Druiden dabei anleitet, den felinen Gestaltwandel zu meistern. Indem er sich durch den Avatar of Saeyleenan manifestiert, verkörpert der Geist die zentralen räuberischen Tugenden von List, Verstohlenheit und Wildheit. Anstatt seine Gestalt frei herauszugeben, prüft er Anwärter durch eine heilige Prüfung, um sicherzustellen, dass sie die Raubtierinstinkte und die Natur der Katze respektieren.",al={"windborne cat spirit","wer ist saeyleenan","lore zum katzengestaltgeist"}},{q="Was ist der Avatar of Saeyleenan?",a="Der Avatar of Saeyleenan ist die physische Präsenz und der Sprecher für The Great Windborne Cat Spirit. Westlich des Stormrage Barrow Den gelegen, überwacht der Avatar die druidische Prüfung der Region. Er weist Suchenden die Aufgabe zu, die gestohlenen oder verborgenen Relikte des Barrow Dens zu bergen, und beurteilt, ob ein Initiand ausreichend Verstohlenheit und List bewiesen hat, um den felinen Segen zu erlangen.",al={"avatar of saeyleenan","wer ist avatar saeyleenan","saeyleenan nsc"}},{q="Welche Relikte werden für die Prüfung benötigt?",a="Die Prüfung erfordert die Bergung von drei bestimmten Relikten aus dem Stormrage Barrow Den: das Relikt des Fangzahns, das Relikt der Klaue und das Relikt des stillen Schattens. Zusammen symbolisieren diese Artefakte die wesentlichen physischen Waffen und die schwer fassbare Verstohlenheit, die die Gestalt des Katzengestaltgeists definieren, und beweisen die Ehrerbietung eines Initianden vor jedem Aspekt des Raubtiers.",al={"drei relikte","relikt der klaue","relikte des stormrage barrow den"}},{q="Wo befindet sich der Stormrage Barrow Den?",a="Der Stormrage Barrow Den liegt östlich des Avatar of Saeyleenan. Die unterirdischen Kammern dienen als Prüfungsstätte für die druidische Prüfung und beherbergen die drei heiligen Relikte. Initianden müssen in diese finsteren Hallen hinabsteigen und dabei den gefährlichen Enraged Spirits ausweichen, die durch die Tunnel streifen.",al={"ort des stormrage barrow den","wo ist der barrow den","wo man relikte findet"}},{q="Warum bewachen Enraged Spirits den Barrow Den?",a="Der Stormrage Barrow Den wurde von mächtigen Enraged Spirits überrannt, die jeden lebenden Eindringling bei Sichtkontakt angreifen. Anstatt als willige Wächter zu dienen, stellen diese feindseligen Wesenheiten eine aktive Gefahr im Barrow Den dar, die angehende Druiden dazu zwingt, List und Verstohlenheit einzusetzen, um die Relikte zu bergen, anstatt sich auf einen direkten Kampf einzulassen.",al={"warum geister erzürnt sind","enraged spirits im stormrage barrow den","wächter des barrow den"}},{q="Wie schleichen Suchende an den Enraged Spirits vorbei?",a="Eine Steinstatue am Eingang zum Stormrage Barrow Den verleiht Suchenden einen temporären Segen der Verstohlenheit. Da junge Initianden noch nicht ihre eigene angeborene Katzengestalt oder Schleichen-Fähigkeiten erlangt haben, ermöglicht ihnen diese schützende Verzauberung, unbemerkt an den wachsamen, feindseligen Geistern vorbeizuschlüpfen, um die Relikte zu sichern.",al={"wie man im barrow den schleicht","statuen-verstohlenheitsstärkungszauber","wie man enraged spirits meidet"}},{q="Welche Belohnung oder welcher Segen wird für den Abschluss der Prüfung gewährt?",a="Nach der Rückgabe des Relikts des Fangzahns, des Relikts der Klaue und des Relikts des stillen Schattens erachtet der Avatar of Saeyleenan den Suchenden als würdig für den Segen von The Great Windborne Cat Spirit. Dieser Ritus markiert das Verständnis des Initianden für die wahre Natur der Katze und verleiht ihm die spirituelle Anerkennung, die nötig ist, um die Gestalt des Raubtiers zu verkörpern.",al={"belohnung der prüfung","was man vom katzengestaltgeist erhält","segen des katzengestaltgeists"}}},fp="30,389,32.527.0,24.549.0,24.577.0,38.385.0,33.383.0,39.359.0,42.302.0,48.345.0,46.323.0,61.330.0"}
P.entries["quest:98407"] = {n="Machtdemonstration",s="Machtdemonstration ist eine Verteidigungsaufgabe der Allianz im Rotkammgebirge, die von Stellvertreter Feldon vergeben wird. Mit dem Auftrag, vordringende Gnollrudel nahe Seenhain aufzuhalten, werden Abenteurer ausgesandt, um Gnollprügler zu jagen und deren Stachelhalsbänder zu sammeln, um weitere Übergriffe auf menschliche Siedlungen zu verhindern.",h="Machtdemonstration ist eine Verteidigungsaufgabe der Allianz im Rotkammgebirge, die von Stellvertreter Feldon...",kw={"stellvertreter feldon","gnollprügler","gnolle","seenhain","rotkammgebirge","machtdemonstration","stachelhalsband"},ang={["class:Warrior"]="Gnolle beugen sich nur Vorführungen direkter, vernichtender Gewalt – was geradlinige, disziplinierte Kampfkraft an vorderster Front zur idealen Methode macht, um ihre Reihen zu brechen.",["faction:Alliance"]="Seenhain ist eine der östlichsten Bastionen der Allianz in den südlichen Östlichen Königreichen; die Sicherung seiner Grenzen gegen bestialische Übergriffe ist für die Stabilität der Region unerlässlich.",["race:Human"]="Die Siedler und Dorfbewohner des Rotkammgebirges sind Mitbürger Sturmwinds, die gefährlich schutzlos zurückgelassen wurden und sich darauf verlassen müssen, dass ihresgleichen die wilden Marodeure zurückschlägt."},sec={{t="Ein kühner Übergriff",b="Das Rotkammgebirge bot wilden Gnollstämmen schon lange Zuflucht, doch sie sind zunehmend dreister geworden. Anstatt isoliert hoch in den schroffen Hügeln zu verweilen, haben Gnoll-Raubtrupps beunruhigend nahe bei Seenhain und den umliegenden menschlichen Gehöften Lager aufgeschlagen. Da Sturmwinds Streitkräfte überdehnt sind und keine Verstärkung für ländliche Grenzgebiete entbehren können, müssen sich die örtlichen Behörden auf durchreisende Abenteurer verlassen, um das Umland zu sichern, bevor diese vordringenden Banden den Mut fassen, den Ort selbst anzugreifen."},{t="Ihre Sprache sprechen",b="Stellvertreter Feldon erkennt, dass Gnolle brutale, unorganisierte Kreaturen sind, die kaum etwas anderes als bloße kriegerische Vorherrschaft respektieren. Um sie zurück in die Wildnis zu zwingen, sind diplomatische Appelle oder halbe Maßnahmen nutzlos. Feldon beabsichtigt, ihre wildeste Vorhut – die Gnollprügler – anzugreifen und ihre Stachelhalsbänder als düsteren Beweis der Vorherrschaft zu erbeuten. Indem sie deren Frontkämpfer brechen und Trophäen ihrer Niederlage zur Schau stellen, hoffen Seenhains Verteidiger, die überlebenden Rudel einzuschüchtern und zum Rückzug in das Hochland zu bewegen."}},faq={{q="Wer bietet diese Quest an und wo befindet sich die Person?",a="Die Quest wird von Stellvertreter Feldon angeboten, einer Stadtwache, die an der Peripherie nahe Seenhain im Rotkammgebirge stationiert ist.",al={"questgeber","stellvertreter feldon standort","wer gibt machtdemonstration"}},{q="Warum dringen die Gnolle so nah an Seenhain vor?",a="Gnolle sind aggressive Opportunisten, die ihre Grenzen austesten. Da Seenhain mit überdehnten Verteidigungslinien und kaum militärischer Hilfe aus Sturmwind zu kämpfen hat, sind die Gnolle kühn genug geworden, um Jagdlager direkt vor den Grenzen der menschlichen Siedlungen zu errichten.",al={"warum gnolle angreifen","gnollbedrohung rotkammgebirge","warum gnolle so nah"}},{q="Welche Feinde müssen für diese Mission besiegt werden?",a="Die Mission zielt auf Gnollprügler ab, die gefährlicheren und aggressiveren Stoßtruppen der örtlichen Rudel, die schwere Stachelhalsbänder tragen.",al={"welche gnolle","welche mobs töten","gnollprügler"}},{q="Warum verlangt Stellvertreter Feldon ausdrücklich Stachelhalsbänder?",a="Gnolle richten sich nach einer brutalen Hierarchie und roher Stärke. Das Erbeuten der Stachelhalsbänder ihrer Prügler dient als direkte Machtdemonstration mit dem Ziel, die überlebenden Gnolle einzuschüchtern, damit sie sich wieder in die Hügel zurückziehen.",al={"warum stachelhalsbänder","zweck der halsbänder","warum halsbänder sammeln"}},{q="Kann Sturmwind Soldaten stellen, um sich um die Gnolle zu kümmern?",a="Sturmwind hat das Rotkammgebirge weitgehend sich selbst überlassen. Angesichts innenpolitischer Instabilität und Truppenknappheit im gesamten Königreich hat die Hauptstadt praktisch keine Verstärkung entsandt, was die örtlichen Deputys dazu zwingt, sich auf unabhängige Recken zu verlassen.",al={"sturmwind hilfe rotkammgebirge","warum keine armee aus sturmwind","wo sind die wachen"}},{q="Wo lagern die Gnolle typischerweise im Rotkammgebirge?",a="Gnoll-Lagerstätten liegen verstreut in den Hügeln und niedrigen Bergkämmen, die an den Immerruhsee grenzen, sowie entlang der Straßen, die nach Osten in Richtung Steinwacht führen.",al={"gnolllager","wo gnolle finden","gnollfundorte rotkammgebirge"}}},fp="13,284,19.520.0,23.530.0,49.120.0,49.244.0,50.136.0,56.214.0,55.228.0,52.149.0"}
P.entries["quest:98423"] = {n="The Treaty of Understanding",s="Das Abkommen des Einvernehmens ist eine uralte Zwergentafel, die das historische Friedensabkommen zwischen den Bronzebeard- und Wildhammer-Klans nach dem War of the Three Hammers ausführlich beschreibt. Aus unterirdischen Tiefen geborgen und vor König Magni Bronzebart gebracht, bewahrt das Artefakt einen entscheidenden Moment in der Geschichte der Zwerge und verdeutlicht zugleich die bittere Kluft, durch die der Dark Iron-Klan vom Frieden ausgeschlossen blieb.",h="Das Abkommen des Einvernehmens ist eine uralte Zwergentafel, die das historische Friedensabkommen zwischen...",kw={"dark iron","eisenschmiede","madoran bronzebeard","magni bronzebart","friedensabkommen","abkommen des einvernehmens","war of the three hammers","wildhammer"},ang={["faction:Alliance"]="Der historische Frieden zwischen Bronzebeard- und Wildhammer-Zwergen bildete die Grundlage ihrer modernen Zusammenarbeit innerhalb der Großen Allianz.",["race:Dwarf"]="Diese Steintafel ist ein greifbares Zeugnis zwergischer Versöhnung und zeigt, wie Eure Vorfahren ihre Fehde beilegten, nachdem um den Berg gekämpft worden war."},sec={{t="Ein Relikt zwergischer Versöhnung",b="Tief aus einer uralten Gruft geborgen, ist das Abkommen des Einvernehmens eine historische Steintafel, die die formelle Beendigung der Feindseligkeiten zwischen Zwergenklans dokumentiert. Es stammt aus den turbulenten Nachwirkungen des War of the Three Hammers und stellt jenen Moment dar, in dem Frieden zwischen den Bronzebeard- und Wildhammer-Klans geschlossen wurde, nachdem sich die Bronzebeards die Kontrolle über den Berg von Eisenschmiede gesichert hatten."},{t="Der ununterzeichnete Frieden",b="Als ihm die geborgene Tafel präsentiert wird, erkennt König Magni Bronzebart sie als das Werk seines Vorfahren Madoran Bronzebeard an, des ersten Bronzebeard-Königs von Eisenschmiede. Während das Dokument die Unterschriften der Anführer sowohl der Bronzebeard als auch der Wildhammer trägt, fehlt auffälligerweise das Zeichen des Dark Iron-Klans, was als bleibendes Zeugnis der anhaltenden Kluft zwischen den Dark Irons und ihrer Verwandtschaft im Berg dient."}},faq={{q="Was ist das Abkommen des Einvernehmens?",a="Das Abkommen des Einvernehmens ist eine uralte Zwergensteintafel, die aus tiefen Gewölben geborgen wurde. Es verzeichnet das formelle Friedensabkommen zwischen den Bronzebeard- und Wildhammer-Klans, das direkt im Anschluss an das Ende des War of the Three Hammers geschlossen wurde.",al={"was ist das abkommen des einvernehmens","abkommenstafel","was ist dieses abkommen"}},{q="Wer hat das Abkommen geschaffen?",a="Das Abkommen wurde in den Nachwirkungen des War of the Three Hammers während der Herrschaft von Madoran Bronzebeard entworfen, dem ersten Bronzebeard-König von Eisenschmiede, nachdem die drei Klans um die Kontrolle über den Berg gekämpft hatten.",al={"wer schrieb das abkommen des einvernehmens","wer erstellte das abkommen des einvernehmens","wer entwarf das abkommen"}},{q="Warum hat der Dark Iron-Klan das Abkommen nicht unterzeichnet?",a="Der Dark Iron-Klan weigerte sich, Frieden anzunehmen, nachdem die Bronzebeards die Kontrolle über Eisenschmiede übernommen hatten. Folglich unterzeichneten nur die Bronzebeard- und Wildhammer-Klans das Abkommen, was die Dark Irons isoliert und feindselig zurückließ.",al={"warum dark iron nicht unterzeichneten","haben dark iron das abkommen unterzeichnet","dark irons nicht auf abkommen"}},{q="Wer ist am Abkommen des Einvernehmens interessiert?",a="Die Tafel wird zu König Magni Bronzebart im High Seat von Eisenschmiede gebracht, der sie als unschätzbares Relikt seines Vorfahren Madoran und der Zwergengeschichte schätzt.",al={"wer will das abkommen","wem abkommen des einvernehmens übergeben","wo abkommen abgeben"}},{q="Was war der War of the Three Hammers?",a="Der War of the Three Hammers war ein erbitterter Bürgerkrieg, der zwischen den Zwergenklans der Bronzebeard, Wildhammer und Dark Iron um die Kontrolle über den Berg Eisenschmiede ausgetragen wurde. Die Bronzebeards gingen siegreich hervor und beanspruchten den Berg für sich, während die anderen Klans vertrieben wurden.",al={"was war der war of the three hammers","zwergenbürgerkrieg","three hammers krieg"}},{q="Wer war Madoran Bronzebeard?",a="Madoran Bronzebeard war der Vorfahre von König Magni Bronzebart und der erste Bronzebeard-König, der Eisenschmiede nach dem Bürgerkrieg zwischen den drei Zwergenklans regierte.",al={"wer ist madoran bronzebeard","madoran bronzebeard","magni vorfahre madoran"}}},fp="27,406,33.386.0,18.411.0,36.252.0,23.210.0,47.215.0,49.162.0,38.254.0,28.166.0"}
P.entries["quest:98459"] = {n="A Lack of Virtue",s="A Lack of Virtue ist eine Lieferquest rund um einen anhaltenden, kleinlichen Groll zwischen zwei kartenspielenden Matrosen, Tom Half-fish und Bart Tidewater. Reisende bringen ein verpacktes Geschenk über das Meer zum Hafen von Menethil und geraten dabei mitten in gegenseitige Betrugsvorwürfe darüber, wie die Maiden's Virtue gewonnen wurde.",h="A Lack of Virtue ist eine Lieferquest rund um einen anhaltenden, kleinlichen Groll zwischen zwei...",kw={"a lack of virtue","bart tidewater","maidens virtue","hafen von menethil","poker","tanaris","tom half-fish","toms geschenk","sumpfland"},ang={["faction:Alliance"]="Reisende der Allianz, die durch den Hafen von Menethil reisen, treffen oft auf Bart Tidewater, der seiner Mannschaft Befehle zubrüllt, was diese Lieferung zu einem kurzen Abstecher macht, während man auf den Transport über das Große Meer wartet."},sec={{t="Ein verbitterter Groll",b="A Lack of Virtue dreht sich um eine erbitterte Rivalität zwischen zwei rauen seefahrenden Zockern: Tom Half-fish und Bart Tidewater. Tom heuert vorbeikommende Reisende an, um ein verpacktes Paket über das Wasser zu Bart im Hafen von Menethil zu bringen, und nutzt die Lieferung als kleinliche, gehässige Spitze gegen seinen ehemaligen Gefährten. Unterwegs warnt Tom davor, dass Bart keineswegs ein echter Seebär sei, sondern vielmehr ein ehemaliger Schauspieler, der sich durch Kartenspiele gemogelt habe, um sich sein Kommando zu erkaufen."},{t="Karten auf den Tisch",b="Als Bart Tidewater Toms Geschenk an den Docks vom Hafen von Menethil entgegennimmt, gerät er schon bei der bloßen Erwähnung seines alten Weggefährten in Rage. Bart dreht den Vorwurf unverzüglich um und schwört, dass es Tom war, der beim Kartenspielen betrogen habe, und dass Bart erst genug Münzen zum Kauf der Maiden's Virtue verdient habe, nachdem ihre Pokerrunde Half-fish verbannt hatte. Trotz des explosiven Wutausbruchs fängt sich Bart schnell wieder, entschuldigt sich dafür, den Boten angefahren zu haben, und heißt den Reisenden im Hafen willkommen."}},faq={{q="Wer ist Bart Tidewater?",a="Bart Tidewater ist der selbsternannte Kapitän der Maiden's Virtue, die im Hafen von Menethil vor Anker liegt. Laut seinem alten Weggefährten Tom Half-fish war Bart ursprünglich ein Schauspieler, der sein Schiff mit Gewinnen aus Pokerspielen kaufte – obwohl sich beide Männer gegenseitig des Betrugs beim Kartenspiel bezichtigen.",al={"wer ist bart tidewater","bart tidewater lore","wer ist kapitän der maidens virtue"}},{q="Wer ist Tom Half-fish?",a="Tom Half-fish ist ein alter Bekannter von Bart Tidewater, der Reisenden ein Geschenk übergibt, damit sie es über das Meer zu Bart bringen. Er hegt einen tiefen Groll gegen den Kapitän und behauptet, Bart sei ein Betrüger, ein Geizhals und ein Falschspieler bei Kartenspielen.",al={"wer ist halbfisch","wer ist tom half-fish","wer vergibt a lack of virtue"}},{q="Was ist die Maiden's Virtue?",a="Die Maiden's Virtue ist ein Schiff, das im Hafen von Menethil im Sumpfland vor Anker liegt. Bart Tidewater behauptet, es sei das beste Schiff auf dem Großen Meer, obwohl Tom Half-fish abfällig behauptet, das Schiff sei so weit gesegelt wie ein Fels in Tanaris.",al={"was ist die maidens virtue","maidens virtue schiff","wo ist die maidens virtue"}},{q="Was ist Toms Geschenk?",a="Toms Geschenk ist ein Paket, das von Tom Half-fish an Bart Tidewater im Hafen von Menethil geschickt wurde. Während der genaue Inhalt für den Boten ungeöffnet bleibt, löst der Erhalt bei Bart sogleich einen Ausbruch wütender Beleidigungen bezüglich Toms eigenem Pokerbetrug aus.",al={"was ist toms geschenk","was ist in toms geschenk","warum wird bart wütend über toms geschenk"}},{q="Wer hat eigentlich beim Poker geschummelt?",a="Beide Matrosen bezichtigen sich gegenseitig vehement des Betrugs. Tom Half-fish beharrt darauf, Bart sei ein Schauspieler, der nur durch Mogeln genug Pokerhände gewann, um sein Schiff zu kaufen, wohingegen Bart behauptet, er habe sein Schiff erst rechtmäßig gewonnen, nachdem sie Tom wegen Betrugs aus ihrer Pokerrunde geworfen hatten.",al={"wer hat beim poker gemogelt","hat bart beim poker gemogelt","hat tom beim poker gemogelt"}},{q="Wie liefert Ihr das Geschenk im Hafen von Menethil ab?",a="Reisende können den Hafen von Menethil im Sumpfland erreichen, indem sie ein Schiff über das Große Meer nehmen. Der Questgeber merkt an, dass eine direkte Schiffsverbindung den Hafen bei ihrem zweiten Halt anläuft.",al={"wie komme ich zum hafen von menethil","schiff zum hafen von menethil"}}},fp="16,307,15.452.0,18.486.1,22.281.0,21.231.0,28.229.0,19.251.0,30.269.0,47.179.0"}
P.entries["quest:98461"] = {n="Unrequited Love",s="Unrequited Love ist eine Lieferquest der Allianz, die ihren Ursprung in Auberdine an den Küsten der Dunkelküste hat. Hollee bittet Reisende, die das Schiff zum Hafen von Menethil nehmen, Tarrel Felsweber, einem Mitschüler aus Ausgrabungszeiten, für den sie immer noch stille Zuneigung hegt, eine persönliche Nachricht zu überbringen.",h="Unrequited Love ist eine Lieferquest der Allianz, die ihren Ursprung in Auberdine an den Küsten der...",kw={"auberdine","dunkelküste","ausgrabung","hollee","hollees nachricht","hafen von menethil","merrin","tarrel felsweber","unrequited love","sumpfland"},ang={["faction:Alliance"]="Diese Lieferung verbindet den Allianzhafen Auberdine an der Dunkelküste direkt mit dem Hafen von Menethil im Sumpfland und verknüpft so Kalimdor und die Östlichen Königreiche.",["race:Dwarf"]="Tarrel Felsweber und Hollee teilen einen Hintergrund im Bereich der Ausgrabung, einem Handwerk, das für zwergische Tradition und Studien in ganz Azeroth von zentraler Bedeutung ist."},sec={{t="Eine Botschaft über das Meer",b="In der Hafenstadt Auberdine entlang der nebligen Küste der Dunkelküste beobachtet Hollee Reisende, die Schiffe zu den Östlichen Königreichen besteigen. Sie sucht Hilfe von Vorbeikommenden, um einen alten Mitschüler zu erreichen, Tarrel Felsweber, mit dem sie jahrelang das Handwerk der Ausgrabung erlernte, bevor der Abschluss sie über Kontinente hinweg trennte."},{t="Ungesagte Gefühle",b="Während Hollee sich gern an Tarrels scharfen Verstand und sein Geschick bei Ausgrabungen erinnert, gerät ihre Fassung bei der Erwähnung seiner Frau Merrin ins Wanken. Trotz der Entfernung und seiner Heirat vertraut Hollee einem Abenteurer einen persönlichen Brief an und bittet darum, Tarrel nahe dem Hafen von Menethil aufzusuchen, um sicherzustellen, dass er in Sicherheit ist."}},faq={{q="Wer bietet die Quest Unrequited Love an?",a="Hollee vergibt die Quest in der Küstensiedlung Auberdine an der Dunkelküste. Sie bittet Reisende, die das Schiff zum Hafen von Menethil besteigen, einem alten Schulkameraden eine persönliche Nachricht zu überbringen.",al={"wer gibt unrequited love","questgeber auberdine"}},{q="Wer ist Tarrel Felsweber?",a="Tarrel Felsweber ist ein Ausgräber und ehemaliger Schulkamerad von Hollee. Nach ihrer Ausbildung wurde er in das Sumpfland entsandt, wo er nun nahe dem Hafen von Menethil an der Seite seiner Frau Merrin arbeitet.",al={"wer ist tarrel felsweber","tarrel lore"}},{q="Wer ist Merrin?",a="Merrin ist Tarrel Felswebers Ehefrau. Hollee erwähnt sie mit sichtlichem Zögern und gerunzelter Stirn, was ihre anhaltenden, unerwiderten Gefühle für Tarrel trotz seiner Ehe offenbart.",al={"wer ist merrin","tarrels frau"}},{q="Warum heißt die Quest Unrequited Love?",a="Der Titel bezieht sich auf Hollees stille Gefühle für Tarrel Felsweber. Obwohl sie die Ausgrabungskunde gemeinsam als enge Mitschüler studierten, heiratete Tarrel Merrin, sodass Hollee von jenseits des Meeres in Auberdine zurückblieb und sich nach ihm sehnt.",al={"worum geht es in der quest unrequited love","warum heisst es unrequited love"}},{q="Wo befindet sich Tarrel Felsweber?",a="Tarrel Felsweber ist nahe dem Hafen von Menethil im Sumpfland zu finden, jenseits des Großen Meeres von der Dunkelküste aus. Ein Passagierschiff von Auberdine bringt Reisende direkt zu den Hafenanlegern.",al={"wo man tarrel felsweber findet","tarrel aufenthaltsort sumpfland"}},{q="Welcher Gegenstand wird in dieser Quest überbracht?",a="Ihr werdet gebeten, Hollees Nachricht zu Tarrel Felsweber zu bringen, um im Sumpfland nach seinem Wohlbefinden zu sehen und ihre persönliche Botschaft zu überbringen.",al={"was liefert ihr ab","hollees nachricht"}}},fp="15,272,24.318.0,17.299.0,37.180.0,25.188.0,14.182.0,40.208.0,35.183.0,37.134.0"}
P.entries["quest:985"] = {n="Wie groß ist die Bedrohung?",s="Wie groß ist die Bedrohung? ist eine Allianz-Quest, die vom Nachtelf Terenthis in Auberdine angeboten wird. Nachdem die Abenteurer das feindliche Lager der Blackwood-Furbolgs südlich der Stadt bereits ausgekundschaftet haben, werden sie ausgesandt, um die verderbten Pfadfinder und Windsprecher zu dezimieren, bevor deren Raserei die Siedlung bedroht.",h="Wie groß ist die Bedrohung?",kw={"auberdine","blackwood","dunkelküste","teufelsmoos","furbolg","grimclaw","pfadfinder","terenthis","windsprecher"},ang={["class:Druid"]="Druiden empfinden die Tragödie zutiefst, da das Leid der Furbolgs die anhaltende Qual des Waldes unter der Verseuchung durch Teufelsmoos widerspiegelt.",["faction:Alliance"]="Auberdine dient als lebenswichtiger Hafen für die Allianz in Dunkelküste, weshalb die Beseitigung der nahegelegenen feindlichen Lager für die Sicherung der Region entscheidend ist.",["race:NightElf"]="Für Nachtelfen ist die Ausmerzung der Blackwood ein bitterer Schmerz; jahrhundertelange Verwandtschaft mit den Furbolgs wurde durch die anhaltende dämonische Plage des Dritten Krieges zerstört."},sec={{t="Eine notwendige Ausmerzung",b="Nach ersten Erkundungen südlich von Auberdine haben die Wächterinnen festgestellt, dass die Blackwood-Furbolgs eine unmittelbare Gefahr für die Flüchtlinge und Verteidiger von Dunkelküste darstellen. Terenthis beauftragt kampffähige Reisende, direkt ihr Lager anzugreifen und Blackwood-Pfadfinder sowie Windsprecher zu eliminieren, um ihren Angriffsschwung zu brechen."},{t="Tragödie der Verderbten",b="Nachtelfen betrachten Furbolgs traditionell als spirituelle Verwandte und historische Verbündete der Wildnis. Die bösartige Ausbreitung von Teufelsmoos und dämonischer Verderbnis im nördlichen Kalimdor hat den Stamm der Blackwood jedoch in den Wahnsinn getrieben. Da kein Heilmittel bekannt ist, um den Verstand der Furbolgs wiederherzustellen, betrachten die Verteidiger von Auberdine Gewalt als grimmige Notwendigkeit, um unschuldige Tode zu verhindern."},{t="Grimclaws Ankunft",b="Nachdem die Ausmerzung bei Terenthis gemeldet wurde, stürmt ein weißer Bär namens Grimclaw in Auberdine auf den Nachtelfen zu. Diese Ankunft signalisiert dringende neue Entwicklungen bezüglich der Tierwelt und der Verderbnis, die die Küste heimsucht, und läutet die nächste Stufe der Verteidigungsbemühungen von Auberdine ein."}},faq={{q="Warum will Terenthis, dass die Blackwood-Furbolgs getötet werden?",a="Der Stamm der Blackwood südlich von Auberdine ist der Verderbnis anheimgefallen und wurde gewalttätig und irrational. Da ihr Lager eine unmittelbare Bedrohung für die Siedlung darstellt und noch kein Heilmittel für ihre Verderbnis entdeckt wurde, ordnet Terenthis einen Präventivschlag an, um Auberdine zu schützen.",al={"warum blackwood-furbolgs töten","grund für furbolg-ausmerzung","terenthis furbolg quest"}},{q="Wo befindet sich das Lager der Blackwood-Furbolgs?",a="Das Lager liegt direkt südlich von Auberdine im Küstenwald von Dunkelküste, eingebettet zwischen den verderbten Bäumen, wo sich der Stamm der Blackwood versammelt hat.",al={"standort blackwood-furbolgs","wo sind pfadfinder und windsprecher","furbolg-lager dunkelküste"}},{q="Wer ist Grimclaw?",a="Grimclaw ist ein weißer Bär, der mit den Untersuchungen der Wildnis in Dunkelküste in Verbindung steht.",al={"weißer bär auberdine","grimclaw der bär"}},{q="Was führt dazu, dass die Furbolgs wahnsinnig werden?",a="Die Furbolgs wurden durch Teufelsmoos und die anhaltende dämonische Verderbnis vergiftet, die nach dem Dritten Krieg zurückblieb. Die dunklen Energien, die Dunkelküste verwüsten, verzerren Körper und Geist und treiben friedliche Stämme in unkontrollierbare Aggression.",al={"warum sind furbolgs wahnsinnig","furbolg-verderbnis dunkelküste","was hat die blackwood verderbt"}},{q="Warum zögern Nachtelfen, Furbolgs zu töten?",a="Die Furbolgs und Nachtelfen teilen seit Jahrtausenden ein Band der Freundschaft und der Ehrfurcht vor der Natur. Sie zu töten fühlt sich für die Nachtelfen an, als würden sie ihre eigenen Brüder der Wildnis abschlachten, aber die Verderbnis lässt ihnen keine Alternative.",al={"nachtelfen und furbolgs","warum um furbolgs trauern"}},{q="Was ist der Unterschied zwischen der ersten und der zweiten Quest „Wie groß ist die Bedrohung?“?",a="Die erste Quest prüft die Spähfähigkeiten, indem Ihr das Lager der Blackwood lokalisieren und beobachten müsst. Die zweite Quest ist ein direkter Kampfauftrag, um die Pfadfinder und Windsprecher des Lagers auszudünnen, sobald die Bedrohung bestätigt ist.",al={"teile von wie groß ist die bedrohung","unterschied wie groß ist die bedrohung"}}},fx={["0dbe6a0f"]={q="Wer sind die Wegfinder und Windsprecher der Blackwood?",a="Sie sind Mitglieder des Furbolgstamms der Blackwood, die ein Lager südlich von Auberdine errichtet haben. Durch die sich ausbreitende Waldverderbnis in den Wahnsinn getrieben und aggressiv gemacht, stellen ihre Späher und Schamanen eine unmittelbare, eskalierende Gefahr für die Nachtelfensiedlung dar. Bis ein Heilmittel für ihr Leiden entdeckt wird, hält Terenthis das Ausdünnen ihrer Reihen für den einzigen Weg, sein Volk zu schützen.",al={"blackwood wegfinder","blackwood windsprecher","wen töten wir"}},a17cffed={q="Warum schickt Terenthis einen Abenteurer anstelle der Schildwachen von Auberdine?",a="Terenthis wendet sich an einen Reisenden, der sich bereits als geschickt im Auskundschaften des Blackwood-Lagers erwiesen hat. Er fragt, ob dieser Reisende bereit ist, sich dem Stamm im Kampf zu stellen und die Bedrohung für Auberdine zu verringern.",al={"warum mich schicken","warum nicht die wachen nutzen","warum terenthis mich braucht"}}},fp="17,277,16.332.0,24.358.0,18.281.1,54.277.0,44.150.0,16.84.1,39.227.0,47.250.0,79.225.0"}
P.entries["quest:98512"] = {n="Al'Aketh Assassins",s="Al'Aketh Assassins ist eine Quest, bei der es um die Eliminierung einer gefährlichen Gruppe tödlicher Mörder geht. Abenteurer unterstützen einen Späher bei der Neutralisierung der Bedrohung und verdienen sich formelle Anerkennung, die in einem Bericht an Valanaar enthalten sein wird.",h="Al'Aketh Assassins ist eine Quest, bei der es um die Eliminierung einer gefährlichen Gruppe tödlicher Mörder...",kw={"al'aketh","assassinen","killer","quest","bericht","valanaar"},ang={["class:Rogue"]="Tödlichen Mördern wie den Al'Aketh entgegenzutreten erfordert, ihrer tödlichen Entschlossenheit und rücksichtslosen Präzision ebenbürtig zu sein."},sec={{t="Eine tödliche Bedrohung",b="Die Al'Aketh-Assassinen stellen eine tödliche Bedrohung auf dem Schlachtfeld dar und werden von Spähern vor Ort als eiskalte Mörder beschrieben. Ihre rücksichtslose Effizienz und koordinierte Präsenz machen jede Konfrontation mit ihnen sowohl für lokale Späher als auch für Reisende außergewöhnlich gefährlich. Der Umgang mit ihrer Präsenz erfordert schnelles und entschlossenes Handeln, bevor sie ihre Ziele zur Strecke bringen können."},{t="Bericht an Valanaar",b="Nach der Neutralisierung der feindlichen Streitmacht der Al'Aketh äußert ein verbündeter Agent tiefe Erleichterung über Euer Überleben gegen solch gefährliche Widersacher. Dankbar für das rechtzeitige Eingreifen verspricht der Späher, Eure heldenhafte Hilfe in einem offiziellen Bericht für Valanaar formell zu dokumentieren."}},faq={{q="Was ist Al'Aketh Assassins?",a="Al'Aketh Assassins ist eine Mission, die Abenteurer damit beauftragt, ein tödliches Kontingent von Al'Aketh-Agenten zu eliminieren. Die von ihnen ausgehende Bedrohung ist schwerwiegend genug, um sofortiges Eingreifen und einen offiziellen Bericht zu verlangen.",al={"was ist alaketh assassins","was ist diese quest","alaketh assassins quest"}},{q="Wer sind die Al'Aketh-Assassinen?",a="Die Al'Aketh-Assassinen werden als eiskalte Mörder beschrieben, die als koordinierte und gefährliche Eingreiftruppe operieren. Ihr tödliches Auftreten macht sie zu einer ernsten Bedrohung im Feld.",al={"wer sind alaketh","wer sind die alaketh assassins","alaketh killer"}},{q="Wer ist Valanaar?",a="Valanaar ist die Siedlung am südöstlichen Rand der Insel, ein Stützpunkt für ihre Friedensbewahrer. Der Späher plant, Eure Hilfe in einen Bericht aufzunehmen, wenn er nach Valanaar zurückkehrt.",al={"wer ist valanaar","was ist valanaar","bericht an valanaar"}},{q="Warum muss gegen die Al'Aketh-Assassinen vorgegangen werden?",a="Die Al'Aketh-Assassinen stellen eine tödliche und unmittelbare Gefahr für Agenten und Reisende in der Region dar. Ihre Neutralisierung ist notwendig, um verbündete Streitkräfte zu schützen und das Überleben zu sichern.",al={"warum gegen alaketh kaempfen","warum alaketh assassins toeten","alaketh bedrohung"}},{q="Was geschieht nach dem Vorgehen gegen die Assassinen?",a="Nach der Konfrontation mit den Assassinen trifft der Späher Vorbereitungen, um Valanaar Bericht zu erstatten, und würdigt dabei Eure entscheidende Hilfe während des Einsatzes.",al={"was geschieht nach alaketh assassins","folgequest alaketh","bericht an valanaar quest"}},{q="Wer würdigt Eure Hilfe beim Sieg über die Assassinen?",a="Die Quest beinhaltet einen verbündeten Agenten, der im Feld stationiert ist und feindliche Bewegungen überwacht. Dankbar für Euer Eingreifen gegen die tödlichen Assassinen vermerkt dieser Späher Euren Beitrag für das Kommando.",al={"wer vergibt alaketh assassins","wer ist der spaeher","spaeherbericht valanaar"}}},fp="18,221,15.370.0,21.289.0,27.207.0,31.177.0,16.178.0,46.178.0,46.164.0,53.200.0"}
P.entries["quest:98545"] = {n="Leonid's Letter",s="Leonid's Letter ist eine Lieferquest, die Reisende in die Tiefen von Unterstadt führt. Da Leonid die Hauptstadt der Verlassenen aufgrund einer belasteten Vergangenheit mit Fürstin Sylvanas Windläufer nicht selbst betreten möchte, heuert er einen unparteiischen Kurier an, um Glix Xizzix, einem alten Goblin-Bekannten im Trade Quarter, eine Nachricht zu überbringen.",h="Leonid's Letter ist eine Lieferquest, die Reisende in die Tiefen von Unterstadt führt.",kw={"dunkle fürstin","glix xizzix","leonid","fundsachen","naxxramas","versiegelter brief","sylvanas","trade quarter","unterstadt"},ang={["faction:Horde"]="Das Betreten der Hauptstadt der Verlassenen im Auftrag eines Außenseiters ermöglicht Horde-Abenteurern leichten Zugang zu den Annehmlichkeiten des Trade Quarters von Unterstadt.",["race:Undead"]="Leonids Vergangenheit mit der Dunklen Fürstin hindert ihn daran, Unterstadt selbst zu betreten, was die politischen Spannungen zwischen unabhängigen Untoten und Sylvanas' Loyalisten verdeutlicht."},sec={{t="Der Auftrag eines Außenseiters",b="Leonid benötigt einen Kurier, der einen versiegelten Brief zu einem Bekannten in Unterstadt bringt. Wegen vergangener Reibereien und einer heiklen Beziehung zu Fürstin Sylvanas Windläufer zieht Leonid es vor, die Hallen der Hauptstadt der Verlassenen nicht selbst zu betreten, und vertraut darauf, dass eine reisende neutrale Partei die Wachen der Stadt passiert, ohne Alarm auszulösen."},{t="Alte Kameraden im Trade Quarter",b="Der Empfänger ist Glix Xizzix, ein opportunistischer Goblin, der im Trade Quarter von Unterstadt Geschäfte macht. Beim Erhalt der Nachricht erinnert sich Glix daran, an der Seite von Leonid im Schatten der Geißelzitadelle Naxxramas überlebt zu haben. Obwohl er von Leonids Entschädigungsversprechen überrascht und verärgert ist, zahlt Glix widerwillig aus den verschiedenen Fundsachen aus, die von unachtsamen untoten Kunden zurückgelassen wurden."}},faq={{q="Wer ist Leonid und warum betritt er Unterstadt nicht?",a="Leonid ist ein erfahrener Soldat, der heikle Beziehungen zu verschiedenen Fraktionen unterhält. Aufgrund einer komplizierten Vergangenheit mit Fürstin Sylvanas Windläufer vermeidet er es, Unterstadt direkt zu betreten, und verlässt sich auf wandernde Abenteurer, um Nachrichten an seine Bekannten zu überbringen.",al={"wer vergibt leonid letter","leonid barthalomew","leonid questgeber"}},{q="Wer ist Glix Xizzix?",a="Glix Xizzix ist ein Goblin, der im belebten Trade Quarter von Unterstadt stationiert ist. Er scheint in der Nähe oder im Umfeld von Pflegediensten tätig zu sein und bewahrt ein Sortiment an Fundsachen auf, die von geistesabwesenden untoten Gästen zurückgelassen wurden.",al={"wo ist glix xizzix","wer ist glix xizzix","unterstadt goblin barbier"}},{q="Welche Geschichte verbindet Leonid mit der Dunklen Fürstin?",a="Leonid räumt ein, eine „etwas bunte Geschichte“ mit Sylvanas Windläufer, der Bansheekönigin der Verlassenen, zu haben. Anstatt zu riskieren, sie oder ihre Wachen zu provozieren, beauftragt er neutrale Dritte mit der Abwicklung seiner Angelegenheiten innerhalb der Stadt.",al={"leonid geschichte mit der dunklen fürstin","leonid und sylvanas"}},{q="Woher kennen sich Leonid und Glix?",a="Glix erinnert sich an Leonid als kampferprobten Veteranen aus intensiven militärischen Kämpfen gegen die Geißel und gedenkt jener Zeiten, als die Schreckenszitadelle Naxxramas Zerstörung auf sie herabregnen ließ.",al={"glix xizzix leonid naxxramas","woher kennen sich glix und leonid"}},{q="Warum belohnt Glix Euch mit Fundsachen?",a="Leonid sagte dem Kurier, dass Glix gerne ein Trinkgeld zahlen würde, doch Glix hatte kein solches Versprechen abgegeben. Widerstrebend fügt sich der Goblin und bietet sonderbare Schmuckstücke aus dem Fundbüro des Salons an, die von vergesslichen Kunden der Verlassenen zurückgelassen wurden.",al={"questbelohnung glix","warum fundsachen"}},{q="Wohin wird der Brief geliefert?",a="Der Brief wird hinab in die Hauptstadt der Verlassenen, Unterstadt, gebracht, direkt in das Trade Quarter, wo Händler, Handwerker und Goblins unter den wachsamen Augen der Königlichen Apothekervereinigung und der Stadtwachen ihren Geschäften nachgehen.",al={"wohin leonid letter liefern","lieferung in das trade quarter"}}},fp="15,315,20.328.0,33.404.0,47.259.0,19.218.0,44.236.0,39.175.0,51.231.0,30.227.0"}
P.entries["quest:98574"] = {n="Hallowed Memorandum",s="Das Hallowed Memorandum ist eine schriftliche Vorladung, die angehende Gnomenpriester im Coldridgetal anweist, sich mit Branstock Khalder in Ambossar zu treffen. Es markiert den Beginn ihrer spirituellen Ausbildung und stellt das Heilige Licht als ein philosophisches Rätsel dar, das gut zum gnomischen Intellekt und zur gnomischen Neugier passt.",h="Das Hallowed Memorandum ist eine schriftliche Vorladung, die angehende Gnomenpriester im Coldridgetal...",kw={"ambossar","branstock khalder","das coldridgetal","dun morogh","gnomenpriester","hallowed memorandum","heiliges licht"},ang={["class:Priest"]="Dieses Memorandum markiert den Beginn der formellen Priesterausbildung im Coldridgetal und führt angehende Heiler in die Philosophie des Heiligen Lichts ein.",["race:Gnome"]="Gnome, die sich dem Licht nähern, bringen scharfen Verstand und Neugier in das spirituelle Studium ein und behandeln heilige Mysterien als Rätsel, über die man neben dem Glauben nachgrübeln kann."},sec={{t="Eine Vorladung nach Ambossar",b="Während sie Verbündeten im Coldridgetal beistehen, erhalten vielversprechende gnomische Novizen das Hallowed Memorandum, eine einführende Nachricht, die sie anweist, Branstock Khalder in Ambossar aufzusuchen. Als Ruf zum spirituellen Studium lädt die Notiz angehende Priester dazu ein, ihre formelle Unterweisung in Dun Morogh zu beginnen."},{t="Rätsel des Glaubens",b="Nach dem Vorzeigen des Memorandums heißt Branstock Khalder den Novizen in der Gemeinschaft willkommen. Er erklärt, dass das Ergründen des Heiligen Lichts kein starres technisches Handwerk ist, sondern ein tiefgründiges Rätsel, das Neugier, scharfen Verstand und Harmonie zwischen Intellekt und Gefühl erfordert. Durch Kontemplation und Übung lernen die Schüler, diese heiligen Mysterien in heilsame Genesung und göttliche Vergeltung zu lenken."}},faq={{q="Wer hat das Hallowed Memorandum geschickt?",a="Das Memorandum wurde von einem einheimischen Verbündeten übergeben, während Ihr im Coldridgetal geholfen habt, und stammte ursprünglich von Branstock Khalder, dem in Ambossar ansässigen Priesterlehrer.",al={"wer hat mir das memorandum gegeben","wer hat das hallowed memorandum geschickt","woher kam die notiz"}},{q="Wer ist Branstock Khalder?",a="Branstock Khalder ist ein zwergischer Priesterlehrer, der in Ambossar im Coldridgetal stationiert ist. Er leitet angehende Priester dabei an, das Licht zu verstehen und heilige Kräfte zu nutzen, um Wunden zu heilen oder das Böse zu strafen.",al={"wer ist branstock","branstock khalder ambossar"}},{q="Wie nähern sich Gnome dem Heiligen Licht?",a="Branstock erklärt, dass gnomische Neugier und gnomischer Intellekt als natürliche Wege dienen, um das Licht zu verstehen. Anstatt es als strenges technisches Handwerk zu behandeln, ermutigt er dazu, es als ein philosophisches Rätsel zu betrachten, das Denken und Fühlen vereint.",al={"können gnome priester sein","verbindung der gnome zum licht","wie sehen gnome das licht"}},{q="Was lehrt Branstock über das Licht?",a="Branstock beschreibt das Licht nicht als eine exakte technische Disziplin, sondern als ein Rätsel, das praktische Segnungen und Lebenslektionen bietet, die man durch die Vereinigung der eigenen Gedanken und inneren Gefühle entdeckt.",al={"was ist das licht laut branstock","lichträtsel branstock"}},{q="Welche Fähigkeiten bietet Branstock zu lehren an?",a="Sobald ein Priester beginnt, das Licht zu begreifen, bietet Branstock gegen bescheidene Spenden Anleitung dazu, diese Macht direkt in schützende Heilgebete und heilige Züchtigung gegen die Frevler zu lenken.",al={"was lehrt branstock","was können priesterlehrer lehren"}},{q="Wo ist Branstock Khalder zu finden?",a="Ambossar ist die zentrale Festung und Empfangshalle im Herzen des Coldridgetals in Dun Morogh, die Ausbilder beherbergt und Zwergen sowie reisenden Gnomen Zuflucht bietet.",al={"wo ist ambossar","standort von branstock"}}},fp="19,298,21.309.0,20.398.0,33.184.0,25.205.0,38.246.0,42.193.0,45.208.0,37.168.0"}
P.entries["quest:98576"] = {n="Glyphenpergament",s="Glyphenpergament ist eine einleitende Aufforderung an angehende Magier im Tal der Prüfungen. Das von Gornek übergebene Schreiben leitet Neulinge zu Mai'ah, einer Magierlehrerin der Trolle nahe dem Höhlenbau, um ihre arkane Disziplin zu beginnen.",h="Glyphenpergament ist eine einleitende Aufforderung an angehende Magier im Tal der Prüfungen.",kw={"arkan","durotar","glyphenpergament","gornek","magier","mai'ah","der bau","das tal der prüfungen"},ang={["class:Mage"]="Dieses Schreiben markiert Eure formelle Anerkennung als Ein Schüler des Arkanen und weist Euch an, Mai'ah aufzusuchen, um mit dem Lernen und dem Ausbau Eures Zauberbuchs zu beginnen.",["faction:Horde"]="Die Ausbildung im Tal der Prüfungen stellt sicher, dass selbst so unbeständige Künste wie das Arkane mit Disziplin erlernt werden, um die Zukunft der Horde zu stärken.",["race:Troll"]="Mai'ah repräsentiert die wachsenden arkanen Traditionen der Dunkelspeere und bietet ihre kosmischen Erkenntnisse dar, um sowohl andere Trolle als auch verbündete Rekruten zu leiten."},sec={{t="Ein Ruf zum Studium",b="Während neue Rekruten ihren körperlichen Mut gegen das einheimische Ungeziefer von Durotar unter Beweis stellen, können sich jene mit einer Affinität zum Arkanen nicht allein auf rohe Gewalt verlassen. Gornek überreicht eine mit Runen beschriebene Nachricht, die Zauberanfänger anweist, Mai'ah aufzusuchen, welche die frühe magische Ausbildung der neuesten Rekruten der Horde beaufsichtigt."},{t="Der Weg des Arkanen",b="Direkt vor dem Eingang zum Höhlenbau dämpft Mai'ah die Ambitionen junger Zauberwirker. Anstatt unbedacht rohe Zauberei zu schleudern, legt sie Wert auf Geduld, Timing und kalkulierten Intellekt. Unter ihrer Führung lernen Neulinge, den Kosmos als feine Fäden zu begreifen, die es zu verweben gilt, statt als unbändigen Sturm, den man entfesselt."}},faq={{q="Wer schickt das Glyphenpergament?",a="Das Pergament wird von Mai'ah geschickt, der Magierlehrerin nahe dem Höhlenbau im Tal der Prüfungen. Gornek bewahrt den Brief auf und händigt ihn aus, sobald ein angehender Magier seine Prüfungen beginnt.",al={"wer schrieb glyphenpergament","wer hat das geschickt","autor des pergaments"}},{q="Wo ist Mai'ah zu finden?",a="Mai'ah befindet sich im Tal der Prüfungen in Durotar und steht direkt vor dem Eingang zum Höhlenbau an der Seite anderer Klassenmentoren.",al={"wo ist maiah","mai'ah aufenthaltsort","mai'ah finden"}},{q="Was ist der Zweck dieser Quest?",a="Sie dient dazu, Magierneulinge mit ihrem Klassenlehrer bekannt zu machen. Ein Gespräch mit Mai'ah leitet Eure formelle Ausbildung in den arkanen Künsten ein und eröffnet den Zugang zu neuen Zaubern sowie grundlegendem Training.",al={"was bewirkt glyphenpergament","warum diese quest machen","questziel"}},{q="Wie lautet Mai'ahs Philosophie zur Magie?",a="Mai'ah lehrt, dass arkane Magie Intellekt, Beherrschung und wohlüberlegte Geduld erfordert. Anstatt impulsiv zu handeln, beobachtet ein fähiger Magier aufmerksam und schlägt im richtigen Moment mit der passenden Antwort zu.",al={"was lehrt maiah","mai'ah lore"}},{q="Warum bildet ein Troll im Tal der Prüfungen Magier aus?",a="Das Tal der Prüfungen heißt sowohl junge Orcs als auch Dunkelspeer-Trolle willkommen, die den Reihen der Horde beitreten. Dunkelspeer-Zauberwirker wie Mai'ah stellen ihre Weisheit und die Beherrschung kosmischer Kräfte zur Verfügung, um angehende Anwender anzuleiten.",al={"warum trollmagier","trolle und arkanmagie","troll-lehrer im orc-gebiet"}},{q="Wer überbringt dem Spieler das Pergament?",a="Gornek, der oberste Prüfungsaufseher im zentralen Lager des Tals der Prüfungen, überreicht das Pergament, wenn Ihr während Eurer ersten Aufgaben zu ihm zurückkehrt.",al={"wer vergibt glyphenpergament","gornek quest"}}},fp="17,250,18.345.0,21.326.0,32.183.0,26.132.0,34.186.0,37.221.0,54.209.0,41.159.0"}
P.entries["quest:98581"] = {n="Archaic Rune",s="Die Archaic Rune ist eine Einführungsquest für angehende Zwergenschamanen in Dun Morogh. Erfüllt von elementarer Kraft aus uralten Inschriften der Wildhammer führt diese heilige Tafel junge Initianden an ihr elementares Erbe heran. Das Überbringen des Steins an Teo Hammerstorm in Ambossar markiert den offiziellen Beginn ihrer Ausbildung in den Lehren von Erde, Luft, Feuer und Wasser.",h="Die Archaic Rune ist eine Einführungsquest für angehende Zwergenschamanen in Dun Morogh.",kw={"ambossar","archaic rune","bronzebart","das coldridgetal","elemente","schamane","teo hammerstorm","wildhammerclan"},ang={["class:Shaman"]="Die Archaic Rune stellt den allerersten Schritt auf der spirituellen Reise eines Zwergenschamanen dar, bestätigt seine elementare Einstimmung und führt ihn zu seinem ersten Mentor.",["faction:Alliance"]="Indem Mentoren der Wildhammer schamanische Künste nach Dun Morogh bringen, erweitern sich die spirituellen Praktiken der Allianz, wodurch elementare Traditionen neben dem Heiligen Licht etabliert werden.",["race:Dwarf"]="Diese Rune markiert einen bedeutenden kulturellen Austausch zwischen Zwergenclans, da die Wildhammer ihre uralten spirituellen Traditionen mit ihren Verwandten von den Bronzebart im Coldridgetal teilen."},sec={{t="Eine uralte Inschrift",b="Angehende Abenteurer im Coldridgetal entdecken die Archaic Rune, nachdem sie einheimischen Verbündeten nahe Ambossar beigestanden haben. Der Stein, der markante Schriftzeichen im Stil des Wildhammerclans trägt, ist sichtlich und spürbar mit uralter elementarer Kraft aufgeladen. Die Rune dient nicht bloß als Relikt der Steinmetzkunst, sondern als elementare Prüfung: Nur jene, die über eine beginnende Einstimmung auf die Urgeister verfügen, vermögen die Zeichen auf seiner verwitterten Oberfläche zu begreifen. Jenen, die in der Lage sind, die Schrift zu lesen, weist sie den klaren Weg, in den nahegelegenen Zwergenaußenposten nach angemessener Unterweisung zu suchen."},{t="Die Weisheit der Wildhammer in Dun Morogh",b="In der großen Halle von Ambossar nimmt der Wildhammerschamane Teo Hammerstorm den beschrifteten Stein in Empfang. Über Generationen hinweg wurden die spirituellen Künste der Elemente größtenteils vom Wildhammerclan inmitten ihrer windgepeitschten Gipfel bewahrt. Nun beginnen diese Traditionen auch unter den Bronzebartzwergen von Eisenschmiede und Dun Morogh Fuß zu fassen. Hammerstorm dient als wichtige Brücke zwischen den beiden Zwergenkulturen, indem er junge Initianden willkommen heißt, die eine Berufung zur Zwiesprache mit den Elementen verspüren, und ihnen formelle Unterweisung in den Disziplinen von Erde, Luft, Feuer und Wasser erteilt."}},faq={{q="Was ist die Archaic Rune?",a="Die Archaic Rune ist eine uralte Steintafel, die mit alten Wildhammerschriftzeichen versehen und von elementarer Macht erfüllt ist. Sie wird vielversprechenden neuen Abenteurern im Coldridgetal als erste Prüfung ihres spirituellen Potenzials übergeben. Verfügt ein Initiand über das innere Gespür, um die Rune zu lesen, bestätigt dies seine Berufung zum Weg der Schamanen und weist ihn an, mit dem Lehrer in Ambossar zu sprechen.",al={"archaic rune quest","was ist diese rune","archaic rune gegenstand"}},{q="Wer hat die Archaic Rune gemeißelt?",a="Die Inschriften auf der Rune sind im traditionellen Stil des Wildhammerclans gefertigt. Sie wurde von Teo Hammerstorm entsandt, einem Wildhammerschamanen, der sich in Ambossar aufhält und den beschrifteten Stein nutzt, um neue Initianden mit einer angeborenen Verbindung zu den Elementargeistern zu erkennen und zu kontaktieren.",al={"wer hat die archaic rune erschaffen","herkunft der rune","runenschöpfer der wildhammer"}},{q="Wer ist Teo Hammerstorm?",a="Teo Hammerstorm ist ein Wildhammerzwerg und Schamanenlehrer, der in Ambossar im Coldridgetal stationiert ist. Er ist nach Dun Morogh gereist, um dabei zu helfen, die überlieferten schamanischen Lehren seines Clans mit den Bronzebartzwergen zu teilen und neue Praktizierende in den Wegen von Erde, Feuer, Wasser und Luft anzuleiten.",al={"wer ist teo hammerstorm","teo hammerstorm ambossar","schamanenlehrer ambossar"}},{q="Warum werden die Lehren der Wildhammer mit den Bronzebartzwergen geteilt?",a="Während die schamanischen Künste viele Jahre lang traditionell vom Wildhammerclan bewahrt und gehütet wurden, sind diese elementaren Praktiken vor Kurzem auch in die Obhut und Ausübung der Bronzebartzwerge übergegangen. Mentoren wie Teo Hammerstorm sind hervorgetreten, um den Zwergen von Eisenschmiede beizubringen, wie man mit den Elementargeistern Zwiesprache hält und sie ehrt.",al={"warum zwerge schamanen sind","bronzebart wildhammer schamane","hintergrund der zwergenschamanen"}},{q="Wohin bringe ich die Archaic Rune?",a="Die Rune muss zu Teo Hammerstorm gebracht werden, der sich in der Haupthalle von Ambossar im Coldridgetal aufhält. Ihm die Rune zu überreichen, beweist Eure Fähigkeit, die Elemente zu kanalisieren, und schaltet weitere Unterweisung in Euren grundlegenden Schamanenzaubern frei.",al={"wo archaic rune abgeben","archaic rune abgabe","teo hammerstorm finden"}},{q="Was bedeutet es, die Rune lesen zu können?",a="Die Archaic Rune ist von den elementaren Energien uralter Zwergenschrift erfüllt. Nur ein Initiand mit einer angeborenen Einstimmung auf die elementaren Mächte vermag ihre Schrift zu entziffern. Sie erfolgreich zu lesen beweist, dass ein Abenteurer die natürlichen Anlagen und die spirituelle Reife eines wahren Schamanen besitzt.",al={"warum kann ich die rune lesen","bedeutung der rune","die archaic rune lesen"}}},fp="12,371,22.600.0,31.566.0,25.392.0,28.298.0,23.292.0,67.343.0,33.257.0,35.290.0"}
P.entries["quest:986"] = {n="Ein verirrter Meister",s="Ein verirrter Meister beauftragt einen Abenteurer der Allianz mit dem Sammeln von Materialien, um die Suche nach Volcor zu unterstützen, einem Nachtelfen, der in der Wildnis der Dunkelküste verschollen ist. Terenthis in Auberdine bietet an, einen verzauberten Tarnumhang zu weben, um den Retter zu schützen, wofür er Pelze der wildesten Mondpirscher der Küste benötigt.",h="Ein verirrter Meister beauftragt einen Abenteurer der Allianz mit dem Sammeln von Materialien, um die Suche...",kw={"ein verirrter meister","auberdine","dunkelküste","feiner mondpirscherpelz","grimclaw","mondpirscher","terenthis","volcor","der wildbend"},ang={["class:Druid"]="Druiden können Terenthis' Respekt vor der natürlichen Heimlichkeit der Mondpirscher schätzen, der ihre wilde Essenz in eine schützende Tarnung verwandelt.",["class:Hunter"]="Jäger werden die Verbundenheit zwischen Volcor und Grimclaw sowie das Geschick erkennen, das erforderlich ist, um die Matriarchinnen und Vatertiere der Dunkelküste aufzuspüren und zu erlegen.",["race:NightElf"]="Das Aufspüren von Volcor spiegelt die Pflicht der Nachtelfen wider, ihr Volk und ihre wilden Gefährten in den ungezähmten Weiten der Dunkelküste zu beschützen."},sec={{t="Eine Suche in der Wildnis",b="Beim Aufspüren von Bedrohungen entlang der Dunkelküste macht sich Terenthis in Auberdine Sorgen um das Schicksal von Volcor und dessen Gefährten Grimclaw. Das Vordringen tief in die südlichen Ausläufer der Region ist wegen aggressiver Raubtiere und verdorbener Wildtiere bekanntermaßen gefährlich. Anstatt einen Späher ungeschützt loszuschicken, fasst Terenthis den Plan, einen schützenden, mit wilden Illusionen erfüllten Umhang herzustellen."},{t="Pelze des Rudels",b="Um einen Umhang zu weben, der die Bestien der Dunkelküste zu täuschen vermag, genügen einfache Felle nicht. Terenthis verlangt feine Mondpirscherpelze, die gezielt von ausgewachsenen Mondpirschervatertieren oder -matriarchinnen erbeutet wurden. Diese furchterregenden Raubkatzen streifen durch die Wälder südlich von Auberdine nahe dem Wildbend und bis hin zur bewaldeten Grenze des Eschentals."},{t="Empfindliche Magie",b="Das fertige Gewand nutzt Mondpirscherfell und Naturverzauberungen, damit der Träger bei der Suche nach Volcor ungehindert durch feindseliges Gebiet reisen kann. Terenthis warnt jedoch davor, dass die Illusion empfindlich ist: Anstrengende Aktivitäten oder Kämpfe brechen die Verzauberung und lassen den Suchenden ungeschützt zurück."}},faq={{q="Wer ist Volcor?",a="Volcor ist ein Fährtenleser oder Späher der Nachtelfen, der in der Wildnis der südlichen Dunkelküste verschwand. Sein Gefährte Grimclaw und Terenthis in Auberdine suchen nach seinem Verbleib, was den Anstoß für die Suche gibt.",al={"wer ist volcor","volcor lore","ein verirrter meister volcor"}},{q="Wer bietet diese Aufgabe an?",a="Terenthis, ein in der Siedlung Auberdine an der Dunkelküste stationierter Nachtelf, bietet die Quest an, nachdem Abenteurer ihm bei früheren örtlichen Anliegen geholfen haben.",al={"questgeber","wo man ein verirrter meister erhält","terenthis standort"}},{q="Wo sind Mondpirschervatertiere und -matriarchinnen zu finden?",a="Diese erwachsenen Mondpirscher durchstreifen den Süden der Dunkelküste, insbesondere nahe den Ufern des Wildbend und weiter südlich an der Grenze zum Eschental.",al={"fundorte feiner mondpirscherpelze","wo man mondpirscher findet","wildbend raubkatzen"}},{q="Was soll der Umhang bewirken?",a="Terenthis beabsichtigt, einen verzauberten Umhang herzustellen, der den Träger vor den feindseligen Bestien der Dunkelküste verbirgt und es ihm ermöglicht, nach Volcor zu suchen, ohne ständig Angriffe auf sich zu ziehen.",al={"was bewirkt der umhang","terenthis umhang","umhangverzauberung"}},{q="Warum benötigt Terenthis bestimmte Pelze?",a="Terenthis sagt, er benötige fünf feine Pelze von Mondpirschervatertieren oder -matriarchinnen, um genügend Material für den Umhang zu haben.",al={"warum vatertiere und matriarchinnen","warum feine pelze"}},{q="Hat der Tarnumhang Einschränkungen?",a="Ja. Terenthis warnt davor, dass die Verzauberung zerbrechlich ist. Mit anderen zu sprechen ist erlaubt, aber anstrengende Interaktionen oder Kämpfe heben die Illusion schnell auf.",al={"bricht die illusion","einschränkungen des umhangs"}}},fx={bc18541c={q="Warum will Terenthis, dass dies getan wird?",a="Terenthis ist zutiefst besorgt um seinen Nachtelfengefährten Volcor, der in der gefährlichen Wildnis der südlichen Dunkelküste verschollen ist, und um den treuen Bären Grimclaw, der nach Auberdine kam, um Hilfe für seinen Meister zu suchen. Terenthis weigert sich, Euch ungeschützt in ein so gefährliches Gebiet zu schicken, daher besteht er darauf, zuerst einen magischen Tarnumhang vorzubereiten, um sicherzustellen, dass Ihr Volcor sicher aufspüren könnt, ohne von den Raubtieren der Küste zerfleischt zu werden.",al={"warum volcor helfen","terenthis motiv","warum will terenthis pelze"}}},fp="13,298,23.399.0,18.341.0,14.304.0,14.185.0,21.154.0,49.157.0,30.179.0,39.123.0,43.157.0"}
P.entries["quest:98601"] = {n="A Difficult Path",s="A Difficult Path markiert den offiziellen Beginn der Ausbildung eines Paladins der Verlassenen in Todesend. Nachdem sie sich um die geistlosen Untoten gekümmert haben, die aus den Grüften aufsteigen, werden frisch erweckte Streiter des Lichts zu Aramis Hammerhand in der Dorfkirche geschickt, um sich der qualvollen Realität zu stellen, im Untod heilige Energie zu führen.",h="A Difficult Path markiert den offiziellen Beginn der Ausbildung eines Paladins der Verlassenen in Todesend.",kw={"a difficult path","aramis hammerhand","geweihte schriftrolle","todesend","paladin der verlassenen","heiliges licht","schattenpriester sarvis","tirisfal"},ang={["class:Paladin"]="Diese Quest stellt die grundlegende Prüfung des Paladins der Verlassenen dar und begreift heilige Macht nicht als leichten Segen, sondern als qualvollen Schmelztiegel aus Disziplin und Ausdauer.",["race:Undead"]="Für die Verlassenen beweist das Anrufen des Lichts, dass Hingabe und Disziplin den körperlichen Tod überdauern können, selbst wenn die Magie die Hülle, die sie kanalisiert, aktiv verbrennt."},sec={{t="Eine stinkende Schriftrolle",b="Sobald ein frisch erweckter Paladin der Verlassenen die wilden Untoten vor der Krypta beseitigt hat, übergibt Schattenpriester Sarvis eine unerwartete Lieferung. Die Geweihte Schriftrolle strahlt so intensiv heilige Energie aus, dass der Schattenpriester sichtlich zurückweicht und den Überbringer unverblümt auffordert, zur Seite zu treten. Für einen Anwender von Schatten und Verfall fühlt sich schon die bloße Aura des Heiligen Lichts wie eine offene Flamme an."},{t="Der Schmelztiegel des heiligen Feuers",b="In der geschändeten Kirche von Todesend wartet Aramis Hammerhand, der Paladintrainer der Verlassenen. Während andere Völker das Licht ganz natürlich und freudvoll führen, erleiden Untote, die es anrufen, brennende, quälende Pein. Aramis unternimmt keinen Versuch, die Wahrheit zu beschönigen: Das Kanalisieren heiliger Macht durch eine verrottende Hülle ist reine Qual, doch er verlangt von seinen Schülern, den Schmerz anzunehmen, anstatt vor ihm zurückzuschrecken, und ihn als Schmelztiegel zu nutzen, um ihre neu gefundene Entschlossenheit zu stählen."}},faq={{q="Warum mag Schattenpriester Sarvis die Schriftrolle nicht?",a="Schattenpriester Sarvis hat sich der Shadow Magic und der Bewahrung seiner untoten Mitstreiter verschrieben. Die Geweihte Schriftrolle strahlt reine heilige Energie aus, die untotem Fleisch von Natur aus feindlich gesinnt ist und auf Anwender des Schattens zutiefst verstörend wirkt.",al={"sarvis heilige schriftrolle","warum ist sarvis unruhig","schattenpriester reagiert auf schriftrolle"}},{q="Können Verlassene das Heilige Licht wahrhaftig führen, ohne zu sterben?",a="Verlassene können das Licht durch schiere Willenskraft und Glauben führen, doch dies verursacht ihnen heftige Schmerzen, insbesondere wenn sie es kanalisieren, um sich selbst oder andere zu heilen. Es zu kanalisieren erfordert ungeheure geistige Ausdauer.",al={"lore der paladine der verlassenen","untote nutzen das licht","schadet das licht verlassenen"}},{q="Wer ist Aramis Hammerhand?",a="Aramis Hammerhand ist der in der Kapelle von Todesend stationierte Paladintrainer. Er leitet die neu auferstandenen Paladine der Verlassenen an und lehrt sie, die Qualen des Führens des Lichts im Untod zu ertragen und es zu einer wirksamen Waffe zu schmieden.",al={"wer ist aramis hammerhand","paladintrainer todesend","aramis rolle"}},{q="Wo findet diese Quest statt?",a="Die Quest beginnt bei Schattenpriester Sarvis auf der zentralen Lichtung von Todesend und endet nur wenige Schritte entfernt in der zerstörten Kapelle des Dorfes, wo Aramis Hammerhand sich aufhält.",al={"wo ist a difficult path","questort","wo ist die kirche von todesend"}},{q="Muss ich die Geweihte Schriftrolle lesen, um die Quest abzuschließen?",a="Nein, das Lesen der Schriftrolle ist nicht zwingend erforderlich, um das Ziel abzuschließen; wenn Ihr direkt mit Aramis Hammerhand in der Kirche sprecht, bringt dies Eure Ausbildung voran.",al={"geweihte schriftrolle lesen","ist das lesen der schriftrolle erforderlich","lesen der schriftrolle überspringen"}},{q="Warum wird der Pfad als „schwierig“ bezeichnet?",a="Der Name spiegelt den brutalen Weg des Paladins der Verlassenen wider. Während andere Krieger des Lichts Trost und Zuversicht aus ihrem Glauben schöpfen, muss ein untoter Paladin jedes Mal, wenn er einen Segen wirkt oder zuschlägt, sengendes heiliges Feuer ertragen, das durch totes Fleisch fließt.",al={"warum difficult path","bedeutung des questnamens"}}},fx={["6833d98f"]={q="Warum möchte Schattenpriester Sarvis, dass dies erledigt wird?",a="Sarvis will das Heilige Licht einfach nicht in seiner Nähe haben. Die Geweihte Schriftrolle kam für Euch an, während Ihr die gedankenlose Geißel ausdünntet, und ihre strahlende Magie beleidigt natürlicherweise seine von Schatten berührten Sinne. Anstatt in ihrer Nähe zu verweilen oder sich mit einem angehenden Paladin abzugeben, weist er Euch an, Eurem eigenen Ausbilder, Aramis Hammerhand, Bericht zu erstatten, damit Ihr beginnen könnt, Eure schmerzhafte Disziplin zu schulen.",al={"warum schickt sarvis mich zu aramis","sarvis motiv schwieriger pfad","warum gibt mir sarvis die schriftrolle"}}},fp="16,322,16.384.0,25.449.0,49.238.0,54.212.0,25.226.0,33.179.0,63.159.0,35.256.0"}
P.entries["quest:98738"] = {n="Blessings of the Great Windborne Cat Spirit",s="Blessings of the Great Windborne Cat Spirit ist eine Übergangsritus-Quest, die die Rückkehr eines Initianden von der Zwiesprache mit the Great Cat Spirit von Zephras markiert. Nachdem der Initiand die Verstohlenheit, Schnelligkeit und Wildheit der Wildkatze in sich aufgenommen hat, präsentiert er Dendrite seine neu erwachte Aura zur weiteren spirituellen Unterweisung.",h="Blessings of the Great Windborne Cat Spirit ist eine Übergangsritus-Quest, die die Rückkehr eines Initianden...",kw={"blessings of the great windborne cat spirit","katzengestalt","dendrite","druide","the great cat spirit","shen'dorei","verstohlenheit","zephras"},ang={["class:Druid"]="Diese Quest markiert einen entscheidenden Meilenstein bei der Beherrschung des raubtierhaften Katzeninstinkts und verleiht Druiden die Verstohlenheit, Schnelligkeit und Wildheit, die erforderlich sind, um mit dem Aspekt der Katze Zwiesprache zu halten und ihn anzunehmen.",["race:Skyborne"]="Der Geist erkennt den Initianden ausdrücklich als jungen shen'dorei an und bietet die Führung von Wind und Schatten aus Zephras, während sie lernen, die wilde Macht zu nutzen."},sec={{t="Zwiesprache mit dem windgeborenen Geist",b="Blessings of the Great Windborne Cat Spirit markiert den Höhepunkt einer heiligen Zwiesprache mit the Great Cat Spirit von Zephras. Nachdem ein Initiand diesen windgeborenen Beschützer aufgesucht und seine Gunst erlangt hat, kehrt er zu Dendrite zurück, um zu beweisen, dass er die List, die raubtierhafte Verstohlenheit und die Wildheit der Wildkatze verinnerlicht hat."},{t="Dendrites Unterweisung",b="Nachdem man sich nach dem Empfang des Segens präsentiert hat, führt Dendrite subtile somatische Gesten aus, um die neu erwachte Aura des Initianden zu lesen. Da Dendrite die in ihren Geist eingewobenen Katzeninstinkte wahrnimmt, erkennt er an, dass der Kandidat endlich bereit ist, seinen Geist zu fokussieren und den wahren Aspekt der Katze anzurufen."}},faq={{q="Was ist Blessings of the Great Windborne Cat Spirit?",a="Blessings of the Great Windborne Cat Spirit ist eine Übergangsritus-Quest, bei der ein Initiand, der the Great Cat Spirit aufgesucht und dessen Segen empfangen hat, zu Dendrite zurückkehrt, um seine spirituelle Zwiesprache zu vollenden.",al={"was ist diese quest","segen der katze quest","katzengeist quest"}},{q="Wer ist Dendrite?",a="Dendrite ist eine Mentorenfigur, die Initianden aussendet, um Zwiesprache mit the Great Cat Spirit zu halten. Nach ihrer Rückkehr kanalisiert er rituelle Gesten, um die Verwandlung zu spüren und zu bestätigen, ob der Initiand die Verstohlenheit, Schnelligkeit und List verinnerlicht hat, die erforderlich sind, um die Katzennatur zu kanalisieren.",al={"wer ist dendrite","dendrite lore"}},{q="Wer ist the Great Cat Spirit?",a="The Great Cat Spirit ist ein uralter Schutzgeist in Zephras. Er verleiht würdigen Initianden spirituelle Gunst, die Schnelligkeit der Winde und raubtierhafte Verstohlenheit, bevor er sie zurücksendet, um ihre Unterweisung fortzusetzen.",al={"was ist der katzengeist","great windborne cat spirit"}},{q="Wo befindet sich Zephras?",a="Zephras ist die Heimat von the Great Cat Spirit, wohin vielversprechende Initianden reisen, um seinen Rat zu suchen, seine Segen aus Wind und Schatten zu empfangen und die Grundlagen der Katzengestalt zu erlernen.",al={"wo ist zephras","katzengeist ort"}},{q="Warum spricht der Geist den Initianden als shen'dorei an?",a="The Great Cat Spirit spricht den Initianden direkt als junger shen'dorei an und verweist damit auf das uralte Erbe des Praktizierenden, der danach strebt, mit Naturgeistern Zwiesprache zu halten und den wilden Gestaltwandel zu meistern.",al={"wer sind shendorei","junge shendorei"}},{q="Was gewährt der Segen des Katzengeistes?",a="Der Segen verleiht die List, Schnelligkeit und Verstohlenheit der Katzenform. Mit dem empfangenen Segen erlangt der Initiand Dendrites Anerkennung, um seine innere Wildheit zu fokussieren und die wahre Natur der Katze anzurufen.",al={"was gewährt der segen","katzengeist segen wirkung"}}},fp="43,313,35.325.0,22.316.0,52.216.0,16.273.0,28.216.0,25.187.0,55.199.0,47.214.0"}
P.entries["quest:98815"] = {n="Highland Hides",s="Highland Hides ist ein Expeditionsauftrag, der von James Halloran in Auftrag gegeben wurde, einem Gerber mit Sitz im Hafen von Menethil. Auf der Suche nach erstklassigen Materialien aus den nebligen Bergmarschen der Highlands tauscht Halloran gefertigte Lederwaren gegen die zähen Häute räuberischer Thicket Raptors.",h="Highland Hides ist ein Expeditionsauftrag, der von James Halloran in Auftrag gegeben wurde, einem Gerber mit...",kw={"highland hides","hochland","james halloran","hafen von menethil","raptorhäute","gerber","thicket raptor","sumpfland"},ang={["class:Hunter"]="Jäger, die sich in die Bergmarschen der Highlands wagen, werden auf furchterregende Bestien wie Thicket Raptors treffen, deren zähe Häute präzises Fährtenlesen und eine saubere Jagd erfordern.",["faction:Alliance"]="Der Hafen von Menethil dient als wichtiger Hafen der Allianz im Sumpfland, in dem Handwerker wie James Halloran Reisende ausrüsten, die in die gefährlichen umliegenden Marschlande aufbrechen."},sec={{t="Die Gelegenheit eines Gerbers",b="James Halloran, ein geschickter Gerber, der in der Hafenstadt Hafen von Menethil arbeitet, hält ständig Ausschau nach exotischen Handwerksmaterialien. Als die Nachricht von einer Expedition eintrifft, die vergessene Ruinen in den Highlands erforscht, schenkt Halloran der alten Geschichte weniger Beachtung als den furchterregenden Bestien, die das bergige Marschland durchstreifen. Da er den kommerziellen und handwerklichen Wert der Tierwelt erkennt, heuert er kühne Abenteurer an, sich in die nebelverhangenen Gipfel zu wagen und auserlesene Pelze zurückzubringen."},{t="Bestien der Highlands",b="Unter der in den Highlands lauernden Fauna sind Thicket Raptors berüchtigte Raubtiere, die an das zerklüftete Marschterrain angepasst sind. Ihre zähen, strukturierten Häute werden von Handwerkern für spezialisierte Lederverarbeitung geschätzt. Halloran beauftragt Reisende damit, diese Kreaturen aufzuspüren und mit vier intakten Häuten zurückzukehren, die er für feine Verzierungen und dekorative Besätze für die Schöpfungen seiner Werkstatt verwendet."}},faq={{q="Wer ist James Halloran?",a="James Halloran ist ein einheimischer Gerber und Handwerker, der im Hafen von Menethil stationiert ist. Er arbeitet mit Leder und Ölen und sucht im gesamten Sumpfland und den umliegenden Hochlanden nach hochwertigen Häuten exotischer Bestien, um feine Besätze und Rüstungen herzustellen.",al={"wer vergibt highland hides","wer ist james halloran","gerber in menethil"}},{q="Warum benötigt James Halloran diese Häute?",a="Halloran sucht die Häute von Thicket Raptors aufgrund ihrer außergewöhnlichen Haltbarkeit und Beschaffenheit. Er hält sie für einige der feinsten Häute, die er je verarbeitet hat, und verwendet sie für spektakuläre Details an Lederverzierungen.",al={"wofür sind highland hides","warum will james raptorhäute","zweck von raptorhäuten"}},{q="Wo sind Thicket Raptors zu finden?",a="Thicket Raptors leben in den bergigen Marschlanden der Highlands und lauern in der zerklüfteten Wildnis nahe alter Ruinen, die derzeit von einer Expedition erkundet werden.",al={"wo sind dickichtraptoren","aufenthaltsort von thicket raptors","wo sind die raptoren"}},{q="Auf welche Ruinen bezieht sich Halloran?",a="Die Highlands beherbergen vergessene Ruinen, die gegenwärtig von einem Expeditionsteam untersucht werden. Während Handwerker wie Halloran sich auf die Tierwelt konzentrieren, dringen Gelehrte und Forscher tiefer in die uralten Geheimnisse des Gebiets vor.",al={"welche ruinen im hochland","expeditionsruinen im hochland","wer erforscht das hochland"}},{q="Ist diese Jagd für eine Gruppe gedacht?",a="Halloran rät dazu, gut ausgerüstete Gefährten mitzubringen. Die Bergmarschen der Highlands beherbergen eine wilde Tierwelt, was Ausflüge gegen Raubtiere wie Thicket Raptors für einen einzelnen Reisenden tückisch macht.",al={"ist highland hides gefährlich","gruppe benötigt für highland hides","brauche ich freunde für highland hides"}},{q="Was bietet James Halloran zum Tausch an?",a="Im Austausch gegen vier makellose Häute von Thicket Raptors bietet Halloran hochwertige Lederarbeiten aus seiner Werkstatt an, sodass Abenteurer ein Stück wählen können, das zu ihren Reisen passt.",al={"was bietet halloran zum tausch an","belohnungswissen zu highland hides"}}},fp="14,272,22.488.0,23.393.0,22.231.0,41.212.0,35.172.0,36.217.0,34.216.0,40.187.0"}
P.entries["quest:98824"] = {n="Prehistoric Prism",s="Prehistoric Prism ist eine Erkundungsquest, die Abenteurer anweist, ein facettenreiches Titanenrelikt aus dem Sumpfland nach Eisenschmiede zu transportieren. Von Ausgrabungsleiter Whelgar anvertraut, wird das Relikt Oberstem Forscher Magellas in der Hall of Explorers übergeben, um die Forschungen der Liga über die uralten Hüter voranzutreiben.",h="Prehistoric Prism ist eine Erkundungsquest, die Abenteurer anweist, ein facettenreiches Titanenrelikt aus dem...",kw={"hall of explorers","oberster forscher magellas","eisenschmiede","prähistorisches prisma","ausgrabungsleiter whelgar","titanenrelikt","uldaman","sumpfland"},ang={["faction:Alliance"]="Das Stiften entdeckter uralter Schätze bereichert direkt die wissenschaftlichen Sammlungen von Eisenschmiedes prestigeträchtiger Hall of Explorers.",["race:Dwarf"]="Die Bergung echter Titanenrelikte berührt das Herz der zwergischen Identität sowie den Kernauftrag der Forscherliga, die Ursprünge ihrer Schöpfer aufzudecken."},sec={{t="Eine uralte Entdeckung",b="Bei der Vermessung des Sumpflands identifiziert Ausgrabungsleiter Whelgar ein bemerkenswertes Artefakt, das auf seinen Facetten mit kunstvollen Hüterinschriften verziert ist. Da der Zwergenausgrabungsleiter erkennt, dass ein Fund von solcher historischer Tragweite in gelehrte Hände gehört, drängt er darauf, es unverzüglich in die Zwergenhauptstadt Eisenschmiede zu transportieren. Whelgar hofft, dass die Entdeckung in den offiziellen Katalog aufgenommen wird, wodurch sichergestellt wird, dass der Abenteurer neben seiner Beglaubigung gebührende Anerkennung erhält."},{t="Ein Geschenk an das Museum",b="In den geschichtsträchtigen Hallen der Hall of Explorers nimmt Oberster Forscher Magellas das Relikt im Namen der Forscherliga entgegen. Der leitende Archäologe staunt über die authentischen Schöpferzeichen und bemerkt, wie das durch die polierten Facetten fallende Licht an die Wunder erinnert, die er bei seiner frühesten Ausgrabung in Uldaman erblickte. Die Spende des Artefakts bewahrt es für wissenschaftliche Studien und erweitert die wachsenden Aufzeichnungen der Liga über das Erbe der Titanen."}},faq={{q="Wer vergibt die Quest Prehistoric Prism?",a="Ausgrabungsleiter Whelgar weist Euch an, das Relikt nach Eisenschmiede zu bringen, nachdem er die titanenartigen Inschriften auf dessen Facetten im Sumpfland beglaubigt hat.",al={"wer vergibt prähistorisches prisma","wo beginnt prähistorisches prisma","questgeber prähistorisches prisma"}},{q="Wo gebt Ihr Prehistoric Prism ab?",a="Ihr gebt das Relikt bei Oberstem Forscher Magellas in der Hall of Explorers in Eisenschmiede ab, der es mit Freuden in die Sammlung des Museums aufnimmt.",al={"bei wem prähistorisches prisma abgeben","wo prähistorisches prisma abgeben","abschluss von prähistorisches prisma"}},{q="Um was für ein Artefakt handelt es sich bei Prehistoric Prism?",a="Es ist ein uraltes, facettenreiches Artefakt, das die unverkennbaren Zeichen der Hüter trägt. Fällt Licht darauf, tanzt der Schein auf eine Weise durch seine kristalline Gestalt, die an die in Uldaman geborgenen Relikte erinnert.",al={"was ist prähistorisches prisma","ist prähistorisches prisma von titanen","was ist das relikt"}},{q="Warum ist die Hall of Explorers an dem Prisma interessiert?",a="Die Forscherliga sammelt und katalogisiert aktiv authentische Relikte titanischen Ursprungs. Oberster Forscher Magellas erachtet Artefakte dieses Kalibers als unverzichtbar, um das Wissen der Welt zu mehren und die uralte Geschichte zu verstehen.",al={"warum will magellas es haben","warum prisma spenden","hall of explorers prisma"}},{q="Welcher Bezug besteht zwischen dem Prisma und Uldaman?",a="Bei der Untersuchung der Lichtbrechung und der Hüterzeichen des Artefakts vergleicht Oberster Forscher Magellas das tanzende Licht mit Relikten, die er bei seiner allerersten archäologischen Ausgrabung in Uldaman untersuchte.",al={"hat uldaman bezug zum prisma","verbindung zu uldaman","prisma uldaman"}},{q="Wird Euer Name im Museumskatalog verzeichnet?",a="Ausgrabungsleiter Whelgar und Oberster Forscher Magellas stellen sicher, dass Eure Bergung des Relikts offiziell gewürdigt und in den historischen Archiven der Forscherliga festgehalten wird.",al={"prähistorisches prisma katalog","wird man namentlich erwähnt","historische anerkennung prisma"}}},fp="17,294,20.472.0,20.438.0,38.150.0,43.143.0,47.205.0,53.223.0,37.186.0,54.171.0"}
P.entries["quest:98895"] = {n="Darkspear Islands Clash",s="Darkspear Islands Clash ist ein militärischer Aufruf zu den Waffen der Allianz, der Champions dazu drängt, lebenswichtigen Boden gegen wilde Darkspear-Räuber zu verteidigen. Ohne sofortige Unterstützung an den Frontlinien riskiert die Allianz, den umkämpften Archipel vollständig zu verlieren.",h="Darkspear Islands Clash ist ein militärischer Aufruf zu den Waffen der Allianz, der Champions dazu drängt...",kw={"allianz","schlachtfeld","brigadegeneral","darkspear islands","darkspear islands clash","darkspear-räuber","ehrenabzeichen"},ang={["class:Paladin"]="Heilige Krieger der Allianz bringen unerschütterliche Entschlossenheit in die heftigen Zusammenstöße ein und folgen dem Ruf, das Leben von Angehörigen der Allianz zu schützen und feindliche Truppen abzuwehren.",["class:Warrior"]="Frontkämpfer tragen die Hauptlast des Angriffs gegen wilde Trollräuber, wo militärische Disziplin und Tapferkeit auf dem Schlachtfeld das Blatt wenden.",["faction:Alliance"]="Das Oberkommando der Allianz verlässt sich auf freiwillige Champions, um die Front gegen die Darkspear-Räuber zu verstärken und strategische Positionen auf den Inseln zu sichern."},sec={{t="Eine umkämpfte Front",b="Der Kampf um die Kontrolle über die Darkspear Islands ist zu einem offenen Krieg zwischen der Allianz und aggressiven Kriegstrupps der Darkspear-Räuber entbrannt. Kommandeure der Allianz, die davor warnen, dass ihr Stützpunkt auf dem Archipel ohne dringende Verstärkung überrannt wird, haben einen Aufruf zu den Waffen erlassen, damit fähige Champions die feindliche Flut eindämmen."},{t="Beweis des Mutes",b="Die Führung der Allianz verlässt sich auf bewährte Kämpfer, die bereit sind, sich direkt an die Frontlinien zu begeben. Um Disziplin zu wahren und echten Heldenmut anzuerkennen, verlangen die Kommandeure von den Kriegern, Ehrenabzeichen der Darkspear Islands als greifbaren Beweis für ihren Kampfeinsatz zurückzubringen, wodurch jene geehrt werden, die das Blatt in der Schlacht wenden."}},faq={{q="Was ist Darkspear Islands Clash?",a="Darkspear Islands Clash ist ein militärischer Aufruf zu den Waffen, der von Offizieren der Allianz herausgegeben wird, welche die Kriegsanstrengungen an den Frontlinien beaufsichtigen. Champions der Allianz haben die Aufgabe, die Darkspear-Räuber im Kampf zu stellen und ihre Beiträge durch das Bergen von Ehrenabzeichen aus den Gefechten zu beweisen.",al={"was ist darkspear islands clash","clash-quest","schlacht auf den darkspear islands"}},{q="Wer sind die Darkspear-Räuber?",a="Die Darkspear-Räuber sind Trollkriegstrupps, welche die Kontrolle über die Darkspear Islands anfechten. Ihre aggressiven Vorstöße bedrohen die Stellungen der Allianz in dem Gebiet, was das Oberkommando dazu veranlasst, dringende Rufe nach Verstärkung zu erlassen.",al={"wer sind die darkspear-räuber","darkspear-räuber feind","gegen wen kämpfen wir auf den darkspear islands"}},{q="Warum kämpft die Allianz auf den Darkspear Islands?",a="Die Allianz versucht, strategisches Territorium auf den Darkspear Islands zu halten und zu verhindern, dass die Region vollständig unter die Kontrolle der Trolle fällt. Ein Verlust von Boden würde den Einfluss und die Sicherheit der Allianz in den umkämpften Küstengewässern gefährden.",al={"warum die allianz auf den darkspear islands kämpft","warum hier kämpfen","allianz darkspear krieg"}},{q="Wer vergibt und schließt diese Mission ab?",a="Ein Brigadegeneral der Allianz, der außerhalb der Schlachtfelder stationiert ist, beaufsichtigt die Mobilisierung der Truppen und nimmt von zurückkehrenden Champions den Beweis ihres Einsatzes auf dem Schlachtfeld entgegen.",al={"wer vergibt darkspear islands clash","wer nimmt ehrenabzeichen der darkspear islands an","standort des brigadegenerals der allianz"}},{q="Was sind Ehrenabzeichen der Darkspear Islands?",a="Ehrenabzeichen sind militärische Marken, die Kämpfern für Tapferkeit und aktive Teilnahme an der Front verliehen werden. Das Vorzeigen von drei dieser Marken bei einem Brigadegeneral der Allianz dient als eindeutiger Beweis für Eure Beiträge auf dem Schlachtfeld.",al={"was sind ehrenabzeichen","ehrenabzeichen der darkspear islands","wie man den fronteinsatz nachweist"}},{q="Was steht auf dem Spiel, wenn die Allianz scheitert?",a="Ohne rasche Verstärkung droht den Stellungen der Allianz auf den Darkspear Islands unter dem unerbittlichen Druck der Darkspear-Räuber der vollständige Zusammenbruch. Die Sicherung der Inseln verhindert, dass feindliche Streitkräfte eine unangefochtene Vorherrschaft über den Archipel festigen.",al={"was passiert wenn die allianz die darkspear islands verliert","warum dringende hilfe benötigt wird","verlust der darkspear islands"}}},fp="23,242,17.337.0,14.308.0,32.280.0,30.215.0,54.233.0,38.161.0,42.236.0,39.257.0"}
P.entries["quest:98896"] = {n="Darkspear Islands Clash",s="Darkspear Islands Clash ruft Kämpfer dazu auf, ihre Gefährten zu sammeln und die feindseligen Darkspear-Räuber zu besiegen, die den Archipel umkämpfen. Die anhaltende Schlacht erfordert koordiniertes Handeln, um feindliche Vorstöße über die umkämpfte Inselkette hinweg einzudämmen.",h="Darkspear Islands Clash ruft Kämpfer dazu auf, ihre Gefährten zu sammeln und die feindseligen...",kw={"clash","darkspear islands","darkspear-räuber","inselkonflikt","sammeln","scharmützel","trollräuber"},ang={["faction:Horde"]="Dies ist die Allianz-Seite des Kampfes um die Darkspear Islands, die heiligen Trollinseln vor der Küste Kalimdors, welche die Horde gegen alle Außenstehenden hält.",["race:Troll"]="Für Troll-Abenteurer sind die Darkspear-Räuber, auf die dieser Allianz-Befehl abzielt, Vol'jins eigenes Volk, das die heiligen Inseln ihres Stammes verteidigt."},sec={{t="Der Archipel im Krieg",b="Der Darkspear Islands Clash stellt einen aktiven militärischen Vorstoß innerhalb der umkämpften Darkspear Islands dar. In das Einsatzgebiet entsandte Streitkräfte werden dazu angehalten, standhaft gegen Wellen von Darkspear-Räubern zu bleiben, die weiterhin Scharmützel an den Stränden und im Landesinneren austragen. Anstelle eines isolierten Zwischenfalls ist der Zusammenstoß Teil eines anhaltenden Feldzugs, um ein Brückenkopfgebiet auf dem Archipel zu sichern."},{t="Die Frontlinie sammeln",b="Kommandanten an der Frontlinie betonen die Notwendigkeit von Organisation und Zahlenstärke, um die widerstandsfähigen Räuber zu überwältigen. Überleben und Sieg hängen davon ab, nahe Verbündete zu einer geschlossenen Streitmacht zu sammeln, die in der Lage ist, Gegenangriffen standzuhalten, verschanzte Räuberbanden in die Flucht zu schlagen und ihre Kontrolle über die umstrittenen Inselfestungen zu brechen."}},faq={{q="Was ist der Darkspear Islands Clash?",a="Darkspear Islands Clash ist eine Aufgabe, die Abenteurer dazu aufruft, ihre Verbündeten zu sammeln und den Angriff gegen feindselige Darkspear-Räuber inmitten des anhaltenden Konflikts auf den Darkspear Islands voranzutreiben.",al={"was ist diese quest","darkspear islands clash zusammenfassung","clash quest-info"}},{q="Wo findet dieser Kampf statt?",a="Das Scharmützel findet auf den Darkspear Islands statt, einem Archipel, der von erbitterten Territorialkämpfen und anhaltenden Seegefechten geprägt ist.",al={"wo findet das statt","wo sind die darkspear islands","clash ort"}},{q="Wer sind die Darkspear-Räuber?",a="Die Darkspear-Räuber sind die Troll-Verteidiger der Horde auf den Darkspear Islands, den heiligen Inseln von Vol'jins Stamm. Die Direktive befiehlt Kämpfern, sie zu besiegen, während sie das Gebiet auf den Inseln umkämpfen.",al={"wer sind die feinde","gegen wen kämpfen wir","darkspear-räuber ziel"}},{q="Warum müssen Streitkräfte für diesen Zusammenstoß gesammelt werden?",a="Der Konflikt erfordert das Zusammenziehen und Sammeln verbündeter Streitkräfte, um anhaltenden Gegenangriffen standzuhalten und die Linien der gegnerischen Räuber zu durchbrechen.",al={"warum streitkräfte sammeln","was ist das ziel","wie clash abschließen"}},{q="Warum dauert der Kampf auf den Darkspear Islands an?",a="Die Horde und die Allianz befinden sich in einem unentschiedenen Kampf um die Stützpunkte der Inseln: Die Horde verteidigt sie als heiligen Trollboden, während die Allianz einen Stützpunkt vor der Küste Kalimdors sucht.",al={"warum gekämpft wird","warum konflikt auf den inseln","ursache der inselschlacht"}},{q="Wer befehligt die Streitkräfte in diesem Gefecht?",a="Die Direktive wird vom Brigadier General der Allianz im Alteracgebirge herausgegeben und fordert die Soldaten vor Ort auf, ohne Zögern vorzurücken.",al={"wer gibt diese quest","questgeber clash","clash kommandant"}}},fp="23,244,22.393.0,23.328.0,36.187.0,33.138.0,30.209.0,42.141.0,53.198.0,42.147.0"}
P.entries["quest:99"] = {n="Arugals Torheit",s="Arugals Torheit gipfelt in einer gefährlichen Untersuchung des Fluchs, der auf Lohenscheit lastet. Dalar Morgenweber beauftragt Agenten der Horde damit, verzauberte Fesseln von den Dorfbewohnern zu beschaffen, um Erzmagier Arugals finsteres Machwerk zu entschlüsseln. Das Aufdecken dieser Bindungen legt die tragische Magie offen, die die Siedlung im Schatten der Worgen gefangen hält.",h="Arugals Torheit gipfelt in einer gefährlichen Untersuchung des Fluchs, der auf Lohenscheit lastet.",kw={"arugal","arugals torheit","dalar morgenweber","moonrage worgen","pyrewood fesseln","pyrewood","silberwald","das grabmal"},ang={["class:Mage"]="Für Kenner des Arkanen sind Arugals Fesseln eine düstere Mahnung daran, wie die Zauberei der Kirin Tor in den Wahnsinn abdriften kann, wenn sie mit anderweltlich beschworenen Bestien vermengt wird.",["faction:Horde"]="Die Sicherung dieser Fesseln bricht Arugals mystischen Würgegriff über die Straße, die nach Süden zum Greymane-Wall führt.",["race:Undead"]="Die Verlassenen betrachten Lohenscheit mit kalter Faszination und rücksichtslosem Pragmatismus, bestrebt, Arugals Verzauberungen aufzuheben, um den südlichen Silberwald zu sichern."},sec={{t="Das Doppelleben von Pyrewood",b="Südlich des Grabmals liegt Lohenscheit, eine Siedlung, die in einem unheimlichen Zustand des Daseins gefangen ist. Im Tageslicht gehen ihre Bewohner als gewöhnliche menschliche Bauern ihrem Leben nach, ängstlich und abgeschottet. Doch wenn die Dämmerung über den Wald hereinbricht, zerreißt ihre menschliche Gestalt zu wilden Moonrage-Worgen, die unter Arugals Einfluss durch die Straßen streifen. Dalar Morgenweber versucht, genau jene arkanen Bindungen zu ergründen, die diesen täglichen Schrecken hervorrufen."},{t="Das Zerbrechen der Fesseln",b="Um die Verzauberung zu analysieren, die Pyrewood in Knechtschaft hält, benötigt Dawnweaver verzauberte Fesseln aus Pyrewood, die direkt von den verwandelten Stadtbewohnern erbeutet wurden. Statt aus einfachem Eisen bestehen diese Fesseln aus pulsierender Restmagie von Arugals fehlgeschlagenen Schutzbannungen. Durch das Studium ihrer arkanen Zusammensetzung hofft der Magier der Verlassenen, die Mechanismen der bestialischen Verwandlung zu begreifen und einen Weg zu finden, den abtrünnigen Erzmagier von Burg Shadowfang endgültig zur Strecke zu bringen."}},faq={{q="Warum verwandeln sich die Menschen von Lohenscheit nachts in Worgen?",a="Erzmagier Arugal legte finstere Verzauberungen über Lohenscheit. Tagsüber halten seine Zauber eine Illusion oder einen schlummernden Zustand der Menschlichkeit aufrecht, doch mit Einbruch der Nacht verwandeln sich die Stadtbewohner in Moonrage-Worgen unter seiner Kontrolle.",al={"pyrewood tag nacht","pyrewood fluch","warum mensch dann wolf"}},{q="Was sind die Fesseln aus Pyrewood?",a="Es sind verzauberte Fesseln, die von den verfluchten Bewohnern von Lohenscheit getragen werden. Arugal nutzte sie als Teil seiner Magie über das Dorf, und Dalar Morgenweber nutzt ihre Restenergie, um den Fluch zu erforschen.",al={"pyrewood fessel","arugal fesseln"}},{q="Wer ist Dalar Morgenweber?",a="Dalar Morgenweber ist ein Magier der Verlassenen, der im Grabmal im Silberwald stationiert ist. Er leitet die magischen Nachforschungen der Verlassenen bezüglich der von Erzmagier Arugal beschworenen Worgen.",al={"dalar morgenweber lore","wer ist questgeber das grabmal"}},{q="Heilt der Abschluss dieser Quest Lohenscheit?",a="Nein. Die erbeuteten Fesseln verschaffen Dalar Morgenweber zwar die nötigen magischen Erkenntnisse, um Arugals Magie zu verstehen, doch der Fluch hält Pyrewood weiterhin in endloser Qual gefangen.",al={"kann man pyrewood heilen","werden die bewohner von pyrewood geheilt"}},{q="Wie kontrolliert Arugal die Dorfbewohner?",a="Durch rücksichtslose Verzauberungen und verzauberte Fesseln unterwarf Arugal die Dorfbewohner seinem Willen und zwang sie in bestialische Gestalten, die den Zugang zu seiner Domäne in Burg Shadowfang bewachen.",al={"arugal pyrewood verbindung","wie kontrolliert arugal sie"}},{q="Was geschieht nach dem Abschluss der Questreihe um Arugals Torheit?",a="Dieser Auftrag markiert das letzte Kapitel der Reihe um Arugals Torheit. Das gesammelte Wissen ermöglicht es den Verlassenen, die Bedrohung von Burg Shadowfang vollständig einzuschätzen und Arugals Sturz zu planen.",al={"nach arugals torheit","arugals torheit finale"}}},fx={["0ad90a3b"]={q="Warum möchte Dalar Morgenweber die Pyrewood-Fesseln?",a="Dalar Morgenweber studiert die bizarren Verzauberungen, die Erzmagier Arugal über den Silberwald gelegt hat. Durch die Analyse der Magie, die in den Fesseln der Dorfbewohner gebunden ist, hofft Dalar, Arugals sogenannte Heilmittel zu entschlüsseln, die Geheimnisse seiner wilden Zauber zu meistern und das entscheidende Wissen zu sammeln, das benötigt wird, um den verrückten Magier letztendlich zu stürzen und seine rücksichtslose Zauberei rückgängig zu machen.",al={"warum will dalar das","dalar morgenweber motiv","warum pyrewood-fesseln sammeln"}}},fp="14,342,26.434.0,23.448.1,64.222.0,31.198.0,24.175.0,48.176.1,38.183.0,61.185.1"}
P.entries["quest:990"] = {n="Marsch ins Eschental",s="Marsch nach Eschental ist eine Reisequest der Allianz, die erfahrene Abenteurer von der Dunkelküste nach Süden in die uralten Wälder von Eschental führt. Entsandt von Schildwache Selarin, die nach Auberdine kam, um Hilfe zu suchen, werden Reisende geschickt, um sich bei Raene Wolfsläufer in der Stadt Astranaar zu melden, wo die Schildwachen gegen die sich ausbreitende Verderbnis kämpfen.",h="Marsch nach Eschental ist eine Reisequest der Allianz, die erfahrene Abenteurer von der Dunkelküste nach...",kw={"eschental","astranaar","dunkelküste","nachtelf","raene wolfsläufer","schildwache selarin","marsch nach eschental"},ang={["faction:Alliance"]="Als Champion der Allianz stärkt das Befolgen des Rufs von Astranaar die Bande zu den Nachtelfen und festigt die primäre Bastion der Fraktion im nördlichen Kalimdor.",["race:NightElf"]="Für Nachtelfen ist diese Reise eine Rückkehr in das heilige Kernland von Kalimdor, dem Ruf Eurer Schwestern folgend, um uralte heilige Stätten vor unnatürlicher Fäulnis zu schützen."},sec={{t="Aufbruch von der Küste",b="Nachdem sie Schildwache Selarins Hilferuf in Auberdine gefolgt sind, lassen Reisende die düsteren grauen Strände und schattigen Ruinen der Küste hinter sich. Die Schildwache erkennt fähige Kämpfer und Kundschafter, die sich behaupten können, und weist ihnen den Weg direkt ins Herz des Waldgebiets der Nachtelfen. Da die lokalen Bedrohungen an der Dunkelküste bewältigt sind, richtet sich das Augenmerk auf die weitaus größeren Gefahren, die aus dem Süden heranrücken."},{t="Die Straße nach Astranaar",b="Der Weg nach Süden folgt einer uralten Nachtelfenstraße, die sich durch das dichte, alte Blätterdach von Eschental schlängelt. Raene Wolfsläufer, die Anführerin der in Astranaar stationierten Schildwachen, hat einen dringenden Ruf nach Verstärkung erlassen. Angesichts dämonischen Verfalls, wild gewordener Bestien und äußerer Übergriffe auf das angestammte Land sind die Schildwachen in Astranaar überlastet und benötigen Hilfe von außen, um ihren Halt auf den heiligen Wald zu behaupten."}},faq={{q="Wer schickt Euch auf diesen Marsch?",a="Schildwache Selarin, eine Nachtelfenschildwache, die von Raene Wolfsläufer nach Auberdine geschickt wurde, um Hilfe zu suchen, weist Euch den Weg nach Süden in Richtung Astranaar.",al={"questgeber","wer startet marsch nach eschental","selarin"}},{q="Wer ist Raene Wolfsläufer?",a="Raene Wolfsläufer ist die oberste Kommandantin der Schildwachen in Astranaar. Sie ist für die Organisation der Verteidigung von Eschental verantwortlich und koordiniert die Bemühungen, die den Wald plagende Verderbnis einzudämmen.",al={"raene","wolfrunner","astranaar anführer"}},{q="Warum werden Abenteurer nach Eschental geschickt?",a="Die uralten Wälder von Eschental erliegen einer sich ausbreitenden Verderbnis und wachsenden äußeren Bedrohungen. Die einheimischen Nachtelfenschildwachen sind überwältigt und benötigen dringend fähige Verbündete, um den Bürgern und Verteidigern von Astranaar beizustehen.",al={"warum eschental","was geschieht in eschental","verderbnis eschental"}},{q="Ist die Straße zwischen der Dunkelküste und Eschental sicher?",a="Schildwache Selarin rät ausdrücklich dazu, nah an der Straße zu bleiben. Wer vom Pfad in die tiefen Wälder abweicht, setzt sich aggressiven Raubtieren, Satyren und feindlichen Kräften aus, die die ungezähmten Grenzlande durchstreifen.",al={"straßensicherheit","eschental straße sicher"}},{q="Was sollte ich nach der Ankunft in Astranaar tun?",a="Nachdem Ihr Euch direkt bei Raene Wolfsläufer gemeldet habt, rät sie dazu, mit den anderen Bewohnern und Verteidigern in ganz Astranaar zu sprechen, da viele von ihnen sofortige Hilfe bei der Bewältigung lokaler Krisen benötigen.",al={"was tun in astranaar","ankunft astranaar"}},{q="Für welche Stufe von Abenteurern ist dies gedacht?",a="Diese Reise markiert typischerweise den Abschluss der Dunkelküste um Stufe 19 herum und führt fortgeschrittene Abenteurer in das größere und umkämpftere Grenzland von Eschental.",al={"welche stufe","stufenvoraussetzung"}}},fx={b4a50545={q="Warum möchte Schildwache Selarin, dass Ihr nach Eschental geht?",a="Schildwache Selarin untersteht Raene Wolfsläufer, die die Verteidigungs- und Wiederherstellungsbemühungen in Astranaar beaufsichtigt. Da sich die Verderbnis in den uralten Wäldern von Eschental ausbreitet, sind die örtlichen Schildwachen überlastet und stehen unter enormem Druck. Selarin leitet bewährte Helden von der Dunkelküste direkt an ihre Herrin weiter, damit fähige Hände sofort damit beginnen können, die Notlage des Waldes zu lindern.",al={"warum nach eschental schicken","selarin motiv","warum nach eschental reisen"}}},fp="17,339,17.409.0,21.425.0,27.126.0,24.193.0,44.232.0,49.209.0,44.192.0,46.171.0"}
P.entries["quest:99046"] = {n="The Lost Runner",s="The Lost Runner ist eine Aufgabe, um Schildwache Eralya Leafshadow aufzuspüren, eine Kurier-Initiandin, die vom Oracle Tree überfällig ist. Sie ist von Bedeutung, da die Kommunikation zwischen dem heiligen Baum und den Ältesten in Darnassus für die Führung der Nachtelfen unerlässlich ist.",h="The Lost Runner ist eine Aufgabe, um Schildwache Eralya Leafshadow aufzuspüren, eine Kurier-Initiandin, die...",kw={"council of the forest","darnassus","eralya leafshadow","die lichtung des orakels","oracle tree","schildwachen","the lost runner"},ang={["faction:Alliance"]="Das Sichern von Straßen und Kommunikationslinien in ganz Teldrassil stärkt die Stabilität von Darnassus und dem Territorium der Allianz.",["race:NightElf"]="Die Gewährleistung einer sicheren Kommunikation zwischen dem uralten Oracle Tree und der Führung in Darnassus ist für die Sicherheit und spirituelle Führung der Kaldorei von entscheidender Bedeutung."},sec={{t="Boten des Orakels",b="Der Council of the Forest unterhält ein Kontingent von Schildwachen, die am verehrten Oracle Tree in Teldrassil stationiert sind. Der Baum übermittelt den Ältesten der Nachtelfen heilige Botschaften und verlässt sich auf engagierte Läufer, um diese Depeschen entlang der gewundenen Waldwege zurück nach Darnassus zu bringen. Die sichere Ankunft dieser Schreiben zu gewährleisten, ist für die Führung und Lenkung der Kaldorei von wesentlicher Bedeutung."},{t="Ein überfälliger Kurier",b="Nachrichten vom Oracle Tree treffen in unterschiedlichen Abständen ein, doch ein ungewöhnlich langes Schweigen schlägt Alarm, wenn ein Kurier ausbleibt. Die jüngste Aufgabe fiel Schildwache Eralya Leafshadow zu, einer Initiandin, die sich noch in der Ausbildung befindet. Aus Furcht, dass ihr auf dem Pfad ein Unglück zugestoßen sein könnte, weisen ihre Vorgesetzten Reisende an, den nach Westen führenden Weg zur Lichtung des Orakels abzusuchen, um ihr Schicksal zu ergründen."}},faq={{q="Wer ist der verlorene Läufer?",a="Die vermisste Läuferin ist Schildwache Eralya Leafshadow, eine Nachtelfen-Schildwache in Ausbildung, die den Auftrag hatte, eine Nachricht vom Oracle Tree nach Darnassus zu überbringen.",al={"wer ist the lost runner","vermisste schildwache","wer ist eralya"}},{q="Was ist der Oracle Tree?",a="Der Oracle Tree ist ein uralter Baum auf der Lichtung des Orakels, der den Ältesten der Nachtelfen in Darnassus regelmäßig Botschaften übermittelt, wofür stationierte Schildwachen benötigt werden, um diese sicher zuzustellen.",al={"was ist der oracle tree","zweck der lichtung des orakels","warum nachrichten vom oracle tree"}},{q="Wohin war Eralya Leafshadow unterwegs?",a="Eralya wurde auf der nach Westen führenden Straße zwischen Darnassus und der Lichtung des Orakels erwartet, auf der regelmäßig Läufer unterwegs sind, um Botschaften des Baumes zu überbringen.",al={"wohin ging eralya","eralyas route","standort von the lost runner"}},{q="Wer hat die Schildwachen am Oracle Tree stationiert?",a="Der Council of the Forest teilte dem Oracle Tree ein Kontingent von Schildwachen zu, um sicherzustellen, dass Nachrichten sicher und schnell an die Ältesten in Darnassus übermittelt werden.",al={"wer schickte schildwachen zum oracle tree","was ist der council of the forest"}},{q="Warum ist ihre Abwesenheit ein Grund zur Sorge?",a="Obwohl die Mitteilungen des Oracle Tree zeitlich variieren, ist ihr Ausbleiben ungewöhnlich lang geworden, was ihren Vorgesetzten angesichts ihres Status als Auszubildende Sorge bereitet.",al={"warum ihre verzögerung ungewöhnlich ist","wie oft das orakel nachrichten sendet"}},{q="Was ist das Ziel dieser Suche?",a="Ihr werdet gebeten, dem Pfad nach Westen in Richtung der Lichtung des Orakels zu folgen, um nach Schildwache Eralya Leafshadow zu suchen und herauszufinden, was sie aufgehalten hat.",al={"was man in the lost runner tut","questziel von the lost runner"}}},fp="15,238,24.380.0,18.378.0,23.164.0,24.189.0,36.160.0,47.157.0,29.162.0,37.141.0"}
P.entries["quest:99047"] = {n="Not Dead Yet",s="„Not Dead Yet“ ist das dringende Flehen von Eralya, einer tödlich verwundeten Nachtelfe, die nach einer verhängnisvollen Mission in Richtung des Oracle Tree entdeckt wurde. Überwältigt von bösartigen Harpyien fleht sie Reisende an, Byancie in Dolanaar die Nachricht vom Schicksal ihrer Patrouille zu überbringen. Dies verdeutlicht die tödlichen Gefahren, die auf den Waldpfaden von Teldrassil lauern.",h="„Not Dead Yet“ ist das dringende Flehen von Eralya, einer tödlich verwundeten Nachtelfe, die nach einer...",kw={"byancie","dolanaar","eralya","harpyien","not dead yet","oracle tree","teldrassil"},ang={["faction:Alliance"]="Abenteurer der Allianz, die Teldrassil erkunden, sind dazu aufgerufen, dringende Nachrichten zurück zu Außenposten der Siedlung wie Dolanaar zu bringen, wenn Späher im Feld abgeschnitten und überwältigt werden.",["race:NightElf"]="Die gefallene Botin Eralya und ihre Schwestern sind Schildwachen, die auf Teldrassil dienen. Zu sehen, wie Verteidiger der Nachtelfen in der Nähe des heiligen Oracle Tree von Harpyien überfallen werden, führt die eskalierenden Gefahren der Äste deutlich vor Augen."},sec={{t="Eine Patrouille im Hinterhalt",b="Als verzweifeltes Flehen in der Wildnis von Teldrassil dreht sich „Not Dead Yet“ um Eralya, eine verwundete nachtelfische Botin, die blutend und mit dem Tode ringend aufgefunden wird. Zusammen mit ihren Schwestern auf eine entscheidende Mission zum heiligen Oracle Tree entsandt, geriet die Patrouille in einen gewaltsamen Hinterhalt und wurde von vordringenden Harpyien niedergemacht. Da keine Hilfe in Sicht ist und ihre eigenen Kräfte rapide schwinden, vertraut Eralya vorbeikommenden Reisenden die dringende Botschaft an, um sie in Sicherheit zu bringen."},{t="Ein Ruf nach Dolanaar",b="Mit rasselndem Atem und Blut spuckend fleht Eralya die Spieler an, ihren Bericht zu Byancie im nahegelegenen Dorf Dolanaar zu bringen. Die Harpyien, die die großen Äste von Teldrassil heimsuchen, sind zunehmend kühner und aggressiver geworden und stellen eine tödliche Bedrohung für einsame Boten und Schildwachen dar, die die Waldpfade durchqueren. Die Überbringung von Eralyas Bitte stellt sicher, dass die Siedlung Dolanaar von dem Hinterhalt am Oracle Tree erfährt, bevor weitere Leben verloren gehen."}},faq={{q="Wer ist Eralya?",a="Eralya ist eine Schildwache oder Botin der Nachtelfen, die auf einer Mission zum Oracle Tree in einen Hinterhalt geriet. Mit dem Tode ringend und Blut spuckend beschwört sie vorbeikommende Abenteurer, die Nachricht vom Schicksal ihrer Einheit zu überbringen, bevor ihre Zeit abläuft.",al={"wer ist eralya","eralya quest","sterbende nachtelfe"}},{q="Was ist der Oracle Tree?",a="Der Oracle Tree ist ein uralter Orientierungspunkt in der Lichtung des Orakels auf Teldrassil. Eralya und ihre Schwestern wurden mit einer Dringenden Nachricht dorthin entsandt, bevor sie unterwegs überwältigt wurden.",al={"was ist der oracle tree","lichtung des orakels baum","wohin ging eralya"}},{q="Was geschah mit Eralya und ihrer Patrouille?",a="Eralya und ihre Schwestern gerieten in einen Hinterhalt und wurden von Harpyien überrannt, die die Äste von Teldrassil heimsuchen. Die Kreaturen schwärmten in großer Zahl herbei, machten die Patrouille nieder und ließen Eralya tödlich verwundet zurück.",al={"wer griff eralya an","wer überfiel sie","warum blutet eralya"}},{q="Wer ist Byancie?",a="Byancie ist eine Kontaktperson, die im Nachtelfendorf Dolanaar stationiert ist. Eralya bittet dringend darum, die Nachricht vom Hinterhalt der Harpyien und der Notlage der Patrouille direkt zu Byancie zu bringen.",al={"wer ist byancie","wo ist byancie","byancie dolanaar"}},{q="Wohin muss Eralyas Nachricht gebracht werden?",a="Dolanaar ist das wichtigste Nachtelfendorf an der Straße südlich des Laubschattentals auf Teldrassil. Byancie hält sich dort auf, um Berichte entgegenzunehmen und die örtlichen Verteidigungsbemühungen zu koordinieren.",al={"wohin botschaft bringen","eralya abgabe","wo liegt dolanaar"}},{q="Was geschah mit den anderen Schwestern auf der Mission?",a="Eralyas Kameradinnen von den Schildwachen der Nachtelfen wurden während des bösartigen Harpyienangriffs voneinander getrennt oder getötet. Da keine Verstärkung in Sicht war, fürchtete Eralya, dass keine ihrer Schwestern dem Ansturm entkommen ist.",al={"was geschah mit eralyas schwestern","schildwachen patrouille schwestern"}}},fp="12,332,18.433.0,18.460.0,14.233.0,24.184.0,39.196.0,15.178.0,41.186.0,50.188.0"}
P.entries["quest:99048"] = {n="A Missing Hand",s="A Missing Hand ist eine Quest in Durotar, die das plötzliche Verschwinden von Heglan Shadeeye betrifft, einer Späherin von The Shattered Hand, die damit beauftragt war, Burg Tiragarde im Auge zu behalten. Als ihre regelmäßigen Geheimdienstberichte abrupt ausbleiben, wird ein Ermittler ausgesandt, um ihren Posten zu finden und aufzudecken, was sie zum Schweigen brachte.",h="A Missing Hand ist eine Quest in Durotar, die das plötzliche Verschwinden von Heglan Shadeeye betrifft, einer...",kw={"a missing hand","durotar","heglan shadeeye","schurke","späher","the shattered hand","burg tiragarde"},ang={["class:Rogue"]="The Shattered Hand fungiert als das verdeckte Rückgrat und die Geheimdienstgilde der Horde. Die Untersuchung eines verschwundenen Agenten zeigt, wie gefährlich ihre Feldüberwachungseinsätze sein können.",["faction:Horde"]="Die Überreste von Kul Tiras auf Burg Tiragarde im Auge zu behalten, ist für Durotars Sicherheit von entscheidender Bedeutung, und der ungeklärte Verlust einer Späherin signalisiert eine potenzielle ungesehene Bedrohung direkt vor den Toren von Orgrimmar.",["race:Orc"]="Durotar ist ein neu gesichertes orkisches Gebiet, und dass eine Agentin in Sichtweite der nahegelegenen menschlichen Besatzer verstummt, löst sofortige Besorgnis um die Sicherheit des Reiches aus."},sec={{t="Verstummte Berichte",b="A Missing Hand beginnt mit wachsender Sorge um Heglan Shadeeye, einer Späherin, die zu The Shattered Hand gehört. In Durotar stationiert, um die feindliche Menschengarnison, die Burg Tiragarde besetzt hält, aus der Ferne zu überwachen, versiegte ihr stetiger Strom an Geheimdienstberichten plötzlich ohne Erklärung. Ihre Vorgesetzten bezweifeln, dass es den menschlichen Soldaten gelang, sie zu entdecken und gefangen zu nehmen, was Befürchtungen weckt, dass eine unerwartete und weitaus gefährlichere Bedrohung dazwischenkam. Abenteurer werden nördlich der Burg entsandt, um ihren Posten ausfindig zu machen und festzustellen, ob die Unterbrechung lediglich eine Verzögerung in der Kommunikation oder etwas weitaus Düstereres ist."},{t="Die kalte Hütte",b="Nach der Ankunft am zugewiesenen Beobachtungsposten nördlich von Burg Tiragarde endet die Suche in einer Tragödie. Heglans kalter Leichnam liegt inmitten der zersplitterten Trümmer einer verfallenen Hütte. Die physischen Spuren, die zurückgelassen wurden, deuten darauf hin, dass ihr Angreifer kein Mensch war, was die beunruhigende Frage offenlässt, welche Kreatur oder welches Wesen eine ausgebildete Agentin so nahe an den Ländereien der Horde niederstreckte. In der Nähe der Trümmer verstreute Hinweise deuten auf eine unbekannte Bedrohung hin, die nun aufgedeckt werden muss."}},faq={{q="Was ist die Quest A Missing Hand?",a="A Missing Hand ist eine Quest in Durotar, bei der ein Abenteurer damit beauftragt wird, Heglan Shadeeye ausfindig zu machen, eine Überwachungsagentin von The Shattered Hand, die nördlich von Burg Tiragarde stationiert ist und deren regelmäßige Geheimdienstberichte plötzlich abbrachen.",al={"was ist a missing hand","a missing hand quest übersicht"}},{q="Wer ist Heglan Shadeeye?",a="Heglan Shadeeye ist eine Agentin von The Shattered Hand, die den Auftrag hat, Burg Tiragarde von einem nahe gelegenen Aussichtspunkt aus heimlich zu beobachten. Ihre Überwachungsberichte brachen abrupt ab, was zu einer Untersuchung ihres Verbleibs führte.",al={"wer ist heglan","wo ist heglan shadeeye","vermisster späher"}},{q="Was geschah mit Heglan Shadeeye?",a="Das will diese Quest in Erfahrung bringen. Ihre Berichte von ihrem Posten nördlich von Burg Tiragarde blieben ohne Vorwarnung aus, und derjenige, der Euch entsendet, bezweifelt, dass die Menschen sie gefasst haben, und befürchtet, dass etwas Gefährlicheres im Spiel ist.",al={"was geschah mit heglan shadeeye","ist heglan tot","heglans schicksal"}},{q="Was ist The Shattered Hand?",a="In der modernen Horde dient The Shattered Hand als eine Organisation von heimlichen Agenten, Attentätern und Spionen. Sie führen verdeckte Überwachungs- und Aufklärungsoperationen durch, um die Gebiete der Horde zu schützen.",al={"was ist the shattered hand","wer sind the shattered hand"}},{q="Töteten die Menschen auf Burg Tiragarde Heglan?",a="Ihr Vorgesetzter bezweifelt das. Obwohl Heglan die feindlichen Menschen von Kul Tiras überwachte, die Burg Tiragarde besetzen, glaubt derjenige, der Euch entsendet, nicht, dass sie sie hätten fangen können, und befürchtet, dass etwas Gefährlicheres im Spiel ist.",al={"haben menschen heglan getötet","haben soldaten von tiragarde sie getötet"}},{q="Warum wurde Burg Tiragarde beobachtet?",a="Burg Tiragarde ist ein Außenposten, der von feindlichen Seeleuten und Soldaten aus Kul Tiras gehalten wird, welche die Küste von Durotar bedrohen. Heglan war in der Nähe stationiert, um ihre Aktivitäten im Auge zu behalten und Aufklärungsergebnisse an die Horde weiterzuleiten.",al={"warum beobachtete heglan burg tiragarde","überwachung von burg tiragarde"}}},fp="14,289,14.588.0,12.461.1,33.223.0,23.220.0,33.218.0,27.202.0,45.228.0,37.212.0"}
P.entries["quest:99049"] = {n="Threat from Below",s="Threat from Below ist eine Quest der Horde, die sich um die Untersuchung eines gewaltsamen Hinterhalts an den östlichen Küsten von Durotar dreht. Nachdem die Späherin Heglan Shadeeye an ihrem Posten in einem heftigen Scharmützel überfallen wurde, müssen Abenteurer das verwüstete Gebiet nach Hinweisen auf die Angreifer untersuchen. Das Aufdecken physischer Beweise offenbart eine drohende Gefahr, die die Verteidigungslinien von Klingenhügel direkt gefährdet.",h="Threat from Below ist eine Quest der Horde, die sich um die Untersuchung eines gewaltsamen Hinterhalts an den...",kw={"durotar","heglan shadeeye","horde","naga","orgnil narbenseele","klingenhügel","kundschafter","threat from below"},ang={["faction:Horde"]="Die Untersuchung der Küstenlinie ist für die Sicherheit von Durotar von entscheidender Bedeutung, um zu verhindern, dass die junge Nation der Horde an ihren Seegrenzen flankiert wird.",["race:Orc"]="Verteidiger der Orcs betrachten den Hinterhalt auf die Kundschafterin Heglan Shadeeye als unerträglichen Übergriff auf ihre besiedelte Heimat, der unverzügliche Untersuchungen und Vergeltung verlangt.",["race:Troll"]="Dunkelspeertrolle verstehen die heimtückische Natur der Naga nur allzu gut, da sie zuvor im Großen Meer bereits mit Meerhexen und aquatischen Schrecken konfrontiert wurden."},sec={{t="Hinterhalt an der Küste von Durotar",b="Ein heftiges Scharmützel an der Küste von Durotar hinterlässt aufgeworfene Erde und unmittelbaren Anlass zur Besorgnis unter den Verteidigern der Horde. Heglan Shadeeye, eine Späherin der Shattered Hand, die von ihrem Posten aus Wache hielt, wurde von einem unsichtbaren Widersacher überfallen. Der Schauplatz des Scharmützels zeigt deutlich, dass Heglan sich heftig zur Wehr setzte und ihre Angreifer verletzte. Da sich feindliche Streitkräfte ungehindert an der östlichen Küstenlinie bewegen, sind Abenteurer der Horde aufgerufen, das verwüstete Lager zu begutachten, den umliegenden Boden nach Hinweisen abzusuchen und festzustellen, welche Art von Feind die Späherin angegriffen hat."},{t="Die Schlangenbedrohung",b="Das Durchsuchen der Trümmer fördert ein zerrissenes Banner und das Bruchstück einer exotischen Klinge zutage, die beide zu den schlangenartigen Naga gehören. Diese unheimlichen aquatischen Kreaturen scheinen von Azshara aus an der Küste von Durotar nach Süden gekrochen zu sein, um dort einen räuberischen Stützpunkt zu errichten. Für die in Klingenhügel stationierte Garnison signalisiert diese Entdeckung eine drohende Krise. Bedrängt von menschlichen Invasoren aus Burg Tiragarde im Süden und Quilboar entlang der westlichen Canyons kann die Siedlung keine neue, von Norden heranrückende maritime Offensive ertragen, ohne den völligen Zusammenbruch zu riskieren."}},faq={{q="Was ist Threat from Below?",a="Threat from Below ist eine Quest in Durotar, bei der Abenteurer der Horde den Hinterhalt auf die Späherin Heglan Shadeeye untersuchen. Den Spuren eines heftigen Kampfes an der Küste folgend, suchen die Spieler das aufgewühlte Terrain nach Hinweisen ab, die von den unbekannten Angreifern hinterlassen wurden. Sichergestellte Artefakte werden anschließend direkt zu Orgnil Narbenseele in Klingenhügel gebracht, um die militärische Bedrohung für die Region einzuschätzen.",al={"threat from below quest","was ist threat from below","threat from below übersicht"}},{q="Wer ist Heglan Shadeeye?",a="Heglan Shadeeye ist eine Späherin der Shattered Hand, die von einer Hütte nördlich von Burg Tiragarde aus Wache über diese hielt und das Kernland der Horde bewachte. Während ihres Auftrags wurde sie an ihrem Aussichtspunkt an der Küste überfallen. Der schwere Schaden am Lagerplatz weist darauf hin, dass sie ihren Angreifern einen heftigen Kampf lieferte, was dringende Nachforschungen seitens der Führung der Siedlung in Klingenhügel auslöst.",al={"heglan shadeeye","wer ist heglan","heglan shadeeye lore"}},{q="Wer griff Heglan Shadeeye an?",a="Heglan Shadeeye wurde von Naga überfallen, die sich entlang der Küstenlinie von Durotar nach Süden bewegten. Physische Beweise, die am Ort des Scharmützels sichergestellt wurden – insbesondere ein markantes Banner und das Bruchstück einer Klinge –, bestätigen, dass die Schlangenwesen den Überfall verübten. Die Heftigkeit des Zusammentreffens hinterließ auch die Angreifer verwundet.",al={"wer überfiel heglan","heglans angreifer","was griff heglan shadeeye an"}},{q="Wer ist Orgnil Narbenseele?",a="Orgnil Narbenseele ist eine prominente Orc-Autorität, die in Klingenhügel im zentralen Durotar stationiert ist. Betraut mit der Organisation der Verteidigung der Region und der Koordination der Späher der Horde, überwacht Orgnil Berichte über feindliche Einfälle. Wenn die Meldung von Heglan Shadeeye ausbleibt, verlässt sich Orgnil auf zurückkehrende Späher und Abenteurer, um die Angreifer zu identifizieren und die Siedlung zu schützen.",al={"wer ist orgnil","orgnil narbenseele","orgnil in klingenhügel"}},{q="Warum stellen die Naga eine Gefahr für Klingenhügel dar?",a="Klingenhügel steht bereits unter starkem militärischem Druck durch menschliche Soldaten aus Kul Tiras, die sich im Süden verschanzt haben, sowie durch feindselige Quilboar im Westen. Sollten die Naga einen dauerhaften Brückenkopf an der östlichen Küste im Norden errichten, droht der Vorposten der Horde in eine unausweichliche Zangenbewegung zu geraten, was seine begrenzten Garnisonskräfte überfordern und Verstärkungswege durch Durotar abschneiden würde.",al={"warum naga hier gefährlich sind","naga-bedrohung klingenhügel","klingenhügel naga-gefahr"}},{q="Woher stammten die angreifenden Naga?",a="Die geborgenen militärischen Überreste deuten darauf hin, dass die Naga entlang der Küste aus nördlichen Gewässern nach Süden zogen, wahrscheinlich mit Ursprung in Azshara oder dem Schelf des Großen Meeres. Indem sie die Wasserwege nutzten, um Patrouillen im Landesinneren zu umgehen, schlugen die aquatischen Invasoren rasch gegen isolierte Küstenbeobachtungsposten zu, noch bevor die Verteidiger von Durotar eine geordnete Verteidigungslinie aufstellen konnten.",al={"woher kamen naga","naga-ursprung durotar","wie kamen naga nach durotar"}}},fp="17,381,27.563.0,18.564.1,26.391.0,23.367.0,29.310.0,23.374.0,40.379.0,39.355.0"}
P.entries["quest:99050"] = {n="The Great Tree Provides",s="The Great Tree Provides ist eine Quest in Dolanaar, bei der Byancie Hilfe anfordert, um ein gefährliches Leiden aufzuhalten, das Eralya bedroht. Indem sie taufrische Peitscherwedel von den Seen Teldrassils ernten und grundlegende Vorräte sammeln, helfen Spieler bei der Zubereitung einer dringenden heilsamen Salbe.",h="The Great Tree Provides ist eine Quest in Dolanaar, bei der Byancie Hilfe anfordert, um ein gefährliches...",kw={"leiden","byancie","taufrische peitscherwedel","dolanaar","eralya","heilsalbe","al'amethsee","teldrassil","the great tree provides","quellsee"},ang={["class:Druid"]="Druiden schätzen die natürlichen regenerativen Eigenschaften der Flora Teldrassils und verlassen sich eher auf einheimische Pflanzen wie Peitscherwedel als auf künstliche Gebräue.",["profession:Herbalism"]="Das Sammeln einheimischer Pflanzenmaterialien wie taufrischer Peitscherwedel zur Zubereitung wirksamer Heilsalben ist für geübte Kräuterkundige eine Selbstverständlichkeit.",["race:NightElf"]="Die pflanzlichen Heilmittel von Teldrassil spiegeln den Glauben der Kaldorei wider, dass ihr Weltenbaum sie erhält und beschützt und ihnen lebendige Medizin gegen plötzliche Leiden bietet."},sec={{t="Ein Wettlauf gegen die Zeit",b="Im bewaldeten Dorf Dolanaar kümmert sich Byancie um das Wohlergehen der örtlichen Nachtelfen. Als die Nachricht eintrifft, dass Eralya in der Wildnis von Teldrassil einem gefährlichen Leiden zum Opfer gefallen ist, macht Byancie sich unverzüglich an die Arbeit, eine Notfallbehandlung vorzubereiten. Ohne eine schnell wirkende Salbe, die das Fortschreiten des Gebrechens stoppt, wird Eralya die Reise zurück ins Dorf für eine angemessene Versorgung nicht überleben."},{t="Der gütige Weltenbaum",b="Selbst in Zeiten der Krise setzen die Kaldorei ihr Vertrauen in The Bounty of Teldrassil. Byancie wendet sich auf der Suche nach einem Heilmittel an den lebendigen Weltenbaum und sucht nach taufrischen Peitscherwedeln, von denen bekannt ist, dass sie nahe dem Al'Amethsee im Süden und dem Quellsee im Nordwesten gedeihen. Vermischt mit sauberem Quellwasser in einer einfachen Glasphiole bieten diese wirksamen Blätter die lebenswichtige Medizin, die benötigt wird, um das Leiden in Schach zu halten."}},faq={{q="Was ist The Great Tree Provides?",a="The Great Tree Provides ist eine dringende Aufgabe in Dolanaar von Byancie, die eine heilsame Salbe herstellen möchte, um ein Eralya bedrohendes Leiden aufzuhalten, bis eine weitere Behandlung möglich ist.",al={"was ist the great tree provides","quest the great tree provides","byancie quest"}},{q="Wer ist Byancie?",a="Byancie ist eine Heilerin oder Apothekerin der Nachtelfen, die im Dorf Dolanaar auf Teldrassil lebt und sich der Pflege der Kranken sowie der Zubereitung natürlicher Heilmittel aus der örtlichen Flora widmet.",al={"wer ist byancie","byancie dolanaar","questgeber byancie"}},{q="Wer ist Eralya und was ist mit ihr geschehen?",a="Eralya ist eine betroffene Person außerhalb von Dolanaar, deren Zustand sich rasch verschlechtert. Byancie benötigt eine Notfallsalbe, um sie lange genug zu stabilisieren, damit sie für eine vollständige Behandlung sicher in den Ort gebracht werden kann.",al={"wer ist eralya","was ist mit eralya geschehen","eralya leere leiden"}},{q="Wo findet man taufrische Peitscherwedel?",a="Taufrische Peitscherwedel wachsen an Pflanzenpeitschern rund um den Al'Amethsee direkt südlich von Dolanaar sowie entlang des Quellsees und seines Flusses im Nordwesten.",al={"wo man taufrische peitscherwedel findet","fundort taufrische peitscherwedel","peitscherwedel teldrassil"}},{q="Welche Zutaten werden benötigt, um die Salbe zuzubereiten?",a="Byancie benötigt sechs taufrische Peitscherwedel, die von einheimischen Peitschern geerntet wurden, eine leere Phiole und Erfrischendes Quellwasser, um die Notfallheilsalbe anzumischen.",al={"welche zutaten braucht byancie","salbenzutaten dolanaar","gegenstände the great tree provides"}},{q="Wo könnt Ihr eine leere Phiole und Erfrischendes Quellwasser erhalten?",a="Sowohl leere Phiolen als auch Erfrischendes Quellwasser können direkt bei Gemischtwarenhändlern oder Handwerkswarenhändlern in der Siedlung Dolanaar gekauft werden.",al={"woher bekommt man phiole und quellwasser","leere phiole dolanaar","erfrischendes quellwasser dolanaar"}}},fp="23,260,19.409.0,24.393.0,32.190.0,15.180.0,39.214.0,35.159.0,51.149.0,63.150.0"}
P.entries["quest:99051"] = {n="Threat from Below",s="Threat from Below ist eine defensive Mission, um aggressive Naga-Späher zu beseitigen, die in der Nähe ihr Lager aufschlagen. Indem sie die Streitkräfte der Späher angreifen und deren Stachelflossen erbeuten, wollen Abenteurer die schlangenartigen Invasoren zurück nach Norden treiben und das Gebiet sichern.",h="Threat from Below ist eine defensive Mission, um aggressive Naga-Späher zu beseitigen, die in der Nähe ihr...",kw={"grunzer","naga","naga-stachelflossen","späher","schlangenabschaum","stachelflossen","threat from below"},ang={["faction:Horde"]="Der Questgeber mobilisiert Grunzer der Horde, um nach Nachzüglern Ausschau zu halten, was dies zu einer proaktiven Verteidigung von Horde-kontrolliertem Territorium gegen vordringende Naga-Späher macht."},sec={{t="Schlangenartiger Übergriff",b="Threat from Below befasst sich mit einer zunehmenden Grenzstörung, die durch vordringende Naga-Späher verursacht wird. Die schlangenartigen Angreifer haben begonnen, in der Nähe Vorpostenlager zu errichten, was die örtlichen Verteidiger dazu veranlasst, zuzuschlagen, bevor die Eindringlinge einen dauerhaften Stützpunkt sichern können. Abenteurer werden ausgesandt, um die Späherkräfte zu dezimieren und mit Naga-Stachelflossen als Beweis für die Zerschlagung des Lagers zurückzukehren."},{t="Sicherung der Grenzen",b="Dies ist nicht das erste Mal, dass das Schlangenvolk die Gegend heimsucht, und das örtliche Kommando stellt unmissverständlich klar, dass ihre Anwesenheit nicht geduldet wird. Nach dem Schlag gegen ihre Späherlager besteht das Ziel darin, alle überlebenden Naga zurück nach Norden zu treiben, während wachsame Grunzer der Horde postiert bleiben, um vor Nachzüglern oder plötzlichen Hinterhalten zu schützen."}},faq={{q="Was ist Threat from Below?",a="Threat from Below ist eine Quest der Horde, die Abenteurer damit beauftragt, Naga-Späher zu eliminieren, die begonnen haben, in der Nähe Lager zu errichten. Um sicherzustellen, dass die Einfälle gestoppt werden, müssen die Spieler das vordringende Schlangenvolk erschlagen und Naga-Stachelflossen als Beweis für die Tat sammeln.",al={"was ist threat from below","quest threat from below"}},{q="Wer sind die in den Befehlen erwähnten Schlangen?",a="Die „Schlangen“ oder der „Schlangenabschaum“ beziehen sich auf die Naga, amphibische schlangenartige Humanoide, die aus den Küsten- oder Wassertiefen aufgetaucht sind, um lokale Stellungen auszukundschaften.",al={"wer sind die schlangen","schlangen in threat from below"}},{q="Warum müssen die Naga-Späher eliminiert werden?",a="Die Lager deuten eher auf eine organisierte Aufklärungsaktion als auf umherwandernde Kreaturen hin. Der örtliche Kommandant verlangt schnelle Vergeltung, um die Invasoren in die Flucht zu schlagen, bevor sie einen größeren Angriff starten oder sich weiter verschanzen können.",al={"warum naga-späher töten","naga-motiv"}},{q="Warum werden Naga-Stachelflossen gesammelt?",a="Abgetrennte Stachelflossen dienen als unbestreitbarer physischer Beweis dafür, dass die Späherlager entdeckt und zerstört wurden, und bestätigen, dass der unmittelbare Druck entlang der Grenze gebrochen wurde.",al={"warum stachelflossen","naga-beweis"}},{q="Wohin sollen sich die Naga voraussichtlich zurückziehen?",a="Bei der Abgabe der Flossen äußert der Kommandant die Hoffnung, dass der Schlag die Naga zurück nach Norden in die Flucht schlagen wird, und teilt Grunzer ein, um nach Nachzüglern oder verdächtigen Bewegungen Ausschau zu halten.",al={"wohin gehen die naga","naga norden"}},{q="Wer hält Wache, nachdem die Späher getötet wurden?",a="Grunzer der Horde werden angewiesen, das Gebiet zu bewachen, um sicherzustellen, dass keine Nachzügler zurückbleiben und die Naga keine weiteren Vorstöße versuchen.",al={"wer hält nach naga ausschau","grunzer naga-wache"}}},fp="17,245,20.379.0,20.334.0,26.262.0,43.157.0,39.231.0,33.178.0,39.179.0,43.143.0"}
P.entries["quest:99052"] = {n="Threat from Below",s="Threat from Below ist ein Kopfgeld der Horde, das Abenteurer damit beauftragt, einen gefährlichen Meerriesen zu jagen, der an Durotars Nordküste lauert. Die Überwindung eines solch gewaltigen Küstentitanen schützt die nahen Gestade und verdient den Respekt der Krieger von Durotar.",h="Threat from Below ist ein Kopfgeld der Horde, das Abenteurer damit beauftragt, einen gefährlichen Meerriesen...",kw={"blut und donner","kuestenmonster","durotar","horde quest","die nordküste","meerriese","threat from below"},ang={["class:Warrior"]="Einem massigen Meerriesen im direkten Kampf gegenüberzutreten, ist eine harte Prüfung kriegerischer Ausdauer und beweist das eigene Können gegen einen der schwersten Grobiane der Küste.",["faction:Horde"]="Einen Meerriesen entlang der Küstenlinie von Durotar zur Strecke zu bringen, beseitigt einen gefährlichen Koloss, der direkt vor den Toren des Kernlandes der Horde lauert.",["race:Orc"]="Die Ehre der Orcs schätzt es, titanischen Widersachern die Stirn zu bieten und dem Schlachtruf „Blut und Donner“ gegen überwältigende physische Macht zu folgen."},sec={{t="Die nördliche Küstenlinie",b="Entlang der nördlichen Küstenlinie von Durotar branden die Wasser des Großen Meeres an zerklüfteten Sand und felsige Küsten. Während sie gewöhnlich von einfachen Aasfressern und Krabben heimgesucht wird, birgt die Nordküste eine weitaus tödlichere Bedrohung: einen massigen Meerriesen, der durch die Untiefen streift und jeden bedroht, der versucht, die Gewässer an den Grenzen der trockenen neuen Heimat der Horde zu bereisen oder zu sichern."},{t="Ein Titan der Wellen",b="Meerriesen sind hoch aufragende Unholde, die in der Lage sind, Langboote zu zerschmettern und Krieger unter gewaltigen Fäusten zu zermalmen. Einen von ihnen zu erschlagen ist keine gewöhnliche Tat für junge Abenteurer, und das Bezwingen dieses Ungetüms der Wellen bringt tiefen Respekt unter den Orcs ein, gefeiert mit dem traditionellen Kriegsschrei „Blut und Donner“, der über die trockenen roten Klippen widerhallt."}},faq={{q="Was ist die Quest Threat from Below?",a="Threat from Below ist eine Aufgabe für Champions der Horde, einen kolossalen Meerriesen aufzuspüren und zu besiegen, der an Durotars Nordküste lauert, und mit einem Beweis für die Tat zurückzukehren.",al={"was ist threat from below","threat from below quest","meerriese quest durotar"}},{q="Wo ist der Meerriese zu finden?",a="Man trifft den Meerriesen dabei an, wie er durch die Gewässer und Küsten entlang der Nordküste von Durotar streift.",al={"wo ist der meerriese","durotar meerriese aufenthaltsort","threat from below aufenthaltsort"}},{q="Was für eine Kreatur ist ein Meerriese?",a="Meerriesen sind gewaltige, uralte Küstenungetüme, die erschaffen wurden, um die Ozeane auszubaggern und die Küstenlinien von Azeroth zu formen. Nur wenige Wanderer überleben eine direkte Konfrontation mit einem von ihnen.",al={"was ist ein meerriese","meerriesen lore","wer sind meerriesen"}},{q="Warum muss der Meerriese beseitigt werden?",a="Eine Kreatur von solch enormer Größe, die so nahe an Durotar lauert, stellt eine schwere Gefahr für Küstenreisende, Fischer und Lager der Horde entlang der Küste dar.",al={"warum meerriese toeten","ist der meerriese gefaehrlich","bedrohung fuer durotar"}},{q="Was meint der Questgeber mit „Blut und Donner“?",a="„Blut und Donner“ ist ein traditioneller Schlachtruf der Orcs, der kriegerische Stärke, Wildheit und Ruhm beim Sieg über gefährliche Widersacher ehrt.",al={"blut und donner bedeutung","orc-gruss blut und donner"}},{q="Welcher Beweis ist erforderlich, um die Aufgabe abzuschließen?",a="Die Quest erfordert es, einen greifbaren physischen Beweis für den Fall des Meerriesen von der Nordküste zurückzubringen, um zu bestätigen, dass die gewaltige Bestie erschlagen wurde.",al={"threat from below beweis","beweis fuer die tat"}}},fp="17,246,22.365.0,20.340.0,36.172.0,29.92.0,37.170.0,45.156.0,54.152.0,44.150.0"}
P.entries["quest:99053"] = {n="Escaping Ban'ethil",s="Escaping Ban'ethil ist eine Rettungsmission im unterirdischen Grabhügel auf Teldrassil. Schildwache Lynessa Duskblossom, die von aggressiven Gnarlpine-Furbolgs gefangen genommen wurde, während sie schlummernden Druiden eine Nachricht überbrachte, muss sicher zurück an die Oberfläche eskortiert und in Dolanaar als wohlbehalten gemeldet werden.",h="Escaping Ban'ethil ist eine Rettungsmission im unterirdischen Grabhügel auf Teldrassil.",kw={"grabhügel von ban'ethil","dolanaar","escaping ban'ethil","furbolg","gnarlpine","kaldorei","kyra starsong","lynessa duskblossom","orakelbaum","teldrassil"},ang={["class:Druid"]="Der Grabhügel von Ban'ethil ist als Refugium für schlummernde Druiden gedacht, die mit dem Smaragdgrünen Traum Zwiesprache halten, was seinen Fall an wilde Furbolgs zu einer dringenden Krise für die cenarischen Beschützer macht.",["faction:Alliance"]="Der Schutz von Darnassus und Teldrassil erfordert es, den Schildwachen gegen die wachsende Feindseligkeit der verderbten einheimischen Tierwelt und Stämme beizustehen.",["race:NightElf"]="Schildwache Lynessa Duskblossom ist eine Waffenbrüderin, deren Gefangenschaft unter den Wurzeln dem heiligen Band der Nachtelfen mit den offenen Sternen und dem Blätterdach von Teldrassil zuwiderläuft."},sec={{t="Hinterhalt unter den Wurzeln",b="Schildwache Lynessa Duskblossom wurde vom Orakelbaum mit einem dringenden Auftrag entsandt, um den im Grabhügel von Ban'ethil ruhenden Druiden eine Nachricht zu überbringen. Was als routinemäßiger Botendienst gedacht war, nahm eine verhängnisvolle Wendung, als sie feststellte, dass die unterirdischen Kammern vollständig von aggressiven Gnarlpine-Furbolgs überrannt worden waren. Abgeschnitten und in einen Hinterhalt geraten, bevor sie sich zurückziehen konnte, wurde sie in den dunklen Tunneln gefangen genommen und fürchtete ein grausames Ende durch die Hand des Stammes, bis ein Abenteurer eingriff, um sich den Weg mit ihr an die Oberfläche zu erkämpfen."},{t="Sichere Rückkehr nach Dolanaar",b="Für die Schildwachen der Kaldorei ist die unterirdische Düsternis eines Grabhügels ein unnatürlicher und verabscheuungswürdiger Ort der Gefangenschaft, weit entfernt vom beruhigenden Sternenlicht von Elune und der frischen Luft von Teldrassil. Nach ihrer Rettung aus den Tiefen flieht Lynessa zurück in Richtung Zivilisation, während die Nachricht von ihrem Überleben nach Dolanaar gebracht wird. Dort nimmt Schildwache Kyra Starsong die Kunde vom Überleben ihrer Freundin mit tiefer Erleichterung auf und belohnt diejenigen, die ihrer Kameradin bei der Verteidigung des Volkes der Kaldorei beigestanden haben."}},faq={{q="Wer ist Schildwache Lynessa Duskblossom?",a="Schildwache Lynessa Duskblossom ist eine Nachtelfenschildwache, die auf Teldrassil stationiert ist. Sie wurde vom Orakelbaum entsandt, um den im Grabhügel von Ban'ethil ruhenden Druiden eine wichtige Nachricht zu überbringen, wurde jedoch tief unter der Erde von Gnarlpine-Furbolgs überfallen und gefangen genommen.",al={"wer ist lynessa duskblossom","lynessa duskblossom","wer ist im grabhügel gefangen"}},{q="Warum betrat Schildwache Lynessa den Grabhügel von Ban'ethil?",a="Sie wurde vom Orakelbaum auf eine offizielle Mission geschickt, um den im Grabhügel von Ban'ethil schlummernden Druiden eine Botschaft zu überbringen. Als sie den unterirdischen Bau erreichte, stellte sie fest, dass er feindseligen Furbolgs anheimgefallen war, bevor sie ihre Nachricht überbringen konnte.",al={"warum ging lynessa nach banethil","was war lynessas mission","botschaft des orakelbaums"}},{q="Wer nahm Schildwache Lynessa gefangen?",a="Sie wurde von den Gnarlpine-Furbolgs gefangen genommen, die den Grabhügel bewohnen. Feindselig und aggressiv überfiel der Stamm sie, bevor sie fliehen konnte, und zerrte sie in die Tiefen, sodass sie fürchtete, ihre nächste Mahlzeit zu werden.",al={"wer nahm lynessa gefangen","welche furbolgs sind in banethil","gnarlpine-furbolgs"}},{q="Was ist der Grabhügel von Ban'ethil?",a="{\"p0\": \"Der Grabhügel von Ban'ethil ist ein unterirdisches Heiligtum auf Teldrassil, westlich von Dolanaar. Traditionell unter der Erde als Ruhestätte für Nachtelfendruiden gehauen, die in tiefe Zwiesprache eintreten, wurde er von verderbten Gnarlpine-Furbolgs überrannt.\"}",al={"wo ist der grabhügel von ban'ethil","was ist der grabhügel von ban'ethil","grabhügel teldrassil"}},{q="Wer ist Schildwache Kyra Starsong?",a="Schildwache Kyra Starsong ist eine Nachtelfenschildwache, die im Dorf Dolanaar stationiert ist. Sie ist eine enge persönliche Freundin von Lynessa Duskblossom und wartet sehnsüchtig auf die Nachricht von Lynessas Entkommen und ihrer Rückkehr in Sicherheit.",al={"wer ist kyra starsong","wo gebe ich escaping ban'ethil ab","schildwache aus dolanaar"}},{q="Warum verabscheut Lynessa es, unter der Erde zu sein?",a="Während Druiden Grabhügel für den heiligen Schlummer nutzen, missfällt es vielen Schildwachen und Kriegern der Nachtelfen zutiefst, unter der Erde gefangen zu sein. Die Kultur der Kaldorei schätzt den offenen Nachthimmel, das Sternenlicht von Elune und die schützenden Äste des Blätterdachs des Waldes weit mehr als unterirdische Tunnel.",al={"warum mögen nachtelfen keine grabhügel","unter der erde ist kein ort für kaldorei"}}},fp="18,283,26.512.0,23.504.0,36.266.0,52.249.0,30.236.0,29.245.0,30.201.0,42.281.0"}
P.entries["quest:99073"] = {n="Easing Suffering",s="Easing Suffering ist eine Quest in Teldrassil, bei der es darum geht, Schildwache Eralya Leafshadow Nothilfe zu leisten, die an der Straße nach The Oracle Tree von einer bösartigen Fäulnis befallen daniederliegt. Spieler eilen mit Peitscherwassersalbe an ihre Seite, um ihre Qualen zu lindern und ihrem schwindenden Atem Frieden zu bringen.",h="Easing Suffering ist eine Quest in Teldrassil, bei der es darum geht, Schildwache Eralya Leafshadow Nothilfe...",kw={"easing suffering","eralya leafshadow","peitscherwassersalbe","the oracle tree","fäulnis","schildwache eralya","teldrassil"},ang={["faction:Alliance"]="Gefallenen Nachtelfen-Schildwachen entlang der Straßen der Heimat von Darnassus beizustehen, hilft dabei, die zerbrechliche Frontlinie gegen das wachsende Verderben in den Ästen von Teldrassil aufrechtzuerhalten.",["race:NightElf"]="Schildwache Eralya Leafshadow ist eine der Euren, heimgesucht von einem bösartigen Verderben in der Wildnis von Teldrassil nahe The Oracle Tree. Ihr Trost zu spenden, ehrt die Pflicht, welche die Schildwachen gegenüber ihren Artverwandten tragen."},sec={{t="Ein Wettlauf gegen die Fäulnis",b="Schildwache Eralya Leafshadow liegt an der Straße nach The Oracle Tree darnieder, geschlagen von einer sich rasch ausbreitenden, schwärenden Fäulnis. Um ihren qualvollen Verfall aufzuhalten, muss ihr unverzüglich eine frisch zubereitete Peitscherwassersalbe gebracht werden, ehe das Leiden sie vollends übermannt."},{t="Frieden in den Schatten",b="Während jene, die sie behandeln, bezweifeln, dass die Peitscherwassersalbe die Kraft besitzt, die Seuche vollständig auszumerzen, bringt ihre Verabreichung rasche Beruhigung für Eralyas mühsamen, rasselnden Atem. Obwohl ihr Überleben ungewiss bleibt, gelingt es der Behandlung, ihr in ihrer dunkelsten Stunde Frieden zu schenken."}},faq={{q="Wer ist Schildwache Eralya Leafshadow?",a="Schildwache Eralya Leafshadow ist eine Nachtelfenbeschützerin, die leidend an der Straße nach The Oracle Tree gefunden wird. Niedergestreckt von einer aggressiven, schwärenden Fäulnis, ist sie handlungsunfähig und dem Tode nahe, als man sie entdeckt.",al={"wer ist eralya","eralya leafshadow","wer ist schildwache eralya"}},{q="Was ist Peitscherwassersalbe?",a="Peitscherwassersalbe ist ein zubereitetes Heilmittel, das verabreicht wird, um die heftigen Schmerzen zu lindern, die durch die bösartige Fäulnis verursacht werden, welche Schildwache Eralya heimsucht. Obwohl es ungewiss ist, ob sie den Zustand vollständig heilen kann, lindert sie ihre Qualen.",al={"was ist peitscherwassersalbe","peitscherwassersalbe","salbe heilt fäulnis"}},{q="Überlebt Schildwache Eralya das Leiden?",a="Die Salbe erleichtert Schildwache Eralyas Atem und schenkt ihr relativen Frieden, doch es bleibt ungewiss, ob sie sich wahrhaftig erholen wird oder der Fäulnis erliegt, die von ihr Besitz ergriffen hat.",al={"überlebt eralya","ist eralya geheilt","starb eralya"}},{q="Wo ist Schildwache Eralya Leafshadow zu finden?",a="Schildwache Eralya Leafshadow liegt am Pfad, der nach The Oracle Tree führt, gelegen in den uralten Gefilden von Teldrassil.",al={"wo ist the oracle tree","straße nach the oracle tree","eralya aufenthaltsort"}},{q="Welches Leiden befiel Schildwache Eralya?",a="Eralya leidet an einer aggressiven und schwärenden Fäulnis, die sich rasch in ihrem Körper ausbreitet. Der genaue Ursprung des Verderbens ist unklar, doch sie greift schnell an und wird mit der Zeit immer bösartiger.",al={"was verursachte eralyas krankheit","was ist die fäulnis","eralya krankheit"}},{q="Warum ist Eile geboten, um die Salbe zu überbringen?",a="Die Fäulnis schwärt und erstarkt rasch, während sie sich durch Eralyas Körper ausbreitet. Schnelligkeit ist geboten, da jeder verstreichende Augenblick sie näher daran bringt, der Pein und dem Verderben vollends zu erliegen.",al={"warum eile salbe","warum eile eralya"}}},fp="16,278,22.266.0,20.296.1,34.208.0,24.209.0,44.175.0,46.129.0,39.191.0,43.194.0"}
P.entries["quest:99079"] = {n="Longwalker Malah",s="Longwalker Malah ist eine vermisste Taurenspäherin, die im Auftrag vom Dorf der Bluthufe entsandt wurde, um die östlichen Grenzlande von Mulgore zu überwachen. Da sie als Elite-Longwalker direkt dem Oberhäuptling untersteht, löst ihr plötzliches Ausbleiben nach drei Tagen eine dringende Suche aus, um sowohl ihr Überleben als auch die Sicherheit des Tals zu gewährleisten.",h="Longwalker Malah ist eine vermisste Taurenspäherin, die im Auftrag vom Dorf der Bluthufe entsandt wurde, um...",kw={"baine bluthuf","dorf der bluthufe","gefiederter stab","longwalker malah","longwalkers","malah longwind","mulgore","taurenspäher"},ang={["class:Hunter"]="Jäger schätzen das Geschick beim Fährtenlesen in der Wildnis und die Ausdauer, die von den Longwalkers verlangt werden, welche die entlegenen Ränder von Mulgore zu Fuß durchstreifen.",["faction:Horde"]="Der Führung vom Dorf der Bluthufe beim Auffinden vermisster Grenzspäher zu helfen, trägt dazu bei, Mulgore vor äußeren Bedrohungen zu schützen, die auf das Land der Horde vordringen.",["race:Tauren"]="Die Longwalkers sind verehrte Späher, die direkt Oberhäuptling Cairne Bluthuf unterstehen, weshalb ihre Sicherheit für alle Tauren von größter kultureller und taktischer Bedeutung ist."},sec={{t="Die Augen des Oberhäuptlings",b="Die Longwalkers dienen als Augen und Ohren der Shu'halo und sind in den gesamten Ebenen für ihren unermüdlichen Schritt und ihre Überlebenskunst berühmt. Diese direkt Oberhäuptling Cairne Bluthuf verpflichteten Elitespäher haben die Aufgabe, weite Gebiete zu durchstreifen, um Informationen zu sammeln und wichtige Botschaften zu überbringen. Obwohl ihre oberste Loyalität allein dem Oberhäuptling gilt, nimmt der junge Baine Bluthuf gelegentlich ihre Hilfe in Anspruch, um die Siedlung vom Dorf der Bluthufe und die umliegenden Weiden zu schützen."},{t="In den Grenzlanden verschollen",b="Entsandt, um Mulgores östliche Grenzen zu überwachen, brach Longwalker Malah Longwind zu einem routinemäßigen, dreitägigen Erkundungslauf auf. Als sie nicht wie geplant ins Dorf der Bluthufe zurückkehrte, verbreitete sich Sorge unter der Führung des Dorfes. Angesichts der wichtigen Informationen, die Longwalkers bei sich tragen, und der allgegenwärtigen Gefahren, die an den Klippen der Grenzen Mulgores lauern, sind Späher und hilfsbereite Reisende aufgerufen, ihre Spur zu suchen und ihre Sicherheit zu bestätigen. Malah ist an den traditionellen Zeichen ihres Ordens zu erkennen: einem zeremoniellen Stirnband und einem gefiederten Stab."}},faq={{q="Wer ist Longwalker Malah?",a="Longwalker Malah Longwind ist eine angesehene Taurenspäherin im Dienst des Oberhäuptlings. Sie wurde auf eine Erkundungsmission nahe der östlichen Grenze von Mulgore entsandt und trägt das traditionelle Stirnband sowie den gefiederten Stab, die sinnbildlich für ihren Orden stehen.",al={"wer ist malah","malah lore","longwalker malah identität"}},{q="Was sind die Longwalkers?",a="Die Longwalkers sind die vertrauenswürdigsten Elitespäher und Boten des Taurenvolkes. Ihre oberste Loyalität gilt direkt dem Oberhäuptling, auch wenn andere Stammesführer wie der junge Baine Bluthuf gelegentlich ihre Hilfe für entscheidende Grenzaufklärung erbitten.",al={"was sind longwalkers","wer sind longwalkers","taurenspäher"}},{q="Warum wird nach Longwalker Malah gesucht?",a="Malah wurde ausgesandt, um die östlichen Ränder von Mulgore zu überwachen, und wurde binnen drei Tagen zurückerwartet. Als sie nicht zurückkehrte, wuchsen im Dorf der Bluthufe die Sorgen, dass sie bei der Patrouille an der zerklüfteten Grenze auf Schwierigkeiten gestoßen sein könnte.",al={"warum wird malah vermisst","malah quest warum","wohin ging malah"}},{q="Wo ist Malah zu finden?",a="Longwalker Malah wurde zur östlichen Grenze von Mulgore entsandt, am Dorf der Bluthufe vorbei in Richtung des Grenzkamms. Reisende, die nach ihr suchen, müssen die Grenzlande östlich des Dorfes durchkämmen.",al={"wo ist malah","malah standort","malah finden"}},{q="Woran erkennt man Longwalker Malah?",a="Malah kann an den unverwechselbaren Gewändern der Longwalkers erkannt werden: einem charakteristischen Stirnband und einem langen, gefiederten Stab, der von den Spähern ihres angesehenen Ordens getragen wird.",al={"malah aussehen","wie malah erkennen","longwalker ausrüstung"}},{q="Warum hat Baine Bluthuf mit den Longwalkers zu tun?",a="Obwohl die Longwalkers ausschließlich Oberhäuptling Cairne Bluthuf unterstehen, wacht sein Sohn Baine über die lokalen Belange im Dorf der Bluthufe und bittet gelegentlich um ihr Fährtenlesergeschick, um Grenzaktivitäten zu überwachen und die Sicherheit des Tals zu gewährleisten.",al={"baine rolle","warum baine beteiligt","baine bluthuf späher"}}},fp="16,324,25.502.0,27.554.0,24.243.0,25.268.0,43.230.0,25.192.0,38.160.0,53.249.0"}
P.entries["quest:991"] = {n="Raenes Säuberung",s="Raenes Säuberung beginnt, als Raene Wolfsläufer einen Abenteurer bittet, ihren vermissten Freund Teronis aufzuspüren. In dem Bestreben, die grassierende Aggression der Furbolgs in ganz Eschental aufzuhalten, machte sich Teronis auf den Weg zum Falathimsee, um einen magischen Edelstein zu bergen.",h="Raenes Säuberung beginnt, als Raene Wolfsläufer einen Abenteurer bittet, ihren vermissten Freund Teronis...",kw={"eschental","falathim","furbolg","edelstein","murloc","raene","teronis","wolfrunner"},ang={["faction:Alliance"]="Rekruten der Allianz, die in Astranaar eintreffen, lernen schnell, dass die heiligen Haine von Eschental von feindseligen Wildtieren, Furbolgs und eindringenden Murlocs belagert werden.",["race:NightElf"]="Das Verschwinden von Teronis ist ein weiterer bitterer Schlag für die Nachtelfen, die bereits bis an die Grenzen ihrer Kräfte beansprucht sind, um Eschental zu heilen und ihre Schreine vor der Verderbnis zu schützen."},sec={{t="Die Sorge eines Freundes",b="Raene Wolfsläufer dient zusammen mit den Sentinels in Astranaar und verteidigt Eschental gegen die zunehmenden Bedrohungen. Zu ihren engsten Gefährten zählte Teronis, der es auf sich nahm, eine wirksame Verteidigung gegen die immer gewalttätigeren Furbolgstämme zu finden. Als Tage vergingen, ohne dass er zurückkehrte, war Raene zutiefst besorgt, konnte aber ihren Posten nicht verlassen, während sie das Schlimmste befürchtete."},{t="Die Suche nach dem Stab",b="Teronis ging Gerüchten über einen mächtigen Stab nach, der von einem verstorbenen, bösen Zauberer geschmiedet worden war, in dem Glauben, seine Magie könne die Furbolgwut bändigen. Um das Artefakt wiederherzustellen, benötigte er einen verzauberten Edelstein, der in einem Elvenschrein am Falathimsee verborgen war, der sich in der Nähe der Berge im Westen befindet. Unglücklicherweise waren die ruhigen Gewässer vor Kurzem von aggressiven Murlocstämmen eingenommen worden."},{t="Tragödie am Falathimsee",b="Wenn man der Spur von Teronis zur Insel im Falathimsee folgt, bietet sich ein düsterer Anblick. Teronis hat das Wasser nicht lebend verlassen; sein Leichnam liegt erschlagen auf dem Schrein, übersät mit tiefen Wunden von Murlocwaffen und Krallen, was ein jähes Ende seiner Suche markiert."}},faq={{q="Wer ist Raene Wolfsläufer?",a="Raene Wolfsläufer ist eine Nachtelfe, die mit den Sentinels von Eschental verbündet ist und in Astranaar stationiert ist. Sie beaufsichtigt verschiedene Verteidigungsmaßnahmen, um den Wald vor eindringenden Feinden zu schützen.",al={"raene","wer ist raene","questgeber"}},{q="Wer war Teronis?",a="Teronis war ein enger Freund von Raene Wolfsläufer, der nach alten magischen Lösungen suchte, um den Wald zu retten. In der Überzeugung, dass ein verzauberter Stab die korrumpierten Furbolgs beruhigen könnte, reiste er allein, um die Komponenten dafür zu sichern.",al={"wer ist teronis","teronis hintergrund","vermisster freund"}},{q="Wo wird Teronis vermisst?",a="Teronis verschwand am Falathimsee, einem Gewässer am Fuße der westlichen Berge in Eschental, das von feindseligen Murlocs überrannt worden war.",al={"wo ist teronis","standort von teronis","falathimsee"}},{q="Warum suchte Teronis nach einem Edelstein?",a="Der Edelstein war eine lebenswichtige Komponente, die benötigt wurde, um einen magischen Stab zu verstärken, der von einem verstorbenen bösen Zauberer gefertigt wurde. Teronis hoffte, die Kraft des Stabes nutzen zu können, um die Angriffe der wütenden Furbolgs einzudämmen.",al={"welcher edelstein","warum edelstein","teronis edelstein"}},{q="Was ist mit Teronis passiert?",a="Raene hat nichts mehr von ihm gehört, seit er zum Falathimsee aufgebrochen ist. Wenn man seiner Spur folgt, offenbart sich sein Schicksal.",al={"wie starb teronis","mörder von teronis","wer tötete teronis"}},{q="Warum greifen die Furbolgs Eschental an?",a="Die Furbolgs von Eschental sind nach dem Dritten Krieg dämonischer Verderbnis und Wahnsinn anheimgefallen, was die einst friedlichen Stämme in eine unerbittliche, gewaltsame Feindseligkeit gegen ihre alten Verbündeten getrieben hat.",al={"furbolgangriffe","warum furbolgs aggressiv","furbolgwahnsinn"}}},fx={["82e89856"]={q="Warum möchte Raene Wolfsläufer, dass Teronis gefunden wird?",a="Teronis ist ein alter und vertrauter Freund von Raene Wolfsläufer, der sich dazu bereit erklärte, die Schildwachen gegen die wütenden Furbolgs zu unterstützen. Er brach auf der Suche nach einem magischen Stab und einem Edelstein auf, die die Angriffe auf ihr Volk stoppen könnten, kehrte jedoch nie zurück. Raene ist zutiefst besorgt um seine Sicherheit und verzweifelt darauf bedacht, herauszufinden, welche Hilfe er für ihre bedrängten Ländereien gesichert haben könnte.",al={"warum raene teronis will","raene wolfsläufer motiv","warum nach teronis suchen"}}},fp="17,245,18.364.0,21.353.0,24.268.1,24.182.0,16.210.0,29.155.0,34.185.0,25.98.1,41.194.0"}
P.entries["quest:99108"] = {n="Sparring Match",s="Sparring Match ist eine einführende Prüfung unter der Aufsicht des Kampfausbilders Tang Stonehoof. Die Prüfung soll Neulinge ungeachtet ihrer Klasse oder Herkunft auf die Probe stellen und fordert Abenteurer heraus, drei Arenanovizen oder andere Duellanten zu besiegen, um ihren Mut im direkten Kampf zu beweisen.",h="Sparring Match ist eine einführende Prüfung unter der Aufsicht des Kampfausbilders Tang Stonehoof.",kw={"arena","kampftraining","duell","kriegernovize","sparring","sparring match","tang steinhuf"},ang={["class:Warrior"]="Auch wenn Tang Stonehoof jene, die keine Krieger sind, nicht in ihren spezifischen Disziplinen ausbilden kann, hebt sein Sparringring die Kriegerphilosophie hervor: dass Kampfgrundlagen, Mut und das Schärfen der eigenen kriegerischen Entschlossenheit jedem Abenteurer zugutekommen.",["race:Tauren"]="Tang Stonehoof verwendet traditionelle Redewendungen der Tauren wie „die Hörner schärfen“, um das Erproben des eigenen Mutes zu beschreiben, und heißt jeden gewillten Widersacher ungeachtet seiner Herkunft in der Sparringarena willkommen."},sec={{t="Der Sparringsplatz",b="Unter der Aufsicht des erfahrenen Ausbilders Tang Stonehoof lädt das Sparring Match Abenteurer jeglicher Herkunft in den Ring ein, um ihren Mut auf die Probe zu stellen. Obwohl Tang ausdrücklich jene anerkennt, die Pfade außerhalb der Kriegertradition beschreiten, vertritt er die Ansicht, dass kriegerische Disziplin und der direkte Kampf jedem Reisenden in einer gefährlichen Welt universelle Weisheit vermitteln."},{t="Die Hörner schärfen",b="In der Arena von Tang Stonehoof spielen Unterschiede bezüglich der Abstammung und bevorzugter Waffen keine Rolle. Ob mit Schwert, Bogen oder Zauberkunst – Herausforderer haben die Aufgabe, ihre Kampfbereitschaft zu beweisen, indem sie drei gewillte Kontrahenten besiegen, seien es die trainierenden Novice Warriors oder andere Abenteurer in Duellen. Das Bestehen dieser Kämpfe bringt Tangs Respekt und Verbände ein, um die Wunden eines ehrlichen Kampfes zu verbinden."}},faq={{q="Wer ist Tang Stonehoof?",a="Tang Stonehoof ist ein Kampfausbilder, der die örtliche Sparringarena beaufsichtigt. Selbst jenen, die andere Pfade als den eines Kriegers beschreiten, bietet Tang Kampfunterricht an und lädt vielversprechende Abenteurer dazu ein, ihren Mut im direkten Kampf gegen Novizen oder gewillte Gefährten auf die Probe zu stellen.",al={"wer ist tang steinhuf","tang steinhuf lore","questgeber"}},{q="Was verlangt Tang Stonehoof für das Sparring Match?",a="Die Prüfung verlangt den Sieg über drei Kontrahenten in der Arena – entweder über andere gewillte Abenteurer in Duellen oder über dort unter Tang Stonehoofs Anleitung stationierte Novice Warriors. Der Zweck besteht darin, Einsatzbereitschaft und kriegerisches Können im direkten Kampf unter Beweis zu stellen.",al={"ziel von sparring match","was tun bei sparring match","gegen wen kämpfen"}},{q="Warum bildet ein Kriegerausbilder andere Klassen aus?",a="Tang Stonehoof glaubt, dass jeder Abenteurer, egal ob er Schwert, Bogen oder Magie führt, davon profitiert, sich dem direkten Kampf zu stellen. In seiner Arena spielen Abstammung und spezifische Klassendisziplinen eine weit geringere Rolle als der Wille, sich selbst auf die Probe zu stellen und die kriegerische Entschlossenheit zu schärfen.",al={"können nicht-krieger das machen","warum sparring für andere klassen","kein krieger"}},{q="Wo findet das Sparring Match statt?",a="Der Wettkampf findet direkt vor Tang Stonehoof in der offenen Sparringarena statt, wo angehende Kämpfer trainieren und gewillte Herausforderer einander auf Augenhöhe gegenübertreten können.",al={"wo novizen bekämpfen","standort der arena","wo ist der ring"}},{q="Kann man sich mit anderen Spielern statt mit den Kriegernovizen duellieren?",a="Ja. Tang Stonehoof erkennt sowohl Siege über in der Arena trainierende Novice Warriors als auch über in formellen Duellen besiegte andere Abenteurer an; ihm ist nur wichtig, dass Ihr Eure Fähigkeiten gegen gewillte Widersacher auf die Probe stellt.",al={"kann ich gegen spieler kämpfen","spieler für quest duellieren","kriegernovizen oder spieler"}},{q="Was sagt Tang Stonehoof, wenn man das Match abschließt?",a="Sobald Ihr Euch gegen drei Widersacher bewiesen habt, würdigt Tang Euer Können mit Hoffnung für die neue Generation und bietet medizinische Vorräte an, um Eure Wunden in Vorbereitung auf den beschwerlichen Weg vor Euch zu versorgen.",al={"belohnung für sparring match","was gibt tang einem"}}},fp="14,280,20.350.0,20.393.0,22.269.0,56.247.0,50.262.0,41.171.0,58.204.0,57.198.0"}
P.entries["quest:99123"] = {n="Lost in the Shadows",s="'Lost in the Shadows' ist eine Quest, bei der es um die Rettung von Pal'juh geht, einer ungestümen Jägerin, die sich allein in Gefahr begab. Ihre Rettung verdeutlicht das feine Gleichgewicht zwischen roher Aggression und geduldigem Anschleichen, das von Fährtenlesern in der Wildnis verlangt wird.",h="'Lost in the Shadows' ist eine Quest, bei der es um die Rettung von Pal'juh geht, einer ungestümen Jägerin...",kw={"jäger","lost in the shadows","pal'juh","paljuh","raptor","tiger"},ang={["class:Hunter"]="Die Quest unterstreicht eine grundlegende Jägerdisziplin: Geduld und das Anschleichen wie ein Tiger, statt wie ein hungriger Raptor unbesonnen vorzustürmen.",["race:Troll"]="Pal'juhs Name und ihr Temperament spiegeln junge Jäger der Dunkelspeere wider, die begierig darauf sind, ihr Können in der Wildnis unter Beweis zu stellen, bevor sie Beherrschung erlernen."},sec={{t="Eine leichtsinnige Kundschafterin",b="'Lost in the Shadows' beinhaltet das Aufspüren und Retten von Pal'juh, einer talentierten, aber hitzköpfigen Jägerin, die sich allein in feindseliges Gebiet wagte. Da sie nicht auf Unterstützung warten wollte, übernahm sie sich völlig und benötigte Hilfe von außen, um ihre sichere Rückkehr zu gewährleisten."},{t="Geduld der Jagd",b="Nach Pal'juhs Rettung stellen ihre Aufseher fest, dass ihr Potenzial als Kundschafterin und Fährtenleserin zwar unbestreitbar ist, sie jedoch wie ein Raptor kopfüber vorprescht, anstatt sich mit der Geduld eines Tigers anzuschleichen. Das Überstehen dieser Tortur dient als deutliche Mahnung an die unbarmherzige Natur der Wildnis."}},faq={{q="Wer ist Pal'juh?",a="Pal'juh ist eine vielversprechende junge Jägerin, die dafür bekannt ist, sich auf eigene Faust in Gefahr zu begeben. Obwohl sie talentiert ist, hat sie den Ruf, unbesonnen zu handeln und von Bestien und der Wildnis in die Enge getrieben oder überwältigt zu werden.",al={"wer ist paljuh","paljuh lore","pal'juh"}},{q="Was geschieht während der Quest 'Lost in the Shadows'?",a="In 'Lost in the Shadows' zog Pal'juh allein los und geriet wieder einmal in Schwierigkeiten. Es bedurfte eines Abenteurers, um sie aufzuspüren und ihr beizustehen, bevor sie ernsthaften Schaden nahm.",al={"was geschah in lost in the shadows","lost in the shadows quest lore","lost in the shadows geschichte"}},{q="Warum sagt der Questgeber, dass Pal'juh eher wie ein Raptor als wie ein Tiger handelt?",a="Der Vergleich bezieht sich auf Jagdtechnik und Disziplin. Ein Raptor stürzt sich angriffslustig und ohne Vorsicht oder Bedacht nach vorn, wohingegen ein Tiger abwartet, sich geduldig anschleicht und mit Präzision und kalkulierter List zuschlägt.",al={"warum raptor tiger","raptor statt tiger bedeutung","jäger raptor tiger"}},{q="Wer nimmt den Bericht für Lost in the Shadows entgegen?",a="Die Quest endet bei einem Mentor oder Gefährten, der Pal'juh gut genug kennt, um ihren Leichtsinn vorherzusehen, und Erleichterung darüber äußert, dass jemand eingeschritten ist, um die eigensinnige Fährtenleserin zu retten.",al={"wer gibt lost in the shadows ab","lost in the shadows questgeber"}},{q="Lernt Pal'juh ihre Lektion aus diesem Missgeschick?",a="Pal'juh überstand die Tortur dank des Eingreifens von außen, wenngleich diejenigen, die sie beaufsichtigen, wachsam bleiben, ob sie die Gefahr des Alleingangs wirklich begreifen wird.",al={"hat paljuh ihre lektion gelernt","geht es paljuh gut"}},{q="Gilt Pal'juh als fähige Jägerin?",a="Sie gilt als vielversprechende Jägerin mit reichlich Naturtalent und Mut, doch ihre Mentoren mahnen, dass Instinkt allein bei der Verfolgung gefährlicher Beute keine taktische Geduld ersetzen kann.",al={"ist paljuh eine gute jägerin","paljuh fähigkeiten"}}},fp="19,237,16.263.0,20.278.0,15.204.0,52.175.0,74.211.0,48.179.0,53.179.0,39.182.0"}
P.entries["quest:99127"] = {n="A Net Disaster",s="A Net Disaster ist eine Quest im Wald von Elwynn, bei der sich alles um eine ungewöhnliche Störung am Kristallsee dreht. Da beim Angeln mit Haken und Schnur nichts anbeißt und selbst Elritzen aus den Untiefen verschwunden sind, werden Abenteurer ausgesandt, um über Nacht aufgestellte Reusen zu überprüfen. Die zerstörten Fallen offenbaren, dass feindselige Eindringlinge aus der Nachbarschaft das hiesige Angelgeschirr aktiv zerstören.",h="A Net Disaster ist eine Quest im Wald von Elwynn, bei der sich alles um eine ungewöhnliche Störung am...",kw={"a net disaster","kristallsee","wald von elwynn","fischbestand","fischfallen","lee","murlocs","plaegegeister"},ang={["faction:Alliance"]="Der Kristallsee liegt mitten im Wald von Elwynn, sodass lokale Störungen die Lebensgrundlagen und Vorräte, die das Herz des Allianzgebiets stützen, unmittelbar bedrohen."},sec={{t="Unruhige Gewässer am Kristallsee",b="Am Kristallsee im Wald von Elwynn sehen sich die einheimischen Fischer mit einer alarmierenden Flaute bei ihrem täglichen Fang konfrontiert. Leere Angelhaken kommen oft genug vor, doch wenn nicht einmal mehr Elritzen im seichten Wasser auftauchen, wird das alltägliche Fischen zu einem ernsten Mysterium. Um zu retten, was noch zu retten ist, werden über Nacht Fallen aufgestellt, in der Hoffnung, grundlegende Bestände einzuholen."},{t="Zerstörte Fallen und Plagegeister aus der Nachbarschaft",b="Das Einholen der unter Wasser liegenden Fallen offenbart, dass das Problem kein Pech ist, sondern regelrechte Sabotage und Zerstörung. Feindselige Plagegeister aus der Nachbarschaft an den Ufern des Sees haben die Reusen ruiniert und drohen, die örtlichen Fischer völlig um ihre Existenz zu bringen, wenn nichts unternommen wird."}},faq={{q="Was ist A Net Disaster?",a="A Net Disaster ist eine Quest, die am Kristallsee im Wald von Elwynn angesiedelt ist. Einheimische Fischer haben bemerkt, dass die Fische nicht mehr anbeißen und selbst die Elritzen verschwunden sind, was zu einer Untersuchung der über Nacht aufgestellten Fallen führt.",al={"was ist a net disaster","a net disaster quest","kristallsee a net disaster"}},{q="Wo untersucht Ihr die Fischfallen?",a="Die Fischfallen befinden sich unter Wasser im Kristallsee und wurden über Nacht von Lee ausgelegt, um den Fischbestand zu sichern, als das normale Fischen mit Haken und Schnur erfolglos blieb.",al={"wo sind die fallen","a net disaster ort","kristallsee fallen"}},{q="Wer ist Lee?",a="Lee ist ein einheimischer Fischer am Kristallsee, der über Nacht Fallen aufstellte, um den Fang zu sichern, als die Fische nicht mehr wie gewohnt an Haken und Schnur anbeißen wollten.",al={"wer ist lee","lee fischer"}},{q="Was ist mit den Fischen im Kristallsee geschehen?",a="Die Fische sind völlig von den Oberflächengewässern verschwunden, wobei nicht einmal eine einzige Elritze zu sehen ist. Eine Inspektion offenbart, dass die über Nacht aufgestellten Fallen von neuen Plagegeistern aus der Nachbarschaft zerstört wurden.",al={"was geschah mit den fischen im kristallsee","warum keine fische kristallsee","kristallsee leer"}},{q="Wer sind die am Ende erwähnten Plagegeister aus der Nachbarschaft?",a="Der Questgeber bezieht sich auf neue Plagegeister aus der Nachbarschaft, die sich am Kristallsee ausbreiten. In den Gewässern und an den Ufern des Kristallsees haben aggressive Murlocs Lager aufgeschlagen und Verwüstung unter der einheimischen Tierwelt und den Fischereigeräten angerichtet.",al={"wer sind die benachbarten plaegegeister","a net disaster plaegegeister","wer hat die fallen zerstoert"}},{q="Warum ist der Mangel an Fischen ein so großes Problem für die Fischer?",a="Der Questgeber ist für seinen Lebensunterhalt direkt auf die Fischbestände aus dem Kristallsee angewiesen. Angesichts beschädigter Fallen und leerer Fänge droht der finanzielle Ruin, wenn der Störung kein Einhalt geboten wird.",al={"warum ist das dem questgeber wichtig","kristallsee fischereigeschaeft"}}},fp="14,338,31.310.0,39.280.1,23.215.0,39.146.0,11.137.0,42.192.0,55.231.0,61.191.0"}
P.entries["quest:99128"] = {n="Slimy Menace",s="Slimy Menace befasst sich mit einer wachsenden Murloc-Plage an den Ufern des Kristallsees im Wald von Elwynn. Diese aggressiven Kreaturen drohen den Fischbestand des Sees zu dezimieren und gefährden die Anwohner in der Nähe, was ein rasches Eingreifen erfordert, um ihre Zahl in Schach zu halten.",h="Slimy Menace befasst sich mit einer wachsenden Murloc-Plage an den Ufern des Kristallsees im Wald von Elwynn.",kw={"kristallsee","wald von elwynn","fisch","goldhain","murloc","murlocs","slimy menace"},ang={["faction:Alliance"]="Die Sicherung der Ufer des Kristallsees schützt einheimische Fischer aus Elwynn und Reisende in der Nähe von Goldhain vor aggressiven Murloc-Überfällen.",["race:Human"]="Für die Bewohner des Walds von Elwynn bedroht das Vordringen der Murlocs unmittelbar ihre Wasserwege, ihre Nahrungsmittelversorgung und die Sicherheit der nahe gelegenen Siedlungen."},sec={{t="Ärger am Kristallsee",b="Entlang des Ostufers des Kristallsees hat sich eine aggressive Enklave von Murlocs festgesetzt. Diese wilden, halbaquatischen Kreaturen besitzen scharfe Zähne sowie ein grimmiges Gemüt und verwandeln ein einst friedliches Gewässer in ein gefährliches Jagdgebiet. Die Anwohner sind für ihren täglichen Lebensunterhalt stark auf den See angewiesen, doch die Anwesenheit der Murlocs bedroht nun jeden, der es wagt zu fischen oder sich dem Ufer zu nähern."},{t="Eine endlose Plage",b="Über die körperliche Gefahr hinaus, die sie für Reisende darstellen, drohen die Murlocs jeden Fisch im See zu verschlingen, wenn sie sich unkontrolliert vermehren dürfen. Das Ausdünnen ihrer Reihen verschafft den lokalen Gewässern eine dringend benötigte Atempause, auch wenn ihr unheimliches, hallendes Gurgeln eine finstere Mahnung ihrer Zähigkeit bleibt. Selbst wenn sie zerstreut werden, füllen Murlocs ihre Ränge rasch wieder auf, sodass eine wachsame Beobachtung des Ufers weiterhin eine ständige Notwendigkeit bleibt."}},faq={{q="Worum geht es in der Quest Slimy Menace?",a="Slimy Menace ist eine lokale Aufgabe, die sich mit der aggressiven Murloc-Population befasst, die an den fernen Ufern des Kristallsees haust. Bleiben diese amphibischen Kreaturen unkontrolliert, verschlingen sie die einheimischen Fische und bedrohen jeden, der versucht, in der Nähe zu arbeiten oder zu reisen.",al={"was ist slimy menace","slimy menace quest-infos","slimy menace zusammenfassung"}},{q="Wo finden die Ereignisse dieser Quest statt?",a="Die Unruhe ereignet sich am Kristallsee im Wald von Elwynn, wo sich eine Gruppe von Murlocs am gegenüberliegenden Ufer versammelt hat. Ihre Anwesenheit stört die natürliche Tierwelt des Sees und stellt eine Gefahr für die Anwohner dar.",al={"wo sind die murlocs kristallsee","kristallsee standort","wo geschieht das"}},{q="Warum müssen die Murlocs am Kristallsee dezimiert werden?",a="Die Murlocs dezimieren rasch den Fischbestand des Sees, während sie das Umland mit ihrem bösartigen Gemüt und ihren scharfen Zähnen terrorisieren. Das Ausdünnen ihrer Reihen hilft, die Fischerei des Sees zu schützen, und stoppt vorübergehend ihre aggressive Ausbreitung.",al={"warum kristallsee-murlocs töten","murlocs fressen fische","was ist das problem mit den murlocs"}},{q="Löst das Beseitigen der Murlocs das Problem dauerhaft?",a="Das Dezimieren der Murlocs verschafft nur einen vorübergehenden Aufschub. Wie beim Abschluss der Aufgabe bemerkt wird, pflanzen sich Murlocs mit alarmierender Geschwindigkeit fort und formieren sich neu, sodass sich ihre Bestände trotz anfänglicher Verluste rasch wieder erholen werden.",al={"sind murlocs für immer weg","haben wir die murlocs ausgelöscht","werden die kristallsee-murlocs zurückkehren"}},{q="Wer bittet um Hilfe bei der schleimigen Bedrohung?",a="Die Aufgabe wird von einem Einheimischen aus Elwynn vergeben, der über den Zustand des Kristallsees besorgt ist. Beunruhigt über das verstörende Gurgeln und den unersättlichen Appetit der Murlocs bittet er Abenteurer darum, die Zahl der Kreaturen auszudünnen, um die Fischerei zu sichern.",al={"wer vergibt slimy menace","slimy menace questgeber"}},{q="Was macht die Murlocs zu einer solchen Bedrohung?",a="Murlocs werden als bösartige, temperamentvolle amphibische Kreaturen mit scharfen Zähnen und einem berüchtigten, kehlig gurgelnden Laut beschrieben. Sie sammeln sich an den Ufern, verteidigen ihr Revier aggressiv und greifen alles an, was sich zu nah an ihre Futterplätze wagt.",al={"wie sind murlocs","murloc-verhalten kristallsee"}}},fp="12,255,23.409.0,22.433.0,37.239.0,45.220.0,47.247.0,58.213.0,40.227.0,37.257.0"}
P.entries["quest:99129"] = {n="A Man About a Murloc",s="A Man About a Murloc ist ein Botengang im Auftrag eines Fischers namens Jason, dem die örtlichen Murlocs zusetzen, da sie seine Fische plündern. Jason schickt Abenteurer los, um Remy „Zweifach“ zu befragen, einen ortsansässigen Sonderling, der einen tiefen Groll hegt und eigene Pläne gegen die Kreaturen schmiedet.",h="A Man About a Murloc ist ein Botengang im Auftrag eines Fischers namens Jason, dem die örtlichen Murlocs...",kw={"a man about a murloc","elwynn","fisch","jason","murloc","remy zweifach"},ang={["faction:Alliance"]="Lokale Siedlungen wie Seeufer und Docks leiden häufig unter Murloc-Überfällen, was Bewohner und Wachen in ganz Elwynn und den nahegelegenen Gebieten der Allianz stark beansprucht."},sec={{t="Ärger auf dem Wasser",b="Ein einheimischer Fischer namens Jason hat es satt, dass Murlocs seine Fänge plündern. Da Jason weiß, dass Remy „Zweifach“ einen geteilten Hass auf die Amphibien hegt, schickt er Reisende zu Remy, um zu sehen, ob dieser praktische Methoden ersonnen hat, um sie aus den Gewässern zu vertreiben."},{t="Remys Vergeltung",b="Als er angesprochen wird, lässt Remy seinem Frust darüber freien Lauf, dass die örtlichen Wachen sich weigern, seine ständigen Warnungen vor der Murloc-Bedrohung zu beachten. Anstatt auf offizielle Hilfe zu warten, bereitet Remy seine eigenen Vergeltungsmaßnahmen gegen die Kreaturen vor und wirbt fähige Reisende an, die ihn bei seinen Plänen unterstützen sollen."}},faq={{q="Wer vergibt die Quest A Man About a Murloc?",a="Ein einheimischer Fischer namens Jason schickt Abenteurer auf diesen Botengang, um Rat einzuholen, wie verhindert werden kann, dass Murlocs seine Fänge plündern.",al={"wer gibt a man about a murloc","wer startet a man about a murloc","jason murloc quest"}},{q="Wer ist Remy „Zweifach“?",a="Remy „Zweifach“ ist ein Bewohner, der für seine ständigen Klagen und Warnungen vor Murlocs bekannt ist und den Jason bezüglich praktischer Abschreckungspläne zu Rate zieht.",al={"wer ist remy zweifach","remy zweifach elwynn","wo ist remy"}},{q="Warum möchte Jason Remy befragen?",a="Murlocs dringen in Jasons Angelplätze ein und stehlen seine Fische, was ihn dazu veranlasst, Hilfe von außen zu suchen, um seine Lebensgrundlage zu schützen.",al={"warum braucht jason hilfe","jason fisch murlocs","murloc-problem jason"}},{q="Was plant Remy gegen die Murlocs zu unternehmen?",a="Remy behauptet, dass die Stadtwachen seine Warnungen ignorieren, also ersinnt er seine eigenen Vergeltungspläne gegen die Kreaturen und benötigt die Hilfe eines Abenteurers, um Materialien zu sammeln.",al={"ideen von remy zweifach","was ist remys plan","remy murlocs plan"}},{q="Warum haben sich die Wachen nicht um die Murlocs gekümmert?",a="Laut Remy hat er wiederholt versucht, die örtlichen Wachen vor der wachsenden Murloc-Plage zu warnen, aber sie haben sich geweigert, seine Warnungen ernst zu nehmen.",al={"wachen murlocs elwynn","warum helfen die wachen remy nicht","remy wachen warnung"}},{q="Was geschieht nach dem Gespräch mit Remy?",a="Das Gespräch mit Remy führt direkt zu seinen persönlichen Plänen, gegen die örtlichen Murlocs zurückzuschlagen, was weitere Aufgaben in seinem Namen nach sich zieht.",al={"wohin führt a man about a murloc","nach a man about a murloc","nächste quest nach remy"}}},fp="20,273,20.278.0,18.288.0,41.127.0,24.148.0,36.139.0,44.176.0,46.155.0,36.135.0"}
P.entries["quest:99130"] = {n="An Enticing Offer",s="'An Enticing Offer' ist eine lokale Initiative, die darauf abzielt, vordringende Murlocs mithilfe eines Köders abzuwehren, der aus giftigem Duskweed hergestellt wird. Durch das Ernten des schädlichen Unkrauts direkt von nahegelegenem Ackerland unterstützt der Plan gleichzeitig die örtlichen Bauern und stellt eine Abschreckung gegen Schädlinge an der Küste dar.",h="'An Enticing Offer' ist eine lokale Initiative, die darauf abzielt, vordringende Murlocs mithilfe eines...",kw={"an enticing offer","duskweed","jason","murloc-köder","murlocs","giftköder"},ang={["class:Hunter"]="Fährtenleser und Bestienmeister sollten die giftigen Eigenschaften von Duskweed beachten, da der daraus resultierende Köder bei Verschlucken eine ernste Gefahr für zahme Tiere und Jagdbegleiter darstellt.",["profession:Herbalism"]="Sammler, die mit der einheimischen Flora vertraut sind, werden die doppelte Natur von Duskweed erkennen – ein lästiges Unkraut, dessen giftige Blütenblätter bei der Herstellung wirksamer Köder eine vorsichtige Handhabung erfordern."},sec={{t="Eine zweifache Lösung",b="Der Umgang mit allgegenwärtigen Murloc-Plagen erfordert oft eine einfallsreiche Schädlingsbekämpfung statt endloser Scharmützel an vorderster Front. 'An Enticing Offer' schlägt eine kluge Lösung vor, um zwei lokale Plagen mit einem einzigen Streich anzugehen: die Herstellung eines speziellen, mit Duskweed versetzten Köders, um Murlocs davon abzuhalten, auf besiedeltes Land vorzudringen, während gleichzeitig wucherndes Unkraut von den benachbarten Feldern entfernt wird."},{t="Die Natur von Duskweed",b="Der Hauptbestandteil des Gebräus ist Duskweed, ein hartnäckiges wildes Unkraut, das nahegelegene landwirtschaftliche Parzellen plagt. In beträchtlichen Mengen enthalten die Blütenblätter von Duskweed starke Giftstoffe, die für die meisten Tiere schädlich sind. Indem das Unkraut direkt von den betroffenen Bauern gesammelt wird, werden die Felder von einer aggressiven Schudpflanze befreit, während seine giftige Ernte die notwendige Basis liefert, um Murloc-Rudeln beizubringen, sich fernzuhalten."},{t="Das Ködern der Gewässer",b="Während das resultierende Gebräu relativ einfach zuzubereiten ist, macht die unterschiedslose Giftigkeit von Duskweed die Handhabung etwas gefährlich. Haustiere und Begleiter müssen strikt von der fertigen Mischung ferngehalten werden, und der Questgeber spricht eine abschließende Warnung aus, um sicherzustellen, dass lokale Bekannte, namentlich jemand namens Jason, den stechenden Köder nicht mit einer Mahlzeit verwechseln."}},faq={{q="Was ist die Quest An Enticing Offer?",a="An Enticing Offer ist eine Aufgabe, bei der es darum geht, sich um lokale Murloc-Probleme zu kümmern und gleichzeitig nahegelegenen Bauern zu helfen. Sie beinhaltet das Sammeln von Zutaten, um einen speziellen giftigen Köder zusammenzubrauen, der dazu gedacht ist, die Kreaturen abzuschrecken.",al={"was ist an enticing offer","was ist diese quest"}},{q="Was ist Duskweed?",a="Duskweed ist ein gewöhnliches Unkraut, das lokale Felder befällt. Obwohl es allgemein als landwirtschaftlicher Schädling gilt, sind seine Blütenblätter in großen Mengen für die meisten Tiere giftig, was es zu einem wirksamen Mittel zur Abschreckung von Schädlingen macht, wenn es in einem Köder konzentriert wird.",al={"was ist duskweed","duskweed-pflanze","duskweed-effekte"}},{q="Wie soll der Murloc-Köder wirken?",a="Der Plan besteht darin, Köder herzustellen, die mit giftigen Duskweed-Blütenblättern versetzt sind. Anstelle einer herkömmlichen Vernichtung besteht das Ziel darin, den Köder so unangenehm oder schädlich zu machen, dass die örtlichen Murloc-Populationen lernen, das Gebiet zu meiden.",al={"wie funktioniert der köder","murloc-giftköder","warum köder herstellen"}},{q="Wer ist Jason?",a="Jason ist der Fischer, der Euch wegen seiner Murloc-Probleme zu Remy geschickt hat. Sobald der giftige duskweed-Köder hergestellt ist, sagt Remy, man solle Jason ausrichten, nichts davon zu essen.",al={"wer ist jason","jason nicht davon essen lassen","jason köder warnung"}},{q="Ist der Murloc-Köder für andere Kreaturen gefährlich?",a="Ja. Obwohl sie für Murlocs gedacht sind, sind die Blütenblätter von Duskweed in beträchtlichen Mengen für die meisten Tiere giftig. Der Questgeber warnt ausdrücklich davor, dass Haustiere und Begleiter weit von der Mischung ferngehalten werden müssen.",al={"ist der duskweed-köder gefährlich","haustier giftköder"}},{q="Warum wird das Sammeln von Duskweed als Win-win-Situation betrachtet?",a="Duskweed überwuchert aggressiv bewirtschaftetes Ackerland und bereitet den örtlichen Bauern Kopfzerbrechen. Das Sammeln des Unkrauts zum Brauen von Ködern säubert die landwirtschaftlichen Felder und liefert gleichzeitig die Materialien, die man braucht, um die Murlocs zurückzudrängen.",al={"warum bauern helfen","win-win-situation"}}},fp="17,283,18.401.0,22.404.0,18.369.0,36.216.0,17.240.0,40.208.0,13.152.0,48.210.0,47.224.0"}
P.entries["quest:99131"] = {n="Baited for Success",s="Bei Baited for Success geht es darum, dem örtlichen Fischer Jason Mathers bei der Bewältigung einer störenden Murloc-Plage zu helfen. Durch die Abstimmung mit Remy zur Herstellung eines gezielten Giftköders hofft Mathers, die Wasserwege zu säubern und seinen Fang wieder sicher verkaufen zu können.",h="Bei Baited for Success geht es darum, dem örtlichen Fischer Jason Mathers bei der Bewältigung einer störenden...",kw={"baited for success","angeln","jason mathers","murloc","giftköder","remy"},ang={["class:Rogue"]="Der Einsatz von maßgeschneidertem Gift als Schädlingsbekämpfung gegen lästige Murlocs spiegelt eine praktische, nüchterne Problemlösung wider.",["faction:Alliance"]="Die Sicherung der Gewässer und die Wiederherstellung lokaler Gewerbe wie der Fischerei sichert die Versorgung von Siedlungen und reduziert gleichzeitig die aggressive Murloc-Population."},sec={{t="Das Dilemma eines Fischers",b="Jason Mathers ist für sein Fischergewerbe auf freie Gewässer angewiesen, doch ein Befall aggressiver Murlocs hat seine Arbeit zum Erliegen gebracht. Da er seinen Fisch nicht mehr sicher verkaufen kann, sucht er nach einer Lösung, um die Kreaturen aus dem Gebiet zu vertreiben. Remy springt ein, um einen speziellen Giftköder herzustellen, der die örtlichen Murlocs dezimieren soll, damit die reguläre Fischerei wieder aufgenommen werden kann."},{t="Eine gezielte Lösung",b="Remy bereitet das giftige Gebräu vor und verspricht eine Einweisung in die fachgerechte Ausbringung, damit das Gift nur Murlocs trifft, ohne die Fische zu kontaminieren. Nach Erhalt der Nachricht plant Mathers, das Gemisch später am Tag abzuholen, in der Hoffnung, dass es die Gewässer endgültig befreit und seine Lebensgrundlage wiederherstellt."}},faq={{q="Wer hat den Köder für Jason Mathers vorbereitet?",a="Remy bereitet den speziellen Köder für Jason Mathers vor und verspricht, dessen ordnungsgemäße Anwendung zu erklären, wenn Mathers später am Tag vorbeikommt.",al={"wer vergibt baited for success","remy köder quest","wer hat den köder hergestellt"}},{q="Warum benötigt Jason Mathers diesen Köder?",a="Jason Mathers ist ein Fischer, der aufgrund einheimischer Murlocs Schwierigkeiten hat, seinen Fang zu verkaufen. Der Giftköder soll die Murlocs dezimieren, ohne den Fischen zu schaden, die er fangen und verkaufen will.",al={"warum braucht jason mathers köder","mathers fischgeschäft","warum giftköder"}},{q="Wird der Giftköder den Fischen schaden?",a="Mathers äußert ausdrücklich seine Sorge, dass Fische ihn fressen könnten. Der Plan beruht darauf, dass das Gift gezielt Murlocs angreift und die Fische unversehrt lässt, damit Mathers seine Existenzgrundlage wieder aufnehmen kann.",al={"ist der köder sicher für fische","tötet giftköder fische"}},{q="Wo wird diese Aufgabe abgeschlossen?",a="Die Aufgabe wird abgeschlossen, indem die Nachricht direkt zu Jason Mathers zurückgebracht wird, um ihn wissen zu lassen, dass Remys Vorbereitungen im Gange sind.",al={"wo gebe ich baited for success ab","baited for success questende"}},{q="Welche Bedrohung stellen die Murlocs für Mathers dar?",a="Murlocs stören die örtlichen Fischereigewässer und machen es für Fischer wie Mathers unmöglich oder gefährlich, ihren Lebensunterhalt zu bestreiten, bis ihre Zahl verringert wird.",al={"warum hier murlocs töten","murloc problem mathers"}},{q="Was plant Mathers, sobald er von Remy hört?",a="Sobald er benachrichtigt wurde, beschließt Mathers, später am Tag zu Remy zu gehen, um den Giftköder abzuholen und Anweisungen für dessen sicheren Einsatz zu erhalten.",al={"was passiert nach überbringen der nachricht","bekommt mathers den köder"}}},fp="18,253,21.332.0,19.287.1,40.131.0,38.184.0,37.189.0,29.127.0,43.148.0,49.152.0"}
P.entries["quest:99134"] = {n="Discipline",s="Disziplin ist eine Aufgabe, die von Exekutor Zygand in Tirisfal erteilt wird. Unbeeindruckt von der Kompetenz der örtlichen Deathguard-Garnison beauftragt Zygand außenstehende Abenteurer damit, nachlässigen untoten Posten körperliche Züchtigungen zu verabreichen.",h="Disziplin ist eine Aufgabe, die von Exekutor Zygand in Tirisfal erteilt wird.",kw={"dunkle fürstin","deathguard","disziplin","exekutor zygand","verlassene","motivator","tirisfal","untoter"},ang={["faction:Horde"]="Die finsteren Methoden der Kommandeure der Verlassenen verdeutlichen die harten, unerbittlichen Realitäten des Lebens und der Herrschaft in den nördlichen Gefilden der Horde.",["race:Undead"]="Für die Verlassenen ist militärische Disziplin eine Frage des Überlebens ihrer Art. Posten, die der Apathie erliegen, gefährden das gesamte Gebiet von Tirisfal."},sec={{t="Ordnung im Untod erzwingen",b="Die Deathguard bildet das militärische Rückgrat der Verlassenen in ganz Lordaeron, doch die Freiheit vom eisernen Willen des Lichkönigs bringt ihre eigenen Komplikationen mit sich: Apathie, Ermüdung und Fahrlässigkeit. Zuchtmeister wie Exekutor Zygand haben wenig Geduld mit nachlassender Disziplin, insbesondere angesichts von Bedrohungen durch die Scharlachroter Kreuzzug und die Geißel, die an den Grenzen von Tirisfal lauern. Um die Truppen wachsam zu halten, verlassen sich Offiziere auf stumpfe Werkzeuge und aggressive Aufsicht, um die militärische Einsatzbereitschaft aufrechtzuerhalten."},{t="Das Register des Exekutors",b="Exekutor Zygand setzt bewusst unabhängige Akteure statt Ränge aus den Reihen der Garnison ein, um seine Bestrafungen zu vollstrecken. Mithilfe des Motivators des Exekutors erinnern Außenstehende fahrlässige Deathguards daran, dass das Überleben im Dienst der Dunklen Fürstin absolute Wachsamkeit erfordert. Diejenigen, die ihren Pflichten nicht nachkommen, lernen schnell, dass das Unleben keinen Schutz vor Konsequenzen bietet."}},faq={{q="Wer vergibt die Quest Disziplin?",a="Disziplin wird von Exekutor Zygand vergeben, einem anspruchsvollen Offizier der Verlassenen, der in Tirisfal stationiert ist, die regionale Verteidigung überwacht und strikten Gehorsam von seinen Truppen verlangt.",al={"questgeber disziplin","wer startet disziplin","exekutor zygand quest"}},{q="Warum will Exekutor Zygand, dass die Deathguard bestraft wird?",a="Zygand hält die Deathguards unter seinem Befehl für inkompetent und ohne den rechten Antrieb. Da Selbstgefälligkeit das Überleben der Verlassenen in Tirisfal bedroht, setzt er harte Disziplin durch, um die Posten zur Wachsamkeit wachzurütteln.",al={"warum todeswachen schlagen","warum todeswache motivieren","zygand todeswache grund"}},{q="Warum nutzt Zygand einen Abenteurer statt eines anderen Soldaten?",a="Zygand merkt an, dass Ihr als Außenstehender, der noch nicht Teil der Deathguard ist, noch keine Gelegenheit hattet, ihn zu enttäuschen.",al={"warum ich disziplin","warum außenseiter zygand"}},{q="Was ist der Motivator des Exekutors?",a="Der Motivator des Exekutors ist ein strafendes Disziplinierungswerkzeug, das von Exekutor Zygand bereitgestellt wird. Er wird verwendet, um müßiggängerischen Deathguards, die in ganz Tirisfal stationiert sind, einen schmerzhaften Verweis zu erteilen.",al={"motivator des exekutors","was ist der motivator zygand"}},{q="Was passiert, wenn Ihr Zygands Befehl verweigert?",a="Zygand warnt davor, dass Zögern oder Weigerung dazu führen werden, dass Euer eigener Name in sein Register eingetragen wird, was Euch zum nächsten Ziel macht, das von jemand anderem diszipliniert wird.",al={"zygand drohungen","register drohung zygand"}},{q="Wie betrachten die Verlassenen Schmerz?",a="Zygand zählt Schmerz zu den wenigen Freuden, die ihm im Tod noch vergönnt sind. Seine Begeisterung für Bestrafung spiegelt sein eigenes hartes Gemüt wider.",al={"fühlen untote schmerz","verlassene schmerz lore"}}},fx={ae86ed1b={q="Wer sind die Todeswachen, die Ihr bestraft?",a="Die Todeswache stellt das stehende Militär und die Schildwachen der Verlassenen dar, deren Aufgabe es ist, Tirisfal zu verteidigen und die Herrschaft der Dunklen Fürstin durchzusetzen. Exekutor Zygand hält diejenigen, die rund um Brill und die Außenposten stationiert sind, für faul und inkompetent und fordert, dass sie durch körperliche Züchtigung an ihre geschworene Pflicht erinnert werden, die Ländereien der Verlassenen zu schützen.",al={"wer sind die todeswachen","todeswache ziele disziplin","wen diszipliniere ich"}}},fp="10,234,26.467.0,21.367.0,31.174.0,54.215.0,61.123.0,33.183.0,42.162.0,30.139.0"}
P.entries["quest:99141"] = {n="Patience",s="Patience ist eine von Exekutor Zygand in Tirisfal vergebene Aufgabe, die strikte militärische Rechenschaftspflicht für die Dunkle Fürstin einfordert. Da routinemäßige Lageberichte überfällig sind, entsendet Zygand einen Abenteurer, um Aktualisierungen von nahegelegenen Todeswachen und einem ungewöhnlichen Wachposten einzuholen. Der Auftrag verdeutlicht die strenge, kompromisslose Disziplin, die in allen Gebieten der Verlassenen durchgesetzt wird.",h="Patience ist eine von Exekutor Zygand in Tirisfal vergebene Aufgabe, die strikte militärische...",kw={"brill","dunkle fürstin","todeswache","dillinger","gordo","kristof","patience","stillwater-tümpel","tirisfal","zygand"},ang={["faction:Horde"]="Die Quest bietet durchreisenden Verbündeten der Horde einen Einblick in die düstere, streng disziplinierte Befehlsstruktur, die von Sylvanas Windläufers Offizieren in ganz Tirisfal durchgesetzt wird.",["race:Undead"]="Für frisch befreite Verlassene bestärkt die Ausführung von Zygands Befehlen die harten Realitäten des Überlebens in Lordaeron: vollkommene Hingabe an die Dunkle Fürstin und null Toleranz für Versagen."},sec={{t="Den Willen der Dunklen Fürstin durchsetzen",b="Exekutor Zygand befehligt die örtliche Sicherheit in Tirisfal und duldet kein Nachlassen der Wachsamkeit. Für Zygand erfordert der Dienst an Fürstin Sylvanas nichts Geringeres als absolute Effizienz. Wenn reguläre Frontberichte seinen Posten nicht planmäßig erreichen, betrachtet er dies als inakzeptable Pflichtverletzung und nicht als bloße Verzögerung. Anstatt seinen Posten zu verlassen, um Nachforschungen anzustellen, schickt er eintreffende Agenten der Verlassenen los, um säumige Untergebene zur Räson zu bringen und dafür zu sorgen, dass die Grenzen gesichert bleiben."},{t="Schildwachen der Lichtungen",b="Die Berichte betreffen Wachposten, die an entscheidenden Aussichtspunkten rund um Brill stationiert sind. Todeswache Dillinger hält Wache über den Friedhof im Westen, wo sich abtrünnige Untote und Überreste der Geißel oft regen. Im Osten überwacht Todeswache Kristof eine Zwischenstation, welche die Zugänge zur Hauptstadt und die östlichen Straßen bewacht. Der Ungewöhnlichste unter ihnen ist Gordo, eine gewaltige Monstrosität, die nahe dem Stillwater-Tümpel umherwandert und deren schlichter Geist das Führen militärischer Aufzeichnungen zu einer äußerst fragwürdigen Erwartung macht."}},faq={{q="Wer ist Exekutor Zygand?",a="Exekutor Zygand ist ein hochrangiger Offizier der Verlassenen, der mit der Aufrechterhaltung von Ordnung und Verteidigung rund um Brill in Tirisfal betraut ist. Er untersteht direkt der Befehlshierarchie von Fürstin Sylvanas und verlangt von allen Truppen unter seiner Aufsicht eine fehlerfreie Pflichterfüllung.",al={"zygand","wer ist zygand","rolle von exekutor zygand"}},{q="Warum schickt Zygand einen Abenteurer los, um Berichte einzuholen?",a="Mehrere Feldwachen haben ihre planmäßigen Berichte nicht rechtzeitig eingereicht. Da ihm die Geduld für Verzögerungen fehlt und er seinen zentralen Posten nicht verlassen will, setzt Zygand frisch bewährte Verlassene ein, um die überfälligen Meldungen im Umland einzutreiben.",al={"warum patience annehmen","warum berichte einholen"}},{q="Wer ist Gordo und warum hat er einen Bericht?",a="Gordo ist eine Monstrosität, die westlich nahe dem Stillwater-Tümpel umherwandert. Zygand erwartete von ihm wie von jedem anderen Feldposten einen Lagebericht, stellt jedoch nach Erhalt schnell fest, dass es ein peinliches Fehlurteil war, schriftliche Aufklärungsdaten von einer Monstrosität zu erwarten.",al={"gordo","warum hat eine monstrosität einen bericht","wer ist gordo"}},{q="Wo befindet sich Todeswache Dillinger?",a="Todeswache Dillinger ist knapp westlich von Brill stationiert und hält Wache nahe dem örtlichen Friedhof, um verbliebene Aktivitäten der Geißel und frisch auferstandene Leichen zu überwachen.",al={"standort von dillinger","dillinger finden","wo ist dillinger"}},{q="Wo ist Todeswache Kristof stationiert?",a="Todeswache Kristof ist an der Zwischenstation entlang der Straße östlich von Brill stationiert, wo er die Zugangswege gegen Eindringlinge bewacht und den Straßenverkehr überwacht.",al={"standort von kristof","kristof finden","wo ist kristof"}},{q="Was geschieht, wenn Gordos Bericht abgegeben wird?",a="Exekutor Zygand räumt ein, dass es ein törichtes Versehen war, von einer Monstrosität einen verständlichen schriftlichen Bericht zu erwarten. Er nimmt das Ergebnis stillschweigend hin und bittet darum, dass dieses peinliche Missgeschick streng zwischen Euch und ihm bleibt.",al={"ausgang von gordos bericht","schreibt gordo"}}},fx={e0ff4089={q="Warum möchte Exekutor Zygand, dass diese Berichte gesammelt werden?",a="Exekutor Zygand hat die Aufgabe, den Willen der Dunklen Fürstin aufrechtzuerhalten und eine strenge Aufsicht über die Verteidigung von Brill zu führen. Wenn Schildwachen und Späher ihre Statusberichte nicht wie geplant einreichen, gefährdet dies die Einsatzbereitschaft der Verlassenen und riskiert, den Unmut von Sylvanas auf sich zu ziehen. Zygand verlangt schnelle Einhaltung, um eiserne Disziplin zu wahren.",al={"zygand motiv","warum will zygand berichte","warum geduld-quest"}},cb8b3e87={q="Wozu dient der Bericht der Todeswache Dillinger?",a="Dillingers Bericht vermittelt die aktuelle Sicherheitslage rund um den Friedhof von Brill westlich der Stadt. Da die Todeswache Dillinger in der Nähe des Friedhofs stationiert ist, um nach Bedrohungen und Störungen Ausschau zu halten, wird von ihr erwartet, dass sie Exekutor Zygand über lokale Unruhen und die Stabilität des Perimeters informiert.",al={"dillingers bericht","was ist dillingers bericht","dillinger bericht zweck"}},["744f946d"]={q="Wozu dient der Bericht der Todeswache Kristof?",a="Kristofs Bericht beschreibt Patrouillenaktivitäten und Straßenbedingungen rund um die östliche Postenstation. Die Todeswache Kristof beobachtet den Durchgang, der nach Osten durch Tirisfal führt, und ihre Depesche liefert Exekutor Zygand wichtige Informationen über den Verkehr und herannahende Gefahren.",al={"kristofs bericht","was ist kristofs bericht","kristof bericht zweck"}},["79b1ee7a"]={q="Wozu dient der Bericht von Gordo?",a="Gordos Bericht soll eine Bestandsaufnahme des Gebiets um den Stillwater-Tümpel im Westen liefern, wo das Monstrosität auf Patrouille herumstapft. Obwohl Exekutor Zygand schriftliche Aufklärung erwartet, tut sich der einfältige Grobian mit dem Konzept militärischer Depeschen schwer.",al={"gordos bericht","was ist gordos bericht","gordo bericht zweck"}}},fp="8,361,30.486.0,23.490.0,23.260.0,54.244.0,43.288.1,38.153.0,38.157.0,46.224.1"}
P.entries["quest:99142"] = {n="Tomb Weed",s="Tomb Weed ist eine alchemistische Quest, die von Junior Apothecary Holland in Tirisfal vergeben wird. Holland hat wildes Verdammniskraut modifiziert und auf dem heimgesuchten Balnirs Bauernhof wieder eingepflanzt, um ein potentes neues Exemplar heranzuzüchten, das unerwartet die örtliche Geißel anlockt.",h="Tomb Weed ist eine alchemistische Quest, die von Junior Apothecary Holland in Tirisfal vergeben wird.",kw={"balnirs bauernhof","verdammniskraut","gordo","junior apothecary holland","royal apothecary society","tirisfal","tomb weed"},ang={["profession:Herbalism"]="Tomb Weed veranschaulicht, wie künstliche alchemistische Manipulation die Eigenschaften und Verhaltensweisen pestbefallener Kräuter wie dem Verdammniskraut grundlegend verändern kann.",["race:Undead"]="Die Forschungen von Junior Apothecary Holland zeigen den anhaltenden Antrieb der Apotheker der Verlassenen, die verseuchte Flora von Tirisfal zu maßgeschneiderten alchemistischen Werkzeugen umzuformen."},sec={{t="Hollands Kultivierung",b="Junior Apothecary Holland gibt sich nicht damit zufrieden, einfach nur einheimische Kräuter für die Royal Apothecary Society zu ernten; er hegt eigene, hochfliegende Ambitionen. Indem er Verdammniskraut sammelte und kleineren alchemistischen Veränderungen unterzog, pflanzte er die Züchtungen in den Boden von Balnirs Bauernhof ein, um ein weiterentwickeltes Exemplar heranzuziehen, das er Tomb Weed taufte. Holland betrachtet diese Hybridflora als das Herzstück seines Werks und als Vorboten seines persönlichen Schicksals."},{t="Ungewollte Anziehung",b="Holland rechnete zwar mit alchemistischer Wirkkraft, doch das Verpflanzen von Tomb Weed nach Balnirs Bauernhof brachte eine unvorhergesehene Nebenwirkung mit sich. Die umherirrenden Überreste der Geißel, die die verseuchten Felder heimsuchen, zeigen eine unheimliche, allgegenwärtige Anziehung zu der sprießenden Flora. Holland verlässt sich auf vorbeireisende Wanderer, die diese vordringenden Untoten zurückschlagen und die reife Ernte einholen sollen, damit er seine Experimente fortsetzen kann."}},faq={{q="Was ist Tomb Weed?",a="Tomb Weed ist eine alchemistisch modifizierte Züchtung von Verdammniskraut, die von Junior Apothecary Holland kultiviert wurde. Er nimmt einheimisches Verdammniskraut, verändert es mit chemischen Reagenzien und pflanzt es in die verseuchte Erde von Balnirs Bauernhof ein.",al={"was ist tomb weed","tomb weed hintergrundgeschichte","tomb weed pflanze"}},{q="Wer ist Junior Apothecary Holland?",a="Holland ist ein Mitglied der Royal Apothecary Society, das in Tirisfal tätig ist. Holland ist ehrgeizig und oft verzweifelt über Gehilfen wie die Monstrosität Gordo; er führt private gärtnerische und alchemistische Experimente durch, die darauf abzielen, sein eigenes Ansehen zu mehren.",al={"wer ist holland","junior apothecary holland","apothecary holland"}},{q="Wo wird Tomb Weed angebaut?",a="Holland pflanzt seine modifizierten Gewächse auf Balnirs Bauernhof an, einem verlassenen Anwesen im Osten von Tirisfal, das dem Verfall und der Pest anheimgefallen ist.",al={"wo man tomb weed findet","tomb weed fundort","balnirs bauernhof kraut"}},{q="Warum fühlt sich die Geißel von Tomb Weed angezogen?",a="Holland hat beobachtet, dass die geistlose Geißel, die Balnirs Bauernhof heimsucht, sich instinktiv zu der modifizierten Pflanze hingezogen zu fühlen scheint, obwohl er nicht weiß, warum; er findet es schlichtweg kurios.",al={"warum geißel tomb weed will","geißel von tomb weed angezogen","geißel reaktion"}},{q="Wie unterscheidet sich Tomb Weed von normalem Verdammniskraut?",a="Verdammniskraut ist eine natürlich vorkommende Pflanze, die nahe der Massengrabstätte nördlich des Friedhofs von Brill wächst. Tomb Weed entsteht, wenn Verdammniskraut künstliche alchemistische Veränderungen durchläuft und unter Hollands Anleitung gezielt im Boden des Bauernhofs wieder eingepflanzt wird.",al={"verdammniskraut vs tomb weed","unterschied verdammniskraut tomb weed"}},{q="Wer ist der von Holland erwähnte Gordo?",a="Gordo ist eine von den Verlassenen erschaffene, umherwandernde Monstrosität, die die Straßen von Tirisfal durchstreift und der Holland oft einfache Aufgaben überträgt, die sich für seinen trägen Verstand jedoch als schwierig erweisen.",al={"wer ist gordo","gordo begegnung","gordo tirisfal"}}},fp="9,263,21.442.0,21.406.0,18.223.0,33.257.0,25.149.0,43.180.0,48.250.0,34.179.0"}
P.entries["quest:99143"] = {n="Bottles and Baubles",s="Bottles and Baubles ist eine Quest, die auf der skurrilen Logik aufbaut, dass Murlocs, weil sie wie Fische aussehen, auch wie sie denken müssen. Adventurers werden ausgesandt, um ein nahegelegenes Murloclager nach glitzerndem Schrott und weggeworfenem Tand zu durchstöbern, den ein eifriger Angler zu Angelködern verarbeiten kann.",h="Bottles and Baubles ist eine Quest, die auf der skurrilen Logik aufbaut, dass Murlocs, weil sie wie Fische...",kw={"köder","bottles and baubles","angeln","kunstköder","murloc","murloclager","glänzender schrott"},sec={{t="Fischlogik und Plündern am Ufer",b="Bottles and Baubles beginnt mit einer ziemlich ungewöhnlichen Theorie der aquatischen Biologie: Da Murlocs fischähnliche Wesen sind, müsse ihr Verstand genauso funktionieren wie der von Fischen, die in der Tiefe schwimmen. Von dieser Logik geleitet stellt ein exzentrischer Angler die Behauptung auf, dass jede merkwürdige Kuriosität, die den umherschweifenden Blick eines Murlocs fesselt, gewiss auch einen hungrigen Fisch an den Haken locken wird. Sammler werden damit beauftragt, sich in ein nahegelegenes Murloclager zu wagen, um deren Hortungshaufen zu durchwühlen und glänzenden, weggeworfenen Schrott zu sammeln, um die Hypothese zu überprüfen."},{t="Schimmernder Tand als Köder",b="Murlocs entlang von Küstengewässern und Flussufern sind berüchtigte Sammler, die glänzende Steine, Muscheln, Splitter geschliffenen Glases und Metallschrott auf unordentlichen Haufen um ihre Hütten horten. Das Durchsieben dieser schlammigen Ansammlungen bringt allerlei glitzernden Abfall zum Vorschein, den ein geschäftstüchtiger Fischer zu einfachen Kunstködern und Blinkern verarbeiten kann. Sobald das sonderbare Sammelsurium geborgen und übergeben wurde, erweist es sich als zufriedenstellend genug, um dem Adventurer ein Set aus anfänglicher Angelausrüstung einzubringen."}},faq={{q="Warum müsst Ihr Schrott von Murlocs sammeln?",a="Der Questgeber glaubt, dass der Verstand von Murlocs, weil sie Fischen ähneln, ebenfalls wie der von Fischen funktionieren müsse. Nach der Theorie, dass alles, was einen Murloc anlockt, unter Wasser auch Fische anlockt, werden Adventurers ausgesandt, um Tand und glänzenden Abfall aus ihren Lagern zu sammeln und als Angelköder wiederzuverwenden.",al={"warum schrott sammeln","wozu bottles and baubles","glänzender schrott murloc"}},{q="Wo ist der glänzende Schrott zu finden?",a="Der glänzende Schrott liegt verstreut um das nahegelegene Murloclager herum. Murlocs sind berüchtigte Sammler, die glitzernde Trümmer, weggeworfenen Tand und Glas entlang von Küstenlinien und Wasserläufen horten, was direkt aus ihrem Revier beschafft werden kann.",al={"wo schrott finden","standort murloclager","wie man glänzenden schrott bekommt"}},{q="Wer vergibt diese Aufgabe und was will diese Person?",a="Die Aufgabe wird von einem einheimischen Angler in Auftrag gegeben, der seinen Vorrat an Kunstködern und Naturködern aufstocken möchte. Obwohl seine Theorien zur Psychologie der Murlocs etwas exzentrisch sind, belohnt er hilfsbereite Sammler mit überschüssiger Angelausrüstung, um Neulinge in diesem Handwerk zu ermutigen.",al={"wer vergibt bottles and baubles","wer ist der questgeber","quest abgeben"}},{q="Denken Murlocs tatsächlich wie Fische?",a="Trotz der Argumentation des Questgebers sind Murlocs amphibische, in Stämmen lebende Humanoide und keine einfachen, geistlosen Fische. Wie viele Kreaturen und Raubtiere fühlen sie sich jedoch von Natur aus von schimmernden Gegenständen, polierten Muscheln und hellem Tand angezogen, wodurch Hortungshaufen entstehen, die zufällig glitzernde Materialien enthalten.",al={"denken murlocs wie fische","murloc-intelligenz","sind murlocs tatsächlich fische"}},{q="Wie wird der Murloc-Schrott als Köder verwendet?",a="Der gesammelte Schrott besteht aus spiegelndem Glas, Metallstücken und poliertem Krimskrams. Der Angler beabsichtigt, diese reflektierenden Bruchstücke zu Kunstködern und improvisierten Ködern zu verarbeiten, in der Hoffnung, dass ihr Glanz kleine Elritzen nachahmt oder die Neugier fressender Fische weckt.",al={"wofür wird glänzender schrott verwendet","ist glänzender schrott ein köder","funktioniert murloc-schrott als köder"}},{q="Was bietet der Questgeber als Belohnung an?",a="Sobald genügend passende glänzende Reste zurückgebracht wurden, überreicht der Questgeber älteren eigenen Angelbedarf. Diese grundlegenden Werkzeuge und Vorräte sollen angehenden Anglern helfen, Fuß zu fassen und sich an den Gewässern zu versuchen.",al={"welche belohnung bottles and baubles","was bekommt man","angelbedarf belohnung"}}},fp="19,280,35.496.0,24.470.0,45.303.0,30.252.0,42.241.0,36.299.0,41.262.0,43.233.0"}
P.entries["quest:99144"] = {n="Seeking Refuge",s="Seeking Refuge ist eine Quest in Tirisfal, die die Rettung von Bareth Dawnstone beinhaltet, einem Gesandten aus der Bandarionfestung, der am Crusader's Outpost gefangen gehalten wird. Sein Kampf verdeutlicht das Entstehen eines unkonventionellen Ordens, der sich trotz schwerer Vorurteile lokaler Eiferer dem Heiligen Licht widmet. Das sichere Überbringen der Nachricht von seiner Flucht nach Brill sichert diesem jungen Zufluchtsort lebenswichtige Verbindungen.",h="Seeking Refuge ist eine Quest in Tirisfal, die die Rettung von Bareth Dawnstone beinhaltet, einem Gesandten...",kw={"die bandarionfestung","bareth dawnstone","brill","crusader's outpost","kreuzfahrer","heiliges licht","seeking refuge","shari stilwell","sollidens bauernhof","tirisfal"},ang={["class:Paladin"]="Paladine bemerken vielleicht den Gegensatz zwischen den Eiferern am Crusader's Outpost, die das Licht getrieben von Hass führen, und Bareth Dawnstones Streben nach Wohlwollen und Schutz.",["class:Priest"]="Priester werden die Philosophie der Bandarionfestung faszinierend finden, da ihre Mitglieder trotz der Vorurteile gegenüber untoten Anwendern reine Meditation und Führung im Heiligen Licht anstreben.",["faction:Horde"]="Die Absicherung von Boten zwischen der Bandarionfestung und Brill stellt sicher, dass neu entstehende neutrale oder verbündete Orden in Tirisfal gegen feindselige Kreuzfahrer Fuß fassen.",["race:Undead"]="Verlassene, die ihre Ehrfurcht vor dem Heiligen Licht bewahren, sehen sich der Feindseligkeit sowohl lebender Eiferer als auch skeptischer Artgenossen ausgesetzt, was die wachsende Bruderschaft in der Bandarionfestung zu einem seltenen Zufluchtsort macht."},sec={{t="Eine gefährliche Reise",b="Seeking Refuge erzählt von der gefährlichen Reise von Bareth Dawnstone, einem Boten, der aus dem abgelegenen Kloster der Bandarionfestung entsandt wurde. Während er unterwegs war, um sich mit Shari Stilwell in Brill zu beraten, wurde Bareth von eifrigen Kriegern am Crusader's Outpost abgefangen und gefangen genommen. Trotz des Hasses, der seinem untoten Zustand entgegenschlägt, bleibt Bareth standhaft in seiner Hingabe an das Licht und sehnt sich nur danach, seinen Peinigern zu entkommen und sicherzustellen, dass seine Nachricht ihr Ziel erreicht."},{t="Vergeltung gegen Hingabe",b="Bareths Gefangenschaft verdeutlicht die bittere ideologische Kluft, die Tirisfal heimsucht. Die Eiferer am Crusader's Outpost kanalisieren das Heilige Licht durch rachsüchtige Wut und dogmatische Rechtschaffenheit und betrachten Bareths Existenz als einen Affront. In krassem Gegensatz dazu meditiert Dawnstone über das Licht als Quelle des Schutzes und der inneren Reinheit und beklagt, wie die Grausamkeit seiner Peiniger die heiligen Lehren verzerrt, die er so schätzt."},{t="Zuflucht auf den Klippen",b="Nach seiner Flucht wird Bareths Sicherheit bei Shari Stilwell in Brill bestätigt. Stilwell enthüllt, dass ihr Klosterorden noch immer auf den Klippen nordwestlich von Sollidens Bauernhof Fuß fasst. Der Verlust eines so vielversprechenden Praktizierenden wie Dawnstone hätte ihrer jungen Gemeinschaft, die ihre Türen für jeden Reisenden öffnet, der nach authentischer spiritueller Führung sucht, einen tragischen Schlag versetzt."}},faq={{q="Wer ist Bareth Dawnstone?",a="Bareth Dawnstone ist ein Ergebener des Heiligen Lichts, der in der Bandarionfestung ansässig ist. Während er nach Brill reiste, um eine Nachricht zu überbringen, wurde er von eifrigen Kreuzfahrern überfallen und eingesperrt, die seine Art verabscheuen. Trotz seines untoten Zustands meditiert er über das Licht und strebt danach, es zum Schutz zu nutzen.",al={"wer ist bareth dawnstone","bareth dawnstone geschichte","dawnstone"}},{q="Wer hat Bareth Dawnstone gefangen genommen und warum?",a="Am Crusader's Outpost stationierte Eiferer lauerten Bareth Dawnstone auf dem Weg von der Bandarionfestung auf. Er beklagt, dass seine Peiniger das Heilige Licht mit grimmigem Hass in ihren Herzen führen, die Tugend des Wohlwollens pervertieren, über die er meditiert, und jene verfolgen, die sie als Abscheulichkeiten erachten.",al={"wer nahm bareth dawnstone gefangen","crusaders outpost entführer","warum wurde er gefangen genommen"}},{q="Wer ist Shari Stilwell?",a="Shari Stilwell ist eine Vertreterin des Ordens des Klosters, die in der Stadt Brill der Verlassenen stationiert ist. Sie empfängt Reisende und stimmt sich mit den aus der Bandarionfestung entsandten Gesandten ab, wobei sie jeden willkommen heißt, der Führung auf den Pfaden des Lichts sucht.",al={"wer ist shari stilwell","stilwell brill","shari brill"}},{q="Was ist die Bandarionfestung?",a="Die Bandarionfestung ist ein abgelegenes Kloster auf den Klippen nordwestlich von Sollidens Bauernhof in Tirisfal. Sie dient als Zufluchtsort und Übungsplatz für einen aufkeimenden religiösen Orden, der sich der reinen Meditation und dem Studium des Heiligen Lichts widmet.",al={"was ist die bandarionfestung","wo liegt die bandarionfestung","kloster nordwestlich von solliden"}},{q="Warum stören sich Bareths Peiniger an seiner Art?",a="Bareth Dawnstone spricht von „was von meinem Blut übrig ist“ und räumt Vorurteile gegenüber seiner Art ein, was darauf hinweist, dass er ein untoter Anwender des Heiligen Lichts ist. Die fanatischen Kreuzfahrer von Tirisfal verachten alle Untoten und weigern sich zu glauben, dass ihre Absichten oder ihre Hingabe jemals rein sein könnten.",al={"warum hassen sie seine art","untote die das licht nutzen","bareth was von meinem blut übrig ist"}},{q="Welche Art von Orden ist in der Bandarionfestung ansässig?",a="Der in der Bandarionfestung ansässige Orden ist eine junge, sich entwickelnde klösterliche Bruderschaft, die auf den Klippen von Tirisfal Fuß fasst. Anders als die hasserfüllten Kreuzfahrer in der Nähe predigen sie friedliche Meditation, Schutz und öffnen ihre Türen für jeden, der wahre Führung im Licht sucht.",al={"was ist der orden in der bandarionfestung","mönche der bandarionfestung","bandarion glaube"}}},fp="14,381,18.460.0,25.409.0,23.384.0,24.289.0,39.284.0,22.241.0,23.253.0,49.282.0,46.265.0"}
P.entries["quest:99152"] = {n="As Above, So Below",s="As Above, So Below ist eine Mission, die von Hilda the Breaker in der Bandarionfestung vergeben wird, um eine verborgene Infiltration der Geißel unter dem nahe gelegenen Schattental zu bekämpfen. Durch das Bergen von Knochen, die noch von frischer Reanimationsmagie erfüllt sind, versuchen die Verteidiger zu verstehen, wie sich die Untoten unbemerkt direkt unter der Stadt versammeln konnten.",h="As Above, So Below ist eine Mission, die von Hilda the Breaker in der Bandarionfestung vergeben wird, um eine...",kw={"as above, so below","die bandarionfestung","leuchtende knochen","hilda the breaker","reanimationsmagie","geißel","schattental","tarnished"},ang={["class:Mage"]="Magier werden die verweilende Reanimationsmagie bemerken, die den leuchtenden Knochen anhaftet, was auf bestimmte nekromantische Praktiken hinweist, die sich unter der Stadt verbergen.",["class:Paladin"]="Paladine betrachten jede unentdeckte Präsenz der Geißel als unmittelbare Gefahr, was die Untersuchung der Reanimationsmagie unter Schattental zu einer dringlichen Pflicht macht.",["class:Priest"]="Priester, die im Kampf gegen das Unheilige ausgebildet sind, sind verständlicherweise beunruhigt über die finsteren Reanimationskünste, die direkt unter einer bewohnten Siedlung schwelen."},sec={{t="Die verborgene Bedrohung",b="In der Bandarionfestung überwacht Hilda the Breaker die rigorose Vorbereitung der Verteidiger auf die umliegenden Gefahren. Während die Blicke an der Oberfläche auf die unruhige Siedlung Schattental im Südwesten gerichtet bleiben – wo eine als die Tarnished bekannte feindselige Fraktion regelmäßig für Unruhe sorgt –, hat eine weitaus dunklere Gefahr ungesehen Fuß gefasst. In den finsteren Kellern unter der Stadt sammelt eine unentdeckte Präsenz der Geißel Kräfte und droht, zu einem plötzlichen Angriff auf die Festung heranzuwachsen, wenn man sie ungehindert gewähren lässt."},{t="Magie in den Kellern",b="Hilda ist nicht gewillt, unerfahrene Rekruten blindlings in unterirdische Krypten marschieren zu lassen, und schickt daher erfahrene Abenteurer auf einen direkten Crashkurs in die Keller unter Schattental. Anstelle einer bloßen Säuberungsaktion besteht das Hauptziel in der Informationsbeschaffung: das Bergen von skelettierten Überresten, die noch von verweilender Reanimationsmagie knistern. Die Untersuchung dieser schwach leuchtenden Knochen bietet den Verteidigern eine entscheidende Gelegenheit, zu entschlüsseln, wie eine derart finstere Nekromantie direkt unter ihren Füßen und völlig unbemerkt wirken konnte."}},faq={{q="Was ist As Above, So Below?",a="As Above, So Below ist eine Aufgabe, die von Hilda the Breaker erteilt wird, um eine verborgene Präsenz der Geißel zu untersuchen, die unter der Siedlung Schattental schwelt. Während in der Bandarionfestung Rekruten gedrillt werden, wird ein Abenteurer unter die Stadt entsandt, um reanimierte Knochenproben zu sammeln.",al={"was ist as above, so below","as above, so below quest"}},{q="Wer vergibt die Quest As Above, So Below?",a="Hilda the Breaker ist eine anspruchsvolle Ausbilderin, die Rekruten in der Bandarionfestung vorbereitet. Hart und kompromisslos verlangt sie von jedem unter ihrem Befehl Ergebnisse und zieht es vor, dass ein Rekrut auf einer Trage zurückkehrt, anstatt mit leeren Händen dazustehen.",al={"wer vergibt as above, so below","wer ist hilda the breaker","questgeberin hilda"}},{q="Wo liegt Schattental?",a="Schattental ist eine Stadt südwestlich der Bandarionfestung. Während die Probleme an der Oberfläche eine als die Tarnished bekannte Gruppe betreffen, verbergen seine unterirdischen Keller einen weitaus heimtückischeren Befall durch Untote.",al={"wo liegt schattental","lage von schattental"}},{q="Welche Bedrohung lauert unter Schattental?",a="Die Keller unter Schattental sind von reanimierten Untoten befallen worden. Bleibt sie unkontrolliert, droht diese verborgene Präsenz der Geißel zu einem ausgewachsenen Aufstand gegen die nahe gelegene Bandarionfestung auszubrechen.",al={"was sind die keller unter schattental","geißel in den kellern von schattental","bedrohung unter schattental"}},{q="Warum benötigt Hilda schwach leuchtende Knochen?",a="Hilda benötigt Knochen, die noch die verbleibende magische Aura ihrer Reanimation in sich tragen. Durch die Untersuchung dieser schwach leuchtenden Überreste hoffen die Verteidiger zu verstehen, wie Nekromanten den Aufstand inszenierten, ohne entdeckt zu werden.",al={"warum leuchtende knochen sammeln","zweck schwach leuchtender knochen","reanimationsmagie knochen"}},{q="Wer sind die Tarnished in Schattental?",a="Die Tarnished sind eine feindselige Fraktion, die an der Oberfläche von Schattental aktiv ist. Obwohl sie eine aktive Bedrohung für das Gebiet darstellen, betrachtet Hilda das verborgene Nest der Geißel unter der Stadt als eine noch weitaus gefährlichere Bedrohung.",al={"wer sind die tarnished","tarnished schattental"}}},fp="18,295,17.496.0,20.498.1,27.266.0,39.230.0,28.201.0,37.200.0,42.225.0,36.219.0"}
P.entries["quest:99153"] = {n="The One That Got Away",s="The One That Got Away ist eine Quest, die von Ephram Barbaro angeboten wird, um einen abtrünnigen Kultisten aufzuspüren, der einem Scharmützel nahe den Überresten von Naxxramas entkommen ist. Der Flüchtige floh unter Schattental und trug ein aktives Fragment eines Fokussierungskristalls bei sich, das die Toten zu stärken oder wiederzubeleben droht.",h="The One That Got Away ist eine Quest, die von Ephram Barbaro angeboten wird, um einen abtrünnigen Kultisten...",kw={"kristallfragment","kultist","ephram barbaro","fokussierungskristall","naxxramas","schattental","the one that got away"},ang={["class:Paladin"]="Paladine, die geschworen haben, nekromantische Bedrohungen auszumerzen, werden die Gefahr eines aktiv gebliebenen Fokussierungskristalls der Geißel erkennen – insbesondere eines solchen, der imstande ist, Untote unter der Erde zu beleben oder zu stärken.",["class:Priest"]="Priester, die mit der Bekämpfung dunkler Magie vertraut sind, verstehen, wie unheilige Relikte umliegende Gebiete verderben können, wenn sie nicht unverzüglich geborgen und gereinigt werden."},sec={{t="Ein Flüchtiger in den Schatten",b="Nach einem Zusammenstoß mit Kultisten rund um die Überreste der Schlacht bei Naxxramas machen Neuigkeiten in den Reihen schnell die Runde. Ephram Barbaro sucht nach fähigen Abenteurern, nachdem er erfahren hat, dass ein einzelner Kultist durch den Sperrgürtel geschlüpft ist und ein aktives Stück eines Fokussierungskristalls der Geißel entwendet hat."},{t="Die Bedrohung unter Schattental",b="Erkenntnisse weisen auf die unterirdischen Gänge unter Schattental hin, in die der entkommene Kultist floh. Das Fragment birgt noch immer dunkle nekromantische Energie und steht im Verdacht, entweder die Toten wiederzubeleben oder feindselige Streitkräfte zu stärken, die im Untergrund lauern. Barbaro beauftragt Abenteurer damit, den verborgenen Kristall aufzuspüren und zu sichern, bevor seine Macht eine größere Katastrophe heraufbeschwört."}},faq={{q="Wer vergibt die Quest The One That Got Away?",a="Die Quest wird von Ephram Barbaro vergeben, der sich an Euch wendet, nachdem er von Euren früheren Bemühungen im Kampf gegen die Kultisten nahe den Überresten der Schlacht bei Naxxramas gehört hat.",al={"wer vergibt the one that got away","wer startet diese quest","questgeber the one that got away"}},{q="Was ist das Fokussierungskristallfragment?",a="Es ist ein verbliebener Splitter eines Fokussierungskristalls der Geißel, der von einem entkommenen Kultisten mitgenommen wurde. Ephram Barbaro merkt an, dass er immer noch Macht birgt und unter Schattental entweder Untote auferstehen lässt oder bestehende stärkt.",al={"was ist das kristallsplitterfragment","was macht der kristall","warum ist der kristall gefaehrlich"}},{q="Wo befindet sich das Kristallfragment?",a="Nach den Erkenntnissen von Ephram Barbaro floh der flüchtige Kultist mit dem Relikt unter Schattental und versteckte es irgendwo im Untergrund, wo seine Macht weiterhin nach außen dringt.",al={"wo ist der kristall versteckt","kristallfundort schattental","wo man das kristallsplitterfragment findet"}},{q="Wer ist „the one that got away“?",a="Der Titel bezieht sich auf einen Kultisten, dem es gelang, nach der Konfrontation an den Überresten der Schlacht bei Naxxramas zu entkommen, wobei er einen aktiven Splitter eines Fokussierungskristalls mit sich nahm.",al={"wer mit dem kristall entkommen ist","kultist mit kristall","the one that got away bedeutung"}},{q="Was passiert, wenn Ihr den Kristall zu Ephram Barbaro zurückbringt?",a="Nach der Rückgabe des geborgenen Kristallfragments lobt Ephram Barbaro Eure Schnelligkeit und bemerkt, dass es Zeit sei, zu seinem Lieblingsteil bei der Bewältigung der Lage überzugehen.",al={"was passiert wenn ihr den kristall zurueckbringt","the one that got away abgeben","ephram barbaro lieblingsteil"}},{q="Woher weiß Ephram Barbaro von Euch?",a="Ephram erwähnt, dass sich Neuigkeiten in den Reihen schnell herumsprechen, und weist ausdrücklich auf frühere Taten gegen Kultisten hin, die sich um die Überreste der Schlacht bei Naxxramas herumtrieben.",al={"naxxramas schlachtueberreste kultisten","woher kennt ephram euch","voraussetzungen the one that got away"}}},fp="21,272,25.290.0,29.365.0,42.165.0,38.217.0,38.175.0,31.184.0,59.167.0,39.172.0"}
P.entries["quest:99156"] = {n="Patrouille zur Rückendeckung",s="Patrouille zur Rückendeckung ist ein kritischer Verteidigungsauftrag, der von Todeswache Linnea in Tirisfal vergeben wird. Anstatt bloße umherwandernde Ghule abzuwehren, haben die Patrouillierenden die Aufgabe, Riptear zu jagen, ein Monstrosität, die nahe dem Giftwebertal umherstreift und es eigentlich niemals am Bollwerk hätte vorbeischaffen dürfen.",h="Patrouille zur Rückendeckung ist ein kritischer Verteidigungsauftrag, der von Todeswache Linnea in Tirisfal...",kw={"monstrosität","das bollwerk","todeswache linnea","patrouille zur rückendeckung","riptear","tirisfal","giftwebertal"},ang={["faction:Horde"]="Die Sicherung von Tirisfals Ostgrenze garantiert, dass die Nachschublinien, die das Bollwerk und Unterstadt versorgen, nicht von abtrünnigen Schrecken gefährdet werden.",["race:Undead"]="Die Verlassenen können es sich nicht leisten, einen Krieg an zwei Fronten zu führen; jedes Konstrukt der Geißel, das hinter ihren Verteidigungsbarrikaden umherstreift, stellt eine existenzielle Bedrohung für ihr Königreich dar."},sec={{t="Der Durchbruch an der Grenze",b="Das Bollwerk steht als einzige befestigte Barriere zwischen Tirisfal und den Schrecken der Westlichen Pestländer. Die Strategie des Militärs der Verlassenen beruht auf einem strikten Einfrontenkrieg. Wenn geistlose Untote hinter die Linien schlüpfen, können die Nachschubwege zur Front im Handumdrehen abgeschnitten werden. Während sich verirrte Geister oder Ghule gelegentlich an den Barrikaden vorbeischleichen, deuten Berichte über eine Monstrosität in den Lichtungen auf ein schweres Versagen der Grenzsicherung hin."},{t="Die Bedrohung durch Riptear",b="Die abtrünnige Monstrosität namens Riptear wurde gesichtet, wie sie nahe dem Giftwebertal hinter den vorgelagerten Redouten des Bollwerks umherschlenderte. Monstrositäten sind gewaltige Schlachtmaschinen, zusammengeflickt aus Leichen und dunkler Nekromantie. Sie wandern nicht ungesehen durch befestigte Engpässe, weshalb Todeswache Linnea zutiefst beunruhigt darüber ist, wie die Kreatur die Grenzlinie überwinden konnte. Linnea fordert Reißers Herz als absoluten Beweis für ihre Vernichtung."}},faq={{q="Wer vergibt die Quest „Patrouille zur Rückendeckung“?",a="Der Patrouillenbefehl wird von Todeswache Linnea erteilt, einer Todeswache der Verlassenen in Tirisfal, die Exekutor Zygand untersteht.",al={"wer gibt patrouille zur rückendeckung","questgeber patrouille zur rückendeckung","wer gibt diese quest"}},{q="Was ist Riptear?",a="Riptear ist eine abtrünnige Monstrosität, die dabei entdeckt wurde, wie sie durch die östlichen Lichtungen nahe dem Giftwebertal hinter den vorderen Verteidigungslinien streifte.",al={"wer ist riptear","was ist riptear","riptear lore"}},{q="Warum ist eine Monstrosität in der Nähe des Giftwebertals so alarmierend?",a="Monstrositäten sind gewaltige Konstrukte, deren Erschaffung dunkle Nekromantie und schwere Arbeit erfordert. Das stark befestigte Bollwerk unbemerkt zu passieren, sollte unmöglich sein, was auf einen alarmierenden Durchbruch oder einen unentdeckten Pfad hinter den Linien der Verlassenen hindeutet.",al={"warum ist riptear so wichtig","warum ist eine monstrosität hier gefährlich","durchbruch am bollwerk"}},{q="Wo ist die Bestie für gewöhnlich zu finden?",a="Sichtungen verorten Riptear in den Wäldern und Lichtungen des östlichen Tirisfal, in der Umgebung des Giftwebertals.",al={"wo ist riptear","riptear aufenthaltsort","wo man die monstrosität findet"}},{q="Welcher Beweis ist erforderlich, um die Patrouille abzuschließen?",a="Todeswache Linnea verlangt Reißers Herz, um zu überprüfen, ob die gewaltige Monstrosität endgültig zur Strecke gebracht wurde.",al={"was bringe ich linnea","gegenstand zur questabgabe","beweis für riptears tod"}},{q="Wer beaufsichtigt die Verteidigung des Bollwerks?",a="Die Quest nennt den Kommandanten des Bollwerks nicht. Todeswache Linnea untersteht ihrem Vorgesetzten, Exekutor Zygand in Brill, der ihre Belobigungen für Patrouillen erhält, welche die Geißel in Schach halten.",al={"wer befehligt das bollwerk","linneas vorgesetzter","exekutor zygand"}}},fp="17,285,24.457.0,21.441.1,39.121.0,16.124.0,53.248.0,33.117.0,44.112.0,40.189.0"}
P.entries["quest:99158"] = {n="Dawn in the Mountains",s="Dawn in the Mountains ist eine Quest, bei der eine Lieferung heiliger Kerzen zu Vater Gavin in der Nebelfichtenzuflucht gebracht werden muss. Als sanftmütiger Priester der Argentumdämmerung unterhält Gavin diesen Bergzufluchtsort, um erschöpfte Reisende zu heilen und zu trösten, anstatt mit Waffen Krieg zu führen.",h="Dawn in the Mountains ist eine Quest, bei der eine Lieferung heiliger Kerzen zu Vater Gavin in der...",kw={"argentumdämmerung","dawn in the mountains","vater gavin","heilige kerzen","nebelfichtenzuflucht","priester","zuflucht"},ang={["class:Priest"]="Vater Gavin verkörpert den sanfteren, wiederherstellenden Pfad des Priestertums und zieht es vor, sich um Reisende zu kümmern und Wunden zu versorgen, anstatt an vorderster Front der Argentumdämmerung Waffen zu führen.",["faction:Alliance"]="Die Bereitstellung von Vorräten für einen Zufluchtsort der Argentumdämmerung wie die Nebelfichtenzuflucht unterstützt die neutrale humanitäre Arbeit in umkämpftem und gefährlichem Berggelände.",["faction:Horde"]="Die Argentumdämmerung nimmt unabhängig von der Zugehörigkeit Hilfe an und bietet Zuflucht, was Außenposten wie jenen von Vater Gavin zu einem seltenen sicheren Hafen in der Wildnis macht."},sec={{t="Ein Zufluchtsort in den Gipfeln",b="Während viele innerhalb der Argentumdämmerung zu den Waffen greifen, um unheilige Schrecken aus Azeroth zu tilgen, wählen manche die sanftere Berufung des Lichts. Vater Gavin, ein Priester, der in der rauen Bergwildnis weilt, hat sich von der Klinge abgewandt, um sich ganz der Heilung der Leidenden und der Fürsorge für die Erschöpften zu widmen. Er nahm sich eines verlassenen Gebäudes an und baute es zur Nebelfichtenzuflucht aus – einem sicheren Rastplatz für Reisende, welche den Gefahren der Hochpässe trotzen."},{t="Kerzen für das Licht",b="Die Instandhaltung einer abgelegenen Zuflucht in den Bergen erfordert ständige Pflege und praktische Hingabe. Um sein geistliches Wirken aufrechtzuerhalten und die Lampen und Altäre brennend zu halten, ist Vater Gavin auf die Wohltätigkeit entfernter Verbündeter angewiesen. Eine Lieferung geweihter Kerzen stellt sicher, dass das Heiligtum inmitten der unbarmherzigen Wildnis ein Leuchtfeuer des Lichts, der Wärme und der Hoffnung bleibt."}},faq={{q="Wer ist Vater Gavin?",a="Vater Gavin ist ein der Argentumdämmerung angehörender Priester, der oben in den Bergen stationiert ist. Anders als viele in seinem heiligen Orden, die zu den Waffen gegen das Unheilige greifen, widmet sich Gavin vor allem der Heilung, dem Trost von Reisenden und der Bereitstellung von Unterkunft in der Nebelfichtenzuflucht.",al={"wer ist vater gavin","vater gavin geschichte","wer ist der priester bei den nebelfichten"}},{q="Was ist die Nebelfichtenzuflucht?",a="Die Nebelfichtenzuflucht ist ein von Vater Gavin errichteter Rastplatz für Bergreisende. Er renovierte ein altes Gebäude in der Wildnis, um einen friedlichen Zufluchtsort zu schaffen, an dem sich Wanderer erholen, ausruhen und Heilung empfangen können.",al={"was ist die nebelfichtenzuflucht","wo ist die nebelfichtenzuflucht","nebelfichtenzuflucht geschichte"}},{q="Was ist die Argentumdämmerung?",a="Die Argentumdämmerung ist ein hingebungsvoller heiliger Orden, der sich der Aufspürung und Vernichtung unheiliger und unnatürlicher Bedrohungen in ganz Azeroth verschrieben hat, während er jenen Beistand und Trost spendet, die in unruhigen Ländern ums Überleben kämpfen.",al={"was ist die argentumdämmerung","zweck der argentumdämmerung","wer ist die argentumdämmerung"}},{q="Warum benötigt Vater Gavin eine Lieferung heiliger Kerzen?",a="Die Kiste mit heiligen Kerzen soll Vater Gavins Vorräte in der Nebelfichtenzuflucht auffüllen. Im geistlichen Dienst und in abgelegenen Zufluchtsorten sind geweihte Kerzen unerlässlich für religiöse Riten, Gebete und die Beleuchtung der Zuflucht für erschöpfte Reisende.",al={"warum kerzen","zweck der heiligen kerzen","lieferung einer kiste mit kerzen"}},{q="Greift Vater Gavin wie andere Mitglieder der Argentumdämmerung zu den Waffen?",a="Vater Gavin zieht es vor, Reisende zu heilen und ihnen Schutz zu bieten, anstatt eine Waffe zu ergreifen. Während die Argentumdämmerung für ihren kriegerischen Kreuzzug gegen die Dunkelheit bekannt ist, dient Gavin dem Orden durch Mitgefühl, Gastfreundschaft und seelsorgerische Fürsorge.",al={"kämpft vater gavin","ist vater gavin ein kämpfer"}},{q="Was ist das Ziel der Quest Dawn in the Mountains?",a="Die Bitte ersucht einen Reisenden, der in die Berge aufbricht, eine Kiste mit heiligen Kerzen direkt zu Vater Gavin in die Nebelfichtenzuflucht zu tragen, um sein bescheidenes Bergheiligtum zu unterstützen.",al={"wer vergab diese quest","wohin führt dawn in the mountains"}}},fp="21,253,24.429.0,21.363.0,20.261.0,26.218.0,24.210.0,54.244.0,62.223.0,55.176.0"}
P.entries["quest:99159"] = {n="Finding Warmth",s="Finding Warmth ist eine bescheidene Besorgung, bei der es darum geht, eine einladende Feuerstelle mit Feuerholz zu versorgen. Da der Gastgeber mit anderen Pflichten beschäftigt ist, werden Reisende gebeten, Holzscheite zu sammeln, damit jede Seele, die Wärme sucht, Trost finden kann. Das Abschließen der Aufgabe hält das Feuer am Brennen und öffnet den Weg für weitere Aufgaben.",h="Finding Warmth ist eine bescheidene Besorgung, bei der es darum geht, eine einladende Feuerstelle mit...",kw={"finding warmth","feuerholz","feuerstelle","licht","wärme","holz"},sec={{t="Eine einladende Feuerstelle",b="Finding Warmth ist eine einfache Aufgabe, die übernommen wird, um ein einladendes Feuer zu unterhalten. Der Questgeber hält eine offene Feuerstelle bereit, um jede wandernde Seele zu wärmen, doch wachsende Verpflichtungen haben dazu geführt, dass er nicht mehr selbst Brennmaterial sammeln kann. Indem sie einspringen, um Feuerholz zu sammeln, stellen Reisende sicher, dass die Feuerstelle für jeden weiter brennt, der Schutz und Trost sucht."},{t="Das Schüren des Feuers",b="Nicht alles Holz, das aus der Umgebung beschafft wird, ist sofort zum Verbrennen bereit. Bei der Übergabe werden Stücke, die zu feucht oder nass sind, um Feuer zu fangen, beiseitegelegt, um richtig zu trocknen, während abgelagertes Holz die Flammen sofort nährt. Erfreut über die rechtzeitige Hilfe widmet sich der Gastgeber schnell anderen dringenden Angelegenheiten, die weiterhin Aufmerksamkeit erfordern."}},faq={{q="Worum geht es bei der Quest Finding Warmth?",a="Finding Warmth ist eine lokale Aufgabe, bei der ein Abenteurer gebeten wird, Feuerholz zu sammeln, um eine einladende Feuerstelle am Brennen zu halten. Der Questgeber kümmert sich gewöhnlich persönlich um das Feuer, ist jedoch mit anderen dringenden Aufgaben beschäftigt und bittet um Hilfe von außerhalb.",al={"finding warmth quest","was ist finding warmth","finding warmth feuerholz"}},{q="Warum wird das Feuerholz benötigt?",a="Das Feuerholz wird benötigt, um eine Feuerstelle zu befeuern, die offen gehalten wird, um vorbeikommende Reisende und Einheimische zu trösten und zu wärmen. Das Holzsammeln ist eine gewöhnliche Pflicht, die ins Hintertreffen geraten ist, da der Gastgeber mit anderen Pflichten beschäftigt war.",al={"warum holz benötigt wird","feuerholz finding warmth","feuerstelle feuerholz"}},{q="Was geschieht mit herbeigebrachtem nassem Feuerholz?",a="Einige gesammelte Holzscheite sind bei der Übergabe möglicherweise zu feucht oder nass, um sofort zu brennen. Der Questgeber legt die nassen Stücke beiseite, damit sie mit der Zeit austrocknen, während er das trockene Holz verwendet, um die Feuerstelle sofort anzuschüren.",al={"finding warmth nasses holz","feuchtes feuerholz"}},{q="Welche Art von Person bietet diese Aufgabe an?",a="Während die genaue Identität des Gastgebers nicht näher beschrieben wird, deutet sein Segen ‚Das Licht leite Euch bei Euren Aufgaben‘ auf eine Person hin, die im Glauben an oder der Verehrung für das Heilige Licht verwurzelt ist und eine offene Feuerstelle bietet, um jede Seele zu wärmen.",al={"wer gibt finding warmth","finding warmth licht leitet"}},{q="Gibt es nach dem Abschluss von Finding Warmth weitere Aufgaben?",a="Ja. Bei der Übergabe des Feuerholzes erwähnt der Gastgeber, dass er weitere Aufgaben zur Hand hat, die ein fähiges Paar Hände erfordern, wenn der Reisende bereit ist, weiter zu helfen.",al={"weitere quests nach finding warmth","finding warmth folgequest"}},{q="Wer ist an dieser Feuerstelle willkommen?",a="Der Gastgeber hält seine Feuerstelle am Brennen, um jedem Durchreisenden Zuflucht, Trost und Wärme zu bieten, der eine Auszeit von der Kälte oder mühseligen Reisen benötigt.",al={"feuerstelle offene seele","offene feuerstelle finding warmth"}}},fp="14,309,18.337.0,16.324.0,39.254.0,27.200.0,40.195.0,37.219.0,53.160.0,30.157.0"}
P.entries["quest:99160"] = {n="Rime's Wrath",s="Rime's Wrath ist eine Quest, die sich darauf konzentriert, einen gefährlichen Ausbruch niederer Eiselementare einzudämmen. Da Methoden zur friedlichen Besänftigung der aggressiven Frostgeister unbekannt waren, wurde ihre Vernichtung notwendig, um die Sicherheit des Gebiets zu gewährleisten.",h="Rime's Wrath ist eine Quest, die sich darauf konzentriert, einen gefährlichen Ausbruch niederer Eiselementare...",kw={"elementare","frost","eiselementare","niedere eiselementare","besänftigen","rime's wrath","rimes wrath"},ang={["class:Mage"]="Frostmagier studieren die reine Beschwörung und Formung von Eismagie, was wilde niedere Eiselementare zu einer faszinierenden, wenn auch unbändigen Demonstration elementarer Kräfte macht.",["class:Shaman"]="Schamanen versuchen, Elementargeister zu verstehen und mit ihnen in Einklang zu treten, doch diese feindseligen Eiseinheiten ließen sich nicht friedlich stimmen und mussten mit Gewalt bezwungen werden."},sec={{t="Eine bittere Manifestation",b="Rime's Wrath beinhaltet den Umgang mit einer lokalen Häufung niederer Eiselementare. Diese Geister beißenden Frosts und eisiger Kälte sind zu einer akuten Gefahr in der Gegend geworden, was ein schnelles Eingreifen erforderlich macht, bevor sich ihre Kälte weiter ausbreitet oder Passanten schadet. Statt eines koordinierten Angriffs handelt es sich bei der Reaktion um eine Eindämmungsmaßnahme gegen wilde, feindselige Elementarmanifestationen."},{t="Jenseits der Besänftigung",b="Während das bevorzugte Ergebnis darin bestanden hätte, die aufgewühlten Frostgeister zu beruhigen, war das zu ihrer Besänftigung erforderliche Wissen unerreichbar. Da keine praktischen Mittel zur Ruhigstellung zur Verfügung standen und die Geister zunehmend gefährlicher wurden, blieb als einzige Wahl, sie zu vernichten, um das umliegende Territorium zu schützen."}},faq={{q="Was ist Rime's Wrath?",a="Rime's Wrath ist eine Aufgabe, die die Vernichtung niederer Eiselementare erfordert, welche eine unmittelbare Bedrohung darstellen. Da friedliche Methoden zur Besänftigung dieser aufgewühlten Geister unbekannt oder nicht verfügbar waren, wurde direkte Gewalt zur einzigen Option, um die Sicherheit aufrechtzuerhalten.",al={"was ist rimes wrath","quest rimes wrath","rimes wrath übersicht"}},{q="Warum müssen die niederen Eiselementare vernichtet werden?",a="Die niederen Eiselementare wurden zu unberechenbar und gefährlich, um sie unkontrolliert zu lassen. Zwar wäre eine friedliche Besänftigung bevorzugt worden, doch fehlte das Wissen, um sie zu beruhigen, sodass ihre Vernichtung als notwendige Maßnahme übrig blieb.",al={"warum eiselementare töten","warum sie bekämpfen","können die elementare nicht beruhigt werden"}},{q="Wer verlangt die Vernichtung der Elementare?",a="Die Quest wird von jemandem geleitet, der um Eindämmung besorgt ist und gehofft hatte, die Geister friedlich zu stimmen. Da das arkane oder spirituelle Wissen fehlte, das zu ihrer Besänftigung erforderlich gewesen wäre, wandte man sich stattdessen an Abenteurer, um die Bedrohung zu neutralisieren.",al={"wer vergibt rimes wrath","wer will die elementare tot sehen","wer ist der questgeber"}},{q="Hätte man friedlich mit den Elementaren umgehen können?",a="Der Questgeber merkt an, dass ihre Besänftigung seine Fähigkeiten überstieg. Elementargeister können manchmal ausgeglichen oder besänftigt werden, aber ohne die richtige Fachkenntnis ließ ihre Aggression keine andere Wahl als den Kampf.",al={"können eiselementare beruhigt werden","eiselementare besänftigen","warum elementare nicht beruhigen"}},{q="Was für Kreaturen sind niedere Eiselementare?",a="Niedere Eiselementare sind unberechenbare Manifestationen elementaren Frosts. Obwohl sie als niedere Geister eingestuft werden, machen ihre umgebende Kälte und ihr aggressives Wesen sie zu einer Gefahr für Reisende und einheimische Bewohner, wenn man sie frei umherstreifen lässt.",al={"was sind niedere eiselementare","gefahr durch eiselementare","wie stark sind niedere eiselementare"}},{q="Was ist das Ergebnis des Vorgehens gegen die Elementare?",a="Sobald zehn niedere Eiselementare besiegt sind, ist die unmittelbare Gefahr gebannt. Der Questgeber bedauert, dass Gewalt notwendig war, räumt jedoch ein, dass es schlicht zu riskant gewesen wäre, sie unkontrolliert zu lassen.",al={"was passiert nach rimes wrath","abschluss von rimes wrath"}}},fp="12,226,22.367.0,16.307.0,21.246.0,53.217.0,47.232.0,53.212.0,48.224.0,51.192.0"}
P.entries["quest:99161"] = {n="Rime's Wrath",s="Nach einem Erdrutsch tauchte ein ungewöhnlich großer Elementar namens Avala auf und begann, unberechenbare Wetterumschwünge sowie sekundäre Erdrutsche auszulösen. Ein Beobachter beauftragt Abenteurer damit, den Elementar zur Strecke zu bringen und seinen Kern zu erbeuten, um das Gebiet zu sichern. Der Sieg über die Kreatur stellt die Stabilität an den Berghängen wieder her und schützt Reisende vor tödlichen Gefahren des Winters.",h="Nach einem Erdrutsch tauchte ein ungewöhnlich großer Elementar namens Avala auf und begann, unberechenbare...",kw={"avala","avalas kern","elementar","elementarkern","rime's wrath","erdrutsch","wetter","winter"},ang={["class:Paladin"]="Paladine halten die Pflicht aufrecht, Reisende und schutzlose einfache Bürger vor plötzlichen Katastrophen zu bewahren. Der Questgeber ruft beim Abschluss der Quest in Dankbarkeit für das Abwenden unnötiger Tode den Segen des Lichts herab.",["class:Shaman"]="Schamanen erkennen die Gefahr, die von ungezähmten Elementaren wie Avala ausgeht, deren turbulente Anwesenheit das lokale Wetter verzerrt und den Stein erschüttert. Das Beschwichtigen solch aufgewühlter Wesen ist von entscheidender Bedeutung, um die Harmonie zwischen den Elementen wiederherzustellen."},sec={{t="In den Nachwehen des Erdrutsches",b="Die Unruhen begannen, als ein plötzlicher Erdrutsch den Gebirgspass destabilisierte und den Weg für elementare Umtriebe öffnete. Unter den hervorgekommenen Kreaturen stach ein bestimmter Elementar hervor, der seine Artgenossen an schierer Größe und roher Kraft überragte. Von dem wachsamen Questgeber mit dem formlosen Beinamen „Avala“ bedacht, ist diese mächtige Entität nicht bloß eine furchteinflößende Erscheinung – sie schürt unmittelbar lokale atmosphärische Turbulenzen und destabilisiert die umliegenden Klippen. Ihre Anwesenheit stellt eine akute Gefahr für jeden dar, der dieses Gebiet zu durchqueren versucht, da der instabile Boden und plötzliche winterliche Kälteeinbrüche gewöhnliche Reisen tödlich machen."},{t="Avala bezwingen",b="Angesichts der wachsenden Gefahr von Avalas Einfluss auf das Terrain erging ein Aufruf, die Bestie zu eliminieren, bevor weitere Einstürze Menschenleben forderten. Das Erschlagen der Kreatur erfordert es, sich sowohl ihrer elementaren Wildheit als auch den rauen Bedingungen zu stellen, die sie erzeugt, und gipfelt in der Bergung ihres Kerns als endgültigem Beweis ihres Ablebens. Ist Avala bezwungen und sein belebtes Herz gesichert, klingen die heftigen Wetterumschwünge ab, was den umliegenden Gebirgspässen ein gewisses Maß an Sicherheit zurückgibt und künftige Reisende vor unnötigen Katastrophen bewahrt."}},faq={{q="Was ist Rime's Wrath?",a="Rime's Wrath ist eine Quest, die Abenteurer damit beauftragt, Avala zu eliminieren – einen großen und gefährlichen Elementar, der sich nach einem plötzlichen Erdrutsch manifestierte. Indem Abenteurer den Elementar zur Strecke bringen und seinen Kern bergen, setzen sie den unberechenbaren Wetterstörungen und wiederkehrenden Erdrutschen ein Ende, die Reisende auf dem Gebirgspass bedrohen.",al={"rimes wrath","was ist rimes wrath","quest rime's wrath"}},{q="Wer oder was ist Avala?",a="Avala ist ein besonders großer Elementar, der in den Nachwehen eines schweren Erdrutsches aufgetaucht ist. Avala ist größer als andere Elementare seiner Art und sorgt aktiv für plötzliche Wetterumschwünge, eisige Kälte sowie gefährliche sekundäre Erderschütterungen in dem Gebiet. Der Name „Avala“ wurde ihm von dem Beobachter verliehen, der den Pass überwacht.",al={"was ist avala","wer ist avala","avala elementar"}},{q="Warum muss Avala vernichtet werden?",a="Avalas anhaltende Präsenz verursacht unvorhersehbare Wetterstörungen und kleinere Erdrutsche, die die umliegenden Hänge destabilisieren. Bleibt der übernatürliche Einfluss des Elementars auf das winterliche Klima und das Terrain ungebremst, drohen weitere Einbrüche und vermeidbare Todesfälle unter Reisenden, die den Gebirgspass durchqueren.",al={"warum avala toeten","grund avala zu toeten","warum avala vernichten"}},{q="Welcher Beweis wird benötigt, um Rime's Wrath abzuschließen?",a="Abenteurer müssen den Kern von Avala an sich bringen, nachdem sie die Kreatur im Kampf besiegt haben. Das Überbringen dieses Elementarkerns an den Questgeber bestätigt, dass die Bedrohung vollständig beseitigt wurde und das regionale Klima sich wieder normalisieren kann.",al={"avala beweis","welcher gegenstand wird erbeutet","avala kern beweis"}},{q="Wie ist Avala erstmals erschienen?",a="Avala tauchte infolge eines anfänglichen Erdrutsches auf, der die Region erschütterte. Die Kreatur erschien in den Nachwehen des Zusammenbruchs an der Seite anderer Elementare und entwickelte sich aufgrund ihrer Größe und Elementarkraft rasch zum markantesten und gefährlichsten Wesen unter ihnen.",al={"woher kam avala","avala herkunft","wie ist avala erschienen"}},{q="Wer bietet die Quest Rime's Wrath an?",a="Die Quest wird von einem einheimischen Beobachter angeboten, der nahe dem gefährlichen Gebirgspass stationiert ist und den Erdrutsch sowie das Auftauchen der Elementare genau beobachtet hat. Indem dieser Wächter beim Abschluss den Segen des Heiligen Lichts herabruft, versucht er unnötige Tode zu verhindern, indem er fähige Streiter für die Beseitigung von Avala anheuert.",al={"wer vergibt rimes wrath","questgeber rimes wrath","questgeber von rimes wrath"}},{q="Was passiert, nachdem Avala besiegt wurde?",a="Sobald Avala getötet und sein Kern zurückgebracht wurde, lassen die schweren Wetterumschwünge und lokalen Erschütterungen nach, die durch die Anwesenheit der Kreatur ausgelöst wurden. Der Questgeber spendet einen Segen des Lichts sowie eine Belohnung und merkt an, dass das Gebiet für künftige Reisende erheblich sicherer geworden ist.",al={"was passiert nach avalas tod","abschluss von rimes wrath","nach rimes wrath"}}},fp="12,362,25.601.0,14.552.0,21.328.0,21.309.0,36.333.0,46.235.0,27.265.0,34.315.0,37.275.0"}
P.entries["quest:99162"] = {n="Treacherous Cold",s="Treacherous Cold ist eine Bergungsaktion in den tückischen Höhen von Dun Morogh nach verheerenden Schnee- und Eislawinen. Abenteurer werden damit beauftragt, die beschrifteten Gewehre gefallener Gebirgsjäger aus Eisenschmiede zu bergen, um sicherzustellen, dass ihre Identität bestätigt wird und ihre Familien Gewissheit erhalten.",h="Treacherous Cold ist eine Bergungsaktion in den tückischen Höhen von Dun Morogh nach verheerenden Schnee- und...",kw={"lawine","dun morogh","eisenschmiede","gebirgsjäger","gewehre","schneelawine","treacherous cold"},ang={["class:Hunter"]="Gebirgsjäger verlassen sich in der eisigen Wildnis auf ihre treuen Gewehre und schnitzen ihre Namen in die Holzschäfte, damit ihre Identität und ihre Taten niemals in Vergessenheit geraten.",["faction:Alliance"]="Die Bergung der Ausrüstung gefallener Gebirgsjäger stellt sicher, dass Eisenschmiede Familien Gewissheit geben kann, die ihre Angehörigen opfern, um die Bergstraßen zu schützen.",["race:Dwarf"]="Die Gipfel von Dun Morogh sind die Heimat der Zwerge, doch selbst erfahrene Gebirgsjäger können in den hohen Pässen plötzlichen Lawinen und feindseligen Elementen zum Opfer fallen."},sec={{t="Gefahren der Gipfel",b="Die zerklüfteten, verschneiten Felsen von Dun Morogh stellen für Reisende und Soldaten gleichermaßen eine ständige Gefahr dar. Selbst die abgehärteten Gebirgsjäger aus Eisenschmiede können von plötzlichen Lawinen und herabstürzenden Eisplatten überrascht werden, wobei unerfahrene Rekruten mit ihrem Leben bezahlen, wenn der Winter ohne Vorwarnung zuschlägt."},{t="Düstere Bergung",b="Wenn Bergrutsche Patrouillen verschütten, wird die Suche im gefährlichen Gelände zu einem düsteren Wettlauf gegen die Zeit. Die erhöhte Elementaraktivität in der gesamten Region macht gründliche Rettungsexpeditionen gefährlich und zwingt die Späher dazu, mutige Wanderer zu rekrutieren, um die Schneewehen nach gefallenen Gebirgsjägern abzusuchen und ihre beschrifteten Gewehre zu bergen, bevor der Schnee sie für immer verdeckt."},{t="Beschriftete Schäfte",b="Jeder Gebirgsjäger aus Eisenschmiede graviert seinen Namen in den Schaft seines Gewehrs, was unter den härtesten Bedingungen als dauerhaftes Erkennungsmerkmal dient. Indem diese Schusswaffen aus den Schneewehen geborgen werden, stellen die Sucher sicher, dass die Gefallenen identifiziert und ihre ehrenvollen Dienste von ihren Familien daheim in Eisenschmiede gewürdigt werden können."}},faq={{q="Was ist Treacherous Cold?",a="Treacherous Cold ist eine Aufgabe, bei der es darum geht, die schneeverwehten Pässe von Dun Morogh nach Gebirgsjägern abzusuchen, die von plötzlichen Lawinen überrascht wurden, und ihre Dienstgewehre zu bergen.",al={"was ist treacherous cold","treacherous cold quest"}},{q="Warum werden die Gewehre der Gebirgsjäger eingesammelt?",a="Gebirgsjäger gravieren ihre Namen direkt in die Schäfte ihrer Gewehre ein. In den eisigen Schneewehen, in denen Leichen begraben oder unauffindbar sein können, ermöglicht die Bergung ihrer Waffen Eisenschmiede, die Gefallenen eindeutig zu identifizieren und ihre Familien zu benachrichtigen.",al={"warum gewehre sammeln","gebirgsjägergewehre","warum werden ihre gewehre gebraucht"}},{q="Wer geht im Schnee verloren?",a="Unerfahrene Gebirgsjäger, die in Dun Morogh patrouillieren, sind besonders anfällig für plötzliche Lawinen, herabstürzendes Eis und extreme Wetterbedingungen auf den hohen Berggipfeln.",al={"wer sind die opfer","wer verirrt sich in dun morogh"}},{q="Warum wurde die Suche nicht bereits durchgeführt?",a="Während der Questgeber nach einem Erdrutsch typischerweise Rettungs- und Bergungsaktionen durchführt, haben die jüngsten Elementarunruhen in Dun Morogh das Vordringen tief in die Bergpässe viel zu gefährlich gemacht, um es allein zu bewältigen.",al={"warum kann der questgeber nicht suchen","warum wird ein abenteurer gebraucht"}},{q="Was geschieht mit den Gewehren, sobald sie geborgen sind?",a="Geborgene Gewehre werden gesammelt und zurück in die Stadt Eisenschmiede geschickt, wo die Behörden sicherstellen, dass die persönlichen Waffen den Familien der gefallenen Gebirgsjäger übergeben werden.",al={"wohin kommen die gewehre","was geschieht mit den geborgenen gewehren"}},{q="Was macht die hohen Pässe von Dun Morogh so gefährlich?",a="Die Höhen von Dun Morogh sind geprägt von strenger Kälte, blendenden Lawinen und instabilen Klippen. In Verbindung mit unruhiger Elementaraktivität können selbst ausgebildete Zwergenpatrouillen der Umgebung schnell zum Opfer fallen.",al={"wie gefährlich ist dun morogh","gefahren in dun morogh"}}},fp="16,294,19.299.0,13.352.0,16.314.0,25.162.0,43.245.0,30.153.0,45.210.0,42.172.0,54.203.0"}
P.entries["quest:99260"] = {n="Fillion's Mission",s="Fillion's Mission folgt den Nachwirkungen eines Aufklärungseinsatzes zur Kartierung von Elementarströmungen bei den Menhiren des Rundblicks. Die gesammelten Daten sollten dazu dienen, sichere Navigationsrouten für Skycutter-Schiffe zwischen dem Himmelswall und Azeroth zu kartieren, doch die Kampfunfähigkeit des Landvermessers gefährdet das gesamte Unterfangen.",h="Fillion's Mission folgt den Nachwirkungen eines Aufklärungseinsatzes zur Kartierung von Elementarströmungen...",kw={"elaadrin evengale","elementarebene","fillion","die menhire der warte","skycutter","der himmelswall","valanaar","windformer"},ang={["class:Mage"]="Arkanisten, die den Plänen von The Supreme Magister folgen, werden die feinen magischen Berechnungen zu schätzen wissen, die erforderlich sind, um Skycutter-Schiffe durch Ebenenturbulenzen zu steuern.",["race:Skyborne"]="Die Quest berührt direkt den Kampf Eures Volkes, inmitten von Spannungen zwischen den Fraktionen sichere Reiserouten zwischen dem Himmelswall und Azeroth einzurichten."},sec={{t="Ein gefährlicher Auftrag",b="Fillion wurde zu den Menhiren des Rundblicks entsandt, um entscheidende Messwerte über elementare Energieströmungen zu sammeln. Diese Messungen bilden die Grundlage für Berechnungen, die erforderlich sind, um Skycutter-Schiffe zwischen dem Himmelswall und Azeroth zu steuern. Nach einer Tortur, die seine Rettung erforderte, sieht sich Fillion außerstande, seine Aufgabe zu vollenden, und die lebenswichtigen Daten gelten als verloren. Da er seine Mission in seinem verwundeten Zustand nicht fortsetzen kann, weist er seinen Retter an, Bericht bei The Supreme Magister zu erstatten."},{t="Ebenenkonflikt in Valanaar",b="In der Siedlung Valanaar nimmt Supreme Magister Elaadrin Evengale den Bericht über Fillions Überleben mit Erleichterung auf, beklagt jedoch die verlorene Forschung. Ohne verlässliche Navigationsdaten steht die Eröffnung sicherer Durchgangsrouten über die Elementarebene vor schweren Komplikationen. Die Lage wird durch Berichte weiter verschärft, wonach rivalisierende Windformer ihre eigenen Mittel für den Ebenentransfer erlangt haben, diese jedoch nicht teilen wollen und fraktionelle Geheimhaltung über das Gemeinwohl stellen."}},faq={{q="Wer ist Fillion?",a="Fillion ist ein Gesandter oder Späher, der von The Supreme Magister geschickt wurde, um entscheidende Messwerte über elementare Energieflüsse von den Menhiren des Rundblicks zu sammeln. Nachdem er von einem Abenteurer gerettet wurde, ist er weiterhin zu geschwächt, um seinen ursprünglichen Auftrag abzuschließen.",al={"wer ist fillion","fillion hintergrundgeschichte","fillion wow"}},{q="Wer ist Supreme Magister Elaadrin Evengale?",a="Elaadrin Evengale ist The Supreme Magister mit Wohnsitz in Valanaar. Er leitet die Bemühungen, die Elementarebene sicher zu durchqueren, und koordiniert die Beschaffung von Ebenendaten zur Sicherung von Reisen zwischen dem Himmelswall und Azeroth.",al={"wer ist the supreme magister","elaadrin evengale","wer ist elaadrin"}},{q="Warum waren Fillions Daten so wichtig?",a="Die Daten erfassen Strömungen elementarer Energie, die bei den Menhiren des Rundblicks gesammelt wurden. Sie sind entscheidend für die mathematischen Berechnungen, die erforderlich sind, um Skycutter-Schiffe sicher und ohne Zerstörung durch die Elementarebene nach Azeroth zu navigieren.",al={"warum sind daten wichtig","welche daten fillion verlor","elementardaten himmelswall"}},{q="Wer sind die Windformer?",a="Die Windformer sind eine Fraktion, die Berichten zufolge ihre eigene Methode des Ebenentransfers gesichert hat. Laut Supreme Magister Evengale hüten sie dieses Geheimnis aus dogmatischer Hybris eifersüchtig, anstatt es zum Wohle ihres Volkes zu teilen.",al={"wer sind die windformer","windformer lore","windformer rivalen"}},{q="Was sind Skycutter?",a="Skycutter sind spezialisierte Schiffe, die dafür konstruiert wurden, durch die Elementarebenen zu fliegen. Sie zu führen erfordert präzise Messwerte über elementare Energieflüsse; andernfalls enden Versuche, sie zwischen dem Himmelswall und Azeroth zu steuern, in einer Katastrophe.",al={"was sind skycutter","skycutter schiff","skycutter"}},{q="Wer sind die Al'Aketh?",a="Die Al'Aketh sind eine gegnerische oder verachtete Fraktion, auf die sich Supreme Magister Evengale bezieht. Er vergleicht das egoistische und dogmatische Verhalten der Windformer direkt mit ihnen.",al={"wer sind die al'aketh","al'aketh","al'aketh lore"}}},fp="17,310,21.471.0,25.464.1,15.246.0,42.212.0,36.240.0,24.247.0,20.233.0,21.177.0"}
P.entries["quest:993"] = {n="Ein verirrter Meister",s="Nachdem Ihr feine Moonstalker-Pelze gesammelt habt, tragt Ihr den fertigen Enchanted Moonstalker Cloak in die Wildnis der Dunkelküste, um den vermissten Nachtelfen Volcor zu finden. Geführt von seinem treuen weißen Bären Grimclaw müsst Ihr den verwundeten Späher aufspüren, bevor feindselige Furbolgs ihn zur Strecke bringen.",h="Nachdem Ihr feine Moonstalker-Pelze gesammelt habt, tragt Ihr den fertigen Enchanted Moonstalker Cloak in die...",kw={"auberdine","dunkelküste","furbolg","grimclaw","moonstalker cloak","nightsaber","terenthis","volcor"},ang={["class:Hunter"]="Zu sehen, wie Grimclaw die Straße entlangläuft, um Hilfe für Volcor zu finden, unterstreicht die bemerkenswerte Intelligenz und Hingabe gut ausgebildeter Bestien Kalimdors.",["faction:Alliance"]="Auberdine ist auf Späher wie Volcor angewiesen, um die zunehmende Verderbnis der Furbolgstämme der Dunkelküste zu überwachen, was seine Rettung zu einer entscheidenden Priorität für den Außenposten macht.",["race:NightElf"]="Das Band zwischen Nachtelfenspähern und ihren tierischen Begleitern zeigt sich hier in Grimclaws unerschütterlicher Loyalität bei der Suche nach Hilfe für seinen Meister Volcor."},sec={{t="Ein Leuchtfeuer im Wald",b="Nachdem Terenthis in Auberdine den Enchanted Moonstalker Cloak gewoben hat, beginnt die Suche nach dem vermissten Späher Volcor ernsthaft. Sein Bärenbegleiter Grimclaw ist auf die Straße südlich der Siedlung zurückgekehrt und hält Ausschau nach jedem von Terenthis gesandten Verbündeten. Indem sie der treuen Bestie einen vertrauten Gruß entbieten, werden Reisende direkt abseits der ausgetretenen Pfade zu der Höhle geführt, in der sich Volcor versteckt hält."},{t="Versteckt im Dunkeln",b="Volcor suchte Zuflucht in einer Höhle, nachdem er durch die Hände der örtlichen verderbten Furbolgs schwere Verletzungen erlitten hatte. Gefangen und blutend musste er sich ganz auf Verstohlenheit und Grimclaws Scharfsinn verlassen, um nicht überrannt zu werden. Der verzauberte Umhang verschafft ihm die nötige Tarnung und Hoffnung, um seine Evakuierung zu planen, auch wenn seine Wunden ihn für den Rückweg nach Auberdine in einem bedenklichen Zustand belassen."}},faq={{q="Wer ist Volcor?",a="Volcor ist ein Nachtelfenspäher mit Stützpunkt an der Dunkelküste, der verschwand, als er sich in die Nähe feindseliger Furbolglager wagte. Er wurde bei einer Konfrontation schwer verwundet und schaffte es, in eine nahe gelegene Höhle zu kriechen, während sein Bärenbegleiter Grimclaw Hilfe suchte.",al={"volcor lore","wer ist der verlorene meister"}},{q="Wie findet Ihr Volcors Versteck?",a="Grimclaw wartet an der Straße südlich von Auberdine. Wenn Ihr der Bestie zuwinkt, weiß sie, dass Ihr der von Terenthis gesandte Helfer seid, was Grimclaw dazu veranlasst, direkt zu der abgelegenen Höhle zu laufen, in der Volcor seine Verletzungen pflegt.",al={"wo ist volcor","volcors höhle finden","wie man grimclaw folgt"}},{q="Was ist der Zweck des Enchanted Moonstalker Cloak?",a="Terenthis verzauberte den aus feinen Moonstalker-Pelzen hergestellten Umhang, um kurze, wirkungsvolle magische Verstohlenheit zu gewähren. Seine Magie lässt Euch ungehindert von den Kreaturen der Dunkelküste wandeln, während Ihr nach Volcor sucht, und der Umhang wird ihm anschließend übergeben.",al={"moonstalker cloak","umhangmagie"}},{q="Wer griff Volcor an?",a="Volcor wurde von den verderbten Furbolgstämmen überfallen und verwundet, die die Dunkelküste durchstreifen. Obwohl es ihm gelang, dem sofortigen Abschlachten zu entgehen, hinderten seine Verletzungen ihn daran, die Reise zurück nach Auberdine ohne Hilfe anzutreten.",al={"wer verletzte volcor","warum blutet volcor"}},{q="Was geschieht nach dem Auffinden von Volcor?",a="Sobald Volcor den verzauberten Umhang erhält, schöpft er Atem und bittet um Eure Hilfe bei der Flucht aus der Wildnis. Dabei stellt er Euch vor die Wahl, ihn entweder durch vorsichtige Verstohlenheit hinauszugeleiten oder sich mit roher Gewalt einen Weg durch die Furbolgs zu bahnen.",al={"volcor nächste quest","nach ein verirrter meister"}}},fx={["49342a22"]={q="Warum möchte Terenthis Volcor so dringend finden?",a="Terenthis befürchtet, dass seinem Nachtelfenkollegen die Zeit davonläuft. Volcor wurde von korrumpierten Furbolgs überfallen, und da nur der treue Bär Grimclaw zurückkehrte, um um Hilfe zu flehen, weiß Terenthis, dass Volcor alleine im Versteck nicht lange überleben kann. Nachdem er den verzauberten Umhang fertiggestellt hat, um dessen Duft und Präsenz zu tarnen, muss Terenthis Euch dazu bringen, Volcor zu erreichen, bevor die Furbolgs ihn jagen oder seine Verletzungen ihn fordern.",al={"terenthis motiv","warum volcor retten","warum kümmert sich terenthis um volcor"}}},fp="13,277,21.399.0,18.402.1,14.248.0,37.223.0,55.230.0,20.211.0,34.243.1"}
P.entries["quest:994"] = {n="Flucht durch Gewalt",s="„Flucht durch Gewalt“ ist eine Quest der Allianz an der Dunkelküste, bei der The Adventurer Volcor dabei hilft, die umgebenden Bedrohungen im direkten Kampf zu durchbrechen. Nachdem er sich an den Gefahren der Wildnis vorbeigekämpft hat, um die Straße zu erreichen und wieder mit seinem treuen Gefährten Grimclaw vereint zu sein, berichtet der Spieler Terenthis in Auberdine von Volcors sicherer Flucht.",h="„Flucht durch Gewalt“ ist eine Quest der Allianz an der Dunkelküste, bei der The Adventurer Volcor dabei...",kw={"auberdine","dunkelküste","eskorte","grimclaw","selarin","terenthis","volcor"},ang={["faction:Alliance"]="Die Unterstützung lokaler Kundschafter vertieft das Bündnis zwischen der jungen Allianz und den Nachtelfen und beweist den Wert der Fraktion bei der Sicherung der nördlichen Grenze von Kalimdor.",["race:NightElf"]="Die Rettung von Kundschaftern wie Volcor ist überlebenswichtig für den unsicheren Einfluss der Kaldorei auf die Dunkelküste, wo wilde Bestien, Verderbnis und Eindringlinge von außerhalb ihre uralten Wälder bedrohen."},sec={{t="Ein direkter Ausweg",b="Wenn man in der gefährlichen Wildnis der Dunkelküste gestrandet ist, ist unbemerktes Bewegen nicht immer der gewählte Pfad. Angesichts der Gefahr entscheidet sich der Nachtelf Volcor für eine kompromisslose Strategie: Er schlägt sich direkt durch die umgebenden feindseligen Kreaturen, um Sicherheit zu erreichen. Anstatt zu versuchen, ungesehen zu entkommen, verlässt sich Volcor auf seine Kampfkraft, um sich eine Schneise direkt hinab zur Hauptstraße zu bahnen."},{t="Wiedersehen auf der Straße",b="Das sichere Erreichen der Hauptstraße ermöglicht es Volcor, sich wieder mit Grimclaw zu vereinen, seinem treuen Bärengefährten, der am Wegesrand gewartet hat. Da ihre Flucht gesichert ist, bereitet sich Volcor auf seine nächste Reise vor und drängt The Adventurer gleichzeitig dazu, Terenthis in Auberdine direkt Bericht zu erstatten. Das Überbringen der Nachricht von Volcors Sicherheit beruhigt die Führung der Nachtelfen und weckt sogleich die Aufmerksamkeit von Schildwache Selarin, was auf tiefere Probleme hindeutet, die sich südlich im Eschental zusammenbrauen."}},faq={{q="Wer ist Volcor?",a="Volcor ist ein Kundschafter oder Waldläufer der Nachtelfen an der Dunkelküste, der zusammen mit seinem Gefährten Grimclaw verschwunden war. Nachdem er von Abenteurern ausfindig gemacht wurde, die im Auftrag von Terenthis suchen, benötigt er Hilfe bei der Flucht vor feindseligen Wildtieren und gefährlichem Terrain.",al={"volcor identität","wer ist volcor","volcor dunkelküste"}},{q="Wer ist Grimclaw?",a="Grimclaw ist Volcors treuer Bärengefährte. Während Volcors Gefangenschaft blieb Grimclaw in der Nähe der Straße getrennt von ihm zurück und diente als markanter Treffpunkt für Volcors Flucht.",al={"grimclaw","volcor bär","volcor begleiter"}},{q="Warum liegt Terenthis Volcors Rückkehr am Herzen?",a="Terenthis koordiniert die Bewegungen der Kundschafter und die lokalen Verteidigungsbemühungen von Auberdine aus. Das Aufspüren verschollener Verbündeter und die Einschätzung von Bedrohungen entlang der Küstenlinie sind entscheidend, um die Kontrolle der Nachtelfen über die sich rasch destabilisierende Dunkelküste aufrechtzuerhalten.",al={"terenthis volcor","warum volcor helfen","terenthis quest"}},{q="Was geschieht nach Abschluss dieser Quest?",a="Meldet Terenthis in Auberdine Volcors sichere Reise. Die Reihe führt dann zu 'Marsch ins Eschental'.",al={"nach flucht durch gewalt","was kommt als nächstes","nächste quest nach volcor"}},{q="Gibt es einen alternativen Weg, Volcors Eskorte abzuschließen?",a="Ja. Bei der Rettung von Volcor haben Abenteurer die Wahl bei der Vorgehensweise: Sie können sich in „Flucht durch Gewalt“ frontal den Weg freikämpfen oder ihn heimlich im Verborgenen an der Gefahr vorbeiführen.",al={"flucht durch gewalt alternative","escape through stealth","volcor entscheidungen"}},{q="Wohin führt diese Quest in der übergeordneten Handlung?",a="Die Sicherung von Volcors Überleben dient als Brücke zwischen den lokalen Konflikten an der Dunkelküste und der größeren regionalen Verteidigung der Länder der Nachtelfen und eröffnet direkt Aufträge im Eschental.",al={"volcor handlungsstrang","questreihe dunkelküste nach eschental"}}},fx={["8bb9ddbb"]={q="Warum möchte Volcor sich freikämpfen?",a="Volcor war zu lange in der Wildnis der Dunkelküste fernab seines Gefährten Grimclaw gefangen und gefährdet. Nachdem er beschlossen hat, direkt auszubrechen, anstatt sich wegzuschleichen, ist er entschlossen, sich einen Weg durch alle Feinde zu bahnen, die den Weg zur Straße versperren. Sein einziger Fokus liegt darauf, Sicherheit zu erreichen und sich wieder mit seinem treuen Bären zu vereinen, bevor er zurück nach Auberdine berichtet.",al={"volcor motiv","warum flucht durch gewalt","warum will volcor das"}},["365007a7"]={q="Warum benötigt Volcor Eure Hilfe bei der Flucht?",a="Volcor ist von Grimclaw getrennt und in der Wildnis von feindlichen Bedrohungen umgeben. Allein und schutzlos ist der Durchbruch durch die Wildnis mit roher Gewalt mit immensem Risiko verbunden. Mit Eurer kämpferischen Unterstützung sind seine Überlebenschancen auf dem Weg zur Sicherheit der Hauptstraße weitaus höher, als wenn er versuchen würde, sich allein freizukämpfen.",al={"warum braucht volcor mich","warum kann volcor nicht allein entkommen","warum volcor helfen"}}},fp="20,323,16.372.0,19.463.1,14.245.0,16.175.0,46.236.0,41.98.1,52.179.0,52.188.1"}
P.entries["quest:99411"] = {n="Kyle's Gone Missing!",s="Kyle's Gone Missing! ist eine lokale Quest im Dorf der Bluthufe, bei der Ahab Wheathoof vorbeiziehende Abenteurer bittet, seinen eigensinnigen Hund Kyle the Frenzied zu finden. Das Füttern des hungrigen Welpen mit einem Stück zartem Schreiterfleisch beruhigt sein Gemüt und sichert seine wohlbehaltene Rückkehr nach Hause.",h="Kyle's Gone Missing!",kw={"ahab wheathoof","dorf der bluthufe","kyle","kyle the frenzied","kyle's gone missing!","mulgore","plainstrider","zartes schreiterfleisch"},ang={["faction:Horde"]="Den Dorfbewohnern von Bluthuf bei alltäglichen Angelegenheiten beizustehen, stärkt die Beziehungen zu den Shu'halo, während sie sich niederlassen und ihre Heimat verteidigen.",["race:Tauren"]="Ahab Wheathoof ist ein Bewohner des Dorfes der Bluthufe, was diese persönliche Besorgung zu einer vertrauten Geste der Unterstützung für die Gemeinschaft auf den Weiden von Mulgore macht."},sec={{t="Ein vermisster Jagdhund",b="Im Dorf der Bluthufe sorgt sich der Älteste Ahab Wheathoof um sein eigensinniges Haustier, Kyle the Frenzied. Während der Titel für Außenstehende alarmierend klingen mag, ist Kyle Ahabs geschätzter Welpe, der auf die grasbewachsenen Ebenen von Mulgore entwischt ist. Ahab bittet Reisende, die durch die Siedlung ziehen, seinen widerspenstigen Begleiter aufzuspüren und ihm eine herzhafte Mahlzeit anzubieten, um seine wilden Geister zu besänftigen."},{t="Ein einfaches Heilmittel",b="Kyle zu beruhigen erfordert ein Stück zartes Schreiterfleisch, das von den schnellen Plainstriders stammt, die Mulgore durchstreifen. Die Übergabe des Leckerbissens stellt den hungrigen Welpen zufrieden, lindert seine rasende Stimmung und bewegt ihn sicher zurück in Richtung Dorf der Bluthufe und zu seinem dankbaren Besitzer."}},faq={{q="Wer ist Ahab Wheathoof?",a="Ahab Wheathoof ist ein älterer Tauren, der im Dorf der Bluthufe in Mulgore lebt. Da er sich sehr um seinen geschätzten Hund Kyle sorgt, wendet sich Ahab an reisende Abenteurer, um dabei zu helfen, den entlaufenen Hund ausfindig zu machen und zu füttern, wenn er zu weit von zu Hause wegläuft.",al={"wer ist ahab wheathoof","ahab mulgore","questgeber kyle"}},{q="Wer ist Kyle the Frenzied?",a="Kyle ist Ahab Wheathoofs geliebter Haushund, bekannt als Kyle the Frenzied. Trotz seines wilden Titels ist er Ahabs geschätzter Gefährte und kann besänftigt und zurückgelockt werden, indem man ihn einfach mit zartem Schreiterfleisch füttert.",al={"wer ist kyle","kyle hund","kyle the frenzied"}},{q="Wo findet diese Aufgabe statt?",a="Das Dorf der Bluthufe ist eine zentrale Siedlung der Tauren im Herzen von Mulgore, südlich von Donnerfels. Es dient als wichtiger Versammlungsort für lokale Stämme, Händler und Hirten.",al={"wo liegt das dorf der bluthufe","dorf der bluthufe standort"}},{q="Warum braucht Kyle zartes Schreiterfleisch?",a="Kyle hat einen besonderen Appetit auf frisches Fleisch von den Plainstriders, die durch Mulgore streifen. Das Anbieten von zartem Schreiterfleisch besänftigt den hungrigen Hund und überzeugt ihn, sicher zu Ahab zurückzukehren.",al={"warum zartes schreiterfleisch","schreiterfleisch kyle","wie man kyle beruhigt"}},{q="Warum gilt Kyle als rasend?",a="Kyle ist lokal als „the Frenzied“ bekannt und streift durch die Ebenen, wenn er verloren oder ausgehungert ist. Seine Raserei legt sich, sobald er von einem geduldigen Reisenden ordentlich gefüttert wird.",al={"warum ist kyle rasend","kyle wütend"}},{q="Wo ist Kyle zu finden?",a="Kyle durchstreift die offenen Ebenen rund um das Dorf der Bluthufe in Mulgore. Reisende spüren ihn gewöhnlich auf, indem sie die nahegelegenen Prärien absuchen, bis sie ihm eine Mahlzeit anbieten können.",al={"kyle aufenthaltsort","wo ist kyle"}}},fp="20,253,15.366.0,15.260.0,22.227.0,25.209.0,32.181.0,39.190.0,32.149.0,24.168.0"}
P.entries["quest:995"] = {n="Flucht durch Verstohlenheit",s="Flucht durch Verstohlenheit ist eine Geleitschutzquest der Allianz in Dunkelküste. Nachdem der Spieler den gefangenen Nachtelfenspäher Volcor tief in einer Furbolghöhle ausfindig gemacht hat, hilft er ihm dabei, sicher an feindseligen Bestien vorbei in die Freiheit zu gelangen, bevor er Terenthis in Auberdine Bericht erstattet.",h="Flucht durch Verstohlenheit ist eine Geleitschutzquest der Allianz in Dunkelküste.",kw={"eschental","auberdine","dunkelküste","geleitschutz","furbolg","verstohlenheit","terenthis","volcor"},ang={["class:Rogue"]="Schurken schätzen Volcors taktisches Gespür, einen verschanzten Feind zu umgehen, anstatt Zeit und Blut in einer rücksichtslosen Frontalschlägerei zu verschwenden.",["faction:Alliance"]="Volcors Flucht erfolgreich zu sichern, beweist der Nachtelfenführung in Auberdine, dass man Verbündeten der Allianz außerhalb der Kaldorei heikle Einsätze in der Wildnis anvertrauen kann.",["race:NightElf"]="Für Nachtelfen stärkt die Hilfe für Volcor das lebenswichtige Spähersystem, das über Kalimdors unruhige Wälder wacht, während sich die Verderbnis von verseuchten Grabhügeln und Höhlen aus ausbreitet."},sec={{t="Der gefangene Späher",b="Volcor, ein Agent, der in die Tiefen von Dunkelküste entsandt wurde, um die wachsenden Bedrohungen der Region zu untersuchen, wurde in einer Furbolghöhle in die Enge getrieben. In der Unterzahl und von den Hauptstraßen abgeschnitten, verlässt er sich auf einen vorbeikommenden Verbündeten, um einen Ausweg zu koordinieren, bevor die feindseligen Furbolgs bemerken, dass er entwischt."},{t="Eine vorsichtige Flucht",b="Statt eines selbstmörderischen Frontalangriffs entscheidet sich Volcor für Vorsicht. Er verlässt sich auf die Schatten sowie bedachtes Vorgehen und schleicht an den verderbten Bewohnern der Höhle vorbei. Da Schnelligkeit und Stille von größter Bedeutung sind, trennt sich Volcor von seinem Retter, sobald sie den Höhleneingang verlassen haben; er eilt zu Fuß voraus und weist seinen Retter an, ihn in der Siedlung Auberdine zu treffen."},{t="Bericht in Auberdine",b="Nach der Rückkehr nach Auberdine überbringt der Spieler Terenthis, einem Anführer der Nachtelfen, der die Bemühungen zum Schutz der unruhigen Küste koordiniert, die Nachricht von der Rettung. Terenthis sieht Volcors sichere Rückkehr als Beweis dafür, dass der vordringenden Dunkelheit in ganz Dunkelküste und der Wildnis dahinter mit Disziplin und Teamarbeit getrotzt werden kann."}},faq={{q="Wer ist Volcor?",a="Volcor ist ein Nachtelfenspäher, der sich auf einer Mission für seine Vorgesetzten tief in die Wildnis von Dunkelküste vorwagte. Er geriet in einer Höhle feindseliger Furbolgs in die Falle, bis ihn ein Abenteurer der Allianz rettete.",al={"volcor lore","wer ist volcor","volcor dunkelküste"}},{q="Warum rennt Volcor allein davon, sobald er außerhalb der Höhle ist?",a="Volcor stellt fest, dass er allein schneller reisen kann, sobald die engen Gänge der Höhle hinter ihm liegen. Er weist den Abenteurer an, sich in Auberdine wiederzutreffen, anstatt auf den offenen Straßen zusammenzubleiben.",al={"warum geht volcor","volcor trennt sich"}},{q="Wer ist Terenthis?",a="Terenthis ist ein bedeutender Nachtelfen-Koordinator, der in Auberdine stationiert ist. Er beaufsichtigt die lokalen Spähbemühungen und organisiert Maßnahmen gegen die Verderbnis und die feindseligen Bewohner, die Dunkelküste bedrohen.",al={"terenthis auberdine","wer ist terenthis"}},{q="Wo findet diese Rettung statt?",a="Die Rettung beginnt tief im Inneren einer Furbolghöhle in den wilderen, umkämpften Wäldern von Dunkelküste, weit entfernt von der Sicherheit Auberdines.",al={"volcor höhle ort","wo ist die volcor höhle"}},{q="Was geschieht nach Abschluss dieser Quest?",a="Nachdem Volcor in Sicherheit ist und Terenthis Bericht erstattet wurde, werden die Spieler in der Quest Marsch nach Eschental zur nächsten Etappe ihrer Reise nach Süden in Richtung Eschental geleitet.",al={"was folgt auf flucht durch verstohlenheit","folgequest nach volcor"}},{q="Was ist bei dieser Rettung die Alternative zur Verstohlenheit?",a="Volcor bietet einen alternativen Ansatz: Anstatt sich heimlich davonzustehlen, können sich Abenteurer in einer separaten, kampforientierten Geleitschutz-Option dafür entscheiden, sich mit roher Gewalt den Weg freizukämpfen.",al={"flucht durch gewalt","volcor andere quest","verstohlenheit oder gewalt"}}},fx={b4a3f8fd={q="Warum möchte Volcor durch Heimlichkeit entkommen?",a="In einem feindlichen Furbolg-Bau tief gefangen, ist es Volcors Hauptanliegen, lange genug zu überleben, um nach Auberdine zurückzukehren und Terenthis Bericht zu erstatten. An den korrumpierten Furbolgs vorbeizuschleichen, ohne Alarm zu schlagen, bietet ihm den saubersten Weg aus dem Bau, ohne einen überwältigenden Kampf auf engem Raum zu riskieren.",al={"warum flucht durch heimlichkeit","volcor motiv heimlichkeit","warum mit volcor rausschleichen"}}},fp="22,259,17.293.0,16.380.0,22.325.0,14.196.0,52.198.0,17.191.0,34.137.0,41.179.0,50.190.0"}
P.entries["quest:997"] = {n="Denalans Erde",s="Denalans Erde ist eine Botenaufgabe, die von der Siedlung Dolanaar nach Süden zu den ruhigen Gewässern des Al'Amethsees führt. Syral Messerblatt bittet Reisende, eine verspätete Lieferung seltener, angereicherter Erde ihrem Botanikerkollegen Denalan persönlich zu überbringen, der die Äste und die Flora des neuen Weltenbaums studiert.",h="Denalans Erde ist eine Botenaufgabe, die von der Siedlung Dolanaar nach Süden zu den ruhigen Gewässern des...",kw={"darnassus","denalan","dolanaar","al'amethsee","seltene erde","syral messerblatt","teldrassil","timberling"},ang={["class:Druid"]="Druiden hegen eine natürliche Verbundenheit mit Denalans Bemühungen, da die Überwachung des Wachstums und des Gleichgewichts der Flora Teldrassils unerlässlich ist, um die Natur auf dem neuen Ast zu bewahren.",["profession:Herbalism"]="Kräuterkundige werden Denalans Zuflucht am See zu schätzen wissen, da sich seine Experimente auf das Verständnis der empfindlichen, aufkeimenden Pflanzenwelt konzentrieren, die dem neu gewachsenen Weltenbaum eigen ist.",["race:NightElf"]="Für Nachtelfen, die aus dem Laubschattental hervortreten, dient die Unterstützung von Syral und Denalan als frühe Einführung in die umfassendere Verantwortung, die für den Erhalt von Teldrassil erforderlich ist."},sec={{t="Ein Bote für Dolanaar",b="Wenn Reisende auf ihrem Weg nach Süden in Richtung des Al'Amethsees Dolanaar durchqueren, macht Syral Messerblatt sie auf eine überfällige Besorgung aufmerksam. Ihr Forscherkollege Denalan hat den weiten Weg aus Darnassus ein spezielles Paket mit Seltener Erde bestellt, um seine laufenden botanischen Studien zu unterstützen. Das Paket verzögerte sich während des Transports und traf erst kürzlich in Dolanaar ein. Anstatt die reichhaltige Erde verderben oder ungenutzt liegen zu lassen, sucht Syral nach einem hilfsbereiten Kurier, der bereit ist, sie den Waldpfad hinunter zu Denalans Lager am Seeufer zu tragen."},{t="Die Kultivierung Teldrassils",b="Denalan betreibt eine einsame Arbeitsstätte am Ostufer des Al'Amethsees, wo er beobachtet, wie das junge Ökosystem von Teldrassil Wurzeln schlägt. Teldrassil ist jung, da er nach der Schlacht um den Hyjal rasch gewachsen ist, und seine Flora verhält sich auf unerwartete Weise. Denalan verwendet einzigartige Erdmischungen und Proben, um die Vitalität und das Verhalten der Timberlinge und einheimischen Pflanzen der Insel zu testen, was die frische Lieferung Seltener Erde für seine Experimente unverzichtbar macht."}},faq={{q="Wer ist Denalan?",a="Denalan ist ein Forscher und Kräuterkundiger der Nachtelfen, der sein Lager am Ostufer des Al'Amethsees aufgeschlagen hat. Er widmet seine Zeit dem Studium, der Kultivierung und der Erforschung der einzigartigen Pflanzenwelt Teldrassils.",al={"denalan lore","wer ist denalan","denalan nsc"}},{q="Wo befindet sich Syral Messerblatt?",a="Syral Messerblatt hält sich in Dolanaar auf, dem Hauptaußenposten der Nachtelfen im Zentrum von Teldrassil, wo sie Forschungsgüter koordiniert und Reisenden hilft, die über die Äste ziehen.",al={"syral messerblatt aufenthaltsort","wo ist syral"}},{q="Wofür wird die Seltene Erde verwendet?",a="Die Lieferung enthält speziell angereicherte Erde, die aus der Hauptstadt Darnassus geschickt wurde. Denalan verlässt sich darauf, um experimentelle Anpflanzungen zu nähren und zu testen, wie Teldrassils einheimische Schösslinge, wie etwa Timberlinge, auf unterschiedliche Wachstumsbedingungen reagieren.",al={"wofür braucht denalan die erde","seltene erde zweck"}},{q="Wo liegt der Al'Amethsee?",a="Der Al'Amethsee liegt südlich von Dolanaar und bildet ein friedliches Gewässer, das eingebettet zwischen den südlichen Wurzeln von Teldrassil ruht.",al={"al'amethsee lage","weg zum al'amethsee"}},{q="Warum kam die Lieferung zu spät?",a="Das Paket musste den Weg von Darnassus antreten und stieß auf den gewundenen Pfaden Teldrassils auf unbestimmte Transportverzögerungen, bevor es schließlich den Umschlagplatz in Dolanaar erreichte.",al={"warum war die erde verspätet","verspätetes paket"}},{q="Wozu führt die Übergabe dieser Erde?",a="Nach Erhalt der Seltenen Erde rekrutiert Denalan den Kurier, um beim Sammeln von Timberling Sprouts und Samen an den Ufern des Sees zu helfen, womit eine tiefergehende Reihe botanischer Feldstudien beginnt.",al={"denalans erde folgequest","wie geht es weiter"}}},fx={["77a156f9"]={q="Warum möchte Syral Messerblatt, dass die Seltene Erde geliefert wird?",a="Denalan wartet sehnsüchtig auf diese Lieferung aus Darnassus, um seine Experimente an der lokalen Flora von Teldrassil fortzusetzen. Da die Seltene Erde beim Transport verzögert wurde und erst vor Kurzem in Dolanaar eingetroffen ist, möchte Syral, dass sie ohne weitere Verzögerung zu seinem Lager am See gebracht wird, bevor das Material seine Wirkung verliert.",al={"warum seltene erde liefern","syral messerblatt motiv","warum erde zu denalan schicken"}},["2b5476f7"]={q="Warum bittet Syral Euch, die Lieferung zu überbringen?",a="Syral Messerblatt bleibt in Dolanaar, um ihren Pflichten nachzukommen, und sie sieht in Euch einfach eine fähige Reisende, die nach Süden in Richtung Al'Amethsee unterwegs ist. Da die Sendung bereits lange Verzögerungen erlitten hat, ist es der schnellste Weg, sie in seine Hände zu bekommen, wenn man sie jemandem anvertraut, der ohnehin zu Denalans Zufluchtsort unterwegs ist.",al={"warum braucht syral mich","warum keinen kurier schicken","warum ich denalans erde"}}},fp="15,297,22.508.0,22.471.0,15.208.0,33.178.0,32.234.0,23.118.0,26.178.0,40.181.1"}
P.entries["quest:cutting-teeth"] = {n="Scharfe Zähne",s="Scharfe Zähne ist die erste Prüfung für frische Rekruten, die im Tal der Prüfungen in Durotar eintreffen. Aufseher Gornek beauftragt Neulinge damit, den Bestand der gescheckten Eber auf den nahegelegenen Kaktusfarmen auszudünnen, um ihre grundlegende Kampfbereitschaft zu testen. Dieses bescheidene Übergangsritual zu überleben, beweist, dass ein angehender Krieger oder Zauberwirker das nötige Rückgrat besitzt, um der Horde zu dienen.",h="Scharfe Zähne ist die erste Prüfung für frische Rekruten, die im Tal der Prüfungen in Durotar eintreffen.",kw={"brachland","eber","scharfe zähne","durotar","gornek","horde","gescheckter eber","rekruten","das tal der prüfungen"},ang={["faction:Horde"]="Jeder junge Champion, der einen Fuß nach Durotar setzt, muss ganz unten im Staub beginnen und beweisen, dass die Zukunft der Horde auf Blut und Schweiß statt auf unverdientem Ansehen ruht.",["race:Orc"]="Die Kultur der Orcs schätzt praktisches Überleben und kriegerische Ehre über alles; selbst das bescheidene Erlegen von Ebern dient als geweihter erster Schritt ins Erwachsenenalter und in den Dienst von Thralls neuer Nation.",["race:Troll"]="Während der Stamm der Dunkelspeere an der Seite seiner orcischen Verbündeten eine neue Existenz aufbaut, müssen auch junge Trollspäher und -mystiker ihre Selbstständigkeit inmitten der unerbittlichen Raubtiere Durotars beweisen."},sec={{t="Ein Maß für das Rückgrat",b="Das Tal der Prüfungen gibt sich keinen Größenvorstellungen hin. Während junge Rekruten davon träumen mögen, gewaltige Bestien durch das Brachland zu jagen oder auf Schlachtfeldern Ruhm zu ernten, beginnt Aufseher Gornek ihre Beurteilung mit weitaus bodenständigeren Angelegenheiten. Das Ausdünnen der gescheckten Eber rund um die Farmen des Tals dient als grundlegende Einschätzung: Es stellt sicher, dass ein Rekrut weiß, wie man eine Waffe führt oder einen Zauber wirkt, mit wilder Aggression umgehen kann und genug Verstand besitzt, um sein allererstes Scharmützel zu überleben."},{t="Die Zähmung des roten Staubs",b="Über das Prüfen roher Rekruten hinaus dient das Ausmerzen der gescheckten Eber einem praktischen Zweck für die Siedlung in der roten Wüste. Die wilden Schweine streifen durch die Farmen nördlich und nordöstlich des Lagers, wühlen in Kaktusfeldern und bedrohen die knappen Vorräte, die im kargen Boden Durotars angebaut werden. Indem Anwärter ausgesandt werden, um sie zu beseitigen, hält das Lager örtliche Schädlinge in Schach, während junge Orcs und Trolle zu fähigen Verteidigern der neuen Nation geschmiedet werden."}},faq={{q="Warum schickt Gornek die Rekruten gegen Eber statt gegen größere Bestien?",a="Wie Gornek selbst zugibt, sind Rekruten für die Horde lebend weitaus nützlicher als tot. Obwohl das Brachland mächtige Kodos und Raubtiere beherbergt, würde das Entsenden eines unerprobten Neulings gegen sie schlicht in einem sinnlosen Abschlachten enden. Eber bieten einen verlässlichen Test für grundlegende Kampffähigkeiten, ohne Leben wegzuwerfen.",al={"warum eber","warum eber töten","gornek eberjagd"}},{q="Wo befinden sich die gescheckten Eber?",a="Gescheckte Eber wühlen im Gestrüpp und auf den Farmen nördlich und nordöstlich der zentralen Lichtung im Tal der Prüfungen.",al={"eber aufenthaltsort","wo sind eber","gescheckte eber finden"}},{q="Welche Bedeutung hat der Ausdruck 'Scharfe Zähne'?",a="Die Redewendung 'Cutting Teeth' ('sich die ersten Hörner abstoßen') bezieht sich darauf, allererste praktische Erfahrungen in einem Handwerk oder einer Berufung zu sammeln. Für einen angehenden Verteidiger der Horde markiert sie den Übergang von Trainingsattrappen und müßigem Gerede zum ersten echten Überlebenskampf.",al={"was bedeutet scharfe zähne","bedeutung von scharfe zähne"}},{q="Wer vergibt diese Prüfung?",a="Die Aufgabe wird von Gornek vergeben, einem Aufseher im Herzen des Tals der Prüfungen, der neue Rekruten auf Durotars Übungsgelände beurteilt und anleitet.",al={"wer vergibt scharfe zähne","questgeber scharfe zähne","gornek prüfung"}},{q="Schließt dies die Ausbildung im Tal der Prüfungen ab?",a="Nein. Gornek warnt davor, dass der Kampf gegen Eber lediglich ein Aufwärmen ist. Der Abschluss dieser Aufgabe führt unmittelbar zu gefährlicheren Herausforderungen, darunter die Konfrontation mit humanoiden Eindringlingen und das Sammeln lebenswichtiger Ressourcen des Tals.",al={"ist das die letzte quest","was kommt nach scharfe zähne"}},{q="Warum stellen die Eber im Tal ein Problem dar?",a="Die wilden Eber streifen angriffslustig über die örtlichen Farmen und durch das Dickicht, wobei sie Arbeiter gefährden und die wenigen widerstandsfähigen Gewächse wie Kaktusäpfel fressen, die das Lager versorgen.",al={"eberproblem","tal der prüfungen eber"}}},fx={["852f533a"]={q="Warum schickt Gornek mich anstelle der erfahrenen Krieger?",a="Das Tal der Prüfungen existiert einzig und allein, um die Schwachen auszusortieren und grüne Rekruten zu fähigen Verteidigern der Horde zu formen. Erfahrene Veteranen haben weitaus dringendere Aufgaben, Durotar zu schützen und Orgrimmar zu befestigen. Für einen unerprobten Neuling beweist der Kampf gegen die einheimische Tierwelt, dass Ihr den Mut und das Rückgrat besitzt, das erforderlich ist, bevor Euch irgendjemand echte militärische Verantwortung überträgt.",al={"warum schickt man mich für cutting teeth","warum braucht gornek rekruten","warum keine erfahrenen wachen"}}},fp="13,382,21.488.0,19.449.0,67.301.0,36.136.0,55.225.0,23.166.0,56.205.0,46.182.0"}
P.entries["quest:galgar-s-cactus-apple-surprise"] = {n="Galgars Kaktusapfel Surprise",s="Galgars Kaktusapfel Surprise ist eine unkomplizierte Besorgung, die von jungen Kriegern und Neulingen im sonnendurchfluteten Tal der Prüfungen übernommen wird. Auf der Suche nach Erleichterung von Durotars unbarmherziger Hitze heuert der Orc Galgar Reisende an, um wilde Kaktusäpfel zu sammeln, damit er seine berühmte erfrischende Speise zubereiten kann. Die Aufgabe lehrt frische Rekruten, wie man Nahrung sucht und in einem kargen Land überlebt.",h="Galgars Kaktusapfel Surprise ist eine unkomplizierte Besorgung, die von jungen Kriegern und Neulingen im...",kw={"kaktus","kaktusapfel","durotar","essen","nahrungssuche","galgar","horde","das tal der prüfungen"},ang={["faction:Horde"]="Jeder frische Rekrut, der das Tal der Prüfungen betritt, lernt schnell, dass das Aushalten von Durotars sengender Sonne ebenso Teil der Ausbildung ist wie der Kampf.",["profession:Cooking"]="Galgars Mahlzeit unterstreicht den Einfallsreichtum, der erforderlich ist, um aus robuster, stacheliger Wüstenflora nahrhafte Speisen und erfrischende Leckerbissen zu kreieren.",["race:Orc"]="Die Besiedlung von Durotar erforderte die Anpassung an eine trockene Landschaft, und einfache Gerichte aus einheimischen Kakteen spiegeln die praktische Fähigkeit der Orcs wider, in ihrer neuen Heimat zu gedeihen."},sec={{t="Überleben in der roten Einöde",b="Die karminrote Erde im Tal der Prüfungen ist berüchtigt gnadenlos. Zwischen anstrengenden Kampfübungen und harten Prüfungen gegen einheimische Bestien setzen Erschöpfung und Dehydrierung schnell ein. Für junge Orcs und Dunkelspeere, die ihre ersten Schritte als Verteidiger der Horde machen, ist das Erlernen des Überlebens in der Wildnis genauso wichtig wie das Schwingen einer Axt. Kakteen, die im gesamten Tal wachsen, bringen reife, wasserreiche Äpfel hervor, die sofortige Linderung von der drückenden Wüstensonne bieten."},{t="Eine Köstlichkeit des Tals",b="Galgar, der auf dem Ausbildungsgelände stationiert ist, hat das Sammeln lokaler Ressourcen zu einer Kunstform erhoben. Seine berühmte „Kaktusapfel Surprise“ ist unter den Bewohnern des Tals legendär für ihre Fähigkeit, jemanden schneller abzukühlen als ein Sprung in Flusswasser. Indem er eifrige Rekruten damit beauftragt, die stacheligen Früchte von nahegelegenen Kakteen zu ernten, hält Galgar seine Küche gefüllt und stellt gleichzeitig sicher, dass neue Wanderer niemals mit leerem Magen nach Durotar aufbrechen."}},faq={{q="Wer ist Galgar?",a="Galgar ist ein Orc, der im Tal der Prüfungen in Durotar stationiert ist. Anstatt formelle Kampfübungen zu beaufsichtigen, verbringt er seine Zeit damit, kühlenden Proviant und Köstlichkeiten wie seine berühmte Kaktusapfel Surprise zuzubereiten, um den Rekruten zu helfen, der Wüstenhitze standzuhalten.",al={"wer ist galgar","galgar geschichte","wer gibt kaktusapfel quest"}},{q="Was ist Kaktusapfel Surprise?",a="Es ist eine beliebte lokale Süßspeise und ein erfrischender Snack, der von Galgar aus frischen Kaktusäpfeln von wilden Wüstenkakteen hergestellt wird. Sie wird unter den Auszubildenden geschätzt, da sie unter der sengenden Sonne von Durotar schnelle Erleichterung und lebenswichtige Flüssigkeit spendet.",al={"kaktusapfel surprise essen","was ist die surprise","galgars rezept"}},{q="Wo sind Kaktusäpfel zu finden?",a="Kaktusäpfel wachsen in kleinen Gruppen am Boden am Fuße blühender Kakteen, die über die roten Klippen und Schluchten im Tal der Prüfungen verstreut sind.",al={"wo gibt es kaktusäpfel","kaktusäpfel finden","kaktusäpfel bekommen"}},{q="Warum bittet Galgar Rekruten, sie zu sammeln?",a="Das Tal der Prüfungen ist glühend heiß, und Galgar kann seinen Posten nicht verlassen, um selbst durch die Wüste zu ziehen. Er bietet an, Portionen seiner geschätzten Köstlichkeit mit jedem vorbeikommenden Neuling zu teilen, der bereit ist, sich in das Gestrüpp zu wagen und die rohen Zutaten für ihn zu sammeln.",al={"warum kaktusäpfel sammeln","warum braucht galgar äpfel"}},{q="Ist diese Quest mit einer größeren Geschichte verbunden?",a="Nein. Es ist eine eigenständige Sammelaufgabe, die neue Rekruten damit vertraut machen soll, Ressourcen aus der lokalen Umgebung zu gewinnen, während sie ihre anfänglichen Prüfungen für die Horde abschließen.",al={"gibt es eine questreihe","kaktusapfel folgequest","was kommt nach kaktusapfel surprise"}},{q="Warum ist das Nahrungssammeln im Tal der Prüfungen wichtig?",a="Durotar ist ein hartes und unbarmherziges Land, geformt aus trockenem Fels und Gestrüpp. Die Anführer der Horde glauben, dass das Überleben von Durotars spärlichen natürlichen Ressourcen ein wesentlicher Teil der Ausbildung für jeden ist, der die Prüfungen der weiten Welt bestehen will.",al={"warum sammeln","überleben in durotar"}}},fx={e97f8b04={q="Warum möchte Galgar, dass Kaktusäpfel gesammelt werden?",a="Die drückende Hitze im Tal der Prüfungen ist unerbittlich und Galgar sucht nach Linderung. Er sehnt sich nach seinem Spezialrezept, Kaktusapfel Surprise, von dem er behauptet, es sei der beste Leckerbissen, um sich unter der brennenden Sonne von Durotar abzukühlen. Indem Ihr die Früchte sammelt, ermöglicht Ihr ihm, eine Portion zuzubereiten, um der Hitze zu trotzen und das erfrischende Essen mit Euch zu teilen.",al={"warum will galgar äpfel","galgar motiv","warum kaktusäpfel sammeln"}}},fp="30,363,24.470.0,17.431.0,14.265.0,30.242.0,30.154.0,44.257.0,46.178.0,50.231.0"}
P.entries["quest:lazy-peons"] = {n="Faule Peons",s="Großknecht Thazz'ril hat es satt, dass die Arbeiterschaft im Tal der Prüfungen während der Arbeit einschläft. Ausgestattet mit seinem beschwerten Totschläger haben junge Rekruten die Aufgabe, das Tal zu durchstreifen, um schlafende Peons zu maßregeln und sicherzustellen, dass lebenswichtiges Bauholz weiterhin zu Durotars Siedlungen fließt.",h="Großknecht Thazz'ril hat es satt, dass die Arbeiterschaft im Tal der Prüfungen während der Arbeit einschläft.",kw={"totschläger","durotar","großknecht thazz'ril","faule peons","bauholz","peon","das tal der prüfungen"},ang={["faction:Horde"]="Jeder Außenposten in Durotar ist auf das von diesen Peons geschlagene Holz angewiesen, was die grundlegende Disziplin der Arbeiter zu einer Frage des kollektiven Überlebens macht.",["race:Orc"]="Für junge Orcs, die erwachsen werden, ist das Disziplinieren der Arbeitskräfte des eigenen Volkes eine frühe Lektion über die harten Realitäten und die praktische Disziplin, die erforderlich sind, um der Wildnis eine Nation abzuringen.",["race:Troll"]="Dunkelspeere, die an der Seite ihrer Verbündeten trainieren, erleben aus erster Hand die eigentümliche Mischung aus roher Kraft und administrativer Verzweiflung, die das Bauwesen der Orcs prägt."},sec={{t="Faulenzen in der Sonne",b="Der Aufbau einer neuen Heimat in den kargen Ebenen von Durotar erfordert gewaltige Mengen an Holz, Stein und schierer körperlicher Mühe. Ein Großteil dieser Last liegt direkt auf der Kaste der Peons – Orcs, denen es an kriegerischem Geschick mangelt, die jedoch das fleißige Rückgrat der Horde bilden. Zum Pech von Großknecht Thazz'ril verleiten die sengende Hitze und die zermürbende Arbeit im Tal der Prüfungen diese Arbeiter allzu leicht dazu, sich für unerlaubte Nickerchen unter schattige Bäume zurückzuziehen."},{t="Ein rascher Weckruf",b="Anstatt zuzulassen, dass die Produktivität zum Stillstand kommt, setzt Großknecht Thazz'ril auf eine recht direkte Führungsmethode: den Großknechttotschläger. Er vertraut dieses stumpfe Züchtigungswerkzeug neu eintreffenden Rekruten der Horde an und schickt sie über den Talboden, um schlafenden Arbeitern einen Schlag auf den Kopf zu verpassen. Aufgeschreckt und benommen kehren die Peons hastig zum Holzhacken zurück – mit der Erinnerung daran, dass für Müßiggang beim Überleben Durotars kein Platz ist."}},faq={{q="Warum schlafen die Peons ein?",a="Das Schlagen von schwerem Holz unter Durotars unbarmherziger Sonne ist eine brutale, kräftezehrende Arbeit. Ohne einen Aufseher, der ihnen im Nacken sitzt, schleichen sich die Peons regelmäßig in den Schatten großer Bäume, um sich auszuruhen.",al={"warum peons faul sind","schlafende peons","peons schlafen bei arbeit"}},{q="Wer ist Großknecht Thazz'ril?",a="Großknecht Thazz'ril ist ein orcischer Vorarbeiter, der im Tal der Prüfungen stationiert ist. Er leitet die Arbeitskolonnen, die für das Schlagen von Holz und die Beschaffung von Vorräten für die noch jungen Bauvorhaben der Horde zuständig sind.",al={"thazzril","wer vergibt faule peons","thazz'ril"}},{q="Was ist der Großknechttotschläger?",a="Es handelt sich um einen schweren Lederschlägel, mit dem Großknecht Thazz'ril nachlässige Arbeiter diszipliniert. Ein rascher Schlag auf den Kopf reicht gerade aus, um einen schlafenden Peon aufzuwecken, ohne dauerhafte Verletzungen zu verursachen.",al={"totschläger","peon knüppel","totschläger werkzeug"}},{q="Welche Rolle spielen die Peons in der Horde?",a="Peons bilden die arbeitende Klasse der orcischen Gesellschaft. Obwohl sie von kräftiger Statur sind, gelten sie als untauglich für das Kriegshandwerk und dienen stattdessen als Baumeister, Bergleute und Holzfäller, um die Kriegsmaschinerie und die Siedlungen der Horde am Laufen zu halten.",al={"rolle der orc peons","was sind peons","peon kaste"}},{q="Wo finde ich die schlafenden Peons?",a="Sie sind im gesamten Tal der Prüfungen zu finden, sowohl nördlich als auch südlich vom Höhlenbau. Haltet unter den breiten Kronen der Bäume Ausschau, wohin sich die Arbeiter zurückziehen, um Schatten zu suchen.",al={"standorte faule peons","wo sind faule peons","schlafende peons finden"}},{q="Was geschieht, nachdem die Peons geweckt wurden?",a="Sobald Ihr den Totschläger zu Großknecht Thazz'ril zurückbringt, schickt er Euch auf eine weitere Aufgabe: Ihr sollt seine verlorene Spitzhacke tief aus einer nahegelegenen Höhle bergen.",al={"nach faule peons","was folgt auf faule peons","folgequest nach peons"}}},fx={a41786ab={q="Warum möchte Großknecht Thazz'ril, dass die Peons geweckt werden?",a="Großknecht Thazz'ril ist dafür verantwortlich, das Tal der Prüfungen mit Holz zu versorgen, und Bauarbeiten erfordern ständige Arbeit. Wenn die Peons faulenzen und unter den Bäumen schlafen, kommt die Holzgewinnung zum Erliegen. Thazz'ril muss sie disziplinieren und dazu bringen, aktiv Holz zu hacken, damit das Lager der Horde seine Vorräte und Befestigungen aufrechterhalten kann.",al={"thazzril motiv","warum peons wecken","warum peons schlagen"}},["088600b8"]={q="Hinter wem seid Ihr her?",a="Ihr seid hinter den Peons des Tals der Prüfungen her, den rangniedrigsten Arbeitern der Horde, die dazu eingeteilt sind, Holz aus den Bäumen des Tals zu ernten. Anstatt zu arbeiten, haben viele ihre Äxte fallen gelassen, um im Schatten zu schlafen. Obwohl sie für die Nachschublinien des Tals unerlässlich sind, erfordert ihre berüchtigte mangelnde Motivation eine harte Erinnerung, damit sie auf ihren Posten bleiben.",al={"wen schlage ich","wer sind die faulen peons","ziel der faulen peons"}},["94fa6eb4"]={q="Warum braucht Großknecht Thazz'ril Euch, um die Peons zu disziplinieren?",a="Großknecht Thazz'ril beaufsichtigt mehrere Operationen im gesamten Tal der Prüfungen und kann seinen Posten nicht verlassen, um jedes Baumgehölz nach Drückebergern zu durchsuchen. Da die Kampfausbilder und Wachen des Tals damit beschäftigt sind, Rekruten auszubilden oder sich vor lokalen Bedrohungen zu schützen, ist es der schnellste Weg, für Ordnung unter den Arbeitern zu sorgen, wenn man einem fähigen jungen Rekruten wie Euch einen Knüppel in die Hand drückt.",al={"warum ich für faule peons","warum schlägt thazzril sie nicht","warum keine wachen"}}},fp="10,277,19.426.0,20.419.0,33.197.0,25.186.0,32.185.0,37.227.0,35.162.0,42.146.1"}
P.entries["quest:sarkoth"] = {n="Sarkoth",s="Hoch oben auf einem südlichen Plateau im Tal der Prüfungen lauert Sarkoth, ein ungewöhnlich bösartiger Skorpid, dessen giftiger Stachel einen jungen Jäger der Dunkelspeer an die Pforte des Todes gebracht hat. Verwundet unter einem Baum liegend, fleht der sterbende Troll Hana'zua einen vorbeikommenden Krieger an, die Bestie zu erschlagen und ihre verstümmelte Klaue zu bergen, um seine Ehre zu retten.",h="Hoch oben auf einem südlichen Plateau im Tal der Prüfungen lauert Sarkoth, ein ungewöhnlich bösartiger...",kw={"dunkelspeer","durotar","hana'zua","verstümmelte klaue","sarkoth","skorpid","das tal der prüfungen"},ang={["faction:Horde"]="In der unbarmherzigen Umgebung des Tals der Prüfungen bestimmt der Beistand für gefallene Kameraden die gemeinschaftliche Stärke, die Thralls Horde zu fördern sucht.",["race:Orc"]="Orcs verstehen die Pein, ohne Sieg zu sterben; die Rache an Sarkoth verschafft einem ungetesteten Späher die kriegerische Genugtuung, seinen Feind bezwungen zu sehen.",["race:Troll"]="Für einen Mitstreiter der Dunkelspeer ist es eine feierliche Pflicht der Sippschaft, Hana'zuas Flehen zu erhören und sicherzustellen, dass der ehrenhafte Kampf eines Stammesmitglieds gewürdigt wird, anstatt im Sand von Durotar verloren zu gehen."},sec={{t="Eine Frage der Ehre",b="Die Prüfungen im Tal sollen angehende Krieger der Horde stählen, doch die erbarmungslose Wüste bietet selten eine zweite Chance. Als er der giftigen einheimischen Fauna des Tals nachstellte, stieß der junge Trollspäher Hana'zua auf einen Skorpid, der weitaus größer und tödlicher war als die übrigen. Obwohl es ihm gelang, einen schweren Schlag zu führen, der eine seiner Zangen verstümmelte, bohrte sich Sarkoths Stachel in Hana'zuas Brust und ließ ihn verblutend im trockenen roten Staub zurück. Im Angesicht seines scheinbar nahenden Lebensendes bleibt ihm nur der Wunsch, dass die Bestie ihn nicht überlebt."},{t="Der Schrecken des Plateaus",b="Sarkoth durchstreift den hochgelegenen Tafelberg mit Blick auf die südlichen Weiten des Tals der Prüfungen. Gezeichnet von der zerschmetterten Klaue durch Hana'zuas Hieb beherrscht die monströse Bestie den hohen Felsgrat und greift jeden an, der kühn genug ist, den felsigen Pfad zu erklimmen. Die Kreatur zu erschlagen und ihre vernarbte Klaue zu Hana'zua zurückzubringen, verschafft dem verwundeten Späher bitteren Trost – einen greifbaren Beweis dafür, dass sein letzter verzweifelter Schlag das Ungeheuer so weit geschwächt hat, dass es zur Strecke gebracht werden konnte."}},faq={{q="Wo kann ich Sarkoth finden?",a="Sarkoth streift auf dem hohen Plateau südlich der Stelle umher, an der Hana'zua verwundet liegt. Um ihn zu erreichen, haltet nach einer Erdrampe Ausschau, die sich die Schluchtwände hinaufwindet; dort wandert der große Skorpid über den Grat.",al={"sarkoth aufenthaltsort","wo ist sarkoth","weg zu sarkoth"}},{q="Wer ist Hana'zua?",a="Hana'zua ist ein junger Dunkelspeertroll, der seine Jagdprüfungen im Tal der Prüfungen ablegt. Von Sarkoth übel zugerichtet und vergiftet liegt er zusammengesackt unter einem Baum und sucht verzweifelt nach einem Abenteurer, der ihn rächt, bevor er seinen Wunden erliegt.",al={"hanazua","sterbender troll tal der prüfungen","questgeber sarkoth"}},{q="Warum will Hana'zua Sarkoths Klaue?",a="Während ihres Kampfes landete Hana'zua einen heftigen Schlag, der Sarkoths Klaue zerschmetterte, bevor er gestochen wurde. Diese verstümmelte Klaue zu bergen dient als Beweis für den Tod des Monsters und gibt Hana'zua den Stolz zurück, dass sein letzter Kampf nicht gänzlich umsonst war.",al={"warum sarkoths klaue","verstümmelte klaue beweis","hanazua ehre"}},{q="Stirbt Hana'zua an dem Gift?",a="Obwohl er schwer verwundet ist und mit seinem vermeintlichen Versagen hadert, schöpft Hana'zua durch Sarkoths Fall genug Hoffnung, um Euch auf der Suche nach medizinischer Hilfe in den Höhlenbau zu schicken, anstatt sich unter dem Baum dem Tod zu ergeben.",al={"überlebt hanazua","hanazua schicksal","ist hanazua tot"}},{q="Was unterscheidet Sarkoth von anderen Skorpiden?",a="Im Gegensatz zu den gewöhnlichen Skorpidarbeitern, die über den unteren Talboden huschen, ist Sarkoth deutlich größer, aggressiver und trägt die unverkennbaren Spuren eines kürzlichen Kampfes, darunter eine beschädigte Klaue.",al={"sarkoth unterschiede","warum ist sarkoth besonders","skorpidboss durotar"}},{q="Was ist die Folgeaufgabe nach dem Töten von Sarkoth?",a="Sobald Ihr Sarkoths Klaue zu Hana'zua zurückbringt, drängt er Euch, schnell in den Höhlenbau zurückzukehren, um die Lagerführer über seine Notlage zu informieren und Hilfe herbeizuholen, bevor seine vergiftete Wunde tödlich endet.",al={"quest nach sarkoth","nächster schritt hanazua","quest zurück zum höhlenbau"}}},fx={["2909716d"]={q="Warum will Hana'zua Sarkoth tot sehen?",a="Hana'zua glaubt, dass sein Leben unter dem Gift des Skorpions schwindet, und er weigert sich, in Schande zu sterben. Sein Vater sagte ihm immer, dass er es zu nichts bringen würde, und einsam im Dreck zu krepieren, ohne seinen Gegner zu erschlagen, würde diese bitteren Worte wahr machen. Die Rache für seine Niederlage ist seine letzte Chance, die Ehre eines Kriegers zu wahren und sicherzustellen, dass sein letzter Feind ihn nicht überlebt.",al={"warum sarkoth töten","hanazua motiv","warum will hanazua sarkoth tot"}},["3ecf0257"]={q="Warum kann Hana'zua Sarkoth nicht selbst töten?",a="Hana'zua ist schwer verstümmelt und verblutet unter einem Baum. In ihrem Zusammenstoß auf dem südlichen Plateau gelang es ihm, Sarkoths Klaue zu treffen, aber das Biest rammte seinen Stachel tief in seine Brust. Vergiftet und zu schwach, um aufzustehen oder zu The Den zurückzukehren, um Hilfe zu holen, ist er völlig darauf angewiesen, dass Ihr die Jagd beendet, bevor sein Leben aus ihm herausrinnt.",al={"warum braucht hanazua mich","warum kann hanazua nicht kämpfen","warum ich für sarkoth"}}},fp="7,323,17.545.0,18.451.0,25.181.0,16.238.0,38.247.0,33.217.1,49.201.0,49.183.1"}
P.entries["quest:your-place-in-the-world"] = {n="Euer Platz in der Welt",s="Dieser einfache Übergangsritus markiert den Moment, in dem ein aufstrebender junger Streiter vortritt, um der Horde zu dienen. Vergeben von Kaltunk im Tal der Prüfungen, schickt er ungeprüfte Rekruten direkt zu Gornek, um ihre grundlegende Kampfausbildung zu beginnen. Er stellt den allerersten Schritt dar, um sich in den rauen Landen von Durotar Ehre und das Überleben zu verdienen.",h="Dieser einfache Übergangsritus markiert den Moment, in dem ein aufstrebender junger Streiter vortritt, um der...",kw={"cutting teeth","durotar","gornek","horde","kaltunk","rekruten","das tal der prüfungen","kriegshäuptling"},ang={["faction:Horde"]="Jeder junge Rekrut der Horde in Durotar muss beweisen, dass er den Mut besitzt, seine heranwachsende Nation zu verteidigen, bevor er im Namen des Kriegshäuptlings zu den Waffen greift.",["race:Orc"]="Für Orcs ist das Erreichen des Erwachsenenalters und der Dienstantritt im Tal der Prüfungen ein tief verwurzelter kultureller Meilenstein, bei dem persönliche Ehre und kriegerische Bereitschaft im Mittelpunkt stehen.",["race:Troll"]="Nachdem sie sich an der Seite ihrer orcischen Verbündeten in Durotar niedergelassen haben, trainieren die Dunkelspeertrolle hier Seite an Seite mit ihren Brüdern, um Einheit und gegenseitiges Überleben zu schmieden."},sec={{t="Coming of Age in Durotar",b="Im trockenen Canyon des Tals der Prüfungen müssen junge Orcs und Dunkelspeertrolle ihren Wert beweisen, bevor sie jemals einen Fuß in die weite Welt setzen können. Das Leben unter Kriegshäuptling Thrall erfordert Stärke, Wachsamkeit und Disziplin. Kaltunk mustert jeden eifrigen Rekruten und dämpft besonnen dessen Träume vom Ringen mit Dämonen und Drachen, um ihn auf realistische Pflichten zu lenken. Neue Rekruten beginnen ihre Ausbildung hier und lernen Demut, bevor sie Ruhm für sich beanspruchen."},{t="Meldung bei Gornek",b="Nur wenige Schritte von Kaltunk entfernt sitzt Gornek, ein mürrischer Veteran, der am Lagerfeuer stationiert ist. Gornek mustert die Neuankömmlinge mit skeptischem Blick und murrt oft über den dürftigen Nachschub, der im Lager eintrifft. Dennoch liegt es in seiner Verantwortung, diese unerfahrenen Kämpfer durch strenge Prüfungen zu stählen, beginnend mit der Ausrottung des einheimischen Ungeziefers, das die Vorräte des Lagers bedroht."}},faq={{q="Was ist der Zweck dieser Quest?",a="Sie dient als einführender Übergangsritus für junge Rekruten im Tal der Prüfungen. Sie nimmt Euch offiziell in den Dienst der Horde auf und stellt Euch Gornek vor, der Euch Eure ersten echten Kampfeinsätze zuweist.",al={"warum diese quest machen","erste horde-quest","was ist your place in the world"}},{q="Wer ist Kaltunk?",a="Kaltunk ist ein Orc-Aufseher, der am Eingang des Tals der Prüfungen stationiert ist. Er begrüßt heranwachsende Rekruten, mustert sie und weist ihnen den Weg zu den passenden Ausbildern und Anführern im Lager.",al={"rolle von kaltunk","wer gibt diese quest"}},{q="Wer ist Gornek?",a="Gornek ist ein erfahrener Ausbilder der Horde, der nahe dem Lagerfeuer im Tal der Prüfungen sitzt. Seine Aufgabe ist es, ankommende Rekruten zu prüfen und sie zu fähigen Soldaten zu stählen, bevor ihnen erlaubt wird, den Canyon zu verlassen.",al={"rolle von gornek","wo ist gornek"}},{q="Wohin führt diese Quest als Nächstes?",a="Die Meldung bei Gornek führt direkt zur Prüfung „Cutting Teeth“, bei der Rekruten in den Dreck geschickt werden, um gescheckte Eber zu erlegen und ihr grundlegendes kriegerisches Können unter Beweis zu stellen.",al={"welche quest kommt danach","nach your place in the world"}},{q="Warum werden Rekruten im Tal der Prüfungen gehalten?",a="Das Tal der Prüfungen ist ein abgelegener, geschützter Canyon in Durotar, der dazu dient, Rekruten auszubilden, zu beurteilen und auszusortieren, bevor sie auf die weitaus tödlicheren Bestien, Borstennacken und feindlichen Späher des weiteren Gebiets treffen.",al={"warum das tal der prüfungen","warum hier beginnen"}},{q="Unterscheidet sich diese Quest zwischen Orcs und Trollen?",a="Sowohl junge Orcs als auch Dunkelspeertrolle beginnen ihre Ausbildung gemeinsam im Tal der Prüfungen und erhalten denselben einleitenden Ruf zu den Waffen von Kaltunk.",al={"troll-einführungsquest","orc-einführungsquest"}}},fx={["4ca14302"]={q="Warum schickt Kaltunk Euch zu Gornek?",a="Ihr seid endlich alt genug geworden, um für die Horde zu kämpfen und Ruhm für Kriegshäuptling Thrall zu gewinnen. Obwohl Kaltunk Potenzial in Euch sieht, weiß er, dass eifrige Rekruten oft davon träumen, Drachen zu erlegen, bevor sie die Grundlagen gelernt haben. Er weist Euch an Gornek, damit Ihr mit Aufgaben getestet werden könnt, die für einen Neuling angemessen sind, um sicherzustellen, dass Ihr lange genug überlebt, um ein echter Gewinn für das Tal zu werden.",al={"warum will kaltunk das erledigt haben","kaltunk motiv","warum kaltunk dich schickt"}}},fp="23,330,24.449.0,19.377.0,34.217.0,15.200.0,14.215.0,32.168.0,46.216.0,47.152.0"}
P.entries["subzone:addle-s-stead"] = {n="Addles Siedlung",s="Addles Siedlung ist ein verlassenes Gehöft im südwestlichen Dämmerwald, das still unter der Düsternis des Waldes südlich von Raven Hill liegt. Während die ursprünglichen Siedler vor langer Zeit geflohen sind, ist der Hof zu einem geheimen Stützpunkt der Bruderschaft der Defias geworden.",h="Addles Siedlung ist ein verlassenes Gehöft im südwestlichen Dämmerwald, das still unter der Düsternis des...",kw={"addles siedlung","defias","bruderschaft der defias","dämmerwald","raven hill"},ang={["class:Rogue"]="Der verdeckte Außenposten zeigt, wie tief die Defias-Syndikate unbemerkt über territoriale Grenzen schlüpfen und ihre Agenten hinter den Schleier der Düsternis des Dämmerwalds einbetten.",["faction:Alliance"]="Für Ermittler der Allianz, die den vermissten König Varian Wrynn suchen, birgt dieses verfallene Bauernhaus wichtige verschwörerische Akten, die von der Bruderschaft der Defias zurückgelassen wurden."},sec={{t="Ein Außenposten in der Dunkelheit",b="Wie viele der vergessenen Gehöfte, die über den Dämmerwald verstreut sind, verfiel Addles Siedlung, als Dunkelheit und Verderben die Region einhüllten. Anstatt leer zu bleiben, wurde der Hof von der Bruderschaft der Defias zweckentfremdet. Agenten streifen durch die Umgebung, lauern im baufälligen Farmhaus und verstecken Vorräte in der Scheune, wobei sie den schattigen Schutz des südwestlichen Dämmerwaldes nutzen, um der Aufmerksamkeit der The Night Watch und der Behörden von Sturmwind zu entgehen."},{t="Verstrickt in das Verschwinden des Königs",b="Die Präsenz der Defias hier geht über bloßes Banditentum hinaus. Addles Siedlung fungiert als operativer Unterschlupf, in dem sensible Aufzeichnungen der Bruderschaft aufbewahrt werden. Entscheidende Dokumente und Akten, die regionale Verschwörer mit dem Verschwinden von König Varian Wrynn in Verbindung bringen, können bis zu diesem Stück Land zurückverfolgt werden, was eine unscheinbare, verfallene Farm zu einem entscheidenden Faden bei der Aufdeckung von Verrat innerhalb der Allianz macht."}},faq={{q="Wo befindet sich Addles Siedlung?",a="Addles Siedlung befindet sich im südwestlichen Dämmerwald, direkt südlich der Ortschaft Raven Hill und westlich des Ogerhort Vul'Gol.",al={"addles siedlung standort","wo ist addles siedlung","addles siedlung finden"}},{q="Wer kontrolliert derzeit Addles Siedlung?",a="Das Gehöft ist stark von der Bruderschaft der Defias besetzt, darunter Nachtläufer, Nachtklingen und Hexer, die das alte Haus und die Scheune als abgelegenes Versteck nutzen.",al={"wer ist in addles siedlung","gegner in addles siedlung","addles siedlung feinde"}},{q="Warum ist die Farm verlassen?",a="Wie ein Großteil des Dämmerwalds wurde die Farm von ihren ursprünglichen Bewohnern aufgegeben, als der Wald unter einen allgegenwärtigen Fluch aus Dunkelheit, Bestien und Untoten fiel, der das einfache Volk vertrieb.",al={"was geschah mit der farm","wer war addle","warum ist addles siedlung verfallen"}},{q="Was führt Abenteurer der Allianz nach Addles Siedlung?",a="Abenteurer der Allianz, die einer Spur von Hinweisen durch den Dämmerwald folgen, werden manchmal nach Addles Siedlung geschickt, um das Versteck der Defias nach einer wichtigen Akte zu durchsuchen.",al={"warum nach addles siedlung gehen","addles siedlung quest","vermisster könig dämmerwald"}}},fx={["84087cc5"]={q="Was ist Addles Siedlung?",a="Addles Siedlung ist ein verlassenes Gehöft im südwestlichen Dämmerwald, südlich von Raven Hill und westlich des Ogerhorts Vul'Gol gelegen. Wie viele Gehöfte in der Region wurde es von der sich ausbreitenden Finsternis verschluckt und von seinen ursprünglichen Besitzern im Stich gelassen, wobei seine überwucherten Felder und das baufällige Bauernhaus zurückblieben.",al={"was ist addles siedlung","addles siedlung","über addles siedlung"}},c80be076={q="Was ist in Addles Siedlung passiert?",a="Einst ein friedliches Gehöft, verfiel der Hof, als dunkle Flüche über den Dämmerwald hereinbrachen und seine Bewohner vertrieben. Agenten von The Defias Brotherhood zogen schließlich ein, um die Scheune und das Bauernhaus als Außenposten zu beanspruchen.",al={"addles siedlung geschichte","was ist hier passiert","geschichte von addles siedlung"}},["67874313"]={q="Ist Addles Siedlung gefährlich?",a="Sehr sogar. Das verlassene Anwesen wird von feindlichen Defias-Agenten patrouilliert, darunter verstohlene Nachtläufer, tödliche Nachtklingen und Zauberwirker, die in der Nähe des Bauernhauses lauern.",al={"wie gefährlich ist addles siedlung","ist addles siedlung sicher","bedrohungen in addles siedlung"}}},fp="13,242,21.445.0,35.406.1,31.134.0,37.166.0,26.177.0,50.154.1"}
P.entries["subzone:agama-gor"] = {n="Agama'gor",s="Agama'gor ist ein großes Lager der Borstennackengropp, gelegen im südlichen Brachland, direkt nördlich der Straße, die von Camp Taurajo nach Westen in Richtung Mulgore führt. Es stellt einen ständigen Dorn im Auge des nahe gelegenen Horde-Außenpostens dar und wimmelt von feindseligen Stachelebern, die sich verbissen an ihr raues Territorium klammern.",h="Agama'gor ist ein großes Lager der Borstennackengropp, gelegen im südlichen Brachland, direkt nördlich der...",kw={"agama'gor","agamagor","brachland","blutscherben","borstennacken","camp taurajo","quetschzahn","stacheleber"},ang={["faction:Horde"]="Die Sicherheit von Camp Taurajo hängt davon ab, die Borstennacken von Agama'gor in Schach zu halten, weshalb die Beseitigung ihrer Krieger für durchreisende Verteidiger der Horde oberste Priorität hat.",["race:Tauren"]="Direkt am Weg zum Great Gate und nach Mulgore gelegen, stellen die Marodeure von Agama'gor eine dauerhafte Gefahr für die Versorgungslinien und Pilger der Tauren dar."},sec={{t="Eine Festung der Borstennacken",b="Agama'gor erstreckt sich über die staubigen Ebenen des südlichen Brachlands und dient dem aggressiven Stamm der Borstennackengropp als befestigte Siedlung. Gefährlich nahe an Camp Taurajo gelegen, unterhalten die Stacheleber hier ein dichtes Netzwerk aus Dornengestrüpp, Hütten und primitiven Totems. Ihre massive Präsenz stellt eine aktive Bedrohung für Reisende dar, die sich zwischen dem Brachland und den grasbewachsenen Hügeln von Mulgore bewegen, was die Späher und Jäger der Horde dazu veranlasst, einen ständigen Eindämmungskrieg gegen sie zu führen."},{t="Blutscherben und Verbannung",b="Über die allgemeine Feindseligkeit zwischen der Horde und den Stachelebern hinaus ist Agama'gor eine Hauptquelle für die geheimnisvollen, purpurroten Steine, die als Blutscherben bekannt sind. Diese geomantischen Mineralien, die bei den in diesem Dorf lebenden Borstennacken zu finden sind, werden von Quetschzahn hoch geschätzt, einem in Camp Taurajo gefangenen Stacheleber-Verbannten. Angetrieben von uralten Glaubensvorstellungen, die mit Agamaggans heiliger Essenz verbunden sind, überfallen Abenteurer oft Agama'gor, um diese Scherben zu erbeuten und sie gegen mächtige Stammeszauber einzutauschen."}},faq={{q="Was ist Agama'gor?",a="Agama'gor ist eine große Siedlung der Borstennackengropp im südlichen Brachland. Sie liegt direkt nördlich der Hauptstraße, die von Camp Taurajo nach Westen in Richtung Mulgore führt.",al={"agamagor übersicht","was ist dieser stacheleberort","stacheleberlager nahe taurajo"}},{q="Warum sind die Borstennackengropp hier so feindselig?",a="Stacheleber glauben, dass jedes Land, das vom gefallenen Urahnen-Ebergott Agamaggan berührt wurde, rechtmäßig ihnen gehört. Daher betrachten die Borstennacken die nahe gelegenen Tauren und Orcs von Camp Taurajo als unwillkommene Eindringlinge, die ihr angestammtes Land verletzen.",al={"warum stacheleber angreifen","feindseligkeit der stacheleber","warum borstennacken wütend sind"}},{q="Was kann man in Agama'gor finden?",a="Die Borstennackengropp in ganz Agama'gor tragen häufig Blutscherben bei sich – kristallisierte Ablagerungen voller urtümlicher Macht, die bei dem verbannten Stacheleber Quetschzahn in Camp Taurajo eingetauscht werden können.",al={"was man hier bekommt","agamagor beute","warum hier borstennacken töten"}},{q="Wer ist Quetschzahn und welche Verbindung hat er zu diesem Ort?",a="Quetschzahn ist ein verbannter Stacheleber, der in einem Käfig in Camp Taurajo gefangen gehalten wird. Er hegt tiefen Groll gegen seine Sippe und verleiht Horde-Abenteurern gerne schützende Zauber im Austausch gegen Blutscherben, die seinen früheren Brüdern in Agama'gor abgenommen wurden.",al={"quetschzahn verbindung","wer ist quetschzahn","schweinegefangener taurajo"}}},fx={["62d1d1e5"]={q="Wer lebt in Agama'gor?",a="Agama'gor wird von den Stacheleber-Quilboar bewohnt. Sie haben dieses Gebiet nördlich von Camp Taurajo in eine befestigte Siedlung verwandelt und verteidigen ihren Boden erbittert gegen jeden Außenstehenden, der sich ihren Dornen und Behausungen nähert.",al={"wer lebt in agamagor","agamagor bewohner","wer ist in agamagor"}},def0ef2e={q="Ist Agama'gor gefährlich?",a="Ja. Agama'gor wimmelt von feindseligen Stacheleber-Quilboar, die Reisende auf Sicht angreifen. Aufgrund der Nähe zur westlichen Straße von Camp Taurajo ist das Verlassen des ausgetretenen Pfades für jeden Wanderer, der nicht auf Schwärme von Quilboar-Verteidigern vorbereitet ist, gefährlich.",al={"wie gefährlich ist agamagor","ist agamagor sicher","agamagor gefahr"}}},fp="9,311,24.479.0,22.458.0,18.164.0,49.247.0,31.194.0,56.247.0"}
P.entries["subzone:agamand-family-crypt"] = {n="Gruft der Familie Agamand",s="Eingebettet in die Hügel nördlich von Agamands Mühlen ist die Gruft der Familie Agamand die uralte Ruhestätte einer der wohlhabendsten Bauerndynastien von Tirisfal. Nun von der Geißel unter Hauptmann Dargol beansprucht, wurden ihre Gräber aufgerissen und die schlummernden Vorfahren als geistlose Schrecken erweckt.",h="Eingebettet in die Hügel nördlich von Agamands Mühlen ist die Gruft der Familie Agamand die uralte Ruhestätte...",kw={"gruft der familie agamand","agamands mühlen","hauptmann dargol","gruft","mausoleum","geißel","skelette","tirisfal"},ang={["race:Undead"]="Für die Verlassenen ist Hauptmann Dargols Besetzung der Gruft eine unerträgliche Präsenz der Geißel in Tirisfal, die die Toten verhöhnt und Unterstadts nördliche Grenze bedroht."},sec={{t="Ruhelose Vorfahren",b="Vor dem Dritten Krieg besaß die Familie Agamand weitläufige Ländereien im Norden von Tirisfal und setzte ihre Ahnen in diesem Mausoleum am Hang bei. Als die Seuche das Königreich ins Verderben stürzte, fiel die Gruft in die Klauen von Hauptmann Dargol, einem Agenten der Geißel. Statt das wohlhabende Geschlecht in Frieden ruhen zu lassen, nutzte Dargol dunkle Nekromantie, um die beigesetzten Skelette und rachsüchtigen Erscheinungen zu erwecken. So verwandelte er eine heilige Begräbnisstätte in einen aggressiven Stützpunkt der Geißel direkt an der Grenze des Territoriums der Verlassenen."}},faq={{q="Wo befindet sich die Gruft der Familie Agamand?",a="Die Gruft ist in den Hang direkt nördlich von Agamands Mühlen in den nördlichen Ausläufern von Tirisfal geschlagen.",al={"agamand gruft standort","wo ist die gruft","agamand gruft finden"}},{q="Wer kontrolliert die Gruft derzeit?",a="Das Grab wird von Hauptmann Dargol gehalten, einem Diener der Geißel, der die dunkle Magie im Inneren lenkt und die auferstandenen Toten befehligt.",al={"wer ist in der agamand gruft","gruft boss","hauptmann dargol"}},{q="Was erwartet mich im Inneren der Gruft?",a="Die Gruft ist voll von erweckten Skeletten und ruhelosen Geistern der Ahnen der Agamands. Getrieben von dunkler Magie greifen diese rachsüchtigen Untoten jeden an, der die Gräber betritt.",al={"gruft gegner","was ist in der agamand gruft","agamand gruft mobs"}},{q="Sind die Untoten in der Gruft mit den Verlassenen verbündet?",a="Nein. Die Kreaturen im Inneren sind Knechte der Geißel, die Hauptmann Dargol unterstehen, was sie sowohl den Verlassenen als auch lebenden Reisenden gegenüber feindlich stimmt.",al={"sind sie verlassene","agamand gruft friedlich","warum untote angreifen"}}},fx={["1e347eab"]={q="Was ist die Gruft der Familie Agamand?",a="Die Gruft der Familie Agamand ist das uralte Grabgewölbe der Agamand-Linie, das nördlich ihrer weitläufigen Mühlen in Tirisfal liegt. Einst ein ruhiger Zufluchtsort, der der noblen Familie ewige Ruhe gewähren sollte, ist er nach der Eroberung von Lordaeron durch die Geißel in die Dunkelheit verfallen.",al={"was ist die gruft der familie agamand","infos zur agamand-gruft","was ist diese gruft"}},["2b90d8b5"]={q="Was ist in der Gruft der Familie Agamand passiert?",a="Als die Geißel durch das nördliche Lordaeron fegte, wurde das Agamand-Anwesen zerstört und seine Grabstätten geschändet. Ein Diener des Lichkönigs namens Captain Dargol beanspruchte die Gruft für sich und nutzte Nekromantie, um die Leichen und Ahnengeister der Agamand-Linie in geistlose, rachsüchtige Knechtschaft zu wecken.",al={"geschichte der agamand-gruft","was geschah mit der agamand-gruft"}},["1ce0db9b"]={q="Ist die Gruft der Familie Agamand gefährlich?",a="Ja, sie ist außergewöhnlich gefährlich. Die staubigen Hallen kriechen vor auferstandenen Untoten und rachsüchtigen Gespenstern, die von nekromantischer Magie verzerrt sind. Kontrolliert von Captain Dargol greifen diese Geister und wandelnden Leichen jeden gewaltsam an, der dumm genug ist, die Grabstätte ungebeten zu betreten.",al={"ist die agamand-gruft gefährlich","gefahr der agamand-gruft","wie gefährlich ist die agamand-gruft"}},["02ac6c6f"]={q="Warum heißt sie Gruft der Familie Agamand?",a="Sie trägt den Namen der Agamands, einer bekannten Mensch-Familie aus Lordaeron, die die nahe gelegenen Agamands Mühlen besaß und betrieb. Das Gewölbe wurde erbaut, um die Überreste mehrerer Generationen ihrer Vorfahren vor dem Fall des Königreichs zu beherbergen.",al={"warum heißt sie agamand-gruft","namensursprung agamand-familien-gruft","wer sind die agamands"}}},fp="20,295,18.535.0,42.109.0,33.129.0,39.175.0,57.144.0"}
P.entries["subzone:agamand-mills"] = {n="Agamands Mühlen",s="Agamands Mühlen ist ein weitläufiger Bauernhof- und Mühlenkomplex, der in den nördlichen Anhöhen von Tirisfal liegt. Einst der stolze Besitz der wohlhabenden Dynastie Agamand, ist er verfallen und steht als größte Festung der Geißel in der Region.",h="Agamands Mühlen ist ein weitläufiger Bauernhof- und Mühlenkomplex, der in den nördlichen Anhöhen von Tirisfal...",kw={"agamand","gruft der familie agamand","agamands mühlen","kapitän dargol","devlin agamand","gregor agamand","geißel","tirisfal"},ang={["race:Undead"]="Für die Verlassenen ist die Rückeroberung von Agamands Mühlen nicht nur taktisch – es ist persönliche Rache an der Geißel und eine Begleichung offener Rechnungen durch ehemalige Diener des Anwesens wie Coleman Heller."},sec={{t="Ein gespaltenes Haus",b="Die wohlhabende Familie Agamand baute ihr Anwesen um ein riesiges Mühlennetzwerk im nördlichen Tirisfal auf. Als der Dritte Krieg ausbrach und die Geißel über Lordaeron hinwegfegte, weigerte sich das Familienoberhaupt Gregor Agamand zu fliehen. Er befestigte das Gelände und überzeugte seine Gefolgsleute und Arbeiter, Widerstand zu leisten. Ihre Vorräte und Steinmauern hätten vielleicht standgehalten, doch ihr jüngster Sohn, Devlin Agamand, verriet sein Blut. Devlin schlachtete die Wachen des Anwesens ab und ließ die wandelnden Toten in die Schlafgemächer. Von innen heraus gelähmt, wurden die verbliebenen Verteidiger ausgelöscht und die Familie schloss sich den geistlosen Reihen der Untoten an."},{t="Eine Bastion des Verfalls",b="Heute sind Agamands Mühlen die am stärksten befestigte Bastion der Geißel in Tirisfal und stellen eine unmittelbare Bedrohung für das Reich der Verlassenen dar. Die verrottenden Windmühlen drehen sich nun über verseuchten Feldern voller Schemen, Zombies und Skelettschrecken. Unter dem Anwesen befehligt Kapitän Dargol die Garnison aus der tiefen Gruft der Familie Agamand und praktiziert Nekromantie, um Generationen von Agamand-Vorfahren wiederzubeleben. Von Brill aus führen Magistrat Sevren und die Todeswachen einen aktiven Feldzug, um die Mühlen zu säubern und die Präsenz der Geißel zu vernichten, bevor sie gegen die Unterstadt marschieren kann."}},faq={{q="Warum wird Agamands Mühlen von der Geißel überrannt?",a="Als die Geißel Lordaeron verwüstete, befestigte die Familie Agamand ihr Anwesen und versuchte, der untoten Horde standzuhalten. Der jüngste Sohn, Devlin Agamand, verriet jedoch seine Familie und öffnete die Tore für die Geißel, was zum Massaker und zur Wiederbelebung aller Anwesenden führte.",al={"was geschah mit agamands mühlen","warum gibt es untote in den mühlen","lore von agamands mühlen"}},{q="Wer kontrolliert momentan die Mühlen?",a="Das Anwesen dient als regionaler Außenposten der Geißel unter der Führung von Kapitän Dargol. Dargol operiert tief in der befestigten Gruft der Familie Agamand, wo er dunkle Magie nutzt, um die Leichen der Vorfahren als neue Soldaten zu erwecken.",al={"wer führt agamands mühlen an","anführer der geißel in tirisfal","wer hat das kommando in den mühlen"}},{q="Warum interessieren sich die Verlassenen für diesen Ort?",a="Die Mühlen stellen die größte Konzentration geistloser Geißelkräfte in Tirisfal dar. Wenn sie nicht aufgehalten werden, bedrohen die Truppen von Kapitän Dargol Brill und könnten die Straßen, die nach Süden zur Unterstadt führen, blockieren.",al={"warum greift brill agamands mühlen an","interesse der verlassenen an agamands mühlen"}},{q="Wer war die Familie Agamand?",a="Sie waren eine wohlhabende menschliche Familie aus Lordaeron, der die Mühlen und das umliegende Ackerland im nördlichen Tirisfal gehörten. Heute wandeln ihre wiederbelebten Nachkommen – darunter Gregor, Nissa, Thurman und Devlin – als geistlose Knechte über das Gelände.",al={"wer sind die agamands","abstammung der agamands","gregor agamand"}}},fx={["9a335608"]={q="Was sind Agamands Mühlen?",a="Agamands Mühlen ist ein weitläufiges Netzwerk aus Windmühlen und Ackerland im nördlichen Hochland von Tirisfal. Bevor die Seuche durch Lordaeron fegte, war es ein wohlhabendes landwirtschaftliches Anwesen im Besitz der wohlhabenden Adelsfamilie Agamand. Heute ist es verfallen und dient als die größte verbliebene Festung der Geißel in der Region.",al={"lore zu agamands mühlen","was waren agamands mühlen","was ist dieser ort"}},ef38e774={q="Was geschah in Agamands Mühlen?",a="Als die Geißel über Tirisfal hereinbrach, beschloss Gregor Agamand, die Mühlen zu befestigen und seine Familie und Arbeiter davon zu überzeugen, Widerstand zu leisten. Ihre Verteidigung war stark und gut versorgt, bis ihr jüngster Sohn Devlin sie an den Feind verriet. Devlin erschlug die Wachen und ließ eine Eingreiftruppe der Untoten in das Lager, die ein Drittel der Verteidiger im Schlaf niedermetzelte. Überwältigt von den darauf folgenden Angriffen, erlagen die Überlebenden der Seuche und erhoben sich als willenlose Schergen des Lichkönigs.",al={"fall von agamands mühlen","agamands mühlen geschichte","wie fielen agamands mühlen"}},["513094d3"]={q="Ist Agamands Mühlen gefährlich?",a="Es ist außergewöhnlich gefährlich. Das Anwesen wimmelt von wiederbelebten Landarbeitern, Skelettwachen und den erhobenen Mitgliedern der Familie Agamand selbst. Tief in der Familiengruft nutzt der Kommandant der Geißel, Kapitän Dargol, dunkle Nekromantie, um längst verstorbene Ahnen zu erwecken und die Mühlen in einen bewaffneten Außenposten zu verwandeln, der sich direkt gegen die Verlassenen in Tirisfal richtet.",al={"ist agamands mühlen sicher","wie gefährlich sind agamands mühlen","bedrohung bei agamands mühlen"}},["4d06011e"]={q="Warum heißt es Agamands Mühlen?",a="Das Anwesen hat seinen Namen von den Agamands, einer wohlhabenden menschlichen Familie aus Lordaeron, denen die Mühlen und das umliegende Ackerland gehörten und deren Namen das Anwesen bis zu ihrem tragischen Ende trug.",al={"warum heißt es agamand","namensursprung agamands mühlen","wer benannte agamands mühlen"}}},fp="13,244,15.623.0,16.563.0,42.290.0,33.222.0,42.218.0,27.234.0"}
P.entries["subzone:agmond-s-end"] = {n="Agmondkuppe",s="Die Agmondkuppe ist eine verlassene Ausgrabungsstätte der Zwerge, die in den südlichen Hügeln des Ödlands liegt. Einst eine hoffnungsvolle Erkundungsgrabung unter der Führung des Prospektors Agmond, verwandelte sich das Lager in ein Schlachthaus, als sich eingrabende Troggs das Unternehmen überrannten und seinen Anführer töteten.",h="Die Agmondkuppe ist eine verlassene Ausgrabungsstätte der Zwerge, die in den südlichen Hügeln des Ödlands...",kw={"agmond","agmondkuppe","ödland","ausgrabungsstätte","prospektor","theldurin der verirrte","trogg"},ang={["race:Dwarf"]="Das Lager dient als ernüchternde Mahnung an die Gefahren, uralten irdenen Boden ohne ausreichende militärische Unterstützung freizulegen."},sec={{t="Eine grausige Ausgrabung",b="Wie viele Stätten im trockenen Ödland begann die Agmondkuppe als ein Unterfangen der Zwerge, um uralte Relikte zu bergen und in die verborgene Geschichte der Erde vorzudringen. Dieser Traum endete jäh, als wilde Troggs aus den umliegenden Felsspalten hervorbrachen und die Minenarbeiter überwältigten. Agmond selbst wurde während des Angriffs niedergestreckt, was der Stätte ihren düsteren Namen einbrachte. Heute ist die zerstörte Grabung völlig von Stonevault-Troggs verseucht, und zertrümmerte Kisten sowie zurückgelassene Werkzeuge liegen genau dort, wo sie zu Boden fielen."},{t="Ein einsamer Nachbar",b="Nahe der zerstörten Ausgrabung befindet sich ein abgelegenes Lager, das von Theldurin dem Verirrten bewohnt wird, einem Zwerg, dessen Verstand schon vor langer Zeit zerrüttet wurde. Er bleibt eine der wenigen Seelen, die bereit sind, der südlichen Wüste nahe der unheilvollen Stätte zu trotzen."}},faq={{q="Wer war Agmond?",a="Agmond war ein Prospektor der Zwerge, der eine Ausgrabung in das südliche Ödland anführte. Seine Untersuchung endete in einer Katastrophe, als unterirdische Troggs auftauchten und ihn und seine Expedition niedermetzelten.",al={"wer ist agmond","agmond geschichte"}},{q="Welche Kreaturen bewohnen die Agmondkuppe?",a="Die verfallene Ausgrabungsstätte ist völlig von feindseligen Troggs überrannt, die die Minenarbeiter der Zwerge abschlachteten und das zerstörte Lager sowie die umliegenden Felsen für sich beanspruchten.",al={"mobs an der agmondkuppe","wer lebt hier"}},{q="Wer lebt nahe der Agmondkuppe?",a="Ein Einsiedlerzwerg namens Theldurin der Verirrte unterhält ein Lager in der Nähe in den südlichen Hügeln und hält wachsam Ausschau über die karge Landschaft.",al={"nsc in der nähe","theldurin aufenthaltsort"}},{q="Warum gruben Zwerge überhaupt hier?",a="Zwergenprospektoren erkunden häufig das Ödland auf der Suche nach Titanenartefakten, uralten Ruinen und ergiebigen Mineraladern, obwohl viele solcher Expeditionen die wilden Kreaturen unterschätzen, die unter der Erde lauern.",al={"warum graben zwerge","zweck der ausgrabung"}}},fp="12,266,21.475.0,17.215.0,15.181.0,36.158.0,28.137.0,49.204.0"}
P.entries["subzone:aku-mai-s-lair"] = {n="Aku'mai's Lair",s="Aku'mai's Lair ist die tiefste und dunkelste Höhle innerhalb der Tiefschwarzen Grotte. Jenseits des Moonshrine Sanctum gelegen, dient diese überflutete Senke als Nistplatz für Aku'mai, eine monströse Hydra, die als Diener der Alten Götter verehrt wird.",h="Aku'mai's Lair ist die tiefste und dunkelste Höhle innerhalb der Tiefschwarzen Grotte.",kw={"aku'mai's lair","akumai","tiefschwarze grotte","hydra","moonshrine sanctum","naga","alte götter","schattenhammer"},ang={["class:Druid"]="Die abscheuliche Mutation und die unnatürliche Verderbnis, die von Aku'mais wässrigem Bau ausgehen, stellen eine schwere Heimsuchung für die natürlichen Wasserwege und Bestien von Kalimdor dar.",["race:NightElf"]="Für die Nachtelfen ist der Anblick eines geschändeten Elunentempels, der in einem dreckigen Nest für eine widerwärtige Brut der Alten Götter gipfelt, eine unerträgliche Entweihung des heiligen Bodens des Eschentals."},sec={{t="Herz der Tiefen",b="Hinter dem Moonshrine Sanctum versiegelt, stellt Aku'mai's Lair den Höhepunkt der Verderbnis dar, die die Tiefschwarze Grotte heimsucht. Um die Höhle zu betreten, müssen dunkle Rituale vollzogen werden, indem die vier Kohlenbeckenfeuer entzündet werden, die eine Naga-Statue flankieren, was Wächter erweckt, die geschworen haben, die Schwelle zu verteidigen. Jenseits dieser schweren Doppeltüren liegt eine sonnenlose, geflutete Grotte. Hier versammeln sich sowohl die Kultisten des Schattenhammers als auch eindringende Naga in Ehrfurcht vor Aku'mai, einer uralten, dreiköpfigen Hydra, die als lebender Diener der Alten Götter gilt."},{t="Verkünder des Ruins",b="Die Anwesenheit von Aku'mai im Bau macht ihn zu einem Brennpunkt für die apokalyptischen Pläne des Schattenhammers. Die Kultisten verehren die große Bestie als Omen eines verheißenen Zeitalters der Dunkelheit und glauben, dass ihr Auftauchen und ihre fortwährende Nahrung das Aufbrechen der unterirdischen Gefängnisse einläuten wird, die ihre uralten Gottheiten gefangen halten. Genährt durch Opfergaben und eifersüchtig durch dunkle Magie bewacht, dient das unterirdische Becken als düsteres Symbol für das uralte Übel, das sich seinen Weg zurück nach Kalimdor bahnt."}},faq={{q="Wo befindet sich Aku'mai's Lair?",a="Aku'mai's Lair befindet sich ganz am Ende des Höhlenkomplexes der Tiefschwarzen Grotte im Eschental, direkt hinter den versiegelten Toren des Moonshrine Sanctum.",al={"wo ist akumais lair","wie man zu akumais raum gelangt","akumais lair standort"}},{q="Wie öffnet Ihr die Türen zu Aku'mai's Lair?",a="Die Doppeltüren, die in das Versteck führen, werden aufgeschlossen, indem man die vier rituellen Kohlenbecken entzündet, die die Naga-Statue im Moonshrine Sanctum umgeben, und die Wellen von Kreaturen besiegt, die zu ihrem Schutz herbeigerufen werden.",al={"akumai tür öffnen","wie man akumais lair freischaltet","feuer entzünden akumai"}},{q="Was haust in dieser Höhle?",a="Die Höhle wird von Aku'mai bewohnt, einer gewaltigen, dreiköpfigen Hydra, die von uralten dunklen Mächten verdorben wurde und ein Diener der Alten Götter ist.",al={"wer ist in akumais lair","was lebt in akumais lair","boss in akumais lair"}},{q="Warum betet der Schattenhammer-Kult hier an?",a="Der Schattenhammer verehrt Aku'mai als Diener der Alten Götter, und seine Kultisten glauben, dass die Stärkung der Bestie dazu beitragen wird, die Ära zurückzubringen, in der die Alten Götter die Welt beherrschten.",al={"warum kultisten akumai anbeten","schattenhammer akumais lair","warum der schattenhammer hier ist"}}},fx={d1c19121={q="Was ist Aku'mai's Lair?",a="Aku'mai's Lair ist die tiefste, dunkelste Höhle innerhalb der überfluteten Ruinen der Tiefschwarze Grotte. Einst Teil eines alten Tempels der Nachtelfen, der Elune gewidmet war, dient dieser überflutete Hohlraum heute als Sanktum für eine monströse dreiköpfige Hydra, ein Wesen, das vom bösartigen Einfluss der Alten Götter durchdrungen ist.",al={"was ist aku'mai's lair","infos zu aku'mai's lair","über aku'mai's lair"}},b75b148a={q="Was geschah, um diesen Ort in Aku'mai's Lair zu verwandeln?",a="Nach dem uralten Großen Auseinanderbrechen versank der Tempel von Blackfathom unter den Gezeiten und verfiel in vergessenes Ruin. Über die Jahrhunderte sickerte Verderbnis in sein überflutetes Untergeschoss, was es der schrecklichen Hydra Aku'mai ermöglichte, diese untergetauchten Kammern als Nest zu beanspruchen, während dunkle Kultisten und Naga sich versammelten, um sie zu verehren.",al={"geschichte von aku'mai's lair","was geschah in aku'mai's lair","wie entstand aku'mai's lair"}},["7d86eb37"]={q="Ist Aku'mai's Lair gefährlich?",a="Es ist außerordentlich gefährlich. Jenseits des Hindernislaufs aus Eiferern und Naga, die das Moonshrine Sanctum bewachen, beherbergt die Höhle selbst einen kolossalen Diener der Alten Götter. Aku'mai schlägt mit ätzendem Atem, vernichtender Wut und urzeitlicher Bosheit um sich, die unvorbereitete Abenteurer zerfetzen kann.",al={"ist aku'mai's lair gefährlich","wie gefährlich ist aku'mai's lair","gefahr aku'mai's lair"}},["39ca825a"]={q="Warum wird diese Höhle Aku'mai's Lair genannt?",a="Die Höhle hat ihren Namen von ihrem monströsen Bewohner, Aku'mai. Die massive, korrumpierte Hydra haust hier lange genug, um den Hohlraum als ihren persönlichen Nistplatz zu beanspruchen, verehrt vom Schattenhammer und Naga, die auf ihr dunkles Erwachen warten.",al={"warum heißt es aku'mai's lair","namensbedeutung aku'mai's lair","wer benannte aku'mai's lair"}}},fp="14,235,19.521.0,17.489.0,32.158.0,44.209.0,31.127.0,50.184.0"}
